SELECT v.uri, v.titulo, v.descricao, v.status::esco_dataset.status_enum, v.nomes_alternativos::jsonb, g.grupo_id
FROM (VALUES
  ('http://data.europa.eu/esco/occupation/00030d09-2b3a-4efd-87cc-c4ea39d27c34', 'Diretor Técnico', 'Os diretores técnicos realizam as visões artísticas dos criadores no quadro de condicionalismos técnicos. Coordenam as operações de várias unidades de produção, tais como palco, guarda-roupa, som, iluminação e maquilhagem. Adaptam o protótipo e estudam a viabilidade, a implementação, o funcionamento e o acompanhamento técnico do projeto artístico. São igualmente responsáveis pelo equipamento de palco e pelo equipamento técnico.', 'released', '["Diretora Técnica", "Diretor Técnico", "Diretora Técnico"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/000e93a3-d956-4e45-aacb-f12c83fedf84', 'Operador de Máquinas de Trefilagem', 'Os operadores de máquinas de trefilagem instalam e operam máquinas de trefilagem para produtos de metal ferroso e não ferroso, concebidos para fornecer arames, barras, tubos, perfis e tubos ocos com a sua forma específica, reduzindo o seu corte transversal e puxando os materiais de trabalho através de fieiras.', 'released', '["Operador de Máquinas de Trefilagem", "Operadora de Máquinas de Trefilagem"]'::jsonb, '8121'),
  ('http://data.europa.eu/esco/occupation/0019b951-c699-4191-8208-9822882d150c', 'Inspetor de Instrumentos de Precisão', 'Os inspetores dos instrumentos de precisão asseguram que os instrumentos de precisão, tais como micrómetros e calibres, funcionam de acordo com as especificações de projeto. Podem ajustar os instrumentos de precisão e os seus componentes em caso de avarias.', 'released', '["Inspetora de Instrumentos de Precisão", "Inspetor de Instrumentos de Precisão"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/0022f466-426c-41a4-ac96-a235c945cf97', 'Técnico de Segurança do Tráfego Aéreo', 'Os técnicos de segurança do tráfego aéreo prestam apoio técnico no que se refere à segurança dos sistemas de controlo de tráfego aéreo e de navegação. Têm como funções a concepção, manutenção, instalação e operação destes sistemas, tanto no aeroporto como a bordo do avião, em conformidade com a regulamentação.', 'released', '["Técnica de Segurança do Tráfego Aéreo", "Técnico de Segurança do Tráfego Aéreo"]'::jsonb, '3155'),
  ('http://data.europa.eu/esco/occupation/002da35b-7808-43f3-83bf-63596b8b351f', 'Gestor de Receitas Hoteleiras', 'Os gestores de receitas hoteleiras maximizam as receitas geradas por unidades como hotéis, estâncias de férias e parques de campismo, através da análise de tendências e da concorrência. Prestam assistência aos gestores do estabelecimento em decisões estratégicas. Os gestores de receitas hoteleiras analisam e otimizam o potencial financeiro das unidades e gerem o pessoal correspondente.', 'released', '["Gestora de Receitas", "Gestor de Receitas Hoteleiras", "Gestora de Receitas Hoteleiras", "Gestor de Receitas", "Gerente"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/0044c991-c26f-4261-a213-4bd1c0564a4c', 'Assistente de Laboratório de Análises Clínicas', 'Os assistentes de laboratório de análises clínicas trabalham sob a supervisão do técnico de laboratório biomédico e realizam procedimentos laboratoriais básicos. Trabalham no manuseamento pré-analítico de amostras, como a verificação dos pormenores das amostras recebidas para análise, a manutenção dos analisadores, o carregamento de reagentes e a embalagem das amostras. Executam igualmente tarefas administrativas, como a monitorização dos níveis de existências de reagentes utilizados nas análises.', 'released', '["Assistentea de Laboratório de Análises Clínicas"]'::jsonb, '3212'),
  ('http://data.europa.eu/esco/occupation/00634fc4-802a-461b-8af0-499273756f99', 'Técnico de Laboratório de Asfalto', 'Os técnicos de laboratório de asfalto realizam inspeções e ensaios laboratoriais em asfalto e noutras matérias-primas conexas, assegurando uma elevada qualidade dos produtos. Participam igualmente na apresentação de resoluções para problemas técnicos em estaleiros de construção.', 'released', '["Técnica de Laboratório de Asfalto", "Operadora de Laboratório", "Técnico de Laboratório de Asfalto", "Operador de Laboratório"]'::jsonb, '3116'),
  ('http://data.europa.eu/esco/occupation/00674f21-2f8f-4a41-9896-133f7cbe2a6e', 'Auxiliar de Educação no Ensino Básico', 'Os auxiliares de educação no ensino básico prestam apoio prático e educativo aos professores do ensino básico. Reforçam a educação com os alunos que necessitam de mais atenção e preparam os materiais necessários para as necessidades dos professores na aula. Também executam trabalho administrativo, controlam o progresso da aprendizagem e o comportamento dos alunos e supervisionam-nos com e sem a presença do diretor da escola.', 'released', '["Técnica de Ação Educativa", "Técnico de Ação Educativa", "Auxiliar de Ação Educativa"]'::jsonb, '5312'),
  ('http://data.europa.eu/esco/occupation/006cc1f9-2841-41c3-991a-dc3f2f3bd533', 'Fisioterapeuta', 'Os fisioterapeutas são profissionais de saúde autónomos que são responsáveis pelo desenvolvimento, manutenção ou restauração do movimento e da função motora ao longo de toda a vida, utilizando práticas baseadas em dados concretos. Reduzem a dor e tratam ou previnem problemas físicos associados a lesões, doenças ou outras deficiências. Os fisioterapeutas habilitam os doentes e os seus cuidadores a gerirem os problemas fora do contexto clínico. Trabalham dentro do âmbito da sua prática e do seu código de conduta profissional.', 'released', '["Terapeuta da Fala", "Terapeuta Psicomotor", "Hidroterapeuta", "Terapeuta Esportiva", "Terapeuta Massagista", "Quiroprático", "Terapeuta Psicomotora", "Terapeuta Ocupacional", "Terapeuta Esportivo", "Quiroprática", "Terapeuta Respiratória", "Terapeuta Respiratório"]'::jsonb, '2264'),
  ('http://data.europa.eu/esco/occupation/00747307-6341-4266-a061-25416f7c6a96', 'Professor de Escola Superior de Teatro', 'Os professores de escola superior de teatro educam os alunos em teoria específica e, principalmente, cursos de teatro baseados na prática num teatro, numa escola ou num conservatório especializados ao nível do ensino superior. Prestam instrução teórica ao serviço das aptidões e técnicas práticas que os alunos deverão posteriormente dominar no teatro. Os professores de escola superior de teatro acompanham os progressos dos alunos, auxiliam-nos individualmente quando necessário e avaliam os seus conhecimentos e desempenho em termos da prática do teatro através da atribuição de trabalhos, testes e exames.', 'released', '["Professora da Escola de Teatro do Conservatório", "Professor de Teatro", "Professora de Teatro", "Professor da Escola de Teatro do Conservatório", "Professora de Escola Superior de Teatro", "Professor de Escola Superior de Teatro"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/0085f271-5999-4d42-b879-75c3b4269883', 'Operador de Máquina de Hidrogenação', 'Os operadores de máquinas de hidrogenação controlam o equipamento de tratamento dos óleos de base para o fabrico de margarina e produtos de banha.', 'released', '["Operadora de Hidrogenação", "Operador de Hidrogenação", "Operador de Máquina de Hidrogenação", "Operadora de Máquina de Hidrogenação"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/0090dd54-057a-4f65-bbe8-f74c4999e8e8', 'Técnico de Produção de Massas Alimentícias', 'Os técnicos de produção de massas alimentícias produzem massas alimentícias secas. Procedem à descarga de ingredientes provenientes de silos e de sistemas de distribuição de ingredientes. Estes operadores procedem à mistura, à prensagem e à extração para alcançar os níveis desejados de secagem das massas.', 'released', '["Operador de Máquina de Fabricação de Massas Alimentícias", "Técnica de Produção de Massas Alimentícias", "Operadora de Máquina de Fabricação de Massas Alimentícias", "Técnico de Produção de Massas Alimentícias"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/00913533-5237-4870-9003-d1cb806603c9', 'Gerente de Tabacaria', 'Os gerentes de tabacaria assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Charutos", "Gerente de Loja de Cigarros Eletrônicos", "Gerentea de Tabacaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/009d29de-5872-43be-8d9b-abd27f8c99f1', 'Representante de Serviço de Aluguel de Outras Máquinas e Equipamentos', 'Os representantes de serviço de aluguer de outras máquinas e equipamentos são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Outras Máquinas e Equipamentos"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/00ab29a3-6d4a-4df9-b46d-de31069e36e8', 'Topógrafo de Minas', 'Os topógrafos de minas elaboram e mantêm planos de exploração mineira em conformidade com os requisitos legais e de gestão. Mantêm registos do progresso físico das operações mineiras e da produção de minérios ou minerais.', 'released', '["Topógrafa de Minas", "Topógrafo de Minas"]'::jsonb, '2165'),
  ('http://data.europa.eu/esco/occupation/00ab5610-e715-428f-99f6-b1e5e469dbcd', 'Especialista em Segurança Alimentar', 'Os especialistas em segurança alimentar organizam processos e aplicam procedimentos para evitar problemas de segurança alimentar. Dão cumprimento à regulamentação.', 'released', NULL, '2263'),
  ('http://data.europa.eu/esco/occupation/00c8d1cf-24f2-47d1-9f10-765e1c102811', 'Técnico de Maquinaria Terrestre', 'Os técnicos de maquinaria terrestre de manutenção, revisão e reparação de equipamento e máquinas agrícolas.', 'released', '["Técnico de Maquinaria Terrestre", "Técnica Especialista na Manutenção de Máquinas Agrícolas", "Técnico Especialista na Manutenção de Máquinas Agrícolas", "Técnica de Maquinaria Terrestre", "Especialista na Manutenção de Maquinaria Agrícola"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/00cee175-1376-43fb-9f02-ba3d7a910a58', 'Motorista de Ônibus', 'Os motoristas de ônibus conduzem ônibus ou camionetas, cobram bilhetes e zelam pelos passageiros.', 'released', NULL, '8331'),
  ('http://data.europa.eu/esco/occupation/00fdad73-4551-4e43-b256-1d4a3759db1e', 'Diretor de Importação e Exportação de Carne e Produtos à Base de Carne', 'Os diretores de importação e exportação de carne e produtos à base de carne implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Carne e Produtos à Base de Carne", "Diretor de Importação e Exportação de Carne e Produtos à Base de Carne", "Diretor de Vendas de Carne e Produtos à Base de Carne", "Diretora de Vendas de Carne e Produtos à Base de Carne"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/01205776-db8d-4588-a6a6-56d0b9c660a9', 'Especialista em Política de Habitação', 'Os especialistas em política de habitação investigam, analisam e desenvolvem políticas de habitação que permitam alojamento acessível e adequado para todos. Aplicam estas políticas com o objetivo de melhorar a situação da população em termos de habitação, através de medidas como a construção de habitação a preços acessíveis, o apoio na aquisição de bens imobiliários e a melhoria das condições de habitação existentes. Os especialistas em política de habitação trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/01484951-15e6-4b88-a20f-1201868d36a0', 'Chef Principal', 'Os chefs principais gerem a cozinha para supervisionar a preparação, a confeção e a apresentação dos alimentos.', 'released', '["Chef de Cozinha", "Master Chef", "Chef Principal"]'::jsonb, '3434'),
  ('http://data.europa.eu/esco/occupation/0152b59d-5005-470c-9273-ef321477d8dc', 'Operador de Máquinas de Filamentos Têxteis', 'Os operadores de máquinas de filamentos têxteis efetuam operações de tratamento químico de filamentos têxteis.', 'released', '["Operadora de Máquinas de Filamentos Têxteis", "Operador de Máquinas de Filamentos de não Tecidos", "Operadora de Máquinas de Filamentos de não Tecidos", "Operador de Máquinas de Filamentos Têxteis"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/01649ae9-22ee-4dba-83a8-3a2c51fbbe95', 'Diretor de Instituição do Ensino Superior', 'Os diretores de instituição do ensino superior gerem as atividades quotidianas de uma instituição de ensino superior, como um colégio ou uma escola profissional. Os diretores de instituição do ensino superior tomam decisões sobre as admissões e são responsáveis pelo cumprimento das normas curriculares, que facilitam o desenvolvimento académico dos alunos. Gerem o pessoal, o orçamento da escola, programas de campus e supervisionam a comunicação entre serviços. Além disso, asseguram que a instituição cumpre os requisitos nacionais em matéria de educação previstos na lei.', 'released', '["Diretora de Instituição do Ensino Superior", "Diretor de Instituição do Ensino Superior"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/0181835d-dd00-49e2-9fc4-e1382a65957f', 'Supervisor de Instalação de Material Isolante', 'Os supervisores de instalação de material isolante acompanham as operações de isolamento. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Instalação de Material Isolante", "Supervisor de Instalação de Material Isolante"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/01989dd8-36c0-43cc-a82d-2bfc409de9c4', 'Engenheiro Especialista em Operações de Desmantelamento', 'Os engenheiros especialistas em operações de desmantelamento investigam e planeiam a melhor maneira de desmantelar equipamento industrial, máquinas e edifícios que atingiram a fase de fim de vida. Analisam o trabalho necessário e programam as várias operações. Dão instruções aos chefes de equipe e supervisionam o seu trabalho.', 'released', '["Engenheiro Especialista em Operações de Desmantelamento", "Engenheira Especialista em Operações de Desmantelamento"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/01a83071-6533-4675-b2da-f0c6d02669f5', 'Gestor de Indenizações de Seguro', 'Os gestores de indemnizações de seguro asseguram que todos os pedidos de indemnização de seguros são tratados com precisão e que o pagamento dos pedidos de indemnização válidos é efetuado aos tomadores de seguros. Utilizam dados estatísticos e relatórios para calcular e ajustar as indemnizações de acordo com as necessidades, comunicam com e orientam os tomadores de seguros e acompanham a evolução dos pedidos de indemnização.', 'released', '["Gestor de Indemnizações de Seguro", "Gestora de Indemnizações de Seguro", "Gerente", "Gestora de Indenizações de Seguro"]'::jsonb, '3315'),
  ('http://data.europa.eu/esco/occupation/01bcac9f-7881-4664-bd63-dea700e3b117', 'Diretor de Desenvolvimento de Vestuário', 'Os diretores de desenvolvimento de vestuário definem conceitos de produtos que são coerentes com a estratégia de consumo e de marketing global. Recebem resultados científicos e especificações na base da apresentação e aplicação de todos os conceitos sazonais e estratégicos relevantes, incluindo distribuição por canal, produto, introduções de cor e variedades disponíveis. Asseguram a realização e a execução do orçamento. Gerem e executam a linha de produtos e o ciclo de vida da categoria, desde a determinação do conceito até às vendas e distribuição, contribuição para a análise do mercado, e tendências da indústria que influenciam os conceitos das categorias e os produtos.', 'released', '["Diretora de Atelier", "Diretor de Atelier", "Diretor de Desenvolvimento de Produtos", "Diretor de Desenvolvimento de Vestuário", "Diretora de Desenvolvimento de Vestuário", "Diretora de Desenvolvimento de Produtos"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/01d74409-5303-4b5c-8925-0cc21c4da8ee', 'Redator Médico', 'Os redatores médicos produzem e processam documentos científicos relacionados com assuntos médicos. Trabalham em conjunto com cientistas, médicos e outros profissionais de saúde.', 'released', '["Redator Médico", "Redatora Médica", "Redatora Médico"]'::jsonb, '2641'),
  ('http://data.europa.eu/esco/occupation/01da600c-ddb3-4a37-95e9-5301b459ae90', 'Operador de Separação de Nitroglicerina', 'Os operadores de separação de nitroglicerina procedem à manutenção do separador de gravidade, utilizado no processamento de explosivos, controlando a temperatura e o fluxo de líquido, de modo a separar a nitroglicerina dos ácidos gastos.', 'released', '["Operador de Separação de Nitroglicerina", "Operadora de Separação de Nitroglicerina"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/01ffb917-98dc-48c1-91ad-93c4104e791d', 'Engenheiro Biomédico', 'Os engenheiros biomédicos combinam o conhecimento dos princípios da engenharia e as descobertas biológicas para o desenvolvimento de tratamentos médicos, medicamentos e cuidados gerais de saúde. Podem desenvolver soluções que vão desde a melhoria dos componentes de medicamentos convencionais até ao desenvolvimento de implantes e o tratamento de tecidos.', 'released', '["Engenheira Biomédica", "Engenheiro Biomédico", "Engenheira Biomédico"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/021663ca-a367-472e-a1f0-6d8ab5b2d860', 'Tutor Legal', 'Os tutores legais assistem e apoiam as crianças menores, as pessoas com deficiência mental ou os adultos com incapacidade na sua vida pessoal. Podem gerir a sua propriedade, ajudar com a administração financeira diária e ajudar com as necessidades médicas ou sociais da pessoa sob tutela.', 'released', '["Tutor Legal", "Tutora Legal"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/02375132-3290-4221-bf55-d93ec61a3bf3', 'Tecelão', 'Os tecelões operam o processo de tecelagem em teares manuais tradicionais (desde seda a tapetes, de tecidos planos a Jacquard). Controlam o estado das máquinas e a qualidade dos tecidos, tais como os tecidos para vestuário, têxteis para o lar ou para fins técnicos. Procedem a trabalhos mecânicos em máquinas que convertem fios em tecidos, tais como cobertores, tapetes, toalhas e material de vestuário. Reparam as avarias em teares comunicadas pelos tecelões, e preenchem as fichas de controlo dos teares.;', 'released', '["Tecelão", "Tecelã", "Tecelãa"]'::jsonb, '7318'),
  ('http://data.europa.eu/esco/occupation/02447817-ea01-4d8b-b09c-8bc128e447e6', 'Assentador de Azulejo e Piso Cerâmico', 'Os assentadores de azulejo e tijoleira instalam azulejo e tijoleira em paredes e pavimentos. Cortam o azulejo e tijoleira com a forma e o tamanho corretos, preparam a superfície e colocam-nos no sítio nivelados e retos. Os assentadores de azulejo e tijoleira também podem realizar projetos criativos e artísticos, e alguns assentam mosaicos.', 'released', '["Assentadora de Azulejo e Tijoleira", "Assentador de Azulejo e Tijoleira", "Assentadora de Azulejo e Piso Cerâmico"]'::jsonb, '7122'),
  ('http://data.europa.eu/esco/occupation/0249b723-1d20-4ff9-8623-d20b98d0b4a4', 'Gerente de Marroquinaria', 'Os gerentes de marroquinaria assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Sapateira", "Gerente de Loja de Artigos de Cabedal", "Correeiro", "Sapateiro", "Correeira", "Gerente de Sapataria e Correaria", "Gerentea de Marroquinaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/02609ece-cea3-43fa-bf38-b6fb821f28b2', 'Gerente de Organizadora de Excursões', 'Os gerentes de organizadores de excursões são responsáveis pela gestão dos trabalhadores e das atividades dos operadores turísticos relacionadas com a organização de pacotes de viagens e outros serviços turísticos.', 'released', '["Gestor de Excursões", "Gerente de Organizadora de Excursões", "Gestora de Excursões", "Gerentea de Organizadora de Excursões"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/026401a9-7d56-4d7b-8052-38985ddbeafa', 'Apicultor', 'Os apicultores supervisionam a produção e o cuidado diário das abelhas. Zelam pela saúde e pelo bem-estar das abelhas.', 'released', '["Meliponicultor", "Meliponicultora", "Apicultor", "Apicultora", "Criador de Abelhas", "Criadora de Abelhas"]'::jsonb, '6123'),
  ('http://data.europa.eu/esco/occupation/0264b794-3771-47aa-a675-78bf13b62ee7', 'Assistente Administrativo de Serviços Jurídicos', 'Os assistentes administrativos de serviços jurídicos exercem as atividades administrativas diárias de sociedades, gabinetes de notários públicos e empresas. Executam atividades como a redação de mensagens de correio eletrônico, o atendimento de chamadas telefônicas e datilografia/digitação informática. Combinam estas atividades com conhecimentos específicos e a compreensão dos procedimentos e códigos utilizados no âmbito dos serviços jurídicos.', 'released', '["Assistente Administrativo de Serviços Jurídicos", "Assistente Administrativa de Serviços Jurídicos", "Assistentea Administrativo de Serviços Jurídicos"]'::jsonb, '3342'),
  ('http://data.europa.eu/esco/occupation/026a5233-cad9-4b1d-8852-22c2685ab34e', 'Operador de Sistema de Bombas de Petróleo', 'Os operadores de sistemas de bombas de petróleo vigiam e controlam as bombas que mantêm a perfeita circulação do petróleo e de produtos derivados. Controlam o fluxo nas condutas de uma refinaria e testam o equipamento a fim de assegurar o mínimo de perturbações. Os operadores de sistemas de bombas trabalham a partir de uma sala de controlo altamente automatizada, onde comunicam com outros trabalhadores para coordenar as atividades da bomba. Os operadores de sistemas de bombas procedem a pequenas reparações e operações de manutenção, comunicando eventuais ocorrências conforme necessário.', 'released', '["Operadora de Sistemas de Bombas de Petróleo", "Operadora de Sistema de Bombas de Petróleo"]'::jsonb, '3134'),
  ('http://data.europa.eu/esco/occupation/029a5b78-4d1c-4cf9-a2d2-bb8d8729b8a3', 'Confeccionador de Vestuário de Proteção', 'Os confecionadores de vestuário de proteção produzem equipamento de proteção individual (EPI) fabricado a partir de têxteis. Produzem vestuário resistente a diferentes perigos (por exemplo, térmico, físico, elétrico, biológico, químico, etc.), vestuário térmico de grande visibilidade, de proteção contra o frio, chuva, radiação solar UV, etc. Cumprem normas e avaliam o cumprimento dos requisitos.', 'released', '["Confeccionador de Vestuário de Proteção", "Confeccionadora de Vestuário de Proteção"]'::jsonb, '8153'),
  ('http://data.europa.eu/esco/occupation/02b5b7b0-b856-4ac7-924c-8c35c7880b2a', 'Operador de Máquinas de Revestimento de Metais', 'Os operadores de máquinas de revestimento de metais instalam e asseguram o correto funcionamento de máquinas de revestimento que cobrem produtos metálicos com uma camada fina de cobertura de materiais, tais como verniz, esmalte, cobre, níquel, zinco, cádmio, crómio ou outros acabamentos metálicos, a fim de proteger ou decorar as superfícies dos produtos metálicos. Gerem todas as estações de máquinas de revestimento em múltiplas máquinas de revestimento.', 'released', '["Operador de Máquinas de Revestimento de Metais", "Operadora de Máquinas de Revestimento de Metais"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/02bd7cac-8263-4425-b03d-19001ffe8787', 'Responsável Pelas Unidades de Incubação em Aquicultura', 'Os responsáveis pelas unidades de incubação em aquicultura planeiam, dirigem e coordenam a produção em operações de aquicultura de grande escala para criar peixe e marisco, desenvolvendo estratégias de criação em aquicultura utilizando vários tipos de técnicas de reprodução. Controlam a reprodução e as fases iniciais do ciclo de vida das espécies cultivadas. Supervisionam a incubação, as técnicas de alimentação precoce e de criação das espécies cultivadas.', 'released', NULL, '6221'),
  ('http://data.europa.eu/esco/occupation/02d4f153-8e43-444d-8bd4-8171d49eab12', 'Técnico de Engrenagens', 'Os técnicos de engrenagens fabricam peças de precisão para engrenagens e outros elementos motrizes. Utilizam uma série de máquinas-ferramentas.', 'released', '["Técnica de Engrenagens", "Técnico de Engrenagens"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/02e19186-458f-40eb-9e78-31c656d12ac7', 'Gestor Hoteleiro', 'Os gestores hoteleiros são responsáveis pela gestão e coordenação de uma equipe de empregados nos serviços de atendimento, reserva, limpeza e manutenção.', 'released', '["Gestora Hoteleira", "Gerente de Recepção de Hotel", "Gestor Hoteleiro", "Gerente de Reservas", "Gerente", "Gestora Hoteleiro"]'::jsonb, '1411'),
  ('http://data.europa.eu/esco/occupation/02e94cd6-8e6d-4e9b-b695-edb460c70528', 'Pintor de Cerâmica', 'Os pintores de cerâmica concebem e criam arte visual em superfícies e objetos de cerâmica, tais como azulejos, esculturas, faianças e produtos de barro. Recorrem a várias técnicas para produzir ilustrações decorativas, desde desenho com estêncil até à mão livre.', 'released', '["Pintor de Cerâmica", "Pintor de Azulejos", "Pintora de Cerâmica", "Pintora de Azulejos"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/02eb0ae6-ecdd-4602-9c8e-60ffe6dbe1e2', 'Engenheiro de Telecomunicações', 'Os engenheiros de telecomunicações concebem, constroem, testam e mantêm sistemas e redes de telecomunicações, incluindo equipamentos de rádio e de radiodifusão. Analisam as necessidades e os requisitos dos clientes, asseguram a conformidade do equipamento com a regulamentação e elaboram e apresentam relatórios e propostas sobre problemas relacionados com as telecomunicações. Os engenheiros de telecomunicações concebem e supervisionam a prestação de serviços em todas as fases, monitorizando a instalação e utilização dos equipamentos e instalações de telecomunicações, elaborando documentação e formando o pessoal da empresa, sempre que sejam instalados novos equipamentos.', 'released', '["Engenheiro de Comunicações", "Engenheiro de Telecomunicações", "Engenheira de Comunicações", "Engenheira de Telecomunicações"]'::jsonb, '2153'),
  ('http://data.europa.eu/esco/occupation/02f1ae71-f89c-47b7-af2c-50d7ab1d9b8a', 'Professor Especialista em Ensino Básico de Adultos', 'Os professores especialistas em ensino básico de adultos formam os alunos adultos, incluindo imigrantes recentemente chegados e jovens que abandonam precocemente a escola, com competências básicas de leitura e escrita, geralmente ao nível do ensino primário. Os professores especialistas em ensino básico de adultos envolvem os alunos no planejamento e execução das suas atividades de leitura e avaliam-nos individualmente através da atribuição de trabalhos e exames.', 'released', '["Professor Especialista em Educação Básica de Adultos", "Professora Especialista em Educação Básica de Adultos", "Professora Especialista em Ensino Básico de Adultos"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/02f26b2f-879c-4811-8381-65e8dd3f4a16', 'Diretor de Qualidade — Calçado', 'Os diretores de qualidade do calçado implementam, gerem e promovem os sistemas de qualidade da empresa, utilizando ferramentas e metodologias adequadas baseadas em normas nacionais, internacionais ou empresariais. São responsáveis pelo estabelecimento de requisitos e objetivos, bem como pela preparação de documentos. Analisam as queixas e promovem e coordenam medidas corretivas e preventivas. Promovem uma comunicação interna e externa eficaz e asseguram o cumprimento das exigências do consumidor. São responsáveis pela definição de instrumentos que acompanham e controlam os sistemas de qualidade, nomeadamente auditorias internas ou externas, e participam no controlo interno.', 'released', '["Diretor de Garantia de Qualidade — Calçado", "Diretora de Qualidade na Indústria do Calçado", "Diretora de Garantia de Qualidade — Calçado", "Diretor de Qualidade na Indústria do Calçado", "Diretora de Qualidade — Calçado"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/02ff199e-38b3-45fd-b659-68846cfeeb92', 'Instalador de Detectores de Incêndio', 'Os instaladores de detetores de incêndio são responsáveis pela instalação de sistemas de proteção contra incêndios que pulverizam água. Estabelecem a ligação dos canos, da tubagem e dos acessórios necessários. Os instaladores de detetores de incêndio também testam os sistemas para ver se existem fugas.', 'released', '["Instaladora de Detetores de Incêndio", "Instalador de Detetores de Incêndio", "Instaladora de Detectores de Incêndio"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/032d4115-03ec-49c9-853d-678f8a41969b', 'Diretor de Distribuição de Equipamento e Peças de Eletrônica e Telecomunicações', 'Os diretores de distribuição de equipamento e peças de eletrônica e telecomunicações planificam a distribuição de equipamento e peças de eletrônica e telecomunicações em diversos pontos de venda.', 'released', '["Diretora de Logística — Equipamento e Peças de Eletrônica e Telecomunicações", "Diretor de Logística — Equipamento e Peças de Eletrônica e Telecomunicações", "Diretor de Distribuição de Equipamento e Peças de Eletrônica e Telecomunicações", "Diretora de Distribuição de Equipamento e Peças de Eletrônica e Telecomunicações"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/034cad59-e666-4770-a7ef-a337257f8072', 'Professor de Ensino Especial de Escola Secundária', 'Os professores de ensino especial de escola secundária fornecem formação especialmente concebida para alunos com uma variedade de deficiências ao nível do ensino secundário e asseguram que os mesmos atingem o seu potencial de aprendizagem. Alguns professores de ensino especial de escola secundária trabalham com crianças que apresentam deficiências ligeiras a moderadas, aplicando um programa curricular alterado para responder às necessidades específicas de cada estudante. Outros professores de ensino especial de escola secundária assistem e ensinam alunos portadores de deficiência intelectual e autismo, centrando-se no ensino da literacia básica e avançada, e em competências de vida e sociais. Todos os professores avaliam os progressos dos alunos, tendo em conta os seus pontos fortes e fracos, e comunicam as suas conclusões aos pais, orientadores, administradores e outras partes envolvidas.', 'released', '["Professora de Educação Especial Escola Secundária", "Professor de Educação Especial Escola Secundária", "Professora de Ensino Especial de Escola Secundária"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/03632d98-0ae3-4dd2-941c-3b48de9a0219', 'Diretor de Produção — Espetáculos', 'Os diretores de produção de espetáculos devem ter em conta uma série de questões práticas relativas à produção. Tratam de questões que vão desde o recrutamento de pessoal à aquisição de materiais e serviços, ao transporte de mercadorias, à coordenação aduaneira, às telecomunicações, às relações laborais, à logística, às tecnologias da informação, à comunicação com as autoridades, à reserva de instalações, à calendarização das operações, à gestão das operações, à resolução de problemas por atrasos e à segurança no local de trabalho.', 'released', '["Diretor de Produção Teatral", "Diretor de Produção Cinematográfica", "Diretora de Produção Cinematográfica", "Diretor de Produção — Espetáculos", "Diretora de Produção Teatral", "Diretor de Produção Televisiva", "Diretora de Produção Televisiva", "Diretora de Produção — Espetáculos"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/0368c4d4-94cf-4168-a84d-283a25880e0d', 'Diretor de Produção na Indústria de Metais', 'Os diretores de produção na indústria de metais organizam e gerem o trabalho quotidiano e o trabalho de projetos a longo prazo numa fábrica de fabrico de metais para transformar metais de base em metais transformados. Criam e programam planos de produção, recrutam novos funcionários, aplicam políticas de segurança e empresariais e trabalham para a satisfação dos clientes, garantindo a qualidade do produto.', 'released', '["Diretora de Produção na Indústria de Metais", "Diretor de Produção na Indústria de Metais"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/036dc42f-bd4d-4533-a3cc-fcd313227ce3', 'Montador de Motores de Aeronaves', 'Os montadores de motores de aeronaves constroem e instalam peças pré-fabricadas para formar motores de aeronaves, tais como motores de pistão e turbinas a gás leves. Analisam as especificações e os desenhos técnicos para determinar os materiais e as instruções de montagem. Inspecionam e testam os motores e rejeitam os componentes avariados.', 'released', '["Montadora de Motores de Aeronaves", "Construtora de Motores de Arenovares", "Construtor de Motores de Arenovares", "Montador de Motores de Aeronaves"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/03b2f112-a891-461d-a8d4-effb9dcf2df6', 'Engenheiro Geotécnico Especialista em Exploração de Pedreiras', 'Os engenheiros geotécnicos especialistas em exploração de pedreiras analisam quais os métodos de extração, como a escavação, a perfuração e a limpeza, mais adequados para extrair matérias-primas do solo. Desenvolvem planos antes da abertura de uma nova pedreira, avaliando se a pedreira é rentável. Os engenheiros geotécnicos especialistas em exploração de pedreiras gerem as operações quotidianas de uma pedreira, criam e mantêm relatórios de progresso, supervisionam o pessoal, asseguram a saúde e a segurança e avaliam o impacto ambiental de uma pedreira no seu ambiente.', 'released', '["Engenheira Geotécnica Especialista em Exploração de Pedreiras", "Engenheiro Geotécnico Especialista em Exploração de Pedreiras", "Engenheira Geotécnico Especialista em Exploração de Pedreiras"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/03b55cb5-9735-4582-8e20-2b1cb76635cb', 'Gerente de Centro de Audiologia', 'Os gerentes de centro de audiologia assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gestora de Vendas de Centro de Audiologia", "Gestor de Vendas de Centro de Audiologia", "Técnico de Audiologia", "Técnica de Audiologia", "Gerente de Loja de Aparelhos Auditivos", "Gerentea de Centro de Audiologia"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/03b9d7c4-9590-4e0d-97a7-470254e165d4', 'Vendedor de Ferragens e Tintas', 'Os vendedores de ferragens e tintas vendem ferragens, tintas e outro material em lojas especializadas.', 'released', '["Vendedor de Ferragens e Tintas", "Vendedora de Ferragens e Tintas"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/03d79393-7b30-4159-945b-01963eddd302', 'Professor do Ensino Básico', 'Os professores do ensino básico ensinam os alunos ao nível do ensino primário. Desenvolvem planos de aulas em consonância com os objetivos curriculares para a variedade de disciplinas que ensinam, incluindo a matemática, as línguas, as ciências naturais e a música. Acompanham o desenvolvimento da aprendizagem dos alunos e avaliam os seus conhecimentos e competências nas matérias ensinadas através de testes. Desenvolvem os seus conteúdos sobre os conhecimentos dos alunos em matéria de aprendizagens anteriores e incentivam-nos a aprofundar a sua compreensão sobre as matérias que lhes interessam. Utilizam recursos de aula e métodos de ensino para criar um ambiente de aprendizagem inspirador. Os professores do ensino básico também contribuem para eventos escolares e comunicam com os pais e o pessoal administrativo.', 'released', '["Professora do Ensino Básico", "Professor do Ensino Básico"]'::jsonb, '2341'),
  ('http://data.europa.eu/esco/occupation/03e02554-15d1-4697-960c-8909e7d36f7e', 'Guarda-Freio de Bondes', 'Os guarda-freios de elétricos conduzem elétricos, cobram bilhetes e zelam pelos passageiros.', 'released', '["Guarda-Freia de Bondes"]'::jsonb, '8331'),
  ('http://data.europa.eu/esco/occupation/040f62f5-d570-4d3f-b732-c8ea4afc2738', 'Supervisor de Montagem de Equipamento de Contêineres', 'Os supervisores de montagem de equipamento de contentores acompanham o processo de montagem de contentores, como caldeiras ou recipientes sob pressão. Prestam formação e orientação aos trabalhadores na área da montagem, tendo em vista alcançar os objetivos de produção.', 'released', '["Supervisora de Montagem de Equipamento de Contentores", "Supervisor de Montagem de Equipamento de Contentores", "Supervisora de Montagem de Equipamento de Contêineres"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/040fcfa5-24be-43eb-afd5-828297175b16', 'Auxiliar de Armazém de Vestuário', 'Os empregados de armazém de vestuário são responsáveis pelo armazenamento de tecidos, acessórios e componentes para a produção de vestuário. Garantem que todos os componentes necessários para a produção de vestuário estão prontos a ser utilizados na cadeia de produção, mediante a classificação e o registo do componente adquirido, a previsão das compras e a sua distribuição pelos diferentes departamentos.', 'released', '["Empregado de Armazém de Vestuário", "Empregada de Armazém de Vestuário"]'::jsonb, '4321'),
  ('http://data.europa.eu/esco/occupation/044d78cc-f62f-4532-83a5-8e04f2889652', 'Assistente Administrativo', 'Os assistentes administrativos prestam apoio administrativo e logístico aos supervisores. Desempenham uma série de tarefas, como o atendimento de chamadas telefônicas, a recepção e encaminhamento de visitantes, a encomenda de material de escritório, a manutenção do bom funcionamento das instalações e a garantia de que o equipamento e os aparelhos funcionam corretamente.;', 'released', '["Assistente Administrativo", "Assistente Administrativa", "Assistentea Administrativo"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/0458929a-f6c9-40ed-8ce3-caa9f03a6b5b', 'Operador de Trituradora de Café', 'Os operadores de trituradora de café utilizam máquinas de trituração para triturar os grãos de café de acordo com a espessura especificada.', 'released', '["Técnica de Operação de Instalação de Trituração de Café", "Operadora de Trituradora de Café", "Operador de Trituradora de Café", "Técnico de Operação de Instalação de Trituração de Café"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/045f05f2-4ff8-46b2-9d08-e12a81657498', 'Assistente Administrativo na Área da Medicina', 'Os assistentes administrativos na área da medicina trabalham em estreita colaboração com os profissionais de saúde. Executam serviços de apoio administrativo, como o tratamento da correspondência, a marcação de consultas e a resposta a perguntas dos doentes.', 'released', '["Assistente Administrativa na Área da Medicina", "Assistente Administrativo na Área da Medicina", "Assistentea Administrativo na Área da Medicina"]'::jsonb, '3344'),
  ('http://data.europa.eu/esco/occupation/0464b062-cea6-4164-b10d-956c61956ae7', 'Administrador de Segurança Informática', 'Os administradores de segurança informática planejam e aplicam medidas de segurança para proteger a informação e os dados contra acessos não autorizados, ataques intencionais, roubo e corrupção.', 'released', '["Administrador de Segurança de Tecnologias de Informação e Comunicação", "Administrador de Segurança de Tecnologia da Informação", "Administradora de Segurança Informática", "Administradora de Segurança de Tecnologia da Informação", "Administrador de Segurança Informática", "Administradora de Segurança de Tecnologias de Informação e Comunicação"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/046574a1-9bb3-4a80-8a7b-83dc7db1dae2', 'Supervisor de Assentamento de Tijolos', 'Os supervisores de assentamento de tijolos acompanham as atividades de assentamento de tijolos. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Assentamento de Tijolos", "Supervisora de Assentamento de Tijolos"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/047108c3-f987-40a4-bef0-f2b3407ec16a', 'Especialista em Física Médica', 'Os especialistas em física médica prestam aconselhamento sobre questões relacionadas com a física das radiações aplicada a exposições médicas. São responsáveis pela dosimetria e pela otimização da proteção contra radiações dos doentes e de outros indivíduos sujeitos a exposição médica, incluindo a aplicação e a utilização de níveis de referência de diagnóstico. Os especialistas em física médica participam na seleção do equipamento de radiologia médica, na garantia de qualidade, incluindo testes de aceitação, na elaboração de especificações técnicas e na instalação, concepção e vigilância das instalações de radiologia médica. Analisam igualmente os eventos que envolvam exposições médicas acidentais ou não intencionais, e são responsáveis pela formação de profissionais e outro pessoal em aspetos relevantes da proteção contra radiações.;', 'released', '["Especialista em Segurança Física de Radiação Médica", "MPE"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/0477b9b0-8d2d-4eec-aaad-bac11092e98b', 'Operador de Máquinas Misturadoras de Ardósia', 'Os operadores de máquinas misturadoras de ardósia procedem à operação e manutenção de máquinas misturadoras de ardósia que misturam os grânulos multicolores utilizados para revestimento de feltro para telhado com revestimento asfaltado.', 'released', '["Operadora de Máquinas Misturadoras de ardósiaMisturadora de Ardósia", "Operador de Máquinas Misturadoras de Ardósia", "Operadora de Máquinas Misturadoras de Ardósia"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/04849c5c-9236-4a75-aabb-11c6d03e459c', 'Técnico de Engenharia Naval', 'Os técnicos de engenharia naval desempenham funções técnicas para ajudar os engenheiros navais na concepção, no desenvolvimento, no fabrico e no ensaio de processos, bem como na instalação e manutenção de todos os tipos de embarcações, desde embarcações de recreio a embarcações navais, incluindo submarinos. Realizam também experiências, recolhem e analisam dados e comunicam as suas conclusões.', 'released', '["Técnico de Manutenção", "Técnica de Manutenção", "Técnica de Engenharia Naval", "Técnico de Engenharia Naval"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/04b52c04-0620-4558-8f89-e252de2963ff', 'Gestor de Leiloeira', 'Os gestores de leiloeira são responsáveis pelo pessoal e pelas atividades de uma leiloeira. Além disso, gerem os aspetos financeiros e comerciais do leilão.', 'released', '["Gestor de Leiloeira", "Gestora de Leiloeira", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/04ba4d6c-957d-417f-bf63-5b9e015a9f86', 'Analista de Software', 'Os analistas de software definem e priorizam requisitos de usuários, produzem e documentam especificações de software, testam a sua aplicação e procedem à sua revisão durante o desenvolvimento do software. Funcionam como interface entre os usuários de software e a equipe de desenvolvimento de software.', 'released', '["Analista de Software", "Analista Programadora", "Analista Programador", "Analista de Aplicações"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/04f39bfa-bc03-4480-98bc-b18ce4fe4b4b', 'Chefe de Contabilidade', 'Os chefes de contabilidade assumem a responsabilidade por todas as atividades contabilísticas relacionadas com a informação financeira. Desenvolvem e mantêm princípios e procedimentos contabilísticos para garantir demonstrações financeiras atempadas e exatas, supervisionam o pessoal de contabilidade e gerem as atividades contabilísticas no prazo e no orçamento previstos.;', 'released', '["Diretora Finaceira", "Contabilista", "Guarda-Livros", "Gerente de Contabilidade do Grupo", "Diretor Financeiro", "Chefea de Contabilidade"]'::jsonb, '1211'),
  ('http://data.europa.eu/esco/occupation/0552ff45-b282-455c-b431-fb05a0e00801', 'Gestor de Fundição', 'Os gestores da fundição coordenam e implementam calendários de produção de curto e médio prazo e coordenam o desenvolvimento, o apoio e a melhoria dos processos de fundição, bem como os esforços de fiabilidade dos departamentos de manutenção e de engenharia. Coordenam também esforços com iniciativas de reabilitação em curso.', 'released', '["Gestora de Fundição", "Gestor Fabril", "Gestora Fabril", "Gestor de Fundição", "Gerente"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/0561328b-875b-4ae2-9ba1-9af9049aef01', 'Especialista em Contratos Públicos em Categorias Específicas', 'Os especialistas em contratos públicos em categorias específicas são peritos em mercados e tipos de contratos específicos e possuem conhecimentos avançados sobre uma determinada categoria de fornecimentos, serviços ou obras. Ajudam os clientes internos e externos a melhorarem a relação qualidade-preço e a satisfação dos usuários finais, graças aos seus conhecimentos aprofundados dos fornecedores e das suas ofertas.;', 'released', '["Especialista de Mercado", "Especialista em Abastecimento", "Especialista em Categoria"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/056bef79-c125-47ab-b6b9-8eed05c9458c', 'Técnico de Telecomunicações', 'Os técnicos de telecomunicações procedem à instalação, ao ensaio, à manutenção e à resolução de problemas de telecomunicações. Reparam ou substituem dispositivos e equipamentos com defeito e mantêm um ambiente de trabalho seguro e um inventário completo dos fornecimentos. Também prestam assistência aos usuários ou aos clientes. ;', 'released', '["Técnico de Telecomunicações", "Engenheiro de Telecomunicações", "Engenheira de Telecomunicações", "Técnica de Telecomunicações"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/056f1849-7ff8-4d6f-9b8a-176a610bba44', 'Demonstrador de Promoções', 'Os demonstradores de promoções visam ativamente a procura e o diálogo com novos clientes potenciais. Prestam aconselhamento específico sobre produtos e demonstram os artigos ou serviços em promoção.', 'released', '["Demonstradora de Promoções", "Demonstrador de Promoções"]'::jsonb, '5242'),
  ('http://data.europa.eu/esco/occupation/0599d0e7-398f-464b-97bb-427686f27d50', 'Instrutor de Navegação Marítima', 'Os instrutores de navegação marítima ensinam todos os que se ocupam de pilotar uma embarcação ou um navio, como os comandantes e os capitães de navios, a operar as embarcações de águas interiores ou navios marítimos em conformidade com a regulamentação. Ensinam aos seus alunos a teoria e as técnicas de pilotar, governar e navegar e manter da melhor forma a embarcação ou navio específicos, e observam e avaliam a prática dos alunos. Também se centram em matérias não relacionadas com o governo do navio, tais como o serviço ao cliente (no caso de transporte de pessoas) e a regulamentação em matéria de medidas de segurança.', 'released', '["Instrutor de Navegação Marítima", "Instrutora de Navegação Marítima"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/05a06850-d465-481e-9d68-792d4ad1da3e', 'Operador no Mercado de Câmbios', 'Os operadores no mercado de câmbios compram e vendem divisas com o objetivo de obterem lucro em resultado das flutuações das taxas de câmbio. Realizam análises técnicas de informações econômicas (liquidez e volatilidade do mercado) para preverem as taxas futuras das divisas no mercado cambial. Negoceiam no seu próprio nome ou para os seus empregadores.', 'released', '["Operador no Mercado de Câmbios", "Operadora no Mercado de Câmbios", "Trader no Mercado de Câmbios"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/05a55bb3-68d6-4ff0-83fd-46a68a45a598', 'Técnico Aeroespacial', 'Os técnicos aeroespaciais trabalham com os engenheiros aeroespaciais na operação, manutenção e ensaio de equipamentos utilizados em aeronaves e veículos espaciais. Analisam planos técnicos e instruções para determinar as especificações e os procedimentos de ensaio. Utilizam software para garantirem o correto funcionamento das partes de um veículo espacial ou de uma aeronave. Registam os procedimentos e os resultados dos ensaios e formulam recomendações para alterações.', 'released', '["Técnico Aeroespacial", "Técnica Aeroespacial"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/05ae3e87-36ad-428f-a086-8a2ed458db3b', 'Operador de Mesas de Serrar', 'Os operadores de mesas de serrar trabalham com serras industriais que cortam com uma lâmina circular rotativa. A serra está montada numa mesa. O operador regula a altura da serra para controlar a profundidade do corte. É dada especial atenção à segurança, uma vez que fatores como as tensões naturais no interior da madeira podem produzir forças imprevisíveis.', 'released', '["Operador de Mesas de Serrar", "Operadora de Mesas de Serrar"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/05ebeb56-6ceb-488d-ba91-ed15088efc8e', 'Supervisor de Construção de Pontes', 'Os supervisores de construção de pontes acompanham a construção de pontes. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Construção de Pontes", "Supervisor de Construção de Pontes"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/05f321f8-055b-407d-bf19-e0ddabda56b7', 'Pedreiro', 'Os pedreiros montam muros e estruturas, dispondo com perícia os blocos num padrão estabelecido, utilizando um agente aglutinante, tal como o cimento, para unir os blocos. Em seguida, enchem depois as juntas com cimento ou outros materiais adequados.', 'released', '["Pedreiro", "Assentador de Refratários", "Calceteira", "Pedreira", "Servente da Construção Civil", "Assentadora de Refratários", "Calceteiro"]'::jsonb, '7112'),
  ('http://data.europa.eu/esco/occupation/05f6eaeb-b285-46bd-a44a-225bd429e329', 'Cortador de Carne', 'Os cortadores de carne cortam carcaças de animais em peças grandes e mais pequenas, para transformação subsequente. Removem os ossos de carcaças pré-transformadas, quer manualmente quer utilizando máquinas.', 'released', '["Cortador de Carne", "Operador de Máquina de Corte e Desossa de Carne", "Operadora de Máquina de Corte e Desossa de Carne", "Talhante", "Cortadora de Carne"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/0611f232-b30e-46c7-9c26-2d59b1448e79', 'Criminólogo', 'Os criminólogos estudam condições da natureza humana, como os aspetos sociais e psicológicos, passíveis de levar um indivíduo a cometer atos criminosos. Observam e analisam diferentes fatores, desde as condições comportamentais até à origem social e ao ambiente dos suspeitos, a fim de prestarem aconselhamento a organizações sobre a prevenção da criminalidade.', 'released', '["Criminólogo", "Criminóloga"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/061f56c6-36eb-4aa7-b5ef-98b7a569da1c', 'Operador de Vídeo', 'Os operadores de vídeo controlam as imagens (projetadas) de um espetáculo com base no conceito artístico ou criativo, em interação com os artistas. O seu trabalho é influenciado e influencia os resultados dos outros operadores. Por conseguinte, os operadores trabalham em estreita colaboração com os designers, os operadores e os artistas. Os operadores de vídeo elaboram excertos dos meios de comunicação social, supervisionam a instalação, dirigem a equipe técnica, programam o equipamento e operam o sistema de vídeo. O seu trabalho baseia-se em planos, instruções e outra documentação. ;', 'released', '["Operadora de Vídeo", "Operador de Vídeo"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/062d666b-8b5f-4ff2-9047-113831eb3e9f', 'Vendedor de Peixe e Marisco', 'Os vendedores de peixe e marisco vendem peixe, crustáceos e moluscos em lojas especializadas. ;', 'released', '["Vendedor de Peixe e Marisco", "Vendedora de Peixe e Marisco"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/0633ec3f-91f1-4038-bc29-e0ec4cd7f1e9', 'Gestor de Produção de Petróleo e Gás', 'Os gestores de produção de petróleo e gás coordenam e implementam programas e planos de produção de petróleo e de gás a curto e a médio prazo, como as operações de perfuração e extração e a gestão de resíduos. Orientam uma ou mais unidades e supervisionam a aplicação de meios técnicos e humanos, no quadro dos objetivos de volume, qualidade e planejamento. Os gestores de produção de petróleo e gás asseguram o cumprimento dos planos e programas de produção.', 'released', '["Gestora de Produção Petróleo e Gás", "Gestor de Produção Petróleo e Gás", "Gerente", "Gestora de Produção de Petróleo e Gás"]'::jsonb, '1322'),
  ('http://data.europa.eu/esco/occupation/06351e17-67c4-44bc-adf7-64b73f92c3b5', 'Técnico de Metalurgia', 'Os técnicos de metalurgia prestam apoio técnico à investigação e à realização de experiências em minerais, metais, ligas, petróleo e gás. Prestam igualmente assistência na melhoria dos métodos de extração.', 'released', '["Técnica de Metalurgia", "Técnico de Metalurgia"]'::jsonb, '3117'),
  ('http://data.europa.eu/esco/occupation/06461fc3-1274-40a1-9322-dfc2753f5eea', 'Operador de Fiação de Matérias Têxteis', 'Os técnicos de máquinas de fiação realizam operações relacionadas com a criação de processos de fiação.', 'released', '["Técnica de Máquinas de Fiação", "Técnico de Máquinas de Fiação", "Operadora de Fiação de Matérias Têxteis", "Operador de Fiação de Matérias Têxteis"]'::jsonb, '8151'),
  ('http://data.europa.eu/esco/occupation/0663d464-f139-4554-ae87-97aa6c4dad77', 'Colocador de Pavimentos Resistentes', 'Os colocadores de pavimentos resistentes instalam tijoleira pré-fabricada ou rolos de materiais para pavimentos, tais como linóleo, vinil, borracha ou cortiça, para servir de revestimento de pavimentos.', 'released', '["Colocador de Linóleo", "Colocadora de Linóleo", "Colocador de Pavimentos Resistentes", "Colocador de Pavimento Vinílico", "Colocadora de Pavimento Vinílico", "Colocadora de Pavimentos Resistentes"]'::jsonb, '7122'),
  ('http://data.europa.eu/esco/occupation/0663da10-e42c-41e8-992c-07d00ac97bea', 'Técnico de Qualidade dos Têxteis', 'Os técnicos de qualidade dos têxteis realizam testes laboratoriais físicos em materiais e produtos têxteis. Comparam os materiais e os produtos têxteis com as normas e interpretam os resultados.', 'released', '["Técnico de Qualidade Química dos Têxteis", "Técnica de Qualidade Química dos Têxteis", "Técnica de Qualidade dos Têxteis"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/066a9d8f-3948-409c-a3cf-ed8ed37cfe22', 'Trabalhador da Sala de Cura', 'Os trabalhadores da sala de cura auxiliam com a mistura, o envelhecimento, a fermentação de talos e caules de tabaco para a produção de charutos, tabaco para mascar e rapé.', 'released', '["Curadora de Tabaco", "Curador de Tabaco", "Trabalhador da Sala de Cura do Tabaco", "Trabalhadora da Sala de Cura do Tabaco", "Técnico da Sala de Cura de Tabaco", "Técnica da Sala de Cura de Tabaco", "Trabalhadora da Sala de Cura"]'::jsonb, '7516'),
  ('http://data.europa.eu/esco/occupation/066fe11d-10e4-4fec-bd27-3e78797500b9', 'Operador de Máquina de Esmaltagem', 'Os operadores de máquina de esmaltagem embelezam metais, tais como o ouro, a prata, o cobre, o aço, o ferro fundido ou a platina, através da pintura. O esmalte aplicado é constituído por vidro colorido em pó.', 'released', '["Operador de Máquina de Esmaltagem", "Operadora de Máquinas de Esmaltagem", "Operadora de Máquina de Esmaltagem"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/068370e0-9c27-4814-87d0-44fbb3140815', 'Consultor de Recrutamento e Seleção', 'Os consultores de recrutamento e seleção disponibilizam aos empregadores os candidatos adequados, de acordo com o perfil solicitado para determinada vaga de emprego. Realizam testes e entrevistas aos candidatos a emprego, elaboram uma lista com um número restrito de candidatos para apresentar aos empregadores e fazem corresponder os candidatos aos empregos adequados. Os consultores de recrutamento e seleção mantêm relações com os empregadores no sentido de prestarem os seus serviços de forma mais permanente.', 'released', '["Consultor de Recrutamento e Seleção", "Consultora de Recrutamento e Seleção"]'::jsonb, '2423'),
  ('http://data.europa.eu/esco/occupation/068c2787-58ff-468e-bbb6-c4e5dd6ee482', 'Consultor Atuarial', 'Os consultores atuariais analisam, gerem e fornecem orientações sobre o impacto financeiro dos riscos. Podem trabalhar em domínios relacionados com seguros, pensões, investimentos, serviços bancários, cuidados de saúde, etc.. Os consultores atuariais aplicam modelos e teorias técnicos e estatísticos para prestar aconselhamento estratégico, comercial e financeiro.', 'released', '["Consultor Atuarial", "Atuária Vida", "Atuário Vida", "Atuário Especialista em Solvência", "Atuário", "Atuária Especialista em Solvência", "Atuária", "Atuário Não-Vida", "Consultora Atuarial", "Atuária Não-Vida"]'::jsonb, '2120'),
  ('http://data.europa.eu/esco/occupation/068df7d1-516f-4829-b339-294cb0cf6318', 'Designer de Iluminação em Espetáculos', 'Os designers de iluminação em espetáculos desenvolvem um conceito de design da iluminação para um espetáculo e supervisionam a sua execução. O seu trabalho baseia-se na investigação e na visão artística. As suas concepções são influenciadas por, e influenciam, outros designs e devem estar em conformidade com eles e com a visão artística global. Por conseguinte, os designers trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Durante os ensaios e os espetáculos orientam os operadores para uma sincronização e uma manipulação ideais. Os designers de iluminação em espetáculos desenvolvem planos de iluminação, listas de orientação e outra documentação para ajudar os operadores e a equipe de produção. Por vezes, trabalham também como artistas independentes, criando arte de luz fora de um contexto de espetáculo.;', 'released', NULL, '2166'),
  ('http://data.europa.eu/esco/occupation/06ac0f53-431e-4bc6-acb8-2f5da041b5d3', 'Repetidor de Dança', 'Os repetidores de dança prestam assistência aos maestros e coreógrafos na direção dos ensaios e na orientação dos artistas no processo de ensaio. Independentemente da sua natureza e do seu âmbito de aplicação, as ações de um repetidor baseiam-se, do ponto de vista ético e prático, no compromisso de respeitar a integridade do trabalho.', 'released', '["Repetidora de Dança", "Repetidor de Dança", "Assistente de Coreografia"]'::jsonb, '2653'),
  ('http://data.europa.eu/esco/occupation/06bd6285-13ed-4ea7-90cc-e9638a0600a9', 'Técnico de Baterias Automóveis', 'Os técnicos de baterias automóveis procedem à montagem, instalação, inspeção, manutenção e reparação das baterias dos veículos a motor. Utilizam equipamentos elétricos de ensaio para confirmar o bom funcionamento após a instalação. Avaliam as baterias para determinar a natureza dos problemas de energia. Também preparam baterias antigas para serem eliminadas.', 'released', '["Técnico de Baterias Automóveis", "Técnica de Baterias Automóveis"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/06f89f2c-c6e9-40c5-a4a5-0e34d5fbc184', 'Designer de Calçado', 'Os designers de calçado procedem à análise das tendências da moda, realizam previsões e pesquisas do mercado, criam conceitos de calçado e coleções com base em estilos ou conceitos, paletes de cor, materiais, desenhos e esboços, etc.. Realizam o processo de amostragem, fabricam protótipos e amostras para apresentações destinadas a promover os conceitos e as coleções de calçado. Identificam a gama de materiais e componentes, definem as especificações de design em colaboração com a equipe técnica e analisam as amostras, protótipos e coleções de calçado.', 'released', '["Designer Gráfico para a Indústria do Calçado", "Designer Gráfica para a Indústria do Calçado"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/070e94a8-a933-4557-9b95-fefe7f4f1763', 'Gestor do Serviço Público de Emprego', 'Os gestores do serviço público de emprego supervisionam as operações de uma agência de serviços públicos de emprego. Supervisionam o pessoal que ajuda as pessoas a encontrarem emprego ou que presta orientação profissional.', 'released', '["Gestora do Serviço Público de Emprego", "Gestor do Serviço Público de Emprego", "Gerente"]'::jsonb, '1120'),
  ('http://data.europa.eu/esco/occupation/072279cf-ed39-47e7-af23-ee6df571eb24', 'Modelista de Vestuário', 'Os modelistas de vestuário produzem moldes em diferentes tamanhos (por exemplo, aumentados ou reduzidos) para reproduzir o mesmo vestuário em diferentes tamanhos. Desenham moldes à mão ou utilizam software seguindo as tabelas de tamanho.', 'released', NULL, '7532'),
  ('http://data.europa.eu/esco/occupation/0752ed49-03e7-4d75-8314-a051b3771a1d', 'Gestor da Administração Pública', 'Os gestores da administração pública dirigem, acompanham e avaliam a execução das políticas governamentais. Supervisionam o pessoal, gerem os recursos executivos utilizados e redigem relatórios sobre o processo executivo. Comunicam igualmente com funcionários do governo e o público para os informar sobre as políticas. Os gestores da administração pública podem também participar na concepção e na criação de políticas públicas.', 'released', '["Administrador Público", "Funcionária Pública", "Funcionário Público", "Administradora da Função Pública", "Administrador da Função Pública", "Gestor da Administração Pública", "Administradora Pública", "Gestora da Administração Pública", "Gerente"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/075e4d25-74b3-46fb-9b6e-6b53cdb196e7', 'Analista de Crédito', 'Os analistas de crédito investigam os pedidos de crédito efetuados pelos clientes e avaliam se os pedidos estão em conformidade com a regulamentação e as orientações da instituição financeira que concede o empréstimo. Com base nas análises de crédito, aconselham as instituições financeiras sobre a idoneidade creditícia dos clientes. Executam tarefas como a recolha de dados sobre o requerente do empréstimo, a obtenção de informações adicionais junto de outros departamentos ou instituições e a indicação do tipo de acordos que a instituição financeira deve celebrar com o requerente de crédito. Os analistas de crédito acompanham igualmente a evolução das carteiras de créditos dos clientes.', 'released', NULL, '3312'),
  ('http://data.europa.eu/esco/occupation/0763c810-8ac6-4e39-867d-780a11af26e0', 'Supervisor de Canalização', 'Os supervisores de canalização acompanham as operações de canalização. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Canalização", "Supervisora de Canalização"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/076d23f3-a689-4f1a-8b55-ae870c9aaa85', 'Analista de Títulos', 'Os analistas de títulos realizam atividades de investigação para recolher e analisar informações financeiras, jurídicas e econômicas. Interpretam dados sobre o preço, a estabilidade e as futuras tendências de investimento num determinado espaço econômico e fazem recomendações e previsões a clientes empresariais.', 'released', NULL, '2413'),
  ('http://data.europa.eu/esco/occupation/07b91f36-8272-493a-8e1c-5625e77efe68', 'Bailarino', 'Os bailarinos interpretam ideias, sentimentos, histórias ou personagens para públicos utilizando o movimento e a linguagem corporal, na maioria das vezes acompanhados de música. Tal envolve normalmente a interpretação do trabalho de um coreógrafo ou de um repertório tradicional, embora possa, por vezes, exigir improviso.', 'released', '["Bailarina", "Bailarino"]'::jsonb, '2653'),
  ('http://data.europa.eu/esco/occupation/07ba3429-cccd-435b-a7d0-c02ba962bbd9', 'Fabricante de Calçado por Medida', 'Os fabricantes de calçado por medida realizam atividades em ambientes de produção de pequena dimensão (por exemplo, oficinas) em que o calçado é geralmente feito por medida. Concebem, preparam, cortam e cosem, montam e acabam o calçado.', 'released', '["Fabricantea de Calçado por Medida"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/07bd65d7-c13f-443a-bdf6-88903f3822be', 'Juiz', 'Os juízes presidem a, analisam e tratam os processos judiciais, as audições, os recursos e os julgamentos. Asseguram a conformidade dos processos judiciais com os processos legais convencionais e analisam os elementos de prova e os júris. Os juízes presidem a casos que envolvem áreas como a criminalidade, as questões familiares, o direito civil, as ações de pequeno montante e os delitos juvenis.', 'released', '["Juiz", "Juíza"]'::jsonb, '2612'),
  ('http://data.europa.eu/esco/occupation/07c2287f-3caa-4128-b7c8-59801084d931', 'Criador de Marionetas', 'Os criadores de marionetas concebem e criam marionetas e objetos manipuláveis para os executantes. O seu trabalho baseia-se na investigação e na visão artística. Os seus desenhos são influenciados por, e influenciam, outros desenhos e devem estar em conformidade com esses desenhos e com a visão artística global. Por conseguinte, os criadores trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Os criadores de marionetas constroem marionetas e objetos manipuláveis a partir de uma variedade de materiais e podem integrar-lhes elementos robóticos. Os criadores de marionetas também trabalham, por vezes, como artistas autónomos, criando paralelamente a um contexto de espetáculo.. ;', 'released', '["Criadora de Marionetas", "Criador de Marionetas"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/07d4a2fa-e278-4f32-8cf9-9c01fc660369', 'Operador Flexográfico', 'Os operadores flexográficos utilizam uma placa de relevo flexográfico para imprimir em quase qualquer material. A placa de relevo é coberta de tinta e prensada no material a imprimir.', 'released', '["Impressor Flexográfico", "Operador Flexográfico", "Impressora Flexográfica", "Operadora Flexográfica", "Operadora Flexográfico"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/07dfff6d-a0d0-4202-a697-fe9176c15999', 'Engenheiro de Fiabilidade', 'Os engenheiros de fiabilidade asseguram a fiabilidade, a disponibilidade e manutenibilidade (RAM) de um processo de produção ou sistema. Centram-se em melhorar a capacidade de um sistema funcionar sem interrupções e operar sempre que necessário, bem como em aumentar a facilidade de reparação, substituição ou modernização do produto.;', 'released', '["Engenheiro de Confiabilidade", "Engenheiro de Confiabilidade e Segurança", "Engenheira de Confiabilidade", "Engenheira RAMS", "Engenheiro RAMS", "Engenheira RAM", "Engenheiro RAM", "Engenheira de Confiabilidade e Segurança", "Engenheira de Fiabilidade"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/07e60525-1aad-4099-aaf3-2c7014c92212', 'Engenheiro de Integração', 'Os engenheiros de integração desenvolvem e implementam soluções que coordenam aplicações em toda a empresa ou nas suas unidades e departamentos. Avaliam os componentes ou sistemas existentes a fim de determinarem os requisitos de integração e de assegurarem que as soluções finais satisfazem as necessidades organizacionais. Sempre que possível, reutilizam componentes e prestam assistência aos responsáveis pela gestão na tomada de decisões. Resolvem problemas de integração de sistemas de tecnologia da informação.', 'released', '["Engenheira de Integração de Tecnologia da Informação", "Engenheira de Integração de Software", "Engenheira de Integração de Tecnologias de Informação e Comunicação", "Engenheiro de Integração de Sistemas", "Engenheira de Integração Tecnológica", "Engenheiro de Integração Tecnológica", "Engenheiro de Integração de Software", "Engenheiro de Integração de Tecnologias de Informação e Comunicação", "Engenheira de Integração de Sistemas", "Engenheiro de Integração de Tecnologia da Informação", "Engenheira de Integração"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/0809ea8a-4f77-4351-a7f1-b9a7b99b6c0b', 'Meteorologista Previsor', 'Os meteorologistas previsores recolhem dados meteorológicos. Preveem as condições meteorológicas de acordo com esses dados. Os meteorologistas previsores apresentam essas previsões ao público através da rádio, da televisão ou em linha.', 'released', '["Meteorologista Previsora", "Observadora Meteorológica", "Observador Meteorológico", "Meteorologista Previsor"]'::jsonb, '2112'),
  ('http://data.europa.eu/esco/occupation/080bce18-066b-4431-90ed-e07608f73fe0', 'Artista Urbano', 'Os artistas urbanos criam arte visual, como arte de graffiti ou com autocolantes, em espaços públicos urbanos e na rua, expressando geralmente sentimentos ou opiniões e ideias políticas, optando por locais de arte não tradicionais.', 'released', '["Artista Urbano", "Artista Urbana"]'::jsonb, '2659'),
  ('http://data.europa.eu/esco/occupation/080fc550-b7ca-4576-aaf5-06fffbede994', 'Gerente de Spa', 'Os gerentes de spa coordenam as operações correntes do estabelecimento termal, a fim de proporcionar aos hóspedes as melhores experiências. Supervisionam as atividades e o desempenho do pessoal, gerem os aspetos financeiros do estabelecimento termal, lidam com os fornecedores e realizam campanhas publicitárias para o estabelecimento termal, a fim de atrair mais clientes.', 'released', '["Diretora de Spa", "Diretora de Estabelecimento Termal", "Gerente de Estabelecimento Termal", "Diretor de Spa", "Diretor de Estabelecimento Termal", "Gerentea de Spa"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/082c234c-0dda-490a-b5af-757c3e48da90', 'Atleta Profissional', 'Os atletas profissionais competem em eventos desportivos e atléticos. Treinam regularmente e exercitam-se com treinadores e formadores profissionais. O reforço das competências necessárias requer talento natural, bem como planejamento e resistência a fim de concluir os programas de formação necessários.', 'released', NULL, '3421'),
  ('http://data.europa.eu/esco/occupation/08984bec-31d8-4bb0-aa2f-d557761ff029', 'Veterinário Especialista', 'Os veterinários especialistas são profissionais com uma formação científica abrangente. Têm autoridade para exercer, de forma independente, ética e pessoalmente responsável, todos os aspetos da medicina veterinária, no interesse da saúde e do bem-estar dos animais e da saúde pública, em conformidade com a legislação nacional e internacional. Além disso, necessitam de uma qualificação e/ou experiência reconhecida numa espécie específica e/ou num procedimento veterinário. ; ;', 'released', '["Veterinário de Animais de Laboratório", "Dermatologista Veterinário", "Dentista Veterinário", "Veterinária de Vida Selvagem", "Veterinário de Medicina Comportamental Animal", "Veterinário de Pequenos Mamíferos", "Dermatologista Veterinária", "Oftalmologista Veterinária", "Parasitólogo Veterinário", "Veterinária de Medicina Veterinária Zoológica", "Patologista Veterinário", "Veterinária Especialista", "Veterinária de Pequenos Ruminantes", "Veterinária de Animais de Laboratório", "Veterinário de Saúde Bovina", "Microbiólogo Veterinário", "Veterinário de Medicina Veterinária Zoológica", "Veterinária de Saúde Bovina", "Oftalmologista Veterinário", "Neurologista Veterinário", "Nutricionista Comparativo Veterinário", "Veterinário Especializado em Medicina Interna de Animais de Companhia", "Veterinária de Medicina Comportamental Animal", "Veterinária de Pequenos Mamíferos", "Cientista Veterinária Especializada em Aves de Capoeira", "Teriogenólogo Veterinário", "Patologista Veterinária", "Veterinário de Animais Aquáticos", "Anestesiologista Veterinária", "Oncologista Veterinário", "Parasitóloga Veterinária", "Veterinária de Medicina Esportiva e Reabilitação", "Farmacologista e Toxicóloga Veterinária", "Veterinário de Vida Selvagem", "Emergencista Veterinário", "Anestesiologista Veterinário", "Nutricionista Comparativa Veterinária", "Teriogenóloga Veterinária", "Veterinária de Medicina Interna Equina", "Veterinário de Saúde Porcina", "Neurologista Veterinária", "Veterinário de Medicina Interna Equina", "Farmacologista e Toxicólogo Veterinário", "Veterinária de Animais Aquáticos", "Cientista Veterinário Especializado em Aves de Capoeira", "Patologista Clínico Veterinário", "Patologista Clínica Veterinária", "Cardiologista Veterinária", "Veterinário de Pequenos Ruminantes", "Veterinária de Imagiologia", "Veterinário de Medicina Esportiva e Reabilitação", "Veterinária de Saúde Porcina", "Oncologista Veterinária", "Microbióloga Veterinária", "Veterinário de Imagiologia", "Cardiologista Veterinário", "Dentista Veterinária", "Emergencista Veterinária", "Veterinário Especialista", "Veterinária Especializada em Medicina Interna de Animais de Companhia"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/08edf4c5-3551-4690-9d09-f9b8b9194c90', 'Operador de Varas Motorizadas', 'Os operadores de varas motorizadas controlam os movimentos de cenários e outros elementos num espetáculo com base no conceito artístico ou criativo, em interação com os artistas. O seu trabalho é influenciado e influencia os resultados dos outros operadores. Por conseguinte, os operadores trabalham em estreita colaboração com os designers, os operadores e os artistas. Os operadores de varas motorizadas preparam e supervisionam a instalação, programam o equipamento e operam sistemas de varas motorizadas, sistemas de manipulação ou sistemas de movimentação horizontal. O seu trabalho baseia-se em planos, instruções e cálculos. A manipulação de cargas pesadas próximo ou por cima dos artistas e do público faz com que seja uma atividade de alto risco. ; ;', 'released', '["Operador de Varas Motorizadas", "Operadora de Varas Motorizadas"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/08f5481e-9233-4ef2-9e4b-945224879ce5', 'Técnico de Finalização de Projetos', 'Os técnicos de finalização de projetos trabalham com os engenheiros especialistas em finalização de projetos para supervisionar as fases finais de um projeto quando os sistemas são instalados e ensaiados. Verificam o correto funcionamento do equipamento, das instalações e das unidades e, quando necessário, procedem a trabalhos de reparação e manutenção.', 'released', '["Técnica de Finalização de Projetos", "Técnico de Finalização de Projetos"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/0917ab6b-18a8-4cfd-8e7a-843b88cf9457', 'Gerente de Sucursal', 'Os gerentes de sucursal são responsáveis pela gestão de todos os assuntos relacionados com uma empresa numa determinada região geográfica ou ramo de atividade. Recebem indicações da sede e, consoante a estrutura da empresa, têm por objetivo implementar a estratégia da empresa, adaptando-a ao mercado em que a sucursal opera. Encarregam-se da gestão dos trabalhadores, comunicações, esforços de marketing e acompanhamento dos resultados e objetivos.', 'released', '["Diretora Comercial Internacional", "Diretora Regional", "Diretor Comercial Internacional", "Diretor Regional", "Gerente de Agência de Recrutamento", "Gerentea de Sucursal"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/092fdeeb-a76f-4ed2-b248-90fd6eaaffef', 'Perito em SEO', 'Os peritos em SEO melhoram a classificação das páginas Web de uma empresa no que se refere a consultas específicas num motor de pesquisa. Criam e lançam campanhas de SEO e identificam áreas de melhoria. Os peritos em SEO podem realizar campanhas de pagamento por clique (PPC).', 'released', '["Growth Hacker", "Consultora de SEO", "Especialista em SEO", "Hacker do Crescimento", "Perito em Otimização de Motores de Busca", "Perito em SEO", "Especialista em Otimização de Motores de Busca", "Consultora de Otimização de Motores de Busca", "Consultor de Otimização de Motores de Busca", "Perita em Otimização de Motores de Busca", "Consultor de SEO", "Perita em SEO"]'::jsonb, '2513'),
  ('http://data.europa.eu/esco/occupation/094b9f9b-7e89-4f34-adbb-fbaf7246f7a4', 'Técnico Operativo de Rede de Abastecimento de Água e Saneamento', 'Os técnicos operativos de rede de abastecimento de água e saneamento procedem à manutenção dos tubos e das casas das bombas utilizados para o abastecimento de água, a eliminação de águas residuais e a rede de esgotos. Executam tarefas de manutenção e reparação planeadas e desobstruem canos e condutas.', 'released', '["Técnica Operativa de Rede de Abastecimento de Água e Saneamento", "Técnico Operativo de Rede de Abastecimento de Água e Saneamento", "Técnica Operativo de Rede de Abastecimento de Água e Saneamento"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/094e04fd-3039-4615-850b-b232794f84f5', 'Agente de Informação a Jovens', 'Os agentes de informação a jovens prestam serviços de informação, orientação e aconselhamento a jovens em diversos contextos, com o objetivo de os capacitar e apoiar o seu bem-estar e autonomia. Asseguram que esses serviços são acessíveis, dotados de recursos e acolhedores para os jovens e levam a cabo atividades destinadas a chegar a toda a população jovem, através de meios eficazes e adequados aos diferentes grupos e necessidades. Os agentes de informação a jovens têm como objetivo dotar os jovens de meios para fazerem as suas próprias escolhas informadas e exercerem uma cidadania ativa. Trabalham em estreita parceria com outros serviços.;', 'released', '["Diretor do Centro Juvenil", "Consultor Jovem", "Animadora de Informação Juvenil", "Moderador Jovem", "Trabalhador de Informação de Campo", "Consultor de Projeto Jovem", "Facilitador Jovem", "Trabalhadora Jovem Escolar", "Especialista em Informação Juvenil", "Consultora de Informação Juvenil", "Consultora de Projeto Jovem", "Gerente Extracurricular", "Provedor de Informação Juvenil", "Trabalhador Jovem Escolar", "Agente Jovem", "Consultor de Carreira Jovem", "Trabalhadora de Informação de Campo", "Técnico de Informação e Aconselhamento Juvenil", "Consultora de Carreira Jovem", "Jovem Informante", "Animador de Informação Juvenil", "Consultor de Informação Juvenil", "Consultora Jovem", "Conselheiro de Juventude", "Diretora do Centro Juvenil", "Provedora de Informação Juvenil", "Mentor Jovem", "Líder da Missão de Informação", "Conselheira de Juventude", "Técnica de Informação e Aconselhamento Juvenil", "Agentea de Informação a Jovens"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/095169ac-feee-4fcf-bff7-222ab6d84bc4', 'Comprador de Café Verde', 'Os compradores de café verde compram grãos de café verde a produtores de todo o mundo, por solicitação de empresas de torrefação de café. Têm um conhecimento profundo do processo de produção de café, desde a colheita do fruto até chegar à chávena na sua forma bebível.', 'released', '["Compradora de Café Verde", "Comprador de Café Verde", "Adquirente de Café Verde"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/0959cd1d-f6c8-4362-939a-ad7d5f75d659', 'Professor de Economia', 'Os professores de economia são professores, professores titulares, professores assistentes ou tutores que ensinam alunos no seu domínio de estudos, a economia. Desenvolvem programas curriculares, preparam aulas (palestras, aulas práticas, seminários, ações de formação, etc.), acompanham os resultados da aprendizagem, supervisionam o percurso académico. Realizam investigação académica no seu domínio da economia e apresentam as suas conclusões em conferências e publicações. Estão envolvidos em algumas funções de gestão das universidades.', 'released', '["Professora de Economia", "Professor Universitário de Economia", "Professor de Economia", "Professora Universitária de Economia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/099a901f-91a7-4d26-af2e-f385247dcf20', 'Vendedor de Peças de Automóveis', 'Os vendedores de peças de automóveis vendem peças para veículos automóveis, encomendam peças e identificam peças alternativas.', 'released', '["Vendedor de Peças de Automóveis", "Vendedora de Peças de Automóveis"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/099c6bb0-22d3-4c5d-8bf5-70910af381ef', 'Cabeleireiro', 'Os cabeleireiros oferecem serviços de beleza, tais como o corte, a coloração, o branqueamento, a ondulação permanente e o penteado dos cabelos dos clientes. Perguntam aos seus clientes as suas preferências relativas ao estilo de cabelo, a fim de prestarem serviços personalizados. Os cabeleireiros utilizam máquinas de cortar, tesouras e lâminas de barbear. Fornecem tratamentos do cabelo e do couro cabeludo e lavam com champô, tratam e enxaguam o cabelo.', 'released', '["Cabeleireira", "Cabeleireira de Senhoras", "Cabeleireiro de Homens", "Cabeleireira Unisexo", "Cabeleireiro de Senhoras", "Cabeleireira de Homens", "Cabeleireiro Unisexo", "Cabeleireiro"]'::jsonb, '5141'),
  ('http://data.europa.eu/esco/occupation/09a40a9a-2b60-422c-abe4-96d829bc27df', 'Restaurador de Arte', 'Os restauradores realizam trabalhos de tratamento corretivo com base numa avaliação das características estéticas, históricas e científicas dos objetos de arte. Determinam a estabilidade estrutural das peças de arte e tratam problemas de deterioração química e física.', 'released', '["Técnico de Restauro e Conservação", "Restaurador de Arte", "Técnica de Restauro e Conservação", "Restauradora de Arte"]'::jsonb, '2651'),
  ('http://data.europa.eu/esco/occupation/09a9a956-db70-436f-8398-d85a17f6cdfe', 'Apresentador', 'Os apresentadores apresentam produções de radiodifusão. São o rosto ou a voz destes programas e comunicam em diferentes plataformas, como a rádio, a televisão, teatros ou outros estabelecimentos. Asseguram o entretenimento do seu público e apresentam os artistas ou as pessoas que serão entrevistados.', 'released', '["Moderador", "Locutora", "Locutor", "Moderadora", "Apresentador", "Apresentadora"]'::jsonb, '2656'),
  ('http://data.europa.eu/esco/occupation/09c2b506-cefa-4ba3-b868-a9c2bc4fc6f1', 'Instrutor de Golfe', 'Os instrutores de golfe treinam e ensinam golfe a indivíduos ou grupos. Treinam os clientes através da demonstração e da explicação de técnicas, tais como postura correta e técnicas de swing. Dão opinião sobre a forma como um aluno pode fazer melhor os exercícios e aperfeiçoar o nível de competências. O instrutor de golfe presta aconselhamento sobre que equipamento é mais adequado para o aluno.', 'released', '["Instrutora de Golfe", "Instrutor de Golfe"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/09e070ce-0afe-40bb-be90-530e5d42cdbd', 'Assessor de Desempenho Energético Doméstico', 'Os assessores de desempenho energético doméstico prestam aconselhamento aos indivíduos sobre o fornecimento de energia às suas casas. Avaliam as necessidades individuais e recomendam a fonte adequada de energia, bem como o fornecedor, procurando garantir as vendas de energia. Prestam igualmente aconselhamento sobre as vantagens econômicas e ambientais dos tipos de energia e criam planos energéticos em conformidade com a regulamentação, os requisitos técnicos e as condições da residência.', 'released', '["Assessor de Desempenho Energético Doméstico", "Assessora de Desempenho Energético Doméstico"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/0a3c2d5b-e1f9-4200-9288-62bf3fed3310', 'Administrador de Contas de Sócios', 'Os administradores de contas de sócios asseguram a administração, documentação e comunicação efetivas de contas de sócios. Apoiam o processo de venda de contas de sócios, os atuais pedidos de sócios e os processos de renovação.', 'released', '["Administrador de Contas de Sócios", "Administradora de Contas de Sócios"]'::jsonb, '4110'),
  ('http://data.europa.eu/esco/occupation/0a5001af-ce4b-4787-92e8-62af70089e53', 'Modelador Manual de Formas', 'Os modeladores manuais de formas moldam e fixam à mão os forros e as gáspeas sobre a forma. Os modeladores manuais de formas puxam a parte dianteira, a cintura e a sede da gáspea sobre a forma utilizando ferramentas manuais, com o objetivo de obter a forma final do modelo de calçado. Começam por puxar os bordos da parte dianteira da gáspea sobre a forma e pressionam a cintura e a sede. Em seguida, alisam os bordos, cortam a biqueira e o forro em excesso e utilizam a costura ou cola para fixar a forma.', 'released', '["Modelador Manual de Formas", "Modeladora Manual de Formas"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/0a5356bc-7f81-4e40-971d-c1dc789c5fb4', 'Ama', 'As amas prestam serviços de cuidados qualificados a crianças nas instalações do empregador. Organizam atividades de jogos e entretêm as crianças com jogos e outras atividades culturais e educativas, de acordo com a respetiva idade, preparam as refeições, dão-lhes banho, transportam-nas de e para a escola e ajudam-nas pontualmente com os trabalhos de casa.', 'released', NULL, '5311'),
  ('http://data.europa.eu/esco/occupation/0a7b874b-e5c0-4dea-8b88-dadba9efee1d', 'Comerciante Grossista de Perfumes e Cosméticos', 'Os comerciantes grossistas de perfumes e cosméticos investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Perfumes e Cosméticos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/0a7e24a8-19bd-4b45-83f0-f05d8fedf62d', 'Rebitador', 'Os rebitadores montam várias partes metálicas por meio de pistolas de rebitar, de rebites e de martelos, utilizando uma máquina de rebitar destinados a fazer furos na haste de perfuração da parte metálica e a inserir rebites, cavilhas, nestes furos a fim de os fixar em conjunto.', 'released', '["Rebitadora", "Rebitador"]'::jsonb, '7214'),
  ('http://data.europa.eu/esco/occupation/0a94df75-6e31-4277-a326-1b01e56b6cb3', 'Fabricante de Instrumentos de Cordas', 'Os fabricantes de instrumentos de cordas criam e montam peças para a criação de instrumentos de cordas, de acordo com instruções ou diagramas especificados. Lixam a madeira, medem e colocam cordas, bem como testam a qualidade das cordas e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Instrumentos de Cordas"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/0a9eb24a-13e7-4847-8f6e-a776771ac96b', 'Operador de Máquinas de Criação de Padrões Têxteis', 'Os operadores de máquinas de criação de padrões têxteis criam padrões, desenhos e decoração para têxteis e tecidos utilizando máquinas e equipamentos. Escolhem os materiais a utilizar e controlam a qualidade dos têxteis, tanto antes como após o seu trabalho.', 'released', '["Operadora de Máquinas de Criação de Padrões Têxteis", "Operador de Máquinas de Criação de Padrões Têxteis"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/0ab5c12c-c1c1-4772-8345-aa287d0e391d', 'Analista de Testes de Tecnologia da Informação', 'Os analistas de testes de tecnologia da informação executam funções de teste de ambientes, avaliação de produtos, verificação da qualidade e da exatidão ou criação de scripts de teste. Concebem testes que são depois implementados pelos testadores.', 'released', '["TI"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/0ab64770-9fd7-4baf-8abf-b1ac0e1538ba', 'Operador de Prensa Hidráulica', 'Os operadores de prensa hidráulica instalam e cuidam das prensas hidráulicas, concebidas para moldar peças de metal ferroso e não ferroso, incluindo canos, tubos e perfis ocos e outros produtos da primeira transformação de aço na forma desejada, utilizando forças de compressão geradas por um êmbolo e uma pressão fluida.', 'released', '["Operador de Prensa Hidráulica", "Operadora de Prensa Hidráulica"]'::jsonb, '7221'),
  ('http://data.europa.eu/esco/occupation/0ab77768-9031-4ccc-9ab8-1f73cbb36bc7', 'Operador de Fabricação de Papel Higiênico', 'Os operadores de fabrico de papel higiénico operam uma máquina que recebe papel higiénico, o perfura e enrola para criar vários tipos de papel higiénico.', 'released', '["Operadora de Fabricação de Papel Higiénico", "Operador de Fabricação de Papel Higiénico", "Operadora de Fabricação de Papel Higiênico"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/0abed785-00f8-4692-9f5f-f2b56efdb829', 'Massagista Veterinário', 'Os massagistas veterinários administram tratamentos terapêuticos na sequência de um diagnóstico ou indicação veterinários, os quais se centram na manipulação manual e mecânica dos tecidos moles, com vista a promover a cura e a recuperação de animais, em conformidade com a legislação nacional.', 'released', '["Massagista Veterinária", "Massagista de Animais", "Massagista Veterinário", "Terapeuta Animal"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/0ac8fe65-32e6-4c25-8345-2b87bc7b2698', 'Especialista de Motores de Aeronaves', 'Os especialistas de motores de aeronaves aconselham sobre os procedimentos de manutenção aplicáveis aos motores de aeronaves e helicópteros. Realizam ensaio de funcionamento a componentes e peças de aeronaves, a fim de diagnosticar a aptidão para utilização e as eventuais operações para melhorar o desempenho. Interpretam e prestam apoio para compreender as especificações técnicas fornecidas pelos fabricantes para aplicação nas instalações do aeroporto.', 'released', '["Especialista de Motores Aeronáuticos"]'::jsonb, '7232'),
  ('http://data.europa.eu/esco/occupation/0af6fc82-8e5e-46c6-a4ca-a672ecf7704c', 'Instrutor de Boxe', 'Os instrutores de boxe treinam indivíduos ou grupos de boxe. Dão instruções aos clientes durante o treino e ensinam aos alunos as técnicas de boxe, tais como posição, defesa e diferentes tipos de socos.', 'released', '["Instrutora de Boxe", "Instrutor de Boxe"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/0b14d5d7-1bbe-4403-b9e6-7b0f37fc44fc', 'Técnico de Cuidados a Animais', 'Os técnicos de cuidados a animais prestam cuidados de rotina aos animais não ligados à produção, que podem incluir a alimentação, a dessedentação, a limpeza, o exercício e o enriquecimento, o tratamento, o treino e a monitorização da saúde e do bem-estar, em conformidade com a legislação nacional.', 'released', '["Técnica de Cuidados a Animais", "Tratador de Animais", "Tratadora de Animais", "Cuidadora de Animais", "Técnico de Cuidados a Animais", "Cuidador de Animais"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/0b15375e-dfdd-4047-9efb-096e0aaee7d2', 'Assistente de Loja', 'Os assistentes de loja trabalham em lojas onde desempenham funções de assistência. Ajudam os comerciantes no seu trabalho quotidiano, tal como com a encomenda e a reposição de mercadorias e existências, a prestação de aconselhamento geral aos clientes, a venda de produtos e a manutenção da loja.', 'released', '["Assistentea de Loja"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/0b1d8dcb-d941-4d79-99bf-fc10c1806c43', 'Capitão de Mar e Guerra', 'Os capitães de mar e guerra asseguram que os navios militares estão prontos para serem incluídos nas operações e são mantidos em conformidade com as regras e regulamentos. Supervisionam também o pessoal da marinha e são responsáveis pelas operações do serviço naval.', 'released', '["Capitão-De- Mar- e- Guerra", "Almirante da Armada", "Contra-Almirante", "Capitão-Tenente", "Vice-Almirante", "Comodoro", "Capitão-De-Fragata", "Capitão de Fragata", "Almirante", "Capitãa de Mar e Guerra"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/0b2d3242-22a3-4de5-bd29-efd39cdf2c31', 'Terapeuta de Reabilitação Animal', 'Os terapeutas de reabilitação animal administram tratamentos terapêuticos na sequência de um diagnóstico ou indicação veterinários.', 'released', '["Terapeuta Animal", "Terapeuta de Veterinária", "Terapeuta de Animais", "Terapeuta de Reabilitação Animal"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/0b5dfc02-b825-4445-811d-d39ed442657e', 'Técnico de Emergências Médicas', 'Os técnicos de emergências médicas prestam cuidados de emergência a pessoas doentes, feridas e vulneráveis em situações de emergência médica, antes e durante o transporte para uma unidade de cuidados médicos. Executam e supervisionam a transferência do doente para o meio de transporte. Prestam assistência em situações agudas, aplicam medidas de socorro de emergência e acompanham o processo de transporte. Conforme permitido pela legislação nacional, podem também administrar oxigénio e determinados medicamentos, efetuar a punção de veias periféricas e a perfusão de soluções cristaloides e realizar a intubação endotraqueal, se tal for necessário para a prevenção imediata de situações de ameaça para a vida ou para a saúde de um doente urgente.', 'released', '["Técnico de Emergências Médicas", "Técnica de Emergências Médicas"]'::jsonb, '3258'),
  ('http://data.europa.eu/esco/occupation/0b5e4142-90ad-48a6-8407-ed47b2664954', 'Instalador de Portas', 'Os instaladores de portas instalam portas. Retiram a porta antiga, se estiver presente, preparam a abertura da estrutura e instalam a nova porta direita, reta, prumada e estanque, se tal for necessário. Os instaladores de portas também inspecionam e fazem a manutenção das portas existentes.', 'released', '["Instaladora de Portas", "Instalador de Portas"]'::jsonb, '7115'),
  ('http://data.europa.eu/esco/occupation/0b6e1a0d-63fe-42d4-8dff-2ff187a9fea9', 'Técnico de Potência Hidráulica', 'Os técnicos de eletricidade procedem à instalação e montagem de equipamentos que utilizam a pressão de líquido ou gás para transmitir ou regulamentar a potência. Também procedem à realização de ensaios e manutenção desse equipamento.', 'released', '["Técnica de Potência Hidráulica", "Técnico de Potência Hidráulica"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/0ba06640-e0ac-4911-9e43-289a8e41651e', 'Especialista em Formação de Recursos Humanos', 'Os especialistas em formação de recursos humanos prestam formação, aconselhamento e orientação aos trabalhadores de uma empresa, promovendo a aprendizagem e a melhoria das suas aptidões, competências e conhecimentos, de acordo com as necessidades da empresa. Desenvolvem o potencial existente dos trabalhadores, com vista a aumentar a sua eficiência, motivação, satisfação profissional e empregabilidade.', 'released', '["Corporate Trainer", "RH"]'::jsonb, '2424'),
  ('http://data.europa.eu/esco/occupation/0ba95ace-bdf5-4ee6-92af-32e1ec9c0de6', 'Engenheiro Especialista em Máquinas de Vapor e Caldeiras', 'Os engenheiros de máquinas a vapor fornecem energia e serviços essenciais, como vapor, calor e refrigeração, a instalações. Investigam e desenvolvem novos métodos e melhorias para o fornecimento de serviços essenciais.', 'released', '["Engenheira Especialista em Instalações de Produção de Energia", "Engenheiro Especialista em Máquinas a Vapor", "Engenheiro Especialista em Máquinas de Vapor e Caldeiras", "Engenheira Especialista em Máquinas a Vapor", "Engenheira Especialista em Máquinas de Vapor e Caldeiras"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/0bce6d52-a45e-4826-91ea-68976f1b9d1c', 'Administrador Artístico', 'Os administradores artísticos fazem parte dos profissionais que gerem as necessidades operacionais de uma organização dedicada às artes. Prestam apoio a tarefas financeiras e empresariais e podem trabalhar para organizações de vários tipos, desde organizações com fins lucrativos a organizações governamentais ou sem fins lucrativos. As companhias de dança, os estúdios cinematográficos, os teatros, os museus ou galerias de arte são exemplos destas organizações.', 'released', '["Administradora Artística", "Administrador Artístico", "Administradora Artístico"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/0bf5d25a-2b4d-43b5-b053-beeb210fa43a', 'Professor de Medicina', 'Os professores de Medicina são professores universitários ou docentes em geral e, frequentemente, médicos que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a medicina, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da medicina, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor de Medicina", "Professor Universitário de Medicina", "Professora Universitária de Medicina", "Professora de Medicina"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/0bf68df5-e808-4c27-abf2-6f85440f2d7f', 'Operador de Central Telefônica', 'Os operadores de central telefônica estabelecem ligações telefônicas através da utilização de centrais e de consolas. Também respondem aos pedidos de informação e aos relatórios sobre os problemas de serviço.', 'released', '["Operadora de Central Telefônica", "Operador de Central Telefônica"]'::jsonb, '4223'),
  ('http://data.europa.eu/esco/occupation/0c041d1e-1841-4acb-b0a1-2c387a61bf65', 'Assistente de Consultório Médico', 'Os assistentes de consultórios médicos prestam apoio aos médicos na tomada de medidas afetas à medicina e na realização de atividades de apoio simples durante procedimentos médicos, programas de diagnóstico normalizados e testes normalizados realizados no local de prestação de cuidados, assegurando a higiene, a limpeza, a desinfeção, a esterilização e a manutenção dos dispositivos médicos, bem como a realização das tarefas organizacionais e administrativas necessárias ao funcionamento do consultório médico, sob supervisão e seguindo as indicações do médico.', 'released', '["Assistentea de Consultório Médico"]'::jsonb, '3256'),
  ('http://data.europa.eu/esco/occupation/0c328e98-6e4e-4e96-b99c-56851e666ad0', 'Operador de Cabos Elétricos', 'Os operadores de cabos elétricos procedem à construção e manutenção de cabos elétricos e cabos de comando instalados em tubos e ranhuras subterrâneos. Também ligam e reparam cabos elétricos ligando os clientes à rede de eletricidade.', 'released', '["Operadora de Cabos Elétricos", "Operador de Cabos Elétricos"]'::jsonb, '7413'),
  ('http://data.europa.eu/esco/occupation/0c3672ed-450b-4fcd-a3d0-579a10004486', 'Instrutor de Equitação', 'Os instrutores de equitação aconselham e orientam indivíduos e grupos sobre como montar a cavalo. Ministram aulas e ensinam as técnicas de equitação, incluindo paragens, fazer viragens, trabalho de figuras e saltos. Motivam os clientes e ajudam a melhorar o seu desempenho.', 'released', '["Instrutora de Equitação", "Instrutor de Equitação"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/0c408028-c48f-4df8-ba5d-c3d3be15f5a2', 'Motorista de Entregas em Automóvel e Furgoneta', 'Os motoristas de entregas em automóvel e furgoneta transportam mercadorias e embalagens para locais especificados, por automóvel ou furgoneta. Carregam e descarregam as mercadorias em função de um horário, asseguram o manuseamento adequado das embalagens, seguem as instruções e planeiam o melhor percurso para cada destino.;', 'released', '["Motorista de Entregas"]'::jsonb, '8322'),
  ('http://data.europa.eu/esco/occupation/0c448a27-10ec-43ba-b880-d9938bade424', 'Perito em Investigação Forense Digital', 'Os peritos em investigação forense digital obtêm e analisam informações provenientes de computadores e de outros tipos de dispositivos de armazenamento de dados. Examinam suportes digitais que possam ter sido ocultados, encriptados ou danificados, utilizando métodos forenses, com o objetivo de identificar, preservar, recuperar, analisar e apresentar fatos e opiniões sobre a informação digital.', 'released', '["Perito em Investigação Forense Informática", "Perita em Investigação Forense Digital", "Investigadora Forense Digital", "Investigador Forense Digital", "Perito em Investigação Forense Digital", "Perita em Investigação Forense Informática"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/0c7c9606-fde3-4658-8136-8fe0c9b8bd09', 'Engenheiro de Eletromedicina', 'Os engenheiros de eletromedicina concebem e desenvolvem sistemas, instalações e equipamentos medicotécnicos, como estimuladores cardíacos, scanners de IRM e máquinas de raios X. Controlam todo o processo de fabrico, desde a concepção à realização do produto. As atividades realizadas incluem, nomeadamente, a melhoria da concepção dos produtos, o desenvolvimento de métodos e técnicas para avaliar a adequação dos projetos, a coordenação da produção inicial, o desenvolvimento de procedimentos de teste e a concepção de diagramas de fabrico.', 'released', '["Engenheira de Eletromedicina", "Engenheiro de Eletromedicina"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/0c849f7b-fa3b-4faf-8501-0e50cd200ba1', 'Gerente de Loja de Equipamento de Telecomunicações', 'Os gerentes de equipamento de telecomunicações assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Celulares e Acessórios", "Gerente de Loja de Telefonia Móvel", "Gerente de Loja de Telecomunicações", "Gerentea de Loja de Equipamento de Telecomunicações"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/0cbfa809-2d71-44e5-b736-c4da3c8fe09d', 'Diretor de Importação e Exportação de Maquinaria e Equipamento Agrícola', 'Os diretores de importação e exportação de maquinaria e equipamento agrícola implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas Maquinaria e Equipamento Agrícola", "Diretor de Importação e Exportação de Maquinaria e Equipamento Agrícola", "Diretora de Importação e Exportação de Maquinaria e Equipamento Agrícola", "Diretor de Vendas Maquinaria e Equipamento Agrícola"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/0cca32c2-9308-4927-adb2-14771ab787f0', 'Engenheiro Especialista em Cálculo dos Custos de Projetos de Construção', 'Os engenheiros especialistas em cálculo dos custos de projetos de construção são responsáveis pela gestão dos custos de construção dos projetos de construção desde o início do projeto até à sua conclusão. Visam uma utilização eficiente dos recursos, sem deixar de ter em conta a qualidade, as normas de qualidade e os requisitos do cliente.', 'released', '["Engenheiro Especialista em Cálculo dos Custos de Projetos de Construção", "Engenheira Especialista em Cálculo dos Custos de Projetos de Construção"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/0cd0082a-ca15-4dcd-b352-b7600c916d8e', 'Coordenador de Operações de Navios', 'Os coordenadores de operações de navios gerem o trânsito e o desempenho dos navios fretados, otimizando a programação, mas também avaliando as capacidades e os riscos para os navios de acordo com os diferentes tipos de carga, tais como o petróleo bruto ou outras cargas químicas. Garantem que todas as certificações necessárias estejam em conformidade com os regulamentos e que todos os trabalhadores disponham de passaportes e licenças atualizados. Os coordenadores de operações de navios procedem à programação e manutenção dos registos das operações de manutenção dos navios. A nível operacional, têm contatos com os clientes, acompanham as queixas dos clientes, identificam novas oportunidades e fornecem soluções aos clientes.', 'released', '["Coordenadora de Operações de Navios", "Coordenador de Operações de Navios"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/0cd729a6-ed11-4338-ac4b-d4b924390128', 'Historiador', 'Os historiadores realizam atividades de investigação, análise, interpretação e apresentação do passado das sociedades humanas. Analisam documentos, fontes e vestígios do passado, a fim de compreenderem as sociedades passadas.', 'released', '["Historiador", "Egiptólogo", "Historiadora", "Historiadora de Arte", "Historiador de Arte"]'::jsonb, '2633'),
  ('http://data.europa.eu/esco/occupation/0ce5a9f4-e00a-4bbe-b255-3c63407167a4', 'Responsável Pela Resposta a Ciberincidentes', 'Os responsáveis pela resposta a ciberincidentes monitoram e avaliam o estado dos sistemas de cibersegurança, analisando, avaliando e atenuando o impacto dos incidentes de cibersegurança. Além disso, identificam os agentes maliciosos e as causas profundas dos ciberincidentes. De acordo com o plano de resposta a incidentes da organização, restauram as funcionalidades dos sistemas e processos para um estado operacional, recolhendo provas e documentando as medidas tomadas.', 'released', '["Consultor de Vulnerabilidades", "Consultor de Segurança Informática", "Perita em Segurança Informática", "Consultora de Vulnerabilidade", "Consultora de Vulnerabilidades", "Perito em Segurança Informática", "Consultora de Segurança Informática", "Especialista em Segurança Informática", "Consultor de Vulnerabilidade"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/0d21a30d-25d9-427b-b8e4-339408425ff5', 'Diretor de Desenvolvimento de Produtos Químicos', 'Os diretores de desenvolvimento de produtos químicos são responsáveis pela coordenação técnica e pelo controlo dos processos de produção dos produtos químicos. Orientam uma ou mais unidades de fabrico e supervisionam a aplicação de meios técnicos e humanos, no quadro dos objetivos de volume, qualidade e planejamento. Os diretores de desenvolvimento de produtos químicos concebem e asseguram o cumprimento dos planos de produção e dos calendários de produção. São responsáveis pela aplicação dos processos concebidos para garantir a qualidade do produto fabricado, boas condições de trabalho e práticas ambientais, bem como a segurança do local de trabalho.', 'released', '["Diretor de Desenvolvimento de Produtos Químicos", "Diretora de Operações de Produtos Químicos", "Diretora de Desenvolvimento de Produtos Químicos", "Diretor de Operações de Produtos Químicos"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/0d423a2e-6fb7-4704-8544-bd6c522b3c62', 'Assistente Social Especialista em Cuidados à Infância', 'Os assistentes sociais especialistas em cuidados à infância prestam serviços sociais às crianças e às suas famílias, a fim de melhorarem o seu funcionamento social e psicológico. Visam maximizar o bem-estar da família e proteger as crianças de abusos e negligência. Sempre que necessário, prestam assistência em processos de adoção e na procura de famílias de acolhimento.', 'released', '["Assistentea Social Especialista em Cuidados à Infância"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/0d442b70-5413-4820-bebf-36dd5ce437ac', 'Gestor de Tráfego Aéreo', 'Os gestores de tráfego aéreo coordenam o planejamento do controlo de terra, a manutenção das aeronaves e as relações com os clientes. Trabalham para a utilização mais eficiente dos recursos na orientação da aeronave. Gerem a segurança, a qualidade e os riscos no trabalho quotidiano. Também planificam e comparam o desempenho com outros prestadores de serviços de navegação aérea.', 'released', '["Gestora de Navegação Aérea", "Gestor de Navegação Aérea", "Gestor de Tráfego Aéreo", "Gestora de Tráfego Aéreo", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/0d595b87-a1fc-410c-abbe-88b92cb0d334', 'Professor de Tecnologias da Informação e da Comunicação do Ensino Secundário', 'Os professores de Tecnologias da Informação e da Comunicação do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, as TIC. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio das TIC através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Tecnologias da Informação e da Comunicação do Ensino Secundário", "Professor de TI do Ensino Secundário", "Professora de TI do Ensino Secundário", "Professora de Tecnologias da Informação e da Comunicação do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/0d61e7e7-afde-49ca-b554-4633842be030', 'Operador de Fornos de Cal', 'Os operadores de fornos de cal controlam o equipamento que queima calcário para produzir cal ou dióxido de carbono. Controlam o fluxo dos materiais, o combustível e o ar e observam o fluxo de material, o ar, a temperatura, os gráficos de combustível e os indicadores de oxigénio e procedem a ajustes, se necessário. Também mantêm registos de produção.', 'released', '["Operadora de Fornos de Cal", "Operador de Fornos de Cal"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/0d6bb2cc-06b0-481c-b553-2a973be03254', 'Técnico de Aquicultura de Flutuação ou Submersão', 'Os técnicos de aquicultura de flutuação ou submersão coordenam e supervisionam as atividades de organismos de aquicultura de engorda em sistemas suspensos (estruturas flutuantes ou submersas). Participam em operações de extração e na manipulação de organismos para comercialização. Os técnicos de aquicultura de flutuação ou submersão supervisionam a manutenção do equipamento e das instalações (gaiolas, balsas, palangres, bouchot).', 'released', '["Técnico de Aquicultura de Flutuação ou Submersão", "Técnica de Aquicultura de Flutuação ou Submersão"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/0d7ae791-653e-4297-9f61-8bad87f61d57', 'Técnico de Meteorologia', 'Os técnicos de meteorologia recolhem grandes quantidades de informações meteorológicas para usuários de informação meteorológica, como as companhias aéreas ou os institutos de meteorologia. Operam instrumentos de medição especializados para fazer previsões meteorológicas exatas e comunicam as suas observações. Os técnicos de meteorologia ajudam os meteorologistas nas suas operações científicas.', 'released', '["Técnico de Metereologia", "Técnica de Metereologia", "Técnica de Meteorologia"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/0d93706d-32fd-4de3-aa08-be1003e325da', 'Químico', 'Os químicos realizam investigação laboratorial mediante ensaio e análise da estrutura química das substâncias. Traduzem os resultados da investigação em processos de produção industrial que são posteriormente utilizados no desenvolvimento ou melhoramento de produtos. Os químicos também testam a qualidade dos produtos fabricados e o seu impacto ambiental.', 'released', '["Especialista em Química Analítica", "Especialista em Química Orgânica", "Especialista em Química Inorgânica", "Especialista em Química Física", "Química"]'::jsonb, '2113'),
  ('http://data.europa.eu/esco/occupation/0d9eed6b-4908-4112-bf37-ae08e2f0f326', 'Vendedor de Munições', 'Os vendedores de munições vendem armas e munições para uso individual em lojas especializadas.', 'released', '["Vendedora de Munições", "Vendedor de Munições"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/0da2ee5c-b480-498f-97a8-a292a0f4c54c', 'Operador de Som', 'Os operadores de som controlam o som de um espetáculo com base no conceito artístico ou criativo, em interação com os artistas. O seu trabalho é influenciado e influencia os resultados dos outros operadores. Por conseguinte, os operadores trabalham em estreita colaboração com os criadores e os artistas. Preparam os excertos áudio, supervisionam a instalação, dirigem a equipe técnica, programam o equipamento e operam o sistema sonoro. O seu trabalho baseia-se em planos, instruções e outra documentação. ;', 'released', '["Operador de Som", "Operadora de Som"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/0da51178-e386-4534-ae71-15ba789ad756', 'Operador de Máquinas de Lavar', 'Os operadores de máquinas de lavar operam e controlam máquinas que utilizam produtos químicos para lavar ou secar artigos, tais como vestuário e vestuário de couro, linhos, reposteiros ou tapetes, garantindo a manutenção da cor e da textura destes artigos. Trabalham em lavandarias e empresas de lavandaria industrial e procedem à triagem dos artigos recebidos de clientes por tipo de tecido. Também determinam a técnica de limpeza a aplicar.', 'released', '["Operador de Máquinas de Lavandaria", "Operadora de Máquinas de Lavandaria", "Operador de Lavandaria", "Operadora de Lavandaria", "Operadora de Máquinas de Lavar"]'::jsonb, '8157'),
  ('http://data.europa.eu/esco/occupation/0da75680-fbf9-44d8-802a-ac12eb425a34', 'Técnico de Biotecnologia', 'Os técnicos de biotecnologia prestam assistência aos cientistas na realização de trabalhos tecnológicos. Trabalham em contextos laboratoriais onde ajudam os cientistas na investigação, no desenvolvimento e no ensaio de formas de biotecnologia. Instalam equipamentos de laboratório, preparam testes científicos e compilam dados científicos.', 'released', '["Técnico de Biotecnologia", "Técnica de Biotecnologia"]'::jsonb, '3141'),
  ('http://data.europa.eu/esco/occupation/0dae04a4-fa4c-40d3-8518-122cc0f7bfcf', 'Operador de Granuladores', 'Os operadores de granuladores procedem à mistura e à granulação dos ingredientes em pó, utilizando máquinas de mistura e moagem, a fim de preparar os ingredientes para serem transformados em comprimidos. Definem a dimensão do lote e seguem as fórmulas dos ingredientes.', 'released', '["Operadora de Granuladores", "Operador de Granuladores"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/0dce2f9b-eda5-4dc4-ba74-36eeed8c9a44', 'Audiodescritor', 'Os audiodescritores apresentam oralmente o que acontece num tela ou num palco para que os invisuais ou as pessoas com deficiência visual possam desfrutar de espetáculos audiovisuais, espetáculos ao vivo ou eventos desportivos. Produzem guiões de audiodescrição para programas e eventos e utilizam a sua voz para os registar.', 'released', '["Audiodescritora", "Audiodescritor"]'::jsonb, '2656'),
  ('http://data.europa.eu/esco/occupation/0dd7e6cd-2e5a-4fae-9ce0-6a3622d4019f', 'Supervisor de Construção', 'Os supervisores de construção acompanham os procedimentos de todas as fases do processo de construção. Coordenam as diferentes equipes, atribuem tarefas e resolvem problemas.', 'released', '["Supervisora de Construção", "Supervisor de Construção", "Mestre de Obras"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/0ddbf393-38f1-4c22-b14c-fe775008f321', 'Diretor de Marketing', 'Os diretores de marketing gerem as operações de marketing de alto nível numa empresa. Coordenam todos os esforços relacionados com as atividades de marketing, promoção e publicidade em unidades ou áreas geográficas. Asseguram que as diferentes atividades destinadas a sensibilizar os produtos são rentáveis para a empresa. Tomam decisões e elaboram relatórios sobre os projetos de marketing e os respetivos custos.', 'released', '["Diretora de Mercados", "Diretor de Marketing", "Diretora de Marketing", "Diretora de Vendas", "Diretor de Mercados", "Diretor de Vendas"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/0deaceea-69d8-4304-bc80-0b3d0491a241', 'Responsável Pela Realização de Inquéritos de Campo', 'Os responsáveis pela realização de inquéritos de campo organizam e supervisionam investigações e inquéritos a pedido de um patrocinador. Monitorizam a sua aplicação de acordo com os requisitos de produção e lideram uma equipe de investigadores no terreno.', 'released', NULL, '3341'),
  ('http://data.europa.eu/esco/occupation/0e09c42d-bff2-4c35-8e1f-639a6dddaa5d', 'Operador de Perfuradora Rotativa', 'Os operadores de perfuradora rotativa procedem à preparação, operação e manutenção de furadoras simples ou multibrocas, utilizando uma barra de brocar com uma ferramenta de corte temperado, rotativo e multipontiagudo, a fim de ampliar um orifício existente numa peça fabricada.', 'released', '["Operadora de Perfuradora Rotativa", "Operador de Perfuradora Rotativa"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/0e216d47-fc12-43e9-8953-ad8ba11f4b96', 'Maestro', 'Os maestros e as maestrinas dirigem conjuntos musicais durante os ensaios, gravam sessões e espetáculos ao vivo e ajudam os músicos a concretizar todo o seu potencial. Podem trabalhar com vários tios de conjuntos musicais, como coros e orquestras. Os maestros e as maestrinas ajustam o andamento (velocidade), o ritmo, a dinâmica (mais alto ou mais baixo) e a articulação (suave ou destacada) da música recorrendo a gestos e, por vezes, dançando a fim de motivarem os músicos a tocar de acordo com a partitura.;', 'released', '["Maestro de Orquestra", "Regente de Orquestra", "Maestro de Banda", "Maestro de Coro", "Maestra"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/0e68f523-3206-4896-b725-44150dd22057', 'Supervisor de Produção de Artigos de Marroquinaria', 'Os supervisores de produção de artigos de marroquinaria acompanham e coordenam as atividades de produção diárias de uma fábrica de produção de artigos de marroquinaria. Supervisionam o controlo de qualidade e gerem o pessoal de produção de artigos de marroquinaria. O trabalho envolve também a organização do fluxo de trabalho, bem como o acompanhamento do plano e dos custos de produção.', 'released', '["Supervisora de Produção de Artigos de Marroquinaria", "Supervisor de Produção de Artigos de Marroquinaria"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/0e99c929-364f-4b0a-8a64-2aab42420f00', 'Engenheiro de Energias Renováveis', 'Os engenheiros de energias renováveis investigam fontes alternativas de energia, a fim de conceber sistemas de produção de energias renováveis. Procuram otimizar a produção de energia a partir de fontes renováveis e reduzem as despesas de produção e a pressão ambiental. Concebem sistemas centrados na sustentabilidade e eficiência energética.', 'released', '["Consultor de Energias Renováveis", "Engenheira de Energias Renováveis", "Projetista de Solar Térmico", "Engenheira de Sistemas de Energias Renováveis", "Engenheira Especialista em Energia Eólica", "Engenheira Especialista em Energia Solar", "Engenheiro de Energias Renováveis", "Consultora de Energias Renováveis", "Engenheiro Especialista em Energia Eólica", "Engenheiro Especialista em Energia Solar", "Engenheiro Especialista em Operação e Manutenção de Turbinas", "Engenheiro de Sistemas de Energias Renováveis", "Engenheira Especialista em Operação e Manutenção de Turbinas", "Projetista de Sistemas Solares Térmicos"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/0ea36a48-a27d-4515-b61f-3cab395cf60f', 'Técnico de Microeletrônica', 'Os técnicos de microeletrónica colaboram com engenheiros no domínio da microeletrónica no desenvolvimento de pequenos dispositivos e componentes eletrônicos, como microprocessadores, chips de memória e circuitos integrados, para comandos de máquinas e de motores. Os técnicos de microeletrónica são responsáveis pela construção, pelo ensaio e pela manutenção de sistemas e dispositivos microeletrónicos.', 'released', '["Técnico de Microeletrónica", "Técnica de Microeletrónica", "Técnica de Microeletrônica"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/0ea5fdff-074c-4094-98b9-04432361e4d9', 'Operador de Gruas de Torre', 'Os operadores de gruas de torre trabalham com gruas de torre, um guindaste constituído por um braço montado na horizontal num poste vertical, juntamente com os motores necessários e o gancho de elevação ligado ao braço. Os operadores controlam a grua numa cabina de controlo ou utilizam o controlo por rádio.', 'released', '["Operadora de Gruas de Torre", "Operador de Gruas de Torre"]'::jsonb, '8343'),
  ('http://data.europa.eu/esco/occupation/0ec62c2e-30c9-434e-bf36-5277a0840450', 'Técnico de Renovação Automóvel', 'Os técnicos de renovação automóvel procedem à revisão e renovação das partes interiores de veículos, tais como peças de motores e bombas para motores diesel.', 'released', '["Técnico de Renovação Automóvel", "Técnica de Renovação Automóvel"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/0ecedad1-1144-45ff-83db-a3c4db393036', 'Gestor de Investimento', 'Os gestores de investimento administram a carteira de investimentos de uma empresa. Realizam um acompanhamento próximo dos investimentos, visando as soluções mais rentáveis representadas em produtos financeiros ou valores mobiliários. Analisam os comportamentos dos mercados financeiros, as taxas de juro e a posição das empresas, a fim de prestar aconselhamento sobre riscos e rendibilidade ao cliente.', 'released', '["Gestora de Investimento", "Gestor de Investimento", "Gerente"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/0ededdc2-050a-4ec3-8e70-6295105fcd19', 'Operador de Centros de Contato', 'Os operadores de centros de contato tratam das chamadas recebidas ou realizadas de uma empresa. Ligam aos clientes existentes e potenciais para a promover bens e serviços. Também realizam vendas e organizam visitas de venda.', 'released', '["Operador de Call Centre", "Operador de Telemarketing", "Operadora de Telemarketing", "Operadora de Call Centre", "Operador de Centros de Contato", "Operadora de Centros de Contato"]'::jsonb, '5244'),
  ('http://data.europa.eu/esco/occupation/0ee5a71a-3c85-48af-bf81-824d3561737a', 'Criador de Animais para a Produção de Peles', 'Os criadores de animais para a produção de peles supervisionam a produção e o cuidado diário dos animais para a produção de peles. Zelam pela saúde e pelo bem-estar dos animais para a produção de peles.', 'released', '["Criadora de Animais para a Produção de Peles", "Criador de Animais para Curtumes", "Criadora de Animais Criados para a Produção de Pele", "Criadora de Animais para Curtumes", "Criador de Animais para a Produção de Peles", "Criador de Animais Criados para a Produção de Pele"]'::jsonb, '6129'),
  ('http://data.europa.eu/esco/occupation/0ee67d5e-8de9-48f0-97c5-ba23d486b1e9', 'Secretário de Estado', 'Os secretários de Estado prestam assistência aos chefes dos serviços da administração pública, tais como os ministros, e ajudam na supervisão dos procedimentos do departamento. Prestam assistência na direção das políticas, operações e pessoal dos serviços e realizam o planejamento, a afetação de recursos e funções relativas à tomada de decisões.', 'released', '["Subsecretária de Estado", "Secretária de Estado", "Subsecretário de Estado", "Secretário de Estado", "Ministra", "Ministro"]'::jsonb, '1111'),
  ('http://data.europa.eu/esco/occupation/0eebf6d2-af43-4a18-b4b7-668fb6433b42', 'Técnico de Iluminação Inteligente', 'Os técnicos de iluminação inteligentes procedem à instalação, preparação, controlo e manutenção do equipamento de iluminação digital e automatizado, a fim de proporcionar a qualidade de iluminação ideal para um espetáculo vivo. Cooperam com a equipe de apoio de estrada para descarregar, instalar e operar equipamentos e instrumentos de iluminação.', 'released', '["Técnica de Ilumincação Inteligente", "Técnico de Ilumincação Inteligente", "Técnica de Iluminação Inteligente"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/0f086907-96a6-4e88-bf00-a84295125a6a', 'Missionário', 'Os missionários supervisionam a execução de missões de proximidade a partir de uma fundação religiosa. Organizam a missão e desenvolvem os seus objetivos e estratégias, além de assegurarem a execução dos objetivos da missão, bem como a aplicação das políticas. Desempenham funções administrativas de manutenção de registos e facilitam a comunicação com as instituições competentes no local da missão.', 'released', '["Missionária", "Missionário"]'::jsonb, '2636'),
  ('http://data.europa.eu/esco/occupation/0f2c04f1-9001-4a77-884f-1ea16949f6f6', 'Técnico de Engenharia de Material Rolante', 'Os técnicos de engenharia de material rolante desempenham funções técnicas para ajudar os engenheiros de material rolante nos processos de concepção, desenvolvimento, fabrico e ensaio, bem como na instalação e na manutenção de veículos ferroviários, como vagões, unidades múltiplas, carruagens e locomotivas. Realizam também experiências, recolhem e analisam dados e comunicam as suas conclusões.', 'released', '["Técnico de Engenharia de Material Rolante", "Técnica de Engenharia de Material Rolante"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/0f5b4653-50b2-413a-826d-39d447480c21', 'Gestor Imobiliário', 'Os gestores imobiliários gerem e supervisionam os aspetos operacionais dos imóveis comerciais ou residenciais, como apartamentos particulares, edifícios de escritórios e lojas de venda a retalho. Negoceiam contratos de arrendamento, identificam e planificam novos projetos imobiliários e a construção de novos edifícios através de parcerias com um promotor para identificar o local adequado para novos edifícios, coordenam os estudos de viabilidade de novas construções e supervisionam todos os aspetos administrativos e técnicos relacionados com a expansão da empresa. Procedem à manutenção das instalações e procuram aumentar o seu valor. Contratam, formam e supervisionam o pessoal.', 'released', '["Gestor Imobiliário", "Gestora Imobiliária", "Gerente", "Gestora Imobiliário"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/0f5cc4eb-925d-4b99-be6d-b0964a253a9a', 'Técnico de Engenharia Civil', 'Os técnicos de engenharia civil ajudam a conceber e executar projetos de construção e executam tarefas de organização, por exemplo no planejamento e acompanhamento, bem como na apresentação de propostas e na faturação de obras de construção. Calculam também as necessidades de materiais e ajudam na aquisição e organização, além de assegurarem a qualidade dos materiais de construção. Os técnicos de engenharia civil podem desempenhar tarefas técnicas na área da engenharia civil e desenvolver e prestar aconselhamento sobre estratégias de aplicação de políticas relativas a obras rodoviárias, semáforos, sistemas de esgotos e de gestão da água.', 'released', '["Técnica de Engenharia Civil", "Técnico de Construção Civil", "Engenheiro Técnico Civil", "Técnica de Construção Civil", "Técnico de Engenharia Civil", "Engenheira Técnica Civil"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/0f63619d-63ea-4345-81f5-4673353fe8d2', 'Escriturário de Tribunal', 'Os escriturários de tribunal prestam assistência aos juízes de uma instituição judicial. Tratam de inquéritos sobre processos judiciais e prestam assistência aos juízes em várias tarefas, tais como a realização de investigação jurídica na preparação dos processos ou a elaboração de pareceres. Também contactam as partes envolvidas nos processos e informam os juízes e outros funcionários judiciais.', 'released', '["Escriturário de Tribunal", "Escriturária de Tribunal"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/0f7c84c5-1c0d-4fc1-8949-07dbe8bd34ef', 'Designer Têxtil', 'Os designers têxteis conceptualizam produtos têxteis tendo em conta a comunicação visual e o desempenho funcional.', 'released', '["Especialista em Design Têxtil para Malhas", "Especialista em Design Têxtil para Estamparia", "Designer Gráfico", "Especialista em Design Têxtil", "Especialista em Padronagem", "Designer Gráfica", "Especialista em Design Têxtil para a Tecelagem", "Criadora de Padrões", "Criador de Padrões"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/0f845e64-de8b-431e-9fe3-1bccf8e1c5b9', 'Especialista em Controle de Qualidade de Produtos Farmacêuticos', 'Os especialistas em controlo de qualidade de produtos farmacêuticos realizam inspeções e medições de precisão, a fim de testar e garantir a qualidade dos produtos farmacêuticos. Estão envolvidos em toda a fase de desenvolvimento de um produto farmacêutico até que este esteja pronto para o mercado. Tal inclui o processo de aquisição de licenças de ensaios clínicos, o aconselhamento do pessoal do desenvolvimento farmacêutico sobre os requisitos regulamentares e a avaliação do conteúdo do folheto informativo e de outra documentação sobre o produto. Além disso, os especialistas em controlo de qualidade de produtos farmacêuticos recolhem e avaliam as informações sobre os efeitos secundários do produto e comunicam estes conhecimentos tanto a nível interno como às autoridades competentes.', 'released', '["Especialista em Controle de Qualidade de Medicamentos"]'::jsonb, '2262'),
  ('http://data.europa.eu/esco/occupation/0f898624-9b89-41ba-adcf-9360ade85a62', 'Técnico de Sistemas de Aproveitamento de Águas', 'Os técnicos de sistemas de aproveitamento de águas instalam sistemas para recuperar, filtrar, armazenar e distribuir água de diferentes fontes, tais como as águas pluviais e as águas residuais domésticas.', 'released', '["Técnico de Sistemas de Aproveitamento de Águas", "Técnico de Sistemas de Aproveitamento de Águas Pluviais", "Técnica de Sistemas de Aproveitamento de Águas", "Técnica de Sistemas de Aproveitamento de Águas Pluviais"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/0f905036-055f-41d9-b292-e3c02617a193', 'Operador de Prensagem', 'Os operadores de prensagem cuidam de equipamento para secar, misturar e comprimir as aparas de metal em briquetes para utilização numa fundição.', 'released', '["Operador de Prensagem", "Operadora de Prensagem"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/0fc6c577-7d5d-4bcd-8ce8-4a4114d6a809', 'Montador de Moldes de Correias Trapezoidais', 'Os montadores de moldes de correias trapezoidais operam a máquina que pressiona as correias numa forma de V. Esticam a correia à volta do molde e colocam a máquina em funcionamento.', 'released', '["Montador de Moldes de Correias Trapezoidais", "Montadora de Moldes de Correias Trapezoidais"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/0fdc5efb-d38e-4019-bede-0ce55404549d', 'Operador de Máquina de Fabricação de Doces', 'Os operadores de máquinas de fabrico de guloseimas asseguram o correto funcionamento de máquinas que pesam, medem e misturam ingredientes para o fabrico de guloseimas. Formam pastas macias, espalhando-as em placas de arrefecimento e aquecimento, cortando-as de forma manual ou mecânica. Vertem as guloseimas em moldes ou através de uma máquina que extrude o doce. ;', 'released', '["Operador de Máquina de Preparar Massas para Rebuçados", "Operadora de Máquina de Preparar Massas para Rebuçados", "Operadora de Máquina de Fabricação de Doces", "Operadora de Máquina de Moldar Rebuçados", "Operador de Máquina de Fabricação de Doces", "Operador de Máquina de Moldar Rebuçados"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/1009be17-7efd-45f1-a033-566bf179c588', 'Chef', 'Os chefes são profissionais culinários com talento para a criatividade e a inovação para proporcionar uma experiência gastronómica única.', 'released', '["Chef de Cozinha", "Chef"]'::jsonb, '3434'),
  ('http://data.europa.eu/esco/occupation/10291962-c0c7-4e5b-a7ed-0762b4d9b010', 'Farmacologista', 'Os farmacologistas estudam a forma como os fármacos e os medicamentos interagem com os organismos, os sistemas vivos e as suas partes (ou seja, células, tecidos ou órgãos). A sua investigação visa identificar substâncias que podem ser ingeridas pelo ser humano e que exercem funções bioquímicas adequadas para a cura de doenças.', 'released', NULL, '2131'),
  ('http://data.europa.eu/esco/occupation/102e75c8-3b47-4964-9b47-30a980aed25c', 'Analista Especializado em Recuperação de Catástrofes Informáticas', 'Os analistas especializados em recuperação de catástrofes informáticas desenvolvem, mantêm e implementam estratégias e soluções de continuidade e de recuperação de catástrofes informáticas. Apoiam as equipes técnicas, avaliam os riscos, concebem e desenvolvem procedimentos, documentação e estratégias para a recuperação de catástrofes, a fim de permitir a continuidade e a recuperação das funções de uma empresa com uma perda mínima de dados. Além disso, coordenam as cópias de segurança, os testes e as validações do sistema.', 'released', '["Analista Especializada em Recuperação de Catástrofes Informáticas", "Analista de Segurança Informática", "Analista de Continuidade Operacional", "Analista de Segurança das Tecnologias de Informação e Comunicação", "Analista Especializado em Recuperação de Catástrofes Informáticas", "Analista de Recuperação de Falhas", "Analista de Segurança da Tecnologia da Informação"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/103aaf7a-48da-4e25-99fc-5cf1ee1388b1', 'Filigranista', 'Os filigranistas criam um tipo delicado de joias, geralmente de ouro e prata, chamada filigrana. Soldam contas diminutas, fios torcidos ou uma combinação dos dois à superfície de um objeto no mesmo metal, dispostos num motivo artístico.', 'released', '["Ourives"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/1044dedc-81d1-48b6-96b3-ced5393b2de1', 'Professor de Apoio a Alunos Sobredotados', 'Os professores de alunos sobredotados ensinam alunos com capacidades avançadas numa ou em várias áreas. Acompanham os progressos dos alunos, sugerem atividades suplementares para estimular e alargar as suas competências, introduzem novas tópicos e matérias no seu estudo, atribuem trabalhos e classificam testes e exames, e, por último, prestam-lhes apoio emocional quando necessário. Os professores que trabalham com alunos sobredotados sabem como fomentar os seus interesses e dar-lhes confiança para viver com a sua inteligência.;', 'released', '["Professora de Apoio a Alunos Sobredotados", "Professor de Apoio a Alunos Sobredotados"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/10469d70-78a3-4650-9e29-d04de13c62c1', 'Designer de Sistemas Embarcados', 'Os designers de sistemas embarcados traduzem e concebem requisitos, bem como o plano ou a arquitetura de alto nível, de um sistema de controle embarcado de acordo com as especificações técnicas do software.', 'released', '["Designer de Sistemas Informáticos Embarcados", "Designer de Sistemas Embarcados"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/106f79e4-6264-45f1-9e7a-297435cd684b', 'Testador de Software', 'Os testadores de software realizam testes de software. Podem igualmente proceder ao seu planejamento e concepção. Além disso, podem realizar a depuração de erros e a reparação de software, embora estas funções sejam sobretudo da responsabilidade de designers e programadores. Asseguram o correto funcionamento das aplicações antes de as entregarem a clientes internos e externos.', 'released', '["Responsável por Testes de Software", "Testadora de Software", "Testadora de Módulos", "Testador de Módulos", "Testadora de Software de Aplicações", "Responsável Pelos Testes de Software", "Testador de Software", "Testador de Software de Aplicações"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/107865e2-ba60-4e4f-b57d-4dd5064f517f', 'Operador de Retorcedeiras', 'Os operadores de retorcedeiras operam máquinas que giram duas ou mais fibras em conjunto num fio. Manuseiam as matérias-primas, preparam-nas para transformação e utilizam as retorcedeiras para o efeito. Também realizam a manutenção de rotina da máquina.', 'released', '["Operador de Retorcedeiras", "Operadora de Retorcedeiras"]'::jsonb, '8151'),
  ('http://data.europa.eu/esco/occupation/107d21c6-973b-411c-89fd-69da48d29ada', 'Diretor de Mina', 'Os diretores de minas controlam, dirigem, planificam e coordenam as atividades de extração mineira. Têm a responsabilidade legal pela segurança e são também responsáveis pelo impacto ambiental. Supervisionam a aquisição, a instalação, a manutenção e o armazenamento de instalações e equipamentos de exploração mineira. Gerem e dirigem de acordo com o código de conduta da organização.', 'released', '["Diretora de Pedreira", "Diretor de Pedreira", "Diretor de Mina", "Diretora de Mina"]'::jsonb, '1322'),
  ('http://data.europa.eu/esco/occupation/10841c22-0154-48ab-aaca-ce61b9a8e448', 'Técnico de Fabricação de Baterias', 'Os técnicos de fabrico de baterias testam e embalam baterias, tais como células, acumuladores e sistemas, assegurando que cumprem as normas de qualidade e as especificações de desempenho exigidas. Trabalham com uma equipe de engenheiros e cientistas a fim de preparar as baterias para várias aplicações, como veículos elétricos, eletrônica de consumo e armazenamento na rede.', 'released', '["Técnica de Fabricação de Baterias", "Técnico de Fabricação de Baterias"]'::jsonb, '3113'),
  ('http://data.europa.eu/esco/occupation/1084e2d6-b153-4090-8065-c9231f71d4f0', 'Técnico de Optometria', 'Os técnicos de optometria procedem à montagem, reparação e concepção de várias partes de óculos, como lentes, armações, padrões e artigos de ótica. Executam o corte, a inspeção, a montagem e o polimento de todas as peças utilizando diversas máquinas e ferramentas manuais. Os técnicos de optometria moldam, retificam e revestem as lentes para óculos sujeitos a receita médica. Encaixam lentes acabadas em armações de óculos. Os técnicos de optometria asseguram que as lentes estão em conformidade com as prescrições do oculista, do médico especialista em oftalmologia ou do optometrista. Podem também trabalhar com outros instrumentos óticos associados e na sua manutenção.', 'released', '["Técnico de Optometria", "Técnica de Optometria"]'::jsonb, '3254'),
  ('http://data.europa.eu/esco/occupation/1092dd4c-b96b-4b3f-87fe-4a9e8d1937fb', 'Assistente Universitário Estagiário', 'Os assistentes universitários estagiários são alunos licenciados ou recém-licenciados empregados com um contrato de trabalho temporário numa universidade ou num estabelecimento de ensino superior com responsabilidades relacionadas com o ensino. Prestam assistência ao professor do curso específico pelo qual são responsáveis na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos.', 'released', '["Assistente Universitário Estagiário", "Assistente Universitária Estagiária", "Assistentea Universitário Estagiário"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/109e0a5d-203d-4af6-8f70-692111335ec3', 'Gestor dos Serviços de Qualidade', 'Os gestores dos serviços de qualidade gerem a qualidade dos serviços em organizações empresariais. Asseguram a qualidade das operações da empresa, tais como as exigências dos clientes e as normas de qualidade dos serviços. Os gestores dos serviços de qualidade controlam o desempenho da empresa e implementam alterações quando necessário.', 'released', '["Gestora dos Serviços de Garantia da Qualidade", "Diretor de Garantia da Qualidade", "Gestora dos Serviços de Qualidade", "Gestor dos Serviços de Qualidade", "Gestor dos Serviços de Garantia da Qualidade", "Diretora de Garantia da Qualidade", "Gerente"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/11103139-4555-4696-b331-1ee581ff9a38', 'Vendedor de Artigos Desportivos', 'Os vendedores de artigos desportivos vendem artigos de desporto, material de pesca, artigos para acampamento, barcos e bicicletas em lojas especializadas.', 'released', '["Vendedora de Artigos Desportivos", "Vendedor de Artigos Desportivos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/114c5a6c-1869-4a67-8ec0-660ec303f8cc', 'Professor de Apoio Educativo', 'Os professores de apoio educativo ajudam os alunos com dificuldades gerais de aprendizagem. Os professores de apoio educativo centram-se nas competências básicas como a numeracia e literacia e, por conseguinte, ensinam competências básicas como a escrita, a leitura, a matemática e as línguas e trabalham para uma instituição de ensino como uma escola primária ou secundária. Apoiam os alunos nos seus trabalhos escolares, planificam estratégias de aprendizagem, identificam as suas necessidades de aprendizagem e o seu progresso e atuam em conformidade. Podem trabalhar em diversos ambientes de ensino e funcionar como apoio a outros professores ou gerir a sua própria turma.', 'released', '["Professor de Apoio Educativo", "Professora de Apoio Educativo"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/114e1eff-215e-47df-8e10-45a5b72f8197', 'Especialista em Vendas de Energias Renováveis', 'Os especialistas em vendas de energias renováveis aconselham os clientes sobre as vantagens e as desvantagens das diferentes fontes de energia renováveis. Realizam inquéritos e entrevistas a fim de analisarem a procura e as opiniões sobre as energias renováveis e procuram aconselhar os clientes sobre a fonte de energia renovável mais vantajosa para os fins pretendidos.', 'released', '["Sales"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/11695786-9fb7-4895-b161-0480419107e4', 'Instrutor de Desportos', 'Os instrutores de desportos iniciam as pessoas num desporto e ensinam-lhes as competências necessárias para o desempenho do desporto. Têm um forte domínio de um ou mais desportos, que muitas vezes são desportos de aventura, e sabem como motivar as outras pessoas e partilham com as mesmas o apreço pela atividade.', 'released', '["Instrutora de Desportos", "Instrutor de Desportos"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/116b4c55-5bd0-41e9-9227-98d7ecffeaf6', 'Professor de Sociologia', 'Os professores de Sociologia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Sociologia, que é predominantemente de natureza académica. Prestam assistência ao professor do curso específico pelo quais são responsáveis na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da Sociologia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Sociologia", "Professor de Sociologia", "Professora Universitária de Sociologia", "Professor Universitário de Sociologia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/11830794-108c-48fe-a282-2cd7a2945344', 'Criador de Jogos de Azar', 'Os criadores de jogos de azar concebem jogos de azar, apostas e lotarias inovadores. Determinam o design, as regras ou a estrutura de um jogo. Os criadores de jogos de azar também podem fazer demonstrações do jogo.;', 'released', '["Designer de Jogos de Azar", "Criadora de Jogos de Loteria", "Criadora de Jogos", "Designer de Jogos de Loteria", "Criador de Jogos de Azar", "Criador de Jogos de Apostas", "Designer de Jogos", "Criadora de Jogos de Apostas", "Criador de Jogos de Loteria", "Criadora de Jogos de Azar", "Criador de Jogos"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/11833a96-fc27-4b03-a53d-892ac891a2bb', 'Técnico de Engenharia de Produção', 'Os técnicos de engenharia de produção planeiam a produção, acompanham os processos de produção e desenvolvem e testam soluções para resolver problemas técnicos. Trabalham em estreita colaboração com engenheiros e técnicos, inspecionam produtos, realizam testes e recolhem dados.', 'released', '["Técnica de Engenharia de Produção", "Técnico de Engenharia de Produção"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/1185cfe1-49a7-44a7-8dee-45b2f36727f9', 'Agente de Educação Ambiental', 'Os agentes de educação ambiental são responsáveis pela promoção da conservação e do desenvolvimento do ambiente. Visitam as escolas e as empresas para dar palestras, produzem recursos educativos e sites, lideram passeios guiados pela natureza, proporcionam cursos de formação relevantes e ajudam com atividades de voluntariado e projetos de conservação. Muitos jardins empregam um agente de educação ambiental para oferecer orientação durante as visitas escolares.', 'released', '["Agentea de Educação Ambiental"]'::jsonb, '5113'),
  ('http://data.europa.eu/esco/occupation/11a6d0f6-e692-4774-aa5f-193b67d31022', 'Kinesiologista', 'Os kinesiologistas estudam e investigam o movimento do corpo, dos seus músculos e das suas partes. Analisam e utilizam dados e métodos científicos para melhorar os movimentos do corpo, geralmente em seres humanos, mediante a compreensão de áreas como a fisiologia, a cinética, a neurologia e a biologia. Reconhecem os efeitos que alguns fatores, como a condição física, têm nos movimentos e desenvolvem soluções para melhorar a mecânica geral e a mobilidade.', 'released', NULL, '2269'),
  ('http://data.europa.eu/esco/occupation/11b6390b-1e48-4903-a5df-d3e04b451a19', 'Químico da Indústria Cosmética', 'Os químicos da indústria cosmética desenvolvem fórmulas para criar e testar novos produtos cosméticos e melhorar os produtos cosméticos existentes, tais como perfumes e fragrâncias, batom, loções impermeáveis e maquilhagem, tintas capilares, sabonetes e detergentes com propriedades especiais, medicamentos de uso tópico ou suplementos de saúde.', 'released', '["Formuladora de Produtos Cosmética", "Química da Indústria Cosmética", "Formulador de Produtos de Cosmética", "Químico da Indústria Cosmética", "Especialista no Desenvolvimento de Produtos de Cosmética"]'::jsonb, '2113'),
  ('http://data.europa.eu/esco/occupation/11d72bd6-779a-4643-9962-313833740094', 'Cientista Ambiental', 'Os cientistas ambientais identificam problemas e encontram soluções para minimizar os riscos ambientais através da realização de análises de amostras, nomeadamente do ar, da água ou do solo. Aconselham ou elaboram políticas ambientais e visam melhorar o abastecimento de água e gerir os locais de eliminação de resíduos. Os cientistas ambientais realizam avaliações dos riscos ambientais e analisam o impacto ambiental de novas soluções, dos estaleiros de construção ou das alterações ambientais, assegurando a aplicação da regulamentação ambiental.', 'released', NULL, '2133'),
  ('http://data.europa.eu/esco/occupation/11df8941-508c-4103-ad40-52cdf9430a59', 'Sociólogo', 'Os sociólogos concentram a sua investigação na explicação do comportamento social e da forma como os indivíduos se organizaram enquanto sociedade. Investigam e explicam o modo como as sociedades evoluíram, descrevendo os seus sistemas jurídicos, políticos e econômicos e as suas expressões culturais.', 'released', '["Socióloga", "Sociólogo"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/11e6d39e-1295-40e7-8eea-3eb042bc7e34', 'Cozinheiro Industrial', 'Os cozinheiros industriais criam novas concepções e receitas alimentares. Preparam, medem e misturam ingredientes para preparar produtos alimentares. Controlam e regulamentam as temperaturas, acompanham o processo de cozedura, atribuem tarefas de cozedura e dirigem os trabalhadores na execução das tarefas.', 'released', '["Cozinheiro Industrial", "Cozinheira Industrial"]'::jsonb, '5120'),
  ('http://data.europa.eu/esco/occupation/11eb55d3-4dbe-45c5-a6ce-f04ae843c938', 'Relojoeiro', 'Os relojoeiros fabricam relógios e aparelhos de relojoaria mecânicos ou eletrônicos. Utilizam ferramentas manuais de precisão ou máquinas automatizadas para a montagem dos dispositivos de sincronização. Os relojoeiros também podem reparar relógios e aparelhos de relojoaria. Podem trabalhar em oficinas ou em fábricas.', 'released', '["Relojoeiro", "Relojoeira"]'::jsonb, '7311'),
  ('http://data.europa.eu/esco/occupation/1209b85e-80f1-490f-a7e1-6ad220bb956d', 'Técnico de Desenvolvimento de Calçado', 'Os técnicos de desenvolvimento de calçado servem de interface entre a concepção e a produção. Concebem os protótipos do calçado anteriormente criados pelos designers. Selecionam, desenham ou redesenham as formas e os componentes do calçado, elaboram padrões para as gáspeas, os forros e os componentes da parte inferior e produzem desenhos técnicos para uma série de ferramentas (por exemplo, matrizes de corte, moldes, etc.). Além disso, produzem e avaliam os protótipos do calçado, classificam e produzem amostras de dimensionamento, efetuam os ensaios requeridos para as amostras e confirmam as condicionantes em matéria de qualidade e de preço.', 'released', '["Técnico de Desenvolvimento de Calçado", "Técnica de Desenvolvimento de Calçado"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/12142c2c-9b6f-4e4f-8153-f1a51554e4e0', 'Diretor de Importação e Exportação de Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica', 'Os diretores de importação e exportação de maquinaria e equipamento industrial, construção naval e aeronáutica implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica", "Diretor de Vendas de Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica", "Diretor de Importação e Exportação de Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica", "Diretora de Vendas de Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/1214a616-aaa5-4140-b82e-2cc5028b0fa4', 'Operador de Misturadora', 'Os operadores de misturadora controlam o equipamento para pesar e misturar óleos vegetais utilizados em produtos, tais como o óleo para salada e as margarinas. Cuidam dos óleos de bombagem para efetuar a mistura de acordo com fórmulas específicas. Colhem amostras de óleos mistos para examinar a sua textura e cor e, com base nas mesmas, fazem ajustes aos processos de mistura.', 'released', '["Operador de Misturadora", "Operador de Sistema de Mistura", "Operadora de Sistema de Mistura", "Operadora de Misturadora"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/121bd198-af39-4fac-8249-b384910f7bd7', 'Vulcanizador de Pneus', 'Os vulcanizadores de pneus reparam rasgões ou furos em moldes e bandas de rodagem dos pneus, utilizando ferramentas ou máquinas.', 'released', '["Vulcanizadora de Pneus", "Vulcanizador de Pneus"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/123a195c-103a-4b84-b3fd-6d40dbc15c54', 'Operador de Fundição em Coquilha', 'Os operadores de fundição em coquilha fabricam peças vazadas, incluindo canos, tubos, perfis ocos e outros produtos da primeira transformação de aço, operando equipamento sob controlo manual numa fundição. Conduzem o fluxo de metais ferrosos e não ferrosos derretidos para coquilhas, tendo o cuidado de criar as condições exatas adequadas para obter metal da mais elevada qualidade. Observam o fluxo de metal para identificar falhas. Em caso de falha, notificam o pessoal autorizado e participam na eliminação da falha.', 'released', '["Operador de Fundição em Coquilha", "Operadora de Fundição em Coquilha"]'::jsonb, '7211'),
  ('http://data.europa.eu/esco/occupation/1242d99a-47f1-4a62-b884-33746db8a6ca', 'Gestor de Serviço de Assistência Informática', 'Os gestores de serviço de assistência informática acompanham a prestação de serviços de apoio técnico aos clientes de acordo com os prazos predefinidos. Planeiam e organizam as ações de apoio ao usuário e resolvem os problemas e as questões informáticas. Os gestores de serviço de assistência informática supervisionam a equipe de assistência que assegura que os clientes recebem as respostas e o apoio adequados. Participam também no desenvolvimento de orientações para os serviços ao cliente e no reforço da equipe.', 'released', '["Gestor de Assistência Técnica", "Gestor de Serviço de Assistência Informática", "Gestora de Assistência Técnica", "Gestora de Suporte Técnico", "Responsável Pelo Serviço de Assistência Informática", "Gestor de Suporte Técnico", "Gestora de Serviço de Assistência Informática", "Gerente"]'::jsonb, '3512'),
  ('http://data.europa.eu/esco/occupation/1246764a-ce7c-45e8-9675-e445d145e818', 'Vendedor de Livros', 'Os vendedores de livros vendem livros em lojas especializadas. Também dão sugestões, aconselham sobre os livros disponíveis e sobre quaisquer outros produtos relacionados à venda na loja especializada.', 'released', '["Vendedor de Livros", "Vendedora de Livros"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/12938d1a-eeb2-4b1e-a22b-f0bebeadfb73', 'Operador de Central Hidroelétrica', 'Os operadores de centrais hidroelétricas operam e efetuam a manutenção do equipamento utilizado na produção de energia a partir do movimento da água. Monitorizam o equipamento de medição, avaliam as necessidades de produção e adaptam o fluxo de água com vista a satisfazer essas necessidades. Desempenham igualmente tarefas de reparação e manutenção.', 'released', '["Operador de Central Hidroelétrica", "Operadora de Central Hidroelétrica"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/12da0bb1-26c8-46eb-9476-797f4f1c441e', 'Guarda Municipal', 'Os guardas municipais dirigem os peões em locais públicos, tais como ruas ou caminhos-de-ferro, nas imediações de escolas ou caminhos-de-ferro, para atravessarem estradas e intersecções públicas, através da observação do tráfego e exibindo um sinal de paragem para os veículos, de modo a permitir a passagem dos peões de forma segura e ordenada.', 'released', NULL, '5419'),
  ('http://data.europa.eu/esco/occupation/12dc4509-7d36-46d8-aca0-c147c7ecd806', 'Armeiro', 'Os armeiros modificam e reparam armas de fogo fabricadas em metal de acordo com especificações especiais do cliente. Utilizam máquinas e ferramentas manuais, tais como plainas, esmeriladores e fresadoras para alterar e restaurar armas, podendo também aplicar gravações, entalhes e outros acabamentos decorativos para o produto acabado.', 'released', '["Armeiro", "Armeira"]'::jsonb, '7222'),
  ('http://data.europa.eu/esco/occupation/12f9c0e8-26f4-4f1d-bf04-b16a34d12798', 'Agulheiro', 'Os agulheiros auxiliam nas tarefas do controlador de tráfego. Operam comutadores e sinais de acordo com as instruções de controlo do tráfego ferroviário. Asseguram o cumprimento da regulamentação e dos requisitos de segurança.;', 'released', '["Agulheira", "Agulheiro", "Operador de Aparelho de Mudança de Via", "Operadora de Aparelho de Mudança de Via"]'::jsonb, '8312'),
  ('http://data.europa.eu/esco/occupation/12ff7f9c-c5b5-4d4a-b585-c350dd1400eb', 'Investigador em Economia Empresarial', 'Os investigadores em economia empresarial realizam investigações sobre temas relacionados com a economia, as organizações e a estratégia. Analisam as tendências macroeconómicas e microeconómicas e utilizam estas informações para analisar as posições das indústrias ou de empresas específicas na economia. Prestam aconselhamento em matéria de planejamento estratégico, viabilidade dos produtos, tendências previstas, mercados emergentes, políticas de tributação e tendências dos consumidores.', 'released', '["Investigador em Economia Empresarial", "Investigadora em Economia Empresarial"]'::jsonb, '2631'),
  ('http://data.europa.eu/esco/occupation/1313aeea-63a9-4b4d-82d1-dbe00ff9ed10', 'Diretor de Responsabilidade Social', 'Os diretores de responsabilidade social controlam as práticas das organizações e das empresas no que diz respeito à ética e ao impacto na comunidade mais alargada. Aconselham sobre a responsabilidade social e a sustentabilidade em função das necessidades da empresa. Os diretores de responsabilidade social promovem ações que são ambientalmente conscientes, filantrópicas ou relacionadas com os direitos do Homem.', 'released', '["Diretora de Responsabilidade Social", "Gestor de Responsabilidade Social", "Diretor de Responsabilidade Social", "Gestora de Responsabilidade Social"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/13331bd9-0599-47c0-9812-29650c218de3', 'Técnico de Engenharia Hidráulica', 'Os técnicos de engenharia de sistemas hidráulicos prestam assistência aos engenheiros no desenvolvimento e na instalação de sistemas de abastecimento de água e de tratamento de água. Acompanham as operações para assegurar o cumprimento da regulamentação em matéria de saúde e segurança, controlam a qualidade da água e asseguram a aplicação da legislação relativa à água.;', 'released', '["Técnico de Engenharia Hidráulica", "Técnica de Engenharia Hidráulica"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/133ab775-f08d-4bc7-8629-89d286180f4e', 'Gestor de Marca do Empregador', 'Os gestores de marca do empregador colaboram com peritos em marketing para promover a imagem do empregador através de formatos de comunicação como a imprensa e as redes sociais. Gerem um programa de marketing em linha para promover ofertas de emprego e oportunidades de carreira na empresa.', 'released', '["Gestora de Marca do Empregador", "Gestor de Marca do Empregador", "Gerente"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/13427968-250b-4967-a682-afac5cd0af4f', 'Agente Eleitoral', 'Os agentes eleitorais operam no terreno para convencer o público a votar no candidato político que representam. Conversam diretamente com o público em locais públicos e recolhem informações sobre a opinião pública, realizando, além disso, atividades que assegurem que as informações sobre a campanha chegam a um público vasto.', 'released', '["Agentea Eleitoral"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/137b1d11-c4bc-4016-89ba-45345d4c71f0', 'Gestor de Comunidades Online', 'Os gestores de comunidades em linha proporcionam e mantêm um ambiente interativo facilitado por aplicações como as redes sociais, os fóruns e os wikis. Mantêm as relações entre as diferentes comunidades digitais.', 'released', '["Gestora de Redes Sociais", "Gestora de Comunidades Online", "Gestor de Comunidades Digitais", "Gestora de Comunidades em Linha", "Gestor de Redes Sociais", "Especialista em Redes Sociais", "Gestor de Comunidades em Linha", "Gestor de Comunidades Online", "Gerente"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/1391bdf9-bd61-4fb5-91ca-c29036ab2b60', 'Ajudante Familiar', 'Os ajudantes familiares prestam assistência pessoal e promovem a autonomia, numa base diária, aos indivíduos que não podem cuidar de si próprios por motivo de doença, envelhecimento ou deficiência. Ajudam-nos com a higiene pessoal, alimentação, comunicação ou medicação, de acordo com as instruções do profissional de saúde.', 'released', '["Técnica de Apoio Familiar e à Comunidade", "Assistente Familiar e de Apoio à Comunidade", "Técnico de Apoio Familiar e à Comunidade", "Ajudantea Familiar"]'::jsonb, '5322'),
  ('http://data.europa.eu/esco/occupation/139fba7b-6c1f-40ee-8acf-78f97e57c905', 'Supervisor de Gestão de Resíduos', 'Os supervisores de gestão de resíduos coordenam instalações de recolha, reciclagem e eliminação de resíduos. Supervisionam as operações de gestão de resíduos, assegurando o cumprimento das normas ambientais, e supervisionam também o pessoal. Contribuem para o desenvolvimento de métodos de gestão de resíduos, tendo em vista uma maior redução dos resíduos, e prestam assistência na prevenção de violações da legislação em matéria de tratamento de resíduos.', 'released', '["Supervisora de Gestão de Resíduos", "Supervisor de Gestão de Resíduos"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/13b12b2d-e223-46f5-a6c0-cb77fe37f03a', 'Diretor de Distribuição Maquinaria para a Indústria Têxtil', 'Os diretores de distribuição maquinaria para a indústria têxtil planificam a distribuição de máquinas da indústria têxtil a diversos pontos de venda.', 'released', '["Diretora de Logística Maquinaria para a Indústria Têxtil", "Diretora de Distribuição Maquinaria para a Indústria Têxtil", "Diretor de Logística Maquinaria para a Indústria Têxtil", "Diretor de Distribuição Maquinaria para a Indústria Têxtil"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/13d1b2b4-99dd-44da-9734-c9f74bae18f7', 'Representante de Serviço de Apoio ao Cliente', 'Os representantes de serviço de apoio ao cliente tratam das queixas e são responsáveis pela manutenção da boa vontade geral entre uma organização e os seus clientes. Gerem dados relativos à satisfação dos clientes e comunicam os mesmos.', 'released', '["Representantea de Serviço de Apoio ao Cliente"]'::jsonb, '4225'),
  ('http://data.europa.eu/esco/occupation/13d8b1be-d711-4bbc-a45e-cad605162f41', 'Diretor Musical', 'Os diretores musicais dirigem grupos musicais como orquestras e bandas durante espetáculos ao vivo ou sessões de gravação. Organizam a música e a composição, coordenam os músicos e gravam a atuação. Os diretores musicais são profissionais que trabalham em diversos locais, como a indústria cinematográfica e dos vídeos musicais, estações de rádio, conjuntos musicais ou escolas.', 'released', '["Diretor Musical", "Diretora Musical"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/13da27aa-ca6a-476d-ab2c-efc9e5bd97b2', 'Vendedor de Vestuário', 'Os vendedores de vestuário vendem vestuário em lojas especializadas.', 'released', '["Vendedora de Vestuário", "Vendedor de Vestuário"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/13e30c08-8834-4e4f-b6f9-89fffed4e310', 'Diretor de Instituição para Alunos com Necessidades Educativas Especiais', 'Os diretores de instituição para alunos com necessidades educativas especiais gerem as atividades quotidianas de uma escola de educação especial. Supervisionam e apoiam o pessoal, bem como a investigação e a introdução de programas que proporcionem a assistência necessária aos alunos com deficiências físicas, mentais ou de aprendizagem. Podem tomar decisões sobre as admissões, são responsáveis pelo cumprimento das normas curriculares e asseguram que a escola cumpre os requisitos nacionais em matéria de educação previstos na lei. Os diretores de instituição para alunos com necessidades educativas especiais gerem igualmente o orçamento da escola e são responsáveis por maximizar a atribuição de subvenções e bolsas. Também analisam e adotam as suas políticas de acordo com a investigação atual realizada no domínio da avaliação das necessidades especiais.', 'released', '["Diretora de Instituição para Alunos com Necessidades Educativas Especiais", "Diretor de Instituição para Alunos com Necessidades Educativas Especiais"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/14031d4a-6e99-442f-b4fe-18262b6432b2', 'Representante Comercial', 'Os representantes comerciais representam uma empresa na venda e no fornecimento de informações sobre bens e serviços a empresas e organizações.', 'released', '["Representantea Comercial"]'::jsonb, '3322'),
  ('http://data.europa.eu/esco/occupation/140613c4-8c3c-43c5-8525-2f63231c95b0', 'Operador de Fabricação de Semicondutores', 'Os operadores de fabrico de semicondutores fabricam semicondutores eletrônicos, bem como dispositivos semicondutores, tais como microchips ou circuitos integrados. Podem também reparar, testar e rever os produtos. Os transformadores de semicondutores trabalham em salas limpas e, por conseguinte, têm de usar um equipamento especial leve sobre o vestuário para evitar que as suas partículas contaminem o local de trabalho.', 'released', '["Operadora de Fabricação de Semicondutores", "Operador de Fabricação de Semicondutores"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/143e49fc-832f-477c-8cac-8eabe6fd7bc2', 'Auxiliar de Armazém de Fábrica de Calçado', 'Os empregados de armazém de fábrica de calçado são responsáveis pelo armazenamento de matérias-primas e subsidiárias, pelos dispositivos de trabalho e pelos componentes para a produção de calçado. Garantem que todos os componentes necessários para a produção de calçado estão prontos a ser utilizados na cadeia de produção, classificando e registando os componentes adquiridos, fazendo previsões de compras e distribuindo-as pelos diferentes departamentos.;', 'released', '["Empregada de Armazén de Fábrica de Calçado", "Empregado de Armazén de Fábrica de Calçado", "Empregado de Armazém de Fábrica de Calçado"]'::jsonb, '4321'),
  ('http://data.europa.eu/esco/occupation/146f2c99-3f8b-4856-95ba-3ecfea681809', 'Gerente de Sala de Jogos', 'Os gerentes de sala de jogos organizam e coordenam as atividades de uma casa de jogo. Supervisionam as operações diárias e facilitam as comunicações entre o pessoal e os clientes. Gerem e formam o pessoal e procuram melhorar a rentabilidade das suas atividades. Assumem a responsabilidade por todas as atividades de jogo e asseguram a observância das regras e regulamentos pertinentes em matéria de jogo.', 'released', '["Diretor de Casino", "Diretora de Casino", "Gerentea de Sala de Jogos"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/1488589a-7b83-471d-b094-492f5616f4e0', 'Diretor de Desenvolvimento de Produtos', 'Os diretores de desenvolvimento de produtos coordenam o desenvolvimento de novos produtos desde o início até ao fim. Recebem sessões de informação e começam a prever o novo produto, tendo em conta critérios de concepção, técnicos e de custos. Realizam investigação sobre as necessidades do mercado e criam protótipos de novos produtos para oportunidades de mercado não exploradas. Os diretores de desenvolvimento de produtos também melhoram e promovem a qualidade tecnológica.', 'released', '["Diretora de Desenvolvimento de Produtos", "Diretor de Desenvolvimento de Novos Produtos", "Diretora de Desenvolvimento de Novos Produtos", "Diretor de Desenvolvimento de Produtos", "Diretora de Inovação", "Diretor de Inovação"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/149062d6-6496-4004-9c23-93c78b29b5db', 'Ceramista Artesanal', 'Os ceramistas artesanais criam tijolos únicos, tubos e outros produtos resistentes ao calor, utilizando ferramentas de moldagem manuais. Criam moldes de acordo com as especificações, limpam e lubrificam os mesmos, introduzem e retiram a mistura do molde. Depois, deixam-se os tijolos secar no forno antes de acabarem e suavizarem os produtos finais.', 'released', NULL, '7314'),
  ('http://data.europa.eu/esco/occupation/14eb2c85-fce5-40b6-bcd0-46ac99994b0d', 'Técnico de Registros Médicos', 'Os técnicos de registos médicos organizam, mantêm atualizados e arquivam os registos dos doentes, para que estejam à disposição do pessoal médico. Transferem as informações médicas contidas nos registos em papel para um modelo eletrônico.', 'released', '["Técnica de Registros Médicos", "Técnico de Registros Médicos"]'::jsonb, '3252'),
  ('http://data.europa.eu/esco/occupation/15151ba4-fbf2-4fd9-8dde-2abbc6ec362c', 'Criador de Cavalos', 'Os criadores de cavalos supervisionam a produção e o cuidado diário dos cavalos. Zelam pela saúde e pelo bem-estar dos cavalos.', 'released', '["Criador de Equinos", "Criadora de Equinos", "Criadora de Cavalos", "Criadora de Equídeos", "Criador de Equídeos", "Criador de Cavalos"]'::jsonb, '6121'),
  ('http://data.europa.eu/esco/occupation/15419750-d6e6-4ab8-a77b-b42794f2e168', 'Técnico de Calçado Ortopédico', 'Os técnicos de calçado ortopédico concebam calçado e fabricam moldes, utilizando tecnologia de fabrico. Compensam e resolvem problemas de colocação do pé e do tornozelo, concebem e fabricam calçado e os seus componentes ortopédicos, incluindo ortóteses, palmilhas, solas e outros.', 'released', '["Técnica de Calçado Ortopédico", "Técnico de Calçado Ortopédico"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/15502187-a1da-407a-843b-ce991d5f65fe', 'Operador de Trançado Têxtil', 'Os operadores de trançado têxtil supervisionam o processo de trançado de um grupo de máquinas, monitorizam a qualidade do tecido e as condições de trançado. Procedem à inspeção das máquinas de trançado após a instalação, colocação em funcionamento e durante o processo de produção, para garantir que o produto trançado cumpre as especificações e as normas de qualidade.', 'released', '["Operadora de Trançado Têxtil", "Operador de Entrançadura Têxtil", "Operador de Trançado Têxtil", "Operadora de Entrançadura Têxtil"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/15620506-fb5d-49cd-87a2-1c9047fb406a', 'Pintor da Construção', 'Os pintores da construção pintam o interior e o exterior de edifícios e outras estruturas. Podem utilizar tintas normalizadas à base de látex ou tintas especializadas para obter efeitos decorativos ou propriedades de proteção. Os pintores da construção são especializados na utilização de pincéis, rolos para pintar e pulverizadores de tinta para diferentes aplicações.', 'released', '["Pintor da Construção", "Pintora da Construção Civil", "Pintor da Construção Civil", "Pintora da Construção"]'::jsonb, '7131'),
  ('http://data.europa.eu/esco/occupation/1562c7a3-c7d9-419d-b9b6-db26610bcf84', 'Especialista em Sistemas de Data Warehouse', 'Os especialistas em sistemas de Data Warehouse são responsáveis pelo planejamento, ligação, concepção, programação e implementação de sistemas de Data Warehouse. Desenvolvem, acompanham e mantêm os processos ETL (extração, transformação e carregamento de dados), as aplicações de comunicação e a concepção de armazéns de dados (data warehouse).', 'released', NULL, '2521'),
  ('http://data.europa.eu/esco/occupation/158965f1-bd83-441c-bca8-1975b74dedc5', 'Técnico de Restauro de Veículos', 'Os técnicos de restauro de veículos renovam veículos antigos e clássicos, tais como automóveis.', 'released', '["Técnica de Restauro de Veículos", "Técnico de Restauro Automóvel", "Técnica de Restauro Automóvel", "Técnico de Restauro de Veículos"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/15a7e87c-f7d5-4a60-bab7-9636b76143fe', 'Instalador de Sistemas de Domótica', 'Os instaladores de sistemas de domótica instalam e procedem à manutenção de sistemas de domótica (aquecimento, ventilação e ar condicionado, iluminação, sombreamento solar, irrigação, segurança, etc.), dispositivos conectados e aparelhos inteligentes nas instalações dos clientes. Além disso, aconselham os clientes e formulam recomendações de produtos e serviços que respondam às suas necessidades em termos de conforto, conveniência, segurança e proteção.;', 'released', '["Técnica de Casa Inteligente", "Instaladora de Dispositivos Conectados", "Instaladora de Casa Inteligente", "Técnica de Automação Residencial", "Instalador de Dispositivos Conectados", "Técnico de Domótica", "Instaladora de Domótica", "Técnico de Automação Residencial", "Instalador de Casa Inteligente", "Instalador de Domótica", "Instalador de Automação Residencial", "Instaladora de Automação Residencial", "Técnico de Casa Inteligente", "Técnica de Domótica", "Instaladora de Sistemas de Domótica"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/15ab8475-549d-48a7-9d4a-5bb310015312', 'Funcionário de Lavandaria', 'Os funcionários de lavandaria recolhem roupa de cama ou uniformes para limpeza. Mantêm a disponibilidade de serviços da roupa e mantêm registos de inventário.', 'released', '["Funcionária de Lavandaria", "Funcionário da Lavandaria"]'::jsonb, '9121'),
  ('http://data.europa.eu/esco/occupation/15cc27b1-7358-48ed-9fb8-69ffe9f1fc98', 'Técnico de Inseminação Artificial Animal', 'Os técnicos de inseminação artificial animal são responsáveis pela deposição de sémen colhido num animal, em conformidade com a legislação nacional.', 'released', '["Técnico de Inseminação Artificial", "Inseminadora Artificial", "Técnico de Inseminação Artificial Animal", "Técnica de Inseminação Artificial Animal", "Técnica de Inseminação Artificial", "Inseminador Artificial"]'::jsonb, '3240'),
  ('http://data.europa.eu/esco/occupation/15d5636f-7714-4697-850a-67b7f7cb3837', 'Técnico de Instrumentos Óticos', 'Os técnicos de instrumentos óticos interpretam esquemas e desenhos de montagem de lentes e instrumentos óticos, tais como microscópios, telescópios, equipamento de projeção e equipamento médico de diagnóstico. Processam, afiam, pulem e revestem materiais de vidro, centram lentes de acordo com o eixo ótico e fixam-nas na armação ótica. Podem testar os instrumentos após a montagem.', 'released', '["Técnico de Instrumentos Óticos", "Técnica de Instrumentos Óticos"]'::jsonb, '7311'),
  ('http://data.europa.eu/esco/occupation/15dfabf5-71e0-400e-af48-4c6f92ef4392', 'Empregado de Canil', 'Os empregados de canil tratam os animais em canis ou gatis e prestam cuidados a animais de companhia. Alimentam os animais, limpam as gaiolas, cuidam dos animais doentes ou velhos, tratam deles e passeiam-nos.', 'released', '["Empregado de Canil", "Empregada de Canil"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/160c1469-bbb6-48d3-b2a7-db8b30d724b5', 'Assistente Atuarial', 'Os assistentes atuariais realizam pesquisas de dados estatísticos a fim de fixarem taxas de prémio e apólices de seguros. Analisam a possibilidade de acidentes, lesões e danos materiais através da utilização de fórmulas e modelos estatísticos.', 'released', '["Assistentea Atuarial"]'::jsonb, '3314'),
  ('http://data.europa.eu/esco/occupation/1619d7f3-7d95-407c-a20e-47745bfcde73', 'Responsável Pela Proteção de Dados', 'Os responsáveis pela proteção de dados asseguram que o tratamento de dados pessoais numa organização cumpre as normas de proteção de dados e as obrigações estabelecidas na legislação aplicável, como o RGPD. Elaboram e implementam a política de organização relacionada com a proteção de dados, são responsáveis por avaliações de impacto na proteção de dados e processam queixas e pedidos de terceiros e de agências reguladoras. Os responsáveis pela proteção de dados conduzem investigações sobre potenciais violações de dados, realizam auditorias internas e atuam como ponto de contato dentro da organização para todas as questões relacionadas com o tratamento de dados pessoais. Podem desenvolver e ministrar programas de formação a outros funcionários sobre os procedimentos envolvidos na proteção de dados.;', 'released', '["Especialista em GDPR", "Especialista em Proteção de Dados", "Oficial de Conformidade Privacidade de Dados", "Oficial Legal e de Proteção de Dados", "Consultor Jurídico de Proteção de Dados", "Oficial de Proteção e Segurança de Dados", "Oficial de Privacidade", "Consultora de Proteção de Dados", "Conselho de Proteção de Dados", "Consultora Jurídica de Proteção de Dados", "Consultor de Proteção de Dados"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/165f32b8-756a-4ef3-87f1-83fbbdc60db7', 'Operador de Máquinas Misturadoras de Pesticidas', 'Os operadores de máquinas misturadoras de pesticidas procedem à operação e manutenção de máquinas que misturam ingredientes químicos em estado seco ou líquido, para produzir inseticidas, fungicidas, rodenticidas ou herbicidas, certificando-se de que o produto final esteja de acordo com a fórmula.', 'released', '["Operador de Máquinas Misturadoras de Pesticidas", "Operadora de Máquinas Misturadoras de Pesticidas"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/16605833-c196-48d7-a6f5-bbdebdc353df', 'Engenheiro de Pré-Venda de Produtos de Informática', 'Os engenheiros de pré-venda de produtos de informática conduzem e gerem a fase do processo de vendas respeitante à avaliação dos produtos de informática, trabalhando em conjunto com a equipe de vendas. Fornecem orientações técnicas ao pessoal da área de pré-vendas e planeiam e modificam as configurações dos produtos de informática, a fim de satisfazerem os requisitos dos clientes. Procuram explorar oportunidades adicionais de desenvolvimento empresarial.', 'released', '["Técnica de Apoio Informático Pré-Venda", "Técnico de Assistência Informática Pré-Venda", "Engenheira de Pré-Venda de Produtos de Informática", "Técnico de Apoio Informático Pré-Venda", "Técnica de Assistência Informática Pré-Venda", "Engenheiro de Pré-Venda de Produtos de Informática"]'::jsonb, '2434'),
  ('http://data.europa.eu/esco/occupation/1663e9d9-857b-4efa-9ab6-886c7fc763f6', 'Diretor de Serviços Pós-Venda — Retalho Automóvel', 'Os diretores de serviços pós-venda — retalho automóvel maximizam as vendas ao encerrar as suas atividades de forma contínua. Negoceiam com os clientes existentes para as renovações de contratos. Mantêm os contratos, tratam os pedidos, gerem as garantias e investigam os danos causados aos produtos.', 'released', '["Coordenador de Serviços Pós-Venda — Pesados", "Coordenadora de Serviços Pós-Venda — Pesados", "Diretor de Serviços Pós-Venda — Retalho Automóvel", "Diretora de Serviços Pós-Venda — Retalho Automóvel"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/16811760-fb2d-42cf-912d-2215f085898f', 'Operador de Máquina de Corte por Jato de Plasma', 'Os operadores de máquina de corte por jato de plasma instalam e operam máquinas de corte por jato de plasma para cortar e moldar os materiais em excesso de uma peça metálica, utilizando uma tocha de plasma a uma temperatura suficientemente quente para fundir e cortar o metal, queimando-o, e que trabalha a uma velocidade que sopra o metal fundido do corte limpo.', 'released', '["Operador de Máquina de Corte por Jato de Plasma", "Operadora de Máquina de Corte por Jato de Plasma"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/16ad07cd-2fd2-4f93-b442-89918c10bbbf', 'Operador de Máquinas de Corte de Calçado', 'Os operadores de máquinas de corte de calçado controlam o couro, os têxteis, os materiais sintéticos, as tinturas e o calçado. Selecionam áreas de materiais a cortar em termos de qualidade e direção de estiramento, decidem onde e como cortar e programam e executam tecnologias ou máquinas específicas. O equipamento utilizado em grandes superfícies de materiais é frequentemente uma faca automática. Os operadores de máquinas de corte de calçado posicionam e manipulam couro ou outros materiais. Ajustam as máquinas de corte, fazem corresponder os componentes e peças de calçado e verificam as peças cortadas em função das especificações e dos requisitos de qualidade. ; ;', 'released', '["Operador de Máquinas de Corte de Calçado", "Operadora de Máquinas de Corte de Calçado"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/16b974f4-cb8c-436c-8c05-a16957c40131', 'Operador de Instalações de Produção de Energia a Partir de Combustíveis Fósseis', 'Os operadores de instalações de produção de energia a partir de combustíveis fósseis operam e efetuam a manutenção de equipamentos industriais, como geradores, turbinas e caldeiras, que fornecem eletricidade produzida a partir de combustíveis fósseis como o gás natural ou o carvão. Garantem a segurança das operações e a conformidade do equipamento com a legislação. Podem também trabalhar em centrais elétricas de ciclo combinado, as quais utilizam sistemas de recuperação que recuperam o calor dos gases de exaustão de uma operação e ativam as turbinas a vapor.', 'released', '["Operador de Instalações de Produção de Energia a Partir de Combustíveis Fósseis", "Operadora de Instalações de Produção de Energia a Partir de Combustíveis Fósseis"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/16bc69b8-5abc-49e4-a860-befb734d54d3', 'Técnico de Qualidade Química dos Têxteis', 'Os técnicos de qualidade química dos têxteis realizam testes laboratoriais químicos em materiais e produtos têxteis. Interpretam os resultados e prestam apoio nas operações de coloração e acabamento de têxteis.', 'released', '["Técnica de Qualidade Química dos Têxteis", "Técnico de Qualidade Química dos Têxteis"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/16bf6d6f-64ec-4f80-9070-f81a7b179d53', 'Supervisor de Mecânica de Precisão', 'Os supervisores de mecânica de precisão supervisionam, formam e gerem os trabalhadores que montam partes complexas de máquinas de pequenas dimensões, como os mecanismos de medição ou de controlo.', 'released', '["Supervisora de Mecânica de Precisão", "Supervisor de Mecânica de Precisão"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/16cb1f72-3d8c-4404-84ec-9c31fbd7c86c', 'Engenheiro de Soldadura', 'Os engenheiros de soldadura realizam investigação e desenvolvem técnicas de soldadura eficazes, e concebem o equipamento correspondente, igualmente eficiente, para ajudar ao processo de soldadura. Realizam igualmente o controlo de qualidade e avaliam os procedimentos de inspeção das atividades de soldadura. Os engenheiros de soldadura têm um conhecimento avançado e uma compreensão profunda da aplicação de tecnologia de soldadura. São capazes de gerir atividades ou projetos técnicos e profissionais de grande complexidade relacionados com aplicações de soldadura, assumindo simultaneamente a responsabilidade pelo processo de tomada de decisões.', 'released', '["Engenheira de Soldadura", "Engenheiro de Soldadura"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/16d7bae5-503e-4e19-bc8b-619c9bcf5c4f', 'Operador de Máquinas de Montagem de Calçado', 'Os operadores de máquinas de montagem de calçado puxam a parte dianteira, a cintura e a sede da gáspea sobre a forma utilizando máquinas específicas, com o objetivo de obter a forma final do modelo de calçado. Começam por colocar o pé na máquina, esticando os bordos da gáspea sobre a forma e pressionando a sede. Em seguida, alisam os bordos, cortam a biqueira e o forro em excesso e utilizam a costura ou cola para fixar a forma.', 'released', '["Operador de Máquinas de Montagem de Calçado", "Operadora de Máquinas de Montagem de Calçado"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/16e65196-3449-4c88-b379-0aa98f43db2b', 'Técnico de Anestesia', 'Os técnicos de anestesia prestam assistência a médicos especialistas em anestesiologia. Preparam os blocos operatórios e outras clínicas especializadas para procedimentos de anestesia, preparam o equipamento necessário para a administração de anestesia e ajudam a induzir e a manter procedimentos adequados de anestesia e pós-anestesia. Executam estas funções sob supervisão, seguindo as indicações do médico.', 'released', '["Técnica de Anestesia", "Técnico de Anestesia"]'::jsonb, '3259'),
  ('http://data.europa.eu/esco/occupation/16ec2281-b0b3-4cde-9888-2cb6cc492c25', 'Operador de Máquinas de Produção de Molhos', 'Os operadores de máquinas de produção de molhos transformam, produzem e fabricam molhos à base de frutas, produtos hortícolas, óleos e vinagres. Operam máquinas e equipamento para atividades tais como a mistura, a pasteurização e a embalagem de molhos.', 'released', '["Operadora de Máquinas de Produção de Molhos", "Operador de Máquinas de Produção de Molhos"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/1738173e-ef9c-4222-88c8-b6aa9bad3cf7', 'Biofísico', 'Os biofísicos estudam a relação existente entre os organismos vivos e a física. Realizam investigação sobre os organismos vivos com base nos métodos da física que visam explicar a complexidade da vida, prever padrões e formular conclusões sobre aspetos da vida. Os campos de investigação da biofísica abrangem o ADN, as proteínas, as moléculas, as células e os ambientes.', 'released', '["Biofisica", "Biofisico", "Biofísica"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/1739b07b-7e8f-4dcb-bc59-b5ae18f30077', 'Comerciante Grossista de Artigos para o Lar', 'Os comerciantes grossistas de artigos para o lar investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Artigos para o Lar"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/173a882d-0a14-4919-ac1b-23e8ee8273de', 'Diretor de Importação e Exportação de Sistemas Combinados de Aquecimento de Água e Calefação', 'Os diretores de importação e exportação de sistemas combinados de aquecimento de água e calefação implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Vendas de Sistemas Combinados de Aquecimento de Água e Calefação", "Diretora de Vendas de Sistemas Combinados de Aquecimento de Água e Calefação", "Diretor de Importação e Exportação de Sistemas Combinados de Aquecimento de Água e Calefação", "Diretora de Importação e Exportação de Sistemas Combinados de Aquecimento de Água e Calefação"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/1765f9b2-8483-490d-8df6-6e39db30ad82', 'Supervisor de Máquinas Agrícolas', 'Os supervisores de máquinas agrícolas planeiam e organizam serviços de máquinas agrícolas para produção agrícola e paisagística, em estreita cooperação com os clientes.', 'released', '["Controladora de Maquinaria Agrícola", "Supervisora de Máquinas Agrícolas", "Supervisor de Maquinaria Terrestre", "Supervisora de Maquinaria Terrestre", "Supervisor de Máquinas Agrícolas", "Controlador de Maquinaria Agrícola"]'::jsonb, '8341'),
  ('http://data.europa.eu/esco/occupation/1790c821-c582-4944-8597-d2d4a66f6a6d', 'Geólogo de Minas', 'Os geólogos de minas localizam, identificam, quantificam e classificam os recursos minerais, bem como as suas características e estrutura geológicas. Prestam aconselhamento aos gestores de minas e aos engenheiros em operações mineiras atuais e futuras .', 'released', '["Especialista em Estatigrafia", "Geólogo de Minas", "Geóloga de Minas"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/17abb59e-a1f9-4ce8-88b7-569e5413dca9', 'Técnico de Gravação de Charutos', 'Os técnicos de gravação de charutos asseguram o correto funcionamento das máquinas que carimbam as marcas nas capas dos charutos. Mantêm as máquinas fornecidas com toda a matéria-prima necessária e observam que os processos não encravem. A título preventivo, limpam os rolos de tinta.', 'released', '["Operadora de Marcação de Charutos", "Técnico de Gravação de Charutos", "Operador de Marcação de Charutos", "Técnica de Gravação de Charutos"]'::jsonb, '8183'),
  ('http://data.europa.eu/esco/occupation/17b29190-6746-4b81-a1d1-8053a5bbc0e9', 'Soldador por Brasagem', 'Os soldadores por brasagem operam diversos equipamentos e máquinas, tais como tochas de gás, ferros de soldar, máquinas de soldar ou equipamento de ultrassons, para soldar dois ou mais artigos (geralmente metais), por fusão e formação de um enchimento metálico entre as junções, o metal de enchimento tem um ponto de fusão inferior ao do metal adjacente.', 'released', '["Operador de Equipamento de Soldadura", "Operadora de Equipamento de Soldadura", "Soldadora", "Soldador por Brasagem", "Soldador", "Soldadora por Brasagem"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/17c02096-05d6-4a5a-ba93-9f22d68df0d3', 'Montador de Instrumentos Odontológicos', 'Os montadores de instrumentos odontológicos montam vários instrumentos odontológicos, tais como brocas, lasers, sondas, espelhos e dispositivos de imagiologia dentária. Utilizam várias máquinas, ferramentas manuais, substâncias químicas, colas e epóxi para a montagem dos instrumentos odontológicos. Utilizam ferramentas de precisão e trabalham em ambientes de sala limpa.', 'released', '["Montadora de Instrumentos Odontológicos", "Montador de Instrumentos Odontológicos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/17e39591-7137-4960-94c8-8169f7a5d67b', 'Oficial de Quarto de Navegação', 'Os oficiais de quarto dirigem a navegação ao nível operacional. Ocupam-se das tarefas de carga e estiva, bem como de controlo do funcionamento do navio. Ao nível operacional, cuidam das pessoas a bordo.', 'released', NULL, '3152'),
  ('http://data.europa.eu/esco/occupation/1801583e-34b3-4c89-97ac-db2a346b4a3e', 'Formador de Cursos Profissionais na Área da Hotelaria', 'Os formadores de cursos profissionais na área da hotelaria formam os alunos no seu domínio de estudos especializado, a hotelaria, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com a hotelaria, tais como rececionista de hotel ou mordomo. Os formadores de cursos profissionais na área da hotelaria acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da hotelaria através de trabalhos, testes e exames.', 'released', '["Formadora de Cursos Profissionais na Área da Hotelaria", "Formador de Cursos Profissionais na Área da Hotelaria"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/1822bfc2-e735-449f-ba00-ca71eb5c062b', 'Porteiro de Edifícios', 'Os porteiros de edifícios procedem à manutenção e ao controlo do estado e segurança dos edifícios. Limpam, prestam assistência com pequenas reparações e assegura que os residentes têm acesso a serviços como o aquecimento e a água quente. Os porteiros de edifícios são responsáveis pela qualidade dos edifícios e também funcionam como pessoa de contato para os residentes.', 'released', '["Porteira de Edifícios", "Porteiro de Edifícios"]'::jsonb, '5153'),
  ('http://data.europa.eu/esco/occupation/18232485-5f8b-4c53-80f2-3d9f8f9d0e20', 'Modelista de Vestuário de Confeção', 'Os modelistas de vestuário de confeção interpretam os esboços de desenhos e cortam moldes para todos os tipos de artigos de vestuário, utilizando várias ferramentas manuais ou máquinas industriais que cumprem os requisitos dos clientes. Fazem amostras e protótipos para produzir séries de moldes de artigos de vestuário em diferentes tamanhos.', 'released', NULL, '7532'),
  ('http://data.europa.eu/esco/occupation/183d60f2-277f-47c8-a8c6-f5c8eedba2b0', 'Montador de Munições', 'Os montadores de munições montam em conjunto explosivos e outros componentes de munições. Realizam este trabalho em produção em série em fábricas de munições. A própria produção centra-se no fabrico de cartuchos ou projéteis.', 'released', '["Montadora de Munições", "Montador de Munições"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/18459eb0-5506-4692-9889-d1f9a2b989eb', 'Operador de Máquina de Gravar', 'Os operadores de máquina de gravar instalam, programam e cuidam das máquinas de gravar concebidas para entalhar com precisão um desenho na superfície de uma peça metálica, através de uma ponta de diamante na máquina de corte mecânica que cria pequenos pontos de impressão separados a partir das células cortadas. Interpretam os esquemas das máquinas de gravar e as instruções das ferramentas, realizam operações regulares de manutenção das máquinas e efetuam ajustes aos comandos precisos de gravação, tais como a profundidade das incisões e a velocidade de gravação.', 'released', '["Operadora de Máquina de Gravar", "Operador de Máquina de Gravar"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/184e59d7-5646-4fe4-9059-46867ff09574', 'Técnico de Proteção Radiológica', 'Os técnicos de proteção radiológica monitorizam os níveis de radiação em edifícios e instalações, a fim de garantir a conformidade com as normas em matéria de saúde e segurança, bem como de prevenir elevações perigosas nos níveis de radiação. Tomam medidas para minimizar as emissões de radiação e para evitar novas contaminações em caso de poluição por radiação, desenvolvendo planos de proteção contra as radiações, em especial para centrais e instalações nucleares.', 'released', '["Técnico de Proteção Radiológica", "Técnica de Proteção Radiológica"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/18552245-3c36-4a52-b4c6-295cabb5c93b', 'Desenvolvedor de Jogos de Azar', 'Os programadores de jogos de azar criam, desenvolvem e produzem conteúdos para lotarias, apostas e outros jogos de azar destinados a grandes audiências.;', 'released', '["Designer de Jogos de Lotaria", "Produtora de Jogos de Lotaria", "Desenvolvedor de Jogos de Fortuna e Azar, de Apostas e de Lotaria", "Desenvolvedora de Jogos", "Produtor de Jogos de Apostas", "Desenvolvedor de Jogos de Fortuna e Azar", "Designer de Jogos de Apostas", "Desenvolvedor de Jogos de Lotaria", "Desenvolvedora de Jogos de Fortuna e Azar", "Desenvolvedor de Jogos", "Desenvolvedora de Jogos de Fortuna e Azar, de Apostas e de Lotaria", "Produtor de Jogos de Fortuna e Azar", "Desenvolvedora de Jogos de Lotaria", "Produtor de Jogos de Lotaria", "Produtora de Jogos de Apostas", "Designer de Jogos de Fortuna e Azar", "Programador", "Desenvolvedora de Jogos de Azar", "Programador de Jogos de Azar"]'::jsonb, '2120'),
  ('http://data.europa.eu/esco/occupation/186ef31e-f26f-4320-a307-c5f95d6cb284', 'Consultor na Área da Ação Social', 'Os consultores na área da ação social prestam serviços de ação social de elevada qualidade, contribuindo para o desenvolvimento e a melhoria do trabalho de ação social e das práticas de assistência social. Contribuem para o desenvolvimento de políticas, realizam ações de formação e dedicam-se à investigação no domínio das práticas de ação social.', 'released', '["Consultor na Área da Ação Social", "Consultora na Área da Ação Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/187f063b-1002-4d46-9b79-c46b2caedbb3', 'Coordenador de Montagem de Máquinas', 'Os coordenadores de montagem de máquinas preparam e planeiam o fabrico de máquinas. Acompanham todo o processo de produção e asseguram a disponibilização atempada das montagens e dos recursos individuais.', 'released', '["Coordenador de Montagem de Máquinas", "Coordenadora de Montagem de Máquinas"]'::jsonb, '4322'),
  ('http://data.europa.eu/esco/occupation/189a337d-f6fb-44e2-9e7a-bc27b7b76e0e', 'Coreógrafo', 'Os coreógrafos criam sequências de movimentos nas quais são especificados o gesto, a forma ou ambos. Alguns coreógrafos assumem também o papel de coordenação, ensino e ensaio de artistas na produção da coreografia. Podem também ser coaches de movimentos para os atores.', 'released', '["Coreógrafa", "Coreógrafo"]'::jsonb, '2653'),
  ('http://data.europa.eu/esco/occupation/18a98579-f0b1-4dde-944f-1758dc113099', 'Operador de Máquina de Corte por Eletroerosão', 'Os operadores de máquina de corte por eletroerosão instalam e cuidam das máquinas de corte por eletroerosão concebidas para cortar o material em excesso de uma peça metálica através da utilização de descargas elétricas, ou faíscas, provocadas pela tensão elétrica e separadas por um líquido dielétrico, que remove os metais dos elétrodos. Estas aplicações podem envolver microscopia de transmissão e ótica.', 'released', '["Operadora de Máquina de Corte por Eletroerosão", "Operador de Máquina de Corte por Eletroerosão"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/18b00c9e-3a07-4346-bb86-b1577554cf56', 'Técnico de Tricotagem Têxtil', 'Os técnicos tricotagem têxtil realizam operações relacionadas com o estabelecimento de processos de tricotagem. Podem trabalhar em fábricas de malha de trama ou de urdidura, utilizando a tecnologia de informação digital (CAD) para o fabrico de padrões. Trabalham em cooperação com os técnicos de laboratório, a fim de garantir que não existam erros nos tecidos de malha. São responsáveis pelas mais elevadas taxas de produtividade.', 'released', '["Técnico de Tricotagem Têxtil", "Técnica de Tricotagem Têxtil"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/18cff178-4ef0-46c9-a6e5-f6f38179cdcb', 'Supervisor de Revestimento', 'Os supervisores de revestimento acompanham as operações de montagem de ladrilhos. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Revestimento", "Supervisora de Revestimento"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/18d2b37a-9c31-4393-833e-bc2f7b1ce52a', 'Analista Especialista em Fusões e Aquisições', 'Os analistas especialistas em fusões e aquisições supervisionam a execução das operações de compra, venda, fusão ou aquisição de empresas. Negoceiam e celebram contratos em nome do cliente, trabalhando em estreita colaboração com os advogados e os contabilistas. Os analistas especialistas em fusões e aquisições realizam as avaliações de riscos operacionais e jurídicos de uma empresa, avaliam as empresas comparáveis no mercado e contribuem para a integração pós-fusão.', 'released', NULL, '2413'),
  ('http://data.europa.eu/esco/occupation/18dafd4f-8c37-4276-b4b3-cfa31059b2b6', 'Marinheiro de Convés de Navio Pesqueiro', 'Os marinheiros de convés de navio pesqueiro trabalham em embarcações onde exercem atividades relacionadas com a pesca. Realizam uma vasta gama de atividades de pesca e de trabalho marítimo em terra e no mar, tais como o manuseamento de artes de pesca e capturas, comunicações, abastecimento, navegação, hospitalidade e provisões.;', 'released', '["Marinheiro de Convés de Navio Pesqueiro", "Marinheira de Convés de Navio Pesqueiro"]'::jsonb, '8350'),
  ('http://data.europa.eu/esco/occupation/18e14e61-495b-44cc-a7c6-df4c625934ba', 'Enfermeiro Especialista', 'Os enfermeiros especialistas promovem e restauram a saúde das pessoas, bem como diagnosticam e prestam cuidados num setor específico do domínio da enfermagem. Os enfermeiros especialistas podem incluir, entre outros: enfermeiros de cuidados ambulatórios, enfermeiros de prática avançada, enfermeiros cardíacos, enfermeiros dentistas, enfermeiros de cuidados à comunidade, enfermeiros de medicina legal, enfermeiros de gastroenterologia, enfermeiros de cuidados paliativos, enfermeiros pediátricos, enfermeiros de saúde pública, enfermeiros de cuidados de saúde, enfermeiros de reabilitação, enfermeiros renais e enfermeiros escolares. Os enfermeiros especialistas são enfermeiros generalistas com preparação para além do nível de um enfermeiro generalista e estão autorizados a exercer a profissão de especialista com competências específicas num domínio da enfermagem. ;', 'released', '["Enfermeiro Especialista em Enfermagem Comunitária", "Enfermeiro Especialista em Enfermagem Médico-Cirúrgica", "Enfermeiro Especialista em Saúde Infantil e Pediátrica", "Enfermeira Especialista em Saúde Mental e Psiquiátrica", "Enfermeiro Especialista em Reabilitação", "Enfermeira Especialista em Reabilitação", "Enfermeira Especialista em Enfermagem Médico-Cirúrgica", "Enfermeira Especialista em Saúde Infantil e Pediátrica", "Enfermeira Especialista em Enfermagem Comunitária", "Enfermeira Especialista", "Enfermeiro Especialista em Saúde Mental e Psiquiátrica", "Enfermeiro Especialista"]'::jsonb, '2221'),
  ('http://data.europa.eu/esco/occupation/18fa8080-3156-429a-bbd7-b3ef559b6721', 'Montador de Andaimes', 'Os montadores de andaimes instalam andaimes e plataformas, a fim de tornar o trabalho de construção em altura seguro.', 'released', '["Montador de Andaimes", "Montadora de Andaimes"]'::jsonb, '7119'),
  ('http://data.europa.eu/esco/occupation/18fbb1f8-eceb-4bf4-8fc7-932b8f6130cd', 'Supervisor de Colocação de Papel de Parede', 'Os supervisores de colocação de papel de parede acompanham as operações de colocação de papel de parede. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Colocação de Papel de Parede"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/190ec9a5-938c-45a5-bd9c-c12b1af33353', 'Embaixador', 'Os embaixadores representam o seu próprio governo em países estrangeiros para fins diplomáticos e de manutenção da paz. Tratam de negociações políticas entre o país de origem e o país onde estão situados e asseguram a proteção dos cidadãos do seu país de origem na nação em que estão situados. Facilitam a comunicação entre as duas nações e exercem funções consultivas junto do governo de origem para ajudar a desenvolver a política externa.', 'released', '["Conselheiro", "Diplomata", "Embaixadora Residente", "Embaixadora", "Secretária", "Cônsul", "Ministro Plenipotenciário", "Adida", "Núncio Apostólico", "Enbaixador", "Adido", "Embaixador Residente", "Embaixadora não-Residente", "Embaixador não-Residente", "Ministra Plenipotenciária", "Secretário", "Conselheira"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/196a4c75-9591-436f-9677-67252df34c22', 'Modelista de vestuário-CAD', 'Os modelistas de vestuário-CAD transformam o molde em papel em formato digital utilizando software informático especial. Operam e controlam máquinas que fabricam produtos diferentes relacionados com o vestuário.', 'released', NULL, '7532'),
  ('http://data.europa.eu/esco/occupation/1978c6ff-37b4-48f1-9aa6-88b9c568f74f', 'Massagista', 'Os massagistas realizam massagens para ajudar os clientes a relaxar e a reduzir o stress de acordo com as suas preferências. Utilizam massagens, equipamentos e óleos adequados e também dão instruções aos seus clientes sobre técnicas para melhorar o relaxamento.', 'released', '["Técnica de Massoterapia", "Técnico de Massoterapia", "Massagista de Estética"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/1999bdfa-f9c4-4a0b-8565-0305108ca65e', 'Assistente da Sala de Secagem de Pirotecnia', 'Os assistentes da sala de secagem de pirotecnia monitorizam e cuidam da sala de secagem, certificando-se de que os produtos pirotécnicos estão secos e armazenados de acordo com os parâmetros e especificações corretos.', 'released', '["Operadora de Câmaras de Secagem de Material Pirotécnico", "Operador de Câmaras de Secagem de Material Pirotécnico", "Assistentea da Sala de Secagem de Pirotecnia"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/19c2acbf-766c-4728-b960-b91252a95fd1', 'Gerente de Loja de Eletrodomésticos', 'Os gerentes de loja de eletrodomésticos assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerentea de Loja de Eletrodomésticos"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/19c2d8bc-aa3d-4b72-b55a-50bf751873fe', 'Fabricante de Cravos', 'Os fabricantes de cravos criam e montam peças para fabricar cravos, de acordo com instruções ou diagramas especificados. Lixam a madeira, afinam, testam e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Cravos"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/19cb84ca-952e-4f33-b31a-c918db074a6e', 'Operador de Montagem de Estruturas em Altura', 'Os operadores de montagem de estruturas em altura instalam e elevam estruturas de suspensão temporária em altura para apoio ao equipamento de espetáculos. O seu trabalho baseia-se em instruções, planos e cálculos. A sua função pode incluir o acesso por meio de cordas, o trabalho por cima dos colegas, a montagem de construções para elevar os artistas e a elevação de cargas pesadas, o faz com que seja uma atividade de alto risco. Trabalham tanto no exterior como no exterior. Cooperam com os operadores de montagem de estruturas ao nível do solo para descarregar e montar as construções ao nível do solo.', 'released', '["Operadora de Montagem de Estruturas em Altura", "Operador de Montagem de Estruturas em Altura"]'::jsonb, '7215'),
  ('http://data.europa.eu/esco/occupation/19db5ad1-ffbf-41a0-8746-d3878f0d5dbd', 'Estudioso dos Meios de Comunicação', 'Os estudiosos dos meios de comunicação investigam o papel e o impacto que os meios de comunicação têm na sociedade. Observam e documentam a utilização de diferentes tipos de meios de comunicação, como os jornais, a rádio e a televisão, e a resposta da sociedade.', 'released', '["Estudiosa dos Meios de Comunicação", "Estudioso dos Meios de Comunicação"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/19f6634f-ec0c-4513-b0d9-d43f9ddeb82d', 'Assistente Social em Contexto Escolar', 'Os assistentes sociais em contexto escolar tratam do bem-estar social e psicológico dos estudantes. Prestam aconselhamento aos estudantes no que respeita aos seus problemas pessoais que afetam o seu comportamento, desempenho e vida social. Estes podem incluir desde problemas de défice de atenção até problemas sociais e pessoais, como a pobreza, a violência doméstica e o abuso sexual. Os assistentes sociais em contexto escolar também são responsáveis pela comunicação entre os estudantes, os pais e a escola.', 'released', '["Assistentea Social em Contexto Escolar"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/1a07bd7d-2e1d-4930-a84a-1a442b8f2a44', 'Tradutor', 'Os tradutores transcrevem documentos escritos de uma ou mais línguas para outra, assegurando que a mensagem e as subtilezas permanecem no material traduzido. Traduzem os materiais com base na sua compreensão, os quais podem incluir documentação comercial e industrial, documentos pessoais, artigos jornalísticos, romances, escrita criativa e textos científicos, entregando as traduções em vários formatos.', 'released', '["Tradutora Técnica", "Tradutora-Revisora", "Tradutora Literária", "Tradutora Científica", "Tradutora", "Tradutor Científico", "Tradutor-Revisor", "Coordenador Linguístico", "Tradutor", "Tradutor Juramentado", "Tradutora Juramentada", "Tradutor Literário", "Tradutor Técnico", "Coordenadora Linguística"]'::jsonb, '2643'),
  ('http://data.europa.eu/esco/occupation/1a165cb5-99ff-4a4e-9e08-97a0fb7ed6f8', 'Técnico de Energias Marítimas Renováveis', 'Os técnicos de energias marítimas renováveis instalam parques e equipamentos de energias marítimas. Asseguram o funcionamento do equipamento em conformidade com a regulamentação e ajudam os engenheiros de energias marítimas renováveis na construção de dispositivos energéticos como pás de turbinas eólicas, geradores de correntes de maré e geradores de ondas. Tomam igualmente medidas em resposta a problemas do sistema e procedem à reparação de avarias.;', 'released', '["Técnica de ORE", "Instalador MRE", "Técnico de Turbina Eólica Offshore", "Técnica de Turbina Eólica Offshore", "Técnico de ORE", "Instaladora de Energia Renovável Marinha", "Instaladora de Energia Renovável Offshore", "Instalador de Energia Renovável Offshore", "Instalador de Energia Renovável Marinha", "Instaladora MRE", "Técnica de Energias Marítimas Renováveis"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/1a1ea837-0103-4230-8756-533a77c5f9f4', 'Técnico de Montagem de Caldeiras e Similares', 'Os técnicos de montagem de caldeiras e similares fabricam contentores, tais como caldeiras ou recipientes sob pressão. Interpretam os esquemas e os desenhos técnicos para montar peças e construir tubagens e acessórios.', 'released', '["Técnica de Montagem de Caldeiras e Similares", "Técnico de Montagem de Caldeiras e Similares"]'::jsonb, '7213'),
  ('http://data.europa.eu/esco/occupation/1a46d0f0-93d7-44d1-bff9-58e3f21bd4c4', 'Consultor de Serviços Sociais', 'Os consultores de serviços sociais prestam auxílio no desenvolvimento de políticas e procedimentos para programas de serviços sociais. Pesquisam programas de serviços sociais e identificam áreas a melhorar, prestando também auxílio no desenvolvimento de novos programas. Desempenham funções consultivas para as organizações de serviços sociais.', 'released', '["Consultor de Serviços Sociais", "Consultora de Serviços Sociais", "Assistente Social"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/1a6d1acf-5956-4ba0-95bf-b15b05a02013', 'Montador de Mecatrônica', 'Os montadores de mecatrónica procedem à montagem e manutenção de equipamento e máquinas de mecatrónica, tais como robôs, elevadores e eletrodomésticos avançados. Constroem os componentes mecânicos, elétricos e eletrônicos, instalam software, colocam os sistemas em funcionamento e procedem à manutenção e reparação dos componentes e sistemas.', 'released', '["Montador de Mecatrónica", "Montadora de Mecatrónica", "Montadora de Mecatrônica"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/1a7fb683-6544-4442-b54c-ec72ef468ff0', 'Realizador', 'Os realizadores são responsáveis pela produção global de um filme ou programa de televisão. Editam e vertem o guião em imagens audiovisuais. Os realizadores exercem a supervisão e a gestão dos atores. Transmitem a sua visão criativa aos atores, aos operadores de equipamento áudio e vídeo, aos técnicos de iluminação, etc. Os realizadores supervisionam também a edição das imagens.', 'released', '["Realizador", "Realizador de TV", "Realizadora de TV", "Realizadora de Cinema", "Realizadora", "Realizador de Cinema"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/1a87e487-6761-4374-b6db-100ac5a9ad5a', 'Consultor de Crédito', 'Os consultores de crédito fornecem orientações aos clientes relacionadas com serviços de crédito. Avaliam a situação financeira do cliente e questões relativas a dívidas referentes a cartões de crédito, faturas médicas e empréstimos para automóveis, com o objetivo de identificarem soluções de crédito adequadas para o cliente e também de fornecerem planos de eliminação de dívidas para regularizar a sua situação financeira, se necessário. Elaboram análises de crédito qualitativas e material de apoio à tomada de decisão relativamente a clientes definidos, em conformidade com a estratégia do banco em matéria de política de crédito, asseguram a qualidade do crédito e acompanham o desempenho da carteira de créditos. Os consultores de crédito dispõem igualmente de conhecimentos especializados no domínio da gestão da dívida e da consolidação do crédito.', 'released', '["Consultora de Crédito", "Consultor de Crédito"]'::jsonb, '3312'),
  ('http://data.europa.eu/esco/occupation/1a8bda86-307e-4cc0-a945-ceb678ff1471', 'Auxiliar de Limpeza de Instalações Sanitárias', 'Os empregados de limpeza de instalações sanitárias procedem à limpeza e manutenção de instalações sanitárias, em conformidade com as normas e as políticas da empresa. Utilizam equipamento de limpeza para limpar os espelhos, os pavimentos, as sanitas e os lavatórios. Executam as atividades de limpeza antes, durante e após os horários de serviço. Os empregados de limpeza de instalações sanitárias efetuam a reposição dos materiais, conforme for necessário, e mantêm registos das suas operações diárias.', 'released', '["Empregado de Limpeza de Instalações Sanitárias", "Empregada de Limpeza de Instalações Sanitárias"]'::jsonb, '9112'),
  ('http://data.europa.eu/esco/occupation/1a953e5a-f53f-461d-818b-6b2e655a751f', 'Técnico de Reparação de Relojoaria', 'Os técnicos de reparação de relojoaria procedem à manutenção e reparação de relógios de pulso e outros relógios. Identificam os defeitos, mudam baterias, colocam braceletes novas, lubrificam e substituem partes danificadas. Também podem restaurar relógios antigos.', 'released', '["Técnica de Reparação de Relojoaria", "Reparador de Relógios", "Técnico de Reparação de Relojoaria", "Reparadora de Relógios"]'::jsonb, '7311'),
  ('http://data.europa.eu/esco/occupation/1a9d99ba-4c08-4864-8f6a-1b0f2b4cf883', 'Trabalhador Hortícola', 'Os trabalhadores hortícolas desenvolvem atividades práticas e prestam assistência em viveiros ou estufas para a produção de culturas hortícolas.', 'released', '["Trabalhador de Cultivos Hortícolas", "Trabalhadora Hortícola", "Operária Hortícola", "Trabalhadora de Cultivos Hortícolas", "Trabalhador de Produção Hortícola", "Operário Hortícola", "Trabalhador Hortícola", "Trabalhadora de Produção Hortícola"]'::jsonb, '9214'),
  ('http://data.europa.eu/esco/occupation/1aa4bb15-c527-4a3b-9270-b3c71c4be111', 'Diretor de Cena', 'Os diretores de cena coordenam e supervisionam a preparação e a execução do espetáculo, a fim de assegurar que a imagem cénica e as ações no palco estejam em conformidade com a visão artística do diretor e da equipe artística. ; Identificam necessidades, controlam os processos técnicos e artísticos durante os ensaios e a realização de espetáculos ao vivo e eventos, de acordo com o projeto artístico, as características do palco e as condições técnicas, econômicas, humanas e de segurança. ; ; ;', 'released', '["Diretora de Cena", "Diretor de Cena"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/1aadb308-432a-4d01-b54b-b4f7f76dd419', 'Padeiro', 'Os padeiros fabricam uma grande gama de produtos de pão, produtos de pastelaria e outros produtos cozidos. Cumprem todos os processos de recepção e armazenamento de matérias-primas, de preparação de matérias-primas para panificação, de medição e mistura de ingredientes na massa e de prova. Vigiam os fornos para produzir produtos de acordo com a temperatura e o tempo adequados.', 'released', '["Padeiro", "Fabricante de Pão", "Chefe de Fabricação de Padaria", "Padeira", "Vendedor de Pão", "Vendedora de Pão"]'::jsonb, '7512'),
  ('http://data.europa.eu/esco/occupation/1ab184b6-de00-4476-ba1d-c6a71c668be3', 'Operador de Sistemas de Tratamento de Água', 'Os operadores de sistemas de tratamento de água tratam a água a fim de garantir a sua segurança para fins de consumo, rega ou outro tipo de utilização. Operam e efetuam a manutenção do equipamento de tratamento de água e garantem que a água é segura para engarrafamento e utilização na produção de alimentos, procedendo à sua análise rigorosa antes da distribuição e cumprindo as normas ambientais.', 'released', '["Operador de Sistemas de Tratamento de Água", "Operadora de Sistemas de Tratamento de Água"]'::jsonb, '3132'),
  ('http://data.europa.eu/esco/occupation/1ad4012e-30e3-492c-b42c-09cff3047574', 'Professor de Ciências do Ensino Secundário', 'Os professores de Ciências do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, as Ciências. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio das Ciências através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Ciências do Ensino Secundário", "Professor de Ciências do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/1ad59946-d13e-441e-9b36-56e1df055e21', 'Auditor Financeiro', 'Os auditores financeiros recolhem e analisam dados financeiros para clientes, organizações e empresas. Asseguram que os dados financeiros são mantidos adequadamente e estão isentos de distorções materiais devido a erros ou fraudes, que são relevantes e que funcionam de forma legal e eficaz. Analisam as apólices de empréstimo e de crédito ou números em bancos de dados e documentos, avaliam, consultam e prestam assistência à fonte da transação, se necessário. Utilizam a sua análise da governação financeira do cliente como garantia para demonstrar aos acionistas, às partes interessadas e ao conselho de administração da organização ou da empresa de que tudo se encontra em ordem.', 'released', '["Técnica de Auditora Interna", "Auditor", "Auditora Financeira", "Auditora Externa", "Auditora", "Auditor Externo", "Técnico de Auditora Interna", "Auditor Financeiro", "Auditora Financeiro"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/1ae8d28e-407c-48ab-88ff-4cb25bfcdea6', 'Concierge de Hotel', 'Os concierge de hotel fornecem informações aos clientes, prestam assistência aos hóspedes com várias tarefas, tais como reservas de restaurante, recomendações de eventos de entretenimento, reservas de transporte (limusinas, aviões, barcos, etc.) e outros serviços, aquisição de bilhetes para eventos especiais e assistência em vários serviços de viagens e circuitos de atrações locais.', 'released', '["Assistente de Serviço", "Concierge", "Conciergea de Hotel"]'::jsonb, '4229'),
  ('http://data.europa.eu/esco/occupation/1b123879-8f0d-4793-8069-3dc21a08921a', 'Especialista no Desenvolvimento de Produtos Químicos', 'Os especialistas no desenvolvimento de produtos químicos desenvolvem produtos químicos de acordo com as necessidades e expectativas dos clientes. Procedem ao desenvolvimento de fórmulas e processos de formulação, bem como à avaliação da eficiência e do desempenho das formulações.', 'released', '["Especialista no Desenvolvimento de Fórmulas Químicas"]'::jsonb, '2113'),
  ('http://data.europa.eu/esco/occupation/1b38a27d-ef98-4d9f-b1b2-8c109bf47e79', 'Gestor de Eventos', 'Os gestores de eventos planificam e supervisionam eventos, como festivais, conferências, cerimónias, eventos culturais, exposições, festas formais, concertos ou convenções. Organizam todas as etapas dos eventos, planificando as instalações, o pessoal, os fornecedores, os meios de comunicação e os seguros, dentro dos limites orçamentais e do prazo atribuídos. Os gestores de eventos asseguram o cumprimento das obrigações legais e a satisfação das expectativas do público destinatário. Trabalham em conjunto com a equipe de «marketing» na promoção do evento, na procura de novos clientes e na recolha de informações construtivas após os eventos.', 'released', '["Gerente", "Gestora de Eventos"]'::jsonb, '3332'),
  ('http://data.europa.eu/esco/occupation/1b3e150f-8ec1-47e2-a2ef-d02632efe0d5', 'Gerente de Loja de Artigos Médicos', 'Os gerentes de loja de artigos médicos são responsáveis pelas atividades e pelo pessoal em lojas especializadas. Estes funcionários gerem os trabalhadores, controlam as vendas do armazém, gerem os orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Farmácia", "Gerente de Drogaria", "Diretora Técnica de Farmácia", "Gerente de Parafarmácia", "Diretor Técnico de Farmácia", "Gerentea de Loja de Artigos Médicos"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/1b422c31-f242-46b5-bbdc-aa63885e4b5c', 'Inspetor de Saúde e Segurança no Setor dos Transportes', 'Os inspetores de saúde e segurança no setor dos transportes são responsáveis pela manutenção das normas de segurança, pela redução dos riscos para a empresa, o pessoal e os clientes e pela execução das normas industriais. Avaliam os sistemas de segurança existentes para determinar os potenciais riscos em todos os setores dos transportes, como os transportes rodoviários e marítimos, e desenvolvem políticas e procedimentos que minimizam os riscos para bens, trabalhadores e sistemas informáticos.', 'released', '["Inspetora de Saúde e Segurança no Setor dos Transportes", "Inspetor de Saúde e Segurança no Setor dos Transportes"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/1b48fbd2-688f-4ba9-b430-86b2ae273724', 'Operador de Estação de Incineração de Resíduos Líquidos', 'Os operadores de estações de incineração de resíduos líquidos eliminam os produtos químicos perigosos e as substâncias poluentes dos resíduos líquidos, como o petróleo, de modo a poderem ser utilizados com segurança em novas aplicações. Operam e efetuam a manutenção do equipamento de tratamento de resíduos líquidos, acompanham as operações e analisam as amostras para garantir o cumprimento das normas de segurança.', 'released', '["Operador de Estação de Incineração de Resíduos Líquidos", "Operadora de Estação de Incineração de Resíduos Líquidos"]'::jsonb, '3132'),
  ('http://data.europa.eu/esco/occupation/1b4e795d-6e49-4b7b-bb34-585edfd6eb18', 'Operador de Máquinas da Fabricação de Calçado', 'Os operadores de máquinas de fabrico de calçado asseguram o correto funcionamento de máquinas específicas na produção industrial de calçado. Operam maquinaria para montagem, corte, fecho e acabamento de calçado. Também realizam a manutenção de rotina da máquina.', 'released', '["Operadora de Máquinas do Fabricação de Calçado", "Operador de Máquinas do Fabricação de Calçado", "Operadora de Máquinas da Fabricação de Calçado"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/1b5ccfe7-1cc3-4f02-974c-f852d3faf57e', 'Técnico de Produção Agrícola', 'Os técnicos de produção agrícola planeiam a produção, gerem a empresa e participam no processo de produção das instalações de produção agrícola.', 'released', '["Trabalhadora Agrícola", "Trabalhador Agrícola", "Jornaleira", "Trabalhador de Produção Agrícola", "Técnico de Produção Agrícola", "Técnica de Produção Agrícola", "Trabalhadora de Produção Agrícola", "Jornaleiro"]'::jsonb, '6114'),
  ('http://data.europa.eu/esco/occupation/1b8c2a8e-204e-4035-bf88-921564e6df2e', 'Técnico de Acabamento Têxtil', 'Os técnicos de acabamento têxtil realizam operações relacionadas com a instalação de processos de acabamento. Os processos de acabamento são a série final de operações que melhora o aspeto e/ou a utilidade dos têxteis.', 'released', '["Técnico de Acabamento Têxtil", "Técnica de Acabamento Têxtil"]'::jsonb, '8154'),
  ('http://data.europa.eu/esco/occupation/1b8c75a9-407b-4554-a7d6-df391672c6b1', 'Operador de Máquinas Agrícolas', 'Os operadores de máquinas agrícolas operam equipamento e maquinaria especializados para a produção agrícola e a manutenção da paisagem.', 'released', '["Operária de Maquinaria Agrícola", "Operador de Maquinaria Terrestre", "Operador de Máquinas Agrícolas", "Operário de Maquinaria Agrícola", "Operadora de Maquinaria Terrestre", "Operadora de Máquinas Agrícolas"]'::jsonb, '8341'),
  ('http://data.europa.eu/esco/occupation/1b949bae-882f-40ff-9fe7-3c8ede5e38b5', 'Ilustrador', 'Os ilustradores proporcionam uma representação visual que corresponde ao conteúdo do texto ou da ideia que lhe está associado. As ilustrações podem ajudar a esclarecer conceitos ou objetos difíceis que são difíceis de descrever textualmente. Os ilustradores podem trabalhar para livros, revistas, jornais, bandas desenhadas e outras publicações.', 'released', '["Ilustradora", "Ilustrador"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/1bb2aa65-1524-4961-8dba-ad25f34f195f', 'Operador de Veículos de Combate a Incêndio', 'Os operadores de veículos de combate a incêndio conduzem e operam veículos de emergência, tais como carros dos bombeiros. Especializam-se em condução de emergência e prestam assistência a operações de combate a incêndio. Asseguram que todo o material seja bem armazenado no veículo, transportado e esteja pronto para utilização.', 'released', '["Operador de Veículos de Combate a Incêndio", "Operadora de Veículos de Combate a Incêndio"]'::jsonb, '8332'),
  ('http://data.europa.eu/esco/occupation/1bb7c072-38c8-430a-b943-76bfa312a5f4', 'Ator Substituto', 'Os atores substitutos substituem os atores antes do início da filmagem. Executam as ações dos atores durante a instalação audiovisual e da iluminação, para que tudo esteja no sítio certo durante a filmagem efetiva com os atores.', 'released', '["Ator Substituto", "Atriz Substituta", "Stand-In", "Atora Substituto"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/1bbaf82c-67ae-4beb-9a55-7298acf5b2af', 'Professor de Ciências de Enfermagem', 'Os professores de ciências de enfermagem são professores universitários ou docentes em geral e, frequentemente, médicos que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Enfermagem, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da Enfermagem, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor Universitário de Ciências de Enfermagem", "Professora de Ciências de Enfermagem", "Professor de Ciências de Enfermagem", "Professora Universitária de Ciências de Enfermagem"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/1bcc6461-4cc2-4732-a6d0-901687046443', 'Operador de Limpa-Neves', 'Os operadores de limpa-neves conduzem caminhões e limpa-neves para remover a neve e o gelo dos passeios, ruas e outros locais públicos. Também aplicam sal e areia no terreno para derreter o gelo dos locais afetados.', 'released', '["Operador de Limpa-Neves", "Operadora de Limpa-Neves"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/1bdb7d70-1769-4338-aa90-d25a90fe8a6d', 'Engenheiro Geólogo', 'Os engenheiros geólogos aplicam conhecimentos geológicos para a avaliação de áreas, solos, estabilidade de declives, sedimentos e outras características observáveis na Terra. Integram estas informações no planejamento e no desenvolvimento de projetos nesses locais. Avaliam e respondem a questões relativas às características geológicas dos solos, realizando atividades de investigação e experimentação nos sítios que serão objeto de intervenção.', 'released', '["Engenheira Geóloga", "Analista de Solos", "Engenheiro Geólogo", "Engenheira Geólogo"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/1c1e86f9-6347-42d6-aa6e-c95b138bf640', 'Agricultor Criador', 'Os agricultores criadores são responsáveis pela gestão de todos os aspetos da produção animal e da produção hortícola enquanto pequena empresa ou para autossuficiência.', 'released', '["Pequena Agricultora", "Agricultor Criador", "Pequeno Agricultor", "Agricultora Criadora", "Agricultora Criador"]'::jsonb, '6130'),
  ('http://data.europa.eu/esco/occupation/1c25fdb4-c6e2-4118-99a5-519e9657a2bd', 'Inspetor de Equipamento Elétrico', 'Os inspetores de equipamento elétrico verificam os produtos elétricos acabados para detectar eventuais defeitos físicos e ligações elétricas com defeito. Registam os resultados das inspeções e procedem à devolução de conjuntos com defeito para a produção.', 'released', '["Inspetor de Equipamento Elétrico", "Inspetora de Equipamento Elétrico"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/1c36dd08-f6a7-43f2-a889-beebedb71c25', 'Engenheiro de Equipamentos', 'Os engenheiros de equipamentos concebem e mantêm as máquinas e equipamentos em instalações de fabrico. Concebem máquinas que se ajustam aos requisitos e processos de fabrico. Além disso, visam a manutenção das máquinas e dos equipamentos para um funcionamento ininterrupto.', 'released', '["Engenheira de Equipamentos", "Engenheiro de Equipamentos"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/1c5a45b9-440e-4726-b565-16a952abd341', 'Engenheiro de Sistemas de Visão por Computador', 'Os engenheiros de sistemas de visão por computador estudam, concebem, desenvolvem e treinam algoritmos de inteligência artificial e primitivas de aprendizagem automática que compreendem o conteúdo das imagens digitais com base numa grande quantidade de dados. Aplicam estes conhecimentos para resolver diferentes problemas do mundo real, como a segurança, a condução autônoma, a produção robótica, a classificação de imagens digitais, o processamento e o diagnóstico de imagens médicas, etc.;', 'released', '["Cientista Aplicado de Visão Computacional", "Especialista em Visão Computacional", "Engenheira de Sistemas de Visão por Computador"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/1c5a896a-e010-4217-a29a-c44db26e25da', 'Engenheiro de Segurança de Sistemas Embarcados', 'Os engenheiros de segurança de sistemas embarcados aconselham e implementam soluções para controlar o acesso a dados e programas em sistemas embarcados e conectados. Contribuem para garantir o funcionamento seguro dos produtos com sistemas embarcados e dispositivos conectados, sendo responsáveis pela proteção e segurança dos sistemas conexos e pela concepção, planejamento e execução de medidas de segurança em conformidade. Os engenheiros de segurança de sistemas embarcados ajudam a manter a integridade destes sistemas, através da aplicação de salvaguardas que previnam intrusões e violações.;', 'released', '["Engenheira de Segurança Cibernética", "Especialista em Segurança Cibernética", "Engenheiro de Segurança Cibernética", "Internet das Coisas Engenheira de Segurança", "Internet das Coisas Engenheiro de Segurança", "Engenheira de Segurança IoT", "Engenheiro de Segurança IoT", "Engenheira de Segurança de Sistemas Embarcados"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/1c5ec3d2-a241-4ba2-ba20-e4da565383a6', 'Operador de Polidoras de Tambor', 'Os operadores de polidoras de tambor instalam e operam polidoras de tambor, muitas vezes tambores rotativos úmidos ou secos, concebidas para remover os materiais em excesso e as rebarbas de peças metálicas pesadas e de metais preciosos e para melhorar o aspeto da superfície, rodando as peças metálicas num tambor com areia, e eventualmente, água, permitindo a fricção mútua entre as peças e com a areia de forma a provocar um efeito suave de arredondamento.', 'released', '["Operador de Polidoras de Tambor", "Operadora de Polidoras de Tambor"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/1c85eee2-a8ca-4750-a889-10a3e6c17b80', 'Gestor de Fundos da UE', 'Os gestores de fundos da UE gerem fundos e recursos financeiros da UE nas administrações públicas. Participam na definição das prioridades de investimento e são responsáveis pela elaboração dos programas operacionais, dialogando com as autoridades nacionais para determinar os objetivos e os eixos prioritários dos programas. Os gestores de fundos da UE supervisionam os projetos financiados por fundos da UE, acompanham a sua execução, monitorizam os resultados alcançados e participam em atividades de certificação e auditoria. Poderão também ser responsáveis pela gestão das relações com as instituições europeias em questões relacionadas com auxílios estatais e gestão das subvenções.;', 'released', '["Gerente de Programas Operacionais de Fundos da UE", "Oficial de Política de Fundos da UE", "Supervisora de Projetos da UE", "Coordenador de Projetos da UE", "Gerente de Política de Fundos Europeus", "Oficial de Política Regional", "Supervisor de Projetos da UE", "Oficial de Políticas para Fundos da UE", "Gestora de Fundos da UE no Secretariado Conjunto", "Coordenadora de Projetos da UE", "Gestor de Fundos da UE no Secretariado Conjunto", "Oficial de Gestão e Controle da UE", "Especialista em Políticas e Financiamento da UE", "Gerente", "Gestora de Fundos da UE"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/1c862e14-80f8-4aa8-8f1c-fd2ca95b63ad', 'Meteorologista', 'Os meteorologistas estudam os processos climáticos, medem e preveem padrões meteorológicos e prestam serviços de consultoria a uma grande variedade de usuários de informação meteorológica. Criam modelos de previsão meteorológica, desenvolvem instrumentos de recolha de dados meteorológicos e elaboram estatísticas e bancos de dados.', 'released', '["Investigador em Meteorologia", "Investigadora em Meteorologia"]'::jsonb, '2112'),
  ('http://data.europa.eu/esco/occupation/1c948509-4015-40b0-b380-105fc85782a5', 'Curador de Jardim Zoológico', 'Os curadores de jardim zoológico ocupam geralmente a posição de gestão intermédia dentro de uma instituição. Grande parte do seu trabalho envolve a supervisão, a gestão e o desenvolvimento do espólio de animais. Frequentemente, isto está relacionado com a criação de animais e a política de bem-estar dos animais, a aquisição e disposição dos animais no jardim zoológico e a decisão da exibição de novas espécies. Os jardins zoológicos adquirem normalmente animais através de programas de criação em cativeiro. A recolha, o comércio e o transporte dos animais de jardim zoológico são regulamentados por agências governamentais, bem como por organizações de membros de jardins zoológicos. Por conseguinte, os curadores de jardim zoológico atuam como ligação entre estas agências e o próprio jardim zoológico. Além disso, desempenham um papel ativo na administração das funções do jardim zoológico e de todos os tipos de programas de criação em cativeiro.', 'released', '["Curador de Mamíferos de Jardim Zoológico", "Curadora de Mamíferos de Jardim Zoológico", "Curadora de Jardim Zoológico", "Curador de Jardim Zoológico", "Diretora de Jardim Zoológico", "Diretor de Jardim Zoológico"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/1c9937fe-5eaa-4f7e-ba31-77e6e7db022c', 'Projetista Aeroespacial', 'Os projetistas aeroespaciais convertem os projetos de engenheiros aeroespaciais em desenhos técnicos, utilizando geralmente programas de desenho assistido por computador. Os seus desenhos pormenorizam as dimensões, os métodos de fixação e montagem e outras especificações utilizados no fabrico de aeronaves e de veículos espaciais.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/1cd93859-d796-4559-90c4-4b4597cd6e54', 'Bombeiro Industrial', 'Os bombeiros industriais são responsáveis pela resposta de emergência em caso de incêndio ou de outras situações perigosas em zonas ou instalações industriais. Respondem ativamente à contenção dos incêndios e de outras substâncias perigosas, a fim de proteger as equipes e as instalações industriais. Asseguram a conformidade da instalação industrial com a regulamentação em matéria de saúde e segurança. Também regulam a limpeza do local e avaliam os danos.', 'released', '["Bombeira Industrial", "Bombeiro Industrial"]'::jsonb, '5411'),
  ('http://data.europa.eu/esco/occupation/1ce76c3b-edee-41b4-88c2-5db9b70d8bf0', 'Operador de Curtimento', 'Os operadores de curtimento programam e utilizam tambores de fábrica de curtumes. Executam o trabalho de acordo com as instruções de trabalho, verificam as características físicas e químicas do couro ou da pele e dos flutuadores líquidos (por exemplo, pH, temperatura, concentração de produtos químicos) durante o processo. Utilizam o tambor para lavar o couro ou a pele, retirando o pelo (no caso de couros e peles curtidos com o pelo ou lã), lavagem, curtimento, recurtimento, tingimento e moagem.', 'released', '["Operador de Curtimento", "Operadora de Curtimento"]'::jsonb, '7535'),
  ('http://data.europa.eu/esco/occupation/1d188cae-90e9-4950-9666-3e1a9500de50', 'Operador de Corte de Artigos em Couro', 'Os operadores de corte de artigos em couro verificam o couro, os seus materiais e moldes de corte, selecionam as áreas a cortar, posicionam peças no couro e noutros materiais, combinam os componentes do couro (peças) e verificam as peças cortadas face às especificações e os requisitos de qualidade. Todas as atividades e tarefas são executadas manualmente.', 'released', '["Operadora de Corte de Artigos em Couro", "Operador de Corte de Artigos em Couro"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/1d196f32-05ca-4ea5-a347-4fccbb3da863', 'Técnico de Eletrônica Naval', 'Os técnicos de eletrônica naval estabelecem, instalam e reparam sistemas e equipamentos eletrônicos nos navios. Reúnem componentes e cabos eletrônicos de acordo com os esquemas e os desenhos de montagem.', 'released', '["Técnica de Eletrônica Naval", "Técnico de Eletrônica Naval"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/1d4a4baf-4073-43bd-ac72-ff7d443273ff', 'Disk Jockey', 'Os disk jockeys misturam música a partir de várias fontes, utilizando um gira-discos ou uma consola de mistura, e põem música a tocar em eventos perante um público ao vivo. Podem difundir a música na rádio. Selecionam as músicas que serão reproduzidas na rádio e garantem a sua transmissão de acordo com a programação definida. Os disk jockeys podem também criar misturas para posterior distribuição e reprodução.', 'released', NULL, '2652'),
  ('http://data.europa.eu/esco/occupation/1d6fbb43-f4c7-4839-8099-55eae5d424a5', 'Assistente de Angariação de Fundos', 'Os assistentes de angariação de fundos prestam apoio administrativo aos responsáveis pela angariação de fundos. Têm como alvo potenciais doadores ou patrocinadores através da realização de pesquisas. Tratam os donativos e os pagamentos de subvenções, conservam os sistemas de arquivo eletrônico e em papel para todas as subvenções e doações, aceitam os donativos, redigem cartas de agradecimento e mantêm registos das angariações de fundos.', 'released', '["Assistentea de Angariação de Fundos"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/1d70e660-1114-41c6-926a-053541460d88', 'Técnico de Reparações de Material Esportivo', 'Os técnicos de reparações de material desportivo procedem à manutenção e reparação de material desportivo recreativo, tais como raquetes de tênis, instrumentos de tiro com arco e equipamento de campismo. Utilizam ferramentas manuais especializadas ou ferramentas mecânicas para reparar as peças danificadas.', 'released', '["Técnica de Reparações de Material Esportivo", "Técnico de Reparações de Material Esportivo"]'::jsonb, '7319'),
  ('http://data.europa.eu/esco/occupation/1d75ea5a-f902-4b47-8d63-5c6d2a5c0bb5', 'Ergonomista', 'Os ergonomistas analisam a concepção dos equipamentos, do mobiliário e dos sistemas, a fim de os melhorar para obter uma maior segurança, saúde e eficiência. Procuram melhorar a interação das pessoas com os equipamentos e o ambiente.', 'released', NULL, '2263'),
  ('http://data.europa.eu/esco/occupation/1d8545df-e3d8-4ece-9449-0f2940e97e7c', 'Operador de Aparelho de Desbaste', 'Os operadores de aparelho de desbaste instalam, programam e controlam aparelhos de desbaste, concebidos para aplicar processos abrasivos para remover pequenas quantidades de material em excesso e suavizar peças metálicas, utilizando uma roda abrasiva de dentes de diamante como dispositivo de corte para cortes muito precisos e leves. Interpretam os esquemas dos aparelhos de desbaste e as instruções das ferramentas, realizam operações regulares de manutenção das máquinas e efetuam ajustes aos comandos de gravação, tais como a profundidade dos cortes e a velocidade de rotação.', 'released', '["Operadora de Máquina Retificadora", "Operadora de Aparelho de Desbaste", "Operador de Aparelho de Desbaste", "Operador de Máquina Retificadora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/1d8f8111-79dd-41dc-aa2a-12f3192dde3c', 'Designer Automóvel', 'Os designers de automóveis criam modelos em 2D ou 3D e elaboram desenhos e gráficos isométricos. Trabalham em estreita colaboração com engenheiros informáticos para desenvolver designs de hardware para a próxima geração de aplicações automóveis, incluindo sistemas avançados de assistência ao condutor e veículo-tudo. Reavaliam o design, os materiais e as tecnologias de fabrico de veículos, antevendo alterações na sua arquitetura e na gestão da energia, nas características dos veículos e na funcionalidade e segurança dos componentes dos assentos.;', 'released', '["Designer da Indústria Automóvel"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/1da55a33-09b3-4ac7-818e-2a0fea68cecc', 'Gestor de Direitos de Publicação', 'Os gestores de direitos de publicação são responsáveis pelos direitos de autor dos livros. Organizam a venda destes direitos para que os livros possam ser traduzidos, produzidos em filmes, etc.', 'released', '["Gestora de Direitos de Publicação", "Agente Literário", "Agente Literária", "Gestor de Direitos de Publicação", "Gerente"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/1dd7c3cb-2d58-4dad-ae15-c9081174ab7e', 'Gestor de Canais de Comércio Eletrônico', 'Os gestores de canais de comércio eletrônico definem o programa de vendas para o comércio eletrônico, como os bens vendidos por correio eletrônico, Internet e redes sociais. Além disso, ajudam a planear a estratégia de vendas eletrônicas e a identificar oportunidades de comercialização. Os gestores de comércio eletrônico também analisam sítios concorrentes, analisam o desempenho e a análise do sítio.', 'released', '["Gestora de Canais de Comércio Eletrônico", "Diretora de Comércio Eletrônico", "Gestora de Vendas por Correspondência", "Diretor de Comércio Eletrônico", "Gestor de Canais de Comércio Eletrônico", "Gestor de Vendas por Correspondência", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/1de91afd-9da2-47ab-a7e7-19bf931709a4', 'Oficial de Operações Especiais', 'Os oficiais de operações especiais operam em missões especializadas, como as missões de luta contra o terrorismo. Executam missões de combate e de informação, a fim de intercetar equipamentos e instalações inimigos e de recolher informações sobre a estratégia e a circulação do inimigo.', 'released', '["Comando", "Paraquedista", "Sniper", "Ranger", "Fuzileira", "Fuzileiro"]'::jsonb, '0210'),
  ('http://data.europa.eu/esco/occupation/1de948c1-192a-4810-afb7-48548217a912', 'Operador de Gruas de Instalações de Produção', 'Os operadores de gruas de instalações de produção operam as gruas tecnológicas de base durante o processo de produção de uma determinada unidade, elevando e movimentando cargas (fardos, contentores, baldes e outros equipamentos) com matérias-primas e outros materiais.', 'released', '["Operador de Gruas de Instalações de Produção", "Operadora de Gruas de Instalações de Produção"]'::jsonb, '8343'),
  ('http://data.europa.eu/esco/occupation/1e2aaeff-5bf1-4649-9f09-9ebbd5cc3501', 'Projetista Eletromecânico', 'Os projetistas eletromecânicos desenham e criam planos técnicos em conjunto com engenheiros eletromecânicos. Interpretam as especificações e os requisitos do engenheiro e desenham equipamentos e componentes eletromecânicos.', 'released', '["Projetista Eletromecânico", "Projetista Eletromecânica"]'::jsonb, '3118'),
  ('http://data.europa.eu/esco/occupation/1e331638-3f66-4641-9c49-56a94235f94c', 'Analista de Seguros', 'Os analistas de seguros analisam informações relacionadas com os mercados de seguros e as suas notações de crédito, elaboram relatórios de notação e faturas, compilam dados financeiros e apresentam e explicam opiniões de notação de crédito às partes interessadas, aos clientes e às partes externas. Trabalham para companhias de seguros e calculam os prémios de seguro e as taxas para os clientes da empresa, utilizando métodos manuais e automatizados.', 'released', NULL, '2413'),
  ('http://data.europa.eu/esco/occupation/1e3c3e4d-a888-426e-aaf0-022c8b5d743d', 'Operador de Cortadora por Jato de Água', 'Os operadores de cortadora por jato de água instalam e operam um cortador de jato de água, concebido para cortar o material em excesso de uma peça metálica, utilizando um jato de água a alta pressão, ou uma substância abrasiva misturada com água.', 'released', '["Operadora de Máquina de Corte por Jato de Água", "Operador de Máquina de Corte por Jato de Água", "Operadora de Cortadora por Jato de Água", "Operador de Cortadora por Jato de Água"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/1e3c569b-e7ef-46b4-943a-2768a9969961', 'Operário de Fábrica de Cerveja', 'Os operários de fábrica de cerveja monitorizam os processos de maceração, brassagem e fermentação das matérias-primas. Certificam-se de que as cubas de cerveja estão corretamente limpas e atempadamente. Supervisionam o trabalho na fábrica de cerveja e operam o equipamento da fábrica de cerveja para fornecer cervejas de boa qualidade dentro do prazo especificado.', 'released', '["Técnico de Produção de Cerveja", "Operária de Fábrica de Cerveja", "Técnica de Produção de Cerveja", "Operário de Fábrica de Cerveja"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/1e55f5e3-2f02-434b-997b-9a9f3eb745e8', 'Supervisor de Linhas Elétricas', 'Os supervisores de linhas elétricas acompanham a construção e a manutenção das linhas elétricas e dos equipamentos associados. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Linhas Elétricas", "Supervisor de Linhas Elétricas"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/1e9e18cb-80b6-4598-acdb-ae3b51047720', 'Operador de Reabastecimento de Aeronaves', 'Os operadores de reabastecimento de aeronaves procedem à manutenção de sistemas de distribuição de combustível e asseguram o reabastecimento de aeronaves.', 'released', '["Operadora de Reabastecimento de Aeronaves", "Operador de Reabastecimento de Aeronaves"]'::jsonb, '8332'),
  ('http://data.europa.eu/esco/occupation/1eb56b85-af25-43d4-9e35-73d8ee78e228', 'Professor de Dança', 'Os professores de dança ensinam aos alunos, num contexto recreativo, os diversos gêneros e formas de dança, como o ballet, o jazz, danças de salão, o hip-hop, as danças latinas, a dança popular, etc.. Proporcionam aos alunos uma noção da história e do repertório de dança, mas centram-se sobretudo numa abordagem prática na suas aulas, nas quais ajudam os alunos a experimentar e a dominar diferentes estilos e técnicas de dança e expressão dramática e a desenvolver o seu próprio estilo. Criam, coreografam e produzem espetáculos e coordenam a produção técnica e o palco, bem como os adereços e os trajes.', 'released', '["Professor de Dança", "Instrutor de Dança", "Instrutora de Dança", "Professora de Dança"]'::jsonb, '2355'),
  ('http://data.europa.eu/esco/occupation/1ee1b792-4d5f-4555-be4e-ce7e4c05d1a9', 'Instrutor de Animais', 'Os instrutores de animais são responsáveis pelo manuseamento dos animais numa função de trabalho e continuam o treino do animal, em conformidade com a legislação nacional.', 'released', '["Manipulador de Animais", "Manipuladora de Animais", "Manuseadora de Animais", "Instrutora de Animais", "Manuseador de Animais", "Instrutor de Animais"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/1ee8dfca-19b0-4e1a-88ed-68548f80951b', 'Diretor de Importação e Exportação de Artigos de Floricultura', 'Os diretores de importação e exportação de artigos de floricultura implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Artigos de Floricultura", "Diretor de Importação e Exportação de Artigos de Floricultura", "Diretor de Vendas de Artigos de Floricultura", "Diretora de Vendas de Artigos de Floricultura"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/1f137f0b-7097-4583-9d1b-b69e57369319', 'Auxiliar de Educação Especial', 'Os auxiliares de educação especial prestam assistência a professores de educação especial nas suas funções na sala de aula. Cuidam das necessidades físicas dos alunos com uma variedade de deficiência e ajudam com tarefas, tais como as pausas para ir à casa de banho, viagens de ônibus, a alimentação e mudanças das salas de aula. Também prestam apoio pedagógico aos alunos, professores e pais e elaboram programas de aulas. Os auxiliares de educação especial prestam apoio aos alunos em função das suas necessidades específicas, ajudam com tarefas difíceis e acompanham o progresso dos alunos e o comportamento na sala de aula.', 'released', NULL, '5312'),
  ('http://data.europa.eu/esco/occupation/1f13d8c3-f601-4d3b-adc8-c8d52e0c15d5', 'Mentor de Voluntários', 'Os mentores de voluntários orientam os voluntários no processo de integração, inserindo-os na cultura de acolhimento e ajudando-os a dar resposta às necessidades administrativas, técnicas e práticas da comunidade. Apoiam o processo de aprendizagem e desenvolvimento pessoal dos voluntários ligado à sua experiência de voluntariado.;', 'released', '["Grupo de Apoio Voluntário", "Conselheiro Voluntário", "Pessoa de Engajamento Voluntário", "Conselheira Voluntário", "Pessoa de Apoio Voluntário", "Mentora de Voluntários"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/1f1a45a8-8f5c-4b66-a8a1-e02490addc55', 'Encarregado de Vestiário', 'Os encarregados de vestiário auxiliam os clientes a tratar de artigos e objetos pessoais em vestiários, geralmente em áreas de desporto ou de teatro. Também mantêm a limpeza geral das áreas designadas e ajudam com situações de objetos perdidos.', 'released', '["Encarregado de Vestiário", "Encarregada de Vestiário"]'::jsonb, '9629'),
  ('http://data.europa.eu/esco/occupation/1f2b8092-1787-4ef4-9282-cf81ce4b4d76', 'Operador de Gruas Móveis', 'Os operadores de gruas móveis trabalham com vários tipos de grua que se podem transportar facilmente por via terrestre, ferroviária e aquática. As gruas móveis são frequentemente montadas em caminhões.', 'released', '["Operador de Gruas Móveis", "Operadora de Gruas Móveis"]'::jsonb, '8343'),
  ('http://data.europa.eu/esco/occupation/1f305576-f57c-42c7-a139-728c72393cd4', 'Operador no Mercado da Energia', 'Os operadores no mercado da energia vendem ou adquirem ações no setor da energia, por vezes de fontes diferentes. Analisam o mercado da energia e investigam as tendências de preços para decidirem quando devem comprar ou vender as ações e assegurar o maior lucro. Fazem cálculos e elaboram relatórios sobre os procedimentos relativos ao comércio de energia e fazem previsões sobre a evolução do mercado.', 'released', '["Operadora no Mercado da Energia", "Operador no Mercado da Energia", "Trader no Mercado da Energia"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/1f31c047-3d72-45fe-83ff-91bd826913c6', 'Técnico de Limpeza e Desentupimento de Esgotos', 'Os técnicos de limpeza e desentupimento de esgotos procedem à manutenção e limpeza dos sistemas de esgotos e das respetivas condutas dentro das localidades. Eliminam os bloqueios que impedem o fluxo dos esgotos para assegurar o bom funcionamento dos sistemas.', 'released', '["Técnica de Limpeza e Desentupimento de Esgotos", "Técnico de Limpeza e Desentupimento de Esgotos"]'::jsonb, '9129'),
  ('http://data.europa.eu/esco/occupation/1f5932eb-b36d-44e1-a063-7aa9e228af51', 'Técnico de Apoio de Serviços de Acolhimento de Emergência', 'Os técnicos de apoio de serviços de acolhimento de emergência prestam assistência e apoio às crianças que são vítimas de abusos mentais ou físicos no sentido de serem juridicamente separadas dos seus pais. Ajudam-nas a recuperar, colocando-as em famílias adequadas e garantindo que o bem-estar das crianças é uma prioridade.', 'released', '["Técnico de Apoio de Serviços de Acolhimento de Emergência", "Écnica de Apoio de Serviços de Acolhimento de Emergência", "Técnica de Apoio de Serviços de Acolhimento de Emergência"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/1f665529-96e9-46c1-99f4-9ffbf9ffa036', 'Agente de Auditoria', 'Os agentes de auditoria recolhem e analisam dados financeiros, tais como as transações de inventário, para organizações e empresas, e garantem que sejam exatos, corretamente mantidos e que estejam corretos. Analisam os números em bancos de dados e documentos, avaliam e consultam e prestam assistência à fonte da transação, se necessário, que inclui contabilistas, gestores ou outros empregados.', 'released', '["Agentea de Auditoria"]'::jsonb, '4312'),
  ('http://data.europa.eu/esco/occupation/1f8314c2-01bd-4af4-babc-04d7034591b8', 'Técnico Agrícola', 'Os técnicos agrícolas reúnem e realizam experiências e testes em espécimes agrícolas e aquícolas. Prestam apoio a cientistas e agricultores, além de analisarem e comunicarem as condições existentes nos ambientes dos espécimes recolhidos.', 'released', '["Técnica Agrícola", "Técnico Agrícola"]'::jsonb, '3142'),
  ('http://data.europa.eu/esco/occupation/1f8967ce-9faa-4d56-a656-50e041f7d07e', 'Diretor de Qualidade na Indústria de Curtumes', 'Os diretores de qualidade na indústria de curtumes gerem e promovem os sistemas de garantia de qualidade aplicados nas organizações. Executam as tarefas de modo a cumprir requisitos e objetivos predefinidos, promovendo a comunicação interna e externa, visando simultaneamente a melhoria contínua e a satisfação do cliente.', 'released', '["Diretora de Qualidade na Indústria de Curtumes", "Supervisora de Qualidade", "Supervisor de Qualidade", "Diretor de Qualidade na Indústria de Curtumes", "Gestora de Qualidade", "Gestor de Qualidade"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/1f958638-066f-470c-9549-a9070ba280a6', 'Engenheiro Especialista em Componentes', 'Os engenheiros especialistas em componentes concebem e visam o desenvolvimento de engenharia de várias pequenas peças que compõem um projeto, uma máquina ou um processo de maior dimensão. Asseguram que as peças não são incompatíveis do ponto de vista da engenharia.', 'released', '["Engenheira Especialista em Componentes", "Engenheiro Especialista em Componentes"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/1f97f6e6-0ac7-4e77-88ab-2e3801c5a223', 'Engenheiro de Climatização', 'Os engenheiros de climatização concebem e desenvolvem sistemas de aquecimento, ventilação, ar condicionado e, eventualmente, de refrigeração para uso em residências, instalações de fabrico, escritórios, edifícios comerciais, etc.. Procuram soluções que sirvam as necessidades dos clientes e respondam às restrições arquitetónicas dos locais.', 'released', '["Engenheiro Especialista em Sistemas de Climatização", "Engenheiro Especialista em Sistemas AVAC", "Engenheira de Climatização", "Engenheiro Especialista em Sistemas de Aquecimento, Ventilação e Ar Condicionado", "Engenheira Especialista em Sistemas de Climatização", "Engenheiro de Climatização", "Engenheira Especialista em Sistemas de Aquecimento, Ventilação e Ar Condicionado", "Engenheira Especialista em Sistemas AVAC"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/1fb92021-9576-4c85-8759-f6918e9f0ad4', 'Diplomata', 'Os diplomatas representam o seu país de origem e o governo do seu país de origem em organizações internacionais. Negoceiam com os funcionários das organizações para assegurar a proteção dos interesses do seu país de origem, bem como para facilitar uma comunicação produtiva e amigável entre o país de origem e a organização internacional.', 'released', '["Alto Comissário", "Adida Militar", "Adida", "Enviada", "Adido", "Funcionária dos Negócios Estrangeiros", "Adida Cultural", "Enviado", "Adido Militar", "Funcionário dos Negócios Estrangeiros", "Agente Diplomático", "Alta Comissária", "Agente Diplomática", "Adido Cultural", "Diplomata da ONU"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/1fc60ca6-c3ea-4aeb-bf3b-350c0c5e7f93', 'Operador de Máquinas de Viticultura', 'Os operadores de máquinas de viticultura realizam atividades práticas relacionadas com o cultivo, a propagação de variedades de uvas e a produção de vinho com maquinaria ou equipamento especializado.', 'released', '["Operador de Máquinas de Viticultura", "Operadora de Máquinas de Viticultura"]'::jsonb, '6112'),
  ('http://data.europa.eu/esco/occupation/1fce1be0-bf52-449b-9a2b-3f2cc710290a', 'Analista de Compensação', 'Os analistas de compensação reconhecem e recompensam as contribuições e os comportamentos que apoiam os objetivos comerciais e os valores corporativos da empresa.', 'released', NULL, '2423'),
  ('http://data.europa.eu/esco/occupation/1ff5cf0d-e81f-4287-ba00-096816b16777', 'Piloto Marítimo', 'Os pilotos marítimos são marinheiros que comandam os navios através de águas perigosas ou congestionadas, como portos ou a foz de rios. São especialistas em manobrar navios, possuindo um profundo conhecimento das vias navegáveis locais.', 'released', '["Pilota Marítimo"]'::jsonb, '3152'),
  ('http://data.europa.eu/esco/occupation/1ff61522-8947-4c95-b589-cb0e0539a62b', 'Engenheiro de Sistemas de Energia', 'Os engenheiros de sistemas de energia supervisionam os processos de conversão e distribuição de energia. Analisam o aprovisionamento energético e a eficiência do consumo, desenvolvendo novas formas de melhorar os processos existentes, tendo em conta tanto os aspetos técnicos como financeiros. Além disso, estudam o impacto ambiental da utilização da energia e combinam a produção de energia renovável nos atuais sistemas de energia.', 'released', '["Engenheira Especialista em de Sistemas de Conversão de Energia", "Engenheira Especialista em Sistemas de Distribuição de Energia", "Engenheiro Especialista em Sistemas de Conversão de Energia", "Engenheira de Sistemas de Energia", "Engenheiro Especialista em Sistemas de Distribuição de Energia", "Engenheiro de Sistemas de Energia"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/2026adb2-62d7-4b92-9ccb-105abdebe37d', 'Engenheiro Especialista em Eletromagnetismo', 'Os engenheiros especialistas em eletromagnetismo concebem e desenvolvem sistemas, dispositivos e componentes eletromagnéticos, como por exemplo eletroímanes em altifalantes, fechaduras eletromagnéticas, ímanes condutores em IRM e ímanes em motores elétricos.', 'released', '["Engenheira Especialista em EMC", "Engenheira Especialista em Eletromagnetismo", "Engenheiro Especialista em EMC", "Engenheiro de Eletromagnética", "Engenheira Especialista em Sistemas Eletromagnéticos", "Engenheira de Eletromagnética", "Engenheiro Especialista em Eletromagnetismo", "Engenheiro Especialista em Sistemas Eletromagnéticos"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/202e1870-77d7-4efa-bf2c-7a032af30b7e', 'Supervisor de Montagem de Navios', 'Os supervisores de montagem de navios coordenam os trabalhadores envolvidos no fabrico de embarcações e de navios e programam as suas atividades. Elaboram relatórios de produção e recomendam medidas para reduzir os custos e aumentar a produtividade. Os supervisores de montagem de navios formam os trabalhadores nas políticas da empresa, na execução de funções e nas medidas de segurança. Verificam a conformidade com os procedimentos de trabalho e as técnicas de engenharia aplicados. Os supervisores de montagem de navios supervisionam as existências e comunicam com outros departamentos, tendo em vista evitar interrupções desnecessárias do processo de produção.', 'released', '["Supervisora de Montagem de Navios"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/203ea2ee-bbee-4aaf-83d7-2f2225f916e3', 'Arqueólogo', 'Os arqueólogos investigam e estudam as civilizações e as povoações do passado através da recolha e da inspeção dos restos materiais. Analisam e retiram conclusões sobre um vasto leque de domínios, como os sistemas hierárquicos, a linguística, a cultura e a política, com base no estudo de objetos, estruturas, fósseis, vestígios e artefactos deixados por estes povos. Os arqueólogos utilizam vários métodos interdisciplinares, como a estratigrafia, a tipologia, a análise 3D, a matemática e a modelação.', 'released', '["Arqueóloga Marinha", "Arqueóloga", "Arqueólogo", "Arqueólogo Marinho"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/2049d7ef-9ebe-41ae-b8b5-e97b77ee58a2', 'Agente de Relocalização', 'Os agentes de relocalização ajudam as empresas e as organizações no processo de deslocalização de trabalhadores. São responsáveis pela gestão de todas as atividades de mudança, incluindo o planejamento de serviços de mudanças e a prestação de aconselhamento sobre bens imóveis. Cuidam do bem-estar geral dos trabalhadores e das suas famílias.;', 'released', '["Agente de Mudanças", "Agentea de Relocalização"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/204c8b13-f5de-4e39-bd23-86ff8cf89b4d', 'Mergulhador Apanhador', 'Os mergulhadores apanhadores procedem à extração e recolha de recursos marinhos, tais como algas, coral, navalheiras, ouriços-do-mar e esponjas, de forma segura, competente e responsável, até uma profundidade de 12 metros, utilizando técnicas de mergulho de apneia, bem como equipamento de alimentação de ar da superfície, em circuito aberto.', 'released', '["Mergulhador Apanhador", "Mergulhadora Apanhadora", "Mergulhadora Apanhador"]'::jsonb, '7541'),
  ('http://data.europa.eu/esco/occupation/20786e6d-36f0-4d1e-b033-05101fa71f3c', 'Avaliador de Aprendizagens Anteriores', 'Os avaliadores da aprendizagens anteriores avaliam as competências, as aptidões e os conhecimentos de um candidato com base numa determinada qualificação ou certificado, de acordo com uma norma ou procedimento predefinido, e determinam objetivamente se o candidato preenche os critérios de desempenho correspondentes.;', 'released', '["Avaliadora de Habilidades", "Avaliador de Habilidades", "Avaliadora de Habilidades de Negócios", "Avaliador de Aprendizagem Anterior", "Avaliadora de Aprendizagem Anterior", "Avaliador de Habilidades de Negócios", "Avaliadora de Aprendizagens Anteriores"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/2079755f-d809-49e6-8037-4de6180e54c0', 'Engenheiro de Dados', 'Os engenheiros de dados desenvolvem a arquitetura necessária para tratar, gerir e armazenar grandes quantidades de dados que serão utilizados pelos cientistas de dados para análise. Concebem a infraestrutura e mantêm condutas e armazéns de dados para tirar partido desses dados para obter benefícios estratégicos.', 'released', '["Engenheira de Dados", "Engenheiro de Dados"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/207d5c25-46fe-401c-b32f-551684e9a8ea', 'Apanhador de Marisco', 'Os apanhadores de marisco apanham ovas e algas marinhas, bem como moluscos ou outros animais aquáticos, tais como crustáceos e equinodermes, ou recursos vegetais.', 'released', '["Apanhador de Marisco", "Apanhadora de Marisco"]'::jsonb, '9216'),
  ('http://data.europa.eu/esco/occupation/207d7b18-6540-432e-8aa6-785ed434572f', 'Analista de Informação Financeira', 'Os analistas de informação financeira obtêm conhecimentos da indústria e dos respetivos processos de inovação e comparam-nos com as operações da empresa, a fim de as melhorar. Concentram a sua análise nos processos, armazéns, sistemas de armazenamento e vendas a nível da cadeia de abastecimento, a fim de facilitarem a comunicação e de aumentarem as receitas.', 'released', NULL, '2421'),
  ('http://data.europa.eu/esco/occupation/2082e125-d06b-43e6-957f-b7aa3c48dc2f', 'Operador de Sistema de Corte Automático', 'Os operadores de sistema de corte automático enviam arquivos do computador para a máquina de corte, posicionam o material a cortar e digitalizam e selecionam a falha na superfície dos materiais, a fim de permitir o encaixe das peças, a não ser que a máquina o faça automaticamente. Dão à máquina a ordem de cortar, recolhem as peças cortadas e fazem a análise final do controlo de qualidade de acordo com as especificações e os requisitos de qualidade. Também controlam o estado dos mecanismos da máquina de corte.;', 'released', '["Operador de Sistema de Corte Automático", "Operadora de Sistema de Corte Automático"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/20b9f370-6b56-4679-8c06-c23b866a5bd0', 'Técnico de Relações Laborais', 'Os técnicos de relações laborais aplicam as políticas laborais numa organização e prestam aconselhamento aos sindicatos em matéria de políticas e negociações. Procedem à resolução de litígios e prestam aconselhamento em matéria de políticas de gestão de pessoal, além de facilitarem a comunicação entre os sindicatos e os gestores.', 'released', '["Técnica de Relações Laborais", "Técnico de Relações Laborais"]'::jsonb, '2423'),
  ('http://data.europa.eu/esco/occupation/20db07fc-cc02-46aa-a4fc-b3c73ba8fa8f', 'Supervisor de Acabamentos em Concreto', 'Os supervisores de acabamentos em betão acompanham o processo de acabamento de obras em betão. Atribuem tarefas aos responsáveis pelos acabamentos e tomam decisões rápidas para resolver problemas. Podem também transmitir os seus conhecimentos aos aprendizes.', 'released', '["Supervisora de Acabamentos em Concreto", "Supervisor de Acabamentos em Concreto"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/20e39113-05f5-4184-94e2-f5e8e8c8d2ea', 'Administrador Esportivo', 'Os administradores desportivos desempenham um papel de direção central nas organizações desportivas a todos os níveis, em qualquer desporto ou país na Europa (por exemplo, clubes desportivos, federações e autoridades locais). Desempenham tarefas organizacionais numa vasta gama de funções, em conformidade com a estratégia e as políticas definidas pela direção, os conselhos de administração e os comités. Desempenham um papel crucial na prestação global de desporto e o seu trabalho nas organizações desportivas tem um impacto direto na realização do potencial do setor na Europa no domínio da saúde, da inclusão social e da economia.', 'released', '["Técnica Esportiva", "Administradora Esportiva", "Administrador de Clube Esportivo", "Administrador Esportivo", "Técnico Esportivo", "Administradora de Clube Esportivo", "Administradora Esportivo"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/2104ee38-2fd1-4647-8f60-d2200f069805', 'Supervisor de Produção Vitícola', 'Os supervisores de produção vitícola supervisionam o trabalho realizado nas vinhas, organizam todo o trabalho relacionado com a vinha a fim de obter uma boa produção de uvas de boa qualidade atendendo ao ambiente. São responsáveis pela gestão técnica da vinha e das estruturas da vinha e pelos agentes de pessoal sazonal.', 'released', '["Supervisora de Produção Vitícola", "Supervisor de Produção de Viticultura", "Supervisor de Produção Vitícola", "Supervisora de Produção de Viticultura"]'::jsonb, '6112'),
  ('http://data.europa.eu/esco/occupation/211716b7-2857-40c8-a078-da983c78c70a', 'Instalador de Vidros de Automóvel', 'Os instaladores de vidros de automóvel instalam vidros em veículos a motor, tendo em conta as especificações do fabricante automóvel, tais como o tipo de vidro, a espessura, a dimensão e a forma. Encomendam e inspecionam as janelas de modelos de automóveis específicos e preparam as áreas danificadas para instalar novos vidros.', 'released', '["Instalador de Vidros de Automóvel", "Instaladora de Vidros Auto", "Instaladora de Vidros de Automóvel", "Instalador de Vidros Auto"]'::jsonb, '7125'),
  ('http://data.europa.eu/esco/occupation/2168e49d-e58a-43ec-a15e-8e173939b255', 'Técnico de Manutenção de Sistemas Microeletrônicos', 'Os técnicos de manutenção de sistemas microeletrónicos são responsáveis por aplicarem medidas preventivas e corretivas e por detetarem problemas em sistemas e dispositivos microeletrónicos. Diagnosticam e detectam anomalias em sistemas, produtos e componentes de microeletrónica e removem, substituem ou reparam esses componentes sempre que necessário. Procedem à manutenção preventiva de equipamentos.;', 'released', '["Técnico Microeletromecânico", "Técnico de Manutenção e Reparo", "Técnico de Manutenção Industrial", "Técnica de Manutenção de Equipamentos Microeletrônicos", "Técnica Microeletromecânico", "Técnica de Manutenção Industrial", "Técnico de Manutenção de Equipamentos Microeletrônicos", "Técnica de Manutenção e Reparo", "Técnica de Manutenção de Sistemas Microeletrônicos"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/2171a849-4065-411c-8390-835b7782ed8b', 'Gerente de Alojamento Local', 'Os gerentes de alojamento local gerem as operações diárias de um estabelecimento de alojamento local. Asseguram a satisfação das necessidades dos convidados.', 'released', '["Gerente de Alojamento Local", "Gerente de Bed and Breakfast", "Gerente de B&B", "Gerentea de Alojamento Local"]'::jsonb, '5152'),
  ('http://data.europa.eu/esco/occupation/217e7ae2-605d-4225-afd2-6319c2408116', 'Operador de Sala de Controle de Refinaria de Petróleo', 'Os operadores de salas de controlo de refinarias de petróleo desempenham uma série de tarefas a partir da sala de controlo de uma refinaria de petróleo. Acompanham os processos através de representações eletrônicas exibidas em monitores, mostradores e luzes. Os operadores de salas de controlo introduzem alterações às variáveis e comunicam com outros departamentos, para garantir que os processos decorrem sem problemas e de acordo com os procedimentos estabelecidos. Tomam as medidas adequadas em caso de irregularidades ou de situações de emergência.', 'released', '["Operador de Sala de Controle de Refinaria de Petróleo", "Operadora de Sala de Controle de Refinaria de Petróleo"]'::jsonb, '3134'),
  ('http://data.europa.eu/esco/occupation/218e30f0-bd6c-4120-99ba-9a90665a314f', 'Operador de Máquinas de Corte de Lâminas de Madeira', 'Os operadores de máquinas de corte de lâminas de madeira cortam madeira em folhas finas para utilizar como cobertura para outros materiais, tais como painéis de partículas ou de fibras. Os operadores de máquinas de corte de lâminas de madeira utilizam várias máquinas para obter diferentes cortes de madeira: um torno rotativo para produzir cortes perpendiculares aos anéis de crescimento, uma máquina de corte para criar peças semelhantes a pranchas, ou um torno semirredondo, que permite ao operador a liberdade de selecionar os cortes mais interessantes.', 'released', '["Operador de Máquinas de Corte de Lâminas de Madeira", "Operadora de Máquinas de Corte de Lâminas de Madeira"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/219d1c30-3849-4de3-b0d6-07da187b6521', 'Analista de Custos de Produção', 'Os analistas de custos de produção recolhem e analisam dados para avaliarem os montantes, os materiais, o trabalho e o tempo necessários para os processos de fabrico. Realizam análises com vista a identificarem projetos técnicos e processos de produção (alternativos) eficazes em termos de custos. Desenvolvem e utilizam métodos e ferramentas de planejamento, controlo e análise de custos. Além disso, realizam análises de risco quantitativas e qualitativas e apresentam relatórios sobre a evolução dos custos.', 'released', NULL, '2421'),
  ('http://data.europa.eu/esco/occupation/219e7fdd-5889-4517-9e86-620a12d535aa', 'Preparador de Locomotivas', 'Os preparadores de locomotivas são responsáveis pela verificação e ensaio de equipamentos e sistemas nos veículos ferroviários antes de os veículos serem deslocados. Asseguram que uma locomotiva está em condições de entrar em serviço, que o equipamento da locomotiva está corretamente instalado e que a formação de locomotivas corresponde ao percurso estabelecido para a locomotiva. Dependendo da organização individual do trabalho do operador, também realizam inspeções técnicas efetuadas antes da entrada em serviço da locomotiva.', 'released', '["Preparadora de Locomotivas", "Preparador de Locomotivas", "Preparador de Trens", "Preparadora de Trens"]'::jsonb, '8312'),
  ('http://data.europa.eu/esco/occupation/21a33619-1959-42e6-8478-64a930f7f225', 'Operador de Preparação de Tintas', 'Os operadores de preparação de tintas aplicam as tintas e as misturas de acabamento, tais como pigmentos e corantes, de acordo com as receitas definidas.;', 'released', '["Operadora de Preparação de Tintas", "Operador de Preparação de Tintas"]'::jsonb, '8155'),
  ('http://data.europa.eu/esco/occupation/21a42cfb-68c7-4f84-bdd7-81de07a6fff3', 'Aferidor de Petróleo', 'Os aferidores de petróleo testam o petróleo durante o processamento e antes da expedição. Controlam os sistemas de bombagem e regulam o fluxo de petróleo para os oleodutos.', 'released', '["Aferidora de Petróleo", "Aferidor de Petróleo"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/21ae429f-a152-46a6-a73c-9ec65c7803f0', 'Promotor', 'Os promotores trabalham com os artistas (ou os seus agentes) e os locais para a organização de um espetáculo. Estabelecem contatos com as bandas e os agentes para chegarem a acordo sobre a data do espetáculo e negociarem um acordo. Reservam o local e promovem o espetáculo agendado. Certificam-se de que tudo o que a banda necessita está pronto e definem as horas do controlo de som e a ordem do espetáculo. Alguns promotores trabalham por conta própria, mas também podem estar vinculados a um único espaço ou festival. ;', 'released', '["Promotor", "Promotora"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/21af40bb-2ae3-4fc7-9b28-d2cdd8308912', 'Assistente de Promoções', 'Os assistentes de promoções prestam apoio na implementação de programas e de ações promocionais em pontos de venda. Pesquisam e administram todas as informações exigidas pelos gestores para decidirem sobre a necessidade de programas de promoção. Em caso afirmativo, auxiliam na obtenção de materiais e recursos para a ação promocional.', 'released', '["Assistentea de Promoções"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/21cba86a-68c5-456c-aec2-cc04840b3c0e', 'Controlador de Pragas', 'Os controladores de pragas identificam, eliminam e repelem pragas mediante a aplicação de soluções químicas específicas, a fixação de armadilhas e outros equipamentos para controlar as pragas, tais como ratazanas, ratos e baratas. Aplicam pesticidas e limpam e eliminam as pragas após o extermínio. As suas tarefas podem incluir a eliminação de fungos, humidade ou insetos. Informam e aconselham os clientes, residentes e proprietários de instalações sobre os cuidados e os métodos de prevenção para evitar as pragas.', 'released', '["Controladora de Pragas", "Controlador de Pragas"]'::jsonb, '7544'),
  ('http://data.europa.eu/esco/occupation/21de0f3b-a71a-4263-a9ba-90c5f3721b4d', 'Consultor Financeiro', 'Os consultores financeiros ajudam as pessoas a lidarem com várias questões financeiras pessoais. São especializados no planejamento financeiro, como planos de reforma, no planejamento do investimento, na gestão dos riscos e no planejamento de seguros, bem como no planejamento fiscal. Aconselham uma estratégia adaptada às necessidades do cliente. Asseguram a exatidão dos registos bancários e de outros registos financeiros, mantendo simultaneamente uma abordagem orientada para o cliente e seguindo as normas éticas.', 'released', '["Assessor Financeiro", "Consultor Financeiro", "Assessora Financeira", "Consultora Financeira", "Consultora Financeiro"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/21f4eb29-f6e5-4623-acb9-f3ff9c2f525d', 'Formador em Técnicas de Oratória', 'Os formadores em técnicas de oratória fornecem, muitas vezes de forma privada, formação aos clientes em teoria e técnicas para a melhorar das suas competências em matéria de oratória. Identificam os pontos fortes e os pontos fracos de cada cliente e adaptam a sua instrução às suas necessidades específicas, o que pode incluir a melhoria da projeção vocal, da articulação, das capacidades de apresentação e da linguagem corporal do cliente. Em função dos antecedentes do cliente, sejam empresariais, académicos ou outros, os formadores em técnicas de oratória também dão formação aos clientes ou alunos em poder argumentativo, retórica e outras técnicas de debate.', 'released', '["Formador em Técnicas de Oratória", "Coach de Public Speaking", "Formadora em Técnicas de Falar em Público", "Formador em Técnicas de Falar em Público", "Public Speaking Coach", "Formadora em Técnicas de Oratória"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/21fe7141-68fa-4db7-9ee2-53097cef541a', 'Operário da Construção de Vias Navegáveis', 'Os operários da construção de vias navegáveis trabalham na manutenção de canais, barragens e outras estruturas de vias navegáveis, tais como estações de águas costeiras ou interiores. São responsáveis pela construção de quebra-mares, canais, diques e represas, bem como por outras obras em e à volta da água.', 'released', '["Operária da Construção de Vias Navegáveis", "Operário da Construção de Vias Navegáveis"]'::jsonb, '9312'),
  ('http://data.europa.eu/esco/occupation/2229a024-21e4-43ef-b3fd-2444ab41bfb8', 'Técnico de Tinturaria Têxtil', 'Os técnicos tinturaria têxtil realizam operações relacionadas com a instalação de processos de tingimento.', 'released', '["Técnico de Tinturaria Têxtil", "Técnica de Tinturaria Têxtil"]'::jsonb, '8154'),
  ('http://data.europa.eu/esco/occupation/2231ed97-69dc-4b6e-93ee-8c0e5bb5dbb8', 'Operador de Máquinas de Fabricação de Móveis Metálicos', 'Os operadores de máquinas de fabrico de móveis metálicos utilizam máquinas e ferramentas elétricas para cortar, moldar e unir peças metálicas para produzir móveis de metal, que vão de equipamento de escritório a acessórios exteriores. Utilizam diferentes tipos de metais, tais como alumínio, ferro e aço inoxidável, e diferentes tipos de processos, tais como a formação e a moldagem de metais. Pulem e aplicam camadas protetoras e, em alguns casos, acabamentos de decoração nas peças metálicas. Montam e juntam os elementos para obter o produto final.', 'released', '["Operador de Máquinas de Fabricação de Móveis Metálicos", "Operadora de Máquinas de Fabricação de Móveis Metálicos"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/22585d1e-48aa-45a6-a8c3-d072b4ff1b31', 'Operador de Sistemas de Integração de Media', 'Os operadores de sistemas de integração de media controlam a imagem global, os conteúdos e/ou a sincronização e distribuição de sinais de comunicação entre a execução de diferentes disciplinas de um espetáculo com base no conceito artístico ou criativo, em interação com os artistas. O seu trabalho é influenciado e influencia os resultados dos outros operadores. Por conseguinte, os operadores trabalham em estreita colaboração com os designers, outros operadores e os artistas. Os operadores de sistemas de integração de media preparam as ligações entre os diferentes quadros operacionais, supervisionam a instalação, dirigem a equipe técnica, configuram o equipamento e operam o sistema de integração de todos os media. O seu trabalho baseia-se em planos, instruções e outra documentação.;', 'released', '["Operador para Integração de Mídia", "Operadora para Integração de Mídia", "Operadora de Sistemas de Integração de Media"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/22799921-76a1-44c4-a7c3-c6a548e8ad85', 'Artista de Circo', 'Os artistas de circo desenvolvem atuações originais, exibindo grandes competências artísticas e de execução, profundidade emotiva e propostas artísticas para o público em geral. De forma individual ou em colaboração, podem executar uma ou mais disciplinas de circo tradicionais ou originais, que se baseiam geralmente em capacidades físicas como a força, o equilíbrio, a agilidade, a flexibilidade, a destreza e a coordenação de partes do corpo, combinadas com disciplinas de execução como a dança, o teatro, a mímica, etc. A natureza física dos exercícios realizados encerra frequentemente um certo nível de risco para o executante.', 'released', '["Faquir", "Contorcionista", "Ventríloquo", "Ventríloqua", "Mágica", "Hipnotizador", "Malabarista", "Domadora", "Mágico", "Hipnotizadora", "Acrobata", "Palhaço", "Trapezista", "Artista do Trapézio", "Domador"]'::jsonb, '2659'),
  ('http://data.europa.eu/esco/occupation/2296fa07-98ae-4875-b18d-96ed86134ffb', 'Inspetor de Equipamento Eletrônico', 'Os inspetores de equipamento eletrônico verificam o equipamento eletrônico para detectar eventuais defeitos e avarias. Asseguram que o equipamento seja corretamente montado de acordo com as especificações e a regulamentação nacional e internacional.', 'released', '["Inspetor de Equipamento Eletrônico", "Inspetora de Equipamento Eletrônico"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/22987b58-dbfa-4ecd-ae3f-82dd209255f6', 'Consultor de Tecnologia da Informação Ecológica', 'Os consultores de tecnologia da informação ecológica prestam aconselhamento às organizações sobre a sua estratégia relativa à tecnologia da informação ecológica, bem como sobre a sua implementação da forma mais eficaz e eficiente para permitir à organização cumprir os seus objetivos ambientais a curto, médio e longo prazo.', 'released', '["Perita em Tecnologia da Informação Ecológica", "Consultor de Tecnologias de Informação e Comunicação Ecológicas", "Consultora de Tecnologia da Informação Ecológica", "Especialista em Tecnologia da Informação Ecológica", "Perito em Tecnologia da Informação Ecológica", "Consultora de Tecnologias da Informação Ecológicas", "Consultora de Tecnologias de Informação e Comunicação Ecológicas", "Consultor de Tecnologias da Informação Ecológicas", "Consultor de Tecnologia da Informação Ecológica", "TI"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/22f86890-f68b-402f-a711-3e6df4913271', 'Datilógrafo', 'Os datilógrafos utilizam computadores para a datilografia e a revisão de documentos e compilam material a ser datilografado, tal como correspondência, relatórios, quadros estatísticos, formulários e gravações áudio. Leem as instruções que acompanham o material ou seguem as instruções verbais para determinar os requisitos, tais como o número de cópias necessárias, a prioridade e o formato desejado.', 'released', '["Datilógrafo", "Datilógrafa"]'::jsonb, '4131'),
  ('http://data.europa.eu/esco/occupation/23043d05-42c4-4811-b478-f8a17d22480b', 'Operador de Molderadora', 'Os operadores de molderadora operam máquinas que fazem parte do processo de produção de moldes para o fabrico de peças vazadas ou de outros materiais moldados. Cuidam das molderadoras que utilizam materiais adequados, tais como areia, plástico ou cerâmica para a obtenção do material de moldagem. Podem, então, utilizar um padrão e um ou mais núcleos para produzir o formato correto neste material. O material moldado é depois deixado a secar e, posteriormente, é utilizado como molde na produção de produtos moldados, tais como peças vazadas de metal ferroso e não ferroso.', 'released', '["Operadora de Molderadora", "Operador de Molderadora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/2339733d-5a37-4031-b587-db28848e4958', 'Especialista em Execução de Hipotecas', 'Os especialistas em execução de hipotecas procedem à revisão da documentação relacionada com bens em situação de execução hipotecária. Prestam assistência aos clientes cujos bens foram reclamados pelos bancos devido ao não pagamento da sua hipoteca, avaliando as possibilidades para o proprietário acautelar o bem.', 'released', NULL, '3315'),
  ('http://data.europa.eu/esco/occupation/234be692-befb-41df-bdf0-e1b2f4eaf5e7', 'Animador Recreativo', 'Os animadores recreativos prestam serviços recreativos a pessoas e crianças em férias. Organizam atividades, tais como jogos para crianças, competições desportivas, circuitos de ciclismo, espetáculos e visitas de museus. Os animadores recreativos também publicitam as suas atividades, gerem o orçamento disponível para cada evento e consultam os seus colegas.', 'released', '["Animadora Recreativa", "Animador Recreativo", "Animadora Recreativo"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/235ce16a-1ef7-4535-a82e-e371213c392b', 'Operador de Unidade de Separação de Ar', 'Os operadores de unidades de separação de ar controlam e efetuam a manutenção dos equipamentos de extração de azoto e de oxigénio do ar, assegurando o cumprimento dos parâmetros operacionais de pressão, de fluxo e de temperatura exigidos. Realizam testes de pureza do produto e monitorizam a sua transferência para tanques de armazenamento ou para encher garrafas.', 'released', '["Operadora de Unidade de Separação de Ar", "Operador de Unidade de Separação de Ar"]'::jsonb, '3133'),
  ('http://data.europa.eu/esco/occupation/237e21f1-a7fa-4273-91eb-28e7b5d72f60', 'Operador de Máquinas de Fabricação de Lacas', 'Os operadores de máquinas de fabrico de lacas procedem à operação e manutenção das lacas, misturadores de tintas sintéticas e moinhos de bolas pequenos, certificando-se de que o produto final esteja de acordo com a fórmula.', 'released', '["Operador de Máquinas de Fabricação de Lacas", "Operadora de Máquinas de Fabricação de Lacas"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/239707a0-4754-4f4b-80b6-6b1ef5657aed', 'Técnico de Masterização de Som', 'Os técnicos de masterização de som convertem registos acabados para o formato desejado, tal como CD, vinil e digital. Asseguram a qualidade do som em todos os formatos.;', 'released', '["Técnica de Masterização", "Técnico de Masterização", "Técnica de Masterização de Som"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/23993e79-a0a0-4155-9f62-68e14ee65dab', 'Chefe de Turno na Mineração', 'Os chefes de turno na mineração supervisionam o pessoal, gerem as instalações e o equipamento, otimizam a produtividade e asseguram a segurança da mina de forma permanente.', 'released', '["Chefea de Turno na Mineração"]'::jsonb, '3121'),
  ('http://data.europa.eu/esco/occupation/23a61ff1-c954-4867-b982-a018b535f98b', 'Agente de Economia de Energia', 'Os agentes de economia de energia promovem a conservação da energia quer em habitações, quer em empresas. Aconselham as pessoas sobre formas de reduzir o seu consumo de energia, através da execução de melhorias da eficiência energética e da aplicação de políticas de gestão da procura de energia.', 'released', '["Técnico de Eficiência Energética", "Técnica de Eficiência Energética", "Consultora Energética", "Consultor Energético", "Agentea de Economia de Energia"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/23a9e478-d465-4b61-b6d9-97b7e90af17a', 'Diretor de Distribuição — Floricultura', 'Os diretores de distribuição — floricultura planificam a distribuição de flores e plantas a diversos pontos de venda.', 'released', '["Diretor de Distribuição — Floricultura", "Diretora de Logística — Floricultura", "Diretora de Distribuição — Floricultura", "Diretor de Logística — Floricultura"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/23be4cb6-c5e7-449e-8d76-8edfe9a00478', 'Auxiliar de Limpeza de Mobiliário', 'Os empregados de limpeza de mobiliário procedem à manutenção de artigos de mobiliário através da limpeza do pó, da aplicação de encáustico, da limpeza de manchas e da manutenção da cor.', 'released', '["Empregado de Limpeza de Mobiliário", "Empregada de Limpeza de Mobiliário"]'::jsonb, '9112'),
  ('http://data.europa.eu/esco/occupation/23e3a8a0-905a-45be-983f-4cf32e133e09', 'Editor de Imagem', 'Os editores de imagem processam imagens e modelos gráficos utilizando máquinas de fotocomposição. Otimizam os modelos para obter os melhores resultados possíveis, determinando a disposição correta do texto e da imagem na folha de impressão. O produto é depois colocado em película ou papel fotográfico.', 'released', '["Editora de Imagem", "Editor de Imagem"]'::jsonb, '7321'),
  ('http://data.europa.eu/esco/occupation/23e692a9-a242-4d4f-988f-ed562f757864', 'Intérprete', 'Os intérpretes compreendem e convertem a comunicação oral de uma língua para outra. Retêm quantidades consideráveis de informações, recorrendo frequentemente à técnica de anotação, e comunicam-nas imediatamente, mantendo simultaneamente as subtilezas e a tônica da mensagem na língua de destino.', 'released', '["Intérprete de Linguagem Gestual", "Intérprete de Conferência", "Guia-Intérprete", "Intérpretea"]'::jsonb, '2643'),
  ('http://data.europa.eu/esco/occupation/23eddde2-5e8b-4953-b275-cdc864e6d976', 'Lubrificador Industrial', 'Os lubrificadores industriais garantem que as máquinas industriais estão devidamente lubrificadas para manter as operações. Utilizam pistolas de lubrificação para lubrificar as máquinas. Os lubrificadores industriais também desempenham funções básicas de manutenção e reparação.', 'released', '["Lubrificadora Industrial", "Lubrificador Industrial"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/24119471-6ca1-465b-8f48-b2aec5c60869', 'Técnico de Equipamento Rotativo', 'Os técnicos de equipamento rotativo são responsáveis pelas atividades de prevenção e manutenção corretiva de equipamentos rotativos, tais como turbinas, compressores, motores e bombas. Asseguram a disponibilidade e a integridade dos sistemas e equipamentos instalados em termos de segurança e fiabilidade.', 'released', '["Técnico de Equipamento Rotativo", "Técnica de Equipamento Rotativo"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/2412bbb1-29ca-4e17-a2b8-70694f0cb14f', 'Orientador Educativo', 'Os orientadores educativos prestam apoio prático e emocional aos alunos de uma instituição de ensino, quer em pequenos grupos, quer em salas de aula, quer individualmente. Funcionam como um funcionário escolar acessível que os alunos podem contactar para uma grande variedade de questões. Os orientadores educativos podem prestar aconselhamento sobre problemas pessoais, como integração social e problemas comportamentais, e sobre questões relacionadas com o ensino, como a criação de programas curriculares adequados, ou a discussão sobre os resultados dos testes, e informam os alunos sobre outras opções de ensino. Podem trabalhar em estreita colaboração com um assistente social escolar e/ou com um psicólogo escolar e reencaminhar os alunos para outros serviços de apoio, se necessário.', 'released', '["Orientadora Educativa", "Orientador Educativo", "Orientadora Educativo"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/24135b84-cbdd-4d42-9ed2-02fd982d15b2', 'Desenvolvedor Blockchain', 'Os programadores de cadeias de blocos implementam ou programam software baseado em cadeias de blocos assentes em especificações e designs, utilizando linguagens, ferramentas e plataformas de programação.;', 'released', '["Engenheiro de Blockchain", "Especialista em Tecnologia de Contabilidade Descentralizada", "Engenheira de Blockchain", "Especialista em DLT", "Programador", "Desenvolvedora Blockchain", "Programador de Cadeias de Blocos"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/24161923-e3e6-4096-b377-f1ee8a7ea31b', 'Engenheiro de Sistemas de Navegação por Satélite', 'Os engenheiros de sistemas de navegação por satélite desenvolvem, testam e supervisionam o fabrico de sistemas por satélite e de programas por satélite. Podem também desenvolver programas de software, recolher e investigar dados e testar os sistemas por satélite. Os engenheiros de satélites podem também desenvolver sistemas de comando e controlo dos satélites. Monitorizam os satélites para a detecção de problemas e comunicam o comportamento do satélite em órbita.', 'released', '["Engenheiro de Sistemas de Navegação por Satélite", "Engenheira de Sistemas de Navegação por Satélite"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/2430774f-d92a-40e4-817d-d03dd5a33207', 'Construtor de Pneus', 'Os construtores de pneus constroem pneus a partir de componentes de borracha. operam máquinas e ferramentas manuais.', 'released', '["Construtor de Pneus", "Construtora de Pneus"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/243f3b7e-cd7a-419a-94c0-d4f2040f09af', 'Diretor de Distribuição — Computadores e Produtos Informáticos', 'Os diretores de distribuição — computadores e produtos informáticos planificam a distribuição de computadores, equipamento informático periférico e software a vários pontos de venda.', 'released', '["Diretora de Distribuição — Computadores e Produtos Informáticos", "Diretor de Distribuição — Computadores e Produtos Informáticos", "Diretora de Logística — Computadores e Produtos Informáticos", "Diretor de Logística — Computadores e Produtos Informáticos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/24413f38-e457-4de1-bba0-5a02b7282e2c', 'Trabalhador da Pesca em Águas Profundas', 'Os trabalhadores da pesca em águas profundas operam a bordo dos navios de pesca para capturar peixe em águas profundas para venda ou entrega. Utilizam equipamento, como canas e redes, para capturar peixe em águas profundas em conformidade com a legislação. Os trabalhadores da pesca em águas profundas também transportam, manuseiam e preservam o peixe através da salga, refrigeração ou congelação.', 'released', '["Trabalhadora da Pesca em Águas Profundas", "Trabalhador da Pesca em Águas Profundas"]'::jsonb, '6223'),
  ('http://data.europa.eu/esco/occupation/244a79eb-122b-4bee-8065-b4c39efce4ff', 'Responsável Pela Área de Corporate Investment Banking', 'Os responsáveis pela área de corporate investment banking prestam aconselhamento estratégico sobre serviços financeiros a empresas e outras instituições. Asseguram que as normas jurídicas são seguidas pelos clientes nos seus esforços de mobilização de capital. Fornecem conhecimentos técnicos e informações sobre fusões e aquisições, obrigações e ações, privatizações e reorganização, mobilização de capital e subscrição de títulos, incluindo mercados de capitais próprios e de dívida.', 'released', NULL, '2412'),
  ('http://data.europa.eu/esco/occupation/245be6d1-fe9a-4ac8-9f81-122a687e4724', 'Operário Fabril', 'Os operadores fabris auxiliam os operadores de máquinas e os montadores de produtos. Limpam as máquinas e as áreas de trabalho. Os operadores fabris asseguram que os fornecimentos e os materiais são reaprovisionados.', 'released', '["Operário Fabril", "Operária Fabril", "Operária de Fábrica", "Operário de Fábrica"]'::jsonb, '9329'),
  ('http://data.europa.eu/esco/occupation/24677ef2-512c-4f4a-bc1c-14bf374e9f22', 'Engenheiro Especialista em Equipamentos Rotativos', 'Os engenheiros de equipamentos rotativos desenvolvem concepções e especificações para os equipamentos rotativos, em conformidade com as normas aplicáveis. Além disso, proporcionam conhecimentos técnicos e ajudam a garantir a conclusão de todas as instalações de equipamentos novos e existentes.', 'released', '["Engenheira Especialista em Equipamentos Rotativos", "Engenheiro Especialista em Equipamentos Rotativos"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/246dda29-70f6-408b-b205-aa17b2ffb168', 'Observador Eleitoral', 'Os observadores eleitorais são espetadores qualificados e formados das eleições numa democracia funcional, tendo como objetivo aumentar a transparência e a credibilidade das eleições observadas.', 'released', '["Observador Eleitoral de Longa Duração", "Observadora Eleitoral de Longa Duração", "Observadora Eleitoral de Curta Duração", "Observador Eleitoral de Curto Prazo", "Observadora Eleitoral de Curto Prazo", "Observadora Eleitoral", "Observadora Eleitoral de Curto Termo", "Observador Eleitoral de Curta Duração", "Observador Eleitoral de Curto Termo", "Observador Eleitoral"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/246e7d87-756e-4db2-97e8-11ef63b864f0', 'Instalador de Escadas', 'Os instaladores de escadas executam escadas padrão ou personalizadas entre os vários níveis dos edifícios. Efetuam as medições necessárias, preparam o local e instalam as escadas com segurança.', 'released', '["Montadora de Escadas", "Instalador de Escadas", "Instaladora de Escadas", "Montador de Escadas"]'::jsonb, '7115'),
  ('http://data.europa.eu/esco/occupation/2480f8b0-4c02-4c66-84ad-2677c1548e03', 'Condutor de Veículos de Recolha de Resíduos', 'Os condutores de veículos de recolha de resíduos conduzem veículos de grandes dimensões utilizados para a recolha de resíduos. Conduzem os veículos a partir de casas e instalações onde os resíduos são recolhidos pelos trabalhadores de recolha do lixo no caminhão e transportam os resíduos para as instalações de tratamento e eliminação de resíduos.', 'released', '["Condutor de Veículos de Recolha de Resíduos", "Condutora de Veículos de Recolha de Resíduos"]'::jsonb, '8332'),
  ('http://data.europa.eu/esco/occupation/24a170fc-be68-43a5-93f1-7a5c31c6062b', 'Montador de Equipamentos Médicos', 'Os montadores de equipamentos médicos fabricam instrumentos, máquinas e aparelhos que podem ser utilizados para prevenir, diagnosticar ou tratar doenças. Os equipamentos médicos podem ser não elétricos, tais como tubos, agulhas, estojos de drenagem e pipetas estéreis, bem como elétricos, tais como estimuladores cardíacos, máquinas de IRM e dispositivos de raios X. Alguns podem também trabalhar na produção de mobiliário médico, tais como camas de hospital e mesas de operações.', 'released', '["Montador de Equipamentos Médicos", "Montadora de Equipamentos Médicos"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/24af7ff6-bd84-43a6-8cba-e60776f956f5', 'Diretor de Distribuição de Produtos Farmacêuticos', 'Os diretores de distribuição produtos farmacêuticos planificam a distribuição de produtos farmacêuticos a vários pontos de venda.', 'released', '["Diretora de Distribuição Produtos Farmacêuticos", "Diretor de Logística Produtos Farmacêuticos", "Diretora de Logística Produtos Farmacêuticos", "Diretor de Distribuição Produtos Farmacêuticos", "Diretora de Distribuição de Produtos Farmacêuticos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/24d378d8-1e16-4667-bdb4-1f4a0f2c6379', 'Mecânico de Motores Diesel', 'Os mecânicos de motores a diesel procedem à reparação e manutenção de todos os tipos de motores diesel. Utilizam ferramentas manuais, instrumentos de medição de precisão e máquinas-ferramentas para diagnosticar problemas, desmontar motores e examinar e trocar peças com defeito e desgaste excessivo.', 'released', '["Mecânica de Motores Diesel", "Mecânico de Motores Diesel"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/24d39e12-e104-49d3-8224-8b7a5f9b99d1', 'Diretor de Biblioteca', 'Os diretores de biblioteca supervisionam a utilização correta do equipamento e dos objetos da biblioteca. Gerem os serviços prestados pela biblioteca e o seu funcionamento. Os gestores de biblioteca proporcionam também formação aos novos membros do pessoal e gerem o orçamento da biblioteca.', 'released', '["Diretora de Biblioteca", "Diretor de Biblioteca"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/24e9f120-eae8-411a-8daf-c48e8ae2f5f6', 'Operador Manual de Artigos de Marroquinaria', 'Os operadores manuais de artigos de marroquinaria usam ferramentas para preparar a união das peças a fim de preparar as peças para serem cosidas ou para terminar as peças já existentes cosidas juntas para dar forma aos artigos de marroquinaria.', 'released', '["Operador Manual de Artigos de Marroquinaria", "Operadora Manual de Artigos de Marroquinaria"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/24f1eb3a-e99c-4c38-9bda-ba2ba6bf9fa4', 'Enfermeiro Veterinário', 'Os enfermeiros veterinários prestam assistência a animais sujeitos a tratamentos veterinários e aconselhamento aos clientes da clínica veterinária relacionado com promoção da saúde animal e prevenção de doenças, em conformidade com a legislação nacional.', 'released', '["Enfermeiro de Cuidados Veterinários", "Enfermeira de Cuidados Veterinários", "Enfermeira Veterinária", "Enfermeiro Veterinário", "Enfermeira Veterinário"]'::jsonb, '3240'),
  ('http://data.europa.eu/esco/occupation/250d6493-68ab-4d69-ba67-c10293a20f49', 'Técnico Especializado em Fotônica', 'Os técnicos especializados em fotónica colaboram com os engenheiros no desenvolvimento de sistemas ou componentes fotónicos, geralmente sob a forma de equipamento ótico, como os lasers, as lentes e o equipamento de fibra ótica. Os técnicos de fotónica constroem, testam, instalam e calibram equipamentos óticos. Efetuam a leitura de planos e outros desenhos técnicos para desenvolverem os procedimentos de ensaio e calibração.', 'released', '["Técnico Especializada em Fotónica", "Técnica Especializada em Fotónica", "Técnica Especializado em Fotônica"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/2515bd46-ccd4-4561-97d1-b9544608a76e', 'Projetista de Equipamento Elétrico', 'Os projetistas de equipamento elétrico prestam apoio aos engenheiros na concepção e conceptualização de equipamento elétrico. Elaboram, com o apoio de software especializado, as especificações de um número variado de sistemas elétricos, como transformadores de tensão e centrais elétricas, ou do fornecimento de energia em edifícios.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/25206eaa-04da-4fd6-bac7-173d7eb142dc', 'Operador de Máquinas de Fundição de Metais', 'Os operadores de máquinas de fundição de metais utilizam máquinas de fundição para enformar substâncias metálicas. Instalam e asseguram o correto funcionamento de máquinas de fundição para transformar metais ferrosos e não ferrosos fundidos no fabrico de materiais metálicos. Conduzem o fluxo de metais fundidos para moldes, tendo o cuidado de criar as condições exatas adequadas para obter o metal da qualidade mais elevada. Observam o fluxo de metal para identificar falhas. Em caso de falha, notificam o pessoal autorizado e participam na eliminação da falha.', 'released', '["Operador de Máquinas de Fundição de Metais", "Operadora de Máquinas de Fundição de Metais"]'::jsonb, '8121'),
  ('http://data.europa.eu/esco/occupation/2555a1bc-9f30-4371-9499-64793e48cd55', 'Técnico de Testes com Placas de Circuito Impresso', 'Os técnicos de testes com placas de circuito impresso inspecionam e testam placas de circuito impresso. Executam uma série de procedimentos de ensaio de placas de circuito impresso e podem efetuar pequenas reparações.', 'released', '["Técnica de Testes com Placas de Circuito Impresso", "Técnico de Testes com Placas de Circuito Impresso"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/2561879a-dd0a-454e-ae6e-9be6c488eb56', 'Topógrafo', 'Os topógrafos concebem e criam mapas e projetos, convertendo os novos resultados de medição no cadastro imobiliário de uma comunidade. Definem e indicam os limites das propriedades e a utilização dos solos, e criam mapas das cidade e dos distritos utilizando equipamento de medição e software especializado.', 'released', '["Agrimensora", "Cartógrafo", "Topógrafa", "Agrimensor", "Topógrafo", "Cartógrafa"]'::jsonb, '2165'),
  ('http://data.europa.eu/esco/occupation/25829508-63f3-41c3-affc-ddbb5c077930', 'Fisiologista', 'Os fisiologistas estudam e realizam investigação sobre o funcionamento dos diferentes organismos vivos, as partes que os compõem e as suas interações. Compreendem a forma como os sistemas vivos reagem a fatores como as doenças, a atividade física e o stress, e utilizam essas informações para desenvolver métodos e soluções para eliminar o efeito desses estímulos nos organismos vivos.', 'released', '["Fisióloga", "Fisiólogo", "Anatomista"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/258e46f9-0075-4a2e-adae-1ff0477e0f30', 'Cientista de Dados', 'Os cientistas de dados pesquisam e interpretam fontes de dados enriquecidos, gerem grandes quantidades de dados, procedem à fusão de fontes de dados, asseguram a consistência dos conjuntos de dados e criam visualizações para ajudar na compreensão dos dados. Constroem modelos matemáticos utilizando os dados, apresentam e comunicam informações e conclusões relativas aos dados aos especialistas e cientistas da sua equipe e, se necessário, a um público não especializado, e recomendam formas de aplicar os dados.', 'released', '["Investigadora de Dados", "Cientista de Investigação de Dados", "Cientista de Dados", "Investigador de Dados"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/259d9967-2189-4b98-be32-9d3169b02e1b', 'Instrutor de Condução de Motociclos', 'Os instrutores de condução de motociclos ensinam às pessoas a teoria e a prática de conduzir um motociclo em segurança e em conformidade com os regulamentos. Ajudam os alunos a desenvolver as competências necessárias para a condução e preparam-nos para o exame teórico e o exame prático.', 'released', '["Instrutor de Condução de Motociclos", "Instrutora de Condução de Motociclos"]'::jsonb, '5165'),
  ('http://data.europa.eu/esco/occupation/25eca7d1-e8ea-4f9d-b922-c532d971e17c', 'Operador de Instalação de Digestão Anaeróbia', 'Os operadores de instalações de digestão anaeróbia supervisionam e asseguram a manutenção do processo de decomposição de matéria orgânica, como os resíduos alimentares, na ausência de oxigénio, para produzir biogás. Acompanham o desempenho e são responsáveis pela resolução de problemas que possam surgir durante o processo, realizando inspeções regulares.', 'released', '["Operador de Instalação de Digestão Anaeróbia", "Operadora de Instalações de Digestão Anaeróbia", "Operadora de Instalação de Digestão Anaeróbia"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/25f45b01-550c-4d17-b69e-7c5ba57c4218', 'Moldador de Artigos em Fibra de Vidro', 'O moldador de artigos em fibra de vidro molda os materiais de fibra de vidro para formar cascos e o convés das embarcações. Interpretam os esquemas e utilizam ferramentas manuais e elétricas para cortar os materiais compósitos. Aplicam ceras e lacas e preparam superfícies para a colocação de revestimentos a fibra de vidro. Utilizam fibra de vidro saturada de resina para unir bandas de reforço de madeira às estruturas de cabina e ao convés. Também preparam materiais expondo-os à temperatura certa. Verificam os produtos acabados para detectar eventuais defeitos e garantem a sua conformidade com as especificações.', 'released', '["Moldadora de Artigos em Fibra de Vidro", "Operador de Máquina de Pulverização de Fibras de Vidro", "Técnico de Fibras de Vidro", "Operadora de Máquina de Pulverização de Fibras de Vidro", "Técnica de Fibras de Vidro", "Moldador de Artigos em Fibra de Vidro"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/26087cc4-6226-41b0-9f97-9564ebe90dce', 'Bengaleiro', 'Os bengaleiros asseguram que os casacos e sacos dos clientes sejam depositados com segurança no interior do bengaleiro. Interagem com os clientes para receber os seus artigos, entregam bilhetes para os artigos correspondentes e devolvem-nos aos respetivos proprietários. Podem auxiliar com pedidos e queixas.', 'released', '["Guarda de Bengaleiro", "Guarda de Vestiário", "Bengaleiro", "Bengaleira"]'::jsonb, '9629'),
  ('http://data.europa.eu/esco/occupation/260b01cc-7dd6-4584-8863-cae5426819c6', 'Responsável da Logística dos Navios', 'Os responsáveis da logística dos navios gerem o desempenho de um navio. Asseguram a segurança do navio e da sua carga, a sua operacionalidade e ligam os navios disponíveis às cargas disponíveis a fim de maximizar a rendibilidade das viagens. Asseguram que cada navio porta-contentores seja carregado de modo a atingir a sua capacidade máxima, reduzindo ao mínimo os tempos de atracagem e os custos de manuseamento. Também planeiam a manutenção e a revisão do navio, bem como a tripulação necessária.', 'released', NULL, '4323'),
  ('http://data.europa.eu/esco/occupation/26105840-8abb-4f91-a888-1211cb798b0b', 'Guia de Parque', 'Os guias de parque ajudam os visitantes, interpretam o património cultural e natural e fornecem informação e orientação aos turistas em parques, tais como de vida selvagem, parques de diversões e parques naturais.', 'released', NULL, '5113'),
  ('http://data.europa.eu/esco/occupation/26171f39-e85a-448f-bd28-a73a5a99927f', 'Ator', 'Os atores desempenham papéis em espetáculos de palco ao vivo, produções de televisão, de rádio, de vídeo e de cinema, ou noutro tipo de cenários para fins de entretenimento ou instrução. Utilizam a linguagem corporal (gestos e dança) e a voz (fala e canto) para apresentarem o personagem ou a história de acordo com o guião, seguindo as orientações de um diretor.', 'released', '["Atriz", "Ator", "Atora"]'::jsonb, '2655'),
  ('http://data.europa.eu/esco/occupation/262d4e45-0cf7-4399-be6f-3d5e96826ef2', 'Gestor do Departamento de Molho Caleiro', 'Os gestores do departamento de molho caleiro planificam e organizam o trabalho, o pessoal e o equipamento do serviço que envolve a lavagem das peles em bruto. Removem os elementos indesejáveis, pesam-nas e preparam-nas para a curtimenta. Coordenam o fornecimento de produtos químicos e de matérias-primas. São responsáveis pela elaboração de fórmulas de fabrico e pela monitorização da qualidade.', 'released', '["Gestor do Departamento de Molho Caleiro", "Gestora do Departamento de Molho Caleiro", "Gerente"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/262f21a3-ae78-46f4-a5f9-5a1f502caa90', 'Oficial da Marinha', 'Os oficiais da Marinha comandam missões durante os períodos de conflito e de paz, e supervisionam a formação e o desenvolvimento das suas equipes. Supervisionam as operações da sua equipe, bem como as missões de ajuda, e realizam missões de patrulha para assegurar a manutenção da paz. Frequentemente, colaboram regularmente com o departamento de RH dos HQCS para o melhor planejamento das necessidades futuras.', 'released', '["Oficial Fuzileiro", "Oficial Médico Naval", "Oficial Fuzileira", "Oficial das Forças Armadas", "Oficial Técnico Naval", "Guarda-Marinha"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/264b00c9-84d0-4dc9-b590-aed2cea2b904', 'Chefe de Oficina de Mecânica Automóvel', 'Os chefes de oficina de mecânica automóvel assumem a responsabilidade pela operação corrente de uma oficina de automóveis.', 'released', '["Chefea de Oficina de Mecânica Automóvel"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/264e1a4a-5074-47e2-a6d9-d225d48e8a9a', 'Corretor de Apostas', 'Os corretores de apostas aceitam apostas sobre jogos desportivos e outros eventos de acordo com as probabilidades, calculam as probabilidades e pagam os prémios. São responsáveis pela gestão dos riscos.', 'released', '["Corretor de Apostas", "Corretora de Apostas"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/2662ed6c-a705-4895-8e9d-0a85c08ad908', 'Treinador de Cães', 'Os treinadores de cães treinam os animais e/ou as pessoas que trabalham com cães para fins gerais e específicos, incluindo assistência, segurança, lazer, competição, transporte, obediência e lida diária, entretenimento e educação, em conformidade com a legislação nacional.', 'released', '["Treinadora de Cães", "Treinador de Cães"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/26852256-d423-41bb-8178-4d37ff2528b9', 'Fabricante de Massas Alimentícias', 'Os fabricantes de massas alimentícias preparam massas frescas, recheios e outros tipos de massas, de acordo com receitas e processos específicos.', 'released', '["Fabricante de Massas Alimentícias", "Preparador de Massas Alimentícias", "Preparadora de Massas Alimentícias", "Fabricantea de Massas Alimentícias"]'::jsonb, '7512'),
  ('http://data.europa.eu/esco/occupation/268565be-d94f-4983-a33f-2b7dabc61f24', 'Vendedor de Produtos de Confeitaria', 'Os vendedores de produtos de confeitaria vendem produtos de confeitaria em lojas especializadas.', 'released', '["Vendedor de Produtos de Confeitaria", "Vendedora de Produtos de Confeitaria"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/269c47e7-9017-4aa6-bce8-49e89a696a64', 'Mecânico de Maquinaria Industrial', 'Os mecânicos de maquinaria industrial trabalham com máquinas e equipamentos novos. Procedem à instalação para a aplicação específica e criam acessórios, se necessário, efetuam a manutenção e a reparação, bem como diagnósticos para detectar falhas nos sistemas ou nas peças que devem ser substituídas.', 'released', '["Mecânico Industrial", "Mecânico de Maquinaria Industrial", "Mecânica de Maquinaria Industrial", "Mecânica Industrial"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/26a86453-4236-49a3-ae3a-313c1cacb5ff', 'Aparelhador de Barcos', 'Os aparelhadores de barcos utilizam ferramentas manuais e elétricas para instalar motores, calibres, comandos e acessórios, tais como baterias, luzes, depósitos de combustível e interruptores de ignição. Também realizam inspeções prévias à entrega.', 'released', '["Aparelhadora de Barcos", "Aparelhador de Barcos"]'::jsonb, '7215'),
  ('http://data.europa.eu/esco/occupation/26ca1895-2047-4c76-a678-831c85824f61', 'Responsável Pela Verificação de Fatos', 'Os responsáveis pela verificação de fatos asseguram a exatidão de todas as informações contidas nos textos prontos para publicação. Investigam os fatos de forma rigorosa e corrigem os erros.', 'released', NULL, '2642'),
  ('http://data.europa.eu/esco/occupation/26ce22fe-4018-4387-8e6b-c2555f5fc0ac', 'Editor de Jornais', 'Os editores de jornais decidem sobre as histórias com interesse suficiente para serem publicadas no jornal. Nomeiam jornalistas para cada tema tratado. Os editores de jornais determinam a extensão de cada artigo noticioso e a parte do jornal onde irá figurar. Além disso, asseguram a conclusão atempada das publicações para edição.', 'released', '["Editor de Jornais", "Editora de Jornais"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/26e1add0-da3f-4ed6-aa91-791cb550146f', 'Técnico de Microssistemas', 'Os técnicos de microssistemas colaboram com os engenheiros de microssistemas no desenvolvimento de dispositivos de microssistemas ou de sistemas microeletromecânicos (MEMS), os quais podem ser integrados em produtos mecânicos, óticos, acústicos e eletrônicos. Os técnicos de microssistemas são responsáveis pela construção, pelo ensaio e pela manutenção de microssistemas.', 'released', '["Técnico de Microsistemas", "Técnica de Microsistemas", "Técnica de Microssistemas"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/270528cf-2bf9-463d-aeaa-d169b1f767c1', 'Marinheiro Pescador', 'Os marinheiros pescadores apenas operam pequenos barcos de pesca costeira. Organizam, gerem e executam atividades de transporte marítimo no convés e com motores. Os marinheiros pescadores capturam e conservam o peixe ou realizam operações de aquicultura. Respeitam as condições de segurança e respeitam a regulamentação nacional e internacional.', 'released', '["Marinheira Pescadora", "Marinheiro Pescador", "Marinheira Pescador"]'::jsonb, '6222'),
  ('http://data.europa.eu/esco/occupation/276a4ff1-a67c-4677-9f20-dc85f1060e1b', 'Analista de Middle Office', 'Os analistas de middle office trabalham na tesouraria de uma instituição financeira, assegurando a conformidade com as políticas da empresa e a legislação, fornecendo investigações e análises sobre assuntos financeiros, avaliando o risco e prestando apoio às operações dos serviços de front office.', 'released', NULL, '2413'),
  ('http://data.europa.eu/esco/occupation/276ba420-ef09-4a0e-b215-2c2e2f80ad28', 'Diretor de Segurança Informática', 'Os diretores de segurança informática protegem do acesso não autorizado as informações sobre empresas e sobre trabalhadores. Definem também a política de segurança do sistema de informação, gerem a implementação da segurança em todos os sistemas de informação e asseguram a disponibilidade das informações.', 'released', '["Diretor de Segurança Informática", "Diretora de Segurança Informática", "Responsável Pela Segurança das Tecnologias de Informação e Comunicação", "Principal Responsável Pela Segurança Informática", "Responsável Pela Segurança da Tecnologia da Informação"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/27811419-407f-4868-a388-2f7df7aafd91', 'Técnico de Engenharia Eletrônica', 'Os técnicos de engenharia eletrônica trabalham em estreita colaboração com os engenheiros eletrônicos no desenvolvimento de equipamentos e dispositivos eletrônicos. Os técnicos de engenharia eletrônica são responsáveis pela construção, pelo ensaio e pela manutenção de dispositivos eletrônicos.', 'released', '["Técnica de Engenharia Eletrônica", "Técnico de Engenharia Eletrônica"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/279c0ab1-212b-4e89-a41f-048f5de9dadf', 'Coordenador de Logística Ferroviária', 'Os coordenadores de logística ferroviária gerem as remessas ferroviárias, incluindo ou excluindo outros modos de transporte. Coordenam a afetação atempada dos meios e equipamentos de transporte e asseguram uma entrega atempada. Procedem ao planejamento e à manutenção de cadeias de abastecimento eficientes para os clientes e os expedidores.', 'released', '["Coordenadora de Logístiva Ferroviária", "Coordenador de Logístiva Ferroviária", "Coordenadora de Logística Ferroviária"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/27a88c48-1d09-4a8c-a82a-a61ea16476d9', 'Piloto de Drones', 'Os pilotos de drones operam, à distância, veículos aéreos não tripulados (UAV). Conduzem o drone e ativam outros equipamentos, tais como câmaras e sensores LIDAR, para calcular distâncias, ou outros instrumentos.;', 'released', '["Operador de Sistemas de Aeronaves não Tripuladas", "Piloto de Veículos Aéreos não Tripulados (UAVs)", "Pilota de Aeronave Pilotada Remotamente (RPA)", "Piloto de Aeronave Pilotada Remotamente (RPA)", "Operador de Drone Civil", "Piloto de Aeronave não Tripulado", "Pilota de Veículos Aéreos não Tripulados (UAVs)", "Operadora de Drone Civil", "Operadora de Sistemas de Aeronaves não Tripuladas", "Operadora de Drone", "Operadora de Veículo Aéreo não Tripulado", "Operador de Veículo Aéreo não Tripulado", "Operador de Drone", "Pilota de Aeronave não Tripulado", "Pilota de Drones"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/27c5097e-a2a3-4b2e-82a6-3b874ebfb092', 'Inspetor de Navios de Carga', 'Os inspetores de navios de carga investigam todas as bagagens e mercadorias indicadas no manifesto do navio. São responsáveis pela verificação do estado da carga e pela verificação da documentação e do cumprimento das regras e regulamentos. Os inspetores de carga marinha analisam as capacidades dos navios, os compartimentos de combustível, o equipamento de segurança e as licenças específicas exigidas.', 'released', '["Inspetor de Navios de Carga", "Inspetora de Navios de Carga"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/27e16eef-c7a6-4577-bc3f-727d01ec1958', 'Professor de História do Ensino Secundário', 'Os professores de História do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a História. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da História através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de História do Ensino Secundário", "Professor de História do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/27eb624c-6171-4c71-aa71-bb21e83381d4', 'Engenheiro Metalúrgico e de Materiais', 'Os engenheiros metalúrgicos e de materiais estão envolvidos na extração de metais utilizáveis a partir de minérios e de material reciclável. Estudam as propriedades do metal, como a corrosão e a fadiga.', 'released', '["Engenheiro Metalúrgico Especialista em Processos Químicos", "Engenheira Metalúrgica e de Materiais", "Engenheira Metalúrgica Especialista em Processos Químicos", "Engenheiro Metalúrgico e de Materiais", "Engenheira Metalúrgico e de Materiais"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/27f92adf-1384-4c01-8ad0-1680ead6abf9', 'Operador de Guilhotinas de Papel', 'Os operadores de guilhotinas de papel operam uma máquina que corta papel com o tamanho e a forma pretendidos. Os operadores de guilhotinas de papel podem também cortar e perfurar outras matérias que se apresentem em folhas, tais como folhas de metal.', 'released', '["Operador de Guilhotinas de Papel", "Operadora de Guilhotinas de Papel"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/2800e788-57b4-49f7-9c00-6c35e12cfb8e', 'Artista de Marionetas', 'Os artistas de marionetas realizam espetáculos de manipulação de marionetas, como fantoches ou marionetas. A exibição baseia-se num guião e os movimentos das marionetas têm de estar sincronizados com o discurso e a música. Os artistas de marionetas podem escrever os seus próprios guiões e conceber e criar as suas próprias marionetas.', 'released', NULL, '2659'),
  ('http://data.europa.eu/esco/occupation/2808c7ec-cdb1-4b48-8429-e160a418ed0c', 'Especialista em Política de Desenvolvimento Regional', 'Os especialistas em política de desenvolvimento regional investigam, analisam e desenvolvem políticas de desenvolvimento regional. Aplicam políticas que visam reduzir as disparidades regionais através da promoção de atividades econômicas numa região e de mudanças estruturais, como o apoio à governação a vários níveis, ao desenvolvimento rural e à melhoria das infraestruturas. Trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/28742973-c452-4996-b070-440e437306dc', 'Analista da Qualidade da Água', 'Os analistas da qualidade da água salvaguardam a qualidade da água através de análises científicas, assegurando a observância das normas de qualidade e segurança. Recolhem amostras da água, realizam testes laboratoriais e desenvolvem processos de depuração para que a água possa ser utilizada para consumo, para irrigação e para outros fins de abastecimento de água.', 'released', '["Analista da Qualidade da Água Potável"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/289c7385-2342-4a4e-b0b1-7b2e977aea79', 'Técnico de Terapias Alternativas para Animais', 'Os técnicos de terapias alternativas para animais examinam animais de pequeno e de grande porte doentes ou feridos e ministram um tratamento alternativo. Podem recorrer à homeopatia ou à acupuntura e a outras medicinas ou métodos alternativos para tratar o animal. Os técnicos de terapias alternativas para animais também prestam aconselhamento sobre tratamentos que reforçam os poderes de autocura dos animais.', 'released', '["Técnica de Terapias Alternativas para Animais", "Técnico de Terapias Alternativas para Animais"]'::jsonb, '3240'),
  ('http://data.europa.eu/esco/occupation/28b25dbf-1eab-45e8-9d02-7a5eea9bb139', 'Fabricante de Artigos Têxteis para o Lar', 'Os fabricantes de artigos têxteis para o lar criam artigos confecionados de qualquer material têxtil, exceto vestuário. Fabricam produtos como os têxteis para o lar (por exemplo, roupa de cama, almofadas, pufes, tapetes) e confecionam artigos têxteis para utilização no exterior.', 'released', '["Fabricantea de Artigos Têxteis para o Lar"]'::jsonb, '7533'),
  ('http://data.europa.eu/esco/occupation/28d82e8d-7379-4245-a5a0-c5a68864a528', 'Operador de Centrífuga', 'Os operadores de centrífuga asseguram o correto funcionamento de máquinas centrífugas que separam as impurezas das matérias alimentares para a transformação em gêneros alimentícios acabados.', 'released', '["Operadora de Centrifugadora", "Operador de Centrifugadora", "Operadora de Centrífuga", "Operador de Centrífuga"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/28dbd459-d634-484a-92d7-e6f8dc1ec532', 'Técnico de Trançado Têxtil', 'Os técnicos de trançado têxtil realizam operações relacionadas com a criação do processo de trançado.', 'released', '["Técnico de Trançado Têxtil", "Técnica de Trançado Têxtil", "Técnico de Entrançadura Têxtil", "Técnica de Entrançadura Têxtil"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/291da1ab-1f90-426d-bbc5-60d0fa7d608b', 'Consultor de Viagens', 'Os consultores de viagens fornecem informações personalizadas e consulta sobre as ofertas de viagens, efetuam reservas e vendem serviços de viagens juntamente com outros serviços conexos.', 'released', '["Consultora de Viagens de Negócios", "Consultora de Viagens", "Consultor de Viagens de Negócios", "Consultor de Viagens de Lazer", "Consultor de Viagens", "Consultora de Viagens de Lazer"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/295dbed9-0330-42af-8650-f9296c6eb195', 'Piloto de Teste', 'Os pilotos de teste conduzem protótipos e veículos de pré-produção e avaliam o seu desempenho, a sua segurança e o seu conforto. Testam os modelos em diferentes situações de condução e elaboram relatórios para ajudar os engenheiros a melhorar a sua concepção e a identificar problemas. Podem trabalhar para os fabricantes, organizações independentes de ensaios de veículos ou revistas para automóveis.', 'released', '["Pilota de Teste", "Piloto de Teste"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/2960c96e-7228-4327-b0a1-85fc13691844', 'Meteorologista Aeronáutico', 'Os meteorologistas aeronáuticos preveem as condições meteorológicas nos aeroportos. Fornecem, diariamente e hora a hora, observações, análises, previsões, alertas e aconselhamento aos pilotos, operadores aeroportuários e companhias aéreas em questões meteorológicas. Comunicam as condições meteorológicas previstas nos aeroportos, as condições atuais e as previsões em rota.', 'released', '["Meteorologista Aeronáutica", "Meteorologista Aeronáutico", "Inspetora de Meteorologia Aeronáutica", "Inspetor de Meteorologia Aeronáutica"]'::jsonb, '2112'),
  ('http://data.europa.eu/esco/occupation/29900d8d-4463-4a6e-b6aa-e97418700245', 'Modelista de Vestuário de cabedal-CAD', 'Os modelistas de vestuário de cabedal-CAD concebem, ajustam e modificam moldes 2D utilizando sistemas CAD. Verificam as variantes de posicionamento utilizando módulos de encaixe do sistema CAD. Estimam o consumo de materiais.', 'released', NULL, '7532'),
  ('http://data.europa.eu/esco/occupation/29a36f21-da45-4a01-b015-cac4445e5025', 'Operador de Corte de Flocos de Sabão', 'Os operadores de corte de flocos de sabão operam as máquinas que transformam as barras de sabão em flocos de sabão, certificando-se de que o produto final esteja em conformidade com as especificações. Também lidam com a transferência e a armazenagem dos flocos de sabão.', 'released', '["Operador de Corte de Flocos de Sabão", "Operadora de Corte de Flocos de Sabão"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/29a95106-3680-427b-bd1c-3f13d6999241', 'Diretor de Distribuição de Animais Vivos', 'Os diretores de distribuição de animais vivos planificam a distribuição de animais vivos a vários pontos de venda.', 'released', '["Diretora de Logística — Animais Vivos", "Diretor de Logística — Animais Vivos", "Diretor de Distrbuição de Animais Vivos", "Diretora de Distrbuição — Animais Vivos", "Diretora de Distribuição de Animais Vivos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/29df0797-c66d-4e54-a5e1-45b18cecf052', 'Instrutor de Patinagem no Gelo', 'Os instrutores de patinagem no gelo ensinam e treinam indivíduos ou grupos de patinagem no gelo e desportos relacionados, tais como a patinagem artística e a patinagem de velocidade. Ensinam aos clientes conhecimentos teóricos e a aptidão, resistência e coordenação físicas. Os instrutores de patinagem no gelo preparam e realizam sessões de treino. Apoiam os seus clientes se estes participarem em competições.', 'released', '["Instrutor de Patinagem no Gelo", "Instrutora de Patinagem no Gelo"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/29e8a27f-5e68-4d47-b991-5c41f835c72a', 'Engenheiro de Inovação', 'Os engenheiros de inovação participam na planificação, organização e execução de projetos de produtos inovadores. Concebem e desenvolvem novos produtos e protótipos utilizando tecnologias e processos de otimização e automatização que impulsionam o crescimento inovador no seio de uma organização. Os engenheiros de inovação identificam potenciais áreas de desenvolvimento, oportunidades de patentes, tendências de inovação e as necessidades dos clientes.', 'released', '["Engenheiro de Inovação", "Engenheira de Inovação"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/29fa406d-de89-4515-be8d-0fe7bda993f1', 'Comprador', 'Os compradores selecionam e compram matérias-primas, materiais, serviços ou produtos. Organizam propostas e selecionam os fornecedores.', 'released', '["Compradora", "Comprador"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/2a04a1df-a3b9-403e-a245-e7f93fdddd44', 'Assistente Executivo', 'Os assistentes executivos são profissionais administrativos avançados que trabalham com executivos de alto nível ou em instalações internacionais de várias indústrias. Organizam reuniões, organizam e mantêm dossiês, organizam viagens, formam os membros do pessoal, comunicam noutras línguas e gerem o funcionamento quotidiano do serviço.', 'released', '["Assistente Executiva", "Assistente Executivo", "Assistentea Executivo"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/2a1190f0-14d5-4ce4-ade0-ef726a1887a0', 'Pastor', 'Os pastores gerem o bem-estar e a circulação dos animais, em especial ovinos, caprinos e outros animais de pastoreio, em diversos ambientes.', 'released', '["Pastora", "Guardador de Gado", "Pastor", "Guardadora de Gado"]'::jsonb, '6121'),
  ('http://data.europa.eu/esco/occupation/2a226be5-6157-49e9-bd4b-e3b46d55c082', 'Supervisor de Infraestruturas Ferroviárias', 'Os supervisores de infraestruturas ferroviárias acompanham a construção e a manutenção das infraestruturas ferroviárias. Atribuem tarefas, quer no terreno, quer a partir de uma sala de controlo, e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Infraestruturas Ferroviárias", "Supervisora de Infra-Estruturas Ferroviárias", "Supervisora de Infraestruturas Ferroviárias"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/2a22ff9e-de3b-408d-b312-5034896cc4f4', 'Carpinteiro', 'Os carpinteiros cortam, moldam e montam elementos em madeira para a construção de edifícios e outras estruturas. Também utilizam materiais como o plástico e o metal nas suas criações. Os carpinteiros criam as estruturas de madeira para apoiar edifícios com estrutura em madeira.', 'released', '["Carpinteiro de Toscos", "Carpinteira de Cofragens", "Carpinteira", "Carpinteiro de Limpos", "Carpinteiro de Cofragens", "Marceneiro", "Carpinteiro", "Marceneira", "Carpinteira de Limpos", "Carpinteira de Toscos"]'::jsonb, '7115'),
  ('http://data.europa.eu/esco/occupation/2a2da883-8af5-4b98-832e-00e6681b22c3', 'Operador de Refrigeração de Alimentos', 'Os operadores de refrigeração de alimentos efetuam vários processos e asseguram o correto funcionamento de máquinas específicas para fabricar refeições e pratos preparados. Aplicam métodos de refrigeração, selagem e congelação aos gêneros alimentícios de consumo não imediato.', 'released', '["Operadora de Refrigeração de Alimentos", "Operador de Refrigeração de Alimentos"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/2a6784d7-c457-413d-ba99-e320de11fc98', 'Figurinista', 'Os figurinistas ajudam e apoiam os artistas antes, durante e após o espetáculo, de modo a garantir que o guarda-roupa dos artistas está de acordo com a visão artística do diretor e da equipe artística. Asseguram a qualidade, a manutenção, o controlo e a reparação do guarda-roupa, bem como as mudanças rápidas de guarda-roupa. ; ; ;', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/2a7d4b37-e831-4e20-827c-0682fe7e370e', 'Operador de Bombas de Oleoduto', 'Os operadores de bombas de oleoduto asseguram o correto funcionamento de equipamentos e sistemas de bombas para transferir líquidos e substâncias (por exemplo, soluções químicas, petróleo bruto, gases e outros) de um ponto para outro. Utilizam mangueiras, bombas e outros equipamentos de acordo com o produto a transferir. Asseguram a boa circulação e o fluxo das mercadorias nos gasodutos.', 'released', '["Operadora de Bombas de Oleoduto", "Operador de Bombas de Oleoduto"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/2a8d6b4c-661d-4620-8f68-2c99e78f512e', 'Fabricante de Moldes de Fundição', 'Os fabricantes de moldes de fundição criam modelos de metal, de madeira ou de plástico do produto acabado a utilizar. Os padrões são então utilizados para criar moldes, conduzindo eventualmente ao vazamento do produto da mesma forma que o padrão.', 'released', '["Fabricantea de Moldes de Fundição"]'::jsonb, '7222'),
  ('http://data.europa.eu/esco/occupation/2a914d26-42aa-46b5-acf3-097d51ba4617', 'Engenheiro de Construção de Edifícios', 'Os engenheiros de construção de edifícios interpretam projetos de construção e atribuem especificações técnicas a projetos de construção. Integram princípios de engenharia nos desenhos, a fim de garantir que as estruturas são seguras e resistentes. Trabalham em conjunto com arquitetos e engenheiros para transformar ideias de concepção em planos executáveis.', 'released', '["Engenheiro de Construção de Edifícios", "Engenheira de Construção de Edifícios"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/2aa7fbbb-f06e-4454-8ff8-2d799e86ba51', 'Técnico de Maquinaria Têxtil', 'Os técnicos de maquinaria têxtil procedem à instalação, manutenção, inspeção e reparação de máquinas e aparelhos mecânicos e controlados por computador utilizados na indústria têxtil, tais como as máquinas de tecelagem, de tingimento e de acabamento. ;', 'released', '["Técnico de Maquinaria Têxtil", "Técnica de Maquinaria Têxtil"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/2aae7736-f58b-4027-8de4-6884281c3b0b', 'Operador de Produtos Explosivos', 'Os operadores de produtos explosivos detonam explosivos de forma segura num local, a fim de explodir e despedaçar material no local.', 'released', '["Operadora de Produtos Explosivos", "Operador de Produtos Explosivos"]'::jsonb, '7542'),
  ('http://data.europa.eu/esco/occupation/2ac509e8-2850-42c3-b11d-d24077a7921b', 'Projetista de Engenharia Naval', 'Os projetistas de engenharia naval convertem os desenhos de engenheiros navais em desenhos técnicos, utilizando geralmente software. Os seus desenhos pormenorizam as dimensões, os métodos de fixação e montagem e outras especificações utilizados no fabrico todos os tipos de embarcações, desde embarcações de recreio a embarcações navais, incluindo submarinos.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/2ad52381-6adb-4262-b17c-ea7fcb3b6696', 'Diretor de Distribuição — Peixe e Marisco', 'Os diretores de distribuição — peixe e marisco planificam a distribuição de peixe e marisco a vários pontos de venda.', 'released', '["Diretor de Logística — Peixe e Marisco", "Diretora de Distribuição — Peixe e Marisco", "Diretora de Logística — Peixe e Marisco", "Diretor de Distribuição — Peixe e Marisco"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/2ada3e89-9159-49e7-88f7-4dd435fd95ac', 'Técnico Reparador de Instrumentos Óticos', 'Os técnicos reparadores de instrumentos óticos reparam instrumentos óticos, tais como microscópios, telescópios, câmaras óticas e bússolas. Testam os instrumentos para assegurar o seu correto funcionamento. Num contexto militar, também interpretam esquemas para poder reparar os instrumentos.', 'released', '["Técnica Reparadora de Instrumentos Óticos", "Técnico Reparador de Instrumentos Óticos", "Técnica Reparador de Instrumentos Óticos"]'::jsonb, '7311'),
  ('http://data.europa.eu/esco/occupation/2ae275fe-4f11-4a38-9e95-d466d74b42a3', 'Comandante de Polícia', 'Os comandantes de polícia supervisionam todo um departamento de polícia, acompanhando e regulando as atividades administrativas e operacionais de um serviço de polícia, bem como desenvolvendo políticas e métodos processuais. São responsáveis pela cooperação entre as várias divisões do departamento e pela supervisão do desempenho dos trabalhadores.', 'released', '["Subcomissário", "Comissário-Adjunto", "Mulher-Polícia", "Subcomissária", "Comissária-Adjunta", "Comissário", "Comissária", "Agente de Polícia", "Agente", "Superintendente", "Comandantea de Polícia"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/2ae76ccc-f02e-4eb6-b693-fff70ba8f409', 'Técnico de Intervenção Precoce de Apoio à Infância', 'Os técnicos de intervenção precoce de apoio à infância prestam uma intervenção e apoio precoces às crianças e às suas famílias, a fim de melhorar o seu funcionamento social e psicológico. Visam maximizar o bem-estar familiar e proteger as crianças de abusos e negligência. Defendem as crianças para que os seus direitos sejam respeitados dentro e fora da família. Podem ajudar as famílias monoparentais ou encontrar casas de acolhimento para crianças abandonadas ou abusadas.', 'released', '["Técnico de Intervenção Precoce de Apoio à Infância", "Técnica de Intervenção Precoce de Apoio à Infância"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/2af80b12-a73a-4cc2-8af1-d26a1e60738d', 'Corretor de Commodities', 'Os corretores de commodities (mercadorias) atuam como intermediários entre compradores e vendedores de bens móveis e imóveis, como matérias-primas, animais ou bens imóveis. Negoceiam os preços e recebem uma comissão das transações. Investigam as condições do mercado relativamente a mercadorias específicas, a fim de informarem os seus clientes. Apresentam propostas de licitação e calculam o custo das transações.', 'released', '["Corretor de Mercadorias", "Corretora de Mercadorias", "Corretora de Commodities", "Corretor de Commodities"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/2afdf635-3cdb-4914-ab61-5dd7d7d46792', 'Gerente de Padaria', 'Os gestores de padarias assumem a responsabilidade pelas atividades de panificação e pelo pessoal.', 'released', '["Chefe de Padaria", "Gerente de Pastelaria", "Gerentea de Padaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/2b136e51-154b-4cb2-8130-f73228f14b11', 'Operador de Máquinas Têxteis', 'Os operadores de máquinas têxteis supervisionam o processo têxtil de um grupo de máquinas, supervisionando a qualidade e a produtividade. Procedem à inspeção das máquinas têxteis após a sua instalação, colocação em funcionamento e durante a produção, a fim de assegurar a conformidade do produto com as especificações e normas de qualidade.', 'released', '["Operadora de Máquinas Téxteis", "Operador de Máquinas Téxteis", "Operadora de Máquinas Têxteis"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/2b292d4d-1905-45ec-a7c0-1ca7b45a4162', 'Criador de Cães', 'Os criadores de cães supervisionam a produção e o cuidado diário dos cães. Zelam pela saúde e pelo bem-estar dos cães.', 'released', '["Criadora de Cães", "Criador de Cães"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/2b318e09-1a5d-4d7f-85a7-fe78945fe917', 'Supervisor de Construção de Dutos', 'Os supervisores de construção de condutas supervisionam a instalação de condutas de esgotos e de outras infraestruturas de esgotos. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Construção Decondutas", "Supervisor de Construção Decondutas", "Supervisora de Construção de Dutos"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/2b31f745-f04f-4d2c-9692-4715e1448f80', 'Inspetor de Saúde e Segurança', 'Os inspetores de saúde e segurança investigam a implementação e a aplicação de normas e políticas laborais num local de trabalho. Prestam aconselhamento aos empregadores, bem como os trabalhadores, sobre a melhoria da aplicação da política e da legislação, asseguram o cumprimento da lei e o cumprimento das questões da igualdade e dos direitos laborais. Elaboram relatórios e comunicam com as autoridades.', 'released', '["Inspetora de Saúde e Segurança", "Inspetor de Saúde e Segurança"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/2b48a4cd-2333-4abf-ac3e-6f63d6ed3663', 'Controlador de Qualidade de Calçado', 'Os controladores de qualidade de calçado realizam uma análise visual do aspeto do calçado, das matérias-primas e dos componentes, aplicando critérios previamente definidos, e decidem se devem ser aceites ou rejeitados. Analisam os dados recolhidos, elaboram relatórios e entregam-nos aos responsáveis pela gestão da qualidade. Utilizam ferramentas de gestão da qualidade previamente definidas, com vista ao cumprimento dos objetivos enunciados na política de qualidade. Participam no acompanhamento e no controlo do sistema de qualidade e na aplicação de medidas corretivas e preventivas.;', 'released', '["Controladora de Qualidade de Calçado", "Controlador de Qualidade de Calçado"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/2b4b5f84-4367-4cb9-9fa0-0e631eded6c8', 'Operador de Pontes', 'Os operadores de pontes são responsáveis pelo funcionamento de uma ponte. Utilizam sinais de trânsito para permitir a passagem de veículos e peões. Redigem relatórios de acidentes e apresentam pedidos de reparação, se for caso disso. Realizam inspeções de rotina e tarefas de manutenção, como a resolução de problemas no sistema elétrico.', 'released', '["Operador de Pontes", "Operadora de Pontes"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/2b6bb2d1-54b0-4feb-8c6c-8ba20adde1df', 'Professor de Línguas Clássicas do Ensino Secundário', 'Os professores de Línguas Clássicas do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, as Línguas Clássicas. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio das Línguas Clássicas através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Latim do Ensino Secundário", "Professora de Línguas Clássicas do Ensino Secundário", "Professora de Grego do Ensino Secundário", "Professor de Línguas Clássicas do Ensino Secundário", "Professor de Latim do Ensino Secundário", "Professor de Grego do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/2b7d34db-11b6-4c10-b227-3917752e28ac', 'Vice-Diretor de Escola', 'Os vice-diretores de escola apoiam as funções de gestão dos diretores de escola e fazem parte do pessoal administrativo da escola. Atualizam o professor titular nas operações diárias e no desenvolvimento da escola. Executam e dão seguimento às orientações, políticas e atividades curriculares das escolas introduzidas pelo diretor da escola em questão. Aplicam o currículo escolar, supervisionam os alunos e mantêm a disciplina.', 'released', '["Vice-Diretora de Escola", "Vice-Diretor de Escola"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/2b871272-bd61-4206-bd1a-0b96d7023098', 'Operador de Caixa', 'Os operadores de caixa operam a caixa registadora, recebem pagamentos dos clientes, emitem recibos e dão o troco devido.', 'released', '["Operador de Caixa", "Caixa de Loja", "Operadora de Caixa"]'::jsonb, '5230'),
  ('http://data.europa.eu/esco/occupation/2bb8adee-2b84-4d7b-84f9-0620bc09ada8', 'Técnico de Instrumentação', 'Os técnicos de instrumentação prestam assistência aos engenheiros de instrumentação no desenvolvimento de equipamento de controlo, como válvulas, relés e reguladores, os quais podem ser utilizados para monitorizar e controlar processos. Os técnicos de instrumentação são responsáveis pela construção, pelo ensaio, pela monitorização e pela manutenção do equipamento. Utilizam chaves de aperto, máquinas de corte de vigas, rebarbadoras e pórticos rolantes para a construção e reparação de equipamento.', 'released', '["Técnico de Instrumentação", "Técnica de Instrumentação"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/2bdf0696-776c-47e6-9259-6460af224dac', 'Leitor de Contadores', 'Os leitores de contadores visitam os edifícios residenciais e empresariais ou industriais e as instalações, a fim de registar as leituras dos contadores que medem o gás, a água, a eletricidade e outras utilizações dos serviços de utilidade pública. Transmitem os resultados ao cliente e ao fornecedor.', 'released', '["Leitor de Contadores", "Leitora de Contadores", "Leitora de Contadores de Eletricidade", "Leitora de Contadores de Água", "Leitor de Contadores de Eletricidade", "Leitor de Contadores de Água", "Leitor de Contadores de Gás", "Leitora de Contadores de Gás"]'::jsonb, '9623'),
  ('http://data.europa.eu/esco/occupation/2be85651-c94a-4531-9df8-3cc56932960e', 'Operador de Máquina de Selagem a Quente', 'Os operadores de máquinas de selagem a quente operam máquinas de selagem e colagem para unir elementos para transformação posterior ou para a selagem de produtos ou embalagens, utilizando o calor.', 'released', '["Operadora de Máquina de Selagem a Quente", "Operador de Máquina de Selagem a Quente"]'::jsonb, '8183'),
  ('http://data.europa.eu/esco/occupation/2bedd02b-aeeb-4ed8-b1ae-29a706638414', 'Representante de Serviço de Aluguel de Bens de Uso Pessoal e Doméstico', 'Os representantes de serviço de aluguer de bens de uso pessoal e doméstico são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Os bens de uso pessoal e doméstico são todos os bens utilizados nos agregados familiares, tais como mobiliário e roupa para quartos e mobiliário de cozinha, máquinas e materiais. Os representantes de serviço de aluguer de bens de uso pessoal e doméstico documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Bens de Uso Pessoal e Doméstico"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/2bef94db-0088-4507-982a-2ca717529adb', 'Arquiteto Empresarial', 'Os arquitetos empresariais equilibram as oportunidades tecnológicas com as necessidades da empresa. Além disso, mantêm uma visão holística da estratégia, dos processos, das informações e dos ativos de tecnologia da informação da organização e associam a missão, a estratégia e os processos da empresa à estratégia da tecnologia da informação.', 'released', '["Arquiteto Empresarial", "Arquiteta Empresarial", "Gestor de Arquitetura de Empresas", "Gestora de Arquitetura de Empresas"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/2bf5169b-2c89-451a-9274-e2b4bc1f9487', 'Engenheiro Têxtil', 'Os engenheiros têxteis trabalham na concepção, desenvolvimento e produção de têxteis e vestuário. Realizam um vasto trabalho de controlo técnico, de investigação e de controlo da qualidade para assegurar o produto final (desde o vestuário até aos têxteis industriais). Cumprem especificações e melhoram a eficiência e a qualidade da produção, ao mesmo tempo que asseguram a ligação com as partes envolvidas no processo de produção. Estabelecem contatos com os designers, adaptam os desenhos aos métodos de produção, fabricam e dimensionam vestuário de pré-produção, aprovisionam tecidos e acessórios, realizam avaliações de qualidade dos materiais e verificam a qualidade do produto final, e têm em conta os aspetos ecológicos.', 'released', '["Engenheira Têxtil", "Especialista em Tecnologia Têxtil", "Engenheiro Têxtil"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/2c027db0-d2a6-43f0-9c4a-caff27c7c54a', 'Instrutor de Navegação', 'Os instrutores de navegação ensinam a teoria e a prática de operar um navio em segurança e em conformidade com os regulamentos. Ajudam os alunos a desenvolver as competências necessárias para os orientar e preparar para a teoria da navegação e os exames de navegação. Também podem supervisionar os exames de navegação.', 'released', '["Instrutor de Navegação", "Instrutora de Navegação"]'::jsonb, '5165'),
  ('http://data.europa.eu/esco/occupation/2c1ed9dd-9799-4882-8bfa-40b841f7d4a1', 'Diretor de Instituição de Ensino Superior Técnico', 'Os diretores de instituição de ensino superior técnico gerem as atividades quotidianas de um instituto de ensino pós-secundário, tais como institutos técnicos e outros estabelecimentos de ensino pós-secundário. Além disso, os diretores de instituição de ensino superior técnico tomam decisões sobre as admissões e são responsáveis pelo cumprimento das normas curriculares, que facilitam o desenvolvimento académico dos alunos. Gerem o pessoal, o orçamento e os programas da escola e supervisionam a comunicação entre os serviços. Além disso, asseguram que a escola cumpre os requisitos nacionais em matéria de educação previstos na lei.', 'released', '["Diretora de Instituto Técnico", "Diretor de Instituição de Ensino Superior Técnico", "Diretor de Conservatório", "Diretor de Instituto Técnico", "Diretora de Instituição de Ensino Superior Técnico", "Diretora de Conservatório"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/2c5ae1b4-c3ca-4882-b7ce-e346ae5b5b00', 'Técnico de Botânica', 'Os técnicos de botânica prestam assistência técnica na investigação e no ensaio de diferentes espécies de plantas, tendo em vista a monitorização das suas propriedades, como o crescimento e a estrutura. Recolhem e analisam dados utilizando equipamentos laboratoriais, elaboram relatórios e mantêm as existências do material de laboratório. Os técnicos de botânica também estudam as plantas para investigarem a sua utilização em áreas como a medicina, a alimentação e os materiais.', 'released', '["Técnica de Botânica", "Técnico de Botânica"]'::jsonb, '3141'),
  ('http://data.europa.eu/esco/occupation/2c83f279-a1d1-4c9f-a6aa-5e5ee1850e46', 'Inspetor da Segurança Social', 'Os inspetores da segurança social investigam atividades fraudulentas em matéria de segurança social que afetam os direitos dos trabalhadores. Procedem à auditoria e analisam os pedidos de prestações e investigam as ações da empresa com base em queixas dos trabalhadores. As inspeções incluem atividades laborais como o não pagamento de salários ou de despesas. Os inspetores de segurança social asseguram que os trabalhadores são tratados de forma equitativa e em conformidade com a legislação. Registam e elaboram relatórios sobre as suas conclusões para garantir a validade das alegações que estão a investigar.', 'released', '["Inspetora da Segurança Social", "Inspetor da Segurança Social"]'::jsonb, '3353'),
  ('http://data.europa.eu/esco/occupation/2c8a4b72-21f4-4ab1-9dbd-1cae779211b7', 'Gerente de Galeria de Arte Comercial', 'Os gerentes de galeria de arte comercial gerem o sucesso comercial e artístico da galeria.', 'released', '["Gerente de Galeria", "Gerente de Espaço de Exposição", "Gerentea de Galeria de Arte Comercial"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/2c90a752-43f0-483d-8f64-3ce5e4535aa8', 'Condutor de Charrete', 'Os condutores de charrete transportam passageiros em carruagens de cavalos. Asseguram a segurança dos passageiros e cuidam dos cavalos.', 'released', '["Condutor de Charrete", "Condutora de Charrete"]'::jsonb, '9332'),
  ('http://data.europa.eu/esco/occupation/2c94916d-bd7d-4855-ab89-574d2c439a63', 'Operador de Máquinas de Medição de Couro', 'Os operadores de máquinas de medição de couro utilizam máquinas para medir a superfície do couro e asseguram que as máquinas são regularmente calibradas. Anotam a dimensão do couro para faturação posterior.;', 'released', '["Operadora de Máquinas de Medição de Couro", "Operador de Máquinas de Medição de Couro"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/2c9939ef-ebab-4111-8f27-605ae8782791', 'Gestor de Contratos', 'Os gestores de contratos velam pelo respeito dos contratos adjudicados, a fim de garantir que os serviços são prestados conforme previsto e que cada fase da execução está devidamente documentada. Funcionam como principal ponto de contato para os fornecedores em questões contratuais, e prestam contas aos seus superiores. Efetuam controlos financeiros e operacionais e garantem o cumprimento de todos os requisitos em matéria de comunicação de informações.;', 'released', '["Líder de Contrato", "Especialista em Contrato", "Auditor de Contrato", "Especialista em Gestão de Contratos", "Auditora de Contrato", "Especialista em Conformidade de Contrato", "Gerente", "Gestora de Contratos"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/2cad9c6f-0289-4b26-b247-e65c0089f8f4', 'Operador de Caldeiras', 'Os operadores de caldeiras procedem à manutenção de sistemas de aquecimento, tais como caldeiras de baixa pressão, caldeiras de alta pressão e caldeiras elétricas. Trabalham sobretudo em grandes edifícios, tais como centrais elétricas ou casas de caldeiras, e asseguram um funcionamento seguro e respeitador do ambiente dos sistemas de caldeiras.', 'released', '["Operador de Caldeiras", "Operadora de Caldeiras"]'::jsonb, '8182'),
  ('http://data.europa.eu/esco/occupation/2cbb23b0-0bf1-4871-9e6d-18f005987310', 'Técnico de Produção Áudio', 'Os técnicos de produção áudio procedem à instalação, preparação, controlo e manutenção do equipamento a fim de proporcionar uma ótima qualidade de som para um espetáculo ao vivo. Cooperam com a equipe de apoio de estrada para descarregar, instalar e operar equipamentos e instrumentos de som.', 'released', '["Técnico de Produção Áudio", "Técnica de Produção Áudio"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/2ce45b9f-ebfb-4105-8e12-690ba2bf00aa', 'Gerente de Loja de Jogos e Brinquedos', 'Os gerentes de loja de jogos e brinquedos assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Brinquedos", "Gerente de Megaloja de Brinquedos", "Gerentea de Loja de Jogos e Brinquedos"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/2cec9e4a-5a37-4cb1-a8b7-2e8d94766417', 'Supervisor de Operador de Máquinas', 'Os supervisores de operadores de máquinas coordenam e orientam os trabalhadores que instalam e operam máquinas. Monitorizam o processo de produção e o fluxo dos materiais e asseguram que os produtos cumprem os requisitos.', 'released', '["Supervisora de Operadora de Máquinas", "Supervisor de Operadora de Máquinas", "Supervisora de Operador de Máquinas"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/2cf2b905-3308-4b5d-8e8d-633fc7a3f3ce', 'Gestor de Sustentabilidade', 'Os gestores de sustentabilidade são responsáveis por garantir a sustentabilidade dos processos empresariais. Prestam assistência na concepção e na execução de planos e medidas para garantir que os processos de fabrico e os produtos fabricados cumprem determinados regulamentos ambientais e normas de responsabilidade social, e acompanham e informam sobre a aplicação de estratégias de sustentabilidade na cadeia de abastecimento e nos processos empresariais da empresa. Analisam questões relacionadas com os processos de fabrico, a utilização de materiais, a redução dos resíduos, a eficiência energética e a rastreabilidade dos produtos, a fim de melhorar os impactos ambientais e sociais e integrar aspetos de sustentabilidade na cultura empresarial.;', 'released', '["Coordenador de Sustentabilidade", "Especialista em Sustentabilidade", "Analista de Sustentabilidade", "Coordenadora de Sustentabilidade", "Gerente", "Gestora de Sustentabilidade"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/2d32bea0-dccd-4dc5-9ea9-c51c653a46ef', 'Cobrador de Seguros', 'Os cobradores de seguros cobram o pagamento de uma fatura do seguro em atraso. Especializam-se em todos as áreas dos seguros, tais como médico, vida, automóvel, viagem, etc., e contactam periodicamente as pessoas para oferecer assistência ao pagamento ou para facilitar os planos de pagamento de acordo com a situação financeira individual.', 'released', '["Cobradora de Seguros", "Cobrador de Seguros"]'::jsonb, '4214'),
  ('http://data.europa.eu/esco/occupation/2d3d7188-47ab-49b9-9045-e452d9db06f1', 'Diretor de Vendas e Marketing', 'Lidera as áreas de vendas e marketing, definindo metas comerciais, estratégias de go-to-market, posicionamento, precificação e planos de captação e retenção de clientes. Gerencia equipes de vendas, marketing e pré-vendas, acompanha pipeline, receita, CAC, LTV e conversão, e alinha a operação comercial ao desenvolvimento de produtos e às metas da empresa.', 'released', '["Diretor de Vendas e Marketing", "Diretor Comercial", "Diretora Comercial", "Gerente Comercial", "Head de Vendas e Marketing", "Diretor de Vendas", "Diretor de Marketing", "Gerente de Vendas e Marketing", "Diretor Comercial Internacional", "Chief Marketing Officer (CMO)", "CMO", "Sales", "Diretora de Vendas e Marketing"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/2d5a50c6-0bf4-45c3-805c-44d1bf1e3d12', 'Assistente de SPA', 'Os assistentes de SPA interagem com os hóspedes no balcão de recepção para fornecer indicações e explicar os serviços disponíveis no centro de SPA. São também responsáveis pela limpeza das instalações de SPA após a utilização, pela manutenção da limpeza da zona de armazenagem e por repor toalhas limpas. Os assistentes de SPA controlam a segurança da instalação e são responsáveis pela venda dos produtos e serviços disponíveis, tais como os pacotes de tratamento.', 'released', '["Assistentea de SPA"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/2d6a1cc1-cd13-42c5-a2b1-f0183bd0d253', 'Representante de Vendas de Máquinas e Equipamentos Agrícolas', 'Os representantes das vendas de máquinas e equipamentos agrícolas prestam serviços em nome de uma empresa para vender as suas mercadorias, fornecendo simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Máquinas e Equipamentos Agrícolas"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/2d6d4cb2-5d46-4d1f-939b-7f55c02c64cb', 'Caldeireiro Artesanal', 'Os caldeireiros artesanais criam e reparam artigos de metais não ferrosos, tais como cobre, latão e materiais semelhantes. Moldam e dão forma às matérias-primas transformando-as em objetos práticos ou artísticos, utilizando ferramentas de forjamento. Os caldeireiros artesanais profissionais criam dispositivos detalhados e altamente técnicos, utilizando técnicas de forjamento adequadas.', 'released', '["Funileira", "Caldeireira Artesanal", "Caldeireiro Artesanal", "Funileiro", "Latoeiro", "Latoeira"]'::jsonb, '7213'),
  ('http://data.europa.eu/esco/occupation/2d92f7f5-d2b1-4223-92c4-23c33f8604fc', 'Escanção de Vinhos', 'Os escanções de vinhos têm conhecimentos gerais sobre o vinho, a sua produção, o seu serviço e o emparelhamento com alimentos. Utilizam estes conhecimentos para a gestão de caves de vinho especializadas, publicam listas de vinhos e livros ou trabalham em restaurantes.', 'released', '["Escanção de Vinhos", "Escançã de Vinhos", "Chefe de Vinhos", "Escançãa de Vinhos"]'::jsonb, '5131'),
  ('http://data.europa.eu/esco/occupation/2dc86f3d-a90e-4e7a-8a94-0bd728f22d7b', 'Fabricante de Molduras', 'Os fabricantes de molduras fabricam molduras, na sua maioria de madeira, para fotografias e espelhos. Discutem as especificações com os clientes e fabricam ou ajustam a moldura em conformidade. Cortam, moldam e unem os elementos de madeira, tratando-os para obter a cor desejada e protegê-los da corrosão e do fogo. Cortam e encaixam o vidro na moldura. Em alguns casos, entalham e decoram as molduras. Também podem reparar, restaurar ou reproduzir molduras mais antigas.', 'released', '["Fabricantea de Molduras"]'::jsonb, '7115'),
  ('http://data.europa.eu/esco/occupation/2dcb5dad-1902-4051-9023-d725485479a7', 'Acupuntor', 'Os acupuntores utilizam agulhas finas e colocam-nas em pontos de acupuntura no corpo, a fim de corrigir os desequilíbrios do corpo humano e restabelecer a boa saúde geral. Os acupuntores centram-se nos meridianos de energia para tratar várias patologias.', 'released', '["Acupuntora", "Especialista em Acupuntura", "Acupuntor"]'::jsonb, '2230'),
  ('http://data.europa.eu/esco/occupation/2dcd3361-4c9b-4feb-a561-62257d6b31dd', 'Comerciante Grossista de Equipamentos Eletrônicos e de Comunicações', 'Os comerciantes grossistas de equipamentos eletrônicos e de comunicações investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Equipamentos Eletrônicos e de Comunicações"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/2ddde737-28f3-444d-b1f8-ef12cc2df3c7', 'Responsável Pelo Gabinete de Apoio ao Aluno', 'Os responsáveis pelo gabinete de apoio ao aluno prestam assistência aos alunos com problemas de aprendizagem e servem de ponto de contato principal para estes alunos. Asseguram a disponibilidade de programas de ensino e tutoria adicionais para os alunos sub-representados com problemas académicos ou pessoais. Organizam também várias atividades sociais ao longo do ano letivo.', 'released', NULL, '2359'),
  ('http://data.europa.eu/esco/occupation/2de007c6-3223-4cd1-9561-e8a2e16e049d', 'Ajudante de Veterinário', 'Os ajudantes de veterinário investigam alegados relatos de crueldade ou negligência dos animais, salvam ou recolhem animais em risco imediato ou potencial, asseguram a ligação com agências internas e externas e outros estabelecimentos de bem-estar dos animais, educam e aconselham os proprietários e cuidadores de animais, procuram melhorar ou manter o bem-estar do(s) animal(ais) e prevenir ou aliviar o sofrimento.', 'released', '["Profissional do Bem-Estar Animal", "Ajudantea de Veterinário"]'::jsonb, '5419'),
  ('http://data.europa.eu/esco/occupation/2e46a2a3-4d33-469e-8d50-588cc17e6bed', 'Contramestre', 'Os contramestres organizam a tripulação no convés e no porão de peixe para executar as ordens recebidas de um superior. Coordenam as operações de manutenção, manobras, montagem e reparação das artes de pesca e triagem, transformação e conservação das capturas, respeitando as normas de higiene e os regulamentos de segurança estabelecidos.', 'released', '["Contramestre", "Contramestra", "Contramestrea"]'::jsonb, '8350'),
  ('http://data.europa.eu/esco/occupation/2e4b41dd-b63d-403d-a0ad-dd323cd3ddac', 'Manuseador de Gaiolas em Aquicultura', 'Os manuseadores de gaiolas em aquicultura operam equipamento altamente especializado, a fim de amarrar as gaiolas em estações estáveis, gaiolas flutuantes, ou mesmo gaiolas autopropulsionadas e semissubmersas.', 'released', '["Manuseador de Gaiolas em Aquicultura", "Manuseadora de Gaiolas em Aquicultura"]'::jsonb, '9216'),
  ('http://data.europa.eu/esco/occupation/2e85b540-4a92-47f3-bc8c-0699c51692d1', 'Supervisor de Instalação de Elevadores', 'Os supervisores de instalação de elevadores acompanham a instalação de elevadores. Mantêm uma visão geral do processo, atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Instalação de Elevadores", "Supervisor de Instalação de Elevadores"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/2e8820ba-5b2d-4572-92a1-942dbd02a6d6', 'Técnico de Laboratório Biomédico', 'Os cientistas biomédicos executam todos os métodos laboratoriais necessários no âmbito das atividades de exame médico, acompanhamento, tratamento e investigação, o que implica conceber, planear, organizar, aplicar, avaliar, interpretar e validar todos os processos analíticos. Desenvolvem a sua atividade em vários domínios de especialização, nomeadamente a hematologia, a microbiologia, a imunologia clínica, a citopatologia, a histopatologia, a imuno-histoquímica e a bioquímica clínica. Tal exige a aplicação de métodos laboratoriais qualitativos e quantitativos, incluindo a análise de imagens e a patologia digital, para fornecer um relatório de investigação e um parecer de diagnóstico sobre produtos de natureza biológica.', 'released', '["Técnico de Laboratório Biomédico", "Técnica de Laboratório Biomédico"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/2e9c9404-0d86-453c-9001-3a0cd1d1323b', 'Vendedor de Produtos de Padaria', 'Os vendedores de produtos de padaria vendem pão e bolos em lojas especializadas, procedendo à pós-transformação dos produtos, se necessário.', 'released', '["Vendedora de Produtos de Padaria", "Vendedor de Produtos de Padaria"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/2ea3070e-3d0b-4de6-b5bd-fe4a04649b04', 'Supervisor de Andaimes', 'Os supervisores de andaimes planeiam e supervisionam o transporte, a montagem, a desmontagem e a manutenção das estruturas. Asseguram também a segurança dos andaimes, das estruturas de suporte, das escadas de acesso e das proteções.', 'released', '["Supervisora de Andaimes", "Supervisor de Andaimes"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/2eac08c2-a81a-46fc-8d75-eb0e0f3e0f6d', 'Gestor de Vendas', 'Os gestores de vendas servem como intermediários entre clientes e a organização, gerindo tanto as vendas como as relações a longo prazo com o cliente. Têm conhecimento dos produtos e serviços e desenvolvem contratos com os clientes.', 'released', '["Gestor de Vendas", "Assistente de Vendas", "Representante de Vendas", "Gestora de Vendas", "Gestora de Clientes", "Gestor de Clientes", "Gerente", "Sales"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/2ecbed9c-0143-4cc9-b047-d1746aeec206', 'Operador de Fornos de Túnel', 'Os operadores de fornos de túnel controlam as câmaras de pré-aquecimento e os fornos de túnel para pré-aquecer e fabricar produtos à base de argila, tais como tijolos, canos de esgotos, mosaico, cerâmica ou ladrilhos de cerâmica. Observam gabaritos e instrumentos e ajustam, se necessário, rodando válvulas. Carregam e descarregam vagões dos fornos e transferem-nos para uma zona de triagem.', 'released', '["Operadora de Fornos de Túnel", "Operador de Fornos de Túnel"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/2ed56c3f-61d6-4f7e-9ef8-8849eb102e4c', 'Desenvolvedor Mobile', 'Desenvolve, testa e mantém aplicativos para dispositivos móveis Android e iOS, implementando interfaces, integrações com APIs, armazenamento local e recursos nativos. Atua com desenvolvimento mobile, React Native, Flutter, Kotlin, Swift ou tecnologias equivalentes, cuida de performance, usabilidade, segurança e publicação nas lojas de aplicativos. Colabora com design, produto, QA e back-end.', 'released', '["Desenvolvedor Mobile", "Desenvolvedor de Aplicações Móveis", "Programador de Aplicações Móveis", "Programadora de Aplicações Móveis", "Programador Mobile", "Desenvolvedor de Aplicativos Móveis", "Desenvolvedor Android", "Desenvolvedor iOS", "Desenvolvedor React Native", "Desenvolvedor Flutter", "Desenvolvedor Mobile Industrial", "Desenvolvedor de Dispositivos Móveis para a Indústria", "Programador", "Desenvolvedora Mobile"]'::jsonb, '2514'),
  ('http://data.europa.eu/esco/occupation/2edd910a-e53e-44ee-b8c2-09e9f9d0395b', 'Engomadeiro', 'Os engomadeiros utilizam ferros de engomar a vapor, tábuas de passar com vácuo ou tábuas de passar manuais para moldar artigos de vestuário.', 'released', '["Engomadora de Roupa", "Engomador de Roupa", "Engomadeira"]'::jsonb, '9121'),
  ('http://data.europa.eu/esco/occupation/2ee57107-08c6-4963-bdde-f2ee514e06d5', 'Comerciante Grossista de Peixes, Crustáceos e Moluscos', 'Os comerciantes grossistas de peixes, crustáceos e moluscos investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Peixes, Crustáceos e Moluscos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/2ef000b1-8058-4e5a-9646-c5d4e7dbfdae', 'Responsável Pela Manutenção de Infraestruturas de Comunicação', 'Os responsáveis pela manutenção de infraestruturas de comunicação procedem à instalação, reparação e manutenção de infraestruturas para sistemas de comunicação.', 'released', '["Responsável Pela Manutenção de Infraestruturas de Comunicação", "Técnico de Cabos", "Técnica de Cabos"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/2f1380b4-b76b-489c-a3a8-cd05ed6ad392', 'Restaurador de Livros', 'Os restauradores de livros corrigem e tratam dos livros com base numa avaliação das suas características estéticas, históricas e científicas. Determinam a estabilidade do livro e abordam os problemas de deterioração química e física do mesmo.', 'released', '["Restauradora de Livros", "Conservador de Livros", "Restaurador de Livros", "Conservadora de Livros"]'::jsonb, '7323'),
  ('http://data.europa.eu/esco/occupation/2f26a52b-cf45-4282-9138-478252161f00', 'Engenheiro Alimentar', 'Os engenheiros alimentares supervisionam as necessidades elétricas e mecânicas do equipamento e das máquinas utilizados no processo de fabrico de alimentos ou bebidas. Procuram maximizar a produtividade das fábricas participando em ações de prevenção em matéria de saúde e segurança, boas práticas de fabrico (BPF), cumprimento das normas de matéria de higiene e execução da manutenção de rotina de máquinas e equipamentos.', 'released', '["Engenheiro de Produção Alimentar", "Engenheira Alimentar", "Engenheira de Produção Alimentar", "Engenheiro Alimentar"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/2f372afe-d513-4357-abe1-e5e0b5cf9ae5', 'Iluminador', 'Os iluminadores determinam quais as luzes que são necessárias durante a produção, de acordo com a visão criativa do realizador do filme. Utilizam o guião para conceber os requisitos de iluminação para cada plano. Os iluminadores supervisionam a instalação e o funcionamento da iluminação.', 'released', '["Iluminador", "Light Designer", "Iluminadora"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/2f5de1ab-eddf-4715-8193-e994912c22ea', 'Gestor de Armazém', 'Os gestores de armazém assumem a responsabilidade pelas instalações de armazenagem. Gerem as operações e o pessoal no seu interior.', 'released', '["Gestora de Armazém", "Gestor de Armazém", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/2f5e38a0-6578-4665-bdbd-e2ab505be140', 'Auxiliar de Bar', 'Os empregados de bar servem bebidas alcoólicas ou não alcoólicas, tal como solicitado pelos clientes num estabelecimento de hotelaria e restauração.', 'released', '["Empregado de Bar", "Técnico de Bar", "Técnica de Bar", "Barman", "Empregada de Bar", "Barmaid"]'::jsonb, '5132'),
  ('http://data.europa.eu/esco/occupation/2f7f5c84-b9b3-41ea-aa5f-5997d0873141', 'Trabalhador de Sala de Jogo de Bingo', 'Os trabalhadores de sala de jogo de bingo organizam e gerem jogos de bingo numa sala de bingo, num clube social ou noutro local de entretenimento. Os chefes de sala têm conhecimento de toda a legislação pertinente que rege a atividade do bingo e das regras do clube relativas ao jogo de todas as variações do bingo. ;', 'released', '["Trabalhadora de Sala de Jogo de Bingo", "Cantadora de Bingo", "Animadora de Jogo de Bingo", "Trabalhador de Sala de Jogo de Bingo", "Animador de Jogo de Bingo", "Cantador de Bingo"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/2f8acdc5-76f5-498b-9818-df075e324eaa', 'Diretor de Comunicações e Sistemas de Informação', 'Os diretores de comunicações e sistemas de informação são responsáveis por atividades e projetos destinados a proporcionar uma infraestrutura de comunicação adequada que apoie o intercâmbio de informações entre os usuários do espaço aéreo.', 'released', '["Diretor de Comunicações e Sistemas de Informação", "Diretora de Comunicações e Sistemas de Informação"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/2fa8c1fc-e722-4985-9822-f5d8174248cf', 'Operador de Instalações de Preparação de Betuminosos', 'Os operadores de instalações de preparação de betuminosos extraem matérias-primas, tais como a areia e as pedras, e operam equipamento móvel para o seu transporte para a instalação. Asseguram o correto funcionamento das máquinas automatizadas para triturar e separar as pedras e misturar a areia e as pedras com betume. Recolhem amostras para verificar a qualidade da mistura e organizam o seu transporte para o estaleiro.', 'released', '["Operadora de Instalações de Preparação de Betuminosos", "Operador de Instalações de Preparação de Betuminosos"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/2fb96c6c-8d0b-4ef0-b1ee-3e493305e4eb', 'Arquiteto de Computação em Cloud', 'Os arquitetos de computação em cloud são responsáveis pela conversão das características técnicas de um projeto numa arquitetura que conduz a um produto final. Para elaborar estratégias técnicas de computação em cloud, possuem um conhecimento aprofundado dos princípios e serviços arquitetónicos, assistem nos esforços de migração para a cloud, analisam as arquiteturas de carga de trabalho e fornecem orientações sobre a forma de abordar problemas de alto risco. Normalmente desempenham uma função de pré-venda e são frequentemente chamados a apresentar projetos de prova de conceito, a ministrar oficinas temáticas e a liderar projetos de execução. Trabalham em equipe com engenheiros de DevOps para desenvolver as tecnologias adequadas.', 'released', '["Arquiteta de Computação em Cloud", "Arquiteto de Computação em Cloud"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/2fc8dace-d828-4af3-b0cb-e1cb73726f4b', 'Operador de Máquina para Rosquear', 'Os operadores de máquina para rosquear instalam e cuidam de máquinas para rosquear concebidas para o fabrico de parafusos (roscados) a partir de peças metálicas transformadas, especificamente de pequena e média dimensão, que foram torneadas por uma máquina de tornear.', 'released', '["Operadora de Máquina para Rosquear", "Operador de Máquina para Rosquear"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/2ff73126-7aff-4233-9d9c-d8725e1c6822', 'Soldador de Tubos', 'Os soldadores de tubos montam e instalam peças e componentes de condutas para o transporte de mercadorias, tais como água, vapor e produtos químicos através dos mesmos. Interpretam especificações, tais como pneumáticas e hidráulicas, para instalação no local, de acordo com os requisitos de segurança e de produção.', 'released', '["Soldador de Tubos", "Soldadora de Tubos", "Instalador de Tubos", "Instaladora de Tubos"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/2ff9e53c-6e7f-42af-8d71-b5dd7f283089', 'Caixa Bancário', 'Os caixas bancários lidam com mais frequência com os clientes do banco. Promovem os produtos e serviços dos bancos e fornecem informações sobre as contas pessoais dos clientes e as transferências, os depósitos, as poupanças associados, etc. Pedem os cartões bancários e os cheques para os clientes, recebem e equilibram o dinheiro e os cheques e asseguram a conformidade com as políticas internas. Trabalham com as contas dos clientes, lidam com pagamentos e gerem a utilização dos cofres e das caixas de segurança.', 'released', '["Caixa Bancário", "Caixa Bancária"]'::jsonb, '4211'),
  ('http://data.europa.eu/esco/occupation/30058b71-fe16-45ea-a2b8-d5461c706372', 'Professor de Ciências Empresariais', 'Os professores de Ciências Empresariais são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências Empresariais, que é predominantemente de natureza académica. Prestam assistência ao professor do curso específico pelo quais são responsáveis na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio das Ciências Empresariais, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Ciências Empresariais", "Professor Universitário de Ciências Empresariais", "Professora Universitária de Ciências Empresariais", "Professor de Ciências Empresariais"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/30194ac4-93b8-4450-8a15-f6f7cbe351cb', 'Assistente de Obstetrícia', 'Os assistentes de obstetrícia trabalham numa equipe constituída por parteiras e profissionais de saúde nas áreas profissionais de enfermagem e obstetrícia. Prestam assistência às parteiras e às mulheres grávidas, prestando o apoio, os cuidados e o aconselhamento necessários durante a gravidez, o trabalho de parto e o período pós-parto, e prestam assistência ao parto e nos cuidados ao recém-nascido.', 'released', '["Assistentea de Obstetrícia"]'::jsonb, '3222'),
  ('http://data.europa.eu/esco/occupation/3025dea4-1752-40a9-9431-fd874420386f', 'Nadador-Salvador', 'Os nadadores-salvadores controlam e garantem a segurança na instalação aquática, prevenindo e respondendo a quaisquer emergências. Identificam riscos potenciais, aconselham as pessoas sobre um comportamento adequado e zonas perigosas, conduzem técnicas de salvamento, tais como primeiros socorros, e supervisionam as atividades do público em geral.', 'released', '["Life Guard", "Nadador Salvador", "Nadadora-Salvadora", "Nadador-Salvadora"]'::jsonb, '5419'),
  ('http://data.europa.eu/esco/occupation/3027abf6-bc54-4709-8dc1-4f20b772ac70', 'Calibrador de Chapas de Madeira Processada', 'Os calibradores de chapas de madeira processada inspecionam produtos de madeira transformada para detectar eventuais problemas de qualidade, tais como colagem incompleta, deformação ou manchas. Também testam as qualidades de suporte de carga da madeira. Classificam os produtos em termos de qualidade de acordo com as orientações.', 'released', '["Calibradora de Chapas de Madeira Processada", "Calibrador de Chapas de Madeira Processada"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/303931a2-860a-4f76-83ac-3c190d67287e', 'Operador de Prensagem de Óleos Alimentares', 'Os operadores de prensagem de óleos alimentares operam prensas hidráulicas que produzem extratos de óleo a partir de sementes oleaginosas.', 'released', '["Operador de Prensagem de Óleos Alimentares", "Prensadora de Sementes Oleaginosas", "Prensador de Sementes Oleaginosas", "Operador de Prensa de Óleos Alimentares", "Operadora de Prensa de Óleos Alimentares", "Operadora de Prensagem de Óleos Alimentares"]'::jsonb, '7514'),
  ('http://data.europa.eu/esco/occupation/303a1e34-cb16-4054-b323-81e5eec17397', 'Auxiliar de Limpeza de Edifícios e Espaços Comuns', 'Os empregados de limpeza de edifícios e espaços comuns procedem à limpeza e a funcionalidade geral de vários tipos de edifícios, tais como escritórios, hospitais e instituições públicas. Executam tarefas de limpeza, tais como varrer, aspirar e lavar os pavimentos, esvaziar o lixo e verificar sistemas de segurança, fechaduras e janelas. Os empregados de limpeza de edifícios e espaços comuns verificam os sistemas de ar condicionado e notificam as pessoas adequadas em caso de avarias ou problemas.', 'released', '["Empregada de Limpeza de Escritórios", "Empregado de Limpeza de Edifícios e Espaços Comuns", "Empregado de Limpeza de Escritórios", "Empregada de Limpeza de Edifícios e Espaços Comuns"]'::jsonb, '9112'),
  ('http://data.europa.eu/esco/occupation/3046f16d-1f7d-408f-b9a5-155410fbd2ea', 'Técnico de Engenharia Pnmeumática', 'Os técnicos de engenharia pneumática avaliam sistemas e unidades pneumáticos em funcionamento, como as máquinas de ar comprimido, e recomendam alterações para uma maior eficiência. Estão igualmente envolvidos na concepção de sistemas e componentes pneumáticos, como os circuitos.', 'released', '["Técnico de Engenharia Pneumática", "Técnica de Engenharia Pneumática", "Técnica de Engenharia Pnmeumática"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/30641348-f9f2-4fe5-ab8c-fe6ff9931a54', 'Técnico de Equipamentos Médicos', 'Os técnicos de equipamentos médicos colaboram com os engenheiros de equipamentos médicos na concepção, no desenvolvimento e na produção de sistemas, instalações e equipamentos medicotécnicos, como estimuladores cardíacos (pacemakers), máquinas de IRM e dispositivos de raios X. Constroem, instalam, inspecionam, modificam, reparam, calibram e efetuam a manutenção de equipamentos medicotécnicos e de sistemas de suporte. Os técnicos de equipamentos médicos são responsáveis pela prontidão operacional, pela utilização segura, pela operação econômica e pela aquisição adequada de equipamentos e de instalações médicas nos hospitais.', 'released', '["Técnico de Equipamentos Médicos", "Técnico na Área da Saúde", "Técnica na Área da Saúde", "Técnica de Equipamentos Médicos"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/306e9867-cf55-446f-88c6-8adad5369f8c', 'Professor de Ciências Naturais', 'Os professores de Ciências Naturais são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências Naturais, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio das Ciências Naturais, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Geociências", "Professor de Geologia", "Professor de Geociências", "Professora de Geografia", "Professora de Geologia", "Professora de Ciências Naturais", "Professor de Ciências Naturais", "Professor Universitário de Ciências Naturais", "Professor de Geografia", "Professora Universitára de Ciências Naturais"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/30739eb6-218b-4e8a-9209-e2f36b9446cd', 'Assistente de Guarda-Roupa', 'Os assistentes de guarda-roupa ajudam a vestir os atores e os figurantes. Devem certificar-se de que tudo esteja como o designer de guarda-roupa visualizou e assegurar a continuidade do aspeto dos artistas. Os assistentes de guarda-roupa procedem à manutenção e reparação do guarda-roupa. Guardam-no de forma correta e segura depois das filmagens.', 'released', '["Assistentea de Guarda-Roupa"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/30870ea4-5e8e-4b92-a9d5-65e3b97a9b30', 'Encarregado de Armazém de Matérias-Primas', 'Os encarregados de armazém de matérias-primas organizam e controlam a recepção e o armazenamento das matérias-primas no armazém, de acordo com as condições exigidas. Controlam os níveis das existências.', 'released', '["Encarregada de Armazém de Matérias-Primas", "Encarregado de Armazém de Matérias-Primas"]'::jsonb, '4321'),
  ('http://data.europa.eu/esco/occupation/30aef4c6-49ca-4464-bf82-78ed88b3eb9b', 'Projetista de Engenharia Civil', 'Os projetistas de engenharia civil desenham e elaboram esboços de projetos de arquitetura de diferentes tipos, de mapas topográficos ou para a reconstrução de estruturas existentes, para engenheiros civis e arquitetos. Incluem nos desenhos/esboços todas as especificações e requisitos, como os matemáticos, estéticos, de engenharia e técnicos.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/30b25ee4-da97-4167-8592-460217f6bdcc', 'Diretor de Animação', 'Os diretores de animação supervisionam e recrutam artistas multimédia. São responsáveis pela qualidade da animação, e asseguram que a produção é entregue dentro do prazo e do orçamento.', 'released', '["Diretor de Animação", "Diretora de Animação"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/30c0943c-caa1-411d-b273-26f475971273', 'Engenheiro de Qualidade', 'Os engenheiros de qualidade definem normas de qualidade para a criação de produtos ou serviços. Verificam se os produtos e serviços estão em conformidade com as normas de qualidade e coordenam melhorias da qualidade.', 'released', '["Engenheira de Qualidade", "Engenheiro de Qualidade"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/30ca97f4-a4fd-4189-a781-ac08f6b09b78', 'Analista de Centro de Atendimento', 'Os analistas de centros de atendimento analisam os dados relativos às chamadas efetuadas ou recebidas pelos clientes. Elaboram relatórios e visualizações.', 'released', '["Analista de Centro de Atendimento", "Analista de Call Centre", "Analista de Centro de Chamadas", "Analista de Centro Telefônico de Atendimento", "Analista de Call Center"]'::jsonb, '3341'),
  ('http://data.europa.eu/esco/occupation/30cdbb0a-4f62-4d0e-811c-72e3f95d017b', 'Operador de Nitração', 'Os operadores de nitração acompanham e controlam o equipamento que processa as substâncias químicas para produzir explosivos. São responsáveis pela armazenagem do produto em tanques.', 'released', '["Operadora de Nitração", "Operador de Nitração"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/30ed83ba-cc89-4d9f-a59d-5c783c1da56e', 'Criador de Páginas Web', 'Os criadores de páginas Web são responsáveis pela criação dos elementos visuais, da paginação e de outros aspetos, como a facilidade de utilização de um site. Acompanham as diferentes fases de criação de um site, desde a concepção até à sua implementação e publicação. Trabalham lado a lado com programadores de primeira linha para conceber interfaces de usuário que satisfaçam as necessidades dos clientes e sejam apelativas. São responsáveis pelo desenvolvimento de maquetas e pela confirmação da viabilidade técnica do produto. Podem utilizar e reunir vários tipos de elementos para o site, incluindo gráficos, animações, texto, vídeos e fotografias. Estão em contato com os clientes e as partes interessadas da empresa para garantir que a concepção do site satisfaz as suas necessidades.', 'released', '["Criador de Páginas Web", "Criadora de Páginas Web"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/30f3ea93-882a-4525-841c-1d5b4b64076f', 'Diretor Financeiro', 'Os diretores financeiros tratam todas as questões relacionadas com o financiamento e os investimentos de uma empresa. Gerem operações financeiras das empresas como os ativos, os passivos, o capital próprio e os fluxos de caixa destinados a manter a saúde financeira da empresa e a viabilidade operacional. Os diretores financeiros avaliam os planos estratégicos da empresa em termos financeiros, mantêm operações financeiras transparentes em relação aos organismos fiscais e de auditoria e criam as demonstrações financeiras da empresa no final do exercício orçamental.', 'released', '["Gerente Financeira", "Diretora Financeira", "Diretor Financeiro", "Gerente Financeiro", "Diretora Financeiro"]'::jsonb, '1211'),
  ('http://data.europa.eu/esco/occupation/310ad9e0-ffc9-4980-b47c-1e856a404eff', 'Operador de Destilação de Petróleo', 'Os operadores de destilação de petróleo gerem e supervisionam o processo de destilação do petróleo e prestam assistência na resolução de avarias. Operam equipamento de destilação de petróleo para separar os produtos intermédios ou as impurezas do petróleo. Rodam válvulas de controlo e indicadores para atingir temperaturas, débito de materiais, pressão, etc.', 'released', '["Operador de Destilação", "Operadora de Destilação", "Operadora de Destilação de Petróleo"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/31308b0c-a298-4802-a052-4020d22bad57', 'Operador de Máquina de Soldadura por Onda', 'Os operadores de máquina de soldadura por onda instalam e operam máquinas para soldar componentes eletrônicos na placa de circuitos impressos. Interpretam os esquemas e desenhos de concepção.', 'released', '["Operador de Máquina de Soldadura por Onda", "Operadora de Máquina de Soldadura por Onda"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/316309e4-5fce-4dca-85d1-07702217ea19', 'Diretor de Produção de Curtumes', 'Os diretores de produção de curtumes planificam todos os aspetos do processo de produção de couro. Asseguram a produção necessária da fábrica em termos de qualidade e quantidade de couro. Organizam o pessoal de produção. Controlam e asseguram o funcionamento das máquinas e equipamentos. Cooperam com os diretores de cada departamento de produção.', 'released', '["Diretora de Produção de Curtumes", "Diretor de Produção — Indústria de Curtumes"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/31808988-fc0a-4bc3-9e47-27216d6759f5', 'Guarda', 'Os guardas observam, detectam irregularidades e protegem pessoas, edifícios e bens. Mantêm sempre a segurança, patrulhando as zonas designadas das propriedades, controlando o acesso nas entradas, observando sistemas de alarme e de gravação de vídeo, solicitando a identificação a pessoas suspeitas e comunicando infrações e violações da lei.', 'released', '["Vigilante"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/31854d78-3615-43a4-aa3a-c597ecb20ceb', 'Conselheiro Jurídico', 'Os conselheiros jurídicos prestam aconselhamento a um conjunto variado de clientes, que incluem desde empresas e particulares até sociedades de advocacia. Prestam aconselhamento jurídico fora das salas de audiências no domínio dos assuntos jurídicos, que dependem da natureza do cliente. Aconselham em matérias como a fusão de multinacionais, a aquisição de habitação, a alteração de contratos e as suas implicações. Ajudam os clientes, de um modo geral, a cumprir a regulamentação e a evitar cometer atos ilícitos.', 'released', '["Conselheira Jurídica", "Conselheiro Jurídico", "Jurisperita", "Jurisperito", "Jurista", "Jurisconsulta", "Jurisconsulto", "Conselheira Jurídico"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/319f9864-7f13-4b0c-a827-d50295e239ad', 'Técnico de Transferência Embrionária Animal', 'Os técnicos de transferência embrionária animal prestam assistência na transferência de embriões sob supervisão veterinária, em conformidade com a legislação nacional.', 'released', '["Técnica de Transferência de Embriões", "Técnico de Transferência Embrionária Animal", "Técnico de Transferência de Embriões", "Técnica de Transferência Embrionária Animal"]'::jsonb, '3240'),
  ('http://data.europa.eu/esco/occupation/31cc4199-703c-4f8a-9b46-a2070a6d35df', 'Técnico de Biologia', 'Os técnicos de biologia prestam assistência técnica na investigação e na análise da relação entre os organismos vivos e o seu ambiente. Utilizam equipamentos de laboratório para examinar substâncias orgânicas como os fluidos corporais, os medicamentos, as plantas e os alimentos. Recolhem e analisam dados para fins de experiências, elaboram relatórios e mantêm as existências do material de laboratório.', 'released', '["Técnico de Biologia", "Técnica de Biologia"]'::jsonb, '3141'),
  ('http://data.europa.eu/esco/occupation/31d0e6b8-64ae-4b04-b988-dbee03a4aaa9', 'Médium', 'Os médiuns atuam como comunicadores entre o mundo natural e o mundo espiritual. Transmitem declarações ou imagens que alegam ter sido fornecidas por espíritos e que podem ter um significado pessoal e muitas vezes privado para o cliente.;', 'released', '["Espírita"]'::jsonb, '5161'),
  ('http://data.europa.eu/esco/occupation/31db6bd9-ee84-4a57-ac9e-87e243ba1c69', 'Auxiliar de Armazém de Produtos de Marroquinaria', 'Os empregados de armazém de produtos de marroquinaria são responsáveis pelo armazém do couro, pelos componentes, pelos outros materiais e dispositivos de produção. Procedem à classificação e ao registo das matérias-primas e dos componentes comprados, bem como às previsões de compras e à sua distribuição pelos diferentes serviços. Garantem que todas as matérias-primas e componentes necessários para a produção estejam prontos a ser utilizados e a ser colocados na cadeia de produção.', 'released', '["Empregado de Armazém de Produtos de Marroquinaria", "Empregada de Armazém de Produtos de Marroquinaria"]'::jsonb, '4321'),
  ('http://data.europa.eu/esco/occupation/31f49d76-b2e4-4313-aeba-90650258dda9', 'Especialista em Import-Export de Madeira e Materiais de Construção', 'Os especialistas em import-export de madeira e materiais de construção possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Madeira e Materiais de Construção"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/3206f826-7d53-4180-9797-e94ad9eaf841', 'Técnico de Aquicultura em Gaiola', 'Os técnicos de aquicultura em gaiola são responsáveis pela produção de organismos aquáticos em processos de engorda de flutuação ou submersão (água doce, água salobra, água salgada) em gaiolas.', 'released', '["Técnica de Aquicultura em Gaiola", "Técnico de Aquicultura em Gaiola", "Técnico de Aquicultura", "Técnica de Aquicultura"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/322635c9-3d93-4280-a359-0b693df21e93', 'Especialista em Import-Export de Matérias-Primas Agrícolas, Sementes e Rações Animais', 'Os especialistas em import-export de matérias-primas agrícolas, sementes e rações animais possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Matérias-Primas Agrícolas, Sementes e Rações Animais"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/32548f7e-8c25-4c49-9f22-78dee3543704', 'Engenheiro de Minas e Geo-Ambiente', 'Os engenheiros de minas e geo-ambiente supervisionam o desempenho ambiental das operações mineiras. Desenvolvem e implementam sistemas e estratégias ambientais para minimizar os impactos ambientais.', 'released', '["Engenheiro de Minas e Geo-Ambiente", "Engenheira de Minas e Geo-Ambiente"]'::jsonb, '2143'),
  ('http://data.europa.eu/esco/occupation/3256e283-0892-4330-b9f2-6dc4aa4bd86b', 'Operador de Refinação de Açúcar', 'Os operadores de refinação de açúcar asseguram o correto funcionamento e controlam o equipamento de refinação para produzir açúcares e produtos afins a partir de açúcar bruto ou de outras matérias-primas, tais como o amido de milho.', 'released', '["Operador de Máquina de Refinação de Açúcar", "Operador de Refinação de Açúcar", "Operadora de Máquina de Refinação de Açúcar", "Operadora de Refinação de Açúcar"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/326027fc-5408-47cd-9b32-fbe770dbbe80', 'Responsável de Controle da Qualidade na Construção', 'Os responsáveis de controlo da qualidade na construção asseguram que a qualidade do trabalho cumpre as normas estabelecidas no contrato, bem como normas legislativas mínimas. Estabelecem procedimentos para verificar a qualidade, realizam inspeções e propõem soluções para insuficiências em matéria de qualidade.', 'released', NULL, '3112'),
  ('http://data.europa.eu/esco/occupation/3288a2fe-4934-47c8-ad0b-11b16c9cd461', 'Inspetor de Instalações', 'Os inspetores de instalações examinam produtos, sistemas e máquinas, como as turbinas das redes de esgotos, hidráulicas, a gás ou elétricas, garantindo que estão construídos e a funcionar em conformidade com a regulamentação. Elaboram relatórios de inspeção e formulam recomendações para melhorar os sistemas e reparar os componentes danificados.', 'released', '["Inspetor de Instalações", "Inspetora de Instalações"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/32ac76f6-20a0-469e-8cac-e68634087dd3', 'Arquivista de Imagens e Administrador de Sistemas de Comunicação', 'Os arquivistas de imagens e administradores de sistemas de comunicação gerem os sistemas de arquivo e comunicação de imagens (PACS). Armazenam as imagens obtidas por vários tipos de equipamentos médicos, como as radiografias, a fim de facilitar o acesso a estas imagens para fins médicos. Os administradores de PACS asseguram a gestão e a manutenção diárias do sistema.', 'released', '["Arquivista de Imagens e Administradora de Sistemas de Comunicação", "Arquivista de Imagens e Administrador de Sistemas de Comunicação"]'::jsonb, '3252'),
  ('http://data.europa.eu/esco/occupation/32ef07df-1b0a-439a-916e-8289eb9f4895', 'Técnico Dentário Equino', 'Os técnicos dentários equinos prestam cuidados dentários de rotina a equídeos, utilizando equipamento adequado em conformidade com a legislação nacional.', 'released', '["Dentista Equino", "Técnico Dentário Equino", "Técnica Dentária Equina", "Dentista Equina", "Técnica Dentário Equino"]'::jsonb, '3240'),
  ('http://data.europa.eu/esco/occupation/32fafe2c-0099-4852-889e-46614ce9a9ae', 'Gestor de Crédito', 'Os gestores de crédito supervisionam a aplicação da política de crédito no banco. Decidem os limites de crédito a impor, os níveis razoáveis de risco aceites e as condições e modalidades de pagamento aos clientes. Controlam a cobrança de pagamentos dos seus clientes e gerem o departamento de crédito de um banco.', 'released', '["Gestor de Crédito", "Gestora de Crédito", "Gerente"]'::jsonb, '3312'),
  ('http://data.europa.eu/esco/occupation/32fcdc6f-1c8a-44e9-99b8-5519e4db4414', 'Técnico de Impressão Têxtil', 'Os técnicos de impressão têxtil efetuam operações relacionadas com a preparação dos processos de impressão.', 'released', '["Técnica de Impressão Têxtil", "Técnico de Impressão Têxtil"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/3327a087-cd36-4b02-ac1b-6455f59f9312', 'Guarda Prisional', 'Os guardas prisionais supervisionam os reclusos num estabelecimento prisional e asseguram a segurança e a manutenção da paz na instalação. Realizam controlos e revistas para assegurar o cumprimento dos regulamentos, controlam as visitas e as atividades dos reclusos, bem como participam em programas de reabilitação e asseguram a manutenção dos registos.', 'released', NULL, '5413'),
  ('http://data.europa.eu/esco/occupation/336cf331-8082-4a0c-bf5f-e7c54706211c', 'Mecânico de Bicicletas', 'Os mecânicos de bicicletas procedem à manutenção e reparação de uma variedade de modelos de bicicletas e de componentes. Podem efetuar alterações personalizadas, de acordo com as preferências do cliente.', 'released', '["Mecânica de Velocípedes", "Mecânico de Motociclos", "Mecânico de Bicicletas", "Mecânica de Motociclos", "Mecânica de Bicicletas", "Mecânico de Velocípedes"]'::jsonb, '7234'),
  ('http://data.europa.eu/esco/occupation/33960bab-4423-4808-af6c-ec2b485dba41', 'Eletricista de Edifício', 'Os eletricistas de edifícios procedem à instalação e manutenção de cabos elétricos e outras infraestruturas elétricas em edifícios. Certificam-se de que os equipamentos elétricos instalados estão isolados e não apresentam qualquer perigo de incêndio. Compreendem as situações existentes e procedem a melhorias, se necessário.', 'released', NULL, '7411'),
  ('http://data.europa.eu/esco/occupation/33ae2ba9-9835-410f-8ea6-e5ac991f5975', 'Monge/Freira', 'Os monges/freiras dedicam-se a um estilo de vida monástico. Fazem voto de participar em trabalhos espirituais como parte da sua comunidade religiosa. Os monges/freiras participam na oração diária e vivem frequentemente em mosteiros ou conventos autossuficientes juntamente com outros monges/freiras.', 'released', '["Freira", "Monge"]'::jsonb, '3413'),
  ('http://data.europa.eu/esco/occupation/33cd8ff4-62f2-4a3f-b053-6e009ecef6da', 'Especialista em Import-Export de Carne e Produtos à Base de Carne', 'Os especialistas em import-export de carne e produtos à base de carne possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Carne e Produtos à Base de Carne"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/33da5532-8c4e-4d1b-b52e-c201ee1bc7ab', 'Terapeuta Ocupacional', 'Os terapeutas ocupacionais prestam assistência a indivíduos ou a grupos com limitações ocupacionais devido a doenças, perturbações físicas e perturbações mentais temporárias ou permanentes, para recuperarem a sua capacidade de realizar atividades diárias. Asseguram o tratamento e a reabilitação para lhes permitir participar ativamente na sociedade, viver a vida como desejam e realizar as atividades que lhes interessam. Os terapeutas ocupacionais trabalham em serviços públicos de saúde e cuidados sociais, mas podem também participar em atividades de apoio a requerentes de asilo, refugiados e pessoas sem-abrigo.;', 'released', '["Terapeuta Corporal e de Reabilitação", "Ergoterapeuta"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/33e3a746-f209-4a1a-96df-301505531cb2', 'Diretor de Salão de Beleza', 'Os diretores de salão de beleza supervisionam as operações diárias e a gestão do pessoal num salão de beleza. Asseguram a satisfação do cliente, o controlo orçamental e a gestão do inventário. Os gestores de salão de beleza criam e aplicam as regras e as orientações relativas à limpeza. São também responsáveis pela promoção do salão para atrair novos clientes.', 'released', '["Diretor de Salão de Beleza", "Diretora de Salão de Cabeleireiro", "Gestor de Salão de Beleza", "Diretor de Salão de Cabeleireiro", "Gestora de Salão de Beleza", "Diretora de Salão de Beleza", "Gerente de Salão de Beleza", "Gerente de Salão de Cabeleireiro"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/33e4f026-a823-4ffc-99e4-60d3fe597a1e', 'Testador de Jogos Digitais', 'Os testadores de jogos digitais reveem e testam vários tipos de jogos digitais jogando-os, a fim de detetarem erros e falhas a nível das funcionalidades ou do grafismo dos jogos. Podem avaliar a capacidade de atração e de jogabilidade dos jogos. Podem igualmente realizar a depuração de erros nos jogos propriamente ditos.', 'released', '["Testador de Videogames", "Testadora de Videogames", "Responsável por Testes de Jogos Digitais", "Testadora de Jogos Digitais", "Testador de Jogos Virtuais", "Testadora de Jogos Virtuais", "Responsável Pelos Testes de Jogos Digitais", "Testador de Jogos Digitais"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/33fe4c90-c4fd-4860-bdc5-24fcab16f45a', 'Técnico de Controle de Qualidade Alimentar', 'Os técnicos de controlo de qualidade alimentar realizam testes normalizados para determinar as características químicas, físicas ou microbiológicas dos produtos destinados ao consumo humano.', 'released', '["Técnica de Análise de Alimentos", "Técnico de Análise de Alimentos", "Analista Alimentar", "Técnica de Controle de Qualidade Alimentar", "Técnico de Controle de Qualidade Alimentar"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/340b04fd-6312-47e5-80ff-28222a343864', 'Técnico de Engenharia das Pescas', 'Os técnicos de engenharia das pescas efetuam a manutenção e a reparação de máquinas e equipamentos nos porões de peixe e no sistema de refrigeração a bordo dos navios de pesca.', 'released', '["Técnico de Refrigeração em Navios de Pesca", "Técnica de Refrigeração em Navios de Pesca", "Técnico de Engenharia das Pescas", "Técnica de Engenharia das Pescas"]'::jsonb, '3151'),
  ('http://data.europa.eu/esco/occupation/3413f234-6230-47a8-8cc7-2691fd54ce3a', 'Auxiliar de Cuidados à Infância', 'Os auxiliares de cuidados à infância prestam cuidados às crianças quando os pais ou familiares não estão disponíveis. Têm em conta as necessidades básicas das crianças e ajudam-nas ou supervisionam-nas enquanto brincam. Os auxiliares de cuidados à infância podem trabalhar em pré-escolas, centros de dia, serviços de acolhimento de crianças ou famílias individuais.', 'released', NULL, '5311'),
  ('http://data.europa.eu/esco/occupation/3417aab3-8b87-4c3b-bee6-be03fe05be2b', 'Operador de Tufagem', 'Os operadores de tufagem supervisionam o processo de tufagem de um grupo de máquinas, supervisionando a qualidade dos tecidos e as condições de colocação dos tufos. Procedem à inspeção das máquinas de tufagem, após a sua instalação, colocação em funcionamento e durante a produção, para garantir que o produto a ser tufado cumpre as especificações e normas de qualidade.', 'released', '["Operador de Tufagem", "Operadora de Tufagem"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/341b405b-12cd-4ece-9b4b-cbfae3551ea3', 'Projetista de Automóveis', 'Os projetistas de automóveis convertem os projetos de engenheiros de automóveis em desenhos técnicos, utilizando geralmente software. Os seus desenhos pormenorizam as dimensões, os métodos de fixação e montagem e outras especificações utilizados no fabrico de componentes para automóveis, ônibus, caminhões e outros veículos a motor.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/3469cbcc-5332-41dc-977a-29cf1b7ef7be', 'Recepcionista de Estabelecimentos de Saúde', 'Os rececionistas de estabelecimentos de saúde recebem os clientes e os doentes quando estes chegam ao estabelecimento de saúde e registam-nos, recolhem as observações do doente e proceder a marcações sob a supervisão e a direção do diretor de instituição de cuidados de saúde.', 'released', NULL, '4226'),
  ('http://data.europa.eu/esco/occupation/34852729-a2f6-4063-aa90-18b3d16754f7', 'Chefe de Departamento Universitário', 'Os chefes de departamento universitário lideram e gerem o departamento da sua disciplina em que são dirigentes académicos e trabalham com o decano da faculdade e com outros chefes de departamento para realizar os objetivos estratégicos acordados e os objetivos estratégicos da universidade. Desenvolvem e apoiam a liderança académica no seu departamento e lideram a atividade empresarial com vista à criação de rendimentos, promovendo a reputação e os interesses do seu departamento na universidade e numa comunidade mais vasta no seu domínio.', 'released', '["Chefe de Departamento Académico", "Chefea de Departamento Universitário"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/349ee6f6-c295-4c38-9b98-48765b55280e', 'Engenheiro de Computação na Cloud', 'Os engenheiros de computação na cloud são responsáveis pela concepção, planejamento, gestão e manutenção de sistemas baseados na cloud. Desenvolvem e implementam aplicações de computação na cloud, tratam da migração das aplicações existentes nas instalações para a cloud e depuram pilhas de software na cloud.;', 'released', '["Engenheiro de Infraestrutura em Cloud", "Engenheira de Segurança em Cloud", "Engenheiro de Software em Cloud", "Engenheira de Computação em Cloud", "Engenheiro de Computação em Cloud", "Engenheiro de Solução em Cloud", "Desenvolvedora de Cloud", "Engenheira Nativo da Cloud", "Desenvolvedor de Cloud", "Engenheira de Solução em Cloud", "Arquiteta de Cloud", "Engenheiro Nativo da Cloud", "Engenheira de Cloud Híbrida", "Engenheira de Cloud Devops", "Engenheiro de Rede em Cloud", "Engenheira de Software em Cloud", "Engenheira de Rede em Cloud", "Arquiteto de Cloud", "Engenheiro de Cloud Híbrida", "Engenheira de Infraestrutura em Cloud", "Engenheiro de Cloud Devops", "Engenheiro de Segurança em Cloud", "Engenheira de Computação na Cloud"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/34b63359-faad-4d6a-9d4d-98c2c15b9fac', 'Operador de Prensa de Cacau', 'Os operadores de prensa de cacau asseguram o correto funcionamento de uma ou mais prensas hidráulicas para eliminar as quantidades especificadas de manteiga de cacau (óleo natural de grão de cacau) do licor de chocolate.', 'released', '["Operadora de Prensa de Cacau", "Operador de Prensa de Cacau", "Prensadora de Cacau", "Prensador de Cacau"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/34c191ec-e3e3-4746-ae10-7ff4306a2794', 'Operador de Secagem de Sabão', 'Os operadores de secagem de sabão procedem ao controlo e manutenção da máquina de sabão viscoso para produzir flocos de sabão. Realizam testes de amostragem e coordenam a descarga dos flocos secos em recipientes de armazenagem.', 'released', '["Operadora de Secagem de Sabão", "Operador de Secagem de Sabão"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/34c57104-ff9b-4003-809e-56eece3cb4d5', 'Designer de Joias', 'Os designers de joias utilizam uma variedade de materiais, incluindo ouro, prata e pedras preciosas para conceber e planear peças de joalharia que podem ter uma finalidade acessória ou decorativa. Estão envolvidos nas diferentes fases do processo de fabrico e podem realizar criações para clientes individuais ou para clientes em massa.', 'released', '["Designer de Joalharia", "Criadora de Jóias", "Criador de Jóias"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/34e1c889-0fd1-4d1f-aba9-3b6263ae667a', 'Cenógrafo', 'Os cenógrafos procedem à construção, preparação, adaptação e manutenção dos elementos cénicos utilizados em palco e para filmagens de filmes ou de programas de televisão. Utilizam uma grande variedade de materiais, tais como madeira, aço, alumínio e plástico. O seu trabalho baseia-se na visão artística, em modelos construídos à escala, esboços e planos. Trabalham em estreita colaboração com os designers e podem construir stands de exposição para feiras, exposições e outros eventos.', 'released', '["Cenógrafo", "Cenógrafa"]'::jsonb, '3432'),
  ('http://data.europa.eu/esco/occupation/34ec79d0-85fb-445a-a5f2-df51b70c6375', 'Cortador de Carnes', 'Os cortadores de carnes abatem animais e processam as carcaças para subsequente transformação e distribuição.', 'released', '["Magarefe", "Matadora de Criação", "Cortadora de Carnes", "Matador de Criação", "Cortador de Carnes"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/351a0eb0-a1d0-49bd-a2f8-6dc447ddf316', 'Gestor de Aspectos Ambientais em Projetos de Gasoduto', 'Os gestores de aspetos ambientais em projetos de gasoduto asseguram a preservação do ambiente em projetos de transporte por gasodutos. Em conjunto com um grupo de gestores e especialistas, analisam as instalações e as rotas das condutas, a fim de prestar aconselhamento sobre questões ambientais que necessitam de consideração e resposta.', 'released', '["Gestor de Aspectos Ambientais em Projetos de Gasoduto", "Gestora de Aspectos Ambientais em Projetos de Gasoduto", "Analista de Impacto Ambiental de Projetos de Gasoduto", "Gerente"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/35291723-dc32-4a7f-a9f0-39c0e5fd96dd', 'Operador de Máquinas de Fabricação de Fibras Têxteis Sintéticas', 'Os operadores de máquinas fabrico de fibras têxteis sintéticas realizam operações de tratamento de fibras ou de filamentos.', 'released', '["Operadora de Máquinas de Fabricação de Fibras Têxteis Sintéticas", "Operadora de Máquinas de Fiação de Fibras Sintéticas", "Operador de Máquinas Fabricação de Fibras Têxteis Sintéticas", "Operador de Máquinas de Fiação de Fibras Sintéticas"]'::jsonb, '8151'),
  ('http://data.europa.eu/esco/occupation/3530b443-d2bf-4741-b771-12c77e7c6232', 'Distribuidor de Filmes', 'Os distribuidores de filmes são responsáveis pela coordenação da distribuição filmes e séries televisivas. Além disso, supervisionam a venda desses filmes em DVD, Blu Ray e noutros suportes.', 'released', '["Distruidor de Filmes", "Distruidora de Filmes", "Distribuidora de Filmes"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/353a22a7-1c55-410c-a7a7-c531692b5e50', 'Instalador de Janelas', 'Os instaladores de janelas colocam janelas em estruturas e fazem a manutenção das mesmas. Retiram as janelas antigas, se estiverem presentes, preparam a abertura, instalam janela no sítio, direita, reta, prumada e estanque, se tal for necessário.', 'released', '["Montador de Janelas", "Instalador de Janelas", "Montadora de Janelas", "Instaladora de Janelas"]'::jsonb, '7115'),
  ('http://data.europa.eu/esco/occupation/353c19d6-62d6-4dfc-85e9-f59d219d457c', 'Juiz do Supremo Tribunal de Justiça', 'Os juízes do Supremo Tribunal de Justiça presidem a tribunais superiores que tratam de processos penais e civis complexos. Analisam o caso durante o processo de julgamento, a fim de formularem uma sentença ou de orientarem um júri para chegar a uma conclusão, e decidem sobre a aplicação da pena caso a parte infratora seja considerada culpada. Decidem em matéria de processos e asseguram que o julgamento é realizado de forma justa, em conformidade com a legislação.', 'released', '["Juiz do Supremo Tribunal de Justiça", "Juíza do Supremo Tribunal de Justiça"]'::jsonb, '2612'),
  ('http://data.europa.eu/esco/occupation/35553663-deab-4d9a-bf22-15c1625d28e8', 'Engenheiro de Inteligência Artificial', 'Os engenheiros de inteligência artificial aplicam métodos de inteligência artificial em engenharia, robótica e informática para conceber programas que simulam a inteligência, incluindo modelos de pensamento, sistemas cognitivos e baseados no conhecimento, resolução de problemas e tomada de decisões. Integram também conhecimentos estruturados em sistemas informáticos (ontologias, bases de conhecimentos), a fim de resolver problemas complexos que normalmente exigem um nível elevado de especialização humana ou de métodos de inteligência artificial.', 'released', '["Engenheira de Tecnologias da Web Semântica", "Engenheiro de Tecnologias da Web Semântica", "Designer de Sistemas Inteligentes", "Designer de Sistemas de IA", "Criador de Sistemas de Inteligência Artificial", "Criadora de Sistemas de IA", "Designer de Sistemas de Inteligência Artificial", "Criadora de Sistemas de Inteligência Artificial", "Criador de Sistemas de IA", "Engenheira de Inteligência Artificial", "Engenheiro de Inteligência Artificial"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/356227b9-2263-4dbd-81e9-7dfc6d3f3af7', 'Especialista em Marketing Digital', 'Os especialistas em marketing digital utilizam o correio eletrônico, a Internet e as redes sociais para o marketing de produtos e marcas.', 'released', '["Especialista em Marketing Digital e e-Business", "Marketing Digital"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/3562e70c-016c-455c-b949-521a367418a5', 'Fazedor de Malha', 'Os fazedores de malha criam têxteis ou tecidos tricotando peças de malha. Utilizam técnicas tradicionais para criar circuitos de interligação de fios que formam um tecido uniforme. Os fazedores de malha utilizam diferentes técnicas, agulhas e materiais de fio para criar materiais de malha de proporções diversas.', 'released', '["Fazedora de Renda", "Fazedor de Renda", "Fazedora de Malha"]'::jsonb, '7318'),
  ('http://data.europa.eu/esco/occupation/3594efa8-cd69-411e-a345-d88ba756b758', 'Calibrador de Pasta', 'Os calibradores de pasta calibram a pasta de papel com base numa série de critérios possíveis, tais como o processo de produção de pasta, as matérias-primas, os métodos de branqueamento, o rendimento e o comprimento das fibras.', 'released', '["Calibrador de Pasta", "Calibradora de Pasta"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/35bc3847-58ad-46f5-8921-e58acc2762a6', 'Técnico de Engenharia Química', 'Os técnicos de engenharia química transformam matérias-primas para o desenvolvimento e o ensaio de produtos químicos. Também trabalham no sentido de melhorar as operações e os processos de instalações químicas.', 'released', '["Técnica de Engenharia Química", "Técnico de Engenharia Química"]'::jsonb, '3116'),
  ('http://data.europa.eu/esco/occupation/35bedc78-1c15-4db7-9c6d-c55e9b5c7b54', 'Programador de Eventos Artísticos', 'Os programadores de eventos artísticos são responsáveis pelo programa artístico de um espaço (teatro, centro cultural, sala de concertos, etc.) ou de ambientes temporários (festivais). Seguem as tendências artísticas e os novos artistas, mantêm o contato com os agentes para construírem um programa coerente e incentivarem a criação artística. Tudo isto acontece dentro dos limites do âmbito artístico e financeiro da organização em que estão envolvidos. ;', 'released', '["Programadora de Eventos Artísticos", "Programador de Eventos Artísticos", "Desenvolvedor"]'::jsonb, '3332'),
  ('http://data.europa.eu/esco/occupation/35cf772d-bbc9-4eb4-9ca6-5f982649d436', 'Engenheiro Especialista em Tecnologia da Madeira', 'Os engenheiros especialistas em tecnologia da madeira desenvolvem materiais e componentes em madeira, constroem instalações de produção e controlam e monitorizam a produção. Além disso, examinam produtos e materiais e aconselham os clientes.', 'released', '["Engenheira Especialista em Tecnologia da Madeira", "Engenheiro Especialista em Tecnologia da Madeira"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/35d41f4f-334b-452e-9e31-99f376302493', 'Engenheiro Especialista em Sistemas Optoeletrônicos', 'Os engenheiros especialistas em sistemas optoeletrónicos concebem e desenvolvem sistemas e dispositivos optoeletrónicos, como sensores UV, fotodíodos e LED. A engenharia optoeletrónica combina a engenharia ótica com a engenharia eletrônica na concepção desses sistemas e dispositivos. Realizam atividades de investigação, realizam análises, testam os dispositivos e supervisionam a investigação.', 'released', '["Engenheiro Especialista em Sistemas Optoeletrónicos", "Engenheira Especialista em Sistemas Optoeletrónicos", "Engenheira Especialista em Sistemas Optoeletrônicos"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/35d4ab0d-5a2a-4ed8-b8ba-7169314168f5', 'Grossista de Computadores, Equipamentos Periféricos e Software', 'Os grossistas de computadores, equipamentos periféricos e software procuram potenciais compradores e fornecedores grossistas e fazem corresponder as suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', NULL, '3324'),
  ('http://data.europa.eu/esco/occupation/35e42c87-faf7-465f-abe4-f26717996dd1', 'Professor de Educação Moral e Religiosa do Ensino Secundário', 'Os professores de Educação Moral e Religiosa do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Educação Moral e Religiosa. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Educação Moral e Religiosa através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Educação Moral e Religiosa do Ensino Secundário", "Professora de Educação Moral e Religiosa do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/35e67944-231e-4bc9-8c69-560f203167ff', 'Especialista em Informação de Origem Eletromagnética', 'Os especialistas em informação de origem eletromagnética trabalham na Força Aérea na análise de informações em locais como quarteis-generais e postos de comando. Pesquisam e intercetam tráfego eletromagnético transmitido em diferentes línguas.', 'released', NULL, '0310'),
  ('http://data.europa.eu/esco/occupation/35eb0aa6-b40d-449d-9390-719be8912277', 'Técnico de Merchandising Visual', 'Os técnicos de merchandising visual são especializados na promoção da venda de mercadorias, especialmente a sua apresentação nos pontos de venda a retalho.', 'released', '["Técnico de Merchandising Visual", "Técnica de Merchandising Visual"]'::jsonb, '3432'),
  ('http://data.europa.eu/esco/occupation/35efc04c-429a-407e-a00a-f07fd03c2743', 'Técnico de Rádio', 'Os técnicos de rádio procedem à instalação, à retificação, ao ensaio, à manutenção e à reparação de equipamentos móveis de transmissão e recepção de radiocomunicações móveis ou fixos e de sistemas de radiocomunicações bidirecionais. Também vigiam o seu funcionamento e determinam as causas de falhas.', 'released', '["Operador de Rádio", "Técnica de Rádio", "Técnico de Rádio", "Operadora de Rádio"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/35f62568-eb4e-4a09-9d83-ecc73116f94c', 'Chocolateiro', 'Os chocolateiros fabricam produtos de confeitaria à base de chocolate. Exercem atividades como o exame, o tato e a prova de pasta de chocolate moído. Esta análise permite verificar se a cor, a textura e o sabor da pasta de chocolate cumprem as especificações.', 'released', '["Produtor de Chocolate", "Fabricante de Chocolate", "Chocolateira", "Produtora de Chocolate", "Chocolateiro"]'::jsonb, '7512'),
  ('http://data.europa.eu/esco/occupation/35fbb8cd-c044-49a1-850c-010481c99b4a', 'Administrador de Back Office de Mercados Financeiros', 'Os administradores de back office de mercados financeiros desempenham tarefas administrativas para todas as transações registadas na sala de mercados. Tratam de transações que envolvem valores mobiliários, derivados, divisas, mercadorias e gerem a compensação e liquidação de transações.', 'released', '["Administrador de Back Office de Mercados Financeiros", "Administradora de Back Office de Mercados Financeiros"]'::jsonb, '4312'),
  ('http://data.europa.eu/esco/occupation/36095ccd-c62d-4f1f-8af7-1fd10618b044', 'Editor de Som', 'Os editores de som criam a banda sonora e os efeitos sonoros de filmes, séries de televisão ou outras produções multimédia. São responsáveis por toda a música e som de filmes, séries ou jogos de vídeo. Os editores de som utilizam equipamento para editar e misturar imagens e gravações de som, e certificam-se de que a música, o som e o diálogo estão sincronizados com a cena e se adequam à mesma. Trabalham em estreita colaboração com o montador de filmes e vídeos.', 'released', '["Editor de Som", "Editora de Som"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/36494988-69d2-4420-9db4-eb56605ac983', 'Enfermeiro de Prática Avançada', 'Os enfermeiros de prática avançada são responsáveis por promover e restaurar a saúde dos doentes, fornecer diagnósticos e cuidados em contextos avançados, coordenar os cuidados no âmbito da gestão das doenças crônicas, prestar cuidados integrados e supervisionar os membros da equipe designados. Os enfermeiros de prática avançada são enfermeiros de cuidados gerais que adquiriram uma base de conhecimentos especializada, competências de tomada de decisões complexas e competências clínicas para práticas clínicas alargadas a nível avançado.', 'released', '["Enfermeiro de Prática Avançada", "Enfermeira de Prática Avançada"]'::jsonb, '2221'),
  ('http://data.europa.eu/esco/occupation/364cb5ca-3002-425f-b815-aefa513df78a', 'Projetista de Arquitetura', 'Os projetistas de arquitetura elaboram desenhos das especificações e das ideias fornecidas pelos arquitetos. Elaboram desenhos de arquitetura utilizando equipamento assistido por computador e software, ou utilizando métodos convencionais, como o papel e a caneta.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/364d9e9f-b14c-4905-b9e5-5de623dba268', 'Técnico de Animação Stop Motion', 'Os técnicos de animação stop motion criam animações através da utilização de marionetas ou de modelos de argila.', 'released', '["Técnico de Animação Stop Motion", "Animador Stop Motion", "Animadora Stop-Motion", "Animador Stop-Motion", "Animadora Stop Motion", "Técnico de Animação Stop-Motion", "Técnica de Animação Stop Motion"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/364e61ab-1631-4fe1-a170-e88797aad6f9', 'Sondador', 'Os sondadores instalam e operam sondas de perfuração e equipamento relacionado concebido para perfurar furos para exploração mineral, em operações com explosivos e para fins de construção.', 'released', '["Sondadora", "Sondador"]'::jsonb, '8111'),
  ('http://data.europa.eu/esco/occupation/36b11444-8634-4194-b679-ed302acdfb22', 'Operador de Máquina de Torrefação de Café', 'Os operadores de máquina de torrefação de café controlam torrefatores a gás para secar os grãos de café. Vertem os grãos de café em fornos de torrefação e, uma vez torrados, comparam a cor dos grãos de café com as especificações. Executam o arrefecimento dos grãos através de ventiladores mecânicos.', 'released', '["Torradora de Café", "Torrador de Café", "Operadora de Máquina de Torrefação de Café", "Operadora de Instalação de Torrefação de Café", "Operador de Instalação de Torrefação de Café", "Operador de Máquina de Torrefação de Café"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/371885b5-0f93-406f-b96a-58ecd5bbc3ce', 'Controlador de Qualidade de Artigos de Marroquinaria', 'Os controladores de qualidade de artigos de marroquinaria analisam os elementos visuais de artigos de marroquinaria relacionados com o aspeto, a robustez, a ausência de rugas, a retilinearidade das costuras, a limpeza e a homogeneidade das cores, em função das especificações. Também realizam testes rápidos.;', 'released', '["Controlador de Qualidade de Artigos de Marroquinaria", "Controladora de Qualidade de Artigos de Marroquinaria"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/3723d7a6-7e65-4735-8235-cb01fb661b2f', 'Operador de Máquinas de Moldagem de Pasta de Papel', 'Os operadores de máquinas de moldagem de pasta de papel asseguram o correto funcionamento da máquina que molda a pasta de papel em diversas formas, geralmente para utilizar em material de embalagem leve mas resistente, tal como caixas de ovos.', 'released', '["Operadora de Máquinas de Moldagem de Pasta de Papel", "Operador de Máquinas de Moldagem de Pasta de Papel"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/373db468-bd25-4b67-a6e0-4ac79d9a9e85', 'Trabalhador da Apanha de Fruta e Vegetais', 'Os trabalhadores da apanha de fruta e vegetais selecionam e colhem fruta, vegetais e frutos de casca rija de acordo com o método adequado para o tipo de fruta, vegetal ou fruto de casca rija.', 'released', '["Trabalhadora da Apanha de Fruta e Vegetais", "Trabalhador da Apanha de Fruta e Vegetais", "Apanhadora de Fruta e Vegetais", "Trabalhadora da Apanha de Fruta", "Trabalhador Rural da Apanha de Fruta e Vegetais", "Trabalhador da Apanha da Fruta", "Apanhador de Fruta e Vegetais", "Apanhador de Fruta", "Apanhadora de Fruta", "Trabalhadora Rural da Apanha de Fruta e Vegetais"]'::jsonb, '9211'),
  ('http://data.europa.eu/esco/occupation/37442765-f7bb-4ccd-9de1-4790296f3d37', 'Chefe de Equipe de Segurança', 'Os chefes de equipe de segurança acompanham e supervisionam as atividades dos guardas que protegem as propriedades dos atos de vandalismo e do furto. Atribuem áreas a ser patrulhadas regularmente por guardas, transferem a pessoa apanhada a invadir a propriedade para a polícia e elaboram planos e exercícios de segurança para os edifícios e os trabalhadores sob a sua supervisão.', 'released', '["Chefea de Equipe de Segurança"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/374d925a-107b-4c99-bc8b-75483441f062', 'Pintor de Arte', 'Os pintores de arte criam pinturas a óleo, em aguarela ou em pastel, miniaturas, colagens e desenhos, os quais são diretamente executados pelo artista e/ou estão totalmente sob o seu controlo.', 'released', '["Pintora de Arte", "Pintor de Arte"]'::jsonb, '2651'),
  ('http://data.europa.eu/esco/occupation/375137f7-5fc2-424e-9f63-d7ff4441c11e', 'Ourives Gravador', 'Os ourives gravadores gravam inscrições e desenhos ornamentais em artigos de joalharia, utilizando ferramentas de gravação. Esboçam e elaboram as inscrições e desenhos no artigo, cortam o desenho no artigo e limpam o mesmo.', 'released', '["Gravador", "Gravadora", "Ourives Gravador", "Ourives Gravadora", "Ourives"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/375a4d32-0950-45db-9d85-3fc2a86f1d85', 'Operador de Conversão de Amidos e Féculas', 'Os operadores de conversão de amidos e féculas controlam conversores para transformar amidos e féculas em xarope de milho. Após a transformação, testam os produtos para verificar o seu grau de pureza.', 'released', '["Operador de Conversão de Amidos e Féculas", "Operadora de Máquina de Conversão de Amidos e Féculas", "Operador de Máquina de Conversão de Amidos e Féculas", "Operadora de Conversão de Amidos e Féculas"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/3765a20d-5160-4e8f-82f1-ad7872b9db24', 'Documentalista', 'Os documentalistas são responsáveis por sistemas que fornecem informações às pessoas. Asseguram o acesso à informação em diferentes ambientes de trabalho (públicos ou privados), com base em princípios teóricos e em capacidades práticas de armazenamento, extração e comunicação de informações.', 'released', NULL, '2622'),
  ('http://data.europa.eu/esco/occupation/377865f0-c327-4599-8c7e-d428c6588edf', 'Gestor de Compras', 'Os gestores de compras são responsáveis pela compra de produtos, equipamentos e serviços para as suas empresas e tentam assegurar os preços mais competitivos. São igualmente responsáveis pela negociação dos contratos, pela análise da qualidade dos produtos e pela análise dos fornecedores, bem como pela utilização e revenda de produtos e serviços.', 'released', '["Gestor de Compras", "Gestora de Produto", "Gestor de Produto", "Gestora de Estoques", "Gestor de Estoques", "Gestora de Compras", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/379a4f3f-4985-4764-8b2f-037946da855d', 'Inspetor de Jogos', 'Os inspetores de jogos têm capacidade para lidar com e inspecionar todos os jogos respetivos e realizar todas as operações de jogo com os mais elevados padrões de eficiência, segurança e serviço ao cliente, em conformidade com os procedimentos da empresa e a legislação em vigor. A sua responsabilidade consiste em supervisionar todos os jogos disputados, e garantir o cumprimento das regras e que os jogadores não fazem batota. São responsáveis pela manutenção do equipamento e pelo tratamento de todas as questões e queixas dos clientes.', 'released', '["Inspetor de Jogos", "Inspetora de Jogos"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/37b15470-3b2d-4ae0-816c-c7c06ed15c99', 'Assistente de Biblioteca', 'Os assistentes de biblioteca ajudam o bibliotecário nas atividades correntes da biblioteca. Ajudam os clientes a encontrar os materiais que necessitam, verificam os materiais da biblioteca e repõem as prateleiras.', 'released', '["Assistentea de Biblioteca"]'::jsonb, '4411'),
  ('http://data.europa.eu/esco/occupation/37c44fdd-eff0-4e16-b459-b3a81fe663ec', 'Professor de Cursos Profissionais na Área da Restauração', 'Os professores de cursos profissionais na área da restauração formam os alunos no seu domínio de estudos especializado, a restauração, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com a restauração. Os professores de cursos profissionais na área da restauração acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da restauração através de trabalhos, testes e exames.', 'released', '["Professora de Cursos Profissionais na Área da Restauração", "Professor de Cursos Profissionais na Área da Restauração"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/37c7880e-cfee-4c41-a41b-061682fefde3', 'Talhante', 'Os talhantes encomendam, inspecionam e compram a carne para venda como produtos consumíveis de carne. Realizam atividades como o corte, o aparo, a desossa, a atadura e a trituração de carne de bovino, de suíno e de aves de capoeira. Preparam as espécies de carne referidas para consumo.', 'released', '["Trabalhador da Preparação de Carne", "Talhante", "Açougueira", "Açougueiro", "Trabalhadora da Preparação de Carne", "Cortadora de Carne", "Cortador de Carne", "Talhantea"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/37f7677a-97d1-420b-a8b0-09339472121f', 'Supervisor de Montagem de Máquinas', 'Os supervisores de montagem de máquinas monitorizam o processo de montagem de máquinas. Prestam formação e orientação aos trabalhadores na área da montagem, tendo em vista alcançar os objetivos de produção.', 'released', '["Supervisor de Montagem de Máquinas", "Supervisora de Montagem de Máquinas"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/37f92bd9-b14c-4ab5-82fb-545ba7ba3b8b', 'Diretor de Distribuição — Porcelanas e Vidros', 'Os diretores da distribuição — porcelanas e vidros planificam a distribuição de porcelanas e vidros a vários pontos de venda.', 'released', '["Diretor de Distribuição — Porcelanas e Vidros", "Diretora de Logística — Porcelanas e Vidros", "Diretora de Distribuição — Porcelanas e Vidros", "Diretor de Logística — Porcelanas e Vidros"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/381b9a17-521c-4702-b7d9-2059bbd8ce76', 'Inspetor de Qualidade de Vestuário', 'Os inspetores de qualidade do vestuário inspecionam componentes fabricados e vestuário pronto-a-vestir, a fim de os classificar em função da sua qualidade, garantindo a conformidade com as normas de qualidade e identificando defeitos ou desvios em relação às especificações. Inspecionam e testam produtos, peças e materiais para verificar se estão em conformidade com as especificações e as normas. Garantem que todo o trabalho produzido cumpre ou excede as normas de qualidade do serviço.;', 'released', '["Inspetor de Qualidade de Vestuário", "Inspetora de Qualidade de Vestuário"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/38240cc5-d1d9-4de9-9480-29c51da291eb', 'Projetista de Engenharia Mecânica', 'Os projetistas de engenharia mecânica convertem os desenhos e esboços dos engenheiros mecânicos em desenhos técnicos que especificam as dimensões, os métodos de fixação e montagem e outras especificações utilizados, por exemplo, nos processos de fabrico.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/3826cb92-27f5-40ac-8dad-70af5abd6036', 'Especialista em Política de Concorrência', 'Os especialistas em política de concorrência gerem o desenvolvimento das políticas e da legislação em matéria de concorrência a nível regional e nacional, a fim de regulamentarem a concorrência e as práticas concorrenciais, de incentivarem práticas comerciais abertas e transparentes e de protegerem os consumidores e as empresas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/38395ab3-766c-4c6c-8d96-430eff19ec8d', 'Agente de Locação de Veículos', 'Os agentes de locação de veículos representam as empresas envolvidas no financiamento de veículos, oferecendo sistemas de locação adequados e serviços adicionais relacionados com o veículo. Documentam as transações, os seguros e as prestações.', 'released', '["Agentea de Locação de Veículos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/384ed128-e86e-4dd8-96ff-b6e6657cb027', 'Inspetor Marítimo', 'Os inspetores marítimos inspecionam embarcações destinadas a operações em águas marítimas ou em mar aberto. Asseguram que as embarcações e os equipamentos cumprem os regulamentos estabelecidos pela Organização Marítima Internacional (OMI). Podem também atuar na qualidade de terceiros em matéria de revisão das instalações offshore e dos projetos de construção.', 'released', '["Inspetora Naval", "Inspetor Naval", "Inspetora Marítima", "Inspetor Marítimo", "Inspetora Marítimo"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/3880e9e8-bc2b-48d9-8afc-a0f258c1c4b0', 'Detetive da Polícia', 'Os detetives da polícia recolhem e compilam elementos de prova que os assistem na resolução de crimes. Utilizam técnicas de investigação para reunir provas e entrevistar todas as partes relacionadas com a sua linha de inquérito, e cooperam com outras divisões do departamento de polícia para reunir os elementos de prova.', 'released', '["Detetivea da Polícia"]'::jsonb, '3355'),
  ('http://data.europa.eu/esco/occupation/388155cc-7ab8-46c7-8051-aefc7b276c84', 'Árbitro', 'Os funcionários desportivos são responsáveis pela gestão das regras e leis de um desporto e pela garantia de uma competição leal, em conformidade com as regras e a legislação. A função inclui a aplicação de regras/leis durante o desporto ou a atividade, contribuindo para a saúde, a segurança e a proteção dos participantes e de terceiros durante o desporto ou a atividade, através da organização de eventos desportivos, do estabelecimento e da manutenção de relações de trabalho eficazes com os concorrentes e terceiros, e através de uma comunicação eficaz.', 'released', '["Árbitro", "Árbitra (Juíza) de Desportos", "Árbitro (Juiz) de Desportos", "Árbitra"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/38a7f453-a7f0-45d2-a74d-5b92506e4a21', 'Técnico de Hardware', 'Os técnicos de hardware colaboram com engenheiros de hardware no desenvolvimento de hardware, como placas-mãe, encaminhadores e microprocessadores. Os técnicos de hardware são responsáveis pela construção, pelo ensaio, pela monitorização e pela manutenção da tecnologia informática desenvolvida.', 'released', '["Técnico de Equipamento Informático", "Técnica de Hardware", "Técnica de Equipamento Informático", "Técnico de Hardware"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/38d9c76b-1a7b-4d65-879b-733ae7e9364e', 'Consultor Financeiro e de Investimentos', 'Os consultores financeiros e de investimentos são profissionais que prestam aconselhamento transparente aos seus clientes, recomendando soluções adequadas em matéria financeira. Aconselham os clientes sobre o investimento de fundos de pensões ou de fundos livres em valores mobiliários como ações, obrigações, fundos mutualistas e fundos cotados em bolsa. Os consultores financeiros e de investimentos prestam os seus serviços a indivíduos, agregados familiares, famílias e proprietários de pequenas empresas.', 'released', '["Consultora Financeiro e de Investimentos", "Consultor Financeiro e de Investimentos"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/38eb308f-0075-451e-9c1a-c557fd173022', 'Auxiliar de Limpeza de Parques de Diversões', 'Os empregados de limpeza de parques de diversões devem manter o parque de diversões limpo e efetuar pequenas reparações. Os empregados de limpeza de parques de diversões trabalham habitualmente à noite, quando o parque está fechado, mas a manutenção e a limpeza urgentes são efetuadas durante o dia.', 'released', '["Empregado de Limpeza de Parques de Diversões", "Empregada de Limpeza de Parques de Diversões"]'::jsonb, '9129'),
  ('http://data.europa.eu/esco/occupation/3900b684-6b4b-4133-b134-e1d129d60383', 'Representante de Serviço de Aluguel', 'Os representantes de serviço de aluguer são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/394a4bdd-7032-4d87-89a2-9d937cebdd09', 'Especialista em Política Econômica', 'Os especialistas em política econômica desenvolvem estratégias econômicas. Monitorizam aspetos econômicos como a competitividade, a inovação e o comércio. Os especialistas em política econômica contribuem para o desenvolvimento de políticas, projetos e programas econômicos. Investigam, analisam e avaliam os problemas de ordem pública e recomendam ações adequadas.', 'released', NULL, '2631'),
  ('http://data.europa.eu/esco/occupation/394bdd9b-3ee8-43a9-b943-442ce146bb21', 'Terapeuta Esportivo', 'Os terapeutas desportivos programam e supervisionam exercícios de reabilitação para indivíduos e grupos. Trabalham com indivíduos que têm doenças crônicas ou apresentam um elevado risco de desenvolvê-las. Comunicam com os profissionais de saúde sobre as condições dos participantes utilizando a terminologia médica correta e com uma compreensão das opções de tratamento padrão para as condições de um indivíduo. Os terapeutas desportivos adotam uma abordagem holística do bem-estar dos clientes, que inclui aconselhamento sobre o estilo de vida, a alimentação ou a gestão do tempo. Não têm formação médica e não é necessário ter habilitações médicas.', 'released', '["Terapeuta Esportivo", "Terapeuta Esportiva"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/39803100-c338-4f01-ad2c-085d488920ca', 'Transitário', 'Os transitários planificam e organizam os transportes de carga a nível nacional e internacional. Comunicam com os transportadores e negoceiam a melhor forma de enviar a carga ao seu destino, que pode corresponder a um único cliente ou a um ponto de distribuição. Os transitários atuam como peritos na gestão da cadeia de abastecimento. Conhecem e aplicam as regras e os regulamentos para cada tipo específico de mercadorias e comunicam as condições e os custos aos clientes.', 'released', '["Transitário", "Transitária"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/399afb40-d58b-4f4a-aa52-a0378fccaf65', 'Vendedor em Loja de Animais', 'Os vendedores em loja de animais vendem animais de companhia, alimentos para animais de companhia, acessórios, produtos para cuidados e serviços relacionados em lojas especializadas.', 'released', '["Vendedor em Loja de Animais", "Vendedora em Loja de Animais"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/39a59c5c-4338-4480-bdc8-96328a491907', 'Operador de Atrações', 'Os operadores de atrações controlam e monitorizam as atrações. Prestam os primeiros socorros e fornecem material, conforme for necessário, e reportam imediatamente ao supervisor da área. Conduzem procedimentos de abertura e encerramento em áreas designadas.', 'released', '["Operadora de Atrações", "Operador de Atrações", "Trabalhador de Parque de Diversões", "Trabalhadora de Parque de Diversões"]'::jsonb, '9629'),
  ('http://data.europa.eu/esco/occupation/39b4e367-94b5-49fe-bcd7-4b116865ca59', 'Especialista em Import-Export de Fruta e Hortaliças', 'Os especialistas em import-export de fruta e produtos hortícolas possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Fruta e Produtos Hortícolas"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/39c89133-bd2a-45db-b3eb-529b94daeeaf', 'Agente de Licenciamento', 'Os agentes de licenciamento tratam os pedidos de licença e prestam aconselhamento sobre a legislação em matéria de licenciamento. Também executam tarefas de investigação para assegurar que o requerente é elegível para a licença requerida, asseguram o pagamento atempado das taxas de licença e asseguram o cumprimento da legislação.', 'released', '["Agentea de Licenciamento"]'::jsonb, '3354'),
  ('http://data.europa.eu/esco/occupation/39d7dca7-5e0b-4308-889e-9e3d22a3cb56', 'Instrutor de Escola de Condução', 'Os instrutores de escola de condução ensinam aos condutores profissionais a forma de operar os veículos de acordo com as regras de condução. Ensinam aos seus alunos a teoria e as técnicas de conduzir e manter da melhor forma um veículo específico, e observam e avaliam a prática dos alunos. Também se centram em matérias não relacionadas com a condução, tais como o serviço ao cliente (no caso de transporte de pessoas) e a regulamentação em matéria de medidas de segurança.', 'released', '["Instrutor de Escola de Condução", "Instrutora de Condução Automóvel", "Instrutora de Escola de Condução", "Instrutor de Condução Automóvel"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/39e06c20-d262-44f9-a6a8-a0f3ba9e887c', 'Operador de Máquinas de Fabricação de Sabão', 'Os operadores de máquinas de fabrico de sabão operam equipamentos e misturadores que produzem sabão, certificando-se de que o produto final seja produzido de acordo com a fórmula especificada.', 'released', '["Operadora de Máquinas de Fabricação de Sabão", "Operador de Máquinas de Fabricação de Sabão"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/39e9fc8f-02bd-4577-b603-2dc96204ce74', 'Responsável Pela Política de Desenvolvimento Comunitário', 'Os responsáveis pela política de desenvolvimento comunitário desenvolvem planos para melhorar a qualidade de vida nas comunidades locais. Investigam e avaliam os problemas e as necessidades da comunidade, gerem os recursos e desenvolvem estratégias de execução. Comunicam com a comunidade para efeitos de investigação e informam-na sobre os planos de desenvolvimento.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/3a15ec1b-9250-41a0-9344-feb2956481b7', 'Motorista de Troleicarros', 'Os motoristas de troleicarros conduzem troleicarros ou ônibus guiados, cobram bilhetes e zelam pelos passageiros.', 'released', NULL, '8331'),
  ('http://data.europa.eu/esco/occupation/3a17bd32-8a00-47cb-82aa-2b5660cf1192', 'Vendedor de Equipamento de Audiologia', 'Os vendedores de equipamento de audiologia vendem artigos e equipamentos em lojas especializadas.', 'released', '["Vendedor Especializado em Equipamento de Audiologia", "Vendedora Especializada em Equipamento de Audiologia", "Vendedora de Equipamento de Audiologia"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/3a3fac9d-323e-4ba6-989b-0e1d44e113cc', 'Marinheiro Aprendiz', 'Os marinheiros aprendizes ocupam a posição mais baixa de uma tripulação de um navio. Constituem a mão-de-obra principal a bordo de uma embarcação, onde ajudam a operar o navio. São supervisionados pelo comandante de navio e pelo engenheiro, podendo receber instruções de quaisquer superiores.', 'released', '["Marinheiro Aprendiz", "Marinheira Aprendiz"]'::jsonb, '8350'),
  ('http://data.europa.eu/esco/occupation/3a4c4e33-ee34-4abe-ba5c-26f9037d292f', 'Diretor Comercial Regional', 'Os diretores comerciais regionais são responsáveis pelas atividades e pelo pessoal numa determinada cadeia de estabelecimentos.', 'released', '["Gerente Regional de Vendas", "Diretora Comercial Regional", "Diretora Regional de Vendas", "Diretor Regional de Vendas", "Diretor Comercial Regional", "Chefe Regional de Vendas"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/3a55bf97-a0d2-47a0-a8b3-b248d32c7969', 'Gravador de Vidro', 'Os gravadores de vidro gravam inscrições e desenhos ornamentais em artigos de vidro, utilizando ferramentas de gravação manuais. Esboçam e dispõem as inscrições e os desenhos no artigo, cortam o desenho no artigo e terminam o mesmo.', 'released', '["Gravadora de Vidro", "Gravador de Vidro"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/3a55ef85-5abf-48e2-884b-5efaf881bfb1', 'Orientador de Aprendizagem em Serviço Social', 'Os orientadores de aprendizagem em serviço social lecionam, supervisionam e avaliam os alunos de trabalho social antes, durante e após a obtenção do seu grau. Contribuem para a sua colocação e têm autoridade para recomendar alunos, com base em fundamentação adequada.', 'released', '["Orientador de Aprendizagem em Serviço Social", "Orientadora de Aprendizagem em Serviço Social"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/3a67544c-919f-4051-b812-c08e69eec3fd', 'Operador de Máquinas Modeladoras de Sabão', 'Os operadores de máquinas modeladoras de sabão controlam a máquina de compressão de sabão moído que produz formas e dimensões específicas de barras de sabão, assegurando a conformidade dos produtos com as especificações e os requisitos de qualidade.', 'released', '["Operador de Máquinas Modeladoras de Sabão", "Operadora de Máquinas Modeladoras de Sabão"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/3a75b477-e151-40fb-9909-b3641401bfed', 'Operador de Inspeção Ótica Automatizada', 'Os operadores de inspeção ótica automatizada operam máquinas automáticas de inspeção ótica para inspecionar placas de circuito impresso montadas. Interpretam esquemas e inspecionam PCI acabadas ou em processamento para detectar eventuais deficiências ou defeitos.', 'released', '["Operadora AOI", "Operador de Inspeção Ótica Automatizada", "Operadora de Inspeção Ótica Automatizada", "Operador AOI", "Operadora de Inspeção Ótica Automática", "Operador de Inspeção Ótica Automática"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/3a8a7f87-d394-42cd-804b-7a32375b90f0', 'Operador de Serra Mecânica para Metais', 'Os operadores de serra mecânica para metais instalam e operam máquinas de serrar metais para cortar o metal em excesso da peça metálica, utilizando uma lâmina dentada, ou várias. Também aparam as formas acabadas de cortar em metal utilizando tesouras para cortar estanho, cisalhas ou alicates de cortar arame. Também suavizam e aparam os bordos afiados ou rugosos, recorrendo a vários instrumentos.', 'released', '["Operador de Serra Mecânica para Metais", "Operador de Máquina-Ferramenta para Serrar", "Operadora de Serra Mecânica para Metais", "Operadora de Máquina-Ferramenta para Serrar"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/3a8ac6cd-b59a-4b93-b071-0324e895b8e4', 'Gerente de Loja de Materiais de Construção', 'Os gerentes de lojas de materiais de construção assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Diretor de Loja de Bricolage", "Diretora de Loja de Bricolage", "Gerentea de Loja de Materiais de Construção"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/3a959644-beed-4afc-8e57-d5068ae6a43e', 'Entregador de Bicicleta', 'Os estafetas de bicicleta recolhem e entregam encomendas e cartas de bicicleta.', 'released', '["Entregador por Bicicleta", "Entregadora de Bicicleta"]'::jsonb, '9331'),
  ('http://data.europa.eu/esco/occupation/3ac7fbb4-91b2-4d4d-abc8-7a6c55ed648f', 'Comerciante Grossista', 'Os comerciantes grossistas investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Agente de Comércio", "Comerciantea Grossista"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/3ae4fd99-814a-4d06-a7db-5ee680c22e26', 'Gestor de Contratos de Turismo', 'Os gestores de contratos de turismo negoceiam contratos relacionados com o turismo entre um operador turístico e um prestador de serviços turísticos.', 'released', '["Negociador de Contratos Hoteleiros", "Gestora de Contratos de Turismo", "Gestora de Contratos", "Gestor de Contratos", "Negociadora de Contratos Hoteleiros", "Gestor de Contratos de Turismo", "Gerente"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/3ae7c42b-7929-402f-bcbc-882b8679abf4', 'Especialista em Import-Export de Equipamento para Canalizações e Aquecimento', 'Os especialistas em import-export de equipamento para canalizações e aquecimento possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Equipamento para Canalizações e Aquecimento"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/3af4d6be-90b5-41f6-be06-3330dab3df73', 'Investigador em Estudos Sociais', 'Os investigadores em estudos sociais gerem projetos de investigação com vista a investigarem e produzirem relatórios sobre questões sociais. A primeira etapa do seu trabalho de investigação consiste na recolha de informações através de entrevistas, grupos de discussão e questionários, seguindo-se a organização e a análise das informações recolhidas utilizando pacotes de «software» informático. Analisam os problemas e as necessidades sociais e as diferentes formas e técnicas para lhes dar resposta.', 'released', '["Investigador em Estudos Sociais", "Investigadora em Estudos Sociais"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/3afd6af4-0c34-4311-ad73-65adc2571f0c', 'Diretor de Operações na Indústria do Vestuário', 'Os diretores de operações na indústria do vestuário fixam as ordens e os prazos de entrega, a fim de assegurar um fluxo eficaz do sistema de produção.', 'released', '["Diretora de Operações na Indústria do Vestuário", "Diretor de Produção — Vestuário", "Diretora de Produção — Vestuário", "Diretor de Operações — Vestuário"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/3b018148-8e92-4177-9267-5f090386f6a3', 'Consultor da Pesca', 'Os consultores da pesca prestam serviços de consultoria sobre as unidades populacionais e os seus habitats. Gerem a modernização das empresas de pesca costeira e fornecem soluções de melhoramento. Os conselheiros da pesca desenvolvem planos e políticas de gestão das pescas. Podem prestar aconselhamento sobre explorações piscícolas e unidades populacionais de peixes selvagens protegidas.', 'released', '["Consultor da Pesca", "Consultora da Pesca"]'::jsonb, '2132'),
  ('http://data.europa.eu/esco/occupation/3b129d8d-268e-465a-b0c5-bf32cae59a41', 'Diretor de Serviços de Mobilidade', 'Os diretores de serviços de mobilidade são responsáveis pelo desenvolvimento estratégico e pela execução de programas que promovam opções de mobilidade sustentáveis e interligadas, reduzam os custos de mobilidade e satisfaçam as necessidades de transporte dos clientes, dos trabalhadores e da comunidade no seu conjunto, tais como a partilha de bicicletas, trotinetas eletrônicas e automóveis e a gestão do estacionamento. Estabelecem e gerem parcerias com empresas de transportes sustentáveis e empresas de TIC e desenvolvem modelos empresariais para influenciar a procura do mercado e promover o conceito de mobilidade enquanto serviço nas zonas urbanas.;', 'released', '["Coordenador do Programa de Mobilidade", "Planejador de Cidade Inteligente", "Gerente de Escritório de Mobilidade Urbana", "Coordenadora do Programa de Mobilidade", "Gerente de Soluções de Mobilidade", "Gerente de Mobilidade", "Diretora de Serviços de Mobilidade"]'::jsonb, '2164'),
  ('http://data.europa.eu/esco/occupation/3b1ea27c-781c-41eb-821f-214285260dd2', 'Gestor de Mudança e Configuração de Tecnologia da Informação', 'Os gestores de mudança e configuração de tecnologia da informação organizam e implementam um processo para gerir as alterações ao longo de todo o ciclo de vida dos ativos de tecnologia da informação, tais como software, aplicações, sistemas informáticos, etc. Possuem sólidos conhecimentos das principais tecnologias e dos processos usados na engenharia de sistemas para gerir o ciclo de vida dos sistemas e subsistemas informáticos.;', 'released', '["Mudança de Software e Gerente de Configuração", "Gerenciador de Configuração", "Especialista Devops", "Engenheiro Devops", "Gerenciador de Ciclo de Vida do Aplicativo", "Engenheira Devops", "TI", "Gerente", "Gestora de Mudança e Configuração de Tecnologia da Informação"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/3b2229b4-807c-482a-89ca-2d0a542be196', 'Assistente Social em Gerontologia Social', 'Os assistentes sociais em gerontologia social prestam assistência a indivíduos idosos e às suas famílias, ajudando-os a fazer face às suas necessidades biopsicossociais. Ajudam na interligação dos idosos com os recursos comunitários, através da recolha de informações sobre a gama de serviços à sua disposição. Os assistentes sociais em gerontologia social avaliam as necessidades, a capacidade funcional e os problemas de saúde dos seus utentes e asseguram o contato com os profissionais de saúde, quando necessário.', 'released', '["Assistente Social Especialista em Trabalho com Idosos", "Assistente Social em Lares de Idosos", "Assistentea Social em Gerontologia Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/3b43dafb-8c6b-4906-9fe5-bc218aacad55', 'Treinador de Futebol', 'Os treinadores de futebol treinam equipes de futebol amador ou profissional de jovens ou de adultos. Os treinadores de futebol desenvolvem e executam planos de treino e melhoram ou mantêm a condição física, a técnica futebolística e as capacidades táticas dos jogadores. Preparam a equipe para competições e escolhem o alinhamento e as táticas de um jogo. Durante um jogo, os treinadores podem dar instruções a partir da linha lateral e são responsáveis pela substituição dos jogadores.', 'released', '["Treinador de Futebol", "Treinadora de Futebol"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/3b46ee4d-a220-4c83-ad90-937456596889', 'Operador de Produção de Pastilhas Elásticas', 'Os operadores de produção de pastilhas elásticas operam máquinas que misturam a base de goma de mascar com o açúcar ou o edulcorante. Seguem procedimentos para colocar a base de goma em recipientes e, em seguida, direcionam a mesma para os misturadores.', 'released', '["Operadora de Produção de Pastilhas Elásticas", "Técnica de Operação de Instalação de Fabricação de Pastilha Elástica", "Operador de Produção de Pastilhas Elásticas", "Técnico de Operação de Instalação de Fabricação de Pastilha Elástica"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/3b4eb248-6b40-42fe-9d10-cba8ccfe6613', 'Assistente de Mecânica Automóvel', 'Os assistentes de mecânica automóvel executam tarefas básicas, tais como a mudança de óleo, de filtros e de velas de ignição numa oficina de automóveis.', 'released', '["Ajudante de Mecânico Auto", "Assistentea de Mecânica Automóvel"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/3b6bea7d-36f4-44fb-ac73-d1cc8a198dcb', 'Produtor de Cinema e Televisão', 'Os produtores de cinema e televisão supervisionam a totalidade da produção de um filme ou programa de televisão. Selecionam os guiões que serão convertidos em filmes ou séries. Os produtores de cinema e televisão obtêm os meios financeiros necessários para produzir um filme ou uma série de televisão. Têm a decisão final sobre todo o projeto, desde o desenvolvimento e a edição até à distribuição. Durante as produções em larga escala, os produtores de cinema e televisão podem fazer parte de uma equipe de produtores e ser responsáveis por algumas destas tarefas.', 'released', '["Produtor de Cinema e Televisão", "Produtora de Cinema e Televisão"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/3b6d4443-4518-4fb3-ae44-188a958e328d', 'Operador de Valores', 'Os operadores de valores utilizam os seus conhecimentos técnicos relativos ao desempenho dos mercados financeiros para aconselhar e fazer recomendações aos gestores de ativos ou aos acionistas no que respeita a uma estratégia de investimento rentável, não esquecendo o desempenho da empresa. Recorrem a operações de negociação no mercado bolsista e lidam com uma série de impostos, comissões e obrigações fiscais. Os operadores de valores compram e vendem obrigações, ações, futuros e participações em fundos de cobertura de risco. Além disso, realizam análises técnicas pormenorizadas a nível micro e macroeconómico e industrial.', 'released', '["Operador de Valores", "Operadora de Valores", "Trader de Valores"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/3b755cda-c4b0-4fa1-8621-372f28ccc2e9', 'Professor de Escola Waldorf', 'Professores da formação Waldorf ensinam alunos através de abordagens que refletem a filosofia e os princípios de (Waldorf) Steiner. Centram-se em atividades práticas dos currículos e dão instrução às suas turmas de uma forma que realça o desenvolvimento das capacidades sociais, criativas e artísticas dos alunos. Os professores de escola Waldorf instruem os alunos em disciplinas similares às do ensino normalizado, embora utilizando uma abordagem diferente, e com exceção de um montante maior número de aulas centradas na prática e teoria criativas e artísticas. Utilizam técnicas de ensino que apoiam a filosofia da escola de (Waldorf) Steiner, avaliam o progresso da aprendizagem dos alunos e comunicam com outro pessoal escolar.', 'released', '["Professora de Escola Waldorf", "Professor Waldorf", "Professora Waldorf", "Professor de Escola Waldorf"]'::jsonb, '2341'),
  ('http://data.europa.eu/esco/occupation/3bdf6206-e952-4177-a17b-2a03bfee2144', 'Lixador de Madeira', 'Os lixadores de madeira alisam a superfície de um objeto de madeira com vários instrumentos de lixar. Aplicam uma superfície abrasiva, normalmente papel de lixa, à peça para remover irregularidades.', 'released', '["Lixador de Madeira", "Lixadora de Madeira"]'::jsonb, '7523'),
  ('http://data.europa.eu/esco/occupation/3c0af499-39f6-4468-9ba4-b13a26d5f888', 'Operador de Projeção de Abrasivos', 'Os operadores de projeção de abrasivos utilizam o equipamento e as máquinas adequados para suavizar superfícies rugosas através da projeção de abrasivos. A projeção de abrasivos utiliza-se, geralmente, no processo de acabamento de peças metálicas e para a projeção de materiais de construção utilizados em alvenaria, tais como tijolos, pedras e betão. Operam aparelhos ou cabinas de projeção de abrasivos que projeta à força um fluxo de material abrasivo, tal como areia, soda ou água, sob grande pressão, movido por uma roda centrífuga, a fim de moldar e suavizar as superfícies.', 'released', '["Operador de Projeção de Abrasivos", "Operadora de Projeção de Abrasivos"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/3c0c688b-f7ca-40dc-8222-ab011d4e2449', 'Técnico de Curtimenta', 'Os técnicos de curtimenta têm conhecimentos da gestão técnica de todas as fases da produção de curtumes, da fase de ribeira à curtimenta, pós-curtimenta e acabamento do couro. Asseguram a conformidade com as especificações do produto e garantem uma qualidade uniforme do couro, a sua adequação ao uso pretendido e a sustentabilidade de processos e produtos.;', 'released', '["Profissional de Bronzeamento", "Especialista em Bronzeamento", "Coordenador do Processo de Curtimento", "Tecnólogo de Bronzeamento", "Coordenadora do Processo de Curtimento", "Técnica de Curtimenta"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/3c1041c1-7a20-41fd-8cb2-529d7f671226', 'Gerente de Peixaria', 'Os gerentes de peixaria assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Peixes e Mariscos", "Peixeira", "Peixeiro", "Gerentea de Peixaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/3c136897-4e0e-41ef-bb57-d8152323b93a', 'Gestor de Serviços às Empresas', 'Os gestores de serviços às empresas são responsáveis pela prestação de serviços profissionais às empresas. Organizam a prestação de serviços adaptados às necessidades do cliente e estabelecem contatos com os clientes para chegar a acordo sobre as obrigações contratuais de ambas as partes.', 'released', '["Diretor de Agência Publicitária", "Gestor de Serviços às Empresas", "Gestora de Serviços às Empresas", "Gerente de Posto dos Correios", "Diretora de Agência Publicitária", "Gerente"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/3c1b7871-87f9-427b-adcb-fe16be8f9f24', 'Técnico de Instrumentos Musicais', 'Os técnicos de instrumentos musicais conservam, afinam e reparam instrumentos musicais, tais como pianos, órgãos de tubos, instrumentos de banda, violinos e outros instrumentos.', 'released', '["Técnico de Instrumentos Musicais", "Técnica de Instrumentos Musicais"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/3c2da05f-eb24-41f7-8307-46c96660fee0', 'Controlador de Tráfego Aéreo', 'Os controladores de tráfego aéreo prestam assistência aos pilotos, fornecendo informações sobre a altura, a velocidade e o rumo. Prestam assistência aos pilotos, para facilitar a descolagem e a aterragem de aeronaves em condições de segurança. São responsáveis pela manutenção de um movimento seguro e ordenado das aeronaves ao longo de importantes rotas aéreas, no céu e em torno dos aeroportos. Controlam o tráfego aéreo dentro e nas imediações dos aeroportos, de acordo com procedimentos e políticas estabelecidos, a fim de evitarem colisões e minimizarem os atrasos decorrentes do congestionamento do tráfego.', 'released', '["Controlador de Tráfego Aéreo", "Controladora de Tráfego Aéreo"]'::jsonb, '3154'),
  ('http://data.europa.eu/esco/occupation/3c305542-a51b-4b96-8d45-af11ca05eaa2', 'Professor de Medicina Veterinária', 'Os professores de Medicina Veterinária são professores universitários ou docentes em geral e, frequentemente, médicos que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Medicina Veterinária, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da Medicina Veterinária, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Medicina Veterinária", "Professor de Medicina Veterinária"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/3caa57c9-d360-4ce4-8000-34a983666ba7', 'Trabalhador de Adega', 'Os operadores de adega são responsáveis pelos tanques de fermentação e maturação. Controlam o processo de fermentação do mosto inoculado com levedura. Asseguram o correto funcionamento do equipamento que arrefece e adiciona levedura ao mosto para produzir cerveja. Para o efeito, controlam o fluxo de refrigeração que passa por serpentinas de arrefecimento que regulam a temperatura do mosto quente nos tanques.;', 'released', '["Supervisor de Adega de Fermentação", "Operador de Adega de Fermentação", "Operador de Fermentação", "Supervisora de Adega de Fermentação", "Operadora de Fermentação", "Operadora de Adega de Fermentação", "Trabalhadora de Adega"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/3cbbdb83-7c36-4ae5-8c45-6c284186f477', 'Modelador', 'Os modeladores criam modelos à escala tridimensional ou vários desenhos ou conceitos e para vários fins, tais como modelos de esqueleto humano ou órgãos. Além disso, montam os modelos em expositores de modo a poderem ser utilizados para o fim último, como a utilização em atividades educativas.', 'released', '["Modelador", "Modeladora", "Modeladora 3D", "Modelador 3D"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/3cc51201-cd20-47f8-92ad-4d5861f963cf', 'Paquete', 'Os paquetes recebem os hóspedes de hotéis, ajudam-nos a transportar a bagagem e prestam serviços, tais como a limpeza ocasional.', 'released', '["Carregador de Malas", "Carregadora de Malas", "Mandarete", "Paquetea"]'::jsonb, '9621'),
  ('http://data.europa.eu/esco/occupation/3cc87d40-f402-4f57-9353-4b36a031cfc5', 'Agente de Aluguel de Veículos', 'Os agentes de aluguer de veículos representam as empresas envolvidas na locação de veículos e determinam curtos períodos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Agentea de Aluguel de Veículos"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/3ce4691e-ecea-4278-939e-b89ab01087b8', 'Gestor de Telecomunicações', 'Os gestores de telecomunicações coordenam as atividades de pessoal de telecomunicações para a instalação, resolução de problemas, reparação e manutenção de equipamentos e infraestruturas de telecomunicações. Supervisionam a investigação, a avaliação e a aplicação de novas tecnologias e asseguram um ambiente de trabalho seguro para os trabalhadores. Supervisionam o inventário dos produtos, bem como ações de assistência aos usuários e aos clientes.', 'released', '["Gestora de Redes e Telecomunicações", "Gestora de Telecomunicações", "Gestor de Telecomunicações e Redes", "Gestor de Telecomunicações", "Gestora de Telecomunicações e Redes", "Gestor de Redes e Telecomunicações", "Gerente"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/3ce9c89d-6f1a-48b5-942d-386e46e2fd06', 'Técnico de Aquecimento, Ventilação, Ar Condicionado e Refrigeração', 'Os técnicos de aquecimento, ventilação, ar condicionado e refrigeração prestam assistência na concepção de dispositivos para aquecimento, ventilação, ar condicionado e, eventualmente, refrigeração de edifícios. Asseguram a conformidade do equipamento com as normas ambientais. Tratam as matérias perigosas utilizadas nos sistemas e asseguram a tomada de precauções de segurança.', 'released', '["Técnica de Manutenção", "Técnica de Aquecimento, Ventilação, Ar Condicionado e Refrigeração", "Técnico de Aquecimento, Ventilação, Ar Condicionado e Refrigeração", "Técnico de Manutenção"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/3cee6bea-4a19-4511-9bbb-fdf820857555', 'Agente de Investigação Criminal', 'Os agentes de investigação criminal examinam e analisam os locais de crimes e os elementos de prova encontrados nos mesmos. Tratam e protegem os elementos de prova em conformidade com as regras e os regulamentos e isolam o local de influências externas. Fotografam o local, asseguram a manutenção dos elementos de prova e redigem relatórios.', 'released', '["Agentea de Investigação Criminal"]'::jsonb, '3355'),
  ('http://data.europa.eu/esco/occupation/3d0f86c1-9bdd-4e84-bc62-93a716128c8d', 'Professor de Apoio à Aprendizagem', 'Os professores de apoio à aprendizagem apoiam os alunos com fraco desempenho dentro e fora da sala de aula, a fim de aumentar o seu aproveitamento escolar. Ajudam os alunos com desvantagens (múltiplas), tais como dificuldades de aprendizagem, problemas comportamentais e problemas de assiduidade, e prestam assistência aos alunos sobredotados pouco motivados. Podem também trabalhar com alunos adultos no sistema de ensino superior. Os professores de apoio à aprendizagem desenvolvem calendários e planos de ação com os alunos, a fim de planear as atividades de tutoria necessárias e acompanhar os progressos. Estabelecem igualmente contatos com os professores, os psicólogos escolares, os assistentes sociais escolares e, se necessário, com os pais dos alunos, a fim de melhorar o desenvolvimento educativo dos alunos.', 'released', '["Professora de Apoio à Aprendizagem", "Professor de Apoio à Aprendizagem"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/3d190639-90f8-4402-b1b3-a104a17e0d67', 'Responsável Pela Integração de Bancos de Dados', 'Os responsáveis pela integração de bancos de dados realizam funções de integração entre diferentes bancos de dados. Mantêm a integração e asseguram a interoperabilidade.', 'released', '["Responsável Pela Integração dos Dados", "Responsável Pela Integração de Bancos de Dados", "Responsável Pela Integração de Dados"]'::jsonb, '2521'),
  ('http://data.europa.eu/esco/occupation/3d2637f9-e56a-4769-b3a9-e413f95c20db', 'Especialista em Import-Export de Bebidas', 'Os especialistas em import-export de bebidas possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Bebidas"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/3d616092-b4fd-4c14-b0e9-a9119bbbd171', 'Musicoterapeuta', 'Os musicoterapeutas utilizam intervenções musicoterapêuticas para tratar doentes com perturbações do comportamento e distúrbios patogénicos para prevenir, atenuar ou eliminar os sintomas e alterar os comportamentos e as atitudes que necessitam de tratamento. Promovem e mantêm ou restabelecem o desenvolvimento, a maturidade e a saúde do doente/cliente através de intervenções terapêuticas. A musicoterapia proporciona, em especial, ajuda a pessoas com perturbações comportamentais e patogénicas emotivas e somáticas, intelectual ou socialmente induzidas, tais como psicoses (disfunções bipolares) e perturbações do desenvolvimento da personalidade. ;', 'released', '["Músico Terapeuta", "Música Terapeuta"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/3d7a1284-824c-47d9-8387-b8e1cd5888b5', 'Professor de Ciências Dentárias', 'Os professores em Ciências Dentárias são professores universitários ou docentes em geral e, frequentemente, médicos que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências Dentárias, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio das Ciências Dentárias, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor Universitário de Ciências Dentárias", "Professor de Ciências Dentárias", "Professora Universitária de Ciências Dentárias", "Professora de Ciências Dentárias"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/3d7b36e2-bfb8-4b67-9585-6787c1dda13e', 'Degustador de Café', 'Os degustadores de café testam amostras de café para avaliar as características do produto ou preparar fórmulas de mistura. Determinam o grau do produto, estimam o seu valor de mercado e exploram a forma como estes produtos podem apelar a diferentes gostos dos consumidores. Escrevam fórmulas de mistura para os trabalhadores que preparam produtos de café para fins comerciais.', 'released', '["Degustadora de Café", "Degustador de Café", "Provadora de Café", "Provador de Café"]'::jsonb, '7515'),
  ('http://data.europa.eu/esco/occupation/3d924c0d-ffee-4f11-adc7-c2bfb76fcf73', 'Engomador Mecânico', 'Os engomadores mecânicos voltam a moldar artigos de vestuário e de roupa de cama e eliminam os vincos através da utilização de ferros de engomar, prensas e ferros de vapor. Procedem à limpeza e manutenção da área de engomagem e secagem e organizam os produtos em conformidade.', 'released', '["Engomador Mecânico", "Engomadora Mecânica", "Engomadora Mecânico"]'::jsonb, '8157'),
  ('http://data.europa.eu/esco/occupation/3d974e0c-8ed9-47a7-aec2-ebdb34391c87', 'Bagageiro de Aeroporto', 'Os bagageiros de aeroporto recebem e devolvem a bagagem dos passageiros nos terminais dos aeroportos. Elaboram e anexam os documentos identificativos de bagagem, empilham a bagagem em carros ou transportadores e podem devolver a bagagem aos passageiros mediante a recepção dos documentos identificativos de bagagem.', 'released', '["Bagageiro de Aeroporto", "Operadora de Rampa", "Bagageira de Aeroporto", "Operador de Rampa"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/3d999108-f37a-4087-a936-b2911240b8c2', 'Coordenador de Voluntários', 'Os coordenadores de voluntários trabalham no setor sem fins lucrativos para recrutar, formar, motivar e supervisionar voluntários. São responsáveis por conceber missões de voluntários, recrutar voluntários, analisar as tarefas realizadas e o respetivo impacto, dar feedback e gerir o seu desempenho global em relação aos objetivos da organização. Os coordenadores de voluntários também podem gerir atividades de voluntariado em linha, por vezes conhecidas como cibervoluntariado ou voluntariado eletrônico.;', 'released', '["Gerente de Programa de Voluntariado", "Coordenadora do Programa de Voluntariado", "Coordenador de Envolvimento da Comunidade", "Gerente de Desenvolvimento de Voluntariado", "Coordenadora Voluntário", "Coordenador de Engajamento de Voluntários", "Coordenadora de Engajamento de Voluntários", "Coordenadora de Envolvimento da Comunidade", "Coordenador Voluntário", "Coordenador do Programa de Voluntariado", "Coordenadora de Voluntários"]'::jsonb, '1212'),
  ('http://data.europa.eu/esco/occupation/3da8ee8c-ab60-4feb-ab5b-3ba31ef9ec1f', 'Operador de Máquinas de Tratamento de Couro', 'Os operadores de máquinas de tratamento de couro utilizam as máquinas e os programas de curtumes, de acordo com os requisitos específicos aplicáveis para cumprir as normas do departamento. Realizam a manutenção de rotina da máquina.', 'released', '["Operador de Máquinas de Tratamento de Couro", "Operador de Máquinas de Produção de Couro", "Operadora de Máquinas de Produção de Couro", "Operadora de Máquinas de Tratamento de Couro"]'::jsonb, '8155'),
  ('http://data.europa.eu/esco/occupation/3dab5c3f-84d0-4d52-901d-dd262eaea509', 'Engenheiro de Investigação e Desenvolvimento de Projeto', 'Os engenheiros de investigação combinam competências de investigação e conhecimentos dos princípios de engenharia com vista a contribuir para o desenvolvimento ou o design de novos produtos e tecnologias. Também melhoram os processos técnicos, as máquinas e os sistemas existentes e criam novas tecnologias inovadoras. As funções dos engenheiros de investigação dependem do ramo da engenharia e da indústria em que trabalham. Os engenheiros de investigação trabalham normalmente num escritório ou laboratório, analisando processos e realizando experiências.;', 'released', '["Engenheiro de Investigação e Desenvolvimento de Projeto", "Engenheira de Investigação e Desenvolvimento de Projeto"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/3db35c88-bcb7-4de4-914a-9a9839a3c911', 'Professor de Cursos Profissionais de Administração e Gestão', 'Os professores de cursos profissionais de administração e gestão formam os alunos no seu domínio de estudos especializado, que tem uma natureza predominantemente prática. Prestam formação teórica sobre as competências práticas e técnicas que os estudantes devem posteriormente dominar numa profissão na área da administração e gestão, tais como contabilista ou bancário. Os professores de cursos profissionais de administração e gestão acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da administração e gestão através de trabalhos, testes e exames.;', 'released', '["Professor de Cursos Profissionais de Administração e Gestão", "Professora de Cursos Profissionais de Administração e Gestão"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/3dbd758c-6dc0-41fe-8248-2250c9bfa4ab', 'Climatologista', 'Os climatologistas estudam a evolução média das condições meteorológicas e climáticas numa perspetiva de longo prazo. Investigam e analisam o historial das condições meteorológicas a fim de prever as tendências da evolução das condições climáticas, nomeadamente a evolução da temperatura, o aquecimento global ou as condições meteorológicas regionais evolutivas. Utilizam essas conclusões para prestar aconselhamento sobre política ambiental, construção, projetos agrícolas e questões societais.', 'released', '["Climatóloga", "Investigadora em Climatologia", "Cientista Climático", "Climatólogo", "Investigadora em Ciência do Clima", "Investigador em Climatologia", "Investigador em Ciência do Clima", "Cientista Climática"]'::jsonb, '2112'),
  ('http://data.europa.eu/esco/occupation/3df28a39-9bfe-4e36-b394-a189ef967a74', 'Instalador de Banheiros', 'Os instaladores de casas de banho instalam elementos de casas de banho. Efetuam as medições necessárias, preparam a divisão, retirando elementos antigos, se necessário, e instalam os novos equipamentos para casas de banho, incluindo as ligações de canos da água, do gás, do saneamento e da eletricidade.', 'released', '["Instalador de Casas de Banho", "Canalizador", "Instaladora de Casas de Banho", "Canalizadora", "Instaladora de Banheiros"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/3e0b4b9b-b624-4ceb-9bc9-9627cdfb0b81', 'Operador de Máquinas de Fabricação de Artigos em Couro', 'Os operadores de máquinas de fabrico de artigos em couro asseguram o correto funcionamento de máquinas específicas na produção industrial de artigos em couro. Operam máquinas de corte, de fecho e de acabamento de produtos de bagagem, sacos de mão e selaria. Também realizam a manutenção de rotina da máquina.', 'released', '["Operador de Máquinas de Fabricação de Artigos em Couro", "Operadora de Máquinas de Fabricação de Artigos em Couro"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/3e1a2f3c-20d6-4d33-aa6f-63cd2a32698d', 'Chefe de Tesouraria', 'Os chefes de tesouraria determinam e supervisionam as políticas financeiras estratégicas de uma empresa ou organização. Recorrem a técnicas de gestão de tesouraria, como a organização das contas, o acompanhamento dos fluxos de caixa, o planejamento e o controlo da liquidez, a gestão dos riscos, incluindo os riscos cambiais e de mercadorias, e mantêm uma ligação estreita com os bancos e as agências de notação.', 'released', '["Analista de Tesouraria", "Chefea de Tesouraria"]'::jsonb, '1211'),
  ('http://data.europa.eu/esco/occupation/3e213d52-e7a0-4980-99d9-23da1f717f50', 'Consultor Político', 'Os consultores políticos prestam apoio durante as campanhas políticas, aconselhando o candidato e o pessoal responsável pela gestão da campanha em matéria de estratégias de campanha e de coordenação do pessoal da campanha, e desenvolvendo estratégias de publicidade e de investigação.', 'released', '["Consultora Política", "Consultor Político", "Consultora Político"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/3e524c3e-3ee8-47dd-8463-2c2a41b548bf', 'Montador de Equipamentos Elétricos', 'Os montadores de equipamentos elétricos são responsáveis pela montagem de material elétrico. Montam os componentes e a cablagem de equipamentos de acordo com os esquemas.', 'released', '["Montadora de Equipamentos Elétricos", "Montador de Equipamentos Elétricos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/3e626058-f669-4503-84ec-6ae1a6077a61', 'Operador de Incinerador', 'Os operadores de incineradores vigiam e controlam as máquinas de incineração que queimam lixo e resíduos. Asseguram a manutenção do equipamento e a conformidade do processo de incineração com a regulamentação em matéria de segurança para a incineração de resíduos.', 'released', '["Operadora de Incinerador", "Operador de Incinerador"]'::jsonb, '3132'),
  ('http://data.europa.eu/esco/occupation/3e6488b6-3ca5-46b9-b380-5cd251d24824', 'Instrutor de Pilates', 'Os instrutores de Pilates planeiam, ensinam e adaptam exercícios com base no trabalho e nos princípios de Joseph Pilates. Recolhem e analisam informações para cada cliente, a fim de assegurar que os programas sejam seguros, adequados e eficazes. Aplicam os princípios de Pilates através do planejamento e do ensino de aulas de apoio e não competitivas. Motivam e incentivam os clientes por forma a garantir a sua adesão às sessões regulares.', 'released', '["Instrutor de Pilates", "Instrutora de Pilates"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/3e7bf729-4442-4b9f-ad5e-83111963795c', 'Técnico de Informática', 'Os técnicos de informática procedem à instalação, manutenção, reparação e operação dos sistemas de informação e quaisquer equipamentos relacionados com informática (computadores portáteis, computadores de secretária, servidores, tablets, telefones inteligentes, equipamentos de comunicação, impressoras e qualquer tipo de redes periféricas), bem como qualquer tipo de software (controladores, sistemas operativos, aplicações).', 'released', '["Técnica de TI", "Técnico de TI", "Técnica de Informática", "Técnica de Tecnologias de Informação", "Técnico de Informática", "Oficial de TI", "Técnico de Tecnologias de Informação e Comunicação", "Técnico de Tecnologias de Informação", "Técnica de Tecnologias de Informação e Comunicação"]'::jsonb, '3512'),
  ('http://data.europa.eu/esco/occupation/3e9c1262-4fe2-4eb1-bf94-4fe64498393a', 'Treinador de Desportos', 'Os treinadores de desportos fornecem instruções sobre o desporto da sua especialização num contexto recreativo a participantes com uma idade específica e não específica. Identificam competências já adquiridas e implementam programas de treino adequados para os grupos ou indivíduos que lecionam, a fim de desenvolver a aptidão física e psicológica dos participantes. Criam o ambiente ideal para o desenvolvimento das competências dos participantes e permitem-lhes maximizar o seu desempenho, promovendo um bom desportivismo e caráter em todos os participantes. Os treinadores de desportos também acompanham a evolução do participante e fornecem instruções personalizadas sempre que necessário. Supervisionam as instalações desportivas e os vestiários e mantêm os uniformes e o equipamento.', 'released', '["Treinador de Desportos", "Treinadora de Desportos"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/3e9c6f2a-dc20-4366-aeb9-99dffd635b4c', 'Aplainador de Pedra', 'Os aplainadores de pedra procedem à operação e manutenção de máquinas de aplainar utilizadas no acabamento de blocos e placas. Manipulam a pedra e asseguram que os parâmetros exigidos estão em conformidade com as especificações.', 'released', '["Aplainadora de Pedra", "Operadora de Máquinas de Aplainar Pedra", "Ajustador de Máquinas de Aplainar Pedra", "Operador de Máquinas de Aplainar Pedra", "Aplainador de Pedra", "Ajustadora de Máquinas de Aplainar Pedra"]'::jsonb, '8112'),
  ('http://data.europa.eu/esco/occupation/3f0093ab-651b-401a-b542-bba84ff46deb', 'Comerciante Grossista de Peles e Artigos de Couro', 'Os comerciantes grossistas de peles e artigos de couro investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Peles e Artigos de Couro"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/3f0b6500-dfb5-40a8-9bce-72998ec3d344', 'Operador de Elevadores de Esqui', 'Os operadores de elevadores de esqui executam ações de prevenção de interrupções e de reparação dos elevadores de esqui. Abordam os períodos de indisponibilidade do equipamento graças às suas competências técnicas. Monitorizam o funcionamento das operações mecânicas dos elevadores. Criam sistemas para assegurar a conformidade com as regras de segurança e os processos de gestão dos riscos.', 'released', '["Operador de Elevadores de Esqui", "Operadora de Elevadores de Esqui"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/3f277813-3cab-4c5d-bfeb-613e449b31c5', 'Corretor de Hipotecas', 'Os corretores de hipotecas tratam dos pedidos de empréstimo hipotecário de clientes, recolhem documentação sobre empréstimos e procuram novas oportunidades de concessão de crédito hipotecário. Concluem e encerram processos de empréstimo hipotecário para os seus clientes.', 'released', '["Corretora de Hipotecas", "Corretor de Hipotecas"]'::jsonb, '3312'),
  ('http://data.europa.eu/esco/occupation/3f2e63fb-dc50-4370-9f6a-85ddc338dcde', 'Especialista em Import-Export de Flores e Plantas Ornamentais', 'Os especialistas em import-export de flores e plantas ornamentais possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Flores e Plantas Ornamentais"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/3f32394b-f1b1-48ef-96ee-74405fb7c6b6', 'Operador de Caixa de Lotaria', 'Os operadores de caixa de lotaria procedem à troca do registo de um conjunto de números ou de símbolos por dinheiro e dão bilhetes os jogadores. Pagam prémios e obtêm as assinaturas e a identificação dos clientes. Procedem à auditoria e contagem de dinheiro na caixa registadora, aplicando os regulamentos para prevenir o branqueamento de capitais.', 'released', '["Operador de Caixa de Lotaria", "Operadora de Caixa", "Operadora de Caixa de Lotaria", "Operador de Caixa"]'::jsonb, '5230'),
  ('http://data.europa.eu/esco/occupation/3f3748a7-4bb3-40b4-9ae3-1c5040c70f52', 'Engenheiro Civil Especialista em Construção de Vias-Férreas', 'Os engenheiros civis especialistas em construção de vias-férreas mantêm uma abordagem segura, eficiente em termos de custos, de elevada qualidade e responsável do ponto de vista ambiental em todos os projetos técnicos das empresas ferroviárias. Prestam aconselhamento em matéria de gestão de projetos em todos os projetos de construção, incluindo o teste, a colocação em funcionamento e a supervisão do local. Procedem à auditoria dos contratantes tendo em vista a segurança, o ambiente e a qualidade da concepção, dos processos e do desempenho, de modo a garantir que todos os projetos seguem as normas internas e a legislação pertinente.', 'released', '["Engenheira Civil Especialista em Construção de Vias-Férreas", "Engenheiro Civil Especialista em Construção de Vias-Férreas"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/3f54ceba-3c4e-4ba1-8ddb-9e49a881a60a', 'Responsável Pela Segurança de Estaleiros de Construção', 'Os responsáveis pela segurança de estaleiros de construção inspecionam, aplicam e controlam medidas de saúde e segurança nos estaleiros de construção. Além disso, gerem os acidentes de trabalho e tomam medidas para garantir a correta aplicação das políticas de segurança.', 'released', NULL, '3112'),
  ('http://data.europa.eu/esco/occupation/3f6fc9db-18c1-45e8-819e-baf7b6cfe372', 'Administrador Judicial', 'Os administradores judiciais executam tarefas de gestão numa instituição judicial, tais como a supervisão do pessoal, a administração, a comunicação com os juízes e a revisão dos procedimentos. Gerem igualmente as finanças do tribunal e supervisionam a manutenção da instalação e do equipamento.', 'released', '["Administradora do Tribunal", "Administrador do Tribunal", "Administrador Legal", "Administradora Legal", "Oficial de Justiça", "Administradora Judicial"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/3f73120d-cece-4848-9fb4-61fdbaa7eba5', 'Projetista de Material Circulante', 'Os projetistas de material circulante convertem os desenhos dos engenheiros de material circulante em desenhos técnicos, utilizando geralmente software. Os seus desenhos pormenorizam as dimensões, os métodos de fixação e montagem e outras especificações utilizados no fabrico de veículos ferroviários, como locomotivas, unidades múltiplas, carruagens e vagões.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/3f74aad8-2d60-4be2-b059-8dba5568d530', 'Acompanhante de Crianças', 'Os acompanhantes de crianças prestam serviços sociais às crianças e às respetivas famílias para melhorar o seu funcionamento social e psicológico. Visam maximizar o bem-estar da família através da prestação de cuidados às crianças durante o dia.', 'released', '["Vigilante de Crianças", "Acompanhantea de Crianças"]'::jsonb, '5311'),
  ('http://data.europa.eu/esco/occupation/3f7b7ce5-94b6-4e0c-98e7-a4ee5a6accf4', 'Toxicologista', 'Os toxicologistas estudam os efeitos que as substâncias químicas ou os agentes biológicos e físicos têm nos organismos vivos, mais especificamente no ambiente e na saúde humana e animal. Determinam as doses de exposição a substâncias que conduzem a efeitos tóxicos em ambientes, pessoas e organismos vivos, e realizam experiências em animais e culturas de células.', 'released', '["Toxicóloga", "Toxicólogo"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/3f863faa-c045-4f05-a419-b19182aea866', 'Engenheiro Especialista em Exploração e Prospeção Petrolífera', 'Os engenheiros especialistas em exploração e prospeção petrolífera desenvolvem e supervisionam a perfuração de poços de gás e petróleo. Contribuem para a concepção, o ensaio e a criação de poços e são utilizados em plataformas terrestres ou offshore. Os engenheiros especialistas em exploração e prospeção petrolífera trabalham com outros profissionais mineiros e supervisionam o progresso da perfuração e a segurança do sítio.', 'released', '["Engenheira Especialista em Exploração e Prospeção Petrolífera", "Engenheiro Especialista em Exploração e Prospeção Petrolífera"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/3fa31588-2e4d-49c3-b839-4b615cc62742', 'Conselheiro Humanitário', 'Os conselheiros humanitários asseguram estratégias para reduzir o impacto das crises humanitárias a nível nacional e/ou internacional. Prestam aconselhamento e apoio profissionais, em colaboração com diferentes parceiros.', 'released', '["Conselheira Humanitária", "Conselheiro Humanitário", "Conselheira Humanitário"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/3fa9a480-ceb3-4c2a-8a91-0508e1bb6ba5', 'Modelista de Calçado CAD', 'Os modelistas de calçado CAD concebem, ajustam e alteram moldes para todo o tipo de calçado utilizando sistemas CAD. Verificam as variantes de posicionamento utilizando módulos de encaixe do sistema CAD e o consumo de materiais. Uma vez aprovado o molde de amostra para a produção, estes profissionais fabricam séries de moldes (classificação) para produzir uma gama do mesmo modelo de calçado em diferentes tamanhos.', 'released', NULL, '7536'),
  ('http://data.europa.eu/esco/occupation/3ff2fdf4-af54-4517-873d-73e9353f112e', 'Vendedor de Jogos de Computador, Multimédia e Software', 'Os vendedores de jogos de computador, multimédia e software vendem produtos de software em lojas especializadas.', 'released', '["Vendedora de Jogos de Computador, Multimédia e Software", "Vendedor de Jogos de Computador, Multimédia e Software"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/40260ee8-c94a-4dc8-a562-f9fbc2fe13b1', 'Técnico de Manutenção de Sistemas de Saneamento Básico', 'Os técnicos de manutenção de sistemas de saneamento básico inspecionam os esgotos e os sistemas de condutas. Para tal, recorrem a câmaras de vídeo móveis, cujos registos os informam sobre a necessidade de efetuarem trabalhos de manutenção e de reparação nestes tipos de sistemas.', 'released', '["Técnico de Manutenção de Sistemas de Saneamento Básico", "Técnica de Manutenção de Sistemas de Saneamento Básico"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/403be630-8d1e-43b7-9f07-098aca5bb689', 'Mediador de Conflitos', 'Os mediadores de conflitos resolvem litígios entre duas partes, examinando o caso, entrevistando ambas as partes e prestando aconselhamento sobre a solução mais vantajosa para as mesmas. Ouvem ambas as partes, a fim de facilitar a comunicação e de encontrar um acordo justo, e organizam encontros. O seu objetivo é a resolução dos litígios através do diálogo e de soluções alternativas, sem necessidade de recorrer a processos judiciais e tribunais. Os mediadores de conflitos asseguram a conformidade da resolução com os regulamentos legais e a sua aplicação.', 'released', '["Mediador de Conflitos", "Mediador", "Mediadora de Conflitos"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/404a50e9-61ce-448d-a695-bbfc697a0727', 'Ministro', 'Os ministros funcionam como decisores dos governos nacionais ou regionais e dos ministérios da administração pública. Exercem funções legislativas e supervisionam o funcionamento do seu departamento.', 'released', '["Primeiro-Ministro", "Ministro", "Primeira-Ministra", "Ministra"]'::jsonb, '1111'),
  ('http://data.europa.eu/esco/occupation/40517ed4-2769-4283-a15b-4b0d939bd2d3', 'Supervisor de Produção', 'Os supervisores de produção coordenam, planeiam e orientam os processos de fabrico e produção. São responsáveis pela revisão dos calendários de produção ou das encomendas, bem como por lidar com o pessoal nestas áreas de produção.', 'released', '["Supervisora de Produção", "Supervisor de Produção"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/40b77b1b-6f9c-4d25-8b08-8b3cb0aaf7e7', 'Engenheiro de Explosivos', 'Os engenheiros de explosivos concebem padrões de perfuração e determinam a quantidade de explosivos necessária. Organizam e supervisionam as explosões controladas e comunicam e investigam as explosões falhadas. Gerem os armazéns de explosivos.', 'released', '["Engenheiro de Explosivos", "Engenheira de Explosivos"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/40d76b2c-b917-4bf1-95b3-191f11472e67', 'Criador de Calçado em 3D', 'Os criadores de calçado em 3D desenham modelos de calçado, fabricam, ajustam e modificam os padrões utilizando sistemas de desenho assistido por computador. Centram-se na concepção sustentável do modelo, na seleção e no desenho de formas e componentes, na utilização correta e eficiente dos materiais, na elaboração de padrões, na seleção da parte inferior e na elaboração de fichas técnicas. Podem supervisionar o desenvolvimento e a avaliação de protótipos, a preparação de amostras, a realização dos necessários testes de controlo da qualidade das amostras e a gestão da documentação técnica do produto.;', 'released', '["Designer e Desenvolvedora de Produtos de Calçados 3D", "Desenvolvedora de Design Auxiliado por Computador em 3D de Calçados", "Desenvolvedora 3D de Calçados", "Desenvolvedor 3D de Calçados", "Especialista em Calçados 3D", "Designer e Desenvolvedor de Produtos de Calçados 3D", "Desenvolvedor de Design Auxiliado por Computador em 3D de Calçados", "Criadora de Calçado em 3D"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/40da2fc6-8cb4-4cd3-8fe3-899715905070', 'Artista de Piercings e Tatuagens', 'Os artistas de piercings e tatuagens decoram a pele dos clientes temporária ou permanentemente. Utilizam diversas técnicas, tais como tatuagens ou piercings. Os artistas seguem as preferências dos clientes em termos de concepção das tatuagens e dos piercings e superfície corporal e aplicam-nos em segurança. Aconselham também sobre os métodos para evitar infeções após os procedimentos nos corpos dos clientes.', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/41519a6e-d4f1-4991-b821-24c54647949d', 'Técnico de Manutenção de Baterias', 'Os técnicos de manutenção de baterias são responsáveis pela manutenção e reparação dos equipamentos utilizados na produção de baterias. Trabalham em fábricas de produção de baterias e são responsáveis por assegurar que os equipamentos estão em bom estado de funcionamento e são capazes de produzir baterias de alta qualidade. Têm de ter um forte domínio dos sistemas mecânicos, elétricos e de controlo, bem como experiência em manutenção e reparação de equipamentos de fabrico.', 'released', '["Técnico de Manutenção de Baterias", "Técnica de Manutenção de Baterias"]'::jsonb, '3113'),
  ('http://data.europa.eu/esco/occupation/41535a7d-f2ed-4937-9b7e-3b14c8c755b3', 'Operador de Branqueadores de Pasta de Papel', 'Os operadores de branqueadores de pasta de papel asseguram o correto funcionamento de máquinas que branqueiam a pasta de madeira na produção de papel branco. Utilizam-se diferentes técnicas de branqueamento para complementar os vários métodos de produção de pasta e obter diferentes graus de brancura.', 'released', '["Operador de Branqueadores de Pasta de Papel", "Operadora de Branqueadores de Pasta de Papel"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/4163b31e-440b-4991-b5c3-48d0515250ef', 'Técnico de Marketing de Rede', 'Os técnicos de marketing de rede aplicam diversas estratégias de marketing, incluindo estratégias de marketing de rede, para vender produtos e convencer novas pessoas a aderir e começar a vender esses produtos. Utilizam relações pessoais para atrair clientes e vender vários tipos de produtos.', 'released', '["Técnico de Marketing de Rede", "Técnica de Marketing de Rede"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/418f3a43-a6b2-4101-aaa0-832fe7d82885', 'Operador do Setor da Fabricação Aditiva Metálica', 'Os operadores do setor do fabrico aditivo metálico (FA) operam máquinas que utilizam processos de fabrico aditivo, tais como a montagem e instalação, manutenção e reparação. Têm uma compreensão factual e ampla do domínio do processo de fabrico aditivo metálico. São capazes de desenvolver soluções para problemas básicos e específicos relacionados com máquinas e processos de fabrico aditivo e de autogerir o manuseamento das matérias-primas (aprovação, armazenamento, contaminação, rastreabilidade).;', 'released', '["Técnico de Manufatura Aditiva", "Técnico de Manufatura Aditiva de Metal", "Operador de Manufatura Aditiva de Metal", "Técnica de Metal AM", "Técnico AM", "Técnica AM", "Operadora de Manufatura Aditiva de Metal", "Técnica de Manufatura Aditiva", "Operador de Metal AM", "Operadora de Metal AM", "Técnica de Manufatura Aditiva de Metal", "Operadora AM", "Técnico de Metal AM", "Operadora do Setor da Fabricação Aditiva Metálica"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/41a51397-089d-459d-9b7e-f1cdee5ad6bb', 'Pintor-Decorador', 'Os pintores-decoradores concebem e criam arte visual em diferentes tipos de superfícies, tais como artigos de cerâmica, caixas, vidro e tecido. Utilizam diversos materiais e uma variedade de técnicas para produzir ilustrações decorativas, desde desenho com estêncil até à mão livre.', 'released', '["Pintor-Decorador", "Pintora Artística", "Pintor Artístico", "Pintora-Decoradora", "Pintor-Decoradora"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/41a8e7c8-e1d8-4984-9b3c-dbbad1699f83', 'Instalador de Tetos', 'Os instaladores de tetos instalam tetos em edifícios. Aplicam diferentes técnicas conforme a situação exigir — por exemplo, quando a resistência ao fogo é particularmente importante, ou quando é necessário espaço entre o teto suspenso e o piso seguinte — ou especializam-se apenas em um.', 'released', '["Instalador de Tetos", "Instalador de Tetos Falsos", "Instaladora de Tetos", "Instaladora de Tetos Industriais", "Instaladora de Tetos Falsos", "Instalador de Tetos Industriais"]'::jsonb, '7123'),
  ('http://data.europa.eu/esco/occupation/41beead9-98ad-4c89-b6e0-a14149f4eeab', 'Assistente de Estação de Serviço', 'Os assistentes de estação de serviço vendem produtos combustíveis, lubrificantes e de arrefecimento para veículos automóveis e motociclos numa estação de combustível.', 'released', '["Vendedora em Estação de Serviço", "Vendedor em Estação de Serviço", "Assistentea de Estação de Serviço"]'::jsonb, '5245'),
  ('http://data.europa.eu/esco/occupation/41d4be58-3111-48b5-814a-83117983dd16', 'Torrista', 'Os torristas orientam as posições e os movimentos de condutas de perfuração. Controlam o equipamento automatizado de tratamento de tubagens. São frequentemente responsáveis pelo estado dos fluidos de perfuração, ou «lama».', 'released', '["Torrista", "Operadora de Torre de Perfuração", "Operador de Torre de Perfuração"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/41d609a1-62df-4cec-ac71-6434e545a729', 'Técnico no Domínio da Corrosão', 'Os técnicos no domínio da corrosão monitorizam a integridade de uma conduta e procedem a reparações na mesma, se necessário. Asseguram que as condutas estão corretamente ligadas e em conformidade com a regulamentação em matéria de saúde e segurança. Os técnicos no domínio da corrosão inspecionam a existência de corrosão nos sistemas de proteção catódica e nos pontos de ligação das condutas. Podem também auxiliar na concepção das condutas, analisar o solo e redigir relatórios sobre questões técnicas.', 'released', '["Técnica no Domínio da Corrosão", "Técnico no Domínio da Corrosão"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/42381741-f3a7-4b26-b35c-da6fad9f1cfd', 'Técnico de Desenvolvimento de Produtos', 'Os técnicos de desenvolvimento de produtos aumentam a eficiência do desenvolvimento de produtos, instalam equipamentos e desenvolvem e testam soluções para resolver problemas técnicos. Trabalham em estreita colaboração com engenheiros e técnicos, inspecionam os produtos, realizam testes e recolhem dados.', 'released', '["Técnica de Desenvolvimento de Produtos", "Técnico de Desenvolvimento de Produtos"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/423f4021-322b-4257-9a4e-d6ee5d166fbc', 'Estofador na Indústria Náutica', 'Os estofadores na indústria náutica fabricam, montam e reparam componentes interiores para todos os tipos de embarcações. Utilizam ferramentas elétricas, ferramentas manuais e equipamento de oficina para preparar e fixar materiais e aplicar acabamentos. Também inspecionam os materiais recebidos e preparam o interior das embarcações para novos componentes.', 'released', '["Estofadora na Indústria Náutica", "Estofador na Indústria Náutica"]'::jsonb, '7534'),
  ('http://data.europa.eu/esco/occupation/425ed170-bf90-42c9-b5bd-148282ed96ff', 'Gestor de Planejamento Turístico', 'Os gestores de planejamento turístico são responsáveis pela gestão e execução das estratégias (ou políticas) nacionais/regionais/locais de turismo para o desenvolvimento, comercialização e promoção de destinos.', 'released', '["Gestora de Destinos Turísticos", "Gestor de Destinos Turísticos", "Gestor de Planejamento Turístico", "Gestora de Planejamento Turístico", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/425f4904-3a7a-4ad0-ac5b-42b38392f768', 'Operador de Equipamento Pesado no Subsolo', 'Os operadores de equipamento pesado no subsolo controlam o equipamento pesado de exploração mineira, tal como o equipamento de corte e de carga, para escavar e carregar o minério e os minerais em bruto em minas subterrâneas.', 'released', '["Operador de Equipamento Pesado no Subsolo", "Operadora de Equipamento Pesado Subterrâneo", "Operadora de Equipamento Pesado no Subsolo", "Operador de Equipamento Pesado Subterrâneo"]'::jsonb, '8111'),
  ('http://data.europa.eu/esco/occupation/426c8cca-31f7-4a88-af60-6f5365ab3a62', 'Operador de Motoniveladoras', 'Os operadores de motoniveladoras trabalham com uma peça pesada de equipamento móvel que cria uma superfície plana, cortando a camada superior do solo com uma lâmina grande. Geralmente, os operadores de motoniveladoras conferem um acabamento plano ao trabalho de terraplanagem pesado efetuado pelos operadores de escrêiperes e de buldózer.', 'released', '["Operador de Motoniveladoras", "Operadora de Motoniveladoras"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/42a96d07-1e1d-49ae-9399-c1f4be27ddea', 'Técnico na Área do Emprego', 'Os técnicos na área do emprego trabalham para serviços e agências de emprego. Fazem a correspondência entre pessoas à procura de emprego e as vagas de emprego anunciadas e prestam aconselhamento em matéria de atividades de procura de emprego.', 'released', '["Técnico na Área do Emprego", "Técnica na Área do Emprego"]'::jsonb, '3333'),
  ('http://data.europa.eu/esco/occupation/42abcbcb-721b-4da6-9c06-f6951969d056', 'Diretor de Importação e Exportação de Artigos de Perfumaria e Cosmética', 'Os diretores de importação/exportação perfumaria e cosmética implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Vendas Perfumaria e Cosmética", "Diretora de Vendas Perfumaria e Cosmética", "Diretor de Importação e Exportação de Artigos de Perfumaria e Cosmética", "Diretora de Importação e Exportação de Artigos de Perfumaria e Cosmética"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/42c769cd-4c60-4bac-94d2-29a492b82b74', 'Revisor de Transcrições', 'Os revisores de transcrições editam as transcrições criadas pelos escrivães de direito, com vista a transformá-las num documento jurídico profissional legível. Escutam e leem os relatórios que lhes são entregues a fim de introduzirem pontuação, palavras em falta e o formato e de aumentarem a exatidão do documento.', 'released', '["Transcritora", "Revisora de Transcrições", "Revisor de Transcrições", "Scopist", "Transcritor"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/42dbb769-4c91-47dc-bd16-ec8e70c4180f', 'Engenheiro de Energia Solar', 'Os engenheiros de energia solar concebem sistemas que produzem energia elétrica a partir da luz solar, como os sistemas fotovoltaicos. Concebem e constroem sistemas que otimizem a produção de energia a partir da luz solar e a sustentabilidade do processo de produção de sistemas solares.', 'released', '["Engenheira de Energia Solar", "Engenheiro de Energia Solar"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/42e9d1c5-76f1-41ef-996e-38d5ac711a31', 'Inspetor de Material Rolante', 'Os inspetores do material rolante inspecionam os vagões e as carruagens, a fim de avaliarem o seu estado técnico quando agrupados e antes de serem utilizados para atividades de transporte. Verificam os dispositivos técnicos, garantem o funcionamento completo e correto do material rolante e preparam a documentação técnica e/ou as listas de controlo necessárias. Dependendo da organização do trabalho, são também responsáveis por trabalhos ad-hoc de manutenção ou intercâmbio limitados e pela realização de ensaios de travagem.', 'released', '["Inspetora de Material Rolante", "Inspetor de Material Rolante"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/42ff9e52-1f56-427d-b772-b9328c39b98a', 'Desenhador Artístico', 'Os desenhadores artísticos expressam conceitos através de uma representação desenhada que corresponde à ideia.', 'released', '["Desenhador", "Desenhador Artístico", "Ilustrador", "Ilustradora", "Desenhadora Artística", "Desenhadora", "Desenhadora Artístico"]'::jsonb, '2651'),
  ('http://data.europa.eu/esco/occupation/4305327d-3537-4dfb-a913-bce6614362f1', 'Supervisor de Limpa-Chaminés', 'Os supervisores de limpa-chaminés supervisionam e coordenam as atividades dos limpadores de chaminés. Realizam controlos de qualidade e asseguram a conformidade com os regulamentos de segurança.', 'released', '["Supervisor de Limpa-Chaminés", "Supervisora de Limpa-Chaminés"]'::jsonb, '7133'),
  ('http://data.europa.eu/esco/occupation/4311b9e0-064e-41bc-b120-5eb21f337780', 'Diretor de Importação e Exportação de Café, Chá, Cacau e Especiarias', 'Os diretores de importação e exportação de café, chá, cacau e especiarias implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Vendas Café, Chá, Cacau e Especiarias", "Diretora de Vendas Café, Chá, Cacau e Especiarias", "Diretor de Importação e Exportação de Café, Chá, Cacau e Especiarias", "Diretora de Importação e Exportação de Café, Chá, Cacau e Especiarias"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/431f0055-43ca-406c-99f0-fb10a73d684e', 'Aplainador de Madeira', 'Os aplainadores de madeira utilizam máquinas para aplainar pranchas de madeira até uma espessura uniforme. De um modo geral, a máquina aplaina ambos os lados da prancha numa operação. Colocam a prancha na máquina cuidadosamente, para evitar um eventual excesso de aplainamento no bordo conhecido por «narceja».', 'released', '["Aplainador de Madeira", "Aplainadora de Madeira"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/432cd69f-6323-4147-94f2-342de3cb0a65', 'Supervisor de Produção de Instrumentos de Ótica', 'Os supervisores de produção de instrumentos de ótica coordenam, planeiam e orientam o processo de produção de instrumentos óticos. Garantem que o vidro ótico é transformado de forma adequada e que o equipamento ótico é montado de acordo com as especificações. Gerem os trabalhadores da linha de produção, supervisionam a qualidade dos produtos montados e realizam a gestão dos custos e dos recursos.', 'released', '["Supervisor de Produção de Instrumentos de Ótica", "Supervisora de Produção de Instrumentos de Ótica"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/4370b117-d9ec-424c-80de-fd92ba740f65', 'Operador de Cilindros Compactadores', 'Os operadores de cilindros compactadores trabalham com equipamento para compactar uma série de materiais, tais como solo, gravilha, betão ou asfalto, na construção de estradas e fundações. Caminham atrás do cilindro compactador ou sentam-se na parte superior do mesmo, dependendo do tipo e da dimensão, e percorrem a área a compactar.', 'released', '["Operadora de Cilindros Compactadores", "Operador de Cilindros Compactadores"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/43841fa5-f8ae-43ce-834d-5482ec23ef9e', 'Fabricante de Produtos Lácteos', 'Os fabricantes de produtos lácteos são produtores de leite cru que fabricam produtos lácteos, tais como a manteiga, o queijo, a nata e o leite.', 'released', '["Fabricantea de Produtos Lácteos"]'::jsonb, '7513'),
  ('http://data.europa.eu/esco/occupation/439c52ae-23ce-4d1e-bea1-bac135497977', 'Hidrometrista', 'Os hidrometristas medem e mapeiam, por meio de equipamento especializado, ambientes marinhos. Recolhem dados científicos para estudar a topografia e a morfologia submarinas das massas de água.', 'released', '["Engenheiro Hidrógrafo", "Engenheiro Hidrográfico", "Engenheiro Hidrográfica", "Engenheira Hidrógrafa"]'::jsonb, '2165'),
  ('http://data.europa.eu/esco/occupation/43c86ca8-7357-4e8e-9a1c-bae427f61c5e', 'Operador de Prensa Helicoidal', 'Os operadores de prensa helicoidal controlam e ajustam uma prensa helicoidal com o objetivo de executar operações de formação, extrusão e corte de argila em produtos em conformidade com as especificações.', 'released', '["Operador de Prensa Helicoidal", "Operadora de Prensa Helicoidal"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/43d49e27-302b-439d-bce6-86555527edb5', 'Inspetor de Cuidados de Saúde', 'Os inspetores de cuidados de saúde visitam as instalações de cuidados de saúde para assegurar que todos os doentes recebem cuidados adequados, em conformidade com os requisitos legais. Verificam também o correto funcionamento de equipamentos e processos e a correta atuação do pessoal no que respeita à prevenção da propagação de infeções e doenças.', 'released', '["Inspetora de Cuidados de Saúde", "Inspetor de Cuidados de Saúde"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/43eb6228-8241-47d6-875e-7ccc214291d5', 'Técnico de Testes em Baterias', 'Os técnicos de testes em baterias utilizam tampões positivos e negativos para testar a capacidade de resistência da bateria. Também testam baterias rejeitadas para determinar as suas falhas.', 'released', '["Técnico de Testes em Baterias", "Técnica de Testes em Baterias"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/43ee9c1a-59c2-48ee-afcd-c384dca92162', 'Porteiro', 'Os porteiros recebem os hóspedes de hotéis e prestam serviços adicionais relacionados com a assistência com a bagagem e a proteção dos hóspedes, assegurando simultaneamente a segurança.', 'released', '["Porteira", "Porteiro"]'::jsonb, '9621'),
  ('http://data.europa.eu/esco/occupation/441a5b76-2f51-4704-9df7-3b8e715dd3ad', 'Especialista em Ciências Comportamentais', 'Os especialistas em ciências comportamentais investigam, observam e descrevem o comportamento humano na sociedade. Retiram conclusões sobre os motivos que levam o ser humano a realizar determinadas ações, observam as diversas circunstâncias para diferentes comportamentos e descrevem diferentes personalidades. Prestam aconselhamento a organizações e a instituições governamentais neste domínio. Podem também analisar o comportamento dos animais.', 'released', NULL, '2632'),
  ('http://data.europa.eu/esco/occupation/444c9aa9-578d-4a9a-9949-99ef1bacb20e', 'Técnico de Mecânica Automóvel', 'Os técnicos de mecânica automóvel trabalham com os engenheiros de automóveis na operação, reparação, manutenção e ensaio de equipamentos utilizados em veículos motorizados. Em alguns ambientes, como os aeroportos, são responsáveis por manter os equipamentos e os veículos operacionais. Analisam planos técnicos e desenhos para determinar as especificações e os procedimentos de ensaio. Os técnicos de mecânica automóvel utilizam software para garantir o correto funcionamento de partes de um veículo motorizado. Registam os procedimentos e os resultados dos ensaios e formulam recomendações para alterações.', 'released', '["Técnico de Mecânica Automóvel", "Técnica de Manutenção", "Técnica de Mecânica Automóvel", "Técnico de Manutenção"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/44508e7b-f56b-4bfb-9cd6-879838aecd94', 'Urbanista Planejador Territorial', 'Os urbanistas planificadores territoriais visitam sítios a fim de criar projetos e planos de utilização e desenvolvimento dos terrenos. Recolhem e analisam dados sobre o terreno. Os urbanistas planificadores territoriais fornecem aconselhamento sobre a eficiência e a segurança dos planos de desenvolvimento.', 'released', '["Urbanista Planificadora Territorial", "Urbanista Planificador Territorial"]'::jsonb, '2164'),
  ('http://data.europa.eu/esco/occupation/447cfc9c-c0bf-4553-8f47-91f7ce5e51bc', 'Polidor de Vidro', 'Os polidores de vidro acabam as chapas de vidro para fabricar uma variedade de produtos de vidro. Pulem as extremidades do vidro utilizando rodas de esmerilagem e de polimento e pulverizam soluções sobre vidro ou utilizam máquinas de revestimento por vácuo para fornecer uma superfície espelhada.', 'released', '["Polidor de Vidro", "Polidora de Vidro"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/449f6aef-a8e6-4edc-aea4-802a7b773e00', 'Diretor de Distribuição — Setor Agrícola', 'Os diretores de distribuição — setor agrícola planificam a distribuição de matérias-primas agrícolas, sementes e alimentos para animais a diversos pontos de venda.', 'released', '["Diretora de Logística — Setor Agrícola", "Diretora de Distribuição — Setor Agrícola", "Diretor de Logística — Setor Agrícola", "Diretor de Distribuição — Setor Agrícola"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/44b0f118-2a70-4eec-b301-89d7fd84a3d0', 'Operador de Estufa para Secagem de Madeira', 'Os operadores de estufa para secagem de madeira controlam o processo de aplicação de calor a madeira úmida ou «verde», a fim de obter madeira seca utilizável. Dependendo do tipo de forno, o operador de secagem será responsável pela transferência da madeira para o interior e para fora do forno, o controlo da temperatura e a ventilação.', 'released', '["Operador de Estufa para Secagem de Madeira", "Operadora de Estufa para Secagem de Madeira"]'::jsonb, '7521'),
  ('http://data.europa.eu/esco/occupation/44cd9d91-5552-4735-86b8-4b2c5d39efc8', 'Gerente de Lavandaria e Limpeza a Seco', 'Os gerentes de lavandaria e limpeza a seco supervisionam as operações de lavandaria numa lavandaria institucional. Supervisionam o pessoal de lavandaria e limpeza a seco, planificam e aplicam procedimentos de segurança, efetuam encomendas e supervisionam o orçamento da lavandaria. Os gerentes de lavandaria e limpeza a seco garantem o cumprimento das normas de qualidade e a satisfação das expectativas dos clientes.', 'released', '["Gerente de Lavandaria", "Gerentea de Lavandaria e Limpeza a Seco"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/44e0c015-309d-4f67-98a3-1e036966ed7f', 'Gestor Orçamental', 'Os gestores orçamentais avaliam as propostas financeiras dos diferentes serviços antes da concessão de recursos financeiros aos projetos. Acompanham a execução das políticas e procedimentos orçamentais. Trabalham em estreita colaboração com outros serviços na avaliação dos programas, o seu impacto na organização, as receitas que podem gerar e os esforços financeiros necessários.', 'released', '["Gestor Orçamental", "Guarda-Livros", "Contabilista", "Tesoureiro", "Gestora Orçamental", "Analista Orçamental", "Tesoureira", "Gerente"]'::jsonb, '1211'),
  ('http://data.europa.eu/esco/occupation/44ec4c04-c2d4-4b92-bb27-e56f5b096d97', 'Diretor de Segurança Aérea', 'Os diretores de segurança aérea supervisionam a segurança e a segurança das operações aéreas e aconselham as autoridades da aviação civil sobre as alterações dos sistemas de informação dos aeroportos. Elaboram relatórios de análise de segurança, asseguram a conformidade com as normas e a regulamentação e melhoram os procedimentos de segurança aérea.', 'released', '["Diretora de Segurança Aérea", "Gestor de Segurança Operacional do Aeroporto", "Diretora de Segurança do Aeroporto", "Diretor de Segurança do Aeroporto", "Diretor de Segurança Aérea", "Gestora de Segurança Operacional do Aeroporto"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/45037d43-a8f5-4f46-b332-b2935bc305f4', 'Motorista de Veículos de Transporte de Mercadorias', 'Os motoristas de veículos de transporte de mercadorias conduzem veículos, tais como caminhões e carrinhas. Também podem ocupar-se do carregamento e do descarregamento da carga.', 'released', NULL, '8332'),
  ('http://data.europa.eu/esco/occupation/45170a38-b3ae-4a96-90ff-eb45e55600b6', 'Orquestrador', 'Os orquestradores criam arranjos para uma música após ter sido criada por um compositor. Interpretam, adaptam ou reformulam uma composição para outros instrumentos ou vozes, ou para outro estilo. Os orquestradores são especialistas em instrumentos e em técnicas de orquestração, harmonia, polifonia e composição.', 'released', '["Arranjista", "Orquestrador", "Orquestradora"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/4542ff68-f809-4ba1-857c-fd26d0914eaa', 'Técnico de Drenagem de Águas', 'Os técnicos de drenagem de águas instalam e operam bombas, peças sobressalentes, condutas e sistemas de drenagem de águas a vácuo para recolher e remover líquidos e produtos químicos.', 'released', '["Técnico de Drenagem de Águas", "Técnica de Drenagem de Águas"]'::jsonb, '8111'),
  ('http://data.europa.eu/esco/occupation/4543bf7b-8ffb-4ade-88b9-58da34366f04', 'Planejador de Capacidade de Tecnologia da Informação', 'Os planejadores de capacidade de tecnologia da informação asseguram que a capacidade dos serviços e das infraestruturas de tecnologia da informação é suficiente para cumprir os objetivos de nível de serviço acordados, de forma atempada e eficiente em termos de custos. Consideram igualmente todos os recursos necessários para prestar o serviço adequado no domínio da tecnologia da informação, e traçam um plano das necessidades comerciais a curto, médio e longo prazo.;', 'released', '["Gestora de Capacidade Informática", "Gestor de Capacidade Informática", "Planejadora de Capacidade de Tecnologia da Informação", "Gestor de Desempenho de Tecnologia da Informação", "Gestora de Desempenho de Tecnologias de Informação e Comunicação", "Gestora de Desempenho de Tecnologia da Informação", "Gestor de Desempenho de Tecnologias de Informação e Comunicação", "Planejador de Capacidade de Tecnologia da Informação", "Gestor de Desempenho Informático", "Gestora de Desempenho Informático", "TI"]'::jsonb, '2523'),
  ('http://data.europa.eu/esco/occupation/45517bc3-0887-416d-95fe-6ace1b90bddd', 'Gestor Metalúrgico', 'Os gestores metalúrgicos coordenam e implementam calendários de curto e médio prazo para a indústria metalúrgica ou siderúrgica, e coordenam o desenvolvimento, o apoio e a melhoria dos processos siderúrgicos, bem como os esforços de fiabilidade dos departamentos de manutenção e de engenharia. Também colaboram com iniciativas de remediação contínua.', 'released', '["Gestor Metalúrgico", "Gestora Metalúrgica", "Gerente", "Gestora Metalúrgico"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/4552095e-3396-4831-86ad-4fc34ec39a19', 'Agricultor Responsável por Exploração Agrícola', 'Os agricultores responsáveis por explorações agrícolas planeiam e organizam as operações quotidianas, a afetação de recursos e a gestão empresarial das explorações pecuárias e de culturas.;', 'released', '["Agricultora Responsável por Exploração Agrícola", "Agricultor Responsável por Exploração Agrícola"]'::jsonb, '6130'),
  ('http://data.europa.eu/esco/occupation/4553ecf8-1f0c-4bf1-8718-d8a6b95d6fc2', 'Instrutor do Curso de Controle de Tráfego Aéreo', 'Os instrutores do curso de Controlo de Tráfego Aéreo prestam formação em todas as questões relacionadas com as operações em serviços de navegação aérea, como a gestão do tráfego de voo e a comunicação de navegação em aeródromos. Ensinam todas as orientações emitidas pelo controlo do tráfego aéreo com o objetivo de transmitir aos estagiários a noção de segurança e fluxo rápido de tráfego aéreo.', 'released', '["Instrutor do Curso de Controle de Tráfego Aéreo", "Instrutora do Curso de Controle de Tráfego Aéreo"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/4568a282-3904-4dfc-a6ec-e847b3ca90e8', 'Supervisor de Produção de Materiais Plásticos e de Borracha', 'Os supervisores de produção de materiais plásticos e de borracha gerem e coordenam as atividades do pessoal envolvido no fabrico de produtos de materiais plásticos ou de borracha, assegurando que a produção decorre de forma eficiente, segura e eficaz em termos de custos. São responsáveis pela instalação de novas linhas de produção e pela ministração de formação.', 'released', '["Supervisor de Produção de Materiais Plásticos e de Borracha", "Supervisora de Produção de Materiais Plásticos e de Borracha"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/456ed487-02f2-45c9-9213-d0fd8e9a069d', 'Configurador de Aplicações Informáticas', 'Os configuradores de aplicações informáticas identificam, registram e mantêm configurações de aplicações específicas para os usuários, com base nos requisitos dos usuários e nas regras empresariais. Configuram sistemas de software genéricos, a fim de criarem uma versão específica aplicada ao contexto da organização. Estas configurações abrangem desde o ajuste dos parâmetros de base, através da criação de regras e funções empresariais no sistema de tecnologia da informação, ao desenvolvimento de módulos específicos [incluindo a configuração de sistemas comercialmente disponíveis (COTS)]. Além disso, documentam as configurações, efetuam atualizações de configurações e asseguram que as configurações são corretamente implementadas na aplicação.', 'released', '["Responsável Pela Configuração de Aplicações", "Configurador de Aplicações", "Configuradora de Aplicações", "Configuradora de Aplicações Informáticas"]'::jsonb, '2514'),
  ('http://data.europa.eu/esco/occupation/4588cd69-e6a5-4668-94c7-f02a3d86a649', 'Professor de Informática', 'Os professores de informática ensinam aos alunos a teoria e a prática da utilização (básica) do computador. Ensinam aos alunos a literacia digital e, facultativamente, princípios mais avançados da informática. Transmitem aos alunos o conhecimento de programas informáticos e asseguram a correta utilização do equipamento informático. Os professores de informática criam e reveem conteúdos de aula e trabalhos e atualizam-nos de acordo com a evolução tecnológica.', 'released', '["Professor de Informática", "Professora de Informática"]'::jsonb, '2356'),
  ('http://data.europa.eu/esco/occupation/45a28fe1-30a4-4175-af19-e451ada60858', 'Gerente de Cooperativa de Crédito', 'Os gerentes de cooperativa de crédito supervisionam e gerem os serviços associados, e supervisionam o pessoal e as operações das cooperativas de crédito. Informam o pessoal sobre os mais recentes procedimentos e políticas da união de crédito e elaboram os relatórios financeiros.', 'released', '["Analista de Crédito", "Gerentea de Cooperativa de Crédito"]'::jsonb, '1346'),
  ('http://data.europa.eu/esco/occupation/45f8504d-24ac-4bcd-8692-a93acc74204c', 'Técnico de Laboratório de Controle de Qualidade na Marroquinaria', 'Os técnicos de laboratório de controlo de qualidade na marroquinaria realizam testes de controlo laboratorial em conformidade com as normas nacionais e internacionais. Durante os testes de controlo laboratorial, preparam as amostras, tratam dos procedimentos de ensaio, da análise e da interpretação dos resultados, em comparação com as linhas de orientação e as normas, e elaboram relatórios. Estabelecem a ligação com laboratórios subcontratados para a realização dos testes que não podem ser realizados na empresa. Propõem medidas corretivas e preventivas.', 'released', '["Técnico de Laboratório", "Técnica de Laboratório de Controle de Qualidade na Marroquinaria", "Técnica de Laboratório", "Técnico de Laboratório de Controle de Qualidade na Marroquinaria"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/461959ed-6a80-4c33-a75e-26aaeb52a5a7', 'Técnico de Tubulação', 'Os técnicos de tubagem procedem à instalação e manutenção do equipamento de drenagem utilizado nos sistemas de saneamento, tais como tubagens e válvulas. Analisam a concepção e asseguram a instalação adequada do sistema de drenagem, bem como realizam funções de manutenção e reparação.', 'released', '["Técnica de Tubulação", "Técnico de Tubulação"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/46354077-416f-4440-a0c3-dddee9031c05', 'Professor de Cursos Profissionais na Área da Eletricidade e Energia', 'Os professores de cursos profissionais na área da eletricidade e energia formam os alunos no seu domínio de estudos especializado, a eletricidade e energia, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com a eletricidade e energia. Os professores de cursos profissionais na área da eletricidade e energia acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da eletricidade e energia através de trabalhos, testes e exames.', 'released', '["Professor de Cursos Profissionais na Área da Eletricidade e Energia", "Professora de Cursos Profissionais na Área da Eletricidade e Energia"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/463558cd-6e02-43a8-a675-d4e65af70431', 'Fitoterapeuta', 'Os fitoterapeutas recorrem à fitoterapia para o alívio da dor e para o tratamento de doenças como alergias, doenças crônicas ou problemas relacionados com o stress. Estudam as propriedades e os benefícios das plantas e criam um plano de tratamento personalizado para os doentes.', 'released', NULL, '3230'),
  ('http://data.europa.eu/esco/occupation/463a687a-c7e9-469a-bb38-dcdfe1e7e35f', 'Gerente de Loja de Equipamento Áudio e Vídeo', 'Os gerentes de loja de equipamento áudio e vídeo assumem a responsabilidade pelas atividades e pessoal em lojas especializadas.', 'released', '["Gerente de Loja Hifi", "Gerente de Loja Multimédia", "Gerente de Loja de Equipamento Audiovisual", "Gerentea de Loja de Equipamento Áudio e Vídeo"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/4666cccf-cfbc-4296-95b5-67dad2f620d2', 'Instrutor de Condução de Ônibus', 'Os instrutores de condução de ônibus ensinam às pessoas a teoria e a prática de conduzir um ônibus em segurança e em conformidade com os regulamentos. Ajudam os alunos a desenvolver as competências necessárias para a condução e preparam-nos para os exames teóricos de condução e o exame prático de condução.', 'released', '["Instrutora de Condução de Ônibus", "Instrutor de Condução de Ônibus"]'::jsonb, '5165'),
  ('http://data.europa.eu/esco/occupation/46bbecf4-368a-44a8-9262-dcd775ae2c46', 'Perfurador de Poços', 'Os perfuradores de poços operam máquinas e equipamentos de perfuração para criar e manter poços para utilização na extração de minérios e outros líquidos e gases. Registam as operações, procedem à manutenção do equipamento, fecham os poços não utilizados e impedem a contaminação do solo.', 'released', '["Perfurador de Poços", "Perfuradora de Poços"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/46db7e2e-d44d-412a-9a80-02d43111aca8', 'Professor de Fotografia', 'Os professores de fotografia ensinam aos alunos as várias técnicas e estilos de fotografia, como, por exemplo, o retrato (de grupo), a fotografia da natureza, de viagens, macro, subaquáticas, a preto e branco, panorâmica, de movimento, etc.. Proporcionam aos alunos uma noção da história da fotografia, mas centram-se sobretudo numa abordagem prática na suas aulas, nas quais ajudam os alunos a experimentar e a dominar diferentes técnicas de fotografia e a desenvolver o seu próprio estilo. Os professores de fotografia acompanham o progresso dos alunos e organizam exposições para mostrar ao público o trabalho dos alunos.', 'released', '["Professor de Fotografia", "Professora de Fotografia"]'::jsonb, '2355'),
  ('http://data.europa.eu/esco/occupation/46f9d58f-11bd-4d96-b000-ff4490d3009b', 'Professor de Cursos Profissionais de Artes Industriais', 'Os professores de cursos profissionais de artes industriais formam os alunos no seu domínio de estudos especializado, as artes industriais, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com as artes industriais e o trabalho com madeira e metal, tais como carpinteiro ou trabalhador de chapa metálica. Os professores de cursos profissionais de cursos profissionais de artes industriais acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio das artes industriais através de trabalhos, testes e exames.', 'released', '["Professor de Cursos Profissionais de Artes Industriais", "Professora de Cursos Profissionais de Artes Industriais"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/47300afa-5496-484c-8f65-14247a98b2b8', 'Operário da Construção Civil', 'Os operários da construção civil executam tarefas relativas à limpeza e preparação de estaleiros para projetos de engenharia civil. Tal inclui os trabalhos de construção e manutenção de estradas, caminhos-de-ferro e barragens.', 'released', '["Trabalhador não Qualificada da Engenharia Civil", "Operário da Construção Civil", "Operária da Construção Civil", "Trabalhadora não Qualificada da Engenharia Civil"]'::jsonb, '9312'),
  ('http://data.europa.eu/esco/occupation/476420bb-2577-4f79-ad32-186f19c4fd02', 'Piloto de Helicóptero', 'Os pilotos de helicóptero pilotam helicópteros destinados a transportar passageiros e mercadorias de um local para outro. Planeiam os voos com recurso a cartas aeronáuticas e a instrumentos de navegação. Antes da partida, procedem à inspeção dos helicópteros, seguindo listas de controlo para detectar eventuais fugas de líquido hidráulico, comandos inoperacionais, níveis baixos de combustível ou outras condições de falta de segurança.', 'released', '["Pilota de Helicóptero"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/4779055b-f769-4c6d-8e0e-088bb74cfce9', 'Técnico de Limpeza de Piscinas', 'Os técnicos de limpeza de piscinas tratam das atividades diárias de uma instalação de piscinas, tais como piscina, praia e lago. Limpam a instalação, mantêm uma boa atitude para com os clientes e asseguram a segurança global dentro da instalação.', 'released', '["Técnica de Limpeza de Piscinas", "Técnico de Limpeza de Piscinas"]'::jsonb, '9129'),
  ('http://data.europa.eu/esco/occupation/4791e217-d607-40d5-9f84-df1d0a071cbc', 'Consultor de Marketing', 'Os consultores de marketing prestam aconselhamento às empresas no desenvolvimento de estratégias de marketing para fins específicos. Podem prestar aconselhamento e desenvolver estratégias para a entrada de uma marca no mercado, para o relançamento de um produto, para a apresentação de um novo produto ou para o posicionamento de uma imagem comercial. Realizam estudos preliminares sobre a posição da empresa e a perceção dos clientes, a fim de definirem a abordagem de marketing.;', 'released', '["Técnico de Marketing", "Técnica de Marketing", "Consultora de Marketing"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/4795d4e3-c623-47ff-abab-7de97fcb764e', 'Comprador de Espaços Publicitários', 'Os compradores de espaços publicitários compram, em nome dos seus clientes, espaço publicitário na imprensa e nos meios de radiodifusão e de comunicação em linha. Analisam a eficácia e a adequação dos diferentes canais, em função do produto ou serviço, prestando aconselhamento para a tomada de decisões. Procuram negociar o melhor preço, sem comprometer a qualidade dos anúncios publicitários. Prestam apoio ao desenvolvimento e à execução de planos de marketing e publicidade na vertente das comunicações através dos meios de comunicação mais adequados.', 'released', '["Comprador Ade Espaços Publicitários", "Comprador de Espaços Publicitários", "Compradora de Espaços Publicitários"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/479ede81-bd51-4f3b-9d30-4910699fd211', 'Professor de Jornalismo', 'Os professores de Jornalismoe comunicação social são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, o Jornalismo e Comunicação Social, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio do Jornalismo e Comunicação Social, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Jornalismo", "Professor Universitário de Jornalismo", "Professor de Jornalismo", "Professora Universitária de Jornalismo"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/47ae3ed9-e03c-450e-9ea8-aab317545adc', 'Operador de Sala de Controle de Unidade de Processamento de Gás', 'Os operadores de salas de controlo de unidades de processamento de gás realizam uma série de tarefas a partir da sala de controlo de uma unidade de processamento. Acompanham os processos através de representações eletrônicas exibidas em monitores, mostradores e luzes. Introduzem alterações às variáveis e comunicam com outros departamentos, para garantir que os processos decorrem sem problemas e de acordo com os procedimentos estabelecidos. Tomam as medidas adequadas em caso de irregularidades ou de situações de emergência.', 'released', '["Operador de Sala de Controle de Unidade de Processamento de Gás", "Operadora de Sala de Controle de Unidade de Processamento de Gás"]'::jsonb, '3134'),
  ('http://data.europa.eu/esco/occupation/47af27c4-5b45-4cce-ba01-4e96f8cf97b9', 'Operador de Equipamentos de Energia Marítima Renovável', 'Os operadores de equipamentos de energia marítima renovável operam e fazem a manutenção de equipamentos que produzem energia elétrica a partir de fontes marinhas renováveis, como a energia eólica marítima, a energia das ondas ou as correntes de marés. Monitorizam o equipamento de medição para garantir a segurança das operações e a satisfação das necessidades de produção. Tomam igualmente medidas em resposta a problemas do sistema e procedem à reparação de avarias.;', 'released', '["Operadora de Planta ORE", "Operador de Energia das Ondas", "Operador de Fazenda de Marés", "Operadora de Corrente de Maré Marinha", "Operadora de Energia das Ondas", "Operador de Energia Eólica Offshore", "Operadora de Energia Eólica Offshore", "Operador de Corrente de Maré Marinha", "Operador de Planta ORE", "Operador de Fazenda de Ondas", "Operadora de Energia Eólica Marinha", "Operador de Energia Eólica Marinha", "Operador de Energia das Ondas Marinhas", "Operadora de Usina de Energia das Ondas", "Operador de Usina de Energia das Ondas", "Operador de Plataforma de Energia Oceânica", "Operadora de Usina de Energia Renovável Marinha", "Operador de Usina de Energia Renovável Marinha", "Operadora de Plataforma de Energia Oceânica", "Operadora de Fazenda de Marés", "Operadora de Energia das Ondas Marinhas", "Técnico de Energia Eólica Marinha", "Operadora de Fazenda de Ondas", "Técnica de Energia Eólica Marinha", "Operadora de Equipamentos de Energia Marítima Renovável"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/47b747bb-5bbf-40d5-aa3e-8d4a79238502', 'Gerente de Ourivesaria', 'Os gerentes de ourivesaria assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Ourivesaria e Relojoaria", "Gerente de Relojoaria", "Gerentea de Ourivesaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/47c27a07-4657-42b7-adee-d805902c1ff8', 'Operador de Draga', 'Os operadores de draga trabalham com equipamento industrial para remover material subaquático, a fim de tornar a zona acessível a navios, criar portos, instalar cabos, ou para outros fins, e deslocam o material para o local desejado.', 'released', '["Operador de Draga", "Operadora de Draga"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/47dd863b-b124-4bb1-bb42-a9498492a8cb', 'Engenheiro Especialista em Combustíveis Líquidos', 'Os engenheiros especialistas em combustíveis líquidos avaliam os locais de extração de combustível líquido. Estes combustíveis incluem os produtos petrolíferos, o gás natural, o gás de petróleo liquefeito, os combustíveis fósseis não petrolíferos, o biodiesel e os álcoois. Maximizam a recuperação dos hidrocarbonetos a um custo mínimo, com um impacto mínimo no ambiente.', 'released', '["Engenheira Especialista em Combustíveis Líquidos", "Engenheiro Especialista em Combustíveis Líquidos"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/47e4135b-95d1-4462-920c-afcbd7c4d9be', 'Técnico de Equipamentos de Aluguel para Espetáculos', 'Os técnicos de equipamentos de aluguer para espetáculos preparam, fazem a manutenção, enviam, transportam, instalam, programam, operam, rececionam, verificam, limpam e armazenam equipamentos audiovisuais, para espetáculos e eventos. O seu trabalho tem por base planos, instruções e outra documentação.;', 'released', '["Técnica de Equipamentos de Alguer para Espetáculos", "Técnico de Equipamentos de Alguer para Espetáculos", "Técnica de Equipamentos de Aluguel para Espetáculos"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/47e81c7f-2d04-4a60-a8ff-9913c36d8344', 'Assistente de Marketing', 'Os assistentes de marketing prestam apoio a todas as ações e operações realizadas pelos gestores e responsáveis de marketing. Elaboram relatórios sobre as operações de marketing necessários a outros departamentos, especificamente as divisões de contabilidade e financeira. Asseguram a disponibilidade dos recursos de que os gestores necessitam para desempenhar as suas funções. ;', 'released', '["Assistentea de Marketing"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/480d2853-db07-43d4-847f-7ffdd8d368f5', 'Fotojornalista', 'Os fotojornalistas cobrem todos os tipos de eventos noticiosos através de imagens informativas. Contam histórias através da recolha, edição e apresentação de imagens para jornais, revistas, televisão e outros meios de comunicação.', 'released', NULL, '3431'),
  ('http://data.europa.eu/esco/occupation/48318e0f-b54b-4654-b296-47c8e544da23', 'Operador de Canteadeira', 'Os operadores de canteadeira asseguram o correto funcionamento de máquinas que envernizam materiais, na sua maioria, madeira, para aumentar a durabilidade e torná-los estéticos. Também regulam a velocidade da correia, definem o controlo da temperatura para regular o calor, passam cola nas extremidades dos painéis e colocam em funcionamento e regulam a máquina.', 'released', '["Operador de Canteadores", "Operadora de Canteadores", "Operadora de Canteadeira"]'::jsonb, '8189'),
  ('http://data.europa.eu/esco/occupation/484ca14a-8e11-4ae1-ba9c-901cd86df56b', 'Comerciante Grossista de Produtos Farmacêuticos', 'Os comerciantes grossistas de produtos farmacêuticos investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Produtos Farmacêuticos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/4874fa37-0cd1-4a68-aed8-a838851f242d', 'Engenheiro da Linguagem', 'Os engenheiros da linguagem trabalham no domínio da informática e, mais especificamente, no domínio do processamento da linguagem natural. Visam colmatar o fosso existente na tradução entre traduções humanas precisas e tradutores operados automaticamente. Analisam os textos, comparam e rastreiam traduções, e melhoram a linguística das traduções através da programação e de códigos.', 'released', '["Engenheira da Linguagem", "Engenheiro da Linguagem"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/4887c8a5-35d3-44c3-be69-346027e485f0', 'Gestor de Atividades Recreativas', 'Os gestores de atividades recreativas são responsáveis pela gestão da equipe que cria atividades de entretenimento para os hóspedes de uma unidade hoteleira.', 'released', '["Animadora", "Organizadora de Diversões", "Animador", "Gestor de Atividades Recreativas", "Organizador de Diversões", "Gestor de Entretenimento", "Gestora de Atividades Recreativas", "Gestora de Entretenimento", "Gerente"]'::jsonb, '1411'),
  ('http://data.europa.eu/esco/occupation/489b9a38-89a2-425c-95b9-79cec66379e1', 'Pedicura', 'As pedicuras oferecem tratamento cosmético e cuidam dos pés e das unhas dos pés dos clientes. Cortam e moldem as unhas dos pés, fazem lava-pés e tratamentos de esfoliação e aplicam verniz das unhas.', 'released', '["Podólogo", "Podóloga", "Calista"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/48b336d2-7ffb-49a3-a010-444b68ddd12d', 'Cortador Halal', 'Os cortadores halal encomendam, inspecionam e compram carne para a preparar e vender como produtos consumíveis de carne, em conformidade com as práticas islâmicas. Realizam atividades como o corte, o aparo, a desossa, a atadura e a trituração de carne de bovino e de aves de capoeira. Preparam a carne halal para consumo.', 'released', '["Cortadora Halal", "Cortador Halal"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/48c8eccb-4bd0-487e-a187-4953cbbe956e', 'Animador', 'Os animadores utilizam software para a criação de animações, sendo estas imagens dispostas em sequência rápida para criar uma ilusão de movimento.', 'released', '["Animadora", "Animadora 3D", "Especialista de Animação 3D", "Animadora 2D", "Animador 3D", "Animador", "Especialista de Animação 2D", "Designer de Animação 3D", "Animador 2D", "Designer de Animação 2D"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/48cff102-9fe2-4e0f-8156-88fd8a686e6c', 'Operador de Filatórios', 'Os operadores de filatórios convertem fibras em fios.', 'released', '["Operador de Máquinas de Fiação", "Operadora de Filatórios", "Operador de Filatórios", "Operadora de Máquinas de Fiação"]'::jsonb, '8151'),
  ('http://data.europa.eu/esco/occupation/49023c69-302f-4671-b26f-7229d1a53915', 'Professor de Ciências da Comunicação', 'Os professores de Ciências da Comunicação são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências da Comunicação, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio das Ciências da Comunicação, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor de Ciências da Comunicação", "Professora de Ciências da Comunicação", "Professora Universitária de Ciências da Comunicação", "Professor Universitário de Ciências da Comunicação"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/490d0c6f-0dc8-4825-9f17-207749fb1785', 'Técnico de Reparações de Caixas Automáticos', 'Os técnicos de reparações de caixas automáticos procedem à instalação, ao diagnóstico, à manutenção e à reparação de caixas automáticos. Viajam atá à localização dos clientes para prestarem os seus serviços. Os técnicos de reparações de caixas automáticos utilizam ferramentas manuais e software para consertar os distribuidores de dinheiro com avaria.', 'released', '["Técnica de Reparações de Caixas Automáticos", "Técnico de Reparações de Caixas Automáticos"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/4910419f-b4af-4f59-b544-9dbebc8a74f0', 'Eletricista', 'Os eletricistas instalam e reparam circuitos elétricos e sistemas de cablagem. Também procedem à instalação e manutenção de equipamento elétrico e máquinas. Este trabalho pode ser realizado no interior e no exterior, em quase todos os tipos de instalações.', 'released', NULL, '7411'),
  ('http://data.europa.eu/esco/occupation/491cf76d-eb0d-4f15-90f0-3f5c9b11472a', 'Controlador da Qualidade dos Jogos de Azar', 'Os controladores da qualidade dos jogos de azar concebem e planificam métodos de testar os jogos de azar, de lotaria ou de apostas. Realizam eles próprios os testes. Estes jogos podem destinar-se quer ao grande público quer a um público privado, sendo os testes feitos tanto aos jogos em linha como aos jogos físicos.;', 'released', '["Controlador da Qualidade dos Jogos de Fortuna e Azar, de Apostas e de Lotaria", "Controladora da Qualidade dos Jogos de Fortuna e Azar, de Apostas e de Lotaria", "Controladora da Qualidade dos Jogos de Azar"]'::jsonb, '2120'),
  ('http://data.europa.eu/esco/occupation/49607371-2712-4b0a-8d7c-1b4bc22d9581', 'Diretor de Distribuição Madeiras e Produtos de Construção', 'Os diretores de distribuição madeiras e produtos de construção planificam a distribuição de madeira e materiais de construção a diversos pontos de venda.', 'released', '["Diretor de Logística Madeiras e Produtos de Construção", "Diretora de Logística Madeiras e Produtos de Construção", "Diretora de Distribuição Madeiras e Produtos de Construção", "Diretor de Distribuição Madeiras e Produtos de Construção"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/49713da4-4e97-4f82-bd1c-16ce7f9179b7', 'Caracterizador', 'Os caracterizadores ajudam e apoiam os artistas antes, durante e após o espetáculo e a filmagem de filmes ou programas de televisão para garantir que a maquilhagem está em consonância com a visão artística do diretor e da equipe artística. Criam imagens e carateres através de maquilhagem e próteses. Procedem à manutenção, controlam e reparam próteses e assistem com mudanças rápidas. ;', 'released', '["Caracterizadora", "Maquilhadora Especializada em Moda", "Maquilhador Especializada em Moda", "Caractrerizador"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/4975c4cc-a89f-4ea8-82aa-501258dfb2f9', 'Verificador de Seguros', 'Os verificadores de seguros avaliam e determinam o risco e a cobertura de seguros patrimoniais de clientes. Analisam e reveem as políticas de subscrição de acordo com a regulamentação legal.', 'released', '["Verificadora de Seguros", "Verificador de Seguros"]'::jsonb, '3321'),
  ('http://data.europa.eu/esco/occupation/497a65bf-04e5-48ed-939e-2a68419f8144', 'Enólogo', 'Os enólogos seguem o processo de fabrico do vinho na sua totalidade e supervisionam os trabalhadores nas empresas vinícolas. Supervisionam e coordenam a produção para garantir a qualidade do vinho e prestam aconselhamento para a determinação do valor e da classificação dos vinhos produzidos.', 'released', '["Enólogo", "Enóloga", "Especialista em Vinhos"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/499f80e3-860c-48ef-8286-be929a93e254', 'Escanção', 'Os escanções armazenam, preparam, aconselham e servem vinho e outras bebidas alcoólicas.', 'released', '["Escanção", "Escançã", "Escançãa"]'::jsonb, '5131'),
  ('http://data.europa.eu/esco/occupation/49b21ca8-04be-4912-a2f7-0170550e18fa', 'Operador de Máquina de Encadernação', 'Os operadores de máquina de encadernação cuidam das máquinas que encadernam papel impresso ou não impresso em volumes, utilizando agrafos, cordéis, cola ou outras tecnologias de união.', 'released', '["Operadora de Máquina de Encadernação", "Operador de Máquina de Encadernação"]'::jsonb, '7323'),
  ('http://data.europa.eu/esco/occupation/49c3db8c-c586-42d1-9726-f65d8303c0b1', 'Lexicógrafo', 'Os lexicógrafos redigem e compilam conteúdos para dicionários. Determinam igualmente as palavras novas de uso comum que devem ser incluídas no glossário.', 'released', '["Lexicógrafa", "Lexicógrafo"]'::jsonb, '2643'),
  ('http://data.europa.eu/esco/occupation/49ca9fe4-4513-4657-b27f-eaad11e6158a', 'Gestor de Lotaria', 'Os gestores de lotaria organizam e coordenam as atividades de uma organização de lotaria. Supervisionam as operações diárias e facilitam as comunicações entre o pessoal e os clientes. Analisam os procedimentos de lotaria, definem os preços, treinam o pessoal e procuram melhorar a rentabilidade das suas atividades. Assumem a responsabilidade por todas as atividades de lotaria e asseguram a observância das regras e regulamentos pertinentes em matéria de lotaria.', 'released', '["Promotor de Lotaria", "Gestor de Operações de Lotaria", "Gestora de Operações de Lotaria", "Gestor de Lotaria", "Gestora de Lotaria", "Promotora de Lotaria", "Gerente"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/49e28648-4fa8-4b36-ac4d-781c108547bf', 'Controlador de Transportes de Mercadorias', 'Os controladores de transportes de mercadorias recebem e transmitem mensagens fiáveis, registam veículos e equipamentos, bem como outras informações importantes. Supervisionam as operações de planejamento de transporte através da coordenação de diferentes modos de transporte. Os controladores de transportes de mercadorias delineiam itinerários ou serviços e determinam o modo de transporte adequado. Também são responsáveis pela manutenção do equipamento e dos veículos, bem como pelo transporte dos trabalhadores. Os controladores de transportes de mercadorias fornecem a documentação jurídica e contratual às partes envolvidas no transporte.', 'released', '["Controlador de Transportes de Mercadorias", "Despachante de Transporte de Mercadorias", "Controladora de Transportes de Mercadorias"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/49e4e358-8ba3-4a05-8ef9-abb73156f5f7', 'Quiroprático', 'Os quiropráticos são responsáveis pelo diagnóstico, tratamento e prevenção das doenças relacionadas com o sistema neuromusculoesquelético e os efeitos destas doenças na saúde geral. São profissionais de cuidados de saúde primários independentes.', 'released', '["Osteopata", "Quiroprática", "Quiroprático"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/49f1e9aa-189b-4417-afaa-373cc4ffeea1', 'Operador de Estiramento de Vidro', 'Os operadores de estiramento de vidro são responsáveis pela produção de chapas de vidro plano contínuo através de estiramento de vidro que transforma vidro fundido.', 'released', '["Operadora de Estiramento de Vidro", "Operador de Estiramento de Vidro"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/4a1125ee-5728-4b1f-b655-7b8eb2e27660', 'Gerente de Restaurante de Refeições Rápidas', 'Os gerentes de restaurante de refeições rápidas gerem as operações num restaurante de serviço rápido.', 'released', '["Supervisor de Restaurante de Refeições Rápidas", "Supervisora de Restaurante de Refeições Rápidas", "Gerentea de Restaurante de Refeições Rápidas"]'::jsonb, '5246'),
  ('http://data.europa.eu/esco/occupation/4a13bafa-a2ac-4864-a278-176ea5969280', 'Representante de Vendas de Ferramentas Manuais e Artigos para Canalizações e Aquecimento', 'Os representantes de vendas de ferramentas manuais e artigos para canalizações e aquecimento prestam serviços em nome de uma empresa para vender as suas mercadorias, fornecendo simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Ferramentas Manuais e Artigos para Canalizações e Aquecimento"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/4a1d28b0-eca5-4c0a-a49d-ce974e7d04ce', 'Operador de Retificadoras Planas', 'Os operadores de retificadoras planas instalam e asseguram o correto funcionamento de retificadoras planas concebidas para aplicar processos abrasivos, a fim de remover pequenas quantidades de material em excesso e suavizar as peças metálicas, mediante uma mó abrasiva, ou afiadora, por rotação num eixo horizontal ou vertical.', 'released', '["Operador de Retificadoras Planas", "Operadora de Retificadoras Planas"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/4a215d87-8363-4db2-a661-3c0d816b2a70', 'Mineiro de Superfície', 'Os mineiros de superfície procedem a uma vasta gama de operações de extração mineira de superfície, envolvendo frequentemente um elevado nível de consciência espacial, tal como a bombagem, a supressão de poeiras e o transporte de materiais, incluindo areia, pedra e argila até ao ponto de produção.', 'released', '["Mineira de Superfície", "Mineiro de Superfície"]'::jsonb, '8111'),
  ('http://data.europa.eu/esco/occupation/4a246568-007e-46a8-a151-b98082ed6b50', 'Operador de Máquinas de Fabricação de Solas e Tacões', 'Os operadores de máquinas de fabrico de solas e tacões fixam as solas ou tacões ao calçado através de costura, cola ou cravejamento. Podem trabalhar com várias máquinas, por exemplo, para puxar as gáspeas, ou para desbastar, limpar o pó ou fixar os tacões. Também operam diferentes máquinas, tanto para construções por costura como por cola.', 'released', '["Operadora de Fixação de Solas e Tacões", "Operador de Máquinas de Fabricação de Solas e Tacões", "Operadora de Máquinas de Fabricação de Solas e Tacões", "Operador de Fixação de Solas e Tacões"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/4a29eab1-5f02-4723-a863-e2d5a0614dfa', 'Diretor de Instituição de Cuidados de Saúde', 'Os diretores de instituição de cuidados de saúde supervisionam as operações das instituições de cuidados de saúde, tais como hospitais, instalações de reabilitação, serviços de cuidados ao domicílio e instituições de cuidados a idosos, a fim de assegurar que a organização cumpre os requisitos, que os doentes e os residentes são tratados, que a organização se mantém e que o equipamento necessário está presente. Supervisionam também o pessoal e asseguram a manutenção dos registos.', 'released', '["Diretor Clínico", "Diretora do Serviço de Cirurgia", "Diretora de Instituição de Cuidados de Saúde", "Diretor do Serviço de Cirurgia", "Diretor de Instituição de Cuidados de Saúde", "Diretora Clínica"]'::jsonb, '1342'),
  ('http://data.europa.eu/esco/occupation/4a30b421-2fda-42d6-b7e1-1c31753f061d', 'Operador de Máquinas de Acabamento de Tubos Isolantes', 'Os operadores de máquinas de acabamento de tubos isolantes instalam e operam uma máquina para acabar tubos isolantes e cortá-los de acordo com as dimensões especificadas.', 'released', '["Operador de Máquinas de Acabamento de Tubos Isolantes", "Operadora de Máquinas de Acabamento de Tubos Isolantes"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/4a375b68-88a0-4e5f-99ce-9b01341dfb81', 'Engenheiro de Materiais', 'Os engenheiros de materiais investigam e concebem materiais novos ou melhorados para um número diversificado de aplicações. Analisam a composição dos materiais, realizam experiências e desenvolvem novos materiais para uma utilização específica da indústria, nomeadamente a borracha, os têxteis, o vidro, os metais e os produtos químicos. Aconselham as empresas em matéria de avaliações de danos, de garantia de qualidade dos materiais e de reciclagem de materiais.', 'released', '["Engenheira de Materiais", "Engenheiro de Materiais"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/4a39fddb-17e7-4431-be03-613edab8d1c8', 'Agente Tributário', 'Os agentes tributários cobram taxas, dívidas e impostos em nome de instituições governamentais em cidades, municípios e outras jurisdições. Desempenham funções administrativas e comunicam com outros funcionários e instituições, a fim de assegurar que as operações são corretas e estão em conformidade com as políticas.', 'released', '["Agente Tributária", "Agente Tributário", "Agentea Tributário"]'::jsonb, '3352'),
  ('http://data.europa.eu/esco/occupation/4a3f40a8-0587-494c-b8d3-7098b8c5992f', 'Praça do Exército', 'Os praças do Exército supervisionam secções de soldados e executam tarefas de instrução. Além disso, controlam equipamento como máquinas pesadas e armas.', 'released', '["Primeiro Cabo", "Soldado", "Segundo Cabo", "Cabo de Secção"]'::jsonb, '0210'),
  ('http://data.europa.eu/esco/occupation/4a5b3686-eea4-4ba0-b446-33f7b6a95aed', 'Técnico de Anatomia Patológica', 'Os técnicos de anatomia patológica prestam assistência a médicos especialistas em patologia na condução de exames post-mortem, mantendo registos das amostras, dos espécimes, dos órgãos e das respetivas conclusões e tomando as medidas necessárias à sua eliminação adequada sob supervisão, seguindo as ordens do médico.', 'released', '["Técnico de Anatomia Patológica", "Técnica de Anatomia Patológica"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/4a5ceaae-0f05-4091-bdbf-59f250ce6374', 'Operador de Equipamentos Térmicos de Tratamento de Plásticos', 'Os operadores de equipamentos térmicos de tratamento de plástico manipulam produtos de plástico utilizando máquinas, tais como fornos ou máquinas de endurecimento, para temperar, recozer ou tratar termicamente. Instalam a máquina e leem as instruções de produção para determinar a temperatura do forno. Os operadores de equipamentos térmicos de tratamento de plásticos retiram produtos de máquinas, deixam-nos arrefecer, examinam e testam os produtos a fim de verificar se estão em conformidade com as especificações.', 'released', '["Operador de Equipamentos Térmicos de Tratamento de Plástic", "Operadora de Equipamentos Térmicos de Tratamento de Plástic", "Operadora de Equipamentos Térmicos de Tratamento de Plásticos"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/4ac3c3a0-eb56-491f-8d21-1e5539a05b54', 'Treinador de Cavalos', 'Os treinadores de cavalos treinam animais e/ou cavaleiros para fins gerais e específicos, incluindo assistência, segurança, lazer, competição, transporte, obediência e lida diária, entretenimento e educação, em conformidade com a legislação nacional.', 'released', '["Treinadora de Cavalos", "Treinador de Cavalos"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/4ad4024e-d1d3-4dea-b6d1-2c7948111dce', 'Técnico de Veículos a Motor', 'Os técnicos de veículos a motor procedem à inspeção, teste e manutenção de veículos, motociclos, afinações dos motores e substituição de pneus. Reparam falhas dos motores e substituem os lubrificantes. Os técnicos de veículos a motor substituem os componentes do veículo e avaliam as opções de garantia. ; ;', 'released', '["Técnico de Veículos a Motor", "Técnica de Veículos a Motor"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/4ae3ad16-2d33-406c-8497-c66f7d61b914', 'Vendedor de Artigos em Segunda Mão', 'Os vendedores de artigos em segunda mão vendem artigos em segunda mão, tais como livros, vestuário, aparelhos, etc., em lojas especializadas.', 'released', '["Vendedora de Artigos em Segunda Mão", "Alfarrabista", "Vendedor de Artigos Usados", "Vendedora de Artigos Usados", "Vendedor de Artigos em Segunda Mão"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/4ae470fc-bcf8-4704-abd5-e086ebb1552c', 'Responsável Pela Gestão de Sócios', 'Os responsáveis pela gestão de sócios supervisionam e coordenam o plano de adesão de sócios, prestam apoio aos sócios existentes e estabelecem contatos com potenciais novos sócios. Analisam os relatórios sobre as tendências do mercado e desenvolvem planos de marketing em conformidade. Os responsáveis pela gestão de sócios acompanham e asseguram a eficiência dos processos, sistemas e estratégias.', 'released', NULL, '2431'),
  ('http://data.europa.eu/esco/occupation/4b05bef2-ded4-4b09-ab94-f4c6a555a775', 'Assistente Social', 'Os assistentes sociais são profissionais que desenvolvem ações de caráter prático, tendo em vista promover a mudança e o desenvolvimento social, a coesão social e a capacitação e a libertação dos indivíduos. Interagem com indivíduos, famílias, grupos, organizações e comunidades, a fim de implementarem várias formas de terapia e aconselhamento, trabalho de grupo e trabalho comunitário. Os assistentes sociais prestam orientação aos indivíduos na utilização de serviços para reclamar benefícios, aceder aos recursos da comunidade, encontrar emprego e formação, obter aconselhamento jurídico ou resolver assuntos noutros departamentos da autoridade local.', 'released', '["Assistentea Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/4b1b1c9c-579c-45c8-8a34-db39f544c031', 'Vendedor de Mobiliário', 'Os vendedores de mobiliário vendem mobiliário e outros artigos de uso doméstico em lojas especializadas.', 'released', '["Vendedor de Mobiliário", "Vendedora de Mobiliário"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/4b214899-ed00-4156-b269-a23df0fb1093', 'Gestor Ambiental', 'Os gestores ambientais prestam aconselhamento sobre o desenvolvimento de políticas ambientais junto de instituições governamentais e oficiais. Analisam eventuais ameaças ao bem-estar das pessoas e do ambiente numa região e gerem campanhas destinadas a resolver problemas como a recolha de resíduos, os aterros e a preservação de zonas verdes.', 'released', '["Gestor Ambiental", "Engenheira do Ambiente", "Gestora Ambiental", "Engenheiro do Ambiente", "Gerente"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/4b3201cb-ffc5-4f61-9fc3-5c0f0038fa5f', 'Gestor de Análise de Negócios de Informática', 'Os gestores de análise de negócios de informática identificam os domínios em que são necessárias alterações ao sistema de informação, com o objetivo de apoiarem os planos de negócios e de monitorarem o impacto em termos de gestão de mudanças. Contribuem para os requisitos funcionais gerais dos sistemas informáticos da organização empresarial. Os gestores de análise de negócios de informática analisam as necessidades da empresa e traduzem-nas em soluções informáticas.', 'released', '["Analista de Negócios de Tecnologia da Informação", "Analista de Negócios de Informática", "Gestora de Análise de Negócios de Informática", "Gestor de Análise de Negócios de Informática", "Analista de Negócios de Tecnologias de Informação e Comunicação", "Gerente"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/4b536ea7-ebac-4f75-8356-94eb639f1ecc', 'Supervisor de Impressão', 'Os supervisores de impressão organizam a atividade de uma ou mais equipes de operadores de máquinas nos domínios da impressão, encadernação de livros e acabamento de materiais impressos. Têm por objetivo otimizar os processos de produção.', 'released', '["Supervisor de Impressão", "Supervisora da Impressão", "Supervisora de Impressão"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/4b6a55a8-8ec9-4ae2-9f62-ebcea1fa93d0', 'Operador de Máquinas de Papel', 'Os operadores de máquinas de papel asseguram o correto funcionamento da máquina que recebe pasta de papel, espalha-a sobre um crivo e drena a água. Em seguida, a pasta é espremida e seca para produzir papel.', 'released', '["Operadora de Máquinas de Fabricação de Papel", "Operador de Máquinas de Papel", "Operadora de Máquinas de Papel"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/4b6b09e6-e1f6-46d8-b16a-d3522c367983', 'Operador de Retificadoras Cilíndricas', 'Os operadores de retificadoras cilíndricas instalam e asseguram o correto funcionamento de retificadoras cilíndricas concebidas para aplicar processos abrasivos, a fim de remover pequenas quantidades de material em excesso e suavizar as peças metálicas, mediante múltiplas rodas de esmerilagem com dentes de diamante como dispositivo de corte para cortes muito precisos e leves, à medida que a peça é maquinada e formada num cilindro.', 'released', '["Operadora de Retificadoras Cilíndricas", "Operador de Retificadoras Cilíndricas"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/4b709f9e-6112-4d58-81b0-2d6e6a69d61b', 'Engenheiro Técnico Alimentar', 'Os engenheiros técnicos alimentares desenvolvem processos para o fabrico de gêneros alimentícios e produtos afins, com base em princípios e tecnologias de natureza química, física e biológica. Concebem e realizam planos ou equipamento, supervisionam o pessoal e participam no controlo e melhoria das tecnologias alimentares nos processos de produção alimentar.', 'released', '["Técnica de Produção Alimentar", "Engenheiro Técnico Alimentar", "Engenheira Técnica Alimentar", "Técnico de Produção Alimentar", "Engenheira Técnico Alimentar"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/4b72d306-9781-434d-8522-1fcaf892cdce', 'Transitário de Transportador não Operador de Navios', 'Os transitários de transportadores não operadores de navios (NVOCC) são os intermediários de transações marítimas que compram espaço a um transportador e subvendem esse espaço a carregadores mais pequenos. Emitem conhecimentos de embarque, publicam tarifas e operam, além disso, como transportadores marítimos comuns.', 'released', '["Transitário de Transportador não Operador de Navios", "Transitário de Non-Vessel Operating Common Carrier (NVOCC)", "Transitária de Transportador não Operador de Navios", "Transitária de Non-Vessel Operating Common Carrier (NVOCC)"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/4b759f0e-8fec-4cf5-80d4-d112a9fd4e51', 'Oceanógrafo', 'Os oceanógrafos estudam e investigam questões relacionadas com o mar e os oceanos. Os oceanógrafos dividem os seus conhecimentos em diferentes ramos de investigação: a oceanografia física cuja investigação incide sobre ondas e marés, a oceanografia química cujos estudos dizem respeito à constituição química das águas do mar e a oceanografia geológica cuja investigação se refere ao fundo dos mares e suas placas.;', 'released', '["Geólogo Marinho", "Oceanógrafa", "Oceanógrafo", "Geóloga Marinha"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/4b8dced3-ac9e-445d-8787-e07daf52e295', 'Técnico de Laboratório nas Indústrias do Couro', 'Os técnicos de laboratório nas indústrias do couro realizam análises químicas e testes físicos ao couro e comunicam os seus resultados. Também realizam análises químicas aos produtos auxiliares, às emissões ambientais e às descargas e comunicam os seus resultados. Asseguram que os testes são realizados de acordo com normas adequadas a nível nacional, internacional ou específicas do cliente.', 'released', '["Técnica de Laboratório nas Indústria do Couro", "Técnico de Laboratório nas Indústria do Couro", "Técnica de Laboratório nas Indústrias do Couro"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/4bc4170d-f4df-44e4-a3be-394242ae3017', 'Operador de Títulos', 'Os operadores de títulos compram e vendem títulos como ações, obrigações e participações, por sua conta ou em nome dos seus empregadores, com base nos conhecimentos especializados que têm dos mercados financeiros. Acompanham o desempenho dos títulos transacionados, avaliando a sua estabilidade ou tendências especulativas. Registam e arquivam todas as transações de títulos e tratam da sua documentação financeira.;', 'released', '["Trader de Títulos", "Operador de Títulos", "Operadora de Títulos"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/4bdc4e52-1c9c-4d80-898a-18522d905fee', 'Assistente Social Especialista em Delinquência Juvenil', 'Os assistentes sociais especialistas em delinquência juvenil prestam apoio a jovens delinquentes, impedindo a sua reincidência, prestando aconselhamento em matéria de mudanças comportamentais, encaminhando-os para agências que disponibilizam alojamento, ajudando-os a regressar à escola, envolvendo-os em atividades construtivas, visitando-os quando se encontram em centros educativos e avaliando os riscos futuros.', 'released', '["Assistentea Social Especialista em Delinquência Juvenil"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/4be03a63-0423-4e50-acbf-aec405bb0741', 'Técnico de Serviços de Informação Aeronáutica', 'Os técnicos de serviços de informação aeronáutica mantêm atualizado o cronograma das operações desde o nascer até ao pôr do sol, a fim de assegurarem a autenticidade das informações transmitidas pelas agências. Procuram garantir a segurança, a regularidade e a eficiência.', 'released', '["Técnica de Serviços de Informação Aeronáutica"]'::jsonb, '3154'),
  ('http://data.europa.eu/esco/occupation/4be368e3-badb-4b9f-9d0a-4d0f7565540a', 'Engenheiro Especialista em Prevenção e Proteção Contra Incêndios', 'Os engenheiros especialistas em prevenção e proteção contra incêndios estudam, concebem e desenvolvem soluções inovadoras para a prevenção de incêndios e a proteção das pessoas, dos sítios naturais e das zonas urbanas. Propõem materiais adequados para a construção, o vestuário ou outras aplicações e concebem sistemas de detecção destinados a prevenir incêndios ou a sua propagação.', 'released', '["Engenheira Especialista em Prevenção e Proteção Contra Incêndios", "Engenheiro Especialista em Prevenção e Proteção Contra Incêndios"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/4be4ea31-1211-4f0c-82bb-f6fe10791f4d', 'Diretor Executivo de Aeroporto', 'Os diretores executivos de aeroporto são responsáveis por um grupo de diretores de aeroporto, que são responsáveis por todas as áreas do aeroporto. Tomam decisões sobre a direção estratégica do aeroporto com base nas informações fornecidas pela sua equipe de gestores.', 'released', '["Diretor Executivo de Aeroporto", "Diretora Executiva de Aeroporto", "Diretora Executivo de Aeroporto"]'::jsonb, '1120'),
  ('http://data.europa.eu/esco/occupation/4bef1707-a251-427e-9d8b-96595ec38d45', 'Editor de Livros', 'Os editores de livros têm como função procurar manuscritos que possam ser publicados. Reveem os textos dos autores, a fim de avaliarem o seu potencial comercial, ou solicitam aos autores que assumam os projetos que a editora pretende publicar. Os editores de livros mantêm boas relações com os autores.', 'released', '["Editora de Livros", "Editor de Livros"]'::jsonb, '2641'),
  ('http://data.europa.eu/esco/occupation/4c313f2a-704e-4d3c-a7c2-98e1b93c9e94', 'Diretor de Importação e Exportação de Mobiliário de Escritório', 'Os diretores de importação e exportação de mobiliário de escritório implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Vendas de Mobiliário de Escritório", "Diretora de Vendas de Mobiliário de Escritório", "Diretora de Importação e Exportação de Mobiliário de Escritório", "Diretor de Importação e Exportação de Mobiliário de Escritório"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/4c40c1e8-0584-4a77-8ca3-ec82538f9488', 'Assistente Social Especialista em Prestações Familiares', 'Os assistentes sociais especialistas em prestações familiares orientam os indivíduos na área da ação social para os ajudar a resolver problemas específicos da sua vida pessoal, tratando problemas pessoais e de relacionamento, conflitos internos, depressão e dependências. Procuram capacitar os indivíduos para concretizarem mudanças e melhorarem a sua qualidade de vida. Podem igualmente prestar apoio e aconselhamento aos utentes no que respeita ao requerimento das suas prestações de segurança social.', 'released', '["Assistentea Social Especialista em Prestações Familiares"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/4c6b3657-316e-43b5-872a-ea763411190d', 'Delegado Comercial para Venda de Eletricidade', 'Os delegados comerciais para venda de eletricidade avaliam as necessidades energéticas dos clientes e recomendam a compra dos serviços de fornecimento de eletricidade oferecidos pela sua empresa. Promovem os serviços da sua empresa e negoceiam as condições de venda com os clientes.', 'released', '["Delegada Comercial para Venda de Eletricidade", "Delegado Comercial para Venda de Eletricidade"]'::jsonb, '3322'),
  ('http://data.europa.eu/esco/occupation/4c715719-3c3f-4058-ba00-9b2ef34848e8', 'Diretor de Relações com Investidores', 'Os diretores de relações com investidores divulgam a estratégia de investimento da empresa e acompanham as reações da comunidade de investimento em relação à mesma. Utilizam conhecimentos especializados em matéria de marketing, finanças, comunicações e legislação sobre títulos financeiros para assegurar uma comunicação transparente com a comunidade mais alargada. Respondem a pedidos de informação de acionistas e investidores relacionados com a estabilidade financeira, as ações ou as políticas empresariais da empresa.', 'released', '["Diretor de Relações com Investidores", "Diretora de Relações com Investidores"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/4c86c7c1-0839-456e-856f-65396d1f39d7', 'Operador de Bobinadeiras', 'Os operadores de bobinadeiras operam máquinas que enrolam fios, cordas, cordéis, cabos em bobinas, canelas ou carretéis. Manuseiam os materiais, preparam-nos para transformação e utilizam bobinadeiras para o efeito. Também realizam a manutenção de rotina da máquina.', 'released', '["Operador de Bobinadeiras", "Operadora de Bobinadeiras"]'::jsonb, '8151'),
  ('http://data.europa.eu/esco/occupation/4c89c65c-4e35-44e3-8fa0-5d73e9e15325', 'Técnico de Apoio Familiar', 'Os técnicos de apoio familiar prestam conselhos práticos e apoio emocional às famílias que atravessam dificuldades, tais como situações de dependência, deficiência, doença, progenitores reclusos, dificuldades matrimoniais e financeiras. Aconselham sobre se a permanência das crianças junto das suas famílias é a solução mais adequada, em função da situação familiar específica. Os técnicos de apoio familiar também fornecem informações sobre os serviços disponíveis com base nas necessidades específicas da família e nas recomendações do assistente social.;', 'released', '["Técnica de Apoio Familiar", "Técnico de Apoio Familiar"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/4c9ca706-3973-4926-854d-44011662ca83', 'Técnico de Proteção Contra Incêndios', 'Os técnicos de proteção contra incêndios instalam e efetuam a manutenção de equipamento de proteção contra incêndios, como extintores, alarmes de incêndio, sistemas de detecção de incêndios ou sistemas de aspersores em instalações, a fim de garantir a conformidade com as normas de segurança e a proteção contra os riscos de incêndio. Inspecionam o equipamento para assegurar a sua funcionalidade e efetuam reparações.', 'released', '["Técnica de Proteção Contra Incêndios", "Técnico de Proteção Contra Incêndios"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/4ca8ba6c-dc55-40c0-ae6c-d55c94dd2e03', 'Especialista em Informações no Âmbito da Segurança Interna', 'Os especialistas em informações no âmbito da segurança interna desenvolvem e executam planos de recolha de dados e informações. Analisam as linhas de investigação que lhes permitem obter as informações necessárias e contactam e entrevistam as pessoas que poderão fornecer essas informações. Redigem relatórios sobre os resultados obtidos e desempenham funções administrativas para assegurar a manutenção dos registos.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/4cbe5a17-056c-489a-9f10-f9d816905000', 'Patrulheiro', 'Os patrulheiros patrulham áreas designadas para garantir uma sensação de segurança com o público, e fornecem apoio geral. Controlam comportamentos suspeitos e cooperam com a polícia e com outras instituições locais para manter a segurança e o bem-estar da comunidade, para aplicar a lei e, quando necessário, sanções.', 'released', '["Agente de Segurança", "Patrulheira", "Guarda", "Patrulheiro"]'::jsonb, '5419'),
  ('http://data.europa.eu/esco/occupation/4cc98057-8ed5-4b45-855b-7a67bc2e5bae', 'Correspondente', 'Os correspondentes investigam e redigem notícias de importância internacional para jornais, revistas especializadas, revistas, rádio, televisão e outros meios de comunicação social. Estão sediados num país estrangeiro.', 'released', '["Correspondentea"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/4cdfac8c-b000-4279-985e-31bc1fbe2447', 'Mineiro de Subsolo', 'Os mineiros de subsolo executam uma vasta gama de atividades relacionadas com a exploração mineira subterrânea, tais como inspeções, vigilância de transportadores e transporte de equipamento e materiais consumíveis desde a superfície até ao ponto de extração subterrânea.', 'released', '["Mineiro de Subsolo", "Mineira de Subsolo"]'::jsonb, '8111'),
  ('http://data.europa.eu/esco/occupation/4ce42c3c-8a46-40b6-9274-1f5cee3c5cba', 'Médico Veterinário Oficial Inspetor Sanitário', 'Os médicos veterinários oficiais inspetores sanitários são profissionais com uma formação científica abrangente. Têm autoridade para exercer, de forma independente, ética e pessoalmente responsável, todas as atividades veterinárias, com especial destaque para a saúde e o bem-estar dos animais e a saúde pública, em conformidade com a legislação nacional e internacional. São responsáveis por programas nacionais de erradicação de doenças animais, pela proteção da saúde pública e pela inspeção alimentar ou animal, pela circulação de animais e pela importação e exportação de animais vivos e seus produtos.', 'released', '["Inspetor Sanitário", "Médica Veterinária Oficial Inspetora Sanitária", "Inspetora Sanitária", "Médica Veterinária Oficial", "Médico Veterinário Oficial", "Médico Veterinário Oficial Inspetor Sanitário", "Médica Veterinário Oficial Inspetor Sanitário"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/4cf7be91-fed9-47a7-9ca9-e74c7eb6becb', 'Técnico de Impressão em 3D', 'Os técnicos de impressão em 3D prestam assistência na concepção e na programação de produtos, incluindo desde produtos protésicos até miniaturas 3D. Podem igualmente efetuar trabalhos de manutenção em impressoras 3D, verificar representações em 3D para os clientes e realizar testes de impressão em 3D. Os técnicos de impressão em 3D podem igualmente efetuar trabalhos de reparação, manutenção e limpeza de impressoras 3D.', 'released', '["Técnica de Impressão em 3D", "Técnico de Impressão em 3D"]'::jsonb, '3118'),
  ('http://data.europa.eu/esco/occupation/4d102082-8d43-4c59-81ab-08a7509f3c40', 'Perchista', 'Os perchistas instalam e operam o microfone de vara, à mão, num braço ou numa plataforma móvel. Asseguram que cada microfone esteja corretamente colocado no cenário e na melhor posição para captar os diálogos. Os perchistas também são responsáveis pelos microfones colocados na roupa dos atores.', 'released', '["Operador de Som", "Operadora de Som"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/4d27152a-a8ee-4f5a-9f93-a2fb4fb2b2e3', 'Auxiliar de Educação Pré-Escolar', 'Os auxiliares de educação pré-escolar apoiam os educadores de infância numa escola de educação pré-escolar ou num jardim-de-infância. Prestam assistência no ensino das aulas, na supervisão da sala de aula na ausência do diretor da escola, e na organização, desenvolvimento e prática do horário diário. Os auxiliares de educação pré-escolar acompanham e ajudam os alunos em grupo, bem como individualmente, e tendem a concentrar-se nos alunos que necessitam de cuidados e atenção adicionais que os educadores de infância não podem prestar.', 'released', '["Técnico de Ação Educativa", "Técnica de Ação Educativa", "Auxiliar de Ação Educativa"]'::jsonb, '5312'),
  ('http://data.europa.eu/esco/occupation/4d34a9ee-2653-4da0-bef7-f59294577224', 'Engenheiro Eletrônico', 'Os engenheiros eletrônicos investigam, concebem e desenvolvem sistemas eletrônicos como circuitos, dispositivos semicondutores e equipamentos que utilizam a eletricidade como fonte de energia. Trabalham com capacitadores, transístores, díodos ou resistências para a criação de circuitos eletrônicos e aplicações de utilização em domínios como as telecomunicações, a acústica, os instrumentos e o controlo.', 'released', '["Engenheiro Eletrônico", "Engenheira Eletrônica", "Engenheira Eletrônico"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/4d4b243f-6c3b-48c3-a564-2e7f2d592a3c', 'Designer de Produção', 'Os designers de produção são responsáveis por toda a apresentação visual (estilos, cores e localizações) de programas televisivos, séries, filmes e anúncios publicitários. Criam o conceito visual para toda a produção, como o design do estúdio, a iluminação, o guarda-roupa e os ângulos de câmara. Os designers de produção trabalham em conjunto com o realizador e os designers e supervisionam o departamento artístico. Criam também esboços, desenhos, colorações e pesquisa de locais, e aconselham o realizador com propostas de estúdios.', 'released', NULL, '2654'),
  ('http://data.europa.eu/esco/occupation/4d5bd738-9202-4fd7-bd8c-7dbe914048de', 'Engenheiro Agrónomo', 'Os engenheiros agrónomos intervêm numa série de matérias no domínio da agricultura, em combinação com conceitos de engenharia. Concebem e desenvolvem máquinas e equipamentos para uma exploração eficiente e sustentável do solo. Aconselham sobre a utilização de recursos em explorações agrícolas, nomeadamente a utilização de água e de solo, os métodos de colheita e a gestão dos resíduos.', 'released', '["Engenheira Agrícola", "Engenheiro Agrónomo", "Engenheiro Agrícola", "Engenheira Agrónoma", "Engenheira Agrónomo"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/4d6d9057-5167-4158-8bc1-cc2f89d73fd7', 'Formador de Cursos de Estética', 'Os formadores de cursos de estética formam os alunos no seu domínio de estudos especializado, a estética, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com a estética tais como a manicura, a maquilhagem e o hair design. Os formadores de cursos de estética acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da cosmetologia através de trabalhos, testes e exames.', 'released', '["Formadora de Estética e Cosmetologia", "Formador de Estética e Cosmetologia", "Formadora de Cursos de Estética", "Formador de Cursos de Estética"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/4d750b7f-f40d-447c-ba90-f5fb0ee9ef27', 'Agente da Segurança Social', 'Os agentes da segurança social prestam aconselhamento aos utentes sobre as prestações de segurança social e asseguram que estes reivindicam os benefícios para os quais são elegíveis, prestando aconselhamento sobre promoções e outros serviços de apoio disponíveis, tais como prestações em matéria de emprego. Auxiliam os utentes com pedidos de prestações, tais como em caso de doença, maternidade, pensões, invalidez, desemprego e prestações familiares. Investigam o direito do utente às prestações, reexaminando o seu caso e analisando a legislação e o pedido, e sugerem uma linha de ação adequada. Os consultores de segurança social também determinam os aspetos de uma prestação específica.', 'released', '["Agentea da Segurança Social"]'::jsonb, '3353'),
  ('http://data.europa.eu/esco/occupation/4d7d2628-1405-4ff2-b5b5-bd0d57ed9bbd', 'Técnico de Cuidados Residenciais a Crianças com Necessidades Especiais', 'Os técnicos de cuidados residenciais a crianças com necessidades especiais prestam aconselhamento e apoio a crianças com deficiência física ou mental. Acompanham os progressos realizados e prestam-lhes cuidados num ambiente de vida positivo. Asseguram a ligação com as famílias para organizar as suas visitas.', 'released', '["Técnica de Cuidados Residenciais a Crianças com Necessidades Especiais", "Técnico de Cuidados Residenciais a Crianças com Necessidades Especiais"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/4daee8bd-8400-4da6-ba52-30d4c193d1a9', 'Engenheiro Especialista em Manutenção de Infraestruturas Aeroportuárias', 'Os engenheiros especialistas em manutenção de infraestruturas aeroportuárias são responsáveis pela supervisão da manutenção dos equipamentos do aeroporto, por exemplo as ajudas visuais, os sistemas elétricos aeroportuários, os sistemas de bagagem, os sistemas de segurança, os pavimentos, a drenagem e a manutenção das áreas não pavimentadas, dos equipamentos e dos veículos.', 'released', '["Engenheiro Especialista em Manutenção de Infraestruturas Aeroportuárias", "Engenheira Especialista em Manutenção de Infraestruturas Aeroportuárias"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/4dc6e03f-bfb0-4078-a453-01bd1cb735aa', 'Vendedor de Computadores e Acessórios', 'Os vendedores de computadores e acessórios vendem computadores e outras unidades periféricas em lojas especializadas.', 'released', '["Vendedora de Computadores e Acessórios", "Vendedor de Computadores e Acessórios"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/4dceca8d-9faf-487b-b342-c9d7dc209533', 'Assistente de Animador de Atividades ao Ar Livre', 'Os assistentes de animador de atividades ao ar livre ajudam no planejamento de atividades ao ar livre, na avaliação dos riscos ao ar livre e na monitorização do equipamento. Gerem os recursos e os grupos ao ar livre. Os assistentes de animador de atividades ao ar livre podem ajudar na administração e manutenção de escritório, podendo assim trabalhar em espaços interiores.', 'released', '["Assistentea de Animador de Atividades ao Ar Livre"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/4e0c14d6-b170-40f1-bcdc-703c0b92109b', 'Barbeiro', 'Os barbeiros cortam, aparam, espontam e penteiam o cabelo dos homens. Removem também os pelos faciais barbeando a área específica. Os barbeiros utilizam ferramentas, tais como tesouras, máquinas de cortar, máquinas de barbear e pentes. Podem oferecer serviços adicionais, tais como lavar com champô, pentear, coloração e massagens ao couro cabeludo.', 'released', '["Barbeiro", "Barbeira"]'::jsonb, '5141'),
  ('http://data.europa.eu/esco/occupation/4e3fede9-5522-4624-91bc-b59c79fada02', 'Engenheiro Mecânico Especialista em Máquinas de Embalagem', 'Os engenheiros mecânico especialista em máquinas de embalagem são responsáveis pelos equipamentos de embalagem. Mantêm e melhoram as normas técnicas, analisam os resultados, estabelecem planos de melhoramento e são responsáveis pela manutenção das máquinas.', 'released', '["Engenheiro Mecânico Especialista em Máquinas de Embalagem", "Engenheira Mecânica Especialista em Máquinas de Embalagem", "Engenheira Mecânico Especialista em Máquinas de Embalagem"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/4e4a1aa1-ca53-406e-9ca6-889d4621a0ed', 'Arquivista de Megadados', 'Os arquivistas de megadados procedem à classificação, ao catálogo e à manutenção de bibliotecas de meios de comunicação digitais. Também avaliam e cumprem as normas relativas a metadados para os conteúdos digitais e atualizam os dados obsoletos e os sistemas antigos.', 'released', '["Bibliotecário Digital", "Arquivista Digital", "Bibliotecária Digital", "Arquivista de Documentos Digitais"]'::jsonb, '3433'),
  ('http://data.europa.eu/esco/occupation/4e4a291d-1d38-4c5a-812a-5827d0691b11', 'Analista Orçamental', 'Os analistas orçamentais acompanham as atividades de despesa das instituições públicas e privadas e das empresas. Elaboram relatórios orçamentais, analisam o modelo orçamental utilizado na empresa e asseguram a conformidade com as políticas orçamentais e outros regulamentos jurídicos.', 'released', NULL, '2411'),
  ('http://data.europa.eu/esco/occupation/4e7a3641-7bd3-4290-9f0c-0e7ca776fb0e', 'Representante de Serviço de Aluguel de Meios de Transporte Marítimo e Fluvial', 'Os representantes de serviço de aluguer de meios de transporte marítimo e fluvial são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Meios de Transporte Marítimo e Fluvial"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/4e82464b-e9d7-4d51-9116-294ab40c5169', 'Técnico de Tecnologias de Apoio', 'Os técnicos de tecnologias de apoio trabalham para melhorar o acesso à aprendizagem e/ou melhorar a autonomia e a participação das pessoas com deficiência. Fazem-no apoiando os aprendentes e o pessoal em atividades de avaliação, formação e orientação. Os técnicos de tecnologias de apoio compreendem bem as necessidades dos aprendentes e têm um vasto conhecimento tecnológico relevante para o contexto de aprendizagem, de vida ou profissional. A função exige o conhecimento de hardware e software de tecnologias de apoio, tais como ferramentas de reconhecimento de voz, previsão, ditado, visão e acesso físico.;', 'released', '["Consultor de Tecnologia Educacional", "Tecnólogo Educacional", "Técnico de Tecnologia Assistiva", "Avaliador de Tecnologia Assistiva", "Avaliadora de Tecnologia Assistiva", "Tecnólogo de Necessidades Especiais", "Técnica de Tecnologia Assistiva", "Tecnólogo Assistencial Educacional", "Conselheiro de Suporte para Deficientes em TI", "Conselheira de Suporte para Deficientes em TI", "Facilitador de Tecnologia Assistiva", "Consultora de Tecnologia Educacional", "Técnica de Tecnologias de Apoio"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/4e8a5d3e-66de-4661-9927-ef3123cc79e9', 'Professor de Arquitetura', 'Os professores de Arquitetura são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Arquitetura, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da Arquitetura, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor Universitário de Arquitetura", "Professora de Arquitetura", "Professor de Arquitetura", "Professora Universitária de Arquitetura"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/4ea620f2-5c75-49ee-85a0-b2fb6bbf3624', 'Gestor de Operações de Transportes Rodoviários', 'Os gestores de operações de transportes rodoviários supervisionam os processos de transporte rodoviário quotidiano, gerindo os processos e procurando dar resposta às expectativas dos clientes.', 'released', '["Gestor de Operações de Transportes Públicos Rodoviários", "Gestora de Operações de Transportes Públicos Rodoviários", "Gestor de Operações de Transportes Rodoviários", "Gestora de Operações de Transportes Rodoviários", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/4eada7b3-5026-4030-936b-4a80aed37252', 'Professor do Curso Profissional de Técnico de Turismo', 'Os professores do curso profissional de Técnico de Turismo formam os alunos no seu domínio de estudos especializado, o turismo, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com o turismo. Os professores do curso profissional de Técnico de Turismo acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio do turismo através de trabalhos, testes e exames.', 'released', '["Professora do Curso Profissional de Técnico de Turismo", "Professor do Curso Profissional de Técnico de Turismo"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/4ebf2dae-c326-4627-befe-fbc91410f432', 'Diretor de Publicidade', 'Os diretores de publicidade executam as iniciativas de publicidade previstas no plano estratégico de marketing. Organizam e preparam os recursos necessários para o lançamento de campanhas e operações publicitárias em agências de publicidade. Preparam e alinham os canais de comunicação, negoceiam contratos e asseguram que as operações aderem aos orçamentos.', 'released', '["Diretor de Publicidade", "Diretora de Publicidade", "Diretora de Marketing", "Diretor de Marketing"]'::jsonb, '1222'),
  ('http://data.europa.eu/esco/occupation/4ed22a87-8478-4731-be11-5942eacb2e16', 'Especialista em Programas de Financiamento Públicos', 'Os especialistas em financiamento público aconselham os indivíduos e as empresas sobre as oportunidades de financiamento oferecidas pelo governo. Analisam as necessidades dos clientes, consultam-nos sobre os fundos, subvenções e subsídios que lhes são aplicáveis e ajudam no respetivo processo de candidatura. Os especialistas em financiamento público também organizam a administração de subvenções públicas em organizações.', 'released', '["Coordenador de Programas de Financiamento Públicos", "Coordenadora de Programas de Financiamento Públicos"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/4ed36f4c-9d5b-4a01-bf59-7f3c7844ce95', 'Pintor de Construção Cénica', 'Os pintores de construção cénica decoram cenários para espetáculos ao vivo. Empregam uma grande variedade de técnicas de arte e pintura, tais como a pintura figurativa, a pintura paisagística e a trompe-l’œil, para criar cenas convincentes. O seu trabalho baseia-se na visão artística, esboços e imagens. Trabalham em estreita colaboração com os designers.', 'released', '["Pintor de Construção Cénica", "Pintora de Construção Cénica"]'::jsonb, '3432'),
  ('http://data.europa.eu/esco/occupation/4ed9ce62-75d4-4b05-80d4-e86528fecdcd', 'Trabalhador da Reciclagem de Resíduos', 'Os trabalhadores da reciclagem de resíduos limpam e eliminam resíduos, e garantem que os resíduos e os materiais recolhidos sejam separados nos contentores de reciclagem adequados. Também procedem ao desmantelamento de veículos e à triagem das peças recolhidas, e depositam os materiais recicláveis nas correias transportadoras, onde podem ser separados.', 'released', '["Trabalhadora da Reciclagem de Resíduos", "Separadora de Resíduos", "Trabalhador da Reciclagem de Resíduos", "Separador de Resíduos"]'::jsonb, '9612'),
  ('http://data.europa.eu/esco/occupation/4edbde9f-218e-49c7-812f-c45262fb4128', 'Técnico de Apoio Domiciliário', 'Os técnicos de apoio domiciliário prestam apoio e assistência a idosos, pessoas com deficiência física ou incapacidade de aprendizagem, sem-abrigo, ex-toxicodependentes, ex-alcoólicos ou ex-infratores.', 'released', '["Técnico de Apoio Domiciliário", "Técnica de Apoio Domiciliário"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/4efdf62f-a1d9-450e-aebc-2d6a6110f05d', 'Animador Artístico', 'Os animadores artísticos investigam, planeiam, organizam e realizam atividades artísticas para pessoas unidas por um interesse, capacidade, ambiente ou condição comum. Gerem e coordenam projetos criativos com grupos locais e indivíduos, a fim de promoverem a sua criatividade artística e de melhorarem a sua qualidade de vida. Os animadores artísticos tornam as artes acessíveis à comunidade para a qual trabalham e oferecem aos participantes a oportunidade de moldarem o seu programa artístico.', 'released', '["Animadora Artística", "Animador Artístico", "Animadora Artístico"]'::jsonb, '2659'),
  ('http://data.europa.eu/esco/occupation/4efee3ed-de09-44c6-bd4a-d9eaafd04683', 'Engenheiro Metalúrgico Especialista em Processos', 'Os engenheiros metalúrgicos especialistas em processos estudam as características dos minérios, incluindo os minérios de cobre, de níquel e de ferro, e o desempenho de vários metais e ligas.', 'released', '["Engenheiro Metalúrgico Especialista em Processos", "Engenheira Metalúrgica Especialista em Processos", "Engenheira Metalúrgico Especialista em Processos"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/4f08cd74-71c6-43aa-88d4-841e5bb677f7', 'Assistente de Podologia', 'Os assistentes de podologia ajudam o podólogo através da realização de tarefas de apoio, como a assistência no diagnóstico e tratamento das patologias, doenças e deformações dos pés, e do aconselhamento às pessoas sobre técnicas de cuidados dos pés e a importância dos cuidados prestados para promover uma melhor mobilidade e bem-estar geral. Desempenham, além disso, pequenas tarefas, como cortar as unhas, a aplicação de gesso e tarefas administrativas gerais.', 'released', '["Assistentea de Podologia"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/4f1bb8b4-3fff-4e68-b427-8c892534a181', 'Colocador de Parquet', 'Os colocadores de parquet instalam pavimentos em madeira maciça. Preparam a superfície, cortam à medida os elementos de parquet ou tábua, fixando-os num padrão predeterminado, retos e nivelados.', 'released', '["Assentadora de Tacos e Afagadora", "Colocadora de Parquet", "Colocador de Soalho de Madeira", "Colocadora de Soalho de Madeira", "Assentador de Tacos e Afagador", "Colocador de Parquet"]'::jsonb, '7122'),
  ('http://data.europa.eu/esco/occupation/4f2f2539-3e38-4393-9dac-a9a48af7cd32', 'Diretor de Elenco', 'Os diretores de elenco selecionam os atores para todos os papéis de um filme ou série de televisão. Cooperam com o produtor e o realizador para determinar o que procuram. Os diretores de elenco contactam agências de atores e organizam entrevistas e audições para os papeis. Determinam os honorários e os contratos dos atores e os extras.', 'released', '["Diretor de Casting", "Diretor de Elenco", "Diretora de Elenco", "Diretora de Casting"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/4f49df98-98b8-4a9e-98ad-9c5557817eba', 'Diretor Estratégico', 'Os gestores estratégicos criam, em conjunto com uma equipe de gestores, os planos estratégicos da empresa no seu conjunto e asseguram a coordenação da execução por departamento. Ajudam a interpretar o plano global e criam um plano pormenorizado para cada um dos departamentos e sucursais. Asseguram a coerência da execução.', 'released', '["Diretora Estratégica", "Diretora de Planejamento Estratégico", "Especialista em Estratégia e Inovação", "Diretor de Planejamento Estratégico", "Diretor Estratégico", "Diretora Estratégico"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/4f4d33a1-0b41-4dd9-8a42-aeba5a3974ab', 'Engenheiro Especialista em Tecnologias de Sensores', 'Os engenheiros especialistas em tecnologias de sensores concebem e desenvolvem sensores, sistemas de sensores e produtos equipados com sensores. Planificam e controlam o fabrico desses produtos.', 'released', '["Engenheiro Especialista em Tecnologias de Sensores", "Engenheira Especialista em Tecnologias de Sensores"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/4f5bc9a5-e989-409b-bfb5-973b472163cd', 'Psicólogo Educacional', 'Os psicólogos educacionais são profissionais que trabalham em instituições de ensino para prestar apoio psicológico e emocional aos alunos necessitados. São especializados na prestação de apoio direto e de intervenções junto dos alunos, na realização de testes e avaliações psicológicos e na consulta de familiares, professores e outros profissionais que prestam apoio aos alunos no contexto escolar, como os assistentes sociais em contexto escolar e os conselheiros educativos, sobre os alunos. Podem também colaborar com a administração escolar para melhorar as estratégias práticas de apoio, tendo em vista o aumento do bem-estar dos alunos.', 'released', '["Psicólogo Educacional", "Psicóloga Educacional"]'::jsonb, '2634'),
  ('http://data.europa.eu/esco/occupation/4f5e4fb1-58bd-4abd-bb06-4af9203a1518', 'Operador de Máquinas Limadoras', 'Os operadores de máquinas limadoras instalam e asseguram o correto funcionamento de máquinas limadoras, tais como limas de fita, limas alternativas e máquinas de limar, para suavizar as superfícies de metal, madeira ou plástico, cortando e removendo com precisão as pequenas quantidades de material em excesso.', 'released', '["Operador de Máquinas Limadoras", "Operadora de Máquinas Limadoras"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/4f7e7482-39e7-4f3a-bf11-763620f4b8e0', 'Operador de Máquina de Estampagem de Papel', 'Os operadores de máquina de estampagem de papel utilizam uma prensa para elevar ou criar recessos em certas áreas do material de suporte, de modo a criar um relevo na impressão. Dois moldes emparelhados são colocados em torno do papel e aplica-se pressão para alterar a superfície do material.', 'released', '["Operadora de Máquina de Estampagem de Papel", "Operador de Máquina de Estampagem de Papel"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/4f89b0d2-b666-4890-af01-25d1d60da1f3', 'Politólogo', 'Os politólogos estudam o comportamento, a atividade e os sistemas políticos, incluindo os elementos que deles fazem parte. O estudo deste domínio abrange desde as origens e a evolução dos vários sistemas políticos até temas atuais, como os processos de tomada de decisão, o comportamento político, as tendências políticas, a sociedade e as perspetivas de poder. Prestam aconselhamento a governos e a organizações institucionais sobre questões de governação.', 'released', '["Politicólogo", "Especialista em Ciências Políticas", "Politólogo", "Politóloga", "Politicóloga"]'::jsonb, '2633'),
  ('http://data.europa.eu/esco/occupation/4fa660b3-ab97-4a99-ad73-ce3c2612f2c3', 'Assistente de Trabalho Social', 'Os assistentes de trabalho social são profissionais baseados na prática, que promovem a mudança e o desenvolvimento social, a coesão social e a emancipação e a libertação das pessoas. Interagem com indivíduos, famílias, grupos, organizações e comunidades, a fim de prestar assistência no fornecimento de várias formas de terapia e aconselhamento, trabalho de grupo e trabalho comunitário. Os assistentes sociais prestam assistência ao pessoal de orientação, ajudando os clientes a utilizar serviços para reclamar prestações, aceder aos recursos da comunidade, encontrar emprego e formação, obter aconselhamento jurídico ou lidar com outros departamentos da autoridade local. Prestam assistência e trabalham em conjunto com os assistentes sociais.', 'released', '["Técnico de Apoio Social", "Técnica de Apoio Social", "Assistentea de Trabalho Social"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/4fe4b1f1-e84d-4056-b062-83d5a64fc571', 'Diretor de Colheitas de Aquicultura', 'Os diretores de colheitas de aquicultura controlam as operações de colheita de organismos aquáticos, o que implica a compreensão e o conhecimento das técnicas e equipamentos utilizados nos processos de colheita.', 'released', '["Diretor de Aquicultura — Pós-Colheita", "Diretora de Colehiras de Aquicultura", "Diretora de Aquicultura — Pós-Colheita", "Diretor de Colheitas de Aquicultura", "Diretora de Colheitas de Aquicultura"]'::jsonb, '1312'),
  ('http://data.europa.eu/esco/occupation/4fef1907-cf82-413b-841a-02ef57e299a6', 'Técnico de Laboratório Científico', 'Os técnicos de laboratório científico realizam atividades de investigação, análise e ensaio em ambiente laboratorial e prestam apoio a profissionais das ciências da vida. Recolhem amostras e realizam testes, medições, investigações e análises em áreas como a biologia, a biotecnologia, a ciência ambiental, a ciência forense e a farmacologia. Os técnicos de laboratório científico também observam e monitorizam as atividades laboratoriais, registam sequências de ensaios e analisam os resultados.', 'released', '["Técnico de Laboratório Científico", "Técnica de Laboratório Científico"]'::jsonb, '3141'),
  ('http://data.europa.eu/esco/occupation/5001506f-dd7d-4801-92ac-6f7e93b45133', 'Técnico de Controle de Robô Industrial', 'Os técnicos de controlo de robots industriais operam e controlam os robots industriais utilizados em processos de automatização, para a realização de várias atividades de fabrico, como a elevação, a soldadura e a montagem. Asseguram que as máquinas funcionam corretamente e em sintonia com outros robots industriais, efetuam a manutenção e a reparação de partes defeituosas, avaliam os riscos e realizam testes.', 'released', '["Técnica de Controle de Robô Industrial", "Técnico de Controle de Robô Industrial"]'::jsonb, '3139'),
  ('http://data.europa.eu/esco/occupation/500b7b14-507c-4c49-816d-c1d0b05b85e4', 'Técnico de Próteses', 'Os técnicos de próteses concebem, criam, adaptam e reparam dispositivos de suporte, como aparelhos de suporte ortopédico, suportes de articulações, suportes do arco plantar e outros aparelhos cirúrgicos e médicos.', 'released', '["Técnico de Próteses", "Técnica de Próteses"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/501a3798-08bf-4475-88d2-0e8c9befb101', 'Tanoeiro', 'Os tanoeiros fabricam barris de madeira e produtos afins fabricados com segmentos de madeira, como baldes de madeira. Moldam a madeira, encaixam aros em redor dos barris e moldam os mesmos para manter o produto, que, atualmente, é normalmente bebidas alcoólicas de qualidade.', 'released', '["Tanoeiro", "Tanoeira", "Toneleira", "Toneleiro"]'::jsonb, '7522'),
  ('http://data.europa.eu/esco/occupation/502fe307-ae65-46cb-a485-e559b9a35266', 'Operador de Máquinas de Moldagem por Injeção', 'Os operadores de máquinas de moldagem por injeção operam e acompanham as máquinas de moldagem por injeção, a fim de moldar produtos a partir de materiais termoplásticos. Regulam a temperatura, a pressão e o volume de plástico, de acordo com especificações predefinidas. Os operadores de máquinas de moldagem por injeção também eliminam os produtos acabados e os materiais de corte em excesso, utilizando uma faca ou outras ferramentas manuais.', 'released', '["Operador de Máquinas de Moldagem por Injeção", "Operadora de Máquinas de Moldagem por Injeção"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/503ea267-93e9-4b8c-ae5e-817fe7e4a245', 'Cantoneiro', 'Os cantoneiros utilizam equipamento e máquinas de limpeza para remover resíduos, folhas ou resíduos das ruas. Mantêm registos das operações de limpeza e manutenção, limpam e realizam pequenas reparações do equipamento utilizado.', 'released', '["Varredora de Rua", "Cantoneira", "Cantoneiro", "Varredor de Rua"]'::jsonb, '9613'),
  ('http://data.europa.eu/esco/occupation/50609eb5-9957-4cbf-9b91-6f46ce49cfad', 'Inspetor de Frete', 'Os inspetores de frete determinam se o frete está seguro e acompanhado da documentação adequada. Inspecionam, gerem e documentam os transportes de carga, verificando se o conteúdo está em conformidade com a regulamentação local, nacional e internacional.', 'released', '["Inspetor de Frete", "Inspetora de Frete"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/50743f62-3d5b-4ef6-b706-00d2b1adfcc3', 'Técnico de Apoio Residencial a Idosos', 'Os técnicos de apoio residencial a idosos prestam aconselhamento e apoio a idosos com deficiência física ou mental. Acompanham os progressos realizados e prestam-lhes cuidados num ambiente de vida positivo. Asseguram a ligação com as famílias dos clientes, a fim de organizar as suas visitas.', 'released', '["Técnico de Apoio Residencial a Idosos", "Técnica de Apoio Residencial a Idosos"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/50760da6-abc3-424c-b159-8ddf0818e016', 'Avaliador de Empresas', 'Os avaliadores de empresas elaboram avaliações de entidades empresariais, ações e outros valores mobiliários e ativos intangíveis, a fim de prestar assistência aos seus clientes em processos de tomada de decisões estratégicas, como fusões e aquisições, litígios, insolvência, conformidade fiscal e reestruturação geral das empresas.', 'released', '["Avaliador de Empresas", "Avaliadora de Empresas"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/509f9452-ed18-4fbf-8a4c-d45de85aa2f7', 'Pulverizador de Pesticidas', 'Os pulverizadores de pesticidas misturam pesticidas, inseticidas, fungicidas e outras soluções químicas e aplicam-nos com equipamento técnico, tais como pulverizadores em árvores, plantas e relvados. Procedem à limpeza e manutenção das máquinas operacionais e asseguram a segurança geral em áreas designadas.', 'released', '["Pulverizador de Pesticidas", "Pulverizadora de Pesticidas"]'::jsonb, '7544'),
  ('http://data.europa.eu/esco/occupation/50a66df6-c141-4b4a-937a-d3bc55737ae3', 'Cobrador de Dívidas', 'Os cobradores de dívidas compilam a dívida devida à organização ou a terceiros, sobretudo nos casos em que a dívida ultrapassou a data de vencimento.', 'released', '["Cobrador de Dívidas", "Cobradora de Dívidas"]'::jsonb, '4214'),
  ('http://data.europa.eu/esco/occupation/50af07f0-7a75-424e-a66d-5a9deea10f4c', 'Testador de Acessibilidade Informática', 'Os testadores de acessibilidade informática avaliam os sites, as aplicações de software, os sistemas ou os componentes de interface do usuário no que diz respeito à facilidade de utilização, à operabilidade da navegação e à visibilidade para todos os tipos de usuários, em especial os que têm necessidades especiais ou deficiências.', 'released', '["Testadora de Acessibilidade", "Responsável por Testes de Acessibilidade", "Testador de Acessibilidade", "Responsável Pelos Testes de Acessibilidade", "Testadora de Acessibilidade Informática"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/50b41847-6dad-4a2e-9427-a0374c2963fd', 'Maquinista de Cena', 'Os maquinistas de cena manipulam os cenários e outros elementos num espetáculo com base no conceito artístico ou criativo, em interação com os artistas. O seu trabalho é influenciado e influencia os resultados dos outros operadores. Por conseguinte, os maquinistas de cena trabalham em estreita colaboração com os designers, os operadores e os artistas. Os maquinistas de cena devem preparar e executar a instalação, executar processos de transição e operar manualmente sistemas de varas. O seu trabalho baseia-se em planos, instruções e cálculos.', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/50e00fda-ac7c-4bc5-9f19-69a33ff3d6e7', 'Especialista em Política Orçamental', 'Os especialistas em política orçamental investigam, analisam e desenvolvem políticas relacionadas com fiscalidade e despesas orçamentais no setor das políticas públicas e aplicam estas políticas a fim de melhorarem a regulamentação existente neste setor. Trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/511c8e9f-b19e-4ae8-9959-c047e7410441', 'Inspetor de Infraestruturas Ferroviárias', 'Os inspetores de infraestruturas ferroviárias são responsáveis pela verificação das condições das vias férreas. Monitorizam o cumprimento das normas de saúde e segurança e inspecionam as infraestruturas para detectar danos ou falhas. Analisam e comunicam as suas conclusões, assegurando que as condições ferroviárias são mantidas a um nível seguro.', 'released', '["Inspetor de Infraestruturas Ferroviárias", "Inspetora de Infraestruturas Ferroviárias"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/511f366c-ba41-4826-9622-8cda6d6e3b91', 'Operador de Serviços Postais', 'Os operadores de serviços postais efetuam serviços de manuseamento, triagem, gravação de correio e outras funções relacionadas com serviços postais das estações de correio ou de organizações relacionadas. Procedem à manutenção dos registos das entradas e das saídas de embalagens e cartas no estabelecimento.', 'released', '["Operadora de Serviços Postais", "Operador de Serviços Postais"]'::jsonb, '4412'),
  ('http://data.europa.eu/esco/occupation/5157706c-3fce-420e-9e7f-863000af5397', 'Modelista de Vestuário de Cabedal', 'Os modelistas de vestuário de cabedal concebem e cortam moldes para vários tipos de artigos de couro, utilizando uma variedade de ferramentas manuais e simples. Verificam as variantes de encaixe e estimam o consumo de materiais.', 'released', NULL, '7532'),
  ('http://data.europa.eu/esco/occupation/517c01aa-e875-4690-bf38-17307a57eafe', 'Operador de Máquina de Costura', 'Os operadores de máquina de costura unem através de costura artigos de vestuário. Podem reparar e renovar o vestuário à mão ou utilizando diferentes máquinas de costura.', 'released', '["Operadora de Máquina de Costura", "Operador de Máquina de Costura"]'::jsonb, '7533'),
  ('http://data.europa.eu/esco/occupation/518348e6-0095-4f37-ad46-5ef1b8b5ee2f', 'Responsável de Operações na Indústria Têxtil', 'Os responsáveis de operações na indústria têxtil programam as encomendas e os prazos de entrega, tendo em vista assegurar um fluxo eficiente do sistema de produção.', 'released', NULL, '1321'),
  ('http://data.europa.eu/esco/occupation/51c7015c-dc81-4fcb-b15f-619a4656a9fe', 'Técnico de Eletromecânica', 'Os técnicos de eletromecânica colaboram com engenheiros eletromecânicos no desenvolvimento de equipamento eletromecânico. Os técnicos de eletromecânica são responsáveis pela construção, instalação, ensaio, monitorização e manutenção de equipamentos, circuitos e sistemas eletromecânicos. Para testar tais equipamentos e sistemas utilizam instrumentos de teste como os osciloscópios e os voltímetros. Os técnicos de eletromecânica também utilizam equipamento de soldadura e ferramentas manuais para reparar equipamento eletromecânico.', 'released', '["Técnico de Eletromecânica", "Técnica de Eletromecânica"]'::jsonb, '3113'),
  ('http://data.europa.eu/esco/occupation/51ca3c6e-1c9b-49e4-aa09-9e77d1a59547', 'Vendedor de Fruta e Hortaliças', 'Os vendedores de frutas e produtos hortícolas vendem fruta e produtos hortícolas em lojas especializadas.', 'released', '["Vendedor de Fruta e Produtos Hortícolas", "Vendedora de Fruta e Produtos Hortícolas", "Vendedora de Fruta e Hortaliças"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/51cd3a7a-eae6-4dc6-9f24-179d7ec6d230', 'Analista de Logística', 'Os analistas de logística simplificam a produção, o transporte, o armazenamento e a distribuição dos produtos. Avaliam os problemas de produção e da cadeia de abastecimento para determinar soluções economicamente eficientes. Prestam assistência aos gestores de empresas nos processos de tomada de decisão e dirigem programas destinados a fornecer aos subcontratantes, gestores e clientes tecnologia logística.', 'released', '["Analista da Cadeia de Abastecimento", "Analista da Cadeia de Distribuição", "Analista da Cadeia de Fornecimento"]'::jsonb, '2421'),
  ('http://data.europa.eu/esco/occupation/51ec004e-aec8-4f89-b114-952bcc56b0b0', 'Vlogger', 'Os vloggers produzem vídeos em linha para falar sobre um vasto leque de temas como a política, a moda, a economia e o desporto. Podem relatar fatos objetivos, mas muitas vezes dão também a sua opinião sobre o tema tratado. Os «vloggers» colocam estes vídeos em linha nas redes sociais ou em plataformas de transferência em contínuo («streaming»), frequentemente acompanhados de texto escrito. Também interagem com os visualizadores através dos comentários.', 'released', NULL, '2642'),
  ('http://data.europa.eu/esco/occupation/521bbfd5-c179-46e3-879b-e74bd6db367c', 'Técnico de Audiologia', 'Os técnicos de audiologia concebem e efetuam a manutenção de aparelhos auditivos e produtos de proteção auditiva. Dispensam, adaptam e fornecem aparelhos auditivos às pessoas que deles necessitam.', 'released', '["Técnica de Audiologia", "Técnico de Audiologia"]'::jsonb, '3214'),
  ('http://data.europa.eu/esco/occupation/52207284-2681-40d3-a317-ec81ca1b3e41', 'Arquiteto Paisagista', 'Os arquitetos paisagistas planeiam e concebem a construção de jardins e espaços naturais. Determinam as especificações e a distribuição do espaço. Além disso, os arquitetos paisagistas investigam e analisam o potencial da paisagem em todas as fases, escalas e contextos do processo de desenvolvimento, combinando uma compreensão do espaço natural com um sentido estético, a fim de criar um espaço harmonioso.', 'released', '["Designer de Jardins", "Arquiteta Paisagista", "Arquiteto Paisagista", "Designer Paisagista"]'::jsonb, '2162'),
  ('http://data.europa.eu/esco/occupation/522c55ca-ee4a-407d-9fc6-f810c5266523', 'Piloto de Linhas Aéreas', 'Os pilotos de linhas aéreas pilotam aeronaves de grande dimensão com um peso máximo à descolagem superior a 5.700 kg, para transportar passageiros, correspondência ou mercadorias em voos de pequeno ou de longo curso, para fins de lazer, de negócios ou comerciais. Têm a responsabilidade global pela segurança e pela operação eficiente das aeronaves, bem como pela segurança da tripulação e dos passageiros.', 'released', '["Pilota de Linhas Aéreas"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/523ab5a0-5e72-418d-9d61-a6126a446123', 'Piloto Comercial', 'Os pilotos comerciais pilotam aeronaves de asa fixa e multimotor para o transporte de passageiros e mercadorias.', 'released', '["Pilota Comercial"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/526ba8e1-fc71-4657-8d27-52f03e8ca81d', 'Coordenador de Cuidados a Crianças', 'Os coordenadores de cuidados a crianças organizam serviços de acolhimento de crianças, atividades e eventos após o horário escolar e durante o horário escolar. Contribuem para o desenvolvimento das crianças através da implementação de programas de cuidados. Os coordenadores de cuidados a crianças ocupam-se também do entretenimento das crianças e mantêm um ambiente seguro para as mesmas.', 'released', '["Coordenador de Atividades de Tempos Livres", "Coordenadora de Cuidados de Crianças", "Coordenador de Cuidados de Crianças", "Coordenadora de Atividades de Tempos Livres", "Coordenador de Atividades Pré-Escolares", "Coordenadora de Atividades Pré-Escolares", "Coordenadora de Cuidados a Crianças"]'::jsonb, '1341'),
  ('http://data.europa.eu/esco/occupation/528e63a7-91be-4477-be2f-69ce82deb726', 'Operador de Forno de Minério', 'Os operadores de fornos de minério acompanham o processo de fabrico de metais antes de serem moldados nas formas. Controlam os fornos de fabrico de metais e orientam todas as atividades de operação do forno, incluindo a interpretação de dados informáticos, a medição e a regulação da temperatura, os recipientes de carga e a adição de ferro, oxigénio e outros aditivos destinados a ser fundidos na composição metálica desejada. Controlam o tratamento quimicotérmico dos metais, com vista ao cumprimento das normas. No caso de detetarem anomalias no metal, notificam o pessoal autorizado e participam na remoção da anomalia.', 'released', '["Operador de Forno de Minério", "Operadora de Forno de Minério"]'::jsonb, '3135'),
  ('http://data.europa.eu/esco/occupation/528f90ed-e250-48bd-aacc-ffb7b1de5654', 'Vendedor de Tecidos e Artigos de Retrosaria', 'Os vendedores de tecidos e artigos de retrosaria vendem têxteis, tecidos e artigos de retrosaria, etc., em lojas especializadas.', 'released', '["Retroseiro", "Vendedora de Tecidos e Artigos de Retrosaria", "Retroseira", "Vendedor de Tecidos e Artigos de Retrosaria"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/52a769ab-c899-4e8c-b31d-e5c2a01f32e3', 'Instrutor de Técnicas de Sobrevivência', 'Os instrutores de técnicas de sobrevivência orientam grupos em vastas áreas naturais, ajudando-os na instrução autodirigida das necessidades básicas de sobrevivência sem qualquer infraestrutura de conforto ou equipamento moderno para apoio. Treinam os participantes no domínio das competências de sobrevivência, tais como fazer fogo, a produção de equipamentos primitivos, a construção de abrigos e a obtenção de água e alimentos. Asseguram que os participantes tenham conhecimento de determinadas medidas de segurança sem diminuir o nível de aventura, de proteção do ambiente e de gestão dos riscos. Incentivam os esforços de liderança do grupo e orientam os participantes a título individual, a fim de testar os seus limites de forma responsável e ajudar a superar potenciais medos.', 'released', '["Instrutora de Técnicas de Sobrevivência", "Instrutor de Técnicas de Sobrevivência"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/52b9e8dc-de6c-41dd-b29a-e1291c273f6f', 'Produtor', 'Os produtores são responsáveis pela gestão da produção de música, filmes ou séries. Planeiam e coordenam todos os aspetos da produção, como a direção, a publicação e o financiamento. Os produtores supervisionam a produção e gerem todos os aspetos técnicos e logísticos da gravação e edição.', 'released', '["Produtora de Rádio", "Produtora de Televisão", "Produtora", "Produtor de Rádio", "Produtor", "Produtor de Televisão"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/52c25b47-c36e-49ff-92ce-8a8c5413fde6', 'Operador de Máquinas de Montagem em Superfície', 'Os operadores de máquinas de montagem em superfície utilizam máquinas de tecnologia de montagem em superfície (SMT) para montar e soldar pequenos componentes eletrônicos em placas de circuito impresso para criar dispositivos de montagem em superfície (SMD).', 'released', '["Operador de Máquinas de Montagem em Superfície", "Operadora de Máquinas de Montagem em Superfície"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/52d303a7-630b-4e3f-9f62-becd9b2fcb46', 'Diretor de Distribuição — Recursos Minerais Metálicos', 'Os diretores de distribuição — recursos minerais metálicos planificam a distribuição de metais e minérios metálicos a diversos pontos de venda.', 'released', '["Diretor de Distribuição — Recursos Minerais Metálicos", "Diretora de Distribuição — Recursos Minerais Metálicos", "Diretora de Logística — Recursos Minerais Metálicos", "Diretor de Logística — Recursos Minerais Metálicos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/52d5edc9-7902-4cd3-8b06-6bd77c98d440', 'Testador de Sistemas Informáticos', 'Os testadores de sistemas informáticos realizam atividades de teste e algumas atividades de planejamento de testes. Além disso, podem realizar a depuração de erros e a reparação de sistemas e componentes informáticos, embora estas funções sejam sobretudo da responsabilidade de designers e programadores. Asseguram o correto funcionamento de todos os sistemas e componentes antes de os entregarem a clientes internos e externos.', 'released', '["Engenheiro de Testes de Sistemas Informáticos", "Testador de Sistemas", "Responsável Pelos Testes de Sistemas Informáticos", "Engenheira de Testes de Sistemas Informáticos", "Responsável por Testes de Sistemas Informáticos", "Testadora de Sistemas", "Testadora de Sistemas Informáticos", "Testador de Sistemas Informáticos"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/52ded7d7-11df-42e3-b90a-d7f4b70fb4b9', 'Psicólogo', 'Os psicólogos estudam o comportamento e os processos mentais do ser humano. Prestam serviços a clientes que lidam com problemas de saúde mental e problemas relacionados com a vida, como o luto, as dificuldades de relacionamento, a violência doméstica e o abuso sexual. Prestam igualmente aconselhamento sobre problemas de saúde mental, como distúrbios alimentares, perturbação do stress pós-traumático e psicoses, a fim de ajudarem os clientes a reaverem e obterem comportamentos saudáveis.', 'released', '["Psicólogo", "Psicóloga"]'::jsonb, '2634'),
  ('http://data.europa.eu/esco/occupation/52df9d56-efd4-48d0-ad93-59231943fc4c', 'Animador 3D', 'Os animadores 3D são responsáveis pela animação 3D de modelos de objetos, ambientes virtuais, apresentações visuais, personagens e animações virtuais 3D.', 'released', '["Animadora de IGC", "Animador de CGI", "Animadora de Imagens Geradas por Computador", "Animadora de CGI", "Animador de Imagens Geradas por Computador", "Animador de IGC", "Animadora 3D", "Animador 3D"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/52fcfdb9-9dcf-4591-aba5-45337f791a10', 'Representante de Vendas de Máquinas para a Indústria Extrativa e de Construção', 'Os representantes de vendas de máquinas para a indústria extrativa e de construção prestam serviços em nome de uma empresa para vender as suas mercadorias, fornecendo simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Máquinas para a Indústria Extrativa e de Construção"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/5318abf2-2e7b-4d09-ae57-6bd500689ebc', 'Moldador', 'Os moldadores criam manualmente moldes para a produção de produtos metálicos. Misturam areia e materiais de endurecimento para obter uma mistura especializada. Em seguida, utilizam um molde e um ou mais núcleos para produzir a impressão do molde correta neste material. O material formado é deixado em repouso, para ser utilizado mais tarde como molde na produção de peças vazadas de metal ferroso e não ferroso.', 'released', '["Moldador", "Moldadora"]'::jsonb, '7211'),
  ('http://data.europa.eu/esco/occupation/531e98aa-2a03-489d-b811-ebbb7389864a', 'Montador de Produtos em Lona', 'Os montadores de produtos em lona fabricam produtos a partir de tecidos apertados e de couro, tais como tendas, sacos ou carteiras. Os artistas também utilizam a lona como superfície de pintura.', 'released', '["Montador de Produtos em Lona", "Montadora de Produtos em Lona"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/534d18fe-eae4-4a02-af4d-f78e92faa5d5', 'Técnico de Irrigação', 'Os técnicos de irrigação especializam-se na instalação, manutenção e reparação de pulverizadores, tubos e outros sistemas de irrigação. Operam as máquinas utilizadas para o tratamento dos sistemas de irrigação e asseguram o cumprimento das normas ambientais.', 'released', '["Técnica de Irrigação", "Técnico de Irrigação", "Técnico de Sistemas de Rega", "Técnica de Sistemas de Rega"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/53a362a4-4c83-4ce2-837f-d1faba4cd247', 'Gestor de Ofertas', 'Os gestores de ofertas são responsáveis pela pesquisa, seleção, análise e apresentação de propostas a concurso. Têm em conta os requisitos da empresa proponente e as possibilidades de execução. Ocupam-se tanto do cálculo dos custos como da estimativa dos riscos possíveis. São responsáveis pela comunicação com a empresa ou instituições adjudicantes. Trabalham em conjunto com os gestores de projeto e servem de interface com os clientes de empresas de maior dimensão. São frequentemente os responsáveis principais pelas ofertas (propostas) e pela sua apresentação.', 'released', '["Gestor de Ofertas", "Gestora de Ofertas", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/53be4843-8f31-4645-b25c-9a5bbb04f6b6', 'Técnico de Engenharia de Processos', 'Os técnicos de engenharia de processos trabalham em estreita colaboração com os engenheiros na avaliação dos processos existentes e na configuração dos sistemas de fabrico, tendo em vista reduzir os custos, aumentar a sustentabilidade e desenvolver boas práticas no processo de produção.', 'released', '["Técnica de Engenharia de Processos", "Técnico de Engenharia de Processos"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/53c0086b-9b54-4c29-8bba-69ce8256cb91', 'Operador de Máquinas de Pré-Costura', 'Os operadores de máquinas de pré-costura manuseiam ferramentas e equipamento para cortar, aparar, dobrar, perfurar, franzir, embalar e marcar as gáspeas para costurar e, quando necessário, aplicam tiras de reforço em várias peças. Também podem colar as peças juntas antes de serem costuradas. Os operadores de máquinas pré-costura desempenham estas funções de acordo com as instruções da ficha técnica.', 'released', '["Operador de Máquinas de Pré-Costura", "Operadora de Máquinas de Pré-Costura"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/53c7756d-4114-4c7f-90b0-26717f458ac5', 'Técnico de Sistemas Pneumáticos', 'Os técnicos de sistemas pneumáticos utilizam esquemas e documentação técnica para montar e instalar equipamento operado por gás ou ar sob pressão. Instalam os sistemas de acordo com as especificações técnicas e testam-nos para garantir o bom funcionamento. Também podem realizar trabalhos de manutenção e reparação de equipamentos pneumáticos instalados.', 'released', '["Técnico de Sistemas Pneumáticos", "Técnica de Sistemas Pneumáticos"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/53cdcc84-e5ee-488c-aa09-88084e06d6d7', 'Farmacêutico Industrial', 'Os farmacêuticos industriais participam na investigação e na criação de medicamentos. Desenvolvem novos medicamentos, realizam testes, asseguram a qualidade e a conformidade dos medicamentos com a regulamentação.', 'released', '["Farmacêutica Industrial", "Farmacêutico Industrial"]'::jsonb, '2262'),
  ('http://data.europa.eu/esco/occupation/53cdd34e-22f2-41bd-b3c7-de22bf9bbcae', 'Diretor Hoteleiro', 'Os diretores hoteleiros são responsáveis pela gestão das operações e pela supervisão da estratégia de um estabelecimento de hotelaria e restauração. Gerem os recursos humanos, as finanças, o marketing e as operações através de atividades como a supervisão do pessoal, a manutenção de registos financeiros e a organização das atividades.', 'released', '["Diretor de Estabelecimento Hoteleiro", "Diretor Hoteleiro", "Diretora de Estabelecimento Hoteleiro", "Diretora-Geral de Hotel", "Diretora Hoteleira", "Diretor-Geral de Hotel", "Diretora Hoteleiro"]'::jsonb, '1411'),
  ('http://data.europa.eu/esco/occupation/53d2052f-edc0-4f44-8be1-164526412bfe', 'Engenheiro Industrial', 'Os engenheiros industriais concebem uma vasta gama de sistemas de produção que visam apresentar soluções eficientes e eficazes. Integram um vasto número de variáveis como os trabalhadores, a tecnologia, a ergonomia, os fluxos de produção e as especificações do produto para a concepção e a aplicação de sistemas de produção. Podem também especificar e conceber microssistemas.', 'released', '["Engenheira Industrial", "Engenheiro Industrial"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/53d55c80-6a82-4187-b59f-b737aa4cdaab', 'Operador de Máquinas de Costura de Artigos em Couro', 'Os operadores de máquinas de costura de artigos em couro unem as peças cortadas de couro e de outros materiais para fabricar os artigos em couro, utilizando ferramentas e uma vasta gama de máquinas, tais como cama plana, braço e uma ou duas colunas. Também manuseiam ferramentas e máquinas de monitorização para preparar as peças a ser cosidas e operam as máquinas. Selecionam os fios e puxam-nos através de guias e agulhas. Selecionam os fios e as agulhas para as máquinas de costura, colocam as peças na zona de trabalho e trabalham com as peças de guiamento da máquina sob a agulha, seguindo as costuras, os bordos ou as marcações ou movendo as peças contra a guia.', 'released', '["Operadora de Máquinas de Costura de Artigos em Couro", "Operador de Máquinas de Costura de Artigos em Couro"]'::jsonb, '8153'),
  ('http://data.europa.eu/esco/occupation/53db8c0d-7aed-47aa-a339-eb9d485d25dc', 'Diretor de Escola Secundária', 'Os diretores de escola secundária são responsáveis pelo cumprimento das normas curriculares, que facilitam o desenvolvimento académico dos alunos. Gerem o pessoal, trabalham em estreita colaboração com os diferentes departamentos e avaliam os professores em tempo útil, a fim de garantir um desempenho ótimo das turmas. Além disso, asseguram que a escola cumpre os requisitos nacionais em matéria de educação previstos na lei e cooperam com as comunidades locais e os governos. Podem também trabalhar em escolas profissionais.', 'released', '["Diretor de Escola Secundária", "Diretor de Liceu", "Diretora de Liceu", "Diretora de Escola Secundária"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/53e61b71-60a3-4873-bc14-d6e28693818c', 'Diretor de Distribuição Têxteis', 'Os diretores de distribuição têxteis planificam a distribuição de produtos a vários pontos de venda.', 'released', '["Diretora de Distribuição Têxteis", "Diretora de Logística Têxteis", "Diretor de Distribuição Têxteis", "Diretor de Logística Têxteis"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/53ed8787-3423-4843-8c63-7be1877d29e2', 'Chefe de Mesa', 'Os chefes de mesa gerem o serviço alimentar e de bebidas num estabelecimento de hotelaria e restauração. São responsáveis pela experiência do cliente. Os chefes de mesa coordenam todas as ações que envolvam clientes, tais como o acolhimento dos clientes, os pedidos, a entrega dos alimentos e bebidas e a supervisão das transações financeiras.', 'released', '["Empregado de Mesa Chefe", "Empregada de Mesa Chefe", "Chefe de Serviço de Mesa", "Chefea de Mesa"]'::jsonb, '5131'),
  ('http://data.europa.eu/esco/occupation/54361270-bc5e-40fb-8f84-a0023a85cdf7', 'Professor de Belas Artes', 'Os professores de Belas Artes ensinam os alunos com teoria específica e, principalmente, cursos de Belas Artes baseados na prática, numa escola de Belas Artes ou num conservatório ao nível do ensino superior, incluindo desenho, pintura e escultura. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar nas Belas Artes. Os professores de Belas Artes acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho nas belas artes, frequentemente por meio de trabalhos, testes e exames práticos.', 'released', '["Professora Universitária de Belas Artes", "Professora de Belas Artes", "Professor de Belas Artes", "Professor Universitário de Belas Artes"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/544cd9cf-e2ee-4ac0-8a02-7147af6b97d7', 'Diretor de Planejamento e Estratégia', 'Define objetivos, prioridades e planos estratégicos da unidade de negócio, conectando análise de mercado, cenários, orçamento e execução operacional. Coordena o planejamento de curto, médio e longo prazo, acompanha indicadores de desempenho e apoia a liderança na tomada de decisão. Atua na gestão de mudanças e no alinhamento entre áreas, parceiros e stakeholders.', 'released', '["Diretor de Planejamento e Estratégia", "Diretor Comercial", "Diretora Comercial", "Diretor de Estratégia", "Diretor de Planejamento", "Diretor de Planejamento Estratégico", "Diretor de Estratégia e Planejamento", "Gerente de Planejamento Estratégico", "Gerente de Estratégia", "Head de Estratégia", "Diretora de Planejamento e Estratégia"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/546ec458-e2a4-4cb1-ac17-553d314ac2e2', 'Gestor de Estação de Tratamento de Água', 'Os gestores de estação de tratamento de água supervisionam o tratamento, o armazenamento e a distribuição de água numa estação de abastecimento de água. Asseguram a conformidade das operações da central com a regulamentação e supervisionam o pessoal. Aplicam igualmente novas políticas e supervisionam a manutenção dos equipamentos.', 'released', '["Gestora de Estação de Tratamento de Água Potável", "Gestora de Estação de Tratamento de Água", "Gestor de Estação de Tratamento de Água", "Gestor de Estação de Tratamento de Água Potável", "Gerente"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/547b304b-9a72-4717-9b24-b7046df5f64e', 'Vendedor Especializado', 'Os vendedores especializados vendem artigos em lojas especializadas.', 'released', '["Vendedor Especializado", "Vendedora Especializada", "Vendedora Especializado"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/54cba39a-5bb8-4e4c-89cd-d6097d3c6c3a', 'Assistente de Publicidade', 'Os assistentes de publicidade prestam apoio em todas as operações efetuadas nos serviços de publicidade ou nas agências de publicidade. Asseguram a gestão e a triagem das atividades administrativas. Comunicam com o pessoal do departamento de publicidade e com clientes externos. Além disso, têm conhecimento das operações de publicidade por forma a contribuir na execução pragmática dos planos e tarefas levados a cabo por gestores e consultores, bem como participam na criação de conteúdos para utilização em linha ou impressos.', 'released', '["Assistentea de Publicidade"]'::jsonb, '4419'),
  ('http://data.europa.eu/esco/occupation/54ffd31f-ed90-4af4-b877-cd246351ad39', 'Técnico de Pré-Impressão', 'Os técnicos de pré-impressão elaboram processos de impressão através da formatação, definição e composição de texto e gráficos de forma adequada. Tal inclui a captura do texto e da imagem e o tratamento dos mesmos por via eletrônica. Também procedem à preparação, manutenção resolução de problemas das máquinas de impressão.', 'released', '["Técnica de Pré-Impressão", "Técnico de Pré-Impressão"]'::jsonb, '7321'),
  ('http://data.europa.eu/esco/occupation/55076d82-52a7-47eb-b882-f12322c42ecd', 'Químico Especialista em Têxteis', 'Os químicos especialistas em têxteis coordenam e supervisionam os processos químicos de têxteis tais como fios e tecidos, nomeadamente o tingimento e o acabamento.', 'released', '["Técnica Especialista em Processos de Coloração e Acabamentos Têxteis", "Técnico Especialista em Design Têxtil para Estamparia", "Química Especialista em Têxteis", "Químico Especialista em Têxteis", "Técnico Especialista em Processos de Coloração e Acabamentos Têxteis", "Técnica Especialista em Design Têxtil para Estamparia"]'::jsonb, '2113'),
  ('http://data.europa.eu/esco/occupation/55167849-82cf-484e-b818-fa702a4e69e9', 'Hidrólogo', 'Os hidrólogos investigam e estudam a qualidade, os atuais desafios e a distribuição da água na Terra. Estudam o abastecimento de água a partir de rios, cursos de água e nascentes para determinar a sua utilização adequada e sustentável. Juntamente com uma equipe integrada de profissionais, planificam e desenvolvem a forma como a água pode ser fornecida às cidades e às zonas urbanas, assegurando simultaneamente a eficiência e a conservação dos recursos.', 'released', '["Hidrólogo", "Hidróloga de Superfície", "Hidrólogo de Superfície", "Hidrobióloga", "Hidrobiólogo", "Hidróloga"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/551a6797-3ca9-41fc-9dca-9a982a8fd8a6', 'Engenheiro Especialista em Robótica', 'Os engenheiros especialistas em robótica concebem e desenvolvem dispositivos e aplicações robóticos em combinação com princípios de engenharia mecânica. Recorrem a modelos preestabelecidos e às descobertas mais recentes para melhorar ou inventar sistemas, máquinas e equipamentos. Combinam vários domínios do conhecimento, como a informática, a engenharia e a eletrônica, no desenvolvimento de novas aplicações de engenharia.', 'released', '["Engenheiro Especialista em Robótica", "Engenheira Especialista em Robótica"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/5520bfd0-49d3-47e5-abe0-d72354711bc0', 'Operador de Máquina de Filtragem de Grãos de Cacau', 'Os operadores de máquina de filtragem de grãos de cacau operam máquinas para a remoção de matérias estranhas, tais como pedras, fios e sujidade das sementes de cacau. Operam silos para movimentar os grãos dos mesmos para tremonhas. Direcionam os grãos limpos para silos específicos. Operam um sistema de limpeza por ar para remover as restantes matérias estranhas.', 'released', '["Técnico de Operação de Instalação de Filtragem de Cacau", "Técnica de Operação de Instalação de Filtragem de Cacau", "Operador de Máquina de Filtragem de Grãos de Cacau", "Operadora de Máquina de Filtragem de Grãos de Cacau"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/555235ce-8c45-409b-a6c9-83e69c2d2bce', 'Praça de Engenharia Militar', 'Os praças de engenharia militar exercem funções técnicas e científicas nas forças armadas, tais como o desenvolvimento de conceitos de equipamento técnico militar, apoio ao fabrico de equipamento militar e investigação técnica, manutenção e garantia da qualidade.', 'released', '["Engenheiro de Combate", "Especialista em Ciência e Tecnologia de Defesa", "Técnico de Combate", "Engenheiro Militar", "Técnico de Defesa", "Engenheira de Balística", "Engenheira Militar", "Consultor em Engenharia Militar", "Engenheiro do Exército", "Engenheira do Exército", "Engenheira de Combate", "Engenheiro de Balística", "Técnica de Combate", "Técnica de Defesa", "Consultora em Engenharia Militar"]'::jsonb, '0310'),
  ('http://data.europa.eu/esco/occupation/555ad9ba-72cf-4bc0-9ea6-c36041462be5', 'Operador de Sistemas de Transporte de Gás', 'Os operadores de sistemas de transporte de gás transportam energia sob a forma de gás natural. Recebem gás natural da estação de produção, transportam-no através de gasodutos, assegurando a entrega às estações de distribuição de gás.', 'released', '["Operador de Sistemas de Transporte de Gás", "Operadora de Sistemas de Transporte de Gás"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/557f9ccc-4e46-4bb2-8d20-272cd978b152', 'Cientista Veterinário', 'Os cientistas veterinários desenvolvem e realizam investigação em modelos de animais, comparam a biologia básica entre animais e traduzem os resultados da investigação para diferentes espécies, incluindo os seres humanos.', 'released', NULL, '2250'),
  ('http://data.europa.eu/esco/occupation/5589e8e0-48d9-4193-8c85-86ba9f17e0e9', 'Modista', 'As modistas concebem, fazem ou adequam, alteram, reparam peças de vestuário feito à medida ou à mão a partir de tecidos têxteis, couro leve, peles com pelo e outro material para mulheres e crianças. Produzem peças de vestuário por medida, de acordo com as especificações do cliente ou do fabricante do vestuário. São capazes de ler e compreender tabelas de tamanho, pormenores sobre as medições acabadas, etc.', 'released', '["Estilista", "Costureiro"]'::jsonb, '7531'),
  ('http://data.europa.eu/esco/occupation/55a785db-0636-41b8-950f-0b65abe5e81b', 'Professor de Ciências Farmacêuticas', 'Os professores Ciências Farmacêuticas são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências Farmacêuticas, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio das Ciências Farmacêuticas, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Ciências Farmacêuticas", "Professor de Ciências Farmacêuticas", "Professora Universitária de Ciências Farmacêuticas", "Professora de Farmácia", "Professor Universitário de Ciências Farmacêuticas", "Professor de Farmácia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/55af6be8-039a-419c-b278-55b3f7d9ef92', 'Instrutor de Atividades ao Ar Livre', 'Os instrutores de atividades ao ar livre organizam e lideram viagens de recreio ao ar livre, através das quais os participantes aprendem competências, tais como caminhada, alpinismo, esqui, snowboard, canoagem, rafting, escalada com cordas, etc. Também proporcionam exercícios de reforço do espírito de equipe e seminários de atividades para participantes desfavorecidos. Asseguram a segurança dos participantes e do equipamento e explicam as medidas de segurança para que os participantes também se possam compreender. Os instrutores de atividades ao ar livre devem estar preparados para lidar com as consequências de más condições meteorológicas e acidentes, e devem gerir de forma responsável a ansiedade possível dos participantes em determinadas atividades.', 'released', '["Instrutor de Atividades ao Ar Livre", "Instrutora de Atividades ao Ar Livre"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/55b4faa3-286f-4fc8-ac67-8bbb97d08820', 'Responsável Administrativo em Estabelecimento Educativo', 'Os responsáveis administrativos em estabelecimentos educativos organizam e gerem a administração, os sistemas de apoio e as atividades (estudantis) de um estabelecimento de ensino. Executam uma série de tarefas administrativas, de secretariado, financeiras e outras tarefas de apoio, a fim de permitir uma gestão eficiente e eficaz em termos de custos da escola. Podem prestar apoio no recrutamento de estudantes, nas relações com antigos estudantes, no departamento de financiamento, no trabalho em comissões, incluindo conselhos académicos, e no domínio da garantia de qualidade.', 'released', '["Responsável Administrativa em Estabelecimento Educativo", "Responsável Administrativo em Estabelecimento Educativo"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/55d2eb3e-1e49-404a-b4bf-be4829694a59', 'Jurista-Linguista', 'Os juristas-linguistas interpretam e traduzem peças jurídicas de uma língua para outra. Realizam uma análise jurídica às informações que lhes são apresentadas e ajudam a compreender as especificidades técnicas do conteúdo expresso noutras línguas.', 'released', NULL, '2643'),
  ('http://data.europa.eu/esco/occupation/55d60ead-0343-4008-b9e4-fb4b5a179c83', 'Educador de Infância', 'Os educadores de infância ensinam aos alunos, sobretudo crianças jovens, matérias básicas e criatividade, com o objetivo de desenvolver as suas competências sociais e intelectuais de modo informal para os preparar para a futura aprendizagem formal. Criam planos de aula, eventualmente de acordo com um currículo fixo, para turmas inteiras ou grupos de menor dimensão e testam os alunos sobre os conteúdos. Estes planos, baseados em matérias básicas, podem incluir o ensino dos números, das letras e do reconhecimento das cores, dos dias da semana, da classificação dos animais e dos veículos de transporte, etc.. Os educadores de infância também supervisionam os alunos fora da sala de aula nas escolas e aplicam regras de comportamento.', 'released', '["Educadora de Infância", "Educador de Infância"]'::jsonb, '2342'),
  ('http://data.europa.eu/esco/occupation/55f001af-fa48-4c0c-a7e5-fc69babe3d45', 'Botânico', 'Os botânicos ocupam-se da manutenção de uma série de plantas de todo o mundo, muitas vezes num jardim botânico. Realizam estudos científicos e viagens para estudar plantas em ambiente selvagem. Os botânicos são responsáveis pela manutenção e pelo desenvolvimento do jardim botânico.', 'released', '["Botanista", "Botânica", "Botânico", "Jardineiro Chefe", "Jardineira-Chefe", "Jardineira Chefe", "Jardineiro-Chefe"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/55f6380c-7511-4c33-8fc4-c74f10f524fa', 'Ajudante de Cabeleireiro', 'Os ajudantes de cabeleireiro lavam o cabelo dos clientes, aplicam condicionador e o tratamento de cor num salão de beleza. Aplicam champô, esfregam o couro cabeludo e enxaguam o cabelo. Também podem fazer tratamentos do couro cabeludo, branqueamento, coloração e massagem aos clientes. Em função das necessidades e das preferências do cliente, utilizam a loções especializadas, champôs, condicionadores e outros equipamentos para o cabelo.', 'released', '["Ajudantea de Cabeleireiro"]'::jsonb, '5141'),
  ('http://data.europa.eu/esco/occupation/56245067-16f0-43e7-84fa-4a1e794a6ac0', 'Representante de Serviço de Aluguel de Máquinas e Equipamento de Escritório', 'Os representantes de serviço de aluguer de máquinas e equipamento de escritório são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Máquinas e Equipamento de Escritório"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/562dd713-5745-4457-929e-5b909da084ca', 'Responsável de Atividades Operacionais de Transporte por Dutos', 'Os responsáveis de atividades operacionais de transporte por condutas supervisionam os aspetos operacionais correntes do transporte de mercadorias através de infraestruturas de condutas. Têm uma visão geral da rede e planeiam os diferentes percursos de transporte de mercadorias de um local para outro. Procuram o percurso mais eficiente e menos oneroso. Resolvem os problemas que surgem nas redes e nos locais, asseguram a aplicação da regulamentação e acompanham a realização dos objetivos em matéria de transporte.', 'released', NULL, '4323'),
  ('http://data.europa.eu/esco/occupation/565987b2-b980-4881-891c-cc4d5ab61d07', 'Gravador de Pedra', 'Os gravadores de pedra utilizam ferramentas manuais, máquinas e produtos químicos para gravar e entalhar nas superfícies das pedras.', 'released', '["Gravador de Pedra", "Escultor de Pedra", "Gravadora de Pedra", "Escultora de Pedra"]'::jsonb, '7113'),
  ('http://data.europa.eu/esco/occupation/5684182e-7b4c-4eea-97d9-4c2b88b9f906', 'Marinheiro', 'Os marinheiros auxiliam o comandante de navio e qualquer membro da tripulação superior na hierarquia a operar navios. Limpam o pó e enceram o mobiliário, pulem os remates de madeira, varrem os pavimentos e os convés e pulem as peças de latão e outros elementos metálicas. Procedem à inspeção, reparação e manutenção das velas e dos cordames, bem como pintam e envernizam as superfícies. Efetuam reparações de emergência do motor auxiliar. Os marinheiros podem estivar os mantimentos e o equipamento e registar os dados no diário de bordo, tais como as condições meteorológicas e a distância percorrida.', 'released', '["Marinheira", "Marinheiro"]'::jsonb, '8350'),
  ('http://data.europa.eu/esco/occupation/56a535ff-189b-45da-97d4-775f78744f83', 'Vendedor de Óculos e Equipamento Ótico', 'Os vendedores de óculos e equipamento ótico vendem óculos em lojas especializadas.', 'released', '["Vendedora de Óculos e Equipamento Ótico", "Vendedor de Óculos e Equipamento Ótico"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/56afc09a-75a0-49c7-a5cb-256df45d8f2d', 'Consultor Econômico', 'Os consultores econômicos investigam as evoluções da economia e prestam aconselhamento sobre problemas econômicos. Preveem tendências e comportamentos no domínio da economia e prestam aconselhamento sobre assuntos financeiros, comerciais, fiscais e outros assuntos conexos. Aconselham as empresas e as organizações em matéria de técnicas de obtenção de lucro econômico.', 'released', '["Analista Econômica", "Consultora Econômica", "Analista Econômico", "Consultor Econômico", "Consultora Econômico"]'::jsonb, '2631'),
  ('http://data.europa.eu/esco/occupation/56bff5e1-3c76-4f45-b50e-e3a59bf1053e', 'Supervisor de Pós-Produção', 'Os supervisores de pós-produção supervisionam todo o processo de pós-produção. Trabalham em conjunto com o editor de música e com o editor de filmes e vídeos. Os supervisores de pós-produção ajudam a planear o fluxo de trabalho da produção, a fim de garantirem que a fase de pós-produção é incluída e orçamentada. Asseguram a entrega e distribuição do produto final.', 'released', '["Supervisor de Pós-Produção", "Supervisora de Pós-Produção"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/56fa783a-cca4-42ef-8862-1fb6e43f215c', 'Coordenador de Operações de Transporte Internacional de Mercadorias', 'Os coordenadores de operações de transporte internacional de mercadorias executam e controlam operações de transporte internacional através da resolução de problemas e da tomada de decisões relacionadas com as atividades de transporte e de apoio. Tratam dos encargos administrativos associados às operações internacionais, como a regulamentação em diferentes contextos nacionais relativa às importações e às exportações. Prestam apoio às empresas e executam funções de coordenação de projetos, avaliação e gestão dos sistemas atuais e gestão e procedimentos relativos à cadeia de abastecimento internacional, conforme necessário.', 'released', '["Coordenadora de Operações de Transporte Internacional de Mercadorias"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/570d7e74-5c65-4a9a-95ba-f8c27025c5f4', 'Professor de Física do Ensino Secundário', 'Os professores de Física do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Física. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Física através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Física do Ensino Secundário", "Professor de Física do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/5727b567-993d-4d41-a13d-81a6af1a9a8e', 'Psicólogo Social', 'Os psicólogos sociais prestam apoio e orientação aos indivíduos na área da ação social, tendo em vista ajudá-los a resolver problemas específicos da sua vida pessoal. Tal implica a abordagem de problemas pessoais e de relacionamento, lidando com os conflitos internos e momentos de crise, como a depressão e a dependência, numa tentativa de capacitar os indivíduos para concretizarem mudanças e melhorarem a sua qualidade de vida.', 'released', '["Psicóloga Social", "Psicólogo Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/572c51ef-531b-4331-8e66-b1641173e54e', 'Dramaturgo', 'Os dramaturgos leem novas peças e obras e propõem-nas ao diretor de palco e/ou ao conselho artístico de um teatro. Recolhem documentação sobre o trabalho, o autor, os problemas abordados, os tempos e os ambientes descritos. Participam igualmente na análise de temas, personagens, construção dramática, etc.', 'released', '["Dramaturga", "Dramaturgo"]'::jsonb, '2641'),
  ('http://data.europa.eu/esco/occupation/572c9810-e1ee-4f7a-a71f-820f17c0c25b', 'Trabalhador em Chapa Metálica', 'Os trabalhadores em chapa metálica na construção utilizam chapa metálica para a construção de telhados, condutas para aquecimento, ventilação e ar condicionado, calhas e outras estruturas metálicas. Interpretam os planos e determinam o tipo e a quantidade de materiais a utilizar, depois medem, dobram, cortam, moldam e anexam peças de chapa metálica para criar a estrutura necessária.', 'released', '["Trabalhador em Chapa Metálica", "Trabalhadora em Chapa Metálica"]'::jsonb, '7213'),
  ('http://data.europa.eu/esco/occupation/5734feab-60be-4f11-8e3f-e983ca6fb07a', 'Responsável por Estrebaria', 'Os responsáveis por estrebaria são responsáveis pela gestão diária da estrebaria, incluindo a gestão do pessoal, a prestação de cuidados aos cavalos, todos os aspetos da saúde e segurança e por lidar com clientes e proprietários.', 'released', '["Responsável Pelas Instalações para Cavalos", "Gestor de Centro Equestre", "Responsável por Cavalariça", "Chefe do Estábulo para Cavalos", "Responsável Pelas Cavalariças", "Gestora de Centro Equestre", "Responsável por Estrebaria"]'::jsonb, '6121'),
  ('http://data.europa.eu/esco/occupation/574f3232-1d07-4034-8cac-c57ddbfff192', 'Químico Analítico', 'Os químicos analíticos estudam e descrevem composição química das substâncias. Além disso, retiram conclusões sobre o comportamento dessas substâncias em diferentes condições. Os químicos analíticos desempenham um papel importante no estudo da relação entre a química e o ambiente, os alimentos, os combustíveis e a medicina. Utilizam uma série de técnicas, como a eletrocromatografia, a cromatografia gasosa, a cromatografia líquida de alta eficiência e a espetroscopia.;', 'released', '["Química Analítica", "Cristalógrafa", "Cristalógrafo", "Químico Analítico", "Química Analítico"]'::jsonb, '2113'),
  ('http://data.europa.eu/esco/occupation/574f46e2-e48d-4cde-a7b1-877004ea4c52', 'Gerente de Loja de Ferragens e Tintas', 'Os gerentes de loja de ferragens e tintas assumem a responsabilidade pelas atividades e pessoal em lojas especializadas. Gerem os trabalhadores, controlam as vendas da loja, gerem os orçamentos, efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Quinquilharia", "Gerente de Estabelecimento de Ferragens, Tintas e Vidros", "Gerentea de Loja de Ferragens e Tintas"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/5779aa3b-b32f-42f7-9581-ef5ce2092621', 'Gerente de Loja de Carnes', 'Os gerentes de loja de carnes assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Charcutaria", "Talhante", "Negociante de Carnes", "Gerente de Talho", "Gerentea de Loja de Carnes"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/578470d7-1848-44cd-a769-96cdd64b2c37', 'Escrivão', 'Os escrivães recolhem e registam atos de nascimento, casamento, parceria civil e morte.', 'released', '["Escrivão", "Escrivã", "Escrivãa"]'::jsonb, '3342'),
  ('http://data.europa.eu/esco/occupation/5791a961-4717-4230-a245-a4082a675f04', 'Técnico de Automação', 'Os técnicos de automação colaboram com os engenheiros de automação no desenvolvimento de aplicações e sistemas para a automação do processo de produção. Os técnicos de automação constroem, testam, monitorizam e efetuam a manutenção dos sistemas controlados por computador utilizados em sistemas de produção automáticos.', 'released', '["Técnico de Automação", "Técnica de Automação"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/579254cf-6d69-4889-9000-9c79dc568644', 'Engenheiro Mecânico', 'Os engenheiros mecânicos investigam, planificam e concebem produtos e sistemas mecânicos e supervisionam o fabrico, a operação, a aplicação, a instalação e a reparação de sistemas e produtos. Investigam e analisam dados.', 'released', '["Engenheiro Mecânico", "Engenheira Mecânica", "Engenheira Mecânico"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/5793c124-c037-47b2-85b6-dd4a705968dc', 'Agente de Polícia', 'Os agentes de polícia utilizam a métodos de investigação para prevenir a criminalidade, procurar e apreender criminosos e proteger o público de atividades violentas e criminosas. Realizam atividades de vigilância e de patrulha para prevenir crimes e deter os criminosos. Prestam apoio às partes vitimizadas e ao público em geral e cumprem funções administrativas.', 'released', '["Guarda", "Agentea de Polícia"]'::jsonb, '5412'),
  ('http://data.europa.eu/esco/occupation/57a09d3f-e3d6-49ad-8c88-d879fc4d0870', 'Operador de Bomba de Concreto', 'Os operadores de bomba de betão conduzem e operam caminhões para o transporte de betão da instalação para os locais dos projetos e operam bombas para dispersar o betão no local. Também procedem à limpeza e manutenção do caminhão e das respetivas peças mecânicas.', 'released', '["Operadora de Bomba de Concreto", "Operador de Bomba de Concreto"]'::jsonb, '8332'),
  ('http://data.europa.eu/esco/occupation/57a12047-4f1e-40ed-add5-9736923f231b', 'Astrônomo', 'Os astrónomos investigam a formação, as estruturas, as propriedades e o desenvolvimento dos corpos celestes e da matéria interstelar. Utilizam equipamento terrestre e equipamento espacial para recolher dados sobre o espaço para fins de investigação.', 'released', '["Astrofísico", "Astrônomo", "Astrônoma", "Astrofísica"]'::jsonb, '2111'),
  ('http://data.europa.eu/esco/occupation/57a73b7c-cf10-4852-b067-c25833fa149e', 'Perfusionista Clínico', 'Os perfusionistas clínicos operam equipamento cardiopulmonar durante operações cirúrgicas, destinado a assegurar a respiração e a circulação de sangue. Trabalham como parte da equipe cirúrgica, ligam o doente à máquina cardiopulmonar (coração-pulmão artificial) na preparação para a cirurgia, monitorizam o seu estado durante a cirurgia, informam a equipe sobre o estado do doente e determinam as técnicas necessárias em função das suas necessidades.', 'released', '["Técnica de Cardiopneumologia", "Técnico de Cardiopneumologia", "Perfusionista Clínica", "Cardeopneumologista", "Perfusionista Clínico"]'::jsonb, '3211'),
  ('http://data.europa.eu/esco/occupation/57ac359a-ae52-4aea-bc9c-93af7efa502e', 'Engenheiro Especialista em Gasodutos', 'Os engenheiros especialistas em gasodutos concebem e desenvolvem os aspetos de engenharia na construção de infraestruturas de gasodutos em vários tipos de instalações (por exemplo, terrestres, marítimas). Visam e criam as especificações para os sistemas de bombagem e para o transporte geral de produtos através das condutas.', 'released', '["Engenheiro Especialista em Gasodutos", "Engenheira Especialista em Gasodutos"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/57af9090-55b4-4911-b2d0-86db01c00b02', 'Desenvolvedor de Sistemas Embarcados', 'Os programadores de software de sistemas embarcados programam, implementam, documentam e mantêm software destinado a ser executado num sistema embarcado.', 'released', '["Programador de Software de Sistemas Embarcados", "Criador de Software de Sistemas Embarcados", "Programadora de Software de Sistemas Embarcados", "Criadora de Software de Sistemas Embarcados", "Programador", "Desenvolvedora de Sistemas Embarcados"]'::jsonb, '2514'),
  ('http://data.europa.eu/esco/occupation/57b459d4-655c-4053-b189-3c249ce33faf', 'Gestor de Desenvolvimento de Negócios de Tecnologia da Informação', 'Os gestores de desenvolvimento de negócios de TIC aumentam as oportunidades de negócio para a organização e desenvolvem estratégias destinadas a reforçar o bom funcionamento da organização, bem como o desenvolvimento e a distribuição dos produtos. Negoceiam os preços e estabelecem cláusulas contratuais.', 'released', '["Gestor de Desenvolvimento de Negócios de Tecnologias de Informação e Comunicação", "Gestora de Desenvolvimento de Negócios de TI", "Responsável Pela Gestão do Desenvolvimento de Negócios de Tecnologias de Informação e Comunicação", "Gestora de Desenvolvimento de Negócios de Tecnologias de Informação e Comunicação", "Responsável Pela Gestão do Desenvolvimento de Negócios de TI", "Gestor de Desenvolvimento de Negócios de TI", "Gestora de Desenvolvimento de Negócios de Informática", "Gestor de Desenvolvimento de Negócios de Informática", "TI", "Gerente", "Gestora de Desenvolvimento de Negócios de Tecnologia da Informação"]'::jsonb, '2434'),
  ('http://data.europa.eu/esco/occupation/57b89801-0e43-4b19-bf29-ef9a51d65155', 'Recozedor de Metais', 'Os recozedores de metais utilizam fornos elétricos ou a gás para suavizar o metal, para que possa ser cortado e moldado mais facilmente. Aquecem o metal a uma temperatura e/ou cor específicas e, em seguida, arrefecem-no lentamente, realizando ambos os processos em conformidade com as especificações. Os recozedores de metais inspecionam os metais ao longo de todo o processo para observar eventuais falhas.', 'released', '["Recozedor de Metais", "Recozedora de Metais"]'::jsonb, '8121'),
  ('http://data.europa.eu/esco/occupation/57d1be2e-c476-43fb-b014-fa58602cac95', 'Supervisor de Desmantelamento', 'Os supervisores de desmantelamento acompanham as operações de desmantelamento, como a remoção e, eventualmente, a reciclagem de equipamentos e máquinas industriais ou a desativação de instalações. Distribuem as tarefas pelos trabalhadores e supervisionam se estão a ser realizadas de acordo com a regulamentação em matéria de segurança. Em caso de ocorrência de problemas, consultam engenheiros e tomam decisões rápidas para os resolver.', 'released', '["Supervisora de Desmantelamento", "Supervisor de Desmantelamento"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/57e87533-e523-4ee5-bf21-94a39fcc279b', 'Gestor Ambiental e de Saúde e Segurança', 'Os gestores ambientais e de saúde e segurança concebem e põem em prática políticas e procedimentos empresariais relacionados com a saúde e segurança no trabalho e a proteção do ambiente. Analisam os processos empresariais para assegurar o cumprimento da legislação governamental e ambiental, efetuam avaliações de risco no domínio da saúde e segurança no trabalho, avaliam o impacto ambiental das atividades econômicas e concebem as medidas adequadas para melhorar os ambientes e as culturas de trabalho. Coordenam a implementação de um sistema integrado de gestão da saúde, segurança e ambiente, definindo indicadores eficazes, organizando auditorias e, eventualmente, participando na investigação e na comunicação de acidentes. Promovem uma abordagem integrada da sustentabilidade e da saúde no trabalho em organizações empresariais, estabelecendo a ligação com os gestores empresariais e de linha e ministrando formação aos trabalhadores. São responsáveis pela elaboração da documentação técnica relativa ao cumprimento da legislação em matéria de saúde, segurança e ambiente.;', 'released', '["Coordenador de HSE", "Diretora de HSE", "Gerente de HSE e Serviços de Sustentabilidade", "Diretor de HSE", "Gerente de HSE Corporativo", "Coordenadora de HSE", "Gerente", "Gestora Ambiental e de Saúde e Segurança"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/580c98d4-fb97-4597-864c-54140f058f1b', 'Auditor de Qualidade de Centro de Atendimento', 'Os auditores de qualidade de centros de atendimento ouvem chamadas dos operadores de centros de atendimento, gravadas ou em tempo real, a fim de avaliarem a conformidade com os protocolos e os parâmetros de qualidade. Atribuem classificações aos funcionários e fornecem informações sobre as questões que necessitam de ser melhoradas. Interpretam e divulgam os parâmetros de qualidade recebidos pela chefia.', 'released', '["Auditora de Qualidade de Centro de Chamadas", "Auditora de Qualidade de Centro Telefônico de Atendimento", "Auditor de Qualidade de Centro de Atendimento", "Auditor de Qualidade de Centro Telefônico de Atendimento", "Auditora de Qualidade de Centro de Atendimento", "Auditora de Qualidade de Call Centre", "Auditor de Qualidade de Centro da Chamadas", "Auditor de Qualidade de Call Centre"]'::jsonb, '3341'),
  ('http://data.europa.eu/esco/occupation/586fe133-1987-41f4-b89a-f39d4bc58e1e', 'Gestor de Comércio Eletrônico', 'Os gestores de comércio eletrônico criam e executam o plano estratégico de comércio eletrônico de uma empresa para a venda em linha de produtos e serviços. Além disso, melhoram a integridade dos dados, a colocação de ferramentas em linha e a exposição das marcas, e acompanham as vendas das empresas que comercializam produtos aos clientes que utilizam a Internet. Colaboram com a equipe de marketing e gestão de vendas, utilizando ferramentas de TIC para atingirem os objetivos de vendas e fornecerem informações precisas e ofertas aos parceiros comerciais.', 'released', '["Gestora de Comércio Online", "Gestor de e-Comércio", "Gestora de Comércio Eletrônico", "Gestora de e-Comércio", "Gestor de Comércio Online", "Gestor de Comércio Eletrônico", "Gerente"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/589efb6c-9080-40b2-ab6a-144955675967', 'Sacristão', 'Os sacristãos exercem funções administrativas para as igrejas e paróquias, asseguram a manutenção do equipamento e apoiam o padre da paróquia ou outros superiores. Também desempenham funções de assistência antes e depois do serviço eclesiástico, tais como a arrumação, a preparação do equipamento e o apoio ao sacerdote.', 'released', '["Sacristã", "Sacristão", "Sacristãa"]'::jsonb, '5153'),
  ('http://data.europa.eu/esco/occupation/58c30193-d29f-4d22-8bf0-fd87346b91dd', 'Engenheiro de Instalações', 'Os engenheiros de instalações supervisionam e gerem a instalação de estruturas que levam muitos anos a conceber e construir. Garantem a segurança, evitam os riscos e visam a otimização dos custos. Os engenheiros de instalações também criam desenhos construtivos dos sistemas e realizam ensaios dos sistemas de instalação. Determinam o material necessário para a construção desses sistemas e os custos, e utilizam software CAD para conceber esses sistemas.', 'released', '["Engenheira de Instalações", "Engenheiro de Instalações"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/58db35e3-fe1f-44d2-8a9e-ab652fc1cec2', 'Comerciante Grossista de Carne e de Produtos à Base de Carne', 'Os operadores grossistas de carne e de produtos à base de carne investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Carne e de Produtos à Base de Carne"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/58db3ac6-5217-4d46-8a4c-126598be1d13', 'Engenheiro Especialista em Sistemas Elétricos de Energia', 'Os engenheiros especialistas em sistemas elétricos de energia concebem e desenvolvem sistemas que geram eletricidade e desenvolvem estratégias para a melhoria dos sistemas de produção de eletricidade existentes. Procuram conciliar soluções sustentáveis com soluções eficientes e a preços acessíveis. Participam em projetos em que é necessário o fornecimento de eletricidade.', 'released', '["Engenheiro Especialista em Sistemas Elétricos de Energia", "Engenheira Especialista em Sistemas Elétricos de Energia"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/58f3f9fc-c9f6-4e14-bedf-a71ace5f27c5', 'Treinador de Expressão Corporal', 'Os treinadores de expressão corporal planeiam, organizam e orientam as atividades artísticas para desportistas, a fim de lhes proporcionar competências artísticas, tais como a dança, a representação, a expressão e a transmissão, que são importantes para o seu desempenho desportivo. Os treinadores de expressão corporal permitem o acesso a competências técnicas, de representação ou artísticas aos desportistas, com o objetivo de melhorar o seu desempenho desportivo.', 'released', '["Treinadora de Expressão Cultural", "Treinador de Expressão Cultural", "Treinadora de Expressão Corporal"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/58ff0ec2-08ba-4b21-b765-babb6d76ca36', 'Assistente de Bordo', 'Os assistentes de bordo realizam atividades de serviços de restauração em todos os serviços de viagens terrestres, marítimas e aéreas.', 'released', '["Comissário de Bordo", "Comissária de Bordo", "Assistentea de Bordo"]'::jsonb, '5111'),
  ('http://data.europa.eu/esco/occupation/59088d93-bd71-4fd7-a39e-8cc9dd37dfae', 'Fabricante de Cópias de Mobiliário Antigo', 'Os fabricantes de cópias de mobiliário antigo reproduzem e recriam mobiliário antigo. Preparam os desenhos e os modelos do artigo, criam, instalam e montam peças e terminam o artigo de acordo com as especificações originais.', 'released', '["Fabricantea de Cópias de Mobiliário Antigo"]'::jsonb, '7522'),
  ('http://data.europa.eu/esco/occupation/591c5063-69ce-4551-ba60-e2304111130f', 'Responsável de Comunicações de Dados Aeronáuticos', 'Os responsáveis de comunicações de dados aeronáuticos realizam o planejamento, a execução e a manutenção das redes de transmissão de dados. Apoiam os sistemas de tratamento de dados que ligam as agências dos participantes aos computadores centrais.', 'released', NULL, '3513'),
  ('http://data.europa.eu/esco/occupation/591d1758-3036-407a-91f7-e0e1f5c9deea', 'Professor de Cursos Profissionais na Área da Eletrônica e Automação', 'Os professores de cursos profissionais na área da eletrônica e automação formam os alunos no seu domínio de estudos especializado, a eletrônica e automação, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com a eletrônica e automação, tais como eletricistas ou técnicos envolvidos em processos de produção automatizada. Os professores de cursos profissionais na área da eletrônica e automação acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da eletrônica e automação através de trabalhos, testes e exames.', 'released', '["Professor de Cursos Profissionais na Área da Eletrônica e Automação", "Professora de Cursos Profissionais na Área da Eletrônica e Automação"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/59207c91-eefa-4f26-baae-9ea215320ed0', 'Montador de Pirotecnia', 'Os montadores de pirotecnia criam dispositivos explosivos, luzes coloridas e instalam dispositivos de pirotecnia. Seguem esquemas ou imagens, fabricam diferentes pós, colocam o pó em invólucros ou tubos, montam todas as peças e inspecionam o produto final.', 'released', '["Montador de Pirotecnia", "Montadora de Pirotecnia"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/594170bc-5663-40b0-97ef-c9f1ad51b2a0', 'Gerente de Agência de Seguros', 'Os gerentes de agência de seguros coordenam e supervisionam as operações de uma instituição ou sucursal de uma instituição que oferece serviços de seguros. Prestam aconselhamento aos clientes sobre produtos de seguros.', 'released', '["Diretor de Agência de Seguros", "Diretor de Sucursal de Companhia de Seguros", "Diretora de Sucursal de Companhia de Seguros", "Diretora de Agência de Seguros", "Gerentea de Agência de Seguros"]'::jsonb, '1346'),
  ('http://data.europa.eu/esco/occupation/5945cba8-19a4-4632-8a8f-4186e2bad1a3', 'Diretor de Produção na Aquicultura', 'Os diretores de produção na aquicultura planificam, dirigem e coordenam a produção de peixes, moluscos e outras formas de vida aquática, nomeadamente culturas para fins comerciais, em operações aquícolas de grande escala para cultura e colheita ou para libertação em água doce, salobra ou salgada.', 'released', '["Gestora de Produção na Aquicultura", "Diretor de Produção na Aquicultura", "Diretora de Produção na Aquicultura", "Gestor de Produção na Aquicultura"]'::jsonb, '1312'),
  ('http://data.europa.eu/esco/occupation/5979893a-0a30-447b-8f33-1ea405600583', 'Engenheiro Especializado em Grupos Motopropulsores', 'Os engenheiros especializados em grupos motopropulsores trabalham na concepção de mecanismos de propulsão em todo o setor automóvel. Tal inclui a implementação técnica de componentes do grupo motopropulsor, como a engenharia mecânica, a eletrônica e o software utilizados em veículos modernos, bem como a coordenação e a otimização de múltiplas fontes de energia no contexto do grupo motopropulsor.;', 'released', '["Engenheiro de Propulsão", "Engenheira de Desenvolvimento de Propulsão", "Engenheiro de Transmissão", "Engenheira de Propulsão", "Projetista de Powertrain", "Engenheira de Transmissão", "Engenheiro de Desenvolvimento de Propulsão", "Especialista em Powertrain", "Engenheira Especializado em Grupos Motopropulsores"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/59883630-45f9-40e7-9732-9e5ff9758d2b', 'Coordenador de Programas de Sensibilização Ambiental', 'Os coordenadores de programas de sensibilização ambiental desenvolvem programas para melhorar a sustentabilidade e a eficiência ambientais de uma organização ou instituição. Inspecionam as instalações a fim de controlar o cumprimento da legislação ambiental por parte das organizações ou instituições. Além disso, asseguram a informação do público sobre preocupações ambientais.', 'released', '["Auditor de Sistemas de Gestão Ambiental", "Gestor Ambiental", "Auditora de Sistemas de Gestão Ambiental", "Gestora Ambiental", "Coordenador de Programas de Sensibilização Ambiental", "Coordenadora de Programas de Proteção do Ambiente", "Coordenadora de Programas de Sensibilização Ambiental"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/599c2ce9-0e1b-4f63-9d65-1f19b3847efb', 'Técnico de Equipamento de Forja', 'Os técnicos de equipamento de forja procedem à manutenção e reparação de máquinas, tais como prensas e equipamento de manuseamento de materiais. Realizam avaliações do equipamento e atividades de manutenção preventiva e reparam falhas. Também ajudam na instalação do equipamento e asseguram o funcionamento adequado.', 'released', '["Técnica de Equipamento de Forja", "Técnico de Equipamento de Forja~"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/599f34f0-bdf7-49e3-b5a9-f5d55f9e6873', 'Montador de Produtos Plásticos', 'Os montadores de produtos plásticos encaixam e secam peças e produtos plásticos acabados de acordo com procedimentos rigorosamente definidos. Os montadores de produtos plásticos também podem cortar e moldar peças plásticas utilizando ferramentas manuais, elétricas e máquinas.', 'released', '["Montador de Produtos Plásticos", "Montadora de Produtos Plásticos"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/59a02420-91df-4e46-b37b-22e3fd8c11f0', 'Professor de Física', 'Os professores de Física são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Física, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da Física, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor Universitário de Física", "Professora Universitária de Física", "Professora de Física", "Professor de Física"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/59bbece0-d1dc-4f4a-845e-1523f68afb2d', 'Operador de Máquinas de Fiação', 'Os operadores de máquinas de fiação produzem fios, cordas e outras fibras através de máquinas de fiação, torção, enrolamento e de dobar. Manuseiam as matérias-primas, preparam-nas para os processos de fiação e utilizam máquinas para o efeito. Também realizam a manutenção de rotina da máquina.', 'released', '["Operador de Máquinas de Fiação", "Operadora de Máquinas de Fiação"]'::jsonb, '8151'),
  ('http://data.europa.eu/esco/occupation/59bce29f-5c8b-47cf-bfd4-6ec003f5323a', 'Explicador', 'Os explicadores proporcionam um ensino personalizado a crianças ou adultos, em complemento do sistema de ensino principal. Ajudam os alunos a melhorar os seus conhecimentos e competências numa disciplina específica, ao seu próprio ritmo. Os explicadores ensinam aos alunos técnicas e estratégias de estudo a fim de assegurar o seu desenvolvimento académico e avaliam o progresso do aluno ao longo das sessões de explicação.', 'released', '["Explicador", "Explicadora"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/59c22779-4d89-4bc9-ba8b-d64bea236723', 'Consultor Fiscal', 'Os consultores fiscais utilizam os seus conhecimentos especializados em legislação fiscal para prestar serviços de assessoria e consultoria para fins comerciais a um vasto leque de clientes de todos os setores econômicos. Explicam a legislação fiscal complexa aos seus clientes e ajudam-nos a assegurar o pagamento de impostos mais eficiente e benéfico através da elaboração de estratégias fiscais eficientes. Informam-nos igualmente das alterações e das evoluções em matéria de fiscalidade e podem especializar-se em estratégias fiscais relativas a fusões ou restruturações multinacionais de clientes empresariais, fundos e impostos sobre o património para clientes individuais, etc.', 'released', '["Consultora Fiscal", "Consultor Fiscal"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/59c724f9-0cfe-4d51-8a7f-9ee182d9e2c2', 'Professor de Língua Gestual', 'Os professores de língua gestual ensinam língua gestual a alunos independentemente da sua idade. Ensinam língua gestual a alunos com ou sem necessidades educativas especiais, como surdez. Organizam as suas turmas utilizando uma grande variedade de materiais, trabalham de forma interativa com o grupo e avaliam os progressos individuais através da atribuição de trabalhos e exames.', 'released', '["Professor de Língua Gestual", "Professora de Língua Gestual"]'::jsonb, '2353'),
  ('http://data.europa.eu/esco/occupation/59cc9783-7289-4e1d-b80b-93c1776f49cc', 'Construtor de Casas', 'Os construtores de casas procedem à construção, manutenção e reparação de casas ou pequenos edifícios semelhantes utilizando uma série de técnicas e materiais de vários operários da construção de edifícios.', 'released', '["Construtor", "Construtora Civil", "Construtor Civil", "Construtora", "Construtora de Casas"]'::jsonb, '7111'),
  ('http://data.europa.eu/esco/occupation/59cfa27b-874f-48b7-8880-b65420239559', 'Técnico de Pirotecnia', 'Os técnicos de pirotecnia controlam os elementos pirotécnicos de um espetáculo com base no conceito artístico ou criativo, em interação com os artistas. O seu trabalho é influenciado e influencia os resultados dos outros operadores. Por conseguinte, os operadores trabalham em estreita colaboração com os designers, os operadores e os artistas. Os pirotécnicos preparam os artigos de pirotecnia, supervisionam a instalação, orientam a equipe técnica, programam o equipamento e operam o sistema pirotécnico. A utilização de material explosivo e combustível próximo dos artistas e do público faz com que seja uma atividade de alto risco. ;', 'released', '["Técnico de Pirotecnia", "Técnica de Pirotecnia"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/59dae100-fdfe-44bd-8bd8-a0d3cd813ce4', 'Técnico de Produção de Calçado', 'Os técnicos de produção de calçado realizam uma vasta gama de atividades no domínio do fabrico de calçado. Estão envolvidos em todas as fases do processo, incluindo a engenharia do produto e os diferentes tipos de construção. Visam maximizar a produtividade e reduzir os custos de produção, garantindo a funcionalidade e a qualidade do produto e a satisfação do cliente.', 'released', '["Técnica de Produção de Calçado", "Técnico de Produção de Calçado"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/59ee6b71-a48d-4940-bdf1-e806ca60245c', 'Operador de Máquinas de Enchimento de Cilindros de Gases', 'Os operadores de máquinas de enchimento de cilindros de gases procedem à operação e manutenção do equipamento e dos recipientes utilizados para encher os cilindros com gases em estado liquefeito ou comprimido.', 'released', '["Operador de Máquinas de Enchimento de Cilindros de Gases", "Operadora de Máquinas de Enchimento de Cilindros de Gases"]'::jsonb, '8183'),
  ('http://data.europa.eu/esco/occupation/5a0ff408-e1df-424b-a2d6-4b475a516f2a', 'Técnico de Cenografia', 'Os técnicos de cenografia instalam, preparam, verificam e mantêm cenários pré-montados, a fim de proporcionar uma ótima qualidade de cenários para um espetáculo ao vivo. Cooperam com a equipe de apoio de estrada para descarregar, instalar e transportar equipamento e cenários.', 'released', '["Técnica de Cenografia", "Técnico de Cenografia"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/5a16dff6-ca31-4a39-85dd-4b5aa0f45419', 'Capataz de Manobras Ferroviárias', 'Os capatazes de manobras ferroviárias deslocam unidades de manobras com ou sem vagões ou grupos de vagões, a fim de construir comboios. Gerem a condução de locomotivas e estão envolvidos na mudança de vagões, na composição ou na divisão de comboios em estações ou vias de manobras. Trabalham de acordo com as características técnicas, tais como o controlo da circulação através de um dispositivo de comando à distância.', 'released', NULL, '8312'),
  ('http://data.europa.eu/esco/occupation/5a282a39-5346-454a-b1ef-c1217c50e156', 'Investigador em Ciências da Educação', 'Os investigadores em Ciências da Educação realizam investigação no domínio da educação. Procuram alargar os conhecimentos sobre a forma como os processos de ensino, os sistemas educativos e os indivíduos (professores e alunos) trabalham. Preveem áreas de melhoria e elaboram planos para a implementação de inovações. Aconselham os legisladores e os decisores políticos sobre questões educativas e prestam assistência no planejamento das políticas educativas.', 'released', '["Pedagoga", "Investigadora em Ciências da Educação", "Pedagogo", "Investigador em Ciências da Educação"]'::jsonb, '2351'),
  ('http://data.europa.eu/esco/occupation/5a2d0031-5dfd-46e8-8eb4-cf1d03876940', 'Comerciante Grossista de Laticínios e Óleos Alimentares', 'Os comerciantes grossistas de laticínios e óleos alimentares investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Laticínios e Óleos Alimentares"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/5a551d36-0e14-40ab-84a2-7aa9b37dc528', 'Restaurador de Mobiliário', 'Os restauradores do mobiliário analisam os materiais e as técnicas para avaliar o estado de uma peça de mobiliário antigo e identificá-la e classificá-la de acordo com a história da arte e da cultura. Utilizam ferramentas e técnicas antigas ou modernas para restaurar a peça e aconselhar os clientes quanto ao restauro, à conservação e à manutenção de tais objetos.', 'released', '["Restauradora de Mobiliário", "Restaurador de Mobiliário"]'::jsonb, '7522'),
  ('http://data.europa.eu/esco/occupation/5a58da2b-2fa0-40d4-a9f5-fead48e7de88', 'Arquiteto Naval', 'Os arquitetos navais concebem, constroem, mantêm e reparam todos os tipos de embarcações, desde embarcações de recreio a embarcações navais, incluindo submarinos. Analisam estruturas flutuantes e têm em conta diversas características, tais como a forma, a estrutura, a estabilidade, a resistência, o acesso e a propulsão dos cascos.', 'released', '["Designer de Iates", "Arquiteta Naval", "Arquiteto Naval"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/5a596834-bc8f-4273-8d09-006957b60347', 'Mergulhador Comercial do Setor da Construção', 'Os mergulhadores comerciais do setor da construção trabalham abaixo da superfície da água para instalar equipamento, tais como estruturas hidráulicas, vias navegáveis e meios marítimos. Também procedem à inspeção, remoção e reparação das estruturas.', 'released', '["Mergulhadora Comercial do Setor da Construção", "Mergulhador Comercial do Setor da Construção"]'::jsonb, '7541'),
  ('http://data.europa.eu/esco/occupation/5a80044b-9b2f-40eb-a210-0c1c3c958e0e', 'Nadador-Salvador Formador', 'Os nadadores-salvadores formadores ensinam aos futuros nadadores-salvadores (profissionais) os programas e métodos necessários para serem nadadores-salvadores licenciados. Prestam formação sobre a supervisão da segurança de todos os nadadores, a avaliação de situações potencialmente perigosas, as técnicas específicas de salvamento e as técnicas de mergulho, o tratamento de primeiros socorros para lesões relacionadas com a água, e informam os alunos sobre as responsabilidades preventivas do nadador-salvador. Garantem que os alunos estão conscientes da importância de verificar a segurança da qualidade da água, da gestão dos riscos e do conhecimento dos protocolos e regulamentos necessários em matéria de salvamento e socorro. Acompanham a evolução dos alunos, avaliam-nos através de exames teóricos e práticos e atribuem as licenças de nadador-salvador quando estas são obtidas.', 'released', '["Nadador-Salvador Formadora", "Nadador-Salvador Formador", "Nadador-Salvadora Formador"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/5a8835bf-65c7-48e3-ab2f-7ad98b3fdb59', 'Consultor de Propriedade Intelectual', 'Os consultores de propriedade intelectual prestam aconselhamento sobre a utilização de propriedade intelectual, como patentes, direitos de autor e marcas comerciais. Ajudam os clientes a avaliar, em termos monetários, as carteiras de propriedade intelectual, a seguir os procedimentos legais adequados para a proteção desses bens e a realizar atividades de corretagem de patentes.', 'released', '["Consultora de Propriedade Intelectual", "Consultor de Propriedade Intelectual"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/5a91a8bc-eb18-4c7e-847d-96cbcce5a47a', 'Redator de Discursos', 'Os redatores de discursos pesquisam e redigem discursos sobre vários temas. Têm de atrair e manter o interesse de um público. Os redatores de discursos criam apresentações em tom de conversa, fazendo parecer que o texto não foi redigido. Escrevem de forma compreensível, para que o público receba a mensagem do discurso.', 'released', '["Redator de Discursos", "Redatora de Discursos", "Autor de Discursos", "Autora de Discursos"]'::jsonb, '2641'),
  ('http://data.europa.eu/esco/occupation/5a940ae0-3fa4-40f9-8ca4-17bf792da243', 'Tratador de Animais', 'Os tratadores de animais são responsáveis pelo tratamento de uma gama de animais, utilizando o equipamento, os materiais e os métodos corretos. Isto inclui a utilização de técnicas de manuseamento adequadas e seguras e a promoção da boa higiene, da saúde e do bem-estar dos animais.', 'released', '["Tratador de Animais", "Esteticista de Animais", "Tratadora de Animais"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/5a9acd29-666c-4ca1-b10e-e086584a526b', 'Técnico de Saúde Mental', 'Os técnicos de saúde mental prestam assistência e tratamento a pessoas com problemas mentais, emocionais ou de abuso de substâncias. Centram-se em casos personalizados e acompanham o processo de recuperação dos seus clientes, fornecendo também terapia, intervenção em situações de crise, defesa dos clientes e educação.', 'released', '["Ténica de Saúde Mental", "Técnico de Saúde Mental", "Técnica de Saúde Mental"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/5ab842f6-1f75-4d84-bf41-b8a9799347df', 'Carroçador', 'Os carroçadores realizam trabalhos nas carroçarias de veículos e ônibus. Têm competências para formar peças a partir de painéis, fabricam e montam os quadros e peças para veículos.;', 'released', '["Carroçador", "Carroçadora"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/5ac377d2-e1d0-4911-a299-b4ef2782a0ba', 'Secretário', 'Os secretários desempenham uma série de tarefas administrativas para ajudar a manter o bom funcionamento de uma organização. Atendem o telefone, redigem e enviam mensagens de correio eletrônico, controlam as agendas, organizam marcações, recebem mensagens, arquivam documentos, organizam e prestam apoio a reuniões e gerem bancos de dados.', 'released', '["Recepcionista", "Secretária", "Secretário"]'::jsonb, '4120'),
  ('http://data.europa.eu/esco/occupation/5ac65daa-0896-4193-9f0e-8b00746b78a1', 'Assistente de Investigação', 'Os assistentes de investigação universitária realizam investigação académica para a universidade ou estabelecimento de ensino superior em que trabalham. Podem prestar assistência aos professores a que estão afiliados, ao seu supervisor, na sua investigação ou desenvolver a sua própria investigação na área relacionada desse professor.', 'released', '["Investigadora Auxiliar", "Investigador Auxiliar", "Assistentea de Investigação"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/5aeaea2f-6585-4d3d-8f3e-1fdd9903aa32', 'Chefe de Equipe de Produção Frutífera', 'Os chefes de equipe de produção de frutífera são responsáveis por liderar e trabalhar com uma equipe. Organizam os horários de trabalho diários para a produção de fruta e participam nos processos de produção.', 'released', '["Fruticultora", "Fruticultor", "Chefea de Equipe de Produção Frutífera"]'::jsonb, '6112'),
  ('http://data.europa.eu/esco/occupation/5aff8b2a-298a-456d-957a-274c774e8523', 'Técnico de Máquinas de Moldar', 'Os técnicos de máquinas de moldar procedem à manutenção das máquinas utilizadas na fundição e moldagem de plásticos e outros materiais. Realizam a calibração do equipamento e atividades de manutenção, examinam os produtos acabados e as reparações.', 'released', '["Técnico de Máquinas de Moldar", "Técnica de Máquinas de Moldar"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/5b3ef95b-7d99-4af9-b2d0-41c6bc33f58c', 'Misturador de Produtos Químicos', 'Os misturadores de produtos químicos procedem à operação e manutenção de tanques de mistura e misturadores para desenvolver produtos químicos a partir de matérias-primas, certificando-se de que os produtos finais estejam em conformidade com as especificações dos números dos lotes.', 'released', '["Misturador de Produtos Químicos", "Misturadora de Produtos Químicos"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/5b6c0c64-1321-4fe7-a274-3287c13b489c', 'Professor de Educação Musical do Ensino Secundário', 'Os professores de Educação Musical do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a música. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da música através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Educação Musical do Ensino Secundário", "Professor de Educação Musical do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/5b912733-abc8-43f7-825c-00ae21043685', 'Diretor de Importação e Exportação de Madeiras e Materiais de Construção', 'Os diretores de importação e exportação de madeiras e materiais de construção implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação de Madeiras e Materiais de Construção", "Diretora de Vendas de Madeiras e Materiais de Construção", "Diretor de Vendas de Madeiras e Materiais de Construção", "Diretora de Importação e Exportação de Madeiras e Materiais de Construção"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/5b942a51-c9a2-4dc7-82cc-57451426cf4d', 'Impressor Têxtil', 'Os impressores têxteis efetuam operações de impressão de têxteis.', 'released', '["Impressora Têxtil", "Impressor Têxtil"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/5b9a678a-7c35-4c50-a804-754b82652ee6', 'Organizador de Excursões', 'Os organizadores de excursões são responsáveis pela gestão e supervisão do itinerário de uma viagem turística e fornecem informações práticas aos turistas.', 'released', '["Organizador de Excursões", "Líder de Excursões", "Gestor de Excursões", "Gestora de Excursões", "Organizadora de Excursões"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/5baffa9d-1607-4665-be94-662bad26b9ff', 'Encarregado de Destilaria', 'Os encarregados de destilarias coordenam os processos de produção de bebidas espirituosas e gerem os trabalhadores envolvidos nesses processos. Verificam a produção dos licores destilados em quantidades e com provas (de álcool) especificadas.', 'released', '["Encarregada de Destilaria", "Encarregado de Destilaria", "Supervisor de Destilaria", "Supervisora de Destilaria"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/5bca96fd-4203-400b-be58-9e9b50bc98da', 'Membro do Parlamento', 'Os membros do Parlamento representam os interesses dos seus partidos políticos nos parlamentos. Exercem funções legislativas, desenvolvem e propõem novas leis e comunicam com funcionários do governo para avaliar questões atuais e o funcionamento do Governo. Supervisionam a aplicação da legislação e das políticas e funcionam como representantes dos governos junto do público, a fim de garantir a transparência.', 'released', '["Deputado", "Membro do Parlamento Europeu", "Membro do Parlamento", "Deputada", "Membro da Assembleia da República", "Membra do Parlamento"]'::jsonb, '1111'),
  ('http://data.europa.eu/esco/occupation/5beafebe-9211-4b3a-adf1-6161097a3975', 'Fisioterapeuta Veterinário', 'Os fisioterapeutas veterinários proporcionam tratamento terapêutico na sequência de um diagnóstico ou de uma sinalização veterinária. Concentram-se na aplicação de procedimentos de terapia física e exercício para apoiar a reabilitação dos animais após uma cirurgia ou uma lesão, com o objetivo de devolver aos animais uma função normal e/ou manter o seu desempenho em conformidade com a legislação nacional.', 'released', '["Fisioterapeuta de Animais", "Fisioterapeuta Veterinário", "Fisioterapeuta Animal", "Fisioterapeuta Veterinária", "Fisioterapeuta de Veterinária"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/5bf823c5-d3fd-46f6-9577-9331de10759f', 'Operador de Máquinas de Corte de Borracha', 'Os operadores de máquinas de corte de borracha operam a máquina que corta o material de borracha em placas. Retiram a placa do transportador e colocam-na numa palete, pulverizando uma solução química em cada placa para impedir que colem.', 'released', '["Operador de Máquinas de Corte de Borracha", "Operadora de Máquinas de Corte de Borracha"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/5c082067-ea18-4ccb-8c43-e70b18ad8120', 'Operador de Máquina de Controle Numérico Digital', 'Os operadores de máquina de controlo numérico digital procedem à instalação, manutenção e controlo de máquinas de controlo numérico digital para executar as encomendas de produtos. São responsáveis pela programação das máquinas, assegurando o cumprimento dos parâmetros e das medições requeridos e respeitando as normas de qualidade e segurança.', 'released', '["Operadora de Máquina de Controle Numérico Digital", "Operador de Máquina de Controle Numérico Digital"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/5c14982e-375d-47c5-9ea1-e9bcf3884643', 'Supervisor de Mineração', 'Os supervisores de mineração coordenam e supervisionam as atividades relacionadas com as indústrias extrativas em minas e pedreiras subterrâneas e de superfície. Supervisionam os trabalhadores, os horários, os processos e a organização das minas e das pedreiras.', 'released', '["Supervisora de Mineração", "Supervisor de Mineração"]'::jsonb, '3121'),
  ('http://data.europa.eu/esco/occupation/5c1eba1e-7820-4287-9746-4c5906320100', 'Assistente de Apoio às Vendas', 'Os assistentes de apoio às vendas executam uma série de tarefas gerais de apoio às vendas, tais como o apoio ao desenvolvimento de planos de vendas, a gestão de atividades administrativas de esforços de venda, a verificação das faturas dos clientes e de outros documentos ou registos contabilísticos, a compilação de dados e a elaboração de relatórios para outros departamentos da empresa.', 'released', '["Sales", "Assistentea de Apoio às Vendas"]'::jsonb, '4311'),
  ('http://data.europa.eu/esco/occupation/5c4ba833-da16-4bd0-a4b2-c08a2eaf5884', 'Operador de Fornos de Produtos Cerâmicos', 'Os operadores de fornos de produtos cerâmicos operam fornos a fim de cozer decorações ou vitrificados. Determinam o nível e a uniformidade da temperatura do forno, regulam a temperatura e dão instruções a um ajudante na preparação das fornalhas e para acender o lume.', 'released', '["Operador de Fornos de Produtos Cerâmicos", "Operadora de Fornos de Produtos Cerâmicos"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/5c5b153e-4bf8-4f3d-973d-12fabf306d12', 'Secretário-Geral', 'Os secretários-gerais chefiam organizações governamentais ou não governamentais internacionais. Supervisionam o pessoal, dirigem as políticas e o desenvolvimento estratégico, e funcionam como o principal representante da organização.', 'released', '["Secretária-Geral", "Presidente Executivo", "Secretário-Geral", "Diretor-Geral Executivo", "Diretora-Geral Executiva", "Diretora Executiva", "Diretor Executivo", "Presidente Executiva"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/5c9dea76-c7da-4e58-857c-fc3cbe7b960a', 'Gestor de Oficina Automóvel', 'Os gestores de oficina automóvel supervisionam o trabalho dos mecânicos de veículos rodoviários e do pessoal administrativo. Organizam o trabalho diário e lidam com os clientes.', 'released', '["Gestora de Oficina Automóvel", "Gestor de Oficina Automóvel", "Gerente"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/5cc6d160-3864-43b0-b3eb-77d1208a51b4', 'Diretor de Importação e Exportação de Metais e Minérios Metálicos', 'O diretores de importação e exportação de metais e minérios metálicos implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação de Metais e Minérios Metálicos", "Diretora de Importação e Exportação de Metais e Minérios Metálicos", "Diretor de Vendas de Metais e Minérios Metálicos", "Diretora de Vendas de Metais e Minérios Metálicos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/5ccb2c34-e860-43a5-9869-342487518115', 'Responsável Pelo Apoio a Projetos', 'Os responsáveis pelo apoio a projetos prestam diferentes tipos de serviços com vista à boa execução de um projeto no âmbito de um gabinete horizontal de gestão de projetos. Prestam apoio administrativo, assistência e formação aos gestores de projeto e a outros membros do pessoal, gerem a documentação do projeto e prestam assistência ao gestor do projeto na programação dos projetos, no planejamento dos recursos, na coordenação e na comunicação de informações. Os responsáveis pelo apoio a projetos têm a seu cargo atividades de garantia da qualidade e velam pelo cumprimento de orientações metodológicas e outras normas organizativas. Prestam igualmente aconselhamento sobre ferramentas de gestão de projetos e serviços administrativos conexos.;', 'released', '["PMO", "Oficial de Controle de Projeto", "Oficial de Entrega de Projeto", "Oficial de Gerenciamento de Projeto"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/5cff1eee-9027-4064-8a26-35b1877e4eb3', 'Gestor de Habitação Social', 'Os gestores de habitação social desenvolvem estratégias com vista à melhoria da política de habitação numa comunidade e à oferta de habitação social às pessoas necessitadas. Identificam necessidades e problemas em matéria de habitação e supervisionam a afetação de recursos. Comunicam igualmente com as organizações envolvidas na construção de instalações públicas de habitação e com as organizações de serviços sociais.', 'released', '["Analista de Habitação", "Gestor de Habitação Social", "Gestora de Habitação Social", "Gerente"]'::jsonb, '1344'),
  ('http://data.europa.eu/esco/occupation/5d009d45-3bb9-4e33-8760-294f59adec8c', 'Eletromecânico', 'Os eletromecânicos procedem à instalação, reparação e manutenção dos componentes mecânicos e elétricos de máquinas, ferramentas e equipamento. Testam as peças elétricas para garantir a eficiência e a introduzem melhorias em conformidade.', 'released', '["Eletromecânica", "Eletromecânico"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/5d0cc30d-068a-424c-8463-f42872a7149e', 'Consultor de Carreiras Profissionais', 'Os consultores de carreiras profissionais prestam orientação e aconselhamento a adultos e a estudantes em matéria de escolhas educativas, formativas e profissionais, e prestam assistência aos indivíduos na gestão das suas carreiras, através do planejamento e da exploração de carreiras. Ajudam a identificar opções para carreiras futuras, auxiliam os beneficiários a elaborar o seu currículo e ajudam as pessoas a refletir sobre as suas ambições, interesses e qualificações. Os consultores de carreiras profissionais podem prestar aconselhamento sobre várias questões relacionadas com o planejamento de carreiras e, se necessário, fazer sugestões para a aprendizagem ao longo da vida, incluindo recomendações de estudos a prosseguir. Podem também auxiliar as pessoas na procura de emprego ou prestar orientação e aconselhamento na preparação de um candidato para o reconhecimento de aprendizagens anteriores.;', 'released', '["Orientadora Vocacional", "Consultora em Orientação Profissional", "Consultora de Carreiras Profissionais", "Orientadora Profissional", "Orientador Vocacional", "Consultor de Carreiras Profissionais", "Consultor em Orientação Profissional", "Orientador Profissional"]'::jsonb, '2423'),
  ('http://data.europa.eu/esco/occupation/5d0e1510-7248-4eca-abe4-13de830d1614', 'Supervisor de Máquinas de Tecelagem', 'Os supervisores de máquinas de tecelagem acompanham o processo de tecelagem. Operam o processo de tecelagem em máquinas automáticas (de seda a tapetes, de tecidos planos a Jacquard). Controlam a qualidade dos tecidos e o estado das máquinas mecânicas, tais como tecidos para vestuário, têxteis do lar ou usos técnicos finais. Realizam trabalhos de manutenção em máquinas que convertem fios em tecidos, tais como cobertores, tapetes, toalhas e material de vestuário. Reparam as avarias em teares, comunicadas pelos tecelões, e preenchem as fichas de controlo dos teares.', 'released', '["Supervisor de Máquinas de Tecelagem", "Supervisora de Máquinas de Tecelagem"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/5d46e448-b6bb-48e5-b245-5aad68e06085', 'Operador de Queimador de Oxigénio-Fuel', 'Os operadores de queimador de oxigénio-fuel instalam e cuidam das máquinas concebidas para cortar, ou antes queimar, o material em excesso da peça metálica, utilizando uma tocha que aquece a peça metálica até à sua temperatura de autoinflamação e, em seguida, arde num óxido metálico mediante a sua reação com um fluxo de oxigénio emitido, que flui do corte criado na peça metálica como escória.', 'released', '["Operadora de Queimador de Oxigénio-Fúel", "Operador de Queimador de Oxigénio-Fúel", "Operadora de Queimador de Oxigénio-Fuel"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/5d4e374f-adfa-48bc-ba34-e51915484251', 'Motorista de Reboques', 'Os motoristas de reboques usam um reboque para transportar veículos danificados, avariados, novos ou imobilizados pelas autoridades públicas. Oferecem uma série de serviços, como o reboque de emergência na estrada ou a remoção de viaturas para o depósito da autoridade competente. Os motoristas de reboques operam o equipamento de reboque, organizam os itinerários e garantem a segurança durante todo o processo de transporte.', 'released', NULL, '8332'),
  ('http://data.europa.eu/esco/occupation/5d549551-d94a-4e98-8444-d6608d70c8d8', 'Supervisor de Perfuração', 'Os supervisores de perfuração assumem a responsabilidade pelas operações de perfuração diárias. Realizam sobretudo trabalho administrativo. Os supervisores de perfuração asseguram que a plataforma petrolífera possui materiais suficientes, peças sobressalentes e pessoal suficiente para prosseguir as operações diárias. Realizam atividades de perfuração em conformidade com o programa previsto, supervisionando a equipe de perfuração e o equipamento.', 'released', '["Supervisora de Perfuração", "Supervisor de Perfuração"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/5d5fde2c-47ce-4dcd-99f0-ba651b7b908f', 'Transcricionista Médico', 'Os transcricionistas médicos interpretam as informações ditadas pelo médico ou por outros profissionais de saúde e convertem-nas em documentos. Criam, formatam e editam registos médicos para os doentes com base nos dados fornecidos e têm o cuidado de aplicar regras de pontuação e gramaticais.', 'released', '["Transcricionista Médico", "Transcricionista Médica"]'::jsonb, '3344'),
  ('http://data.europa.eu/esco/occupation/5d601b40-7e0e-404e-bbff-bb98e147437c', 'Especialista em Assuntos Jurídicos', 'Os especialistas em assuntos jurídicos investigam, analisam e desenvolvem políticas relacionadas com o setor jurídico e aplicam estas políticas a fim de melhorarem a regulamentação existente neste setor. Trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/5d758e75-a116-485a-b800-5db08ffd3ba1', 'Conselheiro em Abuso de Drogas e Álcool', 'Os conselheiros em abuso de drogas e álcool prestam assistência e aconselhamento aos indivíduos com problemas de dependência de drogas e de álcool e às suas famílias, acompanhando os seus progressos, defendendo-os, realizando intervenções em situações de crise e recorrendo à terapia de grupo. Além disso, prestam auxílio relativo às consequências das dependências, que podem incluir o desemprego, os distúrbios físicos ou mentais e a pobreza. Os conselheiros em abuso de drogas e álcool podem também preparar programas educativos para as populações de alto risco.', 'released', '["Conselheira de Vícios", "Conselheira em Abuso de Drogas e Álcool", "Conselheiro de Vícios", "Conselheiro em Abuso de Drogas e Álcool"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/5d9e63a2-8013-434e-9f92-3b3d54a0c320', 'Forneiro de Panificação', 'Os forneiros de panificação asseguram o correto funcionamento de fornos de bobinas automáticas ou do tipo transportador para o fabrico de pão, produtos de pastelaria e outros produtos de panificação. Interpretam as ordens de trabalho para determinar os produtos e as quantidades a fabricar. Regulam a velocidade operacional dos transportadores, os tempos de cozedura e as temperaturas. Supervisionam o processo de cozedura e mantêm as operações do forno sob controlo.', 'released', '["Forneiro de Panificação", "Operador de Forno de Panificação", "Forneira de Panificação", "Operadora de Forno de Panificação"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/5dbb9cf0-b226-402c-a295-2f42ef05ff8b', 'Eletricista Doméstico', 'Os eletricistas domésticos procedem à instalação e manutenção de infraestruturas elétricas e máquinas domésticas em casas e outros edifícios residenciais. Realizam inspeções e reparam peças com defeito, a fim de garantir a eficiência.', 'released', '["Eletricista Doméstica", "Eletricista Doméstico"]'::jsonb, '7411'),
  ('http://data.europa.eu/esco/occupation/5dd01019-3999-4d90-bc8a-7a04b0b208b0', 'Estilista de Maquiagem e Penteados', 'Os estilistas de maquilhagem e penteados desenvolvem um conceito de concepção para a maquilhagem e penteados e supervisionam a sua execução. O seu trabalho baseia-se na investigação e na visão artística. O seu desenho é influenciado por, e influencia, outros desenhos e deve estar em conformidade com estes desenhos e com a visão artística global. Por conseguinte, os designers trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Os estilistas de maquilhagem e penteados elaboram esboços, desenhos de projeto ou outra documentação para apoiar a oficina e a equipe de espetáculo. Por vezes, os estilistas de maquilhagem também trabalham como artistas independentes, criando maquilhagem fora de um contexto de espetáculo. ;', 'released', NULL, '5142'),
  ('http://data.europa.eu/esco/occupation/5df63943-f1bc-4438-90f1-92768a7a23c8', 'Eletricista Industrial', 'Os eletricistas industriais procedem à instalação e manutenção de cabos elétricos e outras infraestruturas elétricas em grandes edifícios industriais e comerciais. Realizam inspeções e reparam peças com defeito de sistemas elétricos para garantir a eficiência.', 'released', NULL, '7411'),
  ('http://data.europa.eu/esco/occupation/5e175ee2-6b07-4f1d-8f5e-962c36ab7bb6', 'Oficial de Justiça', 'Os oficiais de justiça mantêm a ordem e a segurança nas salas de audiência. Transportam os infratores de e para a sala de audiências, asseguram que os abastecimentos necessários estão presentes na sala de audiência e investigam as instalações e examinam as pessoas para garantir que não existem ameaças. Abrem e fecham o tribunal e chamam as testemunhas.', 'released', NULL, '3411'),
  ('http://data.europa.eu/esco/occupation/5e29c263-a3ca-4220-b67e-ee65205db294', 'Fabricante e Reparador de Brinquedos', 'Os fabricantes e reparadores de brinquedos criam ou reproduzem objetos feitos à mão para venda e exposição a partir de vários materiais, tais como o plástico, madeira e têxteis. Desenvolvem, concebem e esboçam o objeto, selecionam os materiais e cortam, moldam e processam os materiais, conforme necessário, e aplicam acabamentos. Os fabricantes e reparadores de brinquedos também procedem à manutenção e reparação de todos os tipos de brinquedos, incluindo brinquedos mecânicos. Identificam defeitos nos brinquedos, substituem as peças danificadas e restauram a sua funcionalidade.', 'released', '["Fabricante e Reparadora de Brinquedos", "Fabricante e Reparador de Brinquedos", "Fabricantea e Reparador de Brinquedos"]'::jsonb, '7317'),
  ('http://data.europa.eu/esco/occupation/5e4d156a-1f05-4b2c-b0f0-5abb82d52ed6', 'Gestor de Conta', 'Os gestores de conta aconselham potenciais clientes sobre o tipo de contas bancárias adequadas às suas necessidades. Trabalham com os clientes na preparação da conta bancária e continuam a ser o seu principal contato no banco, prestando assistência com toda a documentação necessária. Os gestores de conta podem recomendar aos seus clientes o contato com outros departamentos do banco para outras necessidades específicas.', 'released', '["Gestor de Conta", "Gestora de Conta", "Gerente"]'::jsonb, '3312'),
  ('http://data.europa.eu/esco/occupation/5e5522c5-4b09-4586-a8f0-3b6d66d99969', 'Operador de Descascadores de Madeira', 'Os operadores de descascadores de madeira operam máquinas para descascar a casca das árvores colhidas. A árvore é introduzida na máquina e, em seguida, a casca é removida por abrasão ou por corte.', 'released', '["Operadora de Descacadores de Madeira", "Operador de Descacadores de Madeira", "Operadora de Descascadores de Madeira"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/5e5b1b61-1351-4d3b-a293-deb3661715dd', 'Controlador Financeiro', 'Os controladores financeiros tratam de todas as tarefas relacionadas com os aspetos orçamentais e contabilísticos de uma empresa ou organização. Aplicam e asseguram o cumprimento dos procedimentos financeiros e contabilísticos internos e preparam documentação para as auditorias externas. Recolhem informações relacionadas com demonstrações financeiras como ativos, passivos, capital próprio e fluxo de caixa, a fim de avaliar a posição financeira da empresa para preparar orçamentos anuais e previsões.', 'released', '["Controlador Financeiro", "Controladora Financeira", "Controladora Financeiro"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/5e748def-5b90-41e2-aa8b-2ebcc7d25ab0', 'Montador de Estruturas em Embarcações', 'Os montadores de estruturas em embarcações trabalham principalmente no fabrico, na submontagem, na montagem e na montagem final de todos os elementos estruturais em embarcações comerciais e navais, incluindo, entre outros, cascos, superstruturas, mastros, casas do leme e casas das máquinas.;', 'released', '["Instalador de Navio", "Montadora Naval", "Instaladora de Navio", "Montador Naval", "Instalador Marítimo", "Instaladora Marítima", "Despachante", "Montadora de Estruturas em Embarcações"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/5ed024ab-3b6a-4e06-a7fe-8a29f8469a64', 'Técnico de Caldeiras', 'Os técnicos de caldeiras operam uma série de equipamentos e de máquinas para criar e instalar novas condutas e tubagens em caldeiras de água quente e caldeiras a vapor, produzindo-as em todas as fases do processo de produção. Cortam, formam e moldam as chapas metálicas e os tubos à medida para as caldeiras, utilizando maçaricos oxiacetilénicos, montam-nas por meio de soldadura por arco com proteção, soldadura por arco elétrico ou soldadura em atmosfera inerte com elétrodo de tungsténio, e procedem ao acabamento com máquinas-ferramentas, ferramentas elétricas e revestimento apropriados.', 'released', '["Técnica de Caldeiras", "Técnico de Caldeiras"]'::jsonb, '7213'),
  ('http://data.europa.eu/esco/occupation/5ee264b2-9bc5-40f6-9db3-c87143af6b2d', 'Flebotomista', 'Os flebotomistas colhem amostras de sangue dos doentes para análise laboratorial, garantindo a segurança dos doentes durante o processo de colheita de sangue. Transportam a amostra para o laboratório, seguindo instruções rigorosas do médico.', 'released', NULL, '5329'),
  ('http://data.europa.eu/esco/occupation/5efb2c08-ba3a-4659-a2e4-1883f54e77b6', 'Professor do Ensino Secundário', 'Os professores do ensino secundário asseguram o ensino dos alunos, crianças e jovens adultos, num estabelecimento de ensino secundário. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos através da atribuição de trabalhos, testes e exames.', 'released', '["Professora do Ensino Secundário", "Professor do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/5efb4fff-8c5f-4697-9587-034d9f6af094', 'Técnico de Radiologia em Medicina Nuclear', 'Os técnicos de radiologia em medicina nuclear planificam, preparam e realizam exames de medicina nuclear, pós-processamento e tratamento com uma vasta gama de equipamentos e técnicas utilizando radiografias, imagiologia por ressonância magnética e medicamentos radiofarmacêuticos.', 'released', '["Técnica de Radiologia em Medicina Nuclear", "Técnico de Radiologia em Medicina Nuclear"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/5f16819d-50b9-475b-a2d8-607ee6d99a9d', 'Agente Aduaneiro', 'Os agentes aduaneiros combatem a importação de mercadorias ilegais, armas de fogo, drogas ou outros artigos perigosos ou ilegais, verificando a legalidade dos bens trazidos através das fronteiras nacionais. São funcionários governamentais que controlam os documentos para assegurar o cumprimento dos critérios de entrada e da legislação aduaneira e controlam se os impostos aduaneiros são pagos corretamente.', 'released', '["Agente Aduaneiro", "Agente Aduaneira", "Agentea Aduaneiro"]'::jsonb, '3351'),
  ('http://data.europa.eu/esco/occupation/5f45a1ea-4d1b-43c3-b6a8-53b2276b3eb3', 'Genealogista', 'Os genealogistas traçam a história e as linhagens das famílias. Os resultados do seu trabalho são apresentados num esquema designado árvore genealógica, onde os indivíduos surgem por ordem de descendência, ou sob a forma de narrativas escritas. Os genealogistas recorrem à análise de registos públicos, a entrevistas informais, a análises genéticas e a outros métodos para obterem informações.', 'released', NULL, '2633'),
  ('http://data.europa.eu/esco/occupation/5f50290d-f520-4a69-85c7-1390d2a4a8b6', 'Testador de Usabilidade Informática', 'Os testadores de usabilidade informática asseguram o cumprimento dos requisitos e procuram otimizar a usabilidade nas fases de ciclo de engenharia do «software» (análise, concepção, implementação e instalação). Trabalham também em estreita colaboração com os usuários (analistas) nos domínios da investigação e da documentação de perfis de usuários, análise de tarefas, fluxos de trabalho e cenários de utilização.', 'released', '["Responsável Pelos Testes de Usabilidade", "Responsável por Testes de Usabilidade", "Testador de Usabilidade", "Testadora de Usabilidade", "Testadora de Usabilidade Informática"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/5f617498-da0d-454a-9658-5e02d28a4bd7', 'Moldador de Porcelana e Cerâmica', 'Os moldadores de porcelana e cerâmica enchem moldes com argila, a fim de moldar artigos de porcelana e cerâmica. Quando necessário, vertem o excesso para fora dos moldes, drenam os moldes, retiram a peça do molde, alisam as superfícies para remover marcas e colocam as peças em tábuas a secar.', 'released', '["Moldador de Porcelana e Cerâmica", "Moldadora de Porcelana e Cerâmica"]'::jsonb, '7314'),
  ('http://data.europa.eu/esco/occupation/5f68c4c3-9d25-48e2-8efc-5471a80fb155', 'Trabalhador de Construção de Estradas', 'Os trabalhadores de construção de estradas realizam trabalhos de construção de estradas em terraplenagens, subestruturas e secção do pavimento da estrada. Cobrem o solo compactado com uma ou mais camadas. Normalmente, os trabalhadores de construção de estradas colocam primeiro um leito estabilizador de areia ou de argila, antes de adicionar o asfalto ou chapas de betão, a fim de terminar uma estrada.', 'released', '["Trabalhador de Construção de Estradas", "Trabalhadora de Construção de Estradas"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/5f770d3d-5c42-4c22-bc06-23bebd182a37', 'Gerente de Loja de Animais', 'Os gerentes de loja de animais assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Artigos para Animais", "Gerente de Loja de Alimentos para Animais", "Gerentea de Loja de Animais"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/5f84de7d-5008-45c4-a993-8066388e0756', 'Trabalhador da Separação de Folhas', 'Os trabalhadores de folhas analisam a cor e o estado das folhas de tabaco, a fim de determinar se devem ser utilizados como capas ou subcapas para charutos. Selecionam folhas sem defeitos visíveis, tendo em conta as variações de cor, cortes, as manchas de alcatrão, o grão apertado e as dimensões, de acordo com as especificações. Dobram folhas de capa em molhos para separar do talo.', 'released', '["Trabalhadora da Separação de Folhas de Tabaco", "Técnico de Separação de Folhas de Tabaco", "Trabalhador da Separação de Folhas de Tabaco", "Técnica de Separação de Folhas de Tabaco", "Trabalhadora da Separação de Folhas"]'::jsonb, '7516'),
  ('http://data.europa.eu/esco/occupation/5f9e0588-e819-42f7-9975-f53198666c07', 'Instalador de Vidros', 'Os instaladores de vidros colocam chapas de vidro em janelas e outros elementos estruturais, tais como portas, paredes, fachadas e outras estruturas.', 'released', '["Instalador de Vidros", "Vidraceira", "Vidraceiro", "Instaladora de Vidros"]'::jsonb, '7125'),
  ('http://data.europa.eu/esco/occupation/5fd099da-218a-460e-bd5b-b42f1b76c67c', 'Farmacêutico Hospitalar', 'Os farmacêuticos hospitalares preparam, dispensam e fornecem medicamentos a doentes nos hospitais. Colaboram com o pessoal dos cuidados de saúde, como médicos e enfermeiros, para tratar os doentes e prestar aconselhamento e informações sobre medicamentos.', 'released', '["Farmacêutico Hospitalar", "Farmacêutica Hospitalar"]'::jsonb, '2262'),
  ('http://data.europa.eu/esco/occupation/5fd2980e-22c4-4ace-a394-190c76f4f539', 'Gestor de Documentação de Tecnologia da Informação', 'Os gestores de documentação TIC são responsáveis pela gestão do processo de desenvolvimento de documentação, em conformidade com os requisitos legais, as normas, as políticas e os objetivos organizacionais. Definem, controlam e orientam os recursos, as pessoas, o financiamento e as instalações do serviço de documentação (incluindo a fixação de orçamentos e calendários, a análise de risco e a gestão da qualidade). Além disso, desenvolvem normas de documentação, métodos de estruturação e ideias de comunicação para comunicar eficazmente os conceitos e a utilização dos produtos.', 'released', '["Gestor de Comunicação Técnica", "Gestora de Comunicação Técnica", "Gestor de Documentação TI", "Gestora de Documentação Informática", "Gestor de Documentação Informática", "Gestora de Documentação TI", "TI", "Gerente", "Gestora de Documentação de Tecnologia da Informação"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/5fd69ee2-2042-4280-85e1-8f1462886987', 'Engenheiro Especialista em Planejamento e Otimização de Operações Mineiras', 'Os engenheiros especialistas em planificação e otimização de operações mineiras concebem e coordenam operações de desenvolvimento de minas, tais como o corte transversal, a abertura de túneis, a perfuração de túneis, operações em filões, a elevação, e a remoção e substituição das terras de cobertura.', 'released', '["Engenheira Especialista em Planificação e Otimização de Operações Mineiras", "Engenheiro Especialista em Planificação e Otimização de Operações Mineiras", "Engenheira Especialista em Planejamento e Otimização de Operações Mineiras"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/5fdfa822-c1ba-477e-87cc-3d742e59310d', 'Professor de Biologia', 'Os professores de Biologia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Biologia, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da Biologia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor Universitário de Biologia", "Professora de Biologia", "Professora Universitária de Biologia", "Professor de Biologia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/5fe1b340-9b02-4c40-bbc9-ffd4d5fb5699', 'Especialista em Política Cultural', 'Os especialistas em política cultural desenvolvem e aplicam políticas para melhorar e promover atividades e eventos culturais. Gerem recursos e comunicam com o público e com os meios de comunicação social, com o intuito de promover o interesse pelos programas culturais e de destacar a sua importância numa comunidade.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/5ff100c2-00cd-4c64-82ae-8feab6712557', 'Distribuidor de Panfletos', 'Os distribuidores de panfletos entregam prospetos, folhetos e anúncios publicitários destinados a informar as pessoas ou a vender produtos e serviços. Distribuem estes folhetos diretamente às pessoas nas ruas ou através das caixas de correio.', 'released', '["Distribuidora de Panfletos", "Distribuidor de Panfletos"]'::jsonb, '9510'),
  ('http://data.europa.eu/esco/occupation/5ff7a990-a306-40c2-9224-b2bf7f15b2f9', 'Produtor Musical', 'Os produtores musicais são responsáveis pela aquisição de música com o objetivo de ser editada. Escutam versões de demonstração de canções e determinam se são suficientemente boas para serem editadas. Os produtores de música supervisionam a produção das gravações. Gerem os aspetos técnicos da gravação e da edição.', 'released', '["Produtor Musical", "Produtora Musical"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/60082a99-d8ef-4e84-9290-78902681b6ed', 'Analista de Organização e Métodos', 'Os analistas de organização e métodos estudam e compreendem a posição estratégica de negócios e de empresas relativamente aos seus mercados e às suas partes interessadas. Analisam e apresentam os seus pareceres sobre a forma como a empresa pode melhorar, numa variedade de perspetivas, a sua posição estratégica e a sua estrutura empresarial interna. Avaliam as necessidades de mudança, os métodos de comunicação, as tecnologias, as ferramentas informáticas, novas normas e certificações.', 'released', NULL, '2421'),
  ('http://data.europa.eu/esco/occupation/601db24d-cc02-48f3-9939-8c8b41b34ef7', 'Representante de Serviço de Aluguel de Equipamento para Transportes Aéreos', 'Os representantes de serviço de aluguer de equipamento para transportes aéreos são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Equipamento para Transportes Aéreos"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/6040c941-ab83-44b2-84e7-5cbfa1eafcdc', 'Técnico de Obras de Arte', 'Os técnicos de obras de arte são indivíduos formados que trabalham diretamente com objetos em museus e galerias de arte. Trabalham em coordenação com os agentes de registo de exposições, os curadores de coleções, os conservadores-restauradores e curadores, entre outros, a fim de garantir que os objetos são manipulados e tratados de forma segura. Muitas vezes, são responsáveis pela embalagem e desembalagem da arte, pela instalação e pela desinstalação de arte em exposições e pela mudança de arte no museu e nos espaços de armazenagem.', 'released', '["Técnica de Obras de Arte"]'::jsonb, '3433'),
  ('http://data.europa.eu/esco/occupation/60528794-1a68-4440-a141-2df011be98be', 'Gerente de Antiquário', 'Os gerentes de antiquário assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Vendedora de Antiguidades", "Antiquária", "Antiquário", "Vendedor de Antiguidades", "Gerente de Loja de Antiguidades", "Gerentea de Antiquário"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/605e58d6-ad27-4828-b1f5-16707f327fa0', 'Professor de Ciências da Educação', 'Os professores de Ciências da Educação são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências da Educação, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames na realização de sessões de revisão e de feedback para os alunos.', 'released', '["Professora Universitária de Ciências da Educação", "Professor Universitário de Ciências da Educação", "Professor de Ciências da Educação", "Professora de Ciências da Educação"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/6066ed14-ace3-4352-b656-2b621fd7bc88', 'Gestor de Espaço Cultural', 'Os gestores de espaço cultural dirigem as operações das instalações que prestam serviços culturais, tais como teatro, cinema e música. Planificam e organizam as operações diárias do respetivo pessoal e instalações e asseguram que a organização acompanha os últimos desenvolvimentos no seu domínio. Coordenam os diferentes departamentos do espaço e gerem a utilização correta dos recursos, das políticas e dos orçamentos.', 'released', '["Gestor de Espaço Cultural", "Gestora de Espaço Cultural", "Gerente"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/608edf30-fe37-4ae5-bdd1-2d3a8fd347bd', 'Engenheiro Especialista em Testes de Voo', 'Os engenheiros especialistas em testes de voo trabalham com outros engenheiros de sistemas para planear os testes em pormenor e assegurar que estão instalados sistemas de registo para os parâmetros de dados requeridos. Analisam os dados recolhidos durante os voos de teste e elaboram relatórios para cada uma das fases de teste e para o teste final de voo. São igualmente responsáveis pela segurança das operações de teste.', 'released', '["Engenheira Especialista em Testes de Voo", "Engenheiro Especialista em Testes de Voo"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/60b9b847-d964-4a8a-a756-904080b0f35f', 'Operador de Prensa de Estampar', 'Os operadores de prensa de estampar instalam e cuidam de prensas de estampar concebidas para moldar peças metálicas na forma desejada, exercendo pressão através do movimento ascendente e descendente de uma placa de apoio e de um molde ligados a um aríete de estampar no metal, resultando no molde que produz peças metálicas mais pequenas da peça alimentada à prensa.', 'released', '["Operadora de Prensa de Estampar", "Operador de Prensa de Estampar", "Operadora de Prensa para Estampar", "Operador de Prensa para Estampar"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/60bc7374-9fa1-4bbd-b936-2676fca0bfb6', 'Operador nos Mercados Financeiros', 'Os operadores nos mercados financeiros compram e vendem produtos financeiros, tais como ativos, ações e obrigações para clientes particulares, bancos ou empresas. Acompanham de perto os mercados financeiros e procuram maximizar os lucros e minimizar os riscos das suas transações.', 'released', '["Operadora nos Mercados Financeiros", "Operador nos Mercados Financeiros", "Trader nos Mercados Financeiros"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/60d77070-2cf4-4883-b44d-91e8ce54db86', 'Supervisor de Processos de Conservação de Recursos Hídricos', 'Os supervisores de processos de conservação de recursos hídricos supervisionam a instalação de sistemas de recuperação, filtração, armazenamento e distribuição de água a partir de diferentes fontes, como as águas pluviais e as águas cinzentas domésticas. Atribuem tarefas e tomam decisões rápidas.', 'released', '["Supervisora de Conservação de Recursos Hídricos", "Supervisor de Conservação de Recursos Hídricos", "Supervisora de Processos de Conservação de Recursos Hídricos"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/60f7eb23-a7ea-4cbe-98a5-1248291f62d5', 'Bibliotecário', 'Os bibliotecários gerem bibliotecas e prestam serviços relacionados com a biblioteca. Gerem, recolhem e desenvolvem recursos de informação. Disponibilizam informações, tornando-as acessíveis e facilitando a sua pesquisa a qualquer tipo de usuário.', 'released', '["Bibliotecário", "Bibliotecária"]'::jsonb, '2622'),
  ('http://data.europa.eu/esco/occupation/61053604-8091-4a8e-9c63-5151051722e3', 'Consultor na Área dos Cuidados de Saúde', 'Os consultores na área dos cuidados de saúde prestam aconselhamento a organizações de cuidados de saúde sobre o desenvolvimento de planos destinados a melhorar os cuidados prestados aos doentes e a aumentar a segurança dos doentes. Analisam as políticas de cuidados de saúde e identificam problemas, contribuindo para o desenvolvimento de estratégias de melhoria.', 'released', '["Consultor Ana Área dos Cuidados de Saúde", "Consultor na Área dos Cuidados de Saúde", "Consultora na Área dos Cuidados de Saúde"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/610bee9f-d7f0-4b18-918e-f2a4a91f8912', 'Perfurador de Pedra', 'Os perfuradores de pedra operam a perfuradora que realiza furos em blocos de pedra. Manipulam o granito, o grés, o mármore e a ardósia, de acordo com as especificações.', 'released', '["Operador de Broca Radial", "Operador de Broca Pneumática", "Perfuradora de Pedra", "Operadora de Broca Radial", "Operadora de Broca Pneumática", "Perfurador de Pedra"]'::jsonb, '8112'),
  ('http://data.europa.eu/esco/occupation/612430b3-dd43-4786-b823-0466c4953f66', 'Operador de Venda de Bilhetes', 'Os operadores de venda de bilhetes prestam serviços aos clientes, vendem bilhetes e adequam a oferta das reservas às necessidades dos clientes. Vendem bilhetes para todos os eventos, tais como atividades desportivas, culturais e de lazer. Fornecem aos clientes informações sobre as ofertas e procedem aos preparativos necessários.', 'released', '["Operadora de Venda de Bilhetes", "Operador de Venda de Bilhetes", "Bilheteiro", "Bilheteira"]'::jsonb, '5230'),
  ('http://data.europa.eu/esco/occupation/6140be85-2d45-44b2-b0ba-412aadcead1e', 'Geneticista', 'Os geneticistas estudam e centram a sua investigação na genética. Analisam a forma como os genes interagem, operam e herdam aspetos e características. Com base na sua investigação, prestam assistência a doentes com doenças e perturbações hereditárias, malformações congénitas e problemas genéticos em geral.', 'released', '["Geneticista Molecular", "Citologista", "Embriologista", "Embriólogo", "Embrióloga", "Geneticista Celular", "Biólogo Molecular", "Bióloga Molecular"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/615920c5-4f63-4eb3-8b60-afaaed3ab1ff', 'Engenheiro de Manutenção e Reparação', 'Os engenheiros de manutenção e reparação centram-se na otimização de equipamentos, procedimentos, máquinas e infraestruturas. Asseguram a sua disponibilidade máxima a custos mínimos.', 'released', '["Engenheiro de Manutenção e Reparação", "Engenheira de Manutenção e Reparação"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/61704d4b-f54b-43e5-a7de-bfd7a76f2f0d', 'Homeopata', 'Os homeopatas tratam os clientes com base na seleção e na prescrição de soluções homeopáticas que utilizam o princípio da homeopatia do «semelhante pelo semelhante se cura». ;', 'released', '["Especialista em Homoepatia"]'::jsonb, '2230'),
  ('http://data.europa.eu/esco/occupation/6175b828-026d-4fb4-8be7-418394e1add0', 'Impressor Digital', 'Os impressores digitais trabalham com máquinas que imprimem diretamente no material de suporte, sem a intervenção de uma placa. Os impressores digitais normalmente utilizam a tecnologia laser ou a jato de tinta para imprimir páginas individuais sem etapas técnicas demoradas ou trabalhosas entre o produto digital acabado e a impressão.', 'released', '["Impressora Digital", "Impressor Digital"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/6188bf20-5cdb-4702-af72-2cb67ec39810', 'Técnico de Carrosséis', 'Os técnicos de carrosséis procedem à manutenção e reparação das atrações em parques de diversões. Precisam de ter um bom conhecimento técnico e conhecimentos especializados dos carrosséis por cuja manutenção são responsáveis. Normalmente, os técnicos de carrosséis mantêm registos da manutenção e das reparações efetuadas, bem como dos períodos de serviço e de paragem de cada atração na qual se efetuou manutenção. A atenção à segurança é especialmente importante na manutenção e reparação dos carrosséis.', 'released', '["Técnico de Carrosséis", "Técnica de Carrosséis"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/618a854a-4ecd-4535-84e6-350e1fe0aa0f', 'Joalheiro', 'Os joalheiros fabricam e reparam artigos de joalharia. Criam modelos a partir de cera ou metal, prontos para o processo de fundição por cera perdida. Podem empreender o processo de fundição (colocar o modelo de cera no anel de fundição, criar moldes, verter metal derretido no molde, ou operar a máquina de fundição centrífuga para fundir o artigo). Os joalheiros também cortam, serram, limam e soldam peças de joalharia, utilizando um maçarico para soldadura, ferramentas de entalhar e manuais, e pulem o artigo.', 'released', '["Joalheira", "Joalheiro"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/61a61a3b-6fcd-4525-9f5c-0a1415a9a51f', 'Diretor de Distribuição de Produtos do Tabaco', 'Os diretores de distribuição de produtos do tabaco planificam a distribuição de produtos do tabaco a vários pontos de venda.', 'released', '["Diretor de Logística Produtos do Tabaco", "Diretor de Distribuição Produtos do Tabaco", "Diretora de Distribuição Produtos do Tabaco", "Diretora de Logística Produtos do Tabaco", "Diretora de Distribuição de Produtos do Tabaco"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/61b859ed-24d8-48cf-9c1b-67d7a6c62bb5', 'Especialista em Import-Export', 'Os especialistas em import-export possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação. Declaram as mercadorias que atravessam a fronteira, informam os clientes sobre formalidades alfandegárias e prestam aconselhamento sobre litígios relacionados com a legislação aduaneira. Elaboram os documentos necessários e asseguram a sua entrega aos serviços aduaneiros. Verificam e processam os direitos aduaneiros e certificam-se de que os pagamentos de IVA são efetuados nos casos aplicáveis.', 'released', '["Especialista em Import-Export"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/61d9270c-491d-438d-8d41-77ba2e0ef023', 'Inspetor de Qualidade de Produtos', 'Os inspetores de qualidade de produtos verificam os produtos, a fim de avaliar a sua conformidade com uma norma ou diretriz de referência. Observam, medem, testam e formulam perguntas a fim de preencher os formulários e apresentam níveis de conformidade com observações após o processo de inspeção. Os inspetores de qualidade do produto são empregados ou trabalham externamente para empresas.', 'released', '["Inspetor de Qualidade de Produtos", "Inspetora de Qualidade de Produtos"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/61e278a3-2c27-4c18-a827-11e2326b33ae', 'Artista de Rua', 'Os artistas de rua criam espetáculos artísticos de rua para espaços ao ar livre, utilizando o espaço e o público como recurso criativo. A sua atuação é criada através de uma exploração e experimentação lúdicas com o objetivo de entretenimento e, eventualmente, de partilha de opiniões críticas sobre assuntos da sociedade. Estimulam a participação do público como componente da sua atuação, respeitando simultaneamente a segurança e a integridade do público.', 'released', NULL, '2659'),
  ('http://data.europa.eu/esco/occupation/61ed67cd-67d7-44d8-bc2d-47fc79110a59', 'Responsável Serviço de Táxis', 'Os responsáveis pelo serviço de táxis procedem a reservas e ao envio de veículos, e são responsáveis pela coordenação dos motoristas, mantendo a ligação com os clientes.', 'released', NULL, '4323'),
  ('http://data.europa.eu/esco/occupation/62001bb7-4611-4b61-903e-d98589c0821a', 'Diretor de Desenvolvimento de Jogos', 'Os diretores de desenvolvimento de jogos supervisionam e coordenam a criação, o desenvolvimento, a distribuição e a venda de jogos. Comunicam com os fabricantes para garantir a produção de jogos.', 'released', '["Diretor de Desenvolvimento de Jogos", "Diretor de Desenvolvimento de Jogos de Fortuna ou Azar", "Diretora de Desenvolvimento de Jogos", "Diretora de Desenvolvimento de Jogos de Fortuna ou Azar"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/6219f0ef-6414-4d01-9221-41ac25dcb409', 'Codificador Clínico', 'Os codificadores clínicos leem os registos médicos dos doentes. Analisam e interpretam as declarações médicas sobre doenças, lesões e procedimentos. Os codificadores clínicos convertem estas informações em códigos de classificação de doenças, tendo em vista o cálculo de reembolsos de tratamentos, a produção de estatísticas e a monitorização do desempenho dos cuidados de saúde.', 'released', '["Codificador Clínico", "Codificadora Clínica", "Codificadora Clínico"]'::jsonb, '3252'),
  ('http://data.europa.eu/esco/occupation/621b7aa1-b678-49ee-8caa-91b496f8bc5b', 'Especialista em Import-Export de Mobiliário de Escritório', 'Os especialistas em import-export de mobiliário de escritório possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Mobiliário de Escritório"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/62204bd8-98b5-418f-b189-7333904cbde7', 'Chefe de Equipe de Cuidadores no Jardim Zoológico', 'Os chefes de equipe de cuidadores no jardim zoológico são responsáveis pela gestão e pela liderança de uma equipe de cuidadores no jardim zoológico. Realizam os cuidados diários e a gestão dos animais, bem como, em cooperação com os colegas, a gestão a longo prazo e a organização das espécies e das exposições na sua secção. Também são responsáveis por vários aspetos da gestão do pessoal dos cuidadores na sua secção. Em função da dimensão do zoo e da secção dos animais podem ter responsabilidades adicionais em matéria de nomeação de pessoal e de orçamentos.', 'released', '["Chefea de Equipe de Cuidadores no Jardim Zoológico"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/622b1d5e-bf14-4ec0-b83e-3bfcf8dff624', 'Operador de Perfuração', 'Os operadores de perfuração supervisionam uma equipe durante as operações de perfuração e extração. Controlam bem as atividades e tomam medidas em caso de emergência.', 'released', '["Operador de Perfuração", "Operadora de Perfuração"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/622ccd55-910f-483d-8661-44c6162156bf', 'Professor de Apoio Domiciliário a Crianças com Necessidades Educativas Especiais', 'Os professores de apoio domiciliário a crianças com necessidades educativas especiais ensinam as crianças deficientes ou doentes nas suas casas. São professores especializados ao serviço das escolas (públicas) que ensinam crianças incapazes de frequentar fisicamente a escola, mas também ajudam os alunos, os pais e a escola na sua comunicação. Além disso, desempenham as funções de assistente social escolar, ajudando os alunos e os pais nos seus eventuais problemas comportamentais e aplicando, se necessário, os regulamentos de frequência escolar. No caso de uma eventual (re)admissão à escola, os professores aconselham a escola relativamente a estratégias adequadas de orientação em sala de aula e métodos de ensino adequados para apoiar o estudante e tornar a sua transição o mais agradável possível.', 'released', '["Professora de Apoio Domiciliário a Crianças com Necessidades Educativas Especiais", "Professora de Apoio Domiciliário a Crianças com NEE", "Professor de Apoio Domiciliário a Crianças com NEE", "Professor de Apoio Domiciliário a Crianças com Necessidades Educativas Especiais"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/623958d6-775c-4586-b928-86582d9d1b69', 'Planejador de Produção Alimentar', 'Os planificadores de produção alimentar elaboram planos de produção, avaliam todas as variáveis do processo e procuram assegurar que os objetivos de produção são alcançados.', 'released', '["Técnico de Planejamento da Produção Alimentar", "Planificadora de Produção Alimentar", "Técnica de Planejamento da Produção Alimentar", "Planificador de Produção Alimentar", "Planejadora de Produção Alimentar"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/624986f9-21ef-4cdf-8cf6-8407a337ec2f', 'Técnico de Levantamentos Topográficos', 'Os técnicos de levantamentos topográficos levam a cabo tarefas técnicas de geodesia. Prestam assistência a agrimensores, arquitetos ou engenheiros na realização de tarefas técnicas relacionadas com geodesia, como o mapeamento de terrenos, a criação de desenhos de construção e a utilização de equipamentos de medição precisos.', 'released', '["Técnico em Mapeamento", "Técnico de Levantamentos Topográficos", "Técnica de Levantamentos Topográficos", "Técnica em Mapeamento"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/625d316c-2b93-4a9c-ada2-b19efa7c611b', 'Diretor de Distribuição — Vestuário e Calçado', 'Os gestores da distribuição de vestuário e calçado planificam a distribuição de vestuário e calçado a vários pontos de venda.', 'released', '["Diretora de Distribuição — Vestuário e Calçado", "Diretor de Logística — Vestuário e Calçado", "Diretora de Logística — Vestuário e Calçado", "Diretor de Distribuição — Vestuário e Calçado"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/6293a718-3fcd-433f-a010-0899821a51b7', 'Inspetor de Pontes', 'Os inspetores de pontes efetuam inspeções nas estruturas de pontes a fim de detetarem ruturas em juntas, fissuras, ferrugem e outras anomalias. Além disso, realizam ou organizam a manutenção das estruturas.', 'released', '["Inspetora de Pontes", "Inspetor de Pontes"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/6296faea-1909-4943-b0e0-662b43ad855d', 'Agente de Imigração', 'Os agentes de imigração controlam a elegibilidade das pessoas, dos alimentos, dos dispositivos eletrônicos e das mercadorias que entram num país através de um ponto de entrada. Utilizam métodos de vigilância e verificam a identificação e os documentos para assegurar o cumprimento dos critérios de entrada e da legislação aduaneira. Podem também realizar entrevistas com potenciais imigrantes para verificar a elegibilidade e inspecionar a carga para identificar e detectar violações.', 'released', '["Agentea de Imigração"]'::jsonb, '3351'),
  ('http://data.europa.eu/esco/occupation/62975936-0853-4a5d-9f59-bf943aca3cc6', 'Instrutor de Natação', 'Os instrutores de natação treinam e aconselham grupos ou indivíduos na natação. Planeiam os treinos e ensinam diferentes estilos de natação, tais como crawl, bruços e mariposa. Contribuem para melhorar o desempenho dos seus alunos.', 'released', '["Instrutora de Natação", "Instrutor de Natação"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/62979364-6fac-41f2-87ca-202bca19a6ab', 'Operador de CAD', 'Os operadores de CAD utilizam hardware e software para acrescentar as dimensões técnicas aos trabalhos de desenho assistido por computador. Os operadores de CAD garantem que todos os aspetos adicionais das imagens de produtos criadas são exatos e realistas. Calculam igualmente a quantidade de materiais necessários para o fabrico dos produtos. Posteriormente, o desenho digital finalizado é processado por máquinas de fabrico assistido por computador, que produzem o produto acabado.', 'released', '["Operadora de CAD", "Operador de CAD"]'::jsonb, '3118'),
  ('http://data.europa.eu/esco/occupation/62d3f108-ade2-44b5-beeb-d63d0b21268f', 'Engenheiro de Processamento Mineral', 'Os engenheiros de processamento de mineral desenvolvem e gerem equipamentos e técnicas para processar e aperfeiçoar com êxito os minerais valiosos do minério ou dos minerais em bruto.', 'released', '["Mineralogista", "Engenheira de Processamento Mineral", "Engenheiro de Processamento Mineral"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/62f53135-e091-4aa6-8895-5851d72271b9', 'Operador de Clarificadora de Óleo', 'Os operadores de clarificadora de óleo operam equipamento para remover sedimentos e humidade de óleos. Aquecem o reservatório clarificador com vapor e coadores para o processo de clarificação. Removem as matérias estranhas da superfície de óleo quente ou das pilhas de óleo utilizando escumadores.', 'released', '["Técnico de Operação de Instalação Clarificadora de Óleos Alimentares", "Técnica de Operação de Instalação Clarificadora de Óleos Alimentares", "Operadora de Clarificadora de Óleo", "Operador de Clarificadora de Óleo"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/63042e8f-dd59-47fe-87f3-3b2ce21f196a', 'Operador de Máquina de Tornear', 'Os operadores de máquinas de tornear instalam, programam e cuidam das máquinas de tornear concebidas para cortar o metal em excesso de uma peça metálica, utilizando uma ferramenta de corte temperado movida por motores controlados por computador. Interpretam os esquemas da máquina de tornear e as instruções das ferramentas, realizam operações regulares de manutenção das máquinas e efetuam ajustes aos comandos, tais como a profundidade dos cortes e a velocidade de rotação.', 'released', '["Operadora de Máquina de Tornear", "Operador de Máquina de Tornear"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/631aaef2-2d67-45c6-93a6-1b1abdf57542', 'Penhorista', 'Os penhoristas oferecem empréstimos aos clientes através da garantia de objetos ou artigos pessoais. Avaliam os artigos pessoais fornecidos em troca do empréstimo, determinam o seu valor e o montante do empréstimo disponível e conservam um registo dos ativos do inventário.', 'released', NULL, '4213'),
  ('http://data.europa.eu/esco/occupation/631e504f-0db4-4e03-bf90-3f00d550170f', 'Técnico de Sensores', 'Os técnicos de sensores colaboram com engenheiros especialistas em tecnologias de sensores no desenvolvimento de sensores, sistemas de sensores e produtos equipados com sensores. Têm como função construir, testar, efetuar a manutenção e reparar o equipamento de sensores.', 'released', '["Técnico de Sensores", "Técnica de Sensores"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/632e61c8-4e4b-44c7-b213-6dd5a174b143', 'Diretor de Distribuição', 'Os gestores de distribuição planificam a distribuição de produtos a vários pontos de venda.', 'released', '["Diretor de Distribuição", "Diretora de Logística", "Diretora de Distribuição Comercial", "Diretor de Logística", "Diretora de Distribuição", "Diretor de Distribuição Comercial"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/6336c205-46bd-42f6-9e67-6b0be6e7618c', 'Hidrogeólogo', 'Os hidrogeólogos estudam a distribuição, a qualidade e o fluxo da água a fim de manter o funcionamento das minas sem problemas de água e de assegurar um abastecimento adequado de águas de processo. Fornecem e avaliam informações destinadas a proteger as águas subterrâneas e superficiais da contaminação.', 'released', '["Hidrogeólogo", "Hidrogeóloga"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/6353b3e8-e8f2-4ecb-b230-186927139892', 'Operador de Registro de Dados', 'Os operadores de registo de dados procedem à atualização, manutenção e obtenção de informações mantidas nos sistemas informáticos. Preparam dados de origem para serem introduzidos no computador, através da compilação e triagem de informações, tratam documentos de origem dos clientes e das contas, através da revisão dos dados para eliminar deficiências, e verificam os dados introduzidos relativos ao clientes e às contas.', 'released', '["Responsável Pela Inserção dos Dados", "Operador de Registro de Dados", "Responsável Pela Entrada dos Dados", "Responsável Pela Inserção de Dados", "Operadora de Inserção de Dados", "Responsável Pela Entrada de Dados", "Operador de Inserção de Dados", "Operadora de Registro de Dados"]'::jsonb, '4132'),
  ('http://data.europa.eu/esco/occupation/63c92723-ee86-42cb-89bf-d93b65398bef', 'Diretor de Importação e Exportação de Artigos de Relojoaria e Ourivesaria', 'Os diretores de importação e exportação de artigos de relojoaria e ourivesaria implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Artigos de Relojoaria e Ourivesaria", "Diretor de Importação e Exportação de Artigos de Relojoaria e Ourivesaria", "Diretor de Vendas de Artigos de Relojoaria e Ourivesaria", "Diretora de Vendas de Artigos de Relojoaria e Ourivesaria"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/63d99701-1a6c-4c57-87c8-4b0d5c0b4408', 'Vendedor de Bebidas', 'Os vendedores de bebidas vendem bebidas em lojas especializadas.', 'released', '["Vendedora de Bebidas", "Vendedor de Bebidas"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/6426ada1-4d8c-4612-99e3-91bc569805ee', 'Diretor Fabril', 'Os diretores fabris controlam e orientam o processo fabril de uma organização. Garantem que os produtos e serviços são produzidos de forma eficiente dentro do prazo e do orçamento estabelecidos.', 'released', '["Diretora Industrial", "Diretor Industrial", "Diretora de Produção", "Diretor Fabril", "Diretora Fabril", "Diretor de Produção"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/643a2225-6a01-4899-81b0-e867ca09b9c9', 'Inspetor de Políticas Públicas', 'Os inspetores de políticas públicas acompanham o desenvolvimento e a aplicação dos planos e políticas governamentais, bem como o planejamento dos processos e as propostas políticas, e realizam inspeções aos procedimentos de planejamento.', 'released', '["Inspetor de Políticas Públicas", "Inspetora de Políticas Públicas"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/64421dde-df97-4c42-a25a-b3bc55b39ad6', 'Especialista em Import-Export de Produtos para o Lar', 'Os especialistas em import-export de produtos para o lar possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Produtos para o Lar"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/6474e4d4-e3a6-4e88-83ee-971ebbf954e9', 'Timoneiro', 'Os timoneiros são os membros da tripulação com o nível hierárquico mais elevado numa embarcação de navegação interior. Desempenham uma série de tarefas relacionadas com o funcionamento e a manutenção das zonas do convés, as máquinas e outros equipamentos, as operações de amarração e desamarração, bem como com o governo do navio como tarefa principal.', 'released', '["Timoneiro", "Timoneira"]'::jsonb, '3152'),
  ('http://data.europa.eu/esco/occupation/6482664d-48f4-4ff4-9346-584ac0e2f729', 'Diretor de Produção de Calçado', 'Os diretores de produção de calçado planificam, distribuem e coordenam todas as atividades necessárias das diferentes fases de fabrico do calçado, assegurando a adesão a normas de qualidade e a objetivos predefinidos de produção e produtividade.', 'released', '["Diretora de Produção de Calçado", "Diretor de Produção de Calçado"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/64a68a43-24be-4929-95ce-5b14617199d1', 'Soprador de Vidro', 'Os sopradores de vidro concebem, produzem e decoram artefactos de vidro, tais como vitrais, espelhos e vidro de arquitetura. Alguns sopradores de vidro especializam-se no restauro, renovação e reparação de peças originais. Podem também funcionar como sopradores de vidro científicos, concebendo e reparando vidro de laboratório.', 'released', '["Sopradora de Vidro", "Vidreira", "Vidreiro", "Soprador de Vidro"]'::jsonb, '7315'),
  ('http://data.europa.eu/esco/occupation/64b136da-aedf-48a2-96a0-72eb850bfcd0', 'Diretor de Centro de Busca e Salvamento', 'Os diretores de centro de busca e salvamento supervisionam as operações de um centro de salvamento, executando tarefas administrativas e a supervisão do pessoal. Asseguram que o centro funciona de acordo com as políticas e que o pessoal desempenha missões de salvamento de forma segura, eficiente e conforme.', 'released', '["Diretora de Centro de Refugiados", "Diretora da Plataforma de Apoio aos Refugiados", "Diretora de Centro de Busca e Salvamento", "Diretor de Centro de Busca e Salvamento", "Diretor de Centro de Refugiados", "Diretor da Plataforma de Apoio aos Refugiados"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/64c180d0-029b-4dc7-b582-77899d171186', 'Preparador de Bebidas não Alcoólicas', 'Os preparadores de bebidas não alcoólicas produzem águas aromatizadas não alcoólicas através da gestão da administração de uma grande seleção de ingredientes na água. Manuseiam e administram ingredientes, tais como açúcar, sumos de fruta, sumos de produtos hortícolas, xaropes à base de fruta ou ervas, aromas naturais, aditivos alimentares sintéticos, tais como edulcorantes artificiais, corantes, conservantes, reguladores de acidez, vitaminas, minerais e dióxido de carbono. Gerem as quantidades em função do produto.', 'released', '["Produtor de Refrigerantes", "Produtora de Refrigerantes", "Preparadora de Bebidas não Alcoólicas", "Preparador de Bebidas não Alcoólicas", "Fabricante de Refrigerantes", "Fabricante de Bebidas Gaseificadas"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/64c7d461-152c-477f-a8e2-c2c537e9d617', 'Técnico de Redes Informáticas', 'Os técnicos de redes informáticas procedem à instalação, manutenção e resolução de problemas de redes, equipamentos de comunicação de dados e dispositivos instalados em rede, tais como impressoras e redes de áreas de armazenamento. Também analisam e resolvem problemas relacionados com a rede, comunicados pelos usuários.', 'released', '["Técnica de Redes", "Operador de Redes", "Técnico de Redes", "Operadora de Redes", "Técnica de Redes Informáticas"]'::jsonb, '3513'),
  ('http://data.europa.eu/esco/occupation/64e38ce7-3901-4261-bfee-77c7a77397f2', 'Diretor de Estratégia', 'Os diretores de estratégia são responsáveis pela gestão do desenvolvimento de programas políticos e pela garantia do cumprimento dos objetivos estratégicos da organização. Supervisionam a produção de posições políticas, bem como as campanhas e o trabalho de sensibilização da organização em domínios como o ambiente, a ética, a qualidade, a transparência e a sustentabilidade.', 'released', '["Diretor de Controle da Conformidade", "Diretora de Política Ambiental", "Diretor de Política Ambiental", "Diretor de Estratégia", "Diretora de Controle da Conformidade", "Diretora de Estratégia"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/64e909ad-1bd0-493c-a8dc-1afbed0c9c2f', 'Condutor de Ambulância com Prestação de Cuidados de Emergência', 'Os condutores de ambulâncias com prestação de cuidados de emergência utilizam veículos de emergência para responder a emergências médicas e apoiar o trabalho de paramédicos, deslocam os doentes em segurança, registam as alterações nos sinais vitais do doente e informam os paramédicos responsáveis, assegurando o correto armazenamento, transporte e funcionamento dos equipamentos médicos, sob supervisão e seguindo as indicações de um médico.', 'released', '["Condutora de Ambulância com Prestação de Cuidados de Emergência", "Condutor de Ambulância com Prestação de Cuidados de Emergência"]'::jsonb, '3258'),
  ('http://data.europa.eu/esco/occupation/650c4c7b-8cd8-4671-a38e-6e37e45e0c8e', 'Comerciante Grossista de Máquinas e Equipamentos para a Indústria, Comércio e Navegação', 'Os comerciantes grossistas de máquinas e equipamentos para a indústria, comércio e navegação investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Máquinas e Equipamentos para a Indústria, Comércio e Navegação"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/652b847f-837a-4a08-bd5e-36397fe56455', 'Diretor de Qualidade na Indústria Têxtil', 'Os diretores de qualidade na indústria têxtil aplicam, gerem e promovem sistemas de qualidade. Asseguram que os produtos têxteis respeitem as normas de qualidade da organização. Os diretores de qualidade na indústria têxtil inspecionam, por conseguinte, as linhas de produção de têxteis e os produtos.', 'released', '["Supervisora de Qualidade Têxtil", "Diretora de Controle de Qualidade na Indústria Têxtil", "Diretor de Qualidade na Indústria Têxtil", "Supervisor de Qualidade Têxtil", "Diretor de Controle de Qualidade na Indústria Têxtil", "Diretora de Qualidade na Indústria Têxtil"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/653374a9-a96e-4c5b-849f-62ae67b0ed62', 'Professor em Estabelecimento Prisional', 'Os professores em estabelecimento prisional dão formação aos infratores, incluindo reclusos, em matéria de reabilitação social e o comportamento correcional. Ajudam os prisioneiros a adquirir competências que facilitem a sua reintegração na sociedade e a aumentem as suas possibilidades de emprego após a reclusão. Os professores em estabelecimento prisional analisam as necessidades individuais de aprendizagem dos alunos, planificam e preparam material pedagógico e aulas, e atualizam os respetivos registos de aprendizagem. Além disso, asseguram que a zona de trabalho e os materiais de trabalho estão livres de perigo e seguros e supervisionam permanentemente os alunos.', 'released', '["Professora em Estabelecimento Prisional", "Professor em Estabelecimento Prisional"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/654ce97c-9ed1-4614-bc76-36f4a1f67557', 'Engenheiro de Materiais Sintéticos', 'Os engenheiros de materiais sintéticos desenvolvem novos processos de materiais sintéticos ou melhoram os já existentes. Concebem e constroem instalações e máquinas para a produção de materiais sintéticos e analisam amostras de matérias-primas a fim de garantir a qualidade.', 'released', '["Engenheiro de Materiais Sintéticos", "Engenheira de Materiais Sintéticos"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/6565dc02-14e4-4819-b99c-44c352000f43', 'Montador de Equipamentos Eletrônicos', 'Os montadores de equipamentos eletrônicos são responsáveis pela montagem de equipamentos e sistemas eletrônicos. Montam os componentes eletrônicos e a cablagem de acordo com os esquemas e os desenhos de montagem. Podem prestar assistência na inspeção de qualidade e na manutenção do equipamento.', 'released', '["Montador de Equipamentos Eletrônicos", "Montadora de Equipamentos Eletrônicos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/656674ac-9d4e-4a91-963f-c0b6edfd55a4', 'Supervisor de Rotas de Ônibus', 'Os supervisores de rotas de ônibus coordenam os movimentos, as rotas e os motoristas dos veículos, e podem supervisionar a carga, a descarga e o controlo das bagagens ou dos envios via expresso por ônibus. ;', 'released', '["Supervisor de Rotas de Ônibus", "Supervisora de Rotas de Ônibus"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/657eeac9-5bb9-449d-a353-aa7d5f47e2b5', 'Técnico de Mistura de Cores', 'Os técnicos de mistura de cores preparam receitas de mistura de cores e matérias tintoriais. Asseguram a consistência das cores, ainda que utilizem materiais provenientes de fontes diferentes.', 'released', '["Técnica de Mistura de Cores", "Técnico de Mistura de Cores"]'::jsonb, '3116'),
  ('http://data.europa.eu/esco/occupation/6581aa0d-c807-4091-84cc-bc041f962ab1', 'Cantor', 'Os cantores são músicos profissionais, especializados na utilização da sua voz como instrumento musical, com diferentes extensões vocais. Atuam para públicos ao vivo e para gravações em diferentes gêneros musicais.', 'released', '["Rapper", "Cantor", "Cantora de Ópera", "Cantora", "Cantor de Ópera", "Solista", "Cantor Lírico", "Vocalista", "Cantora Lírica"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/659b0ffd-337c-4a1f-82e3-2730812279de', 'Investidor de Capital de Risco', 'Os investidores de capital de risco investem em empresas em fase de arranque recentes ou de pequena dimensão, prestando financiamento privado. Investigam os mercados potenciais e as oportunidades específicas dos produtos para ajudar os proprietários das empresas a desenvolver ou expandir o negócio. Prestam aconselhamento empresarial, conhecimentos técnicos e contatos em rede com base na sua experiência e atividades. Não assumem funções de gestão no seio da empresa, mas têm uma palavra a dizer na sua direção estratégica.', 'released', '["Investidor de Capital de Risco", "Investidora de Capital de Risco", "Business Angel"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/65a9366c-d4d3-484d-a577-c63d335987da', 'Instrutor de Cães-Guias', 'Os instrutores de cães-guias treinam cães responsáveis por guiar os invisuais para se deslocarem de forma eficaz. Planeiam as sessões de treino, emparelham os cães guia e os clientes e asseguram os cuidados de rotina gerais dos cães em formação. Os instrutores de cães-guia também prestam aconselhamento aos invisuais sobre a utilização de técnicas que facilitam a mobilidade e as competências de deslocação do cão.', 'released', '["Instrutor de Cães-Guias", "Instrutora de Cães-Guias"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/65b88636-2ebb-4049-b509-2f6da5d6ea1c', 'Operador de Máquinas de Fabricação de Envelopes', 'Os fabricantes de máquinas de fabrico de envelopes operam uma máquina que recebe papel e executa as etapas para criar envelopes: corta e dobra o papel e cola-o e, em seguida, aplica uma cola mais fraca de grau alimentar na aba do envelope para o consumidor poder selá-lo.', 'released', '["Operadora de Máquinas de Fabricação de Envelopes", "Operador de Máquinas de Fabricação de Envelopes"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/65bd2342-f7de-4932-9164-eb480e35a791', 'Trabalhador de Produção Animal', 'Os trabalhadores de produção animal mantêm a saúde e o bem-estar dos animais. Supervisionam a criação/produção e os cuidados diários, tais como a alimentação e a dessedentação dos animais.', 'released', '["Trabalhadora de Produção Animal", "Operária na Exploração Animal", "Trabalhadora de Criação Animal", "Trabalhador de Criação Animal", "Trabalhador de Produção Animal", "Operário na Exploração Animal", "Trabalhadora Agropecuária", "Trabalhador Agropecuário"]'::jsonb, '9212'),
  ('http://data.europa.eu/esco/occupation/65beb253-61b0-4f8f-9c3c-49419913fd18', 'Diretor de Importação e Exportação de Laticínios e Óleos Alimentares', 'Os diretores de importação e exportação de lacticínios e óleos alimentares implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Lacticínios e Óleos Alimentares", "Diretora de Vendas de Lacticínios e Óleos Alimentares", "Diretor de Vendas de Lacticínios e Óleos Alimentares", "Diretor de Importação e Exportação de Lacticínios e Óleos Alimentares", "Diretora de Importação e Exportação de Laticínios e Óleos Alimentares"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/65fb0b53-b8c4-4839-b099-c80b6de5a158', 'Coordenador de Programas de Emprego', 'Os coordenadores de programas de emprego investigam e desenvolvem programas e políticas de emprego destinados a melhorar as normas em matéria de emprego e a reduzir problemas como o desemprego. Supervisionam a promoção dos planos de políticas e coordenam a sua implementação.', 'released', '["Coordenador de Programas de Emprego", "Coordenadora de Programas de Emprego"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/6630d23f-4c8e-4855-abb0-8ca1e72c74ba', 'Tratador e Desbastador de Equinos', 'Os tratadores e desbastadores de equinos prestam assistência a cavalos e póneis.', 'released', '["Tratador e Desbastador de Cavalos", "Tratador e Desbastador de Equinos", "Tratador de Cavalos", "Tratadora e Desbastadora de Equinos", "Tratadora e Desbastadora de Cavalos", "Trabalhador Agrícola", "Trabalhadora Agrícola", "Tratadora de Cavalos", "Tratadora e Desbastador de Equinos"]'::jsonb, '9212'),
  ('http://data.europa.eu/esco/occupation/6648103b-6984-4880-b8c3-eacb9b0d2bc9', 'Comerciante Grossista de Mobiliário e Artigos de Iluminação', 'Os comerciantes grossistas de mobiliário e artigos de iluminação investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Mobiliário e Artigos de Iluminação"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/664f7498-8e4b-48f8-9fe2-436a692f1204', 'Gerente de Loja de Revestimentos — Parede e Pavimento', 'Os gerentes de loja de revestimentos — parede e pavimento assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas em revestimentos de paredes e pavimentos.', 'released', '["Gerente de Loja de Alcatifas", "Gerrente de Loja de Tapetes", "Gerente de Loja de Papel de Parede", "Gerente de Loja de Decoração", "Gerentea de Loja de Revestimentos — Parede e Pavimento"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/665266cb-50dd-44a5-a920-ab04c67e251a', 'Técnico de Apoio Pastoral', 'Os técnicos de apoio pastoral apoiam as comunidades religiosas. Prestam serviços de educação e orientação espiritual e executam programas, tais como obras de beneficência e ritos religiosos. Os técnicos de apoio pastoral também auxiliam os padres e ajudam os participantes na comunidade religiosa com problemas sociais, culturais ou emocionais.', 'released', '["Técnica de Apoio Pastoral", "Técnico de Apoio Pastoral"]'::jsonb, '3413'),
  ('http://data.europa.eu/esco/occupation/66527cdc-b7a5-4996-9448-7e327b68d08d', 'Professor de Arte', 'Os professores de Arte são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Arte, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames na realização de sessões de revisão e de feedback para os alunos. Realizam também investigação académica no respetivo domínio da Arte, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor de Arte", "Professora de Arte", "Professor Universitário de Arte", "Professora Universitária de Arte"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/66542dd6-05a6-4d9e-97ff-3f4858c31ff9', 'Fotógrafo', 'Os fotógrafos utilizam câmaras e equipamento digitais ou cinematográficos. Os fotógrafos podem revelar negativos ou utilizar programas informáticos para produzir imagens acabadas e impressas.', 'released', '["Fotógrafo", "Fotógrafa"]'::jsonb, '3431'),
  ('http://data.europa.eu/esco/occupation/6656337f-67eb-4f48-b1e4-ecccdfa44dd2', 'Eletricista de Automóveis', 'Os eletricistas de automóveis procedem à manutenção e reparação dos sistemas elétricos e eletrônicos em veículos a motor, tais como sistemas de ar condicionado, lâmpadas, rádios, sistemas de aquecimento, baterias, cablagem elétrica e alternadores. Utilizam equipamento de teste de diagnóstico para inspecionar os veículos e encontrar falhas. Para realizar o trabalho de reparação, utilizam ferramentas manuais e instrumentos e máquinas elétricos especializados.', 'released', NULL, '7412'),
  ('http://data.europa.eu/esco/occupation/6662e56e-bc3d-4d9b-bed2-79d510d7c4ff', 'Organizador de Casamentos', 'Os organizadores de casamentos prestam assistência com todos os pormenores logísticos necessários relacionados com a cerimónia de casamento do seu cliente. Com base nos requisitos do seu cliente, tomam providências relativas às decorações florais, ao local e ao serviço de catering do casamento, aos convites, etc., coordenando as atividades quer antes, quer durante o casamento.', 'released', '["Organizador de Casamentos", "Organizadora de Casamentos"]'::jsonb, '3332'),
  ('http://data.europa.eu/esco/occupation/6667bf29-a3e3-4513-a71b-82c67206045b', 'Técnico de Apoio Residencial a Jovens', 'Os técnicos de apoio residencial a jovens prestam assistência e apoio a jovens que se deparam com necessidades emocionais complexas expressas em comportamentos desafiadores. Apoiam os jovens adultos com dificuldades de aprendizagem para lidar com a escola, incentivá-los a atividades domésticas e ajudá-los a assumir responsabilidades.', 'released', '["Técnica de Apoio Residencial a Jovens", "Técnico de Apoio Residencial a Jovens"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/666846b2-01ce-43f6-8cb7-f3be09fac4a2', 'Provedor de Justiça', 'Os Provedores de Justiça atuam como mediadores imparciais na resolução de litígios entre duas partes quando existe um desequilíbrio de poder. Entrevistam as partes envolvidas e investigam o caso a fim de chegarem a uma resolução benéfica para ambas as partes. Prestam aconselhamento sobre a resolução de conflitos e oferecem apoio aos clientes. As reclamações são, na sua maioria, contra as instituições públicas e as autoridades.', 'released', '["Provedor de Justiça", "Provedora de Justiça"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/668943cc-c454-4a1b-a296-2fcb524a6222', 'Técnico em Hidrografia', 'Os técnicos em hidrografia realizam operações oceanográficas e hidrográficas em ambientes marinhos. Prestam assistência aos inspetores hidrográficos, utilizando equipamento especializado para cartografar e estudar a topografia e a morfologia subaquáticas das massas de água. Prestam assistência na instalação e na implementação de equipamentos de hidrografia e geodesia e elaboram relatórios sobre o seu trabalho.', 'released', '["Técnica em Hidrografia", "Técnico em Hidrografia"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/669353c2-3f5a-4bc4-939b-6afb6a0c7d13', 'Operador de Tesoura para Chapas', 'Os operadores de tesoura para chapas cortam padrões pormenorizados a partir de superfícies metálicas utilizando tesouras para chapas manuais ou motorizadas, tais como uma broca de corte manual ou uma máquina de corte.', 'released', '["Operador de Tesoura para Chapas", "Operadora de Tesoura para Chapas"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/66ca3643-e6f3-4c75-9300-40d813185b3e', 'Assistente de Quiroprática', 'Os assistentes de quiroprática executam tarefas de rotina e administrativas para prestar apoio aos cuidados e ao trabalho com os doentes, sob a direção e supervisão exclusivas de um quiroprático ou quiroprático especializado. Podem entrevistar os doentes, manter registos do historial do processo e prestar assistência a quiropráticos ou quiropráticos especializados na realização de exames aos doentes e na execução de tarefas administrativas. Os assistentes de quiroprática trabalham em contextos definidos, utilizando protocolos e procedimentos acordados.', 'released', '["Assistentea de Quiroprática"]'::jsonb, '3259'),
  ('http://data.europa.eu/esco/occupation/66d22b81-1b5e-42a1-b904-ac67b4a896c6', 'Operador de Processamento de Minerais', 'Os operadores de processamento de minerais operam uma variedade de máquinas e equipamentos para a transformação de matérias-primas em produtos comercializáveis. Fornecem as informações adequadas sobre o processo à sala de controlo.', 'released', '["Operador de Processamento de Minerais", "Operadora de Processamento de Minerais"]'::jsonb, '8112'),
  ('http://data.europa.eu/esco/occupation/66dc9349-6ca3-4ce4-9865-40686234d752', 'Supervisor de Telhados', 'Os supervisores de telhados acompanham os trabalhos de construção de telhados em edifícios. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Telhados", "Supervisor de Telhados"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/66fb9704-0d56-4673-8e69-7823816b73e1', 'Analista de Pesquisas de Mercado', 'Os analistas de pesquisas de mercado recolhem as informações reunidas nas pesquisas de mercado e estudam-nas para tirar conclusões. Definem os potenciais clientes de um produto, o grupo-alvo e a forma de chegar até eles. Os analistas de pesquisas de mercado analisam a posição dos produtos no mercado de diferentes perspetivas, nomeadamente no que se refere às suas características, preços e concorrentes. Analisam as vendas cruzadas e as interdependências entre diferentes produtos e a sua colocação. Os analistas de pesquisas de mercado preparam informações úteis para o desenvolvimento de estratégias de marketing.', 'released', NULL, '2431'),
  ('http://data.europa.eu/esco/occupation/6724e558-2d75-4116-a473-91a4c14d4c69', 'Responsável de Serviços de Pensões', 'Os responsáveis de serviços de pensões exercem funções administrativas na gestão dos regimes de pensões, assegurando o cálculo correto das prestações da pensão do utente, o cumprimento dos requisitos legais, a elaboração de relatórios e a comunicação de informações relevantes aos utentes. Trabalham no setor privado ou no setor público.', 'released', NULL, '3353'),
  ('http://data.europa.eu/esco/occupation/6725a5bb-b79d-4128-9494-089389ae2a48', 'Operador de Máquina de Torrefação de Cacau', 'Os operadores de máquina de torrefação de cacau instalam e operam equipamentos de transformação do cacau, tais como torradeiras contínuas, craqueadores, ventiladores, equipamento de secagem e trituração.', 'released', '["Operadora de Máquina de Torrefação de Cacau", "Torradora de Cacau", "Operador de Máquina de Torrefação de Cacau", "Operador de Instalação de Torrefação de Cacau", "Operadora de Instalação de Torrefação de Cacau", "Torrador de Cacau"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/6729aa5a-285f-4baf-a466-c2ccd2f2d96f', 'Engastador de Pedras Preciosas', 'Os engastadores pedras preciosas utilizam ferramentas para inserir os diamantes e outras pedras preciosas em engastes de joalharia, de acordo com as especificações. O engaste das pedras preciosas depende da sua dimensão e forma.', 'released', '["Ourives", "Engastador de Pedras Preciosas", "Engastadora de Pedras Preciosas"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/673f3266-ab1a-447d-9b28-fc5838dc07e3', 'Inspetor de Saúde e Segurança no Trabalho', 'Os inspetores de saúde e segurança no trabalho realizam auditorias no local de trabalho para assegurar a conformidade com a legislação nacional e ambiental. Além disso, investigam acidentes de trabalho. Os inspetores de saúde e segurança no trabalho entrevistam os trabalhadores para garantir a conformidade do ambiente de trabalho com as regras de saúde e segurança, inspecionam os locais de trabalho físicos e analisam a documentação legal.', 'released', '["Inspetora de Saúde e Segurança no Trabalho"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/67aee472-533b-4569-a7a5-e7bc34b2cdce', 'Diretor de Distribuição Relojoaria e Ourivesaria', 'Os diretores de distribuição relojoaria e ourivesaria planificam a distribuição de perfumes e cosméticos a vários pontos de venda. Os diretores de distribuição relojoaria e ourivesaria planificam a distribuição de perfumes e cosméticos a vários pontos de venda.', 'released', '["Diretor de Distribuição Relojoaria e Ourivesaria", "Diretora de Distribuição Relojoaria e Ourivesaria", "Diretora de Logística Relojoaria e Ourivesaria", "Diretor de Logística Relojoaria e Ourivesaria"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/67b31696-9722-4b41-84d4-b25657266d59', 'Montador de Joalharia', 'Os montadores de joalharia montam peças de joalharia para formarem diferentes tipos de joalharia, tais como pulseiras, colares ou brincos. Agarram em elos com o alicate ou posicionam o elo na ranhura de um anel de ligação, torcem as juntas do elo que estão abertas com o alicate, montam todas as peças em conjunto e reparam correntes partidas.', 'released', '["Montadora de Joalharia", "Montador de Joalharia"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/67d8c64f-e0d9-4e0b-be8b-510f9e20e698', 'Animador de Atividades ao Ar Livre', 'Os animadores de atividades ao ar livre são responsáveis pelo planejamento e pela organização de atividades ao ar livre. Podem, por vezes, participar em aspetos administrativos, serviços de escritório e tarefas relacionadas com a atividade de base e a manutenção do equipamento. O local de trabalho de animador de atividades ao ar livre é essencialmente «no terreno», mas pode também ser em espaços interiores.', 'released', '["Animadora de Atividades ao Ar Livre", "Animador de Atividades ao Ar Livre"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/67f12d6c-295f-4315-8c5c-8e477c7f7019', 'Operador Apícola', 'Os operadores apícolas operam com máquinas para extrair mel líquido dos favos de mel. Também colocam os favos de mel decapados em cestos da máquina de extração de mel para esvaziar os favos de mel.', 'released', '["Trabalhadora da Extração do Mel", "Operadora Apícola", "Operador Apícola", "Trabalhador da Extração do Mel"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/680831bb-64fc-4fc8-ae58-c450327d9700', 'Diretor de Instalações Fabris', 'Os diretores de instalações fabris preveem a manutenção e o planejamento operacional de rotina dos edifícios destinados a ser utilizados para atividades de fabrico. Controlam e gerem os procedimentos de saúde e segurança, supervisionam o trabalho dos contratantes, planificam e tratam as operações de manutenção dos edifícios, a proteção contra incêndios e a segurança, e supervisionam as atividades de limpeza dos edifícios.', 'released', '["Diretor de Instalações Fabris", "Diretora de Instalações Fabris"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/6818c837-072a-4120-b913-bd360b7b14d0', 'Engenheiro de Produção Industrial', 'Os engenheiros de produção industrial concebem processos de fabrico para diferentes tipos de processos de produção. Integram as especificidades e limitações colocadas pela indústria ou o produto produzido de acordo com princípios gerais e generalizados de engenharia de fabrico na concepção e planejamento dos processos de fabrico.', 'released', '["Engenheira de Processos Industriais", "Engenheiro de Produção Industrial", "Engenheiro de Processos Industriais", "Engenheira de Produção Industrial"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/6833077e-e521-4605-bc1a-893f4b3d811c', 'Especialista no Desenvolvimento de Produtos Têxteis', 'Os especialistas no desenvolvimento de produtos têxteis inovam e concebem produtos têxteis de vestuário, têxteis domésticos e têxteis técnicos (por exemplo, agricultura, segurança, construção, medicina, tecnologia móvel, proteção do ambiente, desporto, etc.). Aplicam princípios científicos e técnicos para o desenvolvimento de produtos têxteis inovadores.', 'released', NULL, '2163'),
  ('http://data.europa.eu/esco/occupation/6837611a-7093-40fb-9e7f-74947bf6f54f', 'Operador de Fornos de Produtos de Argila', 'Os operadores de fornos de produtos de argila cozem produtos de argila, tais como tijolos, canos de esgotos ou telhas, utilizando fornos periódicos ou de túnel. Regulam as válvulas, observam os termómetros, vigiam flutuações e procedem à manutenção dos fornos.', 'released', '["Operadora de Fornos de Produtos Cerâmicos", "Operador de Fornos de Produtos Cerâmicos", "Operadora de Fornos de Produtos de Argila"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/68450507-b4a0-40e0-895b-385fe705be10', 'Operador de Central Telefônica de Emergência Médica', 'Os operadores de central telefônica de emergência médica respondem às chamadas urgentes feitas para o centro de controlo, registam informações sobre a situação de emergência, o endereço e outros pormenores e enviam a ambulância ou o helicóptero mais próximo.', 'released', '["Operador de Central Telefônica de Emergência Médica", "Operadora de Central Telefônica de Emergência Médica"]'::jsonb, '4223'),
  ('http://data.europa.eu/esco/occupation/684fd8d5-9b40-4b02-a680-438f0082d923', 'Professor Universitário', 'Os professores universitários instruem os alunos que obtiveram um diploma do ensino secundário no seu próprio domínio de estudos especializado, que tem um caráter predominantemente académico. Podem deter títulos profissionais como professor universitário ou professor catedrático. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio respetivo, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor do Ensino Superior", "Professora do Ensino Superior", "Professora Universitária", "Professor Universitário", "Professora Universitário"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/68ad860f-c5cd-420f-840f-993e3e813508', 'Inspetor de Bens de Consumo', 'Os inspetores de bens de consumo avaliam partes montadas de bens de consumo e produtos relativamente ao cumprimento de especificações e para detectar eventuais defeitos, em conformidade com os requisitos e as políticas organizacionais dos clientes. Os inspetores de bens de consumo apresentam resultados e conclusões para os relatórios. Os defeitos inspecionados podem ser identificados como fissuras, riscos, erros de lixação e defeitos de peças móveis.', 'released', '["Inspetor de Bens de Consumo", "Inspetora de Bens de Consumo"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/68bc2af1-96ea-4ec2-8b2f-5cde76472135', 'Técnico de Dietética', 'Os técnicos de dietética prestam assistência aos dietistas no planejamento de programas nutricionais e de ementas para os doentes, no âmbito de um plano de tratamento global sob supervisão de um dietista. Sob a supervisão de um dietista, os técnicos de dietética prestam assistência aos dietistas na revisão da situação dos doentes, no planejamento da alta relativa à alimentação entérica e nas verificações clínicas, que incluem a avaliação nutricional.', 'released', '["Técnico de Dietética", "Técnica de Dietética"]'::jsonb, '3259'),
  ('http://data.europa.eu/esco/occupation/68d973df-bf10-4bf7-9a1b-fbd9f604b9db', 'Bioinformático', 'Os bioinformáticos analisam os processos biológicos através de programas informáticos. Mantêm ou constroem bancos de dados que contêm informações biológicas. Os bioinformáticos recolhem e analisam dados biológicos e podem também prestar assistência aos cientistas em vários domínios, incluindo a biotecnologia e a farmacêutica. Realizam investigação científica e análises estatísticas e divulgam as suas conclusões. Os bioinformáticos podem também recolher amostras de ADN, descobrir padrões de dados e realizar investigação genética.', 'released', '["Bioinformático", "Bioinformática"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/68dd0dfc-c8b0-4fd0-9a6e-b0864925fa56', 'Instrutor de Cursos de Formação de Maquinistas', 'Os instrutores de cursos de formação de maquinistas ensinam os futuros maquinistas profissionais, como maquinistas de comboio, elétrico, metro e trólei, a operar o veículo ferroviário em conformidade com a regulamentação. Ensinam aos seus alunos a teoria e as técnicas de conduzir e manter da melhor forma um veículo ferroviário específico, e observam e avaliam a prática dos alunos. Também se centram em matérias não relacionadas com a condução, tais como o serviço ao cliente (no caso de transporte de pessoas) e a regulamentação em matéria de medidas de segurança.', 'released', '["Instrutora de Cursos de Formação de Maquinistas", "Instrutor de Cursos de Formação de Maquinistas"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/68f4fdd9-182c-4c0d-a73d-f767b8a8355e', 'Biólogo Especialista em Aquicultura', 'Os biólogos especialistas em aquicultura aplicam os conhecimentos adquiridos na investigação sobre os animais aquáticos e as plantas e as suas interações entre si e com o ambiente, a fim de melhorar a produção aquícola, prevenir problemas sanitários e ambientais e fornecer soluções, se necessário.', 'released', '["Biólogo Especialista em Aquacultura", "Biólogo Especialista em Aquicultura", "Bióloga Especialista em Aquicultura", "Bióloga Especialista em Aquacultura"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/68ffc53b-6067-4fe7-bd85-c96f4a6c1e45', 'Biotecnólogo Alimentar', 'Os biotecnólogos alimentares estudam o ciclo de vida dos alimentos desde a sua preservação até à deterioração e aos agentes patogénicos de origem alimentar. Investigam e compreendem as doenças transmitidas pelos alimentos para as prevenir. Asseguram que os produtos alimentares respeitem as regulamentações governamentais em matéria de saúde e segurança alimentar.', 'released', '["Microbiólogo Alimentar", "Biotecnólogo Alimentar", "Biotecnóloga Alimentar"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/691c86d9-d88f-440f-b885-7ed9726f782c', 'Gerente de Loja Informática e Multimédia', 'Os gerentes de loja informática e multimédia assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Computadores", "Gerentea de Loja Informática e Multimédia"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/691d30cc-6b2c-4025-89b4-3e719fe664c7', 'Curador de Arte', 'Os curadores de arte organizam e expõem obras de arte e artefactos. Trabalham em e para museus, galerias de arte, museus de ciência ou história, bibliotecas e arquivos e outras instituições culturais. Em geral, os curadores de arte trabalham em áreas e eventos de exposição artística e cultural de todos os tipos.', 'released', '["Curador", "Curador de Museu", "Curadora de Arte", "Curadora de Museu", "Curador de Galeria de Arte", "Curadora de Galeria de Arte", "Curador de Arte", "Curadora"]'::jsonb, '2621'),
  ('http://data.europa.eu/esco/occupation/691ec040-f5ad-47ef-8698-03212d66dbbf', 'Operador de Montagem de Estruturas Metálicas', 'Os operadores de montagem de estruturas metálicas na construção instalam elementos metálicos nas estruturas. Erguem estruturas de aço para edifícios, pontes e outros projetos de construção. Colocam varetas metálicas, ou varões, para formar betão armado.', 'released', '["Operador de Montagem de Estruturas Metálicas", "Operadora de Montagem de Estruturas Metálicas"]'::jsonb, '7214'),
  ('http://data.europa.eu/esco/occupation/699057b7-7aeb-4b5c-bb90-01d935ff32c1', 'Operador de Equipamento Florestal', 'Os operadores de equipamento florestal realizam operações com equipamento especializado na floresta para manter, recolher, extrair e enviar madeira para o fabrico de bens de consumo e produtos industriais.', 'released', '["Operador de Dispositivos Florestais", "Ooperadora de Máquinas Florestais", "Operador de Máquinas Florestais", "Operador de Equipamento Florestal", "Operadora de Dispositivos Florestais", "Operadora de Equipamento Florestal", "Operador de Maquinaria Florestal", "Operadora de Maquinaria Florestal"]'::jsonb, '8341'),
  ('http://data.europa.eu/esco/occupation/69bcbb0a-8d80-4ecd-b0a4-9adea2a40de2', 'Designer Gráfico', 'Os designers gráficos criam texto e imagens para comunicar ideias. Elaboram conceitos visuais à mão ou por software destinados a publicação em suporte papel ou em linha, como anúncios, sites e revistas.', 'released', '["Designer Comercial", "Designer Gráfica", "Designer Gráfico"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/69c24e54-567c-4415-b59b-cda97fdbc50c', 'Estofador para a Indústria Ferroviária', 'Os estofadores para a indústria ferroviária criam modelos de produção, fabricam e montam de componentes interiores para carruagens. Utilizam ferramentas elétricas, ferramentas manuais e máquinas CNC para preparar e fixar os materiais. Também inspecionam os materiais recebidos e preparam o interior das carruagens para os elementos de acabamento.', 'released', '["Estofador para a Indústria Ferroviária", "Estofadora para a Indústria Ferroviária"]'::jsonb, '7534'),
  ('http://data.europa.eu/esco/occupation/69e4e877-9d7a-4df0-973b-34defd318e26', 'Técnico de Limpeza de Aviões', 'Os técnicos de limpeza de aviões limpam as cabinas de aviões e os aviões após a sua utilização. Aspiram ou varrem o interior da cabina, escovam os resíduos dos assentos e organizam os cintos de segurança. Limpam o lixo e resíduos das bolsas dos assentos e organizam as revistas de bordo, os cartões de segurança e os sacos de enjoo. Também limpam as cozinhas e as instalações sanitárias.', 'released', '["Técnico de Limpeza de Aviões", "Técnica de Limpeza de Aviões"]'::jsonb, '9112'),
  ('http://data.europa.eu/esco/occupation/69e6db0b-30b4-4e0e-b95b-173f8bc3da73', 'Responsável Pela Gestão Ambiental em Aeroportos', 'Os responsáveis pela gestão ambiental em aeroportos monitorizam questões ambientais, como as emissões, a contaminação e a atividade da vida selvagem nas instalações dos aeroportos. Informam sobre pontos de atração ambientais para os animais, nomeadamente lixeiras ou zonas úmidas nas proximidades. Podem participar no estudo do impacto ambiental que os aeroportos têm nas comunidades circundantes, em referência à contaminação diversificada que os aeroportos produzem. Aplicam as regras que asseguram o desenvolvimento sustentável do aeroporto.', 'released', '["Especialista em Gestão Ambiental em Aeroportos"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/6a0b0c4f-b57a-4978-a637-2c0adff65996', 'Operador de Lagar de Azeite', 'Os operadores de lagar de azeite extraem óleo a partir de sementes oleaginosas seguindo técnicas artesanais.;', 'released', '["Trabalhadora de Lagar", "Trabalhador de Lagar", "Operador de Lagar de Azeite", "Operadora de Lagar de Azeite"]'::jsonb, '7514'),
  ('http://data.europa.eu/esco/occupation/6a163fef-dee8-4583-82b0-13b76d8a27b2', 'Vendedor de Automóveis', 'Os vendedores de automóveis vendem automóveis e veículos a motor em lojas especializadas. ; ;', 'released', '["Vendedora de Automóveis", "Vendedor de Automóveis"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/6a167ceb-f847-4ef0-af47-89454c53770b', 'Assistente Social em Clínicas Sociais', 'Os assistentes sociais em clínicas sociais prestam serviços de terapia, aconselhamento e intervenção aos utentes. Tratam indivíduos com conflitos pessoais, nomeadamente os que sofrem de doenças mentais, dependências e abusos, defendendo-os e ajudando-os a obter acesso aos recursos necessários. Focam-se igualmente no impacto dos problemas médicos e de saúde pública nos aspetos sociais.', 'released', '["Assistentea Social em Clínicas Sociais"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/6a2270bc-3f69-4cfd-b99b-fdc2c70d1779', 'Assistente de Bordo de Navio', 'Os assistentes de bordo de navio trabalham a bordo do navio para prestar serviços aos passageiros, nomeadamente refeições, serviços de limpeza, acolhimento de passageiros e explicação dos procedimentos de segurança.', 'released', '["Assistentea de Bordo de Navio"]'::jsonb, '5111'),
  ('http://data.europa.eu/esco/occupation/6a29d804-f775-446c-bec7-35fc4e28ac97', 'Consultor de Gestão', 'Os consultores de gestão analisam a posição, a estrutura e os processos de negócios e de empresas e prestam serviços ou conselhos destinados a melhorá-los. Investigam e identificam processos empresariais, como os relacionados com ineficiências financeiras ou gestão dos trabalhadores, e concebem planos estratégicos com vista a superar estas dificuldades. Trabalham em empresas de consultoria externa, nas quais fornecem pareceres objetivos sobre a estrutura e os processos metodológicos de negócios ou de empresas.', 'released', '["Consultora de Negócios e Gestão", "Consultor de Negócios e Gestão", "Consultor de Gestão", "Consultor para Negócios e Gestão", "Consultora para Negócios e Gestão", "Consultora de Gestão"]'::jsonb, '2421'),
  ('http://data.europa.eu/esco/occupation/6a3d3d28-0ab6-49b0-9a32-697e5e104bf1', 'Especialista em Ciências do Solo', 'Os especialista em ciências do solo investigam e estudam a disciplina científica relativa ao solo. Aconselham sobre a forma de melhorar a qualidade do solo para apoiar a natureza, a produção alimentar ou a infraestrutura humana através de técnicas de prospeção, técnicas de irrigação e medidas de redução da erosão. Asseguram a conservação e a restauração de terras sujeitas a agricultura intensa ou interação humana.', 'released', NULL, '2133'),
  ('http://data.europa.eu/esco/occupation/6a67114c-60a3-4cec-af26-c7df6fe6e9b5', 'Supervisor de Pintura na Construção Civil', 'Os supervisores de pintura na construção civil planeiam, orientam e supervisionam o trabalho da equipe de pintores destacada para determinado projeto ou localização. Supervisionam e avaliam o trabalho dos pintores.', 'released', '["Supervisora de Pintura na Construção Civil", "Supervisor de Pintura na Construção Civil"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/6a6ce738-b049-4521-b402-8e1f346c7eca', 'Assistente Social Especialista no Apoio às Pessoas sem-Abrigo', 'Os assistentes sociais especialistas no apoio às pessoas sem-abrigo prestam assistência e aconselhamento no local a pessoas que têm problemas de alojamento ou que vivem nas ruas. Apresentam-lhes os serviços disponíveis para sem abrigo, desde vagas em albergues a serviços de ajuda financeira. Podem ter de lidar com pessoas com problemas de saúde mental, dependências ou vítimas de violência doméstica ou de abusos sexuais.', 'released', '["Assistente Social de Apoio aos Cidadãos sem-Abrigo", "Assistentea Social Especialista no Apoio às Pessoas sem-Abrigo"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/6a6e174e-cffa-49a9-9f2f-aa39c81cdee5', 'Atendente de Balcão de Posto de Correio', 'Os empregados de balcão de posto de correio vendem produtos e serviços numa estação de correios. Auxiliam os clientes na recolha e envio de correio. Os empregados de balcão de posto de correio também vendem produtos financeiros.', 'released', '["Empregado de Balcão de Posto de Correio", "Empregada de Balcão de Posto de Correio", "Atendentea de Balcão de Posto de Correio"]'::jsonb, '4211'),
  ('http://data.europa.eu/esco/occupation/6a7212c9-40da-4346-a190-3896bdd9a925', 'Agente Responsável Pela Liberdade Condicional', 'Os agentes responsáveis pela liberdade condicional supervisionam os infratores após a sua libertação ou os indivíduos condenados a penas em regime de não reclusão. Elaboram relatórios de aconselhamento sobre a pena aplicada ao infrator e análises relativamente às possibilidades de reincidência. Auxiliam os infratores durante o processo de reabilitação e reintegração e asseguram que estes cumprem a sua pena de serviço comunitário, quando aplicável.', 'released', '["Agentea Responsável Pela Liberdade Condicional"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/6aa78e46-ce22-421f-8a75-e915ac63c9d0', 'Supervisor de Call Centre', 'Os supervisores de call centre supervisionam os trabalhadores do call centre, gerem projetos e compreendem os aspetos técnicos das atividades do call centre.', 'released', '["Supervisor de Centro de Chamadas", "Supervisora de Call Centre", "Supervisor de Centro de Atendimento", "Supervisora de Centro de Chamadas", "Supervisora de Centro Telefônico de Atendimento", "Supervisor de Call Centre", "Supervisor de Centro Telefônico de Atendimento", "Supervisora de Centro de Atendimento"]'::jsonb, '3341'),
  ('http://data.europa.eu/esco/occupation/6aef7360-8c4a-4e1a-a402-b1e207101dc8', 'Gestor de Parque de Campismo', 'Os gestores de parque de campismo planificam, dirigem ou coordenar todas as instalações do parque de campismo e gerem os empregados.', 'released', '["Gestor de Parque de Campismo", "Gestor de Campismo", "Gestora de Campismo", "Gestora de Parque de Campismo", "Gerente"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/6afe39e2-2674-45db-b05c-a6cab02fe25b', 'Professor Especialista em Educação de Adultos', 'Os professores especialistas em educação de adultos organizam e lecionam programas concebidos especificamente para formandos adultos. Apresentam um vasto espetro de matérias, desde disciplinas académicas como a matemática e a história, até ações de formação para o desenvolvimento pessoal, conhecimentos técnicos ou cursos práticos, como línguas e TIC. Ensinam e apoiam os adultos que aspirem a expandir os seus conhecimentos e competências pessoais e profissionais e/ou a obter mais qualificações. Os professores especialistas em educação de adultos tomam em conta os conhecimentos anteriores e o trabalho e a experiência de vida dos formandos. Individualizam o ensino e envolvem os alunos no planejamento e execução das suas atividades de aprendizagem. Os professores especialistas em educação de adultos elaboram trabalhos e exames adequados aos seus alunos adultos.', 'released', '["Professor Especialista em Educação de Adultos", "Professora Especialista em Educação de Adultos"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/6b0ad7c0-a37f-45c6-a486-ee943a11429e', 'Astrólogo', 'Os astrólogos analisam as constelações e os movimentos dos objetos celestes, bem como os alinhamentos estelares e planetários específicos. Apresentam esta análise juntamente com as suas próprias interpretações sobre o temperamento dos clientes, predisposições relacionadas com a sua saúde, questões amorosas e de casamento, as oportunidades de negócio e de emprego e outros aspetos pessoais. ;', 'released', '["Tarólogo", "Taróloga", "Astróloga", "Astrólogo"]'::jsonb, '5161'),
  ('http://data.europa.eu/esco/occupation/6b304370-0112-4881-a1bd-27d8df645d00', 'Instrutor da Escola Prática de Polícia', 'Os instrutores de escola prática de polícia prestam formação aos novos recrutas ou cadetes e aos veteranos experientes sobre a teoria e a prática necessárias para se tornarem agentes da polícia. Ministram aulas teóricas sobre temas académicos como o direito, a regulamentação governamental, as relações comunitárias e a diversidade humana. Os instrutores de escola prática de polícia também fornecem instruções mais práticas em matéria de treino físico, cuidado das armas de fogo, primeiros socorros, táticas de autodefesa e a operação de veículos. Além disso, preparam e desenvolvem planos de aulas e novos programas de formação à medida que surgem novos regulamentos e desenvolvimentos em matéria de aplicação da lei. Os instrutores acompanham o progresso dos alunos, avaliam-nos individualmente e elaboram relatórios de avaliação do desempenho.', 'released', '["Instrutora da Escola Prática de Polícia", "Instrutor da Escola Prática de Polícia"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/6b46ea2f-403a-473c-b2e5-9fcf0c2bd634', 'Técnico Assistente de Pescaria', 'Os técnicos assistentes de pescaria auxiliam o chefe de máquinas a verificar as operações e a manutenção da instalação de propulsão, das máquinas e do equipamento auxiliar do navio. Colaboram na segurança, na sobrevivência e nos cuidados de saúde a bordo, respeitando as normas nacionais e internacionais aplicáveis.', 'released', '["Técnica Assistente de Pescaria", "Técnico Assistente de Pescaria"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/6b5e5aa6-9bf7-47e6-90d2-4d2187d47d11', 'Especialista em Política de Imigração', 'Os especialistas em política de imigração desenvolvem estratégias para a integração de refugiados e de requerentes de asilo, bem como políticas para a circulação de pessoas de uma nação para outra. Visam melhorar a cooperação e a comunicação a nível internacional sobre a questão da imigração, bem como aumentar a eficiência dos procedimentos de imigração e de integração.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/6ba25e0f-7fb8-4879-a1f9-d4f8945966be', 'Diretor de Fotografia', 'Os diretores de fotografia são responsáveis pela interpretação visual do guião e de todos os componentes fotográficos do filme, incluindo a sequenciação, a cor, a iluminação, o estilo e os locais. Criam o aspeto visual do filme ou do programa de televisão e selecionam o equipamento de filmagem, incluindo a lente e os filtros. Os diretores de fotografia gerem os operadores do equipamento visual e os técnicos de iluminação. Trabalham em conjunto com o realizador a fim de alcançar o efeito desejado.', 'released', '["Diretora de Fotografia", "Diretor de Fotografia"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/6c2b32b4-2f62-4288-a359-3406022c3610', 'Comerciante Grossista de Açúcar, Chocolate e Produtos de Confeitaria', 'Os comerciantes grossistas de açúcar, chocolate e produtos de confeitaria investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Açúcar, Chocolate e Produtos de Confeitaria"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/6c39cf1c-7332-41c1-86c3-6ed3daf3c479', 'Manipulador de Pescado', 'Os manipuladores de pescado cortam as cabeças do peixe e removem os órgãos do corpo para a produção de peixe e marisco. Procedem à remoção de órgãos por raspagem e lavagem, ao corte de zonas que apresentam defeitos e à embalagem dos peixes transformados em recipientes adequados.', 'released', '["Manipulador de Pescado", "Preparadora de Pescado", "Manipuladora de Pescado", "Preparador de Pescado"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/6c3fd65e-2d24-47d8-bc22-9e93512bdcc2', 'Diretor Executivo', 'Os diretores executivos ocupam a posição mais elevada numa estrutura empresarial piramidal. Têm uma ideia abrangente do funcionamento da empresa, dos seus departamentos, dos riscos e das partes interessadas. Analisam diferentes tipos de informação e criam ligações entre eles para efeitos de tomada de decisões. Servem de ligação de comunicação com o conselho de administração para a elaboração de relatórios e a execução da estratégia global.', 'released', '["Administrador", "Diretora Executiva", "Administrador Delegado", "CEO", "Administradora Delegada", "Gerente de Agência de Recrutamento", "Administradora", "Diretor Executivo", "Diretora Executivo"]'::jsonb, '1120'),
  ('http://data.europa.eu/esco/occupation/6c7d333a-b2a9-4325-b25b-566d1ecc956d', 'Inspetor Florestal', 'Os inspetores florestais acompanham as operações florestais para assegurar que os trabalhadores e as suas atividades cumprem a legislação e as normas adequadas. Realizam inspeções para examinar as operações, os salários, os custos e as medidas de saúde e segurança. Os inspetores florestais também analisam e comunicam as suas conclusões.', 'released', '["Inspetora Florestal", "Inspetor Florestal"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/6c999fc7-c6b7-4ef3-a4b9-af124a1783a2', 'Auxiliar de Escritório', 'Os empregados de escritório são responsáveis pela execução de tarefas de escritório e administrativas no ambiente de um escritório e apoiam as operações comerciais dentro de um departamento. Prestam assistência a todo o pessoal administrativo, secretários e assistentes, triando o correio, arquivando formulários e documentos, atendendo chamadas telefônicas, fazendo a recepção de clientes e agendando reuniões.;', 'released', '["Secretário", "Secretária", "Empregada de Escritório", "Empregado de Escritório"]'::jsonb, '4110'),
  ('http://data.europa.eu/esco/occupation/6cc19251-763b-4de1-b4f7-526c9ff732d2', 'Diretor de Relações Públicas', 'Os diretores de relações públicas procuram transmitir e manter a imagem ou reputação desejada de uma empresa, indivíduo, instituição governamental ou organização em geral junto do público e das partes interessadas em geral. Utilizam todo o tipo de meios e eventos para promover a imagem positiva dos produtos, das causas humanitárias ou das organizações. Tentam assegurar que todas as comunicações públicas apresentam os clientes da forma como estes desejam ser percecionados.', 'released', '["Diretora de Relações Públicas", "Técnico de Relações Públicas", "Relações Públicas", "Diretor de Relações Públicas", "Técnica de Relações Públicas"]'::jsonb, '1222'),
  ('http://data.europa.eu/esco/occupation/6ccb925a-264a-4e00-aa3a-503e53c5db2b', 'Operador de Máquinas de Acabamento de Correias Trapezoidais', 'Os operadores de máquinas de acabamento de correias trapezoidais operam máquinas para tornar as correias trapezoidais flexíveis. Também posicionam as correias na máquina que mede o comprimento da correia e carimba informações de identificação.', 'released', '["Operadora de Máquinas de Acabamento de Correias Trapezoidais", "Operador de Máquinas de Acabamento de Correias Trapezoidais"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/6cd08cbe-7611-4d70-8886-6c59c0385442', 'Especialista em Ciências da Comunicação', 'Os especialistas em ciências da comunicação estudam os diferentes aspetos do planejamento, da recolha, da criação, da organização, da conservação, da utilização, da avaliação e da troca de informações através de comunicação verbal ou não verbal. Estudam as interações entre grupos, entre indivíduos e dos indivíduos com tecnologias (robôs).', 'released', NULL, '2632'),
  ('http://data.europa.eu/esco/occupation/6ce3c372-408b-4c46-86d8-ad6b9255d686', 'Gestor de Produção de Turismo', 'Os gestores de produção de turismo analisam o mercado, analisam potenciais ofertas, desenvolvem produtos, e planificam e organizam os processos de distribuição e de comercialização.', 'released', '["Gestora de Produtos Turísticos", "Gestor de Produtos Turísticos", "Gestor de Produção", "Gestora de Produção de Turismo", "Gestor de Produção de Turismo", "Gestora de Produção", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/6ce5f7e3-a534-4aa2-ab23-255408ddb53a', 'Desenvolvedor de IoT', 'Os programadores de IdC analisam e recolhem dados para interpretar o padrão e prever um resultado. Utilizam a inteligência artificial para gerir as tarefas e as decisões autônomas, empregando algoritmos de aprendizagem automática destinados a criar dispositivos mais inteligentes através de sensores de dados. Os programadores de IdC criam software para conectar objetos a sistemas e dispositivos ou para programar esses objetos de modo que funcionem por si próprios.', 'released', '["Programador de Internet das Coisas", "Programadora de Internet das Coisas", "Programador", "Desenvolvedora de IoT"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/6ce86c90-36cc-43ef-a1e0-885d8151f976', 'Oficial de Turno', 'Os oficiais de turno partilham a responsabilidade pela maior parte dos equipamentos e mecanismos de um navio. Asseguram o funcionamento das máquinas principais, do mecanismo de direção, do sistema de produção elétrica e de outros importantes subsistemas. Comunicam com o chefe de máquinas para a realização de operações técnicas.', 'released', NULL, '3151'),
  ('http://data.europa.eu/esco/occupation/6cee3765-2b3b-48b0-af2b-1eb512d071fd', 'Presidente de Câmara Municipal', 'Os presidentes de câmara municipal presidem às reuniões da câmara municipal da sua jurisdição e atuam como principais responsáveis pelas políticas administrativas e operacionais do governo local. Representam igualmente a sua jurisdição em cerimónias e eventos oficiais e promovem atividades e eventos. Em conjunto com a câmara municipal, detêm o poder legislativo local ou regional e supervisionam o desenvolvimento e a aplicação das políticas. Supervisionam também o pessoal e exercem funções administrativas.', 'released', '["Presidente de Câmara Municipal", "Autarca", "Burgomestre", "Prefeita", "Prefeito", "Presidentea de Câmara Municipal"]'::jsonb, '1111'),
  ('http://data.europa.eu/esco/occupation/6cfba9ca-f9a0-4a50-a8d3-064d88c928b1', 'Montador de Estruturas Metálicas para Eventos', 'Os montadores de estruturas metálicas para eventos instalam e desmontam bancadas temporárias, palcos e estruturas temporárias para apoiar o equipamento de espetáculo, os artistas e o público. A sua função pode incluir o acesso por meio de cordas, o trabalho por cima dos colegas e a elevação de cargas pesadas, o faz com que seja uma atividade de alto risco. O seu trabalho baseia-se em instruções, planos e cálculos. Trabalham no interior e no exterior.', 'released', '["Montadora de Estruturas Metálicas para Eventos", "Montador de Estruturas Metálicas para Eventos"]'::jsonb, '7215'),
  ('http://data.europa.eu/esco/occupation/6d03eaef-1ce5-4a1e-bb41-0908e1af1b65', 'Analista de Profissões', 'Os analistas de profissões recolhem e analisam informações sobre profissões num determinado domínio ou empresa, a fim de fazerem recomendações para a redução de custos e a realização de melhorias gerais nas empresas. Prestam assistência técnica aos empregadores para lidar com situações problemáticas de recrutamento e desenvolvimento de pessoal e com reestruturações do quadro de pessoal. Os analistas de profissões estudam e elaboram descrições de funções e preparam sistemas de classificação profissional.', 'released', '["Analista de RH", "Analista de Postos de Trabalho", "Analista de Recursos Humanos"]'::jsonb, '2423'),
  ('http://data.europa.eu/esco/occupation/6d16c41d-81a7-44a9-836d-7aed46ccb955', 'Pintor de Vidro', 'Os pintores de vidro concebem e criam arte visual em superfícies de vidro ou cristal e em objetos, tais como janelas, cálices e garrafas. Recorrem a várias técnicas para produzir ilustrações decorativas, desde desenho com estêncil até à mão livre.', 'released', '["Pintora de Vidro", "Pintor de Vidro"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/6d1e2801-3ab0-4d74-ac27-918339e8db64', 'Inspetor de Estaleiro de Construção', 'Os inspetores de estaleiros de construção monitorizam os estaleiros de construção e a sua conformidade com a regulamentação em matéria de saúde e segurança. Realizam inspeções, identificam perigos para a segurança e apresentam relatórios sobre as suas conclusões.', 'released', '["Inspetora de Estaleiro de Construção", "Inspetor de Estaleiro de Construção"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/6d421d34-baa1-44f9-9ea0-231d76e325fd', 'Teólogo', 'Os teólogos estudam conceitos relacionados com religiões, crenças e espiritualidade. Aplicam o princípio da racionalidade no exercício da moral e da ética através do estudo de escrituras, da religião, da disciplina e do direito divino.', 'released', '["Teólogo", "Teóloga"]'::jsonb, '2636'),
  ('http://data.europa.eu/esco/occupation/6d50f735-dca9-4a02-96dc-e4310ed98ae2', 'Governante Doméstico', 'Os governantes domésticos são responsáveis por todas as atividades domésticas numa casa privada. Supervisionam e executam as tarefas de acordo com as necessidades do empregador, tais como as atividades de cozinhar, limpar e lavar, cuidar de crianças e a jardinagem. Encomendam as provisões e estão encarregados das despesas repartidas. Os governantes domésticos podem supervisionar e dar instruções ao pessoal doméstico dos grandes agregados familiares.', 'released', '["Governante Doméstico", "Governanta Doméstica", "Governantea Doméstico"]'::jsonb, '5152'),
  ('http://data.europa.eu/esco/occupation/6d72138d-2ebb-4a89-b2b2-8c22365b89bf', 'Operador de Brasagem Forte ou de Soldobrasagem', 'Os latoeiros utilizam vários equipamentos e máquinas para unir duas peças metálicas, aquecendo, fundindo e formando um enchimento metálico entre estas, frequentemente em latão ou cobre. Seguem um processo semelhante ao da soldadura, mas a temperaturas mais elevadas, utilizando maçaricos, ferros de soldar, fluxos e máquinas de soldar para unir alumínio, prata, cobre, ouro ou níquel.', 'released', '["Operadora de Brasagem Forte ou de Soldobrasagem", "Operador de Brasagem Forte ou de Soldobrasagem"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/6d765c21-267d-4d3d-a989-9b7596670477', 'Especialista em Tintura de Tecidos e Têxteis', 'Os especialistas em tintura de tecidos e têxteis preparam, desenvolvem e criam cores para aplicações têxteis.', 'released', NULL, '2163'),
  ('http://data.europa.eu/esco/occupation/6d823dbb-4008-4fb7-b98d-f9d934478647', 'Operador de Central Solar', 'Os operadores de centrais solares operam e efetuam a manutenção de equipamento que produz energia elétrica a partir da energia solar. Monitorizam o equipamento de medição para garantir a segurança das operações e a satisfação das necessidades de produção. Tomam igualmente medidas relativas a problemas do sistema e a anomalias de reparação.', 'released', '["Operadora de Central Solar"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/6da80214-d360-49ec-b1e7-172ab0a0cb0c', 'Operador de Máquina de Tricotar', 'Os operadores de máquinas de tricotar instalam, operam e controlam as máquinas de tricotar. Trabalham com máquinas, técnicas e materiais especializados para processar fios em produtos de malha, tais como vestuário, tapetes ou corda. Procedem à manutenção e reparação de máquinas de tricotar e asseguram que as operações funcionam sem problemas.', 'released', '["Operadora de Máquina de Tricotar", "Operador de Máquina de Tricotar"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/6db9eeae-aef5-4f56-913d-4650e4c720c6', 'Diretor de Serviços Correcionais', 'Os diretores de serviços correcionais gerem as operações de um estabelecimento correcional. Supervisionam o pessoal, desenvolvem e supervisionam procedimentos correcionais e asseguram a conformidade das operações com a regulamentação. Desempenham funções administrativas e facilitam a cooperação com as instituições externas e com o pessoal que presta auxílio à instalação.', 'released', '["Diretor de Serviços Correcionais", "Diretor de Serviços Prisionais", "Diretora de Serviços Prisionais", "Diretora de Serviços Correcionais"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/6dbca2aa-f83b-4567-a4e7-b9a21fb948bf', 'Operador de Laminação de Metal', 'Os operadores de laminação de metal instalam e asseguram o correto funcionamento de laminadores de metais concebidos para moldar peças metálicas na forma desejada, passando-as por um ou vários pares de rolos, a fim de reduzir a espessura do metal e torná-lo homogéneo. Também têm em conta a temperatura adequada para este processo de laminação.', 'released', '["Operadora de Laminação de Metal", "Operador de Laminação de Metal"]'::jsonb, '8121'),
  ('http://data.europa.eu/esco/occupation/6df6c5cb-c1a2-42c8-acd0-1ee5563c36c1', 'Bioquímico', 'Os bioquímicos estudam e realizam investigação sobre as reações causadas por produtos químicos nos organismos vivos. Tal inclui a realização de investigação para o desenvolvimento ou a melhoria de produtos de base química (por exemplo, medicamentos) destinados a melhorar a saúde dos organismos vivos e a compreender melhor as suas reações.', 'released', '["Bioquímico", "Bioquímica"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/6e0e068b-cd5c-4400-8899-54056087fa14', 'Ótico-Optometrista', 'Os óticos ajudam a melhorar e a corrigir a visão das pessoas. Adaptam lentes e armações de óculos, lentes de contato e outros dispositivos segundo as especificações do indivíduo. O âmbito da sua atividade varia em função da regulamentação nacional e podem operar de acordo com as prescrições de um médico especialista em oftalmologia ou de um optometrista em determinados países.;', 'released', '["Oculista", "Ótica", "Ótico"]'::jsonb, '3254'),
  ('http://data.europa.eu/esco/occupation/6e102a30-2c0a-4a31-aee3-ae7b1fac5466', 'Operador de Máquinas de Costura de Calçado', 'Os operadores de máquinas de costura de calçado unem as peças cortadas de couro e outros materiais para produzir as gáspeas. Utilizam várias ferramentas e uma vasta gama de máquinas, tais como cama plana, braço e uma ou duas colunas. Selecionam os fios e as agulhas para as máquinas de costura, colocam as peças na zona de trabalho e trabalham com as peças de guiamento da máquina sob a agulha. Seguem as costuras, os bordos, as marcações ou movendo os bordos das peças contra a guia. Por último, cortam o fio ou o material em excesso de peças de calçado utilizando tesouras ou moldes.', 'released', '["Operador de Máquinas de Costura de Calçado", "Operadora de Máquinas de Costura de Calçado"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/6e11692c-fc72-4ef4-8bcf-6bd19a6b0ea3', 'Operador de Gaseificação', 'Os operadores de gaseificação realizam a injeção de gaseificação em bebidas.', 'released', '["Operador de Gaseificadora", "Operador de Máquina de Gaseificação", "Operadora de Máquina de Gaseificação", "Operadora de Gaseificadora", "Operadora de Gaseificação"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/6e18b923-7c5f-42d7-8ff0-de8d8ba30dbf', 'Operador de Máquinas de Moldagem a Vácuo', 'Os operadores de máquinas de moldagem a vácuo procedem à operação, ao controlo e à manutenção de máquinas que aquecem as folhas de plástico antes de movê-las em torno de um molde, utilizando a sucção a vácuo; quando estas folhas arrefecem, são ajustadas permanentemente na forma do molde.', 'released', '["Operador de Máquinas de Moldagem a Vácuo", "Operadora de Máquinas de Moldagem a Vácuo"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/6e1b1bd7-9eec-4f10-bce7-94a27d9023e8', 'Coordenador do Processo de Admissão', 'Os coordenadores do processo de admissão são responsáveis pelas candidaturas e admissões dos alunos numa escola (privada), colégio ou universidade. Avaliam as eventuais qualificações dos futuros alunos e aprovam ou recusam a sua candidatura, com base na regulamentação e nas preferências estabelecidos pelo conselho de administração e pela direção da escola. Além disso, ajudam os alunos admitidos na inscrição no programa e nos cursos da sua escolha.', 'released', '["Coordenadora do Processo de Admissão", "Coordenador do Processo de Admissão"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/6e298596-882b-4687-a0cf-3eb37f8fd328', 'Coordenador de Atividades de Ar Livre', 'Os coordenadores de atividades de ar livre organizam e gerem programas de trabalho e recursos (em especial, pessoal) para fornecer os produtos e serviços da organização. Supervisionam e gerem o pessoal. Podem formar e desenvolver o pessoal, ou planear e gerir este processo através de terceiros. Estão muito conscientes das suas responsabilidades relativamente aos clientes, questões técnicas, questões ambientais e questões de segurança. A função de um coordenador/supervisor de animação de ar livre é frequentemente «no terreno», mas pode também haver aspetos de gestão e administração.', 'released', '["Coordenador de Atividades ao Ar Livre", "Coordenadora de Atividades ao Ar Livre", "Coordenadora de Atividades de Ar Livre"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/6e36bf67-9df2-4d68-8f78-fca1d34acc0b', 'Guarda Prisional em Centros de Detenção Juvenil', 'Os guardas prisionais em centros de detenção juvenil controlam e prestam segurança aos jovens delinquentes. Asseguram a segurança da instalação em conformidade com as regras e os regulamentos, elaboram relatórios sobre as atividades diárias, bem como em caso de incidentes, e comunicam atividades pouco habituais. Também supervisionam os processos de reabilitação dos infratores.', 'released', '["Guarda Prisional"]'::jsonb, '5413'),
  ('http://data.europa.eu/esco/occupation/6e591f17-65c1-4a24-af2a-ca7862d4625e', 'Representante de Vendas de Equipamentos Eletrônicos e de Comunicações', 'Os representantes de vendas de equipamentos eletrônicos e de comunicações prestam serviços em nome de uma empresa para vender as suas mercadorias, fornecendo simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Equipamentos Eletrônicos e de Comunicações"]'::jsonb, '2434'),
  ('http://data.europa.eu/esco/occupation/6e5ceba0-df96-465f-adb4-2e06ae715d43', 'Programador de Ferramentas Numéricas e de Controle de Processos', 'Os programadores de ferramentas numéricas e de controle de processos desenvolvem programas informáticos para o controle de máquinas e equipamentos automáticos envolvidos nos processos de fabricação. Analisam planos técnicos e ordens de trabalho, realizam simulações informáticas e testes de funcionamento.', 'released', '["Programador de Ferramentas Numéricas e de Controle de Processos", "Programadora de Ferramentas Numéricas e de Controle de Processos", "Desenvolvedor"]'::jsonb, '2514'),
  ('http://data.europa.eu/esco/occupation/6e6839b6-099c-4802-906e-7f2c8203ee69', 'Responsável de Escritório', 'Os responsáveis de escritório supervisionam o trabalho administrativo que os empregados de escritório têm de desempenhar em vários tipos de organizações ou associações. Exercem atividades de microgestão e vigiam de perto os processos administrativos, como o controlo da correspondência, a concepção de sistemas de arquivo, a revisão e aprovação de requisições, a atribuição e a monitorização de funções administrativas. Reportam aos gestores do mesmo departamento ou aos gestores gerais das empresas, em função da sua dimensão.', 'released', NULL, '3341'),
  ('http://data.europa.eu/esco/occupation/6e6b62d7-4c9c-482a-9d59-7e20de0d8527', 'Comerciante Grossista de Máquinas para a Indústria Têxtil', 'Os comerciantes grossistas de máquinas para a indústria têxtil investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Máquinas para a Indústria Têxtil"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/6e6e44ba-d9f0-403b-93d4-a8d4bd67787a', 'Recepcionista Noturno', 'Os rececionistas noturnos supervisionam os cuidados prestados aos clientes noturnos em hotéis e realizam uma grande variedade de atividades da recepção à contabilidade.', 'released', '["Recepcionista Noturno", "Recepcionista Noturna", "Recepcionista do Turno da Noite"]'::jsonb, '4224'),
  ('http://data.europa.eu/esco/occupation/6e785f05-969e-4940-aedb-d0f896bb0230', 'Aircraft Dispatcher', 'Os aircraft dispatchers autorizam, regulam e controlam os voos de companhias aéreas comerciais em conformidade com os regulamentos governamentais e da empresa. Aceleram e asseguram o fluxo de tráfego aéreo através da preparação de registos de voos, atrasos, cancelamentos e alterações nos horários ou planos de voo.', 'released', NULL, '4323'),
  ('http://data.europa.eu/esco/occupation/6e873bb0-ff0d-4800-a898-362b9a2e1c47', 'Diretor de Importação e Exportação de Produtos Têxteis Acabados e Semiacabados', 'Os diretores de importação e exportação de produtos têxteis acabados e semiacabados implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Produtos Têxteis Acabados e Semi-Acabados", "Diretora de Vendas do Setor Têxtil", "Diretor de Importação e Exportação de Produtos Têxteis Acabados e Semi-Acabados", "Diretor de Vendas do Setor Têxtil", "Diretora de Importação e Exportação de Produtos Têxteis Acabados e Semiacabados"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/6e8917c8-d883-4475-954c-ec241215ca18', 'Gerente de Loja de Fotografia', 'Os gerentes da fotografia são responsáveis pelas atividades e pelo pessoal num armazém de fotografia. Estes funcionários gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Loja de Artigos Fotográficos", "Fotógrafa", "Gerente de Loja de Material Fotográfico", "Fotógrafo", "Gerentea de Loja de Fotografia"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/6e92d4b5-3167-4166-802f-da7753951a31', 'Consultor de Investigação em Tecnologia da Informação', 'Os consultores de investigação em tecnologia da informação realizam investigações direcionadas para o domínio da tecnologia da informação e apresentam um relatório final ao cliente. Utilizam igualmente ferramentas de tecnologia da informação para a concepção dos questionários destinados aos inquéritos, para a análise dos resultados, para a elaboração de relatórios, para a apresentação de resultados e para a formulação de recomendações com base nos resultados da investigação.', 'released', '["Consultor de Investigação em Tecnologia da Informação", "Consultora de Investigação em Informática", "Consultora de Investigação em Tecnologia da Informação", "Consultor de Investigação em Informática", "Consultor de Investigação em Tecnologias de Informação e Comunicação", "Consultora de Investigação em Tecnologias de Informação e Comunicação", "TI"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/6eaf90cb-144d-486c-86e7-3d2bf4242525', 'Instalador de Sinalização Rodoviária', 'Os instaladores de sinalização rodoviária transportam a sinalização rodoviária até ao local especificado e instalam-na. Os instaladores podem abrir um orifício no solo ou remover o pavimento existente para aceder ao solo. Podem fixar sinais pesados em betão.', 'released', '["Instalador de Sinalização Rodoviária", "Instaladora de Sinalização Rodoviária"]'::jsonb, '9312'),
  ('http://data.europa.eu/esco/occupation/6eb85dd0-1188-4081-bf54-1345fb5de3ca', 'Técnico de Biogás', 'Os técnicos de biogás trabalham no domínio da derivação de gás de matéria orgânica e produzido como gases de aterro ou de processos de digestão. Operam equipamentos em unidades de biogás, realizam testes e tarefas de manutenção e tomam medidas em caso de anomalias.', 'released', '["Técnica de Biogás", "Técnico de Biogás"]'::jsonb, '3133'),
  ('http://data.europa.eu/esco/occupation/6ebe4e2e-7deb-4923-8b47-ca6fc03fa13a', 'Supervisor de Fábrica de Papel', 'Os supervisores de fábricas de papel coordenam e controlam as operações numa fábrica de papel durante a produção de produtos como cartão canelado, caixas de cartão ou envelopes almofadados. Asseguram a concretização dos objetivos de produção, como a quantidade e a qualidade dos produtos, dos prazos e da eficácia em termos de custos. Têm uma visão clara dos processos em curso e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Fábrica de Papel", "Supervisor de Fábrica de Papel"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/6f74ebc4-ab7e-42a8-ad94-921f3d0ef0c6', 'Técnico Operativo de Saneamento', 'Os técnicos operativos de saneamento procedem à manutenção dos sistemas de saneamento que eliminam e transportam as águas residuais e de saneamento. Inspecionam os canos, as casas das bombas e a rede elétrica, para a detecção de fugas ou de outras anomalias, e reparam quaisquer problemas. Desobstruem bloqueios e desempenham funções de manutenção, utilizando mapas da rede e software especializado.', 'released', '["Técnico Operativo de Águas Residuais", "Técnica Operativa de Saneamento", "Técnico Operativo de Saneamento", "Técnica Operativa de Águas Residuais", "Técnica Operativo de Saneamento"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/6f7c1e84-8162-4c20-a575-b57ff624eef5', 'Motorista de Táxis', 'Os motoristas de táxis conduzem um veículo de transporte privado de passageiros licenciado, apoiam os passageiros, cobram a importância do transporte e zelam pelo bom estado do veículo.', 'released', NULL, '8322'),
  ('http://data.europa.eu/esco/occupation/6f8f1da1-9160-4b9f-ba30-e3396d3b2f92', 'Modelista de Réplicas', 'Os modelistas de réplicas concebem e constroem modelos de réplicas à escala a partir de vários materiais, tais como o plástico, a madeira, a cera e os metais, na sua maioria à mão.', 'released', NULL, '7522'),
  ('http://data.europa.eu/esco/occupation/6f9398cc-c4cc-415e-a757-fd855f55fda2', 'Operador de Máquinas de Grampeamento Têxtil', 'Os operadores de máquinas de grampeamento têxtil efetuam operações físicas de grampeamento têxtil.', 'released', '["Operadora de Máquinas de Fabricação de não Tecidos", "Operador de Máquinas de Fabricação de não Tecidos", "Operador de Máquinas de Grampeamento Têxtil", "Operadora de Máquinas de Grampeamento Têxtil"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/6fc25650-e69b-43c7-b4d5-3ca95acd7696', 'Comerciante Grossista de Café, Chá, Cacau e Especiarias', 'Os comerciantes grossistas de café, chá, cacau e especiarias investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Café, Chá, Cacau e Especiarias"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/6fc8f605-98b9-4218-b5e2-91c4c9c55c4d', 'Engenheiro Projetista', 'Os engenheiros projetistas desenvolvem novos desenhos conceptuais e pormenorizados. Criam as apresentações visuais para estes conceitos ou produtos e os sistemas utilizados para as criar. Os engenheiros projetistas trabalham com engenheiros e vendedores para melhorar o funcionamento e a eficiência dos dispositivos existentes.', 'released', '["Engenheira de Concepção", "Engenheiro de Concepção", "Engenheira Projetista"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/6fcf4638-e7c7-4978-9302-9a7b63a3d57c', 'Gestor de Marketing', 'Os gestores de marketing executam os esforços relacionados com as operações de marketing numa empresa. Desenvolvem estratégias e planos de marketing, especificando os custos e os recursos necessários. Analisam a rendibilidade desses planos, desenvolvem estratégias de fixação de preços e procuram sensibilizar os consumidores para os produtos e as empresas.', 'released', '["Diretor de Telemarketing", "Gestora de Operações de Marketing", "Diretor de Vendas e Marketing", "Diretora de Marketing de Produtos", "Diretora de Telemarketing", "Gestora de Marketing", "Gestor de Operações de Marketing", "Diretora de Vendas e Marketing", "Diretor de Marketing de Produtos", "Gestor de Marketing", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/6fed206a-ac4d-492b-a81a-5a3a0f2b67bc', 'Operador de Câmara', 'Os operadores de câmara instalam e operam as câmaras digitais para gravar filmes cinematográficos nacionais ou programas de televisão. Trabalham em conjunto com o realizador, o diretor da fotografia ou o cliente privado. Os operadores de câmara dão conselhos sobre a forma de gravar as cenas aos atores, ao realizador e a outros operadores de câmara.', 'released', '["Operador de Câmara", "Operadora de Câmara"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/6fefa90d-9a71-49c6-be92-52397e9795e6', 'Compilador de Apostas', 'Os compiladores de apostas compilam as probabilidades nos jogos de azar. São empregados por um corretor de apostas, «betting exchange», lotarias e serviços digitais/em linha, bem como casinos, que estabelecem as probabilidades para eventos (tais como resultados desportivos) para os clientes realizarem apostas. Além dos mercados de preços, também participam em qualquer atividade relativa aos aspetos comerciais do jogo, tais como a monitorização das contas dos clientes e a rendibilidade das suas operações. Poderá ser necessário um compilador de apostas para monitorizar a posição financeira em que o corretor de apostas se encontra e para ajustar a sua posição (e probabilidades) em conformidade. Podem também ser consultados sobre a aceitação ou não de uma aposta.', 'released', '["Compiladora de Apostas", "Compilador de Apostas"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/7005c266-d1a9-42ac-8c36-b42d5d755463', 'Técnico de Esterilização', 'Os técnicos de esterilização asseguram a descontaminação dos dispositivos médicos em conformidade com procedimentos de higiene rigorosos. Desmontam e remontam equipamento médico sofisticado através de esterilização, limpeza e reembalagem do mesmo para utilização posterior, sob supervisão, seguindo as ordens do médico ou de outro pessoal médico qualificado.', 'released', '["Técnica de Esterilização", "Técnico de Esterilização"]'::jsonb, '5329'),
  ('http://data.europa.eu/esco/occupation/70182f44-e444-4bf3-940f-0c054c1d5917', 'Investigador nas Áreas dos Têxteis, Couro e Calçado', 'Os investigadores nas áreas dos têxteis, couro e calçado combinam conhecimentos das ciências dos materiais, da química, da física, das tecnologias de processamento, da gestão e da engenharia, a fim de contribuir para inovações futuras no domínio dos têxteis, do vestuário, do couro e do calçado. Colaboram em projetos multidisciplinares a fim de combinar as descobertas de um conjunto diversificado de domínios científicos para o desenvolvimento de produtos.', 'released', '["Investigador nas Áreas dos Têxteis, Couro e Calçado", "Investigadora nas Áreas dos Têxteis, Couro e Calçado"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/701f9161-72e4-4ff3-a9e8-8e6352664ef0', 'Podologista de Gado', 'Os podologistas de gado são especialistas no tratamento dos cascos do gado, em conformidade com os eventuais requisitos regulamentares impostos pela autoridade jurídica nacional.;', 'released', '["Técnica em Podologia de Gado", "Técnico em Podologia de Gado", "Auxiliar em Podologia de Gado"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/7052fd94-f563-46a9-8e2d-cba6c20f3e71', 'Operador de Linhas Elétricas', 'Os operadores de linhas elétricas procedem à construção e manutenção e cabos elétricos e cabos de comando em linhas elétricas. Também ligam e reparam cabos elétricos ligando os clientes à rede de eletricidade.', 'released', '["Operadora de Linhas Elétricas", "Operador de Linhas Elétricas"]'::jsonb, '7413'),
  ('http://data.europa.eu/esco/occupation/706e8b26-befb-429b-b71d-f72fad1bae12', 'Operador de Instalação de Branqueamento', 'Os operadores de instalação de branqueamento retiram os revestimentos ou as peles das amêndoas e dos frutos de casca rija em geral. Cortam as folhas e as impurezas da matéria-prima e controlam o fluxo de frutos de casca rija, sementes e/ou folhas no processo. Se necessário, utilizam a pressão e a temperatura para branquear a matéria-prima.', 'released', '["Operadora de Instalação de Branqueamento", "Operador de Instalação de Branqueamento", "Operador de Branqueamento", "Operadora de Branqueamento"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/7086d0ca-1e77-4690-89c9-7ed1a0478fa3', 'Especialista em Qualidade de Dados', 'Os especialistas em qualidade de dados analisam os dados de uma organização a fim de aferir a sua exatidão, recomendam a implementação de melhorias aos sistemas de registro e aos processos de aquisição de dados e avaliam a integridade dos dados de referência e históricos. Além disso, elaboram documentos e mantêm objetivos e normas de qualidade dos dados, supervisionam a política de privacidade dos dados de uma organização e controlam a conformidade dos fluxos de dados com as normas de qualidade dos dados.', 'released', '["Perita em Qualidade de Dados", "Consultor de Qualidade de Dados", "Perita em Qualidade dos Dados", "Consultora de Qualidade dos Dados", "Perito em Qualidade dos Dados", "Consultor de Qualidade dos Dados", "Perito em Qualidade de Dados", "Especialista em Qualidade de Dados", "Consultora de Qualidade de Dados"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/709170ae-2b9a-4e7a-8201-260da7211898', 'Operador de Máquina de Enlatamento de Peixe', 'Os operadores de máquina de enlatamento de peixe colocam em salmoura, cozinham e a embalam o peixe. Esterilizam as linhas das máquinas de enlatamento de peixe e introduzem peixes em tanques, uma vez descabeçados e esviscerados. Utilizam fogões para pré-aquecer o peixe e enchem as latas manualmente ou mecanicamente com peixe, azeite ou outros produtos.', 'released', '["Conserveira de Peixe", "Operador de Máquina de Enlatamento de Peixe", "Conserveiro de Peixe", "Operadora de Máquina de Enlatamento de Peixe"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/70b5896f-988e-4084-9c19-2c82bd5cc9a5', 'Jornalista Esportivo', 'Os jornalistas desportivos investigam e redigem artigos sobre eventos desportivos e atletas para jornais, revistas, televisão e outros meios de comunicação social. Realizam entrevistas e participam em eventos.', 'released', '["Jornalista Esportivo", "Jornalista Esportiva"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/7109cdfd-1618-43b6-8317-8dc90fa583e6', 'Operador de Máquinas de Fabricação de Péletes de Madeira', 'Os operadores de máquinas de fabrico de péletes de madeira operam um moinho de martelos para transformar os resíduos de madeira em péletes para serem utilizados como combustível. O produto triturado é prensado através de um molde, produzindo a forma e o tamanho normalizados de um pélete.', 'released', '["Operadora de Máquinas de Fabricação de Péletes de Madeira", "Operador de Máquinas de Fabricação de Péletes de Madeira"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/7153a12d-85e0-4123-87e9-46bb1a2dc929', 'Hospedeiro de Terra', 'Os hospedeiros de terra auxiliam os passageiros dos transportes ferroviários antes do embarque. Fazem o registo do embarque dos passageiros e também desempenham funções de serviço ao cliente, tais como a reserva de bilhetes de comboio e ajudam os passageiros a pedir reembolsos após um atraso ou cancelamento.', 'released', '["Hospdedeita de Terra", "Hospedeiro de Terra", "Hospedeira de Terra"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/715b902f-b1b6-4366-afc6-ddb8ab715229', 'Inspetor Agrícola', 'Os inspetores agrícolas controlam as operações agrícolas em explorações e outras instalações agrícolas. Inspecionam atividades, tais como medidas de saúde e segurança, custos e processos de produção, a fim de assegurar que os trabalhadores e as suas atividades cumprem a legislação e as normas adequadas. Os inspetores agrícolas também analisam e comunicam as suas conclusões.', 'released', '["Inspetor Agrícola", "Inspetora Agrícola"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/716df735-77eb-47c8-8c06-d86e46903989', 'Engenheiro de Sistemas de Domótica', 'Os engenheiros de sistemas de domótica são responsáveis pela concepção, integração e testes de aceitação de sistemas de domótica (aquecimento, ventilação e ar condicionado, iluminação, sombreamento solar, irrigação, segurança, etc.), que integram dispositivos conectados e aparelhos inteligentes em residências. Colaboram com as principais partes interessadas para garantir a obtenção dos resultados desejados do projeto, incluindo a concepção, a configuração, o aspeto visual e a programação dos componentes.;', 'released', '["Engenheiro de Domótica", "Engenheiro de Projeto de Casa Inteligente", "Designer de Casa Inteligente", "Integrador de Automação Residencial", "Engenheiro de Plataforma de Automação Residencial", "Engenheira de Software para Casa Inteligente", "Especificador de Automação Residencial", "Engenheira de Projeto de Casa Inteligente", "Engenheira de Domótica", "Engenheiro de Software para Casa Inteligente", "Engenheira de Plataforma de Automação Residencial", "Engenheira de Sistemas de Domótica"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/7180a7be-68cd-4636-8c12-706722ad8862', 'Operador de Revelação de Fotografias', 'Os operadores de revelação de fotografias utilizam produtos químicos, instrumentos e técnicas de fotografia de câmara escura em salas especializadas, para revelar películas fotográficas em imagens visíveis.', 'released', '["Operadora de Fotografias", "Técnico de Laboratório Fotográfico", "Operador de Revelação de Fotografias", "Técnica de Laboratório Fotográfico", "Operadora de Revelação de Fotografias"]'::jsonb, '8132'),
  ('http://data.europa.eu/esco/occupation/71898b81-fc2f-4a97-826d-f45e49a8160a', 'Assistente de Direção de Imagem', 'Os assistentes de direção de imagem são responsáveis pela organização, programação e planejamento do elenco, da equipe e das atividades num cenário. Prestam assistência aos realizadores, controlam os orçamentos e asseguram que todas as atividades de produção decorrem de acordo com o calendário previsto.', 'released', '["Assistentea de Direção de Imagem"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/718bba63-75b7-4b3a-9912-e201b729fe4c', 'Montador de Baterias', 'Os técnicos de montagem de baterias soldam e montam componentes de baterias, como as peças eletrônicas, a cablagem e o invólucro das células, bem como os módulos de baterias, numa instalação de fabrico.', 'released', '["Montador de Baterias", "Montador de Componentes de Baterias", "Montadora de Componentes de Baterias", "Montadora de Baterias"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/719f101d-1866-49d3-8d5c-2256f606a8b9', 'Gestor de Transformação Digital', 'Os gestores de transformação digital são profissionais responsáveis pela aceleração da transformação digital nas empresas, através da implantação de iniciativas de tendências emergentes e estratégias digitais no seio de uma organização. Além disso, identificam novas oportunidades de negócio no domínio da inovação sustentável e elaboram orientações para assegurar uma transição qualificada para os processos empresariais de tecnologia mais recente. Os gestores de transformação digital traduzem os requisitos empresariais e as necessidades do mercado em soluções digitais.', 'released', '["Gestor de Transformação Digital", "Gestora de Transformação Digital", "Gerente"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/71a98a24-e02b-4ba6-b4df-6556d7ae98cc', 'Operador de Máquinas de Fabricação de Artigos em Papel', 'Os operadores de máquinas de fabrico de artigos em papel trabalham com máquinas que realizam uma ou mais operações em papel, para o tornar adequado para mercados específicos, tais como orifícios de perfuração, perfuração, dobragem e compilação com uma folha de carbono revestida.', 'released', '["Operador de Máquinas de Fabricação de Artigos em Papel", "Operadora de Máquinas de Fabricação de Artigos em Papel"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/71bac871-7594-4d86-a19f-592079bd8154', 'Vendedor de Materiais de Construção', 'Os vendedores de materiais de construção vendem materiais de construção em lojas especializadas.', 'released', '["Vendedor de Materiais de Construção", "Vendedora de Materiais de Construção"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/71c3a49a-e55e-42ce-bd3f-31f37d3cfab6', 'Agente de Prevenção de Perdas em Estabelecimentos Comerciais', 'Os agentes de prevenção de perdas em estabelecimentos comerciais controlam as atividades em estabelecimentos comerciais a fim de prevenir e detectar furtos. A partir do momento em que a pessoa é capturada, tomam todas as medidas legais, inclusive informar a polícia.', 'released', '["Agentea de Prevenção de Perdas em Estabelecimentos Comerciais"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/71e4891f-48a6-435f-8897-208969fb4e44', 'Supervisor de Dragagem', 'Os supervisores de dragagem controlam as operações de dragagem. Garantem que as operações decorrem de acordo com os regulamentos e tomam decisões rápidas para resolver os problemas.', 'released', '["Supervisora de Dragagem", "Supervisor de Dragagem"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/71f09c8b-a172-408c-b9e7-32e580e39ff6', 'Médico Generalista', 'Os médicos generalistas promovem a saúde, previnem e identificam problemas de saúde, diagnosticam e tratam doenças e promovem a recuperação de doenças físicas e mentais e de todas as espécies, independentemente da idade, do sexo ou do tipo de problema de saúde.', 'released', '["Médica Generalista", "Médico Generalista"]'::jsonb, '2211'),
  ('http://data.europa.eu/esco/occupation/72149e37-f4f4-4570-8c17-27444160aa16', 'Vendedor de Calçado e Acessórios em Couro', 'Os vendedores de calçado e acessórios em couro vendem calçado em lojas especializadas.', 'released', '["Vendedor de Calçado e Acessórios em Couro", "Vendedora de Calçado e Acessórios em Couro"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/7226c10f-701b-4711-8843-140aace12c6f', 'Vereador', 'Os vereadores representam os residentes de uma cidade na câmara municipal e exercem funções legislativas locais. Analisam as preocupações dos residentes e respondem de forma adequada às mesmas, e representam também os programas e políticas do seu partido político na câmara municipal. Comunicam com funcionários governamentais para assegurar que a cidade e a sua agenda política têm representação, e supervisionam todas as operações que são da responsabilidade da câmara municipal.', 'released', '["Autarca", "Vereador", "Membro do Gabinete", "Vereadora"]'::jsonb, '1111'),
  ('http://data.europa.eu/esco/occupation/7235d075-ecf6-42ba-8a60-d7e79bbce152', 'Operador de Prensa de Fruta', 'Os operadores de prensa de fruta operam prensas elétricas para extrair o sumo da fruta. Para o efeito, espalham a fruta de forma regular no tecido antes de utilizar a prensa e mantêm sacos de filtração entre as secções nas máquinas prontos para o processo de extração. São responsáveis pela remoção dos sacos de filtração ou puxam os carrinhos da prensa e deitam os resíduos de polpa de fruta em contentores.', 'released', '["Operadora de Prensa de Fruta", "Prensadora de Fruta", "Operadora de Instalação de Prensagem de Fruta", "Operador de Instalação de Prensagem de Fruta", "Prensador de Fruta", "Operador de Prensa de Fruta"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/72381086-cb6e-455e-a40b-ccb26550aab6', 'Operador de Instalações de Produção de Eletricidade', 'Os operadores de instalações de produção de eletricidade efetuam a manutenção e operam os equipamentos de centrais elétricas e de outras instalações de produção de energia. Procedem à reparação de anomalias, à operação das máquinas diretamente ou a partir de uma sala de controlo e ao tratamento de materiais relacionados com a produção de eletricidade, em conformidade com os procedimentos em matéria de segurança e ambiente. Facilitam a interação entre as instalações de produção de energia elétrica, assegurando a segurança da distribuição.', 'released', '["Operador de Instalações de Produção de Eletricidade", "Operadora de Instalações de Produção de Eletricidade"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/72413d91-f212-4ad6-bf95-8b78a37c041a', 'Técnico de Depilação', 'Os técnicos de depilação fornecem serviços cosméticos aos clientes, eliminando o pelo indesejado em várias partes do corpo. Podem utilizar diferentes técnicas para a depilação temporária, tais como as técnicas de epilação e de depilação, ou métodos de remoção permanente do pelo, tais como eletrólise ou luz intensa pulsada.', 'released', '["Técnica de Depilação", "Depilador", "Técnico de Depilação", "Depiladora"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/725090a7-9943-4dae-8079-a6999d21ddba', 'Gestor de Clientes', 'Os gestores de clientes atuam como intermediários entre uma empresa e os seus clientes. Asseguram a satisfação dos clientes, fornecendo-lhes orientações e explicações sobre as suas contas e os serviços recebidos pela empresa. Podem desempenhar igualmente outras tarefas, como o desenvolvimento de planos ou a apresentação de propostas.', 'released', '["Gestora de Clientes", "Gestor de Clientes", "Gerente"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/7259dc48-004a-4ceb-aa4e-5bbd548c2397', 'Técnico de Calefação', 'Os técnicos de calefação procedem à instalação e à manutenção de equipamentos de calefação e ventilação a gás, eletricidade, petróleo, combustível sólido e múltiplos combustíveis, como sistemas autónomos de calefação e ventilação ou instalados em máquinas e equipamentos de transporte. Seguem as instruções e os esquemas, procedem à manutenção e à reparação dos sistemas e realizam controlos de segurança.;', 'released', '["Técnico de Calefação", "Técnica de Calefação"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/72628f3a-fd49-499a-9741-870b0a1fcef2', 'Matemático', 'Os matemáticos estudam e aprofundam as teorias matemáticas, a fim de expandir o conhecimento e encontrar novos paradigmas no terreno. Podem aplicar esse conhecimento aos desafios colocados por projetos científicos e de engenharia, a fim de assegurar que as medições, as quantidades e as leis matemáticas comprovam a sua viabilidade.', 'released', '["Matemático", "Matemática"]'::jsonb, '2120'),
  ('http://data.europa.eu/esco/occupation/7284ccbf-e2fd-4e2f-8bbf-bc54eab610d5', 'Gestor de Patrimônio', 'Os gestores de património controlam e gerem fundos fiduciários pessoais. Interpretam adequadamente documentação fiduciária e testamentária, interagem com os consultores financeiros para definir a meta de investimento com vista a alcançar os objetivos dos fundos, coordenam a compra e venda de valores mobiliários com os gestores de conta e analisam regularmente as contas dos clientes.', 'released', '["Gestora de Património", "Gestor de Fortunas", "Gestora de Fortunas", "Gestor de Património", "Gerente", "Gestora de Patrimônio"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/728b9e5b-3da4-4dbd-ac36-614ebdb6c8c0', 'Operador de Máquinas de Destintar por Flutuação', 'Os operadores de máquinas de destintar por flotação cuidam de um reservatório que recebe papel reciclado e o mistura com água. A solução é levada a uma temperatura de cerca de 50 °C, após a qual as bolhas de ar são sopradas para o reservatório. As bolhas de ar elevam as partículas de tinta para a superfície da suspensão e formam uma espuma que é depois removida.', 'released', '["Operador de Máquinas de Destintar por Flutuação", "Operadora de Máquinas de Destintar por Flutuação"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/72913ee1-1696-4d74-b26f-681d17887c58', 'Coordenador de Planos de Resposta de Emergência', 'Os coordenadores de planos de resposta de emergência analisam riscos potenciais, tais como catástrofes e emergências, para uma comunidade ou instituição e elaboram uma estratégia para reagir a esses riscos. Definem orientações para a resposta a uma situação de emergência, a fim de reduzir os seus efeitos. Dão formação às partes em risco sobre essas orientações. Além disso, testam planos de resposta e asseguram que os fornecimentos e equipamentos necessários estão em conformidade com a regulamentação em matéria de saúde e segurança.', 'released', '["Coordenadora de Planos de Resposta de Emergência", "Coordenador de Planos de Resposta de Emergência"]'::jsonb, '2263'),
  ('http://data.europa.eu/esco/occupation/72add02e-ae39-4dfb-8047-ced4c1a347f5', 'Editor de Imagens', 'Os editores de imagens selecionam e aprovam fotografias e ilustrações para jornais, revistas especializadas e revistas. Os editores de imagens certificam-se de que as fotografias são entregues atempadamente para publicação.', 'released', '["Editor de Imagens", "Editora de Imagens"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/72bcb223-da77-4ed5-a03a-796fd5ece728', 'Professor de Artes Visuais', 'Os professores de artes visuais ensinam aos alunos diferentes estilos de artes visuais, como o desenho, a pintura e a escultura, num contexto recreativo. Proporcionam aos alunos uma noção da história da Arte, mas centram-se sobretudo numa abordagem prática na suas aulas, nas quais ajudam os alunos a experimentar e a dominar diferentes técnicas artísticas e a desenvolver o seu próprio estilo.', 'released', '["Professor de Expressão Artística", "Professora de Pintura", "Professora de Expressão Artística", "Professor de Escultura", "Professora de Artes Visuais", "Professora de Escultura", "Professor de Pintura", "Professor de Artes Visuais"]'::jsonb, '2355'),
  ('http://data.europa.eu/esco/occupation/72d03aad-2003-404e-ae71-a37206e3566b', 'Artesão de Artigos de Marroquinaria', 'Os artesãos de artigos de marroquinaria fabricam à mão artigos de marroquinaria ou partes de artigos de marroquinaria, de acordo com as especificações do cliente ou com o seu próprio desenho. Procedem à reparação de artigos de marroquinaria, tais como sapatos, sacos e luvas.', 'released', '["Artesão de Artigos de Marroquinaria", "Artesã de Artigos de Marroquinaria", "Artesãa de Artigos de Marroquinaria"]'::jsonb, '7318'),
  ('http://data.europa.eu/esco/occupation/72d1e9ca-294c-4349-90ed-f99541d447d0', 'Diretor de Distribuição de Produtos Especializados', 'Os diretores de distribuição de produtos especializados planificam, coordenam e gerem a distribuição de produtos especializados a vários pontos de venda. Supervisionam os trabalhadores e asseguram que as operações funcionam eficientemente, como a armazenagem, o transporte e a entrega de produtos especializados.', 'released', '["Diretora de Distribuição de Produtos Especializados", "Diretor de Distribuição de Produtos Especializados"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/72d4b5a3-5458-41e5-8b4e-cb4fb3fd0fbc', 'Especialista em Import-Export de Açúcar, Chocolate e Produtos de Confeitaria', 'Os especialistas em import-export de açúcar, chocolate e produtos de confeitaria possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Açúcar, Chocolate e Produtos de Confeitaria"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/72f4abfe-5337-49be-b9b8-32096fc2ca1f', 'Técnico de Instrumentos', 'Os técnicos de instrumentos auxiliam e apoiam os músicos antes, durante e após o espetáculo, a fim de assegurar que os instrumentos e o equipamento ligado, a linha de retorno, estejam instalados corretamente. Procedem à manutenção, controlo e reparação de instrumentos e prestam assistência com mudanças rápidas. ;', 'released', '["Técnica de Instrumentos", "Técnico de Instrumentos"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/7309ab2d-e2ba-4ccb-b658-6b0a8bd8c4eb', 'Operador de Torrefação de Malte', 'Os operadores de torrefação de malte operam máquinas e equipamento enquanto controlam se a operação de torrefação de cereais se mantém dentro dos parâmetros de torrefação especificados.', 'released', '["Operador de Máquina de Torrefação de Malte", "Torrador de Malte", "Operadora de Torrefação de Malte", "Torradora de Malte", "Operadora de Máquina de Torrefação de Malte", "Operador de Torrefação de Malte"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/731ecac4-06e8-4ec2-a559-101fecbd9183', 'Empregado de Quartos em Hotelaria', 'Os empregados de quartos em hotelaria limpam, arrumam e reabastecem os quartos, bem como outros espaços públicos, conforme lhes for indicado.', 'released', '["Empregada de Quartos em Hotelaria", "Empregado de Limpeza", "Camareira", "Empregada de Limpeza", "Empregado de Quartos em Hotelaria", "Camareiro"]'::jsonb, '9112'),
  ('http://data.europa.eu/esco/occupation/731f38f1-b08f-4dd5-a25e-f8627c038273', 'Testador de Integração Informática', 'Os testadores de integração informática realizam testes em grupos de componentes, unidades ou até mesmo aplicações de sistemas. Agrupam-nos em agregados maiores e aplicam-lhes planos de testes de integração. Supervisionam a complexidade das relações entre os diferentes componentes.', 'released', '["Testadora de Integração", "Responsável por Testes de Integração", "Testador de Integração", "Responsável Pelos Testes de Integração", "Testadora de Integração Informática"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/7324e9f5-0f94-497e-af2f-42142e939a94', 'Bordadeira', 'As bordadeiras/os bordadeiros realizam bordados de desenhos e decoram superfícies têxteis à mão ou utilizando uma máquina de bordar. Aplicam uma série de técnicas de pontos tradicionais para produzir desenhos complexos em vestuário, acessórios e artigos de decoração da casa. As bordadeiras/os bordadeiros profissionais combinam as competências de costura tradicionais com os atuais programas de software para conceber e construir ornamentos num artigo.', 'released', '["Bordadeira de Casa", "Bordador", "Bordadora", "Bordadeira", "Bordadeiro de Casa", "Bordadeiro"]'::jsonb, '7533'),
  ('http://data.europa.eu/esco/occupation/73270b73-8c71-445f-a8d3-4647b1ae38d0', 'Operador de Máquinas de Fabricação de Sacos de Papel', 'Os operadores de máquinas de fabrico de sacos de papel operam uma máquina que recebe papel, dobra-o e cola-o para produzir sacos de papel de vários tamanhos, formas e graus de resistência.', 'released', '["Operadora de Máquinas de Fabricação de Sacos de Papel", "Operador de Máquinas de Fabricação de Sacos de Papel"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/73357956-f607-4baa-9ce6-03beb9b39da2', 'Operador de Vendas', 'Os operadores de vendas tratam das vendas, selecionam canais de entrega, executam pedidos e informam os clientes sobre o envio e os procedimentos. Comunicam com os clientes para tratar de informações em falta e/ou pormenores adicionais.', 'released', '["Operadora de Vendas", "Operador de Vendas", "Sales"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/733d65ac-250b-45d7-ba3c-cc5f48e9e11d', 'Operador de Máquina de Marcação a Laser', 'Os operadores de máquina de marcação a laser instalam e cuidam de máquinas de marcação a laser ou máquinas de gravar concebidas para entalhar com precisão na superfície de uma peça metálica, utilizando um controlador móvel e um ponto de feixe laser para gravar fixado a essa peça, traçando padrões na superfície da peça metálica. Efetuam ajustes à máquina em termos de intensidade, direção e velocidade do feixe laser. Também asseguram que a mesa de laser, utilizada para realizar a marcação a laser e guiar o feixe laser, esteja corretamente instalada.', 'released', '["Operador de Máquina de Marcação a Laser", "Operadora de Máquina de Marcação a Laser"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/734bb387-ea3a-4c62-abc1-05f894d51921', 'Professor de Cursos Profissionais de Técnicas Laboratoriais', 'Os professores de cursos profissionais de técnicas laboratoriais formam os alunos no seu domínio de estudos especializado, as técnicas laboratoriais, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com as técnicas laboratoriais. Os professores de cursos profissionais de técnicas laboratoriais acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio das técnicas laboratoriais através de trabalhos, testes e exames.', 'released', '["Professora de Cursos Profissionais de Técnicas Laboratoriais", "Professor de Cursos Profissionais de Técnicas Laboratoriais"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/737c1795-844b-43ad-95b2-1bf0e8c14ddf', 'Operador de Instalações de Produção de Vapor', 'Os operadores de instalações de produção de vapor procedem à operação e manutenção de equipamentos mecânicos, tais como motores fixos e caldeiras, para fornecer serviços públicos para uso doméstico ou industrial. Acompanham os procedimentos para garantir o cumprimento das regras de segurança e realizam testes para garantir a qualidade.', 'released', '["Operadora de Instalações de Produção de Vapor", "Operador de Instalações de Produção de Vapor"]'::jsonb, '8182'),
  ('http://data.europa.eu/esco/occupation/738257d3-7e56-4745-9b2e-014e60d41d48', 'Assistente Social em Unidades Hospitalares', 'Os assistentes sociais em unidades hospitalares prestam aconselhamento aos doentes e às suas famílias, ajudando-os a lidar melhor com a doença, com as emoções em torno do diagnóstico e com problemas sociais e financeiros. Trabalham em cooperação com médicos, enfermeiros e outros profissionais de saúde, sensibilizando-os para os aspetos emocionais de um doente. Atuam como elo de ligação entre os doentes e o pessoal médico. Os assistentes sociais em unidades hospitalares apoiam também os doentes e as suas famílias aquando da alta hospitalar.', 'released', '["Assistentea Social em Unidades Hospitalares"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/73856e9e-eca2-44c2-bb3c-aaedf4b25979', 'Diretor de Produtos de Seguros', 'Os diretores de produtos de seguros estabelecem e orientam o desenvolvimento de novos produtos de seguros, na sequência da política de ciclo de vida dos produtos e da estratégia geral de seguro. Além disso, coordenam as atividades de comercialização e venda relacionadas com os produtos de seguros específicos da empresa. Os diretores de produtos de seguros informam os seus diretores de vendas (ou o departamento de vendas) sobre os seus produtos de seguros recentemente desenvolvidos.', 'released', '["Diretor de Produtos de Seguros", "Mediadora de Seguros", "Gestor de Produtos de Seguros", "Mediador de Seguros", "Diretora de Produtos de Seguros", "Gestora de Produtos de Seguros"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/73b10c97-b003-45dc-a36d-c1d585c04be1', 'Empreendedor Social', 'Os empreendedores sociais criam modelos de produtos ou serviços inovadores para dar resposta a desafios sociais e ambientais, prosseguindo, através dos seus lucros, uma missão social que beneficia uma comunidade mais vasta ou o ambiente. Utilizam frequentemente um sistema de tomada de decisões mais democrático, envolvendo de perto as partes interessadas, e esforçam-se por efetivar mudanças a nível dos sistemas, influenciando as políticas, a evolução do mercado e as mentalidades.;', 'released', '["Fundador de Empreendimento de Negócio Social", "Empreendedor Verde", "Fundador de Empresa Social", "Fundador de Negócios Sociais", "Eco-Empreendedor", "Empreendedora Social"]'::jsonb, '1120'),
  ('http://data.europa.eu/esco/occupation/73bcde7c-bc34-485d-a7af-7b94fc43f61b', 'Lapidador de Pedras Preciosas', 'Os lapidadores de pedras preciosas utilizam máquinas de corte e ferramentas para cortar ou entalhar diamantes e outras pedras preciosas de acordo com diagramas e padrões, tendo em conta as diferentes especificações. São especialistas no fabrico de joias, tais como anéis, broches, correntes e pulseiras de pedras preciosas.', 'released', '["Ourives", "Lapidador de Pedras Preciosas", "Lapidadora de Pedras Preciosas"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/73bdadf0-2175-4097-8f4d-b6dabeb0a030', 'Diretor de Distribuição — Frutas e Hortaliças', 'Os diretores de distribuição — frutos e produtos hortícolas planificam a distribuição de frutas e produtos hortícolas a diversos pontos de venda.', 'released', '["Diretora de Distribuição — Frutos e Produtos Hortícolas", "Diretora de Logística — Frutos e Produtos Hortícolas", "Diretor de Distribuição — Frutos e Produtos Hortícolas", "Diretor de Logística — Frutos e Produtos Hortícolas", "Diretora de Distribuição — Frutas e Hortaliças"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/73c3f018-71ce-4dc1-abdd-14cea7873717', 'Senador', 'Os senadores exercem funções legislativas a nível do governo central, nomeadamente em matéria de reformas constitucionais, a negociação de atos legislativos e a resolução de conflitos entre outras instituições governamentais.', 'released', '["Senador", "Senadora", "Congressista"]'::jsonb, '1111'),
  ('http://data.europa.eu/esco/occupation/73ceb2f9-18e3-4cfe-9c06-e9fb31ece440', 'Diretor de Investigação e Desenvolvimento', 'Os diretores de investigação e desenvolvimento coordenam os esforços de cientistas, investigadores académicos, criadores de produtos e analistas de mercado no sentido da criação de novos produtos, da melhoria das atividades correntes ou de outras atividades de investigação, incluindo a investigação científica. Gerem e planificam atividades de investigação e desenvolvimento de uma organização, especificam objetivos e requisitos orçamentais e gerem o pessoal.', 'released', '["Diretor de Investigação e Desenvolvimento", "Diretora de Investigação e Desenvolvimento"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/73d3bee2-7c5e-4de2-8dd9-67241615dfd3', 'Montador de Produtos em Borracha', 'Os montadores de produtos em borracha fabricam produtos em borracha, tais como garrafas de água, barbatanas e luvas de borracha. Fixam ponteiras, fivelas e cintas em produtos de borracha, bem como fitas de tecido à volta de fechos e ponteiras.', 'released', '["Montadora de Produtos em Borracha", "Montador de Produtos em Borracha"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/73d3ce3c-296c-4f85-9381-2eed6f3ae5fa', 'Diretor Geral dos Transportes por Vias Navegáveis Interiores', 'Os diretores gerais dos transportes por vias navegáveis interiores coordenam as atividades administrativas e de despacho que ocorrem no contexto do transporte por vias navegáveis interiores. Verificam a disponibilidade, asseguram a ligação com os clientes, gerem os orçamentos e supervisionam as operações de um ponto de vista econômico.', 'released', '["Diretora Geral dos Transportes por Vias Navegáveis Interiores", "Diretor Geral dos Transportes por Vias Navegáveis Interiores"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/73d77554-2016-46fa-ac3d-44a02e8d1a89', 'Trabalhador da Construção de Esgotos', 'Os trabalhadores da construção de esgotos instalam as condutas de esgotos para o transporte de águas residuais para fora das estruturas e para um curso de água ou pra uma estação de tratamento. Escavam as valas e colocam as condutas, certificando-se de que têm um ângulo correto e estão ligadas de forma estanque. Os trabalhadores da construção de esgotos também constroem outras infraestruturas de esgotos, tais como caixas de visita, e procedem à manutenção e reparação dos sistemas existentes.', 'released', '["Trabalhadora da Construção de Esgotos", "Trabalhador da Construção de Esgotos"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/73e776fb-4d99-4031-bad4-7716f121155d', 'Designer de Interiores', 'Os designers de interiores concebem ou renovam espaços interiores, incluindo alterações estruturais, instalações e acessórios, iluminação, esquemas de cor e mobiliário. Combinam a utilização eficiente e funcional do espaço com uma compreensão da estética.', 'released', NULL, '3432'),
  ('http://data.europa.eu/esco/occupation/74332fd0-4a50-464e-9116-98fa9b8127ac', 'Operador de Distribuidor de Energia Elétrica', 'Os operadores de distribuidores de energia elétrica operam e efetuam a manutenção de equipamentos de distribuição de energia a partir do sistema de transmissão para o consumidor. Supervisionam as operações de manutenção e reparação de linhas elétricas e asseguram a satisfação das necessidades de distribuição. Tomam igualmente medidas relativas a anomalias do sistema de distribuição, que causam problemas como as interrupções do serviço.', 'released', '["Operadora de Distribuidor de Energia Elétrica", "Operador de Distribuidor de Energia Elétrica"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/7443811e-6760-44a2-af95-1b9c791733a8', 'Operador de Pistola de Pintura', 'Os operadores de pistola de pintura utilizam pistolas de pintura concebidas para fornecer a peças acabadas de metal, madeira ou plástico uma demão de acabamento duro e resistente, através de um revestimento de verniz ou de tinta que pode ser mate, lustroso ou muito brilhante, mas sempre concebido para superfícies duras.', 'released', '["Operadora de Pistola de Pintura", "Operador de Pistola de Pintura"]'::jsonb, '7132'),
  ('http://data.europa.eu/esco/occupation/745c8bb3-b50b-4380-9377-1b68a6576986', 'Controlador de Processos na Indústria Têxtil', 'Os controladores de processos na indústria têxtil executam operações e funções técnicas em vários aspetos da concepção, da produção e do controlo da qualidade dos produtos têxteis, bem como o controlo dos custos dos processos. Utilizam ferramentas de fabrico assistido por computador (CAM) e de fabrico integrado por computador (CIM), com vista a garantir a conformidade de todo o processo de produção com as especificações. Comparam e trocam processos individuais com outros departamentos (por exemplo, o serviço responsável pelo cálculo dos custos) e tomam as medidas adequadas. Analisam a estrutura e as propriedades das matérias-primas utilizadas nos têxteis e ajudam a preparar as especificações para a sua produção, bem como a analisar e interpretar os dados dos ensaios.', 'released', '["Controladora de Processos na Indústria Têxtil", "Controlador de Processos na Indústria Têxtil"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/74cbe6fb-336f-4f3f-8c8f-7645b279a231', 'Mordomo doméstico/Governanta Doméstica', 'Os mordomos domésticos servem nas refeições oficiais, acompanham as preparações das refeições e colocação da mesa e gerem o pessoal doméstico. Também podem oferecer assistência pessoal com a reserva de serviços de viagens e de restaurantes, o desempenho funções de criado de quarto e cuidando da roupa.', 'released', '["Governanta Doméstica", "Mordomo Doméstico", "Mordoma doméstico/Governanta Doméstica"]'::jsonb, '5152'),
  ('http://data.europa.eu/esco/occupation/74d47633-8e9e-4e08-9cba-d2292c211218', 'Consultor em Segurança de Produtos Perigosos', 'Os consultores em segurança de produtos perigosos inspecionam e fazem recomendações de transporte em conformidade com os regulamentos europeus relativos ao transporte de mercadorias perigosas. Podem aconselhar sobre o transporte de produtos perigosos por via rodoviária, ferroviária, marítima e aérea. Os consultores em segurança de produtos perigosos também elaboram relatórios de segurança e investigam infrações em matéria de segurança. Fornecem aos indivíduos os procedimentos e as instruções a cumprir durante a carga, a descarga e o transporte destes produtos.', 'released', '["Consultora em Segurança de Produtos Perigosos", "Consultor em Segurança de Produtos Perigosos"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/753939ad-b03e-47cd-913b-56f30b5ae8fc', 'Inspetor de Montagem de Produtos', 'Os inspetores de montagem de produtos avaliam os produtos relativamente ao cumprimento de especificações e para detectar eventuais defeitos, em conformidade com os requisitos e as políticas organizacionais dos clientes. Utilizam equipamentos de medição e ensaio para garantir a conformidade com as especificações de engenharia e de fabrico, a qualidade e as normas e regulamentos de segurança. Também fornecem documentação de inspeção pormenorizada e recomendam medidas nos casos em que sejam detectados problemas.', 'released', '["Inspetora de Montagem de Produtos", "Inspetor de Montagem de Produtos"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/754c349d-67d5-48e5-81c1-e84d2fab59d0', 'Aromaterapeuta', 'Os aromaterapeutas utilizam óleos essenciais extraídos de produtos à base de plantas ao nível da pele e das membranas mucosas, com o intuito de melhorar o bem-estar dos clientes. Tratam uma série de doenças e de problemas físicos ou psicológicos, sob supervisão e segundo as indicações de um médico.', 'released', NULL, '2230'),
  ('http://data.europa.eu/esco/occupation/754ce08f-b4d9-4b9c-b9d2-06f15258a3ce', 'Gerente de Banco', 'Os gerentes de banco supervisionam a gestão de uma ou várias atividades bancárias. Definem políticas que promovam operações bancárias seguras, asseguram o cumprimento dos objetivos econômicos, sociais e comerciais e que todos os serviços, atividades e políticas comerciais dos bancos estão em conformidade com os requisitos legais. Além disso, gerem e mantêm uma relação de trabalho eficaz entre o pessoal.', 'released', '["Gerrente de Sucursal de Banco", "Gerente de Banco Privado", "Gerentea de Banco"]'::jsonb, '1346'),
  ('http://data.europa.eu/esco/occupation/7556c748-15b4-4e44-97d9-00d885d4cd7d', 'Conservador', 'Os conservadores organizam e valorizam obras de arte, edifícios, livros e mobiliário. Trabalham numa vasta gama de domínios, como a criação e a implementação de novas coleções de arte, a preservação de edifícios históricos mediante a aplicação de técnicas de restauro, bem como a previsão da conservação de obras literárias, filmes e objetos de valor.', 'released', '["Conservadora", "Conservador"]'::jsonb, '2621'),
  ('http://data.europa.eu/esco/occupation/755c5c5f-2ee3-4487-94db-30ec2ba2e883', 'Técnico de Manutenção de Infraestruturas Ferroviárias', 'Os técnicos de manutenção de infraestruturas ferroviárias realizam inspeções de rotina de vias férreas, linhas elétricas, estações de sinalização, agulhas e outras infraestruturas ferroviárias. São também enviados para reparar defeitos rapidamente, em segurança e em qualquer momento do dia ou da noite.', 'released', '["Técnica de Manutenção de Infraestruturas Ferroviárias", "Técnico de Manutenção de Infraestruturas Ferroviárias"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/7569f423-2c37-49aa-947e-41acb66ec909', 'Engenheiro do Petróleo', 'Os engenheiros do petróleo avaliam os campos de gás e petróleo. Concebem e desenvolvem métodos de extração de petróleo e gás do interior da superfície terrestre. Maximizam a recuperação dos hidrocarbonetos a um custo mínimo, com um impacto mínimo no ambiente.', 'released', '["Engenheira do Petróleo", "Engenheiro do Petróleo"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/757da94f-d1f3-48ad-ac61-74e22bc18cca', 'Especialista em Grafologia', 'Os especialistas em grafologia analisam material escrito ou impresso a fim de extraírem conclusões e elementos de prova sobre as características, a personalidade e as capacidades do autor, bem como sobre a autoria do material. Interpretam a forma das letras, o modo de escrita e os padrões de escrita.', 'released', '["Grafologista"]'::jsonb, '2643'),
  ('http://data.europa.eu/esco/occupation/7591db5b-ee01-4b6b-b626-ddaf892458d4', 'Assistente Social em Situações de Crise e Emergência Social', 'Os assistentes sociais em situações de crise e emergência social prestam apoio e assistência a pessoas com distúrbios físicos ou mentais, procurando dar resposta ao seu sofrimento, dificuldades e instabilidade. Avaliam o nível de risco, mobilizam os recursos para os utentes e estabilizam a situação de crise.', 'released', '["Assistentea Social em Situações de Crise e Emergência Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/75b63949-1b93-4bf2-a777-ccf978dc3e8a', 'Técnico de Energia Solar', 'Os técnicos de energia solar procedem à instalação e manutenção de sistemas que recolhem energia solar. Preparam os dispositivos necessários, muitas vezes em telhados, instalam painéis solares e ligam-nos a um sistema eletrônico que inclui um inversor para ligar os sistemas de energia solar às linhas elétricas.', 'released', '["Técnica de Energia Solar", "Técnico de Energia Solar"]'::jsonb, '7411'),
  ('http://data.europa.eu/esco/occupation/75c5bab4-2546-4ba3-996d-42a9a1bab55d', 'Técnico de Eletrônica Ferroviária', 'Os técnicos de eletrônica ferroviária são responsáveis pela instalação, inspeção, ensaio e manutenção dos sistemas de controlo, rádio, radar, componentes eletrônicos e eletromagnéticos dos comboios.', 'released', '["Técnica de Eletrônica Ferroviária", "Técnico de Eletrônica Ferroviária"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/75f4c7aa-019f-4545-9ce1-2d163fe78580', 'Técnico de Manutenção de Ductos', 'Os técnicos de manutenção de ductos utilizam equipamento diverso para manter os ductos num estado adequado. Realizam controlos para detectar desvios e administram produtos químicos de acordo com as necessidades e com o objetivo de limpeza (por exemplo, eliminação da corrosão).', 'released', '["Técnico de Manutenção de Ductos", "Técnico de Manutenção de Gasodutos", "Técnica de Manutenção de Oleodutos", "Técnica de Manutenção de Gasodutos", "Técnica de Manutenção de Ductos", "Técnico de Manutenção de Oleodutos"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/75fb7771-0403-4116-9c01-9c5717bec600', 'Gerente de Loja de Mobiliário', 'Os gerentes de lojas de mobiliário assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Decoração", "Gerente de Loja de Artigos de Decoração", "Gerente de Loja de Mobiliário e Iluminação", "Gerentea de Loja de Mobiliário"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/760ad7dd-f29d-4e4d-be1f-15100550ab80', 'Fabricante de Moldes CAD para Vestuário', 'Os fabricantes de moldes CAD para vestuário desenham, avaliam, ajustam e modificam moldes de vestuário, planos de corte e arquivos técnicos para todos os tipos de artigos de vestuário utilizando sistemas CAD, agindo como interfaces com operações de impressão, corte e montagem digitais, e conhecendo os requisitos técnicos de qualidade, fabricação e avaliação de custos.;', 'released', '["Fabricantea de Moldes CAD para Vestuário"]'::jsonb, '7532'),
  ('http://data.europa.eu/esco/occupation/7639a601-6db0-41ed-9fb0-813d9b8beb05', 'Técnico de Radiologia', 'Os técnicos de radiologia utilizam uma gama de tecnologias para examinar, tratar e cuidar dos doentes. Trabalham nos domínios da imagiologia médica, da radioterapia e da medicina nuclear e aplicam radiações ionizantes, ultrassons, ressonância magnética e fontes radioativas.', 'released', '["Técnico de Radiologia", "Técnica de Radiologia", "Técnico de Radioterapia", "Técnica de Radioterapia"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/763f82c2-81e3-48d2-9cdf-f532b5016a1f', 'Consultor de Perda de Peso', 'Os consultores de perda de peso assistem os clientes na obtenção e manutenção de um estilo de vida saudável. Aconselham sobre a forma de perder peso, encontrando um equilíbrio entre alimentação saudável e exercício físico. Os consultores de perda de peso definem objetivos juntamente com os clientes e acompanham os progressos realizados durante as reuniões semanais.', 'released', '["Consultor de Nutrição", "Consultora de Nutrição", "Consultor de Perda de Peso", "Consultora de Perda de Peso"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/7642cbcc-9839-47fb-b2cf-d4bb831d6c93', 'Técnico de Audiovisual', 'Os técnicos de audiovisual procedem à instalação, operação e manutenção do equipamento para gravar e editar imagens e som para as emissões de rádio e televisão, em eventos ao vivo e para sinais de telecomunicações.', 'released', '["Técnica de Audiovisual", "Técnico de Audiovisual"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/7648d5d9-cfab-4981-ba82-b66a9a41d37e', 'Engenheiro de Sistemas de Baterias', 'Os engenheiros de sistemas de baterias são profissionais que concebem, testam e desenvolvem sistemas de baterias para várias aplicações. Criam soluções de armazenamento de energia eficientes e econômicas, trabalhando com uma equipe de engenheiros e cientistas. Algumas das soluções destinam-se a veículos elétricos, eletrônica de consumo, armazenamento em rede e outras aplicações. São responsáveis pelo desempenho global do sistema de baterias, que inclui as células da bateria, a eletrônica de controlo e gestão, a gestão térmica e os sistemas de segurança.', 'released', '["Engenheira de Sistemas de Baterias", "Engenheiro de Sistemas de Baterias"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/7664f3e6-b469-4e1a-b52c-8a7ac866eb5a', 'Operador de Máquinas de Fabricação de Tela Metálica', 'Os operadores de máquinas de fabrico de tela metálica instalam e utilizam máquinas de tela metálica, concebidas para produzir tecidos de tela metálica a partir de ligas ou metal dúctil que possam ser estirados para produzir tela.', 'released', '["Operadora de Máquinas de Fabricação de Tela Metálica", "Operador de Máquinas de Fabricação de Tela Metálica"]'::jsonb, '8121'),
  ('http://data.europa.eu/esco/occupation/76884a72-d8b8-4819-bd40-71d6420a9a42', 'Consultor Jurídico', 'Os consultores jurídicos prestam assistência aos advogados na preparação do julgamento ajudando a escolher os membros do júri. Contribuem para o desenvolvimento de estratégias utilizadas durante o julgamento, analisam o comportamento do júri durante o julgamento e aconselham os advogados sobre os processos. Além disso, auxiliam na preparação de testemunhas e na construção de argumentos.', 'released', '["Consultor Jurídico", "Consultora Jurídica", "Consultora Jurídico"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/769159bd-2929-4d40-8aeb-a99a387a0829', 'Montador de Motociclos', 'Os montadores de motociclos fixam peças e componentes de motociclos em conjunto, tais como quadros, rodas, motores, etc. Utilizam ferramentas manuais, ferramentas elétricas e outros equipamentos, tais como máquinas CNC ou robôs. Interpretam os planos técnicos e utilizam equipamento automatizado de montagem para a construção de motociclos. Inspecionam as peças individuais para detectar eventuais avarias e verificam a qualidade das montagens, para garantir que as normas são cumpridas e as especificações são respeitadas.', 'released', '["Montadora de Motociclos", "Montador de Motociclos"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/7696b15a-c52e-4ac5-b38d-9eeb010c5fa3', 'Oficial de Artilharia', 'Os oficiais de artilharia prestam apoio em batalha nos domínios da obtenção de alvos, coordenação da informação, vigilância e armamento. São responsáveis pela tática e pela utilização do armamento no terreno. Também comandam soldados.', 'released', NULL, '0110'),
  ('http://data.europa.eu/esco/occupation/76a1a76c-b014-4600-8901-56cb936de7ed', 'Gestor de Auditores Informáticos', 'Os gestores de auditores informáticos monitoram os auditores informáticos responsáveis pelas realização de auditorias a sistemas de informação, plataformas e procedimentos operacionais em matéria de eficiência, exatidão e segurança, em conformidade com as normas estabelecidas aplicáveis às empresas. Avaliam as infraestruturas de tecnologia da informação em termos de risco para a organização e estabelecem controles para atenuar as perdas. Determinam e recomendam melhorias relativamente aos atuais controles de gestão de riscos e à implementação de alterações ou atualizações dos sistemas.', 'released', '["Gestor de Auditores Informáticos", "Gestor de Auditores de Tecnologias da Informação", "Gestora de Auditores de Tecnologias de Informação e Comunicação", "Gestora de Auditores de Tecnologia da Informação", "Gestor de Auditores de Tecnologia da Informação", "Gestor de Auditores de Tecnologias de Informação e Comunicação", "Gestora de Auditores de Tecnologias da Informação", "Gestora de Auditores Informáticos", "Gerente"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/76a950cb-3def-47f4-895d-555ad138657e', 'Educador Formado na Pedagogia Montessori', 'Os educadores formados na pedagogia Montessori ensinam os alunos através de abordagens que refletem a filosofia e os princípios de Montessori. Centram-se nos modelos de ensino construtivistas e de aprendizagem através da descoberta, através dos quais incentivam os alunos a aprender com as experiências em primeira mão e não através de instrução direta, proporcionando assim aos alunos um nível de liberdade relativamente elevado. Aderem a um programa de estudos específico que respeita o desenvolvimento natural, físico, social e psicológico dos alunos. Além disso, os educadores formados na pedagogia Montessori lecionam turmas com alunos com diferenças de idade de até três anos em grupos bastante grandes, e gerem e avaliam todos os alunos separadamente, de acordo com a filosofia da Montessori.', 'released', '["Educador Montessori", "Educador Formado na Pedagogia Montessori", "Educadora Formada na Pedagogia Montessori", "Educadora do Método Montessori", "Educador do Método Montessori", "Educadora Montessori", "Educadora Formado na Pedagogia Montessori"]'::jsonb, '2342'),
  ('http://data.europa.eu/esco/occupation/76abbb82-c103-4d7a-a4c0-14dba4d6199a', 'Engenheiro Especialista em Finalização de Projetos', 'Os engenheiros especialistas em finalização de projetos supervisionam as fases finais de um projeto quando os sistemas são instalados e testados. Inspecionam o correto funcionamento do equipamento, das instalações e das fábricas para assegurar o cumprimento dos requisitos e das especificações. Realizam as verificações necessárias e aprovam o projeto.', 'released', '["Engenheiro Especialista em Finalização de Projetos", "Engenheira Especialista em Finalização de Projetos"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/76bded28-876a-40b2-9efb-3123c8f14cf6', 'Técnico de Próteses Dentárias', 'Os técnicos de próteses dentárias fabricam dispositivos dentários feitos por medida, como pontes, coroas, próteses dentárias e aparelhos sob a supervisão de dentistas, seguindo as suas instruções e especificações.', 'released', '["Técnico de Próteses Dentárias", "Técnica de Próteses Dentárias"]'::jsonb, '2261'),
  ('http://data.europa.eu/esco/occupation/76deb33d-f9bc-4ca2-a5cc-49c8f5a17f38', 'Artista de Variedades', 'Os artistas de variedades são artistas multidisciplinares que dominam, pelo menos, duas das seguintes disciplinas: comédia, dança, canto, artes circenses, manipulação de objetos e ilusionismo. Atuam a solo ou com outros artistas e podem aparecer em espetáculos musicais de variedades, cabarés, musicais e outros eventos de entretenimento. O seu desempenho artístico caracteriza-se pela combinação de artes, estilos e disciplinas.', 'released', NULL, '2659'),
  ('http://data.europa.eu/esco/occupation/76ef0a87-6afe-4560-b5d0-9a086abe45c5', 'Hacker Ético', 'Os hackers éticos realizam avaliações de vulnerabilidade em matéria de segurança e testes de penetração em conformidade com os métodos e protocolos aceites pela indústria. Analisam potenciais vulnerabilidades nos sistemas que podem resultar da incorreta configuração do sistema, de falhas no hardware ou no software ou de deficiências operacionais.', 'released', '["Testadora de Segurança Informática", "Analista de Segurança Informática", "Analista de Vulnerabilidade", "Testador de Segurança Informática", "Hacker Ético", "Hacker Ética"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/7706342e-c07b-41d3-bc2e-e5c6e96f016f', 'Montador de Joias', 'Os montadores de joias criam a estrutura para uma peça de joalharia, na qual as pedras preciosas são acrescentadas posteriormente.', 'released', '["Montadora de Joias", "Ourives", "Montador de Joias"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/771244bf-b204-4e7f-8b25-ee523ae7b791', 'Ortóptico', 'O ortópticos diagnosticam e tratam anomalias da visão binocular. Analisam, avaliam e tratam deficiências da visão, e pertúrbios como o estrabismo, a ambliopia e a motilidade ocular. Os ortópticos aplicam esses métodos, em particular nos domínios da pediatria, da neurologia, da neurooftalmologia, da oftalmologia, da ortóptica, da optometria, da pleótica e da estrabologia, avaliando as doenças funcionais do olho e tendo em vista a melhoria dos problemas funcionais do sistema visual. Prestam também aconselhamento, medidas preventivas e atividades de formação e podem efetuar rastreios e prescrever óculos, por exemplo óculos de correção. ;', 'released', '["Ortóptica", "Ortóptico"]'::jsonb, '2267'),
  ('http://data.europa.eu/esco/occupation/771955d9-e988-47f3-b60f-207adb2cd571', 'Gerente de Instalações Recreativas', 'Os gerentes de instalações recreativas dirigem as operações de instalações que prestam serviços recreativos, como jardins, spas, jardins zoológicos, e casas de jogos de azar e lotaria. Planificam e organizam as operações diárias do respetivo pessoal e instalações e asseguram que a organização acompanha os últimos desenvolvimentos no seu domínio. Coordenam os diferentes departamentos do espaço e gerem a utilização correta dos recursos e orçamentos.', 'released', '["Gerente de Instalações de Lazer", "Gerente de Instalações Esportivas", "Gerente de Centro Cultural", "Gerente de Sala de Cinema", "Gerentea de Instalações Recreativas"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/771a47c9-9cf4-4368-9752-2a1ea5a783d7', 'Detetive Particular', 'Os detetives particulares investigam e analisam informações para descobrir fatos por motivos pessoais, empresariais ou jurídicos, em função dos seus clientes. Realizam atividades de vigilância, que incluem tirar fotografias, verificar antecedentes e realizar entrevistas a pessoas. Os detetives particulares podem ajudar em processos penais e cíveis, de guarda de menores, fraude financeira, assédio em linha e podem procurar pessoas desaparecidas. Reúnem todas as informações num arquivo e entregam-no aos seus clientes para que tomem medidas adicionais.', 'released', '["Detetive Privado", "Detetive Privada", "Detetivea Particular"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/7720f392-6ea0-4455-a805-7b7eef38a709', 'Revisor de Títulos de Transporte', 'Os revisores de títulos de transporte recolhem bilhetes, títulos e cartões dos passageiros. Respondem a perguntas dos passageiros sobre regras de transporte, estações e informações sobre os horários.', 'released', '["Revisor de Títulos de Transporte", "Revisora de Títulos de Transporte"]'::jsonb, '5112'),
  ('http://data.europa.eu/esco/occupation/772e57c5-fb25-4b0c-8cc8-f8944a9edfbc', 'Operador de Fabricação de Peças em Fibra de Vidro', 'Os operadores de fabrico de peças em fibra de vidro procedem ao controlo e à manutenção da máquina que pulveriza uma mistura de resina e de fibras de vidro em produtos, tais como banheiras ou cascos de embarcações, para obter produtos compósitos acabados, fortes e leves.', 'released', '["Moldador de Artigos em Fibra de Vidro", "Moldadora de Artigos em Fibra de Vidro", "Operadora de Fabricação de Peças em Fibra de Vidro"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/773753ad-c4f7-4052-b3b4-440435199d6b', 'Vendedor de Perfumes e Cosméticos', 'Os vendedores de perfumes e cosméticos vendem cosméticos e artigos de higiene em lojas especializadas.', 'released', '["Vendedor de Perfumes e Cosméticos", "Vendedora de Perfumes e Cosméticos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/773cf1de-50a4-42e7-bab1-e68dcbae3f54', 'Trabalhador Florestal', 'Os trabalhadores florestais exercem uma série de funções para cuidar e gerir as árvores, as zonas florestais e as florestas. As suas atividades incluem a plantação, o corte, o desbaste e o abate de árvores e a sua proteção contra pragas, doenças e danos.', 'released', '["Trabalhador Florestal", "Operador Florestal", "Trabalhadora Florestal", "Silvicultora", "Operadora Florestal", "Silvicultor"]'::jsonb, '9215'),
  ('http://data.europa.eu/esco/occupation/773e5ea3-235b-4e72-afc5-290dd841eed8', 'Organizador de Espaços Internos', 'Os organizadores de espaços internos ajudam os clientes a planear os espaços internos para fins comerciais e privados.', 'released', '["Organizador de Espaços Internos", "Organizadora de Espaços Internos"]'::jsonb, '3432'),
  ('http://data.europa.eu/esco/occupation/774ad663-2124-4ac2-a287-5fb2e478906e', 'Técnico Nuclear', 'Os técnicos nucleares funcionam como auxiliares de físicos e engenheiros em laboratórios e centrais nucleares. Monitorizam os procedimentos para garantir a segurança e o controlo da qualidade e efetuam a manutenção do equipamento. Também manipulam e controlam o equipamento radioativo e medem os níveis de radiação para garantir a segurança.', 'released', '["Técnica Nuclear", "Técnico Nuclear"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/7754d570-9519-48c2-b1c9-8e165f8bca0f', 'Gestor de Riscos de Cibersegurança', 'Os gestores de riscos de cibersegurança identificam, analisam, avaliam, estimam e atenuam os riscos relacionados com a cibersegurança das infraestruturas de tecnologias da informação e comunicação, como sistemas ou serviços. Gerem estes aspectos através do planejamento da análise de risco, da aplicação, da elaboração de relatórios, da avaliação, da comunicação e do tratamento dos mesmos. Estabelecem uma estratégia de gestão de riscos para a organização e asseguram que os riscos permanecem a um nível aceitável para a mesma, selecionando ações de atenuação e controles.', 'released', '["Responsável Pela Segurança Informática", "Perito em Segurança Informática", "Gestora de Riscos de Cibersegurança", "Coordenador de Segurança Informática", "Gestor de Riscos de Cibersegurança", "Perita em Segurança Informática", "Gestora de Segurança Informática", "Coordenadora de Segurança Informática", "Gestor de Segurança Informática", "Gerente"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/776837b1-6f6b-4014-8330-d56918303e93', 'Instrutor de Snowboard', 'Os instrutores de snowboard ensinam grupos ou indivíduos a fazer snowboard. Instruem alunos de todas as idades e nível de competências, individualmente ou em grupos. Os instrutores de snowboard ensinam técnicas básicas e avançadas de snowboard através da demonstração de exercícios e dando a opinião aos alunos. Prestam aconselhamento relativamente a segurança e ao equipamento para a prática de snowboard.', 'released', '["Instrutor de Snowboard", "Instrutora de Snowboard"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/778c1d37-69f2-4184-ac98-03b7dbfba332', 'Engenheiro Especialista em Fotônica', 'Os engenheiros especialistas em fotónica ocupam-se da produção, do transporte, da transformação e da detecção de luz. Realizam atividades de investigação, concepção, montagem, ensaio e utilização de componentes ou sistemas fotónicos em vários campos de aplicações, desde as comunicações óticas até à instrumentação médica, ao processamento de material ou à tecnologia de detecção.', 'released', '["Engenheiro Especialista em Fotónica", "Engenheira Especialista em Fotónica", "Engenheira Especialista em Fotônica"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/779d13be-60b4-48f3-a339-fe483be96c7f', 'Especialista em Aspectos Legais e Regulamentares', 'Os especialistas em aspetos legais e regulamentares são responsáveis pelas questões regulamentares e legais em vários setores, como os setores dos cuidados de saúde, da energia e da banca. Supervisionam o desenvolvimento de produtos e serviços desde a sua origem até ao lançamento no mercado, garantindo que tudo está em conformidade com a legislação local e cumpre os requisitos regulamentares. Têm experiência nas diferentes fases dos processos regulamentares e atuam como uma interface entre a legislação empresarial e nacional ou os órgãos reguladores.', 'released', NULL, '2619'),
  ('http://data.europa.eu/esco/occupation/77a05858-f682-4648-baa5-9b86deeffbc1', 'Operador de Máquina para Mobiliário de Madeira', 'Os operadores de máquina para mobiliário de madeira utilizam máquinas que fabricam peças de mobiliário de madeira, de acordo com o procedimento operacional estabelecido. Garantem que a máquina funciona bem e reparam peças, se necessário.', 'released', '["Operador de Máquina para Mobiliário de Madeira", "Operadora de Máquina para Mobiliário de Madeira"]'::jsonb, '7523'),
  ('http://data.europa.eu/esco/occupation/77a25ee0-94ad-443e-91ea-3e6d3506181b', 'Operador de Máquina para Rosquear por Rolagem', 'Os operadores de máquina para rosquear por rolagem instalam e cuidam de máquinas para rosquear por rolagem concebidas para formar peças metálicas em roscas de parafuso internas e externas, pressionando um molde para rosquear contra varetas metálicas em branco, criando um diâmetro maior do que o das peças em branco originais.', 'released', '["Operador de Máquina para Rosquear por Rolagem", "Operadora de Máquina para Rosquear por Rolagem", "Operadora de Máquina para Abrir Roscas em Parafusos por Rodagem (ou Laminagem)", "Operadora de Máquina para Fabricar Cavilhas e Parafusos", "Operador de Máquina para Fabricar Cavilhas e Parafusos", "Operador de Máquina para Abrir Roscas em Parafusos por Rodagem (ou Laminagem)"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/77abfaec-a250-4765-95fa-6091e8da1bba', 'Engenheiro Eletromecânico', 'Os engenheiros eletromecânicos concebem e desenvolvem equipamentos e máquinas que utilizam tanto a tecnologia elétrica como a tecnologia mecânica. Elaboram projetos e preparam documentos que especifiquem os materiais necessários, o processo de montagem e outras especificações técnicas. Os engenheiros eletromecânicos também testam e avaliam protótipos. Supervisionam o processo de fabrico.', 'released', '["Engenheiro Mecânico", "Engenheiro Elétrico", "Engenheira Mecânica", "Engenheiro Eletromecânico", "Engenheira Eletromecânica", "Engenheira Elétrica", "Engenheira Eletromecânico"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/77bfd6e7-5598-4818-84cb-31e2651eb046', 'Designer de Moda', 'Os designers de moda trabalham em modelos para a alta costura e/ou o pronto-a-vestir, para os mercados de moda e, de um modo mais geral, em artigos de vestuário e moda. Os designers de moda podem trabalhar num domínio especializado, como o vestuário de desporto, o vestuário de criança, o calçado ou os acessórios.', 'released', '["Designer de Vestuário", "Estilista de Vestuário", "Especialista em Moda", "Estilista", "Estilista de Moda"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/77de6c7d-27bf-4bc2-8c80-5d6f6d9811f4', 'Técnico de Reprografia', 'Os técnicos de reprografia são responsáveis pelo processo de reprodução integral ou parcial dos documentos gráficos através de meios mecânicos ou digitais, tais como fotografia, digitalização ou impressão digital. Estas atividades são normalmente realizadas para efeitos de manutenção de arquivos ou de outros catálogos estruturados.', 'released', '["Técnica de Reprografia", "Técnico de Reprografia"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/7819669b-30c2-42e6-a1c4-0bcd6f0379ff', 'Responsável na Área das Relações Internacionais', 'Os responsáveis na área das relações internacionais asseguram o desenvolvimento da cooperação entre as organizações públicas e os governos a nível internacional. Facilitam a comunicação entre a sua organização e organizações estrangeiras e desenvolvem estratégias de colaboração, promovendo uma relação de colaboração benéfica para ambas as partes.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/781a6350-e686-45b9-b075-e4c8d5a05ff7', 'Desenvolvedor Cloud', 'Os programadores de software na cloud criam, implementam e modernizam aplicações de software para serem executadas na cloud por meio de microsserviços, contêineres e tecnologias sem servidor. Desenvolvem aplicações escaláveis e altamente disponíveis utilizando arquiteturas de computação em cloud e boas práticas. Incorporam no seu código o registro e o monitoramento e são capazes de efetuar análises das causas profundas das falhas.', 'released', '["Programador de Software na Cloud", "Programadora de Software na Cloud", "Programador", "Desenvolvedora Cloud"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/78216000-edc1-474b-9569-28ed6a657da2', 'Especialista em Edição Eletrônica', 'Os especialistas em edição eletrônica são responsáveis pela apresentação das publicações. Utilizam programas informáticos para organizar textos, fotografias e outros materiais num produto acabado apelativo e legível.', 'released', '["Especialista em DTP", "Especialista em Desktop Publishing"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/782ced63-e234-42a4-a7bd-a2d9a12ee61a', 'Operador de Máquinas de Enchimento de Cápsulas', 'Os operadores de máquinas de enchimento de cápsulas controlam o enchimento das cápsulas de gelatina com os preparados medicinais específicos.', 'released', '["Operador de Máquinas de Enchimento de Cápsulas", "Operadora de Máquinas de Enchimento de Cápsulas"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/7833d5cd-873d-4fdd-b2f8-9762d68494a7', 'Técnico de Engenharia Robótica', 'Os técnicos de engenharia robótica colaboram com os engenheiros no desenvolvimento de dispositivos e aplicações de robótica através de uma combinação de engenharia mecânica, engenharia eletrônica e engenharia informática. Os técnicos de engenharia robótica constroem, testam, instalam e calibram equipamentos robóticos.', 'released', '["Técnica de Engenharia Robótica", "Técnico de Engenharia Robótica"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/7843a4c6-a9f6-4095-94b9-45b384d4bd57', 'Entrevistador de Estudos de Mercado', 'Os entrevistadores de estudos de mercado procuram recolher informações sobre as perceções, opiniões e preferências dos clientes relativamente a produtos ou serviços comerciais. Utilizam técnicas de entrevista para recolher o máximo de informação possível, contactando as pessoas através de chamadas telefônicas, quer pessoalmente, quer através de meios virtuais. Estas informações são transmitidas aos peritos para análise.', 'released', '["Entrevistador de Estudos de Mercado", "Entrevistadora de Estudos de Mercado"]'::jsonb, '4227'),
  ('http://data.europa.eu/esco/occupation/784c98c2-96bd-4610-8da3-87d80f136285', 'Chefe de Armazém de Produtos de Couro', 'Os chefes de armazém de produtos de couro organizam e controlam o armazém de produtos de couro e os níveis do estoque e organizam a embalagem e a expedição dos produtos. Maximizam o espaço de armazém e gerem o tempo para controlar as encomendas.', 'released', '["Capataz de Armazém de Produtos de Couro", "Supervisora de Armazém de Produtos de Couro", "Supervisor de Armazém de Produtos de Couro", "Chefea de Armazém de Produtos de Couro"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/78625dd8-257b-483b-bca0-172dd9b02754', 'Montador de Peças de Veículos', 'Os montadores de peças de veículos fixam peças e componentes de veículos automóveis em conjunto. Utilizam ferramentas manuais e ferramentas elétricas para ligar a cablagem, posicionam e ajustam as peças. Os montadores de peças de veículos também instalam dispositivos programáveis ou robôs. Testam as montagens e equipamentos elétricos e inspecionam as peças individuais para detectar eventuais avarias. Verificam a qualidade das montagens para garantir que as normas são cumpridas e as especificações são respeitadas.', 'released', '["Montadora de Peças de Veículos", "Montador de Peças de Automóveis", "Montadora de Peças de Automóveis", "Montador de Peças de Veículos"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/788a9895-a39a-4a83-be90-e006e2f8dce5', 'Superintendente de Gaseoduto ou Oleoduto', 'Os superintendentes de gaseoduto ou oleoduto gerem a direção e o desenvolvimento global dos projetos de transporte por condutas. Preveem o planejamento, a seleção do itinerário, a gestão dos recursos e as operações diárias. Desenvolvem uma visão a longo prazo que salvaguarda a eficiência da infraestrutura.', 'released', '["Coordenadora de Rede de Distribuição", "Coordenador de Rede de Distribuição", "Chefe de Projeto de Oleoduto ou Gaseoduto", "Superintendentea de Gaseoduto ou Oleoduto"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/789517fb-95ee-43d1-9530-c2860be1a439', 'Especialista em Saúde e Segurança no Trabalho', 'Os especialistas em saúde e segurança no trabalho executam planos para a melhoria dos ambientes de trabalho e das culturas. Avaliam os riscos e entrevistam os empregados para garantir que o ambiente de trabalho está em conformidade com as normas de saúde e segurança, e asseguram que a interação no local de trabalho decorre de forma positiva e produtiva. Quando exercem funções num estabelecimento de cuidados de saúde, os especialistas em saúde e segurança no trabalho têm de investigar a existência de infeções numa unidade e prestar aconselhamento a todos os trabalhadores sobre a forma de combater e prevenir infeções. Além disso, a física da saúde é aplicada nas instalações onde as pessoas estão expostas a radiações ionizantes, como centrais nucleares e instituições de investigação.', 'released', '["Consultor em Saúde e Segurança no Trabalho", "Consultora em Saúde e Segurança no Trabalho", "Higienista Ocupacional"]'::jsonb, '2263'),
  ('http://data.europa.eu/esco/occupation/789a1a35-8e03-42da-857f-4216c4d2ac68', 'Comerciante Grossista de Desperdícios e Sucata', 'Os comerciantes grossistas de desperdícios e sucata investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Desperdícios e Sucata"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/789d9781-8724-4367-936a-3a4cb7c54315', 'Dançaterapeuta', 'Os dançaterapeutas ajudam os indivíduos com os seus problemas de saúde emocionais, mentais ou físicos, ajudando-os a melhorar a sua consciência do corpo, a autoestima, a integração social e o desenvolvimento pessoal através de padrões de dança e de movimento num ambiente terapêutico.', 'released', '["Dança-Terapeuta", "Terapeuta Especialista em Dança", "Terapeuta Especialista em Movimento", "Terapeuta em DMT"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/78db356f-a96a-4456-ab29-2de62e52f830', 'Contabilista Público', 'Os contabilistas públicos são responsáveis pelo departamento de tesouraria de uma instituição governamental. Gerem a administração financeira, as despesas e a criação de receitas da instituição, bem como a conformidade com a fiscalidade e demais legislação financeira. Desempenham funções administrativas para assegurar a manutenção de registos, elaborar planos de gestão orçamental e executar previsões financeiras.', 'released', '["Técnica Superiora em Contabilidade Pública", "Técnico Superior em Contabilidade Pública", "Contabilista Público", "Contabilista Pública"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/78ddc0cc-166e-437e-9c41-48aa0a6c6f93', 'Operador de Misturadora de Especiarias', 'Os operadores de misturadora de especiarias peneiram as especiarias utilizando peneiras mecânicas. Operam máquinas de misturar para misturar especiarias e pesá-las até se alcançar uma determinada consistência. Comparam as cores das misturas com o gráfico de cores normalizado, para garantir que as cores da mistura cumprem as especificações.', 'released', '["Operador de Misturadora de Especiarias", "Técnica de Mistura de Especiarias", "Técnico de Mistura de Especiarias", "Operadora de Misturadora de Especiarias"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/78eacaf8-06d6-4b78-920f-edece2e41464', 'Auxiliar de Transporte Escolar', 'Os auxiliares de transporte escolar monitorizam as atividades de transporte escolar a fim de assegurar e supervisionar a segurança e o bom comportamento dos alunos. Ajudam as crianças a subir a descer do ônibus, apoiam o motorista e prestam assistência em caso de emergência.', 'released', NULL, '5311'),
  ('http://data.europa.eu/esco/occupation/78ed3811-f421-45e5-9574-31364c76af67', 'Professor de Escola Superior de Dança', 'Os professores de escola superior de dança ensinam os alunos com teoria específica e, principalmente, cursos de dança baseados na prática, numa escola de dança ou num conservatório ao nível do ensino superior. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar na dança. Os professores de escola superior de dança acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho na dança, frequentemente por meio de trabalhos, testes e exames práticos.', 'released', '["Professora de Escola Superior de Dança", "Professora de Escola de Dança do Conservatório", "Professor de Escola de Dança do Conservatório", "Professor de Academia de Dança", "Professor de Escola Superior de Dança"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/78f474ae-c154-4206-ad0f-d8a00e9c541e', 'Técnico de Apoio Residencial a Adultos Toxicodependentes ou com Deficiência', 'Os técnicos de apoio residencial a adultos toxicodependentes prestam aconselhamento ou apoio a adultos vulneráveis que tenham deficiências físicas ou mentais ou problemas de dependência. Acompanham os progressos realizados e prestam-lhes cuidados num ambiente de vida positivo. Trabalham com famílias para apoiar o desenvolvimento das pessoas e satisfazer as suas necessidades.', 'released', '["Técnico de Apoio Residencial a Adultos Toxicodepentes ou com Deficiência", "Técnica de Apoio Residencial a Adultos Toxicodepentes ou com Deficiência", "Técnica de Apoio Residencial a Adultos Toxicodependentes ou com Deficiência"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/78faf623-2543-43a5-acb2-3c43a22d36e4', 'Arquiteto de Cadeia de Blocos', 'Os arquitetos de cadeia de blocos são arquitetos de sistemas de tecnologia da informação especializados em soluções baseadas em cadeias de blocos. Desenham a arquitetura, os componentes, os módulos, as interfaces e os dados de um sistema descentralizado para cumprir requisitos especificados.;', 'released', '["Engenheira de Blockchain", "Especialista em Tecnologia Blockchain", "Arquiteta de Cadeia de Blocos"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/79082f76-4b11-4594-8437-2db567331f41', 'Operário da Marcação de Estradas', 'Os operários da marcação de estradas aplicam marcações em estradas para aumentar a segurança, indicar a regulamentação relativa ao tráfego e ajudar os utentes da estrada a encontrar o caminho. Utilizam várias máquinas para pintar linhas de tinta nas estradas e instalam outras marcações, tais como os postes refletores.', 'released', '["Trabalhador não Qualificado da Marcação de Estradas", "Operária da Marcação de Estradas"]'::jsonb, '9312'),
  ('http://data.europa.eu/esco/occupation/790c8dca-f624-4bdc-ac16-27bc13ead188', 'Designer Sonoro', 'Os designers sonoros desenvolvem um conceito de concepção de som para um espetáculo e supervisionam a sua execução. O seu trabalho baseia-se na investigação e na visão artística. O seu desenho é influenciado por, e influencia, outros desenhos e deve estar em conformidade com estes desenhos e com a visão artística global. Por conseguinte, os designers trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Os designers sonoros preparam excertos áudio que serão utilizados num espetáculo, que podem envolver a gravação, a composição, a manipulação e a edição. Durante os ensaios e o espetáculo orientam os operadores a fim de obter uma sincronização e uma manipulação ideais. Os responsáveis pela concepção sonora desenvolvem planos, listas de orientação e outros documentos para apoiar os operadores e a equipe de produção. Por vezes, os designers sonoros também trabalham como artistas independentes, criando arte sonora fora de um contexto de espetáculo.', 'released', '["Criadora Sonora", "Designer Sonoro", "Sonoplasta", "Assistente de Som", "Artista Sonora", "Designer Sonora", "Criador Sonoro", "Artista Sonoro", "Designer de Som"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/79874366-6ec2-4601-aceb-9dbb8e68d015', 'Gerente de Frutaria', 'Os gerentes de frutaria assumem a responsabilidade pelas atividades e pelo pessoal das lojas especializadas no setor das frutas e produtos hortícolas.', 'released', '["Gerente de Mercearia", "Gerentea de Frutaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/79c2e54e-26e8-4cdc-a7f1-908e000bfb83', 'Auxiliar de Educação no Ensino Secundário', 'Os auxiliares de educação no ensino secundário prestam vários serviços de apoio aos professores do ensino secundário, tal como apoio educativo e prático. Ajudam na preparação dos materiais de aula necessários à aula e reforçam as instruções com os alunos que necessitam de mais atenção. Também desempenham funções administrativas básicas, acompanham o progresso e o comportamento dos alunos e supervisionam-nos com e sem o professor presente.', 'released', '["Auxiliar de Ação Educativa", "Técnica de Ação Educativa", "Técnico de Ação Educativa"]'::jsonb, '5312'),
  ('http://data.europa.eu/esco/occupation/79f435d0-9bc6-4d25-a26a-acbe16569ebb', 'Instalador de Sistemas de Aquecimento e Ventilação', 'Os instaladores de sistemas de aquecimento e ventilação instalam e procedem à manutenção de sistemas industriais de aquecimento e refrigeração. Instalam fornos, termóstatos, condutas, respiradouros e outros equipamentos necessários para assegurar a passagem controlada e o tratamento do ar. Também efetuam reparações.', 'released', '["Técnica de Refrigeração Industrial", "Instalador de Sistemas de Aquecimento e Ventilação", "Aquecimento, Ventilação e Ar Condicionado Mecânica", "Inspetora de Ar Condicionado e Refrigeração", "Inspetor de Ventilação e Ar Condicionado", "Inspetor HVACR", "Instaladora de Sistemas de Aquecimento e Ventilação", "Inspetora HVACR", "Mecânica de Aquecimento HVAC", "Inspetor de Instrumento de Aquecimento", "Inspetora de Instrumento de Aquecimento", "Aquecimento, Ventilação e Ar Condicionado Mecânico", "Mecânico de Aquecimento HVAC", "Inspetor de Ar Condicionado", "Mecânica de HVAC", "Mecânico de HVAC", "Inspetora de Ar Condicionado", "Inspetora de Ventilação e Ar Condicionado", "Técnico de Refrigeração Industrial", "Inspetor de Ar Condicionado e Refrigeração"]'::jsonb, '7127'),
  ('http://data.europa.eu/esco/occupation/79f8f68c-5509-4119-9373-8bef1c364d31', 'Agente de Viagens', 'Os agentes de viagens planeiam e comercializam itinerários do programa de viagens para potenciais viajantes ou visitantes.', 'released', '["Agente de Reservas", "Agente de Viagens", "Agente de Vendas", "Agentea de Viagens"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/79fed799-ab3a-43d9-bd91-414c2c3b2f57', 'Engenheiro Projetista de Ferramentas', 'Os engenheiros projetistas de ferramentas criam novas ferramentas para o fabrico de equipamentos. Elaboram pedidos de cotações de ferramentas. Estimam os custos e os tempos de entrega, gerem o acompanhamento da construção das ferramentas e supervisionam a manutenção corrente das ferramentas. Analisam também os dados para determinar a causa das principais dificuldades relacionadas com as ferramentas e elaboram recomendações e planos de ação para as soluções.', 'released', '["Engenheiro Projetista de Ferramentas", "Engenheira Projetista de Ferramentas"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/7a031723-2b2c-4fdd-8ed5-30d67088b8b8', 'Gestor de Licenças', 'Os gestores de licenças supervisionam as licenças e os direitos de uma empresa relativos à utilização dos seus produtos ou à propriedade intelectual. Asseguram que os terceiros cumprem os acordos e contratos especificados e negoceiam e dialogam com ambas as partes.', 'released', '["Gestor de Licenças", "Gestora de Licenças", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/7a0afb5e-f118-449a-82bd-d8b9230fd49f', 'Operador de Tuneladora', 'Os operadores de tuneladora trabalham em grandes equipamentos de perfuração de túneis, geralmente conhecidos por «TBM». Regulam o funcionamento da máquina, ajustando o binário da roda de corte rotativa e do transportador helicoidal para maximizar a estabilidade do túnel antes da instalação de anéis de túnel. Em seguida, os operadores de tuneladora colocam os anéis de betão armado, utilizando controlos à distância.', 'released', '["Operador de Tuneladora", "Operadora de Tuneladora"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/7a18e959-44fe-49ae-9757-124f46a7487c', 'Aderecista', 'Os aderecistas constroem, edificam, preparam, adaptam e mantêm os adereços utilizados no palco e para as filmagens de filmes ou de programas de televisão. Os adereços podem ser imitações simples de objetos da vida real, ou podem incluir efeitos eletrônicos, pirotécnicos, ou outros. O seu trabalho baseia-se na visão artística, esboços e planos. Trabalham em estreita colaboração com os designers envolvidos na produção.', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/7a3996d8-b90d-4b81-bd5e-e37f005b2683', 'Diretor de Conformidade e Segurança da Informação no Setor do Jogo', 'Os diretores de conformidade e segurança da informação no setor do jogo asseguram a conformidade regulamentar dos jogos de azar e supervisionam a segurança da informação para garantir a utilização segura de todas as tecnologias da informação associadas ao jogo.', 'released', '["Diretor de Controle da Conformidade e de Segurança no Domínio do Jogo", "Diretor de Segurança", "Diretora de Conformidade e Segurança da Informação no Setor do Jogo", "Diretor de Conformidade", "Diretora de Segurança", "Diretora de Controle da Conformidade e de Segurança no Domínio do Jogo", "Diretor de Conformidade e Segurança da Informação no Setor do Jogo", "Diretora de Conformidade"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/7a523273-9fff-4f11-beb6-110eeaec1436', 'Especialista em Reciclagem e Gestão de Resíduos', 'Os especialistas em reciclagem e gestão de resíduos investigam políticas e legislação em matéria de reciclagem e supervisionam a sua aplicação numa organização para assegurar a gestão dos resíduos ]e realizada em conformidade com a regulamentação. Realizam inspeções, fornecem equipamento de reciclagem e supervisionam os trabalhadores da reciclagem. Aconselham também as organizações sobre formas de melhorar os seus procedimentos de gestão de resíduos.', 'released', NULL, '2143'),
  ('http://data.europa.eu/esco/occupation/7a6ca615-a2bc-499d-8288-d186ce2594ea', 'Gestor de Riscos Financeiros', 'Os gestores de riscos financeiros identificam e avaliam potenciais áreas de risco que ameaçam os ativos ou o capital das organizações e prestam aconselhamento sobre a forma de lidar com eles. São especializados na análise de risco de crédito, de mercado, operacional ou regulamentar. Utilizam análises estatísticas para avaliar os riscos, fazem recomendações para reduzir e controlar os riscos financeiros e garantem que a documentação cumpre os requisitos legais.;', 'released', '["Gestor de Risco", "Gestora de Risco", "Analista de Risco de Crédito", "Analista e Gestor de Risco", "Analista e Gestora de Risco", "Gerente", "Gestora de Riscos Financeiros"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/7aedaa07-3884-4c5b-88f9-80997b2aa54b', 'Soldador', 'Os soldadores operam com equipamento de soldadura a fim de unir peças metálicas. Podem utilizar processos de soldadura por fusão com base em técnicas e materiais diferentes. Realizam também uma simples inspeção visual das soldaduras.', 'released', '["Soldadora", "Soldador"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/7af81505-6681-49b5-b65e-401884a71f1f', 'Técnico de Monitoramento de Águas Subterrâneas', 'Os técnicos de monitorização de águas subterrâneas monitorizam o ambiente, recolhendo dados sob a forma de amostras e realizando testes num laboratório ou no terreno, a fim de investigarem potenciais fontes de poluição. Desempenham igualmente tarefas de manutenção do equipamento de monitorização.', 'released', '["Técnica de Monitoramento de Águas Subterrâneas", "Técnico de Monitoramento de Águas Subterrâneas"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/7afeee90-5672-470d-b061-24ffaafb2fc9', 'Chefe de Turno em Refinaria', 'Os chefes de turno em refinarias supervisionam o pessoal, gerem as instalações e o equipamento, otimizam a produção e asseguram a segurança diária na refinaria de petróleo.', 'released', '["Chefea de Turno em Refinaria"]'::jsonb, '3134'),
  ('http://data.europa.eu/esco/occupation/7b1b5da8-573a-49bb-a38e-68725a949f4f', 'Diretor de Tecnologia', 'Os diretores de tecnologia contribuem para a visão técnica da empresa e lideram todos os aspetos do desenvolvimento tecnológico, de acordo com a sua orientação estratégica e os seus objetivos de crescimento. Visam garantir a correspondência entre a tecnologia e as necessidades da empresa.', 'released', '["Diretor de Tecnologia", "Principal Responsável Pela Tecnologia", "Principal Responsável Pelas Tecnologias", "Diretora de Tecnologia", "Responsável Pela Tecnologia", "Diretor Digital", "Responsável Pelas Tecnologias"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/7b4744a8-a4e3-4104-9b74-4ec54108af7b', 'Designer de Microeletrônica', 'Os designers de microeletrónica centram-se no desenvolvimento e na concepção de sistemas microeletrónicos, desde a embalagem ao circuito integrado. Os seus conhecimentos integram uma compreensão do sistema global com o conhecimento analógico e digital dos circuitos, incorporando os processos tecnológicos e uma perspetiva global dos princípios básicos dos sensores microeletrónicos. Trabalham com outros engenheiros, especialistas em ciências dos materiais e investigadores, no intuito de gerar inovação e facilitar o desenvolvimento contínuo de dispositivos já existentes.;', 'released', '["Engenheiro de Circuito Microeletrônico", "Engenheira de Sistema de Circuito Microeletrônico", "Engenheira de Projeto de Circuitos Microeletrônicos", "Engenheira de Design de Embalagens Microeletrônica", "Engenheira de Circuito Microeletrônico", "Engenheiro de Projeto de Tecnologia Microeletrônica", "Engenheiro de Projeto de Fabricação de Microeletrônica", "Projetista de Sistema Microeletrônico", "Engenheiro de Silício", "Designer de Hardware Microeletrônica", "Engenheira de Hardware Microeletrônica", "Engenheira de Silício", "Engenheira de Hardware de Circuito Integrado", "Engenheiro de Projeto de Circuitos Microeletrônicos", "Engenheiro de Hardware Microeletrônica", "Engenheira de Projeto de Fabricação de Microeletrônica", "Engenheiro de Design de Embalagens Microeletrônica", "Engenheira de Projeto de Tecnologia Microeletrônica", "Designer de Embalagem Microeletrônica", "Engenheira de Sistema Microeletrônico", "Engenheiro de Sistema de Circuito Microeletrônico", "Projetista de Circuitos Microeletrônicos", "Engenheiro de Hardware de Circuito Integrado", "Engenheiro de Sistema Microeletrônico"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/7b629a14-09d0-417e-8181-7683923b4e5e', 'Coordenador de Programas de Esporte', 'Os coordenadores de programas de desporto coordenam atividades desportivas e recreativas e a execução de políticas neste domínio. Desenvolvem novos programas e visam a sua promoção e implementação, além de assegurarem a manutenção de instalações desportivas e recreativas.', 'released', '["Coordenador de Programas de Esporte", "Coordenadora de Programas de Esporte"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/7b74626d-b487-48a1-9e80-47faf9928210', 'Técnico de Farmácia', 'Os técnicos de farmácia, sob a supervisão de um farmacêutico, verificam as entradas de produtos, controlam as existências e manipulam e armazenam de forma adequada os produtos farmacêuticos. Sempre que tal seja permitido pelas regras nacionais, dispensam medicamentos e prestam aconselhamento sobre a sua utilização adequada.', 'released', '["Técnico de Farmácia", "Técnica de Farmácia"]'::jsonb, '2262'),
  ('http://data.europa.eu/esco/occupation/7b89d3e0-c6fb-4c95-bf0d-3b4acf05f9d6', 'Especialista na Redação de Documentos Legais', 'Os especialistas na redação de documentos legais pesquisam textos legislativos e editam-nos, a fim de os tornarem mais sólidos e claros. Esporadicamente, também acrescentam novas ideias nunca antes incorporadas numa lei ou num projeto de lei.', 'released', NULL, '2619'),
  ('http://data.europa.eu/esco/occupation/7b8b6118-6876-4a71-81a6-4b5fa9bfa221', 'Técnico de Terapia Respiratória', 'Os técnicos de terapia respiratória prestam assistência a médicos e cirurgiões no tratamento de problemas respiratórios. Trabalham em hospitais e unidades médicas, onde utilizam equipamento médico para realizar testes às doenças respiratórias dos doentes e ajudar no seu tratamento. Os técnicos de terapia respiratória também vigiam e operam equipamentos e máquinas respiratórios durante uma cirurgia.', 'released', '["Técnica de Terapia Respiratória", "Técnico de Terapia Respiratória"]'::jsonb, '3259'),
  ('http://data.europa.eu/esco/occupation/7b99007f-c6bf-4703-85d3-f168bc6a9f28', 'Engenheiro Especialista em Planejamento de Operações Mineiras', 'Os engenheiros especialistas em planificação de operações mineiras concebem planos de exploração futuros capazes de alcançar os objetivos de produção e de desenvolvimento de minas, tendo em conta as características geológicas e a estrutura do recurso mineral. Elaboram calendários de produção e de desenvolvimento e acompanham os progressos alcançados.', 'released', '["Engenheiro Especialista em Planificação de Operações Mineiras", "Engenheira Especialista em Planificação de Operações Mineiras", "Engenheira Especialista em Planejamento de Operações Mineiras"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/7bc02fa7-7aaa-41a6-be5b-ab7a7b6684d3', 'Engenheiro Projetista de Redes de Gás', 'Os engenheiros de distribuição de gás concebem e constroem sistemas de transporte de gás natural, ligando a rede de distribuição de gás ao consumidor através da concepção de tubagens e obras. Investigam métodos para garantir a sustentabilidade e para reduzir o impacto ambiental, bem como para otimizar a eficiência em termos de custos.', 'released', '["Engenheiro Projetista de Redes de Gás", "Engenheira Projetista de Redes de Gás"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/7bcafcd7-3f35-4a72-849c-c92b334927fd', 'Consultor de Risco de Seguro', 'Os consultores de risco de seguro elaboram relatórios para os verificadores de seguros. Para o efeito, realizam inquéritos para determinar o potencial risco financeiro relativo a produtos, bens ou locais.', 'released', '["Consultora de Risco de Seguro", "Consultor de Risco de Seguro"]'::jsonb, '3321'),
  ('http://data.europa.eu/esco/occupation/7beefadd-ea05-4f59-bc4b-01075f27b937', 'Infografista', 'Os infografistas criam vídeos utilizando técnicas analógicas ou digitais para obter efeitos especiais, animações ou outros suportes visuais recorrendo a filmes, vídeos, imagens, computadores ou outras ferramentas eletrônicas.', 'released', '["Infografista 3D", "Infografista 2D"]'::jsonb, '2651'),
  ('http://data.europa.eu/esco/occupation/7bf11599-d0bb-4789-9886-55c87f5da449', 'Técnico de Qualidade na Marroquinaria', 'Os técnicos de qualidade na marroquinaria desempenham tarefas relacionadas com o sistema de qualidade, através do controlo da qualidade e da execução de testes laboratoriais (produtos acabados, materiais utilizados e componentes), de acordo com as normas nacionais e internacionais. Analisam e interpretam os resultados dos testes laboratoriais, elaboram relatórios e aconselham sobre medidas corretivas e preventivas, contribuindo para o cumprimento dos requisitos e objetivos, tendo em vista uma melhoria contínua e a satisfação do cliente.', 'released', '["Técnico de Qualidade na Marroquinaria", "Técnica de Qualidade na Marroquinaria"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/7c132147-428b-4ea3-87e1-70f7abb691ce', 'Farmacêutico', 'Os farmacêuticos preparam, dispensam e fornecem prescrições para medicamentos não sujeitos a receita medica. Fornecem informações clínicas sobre medicamentos, comunicam suspeitas de reações adversas e prestam apoio personalizado aos doentes. Os farmacêuticos formulam e testam medicamentos em laboratórios, e armazenam-nos, preservam-nos e distribuem-nos.', 'released', '["Farmacêutica", "Farmacêutico"]'::jsonb, '2262'),
  ('http://data.europa.eu/esco/occupation/7c205166-d862-45fc-90e5-58a3aa3721dd', 'Supervisor de Obras de Estrada', 'Os supervisores de obras de estrada acompanham a construção e a manutenção de estradas. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Obras de Estrada", "Supervisora de Obras de Estrada"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/7c2fbf7d-b934-4f62-8167-0ed90fb2a16f', 'Engenheiro Mecânico Especialista em Veículos Ferroviários', 'Os engenheiros mecânicos especialistas em veículos ferroviários concebem e supervisionam o processo de fabrico e a instalação de veículos ferroviários, incluindo locomotivas, carruagens, vagões e unidades múltiplas. Concebem novos comboios e peças elétricas ou mecânicas, supervisionam as modificações e resolvem problemas técnicos. Desempenham igualmente funções de manutenção de rotina, a fim de assegurar que os comboios se encontram em boas condições e cumprem as normas de qualidade e segurança.', 'released', '["Engenheira Mecânica Especialista em Veículos Ferroviários", "Engenheiro Mecânico Especialista em Veículos Ferroviários", "Engenheira Mecânico Especialista em Veículos Ferroviários"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/7c320679-131d-4828-87ed-94886614b7ed', 'Operador de Autobomba', 'Os operadores de autobomba ajudam nas operações de combate a incêndios através do controlo das bombas que fornecem água e outras substâncias para a extinção dos incêndios. Asseguram a entrega da substância na quantidade certa e sob a pressão correta através da mangueira.', 'released', '["Operador de Auto-Bomba", "Operadora de Auto-Bomba", "Operadora de Autobomba"]'::jsonb, '5411'),
  ('http://data.europa.eu/esco/occupation/7c5e4ca1-e8be-4297-9014-509d5ba57210', 'Guia de Jardim Zoológico', 'Os guias de jardim zoológico ensinam aos visitantes sobre os animais que vivem no jardim zoológico/aquário, bem como outras espécies e habitats. Fornecem informações sobre a gestão dos jardins zoológicos, a sua coleção de animais e a conservação da vida selvagem. Os guias de jardim zoológico podem participar em oportunidades de aprendizagem formal e informal, desde a produção de sinais de informação em compartimentos à realização de aulas relacionadas com programas escolares ou universitários. Dependendo da dimensão da organização, a equipe de guias pode ser uma única pessoa ou uma grande equipe. Por conseguinte, as competências opcionais exigidas são muito amplas e variam de organização para organização. ; ; Os guias de jardim zoológico também promovem esforços de conservação. Tal pode envolver o trabalho no jardim zoológico, mas também no terreno, como parte de qualquer projeto de sensibilização em jardins zoológicos.', 'released', NULL, '5113'),
  ('http://data.europa.eu/esco/occupation/7c64479f-7a76-49e9-ac42-bd925f2bf99d', 'Operador de Sala de Controle de Minas', 'Os operadores de sala de controlo de minas desempenham uma série de tarefas da sala de controlo de uma mina. Acompanham os processos através de representações eletrônicas em monitores, mostradores e luzes. Os operadores de sala de controlo de minas introduzem alterações nas variáveis e comunicam com outros departamentos, a fim de garantir que os processos funcionam sem problemas e de acordo com os procedimentos estabelecidos. Tomam as medidas adequadas em caso de irregularidades ou de situações de emergência.', 'released', '["Operadora de Sala de Controle de Minas", "Operador de Sala de Controle de Minas"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/7c6fc2f0-6e16-4429-8190-f6faac0c3853', 'Luveiro', 'Os luveiros concebem e fabricam luvas técnicas, de desporto ou de uso habitual.', 'released', '["Fabricante de Luvas", "Luveira", "Luvista", "Luveiro"]'::jsonb, '7533'),
  ('http://data.europa.eu/esco/occupation/7cb71c5f-c310-481c-b46b-d0044328758c', 'Auxiliar de Limpeza de Veículos', 'Os empregados de limpeza de veículos limpam e pulem as superfícies das partes exteriores e interiores de veículos.', 'released', '["Lavadora de Veículos", "Empregada de Limpeza de Veículos", "Empregado de Limpeza de Veículos", "Lavador de Veículos"]'::jsonb, '9122'),
  ('http://data.europa.eu/esco/occupation/7cd070f5-b5dd-4228-bdcf-0419dbacfcf4', 'Moleiro de Destilaria', 'Os moleiros de destilaria asseguram o correto funcionamento de destilarias e limpam e moem os grãos inteiros para serem utilizados na produção de licores destilados. asseguram o correto funcionamento das máquinas de limpeza para remover as impurezas dos grãos, seguindo-se a trituração e a pesagem dos grãos. Realizam operações de manutenção diária em bombas, em transportadores por gravidade e em máquinas.', 'released', '["Moleira de Destilaria", "Operadora de Moinho de Destilaria", "Operadora de Instalação de Moagem de Destilaria", "Operador de Moinho de Destilaria", "Moleiro de Destilaria", "Operador de Instalação de Moagem de Destilaria"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/7cdeb653-8f3d-4921-832b-b95f9d700a86', 'Operador de Sistema de Transmissão de Energia Elétrica', 'Os operadores de sistema de transmissão de energia elétrica transportam a energia sob a forma de energia elétrica. Efetuam a transmissão de energia elétrica a partir das centrais de produção, através de uma rede interligada, ou seja a rede elétrica, para as estações de distribuição de eletricidade.', 'released', '["Operadora de Sistema de Transmissão de Energia Elétrica", "Operador de Sistema de Transmissão de Energia Elétrica"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/7ceb2340-339c-4367-bc4e-e08f57c992f6', 'Empregado de Abrigo para Animais', 'Os empregados de abrigo para animais prestam serviços de rotina aos animais nos abrigos para animais. Recebem animais levados para o abrigo, respondem a chamadas sobre animais perdidos ou feridos, prestam cuidados de enfermagem aos animais, limpam as gaiolas, tratam dos documentos para a adoção de animais, transportam os animais para o veterinário e procedem à manutenção da banco de dados com os animais presentes no abrigo.', 'released', '["Empregada de Abrigo para Animais", "Empregado de Abrigo para Animais"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/7d092380-1c2e-48fe-81de-0d191b4e96d6', 'Técnico de Radiologia de Diagnóstico', 'Os técnicos de radiologia de diagnóstico planificam, preparam e realizam exames de imagiologia para diagnóstico e pós-processamento, com uma vasta gama de equipamentos e técnicas com recurso a raios X, campos magnéticos fortes ou imagiologia por ressonância magnética (IRM) e som de alta frequência (ultrassons).', 'released', '["Técnica de Radiologia de Diagnóstico", "Técnico de Radiologia de Diagnóstico"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/7d27600b-5cff-4ebc-b259-cc2d47572035', 'Responsável de Workshops', 'Os responsáveis de workshops coordenam workshops especializados que construam, edifiquem, preparem, adaptem e mantenham os elementos utilizados no palco. O seu trabalho baseia-se na visão artística, nos horários e na documentação de produção global. Asseguram a ligação com os designers envolvidos na produção, a equipe de produção e outros serviços da organização.', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/7d4266b3-2108-4330-b27b-430a96012c21', 'Operador de Máquina de Costurar', 'Os operadores de máquina de costura operam máquinas de costura específicas na cadeia de produção industrial de artigos de vestuário. Executam operações tais como a união, a montagem, o reforço, a reparação e a alteração de artigos de vestuário.', 'released', '["Operador de Máquina de Costura", "Operadora de Máquina de Costura", "Operadora de Máquina de Costurar"]'::jsonb, '8153'),
  ('http://data.europa.eu/esco/occupation/7d599049-d15a-4fda-afe9-b334b0614ec7', 'Técnico de Manutenção de Motores de Avião com Turbina a Gás', 'Os técnicos de manutenção de motores de avião com turbina a gás realizam trabalhos de revisão, manutenção e reparação de motores com turbina a gás. Desmontam, inspecionam, limpam, reparam e voltam a montar os motores com ferramentas específicas para o motor.', 'released', '["Técnica de Manutenção de Motores de Avião com Turbina a Gás", "Técnico de Manutenção de Motores de Avião com Turbina a Gás"]'::jsonb, '7232'),
  ('http://data.europa.eu/esco/occupation/7d7ea936-a1c6-499d-9aa7-054e943b019b', 'Gerente de Agência de Interpretação', 'Os gerentes de agência de interpretação supervisionam as operações de prestação de serviços de interpretação. Coordenam os esforços de uma equipe de intérpretes que compreendem e convertem a comunicação falada de uma língua para outra. Asseguram a qualidade do serviço e a administração da agência de interpretação.', 'released', '["Gestora de Agência de Tradução", "Gestora de Agência de Interpretação", "Gestor de Agência de Tradução", "Gestor de Agência de Interpretação", "Gerentea de Agência de Interpretação"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/7d8b3c73-20f8-467e-91e4-00378673a2cd', 'Inspetor de Segurança Alimentar', 'Os inspetores de segurança alimentar realizam inspeções em ambientes de transformação alimentar do ponto de vista da segurança dos alimentos. Fazem parte de organismos oficiais de controlo que verificam e controlam os produtos e processos alimentares, a fim de garantir o cumprimento da regulamentação e da legislação em matéria de saúde e segurança.', 'released', '["Inspetora de Segurança Alimentar", "Controladora de Qualidade Alimentar", "Controlador de Qualidade Alimentar", "Inspetor de Segurança Alimentar", "Inspetora de Qualidade Alimentar", "Inspetor de Qualidade Alimentar"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/7d9242d3-2a55-45e3-9d67-be76f879de0b', 'Operador de Torno para Trabalho de Metais', 'Os operadores de torno para trabalho de metais instalam e cuidam do torno para trabalho de metais à mão, que é responsável pelo corte de metal no tamanho e na forma desejados, utilizando um trem de engrenagens ou um dispositivo de troca que impulsiona o parafuso de avanço a um rácio de velocidade variável, rodando assim a peça metálica no seu eixo, facilitando o processo de corte. Verificam o desgaste do equipamento do torno e manuseiam as peças metálicas, tal como foram cortadas pelo torno.', 'released', '["Operadora de Torno para Trabalho de Metais", "Operador de Torno para Trabalho de Metais"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/7d99ed04-fda7-4f35-9f02-0db18078159c', 'Operador de Máquinas de Acabamento de Couros', 'Os operadores de máquinas de acabamento de couros utilizam máquinas para acabar o couro de acordo com as especificações do cliente para as características da superfície. Estas características referem-se à nuance de cores, à qualidade, ao padrão e a propriedades especiais, tais como a resistência à água e a proteção antichama e antinevoeiro do couro. Asseguram a dosagem das misturas de acabamento que se aplicam ao couro e realizam a manutenção de rotina da máquina.;', 'released', '["Operador de Máquinas de Acabamento de Couros", "Operadora de Máquinas de Acabamento de Couros"]'::jsonb, '8155'),
  ('http://data.europa.eu/esco/occupation/7d9c060a-f280-441d-baf9-7d4a6b520a2a', 'Diretor de Importação e Exportação de Computadores e Produtos Informáticos', 'Os diretores de importação e exportação de computadores e produtos informáticos implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Computadores e Produtos Informáticos", "Diretor de Importação e Exportação de Computadores e Produtos Informáticos", "Diretor de Vendas de Computadores e Produtos Informáticos", "Diretora de Importação e Exportação de Computadores e Produtos Informáticos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/7d9e2a65-758c-4cbd-b66d-3a595d3d63b1', 'Operador de Polígrafo', 'Os operadores de polígrafo preparam os indivíduos para a realização de testes poligráficos, realizam os testes e interpretam os resultados. Prestam atenção ao pormenor e utilizam uma série de instrumentos para monitorizarem as respostas respiratória, sudorípara e cardiovascular às perguntas colocadas durante o processo. Os operadores de polígrafo elaboram relatórios com base nos resultados e podem prestar depoimento em tribunal.', 'released', '["Operadora de Polígrafo", "Operador de Polígrafo"]'::jsonb, '2634'),
  ('http://data.europa.eu/esco/occupation/7daa8fed-9a78-4fe2-afc2-153fc423040b', 'Especialista em Comportamento Animal', 'Os especialistas em comportamento animal trabalham com animais e pessoas para estudar, observar, avaliar e compreender o comportamento dos animais em relação a fatores específicos e prevenir ou corrigir comportamentos inadequados ou problemáticos de cada animal através do desenvolvimento de ambientes e regimes de gestão adequados, em conformidade com a legislação nacional.', 'released', '["Especialista em Comportamento dos Animais", "Especialista em Comportamento Animal", "Perita em Comportamento Animal", "Perito em Comportamento Animal"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/7db415ec-0437-4a5e-95ea-622ea9f13dd0', 'Supervisor de Produção de Metais', 'Os supervisores de produção de metais supervisionam o processo de trabalho diário e as atividades dos trabalhadores numa fábrica de produção de metais. Supervisionam o pessoal, criam horários de trabalho, mantêm um ambiente de trabalho seguro e constituem o primeiro e mais acessível representante da direção com o qual os trabalhadores deverão contactar em caso de necessidade.', 'released', '["Supervisor de Produção de Metais", "Supervisora de Produção de Metais"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/7dbb116c-a4e7-41e8-9f28-c8a738d93e28', 'Técnico de Filtragem de Bebidas', 'Os técnicos de filtragem de bebidas operam máquinas que clarificam as bebidas antes da filtragem. Para o efeito, transferem bebidas fermentadas de barris para reservatórios para clarificar e espalham produtos químicos sobre a superfície das bebidas para auxiliar na sua clarificação. Em seguida, bombeiam as bebidas para as transferir para os tanques de filtragem.', 'released', '["Operador de Clarificação de Bebidas", "Operadora de Filtro de Bebidas", "Operadora de Clarificação de Bebidas", "Operador de Filtro de Bebidas", "Técnico de Filtragem de Bebidas", "Técnica de Filtragem de Bebidas"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/7dc05fcc-b079-45ed-b5d4-74c75f99976c', 'Compositor', 'Os compositores criam novas peças musicais numa variedade de estilos. Geralmente, registam a música criada sob a forma de notação musical. Os compositores podem trabalhar de forma independente ou como parte de um grupo ou conjunto. Muitos criam peças para acompanhar filmes, programas de televisão, jogos ou espetáculos ao vivo.', 'released', '["Compositora", "Compositor"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/7dea476a-dffe-4919-9ee2-fb222e283f41', 'Professor de Psicologia', 'Os professores de Psicologia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Psicologia, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Psicologia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Psicologia", "Professor de Psicologia", "Professora Universitária de Psicologia", "Professor Universitário de Psicologia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/7dec82e0-3bfc-4c48-812d-c2095bfe05bb', 'Diretor de Grande Superfície', 'Os gerentes de grande superfície organizam e controlam as operações e o pessoal dos estabelecimentos que prestam serviços de retalho.', 'released', '["Vice-Diretor de Grande Superfície", "Diretora de Grande Superfície", "Diretor de Grande Armazém", "Vice-Diretora de Grande Superfície", "Diretora de Grande Armazém", "Diretor de Grande Superfície"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/7e08d38d-30c9-4a6f-b88e-b28e87c0b259', 'Operador de Máquina Perfuradora de Madeira', 'Os operadores de máquina perfuradora de madeira utilizam máquinas de fresar ou mandriladoras para realizar furos em peças de madeira. A perfuração da madeira distingue-se da fresagem sobretudo pelo fato de o movimento principal ser para dentro da peça e não ao longo da superfície.', 'released', '["Operador de Máquina Perfuradora de Madeira", "Operadora de Máquina Perfuradora de Madeira"]'::jsonb, '7523'),
  ('http://data.europa.eu/esco/occupation/7e17f4ea-9565-41e0-b408-b52b5c9492a3', 'Supervisor de Entrada', 'Os supervisores de entrada asseguram que as pessoas que entram em locais públicos, tais como bares, restaurantes e recintos de concertos são adequadas e não representam potenciais problemas. São responsáveis pela aplicação das normas legais, mediante a verificação da idade legal para a entrada num bar, procedem à gestão de multidões e emergências, controlam os códigos de vestuário e lidam com comportamentos agressivos e abusivos.', 'released', '["Porteiro", "Supervisora de Entrada em Espaços Confinados", "Supervisor de Entrada", "Supervisora de Entrada"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/7e33b166-4a6d-40f3-8048-83b3a9d3ef49', 'Técnico de Transformação de Carne', 'Os técnicos de transformação de carne preparam carne fresca com ingredientes como especiarias, ervas aromáticas ou aditivos para fabricar preparados de carne prontos para venda.', 'released', '["Técnico de Transformação de Carne", "Técnica de Transformação de Carne", "Operadora de Transformação de Carne", "Operador de Transformação de Carne"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/7e46c066-2b98-4eaf-bed6-9848c79902e0', 'Operador de Compra e Venda de Bens Imobiliários', 'Os operadores de compra e venda de bens imobiliários compram e vendem bens imobiliários próprios, como apartamentos, habitações, terrenos e edifícios não residenciais com fins lucrativos. Podem investir ativamente nestas propriedades, com vista a aumentar o seu valor, através da reparação, renovação ou melhoria das instalações disponíveis. As suas outras tarefas podem incluir a pesquisa dos preços do mercado imobiliário e a realização de pesquisas de imóveis.', 'released', '["Operadora de Compra e Venda de Bens Imobiliários", "Operador de Compra e Venda de Bens Imobiliários"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/7eadbe33-d62e-4a82-8e3a-e89df5aefb2c', 'Montador de Produtos em Madeira', 'Os montadores de produtos em madeira montam produtos a partir de peças pré-fabricadas em madeira. Operam máquinas, frequentemente hidráulicas, que unem os vários elementos de um produto através de juntas, colas ou outros elementos de fixação. Os montadores de produtos em madeira colocam os elementos no sítio, operam a máquina e procuram detectar problemas.', 'released', '["Montadora de Produtos em Madeira", "Montador de Produtos em Madeira"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/7ed2e153-8da8-4c0d-b4c5-3402c623f34b', 'Carteiro', 'Os carteiros entregam o correio e encomendas às residências e às empresas. Efetuam entregas de correio e recolhem assinaturas junto dos destinatários. Desempenham outras funções no âmbito dos serviços postais de estações de correio ou de organizações relacionadas.', 'released', '["Carteiro", "Carteira"]'::jsonb, '4412'),
  ('http://data.europa.eu/esco/occupation/7ef064b1-aab8-4818-a468-8f17acbfd995', 'Técnico de Sistemas Hidroelétricos', 'Os técnicos de sistemas hidroelétricos instalam e efetuam a manutenção de sistemas em centrais hidroelétricas. Realizam inspeções, analisam problemas e efetuam reparações. Asseguram que as turbinas funcionam em conformidade com a regulamentação e prestam assistência aos engenheiros de sistemas hidroelétricos na construção de turbinas.', 'released', '["Técnica de Sistemas Hidroelétricos", "Técnico de Sistemas Hidroelétricos"]'::jsonb, '3113'),
  ('http://data.europa.eu/esco/occupation/7f0b46be-8b7a-4675-987d-89a8a7193730', 'Gerente de Loja Audiovisual', 'Os gerentes de loja audiovisual assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Música", "Gerentea de Loja Audiovisual"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/7f0d69cf-8b02-4a84-865a-37585dea9b43', 'Diretor de Radiodifusão', 'Os diretores de radiodifusão apresentam o horário do programa. Decidem quanto tempo um programa tem de difusão e quando é transmitido, com base em alguns fatores, tais como as audiências, a demografia dos espetadores, etc.', 'released', '["Diretora de Radiodifusão", "Diretor de Radiodifusão"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/7f0fe7d3-54c6-41e9-88ba-9d4f0f1a46b4', 'Engenheiro de Microsistemas', 'Os engenheiros de microssistemas investigam, concebem, desenvolvem e supervisionam a produção de sistemas microeletromecânicos (MEMS), que podem ser integrados em produtos mecânicos, óticos, acústicos e eletrônicos.', 'released', '["Engenheiro de Microsistemas", "Engenheira de Microsistemas"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/7f2761eb-4edc-48ad-9fbf-eed0a0db9a21', 'Físico', 'Os físicos são os cientistas que estudam os fenômenos físicos. Concentram a sua investigação em função da sua especialização, que pode ir da física das partículas atómicas ao estudo dos fenômenos do universo. Aplicam as suas conclusões à melhoria da sociedade, contribuindo para o desenvolvimento do aprovisionamento energético, do tratamento de doenças, do desenvolvimento de jogos, de equipamento de ponta e de objetos de utilização diária.', 'released', '["Física", "Biofísica", "Físico Forense", "Física Nuclear", "Petrofísica", "Biofísico", "Física Forense", "Físico Nuclear", "Físico", "Petrofísico", "Investigadora Física", "Investigador Físico"]'::jsonb, '2111'),
  ('http://data.europa.eu/esco/occupation/7f346896-a4fb-47a1-9572-13398bc297a6', 'Arrumador de Salas de Espetáculos', 'Os arrumadores de salas de espetáculos auxiliam os visitantes indicando o caminho num edifício grande, tal como um teatro, um estádio ou uma sala de espetáculos. Verificam os bilhetes para acesso autorizado, dão indicações para os lugares e respondem a perguntas. Quando necessário, os arrumadores de salas de espetáculos podem desempenhar tarefas de segurança e alertar o pessoal de segurança.', 'released', '["Arrumador de Salas de Espetáculos", "Arrumadora de Salas de Espetáculos"]'::jsonb, '9629'),
  ('http://data.europa.eu/esco/occupation/7f35043b-ebb5-40bf-9974-46a29915f6bf', 'Operador de Máquina para Costura de Livros', 'Os operadores de máquinas para costura de livros cuidam da máquina que cose papel para formar um volume. Verificam se os cadernos são inseridos de forma correta e a máquina não encrava.', 'released', '["Operador de Máquina para Costura de Livros", "Operadora de Máquina para Costura de Livros"]'::jsonb, '7323'),
  ('http://data.europa.eu/esco/occupation/7f46db3a-754b-4bda-b287-5932fa062ee9', 'Engenheiro Especialista em Eletrônica de Potência', 'Os engenheiros especialistas em eletrônica de potência concebem e testam circuitos para utilização em sistemas de potência eletrônica. Encontram soluções para falhas conhecidas nos designs mecânicos e colaboram com outros engenheiros na execução de tarefas transversais durante os testes dos designs.;', 'released', '["Engenheiro de Design de Eletrônica de Potência", "Engenheira de Tecnologia de Eletrônica de Potência", "Engenheira de Teste de Eletrônica de Potência", "Engenheira de Design de Eletrônica de Potência", "Engenheiro de Teste de Eletrônica de Potência", "Engenheiro de Tecnologia de Eletrônica de Potência", "Engenheira de Eletrônica de Potência", "Consultor de Engenharia Eletrônica de Potência", "Especialista em Engenharia Eletrônica de Potência", "Consultora de Engenharia Eletrônica de Potência", "Engenheiro de Eletrônica de Potência", "Engenheira Especialista em Eletrônica de Potência"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/7f7d2bfe-f038-436f-95ff-29bc90726430', 'Marshaller', 'Os marshallers fazem sinais aos pilotos para os auxiliar em operações como a viragem, o abrandamento, a paragem e o desligamento dos motores. Orientam aeronaves para os respetivos lugares de estacionamento ou para a pista. Também dão orientações aos pilotos através da condução de um carro «follow-me».', 'released', NULL, '5419'),
  ('http://data.europa.eu/esco/occupation/7f800e7d-9d86-406a-9116-b5eca7526869', 'Técnico de Estação de Tratamento de Água', 'Os técnicos de estações de tratamento de água efetuam a manutenção e a reparação de equipamentos de tratamento e fornecimento de água numa estação de tratamento de água. Asseguram o abastecimento de água limpa, analisando a qualidade da água, assegurando que é filtrada e tratada corretamente e efetuando a manutenção dos sistemas de distribuição.', 'released', '["Técnica de Estação de Tratamento de Água"]'::jsonb, '3132'),
  ('http://data.europa.eu/esco/occupation/7fbe45c6-1914-43ba-9cfb-e0a4e051da92', 'Operador de Rotogravura', 'Os operadores de rotogravura trabalham com prensas de gravura, em que a imagem está gravada diretamente num rolo. Instalam a prensa e controlam-na durante o seu funcionamento, garantindo a segurança e a resolução de problemas.', 'released', '["Operadora de Rotogravura", "Operador de Rotogravura"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/7fddf2b5-1ba7-4327-86f9-e5da8ddb28a6', 'Comerciante Grossista de Máquinas e Equipamento de Escritório', 'Os comerciantes grossistas de máquinas e equipamento de escritório investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Máquinas e Equipamento de Escritório"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/7ff7ab7d-12a6-4d87-ac91-8a8f3540b1c0', 'Diretor de Distribuição — Curtumes', 'Os diretores de distribuição — curtumes planificam a distribuição de couros, peles e produtos de couro a vários pontos de venda.', 'released', '["Diretor de Distribuição — Curtumes", "Diretor de Logística — Curtumes", "Diretora de Logística — Curtumes", "Diretora de Distribuição — Curtumes"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/8021f3a2-e3de-43c0-b366-075da74dc5b7', 'Terapeuta da Fala', 'Os terapeutas da fala centram-se na etiologia, na avaliação, no diagnóstico, no tratamento e na prevenção de problemas de comunicação e deglutição em pessoas de todas as idades, a fim de as ajudar a manter, promover, melhorar, adquirir ou recuperar a capacidade de comunicar verbalmente e não verbalmente. Abordam o desenvolvimento de funções linguísticas, do discurso, vocais e auditivas, bem como problemas e deficiências da zona craniana, facial e oral.', 'released', '["Logopedista"]'::jsonb, '2266'),
  ('http://data.europa.eu/esco/occupation/8022c821-1ed0-414e-b440-63cc88943a89', 'Comerciante Grossista de Relógios e de Artigos de Ourivesaria', 'Os comerciantes grossistas de relógios e de artigos de ourivesaria investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Relógios e de Artigos de Ourivesaria"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/802a0e5d-5625-4166-a1f0-d13e2586df55', 'Gravador', 'Os gravadores executam trabalhos de gravação em metal, madeira, borracha ou noutros materiais para criar imagens que são transferidas para superfícies, geralmente utilizando uma prensa de impressão. Os gravadores utilizam frequentemente ferramentas como os processadores de gravação de circuitos, os gravadores pantográficos e os equipamentos de serigrafia.', 'released', '["Gravadora", "Gravador"]'::jsonb, '2651'),
  ('http://data.europa.eu/esco/occupation/802d3a2f-b966-42e3-94df-683adfcff20c', 'Técnico de Pesca de Juvenis', 'Os técnicos de pesca de juvenis são responsáveis pela produção de organismos aquáticos. São especialistas na criação, desmame e produção de juvenis.', 'released', '["Técnico de Pesca de Juvenis", "Técnica de Pesca de Juvenis"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/804f1ae2-429c-48a9-9858-d5d42df144eb', 'Operador de Máquina de Secagem', 'Os operadores de máquina de secagem asseguram o correto funcionamento de secadores rotativos para retirar a humidade das matérias-primas ou dos produtos alimentares em transformação. Observam os instrumentos para verificar a temperatura do secador e regulam a pressão do vapor para determinar se os produtos têm o teor de humidade especificado.', 'released', '["Operador de Secador", "Operadora de Secador", "Operador de Máquina de Secagem", "Operador de Máquina de Secar", "Desidratadora", "Operadora de Máquina de Secagem", "Operadora de Máquina de Secar", "Desidratador"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/8050a89e-563b-4073-943b-84b0c4286c1f', 'Selecionador de Aves de Capoeira', 'Os selecionadores de aves de capoeira são especialistas que trabalham em explorações de aves de capoeira que determinam o sexo dos animais para separar os machos das fêmeas.', 'released', '["Selecionador de Aves Domésticas", "Selecionadora de Aves Domésticas", "Selecionador de Aves de Capoeira", "Sexador de Aves", "Sexadora de Aves", "Selecionadora de Aves de Capoeira"]'::jsonb, '6122'),
  ('http://data.europa.eu/esco/occupation/807a1ac3-4f56-41f3-a68c-d653d558eb0a', 'Co-Piloto', 'Os co-pilotos são responsáveis pela assistência aos comandantes através da monitorização dos instrumentos de voo, do tratamento das comunicações de rádio, da observação do tráfego aéreo e da substituição do piloto, conforme necessário. Obedecem às ordens do piloto, aos planos de voo e aos regulamentos e procedimentos das autoridades nacionais da aviação, das empresas e dos aeroportos.', 'released', '["Co-Pilota"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/808b5940-8092-4f08-bc37-9b60ee5761d8', 'Ensaiador', 'Os ensaiadores testam e analisam metais preciosos como a prata e o ouro para determinar o valor e as propriedades dos componentes utilizando técnicas químicas e físicas. Além disso, separam os metais preciosos ou outros componentes de outros materiais.', 'released', '["Ensaiadora-Fundidora", "Ensaiadora de Ouro e Prata", "Ensaiador de Metais", "Ensaiador-Fundidor", "Ensaiador de Ouro e Prata", "Ensaiador", "Ensaiadora", "Ensaiadora de Metais"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/808becc8-5a4e-4e71-a043-c2ea32b56ae3', 'Carregador de Armazém', 'Os carregadores de armazém executam o manuseamento e a armazenagem dos materiais através de atividades como a carga, descarga e movimentação de artigos num armazém ou sala de armazenagem. Trabalham de acordo com as ordens de inspeção dos materiais e fornecem documentação para o tratamento dos produtos. Os carregadores de armazém também gerem o inventário e asseguram a eliminação segura dos resíduos.', 'released', '["Carregador de Armazém", "Empregada de Armazém", "Carregadora de Armazém", "Empregado de Armazém"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/8099a96a-753b-49fc-a36a-d70b8aa9fdcf', 'Especialista em Import-Export de Animais Vivos', 'Os especialistas em import-export de animais vivos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Animais Vivos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/80a2aba7-ef7d-46ef-a8ec-15ff6131c0f1', 'Terapeuta de Medicina Tradicional Chinesa', 'Os terapeutas de medicina tradicional chinesa utilizam abordagens médicas alternativas para curar doenças em todas as suas formas. Também utilizam diversas terapias, como a utilização de medicamentos à base de plantas, a acupuntura, a massagens e as terapias alimentares, para aumentar a saúde geral do doente e prevenir a ocorrência de uma doença.', 'released', '["Especialista de Medicina Tradicional Chinesa", "Instrutor de ChiKung Terapêutico", "Terapeuta de Zen Shiatsu", "Instrutora de ChiKung Terapêutico", "Terapeuta de Shiatsu"]'::jsonb, '2230'),
  ('http://data.europa.eu/esco/occupation/80a648c5-ecb7-40e6-a4d4-7680291ffa74', 'Técnico de Ensaios de Material Rolante', 'Os técnicos de ensaios de material rolante testam o desempenho dos motores diesel e elétricos utilizados em locomotivas. Posicionam ou fornecem orientações aos trabalhadores para o posicionamento dos motores no banco de ensaios. Utilizam ferramentas manuais e máquinas para posicionar e ligar o motor ao banco de ensaios. Utilizam equipamento informatizado para introduzir, ler e registar dados de ensaios, como a temperatura, a velocidade, o consumo de combustível e a pressão do óleo e dos gases de escape.', 'released', '["Técnica de Ensaios de Material Rolante", "Técnico de Ensaios de Material Rolante"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/80c72c55-556a-41b1-87ef-a29c3d2afa6e', 'Professor de Economia e Gestão do Ensino Secundário', 'Os professores de Economia e Gestão do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Economia e Gestão. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Economia e Gestão através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Economia e Gestão do Ensino Secundário", "Professor de Economia e Gestão do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/80d880ec-3bae-45a2-a2d3-41345ee0b319', 'Responsável Pela Conservação da Natureza', 'Os responsáveis pela conservação da natureza gerem e melhoram o ambiente local em todos os setores de uma comunidade local. Promovem a sensibilização e a compreensão sobre o ambiente natural. Este trabalho pode ser muito variado e envolver projetos relacionados com espécies, habitats e comunidades. Informar as pessoas e sensibilizam o público em geral para as questões ambientais.', 'released', NULL, '2133'),
  ('http://data.europa.eu/esco/occupation/80db1e93-6dad-49aa-b465-d64a4a73141b', 'Diretor de Compras — Peles e Couro', 'Os diretores de compras — peles e couro planificam e adquirem os couros, as peles, o wet-blue ou as crostas em coordenação com os requisitos de produção. Negoceiam processos e preveem os níveis de procura dos produtos para satisfazer as necessidades das empresas e mantêm uma verificação constante dos níveis e da qualidade das unidades em estoque, a fim de maximizar a eficiência das empresas. Identificam potenciais fornecedores, visitam os fornecedores existentes e desenvolvem relações de negócio com os mesmos.', 'released', '["Diretora de Compras — Peles e Couro", "Diretor de Compras — Peles e Couro"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/80ec8f3e-2cda-4ea6-a382-ece99589ccdd', 'Professor de Arte do Ensino Secundário', 'Os professores de Arte do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Arte. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Arte através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Arte do Ensino Secundário", "Professora de Arte do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/80fe3002-3ae4-4d3b-8969-0f2ce1049d7d', 'Vendedor de Joalharia e Relógios', 'Os vendedores de joalharia e relógios vendem, procedem à manutenção e limpeza de joias e relógios em lojas especializadas.', 'released', '["Vendedora de Joalharia e Relógios", "Vendedor de Joalharia e Relógios"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/810e5e67-acd5-499a-b307-cf5bea330859', 'Gestor de Informação e Conhecimento Informático', 'Os gestores de informação e conhecimentos informático contribuem para a definição de uma estratégia de informação organizativa e aplicam políticas de informação e criação de conhecimentos, edição, armazenamento e distribuição. Gerem a manutenção e a evolução das informações estruturadas e não estruturadas. Criam estruturas digitais para permitir a exploração e a otimização das informações e dos conhecimentos, gerem a análise de dados e potenciam a inteligência empresarial.', 'released', '["Gestora de Informação de Tecnologias de Informação e Comunicação", "Gestora de Conhecimento Informático", "Gestora de Informação de TI", "Gestor de Conhecimento de Tecnologias de Informação e Comunicação", "Gestor de Conhecimento de TI", "Gestor de Informação de Tecnologias de Informação e Comunicação", "Gestora de Conhecimento de Tecnologias de Informação e Comunicação", "Gestor de Conhecimento Informático", "Gestor de Informação e Conhecimento Informático", "Gestora de Informação e Conhecimento Informático", "Gestora de Conhecimento de TI", "Gestor de Informação de TI", "Gerente"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/811595cc-3100-4ca0-b860-3a77349342ae', 'Engenheiro Hidráulico', 'Os engenheiros hidráulicos supervisionam a montagem, a instalação, a manutenção e os testes dos equipamentos hidráulicos, em conformidade com processos de fabrico especificados. Concebem projetos com esquemas e modelos de montagem, criam desenhos e listas de materiais para componentes e analisam equipamentos.', 'released', '["Engenheiro Hidráulico", "Engenheira Hidráulica", "Engenheira Hidráulico"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/812276dd-95ea-428b-b05e-a61c4089063c', 'Instrutor de Esqui', 'Os instrutores de esqui ensinam técnicas de esqui e de esqui avançado a indivíduos ou grupos. Aconselham os alunos sobre a escolha do equipamento, dão instruções sobre as regras de segurança alpina e planeiam e preparam o ensino do esqui. Os instrutores de esqui demonstram exercícios e técnicas durante as lições de esqui e dão a sua opinião aos alunos sobre a forma de melhorar o seu nível.', 'released', '["Instrutora de Esqui", "Instrutor de Equi"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/812c217d-32b7-4f6a-9faf-993d3577ac7f', 'Engenheiro do Conhecimento', 'Os engenheiros do conhecimento integram conhecimentos estruturados em sistemas informáticos (bases de conhecimentos), a fim de resolverem problemas complexos que exigem normalmente um elevado nível de competências humanas ou métodos de inteligência artificial. São também responsáveis pela divulgação ou extração de conhecimentos de fontes de informação, pela manutenção desses conhecimentos e pela sua disponibilização à organização ou aos usuários. Para tal, têm conhecimento das técnicas de representação e manutenção dos conhecimentos (regras, estruturas, redes semânticas, ontologias) e utilizam técnicas e ferramentas de extração de conhecimentos. Podem conceber e construir sistemas de inteligência artificial ou especializados que utilizem esses conhecimentos.', 'released', '["Engenheira de Tecnologias de Web Semântica", "Engenheira de Tecnologias da Web Semântica", "Engenheira de Informação", "Engenheiro da Informação", "Engenheiro de Tecnologias de Web Semântica", "Engenheiro de Tecnologias da Web Semântica", "Engenheira da Informação", "Engenheiro do Conhecimento", "Engenheiro de Informação", "Engenheira do Conhecimento"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/814205e9-8bd1-4653-bdbc-fd2f9e9a8225', 'Gerente de Loja de Cozinhas e Banheiros', 'Os gerentes de lojas de cozinha e de casas de banho são responsáveis pelas atividades e pelo pessoal em lojas especializadas na venda de cozinhas e casas de banho. Estes funcionários gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Loja de Casas de Banho", "Gerente de Loja de Cozinhas", "Gerente de Showroom de Cozinhas e Casas de Banho", "Gerentea de Loja de Cozinhas e Banheiros"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/81480b40-a318-47f3-9b2c-56b69ed67d95', 'Administrador de Redes Informáticas', 'Os administradores de redes informáticas mantêm o funcionamento de uma rede de comunicações de dados fiável, segura e eficiente, incluindo redes LAN, WAN, intranets e a Internet. Executam a atribuição de endereços de rede, a gestão e a implementação de protocolos de encaminhamento, como o ISIS, o OSPF e o BGP, de configurações da tabela de encaminhamento e determinadas implementações de autenticação. Realizam a manutenção e a administração de servidores (servidores de arquivos, portas de ligação a redes privadas virtuais, sistemas de detecção de intrusão), computadores de secretária, impressoras, encaminhadores, comutadores, firewalls, telefones, comunicações IP, assistentes pessoais digitais, smartphones, implementação de software, atualizações e correções de segurança, bem como uma vasta gama de tecnologias adicionais, incluindo de hardware e de software.', 'released', '["Gestora de Redes", "Administradora de Redes", "Engenheiro de Redes", "Engenheira de Redes", "Administrador de Redes", "Especialista em Redes", "Gestor de Redes", "Administradora de Redes Informáticas"]'::jsonb, '2522'),
  ('http://data.europa.eu/esco/occupation/8188136d-df82-4910-91e1-b185ec17c3c9', 'Trabalhador de Recepção de Leite', 'Os trabalhadores de recepção de leite utilizam dispositivos que assegurem a recepção qualitativa e quantitativa correta do leite cru. Efetuam operações de limpeza, armazenamento e distribuição iniciais de matérias-primas para as diferentes unidades de transformação.', 'released', '["Empregado de Recepção de Leite", "Trabalhador de Recepção de Leite", "Empregada de Recepção de Leite", "Trabalhadora de Recepção de Leite"]'::jsonb, '7513'),
  ('http://data.europa.eu/esco/occupation/81a1e1f5-cce3-444d-bfc3-9771236d57cd', 'Engenheiro de Manutenção de Aeronaves', 'Os engenheiros de manutenção de aeronaves procedem a inspeções, ajustes e pequenas reparações pré-voo e pós-voo para garantir um desempenho seguro e sólido das aeronaves. Inspecionam as aeronaves antes da descolagem para detectar anomalias, como fugas de óleo, problemas elétricos ou hidráulicos. Verificam a distribuição dos passageiros e da carga, bem como da quantidade de combustível, a fim de assegurar o cumprimento das especificações em matéria de peso e de equilíbrio.', 'released', '["Engenheiro de Manutenção de Aeronaves", "Técnica de Manutenção de Aeronaves", "Técnico de Manutenção de Aeronaves", "Engenheira de Manutenção de Aeronaves"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/81cc1583-3614-4207-8e54-00b8cd4ddf09', 'Diretor Fabril na Indústria Química', 'Os diretores fabris na indústria química coordenam a produção diária de produtos químicos, assegurando a qualidade dos produtos e equipamentos, a segurança do pessoal e a proteção do ambiente. Definem e implementam o orçamento de investimento, utilizam objetivos industriais e gerem a unidade como centro de lucro que representa a empresa no seu ambiente econômico e social.', 'released', '["Diretor de Unidade de Transformação Química", "Diretora de Unidade de Transformação Química", "Diretor Fabril na Indústria Química", "Diretora de Indústria Química", "Diretora Fabril na Indústria Química", "Diretor de Indústria Química"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/81f6a814-1f4e-47d4-9c75-47977c7267ee', 'Maquinista de Trem', 'Os maquinistas de comboio operam comboios que prestam serviços de transporte de passageiros ou de carga. São responsáveis por conduzir a locomotiva de forma segura, respeitando todos os regulamentos de segurança, operacionais e de comunicação pertinentes, e têm toda a responsabilidade pela segurança dos passageiros e da carga. A tarefa envolve a cooperação e a comunicação com o pessoal relevante no âmbito do gestor da infraestrutura, bem como com o pessoal a bordo do comboio.', 'released', NULL, '8311'),
  ('http://data.europa.eu/esco/occupation/81f8d141-3f67-4fb0-a349-db0147ef7b3a', 'Professor do Ensino Profissional', 'Os professores do ensino profissional formam os alunos no seu domínio de estudos especializado, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar na vocação especializada da sua escolha e ajudam ao desenvolvimento dos respetivos valores e atitudes. Os professores do ensino profissional acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no respetivo domínio através de trabalhos, testes e exames.', 'released', '["Professora do Ensino Profissional", "Professor do Ensino Profissional"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/81f8ea60-41d4-434a-b0fc-f870e83e7e27', 'Operador de Máquinas Misturadoras de Fertilizantes', 'Os operadores de máquinas misturadoras de fertilizantes procedem à operação e manutenção de máquinas que misturam ingredientes químicos para produzir fertilizantes, certificando-se de que o produto final esteja em conformidade com as especificações.', 'released', '["Operador de Máquinas Misturadoras de Fertilizantes", "Operadora de Máquinas Misturadoras de Fertilizantes"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/82025c02-9082-416c-998b-f51eb0359ee6', 'Recepcionista de Hotel', 'Os rececionistas de hotel fornecem o primeiro ponto de contato e assistência aos clientes de um hotel. Também são responsáveis pelas reservas, pelo processamento dos pagamentos e por dar informações.', 'released', '["Funcionário de Recepção", "Recepcionista", "Funcionária de Recepção"]'::jsonb, '4224'),
  ('http://data.europa.eu/esco/occupation/8213b4bc-60ce-4ffc-9e00-9758fb2003c6', 'Responsável Pelo Monitoramento e Avaliação', 'Os responsáveis pela monitorização e pela avaliação asseguram a conceptualização, o design, a execução e o acompanhamento das atividades de monitorização e avaliação de projetos, programas, políticas, estratégias, instituições ou processos, ao longo do ciclo de programação pertinente. Desenvolvem os métodos e instrumentos de monitorização, inspeção e avaliação necessários para recolher e analisar dados, e comunicam os resultados através da aplicação de quadros, teorias, abordagens e metodologias estruturadas de monitorização e avaliação. Os responsáveis pela monitorização e avaliação contribuem para a tomada de decisões mediante a produção de relatórios, produtos ou atividades de aprendizagem e gestão de conhecimentos. Podem igualmente participar em atividades de desenvolvimento de capacidades, ministrando formação e prestando apoio neste processo nas respetivas organizações ou a clientes e parceiros.;', 'released', '["Gerente de Avaliação de Impacto", "Oficial de Avaliação", "Oficial de Projeto MEL", "Oficial de M&A", "Avaliadora", "Especialista em Avaliação de Impacto Social", "Oficial de Monitoramento, Avaliação e Aprendizagem", "Oficial MEL", "Oficial MEIL", "Avaliador", "Oficial de Monitoramento, Avaliação, Impacto e Aprendizagem", "Analista de Monitoramento e Relatórios", "Oficial de Pesquisa e Avaliação", "Analista de Avaliação de Impacto Social", "Especialista em Monitoramento e Avaliação", "Oficial de Avaliação de Impacto Econômico"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/822bbc2d-bc6a-4fb5-afb8-89170120c6d8', 'Técnico de Manutenção Aeroportuária', 'Os técnicos de manutenção aeroportuária são responsáveis pela manutenção de todo o equipamento necessário para assegurar a funcionalidade do aeroporto, por exemplo ajudas visuais, sistemas elétricos aeroportuários, sistemas de bagagem e sistemas de segurança, bem como pela drenagem de pavimentos e manutenção de áreas não pavimentadas.', 'released', '["Técnico de Manutenção Aeroportuária", "Técnica de Manutenção Aeroportuária"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/8234eee9-1647-460d-8d62-7fe02cb884b0', 'Técnico de Ar Condicionado e Bombas de Calor', 'Os técnicos de ar condicionados e bombas de calor têm competência e capacidade para executar, de forma segura e satisfatória, a concepção, a pré-montagem, a instalação, a ativação, o funcionamento, a inspeção em serviço, a verificação de fugas, a manutenção geral, a manutenção dos circuitos, a desativação, a remoção, a recuperação, a reciclagem do refrigerante e a desmontagem de sistemas de refrigeração, ar condicionado e bombas de calor. Trabalham também com componentes elétricos, eletrotécnicos e eletrônicos dos sistemas de refrigeração, ar condicionado e bombas de calor.;', 'released', '["Técnico de Instalação de Bomba de Calor", "Técnico de Serviço de Ar Condicionado", "Técnico de Bomba de Calor", "Técnico de Serviço de Refrigeração", "Técnico de Serviço de Bomba de Calor", "Técnica de Bomba de Calor", "Técnica de Ar Condicionado", "Técnico de Refrigeração", "Mecânico de Refrigeração", "Técnica de Serviço de Refrigeração", "Técnica de Refrigeração", "Técnica de Instalação de Ar Condicionado", "Técnico de Ar Condicionado", "Técnico de Instalação de Refrigeração", "Técnica de Instalação de Bomba de Calor", "Técnica de Serviço de Ar Condicionado", "Técnica de Serviço de Bomba de Calor", "Técnica de Instalação de Refrigeração", "Técnico de Instalação de Ar Condicionado", "Mecânica de Refrigeração", "Técnica de Ar Condicionado e Bombas de Calor"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/823db06f-25e1-4658-b063-d6ef956b41f5', 'Diretor de Distribuição e Logística', 'Os diretores de distribuição e logística tomam decisões em matéria de serviços, operações e disposições logísticas. Têm em conta variáveis internas e externas com vista à eficácia e o sucesso dos serviços de logística organizacional. Prestam apoio adequado a todas as atividades da cadeia de abastecimento desde o início até ao fim. Estes profissionais organizam o armazenamento e a distribuição de produtos e asseguram que os produtos adequados são entregues ao local certo em tempo útil e a um bom custo.', 'released', '["Gestora de Logística", "Gestor de Logística", "Diretor de Distribuição e Logística", "Diretor de Logística", "Diretora de Logística", "Diretora de Distribuição e Logística"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/8249697a-3dc8-417d-9acf-3a7e0864069a', 'Supervisor de Assentamento de Revestimentos de Solo', 'Os supervisores de assentamento de revestimentos de solo acompanham as operações de assentamento de revestimentos de solo. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Assentamento de Revestimentos de Solo", "Supervisora de Assentamento de Revestimentos de Solo"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/825ab049-2f0c-4acf-b402-9c6bb51acca2', 'Gerente de Instalações Esportivas', 'Os gerentes de instalações desportivas dirigem e gerem uma instalação ou um local desportivo, incluindo as suas operações, programação, vendas, promoção, saúde e segurança, desenvolvimento e pessoal. Asseguram a prestação de um serviço excelente ao cliente, assegurando simultaneamente a realização dos objetivos comerciais, financeiros e operacionais.', 'released', '["Gerente de Sala Esportiva", "Gerente de Estádio", "Gerente de Ginásio", "Gerente de Clube de Fitness", "Gerentea de Instalações Esportivas"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/82616669-cc82-4455-9332-a2df209e9f3e', 'Engenheiro de Produção Inteligente em Microeletrônica', 'Os engenheiros de produção inteligente em microeletrónica concebem, planeiam e supervisionam a produção e a montagem de dispositivos e produtos eletrônicos, tais como circuitos integrados, eletrônica automóvel ou telefones inteligentes, num ambiente conforme com a Indústria 4.0.;', 'released', '["Engenheira de Tecnologia Microeletrônica", "Especialista em Tecnologia Microeletrônica", "Engenheiro de Produção Microeletrônica", "Consultora de Produção de Microeletrônica", "Engenheira de Manufatura Inteligente", "Consultor de Tecnologia Microeletrônica", "Engenheiro de Tecnologia Microeletrônica", "Engenheira de Produção Microeletrônica", "Profissional de Fabricação de Microeletrônica", "Consultor de Produção de Microeletrônica", "Especialista em Produção Inteligente", "Engenheira de Manufatura Microeletrônica", "Supervisor de Produção de Microeletrônica", "Consultora de Tecnologia Microeletrônica", "Especialista em Produções Microeletrônicas", "Engenheiro de Manufatura Inteligente", "Supervisora de Produção de Microeletrônica", "Engenheiro de Manufatura Microeletrônica", "Engenheira de Produção Inteligente em Microeletrônica"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/8269720b-49c7-4185-ad7e-05d8d31ac041', 'Vendedor de Jogos e Brinquedos', 'Os vendedores de jogos e brinquedos vendem brinquedos e jogos em lojas especializadas.', 'released', '["Vendedora de Brinquedos", "Vendedor de Prinquedos", "Vendedora de Jogos e Brinquedos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/8289625a-c1c1-4a49-8ddd-37be4c3cd3fc', 'Professor do Curso de Auxiliar de Enfermagem e Obstetrícia', 'Os professores do curso de auxiliar de enfermagem e obstetrícia formam os alunos no seu domínio de estudos especializado, a enfermagem e obstetrícia, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar. Os professores do curso de auxiliar de enfermagem e obstetrícia acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da enfermagem e obstetrícia através de trabalhos, testes e exames.', 'released', '["Professora do Curso de Auxiliar de Enfermagem e Obstretícia", "Professor do Curso de Auxiliar de Enfermagem e Obstretícia", "Professora do Curso de Auxiliar de Enfermagem e Obstetrícia"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/82b5c6dc-6a4d-4415-80d8-5cfedfc54de7', 'Assistente de Ensaios Clínicos', 'Os assistentes de ensaios clínicos apoiam a investigação clínica de medicamentos. Colaboram com investigadores e médicos em hospitais. Gerem documentos essenciais, como formulários de relatório de casos clínicos, protocolos de estudos e formulários de consentimento esclarecido. Arquivam registos pertinentes relacionados com os efeitos secundários dos medicamentos.', 'released', '["Assistentea de Ensaios Clínicos"]'::jsonb, '3213'),
  ('http://data.europa.eu/esco/occupation/82cbe20d-967c-4161-9ecd-eafc724d171c', 'Assistente de Terapia Ocupacional', 'Os assistentes de terapia ocupacional apoiam os terapeutas ocupacionais trabalhando com as pessoas e as comunidades para reforçar a sua capacidade de exercer as ocupações que pretendem, de que precisam de, ou que se espera que desempenhem, ou alterando a ocupação ou o ambiente para apoiar melhor o seus compromissos ocupacionais. Trabalham sob a supervisão de um terapeuta ocupacional. ; ; ;', 'released', '["Assistentea de Terapia Ocupacional"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/82d75f3b-644a-4582-ad6b-a2a1833e44cb', 'Especialista de Testes não Destrutivos', 'Os especialistas de testes não destrutivos realizam testes de veículos, embarcações, outros objetos fabricados e estruturas de construção sem terem de danificá-los. Utilizam equipamento especial, tais como raios X, ultrassons, radiográficos ou instrumentos de infravermelhos, para realizar atividades de ensaio e comunicar informações com base nos resultados observados.', 'released', NULL, '7543'),
  ('http://data.europa.eu/esco/occupation/82dea303-26e1-4bbc-a07c-cff3cac6b50e', 'Estilista de Cabelo', 'Os estilistas de cabelo lavam, secam, cortam e penteiam o cabelo de cantores e apresentadores e vários tipos de atores, incluindo atores de teatro, de cinema, de televisão e de vídeos de música. Trabalham em conjunto com o diretor de arte para conceber a aparência de todas as pessoas. Os estilistas de cabelo também tratam de perucas e cabelo postiço. Durante estas atividades artísticas, estão disponíveis para retocar no cabelo ou as perucas dos atores.', 'released', NULL, '5141'),
  ('http://data.europa.eu/esco/occupation/82e37849-30ec-4461-a40e-263d4c984f88', 'Paleontólogo', 'Os paleontólogos investigam e analisam formas de vida que existiam em antigas eras do planeta Terra. Procuram definir o percurso evolutivo e a interação com diferentes áreas geológicas de todos os tipos de organismos e plantas, pólen e esporos, animais invertebrados e vertebrados, seres humanos, vestígios como pegadas, e a ecologia e o clima.', 'released', '["Investigador Científico em Paelontologia", "Icnólogo", "Paleontólogo", "Micropaleontóloga", "Paleontóloga", "Micropaleontólogo", "Investigadora Científica em Paelontologia", "Icnóloga"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/82ea66b0-0f9c-44ed-94bc-0c5b829531b3', 'Fabricante de Guitarras', 'Os fabricantes de guitarras criam e montam peças para construir guitarras de acordo com instruções ou diagramas especificados. Trabalham a madeira, medem e colocam cordas, testam a qualidade das cordas e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Guitarras"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/82f90e87-de92-4678-adae-61d3e5f7e1e4', 'Diretor de Informação de Tecnologia da Informação', 'Os diretores de informação TIC definem e implementam a estratégia e a governação de TIC. Determinam os recursos necessários para a execução das estratégias de TIC, antecipam as evoluções do mercado das TIC e as necessidades das empresas. Contribuem para o desenvolvimento do plano estratégico da organização e asseguram que a infraestrutura das TIC apoia as operações e prioridades globais da organização.', 'released', '["Responsável Pela Informação", "Diretora de Informação TI", "Diretor de Informação TI", "Principal Responsável Pela Informação", "TI", "Diretora de Informação de Tecnologia da Informação"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/82fe0140-7069-47f9-a7d4-d63a611cb5bd', 'Diretor de Campanha Eleitoral', 'Os diretores de campanha eleitoral gerem a campanha de um candidato político e supervisionam as operações relacionadas com as eleições, a fim de garantir a sua exatidão. Desenvolvem estratégias de apoio aos candidatos e convencem o público a votar no candidato que representam. Realizam pesquisas a fim de avaliarem as imagens e ideias mais vantajosas para o candidato apresentar ao público, com o objetivo de garantir a maioria dos votos.', 'released', '["Diretora de Campanha Eleitoral", "Especialista em Marketing Político", "Diretor de Campanha Eleitoral"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/83191970-020d-4350-b2e0-be971533d286', 'Supervisor de Produção de Material Eletrônico', 'Os supervisores de produção de material eletrônico coordenam, planeiam e orientam o processo de produção de material eletrônico. Gerem os trabalhadores da linha de produção, supervisionam a qualidade dos produtos montados e realizam a gestão dos custos e dos recursos.', 'released', '["Supervisora de Produção de Material Eletrônico", "Supervisor de Produção de Material Eletrônico"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/834aab9b-2246-4c3e-ab4a-cf3de1267e1a', 'Instrutor de Condução de Veículos Ligeiros', 'Os instrutores de condução de veículos ligeiros ensinam às pessoas a teoria e a prática de conduzir um automóvel em segurança e em conformidade com os regulamentos. Ajudam os alunos a desenvolver as competências necessárias para a condução e preparam-nos para os exames teóricos de condução e o exame prático de condução.', 'released', '["Instrutora de Condução de Veículos Ligeiros", "Instrutor de Condução de Veículos Ligeiros"]'::jsonb, '5165'),
  ('http://data.europa.eu/esco/occupation/83588a0e-b63d-4483-a884-06f1e3a1a4be', 'Diretor de Agência de Tradução', 'Os diretores de agência de tradução supervisionam as operações de prestação de serviços de tradução. Coordenam os esforços de uma equipe de tradutores que traduzem material escrito de uma língua para outra. Asseguram a qualidade do serviço e a administração da agência de tradução.', 'released', '["Diretor de Agência de Tradução", "Diretora de Agência de Tradução"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/835d118e-11db-4b11-b055-d78bfe426cac', 'Afiador de Ferramentas', 'Os afiadores de ferramentas realizam processos de afiação de precisão em objetos e ferramentas metálicos. Afiam, aguçam ou suavizam superfícies metálicas utilizando as ferramentas e os instrumentos adequados. Os afiadores de ferramentas seguem as instruções das ferramentas e asseguram que as peças transformadas cumprem as especificações necessárias.', 'released', '["Afiador de Ferramentas", "Afiadora de Ferramentas"]'::jsonb, '7224'),
  ('http://data.europa.eu/esco/occupation/836f0a96-7546-4003-9fc8-714fc79199d4', 'Engenheiro Especialista em Contratos', 'Os engenheiros especialistas em contratos combinam conhecimentos técnicos sobre contratos e questões jurídicas com a compreensão das especificações e dos princípios da engenharia. Asseguram que ambas as componentes estão alinhadas no desenvolvimento de um projeto e preveem a conformidade de todas as especificações e questões de engenharia definidas nos contratos.', 'released', '["Engenheiro Especialista em Contratos", "Engenheira Especialista em Contratos"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/837502a6-57d9-4df4-903a-8a67dd53927f', 'Marinheiro Fluvial de Máquinas', 'Os marinheiros fluviais de máquinas executam trabalhos relacionados com o convés de um navio de transporte de águas interiores. Utilizam a sua experiência a bordo de um navio motorizado de navegação interior como membro da tripulação e têm um conhecimento básico dos motores.', 'released', '["Marinheiro Fluvial de Máquinas", "Marinheiro-Maquinista Fluvial", "Marinheira-Maquinista Fluvial", "Marinheira Fluvial de Máquinas"]'::jsonb, '8350'),
  ('http://data.europa.eu/esco/occupation/839d738b-8b54-4408-868a-6d8af102d2de', 'Montador de Material Circulante', 'Os montadores de material circulante utilizam ferramentas manuais, ferramentas elétricas e outros equipamentos, tais como equipamento de elevação ou robôs para construir, colocar e instalar peças pré-fabricadas para fabricar os subconjuntos e as estruturas do material circulante. Leem e interpretam os esquemas. Operam sistemas de controlo para determinar o desempenho funcional dos conjuntos e ajustar em conformidade.', 'released', '["Trabalhador de Montagem de Veículos Ferroviários", "Montadora de Material Circulante", "Montador de Material Circulante", "Trabalhador de Montagem de Material Circulante", "Trabalhadora de Montagem de Material Circulante", "Trabalhadora de Montagem de Veículos Ferroviários"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/83b30677-6468-4a04-b20c-15daf6bc8fb5', 'Especialista em Import-Export de Computadores, Equipamentos Periféricos e Programas Informáticos', 'Os especialistas em import-export de computadores, equipamentos periféricos e programas informáticos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Computadores, Equipamentos Periféricos e Programas Informáticos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/83dc2d94-9e30-493a-bd93-6346e05fe146', 'Conselheiro Familiar', 'Os conselheiros familiares prestam apoio e aconselhamento a adultos e adolescentes sobre questões como a reprodução, os métodos contracetivos, a gravidez ou a interrupção da gravidez, em conformidade com a legislação e as práticas. Fornecem igualmente informações sobre a manutenção de boas práticas de saúde e consultas de recomendação para a prevenção e o tratamento de doenças sexuais, trabalhando em colaboração com profissionais de medicina.', 'released', '["Conselheira Familiar", "Conselheiro Familiar"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/83de6811-975d-4f7c-b81e-604c0c17e800', 'Operador de Máquina Preparadora de Peixe', 'Os operadores de máquina preparadora de peixe regulam e supervisionam as instalações de fabrico de produtos à base de peixe. Mantêm a armazenagem de todos os ingredientes e equipamentos necessários para o fabrico em massa. Também executam processos como moldar, panar, fritar, congelar, regular a temperatura do sistema e controlar as velocidades.', 'released', '["Operadora de Máquina Preparadora de Peixe", "Operador de Máquina Preparadora de Peixe", "Operadora de Produção de Peixe", "Operador de Produção de Peixe"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/83e45d86-1bce-45c5-ba8b-097738f9f28b', 'Apresentador de Noticiário', 'Os apresentadores de noticiário apresentam notícias na rádio e na televisão. Apresentam peças jornalísticas pré-gravadas e notícias tratadas por repórteres em direto. Os apresentadores de noticiário são frequentemente jornalistas formados.', 'released', '["Apresentadora de Noticiário", "Apresentador de Noticiário"]'::jsonb, '2656'),
  ('http://data.europa.eu/esco/occupation/84219dd7-eb68-426e-9ec3-431eceb61c96', 'Inspetor de Motores de Material Rolante', 'Os inspetores de motores de material rolante efetuam a inspeção dos motores diesel e elétricos utilizados em locomotivas para garantir a sua conformidade com as normas e a regulamentação. Realizam inspeções de rotina, pós-revisão, pré-disponibilidade e pós-acidentes. Fornecem documentação para atividades de reparação e apoio técnico aos centros de manutenção e reparação. Verificam os registos administrativos, analisam o desempenho operacional dos motores e elaboram relatórios com as suas conclusões.', 'released', '["Inspetor de Motores de Material Rolante", "Inspetora de Motores de Material Rolante"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/842d4d83-7e18-493a-a4a6-3f2a36504b18', 'Agente de Controle de Acessos', 'Os agentes de controlo de acessos controlam o acesso e a saída em edifícios, armazéns ou outro tipo de propriedades para impedir a presença de pessoa não autorizada e incidentes indesejáveis. Previnem e identificam o furto de bens patrimoniais, investigam atividades suspeitas e redigem relatórios. Os agentes de controlo de acessos podem prestar assistência aos trabalhadores ou aos visitantes com pedidos ou indicações. Utilizam estações de rádio portáteis para comunicar e operar sistemas de alarme e computadores.', 'released', '["Guarda", "Vigilante", "Segurança", "Agentea de Controle de Acessos"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/8467dda9-34c6-4c6f-aa37-e7bddffac007', 'Profissional de Saúde dos Animais Aquáticos', 'Os profissionais de saúde dos animais aquáticos diagnosticam, previnem e tratam doenças, lesões e disfunções dos animais aquáticos através da aplicação de protocolos de amostragem adequados. Supervisionam a utilização de medicamentos, incluindo vacinas, e recolhem dados sobre a saúde dos peixes, apresentando relatórios periódicos ao pessoal adequado. Podem prestar cuidados a uma vasta gama de animais aquáticos ou especializar-se no tratamento de um determinado grupo ou numa determinada área. Podem prestar aconselhamento, apoio e formação ao pessoal das explorações aquícolas sobre as melhores práticas em matéria de saúde e bem-estar dos organismos criados.', 'released', '["Especialista em Saúde dos Animais Aquáticos"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/84871c2a-abd1-45eb-b03a-65e51a26fd84', 'Analista de Custos', 'Os analistas de custos elaboram análises e relatórios regulares de despesas e orçamento, a fim de contribuir para o planejamento global dos custos e as atividades de previsão de uma empresa. Analisam e conciliam balanços e identificam novas oportunidades de poupança de custos.', 'released', NULL, '2411'),
  ('http://data.europa.eu/esco/occupation/84931290-ad27-45ad-b611-9556c5facbdb', 'Assistente de Eventos', 'Os assistentes de eventos executam e seguem planos pormenorizados pelos gestores e organizadores de eventos. Especializam-se numa parte do planejamento, que pode ser a coordenação do serviço de catering, do transporte ou das instalações.', 'released', '["Assistentea de Eventos"]'::jsonb, '3332'),
  ('http://data.europa.eu/esco/occupation/849a656c-8559-4471-91ed-442c42b0b641', 'Técnico de Sistemas CAD na Indústria do Vestuário', 'Os técnicos de sistemas CAD utilizam software para criar planos de concepção de artigos de vestuário. Trabalham em desenho 2D, conhecido como modelação de superfícies, ou em desenho 3D, denominado modelação sólida. Utilizam a modelação de superfícies para desenhar uma representação plana do artigo de vestuário. Na modelação sólida, criam uma visualização 3D de uma estrutura ou componente, a fim de obterem uma perspetiva virtual do artigo de vestuário.', 'released', '["Técnico em Vestuário", "Modelista de Vestuário", "Técnica de Sistemas CAD na Indústria do Vestuário", "Técnica em Vestuário", "Técnico de Sistemas CAD na Indústria do Vestuário"]'::jsonb, '3118'),
  ('http://data.europa.eu/esco/occupation/84cb6e91-ce11-409e-9306-23c9698631af', 'Técnico de Levantamento de Solos', 'Os técnicos de levantamento de solos analisam os solos através da realização de trabalhos técnicos de geodesia, utilizando técnicas de levantamento de solos. Centram-se no processo de classificação dos tipos de solo e de outras propriedades do solo. Os técnicos de levantamento de solos utilizam equipamento de geodesia, bem como programas para obter e interpretar os dados relevantes e executar cálculos, conforme necessário.', 'released', '["Técnico de Pedologia", "Técnica de Pedologia", "Técnica de Levantamento de Solos", "Técnico de Levantamento de Solos"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/84cdc2ef-ee7c-42b1-be19-5e1c6b537f8f', 'Cuidador de Animais de Companhia', 'Os cuidadores de animais de companhia fornecem serviços de cuidado de animais, incluindo passear cães, cuidados ao domicílio, cuidados dos animais de companhia/em casa, cuidados diurnos e serviços de transporte de animais. Procedem à manutenção de registos, utilizam técnicas de manipulação adequadas e seguras e efetuam controlos de rotina da saúde e do bem-estar dos animais.', 'released', '["Cuidadora de Animais", "Pet-Sitter", "Cuidadora de Animais de Companhia", "Cuidador de Animais de Companhia", "Tratador de Animais", "Pet Sitter", "Cuidador de Animais", "Tratadora de Animais"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/84d45916-eef7-4c58-a73c-3639c9965014', 'Operador de Máquinas de Fabricação de Móveis em Plástico', 'Os operadores de máquinas de fabrico de móveis em plástico asseguram o correto funcionamento de máquinas de processamento de plástico que produzem peças tais como cadeiras e mesas de plástico. Inspecionam todos os produtos resultantes, detectam anomalias e eliminam peças inadequadas. Em alguns casos, podem montar diferentes peças de plástico para obter o produto final.', 'released', '["Operador de Máquinas de Fabricação de Móveis em Plástico", "Operadora de Máquinas de Fabricação de Móveis em Plástico"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/84dfc210-db07-4a83-87fe-d6131907ea83', 'Operador de Máquina de Preparação de Carne Processada', 'Os operadores de máquina de preparação de carne processada transformam carne quer manualmente quer utilizando máquinas de carne, tais como máquinas para triturar, moer ou misturar carne. Executam processos de conservação, tais como pasteurização, salga, secagem, liofilização, fermentação e fumagem. Os operadores de máquina de preparação de carne procuram manter a carne isenta de germes e de outros riscos para a saúde durante um período mais longo do que a carne fresca.', 'released', '["Operadora de Máquina de Preparação de Carne Processada", "Técnico de Produção de Preparados de Carne", "Técnica de Produção de Preparados de Carne", "Operador de Máquina de Preparação de Carne Processada"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/84e4c780-ee17-44dd-af6f-d1c06a3e353d', 'Diretor de Importação e Exportação de Maquinaria para Minas, Construção e Engenharia Civil', 'Os diretores de importação e exportação de maquinaria para minas, construção e engenharia civil implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Maquinaria para Minas, Construção e Engenharia Civil", "Diretora de Importação e Exportação de Maquinaria para Minas, Construção e Engenharia Civil", "Diretor de Vendas de Maquinaria para Minas, Construção e Engenharia Civil", "Diretor de Importação e Exportação de Maquinaria para Minas, Construção e Engenharia Civil"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/84f20f5d-149a-4512-b319-18a81d3d6026', 'Duplo', 'Os duplos executam ações demasiado perigosas para os atores executarem, que estes não são fisicamente capazes de fazer ou que requerem competências especializadas, tais como cenas de luta, saltos a partir de edifícios, dança e outras.', 'released', '["Dupla"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/84fabf82-4abf-4f41-99aa-55718a2e500b', 'Escriturário Fiscal', 'Os escriturários fiscais recolhem informações financeiras a fim de preparar documentos contabilísticos e fiscais. Também desempenham tarefas administrativas.', 'released', '["Escriturária Fiscal", "Escriturário Fiscal"]'::jsonb, '4312'),
  ('http://data.europa.eu/esco/occupation/8529edc5-96ad-4cde-b34a-f86ad3753e4d', 'Engenheiro de Vendas', 'Os engenheiros de vendas procedem à personalização técnica dos produtos com base nos pedidos e necessidades dos clientes (sobretudo da indústria pesada), como os equipamentos de construção. São responsáveis pelo contato entre as empresas e assumem a responsabilidade por operações complexas de reparação e manutenção.', 'released', '["Engenheiro de Vendas", "Engenheiro Pré-Vendas", "Engenheira Pré-Vendas", "Engenheira de Vendas", "Sales"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/853698f5-0f1e-42ae-9301-e5411a26dae2', 'Instrutor Militar', 'Os instrutores militares prestam formação aos novos recrutas ou cadetes sobre a teoria e a prática necessárias para se tornarem soldados ou oficiais, e precisam eles próprios de possuir experiência de oficial militar. Preparam e apresentam os cursos e os materiais teóricos durante a formação sobre temas como a legislação, a regulamentação nacional e internacional, modelos de defesa e ofensiva, questões mundiais, etc. Além disso, ocupam-se do treino físico dos cadetes, prestam-lhes formação no cuidado e manuseamento de armas e máquinas, em primeiros socorros, em técnicas defensivas e ofensivas e na operação de veículos militares, e sujeitam-nos a exercícios e treino físico exigentes. Os instrutores militares gerem planos de formação, desenvolvendo e atualizando os programas e os exercícios de formação no terreno sempre que necessário. Além disso, prestam assistência aos oficiais graduados na preparação de uma promoção e, de um modo geral, acompanham o progresso dos cadetes e avaliam o seu desempenho através de uma série de testes teóricos e físicos. Elaboram relatórios de desempenho e de avaliação para cada cadete individualmente.', 'released', '["Instrutor de Tiro Defensivo", "Instrutora de Tiro Defensivo", "Instrutora de Tática de Artilharia", "Instrutora da Academia Militar", "Instrutora de Educação Física Militar", "Instrutora Militar", "Instrutor de Educação Física Militar", "Instrutor da Academia Militar", "Instrutor de Tática de Artilharia", "Instrutor de Paraquedismo", "Instrutor Militar", "Instrutora de Paraquedismo"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/85482504-c83d-4038-80d9-265198d18b48', 'Assistente Social de Apoio Domiciliário', 'Os assistentes sociais de apoio domiciliário realizam serviços de avaliação e gestão dos cuidados. Organizam serviços domiciliários para prestar apoio a adultos vulneráveis com deficiências físicas ou em convalescença, com o objetivo de melhorar as suas vidas na comunidade e de lhes permitir viver de forma segura e independente na sua própria casa.', 'released', '["Assistentea Social de Apoio Domiciliário"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/857ed740-f4ae-43d0-8295-d6181f1d7eed', 'Diretor de Serviços Funerários', 'Os diretores de serviços funerários coordenam a logística dos funerais. Apoiam a família da pessoa falecida organizando os pormenores relativos ao local, à data e à hora do serviço fúnebre. Os diretores de serviços funerários contactam os representantes do cemitério para preparar o local, planeiam o transporte da pessoa falecida, prestam aconselhamento sobre os tipos de jazigos e requisitos legais ou formalidades administrativas. ; ; Os diretores de serviços funerários organizam as operações diárias do crematório. Supervisionam as atividades do pessoal no crematório e asseguram que prestam serviços em conformidade com os requisitos legais. Controlam o orçamento das receitas do serviço de crematório e desenvolvem e mantêm regras operacionais no crematório.', 'released', '["Diretor de Serviços Funerários", "Diretora de Serviços Funerários"]'::jsonb, '5163'),
  ('http://data.europa.eu/esco/occupation/85acc7e9-1fac-4e91-962b-8b8031f39487', 'Especialista em Tecnologia Têxtil', 'Os especialistas em tecnologia têxtil são responsáveis pela otimização da gestão dos sistemas de produção têxtil, sejam eles tradicionais ou inovadores. Desenvolvem e supervisionam o sistema de produção têxtil de acordo com o sistema de qualidade - processos de fiação, tecelagem, tricotagem, tingimento, acabamento e estampagem - usando metodologias adequadas de organização, gestão e controlo e tecnologias têxteis emergentes.;', 'released', '["Gerente do Departamento de Manufatura Têxtil", "Engenheiro Têxtil", "Tecnólogo Analítico Têxtil", "Tecnólogo de Tecido", "Oficial de Tecnologia Têxtil", "Engenheira Têxtil"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/85fdd1cb-98d3-4c40-a868-1078ce770440', 'Inspetor de Qualidade Têxtil', 'Os inspetores de qualidade têxtil asseguram que o fabrico de produtos têxteis está em conformidade com especificações predeterminadas.', 'released', '["Inspetora de Qualidade Têxtil", "Inspetor de Qualidade Têxtil"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/8606c0fd-c7cb-404d-887f-3a30ef7a81b4', 'Especialista em Análise Sensorial', 'Os especialistas em análise sensorial procedem a análises sensoriais com vista a compor ou melhorar aromas e fragrâncias para a indústria alimentar, bebidas e cosméticos. Baseiam o desenvolvimento de aromas e fragrâncias na investigação sensorial e dos consumidores. Os especialistas em análise sensorial realizam a investigação e análise de dados estatísticos para satisfazer as expectativas dos clientes.', 'released', NULL, '2113'),
  ('http://data.europa.eu/esco/occupation/862ed9e5-96ec-410d-a0fd-5206a05a7954', 'Operador de Máquinas Rebarbadoras Industriais', 'Os operadores de máquinas rebarbadoras industriais instalam e asseguram o correto funcionamento de máquinas rebarbadoras concebidas para decapar peças metálicas dos seus bordos rugosos, ou rebarbas, martelando as superfícies, para suavizá-las ou laminar os bordos, em caso de fendas ou fissuras irregulares, a fim de alisá-los na superfície.', 'released', '["Operador de Máquinas Rebarbadoras Industriais", "Operadora de Máquinas Rebarbadoras Industriais"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/865adac9-9bb7-4680-a13d-62b2942974ac', 'Operador de Máquinas de Serraria', 'Os operadores de máquinas de serraria trabalham com equipamento automático para serrar madeira em tábuas. Também utilizam várias máquinas para serrar, que transformam a madeira dando-lhe várias formas e tamanhos. Atualmente, estes processos são frequentemente controlados por computador.', 'released', '["Operadora de Máquinas de Serraria", "Operador de Máquinas de Serraria"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/866c7813-2c03-47d7-9bdc-192cfbace57c', 'Desenvolvedor Front-end', 'Os programadores de interfaces do usuário implementam, codificam, documentam e mantêm a interface de um sistema de software utilizando tecnologias de desenvolvimento de interfaces («front-end»).', 'released', '["Programadora de Interfaces do Usuário", "Programador de UI", "Programador de Interfaces do Usuário", "Programadora de UI", "Programador de IU", "Programadora de IU", "Programador", "Desenvolvedora Front-end"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/869e3a85-6e4c-4e3c-b14f-a8399c1abd2d', 'Operador de Linha de Montagem Automatizada', 'Os operadores de linhas de montagem automatizadas operam, efetuam a manutenção e a limpeza de máquinas de produção. São responsáveis pela montagem de um produto na sua totalidade ou de uma parte de um produto. Os operadores de linhas de montagem automatizadas executam todas as tarefas de um processo de produção através de um sistema de rotação.', 'released', '["Operador de Linha de Montagem Automatizada", "Operadora de Linha de Montagem Automatizada"]'::jsonb, '3139'),
  ('http://data.europa.eu/esco/occupation/86a0c9ab-c3fa-41a3-ad3e-d0083036b3d6', 'Mineralogista', 'Os mineralogistas estudam a composição, a estrutura e outros aspetos físicos da Terra. Analisam vários minerais e utilizam equipamento científico para determinar a sua estrutura e propriedades. O seu trabalho centra-se essencialmente na classificação e identificação de minerais, através da colheita de amostras e da realização de testes, análises e exames complementares.', 'released', NULL, '2114'),
  ('http://data.europa.eu/esco/occupation/86c49d9c-b37d-4a14-8e9d-d0357005a48d', 'Operador de Manutenção de Poços de Petróleo', 'Os operadores de manutenção de poços de petróleo procedem à manutenção e reparação de equipamento de exploração petrolífera e das máquinas utilizando ferramentas de mão e elétricas. Realizam os trabalhos de caráter geral, tais como a limpeza, a escavação, a raspagem e a pintura de componentes de perfuração.', 'released', '["Operador de Manutenção de Poços de Petróleo", "Operadora de Manutenção de Poços de Petróleo"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/86c892cf-09a3-44c8-b9d1-814d93dbcbb4', 'Especialista Militar', 'Os especialistas militares desempenham funções estratégicas, como a tomada de decisões táticas, a detecção e a identificação de potenciais ameaças e a localização de alvos e objetivos. Comunicam com as respetivas equipes e com outras equipes para assegurar a eficiência da operação, bem como supervisionar a segurança da equipe.', 'released', '["Analista de Informações", "Especialista em Missões de Vigilância", "Especialista em Guerra Eletrônica", "Operador de Missões de Vigilância", "Operadora de Missões de Vigilância", "Especialista em Defesa"]'::jsonb, '0210'),
  ('http://data.europa.eu/esco/occupation/86ca306c-ab99-420a-9e2a-aa73c5c4de22', 'Engenheiro Elétrico', 'Os engenheiros elétricos concebem e desenvolvem sistemas elétricos, equipamentos elétricos, componentes, motores e equipamentos com características de transmissão de energia. Participam em projetos de grande escala, como a concepção e manutenção de centrais elétricas e a distribuição de energia a aplicações mais pequenas, como eletrodomésticos.', 'released', '["Engenheira de Sistemas Elétricos de Energia", "Engenheiro Elétrico", "Projetista Elétrica", "Engenheiro de Sistemas Elétricos de Energia", "Projetista de Sistemas Elétricos", "Projetista de Instalações Elétricas", "Engenheira Elétrica", "Projetista Elétrico", "Engenheira Elétrico"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/86da9311-1f7a-40bb-af65-ed2a7178fcae', 'Operador de Máquinas de Fabricação de Produtos em Concreto', 'Os operadores de máquinas de fabrico de produtos em betão asseguram o correto funcionamento das máquinas utilizadas para produzir produtos em betão moldado. Realizam a lubrificação, a montagem e a extração de moldes. Participam também no processo de mistura de cimento.', 'released', '["Operador de Máquinas de Fabricação de Produtos em Concreto", "Operadora de Máquinas de Fabricação de Produtos em Concreto"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/86e8e172-234d-4e85-b9ae-6a4aecc2c321', 'Guia de Montanha', 'Os guias de montanha ajudam os visitantes, interpretam o património natural e fornecem informações e orientações aos turistas sobre expedições em montanhas. Assistem os visitantes em atividades como a caminhada, o alpinismo e o esqui, além de garantir a sua segurança através da monitorização das condições meteorológicas e de saúde.;', 'released', '["Treinador de Segurança de Montanha", "Guia de Esqui", "Líder da Montanha", "Líder da Expedição", "Líder ao Ar Livre", "Guia de Escalada", "Guia de Caminhada", "Guia de Caminhada na Montanha", "Guia Alpino", "Trabalhadora do Centro de Atividades ao Ar Livre", "Treinadora de Segurança de Montanha", "Guia de Expedição", "Trabalhador do Centro de Atividades ao Ar Livre", "Líder de Férias na Montanha"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/8712c91f-defb-4483-9e99-d9f896664a11', 'Vendedor de Eletrodomésticos', 'Os vendedores de eletrodomésticos vendem eletrodomésticos em lojas especializadas.', 'released', '["Vendedora de Eletrodomésticos", "Vendedor de Eletrodomésticos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/87426cf2-9e36-46a4-aa4f-6a8d20dd93d6', 'Diretor de Distribuição — Produtos Químicos', 'Os diretores de distribuição — produtos químicos planificam a distribuição de produtos químicos a vários pontos de venda.', 'released', '["Diretora de Logística — Produtos Químicos", "Diretor de Distribuição — Produtos Químicos", "Diretor de Logística — Produtos Químicos", "Diretora de Distribuição — Produtos Químicos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/874a2080-a9b6-46a9-8662-c9b7d4208f73', 'Designer de Cenários', 'Os designers de cenários desenvolvem um conceito para um espetáculo e supervisionam a sua execução. O seu trabalho baseia-se na investigação e na visão artística. O seu desenho é influenciado por, e influencia, outros desenhos e deve estar em conformidade com estes desenhos e com a visão artística global. Por conseguinte, os designers trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Durante os ensaios e o espetáculo orientam os operadores a fim de obter uma sincronização e uma manipulação ideais. Os designers de cenários desenvolvem esboços, desenhos, modelos, planos ou outra documentação de apoio ao seminário e à equipe do espetáculo. Podem também conceber stands de exposição para feiras e outros eventos.', 'released', NULL, '3432'),
  ('http://data.europa.eu/esco/occupation/87580fa5-39d2-4b7e-9274-b744e684f17c', 'Supervisor de Carpintaria', 'Os supervisores de carpintaria acompanham as operações de carpintaria na construção. Atribuem tarefas e tomam decisões rápidas para resolver problemas. Transmitem os seus conhecimentos aos aprendizes de carpintaria.', 'released', '["Supervisor de Carpintaria", "Supervisora de Carpintaria"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/87775d69-ae88-449e-ad71-6f9875711816', 'Técnico das Ciências Químicas', 'Os técnicos de ciências químicas monitorizam os processos químicos e realizam testes para a análise de substâncias químicas para fins de fabrico ou científicos. Trabalham em laboratórios ou instalações de produção, onde prestam assistência a químicos no seu trabalho. Os técnicos de ciências químicas realizam atividades laboratoriais, testam substâncias químicas, analisam dados e elaboram relatórios sobre o seu trabalho.', 'released', '["Técnico em Química", "Técnico das Ciências Químicas", "Técnica em Química", "Técnica de Química", "Técnico de Química", "Técnica das Ciências Químicas"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/87afe3f0-c891-45de-a498-ad2608471c86', 'Acabador de Vestuário', 'Os acabadores de vestuário colocam artigos de retrosaria (por exemplo, fundos, fechos, fitas) e cortam fios. Pesam, embalam e rotulam os materiais e os produtos.', 'released', '["Acabadora", "Acabador de Vestuário", "Acabador", "Acabadora de Vestuário"]'::jsonb, '9321'),
  ('http://data.europa.eu/esco/occupation/87cb6ef5-fa94-4af4-9511-6fe64c463835', 'Operador de Fabricação de Produtos Lácteos', 'Os operadores de fabrico de produtos lácteos instalam, operam e asseguram o correto funcionamento de equipamento para transformar leite, queijo, gelados e outros produtos lácteos.', 'released', '["Trabalhadora do Fabricação de Produtos Lácteos", "Operadora de Fabricação de Laticínios", "Operador de Fabricação de Produtos Lácteos", "Operador de Fabricação de Laticínios", "Trabalhador do Fabricação de Produtos Lácteos", "Operadora de Fabricação de Produtos Lácteos"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/87d0795a-d41f-47ee-979f-0ab7d73836e7', 'Assistente de Enfermagem', 'Os assistentes de enfermagem trabalham em equipes de enfermeiros nos domínios profissionais de enfermagem, cuidados sociais, cuidados de saúde e cuidados a pessoas de todos os grupos etários. Os assistentes de enfermagem prestam assistência na promoção e restauração da saúde dos doentes, prestando apoio físico e psicológico aos doentes, amigos e famílias.', 'released', '["Assistentea de Enfermagem"]'::jsonb, '5321'),
  ('http://data.europa.eu/esco/occupation/87e40e79-16fb-4391-9dcb-c15f40e026c1', 'Gerente de Casa de Apostas', 'Os gerentes de casa de apostas organizam e coordenam as atividades de uma casa de apostas. Supervisionam as operações diárias e facilitam a comunicação entre o pessoal e os clientes. Desempenham tarefas no setor da tesouraria, formam o pessoal e procuram melhorar a rentabilidade das suas atividades. Assumem a responsabilidade por todas as atividades de apostas e asseguram a observância das regras e regulamentos pertinentes em matéria de apostas.', 'released', '["Gerentea de Casa de Apostas"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/87e644b2-8bc1-42d4-bb14-cc4abb0bc715', 'Operador de Luz', 'Os operadores de luz controlam a iluminação de um espetáculo com base no conceito artístico ou criativo, em interação com os artistas. O seu trabalho é influenciado e influencia os resultados dos outros operadores. Por conseguinte, os operadores trabalham em estreita colaboração com os designers, os operadores e os artistas. Os operadores de luz preparam e supervisionam a instalação, dirigem a equipe técnica, programam o equipamento e operam o sistema de iluminação. Podem ser responsáveis por dispositivos de iluminação convencionais ou automatizados e, em alguns casos, controlam também o vídeo. O seu trabalho baseia-se em planos, instruções e outra documentação. ;', 'released', '["Operadora de Luz", "Operador de Luz"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/87fd9791-0922-4da0-a984-f518aadf85ec', 'Gerente de Loja de Munições', 'Os gerentes de loja de munições são responsáveis pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Subgerente de Loja de Armas", "Gerente de Loja de Armas", "Gerentea de Loja de Munições"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/8801ef16-92a4-4889-8f80-9b78206c7ec0', 'Especialista em Defesa de Direitos Humanos', 'Os especialistas em defesa de direitos humanos investigam e tratam os casos de violações aos direitos humanos, além de desenvolverem planos para reduzir as violações e assegurar o cumprimento da legislação em matéria de direitos humanos. Investigam queixas, analisando informações e entrevistando as vítimas e os autores das violações, e comunicam com as organizações envolvidas em atividades no domínio dos direitos humanos.', 'released', NULL, '2619'),
  ('http://data.europa.eu/esco/occupation/880a6cd1-2356-4994-8983-ac364763beaf', 'Manobrista', 'Os manobristas prestam assistência aos clientes conduzindo os seus veículos para um local de estacionamento específico. Também podem apoiar no manuseamento de bagagens dos clientes e fornecer informações sobre as taxas de estacionamento. Os manobristas mantêm uma atitude cordial para com os clientes e seguem as políticas e os procedimentos da empresa.', 'released', '["Manobrista"]'::jsonb, '8322'),
  ('http://data.europa.eu/esco/occupation/884beda8-d242-4fc3-a097-dc11098a7c3d', 'Tintureiro de Produtos Têxteis', 'Os tintureiros de produtos têxteis asseguram o correto funcionamento de máquinas de tingimento assegurando a instalação das mesmas. Preparam produtos químicos, tinturas, banhos de tintura e soluções de acordo com as fórmulas. Produzem amostras tingindo os têxteis e calculando as fórmulas e as tinturas necessárias para todo o tipo de fios e/ou têxteis.', 'released', '["Tintureiro de Produtos Têxteis", "Tintureira de Produtos Têxteis"]'::jsonb, '8154'),
  ('http://data.europa.eu/esco/occupation/88589d68-b870-440e-8444-32e9935cbbbc', 'Mecânico de Bordo', 'Os mecânicos de bordo são responsáveis pelos motores e pelas peças mecânicas do navio e substituem o equipamento e as peças defeituosos. Comunicam com outros membros da equipe ao nível operacional. Os mecânicos de bordo procedem à manutenção e reparação dos motores e de outras máquinas de embarcações, tais como caldeiras, geradores e equipamento elétrico.', 'released', '["Mecânica de Bordo", "Técnica de Mecânica Naval", "Técnico de Mecânica Naval", "Mecânico de Bordo"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/8862c29b-3810-4fbc-85c7-c9ee87535f73', 'Supervisor de Instalações Elétricas', 'Os supervisores de instalações elétricas acompanham as operações de instalação e manutenção de cabos elétricos e de outras infraestruturas elétricas. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Instalações Elétricas", "Supervisor de Instalações Elétricas"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/8870032b-9be3-4fd4-b9fb-1d8d9de33c5f', 'Operador de Máquinas de Destintar por Lavagem', 'Os operadores de máquinas de destintar por lavagem operam um reservatório em que o papel reciclado é misturado com água e dispersantes para lavar as tintas de impressão. A solução, designada por pasta de papel, é então escorrida para retirar as tintas dissolvidas.', 'released', '["Operadora de Máquinas de Destintar por Lavagem", "Operador de Máquinas de Destintar por Lavagem"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/88721b6c-d2ce-41c6-8878-73c0d3aacf39', 'Bombeiro', 'Os bombeiros são responsáveis pela resposta de emergência em caso de incêndio ou outras situações perigosas. Supervisionam a evacuação das instalações em perigo e asseguram que as vítimas sejam socorridas e tratadas pelos profissionais competentes. Assim que as instalações estão sem vítimas, garantem a extinção do incêndio, em conformidade com a regulamentação em matéria de saúde e segurança. Também regulam a limpeza do local e avaliam os danos.', 'released', '["Bombeiro", "Bombeira"]'::jsonb, '5411'),
  ('http://data.europa.eu/esco/occupation/88760821-9df4-47a6-a1c2-ac08b9759396', 'Designer de Miniaturas', 'Os designers de miniatura concebem e constroem adereços e cenários em miniatura para filmes. Constroem modelos utilizados para efeitos visuais que satisfazem o aspeto e os requisitos da produção. Cortam material utilizando ferramentas manuais para construir adereços e cenários tridimensionais.', 'released', NULL, '3432'),
  ('http://data.europa.eu/esco/occupation/88990bdf-4f6b-4411-82c9-9eecad1db8fb', 'Professor de Conservatório de Música', 'Os professores de conservatório de música ensinam os alunos com teoria específica e, principalmente, cursos de música baseados na prática, numa escola de música ou num conservatório ao nível do ensino superior, incluindo instrumentos musicais e treino de voz. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar na música. Os professores do conservatório de música acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho na prática da música, frequentemente por meio de trabalhos, testes e exames práticos.', 'released', '["Professora de Música", "Professor do Conservatório de Música", "Professor de Música", "Professora do Conservatório de Música", "Professora de Conservatório de Música"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/88a34087-311e-497e-ad81-a6843b9b461e', 'Montador de Motores Náuticos', 'Os montadores de motores náuticos constroem e instalam peças prefabricadas para motores utilizados em todos os tipos de embarcações, tais como os motores elétricos, os reatores nucleares, os motores de turbina a gás, os motores do tipo fora de borda, os motores a dois ou a quatro tempos e, em alguns casos, os motores a vapor marítimos. Analisam as especificações e os desenhos técnicos para determinar os materiais e as instruções de montagem. Inspecionam e testam os motores e rejeitam os componentes avariados.', 'released', '["Montadora de Motores Náuticos", "Montador de Motores Náuticos"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/88b21b2f-350c-4f41-9680-a53f8ea708ed', 'Operador de Máquinas de Enrolamento de Filamentos', 'Os operadores de máquinas de enrolamento de filamentos procedem ao controlo e à manutenção de máquinas que revestem os filamentos, em geral fibra de vidro ou carbono, em resina e os enrolam em torno de um molde rotativo para produzir canos, recipientes, tubos e outros produtos cilíndricos ocos.', 'released', '["Operador de Máquinas de Enrolamento de Filamentos", "Operadora de Máquinas de Enrolamento de Filamentos"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/88c55070-444a-45db-abe3-7b95c40bc9ec', 'Recepcionista de Centro de Fitness', 'Os rececionistas de centros de fitness promovem a saúde e a participação de membros novos e dos já existentes no centro de fitness. Proporcionam um ambiente limpo, seguro e cordial que promove a satisfação e a participação regular dos membros. São fonte de informação e de incentivo para todos os membros e ajudam ativamente os instrutores de fitness e outros trabalhadores, sempre que possível.', 'released', '["Recepcionista de Centro de Fitness"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/88c56310-14bc-4956-8450-ce0e178ae847', 'Operador de Secagem de Cerâmica', 'Os operadores de secagem de cerâmica gerem os túneis de secagem destinados a secar os produtos de argila antes do seu tratamento no forno.', 'released', '["Operador de Secagem de Cerâmica", "Operadora de Secagem de Cerâmica"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/8908d5aa-ac58-465e-9b75-7e02ed4af3a9', 'Coordenador do Tráfego Marítimo', 'Os coordenadores do tráfego marítimo gerem os movimentos de um navio nos portos e nas vias navegáveis. Asseguram a utilização eficiente dos navios de uma companhia de navegação.', 'released', '["Coordenador do Tráfego Marítimo", "Coordenadora do Tráfego Marítimo"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/8914badc-df5e-4671-908e-de5bc795658b', 'Diretor de Importação e Exportação de Equipamento Eletrônico e de Telecomunicações', 'Os diretores de importação e exportação de equipamento eletrônico e de telecomunicações implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Equipamento Eletrônico e de Telecomunicações", "Diretora de Importação e Exportação de Equipamento Eletrônico e de Telecomunicações", "Diretor de Vendas de Equipamento Eletrônico e de Telecomunicações", "Diretor de Importação e Exportação de Equipamento Eletrônico e de Telecomunicações"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/8918dda6-d99b-4572-a8ba-2a786bf5e4e9', 'Fabricante de Bonecas', 'Os fabricantes de bonecas concebem, criam e reparam bonecas utilizando vários materiais, tais como a porcelana, a madeira ou o plástico. Constroem moldes de formas e fixam peças com produtos adesivos e ferramentas manuais.', 'released', '["Fabricante de Bonecas de Porcelana", "Reparadora de Bonecas Antigas", "Reparador de Bonecas Antigas", "Fabricantea de Bonecas"]'::jsonb, '7533'),
  ('http://data.europa.eu/esco/occupation/891af43e-0946-4fa9-8115-a2b9be849cb0', 'Especialista em Import-Export de Relógios e Artigos de Ourivesaria', 'Os especialistas em import-export de relógios e artigos de ourivesaria possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Relógios e Artigos de Ouriverasia"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/89330b57-6a30-40e1-b623-50f47a4b0c34', 'Gestor de Subvenções', 'Os gestores de subvenções trabalham a nível profissional na administração e na gestão dos fundos de subvenções. Analisam os pedidos de subvenção apresentados por particulares, instituições de caridade, grupos comunitários ou departamentos de investigação universitários e decidem da concessão ou não de financiamento por fundos de beneficência, administrações públicas ou organismos públicos. No entanto, podem por vezes remeter o pedido de subvenção para uma comissão ou funcionário superiores. ;', 'released', '["Gestor de Subvenções", "Gestora de Subvenções", "Gerente"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/89860c2a-d217-432a-8636-84aa17f09c15', 'Engenheiro de Produção de Gás', 'Os engenheiros de produção de gás desenvolvem métodos para otimizar a extração e a produção de gás para energia e serviços. Concebem sistemas de produção de gás, supervisionam as operações de produção e aperfeiçoam os sistemas existentes.', 'released', '["Engenheiro de Produção de Petróleo", "Engenheira de Produção de Petróleo", "Engenheira de Produção de Gás", "Engenheiro de Produção de Gás"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/898f99f7-8c0a-4212-9e58-9ab00379e5ae', 'Ajustador', 'Os ajustadores utilizam máquinas-ferramentas para criar e modificar peças metálicas, de acordo com as especificações estabelecidas, a fim de montar componentes para máquinas. Garantem que os componentes acabados estão prontos para ser montados.', 'released', '["Torneiro", "Afinadora", "Torneira", "Afinador", "Ajustador", "Ajustadora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/89a0af2a-edf4-4d1a-8526-f4a8f476cea2', 'Responsável de Localização', 'Os responsáveis de localização são responsáveis pela aquisição de locais para filmagens no exterior do estúdio e por toda a logística que tal inclui. Negoceiam a utilização do local e gerem e mantêm o sítio durante a filmagem. Os responsáveis de localização gerem a segurança e a proteção da equipe de filmagem no local.', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/89a3b3af-7264-4e00-9a14-21e5fbd4ee87', 'Professor de Geografia do Ensino Secundário', 'Os professores de Geografia do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Geografia. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Geografia através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Geografia do Ensino Secundário", "Professora de Geografia do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/89a6d6e5-8362-4b99-b745-1c68bffbda77', 'Técnico de Tratamento de Fossas Sépticas', 'Os técnicos de tratamento de fossas sépticas procedem à limpeza e manutenção de sistemas de fossas sépticas. Reparam os danos e as falhas e asseguram a limpeza e manutenção das fossas, utilizando máquinas de limpeza e de manutenção, em conformidade com os procedimentos de segurança.', 'released', '["Técnica de Tratamento de Fossas Sépticas", "Técnico de Tratamento de Fossas Séticas"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/89b85c45-ddc7-4fe1-be5a-d3db2be11f3b', 'Gestor de Contas de Tecnologia da Informação', 'Os gestores de contas de TIC criam relações de negócio com os clientes tendo em vista facilitar a venda de hardware, software e serviços de telecomunicações ou de TIC. Além disso, identificam oportunidades e gerem o fornecimento e a entrega de produtos aos clientes. Cumprem os objetivos de vendas e mantêm a rentabilidade.', 'released', '["Gestora de Contas de TI", "Gestora de Contas Informáticas", "Responsável Pela Gestão de Contas Informáticas", "Gestor de Contas Informáticas", "Responsável Pela Gestão de Contas de TI", "Responsável Pela Gestão de Contas de Tecnologias de Informação e Comunicação", "Gestor de Contas de TI", "TI", "Gerente", "Gestora de Contas de Tecnologia da Informação"]'::jsonb, '2434'),
  ('http://data.europa.eu/esco/occupation/89b87aa2-4008-4cc7-96f8-e2b5ffe59f28', 'Ecologista', 'Os ecologistas realizam avaliações da saúde e da distribuição de organismos, nomeadamente pessoas, plantas e animais, bem como da relação entre os organismos e o seu ambiente. Normalmente, os ecologistas têm um domínio de especialização, por exemplo ecologia de água doce, marinha, terrestre, da fauna e da flora, no âmbito da qual realizam investigação e tarefas relacionadas.', 'released', NULL, '2133'),
  ('http://data.europa.eu/esco/occupation/8a007cd3-ba40-4c55-b238-587bd59e74b2', 'Ourives', 'Os ourives concebem, fabricam e vendem joalharia. Também ajustam, reparam e avaliam as pedras preciosas e as joias para os clientes, utilizando a experiência no trabalho do ouro e de outros metais preciosos. ;', 'released', NULL, '7313'),
  ('http://data.europa.eu/esco/occupation/8a0c1556-f616-4d41-a03c-8a093a644807', 'Técnico de Qualidade na Indústria do Calçado', 'Os técnicos de qualidade na indústria do calçado gerem todas as normas e técnicas relacionadas com os processos e os produtos. Executam tarefas utilizando sistemas de qualidade baseados em normas nacionais e internacionais. Analisam e interpretam os resultados, elaboram relatórios, aconselham sobre medidas corretivas e contribuem para o cumprimento de requisitos e objetivos em benefício da melhoria contínua e da satisfação do cliente.', 'released', '["Técnico de Qualidade na Indústria do Calçado", "Técnica de Qualidade na Indústria do Calçado"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/8a3498c7-470a-4067-b48e-f330d9b702e8', 'Segurador de Títulos', 'Os seguradores de títulos administram as atividades de distribuição de novos títulos de uma empresa. Trabalham em estreita colaboração com o organismo emissor dos títulos, a fim de definirem o preço e a sua compra e venda a outros investidores. Recebem comissões de corretagem dos seus clientes emitentes.', 'released', '["Subscritora de Títulos", "Segurador de Títulos", "Seguradora de Títulos", "Subscritor de Títulos"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/8a42240b-2b5c-4f6f-8787-f0547fbc46c5', 'Piloto Privado', 'Os pilotos privados operam aviões não comerciais para fins de lazer com uma quantidade limitada de lugares e de potência dos motores. Além disso, prestam serviços de transporte privado de passageiros.', 'released', '["Pilota Privado"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/8a451ae2-3c31-4f35-90af-6275b1b02f93', 'Encenador de Teatro', 'Os encenadores de teatro supervisionam e organizam a montagem de um espetáculo de representação através da unificação de vários esforços e aspetos de uma produção teatral. Asseguram a qualidade e a exaustividade da produção teatral e chefiam os membros da equipe criativa na realização da visão artística.', 'released', '["Encenadora de Teatro", "Encenador de Teatro"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/8a53f8d3-d995-4c7b-a70d-d79f76bdcb3f', 'Dietista', 'Os dietistas avaliam as necessidades nutricionais específicas das populações ou dos indivíduos ao longo das suas vidas e prestam aconselhamento para a manutenção, redução dos riscos ou restabelecimento da saúde das pessoas. Utilizando abordagens baseadas em dados concretos, os dietistas ajudam os indivíduos, as famílias e os grupos a fornecer ou selecionar alimentos nutricionalmente adequados, seguros, saborosos e sustentáveis. Para além dos cuidados de saúde, os dietistas melhoram o ambiente nutricional para todos através das autoridades públicas, da indústria, das universidades e da investigação.', 'released', '["Nutricionista em Saúde Coletiva", "Nutricionista", "Dietista Clínico", "Dietista de Serviço Alimentar", "Dietista Clínica"]'::jsonb, '2265'),
  ('http://data.europa.eu/esco/occupation/8a87e8b3-aecf-48a7-9837-4e022c3b9bb9', 'Técnico de Cromatografia', 'Os técnicos de cromatografia aplicam as técnicas de cromatografia correspondentes (como técnicas de permuta gasosa, de líquidos ou de iões) para a identificação e análise de compostos químicos em amostras. Efetuam a calibração e a manutenção da máquina de cromatografia e preparam o equipamento e as soluções. Os técnicos de cromatografia podem ainda desenvolver e aplicar novos métodos de cromatografia, em função das amostras e dos compostos químicos que têm de ser analisados.', 'released', '["Técnica de Cromatografia", "Técnico de Cromatografia"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/8a925aca-f636-437c-8962-5deae170e246', 'Engenheiro Técnico de Desenvolvimento de Embalagens de Alimentos e Bebidas', 'Os engenheiros técnicos de desenvolvimento de embalagens de alimentos e bebidas avaliam embalagens adequadas para vários produtos alimentares. Gerem questões relacionadas com a embalagem, ao mesmo tempo que asseguram o cumprimento das especificações dos clientes e dos objetivos das empresas. Desenvolvem projetos de embalagem sempre que necessário.', 'released', '["Engenheiro Técnico de Produção Alimentar", "Engenheira Técnica de Desenvolvimento de Embalagens de Alimentos e Bebidas", "Engenheira Técnica de Produção Alimentar", "Engenheiro Técnico de Desenvolvimento de Embalagens de Alimentos e Bebidas", "Engenheira Técnico de Desenvolvimento de Embalagens de Alimentos e Bebidas"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/8ae1e637-840b-4be0-a5df-8653375d8949', 'Supervisor de Aterros', 'Os supervisores de aterros coordenam as atividades e as operações de aterros e do pessoal de aterros. Pesquisam a legislação em matéria de gestão de resíduos e asseguram a conformidade das operações do aterro, e dirigem as operações de eliminação de resíduos.', 'released', '["Supervisora de Aterros", "Supervisor de Aterros"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/8afab6c4-6145-4ea1-a0ae-d2c3438bda7e', 'Técnico de Construção Naval', 'Os técnicos de construção naval constroem e reparam pequenas embarcações desde embarcações de recreio a embarcações militares. Elaboram esboços preliminares e criam modelos. Utilizam ferramentas manuais e elétricas para construírem embarcações mais pequenas ou supervisionam uma equipe de construtores navais. Também constroem picadeiros e rampas de lançamento para a construção, o transporte, o lançamento e o deslizamento do navio. Consoante os navios, poderão trabalhar com diferentes materiais, tais como metal, madeira, fibra de vidro, alumínio, etc.', 'released', '["Técnico de Construção Naval", "Técnica de Construção Naval"]'::jsonb, '7214'),
  ('http://data.europa.eu/esco/occupation/8b128a08-606f-4bb1-806e-07e0ed98b40e', 'Professor de Ciências Espaciais', 'Os professores das Ciências Espaciais são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências Espaciais, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio das Ciências Espaciais, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora Universitária de Ciências Espaciais", "Professora Universitária de Astrofísica", "Professor Universitário de Astrofísica", "Professora de Ciências Espaciais", "Professor Universitário de Ciências Espaciais", "Professor de Astrofísica", "Professor de Ciências Espaciais", "Professora de Astrofísica"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/8b26eec6-7497-4218-8364-9b5983b04ae7', 'Administrador no Domínio da Defesa', 'Os administradores no domínio da defesa desempenham tarefas de gestão e tarefas administrativas em instituições de defesa, tais como a manutenção de registos, a gestão do pessoal e a gestão das contas.', 'released', '["Administradora no Domínio da Defesa", "Administrador no Domínio da Defesa", "Diretora Administrativa para a Defesa", "Diretor Administrativo para a Defesa"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/8b273f5e-bdc5-4b73-80bd-3e324a20309b', 'Operador de Máquinas Misturadoras de Tinta', 'Os operadores de máquinas misturadoras de tinta procedem à operação e manutenção de máquinas que misturam lacas, solventes e tintas para fabricar tintas, certificando-se de que o produto final esteja de acordo com a fórmula especificada.', 'released', '["Fabricante de Tintas", "Operador de Máquinas Misturadoras de Tinta", "Operadora de Máquinas Misturadoras de Tinta"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/8b2d562c-8407-49cd-9843-636c352b8c82', 'Gravador de Metais', 'Os gravadores de metais fazem incisões de um desenho numa superfície metálica através de ranhuras de entalhar, geralmente para fins decorativos, incluindo armamento metálico. Para cortar o desenho na superfície utilizam ferramentas, tais como cinzéis ou buris. ; ;', 'released', '["Gravadora de Metais", "Gravador de Metais"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/8b304664-ba25-45fe-a5bf-80c727943a86', 'Técnico de Vitivinicultura', 'Os técnicos de vitivinicultura organizam a gestão da vinha e da adega, em alguns casos também a administração e a comercialização.', 'released', '["Técnico Vitivinícola", "Técnica Vitivinícola", "Técnica de Vitivinicultura", "Técnico de Vitivinicultura"]'::jsonb, '6112'),
  ('http://data.europa.eu/esco/occupation/8b490c1a-2f8c-4693-bcfa-ecfc88838a8e', 'Inspetor de Veículos a Motor', 'Os inspetores de veículos a motor inspecionam os motores diesel, a gás, a gasolina e elétricos utilizados em automóveis, ônibus, caminhões, etc., em instalações de montagem, como fábricas e oficinas mecânicas, a fim de garantir a sua conformidade com as normas e a regulamentação em matéria de segurança. Realizam inspeções de rotina, pós-revisão, pré-disponibilidade e pós-acidentes. Fornecem documentação para atividades de reparação e apoio técnico aos centros de manutenção e reparação. Verificam os registos administrativos, analisam o desempenho operacional dos motores e elaboram relatórios com as suas conclusões.', 'released', '["Inspetora de Veículos a Motor", "Inspetor de Veículos a Motor"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/8b6388a4-4904-471b-9331-d3b1211f5525', 'Gestor de Projetos de Tecnologia da Informação', 'Os gestores de projetos de TIC programam, controlam e orientam os recursos, as pessoas, o financiamento e as instalações para alcançar os objetivos dos projetos de TIC. Estabelecem orçamentos e calendários, procedem à análise de risco e à gestão da qualidade e elaboram os relatórios de encerramento dos projetos.', 'released', '["Gestor de Projetos de Informática", "Gestor de Projetos Web", "Gestor de Projetos de TI", "Gestora de Projetos de Tecnologias de Informação e Comunicação", "Gestor de Projetos de Tecnologias da Informação", "Gestora de Projetos de TI", "Gestora de Projetos Web", "Gestora de Projetos de Tecnologias da Informação", "Gestora de Projetos de Informática", "Gestor de Projetos de Tecnologias de Informação e Comunicação", "TI", "Gerente", "Gestora de Projetos de Tecnologia da Informação"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/8b828b9f-e41a-48d1-9d35-2c4378279a79', 'Coordenador de Conformidade de Dutos', 'Os coordenadores de conformidade de condutas acompanham, compilam e resumem todas as atividades de conformidade e cumprimento em infraestruturas e terrenos de condutas. Asseguram que os trabalhos são realizadas no âmbito dos quadros regulamentares. Procuram desenvolver e aplicar políticas de conformidade e recomendam formas de minimizar os riscos. Inspecionam os locais, recolhem provas e comunicam ao departamento de gestão as necessidades em matéria de conformidade.', 'released', '["Inspetor de Condutas", "Coordenadora de Conformidade de Dutos", "Inspetora de Condutas", "Coordenador de Conformidade de Dutos"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/8b8ae0a5-342c-43ae-b856-e1fea6fd6d1c', 'Técnico de Reparação de Máquinas-Ferramentas', 'Os técnicos de reparação de máquinas-ferramentas identificam os defeitos e reparam as máquinas-ferramentas, tais como brocas, motosserras, máquinas de cortar relva e máquinas retificadoras. Desmontam, testam e substituem peças com defeito nas ferramentas. Os técnicos de reparação de máquinas-ferramentas aconselham os clientes sobre produtos e métodos de manutenção para o seu equipamento. Podem vender estes produtos.', 'released', '["Técnico de Reparação de Máquinas-Ferramentas", "Técnica de Reparação de Máquinas-Ferramentas"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/8b97d85f-4a7a-4908-aa72-9c947c0cb0cd', 'Fabricante de Tapetes', 'Os fabricantes de tapetes utilizam técnicas artesanais para a criação de revestimentos têxteis para pavimentos. Criam tapetes e carpetes a partir da lã ou de outros têxteis, utilizando técnicas artesanais tradicionais. Podem utilizar diversos métodos, tais como a tecelagem, macramé ou esmirna, para criar tapetes de diferentes estilos.', 'released', '["Tecelão", "Tecelã", "Fabricantea de Tapetes"]'::jsonb, '7318'),
  ('http://data.europa.eu/esco/occupation/8b98dbc3-11f7-4720-86de-dcecee368be1', 'Operador de Máquinas de Moldagem por Sopro', 'Os operadores de máquinas de moldagem por sopro operam e controlam as máquinas de moldagem por sopro para formar artigos de plástico, de acordo com os requisitos. Regulam a temperatura, a pressão do ar e o volume de plástico, de acordo com as especificações. Os operadores de máquinas de moldagem por sopro removem os produtos acabados e cortam o material em excesso, utilizando uma faca. Voltam a triturar excedentes e peças rejeitadas para reutilização, utilizando uma máquina de trituração.', 'released', '["Operadora de Máquinas de Moldagem por Sopro", "Operador de Máquinas de Moldagem por Sopro"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/8ba8acb8-c0f2-4679-ae15-3a4f6e876c6f', 'Operador de Laminador de Plásticos', 'Os operadores de laminador de plásticos operam e controlam as máquinas para produzir rolos de plástico ou para nivelar e reduzir o material. Analisam as matérias-primas e os produtos acabados, a fim de garantir que estão em conformidade com as especificações.', 'released', '["Operador de Laminadores de Plásticos", "Operadora de Laminadores de Plásticos", "Operadora de Laminador de Plásticos"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/8bbac392-3d62-4c46-a56e-3f244fdda216', 'Gerente de Loja de Ortopedia', 'Os gerentes de lojas de ortopedia assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas. Gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Loja de Próteses", "Gerente de Loja de Podologia", "Gerentea de Loja de Ortopedia"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/8bc48c43-d976-458a-9e3c-ee784572351d', 'Engenheiro Projetista de Equipamento Industrial', 'Os engenheiros projetistas de equipamento industrial concebem várias ferramentas industriais de acordo com as necessidades dos clientes, os requisitos de fabrico e as especificações dos edifícios. Testam os desenhos, procuram soluções para eventuais problemas e supervisionam a produção.', 'released', '["Engenheira Especialista em Concepção de Equipamento Industrial", "Engenheiro Projetista de Equipamento Industrial", "Engenheira Projetista de Equipamento Industrial", "Engenheiro Especialista em Concepção de Equipamento Industrial"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/8bc845cb-0702-47e4-aabc-4036032b0a8d', 'Agente de Navegação', 'Os agentes de navegação representam o armador num porto estrangeiro. Asseguram o desalfandegamento atempado, de modo a que as mercadorias não tenham de permanecer demasiado tempo no porto. Os agentes de navegação asseguram igualmente que os seguros, as licenças e outras formalidades estão em ordem.', 'released', '["Agentea de Navegação"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/8bd74371-1818-47d5-a253-d703c51c5f26', 'Revisor de Conteúdos', 'Os revisores de conteúdos verificam se um texto tem uma leitura agradável. Asseguram que o texto respeita as convenções gramaticais e ortográficas. Os revisores de conteúdos leem e reveem materiais para livros, revistas especializadas, revistas e outros meios de comunicação social.', 'released', '["Revisora de Conteúdos", "Revisor de Conteúdos"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/8befd482-70e2-4d1e-8a09-091e15fe85c3', 'Educador Formado na Pedagogia Freinet', 'Os educadores formados na pedagogia Freinet ensinam os alunos através de abordagens que refletem a filosofia e os princípios de Freinet. Centram-se em métodos de aprendizagem baseados na curiosidade, na aplicação da democracia e na aprendizagem em cooperação. Aderem a um programa curricular específico que incorpora estes métodos de aprendizagem através dos quais os alunos utilizam práticas de tentativa e erro para desenvolverem os seus próprios interesses num contexto democrático e de autogoverno. Os educadores formados na pedagogia Freinet incentivam também os alunos a criar produtos de forma prática e a prestar serviços dentro e fora da escola, geralmente artesanais ou de iniciativa pessoal, pondo em prática a teoria da «pedagogia do trabalho». Gerem e avaliam todos os alunos em separado, de acordo com a filosofia de Freinet.', 'released', '["Educadora Formada na Pedagogia Freinet", "Educador da Escola Nova de Freinet", "Educador Formado na Pedagogia Freinet", "Educadora de Escola Nova de Freinet", "Educadora Formado na Pedagogia Freinet"]'::jsonb, '2342'),
  ('http://data.europa.eu/esco/occupation/8bf76ba6-e661-4574-9887-4f2cb943835a', 'Conselheiro Político', 'Os conselheiros políticos analisam os desenvolvimentos a nível da política externa e outras questões políticas, acompanham os conflitos e prestam consultoria em matéria de medidas de mediação, bem como no que respeita a outras estratégias de desenvolvimento. Redigem relatórios para assegurar a comunicação com os organismos governamentais e desenvolvem políticas e métodos de execução.', 'released', '["Conselheira Política", "Conselheiro Político", "Conselheira Político"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/8c0524b8-f878-4c68-8293-698d07c1807c', 'Comerciante Grossista de Matérias-Primas Agrícolas, Sementes e Rações Animais', 'Os comerciantes grossistas de matérias-primas agrícolas, sementes e rações animais investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Matérias-Primas Agrícolas, Sementes e Rações Animais"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/8c0cc417-6b09-4082-8062-2f0f7123a573', 'Diretor de Importação e Exportação de Máquinas e Equipamento de Escritório', 'Os diretores de importação e exportação de máquinas e equipamento de escritório implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Máquinas e Equipamento de Escritório", "Diretora de Importação e Exportação de Máquinas e Equipamento de Escritório", "Diretor de Importação e Exportação de Máquinas e Equipamento de Escritório", "Diretor de Vendas de Máquinas e Equipamento de Escritório"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/8c0f59c9-9a47-42e7-8287-aab19df4e6ab', 'Engenheiro Especialista em Microeletrônica', 'Os engenheiros especialistas em microeletrónica concebem, desenvolvem e supervisionam a produção de pequenos dispositivos e componentes eletrônicos, como microprocessadores e circuitos integrados.', 'released', '["Engenheiro Especialista em Microeletrónica", "Engenheira Especialista em Microeletrónica", "Engenheira Especialista em Microeletrônica"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/8c3f536e-ba66-4321-ba40-363dc39f129b', 'Arquiteto', 'Os arquitetos investigam, concebem e supervisionam a construção e o desenvolvimento de edifícios, espaços urbanos, projetos de infraestruturas e espaços sociais. Realizam o seu trabalho de concepção de acordo com o contexto circundante e as regras aplicáveis em áreas geográficas específicas, tendo em conta fatores como as funções, a estética, os custos e a saúde e segurança públicas. Têm conhecimento dos contextos sociais e dos fatores ambientais, nomeadamente as relações entre as pessoas e os edifícios e entre os edifícios e o ambiente. Participam em projetos pluridisciplinares destinados a desenvolver o tecido social de uma área geográfica e a promover projetos no domínio do urbanismo social.', 'released', '["Arquiteto de Edifícios", "Arquiteto", "Arquiteta", "Arquiteta de Edifícios"]'::jsonb, '2161'),
  ('http://data.europa.eu/esco/occupation/8c57af09-719c-42b3-be40-6ed4946236cc', 'Administrador de Bancos de Dados', 'Os administradores de bancos de dados testam, implementam e administram bancos de dados informáticos. Utilizam os seus conhecimentos especializados em sistemas de gestão de bancos de dados para planear, coordenar e aplicar medidas de segurança destinadas a salvaguardar os bancos de dados informáticos. Utilizam igualmente guiões («scripts») e arquivos de configuração para adaptar os bancos de dados às necessidades dos usuários.', 'released', '["Configurador de Bancos de Dados", "Administradora de Bancos de Dados", "Administrador de Bancos de Dados", "Gestor de Bancos de Dados", "Configuradora de Bancos de Dados", "Gestora de Bancos de Dados"]'::jsonb, '2521'),
  ('http://data.europa.eu/esco/occupation/8c778238-98a4-4fec-a828-a4e978fb7a64', 'Instalador de Tendas', 'Os instaladores de tendas instalam e desmontam abrigos temporários, tendas e tendas de circo com o alojamento associado para eventos e espetáculos. O seu trabalho baseia-se em instruções, planos e cálculos. Trabalham sobretudo no exterior e podem ser assistidas pela equipe local.', 'released', '["Instaladora de Tendas", "Instalador de Tendas"]'::jsonb, '7119'),
  ('http://data.europa.eu/esco/occupation/8c8b5cba-14b2-4728-b22c-eb90f1786e00', 'Responsável de Consultório Médico', 'Os responsáveis de consultórios médicos gerem as operações quotidianas de um consultório médico. Supervisionam o pessoal e a vertente comercial do consultório.', 'released', NULL, '3344'),
  ('http://data.europa.eu/esco/occupation/8c8ec7a2-adbb-4d1a-9a56-a7048d66c00b', 'Gestor de Vigilância Aérea e Coordenação de Códigos', 'Os gestores de vigilância aérea e coordenação de códigos asseguram que todos os componentes das infraestruturas de vigilância, tanto terrestres como aéreas, funcionam de forma segura, coesa e interoperável.', 'released', '["Operador Radarista de Detecção", "Gestor de Vigilância Aérea e Coordenação de Códigos", "Operadora Radarista de Detecção", "Gestora de Vigilância Aérea e Coordenação de Códigos", "Gerente"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/8cb59bc4-1f39-477e-beea-effed12d186c', 'Especialista em Escrita Técnica', 'Os especialistas em escrita técnica preparam uma comunicação clara, concisa e profissional dos criadores de produtos para os usuários dos produtos, como a ajuda em linha, os manuais do usuário, os documentos informativos, as especificações e os vídeos industriais. Para o efeito, analisam produtos, requisitos legais, mercados, clientes e usuários. Desenvolvem conceitos de informação e de meios de comunicação, normas, estruturas e apoio de ferramentas de software. Planeiam a criação de conteúdos e os processos de produção de suportes, desenvolvem conteúdos escritos, gráficos, de vídeo ou outros conteúdos, produzem suportes, lançam os seus produtos de informação e recebem o feedback dos usuários.', 'released', '["Especialista em Documentos Técnicos", "Especialista em Comunicação Técnica", "Especialista em Escrita Técnica", "Escritor Técnico", "Escritora Técnica", "Especialista em Documentação Técnica"]'::jsonb, '2641'),
  ('http://data.europa.eu/esco/occupation/8cc90646-fc23-445f-a95f-e28e6b5d5a05', 'Animador Turístico', 'Os animadores turísticos desenvolvem e organizam atividades de entretenimento para os hóspedes de uma unidade hoteleira. Implementam e coordenam atividades para entreter os clientes.', 'released', '["Técnica de Animação Turística", "Animador Turístico", "Animadora Turística", "Técnico de Animação Turística", "Animadora Turístico"]'::jsonb, '2659'),
  ('http://data.europa.eu/esco/occupation/8cce40c1-4479-47e7-b5fc-c976631d919f', 'Assistente de Direção', 'Os assistentes de direção desempenham funções variadas, geralmente sob supervisão geral. Executam tarefas administrativas e prestam apoio aos gestores para assegurar o bom funcionamento de todo o departamento.', 'released', '["Assistentea de Direção"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/8cf68522-dfc9-43c0-9f65-892703f4705e', 'Técnico de Eletricidade de Aeroportos', 'Os técnicos de eletricidade de aeroportos procedem à inspeção e manutenção dos sistemas de iluminação dos aeroportos. Registam as suas conclusões e formulam as ações a seguir.', 'released', '["Técnica de Eletricidade de Aeroportos", "Técnico de Eletricidade de Aeroportos"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/8d2df08e-0b2e-4837-8096-66595bbaab15', 'Operador de Fabricação de Correias de Borracha', 'Os operadores de fabrico de correias de borracha fabricam a transmissão e as correias transportadoras através da acumulação de telas de tecidos com borracha. Cortam a tela com a tesoura de acordo com o comprimento requerido e unem as telas com rolos e brochadoras. Os operadores de fabrico de correias de borracha inserem a correia acabada entre os rolos de pressão. Medem a correia acabada para verificar se a mesma está em conformidade com as especificações.', 'released', '["Operadora de Fabricação de Correias de Borracha", "Operador de Fabricação de Correias de Borracha"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/8d315e32-73f6-463d-a335-c200e0bac97d', 'Professor de Biologia do Ensino Secundário', 'Os professores de Biologia do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Biologia. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Biologia através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Biologia do Ensino Secundário", "Professor de Biologia do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/8d3cc890-5902-4fac-9438-6098a3ee437c', 'Operador de Recalcadora', 'Os operadores de recalcadora instalam e cuidam de recalcadoras, sobretudo prensas excêntricas, concebidas para moldar, através de processos de forjagem, peças metálicas, geralmente arames, varetas ou barras, na forma desejada, utilizando moldes divididos com múltiplas cavidades para comprimir o comprimento das peças e aumentar o seu diâmetro.', 'released', '["Operadora de Recalcadora", "Operador de Recalcadora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/8d3e8aaa-791b-4c75-a465-f3f827028f50', 'Enfermeiro de Cuidados Gerais', 'Os enfermeiros de cuidados gerais são responsáveis pela promoção e recuperação da saúde dos doentes, prestando apoio físico e psicológico aos doentes, amigos e famílias. Supervisionam também os membros da equipe designados.', 'released', '["Enfermeira de Cuidados Gerais", "Enfermeiro de Cuidados Gerais", "Enfermeiro Generalista", "Enfermeira Generalista"]'::jsonb, '2221'),
  ('http://data.europa.eu/esco/occupation/8d3fd879-986d-42e7-bf67-c3c415592fe3', 'Operador de Máquinas de Pré-Fabricados de Concreto', 'Os operadores de máquinas de pré-fabricados de betão pré-fabricam à mão produtos de construção de betão, estruturais e decorativos, tais como lareiras, blocos ou ladrilhos coloridos. Utilizam uma betoneira portátil.', 'released', '["Operadora de Máquinas de Pré-Fabricados de Concreto", "Operador de Máquinas de Pré-Fabricados de Concreto"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/8d410283-865d-4cbb-acae-ac7f69d9cf26', 'Engenheiro de Automóveis', 'Os engenheiros de automóveis concebem e supervisionam o processo de fabrico e o funcionamento de veículos a motor, tais como motociclos, automóveis, caminhões, ônibus e respetivos sistemas de engenharia. Concebem novos veículos ou peças mecânicas, supervisionam as modificações e resolvem problemas técnicos. Certificam-se de que os desenhos ou modelos cumprem as especificações de custos e outros condicionalismos. Realizam também estudos sobre aspetos ambientais, energéticos e de segurança.', 'released', '["Engenheira Mecânica do Setor Automóvel", "Engenheiro de Automóveis", "Engenheira de Automóveis", "Engenheiro Mecânico do Setor Automóvel"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/8d463763-5d38-4f47-903c-1c4df32141c1', 'Consultor de Cidades Inteligentes', 'Os consultores de cidades inteligentes prestam aconselhamento sobre soluções de sustentabilidade para a execução de iniciativas de cidades inteligentes. Executam projetos ambientais baseados em serviços inteligentes, tecnologias avançadas e transformação digital em zonas urbanas. Além disso, os consultores de cidades inteligentes desenvolvem planos de negócio para atrair investimentos, identificam desafios e oportunidades de negócios sustentáveis, bem como sinergias entre partes interessadas ou clientes públicos e privados.', 'released', '["Consultora de Cidades Inteligentes", "Consultor de Cidades Inteligentes"]'::jsonb, '2421'),
  ('http://data.europa.eu/esco/occupation/8d4ce4a2-3453-4aa3-befb-7a24595cd68f', 'Condutor de Veículos Blindados', 'Os condutores de veículos blindados conduzem o veículo blindado para transportar objetos de valor, tais como dinheiro, para diferentes locais. Nunca deixam o automóvel. Trabalham em cooperação com os guardas de veículos blindados que entregam os objetos de valor aos destinatários finais. Os condutores de veículos blindados asseguram a segurança do veículo a qualquer momento, seguindo as políticas da empresa.', 'released', '["Condutora de Veículos Blindados", "Condutor de Veículos Blindados"]'::jsonb, '8322'),
  ('http://data.europa.eu/esco/occupation/8d586ee9-0ab1-4155-a3b0-2ca786c8e48c', 'Analista Financeiro', 'Os analistas financeiros realizam pesquisas econômicas e produzem análises valiosas sobre questões financeiras como a rentabilidade, a liquidez, a solvência e a gestão de ativos. Apresentam recomendações sobre assuntos financeiros para os processos de tomada de decisão. Os analistas financeiros trabalham tanto no setor público como no setor privado.', 'released', '["Analista Financeiro", "Analista de Mercados Financeiros", "Analista Financeira"]'::jsonb, '2413'),
  ('http://data.europa.eu/esco/occupation/8d703e8f-1e57-4246-8a6b-cb87a760d4ab', 'Técnico de Ação Social', 'Os técnicos de ação social prestam apoio e ajudam as pessoas com serviços de cuidados. Ajudam as pessoas a viver vidas plenas e significativas na comunidade. Auxiliam bebés, crianças pequenas, adolescentes, adultos e adultos mais velhos. Cuidam das necessidades psicológicas, sociais, emocionais e físicas dos usuários do serviço. Trabalham numa grande variedade de contextos com indivíduos, famílias, grupos, organizações e comunidades.', 'released', '["Técnico de Ação Social", "Técnica de Ação Social"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/8d765d88-c8d6-406e-8dfe-e37c5aa89be6', 'Plataformista', 'Os plataformistas estabelecem ou quebram ligações quando o tubo de sondagem é colocado e retirado do orifício de perfuração. Procedem à montagem e desmontagem de tubos e sondas, bem como à recolha de amostras. Procedem à manutenção e reparação do equipamento na plataforma de perfuração.', 'released', '["Operadora de Plataforma de Perfuração de Petróleo", "Operador de Plataforma de Perfuração de Petróleo", "Assistente de Perfuração de Petróleo", "Perfurador", "Perfuradora de Solos"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/8d9ec84d-cf2d-4179-87bc-335cda54a427', 'Designer de Bancos de Dados', 'Os designers de bancos de dados especificam a estrutura lógica, os processos e os fluxos de informação da banco de dados. Concebem modelos de dados e bancos de dados para a aquisição de dados.', 'released', '["Arquiteto de Bancos de Dados", "Arquiteta de Bancos de Dados", "Designer de Bancos de Dados", "Arquiteta de Dados", "Arquiteto de Dados"]'::jsonb, '2521'),
  ('http://data.europa.eu/esco/occupation/8db28ebf-8818-4639-aa49-30324901836e', 'Especialista em Farmácia Hospitalar', 'Os especialistas em farmácia hospitalar prestam serviços especializados às empresas da indústria farmacêutica e às farmácias hospitalares. O papel do especialista em farmácia hospitalar varia em toda a Europa, em função das normas e da formação nacionais. ;', 'released', '["Farmacêutico Hospitalar", "Farmacêutica Hospitalar"]'::jsonb, '2262'),
  ('http://data.europa.eu/esco/occupation/8dded776-dc04-4099-a32c-7c5a41ee00e1', 'Representante de Serviço de Aluguel de Máquinas para Construção e Engenharia Civil', 'Os representantes de serviço de aluguer de máquinas para construção e engenharia civil são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Máquinas para Construção e Engenharia Civil"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/8de99659-5b10-4825-ac67-0c50189bcc3c', 'Gestor da Produção de Embalagens', 'Os gestores da produção de embalagens definem e analisam as unidades de embalagem, a fim de evitar danos ou perdas de qualidade dos produtos embalados. Além disso, concebem as embalagens de acordo com as especificações do produto e apresentam soluções para resolver problemas de embalagem.', 'released', '["Gestor de Produção de Embalagens", "Gestora de Produção de Embalagens", "Gerente", "Gestora da Produção de Embalagens"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/8e185c49-704e-49c0-8584-a7e0b618f628', 'Gestor de Financiamento', 'Os gestores de financiamento avaliam e autorizam a aprovação de pedidos de empréstimo para indivíduos e empresas. Asseguram a conclusão das transações entre as organizações de concessão de empréstimos, os mutuários e os vendedores. Os gestores de financiamento são especialistas em crédito ao consumo, hipotecário ou comercial.', 'released', '["Gestora de Financiamento", "Gestor de Financiamento", "Gerente"]'::jsonb, '3312'),
  ('http://data.europa.eu/esco/occupation/8e24c53a-9dc6-46d1-986b-48a93f20df2a', 'Chefe de Equipe de Produção Hortícola', 'Os chefes de equipe de produção hortícola são responsáveis por liderar e trabalhar com uma equipe. Organizam os horários de trabalho diários para a produção de culturas hortícolas e participam na produção.', 'released', '["Chefea de Equipe de Produção Hortícola"]'::jsonb, '6113'),
  ('http://data.europa.eu/esco/occupation/8ec6b513-3d44-4e94-b187-d55734a587a4', 'Corretor de Bolsa', 'Os corretores de bolsa atuam em nome dos seus clientes individuais ou institucionais, a fim de comprarem e venderem ações e outros títulos. Mantêm-se em estreito contato com os seus clientes e asseguram que o que compram ou vendem no mercado bolsista está de acordo com as pretensões dos seus clientes. Os corretores de bolsa realizam pesquisas analíticas, através de vários métodos, para fazerem recomendações aos seus clientes e expandirem a sua base de clientes.', 'released', '["Corretor de Bolsa", "Corretora de Bolsa"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/8ec8df02-e9dd-43b7-b416-5846ae0414ab', 'Agente Imobiliário', 'Os agentes imobiliários administram o processo de venda ou arrendamento de imóveis residenciais e comerciais ou de terrenos, em nome dos seus clientes. Investigam o estado do imóvel e avaliam o seu valor a fim de proporem o melhor preço aos seus clientes. Negoceiam, elaboram contratos de venda ou de arrendamento e estabelecem contatos com terceiros, a fim de cumprirem os objetivos definidos durante as transações. Realizam trabalhos de investigação para determinar a legalidade da venda de um imóvel antes de ser vendido e certificam-se de que a transação não está sujeita a quaisquer litígios ou restrições.', 'released', '["Agente Imobiliária", "Agente Imobiliário", "Agentea Imobiliário"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/8edc768c-0bc6-4d65-b559-50f9fb2cc93f', 'Construtor de Correias Trapezoidais', 'Os construtores de correias trapezoidais fabricam correias trapezoidais a partir de rolos de borracha calandrados. Medem a quantidade de borracha necessária e cortam-na com tesouras. Os construtores de correias trapezoidais esfregam cola de borracha nas partes laterais da correia. Colocam correias no tambor para comprimir materiais em conjunto e cortam a correia com uma largura especificada com uma faca.', 'released', '["Construtora de Correias Trapezoidais", "Construtor de Correias Trapezoidais"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/8edd8bff-cb59-4c9c-ab0f-59e77d18be48', 'Especialista em Manutenção Preditiva', 'Os especialistas em manutenção preditiva analisam os dados recolhidos a partir de sensores localizados em fábricas, máquinas, carros e ferrovias, entre outros, para monitorizar o seu estado, a fim de manter os usuários informados e, eventualmente, notificar a necessidade de efetuar operações de manutenção.;', 'released', '["Coordenador de Manutenção Preditiva e Preventiva", "Especialista em Confiabilidade de Manutenção", "Especialista em Confiabilidade de Equipamentos", "Engenheiro de Manutenção Preditiva", "Especialista em Confiabilidade", "Planejador de Manutenção de Engenharia de Confiabilidade", "Engenheira de Manutenção Preditiva", "Coordenadora de Manutenção Preditiva e Preventiva"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/8f10ea9b-bfdf-4a4c-9fa7-b6e02daa93e5', 'Chef de Confeitaria', 'Os chefs de pastelaria são responsáveis pela preparação, confeção e apresentação das sobremesas, dos produtos doces e dos produtos de panificação.', 'released', '["Padeiro", "Padeira", "Pasteleiro", "Pasteleira", "Chefe de Pastelaria"]'::jsonb, '3434'),
  ('http://data.europa.eu/esco/occupation/8f324afc-6ae8-48f5-af68-0fac08024fd1', 'Responsável Pela Gestão de Obras de Arte', 'Os responsáveis pela gestão de obras de arte organizam, gerem e documentam a circulação de artefactos entre museus e unidades de armazenamento, mostras e exposições. Tal acontece em colaboração com parceiros públicos ou privados, como transportadores de arte, seguradoras e restauradores, dentro e fora do museu.', 'released', NULL, '2621'),
  ('http://data.europa.eu/esco/occupation/8f592e05-8035-4646-b33e-a4ea2c2314e3', 'Operador de Acabamentos em Artigos de Marroquinaria', 'Os operadores de acabamento em artigos de marroquinaria organizam produtos de marroquinaria para acabamento aplicando diferentes tipos de acabamento (por exemplo, cremoso, oleoso, ceroso, polimento, revestimento de plástico, etc.). Utilizam ferramentas, meios e materiais para incorporar as pegas e aplicações metálicas em sacos, malas e outros acessórios. Estudam a sequência de operações de acordo com as informações recebidas do supervisor e da ficha técnica do modelo. Aplicam técnicas para a engomagem, aplicação de creme ou óleo, aplicação de líquidos para impermeabilização, lavagem de couros, limpeza, polimento, enceramento, escovagem, queimadura de pontas, remoção de resíduos de cola e pintar os remates, de acordo com as especificações técnicas. Também inspecionam visualmente a qualidade do produto acabado, prestando especial atenção à ausência de rugas, retilinearidade das costuras e limpeza. Corrigem anomalias ou defeitos que podem ser resolvidos pelo acabamento e comunicados ao supervisor.', 'released', '["Operadora de Acabamentos em Artigos de Marroquinaria", "Operador de Acabamentos em Artigos de Marroquinaria"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/8f654b67-89f8-4669-8c9c-a4875bf22699', 'Operador de Laminadores de Papel', 'Os operadores de laminadores de papel asseguram o correto funcionamento de uma máquina que aplica uma camada de plástico ao papel para o reforçar e proteger da humidade e das manchas.', 'released', '["Operadora de Laminadores de Papel", "Operador de Laminadores de Papel"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/8f71761e-6fa5-4237-a240-4d0c7feff026', 'Operador de Forno', 'Os operadores de forno monitorizam o funcionamento de um forno industrial, normalmente automático, que recebe carvão em pó, lavado e betuminoso misturado, e que o aquece a temperaturas entre 1 000 e 2 000 °C, sem a presença de oxigénio, a fim de obter coques. Os coques acabados são então temperados com água ou ar e preparados para transporte.', 'released', '["Operadora de Forno", "Operador de Forno"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/8f8455a9-d2ac-4f1c-ac83-4f4aa82b1eb7', 'Vendedor de Material Ortopédico', 'Os vendedores de material ortopédico vendem produtos ortopédicos em lojas especializadas.', 'released', '["Vendedor de Material Ortopédico", "Vendedora de Material Ortopédico"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/8f928d49-da89-4d07-9123-2151a4d276d4', 'Gestor de Mudanças', 'Os gestores de mudanças coordenam todos os recursos e atividades incluídos nos serviços de mudanças. Trabalham em conjunto com os clientes para definir os requisitos do serviço e adaptá-lo às suas exigências. Gerem a comunicação com as companhias de transporte, os responsáveis pela planificação e os transportadores, a fim de assegurar a conformidade, a eficiência da empresa e a satisfação do cliente.', 'released', '["Gestora de Mudanças Internacionais", "Gestora de Mudanças", "Gestor de Mudanças Rodoviárias", "Gestora de Mudanças Rodoviárias", "Gestor de Mudanças Internacionais", "Gestor de Mudanças", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/8f9b20ff-86b3-478c-8054-73a220973d6f', 'Operador de Funiculares', 'Os controladores de funiculares operam sistemas e quadros de comando mantendo sob controlo as operações de um conjunto variado de modos de transporte operados por cabo. Podem operar cabinas aéreas, teleféricos, funiculares, etc. Asseguram o funcionamento contínuo e intervêm nas operações quando ocorrem situações imprevistas.', 'released', '["Operadora de Funiculares", "Operador de Funiculares"]'::jsonb, '8343'),
  ('http://data.europa.eu/esco/occupation/8fc3d559-d61c-418c-ad4a-bf4c6b2909e3', 'Agente de Controle de Multidões', 'Os agentes de controlo de multidões mantêm uma vigilância constante da multidão durante um evento específico, tais como discursos públicos, eventos desportivos ou concertos, a fim de prevenir e reagir rapidamente a incidentes. Controlam a entrada no local, vigiam o comportamento da multidão, lidam com comportamentos agressivos e efetuam evacuações de emergência.', 'released', '["Agentea de Controle de Multidões"]'::jsonb, '5419'),
  ('http://data.europa.eu/esco/occupation/8fdce434-caaa-42c7-a77c-7ba8d1cbc4be', 'Construtor de Células Eletrolíticas', 'Os construtores de células eletrolíticas criam, concluem e testam células eletrolíticas em betão, utilizando equipamentos, ferramentas e betoneiras.', 'released', '["Construtor de Células Eletrolíticas", "Construtora de Células Eletrolíticas"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/903dc1bf-2da8-477d-83b2-687d360cf1da', 'Mediador Intercultural', 'Os mediadores interculturais especializam-se na interação social entre partes de diferentes culturas, aconselham as organizações sobre as interações internacionais com vista à otimização do seu desempenho e facilitam a cooperação e a interação positiva com organizações e indivíduos de outras culturas.', 'released', '["Mediadora Intercultural", "Mediador Intercultural"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/90569478-805c-4d14-a1ba-e9c9c4ac2818', 'Assistente Social de Apoio à Vítima', 'Os assistentes sociais de apoio à vítima prestam assistência e aconselhamento a pessoas que foram vítimas ou testemunhas de crimes, como agressões sexuais, violência doméstica ou comportamentos antissociais. Desenvolvem soluções em função das diferentes necessidades e sentimentos das pessoas.', 'released', '["Assistente Social Especialista em Apoio a Vítimas de Violência Sexual", "Assistente Social de Apoio a Vítimas de Maus Tratos", "Assistente Social de Apoio a Vítimas de Violência Doméstica", "Assistentea Social de Apoio à Vítima"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/90a73720-642d-4f45-88e7-8f593a5e0df2', 'Professor de Cursos Profissionais de Tecnologias dos Transportes', 'Os professores de cursos profissionais de tecnologias dos transportes formam os alunos no seu domínio de estudos especializado, as tecnologias dos transportes, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com as tecnologias dos transportes, como técnico de travões automóveis. Os professores de cursos profissionais de tecnologias dos transportes acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio das tecnologias dos transportes através de trabalhos, testes e exames.', 'released', '["Professor de Cursos Profissionais de Tecnologias dos Transportes", "Professora de Cursos Profissionais de Tecnologias dos Transportes"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/90f75f67-495d-49fa-ab57-2f320e251d7e', 'Chefe de Cozinha', 'Os chefes de cozinha são agentes culinários capazes de preparar e apresentar alimentos, normalmente em ambientes domésticos e institucionais.', 'released', '["Cozinheira", "Técnico de Cozinha", "Técnico de Restauração", "Técnica de Cozinha", "Cozinheiro", "Técnica de Restauração", "Chefea de Cozinha"]'::jsonb, '5120'),
  ('http://data.europa.eu/esco/occupation/91373a70-79b6-47a2-aa50-07dfe20dd258', 'Técnico de Manutenção de Aeronaves', 'Os técnicos de manutenção de aeronaves realizam operações de manutenção preventiva em aeronaves, componentes, motores e conjuntos de aeronaves, tais como estruturas de ar e sistemas hidráulicos e pneumáticos. Realizam inspeções cumprindo protocolos rigorosos e as leis da aviação.', 'released', '["Mecânico de Aeronaves", "Mecânica de Aeronaves", "Técnica de Manutenção de Aeronaves", "Técnico de Manutenção de Aeronaves"]'::jsonb, '7232'),
  ('http://data.europa.eu/esco/occupation/9161b2df-624c-4f5e-ad6c-0392439fa5c3', 'Operador de Extração de Amidos e Féculas', 'Os operadores de extração de amidos e féculas utilizam equipamento para extrair amidos e féculas de matérias-primas, tais como milho, batatas, arroz, tapioca, trigo, etc.', 'released', '["Técnico de Extração de Amidos e Féculas", "Operadora de Extração de Amidos e Féculas", "Operador de Extração de Amidos e Féculas", "Técnica de Extração de Amidos e Féculas"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/916d989e-0c5b-4c35-8d43-62ba65bebd30', 'Especialista em Import-Export de Máquinas e Equipamento Agrícola', 'Os especialistas em import-export de máquinas e equipamento agrícola possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Máquinas e Equipamento Agrícola"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/91ba2935-f5c9-426d-8573-997b8b91e5ed', 'Professor de Cursos Profissionais nas Áreas da Agricultura, Silvicultura e Pescas', 'Os professores de cursos profissionais nas áreas da agricultura, silvicultura e pescas formam os alunos no seu domínio de estudos especializado, a agricultura, silvicultura e pescas, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão de agricultura, silvicultura ou pescas. Os professores de cursos profissionais nas áreas da agricultura, silvicultura e pescas acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da agricultura, silvicultura e pescas através de trabalhos, testes e exames.', 'released', '["Professor de Cursos Profissionais nas Áreas da Agricultura, Silvicultura e Pescas", "Professora de Cursos Profissionais nas Áreas da Agricultura, Silvicultura e Pescas"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/91d0f74b-8612-49cc-a7da-83ee3c4b94d9', 'Técnico de Engenharia Industrial na Marroquinaria', 'Os técnicos de engenharia industrial na marroquinaria analisam as especificações técnicas dos produtos, definem as operações de produção e a sua sequência, aperfeiçoam os métodos de trabalho e calculam os tempos operacionais utilizando técnicas de medição do tempo. Atribuem os recursos humanos e tecnológicos a cada operação e definem a distribuição do trabalho em função da capacidade de produção. Todas as suas atividades e tarefas têm por objetivo maximizar a produtividade e reduzir os custos de produção, garantindo a funcionalidade, a qualidade do produto e a satisfação do cliente.', 'released', '["Técnica de Engenharia Industrial na Marroquinaria", "Técnico de Engenharia Industrial na Marroquinaria"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/91e35fd9-ac59-48ef-8416-c06a201b2da8', 'Engenheiro Projetista de Placas de Circuitos Impressos', 'Os engenheiros projetistas de placas de circuitos impressos elaboram o esquema e o desenho da construção de placas de circuitos. Perspetivam a colocação lógica dos trilhos condutores, dos elementos em cobre e dos pinos na placa. Utilizam programas informáticos e software especializado para os desenhos.', 'released', '["Engenheira Projetista de Placas de Circuitos Impressos", "Engenheiro Projetista de Placas de Circuitos Impressos"]'::jsonb, '3118'),
  ('http://data.europa.eu/esco/occupation/91f93dc4-1b71-4053-b6fb-c579ec19303a', 'Diretor de Departamento de Contratação Pública', 'Os diretores de departamentos de contratação pública asseguram que os objetivos políticos da organização são transformados em ações concretas e apoiam as suas equipes para garantir os melhores resultados aos seus clientes e ao público em geral. Supervisionam os profissionais envolvidos na contratação pública na organização para cumprir os seus objetivos.;', 'released', '["Chefe da Unidade de Compras", "Diretor de Procuração", "Diretora de Procuração", "Chefe do Departamento de Compras", "Diretora de Departamento de Contratação Pública"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/920c22e1-10a1-4afa-86b3-c43da8488391', 'Professor de Serviço Social', 'Os professores de serviço social são profissionais que exercem funções duplas: por um lado, praticam a disciplina académica que presta serviços sociais, tais como aconselhamento, terapia ou defesa de direitos, a indivíduos ou grupos de pessoas; por outro, fazem parte do mundo académico ao prestarem formação profissional, participando também na investigação e no desenvolvimento de conhecimentos, contribuindo para soluções relativas a problemas sociais complexos e abordagens inovadoras para solucionar esses problemas. Ensinam os conhecimentos, as competências e os valores do serviço social para a preparação dos alunos para uma prática culturalmente competente do serviço social com populações e comunidades diversas.', 'released', '["Professor de Serviço Social", "Professora Especialista em Serviços Sociais", "Professora de Serviço Social"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/92371348-ef8f-41ce-9666-c903b57cc8b4', 'Operador Ferroviário de Equipamento Intermodal', 'Os operadores ferroviários de equipamento intermodal auxiliam no carregamento de reboques e contentores de automotoras e chassis. Manobram conjuntos de trator-reboque em cantos apertados e para dentro e para fora de áreas de estacionamento. Utilizam equipamento periférico de computador de bordo para comunicar com o sistema informático de gestão do estaleiro e para identificar as automotoras.', 'released', '["Operador Ferroviário de Equipamento Intermodal", "Operadora Ferroviária de Equipamento Intermodal", "Operadora Ferroviário de Equipamento Intermodal"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/928dd410-c74b-4dab-94b8-fcbdcf541bd1', 'Cortador de Tecidos para Vestuário', 'Os cortadores de tecidos para vestuário marcam, cortam, formam e aparam materiais têxteis ou outros relacionados, de acordo com o esquema ou as especificações de fabrico do artigo de vestuário.', 'released', '["Cortadora de Tecidos para Vestuário", "Cortador de Tecidos para Vestuário"]'::jsonb, '7532'),
  ('http://data.europa.eu/esco/occupation/929b5c9d-2fbf-44f2-980d-2ac6c0dc212f', 'Protesista-Ortotista', 'Os protesistas-ortotistas concebem e adaptam próteses e ortóteses por medida para indivíduos com um membro em falta em resultado de um acidente, de uma doença ou de malformações congénitas, ou para indivíduos que têm incapacidades, deficiências ou fraquezas causadas por lesões, patologias ou malformações congénitas. Combinam os cuidados aos doentes com a concepção e o fabrico destes dispositivos para dar resposta às necessidades dos doentes.', 'released', NULL, '3214'),
  ('http://data.europa.eu/esco/occupation/929ef41d-afd0-4d5a-b85b-69eab68fa368', 'Assistente Jurídico', 'Os assistentes jurídicos trabalham em estreita colaboração com advogados e representantes legais na investigação e preparação de processos levados a tribunais. Auxiliam com os documentos de trabalho dos processos e com a gestão do aspeto administrativo dos assuntos judiciais.', 'released', '["Assistente Jurídica", "Assistente Jurídico", "Assistentea Jurídico"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/92b7776f-5d90-413d-b05f-51e429e28346', 'Funcionário de Parque de Campismo', 'Os funcionários de parque de campismo prestam assistência aos clientes no parque de campismo e realizam outros trabalhos operacionais.', 'released', '["Funcionário de Parque de Campismo", "Operadora de Campismo", "Operador de Campismo", "Funcionária de Parque de Campismo"]'::jsonb, '4224'),
  ('http://data.europa.eu/esco/occupation/92b7a42c-b437-4412-ac21-1a750883cf21', 'Técnico Geotérmico', 'Os técnicos geotérmicos instalam e procedem à manutenção de centrais geotérmicas e instalações de aquecimento geotérmico em espaços comerciais e residenciais. Realizam inspeções, analisam problemas e efetuam reparações. Participam na instalação inicial, nos ensaios e na manutenção de equipamento geotérmico e asseguram o cumprimento da regulamentação em matéria de segurança.;', 'released', '["Instaladora Geotérmico", "Técnico de Energia Geotérmica", "Técnica de Energia Geotérmica", "Instaladora de Energia Geotérmica", "Instalador Geotérmico", "Instalador de Energia Geotérmica", "Técnica Geotérmico"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/92bb3d8c-8a9f-4cd7-80ec-247bbf173004', 'Engenheiro de Hardware', 'Os engenheiros de hardware concebem e desenvolvem sistemas e componentes informáticos, tais como placas de circuito, modems e impressoras. Elaboram planos e linhas de montagem, desenvolvem e testam os protótipos e supervisionam o processo de produção.', 'released', '["Engenheira Informática", "Engenheiro de Hardware", "Engenheira de Hardware", "Engenheiro Informático", "Engenheiro de Desenvolvimento de Hardware"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/92be1fac-97c4-4d4d-ada7-f6aa07d6f316', 'Coordenador de Listas de Espera', 'Os coordenadores de listas de espera garantem a gestão diária dos tempos de listas de espera. Planeiam a disponibilidade de salas de operações e convocam os doentes para a realização das cirurgias. Os coordenadores de listas de espera garantem a otimização da utilização dos recursos.', 'released', '["Coordenadora de Listas de Espera", "Coordenador de Listas de Espera"]'::jsonb, '3252'),
  ('http://data.europa.eu/esco/occupation/92cba6b4-8fca-49bb-b68c-45c5096fedc9', 'Lavador de Janelas', 'Os lavadores de janelas utilizam ferramentas de limpeza, tais como esponjas e detergentes, para lavar janelas, espelhos e outras superfícies de vidro de edifícios, tanto no interior como no exterior. Utilizam escadas específicas para limpar edifícios altos, utilizando cintos de segurança para apoio.', 'released', '["Lavadora de Vidros", "Lavador de Janelas", "Lavador de Vidros", "Lavadora de Janelas"]'::jsonb, '9123'),
  ('http://data.europa.eu/esco/occupation/92dc335d-a116-416f-ad2b-257e5382e574', 'Colchoeiro', 'Os colchoeiros fabricam colchões criando almofadas e revestimentos. Enchem colchões à mão e cortam, espalham e fixam o enchimento e o material de revestimento sobre as montagens interiores de molas.', 'released', '["Fabricante de Colchões", "Colchoeira", "Colchoeiro"]'::jsonb, '7534'),
  ('http://data.europa.eu/esco/occupation/92df4ee3-bce3-45f6-a693-597df1b96f43', 'Operador de Linha de Apoio Telefônico', 'Os operadores de linha de apoio telefônico prestam aconselhamento e apoio aos utentes com problemas. Têm de lidar com um leque diversificado de questões como abusos, depressão e problemas financeiros. Os operadores de linha de apoio telefônico mantêm registos das chamadas telefônicas de acordo com a regulamentação e as políticas de privacidade.', 'released', '["Operador de Linha de Apoio Telefônico", "Operador de Linha de Ajuda Telefônica", "Operadora de Linha de Ajuda Telefônica", "Operadora de Linha de Apoio Telefônico", "Operador Ade Linha de Ajuda", "Operadora de Linha de Apoio", "Operador de Linha de Apoio", "Operador de Linha de Ajuda"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/92efb42f-6b0a-44d8-94ea-0141555e6c3b', 'Geólogo Ambiental', 'Os geólogos ambientais estudam a forma como as operações minerais podem afetar a composição e as características físicas da Terra e dos seus recursos. Prestam aconselhamento sobre questões como a recuperação de terras e a poluição ambiental.', 'released', '["Ambientalista", "Analista de Recursos Minerais", "Geóloga Ambiental", "Geólogo Ambiental"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/933a0762-1201-4855-909c-94403f6867a9', 'Comerciante Grossista de Porcelana e Outros Vidros', 'Os comerciantes grossistas de porcelana e outros vidros investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Porcelana e Outros Vidros"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/933d02c0-3dfa-418f-9c2d-470b525cc42c', 'Inspetor de Bagagem', 'Os inspetores da bagagem verificam a bagagem das pessoas para detectar potenciais objetos ameaçadores. Cumprem os regulamentos relativos à segurança pública e o procedimento da empresa.', 'released', '["Inspetor de Bagagem", "Inspetora de Bagagem"]'::jsonb, '3351'),
  ('http://data.europa.eu/esco/occupation/934c3572-37f4-4cdd-a4a4-017f5f7809e4', 'Assistente de Gestão de Fundos de Investimento', 'Os assistentes de gestão de fundos de investimento fornecem aos clientes consultoria de planejamento financeiro sobre produtos financeiros e servem de ponto de contato principal para clientes novos e antigos. Prestam assistência e realizam trabalho preparatório na criação e administração de fundos e contribuem para a execução das decisões de gestão de fundos por parte do gestor da carteira ou dos fundos.', 'released', '["Assistentea de Gestão de Fundos de Investimento"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/9358775a-3769-4327-bf25-6c0d9d69d192', 'Gerente de Agência de Viagens', 'Os gerentes de agência de viagens estão encarregados de gerir os trabalhadores e as atividades de uma agência de viagens. Organizam, publicitam e vendem ofertas turísticas e pacotes de viagem para regiões específicas.', 'released', '["Gerente de Vendas de Viagens", "Gerente de Agência de Turismo", "Gerente de Agência de Viagens", "Gerentea de Agência de Viagens"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/9388a977-6f79-4509-81aa-026bc49e1919', 'Operador de Linha de Enlatamento e Engarrafamento', 'Os operadores de linha de enlatamento e engarrafamento observam as garrafas e as latas de conserva durante o processo de produção. Ficam de pé junto dos tapetes transportadores, a fim de garantir que as garrafas são enchidas de acordo com os níveis normalizados e que não se verificam grandes desvios. Eliminam as garrafas ou latas com defeito.;', 'released', '["Operador de Linha de Enchimento de Latas e Garrafas", "Operadora de Linha de Enchimento de Latas e Garrafas", "Operadora de Linha de Enlatamento e Engarrafamento", "Operador de Linha de Enlatamento e Engarrafamento"]'::jsonb, '8183'),
  ('http://data.europa.eu/esco/occupation/939e05ea-2589-4e3c-a501-eea2bdd6864a', 'Operador de Máquina de Tecer', 'Os operadores de máquinas de tecer instalam, operam e controlam as máquinas de tecer. Trabalham com máquinas, técnicas e materiais especializados para processar fios em produtos tecidos, tais como vestuário, têxteis para o lar ou produtos finais técnicos. Procedem à manutenção e reparação de máquinas de tecer e asseguram que as operações decorram sem problemas.', 'released', '["Operadora de Máquina de Tecer", "Operador de Máquina de Tecer"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/93a8bd5f-c268-46f5-8461-1138a9a96189', 'Operador de Forjagem por Estampagem', 'Os operadores de forjagem por estampagem utilizam de máquinas e equipamentos de forjagem, especificamente martelos, para moldar peças de metal ferroso e não ferroso na forma desejada. Cuidam dos martelos de forjagem que batem na peça a fim de remodelá-la de acordo com a forma do molde, que pode ser fechado ou aberto, contendo a peça inteira ou não.', 'released', '["Operador de Forjagem por Estampagem", "Operadora de Forjagem por Estampagem"]'::jsonb, '7221'),
  ('http://data.europa.eu/esco/occupation/93aa611c-a58c-43ff-bc34-6e201dfdd0dd', 'Modelista de Calçado', 'Os modelistas de calçado concebem e cortam moldes para todo o tipo de calçado, utilizando uma variedade de ferramentas manuais e máquinas-ferramentas simples. Verificam várias variantes de encaixe e estimam o consumo de materiais. Uma vez aprovado o molde de amostra para a produção, produzem uma série de moldes da gama de calçado em diferentes tamanhos.', 'released', NULL, '7536'),
  ('http://data.europa.eu/esco/occupation/93b11f0f-69af-4ece-b9da-f29aab7d38d3', 'Engenheiro Projetista de Equipamento Contêiner', 'Os engenheiros projetistas de equipamento contentor concebem equipamentos contentores de produtos ou líquidos de acordo com especificações estabelecidas, tais como caldeiras ou recipientes sob pressão. Testam os desenhos, procuram soluções para eventuais problemas e supervisionam a produção.', 'released', '["Engenheiro Projetista de Equipamento Contentor", "Engenheira Projetista de Equipamento Contentor", "Engenheira Projetista de Equipamento Contêiner"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/93dfef83-579c-4bef-b0ba-d41ee9cbda85', 'Gestor de Instalações para Animais', 'Os gestores de instalações para animais coordenam e planificam todas as atividades de um jardim zoológico. Elaboram políticas, gerem as operações diárias e planificam a utilização de materiais e recursos humanos. São a força motriz e o rosto público da instituição. Tal implica frequentemente representar a instituição a nível nacional, regional e mundial e participar em atividades coordenadas de jardim zoológico.', 'released', '["Diretora de Jardim Zoológico", "Diretora de Abrigo para Animais", "Gestor de Instalações para Animais", "Diretor de Jardim Zoológico", "Diretora de Oceanário", "Gestora de Instalações para Animais", "Diretor de Abrigo para Animais", "Diretor de Aquário", "Diretor de Oceanário", "Diretora de Aquário", "Gerente"]'::jsonb, '1120'),
  ('http://data.europa.eu/esco/occupation/93e4e70b-aae4-4fdc-8037-e48e7077564e', 'Urbanista de Tráfego', 'Os urbanistas de tráfego desenvolvem e implementam políticas destinadas a melhorar os sistemas de transporte, tendo em conta fatores sociais, ambientais e econômicos. Recolhem e analisam os dados de tráfego utilizando ferramentas de modelização estatística.;', 'released', NULL, '2164'),
  ('http://data.europa.eu/esco/occupation/93f61216-b9c8-4051-bb1e-32839c1566c1', 'Formador de Cursos Profissionais de Cabeleireiro e Barbeiro', 'Os formadores de cursos profissionais de cabeleireiro e barbeiro formam os alunos no seu domínio de estudos especializado, a profissão de cabeleireiro e barbeiro, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar. Os formadores de cursos profissionais de cabeleireiro e barbeiro acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da atividade de cabeleireiro e barbeiro através de trabalhos, testes e exames.', 'released', '["Formador de Cursos Profissionais de Cabeleireiro e Barbeiro", "Formadora de Cursos Profissionais de Cabeleireiro e Barbeiro"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/942211c1-b534-4a14-ae85-38ea44c2d14b', 'Gestor de Reclamações — Seguros', 'Os gestores de reclamações de seguros dirigem a equipe de agentes de seguros para assegurar que as reclamações de seguros são tratadas de forma adequada e eficiente. Tratam de reclamações de clientes mais complexas e prestam assistência em casos de fraude. Os gestores de reclamações de seguros trabalham com corretores, agentes, peritos e clientes.', 'released', '["Diretora do Departamento de Gestão de Reclamações — Seguros", "Diretor do Departamento de Gestão de Reclamações — Seguros", "Gestora de Reclamações — Seguros", "Gestor de Reclamações — Seguros", "Gerente"]'::jsonb, '1346'),
  ('http://data.europa.eu/esco/occupation/9422c30d-c5ef-4fcc-a493-d67ee42189c0', 'Eletricista Naval', 'Os eletricistas navais procedem à instalação, manutenção e reparação de sistemas elétricos e eletrônicos em navios, tais como sistemas de ar condicionado, lâmpadas, rádios, sistemas de aquecimento, baterias, cablagem elétrica e alternadores. Utilizam equipamento de teste de diagnóstico para inspecionar os navios e encontrar falhas. Para realizar o trabalho de reparação, utilizam ferramentas manuais e instrumentos e máquinas elétricos especializados.', 'released', NULL, '7412'),
  ('http://data.europa.eu/esco/occupation/9487f835-b5a9-4742-8ecf-35520911e28c', 'Massoterapeuta', 'Os massoterapeutas administram tratamentos de massagem terapêutica para melhorar o bem-estar dos seus clientes. Em função das necessidades e das preferências dos clientes, realizam vários tipos de massagem, como shiatsu e massagem sueca.', 'released', NULL, '3255'),
  ('http://data.europa.eu/esco/occupation/949ab84f-5d76-4139-a568-45691b7ebc53', 'Diretor para a Igualdade e a Inclusão', 'Os diretores para a igualdade e a inclusão desenvolvem políticas para melhorar a ação positiva, a diversidade e a igualdade. Informam o pessoal das empresas sobre a importância das políticas e a sua aplicação e aconselham os quadros superiores em matéria de clima empresarial. Desempenham também funções de orientação e apoio aos trabalhadores.', 'released', '["Diretora de Direitos Humanos", "Diretora de Diversidade e Inclusão", "Diretor de Direitos Humanos", "Diretor para a Igualdade e a Inclusão", "Diretora para a Igualdade e a Inclusão", "Diretor de Diversidade e Inclusão"]'::jsonb, '1212'),
  ('http://data.europa.eu/esco/occupation/949bccd9-e1d2-4c57-b787-53b451aa1354', 'Fabricante de Mobília de Vime', 'Os fabricantes de mobília de vime selecionam e preparam materiais, tais como ramos de rotim ou salgueiro, a fim de produzir mobília de vime, como cadeiras, mesas e sofás. Utilizam ferramentas manuais, elétricas ou máquina para cortar, dobrar e tecer materiais para criar os objetos desejados. Por último, tratam a superfície para garantir um aspeto acabado e protegê-la da corrosão e do fogo, utilizando ceras, vernizes e outros revestimentos.', 'released', '["Fabricantea de Mobília de Vime"]'::jsonb, '7317'),
  ('http://data.europa.eu/esco/occupation/949ed945-f697-415e-b4c5-51d8abf7cfdf', 'Nanoengenheiro', 'Os nanoengenheiros combinam os conhecimentos científicos de partículas atómicas e moleculares com os princípios da engenharia para aplicações num leque variado de domínios. Aplicam as descobertas em química, biologia e engenharia dos materiais, etc.. Utilizam conhecimentos tecnológicos para a melhoria de aplicações existentes ou para a criação de micro objetos.', 'released', '["Nano Engenheiro", "Nanoengenheiro", "Nano Engenheira", "Nanoengenheira"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/949f1dc9-fb19-4212-8ac6-35ce83c88921', 'Ponto', 'Os pontos dão indicações ou deixas aos artistas quando se esquecem das falas ou não se deslocam para a posição correta no palco.', 'released', '["Ponta"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/94adbb11-1c90-4092-ae91-781e8a55865d', 'Agente Marítimo', 'Os agentes marítimos atuam como intermediários entre compradores e vendedores de navios, de espaço de carga em navios e de navios de fretamento para a transferência de carga. Informam os clientes sobre os mecanismos e os movimentos do mercado de transporte marítimo, fornecem informações sobre preços e vendas de navios e de espaço de carga e negoceiam não só o custo dos navios, do espaço de carga ou da carga, mas também os requisitos logísticos para a transferência do navio ou das mercadorias para os compradores.', 'released', '["Agente Marítima", "Agente Marítimo", "Agentea Marítimo"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/94d94bd0-9ac3-4bd8-81c0-c3fdf551aa16', 'Escultor', 'Os escultores podem utilizar uma grande variedade de materiais para a criação de esculturas, como pedra, argila, vidro, madeira, gesso ou qualquer material à sua escolha. Esses materiais podem ser esculpidos, modelados, moldados, fundidos, trabalhados, soldados, etc., a fim de alcançarem a forma desejada.', 'released', '["Escultora", "Escultor"]'::jsonb, '2651'),
  ('http://data.europa.eu/esco/occupation/94e0bedd-e56e-42be-a5a4-b74a260f437c', 'Chefe de Departamento', 'Os chefes de departamento são responsáveis pelas operações de uma determinada divisão ou serviço de uma empresa. Garantem a realização de objetivos e metas e gerem os trabalhadores.', 'released', '["Coordenadora de Departamento", "Chefe de Unidade", "Chefe de Divisão", "Diretora de Departamento", "Diretor de Departamento", "Coordenador de Departamento", "Chefea de Departamento"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/951b9d94-9bf1-4771-877d-3a26b75d9e53', 'Designer de Animação', 'Os designers de animação trabalham com o diretor e cameraman para coordenar e criar imagens de animação 3D otimizadas. Transformam imagens 2D em cenas de animação 3D e são responsáveis pelos ângulos de câmara, pela sequenciação e pela iluminação das cenas de animação. Os designers de animação decidem quais as ações que têm lugar em cada cena de animação.', 'released', NULL, '2166'),
  ('http://data.europa.eu/esco/occupation/952aa13c-731f-4add-98d1-66b59f70e607', 'Condutor de Transporte de Animais Vivos', 'Os condutores de transporte de animais vivos fornecem transporte e transferência para animais vivos, incluindo a vigilância da saúde e do bem-estar dos animais, o planejamento e a preparação para viagens, carga e descarga de animais, de acordo com a legislação nacional e internacional.', 'released', '["Condutora de Transporte de Animais Vivos", "Condutor de Transporte de Animais Vivos", "Funcionário de Transportadora de Animais Vivos", "Operador de Transportadora de Animais Vivos", "Operadora de Transportadora de Animais Vivos", "Funcionária de Transportadora de Animais Vivos"]'::jsonb, '8332'),
  ('http://data.europa.eu/esco/occupation/952c766a-db5c-42b2-809d-d14cbb02cdb6', 'Técnico de Transformação de Produtos Lácteos', 'Os técnicos de transformação de produtos lácteos supervisionam e coordenam os processos de produção, as operações e os trabalhadores da área de manutenção em unidades de produção de leite, queijo, gelados e/ou outras unidades de produção de produtos lácteos. Prestam assistência aos especialistas em tecnologia alimentar na melhoria dos processos, no desenvolvimento de novos produtos alimentares e no estabelecimento de procedimentos e normas de produção e embalagem.', 'released', '["Supervisor de Produção de Produtos Lácteos", "Técnica de Transformação de Produtos Lácteos", "Técnico de Transformação de Produtos Lácteos"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/95324a4a-a5ea-4d89-8ede-4422ccb46a28', 'Técnico de Bioquímica', 'Os técnicos de bioquímica prestam assistência técnica na investigação, na análise e no ensaio das reações causadas por produtos químicos em organismos vivos. Utilizam equipamento laboratorial para ajudar a desenvolver ou melhorar produtos de base química e também recolhem e analisam dados para experiências, elaboram relatórios e mantêm as existências de material de laboratório.', 'released', '["Técnico de Bioquímica", "Técnica de Bioquímica"]'::jsonb, '3141'),
  ('http://data.europa.eu/esco/occupation/955ae83a-4d91-4db8-a5d6-bd489e5058df', 'Mecânico de Equipamento Mineiro', 'Os mecânicos de equipamento mineiro procedem à instalação, remoção, manutenção e reparação de equipamento mineiro.', 'released', '["Mecânica de Equipamento Mineiro", "Mecânico de Equipamento Mineiro"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/9581c837-fee7-4068-9618-1116fd93d723', 'Assistente de Projetos', 'Os assistentes de projetos asseguram a administração e o acompanhamento dos dossiês técnicos e de engenharia relativos a projetos, missões e questões de qualidade. Prestam assistência aos engenheiros com as suas experiências, participam em visitas ao local e administram a recolha de informações.', 'released', '["Assistentea de Projetos"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/95a6ecd2-a140-4861-aad7-dcb8cfc1c9a3', 'Operador de Máquinas Cortadoras Longitudinais', 'Os operadores de máquinas cortadoras longitudinais instalam, operam ou asseguram o correto funcionamento de máquinas para cortar, rasgar, dobrar, ou endireitar folhas de metal, papel ou outros materiais de acordo com larguras determinadas. Os operadores de máquinas cortadoras longitudinais também devem assegurar a qualidade, examinando vários produtos finais e observando as tolerâncias predefinidas.', 'released', '["Operadora de Máquina Cortadora Longitudinal", "Operador de Cortadores Longitudinais", "Operador de Máquina Cortadora Longitudinal", "Operadora de Cortadores Longitudinais", "Operadora de Máquinas Cortadoras Longitudinais"]'::jsonb, '8189'),
  ('http://data.europa.eu/esco/occupation/95a89206-4dc8-4753-a5d9-bc14a0e5f7ca', 'Estofador', 'Os estofadores dotam objetos, tais como móveis, painéis, dispositivos ortopédicos, acessórios fixos ou peças para veículos, de um estofo ou revestimento macio. Podem instalar, reparar ou substituir os estofos de objetos com materiais, tais como tecidos, couro, camurça ou algodão. Os estofadores instalam as cintas e as molas necessárias para cobrir o material.', 'released', '["Estofadora", "Estofador"]'::jsonb, '7534'),
  ('http://data.europa.eu/esco/occupation/95cd3d64-20d0-4681-857d-d6c63d07349f', 'Mestre Cervejeiro', 'Os mestres cervejeiros asseguram a qualidade dos produtos atuais e criam misturas para o desenvolvimento de novos produtos. Para os produtos atuais, controlam todo o processo de fabrico seguindo um dos muitos processos de fabrico de cerveja. No caso de novos produtos, desenvolvem novas fórmulas de fabrico e técnicas de transformação ou modificam as existentes de modo a criar potenciais novos produtos.', 'released', '["Produtor de Cerveja", "Mestre Cervejeiro", "Produtora de Cerveja", "Mestre Cervejeira", "Mestrea Cervejeiro"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/95cda6a9-a70a-4a93-9442-11d573cb4a02', 'Parteiro', 'Os parteiros assistem as mulheres no parto, prestando o apoio, os cuidados e o aconselhamento necessários durante a gravidez, o trabalho de parto e o período pós-parto, realizam o parto e prestam cuidados aos recém-nascidos. Prestam aconselhamento em matéria de saúde, medidas preventivas, preparação para a parentalidade, detecção de complicações na mãe e da criança, acesso a cuidados médicos, promoção do nascimento normal e execução de medidas de emergência.', 'released', '["Parteira", "Parteiro"]'::jsonb, '2222'),
  ('http://data.europa.eu/esco/occupation/95d0a616-a4a9-4f56-a8fb-4de43cdb4c82', 'Assistente Social de Apoio Familiar', 'Os assistentes sociais de apoio familiar prestam aconselhamento às famílias sobre a gama de serviços sociais disponíveis para resolver problemas ou situações difíceis que se lhes deparam, tais como dependências, doenças mentais, dificuldades médicas ou financeiras. Ajudam os utentes a aceder a estes serviços sociais e certificam-se de que estes serviços são usados devidamente.;', 'released', '["Assistentea Social de Apoio Familiar"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/95d69048-3a4b-4cce-a155-584aaecfe403', 'Supervisor de Montagem de Calçado', 'Os supervisores de montagem de calçado verificam e coordenam as atividades dos operadores da secção de enformação. São responsáveis pela coordenação da atividade da secção de enformação com as atividades anteriores e seguintes da cadeia de produção. Analisam as gáspeas e as solas destinadas a enformação e dão instruções para a sua produção. Estes supervisores estão encarregados de fornecer gáspeas, formas, almas, contrafortes e pequenas ferramentas de manuseamento à secção de enformação, e são também responsáveis pelo controlo de qualidade do processo de enformação.', 'released', '["Supervisor de Montagem de Calçado", "Supervisora de Montagem de Calçado"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/95d8f19e-f62b-443f-ac53-324ea8f98cf5', 'Diretor de Importação e Exportação de Porcelanas e Vidros', 'Os diretores de importação e exportação de porcelanas e vidros implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Porcelanas e Vidros", "Diretor de Importação e Exportação de Porcelanas e Vidros", "Diretora de Importação e Exportação de Porcelanas e Vidros", "Diretor de Vendas de Porcelanas e Vidros"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/95da5e1b-cc1e-46bd-96c4-81d4f7003080', 'Montador de Edifícios Modulares de Madeira', 'Os montadores de edifícios modulares de madeira instalam elementos de madeira para utilização na construção. Os elementos, ou módulos, podem consistir em paredes com janelas e portas encastráveis, ou podem ser tão grandes como divisões inteiras. Os montadores instalam a estrutura de apoio, os materiais de isolamento e a cobertura e fixam-nos para obter conjuntos utilizáveis.', 'released', '["Montador de Edifícios Modulares de Madeira", "Montadora de Edifícios Modulares de Madeira"]'::jsonb, '7119'),
  ('http://data.europa.eu/esco/occupation/95f56fc4-99f9-49da-b942-1dfbc857e933', 'Chefe de Cabine', 'Os chefes de cabine são responsáveis por motivar os tripulantes de cabina a ultrapassarem as expectativas dos passageiros e pela aplicação das regras de segurança a bordo do avião.', 'released', '["Supervisora de Cabine", "Supervisor de Cabine", "Chefea de Cabine"]'::jsonb, '5111'),
  ('http://data.europa.eu/esco/occupation/96186698-f79d-423a-9652-a2a58085d5f1', 'Pintor de Madeira', 'Os pintores de madeira concebem e criam arte visual em superfícies e objetos de madeira, tais como mobília, figuras e brinquedos. Recorrem a várias técnicas para produzir ilustrações decorativas, desde desenho com estêncil até à mão livre.', 'released', '["Pintor de Madeira", "Pintora de Madeira", "Pintora-Decoradora de Madeira", "Pintor-Decorador de Madeira"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/961cbd1f-2a9b-4756-b227-67a1c23c94b6', 'Operador de Caixa em Casino', 'Os operadores de caixa em casino trocam moedas ou fichas por dinheiro. Organizam pagamentos e obtêm as assinaturas e a identificação dos clientes. Efetuam auditorias e contam dinheiro numa caixa registadora, aplicando a regulamentação relativa ao branqueamento de capitais.', 'released', '["Operador de Caixa em Casino", "Operadora de Caixa em Casino"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/96430121-2757-4e96-9d6f-7517b25db4f7', 'Vigilante', 'Os vigilantes circulam na casa dos empregadores a fim de manter a segurança dos bens durante a sua ausência. Vigiam as zonas de entrada e impedem pessoas não autorizadas de entrar na casa, inspecionam o estado das instalações, tais como as canalizações e o aquecimento, e contactam reparadores, se necessário. Os vigilantes podem também realizar algumas atividades de limpeza, enviar correio e pagar faturas.', 'released', '["Caseiro", "Caseira", "Vigilantea"]'::jsonb, '5153'),
  ('http://data.europa.eu/esco/occupation/96514fed-b9a9-4df3-ab0b-20676369297d', 'Operador de Prensas Hidráulicas de Plásticos', 'Os operadores de prensas hidráulicas de plásticos instalam e asseguram o correto funcionamento das prensas hidráulicas que compactam e fabricam aparas de plástico em moldes para produzir folhas de plástico. Regulam e ajustam a pressão e a temperatura.', 'released', '["Operadora de Prensas Hidráulicas", "Operador de Prensas Hidráulicas", "Operadora de Prensas Hidráulicas de Plásticos"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/9653fb92-ad48-4865-a471-f270302fa93b', 'Agente de Apoio aos Passageiros', 'Os agentes de apoio aos passageiros passam algum tempo com os clientes das estações ferroviárias, respondem às suas perguntas e reagem rapidamente e em segurança a situações inesperadas. Fornecem informações, assistência à mobilidade e segurança nas estações ferroviárias. Fornecem informações exatas e atualizadas sobre os horários de chegada e de partida dos comboios, as ligações ferroviárias e ajudam os clientes a planear as suas viagens.', 'released', '["Agentea de Apoio aos Passageiros"]'::jsonb, '5112'),
  ('http://data.europa.eu/esco/occupation/969f8af0-3c0d-403a-9c16-a6fb76c6b443', 'Artista Conceitual', 'Os artistas conceptuais têm a capacidade de escolher qualquer material enquanto ferramenta e/ou material artístico para exprimir um conceito criativo, destinado a ser apresentado ao público como uma experiência artística. O seu trabalho, pertencente ao domínio das belas-artes, pode ser bidimensional (desenho, pintura, colagem), tridimensional (escultura, instalação) ou quadridimensional (imagens em movimento, espetáculos).', 'released', NULL, '2651'),
  ('http://data.europa.eu/esco/occupation/96a0d8d3-d4a6-473d-80d6-b5dbadde940a', 'Membro de Equipe de Restaurante de Refeições Rápidas', 'Os membros de equipe de restaurante de refeições rápidas preparam, cozinham e servem alimentos e bebidas num serviço rápido.', 'released', '["Membro de Equipe de Restaurante de Fast Food", "Membra de Equipe de Restaurante de Refeições Rápidas"]'::jsonb, '9411'),
  ('http://data.europa.eu/esco/occupation/96be6ac3-5932-4bfc-933d-84b267d0d486', 'Curador de Coleção', 'Os curadores de coleção asseguram a manutenção e a preservação de objetos em instituições culturais, como museus, bibliotecas e arquivos. Os curadores de coleção, juntamente com os curadores de arte e os conservadores, desempenham um papel muito importante na conservação das coleções. É possível encontrá-los na maioria dos grandes museus.', 'released', '["Curador", "Curadora de Coleção", "Curadora", "Curador de Coleção"]'::jsonb, '2621'),
  ('http://data.europa.eu/esco/occupation/96c870c0-f93a-43c3-9ce4-1fe9e737fece', 'Diretor de Distribuição — Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica', 'Os diretores de distribuição — maquinaria e equipamento industrial, construção naval e aeronáutica planificam a distribuição de máquinas, equipamentos industriais, navios e aeronaves a vários pontos de venda.', 'released', '["Diretor de Distribuição — Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica", "Diretora de Distribuição — Maquinaria e Equipamento Industrial, Construção Naval e Aeronáutica"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/96e139de-0756-45ad-b512-f7c2109a72b1', 'Supervisor de Montagem de Aeronaves', 'Os supervisores de montagem de aeronaves coordenam os trabalhadores envolvidos no fabrico de aeronaves e programam as suas atividades. Elaboram relatórios de produção e recomendam medidas para reduzir os custos e aumentar a produtividade, como a contratação, a encomenda de novos equipamentos e a implementação de novos métodos de produção. Formam os trabalhadores nas políticas da empresa, no exercício das funções e nas medidas de segurança. Supervisionam as existências e comunicam com outros departamentos, tendo em vista evitar interrupções desnecessárias do processo de produção.', 'released', '["Supervisor de Montagem de Aeronaves", "Supervisora de Montagem de Aeronaves"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/96e20037-0a25-4bf6-a25e-808d1605d890', 'Designer de Interfaces do Usuário', 'Os designers de interfaces do usuário são responsáveis pela concepção de interfaces de usuário para aplicações e sistemas. Realizam atividades de concepção de configurações, gráficos e diálogos, bem como atividades de adaptação.', 'released', '["Engenheira de Usabilidade", "Designer de Interfaces do Usuário", "Engenheiro de Usabilidade", "Designer de IU", "Designer de Acessibilidade", "Designer de UI"]'::jsonb, '2513'),
  ('http://data.europa.eu/esco/occupation/96e88e86-f2c7-42e6-a2b2-17e4f08d4ee0', 'Coordenador de Programas de Voluntariado Empresarial', 'Os coordenadores de programas de voluntariado empresarial operam em todos os setores e domínios para coordenar e gerir programas de voluntariado de trabalhadores (voluntariado empresarial ou corporativo) para os respetivos empregadores. Compete-lhes estabelecer a ligação com as organizações da comunidade local para determinar as necessidades e mobilizar voluntários entre o pessoal da empresa para dialogar com entidades locais, como as autoridades ou as organizações da sociedade civil locais, a fim de satisfazer essas necessidades. Os coordenadores dos programas de voluntariado empresarial podem também providenciar para que os voluntários desempenhem as suas funções em linha, em colaboração com iniciativas da sociedade civil que respondam às necessidades identificadas. Estes papéis podem ser desempenhados na empresa ou no contexto em que os trabalhadores estão sediados, bem como na organização da sociedade civil que recebe os voluntários.;', 'released', '["Gerente de Voluntariado Corporativo", "Coordenador de Voluntariado Corporativo", "Coordenadora de Voluntariado Corporativo", "Coordenadora de Programas de Voluntariado Empresarial"]'::jsonb, '1212'),
  ('http://data.europa.eu/esco/occupation/9703fe09-51fd-4d00-a2a1-99ba809521ac', 'Gerente de Loja de Esporte e Aventura', 'Os gerentes de loja de desporto e aventura assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas. Gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Loja de Campismo", "Gerente de Loja de Aventura e Outdoor", "Gerente de Loja de Esporte e Atividades de Lazer", "Gerentea de Loja de Esporte e Aventura"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/9711dcfc-d9a8-4fba-9c5e-8428d8bcb53e', 'Professor de Escola de Línguas', 'Os professores de escola de línguas ensinam a alunos de todas as idades uma língua que não a sua língua materna numa escola especializada, não vinculada a qualquer nível de ensino. Centram-se menos no aspeto académico do ensino das línguas, ao contrário dos professores de línguas do ensino secundário ou superior, e mais na teoria e na prática que serão mais úteis aos alunos em situações reais, uma vez que a maioria dos alunos escolhe este tipo de ensino para fins laborais, de migração ou lazer. Organizam as suas turmas utilizando uma grande variedade de materiais, trabalham de forma interativa com o grupo e avaliam os progressos individuais através da atribuição de trabalhos e exames, colocando a tônica nas competências linguísticas ativas como a escrita e a expressão oral.', 'released', '["Professor de Escola de Línguas", "Professor de Instituto de Línguas", "Professora de Instituto de Línguas", "Professora de Escola de Línguas"]'::jsonb, '2353'),
  ('http://data.europa.eu/esco/occupation/9729c0f3-c9bc-482e-ac59-a82ec3b67ba3', 'Operador de Centro de Dados', 'Os operadores de centro de dados controlam as operações informáticas no centro de dados. Gerem as atividades diárias no centro para resolver problemas, manter a disponibilidade do sistema e avaliar o desempenho do sistema.', 'released', '["Funcionária de Centro de Dados", "Operadora de Centro de Dados", "Operador de Centro de Dados", "Funcionário de Centro de Dados"]'::jsonb, '3511'),
  ('http://data.europa.eu/esco/occupation/972ef593-89c3-468b-aad5-81bc575feb58', 'Diretor de Importação e Exportação de Maquinaria para a Indústria Têxtil', 'Os diretores de importação e exportação de maquinaria para a indústria têxtil implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação de Maquinaria para a Indústria Têxtil", "Diretora de Importação e Exportação de Maquinaria para a Indústria Têxtil", "Diretora de Vendas de Maquinaria para a Indústria Têxtil", "Diretor de Vendas de Maquinaria para a Indústria Têxtil"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/9740933e-e04a-41f6-af1f-a6d58c7eb0ec', 'Engenheiro Especialista em Sistemas de Tratamento de Águas Residuais', 'Os engenheiros especialistas em sistemas de tratamento de águas residuais concebem sistemas de esgotos e redes para a remoção e o tratamento das águas residuais das cidades e de outras zonas residenciais. Concebem sistemas conformes com as normas ambientais e visam minimizar o impacto no ecossistema e nos cidadãos nas proximidades da rede.', 'released', '["Engenheira Especialista em Sistemas de Tratamento de Águas Residuais", "Engenheiro Especialista em Sistemas de Tratamento de Águas Residuais"]'::jsonb, '2143'),
  ('http://data.europa.eu/esco/occupation/974494ee-5f32-4eec-9950-9d431e902dc1', 'Vendedor de Carne e Produtos à Base de Carne', 'Os vendedores de carne e produtos à base de carne cortam e vendem carne em estabelecimentos especializados.', 'released', '["Vendedor de Carne e Produtos à Base de Carne", "Vendedora de Carne e Produtos à Base de Carne"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/97467934-a220-41ca-96df-36fc85258c47', 'Gerente de Livraria', 'Os gerentes de livraria assumem a responsabilidade pelas atividades e pessoal neste armazém especializado.', 'released', '["Livreira", "Gerente de Papelaria e Tabacaria", "Alfarrabista", "Gerente de Alfarrabista", "Livreiro", "Gerentea de Livraria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/974d4eab-fbee-4c52-b16e-73bdd8c25b53', 'Advogado', 'Os advogados prestam aconselhamento jurídico aos clientes e atuam em seu nome em processos judiciais e em conformidade com a lei. Investigam, interpretam e estudam os casos de forma a representarem os seus clientes numa variedade de contextos, como os tribunais e os conselhos de administração. Criam argumentos em nome dos seus clientes para ações judiciais em diferentes contextos, com o objetivo de encontrarem uma solução legal.', 'released', '["Advogado", "Solicitador", "Solicitadora", "Advogada"]'::jsonb, '2611'),
  ('http://data.europa.eu/esco/occupation/9757122b-1161-4f4a-8286-a603d4ad7012', 'Trabalhador de Destilaria', 'Os trabalhadores de destilaria utilizam equipamentos e máquinas de destilarias industriais. Realizam a manutenção e a limpeza das máquinas, rolam os barris e carimbam os fundos dos barris.', 'released', '["Trabalhador de Destilaria", "Operadora de Destilação", "Trabalhadora de Destilaria", "Operador de Destilação"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/9766cc19-5a64-4b3c-a741-71561285a419', 'Professor de Antropologia', 'Os professores de Antropologia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Antropologia, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Antropologia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora Universitária de Antropologia", "Professor de Antropologia", "Professora de Antropologia", "Professor Universitário de Antropologia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/976c739f-fec7-45c2-b12e-e1b496aa816b', 'Operador de Trituradoras de Madeira', 'Os operadores de trituradoras de madeira asseguram o correto funcionamento das máquinas que cortam a madeira em pedaços pequenos para utilizar em painéis de partículas, para posterior transformação em pasta de papel, ou para utilização por direito próprio. A madeira é introduzida na trituradora e é triturada ou esmagada através de uma série de mecanismos.', 'released', '["Operadora de Trituradoras de Madeira", "Operador de Trituradoras de Madeira"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/976c7f50-7f9e-4347-bbb9-f0dc842046a3', 'Psicólogo da Saúde', 'Os psicólogos da saúde lidam com os vários aspetos do comportamento dos indivíduos e dos grupos em matéria de saúde, ajudando-os a prevenir doenças e a promover comportamentos saudáveis, incluindo através da prestação de serviços de aconselhamento. Realizam tarefas de desenvolvimento de atividades e projetos de promoção da saúde com base nas ciências psicológicas e em resultados de investigações, teorias, métodos e técnicas de psicologia. Além disso, realizam investigações sobre questões relacionadas com a saúde, a fim de influenciarem a política pública em matéria de cuidados de saúde.', 'released', '["Psicólogo da Saúde", "Psicóloga da Saúde"]'::jsonb, '2634'),
  ('http://data.europa.eu/esco/occupation/976cbfcc-8958-4800-a435-71d15405a42a', 'Professor de Ensino Especial', 'Os professores ensino especial trabalham no ensino de crianças, jovens e adultos com deficiência intelectual ou física. Recorrem a uma série de conceitos, estratégias e instrumentos especializados para otimizar a comunicação, a mobilidade, a autonomia e a integração social dos alunos. Selecionam métodos de ensino e recursos de apoio que permitam a cada aluno maximizar o seu potencial de vida independente.', 'released', '["Professor de Língua Gestual Portuguesa", "Professora de Língua Gestual Portuguesa", "Professor de Educação Especial", "Professora de Educação Especial", "Professora de Ensino Especial"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/976f752c-5f10-42ca-84fb-89aa529af04f', 'Condutor de Veículos de Transporte de Doentes', 'Os condutores de veículos de transporte de doentes transportam doentes com deficiência, vulneráveis e idosos de e para estabelecimentos de cuidados de saúde, tais como hospitais ou centros de assistência social. Conduzem a ambulância e zelam pelo bom estado de todo o equipamento conexo, mas em circunstâncias não urgentes.', 'released', '["Condutor de Veículos de Transporte de Doentes", "Condutora de Veículos de Transporte de Doentes"]'::jsonb, '8322'),
  ('http://data.europa.eu/esco/occupation/97896345-d102-4549-97a5-8851979e6938', 'Oleiro', 'Os oleiros processam e moldam a argila, à mão ou utilizando a roda, em produtos finais de cerâmica, produtos de grés, de faiança e porcelana. Introduzem a argila já formada em fornos, aquecendo-a a uma temperatura elevada para retirar toda a água da argila.', 'released', '["Ceramista", "Oleiro", "Oleira"]'::jsonb, '7314'),
  ('http://data.europa.eu/esco/occupation/978ae3a2-0831-415a-8396-b84dde656fc5', 'Alfaiate', 'Os alfaiates concebem, fazem ou adequam, alteram, reparam peças de vestuário feito à medida ou à mão a partir de tecidos têxteis, couro leve, peles com pelo e outro material, ou fazem chapéus e perucas para homens. Produzem peças de vestuário por medida, de acordo com as especificações do cliente ou do fabricante do vestuário. São capazes de ler e compreender tabelas de tamanho, pormenores sobre as medições acabadas, etc.', 'released', '["Modista", "Alfaiatea"]'::jsonb, '7531'),
  ('http://data.europa.eu/esco/occupation/97b3cab1-f4f0-41ed-8c80-e65e6c067e95', 'Técnico de Gás', 'Os técnicos de gás procedem à instalação e manutenção de aparelhos e sistemas de serviço de gás em instalações ou edifícios. Instalam o equipamento em conformidade com os regulamentos, reparam as falhas e investigam as fugas e outros problemas. Testam o equipamento e aconselham sobre a utilização e o cuidado de aparelhos e sistemas que utilizam a energia do gás.', 'released', '["Técnica de Instalação de Gás", "Técnico de Instalação de Gás", "Técnico de Gás", "Técnica de Gás"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/97d65832-3817-4ded-946b-cfc4a0237b9a', 'Planejador de Produção na Indústria do Couro', 'Os planificadores de produção na indústria do couro são responsáveis pelo planejamento e acompanhamento da produção. Trabalham com o gestor da produção para garantir o cumprimento dos prazos. Trabalham com o armazém para assegurar que é atingido o nível e qualidade ótimos dos materiais, bem como com o departamento de comercialização e venda para satisfazer os requisitos de encomendas dos clientes.', 'released', '["Planificador de Produção na Indústria do Couro", "Planificadora de Produção na Indústria do Couro", "Planejadora de Produção na Indústria do Couro"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/97dadd59-d1cb-4fef-81a7-d92eb15572e2', 'Soldador por Pontos', 'Os soldadores por pontos instalam e cuidam das máquinas de soldar por pontos, concebidas para pressionar e unir peças metálicas. A resistência do metal à passagem da corrente elétrica e o subsequente calor criado no processo permitem a fusão e a união local das peças.', 'released', '["Soldador por Pontos", "Soldadora por Pontos"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/97dd9a0c-dd6b-416d-9537-655a08dd2895', 'Fabricante de Pianos', 'Os fabricantes de pianos criam e montam peças para fabricar pianos, de acordo com instruções ou diagramas especificados. Lixam a madeira, afinam, testam e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Pianos"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/980c52f3-0054-45b1-a6f1-20ee8a1e8b9e', 'Gerente de Loja de Vestuário', 'Os gerentes de lojas de vestuário assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Roupa Infantil", "Gerente de Loja de Roupa", "Gerente de Loja de Roupa para Grávidas", "Gerente de Loja de Vestuário Técnico", "Gerentea de Loja de Vestuário"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/98164d70-93a8-409c-aa9f-7d56314f4d7f', 'Operador de Fresadora de Alta Velocidade', 'Os operadores de fresadora de alta velocidade instalam e operam fresadoras de árvores múltiplas, a fim de escavar ou cortar vários materiais duros, tais como madeira, compósitos, alumínio, aço e plásticos, e outros materiais, tais como espumas. Também interpretam esquemas para determinar os locais de corte e as dimensões específicas.', 'released', '["Operador de Fresadora de Alta Velocidade", "Operadora de Fresadora de Alta Velocidade"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/98358049-fbcd-479e-a644-e92bde5af2e0', 'Ativista', 'Os ativistas promovem ou dificultam as mudanças sociais, políticas, econômicas ou ambientais, recorrendo a estratégias diferentes, como a investigação persuasiva, a pressão mediática ou as campanhas públicas.', 'released', NULL, '2432'),
  ('http://data.europa.eu/esco/occupation/983c2816-a339-4817-97f4-151a9ff3e64d', 'Responsável de Registros Médicos', 'Os responsáveis de registos médicos têm a seu cargo a gestão das atividades de registo médico, para manutenção e proteção dos dados dos doentes. Supervisionam e formam os trabalhadores, ao mesmo tempo que executam as políticas do departamento médico.', 'released', NULL, '3252'),
  ('http://data.europa.eu/esco/occupation/9851c83c-5670-4da0-964a-1ef0e682e30b', 'Investigador em Tanatologia', 'Os investigadores em tanatologia estudam a morte e os moribundos em vários domínios científicos, como a psicologia, a sociologia, a fisiologia e a antropologia. Contribuem para o desenvolvimento de conhecimentos sobre aspetos da morte, como os fenômenos psicológicos vividos pelos moribundos e pelos que os rodeiam.', 'released', '["Investigadora em Tanatologia", "Investigador em Tanatologia"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/985400a7-362f-4f91-941a-2e149d94ac2a', 'Escanção de Cerveja', 'Os escanções de cerveja compreendem e aconselham sobre estilos, o de cerveja e o melhor emparelhamento das cervejas com alimentos em locais como restaurantes, fábricas de cerveja e lojas. Conhecem os seus ingredientes, a história das cervejas, os artigos de vidro e os sistemas de tiragem. Preparam provas de cerveja, consultam empresas e clientes, avaliam os produtos de cerveja e escrevem sobre este assunto.', 'released', '["Escanção de Cerveja", "Escançã de Cerveja", "Escançãa de Cerveja"]'::jsonb, '5131'),
  ('http://data.europa.eu/esco/occupation/98588703-5f5c-41c6-a240-3411b6518b83', 'Especialistas em Import-Export de Produtos Farmacêuticos', 'Os especialistas em import-export de produtos farmacêuticos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Produtos Farmacêuticos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/98ad0008-13d9-4e9b-94bf-4f4a5faae764', 'Gestor da Infraestrutura Ferroviária', 'Os gestores da infraestrutura ferroviária ocupam-se da supervisão, da concepção e do controlo dos processos de transporte. Os gestores da infraestrutura ferroviária podem trabalhar para os operadores ferroviários no que respeita a tarefas como a gestão segura e eficiente dos serviços de transporte, incluindo tarefas relacionadas com o cliente ou a gestão do pessoal e da organização do trabalho neste domínio. Os gestores da infraestrutura ferroviária empregados pelos operadores das infraestruturas gerem a utilização eficiente e segura da rede. Tal inclui a planificação dos horários e a atribuição de faixas horárias aos clientes. Planificam os trabalhos de construção e manutenção.', 'released', '["Chefe de Trem", "Gestora da Infraestrutura Ferroviária", "Operadora de Transporte Ferroviário", "Maquinista", "Chefe de Estação", "Chefe de Linha", "Operador de Transporte Ferroviário", "Gestor da Infraestrutura Ferroviária", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/98af7387-3974-457a-aa57-5397d1ea3949', 'Arquiteto de Espaços Verdes de Interiores', 'Os arquitetos de espaços verdes interiores procedem à concepção, instalação, gestão e manutenção de espaços verdes interiores de acordo com os requisitos dos clientes.', 'released', '["Arquiteto de Espaços Verdes de Interiores", "Arquiteta de Espaços Verdes de Interiores"]'::jsonb, '6113'),
  ('http://data.europa.eu/esco/occupation/98b261ec-def2-4871-b062-56cdd290c844', 'Assistente Social de Serviço de Ação Social das Forças Armadas', 'Os assistentes sociais de serviço de ação social das Forças Armadas prestam assistência às famílias para fazer face ao destacamento militar de um familiar, apoiando-as ao longo do processo de adaptação à partida e ao regresso desse familiar. Ajudam os adolescentes a superar o medo de perderem os seus pais em missão ou de não reconhecerem os pais aquando do seu regresso. Os assistentes sociais de serviço de ação social das Forças Armadas ajudam os veteranos a readaptarem-se à vida civil, bem como a gerirem o sofrimento, as perturbações traumáticas ou a tristeza.;', 'released', '["Assistentea Social de Serviço de Ação Social das Forças Armadas"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/98c3d8f8-e3a8-49b7-9e58-236f25a6f6a0', 'Configurador de Sistemas', 'Os configuradores de sistemas adaptam um sistema informático às necessidades da organização e dos usuários. Ajustam o sistema de base e o «software» às necessidades do cliente. Realizam atividades de configuração e de criação de «scripts» e asseguram a comunicação com os usuários.', 'released', '["Configurador de Sistemas", "Responsável Pela Configuração de Sistemas", "Configuradora de Sistemas"]'::jsonb, '2522'),
  ('http://data.europa.eu/esco/occupation/98c429ad-128e-467e-803a-9a6dc1ceed72', 'Montador de Pneus', 'Os montadores de pneus procedem à inspeção, manutenção e reparação e instalação de pneus em veículos. Aconselham os clientes sobre diferentes tipos de pneus e de rodas. Também equilibram os pneus, verificam se as rodas estão corretamente alinhadas e garantem a conformidade com as normas e os regulamentos de segurança.', 'released', '["Montadora de Pneus", "Montador de Pneus"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/98e58946-3227-4f6c-a5d1-5892fe76883d', 'Técnico de Serviço Após-Venda', 'Os técnicos de serviço pós-venda prestam assistência pós-venda aos clientes, nomeadamente no que diz respeito à instalação, à manutenção e à reparação dos produtos vendidos. Tomam medidas corretivas para garantir a satisfação dos clientes, resolvem problemas técnicos relacionados com os produtos e redigem relatórios de síntese para os clientes.', 'released', '["Técnica de Serviço Após-Venda", "Técnico de Serviço Após-Venda"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/98f17395-0f8c-4f51-9072-cb8f66fd6044', 'Especialista em Política Agrícola', 'Os especialistas em política agrícola analisam e identificam questões de política agrícola e desenvolvem planos para a sua melhoria e para a aplicação de novas políticas neste domínio. Redigem relatórios e apresentações, a fim de comunicarem com funcionários governamentais e com o público e de obterem junto destes apoio para as suas políticas. Comunicam igualmente com profissionais do setor da agricultura para fins de investigação e informação e desempenham funções administrativas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/98f9909b-016d-4c62-90ae-893b0cbabbca', 'Gerente de Tabacaria e Papelaria', 'Os gerentes de tabacaria e papelaria assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Quiosque", "Gerente de Papelaria", "Gerentea de Tabacaria e Papelaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/98fa571c-dc8f-438f-909f-f426ec322c72', 'Comerciante Grossista de Máquinas-Ferramentas', 'Os comerciantes grossistas de máquinas-ferramentas investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Máquinas-Ferramentas"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/9905cc76-d48b-49b1-94ab-17becb30be1a', 'Professor de Ciências da Nutrição e Alimentação', 'Os professores de Ciências da Nutrição e Alimentação são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências da Nutrição e Alimentação, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio das Ciências da Nutrição e Alimentação, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Ciências da Nutrição e Alimentação", "Professor Universitário de Ciências da Nutrição e Alimentação", "Professor de Ciências da Nutrição e Alimentação", "Professora Universitária de Ciências da Nutrição e Alimentação"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/990738f4-587c-4045-a10f-e3c1c019220e', 'Operador de Máquinas de Fabricação de Blocos de Alvenaria', 'Os operadores de máquinas de fabrico de blocos de alvanaria procedem ao controlo, à manutenção e operação da máquina de moldes de blocos de alvanaria, que enche e faz vibrar os moldes para compactar o betão úmido para produzir blocos acabados.', 'released', '["Operadora de Máquinas de Fabricação de Blocos de Alvenaria", "Operador de Máquinas de Fabricação de Blocos de Alvenaria"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/990bfa45-5001-4365-93b6-daf01a03b4cd', 'Técnico de Remoção de Amianto', 'Os técnicos de remoção de amianto eliminam o amianto dos edifícios e outras construções, em conformidade com a regulamentação em matéria de saúde e segurança relativa ao manuseamento de materiais perigosos. Investigam a intensidade da contaminação pelo amianto, preparam a estrutura para a remoção e evitam a contaminação de outras áreas.', 'released', '["Técnico de Remoção de Amianto", "Técnica de Remoção de Amianto"]'::jsonb, '7133'),
  ('http://data.europa.eu/esco/occupation/99492920-e5a5-4dba-9e5a-93193147198c', 'Economista', 'Os economistas realizam atividades de investigação e desenvolvem teorias no domínio da economia, para efeitos de análise microeconómica ou macroeconómica. Estudam as tendências, analisam os dados estatísticos e, em certa medida, trabalham com modelos econômicos matemáticos a fim de prestarem aconselhamento a empresas, governos e instituições conexas. Prestam aconselhamento sobre a viabilidade dos produtos, as previsões de tendências, os mercados emergentes, as políticas fiscais e as tendências dos consumidores.', 'released', '["Econometrista"]'::jsonb, '2631'),
  ('http://data.europa.eu/esco/occupation/994fe880-dc26-4f0f-a3cd-500709b6a665', 'Engenheiro de Precisão', 'Os engenheiros de precisão concebem processos, máquinas, fixações e outros equipamentos com tolerâncias de engenharia excecionalmente baixas, repetíveis e estáveis ao longo do tempo. Garantem que os protótipos são construídos e testados e asseguram que os projetos cumprem as especificações do sistema e os requisitos operacionais.', 'released', '["Nanotechnóloga", "Nanotecnólogo", "Engenheiro de Precisão", "Engenheira Eletrônica", "Engenheira de Precisão", "Engenheiro Eletrônico"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/9967986b-570d-4db1-a179-aad7d1623ea8', 'Técnico de Operações Aeroportuárias', 'Os técnicos de operações aeroportuárias executam funções de supervisão e administrativas, acompanhando as atividades operacionais correspondentes ao turno atribuído num grande aeroporto. Asseguram a descolagem e a aterragem de aeronaves em condições de segurança.', 'released', '["Técnica de Operações Aeroportuárias"]'::jsonb, '3154'),
  ('http://data.europa.eu/esco/occupation/9980a417-f990-495a-ae11-66a112737f3b', 'Recozedor de Vidro', 'Os recozedores de vidro operam fornos elétricos ou a gás utilizados para reforçar os produtos de vidro através de um processo de aquecimento e arrefecimento, garantindo que a temperatura esteja definida de acordo com as especificações. Inspecionam os produtos de vidro ao longo de todo o processo para observar eventuais falhas.', 'released', '["Operador de Fornos de Recozimento de Vidro", "Operadora de Fornos de Recozimento de Vidro", "Recozedor de Vidro", "Recozedora de Vidro", "Operador de Fornos Elétricos de Recozimento de Vidro", "Operadora de Fornos Elétricos de Recozimento de Vidro"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/998a0bf4-b1be-42ab-aee5-0096c9be3319', 'Técnico de Qualidade', 'Os técnicos de qualidade trabalham com engenheiros ou gestores de qualidade para analisar e resolver problemas de qualidade e aumentar a produtividade. Verificam máquinas para detecção de imperfeições e inspecionam os produtos, com o objetivo de garantir a sua conformidade com as normas. Além disso, formam o pessoal em técnicas de inspeção e elaboram planos de inspeção.', 'released', '["Técnico de Qualidade", "Técnica de Qualidade"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/99b096eb-a628-4e69-a79b-0563f2ed1b93', 'Supervisor de Guião', 'Os supervisores de guião são responsáveis pela continuidade do filme ou do programa de televisão. Assistem a cada filmagem para se certificar de que esteja de acordo com o guião. Os supervisores de guião asseguram que durante a montagem a história faz sentido visual e verbal e não contém quaisquer erros de continuidade.', 'released', '["Anotador", "Anotadora", "Supervisora de Guião", "Supervisor de Guião"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/99d97310-29ea-443e-96a1-892c8d86ce54', 'Especialista em Import-Export de Móveis, Carpetes e Artigos de Iluminação', 'Os especialistas em import-export de móveis, carpetes e artigos de iluminação possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Móveis, Carpetes e Artigos de Iluminação"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/99ebf2c2-1811-4c77-b2e6-7008cba29ea0', 'Técnico de Veterinária', 'Os técnicos de veterinária prestam apoio técnico e administrativo ao veterinário, em conformidade com a legislação nacional.', 'released', '["Auxiliar de Veterinária", "Assistente de Veterinário", "Auxiliar de Veterinário", "Assistente de Veterinária", "Técnica de Veterinária", "Técnico de Veterinária"]'::jsonb, '3240'),
  ('http://data.europa.eu/esco/occupation/9a20c93e-a345-4a46-a406-9ffbf11daeef', 'Gestor de Resíduos', 'Os gestores de resíduos fornecem aconselhamento e aplicam a regulamentação relativa às instalações que gerem a eliminação, a recolha e a reciclagem de resíduos. Elaboram e aplicam regras e avaliam a conformidade com a legislação existente.', 'released', '["Gestora de Resíduos", "Gestor de Resíduos", "Gerente"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/9a2147aa-a72f-4f83-8653-c3f50d4e1e73', 'Intérprete de Linguagem Gestual', 'Os intérpretes de linguagem gestual compreendem e convertem a língua gestual em língua falada e vice-versa. Mantêm as subtilezas e a tônica da mensagem na língua do destinatário.', 'released', '["Intérpretea de Linguagem Gestual"]'::jsonb, '2643'),
  ('http://data.europa.eu/esco/occupation/9a26d76b-b9e3-46ae-ab4b-057a1262138b', 'Coordenador de Ensino Especial e Apoios Educativos', 'Os coordenadores de ensino especial e apoios educativos supervisionam programas e atividades que prestam apoio educativo a crianças com uma variedade de deficiências. Estão a par dos mais recentes desenvolvimentos no domínio da investigação das necessidades especiais, com o objetivo de facilitar os processos de ensino especial necessários para maximizar o potencial de crescimento e de aprendizagem dos alunos com necessidades de aprendizagem especiais, e aconselhar o responsável pelo ensino especial sobre estes desenvolvimentos e novas propostas de programas.', 'released', '["Coordenador da Educação Especial e Apoios Educativos", "Coordenadora da Educação Especial e Apoios Educativos", "Coordenadora de Ensino Especial e Apoios Educativos"]'::jsonb, '2351'),
  ('http://data.europa.eu/esco/occupation/9a39a143-d93c-4093-ba3b-47fb67ade318', 'Escriturário de Seguros', 'Os escriturários de seguros exercem funções de escritório gerais e administrativas numa companhia de seguros, outra instituição de serviços, no agente ou corretor de seguros por conta própria ou numa instituição governamental. Prestam assistência e fornecem informações sobre os seguros aos clientes e gerem a burocracia dos contratos de seguro.', 'released', '["Escriturária de Seguros", "Escriturário de Seguros"]'::jsonb, '4312'),
  ('http://data.europa.eu/esco/occupation/9a4ba556-e72b-49c2-834c-d6a03a2fc906', 'Piloto de Aeronaves', 'Os pilotos de aeronaves controlam e pilotam aeronaves. Operam os sistemas mecânicos e elétricos da aeronave e transportam passageiros, correspondência e mercadorias.', 'released', '["Pilota de Aeronaves"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/9a6d8a84-a8a9-4c9b-9ead-59a710e93759', 'Professor de Cursos Profissionais de Gestão e Marketing', 'Os professores de cursos profissionais de gestão e marketing formam os alunos no seu domínio de estudos especializado, a vendas e o marketing, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar para uma profissão relacionada com as vendas e o marketing. Os professores de cursos profissionais de gestão e marketing acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio das vendas e do marketing através de trabalhos, testes e exames.', 'released', '["Professor de Cursos Profissionais de Gestão e Marketing", "Professora de Cursos Profissionais de Gestão e Marketing"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/9a7e780a-b778-4a5a-b4eb-309d394d313d', 'Professor de Literatura', 'Os professores de Literatura são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Literatura, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Literatura, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora Universitária de Literatura", "Professor Universitário de Literatura", "Professor de Literatura", "Professora de Literatura"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/9a903a4a-282d-4724-a7de-1918b41d2965', 'Inspetor de Montagem de Veículos a Motor', 'Os inspetores da montagem de veículos a motor utilizam equipamentos de medição e de ensaio para inspecionar e monitorizar os conjuntos de veículos a motor, a fim de garantir a conformidade com as especificações de engenharia e de fabrico, a qualidade e as normas e regulamentos de segurança. Detectam anomalias e danos e inspecionam o trabalho de reparação. Também fornecem documentação de inspeção pormenorizada e recomendam medidas nos casos em que sejam detectados problemas.', 'released', '["Inspetor de Montagem de Veículos a Motor", "Inspetora de Montagem de Veículos a Motor"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/9a99a5fe-875d-49b2-9b53-cc1b73be1659', 'Agente de Vendas de Passagens de Trem', 'Os agentes de vendas de bilhetes de comboio prestam serviço a clientes no balcão de vendas. Fornecem informações, tratam de reservas, vendas e reembolsos de bilhetes. Também realizam tarefas administrativas, tal como a manutenção do balanço das vendas diárias de bilhetes. Tratam os pedidos de reservas de lugares e analisam os diagramas de cada carruagem no comboio para verificar o espaço disponível no comboio especificado.', 'released', '["Sales", "Agentea de Vendas de Passagens de Trem"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/9aa2115d-83cb-4db1-af1d-b426c87c2393', 'Assistente Social em Estabelecimentos Prisionais', 'Os assistentes sociais em estabelecimentos prisionais combatem os comportamentos criminosos e reduzem o risco de reincidência através da promoção e do estabelecimento de programas de prevenção da criminalidade nas comunidades. Prestam assistência em processos de acusação e ajudam a investigar processos penais. Prestam apoio na reinserção de prisioneiros na comunidade após a sua libertação. Além disso, apoiam e supervisionam infratores condenados a serviço comunitário e prestam apoio às vítimas e às pessoas diretamente afetadas pelo crime.', 'released', '["Assistentea Social em Estabelecimentos Prisionais"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/9aa2a36f-296e-45fe-9798-b7839e0ed389', 'Técnico de Eletrotecnia', 'Os técnicos de eletrotecnia trabalham em conjunto com engenheiros eletrotécnicos em investigação na área da engenharia eletrotécnica. Desempenham tarefas técnicas e prestam assistência na concepção, no ensaio, no fabrico e na operação de dispositivos e equipamentos elétricos.', 'released', '["Técnica de Eletrotecnia", "Técnico de Electrotecnia"]'::jsonb, '3113'),
  ('http://data.europa.eu/esco/occupation/9ab02537-920a-4549-9711-fd999fd40c28', 'Operador de Máquina de Venda Automática', 'Os operadores de máquina de venda automática retiram o dinheiro, realizam inspeções visuais à máquina, prestam manutenção de base e reabastecem os produtos de venda automática e outras máquinas que funcionam com moedas.', 'released', '["Técnica de Máquinas de Venda Automáticas", "Coletor de Dinheiro em Máquina de Venda Automática", "Técnico de Máquinas de Venda Automáticas", "Coletora de Dinheiro em Máquina de Venda Automática", "Operador de Lavandaria Self-Service", "Coletora de Dinheiro em Lavandaria Self-Service", "Operadora de Máquina de Venda Automática"]'::jsonb, '9623'),
  ('http://data.europa.eu/esco/occupation/9ab0f0db-1128-4050-becd-b09db5eabdaa', 'Classificador Arquivista', 'Os classificadores arquivistas são responsáveis pela manutenção de registos de uma empresa e pela gestão de formulários e informações. Organizam e procuram documentos, quando necessário, e asseguram um sistema de trabalho eficiente.', 'released', '["Classificador Arquivista", "Classificadora Arquivista"]'::jsonb, '4415'),
  ('http://data.europa.eu/esco/occupation/9ab80ce6-504f-474f-bb91-98163e9d45fd', 'Cozinheiro Dietista', 'Os cozinheiros dietistas preparam e apresentam refeições de acordo com necessidades alimentares ou nutricionais especiais.', 'released', '["Cozinheiro Dietetista", "Cozinheira Dietetista", "Cozinheira Dietista"]'::jsonb, '5120'),
  ('http://data.europa.eu/esco/occupation/9ac10bde-93a0-4570-afc2-e2b6cf46d8d2', 'Técnico de Luz', 'Os técnicos de luz procedem à instalação, à preparação, controlo e manutenção do equipamento a fim de fornecer uma ótima qualidade de iluminação para espetáculos ao vivo e filmes. Cooperam com a equipe de apoio de estrada para descarregar, instalar e operar equipamentos e instrumentos de iluminação.', 'released', '["Técnico de Luz", "Técnica de Luz"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/9ae8251e-cb8e-4324-9d77-d967d43e6b46', 'Operador de Instalação de Filtragem de Gordura', 'Os operadores de instalação de filtragem de gordura operam equipamento e tanques de acidulação que ajudam na separação de componentes indesejáveis provenientes dos óleos.', 'released', '["Operadora de Filtro de Gordura", "Operador de Instalação de Filtragem de Gordura", "Operadora de Instalação de Filtragem de Gordura", "Operador de Filtro de Gordura"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/9aeefea6-11c3-4479-b703-902ee84787d7', 'Operador de Transformação de Produtos Lácteos', 'Os operadores de transformação de produtos lácteos instalam e operam um equipamento de fluxo contínuo ou do tipo cuba para processar leite, queijo, gelados e outros produtos lácteos em conformidade com instruções, métodos e fórmulas específicos.', 'released', '["Operadora de Processamento de Laticínios", "Operador de Processamento de Laticínios", "Operadora de Transformação de Produtos Lácteos", "Operador de Transformação de Produtos Lácteos"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/9af5fd79-d76e-4343-bc13-ff2d172aec62', 'Modelo de Moda', 'Os modelos de moda ajudam a promover produtos, tais como vestuário, cosméticos e aparelhos, posando para jornalistas, fotógrafos e perante um público em passarelas. Têm de garantir que o seu aspeto seja sempre arranjado. Os modelos de moda têm de ter um bom aspeto em frente de uma câmara e fazer as poses corretamente.', 'released', '["Modelo", "Manequim", "Modela de Moda"]'::jsonb, '5241'),
  ('http://data.europa.eu/esco/occupation/9af8907f-56a7-4170-83b1-3c6ba0997cfa', 'Especialista em Sistemas de Informação Geográfica', 'Os especialistas em sistemas de informação geográfica utilizam sistemas informáticos especializados, medidas de engenharia e conceitos geológicos para transformar a informação terrestre, geográfica e geoespacial em mapas digitais e geomodelos visualmente pormenorizados de um reservatório. Convertem informações técnicas como a densidade e as propriedades do solo em representações digitais a utilizar por engenheiros, governos e partes interessadas.;', 'released', '["Especialista em Geomodelos", "Técnico de SIG", "Analista de SIG", "Especialista em Aplicações dos SIG", "Técnica de SIG", "Especialista em SIG"]'::jsonb, '2165'),
  ('http://data.europa.eu/esco/occupation/9b35eab1-2adc-4057-a620-181862656a19', 'Agente de Informação Turística', 'Os agentes de informação turística prestam informações e aconselhamento aos viajantes sobre as atrações, eventos, viagens e alojamento a nível local.', 'released', '["Agente de Informação Turística", "Funcionária de Posto de Turismo", "Recepcionista de Posto de Turismo", "Funcionário de Posto de Turismo", "Agentea de Informação Turística"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/9b3c6dd8-4d3b-4a12-8bb8-55bb2e92c3a6', 'Responsável de Compras de Guarda-Roupa e Adereços', 'Os responsáveis de compras de guarda-roupa e adereços analisam o guião a fim de identificarem o guarda-roupa e os adereços necessários para cada uma das cenas. Consultam igualmente o designer responsável pela produção e a equipe de criação dos adereços e dos cenários. Os responsáveis de compras de guarda-roupa e adereços compram, alugam ou encomendam a produção dos adereços. Os responsáveis de compras de guarda-roupa e adereços certificam-se de que os cenários são autênticos e credíveis.', 'released', NULL, '3323'),
  ('http://data.europa.eu/esco/occupation/9b51a2d2-999a-43a6-a814-63dd30a585fa', 'Inspetor de Ensino', 'Os inspetores de ensino visitam as escolas para assegurar que o pessoal desempenha as suas funções em conformidade com as regras e a regulamentação em matéria de ensino e que a administração, as instalações e o equipamento da escola estão em conformidade com os regulamentos. Observam aulas e analisam registos para avaliar o funcionamento da escola e redigem relatórios com as suas conclusões. Prestam informações e aconselhamento sobre melhorias e comunicam os resultados aos funcionários superiores. Por vezes, também preparam cursos de formação e organizam conferências em que os professores da disciplina devem participar.', 'released', '["Inspetora de Educação", "Inspetora Escolar", "Inspetor de Educação", "Inspetor Escolar", "Inspetora de Ensino"]'::jsonb, '2351'),
  ('http://data.europa.eu/esco/occupation/9b889f07-c39c-464d-b9d9-b2daa650f9ac', 'Médico Especialista', 'Os médicos especialistas previnem, diagnosticam e tratam doenças em função da sua especialidade médica ou cirúrgica.', 'released', '["Médica Especialista", "Médico Especialista"]'::jsonb, '2212'),
  ('http://data.europa.eu/esco/occupation/9ba74e8a-c40c-4228-9998-eb3c7a5c11df', 'Assistente de Vendas', 'Os assistentes de vendas representam o contato direto com os clientes. Prestam aconselhamento geral aos clientes.', 'released', '["Sales", "Assistentea de Vendas"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/9beeb1f0-5aca-4bde-bae9-c74ddb94fac3', 'Gerente de Loja Têxtil', 'Os gerentes de loja têxtil assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Tecidos", "Gerente de Retrosaria", "Gerentea de Loja Têxtil"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/9bf4c8ea-e814-4772-ae31-0f29672dc497', 'Capitão do Exército', 'Os capitães do Exército auxiliam na supervisão de grandes unidades de soldados e procedem ao planejamento e tarefas estratégicas em operações táticas. Além disso, asseguram a manutenção do equipamento e prestam apoio em aspetos logísticos e durante as operações.', 'released', '["Alferes do Exército", "Marechal do Exército", "Tenente-Capitão do Exército", "Capitãa do Exército"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/9c3cdf9a-f62f-4d73-bb8d-4cfc85c2d271', 'Bombeiro Naval', 'Os bombeiros navais são responsáveis pela resposta de emergência em caso de incêndio ou outras situações perigosas em ambientes navais. Respondem ativamente para conter incêndios e outros riscos perigosos para os navios, as docas e outras instalações navais. Asseguram a conformidade da instalação naval com a regulamentação em matéria de saúde e segurança. Também regulam a limpeza do local e avaliam os danos.', 'released', '["Bombeiro Naval", "Bombeira Naval"]'::jsonb, '5411'),
  ('http://data.europa.eu/esco/occupation/9c55aa23-e3f2-4c00-8c90-5ed5204951a3', 'Técnico de Apoio à Deficiência', 'Os técnicos de apoio à deficiência prestam assistência pessoal e apoio a indivíduos de todas as idades com condições de deficiência, quer intelectual quer física. Trabalham com outros profissionais de saúde para maximizar o bem-estar físico e mental dos indivíduos. As suas funções incluem dar banho, levantar, deslocar, vestir ou alimentar pessoas com deficiência.', 'released', '["Técnico de Apoio à Deficiência", "Técnica de Apoio à Deficiência"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/9c57263e-a38f-4c45-9265-a3c3e7cc2c5c', 'Escoveiro', 'Os escoveiros introduzem diferentes tipos de material, tais como crina, fibra vegetal, nylon e cerdas em tubos metálicos denominados «virolas». Introduzem um tampão de madeira ou de alumínio nas cerdas para formar a cabeça da escova e fixam o cabo no outro lado da virola. Mergulham a cabeça da escova numa substância protetora, para manter a forma, terminam e inspecionam o produto final.', 'released', '["Escoveira", "Escoveiro"]'::jsonb, '7317'),
  ('http://data.europa.eu/esco/occupation/9c61bba4-56b7-4846-9f4e-b1f2decf3e7e', 'Operador de Central de Alarme', 'Os operadores de central de alarme respondem a sinais de alarme contra roubo e investigar perturbações identificadas pelo sistema de alarme nas instalações dos clientes. Vigiam os sistemas de alarme de segurança e outros dispositivos de vigilância e contactam a polícia em caso de invasão da propriedade.', 'released', '["Operadora de Central de Alarme", "Operador de Central de Alarme"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/9c9752b7-3e3b-4a08-8553-b63a013f8072', 'Gestor de Experiência do Cliente', 'Os gestores de experiência do cliente acompanham as experiências dos clientes através da criação, avaliação e melhoria das organizações de interação com o cliente no setor da hotelaria, do lazer ou do entretenimento. Desenvolvem planos de ação para otimizar todos os aspetos da experiência do cliente. Os gestores de experiência do cliente procuram assegurar a satisfação dos clientes e aumentar os lucros da empresa.', 'released', '["Gestora de Experiência do Cliente", "Gestor de Relações com os Clientes", "Relações Públicas", "Gestor de Experiência do Cliente", "Gestora de Relações com os Clientes", "Gerente"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/9cda1c7c-ba07-4381-b831-1bb346ff865f', 'Conselheiro Matrimonial', 'Os conselheiros matrimoniais apoiam e orientam os casais e as famílias que estão a atravessar crises como a depressão, o abuso de substâncias e problemas de relacionamento. Ajudam a melhorar a comunicação através de terapia de grupo ou individual.', 'released', '["Conselheiro Matrimonial", "Conselheira Matrimonial"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/9ce12690-c3bf-4135-b7a5-b666bb8c68f5', 'Técnico de Topografia de Minas', 'Os técnicos de topografia de minas realizam levantamentos de limites fronteiriços e topográficos e levantamentos do progresso das operações de exploração mineira. Operam equipamentos de geodesia e utilizam programas para recolher e interpretar dados pertinentes, executando cálculos quando necessário.', 'released', '["Técnico de Topografia de Minas", "Técnica de Topografia de Minas"]'::jsonb, '3117'),
  ('http://data.europa.eu/esco/occupation/9cee6106-04cf-401a-ae4c-b4b8652d6915', 'Chefe de Estação', 'Os chefes de estação são responsáveis pelo desempenho seguro de todas as tarefas operacionais a bordo de comboios de passageiros fora da cabina de condução, tais como a supervisão da abertura e do fecho das portas do comboio em segurança. Supervisionam e asseguram o acompanhamento contínuo da segurança dos passageiros, especialmente em caso de incidentes técnicos e de situações de emergência. Asseguram a comunicação operacional ao maquinista e ao pessoal de controlo do tráfego, tal como definido nos regulamentos operacionais. No caso de vários membros do pessoal estarem de serviço no comboio, supervisionam a equipe de cobradores. Também desenvolvem atividades comerciais, tais como o controlo e a venda de bilhetes, prestam apoio e informação aos passageiros e prestam serviços gastronómicos. ;', 'released', '["Chefea de Estação"]'::jsonb, '5112'),
  ('http://data.europa.eu/esco/occupation/9d2aae3e-cbfe-409f-86cc-7cef9cd0435a', 'Supervisor de Centro de Contato', 'Os supervisores de centros de contato supervisionam e coordenam as atividades dos trabalhadores de centros de contato. Asseguram que as operações diárias decorrem sem problemas através da resolução de problemas, do fornecimento de instruções e da formação de pessoal e da supervisão de tarefas.', 'released', '["Supervisor de Centro de Contato", "Supervisora de Centro de Contato"]'::jsonb, '3341'),
  ('http://data.europa.eu/esco/occupation/9db7d74c-b46d-45c0-b611-6bcb7456ecc6', 'Gestor de Investigação em Tecnologia da Informação', 'Os gestores de investigação em TIC planificam, gerem e controlam as atividades de investigação e avaliam as tendências emergentes no domínio das tecnologias da informação e da comunicação, a fim de avaliar a sua pertinência. Também concebem e supervisionam a formação do pessoal sobre a utilização de novas tecnologias e recomendam formas de implementar novos produtos e soluções que maximizem os benefícios para a organização.', 'released', '["Gestor de Investigação em Tecnologias de Informação e Comunicação", "Gestor de Inovação Tecnológica", "Gestor de Investigação em Informática", "Gestor de Investigação em TI", "Gestora de Investigação em Informática", "Gestora de Investigação em TI", "Gestora de Inovação Tecnológica", "Gestora de Investigação em Tecnologias de Informação e Comunicação", "Gestor de Investigação em Tecnologias da Informação", "TI", "Gerente", "Gestora de Investigação em Tecnologia da Informação"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/9dbbeb2c-0d51-4c03-8ef6-8dfa7360db22', 'Oficial Assistente de Navios', 'Os oficiais assistentes de navios prestam assistência ao chefe de máquinas e ao oficial de turno nas operações de engenharia de cascos de navio. Prestam apoio ao funcionamento das máquinas principais, do mecanismo de direção, do sistema de produção elétrica e de outros importantes subsistemas. Comunicam com os chefes de máquinas sobre o desempenho das operações técnicas. Além disso, asseguram o cumprimento de normas de segurança e regulamentares adequadas e podem assumir funções de nível superior, se necessário.', 'released', NULL, '3151'),
  ('http://data.europa.eu/esco/occupation/9deee896-be9b-4aac-b55e-ceff1a7a843a', 'Gestor de ETAR', 'Os gestores de ETAR coordenam e planificam condutas e sistemas de esgotos e supervisionam as operações de construção e manutenção das ETAR. Supervisionam as estações de tratamento de águas residuais e outras instalações de tratamento de águas residuais e asseguram a conformidade das operações com a regulamentação.', 'released', '["Gestora de ETAR", "Gestor de ETAR", "Gestor de Estação de Tratamento de Resíduos", "Gestora de Estação de Tratamento de Resíduos", "Gerente"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/9defc0f8-3eed-4a56-80e1-d534983aff4f', 'Supervisor de Demolições', 'Os supervisores de demolições acompanham as operações de demolição de edifícios e de limpeza do entulho. Tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Demolições", "Supervisor de Demolições"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/9e1a31bf-2963-40f4-95af-cedc3fbac537', 'Professor de Cursos Profissionais de Design e Artes Aplicadas', 'Os professores de cursos profissionais de design e artes aplicadas formam os alunos no seu domínio de estudos especializado, o design e artes aplicadas, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar para uma profissão de design e artes aplicadas, tais como designer gráfico ou designer de interiores. Os professores de cursos profissionais de design e artes aplicadas acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio do design e artes aplicadas através de trabalhos, testes e exames.', 'released', '["Professor de Design e Artes Aplicadas", "Professora de Design e Artes Aplicadas", "Professora de Cursos Profissionais de Design e Artes Aplicadas"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/9e1e8379-6377-4969-b141-0d2337218fc9', 'Coordenador de Desenvolvimento Econômico', 'Os coordenadores de desenvolvimento econômico definem e aplicam políticas destinadas a melhorar o crescimento e a estabilidade econômicos de uma comunidade, de um governo ou de uma instituição. Investigam as tendências econômicas e coordenam a cooperação entre as instituições que trabalham na área do desenvolvimento econômico. Analisam os potenciais riscos e conflitos econômicos e desenvolvem planos para a sua resolução. Os coordenadores de desenvolvimento econômico prestam aconselhamento sobre a sustentabilidade econômica e o crescimento econômico das instituições.', 'released', '["Coordenadora de Desenvolvimento Econômico", "Coordenador de Desenvolvimento Econômico"]'::jsonb, '2631'),
  ('http://data.europa.eu/esco/occupation/9e285322-2cfa-430f-9b66-41be57d698e2', 'Lobista', 'Os lobistas funcionam como representantes do objetivo de um cliente. Procuram persuadir os órgãos legislativos e os decisores políticos a aplicarem leis ou regulamentos em conformidade com os desejos do cliente, bem como a negociarem com partes com interesses potencialmente contraditórios. Executam tarefas de análise e investigação, a fim de assegurarem que a causa do cliente está a ser dirigida de forma adequada às partes apropriadas. Consultam igualmente os seus clientes sobre as suas causas e políticas.', 'released', NULL, '2432'),
  ('http://data.europa.eu/esco/occupation/9e2e6e1e-363b-4e1b-a673-7bc0f7343300', 'Administrador de Sistemas Informáticos', 'Os administradores de sistemas informáticos são responsáveis pela manutenção, pela configuração e pela fiabilidade do funcionamento de sistemas, servidores, estações de trabalho e dispositivos periféricos informáticos e de rede. Podem adquirir, instalar ou atualizar componentes e «software» de computador, automatizar tarefas de rotina, escrever programas informáticos, resolver problemas, formar e supervisionar o pessoal e prestar assistência técnica. Asseguram a máxima integridade, segurança, capacidade de salvaguarda e desempenho do sistema.', 'released', '["Administrador de Tecnologia da Informação", "Administradora de Tecnologias de Informação e Comunicação", "Administradora de Sistemas Informáticos", "Administrador de Servidores", "Administrador de Tecnologias de Informação e Comunicação", "Administrador de Sistemas", "Administradora de Sistemas", "Administrador de Sistemas Informáticos", "Administradora de Tecnologia da Informação", "Administradora de Servidores"]'::jsonb, '2522'),
  ('http://data.europa.eu/esco/occupation/9e4269d5-e10e-4f49-ac99-65c833f933a2', 'Governador do Banco Central', 'Os governadores dos bancos centrais fixam a política monetária e regulamentar, determinam as taxas de juro, mantêm a estabilidade dos preços, controlam o fornecimento e a emissão de moeda nacional, bem como as taxas de câmbio e as reservas de ouro. Supervisionam e controlam o setor bancário.', 'released', '["Governador do Banco de Portugal", "Governador do Banco Central", "Governadora do Banco Nacional", "Governadora do Banco de Portugal", "Gestora do Banco Central", "Gestor do Banco Central", "Governador do Banco Nacional", "Governadora do Banco Central"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/9e47c727-5718-48f1-a567-6a4c09397a21', 'Engenheiro Aerodinâmico', 'Os engenheiros aerodinâmicos realizam análises de aerodinâmica para garantir que os projetos de equipamento de transporte satisfazem os requisitos de aerodinâmica e de desempenho. Contribuem para a concepção de motores e componentes de motores e elaboram relatórios técnicos para o pessoal de engenharia e os clientes. Coordenam com outros departamentos de engenharia a verificação do desempenho dos desenhos como especificado. Os engenheiros aerodinâmicos realizam investigação para avaliar a adaptabilidade dos equipamentos e materiais. Além disso, analisam propostas para avaliar o tempo de produção e a viabilidade.', 'released', '["Engenheira Aerodinâmica", "Engenheiro Aerodinâmico", "Engenheira Aerodinâmico"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/9e657046-67ce-4e16-ab2e-ddb918638910', 'Formador de Tecnologia da Informação', 'Os formadores de TIC realizam análises das necessidades de formação e criam programas para formar os alunos na utilização de pacotes de software e de sistemas de informação em conformidade. Produzem e atualizam materiais de formação existentes (conteúdos e métodos), proporcionam formação eficaz em sala de aula, em linha ou informal, e acompanham, avaliam e comunicam a eficácia da formação. Mantêm e atualizam os conhecimentos especializados sobre temas de TIC e avaliam e comunicam informações sobre o desempenho dos alunos.', 'released', '["Formadora de TI", "Formador de Tecnologias da Informação", "Formador de Tecnologias de Informação e Comunicação", "Formador de TI", "Formadora de Tecnologias da Informação", "Formador de Informática", "Formadora de Informática", "Formadora de Tecnologias de Informação e Comunicação", "TI", "Formadora de Tecnologia da Informação"]'::jsonb, '2356'),
  ('http://data.europa.eu/esco/occupation/9e81adde-9983-44fa-b74b-c548d0dbfbdd', 'Gerente de Loja', 'Os gerentes de loja são responsáveis pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerentea de Loja"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/9ebaf3f0-0be0-47b7-b2b1-b3b04130fa81', 'Desenvolvedor de Jogos Digitais', 'Os programadores de jogos digitais programam, implementam e documentam jogos digitais. Aplicam normas técnicas a nível dos jogos, gráficos, som e funcionalidades.', 'released', '["Programadora de Jogos Virtuais", "Programador de Jogos Digitais", "Criador de Jogos Digitais", "Programador de Jogos Virtuais", "Criadora de Jogos Digitais", "Programadora de Jogos Digitais", "Programador de Videogames", "Programadora de Videogames", "Programador", "Desenvolvedora de Jogos Digitais"]'::jsonb, '2513'),
  ('http://data.europa.eu/esco/occupation/9efbe0de-37c0-4cc2-a1e6-a916eb4ecaa2', 'Fabricante de Papel Artesanal', 'Os fabricantes de papel artesanal criam pasta de papel, escorrem-na em peneiras e secam-na manualmente ou utilizando equipamento de pequena escala.', 'released', '["Fabricantea de Papel Artesanal"]'::jsonb, '7317'),
  ('http://data.europa.eu/esco/occupation/9f12704c-5e6c-47b0-a866-3b92663e6a4b', 'Gestor de Recursos', 'Os gestores de recursos gerem recursos para todos os projetos potenciais e atribuídos. Estabelecem a ligação com os diferentes departamentos para verificar que todos os recursos são satisfeitos, em tempo útil, e comunicam todas as questões relativas aos recursos que possam afetar os prazos previstos.', 'released', '["Diretora de Recursos", "Gestora de Recursos", "Diretor de Recursos", "Gestor de Recursos", "Coordenador de Recursos", "Coordenadora de Recursos", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/9f1d546b-1b4e-4b64-97e8-600fc502304b', 'Responsável Pela Inovação', 'Os responsáveis pela inovação são o elo de ligação entre a produção industrial e as estratégias de inovação de uma empresa. Trabalham para melhorar, através da inovação, as respostas das empresas a mudanças súbitas nos mercados, com o objetivo de prevenir e lidar com perturbações das atividades empresariais. Gerem e formam uma equipe de trabalhadores dedicada a projetos ou ideias inovadores. Supervisionam e planeiam alterações aos produtos e processos com vista a melhorar a eficiência organizacional e a tornar a empresa mais competitiva. Trabalham lado a lado com outros executivos para garantir que estes apoiam as iniciativas destinadas a promover a inovação.', 'released', NULL, '1223'),
  ('http://data.europa.eu/esco/occupation/9f508305-80ce-4111-8722-f2c9b4a44890', 'Diretor de Produtos', 'Define a estratégia, a visão e o roadmap de produtos como product manager (gerente de produto), priorizando necessidades de clientes, oportunidades de mercado e objetivos de negócio. Lidera o ciclo de vida do produto, da descoberta e validação ao lançamento e evolução, coordenando equipes multifuncionais de produto, design, engenharia, marketing e vendas. Acompanha indicadores de adoção, receita, retenção e satisfação para orientar decisões e promover inovação contínua.', 'released', '["Diretor de Produtos", "Diretora de Produtos", "Diretor de Produto", "Gerente de Produto", "Gerente de Produtos", "Product Manager", "Product Owner", "Head de Produto", "Líder de Produto", "Diretor de Desenvolvimento de Novos Produtos", "Diretor de Produtos Comerciais", "Gerente de Ciclo de Vida de Produto"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/9f686e81-c236-42cb-b848-1918eb36e16a', 'Atador de Folhas', 'Os atadores de folhas de tabaco atam manualmente folhas em molhos para transformação. Selecionam manualmente as folhas soltas e unem-nas pelas extremidades. Enrolam as folhas atando-as à volta das extremidades.', 'released', '["Técnica de Preparação das Folhas de Tabaco", "Atador de Folhas de Tabaco", "Técnico de Preparação das Folhas de Tabaco", "Atadora de Folhas de Tabaco", "Atadora de Folhas"]'::jsonb, '7516'),
  ('http://data.europa.eu/esco/occupation/9faaae26-804d-48f3-97b0-84f7e1aceae8', 'Diretor de Importação e Exportação de Bebidas', 'Os diretores de importação e exportação de bebidas implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Bebidas", "Diretor de Vendas de Bebidas", "Diretor de Importação e Exportação de Bebidas", "Diretora de Vendas de Bebidas"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/9fcce643-276b-435f-aa94-4516c2414686', 'Diretor de Distribuição Sucata e Desmantelamento', 'Os diretores de distribuição sucata e desmantelamento planificam a distribuição de produtos a diversos pontos de venda.', 'released', '["Diretora de Distribuição Sucata e Desmantelamento", "Diretor de Logística Sucata e Desmantelamento", "Diretora de Logística Sucata e Desmantelamento", "Diretor de Distribuição Sucata e Desmantelamento"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/a001cf0d-b0eb-420a-a110-9408448ba8b8', 'Operador de Máquinas Separadoras de Pedra', 'Os operadores de máquinas separadoras de pedra procedem à operação e manutenção de máquinas que separam pedra. Manipulam a pedra em diferentes formas, tais como blocos, pedras de calçada, ladrilhos e produtos de betão.', 'released', '["Operadora de Máquinas Separadoras de Pedra", "Operador de Máquinas Separadoras de Pedra"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/a005f8a2-2d8a-433e-8d89-13575f822fd4', 'Gestor Local de Energia', 'Os gestores locais de energia coordenam o consumo de energia numa organização e visam a aplicação de políticas destinadas a uma maior sustentabilidade e a minimização dos custos e do impacto ambiental. Monitorizam as necessidades e utilização energéticas e desenvolvem estratégias de melhoria, realizando investigação sobre as fontes de energia mais vantajosas para as necessidades da organização.', 'released', '["Gestora Municipal de Energia", "Gestora Local de Energia", "Engenheiro de Energia", "Engenheira de Energia", "Gestor Municipal de Energia", "Gestor Local de Energia", "Gerente"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/a02a1117-212f-4a49-b21a-d3b971e00e48', 'Pizzaiolo', 'Os pizzaiolos são responsáveis pela preparação e confeção de pizas.', 'released', '["Cozinheiro de Pizzas", "Pizzaiolo", "Pizzaiola", "Cozinheira de Pizzas", "Chefe de Pizzaria"]'::jsonb, '9411'),
  ('http://data.europa.eu/esco/occupation/a04eedcf-8424-475a-8dc5-f30a9da4b151', 'Investigador de Fraude Financeira', 'Os investigadores de fraude financeira realizam inquéritos antifraude, incluindo irregularidades de demonstrações financeiras, fraude de valores mobiliários e detecção de abusos de mercado. Gerem avaliações de risco de fraude e elaboram relatórios forenses, incluindo a análise e a verificação de elementos de prova. Os investigadores de fraude financeira mantêm ligações com as entidades reguladoras.', 'released', '["Investigadora de Fraude Financeira", "Investigador de Fraude Financeira", "Investigadora de Fraude", "Investigador de Fraude"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/a05d0a6d-7b60-445a-8dcb-282c7d5a6852', 'Comandante de Corpo de Bombeiros', 'O comandantes de corpo de bombeiros supervisionam um serviço de bombeiros. Coordenam as operações do serviço e supervisionam e lideram o pessoal de combate a incêndios e salvamento durante o combate a incêndios e as atividades de salvamento, a fim de garantir a segurança do pessoal e a limitação dos riscos. Desempenham funções administrativas para assegurar a manutenção de registos e aplicam políticas destinadas a melhorar as operações do departamento.', 'released', '["Chefe de Bombeiros", "Chefe de Corpo de Bombeiros", "Comandantea de Corpo de Bombeiros"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/a0872ef2-ecf2-476d-8390-3e81ae45a411', 'Comerciante Grossista de Eletrodomésticos', 'Os comerciantes grossistas de eletrodomésticos investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Eletrodomésticos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/a092cb70-f3e3-4224-98a3-b97c0114de77', 'Inspetor de Saúde Ambiental', 'Os inspetores de saúde ambiental realizam investigações para garantir o cumprimento da legislação em matéria de ambiente e saúde pública em determinadas zonas, organizações e empresas. Avaliam as queixas ambientais, apresentam relatórios sobre as suas conclusões e trabalham no sentido de prevenir riscos futuros ou o incumprimento das políticas em vigor. Os inspetores de saúde ambiental realizam consultas para promover a saúde e a segurança públicas.', 'released', '["Inspetora de Saúde Ambiental", "Inspetor de Saúde Ambiental"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/a0ebd342-8f89-4947-893d-fee9468cf001', 'Designer de Pirotecnia', 'Os designers de pirotecnia desenvolvem um conceito de concepção pirotécnica para um espetáculo e supervisionam a sua execução. O seu trabalho baseia-se na investigação e na visão artística. O seu desenho é influenciado por, e influencia, outros desenhos e deve estar em conformidade com estes desenhos e com a visão artística global. Por conseguinte, os designers de pirotecnia trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Durante os ensaios e o espetáculo orientam os operadores a fim de obter uma sincronização e uma manipulação ideais. Os designers de pirotecnia elaboram planos, listas de orientação e outros documentos para apoiar os operadores e a equipe de produção. Por vezes, os criadores de pirotecnia também trabalham como artistas independentes, criando arte pirotécnica fora de um contexto de espetáculo.', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/a0f9903e-2ba5-4b9d-bb0a-a8646db15221', 'Operador de Máquinas Extrusoras', 'Os operadores de máquinas extrusoras procedem à instalação, controlo e manutenção de máquinas que aquecem ou derretem matérias-primas e puxam ou empurram o material aquecido através de um molde para o enformar num perfil contínuo com uma secção transversal predefinida, tais como tubos e folhas. Também podem proceder à limpeza e manutenção do equipamento.', 'released', '["Operadora de Máquinas Extrusoras", "Operador de Máquinas Extrusoras"]'::jsonb, '8121'),
  ('http://data.europa.eu/esco/occupation/a10222e7-1940-4ca3-86c1-99b115535969', 'Vendedor de Equipamento Áudio e Vídeo', 'Os vendedores de equipamento áudio e vídeo vendem equipamento áudio e vídeo, tais como rádios e televisões, leitores e gravadores de CD, DVD, etc., em lojas especializadas.', 'released', '["Vendedor de Equipamento Áudio e Vídeo", "Vendedora de Equipamento Áudio e Vídeo"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/a10849c1-f0d8-4600-bca6-9549c2517650', 'Professor de Educação Física do Ensino Secundário', 'Os professores de Educação Física do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Educação Física. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Educação Física através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Educação Física do Ensino Secundário", "Professor de Educação Física do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/a10eb17a-3c78-4f7a-a1da-8f31146339d3', 'Auxiliar de Jardineiro', 'Os auxiliares de jardineiro desempenham tarefas simples de cultivo e manutenção de flores, árvores e arbustos. Este trabalho pode ter lugar em parques ou jardins privados.', 'released', NULL, '9214'),
  ('http://data.europa.eu/esco/occupation/a1273779-d2d4-4708-a406-62f7cdd26aab', 'Engenheiro de Segurança e Higiene Ocupacionais', 'Os engenheiros de segurança e higiene ocupacionais concebem objetos e programas combinando os princípios da engenharia com os requisitos de saúde e segurança. Visam a proteção e o bem-estar das pessoas que utilizam os objetos concebidos ou realizam trabalhos no âmbito dos programas de saúde e segurança concebidos. Avaliam as instalações e os riscos que podem representar (por exemplo, materiais contaminantes, ergonomia, manuseamento de substâncias perigosas, etc.), a fim de conceber e melhorar as medidas de saúde e segurança.', 'released', '["Engenheira de Segurança e Higiene Ocupacionais", "Engenheira de Saúde e Segurança", "Engenheiro de Saúde e Segurança", "Engenheiro de Segurança e Higiene Ocupacionais"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/a142a645-6e9e-4d86-accd-9816df857c90', 'Designer de Marroquinaria', 'Os designers de marroquinaria são responsáveis pelo processo criativo de produtos de couro. Realizam análises das tendências da moda, acompanham as pesquisas de mercado e preveem necessidades, planificam e desenvolvem coleções, criam conceitos e criam coleções. Além disso, realizam amostragem, criam protótipos ou amostras para apresentação e promovem conceitos e coleções. Durante a fase de desenvolvimento da coleção, definem o estilo e o conceito, as paletes de cor, os materiais, os desenhos e os esboços. Os designers de marroquinaria identificam a gama de materiais e componentes e definem as especificações de concepção. Colaboram com a equipe técnica.', 'released', NULL, '2163'),
  ('http://data.europa.eu/esco/occupation/a14e96a7-6c4d-4d69-8c6f-7ccadf77bac5', 'Gestor de Formação e Desenvolvimento de Recursos Humanos', 'Os gestores de formação e desenvolvimento de recursos humanos coordenam todas as atividades de formação e os programas de desenvolvimento de uma empresa. Concebem e desenvolvem igualmente novos módulos de formação e supervisionam todas as atividades relacionadas com o planejamento e a execução destes programas.', 'released', '["Gestor de Formação e Desenvolvimento de Recursos Humanos", "Gestora de Formação e Desenvolvimento de Recursos Humanos", "Gerente", "RH"]'::jsonb, '1212'),
  ('http://data.europa.eu/esco/occupation/a198de8c-24b1-4002-982f-a57ae6d6c19c', 'Corretor de Seguros', 'Os corretores de seguros promovem, vendem e prestam aconselhamento sobre várias apólices de seguros, como as referentes a seguros de vida, seguros de saúde, seguros de acidentes e seguros contra incêndios, a particulares e organizações. Trabalham também como intermediários entre indivíduos ou organizações e companhias de seguros, e negoceiam as melhores apólices de seguros para os seus clientes, com as coberturas adequadas a cada situação. Os corretores de seguros estabelecem contato com novos potenciais clientes, fornecem-lhes cotações de apólices passíveis de atender às suas necessidades, prestam-lhes assistência na assinatura de novos contratos de seguros e propõem soluções específicas para os seus problemas específicos.', 'released', '["Corretora de Seguros", "Corretor de Seguros"]'::jsonb, '3321'),
  ('http://data.europa.eu/esco/occupation/a1acd539-c359-4af3-8a4a-07f1b611e368', 'Trabalhador Agrícola do Setor da Avicultura', 'Os trabalhadores agrícolas do setor da avicultura são especialistas que trabalham nas explorações de avícolas para capturar as aves de capoeira.', 'released', '["Trabalhadora de Exploração Avícola", "Trabalhadora Avícola", "Trabalhadora Agrícola do Setor da Avicultura", "Trabalhador Avícola", "Trabalhador Agrícola do Setor da Avicultura", "Trabalhador de Exploração Avícola"]'::jsonb, '9212'),
  ('http://data.europa.eu/esco/occupation/a1b32703-a2e5-4e0a-910f-7cdd0293b52d', 'Animador Especializado em Atividades ao Ar Livre', 'Os animadores especializados em atividades ao ar livre planeiam, organizam e realizam atividades ao ar livre de forma segura. Podem também ajudar um ou mais animadores assistentes de atividades ao ar livre, lidar com aspetos administrativos e assumir funções de atendimento ao cliente e tarefas relacionadas com a manutenção das instalações e do equipamento. Trabalham com clientes particularmente exigentes, quer em termos das suas necessidades, aptidões ou deficiências específicas, quer do elevado nível de habilidade requerido e do trabalho em condições ou ambientes perigosos. ;', 'released', '["Animadora Especializada em Atividades ao Ar Livre", "Animador Especializada em Atividades ao Ar Livre", "Animadora Especializado em Atividades ao Ar Livre"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/a1b4eb5e-45d4-441b-a7e8-795ac5cf6fbf', 'Fabricante de Tabuletas e Sinalética', 'Os fabricantes de tabuletas e sinalética elaboram e desenvolvem sinais para uma grande variedade de utilizações, tais como folhetos, sinais de trânsito, painéis publicitários e sinais comerciais. Utilizam diferentes materiais e técnicas e, se necessário, instalam o sinal no local. Também realizam operações de manutenção e reparação.', 'released', '["Fabricantea de Tabuletas e Sinalética"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/a1b86a8b-ad91-4192-b386-bbf89bb11699', 'Recepcionista de Restaurante', 'Os rececionistas de restaurante acolhem os clientes num estabelecimento de hotelaria e restauração e prestam os serviços iniciais.', 'released', '["Chefe de Sala"]'::jsonb, '5131'),
  ('http://data.europa.eu/esco/occupation/a1ba7574-cc28-446c-9741-12d7fbb325cb', 'Especialista em Política de Emprego', 'Os especialistas em política de emprego investigam, analisam e desenvolvem políticas relativas ao mercado de trabalho. Aplicam políticas que abrangem desde políticas financeiras a políticas de caráter prático, como a melhoria dos mecanismos de procura de emprego, a promoção da formação profissional, a concessão de incentivos a empresas em fase de arranque e o apoio ao rendimento. Os especialistas em política de emprego trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/a1c9f8b7-c4ce-4b15-ac3c-3378c300d8f2', 'Operador de Fresadora', 'Os operadores de fresadora instalam, programam e controlam fresadoras, concebidas para cortar material em excesso de peças metálicas, utilizando uma fresa de corte rotativo controlado por computador. Interpretam os esquemas das fresadoras e as instruções das ferramentas, realizam operações regulares de manutenção das máquinas e efetuam ajustes aos comandos de fresagem, tais como a profundidade dos cortes ou a velocidade de rotação.', 'released', '["Operador de Fresadora", "Operadora de Fresadora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/a1ccbfc4-3afd-4408-8e5a-41832cdef511', 'Comerciante Grossista de Têxteis, Produtos Têxteis Semiacabados e Matérias-Primas Têxteis', 'Os comerciantes grossistas de têxteis, produtos têxteis semiacabados e matérias-primas têxteis investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Têxteis, Produtos Têxteis Semiacabados e Matérias-Primas Têxteis"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/a1cf1406-3632-494c-bff3-0bd5d5327d8f', 'Entrevistador de Inquéritos', 'Os entrevistadores de inquéritos realizam entrevistas e preenchem formulários a fim de recolher os dados fornecidos pelos entrevistados. Podem recolher informações por telefone, correio, visitas pessoais ou na rua. Conduzem e ajudam os entrevistados a administrar as informações que o entrevistador está interessado em ter, normalmente, relacionadas com a informação demográfica para fins estatísticos governamentais.', 'released', '["Entrevistador de Sondagens de Opinião", "Entrevistadora de Inquéritos", "Entrevistadora de Sondagens de Opinião", "Entrevistador de Inquéritos"]'::jsonb, '4227'),
  ('http://data.europa.eu/esco/occupation/a1d0eb6b-20ac-4a2c-a7c1-9b016ea92b24', 'Vidente', 'Os videntes alegam prever acontecimentos futuros sobre a vida de uma pessoa e fornecem aos clientes a sua interpretação. Utilizam frequentemente várias técnicas, tais como a leitura de cartas, a leitura das mãos ou a leitura de folhas. ;', 'released', '["Advinhador", "Advinhadora", "Videntea"]'::jsonb, '5161'),
  ('http://data.europa.eu/esco/occupation/a1da839e-9b70-4032-bb83-820790e77003', 'Representante de Serviço de Aluguel de Veículos Pesados', 'Os representantes de serviço de aluguer de veículos pesados são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Veículos Pesados"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/a1e1a788-2352-4172-8fcf-1f985a6968b0', 'Esteticista', 'As esteticistas oferecem tratamentos da pele. Aplicam vários tratamentos faciais em função das necessidades dos clientes e do tipo de pele, tais como loções, esfoliações, peelings e máscaras, a fim de manter a pele saudável e atrativa. As esteticistas podem também fazer massagens ao pescoço e tratamentos corporais, tais como envolvimentos. As esteticistas removem o pelo indesejado em diferentes partes do corpo, como sobrancelhas, buço ou zona do biquíni. Realizam massagens faciais e aplicam maquilhagem para várias ocasiões.', 'released', '["Técnico de Cosmética", "Esteticista Cosmetologista", "Técnico de Esteticismo-Cosmetologia", "Técnica de Esteticismo", "Técnico de Esteticismo", "Técnica de Cosmética", "Técnica de Esteticismo-Cosmetologia"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/a20e4b15-a128-49b9-a06a-e790e3bd5c68', 'Escanção-Chefe', 'Os escanções-chefe gerem o pedido, a preparação e o serviço do vinho e de outras bebidas conexas num estabelecimento de hotelaria e restauração.', 'released', '["Escançã-Chefe", "Escanção-Chefe", "Escanção-Chefea"]'::jsonb, '5131'),
  ('http://data.europa.eu/esco/occupation/a241eff8-309b-43ae-8890-ac4cfbd3067c', 'Técnico de Controle de Processos Químicos', 'Os técnicos de controlo de processos químicos controlam o processo de produção de produtos químicos. Operam máquinas e sistemas, sendo responsáveis pela monitorização e manutenção dos equipamentos e dos instrumentos de controlo.', 'released', '["Técnica de Controle de Processos Químicos", "Técnico de Controle de Processos Químicos"]'::jsonb, '3133'),
  ('http://data.europa.eu/esco/occupation/a2494c65-11a8-4853-9371-c89333c33be1', 'Conselheiro de Embaixada', 'Os conselheiros de embaixada supervisionam secções específicas numa embaixada, como a economia, a defesa ou os assuntos políticos. Desempenham funções consultivas junto do embaixador e desempenham funções diplomáticas na sua secção ou especialidade. Desenvolvem políticas e métodos de execução e supervisionam o pessoal da secção da embaixada.', 'released', '["Adida Econômica", "Adida de Embaixada", "Enviada", "Funcionário de Embaixada", "Adido Econômico", "Funcionária de Embaixada", "Enviado", "Adido de Embaixada", "Conselheiro de Embaixada", "Conselheira de Embaixada"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/a256838b-0843-4ad2-a2fb-4531f94e63d8', 'Chef Privado', 'Os chefs privados cumprem as regras alimentares e de higiene na preparação de refeições para os seus empregadores. Têm em consideração as intolerâncias do empregador em relação a ingredientes específicos, ou as suas preferências, e cozinham as refeições no domicílio do empregador. Os chefs privados podem também ser convidados a organizar pequenos jantares ou outro tipo de celebrações em ocasiões especiais.', 'released', '["Chefa Privada", "Chef Privada"]'::jsonb, '3434'),
  ('http://data.europa.eu/esco/occupation/a273ec4c-96fd-48e5-9343-695a6bd08512', 'Técnico de Tear', 'Os técnicos de tear efetuam operações relacionadas com a instalação de processos de tecelagem.', 'released', '["Técnica de Tear", "Técnico de Tecelagem", "Técnica de Tecelagem", "Técnico de Tear"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/a28dff76-74df-46ee-929f-d1fffbb63cd7', 'Gestor de Garantia da Qualidade em Tecnologia da Informação', 'Os gestores de garantia da qualidade em tecnologia da informação estabelecem e executam uma abordagem de qualidade no domínio da tecnologia da informação através de sistemas de gestão da qualidade, em conformidade com as normas internas e externas e com a cultura da organização. Asseguram que os controles de gestão são corretamente aplicados, a fim de salvaguardar os ativos, a integridade dos dados e as operações. Centram-se no cumprimento de objetivos de qualidade, incluindo a manutenção da certificação externa, de acordo com normas de qualidade, e o acompanhamento das estatísticas, a fim de preverem resultados no domínio da qualidade.', 'released', '["Gestor de Garantia da Qualidade Informática", "Gestor de Garantia da Qualidade em Tecnologia da Informação", "Gestora de Garantia da Qualidade Informática", "Responsável Pela Garantia da Qualidade Informática", "Gestora de Garantia da Qualidade em Tecnologias de Informação e Comunicação", "Responsável Pela Garantia da Qualidade em Tecnologias de Informação e Comunicação", "Gestora de Garantia da Qualidade em Tecnologia da Informação", "Gestor de Garantia da Qualidade em Tecnologias de Informação e Comunicação", "Responsável Pela Garantia da Qualidade em Tecnologia da Informação", "TI", "Gerente"]'::jsonb, '2519'),
  ('http://data.europa.eu/esco/occupation/a2a126ac-d90d-4e9f-97d1-9b8dff2ff946', 'Encarregado da Instalação de Torrefação de Café', 'Os encarregados da instalação de torrefação de café concebem novos estilos de café e asseguram a qualidade das misturas e das receitas de forma pragmática. Escrevem fórmulas de mistura para orientar os trabalhadores que elaboram as misturas de café para fins comerciais.', 'released', '["Torrador de Café", "Operadora de Instalação de Torrefação de Café", "Encarregada da Instalação de Torrefação de Café", "Torradora de Café", "Operador de Instalação de Torrefação de Café", "Encarregado da Instalação de Torrefação de Café"]'::jsonb, '7515'),
  ('http://data.europa.eu/esco/occupation/a2abd144-2a36-45ea-919c-1fcc6ebc5d45', 'Colocador de Papel de Parede', 'Os colocadores de papel de parede são especializados em colocar papel de parede. Aplicam cola no papel, ou na parede no caso de papel de parede reforçado, e fixam o papel reto, bem alinhado e evitando a inclusão de bolhas de ar.', 'released', '["Colocadora de Papel de Parede", "Colocador de Papel de Parede", "Aplicadora de Papel de Parede", "Aplicador de Papel de Parede"]'::jsonb, '7131'),
  ('http://data.europa.eu/esco/occupation/a2ade835-81c2-452e-a4d8-a90348bbe378', 'Gestor de Serviços Pós-Venda', 'Os gestores de serviços pós-venda recrutam pessoal e colaboradores, exercem a liderança e seguem os indicadores-chave de desempenho (ICD) para as existências de produtos, as margens e as encomendas. Asseguram que as regras e os procedimentos de segurança são respeitados por toda a equipe. Gerem os processos relativos a reclamações e garantias.', 'released', '["Gestora de Serviços Pós-Venda", "Gestor de Serviços Pós-Venda", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/a2b81132-2147-4c8e-b250-e6290ed906ea', 'Investigador de Fraudes nos Seguros', 'Os investigadores de fraudes nos seguros combatem as atividades fraudulentas, investigando as circunstâncias de determinados pedidos de indemnização suspeitos, as atividades relacionadas com novos clientes, a compra de produtos de seguros e os cálculos de prémios. Os investigadores de fraudes nos seguros remetem pedidos de indemnização potencialmente fraudulentos para os investigadores de seguros, que realizam depois pesquisas e investigações para sustentar ou negar o caso do requerente.', 'released', '["Investigador de Fraudes nos Seguros", "Investigadora de Fraudes nos Seguros"]'::jsonb, '3315'),
  ('http://data.europa.eu/esco/occupation/a2bc52c2-9802-4929-a95c-6379d9f19204', 'Diretor de Operações de Acabamento de Peles', 'Os diretores de operações de acabamento de peles planificam e organizam o trabalho do departamento de acabamento do couro. São responsáveis pela gestão dos produtos e equipamentos químicos. Além disso, coordenam o pessoal.', 'released', '["Diretora de Operações de Acabamento de Peles", "Diretor de Operações de Acabamento de Peles"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/a2dee758-72f5-4f1c-b760-f2b8e9d81911', 'Limpador de Chaminés', 'Os limpadores de chaminés realizam atividades de limpeza de chaminés para todos os tipos de edifícios. Removem as cinzas e fuligem e realizam a manutenção regular, em conformidade com os regulamentos em matéria de saúde e segurança. Os limpadores de chaminés podem efetuar inspeções de segurança e pequenas reparações.', 'released', '["Limpa-Chaminés", "Limpador de Chaminés", "Limpadora de Chaminés"]'::jsonb, '7133'),
  ('http://data.europa.eu/esco/occupation/a2fa73d0-7e51-456f-95c6-90f126f52ab8', 'Controlador de Tráfego', 'Os controladores de tráfego asseguram a expedição segura e eficiente dos serviços ferroviários. A segurança dos passageiros é a sua principal prioridade. Quando realizam tarefas de expedição dos comboios, verificam os sinais de trânsito e comunicam prontamente aos maquinistas e condutores se o comboio pode partir em segurança.', 'released', '["Controlador de Tráfego", "Expedidor de Trens", "Controladora de Tráfego", "Expedidora de Trens"]'::jsonb, '8312'),
  ('http://data.europa.eu/esco/occupation/a2ff6cc3-15fa-4f02-a457-8fd5df7aa29e', 'Diretor de Logística Intermodal', 'Os diretores de logística intermodal gerem e supervisionam os aspetos comerciais e operacionais da logística intermodal para uma organização.', 'released', '["Diretora de Logística Intermodal", "Consultor de Transportes", "Consultora de Transportes", "Diretor de Logística Intermodal"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/a30734bb-2f10-4747-a94c-75f5ec3c63a4', 'Maqueiro', 'Os maqueiros são assistentes profissionais de cuidados de saúde que transportam pessoas em macas no hospital, bem como objetos.', 'released', '["Maqueiro", "Maqueira"]'::jsonb, '5329'),
  ('http://data.europa.eu/esco/occupation/a317e9c2-62d5-4a24-8ad4-5cb7b9db3f3b', 'Fisioterapeuta Especializado', 'Os fisioterapeutas especializados são altamente especializados. Tomam decisões complexas e gerem riscos em contextos imprevisíveis e no âmbito de uma determinada área. Podem centrar-se num domínio específico de prática clínica, educação, investigação ou gestão profissional.', 'released', '["Fisioterapeuta Especializado", "Fisioterapeuta Especializada"]'::jsonb, '2264'),
  ('http://data.europa.eu/esco/occupation/a32187fa-bc37-4fc2-8e89-296632bfc271', 'Técnico de Parque Eólico Terrestre', 'Os técnicos de parques eólicos terrestres operam e fazem a manutenção de parques eólicos terrestres, procedendo a inspeções de diagnóstico, analisando falhas e realizando trabalhos de reparação. Asseguram que as turbinas eólicas funcionam em conformidade com a regulamentação e prestam assistência aos engenheiros eólicos na construção de turbinas eólicas. Os técnicos de parques eólicos terrestres também podem testar e instalar componentes de hardware e software de turbinas eólicas.;', 'released', '["Técnica de Parque Eólico", "Técnico em Conserto de Turbinas Eólicas Onshore", "Técnico de Serviço de Turbina Eólica", "Operadora de Usina Eólica Onshore", "Técnica de Manutenção de Turbinas Eólicas Onshore", "Técnico de Manutenção de Turbinas Eólicas Onshore", "Técnica de Serviço de Turbina Eólica", "Técnico de Parque Eólico", "Operadora de Parque Eólico Onshore", "Técnica de Usina Eólica Onshore", "Operador de Parque Eólico Onshore", "Técnico de Usina Eólica Onshore", "Técnica em Conserto de Turbinas Eólicas Onshore", "Operador de Usina Eólica Onshore", "Técnica de Parque Eólico Terrestre"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/a330b100-e651-4db1-bcf0-e9cbc025c614', 'Analista de Processos Organizacionais', 'Analisa, documenta e melhora processos organizacionais, mapeando o fluxo atual, identificando gargalos, riscos e oportunidades de automação. Define indicadores de desempenho, elabora procedimentos e apoia as áreas na implantação de melhorias e na gestão de mudanças. Atua com BPM, mapeamento de processos, melhoria contínua e conformidade operacional.', 'released', '["Analista de Processos Organizacionais", "Responsável de Processos", "Analista de Processos", "Analista de Melhoria de Processos", "Especialista em BPM", "Analista de Processos de Negócio", "Analista de Processos e Qualidade", "Especialista em Melhoria Contínua"]'::jsonb, '2421'),
  ('http://data.europa.eu/esco/occupation/a330b7b6-696e-455c-b6d5-f39f82c1489f', 'Gestor de Sistemas de Recirculação em Aquicultura', 'Os gestores de sistemas de recirculação em aquicultura controlam a produção de organismos aquáticos em sistemas de recirculação em terra, gerem processos de reutilização da água e supervisionam a circulação, arejamento e os sistemas de biofiltros de complexidade.', 'released', '["Gestor de Sistemas de Recirculação em Aquacultura", "Gestora de Sistemas de Recirculação em Aquacultura", "Gestora de Sistemas de Recirculação em Aquicultura", "Gestor de Sistemas de Recirculação em Aquicultura", "Gerente"]'::jsonb, '2132'),
  ('http://data.europa.eu/esco/occupation/a36c14e6-ed96-467d-8390-6f9cf47ac350', 'Professor de História', 'Os professores de História são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a História, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da História, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de História", "Professor de História", "Professora Universitária de História", "Professor Universitário de História"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/a377fafb-7e6e-4925-bc64-8099b58aafb8', 'Engenheiro Civil Especialista em Hidráulica e Recursos Hídricos', 'Os engenheiros civis especialistas em hidráulica e recursos hídricos concebem e constroem sistemas de drenagem para esgotos e águas pluviais. Avaliam as opções de concepção de sistemas de drenagem de acordo com os requisitos, assegurando simultaneamente o cumprimento da legislação e das normas e políticas ambientais. Os engenheiros civis especialistas em hidráulica e recursos hídricos escolhem o sistema de drenagem ótimo para prevenir inundações, controlar a irrigação e encaminhar as águas residuais para longe das fontes de água.', 'released', '["Engenheira Especialista em Sistemas de Drenagem", "Engenheiro Civil Especialista em Hidráulica e Recursos Hídricos", "Engenheira Civil Especialista em Hidráulica e Recursos Hídricos", "Engenheiro Especialista em Sistemas de Drenagem"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/a3ef0728-7540-4676-ad18-cf0a7913b3ce', 'Despachante Aduaneiro', 'Os despachantes aduaneiros aprovam ou recusam a passagem de mercadorias através de barreiras alfandegárias para o comércio internacional e asseguram o cumprimento da legislação em matéria de remessas. Facilitam a comunicação entre as instituições comerciais de importação e de exportação e os funcionários governamentais e são responsáveis pelo cálculo dos impostos e pela garantia do pagamento.', 'released', '["Despachante Aduaneiro", "Despachante Aduaneira", "Despachantea Aduaneiro"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/a41acf2b-fb87-496f-aec3-7c5fdc5e9211', 'Inspetor de Resíduos Industriais', 'Os inspetores de resíduos industriais realizam controlos nas empresas para garantir que cumprem a regulamentação em matéria de resíduos e ambiente. Verificam a documentação relacionada com a gestão de resíduos, recolhem amostras para análise e observam as práticas industriais. Podem aconselhar ou tomar medidas preventivas ou corretivas para melhorar a gestão e a eliminação dos resíduos industriais.', 'released', '["Inspetor de Resíduos Industriais", "Inspetora de Resíduos Industriais"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/a424aa0f-b3f1-41fb-901f-85e05fed83ed', 'Designer Paisagístico', 'Os designers paisagísticos concebem e criam espaços públicos, atrações, estruturas, parques, jardins e jardins privados ao ar livre para obter resultados ambientais, sociais-comportamentais ou estéticos.', 'released', '["Designer Paisagístico", "Designer Paisagística", "Desenhador Paisagístico", "Designer de Paisagens", "Desenhadora Paisagística"]'::jsonb, '2162'),
  ('http://data.europa.eu/esco/occupation/a429e4fe-22c6-4cb5-89ef-ca4d5b4d0363', 'Instalador de Sistemas de Descongelamento em Aeronaves', 'Os instaladores de sistemas de descongelamento em aeronaves procedem à montagem, instalação, ensaio, a manutenção e reparação de sistemas mecânicos de descongelamento e antigelo que impedem a acumulação ou formação de gelo em aeronaves e veículos espaciais.', 'released', '["Instalador de Sistemas de Descongelamento em Aeronaves", "Instaladora de Sistemas de Descongelamento em Aeronaves"]'::jsonb, '7232'),
  ('http://data.europa.eu/esco/occupation/a44a1dc5-be08-4840-8bd5-770c4ac1ca6d', 'Técnico de Segurança Informática', 'Os técnicos de segurança informática propõem e aplicam as atualizações e medidas necessárias em matéria de segurança sempre que necessário. Aconselham, apoiam, informam e disponibilizam formação e sensibilização em matéria de segurança.', 'released', '["Técnica de Segurança das TI", "Técnico de Segurança das TI", "Técnico de Segurança Informática", "Técnica de Segurança das Tecnologias de Informação e Comunicação", "Técnico de Segurança das Tecnologias de Informação e Comunicação", "Técnica de Segurança Informática"]'::jsonb, '3512'),
  ('http://data.europa.eu/esco/occupation/a464015d-a622-44aa-a4fe-bf01e412e120', 'Inspetor de Montagem de Embarcações', 'Os inspetores de montagem de embarcações utilizam equipamento de medição e de ensaio para inspecionar e monitorizar os conjuntos de embarcações, a fim de garantir a conformidade com as especificações técnicas e as normas e regulamentos de segurança. Analisam os conjuntos para detectar anomalias e danos e verificam o trabalho de reparação. Também fornecem documentação de inspeção pormenorizada e recomendam medidas nos casos em que foram detectados problemas.', 'released', '["Inspetor de Montagem de Embarcações", "Inspetora de Montagem de Embarcações"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/a47f82d3-4cf7-4abf-bb36-2c8cbad28234', 'Jornalista', 'Os jornalistas investigam, verificam e redigem notícias para jornais, revistas, televisão e outros meios de radiodifusão. Fazem a cobertura de eventos políticos, econômicos, culturais, sociais e desportivos. Os jornalistas devem respeitar os códigos deontológicos, como a liberdade de expressão e o direito de resposta, o direito de imprensa e as normas editoriais, a fim de transmitirem informações objetivas.', 'released', '["Repórter de Rádio", "Repórter de Televisão", "Repórter"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/a4869ae9-2dfe-48cc-bd97-f803880f3407', 'Projetista', 'Os projetistas preparam e criam desenhos técnicos utilizando um software especial ou técnicas manuais para mostrar como algo é construído ou como funciona.', 'released', '["Desenhador Técnico", "Desenhadora Técnica"]'::jsonb, '3118'),
  ('http://data.europa.eu/esco/occupation/a486b6eb-207c-4aae-ad0b-397d0744b16f', 'Comerciante Grossista de Mobiliário de Escritório', 'Os comerciantes grossistas de mobiliário de escritório investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Mobiliário de Escritório"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/a48b9a5a-5ded-482d-8cda-7fd097a32c16', 'Jardineiro', 'Os jardineiros prestam serviços paisagísticos e de espaços verdes e procedem à manutenção de jardins de casas privadas, instalações comerciais e públicas, escolas, hotéis, jardins botânicos, campos de golfe, parques e campos de atletismo.', 'released', '["Jardineiro", "Técnica de Jardinagem e Espaços Verdes", "Técnico de Jardinagem e Espaços Verdes", "Jardineira", "Operador de Manutenção em Campos de Golfe (Golf Keeper)", "Operador de Jardinagem", "Operadora de Manutenção em Campos de Golfe (Golf Keeper)", "Operadora de Jardinagem"]'::jsonb, '6113'),
  ('http://data.europa.eu/esco/occupation/a491c5c1-e126-4414-9ac9-3625a4a79513', 'Guarda de Caça', 'Os guardas de caça gerem o habitat e a população de caça selvagem numa zona definida.', 'released', NULL, '5419'),
  ('http://data.europa.eu/esco/occupation/a49e1479-90c4-41d2-871b-ac58ebc4894b', 'Diretor de Distribuição de Bens de Consumo Doméstico', 'Os diretores de distribuição de bens de consumo doméstico planificam a distribuição de bens de uso doméstico a diversos pontos de venda.', 'released', '["Diretora de Distribuição de Bens de Consumo Doméstico", "Diretor de Logística — Bens de Consumo Doméstico", "Diretor de Distribuição de Bens de Consumo Doméstico", "Diretora de Logística — Bens de Consumo Doméstico"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/a4ab8347-782f-4ca1-940d-44ffea256ebf', 'Operador de Máquinas de Moldagem de Discos Óticos', 'Os operadores de máquinas de moldagem de discos óticos asseguram o correto funcionamento de máquinas de moldagem que derretem os granulados de policarbonato e injetam o plástico numa cavidade de molde. O plástico é, em seguida, arrefecido e solidifica, ostentando as marcas que podem ser lidas digitalmente.', 'released', '["Operador de Máquinas de Moldagem de Discos Óticos", "Operadora de Máquinas de Moldagem de Discos Óticos"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/a4c5fb46-1d72-47de-b349-f579a0f1edfb', 'Supervisor de Operações - Petróleo e Gás', 'Os supervisores de operações - petróleo e gás supervisionam as operações de perfuração. Gerem e coordenam os empregados que operam equipamentos de elevação e de perfuração. Organizam as atividades de trabalho correntes.', 'released', '["Supervisora de Operações - Petróleo e Gás", "Supervisor de Operações - Petróleo e Gás"]'::jsonb, '7215'),
  ('http://data.europa.eu/esco/occupation/a4dd6eae-ca75-456f-829d-333671a7c186', 'Capelão', 'Os capelões realizam atividades religiosas em instituições seculares. Prestam serviços de aconselhamento e apoio espiritual e emocional às pessoas na instituição, além de cooperarem com os padres ou outros funcionários religiosos prestando apoio a atividades religiosas na comunidade.', 'released', '["Capelã", "Capelão", "Capelãa"]'::jsonb, '2636'),
  ('http://data.europa.eu/esco/occupation/a4e96a0c-3a49-4cd3-a45c-ff081c28405d', 'Calafate', 'Os calafates colocam estopa nas fendas entre o tabuado do convés ou o casco dos navios de madeira, de modo a torná-los estanques. Utilizam principalmente ferramentas manuais para aquecer a cola marinha e introduzi-la à força nas fendas. Também podem martelar cordas de cânhamo e linhas de algodão nas fendas e esfregar alcatrão quente sobre as mesmas.', 'released', '["Calafatea"]'::jsonb, '9329'),
  ('http://data.europa.eu/esco/occupation/a504e79e-f146-4773-a1cf-2b15b9d614db', 'Motorista de Caminhões de Mudanças', 'Os motoristas de caminhões de mudanças conduzem carrinhas ou caminhões destinados a transferir e transportar artigos, bens, máquinas e outros. Prestam assistência na colocação de artigos no caminhão, tendo em conta a utilização eficiente do espaço e a conformidade em matéria de segurança.', 'released', NULL, '8332'),
  ('http://data.europa.eu/esco/occupation/a50d64e7-2dba-4418-81a7-92b2ba2e508f', 'Assentador de Pavimentos', 'Os assentadores de pavimentos criam superfícies de pavimentos. Preparam a superfície, instalando tiras para dividir as secções. Em seguida, vertem a solução que contém cimento e lascas de mármore. Os assentadores de pavimentos concluem o chão polindo a superfície, a fim de assegurar a suavidade e o brilho.', 'released', '["Assentador de Pavimentos", "Pavimentadora", "Pavimentador", "Assentadora de Pavimentos"]'::jsonb, '7114'),
  ('http://data.europa.eu/esco/occupation/a51ab2e2-aaa9-4d7d-a747-bff2e276636a', 'Operador de Fornalha', 'Os operadores de fornalha controlam o processo de tratamento térmico das peças vazadas. Controlam os fornos de tratamento e dirigem as atividades de funcionamento da fornalha, incluindo a interpretação de dados informáticos, a medição e a regulação da temperatura, bem como os recipientes de carga. Controlam o tratamento químico-térmico das peças vazadas a fim de cumprir as normas.', 'released', '["Operadora de Fornalha", "Operador de Fornalha"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/a520fba4-2a29-43a0-bfd5-43892306501d', 'Consultor de Modelação da Informação da Construção', 'Os consultores de modelação da informação da construção aconselham, orientam e avaliam os clientes nos processos empresariais de modelação da informação da construção (BIM), bem como as equipes de construção na execução de tecnologias BIM. Gerem a comunicação com o pessoal e os clientes, implementam estratégias e soluções BIM para completar os entegráveis e elaboram documentos, como fluxogramas, ordens de trabalho e guias de boas práticas.', 'released', '["Consultor de Modelação da Informação da Construção", "Consultora de Modelação da Informação da Construção"]'::jsonb, '2421'),
  ('http://data.europa.eu/esco/occupation/a5245c01-4ca8-406e-a152-620c28530ea8', 'Operador de Plaina Metálica', 'Os operadores de plaina metálica instalam e operam uma plaina, que é uma máquina metalúrgica concebida para cortar metal em excesso de uma peça metálica, utilizando um movimento linear relativo entre a ferramenta de corte da plaina e a peça para criar uma trajetória linear e cortar.', 'released', '["Operadora de Plaina Metálica", "Operador de Plaina Metálica"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/a527f263-0feb-4d55-b416-0577e9dc7847', 'Representante de Serviço de Aluguel de Bens Recreativos e Desportivos', 'Os representantes de serviço de aluguer de bens recreativos e desportivos são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Bens Recreativos e Desportivos"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/a580e79a-b752-49c1-b033-b5ab2b34bfba', 'Médico Dentista', 'Os médicos dentistas previnem, diagnosticam e tratam anomalias e doenças dos dentes, da boca, dos maxilares e dos tecidos adjacentes e são especializados em cirurgia oral ou ortodontia.', 'released', '["Dentista", "Médica Dentista", "Ortodentista", "Odontologista", "Médico Dentista", "Endontista"]'::jsonb, '2261'),
  ('http://data.europa.eu/esco/occupation/a5826284-14fb-4866-b9be-69ce69db1b71', 'Diretor de Gestão na Aquicultura', 'Os diretores de gestão na aquicultura são especializados na criação de espécies aquáticas em crescimento, especialmente na alimentação, no crescimento e nos processos de gestão das unidades populacionais.', 'released', '["Diretor de Produção na Aquicultura", "Diretora de Produção na Aquicultura", "Diretora de Gestão na Aquicultura", "Diretor de Gestão na Aquicultura"]'::jsonb, '1312'),
  ('http://data.europa.eu/esco/occupation/a59feab2-9bc9-4b25-97cf-995998164502', 'Técnico de Vídeo', 'Os técnicos de vídeo procedem à instalação, preparação, controlo e manutenção do equipamento de vídeo, a fim de fornecer uma projeção de imagem de qualidade ótima para um espetáculo ao vivo. Cooperam com a equipe de apoio de estrada para descarregar, instalar e operar equipamentos e instrumentos de vídeo.', 'released', '["Técnico de Vídeo", "Técnica de Vídeo"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/a5a4e4d6-e705-4b38-96b5-225f8ab01f2c', 'Comerciante Grossista de Canalizações e Equipamento para Aquecimento', 'Os comerciantes grossistas de canalizações e equipamento para aquecimento investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Canalizações e Equipamento para Aquecimento"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/a5dc92b4-9712-4bc5-a08a-f6efa07b855f', 'Engenheiro Projetista de Equipamento Agrícola', 'Os engenheiros projetista de equipamento agrícola aplicam conhecimentos de engenharia e ciências biológicas para resolver diversos problemas agrícolas, tais como a conservação dos solos e da água e a transformação de produtos agrícolas. Concebem estruturas agrícolas, máquinas, equipamentos e processos.', 'released', '["Engenheiro Projetista de Equipamento Agrícola", "Engenheira Especialista em Concepção de Equipamento Agrícola", "Engenheira Projetista de Equipamento Agrícola", "Engenheiro Especialista em Concepção de Equipamento Agrícola"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/a6007269-912a-4445-b792-b4d5fe016bb2', 'Host', 'Estes profissionais acolhem e informam os visitantes em aeroportos, estações ferroviárias, hotéis, feiras de exposições e eventos e/ou assistem passageiros nos meios de transporte.;', 'released', NULL, '4221'),
  ('http://data.europa.eu/esco/occupation/a603fdd9-31e7-424a-883a-e9f6bf88085a', 'Supervisor de Serralharia', 'Os supervisores de serralharia acompanham as atividades de serralharia. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisora de Serralharia", "Supervisor de Serralharia"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/a632fb74-ef49-4f4a-9777-b7df54a0f897', 'Zelador do Exterior de Edifício', 'Os zeladores do exterior de edifício eliminam a sujidade e o lixo do exterior do edifício, bem como realizam tarefas de restauro. Asseguram a conformidade dos métodos de limpeza com a regulamentação em matéria de segurança e controlam os exteriores para garantir que estão em bom estado.', 'released', '["Zelador do Exterior de Edifício", "Zeladora do Exterior de Edifício"]'::jsonb, '7133'),
  ('http://data.europa.eu/esco/occupation/a63733fa-f7ff-4733-8961-1ec4eeaab00b', 'Museólogo', 'Os museólogos realizam e/ou gerem trabalhos curatoriais, preparatórios e administrativos em museus, jardins botânicos, galerias de arte, coleções relacionadas com belas-artes, aquários ou áreas similares. Gerem coleções de materiais naturais, históricos e antropológicos com finalidade educativa, científica ou estética.;', 'released', '["Museólogo", "Museóloga"]'::jsonb, '2621'),
  ('http://data.europa.eu/esco/occupation/a645b7e5-dfa8-4cce-938f-2d6395a6b51d', 'Técnico de Produção de Artigos de Marroquinaria', 'Os técnicos de produção de artigos de marroquinaria desempenham uma vasta gama de atividades e tarefas relacionadas com o processo de produção de artigos de marroquinaria, incluindo corte, fecho e acabamento, de acordo com critérios de qualidade predefinidos, resultantes da relação direta com o cliente. Utilizam técnicas manuais apoiadas por equipamento tradicional simples para a produção de modelos exclusivos ou de encomendas muito pequenas.', 'released', '["Técnico de Acabamento da Indústria de Curtumes", "Técnica de Produção de Artigos de Marroquinaria", "Técnica de Acabamento da Indústria de Curtumes", "Técnico de Produção de Artigos de Marroquinaria"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/a6517365-211c-456d-aca4-1a0115c7b1e1', 'Arquiteto de e-Learning', 'Os arquitetos de e-learning (ou aprendizagem eletrônica) estabelecem objetivos e procedimentos para a aplicação de tecnologias de aprendizagem numa organização e para a criação de uma infraestrutura de apoio a esses objetivos e procedimentos. Analisam os programas dos cursos existentes e determinam se podem ser ministrados em linha e, se não for o caso, propõe alterações para os adaptar a um ensino em linha.;', 'released', '["Arquiteto de e-Learning", "Criadora de Conteúdos Elearning", "Criador de Conteúdos Elearning", "Arquiteta de e-Learning", "Criador de Conteúdos e-Learning", "Criadora de Conteúdos e-Learning"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/a655aff1-e5e9-4c64-bc85-b902568a3dfb', 'Artista', 'Os artistas criam atuações que podem consistir em qualquer tipo de situação que abranja quatro elementos básicos: o tempo, o espaço, o corpo do artista ou a sua presença num meio e a relação entre o artista e o público ou os espetadores. A atuação pode ter um guião ou ser espontânea, com ou sem a participação do público. A atuação pode ser ao vivo ou difundida através dos meios de comunicação social. Este tipo de atuação pode acontecer em qualquer local, em qualquer espaço ou cenário e pode ter durações variáveis.', 'released', NULL, '2659'),
  ('http://data.europa.eu/esco/occupation/a659968d-0804-4357-bc60-735e4d41e65c', 'Supervisor de Produção de Calçado', 'Os supervisores de produção de calçado acompanham e coordenam as atividades de produção diárias de uma instalação de fabrico de calçado. Supervisionam o controlo de qualidade, assegurando que o produto final está em conformidade com as especificações de produção, e gerem o pessoal do setor de produção de calçado. O trabalho também envolve negociações com os fornecedores, bem como o acompanhamento do plano de produção e dos custos de produção.', 'released', '["Supervisora de Produção de Calçado", "Supervisor de Produção de Calçado"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/a67721a6-a95d-4c3b-a48c-f9920941ecd1', 'Operador de Máquina para Endireitar', 'Os operadores de máquina para endireitar instalam e cuidam das máquinas para endireitar concebidas para formar as peças metálicas na forma desejada, utilizando práticas de prensagem. Ajustam o ângulo e a altura dos rolos para endireitar e selecionam os parâmetros para a força de pressão necessária para endireitar a peça, tendo em conta a resistência e a dimensão do produto, sem um endurecimento do trabalho em excesso.', 'released', '["Operadora de Máquina para Endireitar", "Operador de Máquina para Endireitar"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/a6a0b60f-08da-4faa-bf54-942987efb471', 'Analista de Sistemas Informáticos', 'Os analistas de sistemas informáticos especificam as necessidades dos sistemas a fim de satisfazerem os requisitos dos usuários finais. Analisam as funções do sistema a fim de definirem os seus objetivos ou finalidades e de descobrirem as operações e procedimentos que permitem executá-las de forma mais eficiente. Além disso, concebem novas soluções informáticas para aumentar a eficiência e a produtividade das empresas, produzem esquemas e calculam os custos de novos sistemas, especificam as operações que o sistema irá executar e a forma como os dados serão visualizados pelo usuário final. Apresentam o projeto aos usuários e trabalham em estreita colaboração com os mesmos na implementação da solução.', 'released', '["Analista de Sistemas", "Analista de Sistemas Informáticos", "Analista de Sistemas de Tecnologias de Informação e Comunicação", "Analista de Sistemas de Tecnologia da Informação"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/a6af318e-8a3a-4266-a1ef-cf7afe588201', 'Produtor de Lúpulo', 'Os produtores de lúpulo plantam, cultivam e colhem lúpulo para a produção de produtos como a cerveja.', 'released', '["Produtor de Lúpulo", "Produtora de Lúpulo"]'::jsonb, '6112'),
  ('http://data.europa.eu/esco/occupation/a6e8a6bf-9209-4d19-a131-a8b6431e0f75', 'Gestor de Aquisição de Talentos', 'Os gestores de aquisição de talentos planeiam, desenvolvem, gerem e supervisionam os processos de aquisição e recrutamento de talentos. Entrevistam os candidatos, verificam as suas referências e gerem os anúncios nos sítios em linha de ofertas de emprego.', 'released', '["Gestor de Aquisição de Talentos", "Gestora de Aquisição de Talentos", "Gerente"]'::jsonb, '1212'),
  ('http://data.europa.eu/esco/occupation/a70315e3-ae41-44a9-9fe5-7fe668469ee0', 'Diretor de Importação e Exportação de Mobiliário e Artigos de Decoração', 'Os diretores de importação e exportação de mobiliário e artigos de decoração implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Mobiliário e Artigos de Decoração", "Diretora de Vendas de Mobiliário e Artigos de Decoração", "Diretor de Importação e Exportação de Mobiliário e Artigos de Decoração", "Diretor de Vendas de Mobiliário e Artigos de Decoração"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/a7198837-139d-49c7-8fd0-eb8d8c1ee844', 'Osteopata', 'Os osteopatas tratam distúrbios do sistema musculoesquelético em doentes com problemas físicos, como dores nas costas, dores nas articulações e distúrbios digestivos. Recorrem principalmente à manipulação dos tecidos do corpo e a técnicas de toque, alongamento e massagem para aliviar a dor dos doentes e promover um estilo de vida saudável.', 'released', NULL, '2269'),
  ('http://data.europa.eu/esco/occupation/a7358961-46d4-4715-ac1e-6148fd042510', 'Ambientalista', 'Os ambientalistas procuram soluções tecnológicas para resolver os problemas ambientais. Detectam e analisam problemas ambientais e desenvolvem novos processos de produção tecnológica para combater esses problemas. Investigam o efeito das suas inovações tecnológicas e apresentam as suas conclusões em relatórios científicos.', 'released', '["Especialista Ambiental", "Especialista na Proteção do Ambiente"]'::jsonb, '2143'),
  ('http://data.europa.eu/esco/occupation/a74f6c51-37e5-423e-aa5b-044e98663027', 'Gestor de Conteúdos Web', 'Os gestores de conteúdos Web organizam ou criam conteúdos para uma plataforma Web, de acordo com os objetivos estratégicos a longo prazo, as políticas e os procedimentos para os conteúdos em linha de uma organização ou para os seus clientes. Controlam e monitoram a conformidade com as normas, a legislação e a regulamentação em matéria de privacidade e asseguram a otimização da Web. São igualmente responsáveis pela integração do trabalho dos escritores e dos designers, a fim de produzirem uma configuração final compatível com as normas empresariais.', 'released', '["Redatora de Conteúdos Web", "Administradora de Conteúdos Web", "Redator de Conteúdos Web", "Especialista em Conteúdos Web", "Administrador de Conteúdos Web", "Especialista em Conteúdos Digitais", "Gerente", "Gestora de Conteúdos Web"]'::jsonb, '2513'),
  ('http://data.europa.eu/esco/occupation/a7594892-ff23-4e2a-aedf-2f967ebca15c', 'Diretor de Vendas', 'Os diretores de vendas desenvolvem estratégias de venda e de orientação para as empresas. Gerem equipes de vendas, afetam os recursos de vendas com base nos planos, dão prioridade e acompanham as críticas, desenvolvem e ajustam áreas de vendas ao longo do tempo e mantêm uma plataforma de vendas para acompanhar todos os avanços e vendas.', 'released', '["Diretor de Vendas", "Diretora de Marketing", "Diretor de Vendas e Comércio Internacional", "Diretora de Vendas", "Diretora de Vendas e Comércio Internacional", "Diretor de Marketing", "Sales"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/a75c740c-d8d9-41a7-ab1a-e69a6eb6eac1', 'Engenheiro de Combustíveis Alternativos', 'Os engenheiros de combustíveis alternativos concebem e desenvolvem sistemas, componentes, motores e equipamentos que substituem a utilização de combustíveis fósseis convencionais como principal fonte de energia para a propulsão e a produção de eletricidade, com a característica de utilizar energias renováveis e combustíveis não fósseis. Procuram otimizar a produção de energia a partir de fontes renováveis e reduzir as despesas de produção e a pressão no ambiente. Os combustíveis alternativos utilizados incluem principalmente o gás natural liquefeito (GNL), o gás de petróleo liquefeito (GPL), o biodiesel, o bioálcool e a eletricidade (ou seja, baterias e pilhas de combustível), o hidrogénio e os combustíveis produzidos a partir da biomassa.;', 'released', '["Engenheira de Célula de Combustível", "Engenheiro de Hidrogênio", "Engenheiro de Célula de Combustível", "Engenheira de Hidrogênio", "Engenheira de Combustíveis Alternativos"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/a76a05bb-e04d-4be8-953e-1ffd691dd58d', 'Assistente Social Especialista em Saúde Mental', 'Os assistentes sociais especialistas em saúde mental prestam assistência e aconselhamento a pessoas com problemas mentais, emocionais ou de abuso de substâncias. Centram-se na prestação de apoio personalizado a cada caso e no acompanhamento do processo de recuperação dos seus utentes, através de terapia, de intervenção em situações de crise, da defesa e da educação dos utentes. Os assistentes sociais especialistas em saúde mental podem contribuir para a melhoria dos serviços de saúde mental e para resultados positivos em matéria de saúde mental dos cidadãos.', 'released', '["Assistente Social da Psiquiatria", "Assistentea Social Especialista em Saúde Mental"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/a77bc925-c441-42f2-92d4-666b103fc025', 'Fabricante de Paletes', 'Os fabricantes de paletes de madeira criam paletes de madeira para utilização em armazenagem, expedição e manipulação de mercadorias. Os fabricantes de paletes utilizam uma máquina que utiliza, geralmente, pranchas de madeira de baixa qualidade tratadas com calor ou produtos químicos e as prega em conjunto. O material e a forma das paletes, os métodos de tratamento e a quantidade e o modelo dos pregos utilizados são altamente normalizados para possibilitar a troca de paletes usadas.', 'released', '["Fabricantea de Paletes"]'::jsonb, '7523'),
  ('http://data.europa.eu/esco/occupation/a784b063-89cf-441b-9624-deed9dbdeae6', 'Pintor de Meios de Transporte', 'Os pintores de meios de transporte utilizam máquinas de pintura e ferramentas manuais para revestir as peças individuais e pintar a superfície de todo o tipo de equipamento de transporte, tais como automóveis, ônibus, barcos, aeronaves, motociclos e veículos ferroviários. Preparam a superfície das peças para a pintura e aplicam a demão. Os pintores de meios de transporte podem realizar pintura industrial ou personalizada. Também podem remover ou reparar erros de pintura, tais como riscos. ;', 'released', '["Pintor de Meios de Transporte", "Pintora de Meios de Transporte"]'::jsonb, '7132'),
  ('http://data.europa.eu/esco/occupation/a78d8e2b-fe31-447f-8694-38ed7198d143', 'Taxidermista', 'Os taxidermistas montam e reproduzem animais mortos ou partes de animais mortos, tais como cabeças troféu, para fins de exposição pública e ensino, tais como num museu ou monumento, ou para outras fontes de estudo científico, ou para uma coleção privada.', 'released', NULL, '3433'),
  ('http://data.europa.eu/esco/occupation/a79170ad-0b7b-4697-864f-1748359aa10a', 'Gestor de Produtos Informáticos', 'Os gestores de produtos informáticos analisam e definem o estado atual e o estado ideal dos produtos, serviços ou soluções de TIC. Estimam a relação custo-eficácia, os pontos de risco, as oportunidades, os pontos fortes e os pontos fracos dos produtos ou serviços fornecidos. Os gestores de produtos informáticos criam planos estruturados e estabelecem prazos e metas, assegurando a otimização das atividades e dos recursos.', 'released', '["Gestora de Produtos de Tecnologias da Informação", "Gestora de Produtos de TI", "Gestor de Produtos de TI", "Gestor de Produtos Informáticos", "Gestora de Produtos de Tecnologias de Informação e Comunicação", "Gestor de Produtos de Tecnologias de Informação e Comunicação", "Gestor de Produtos de Tecnologias da Informação", "Gestora de Produtos Informáticos", "Gerente"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/a79d9e58-36be-4e67-a4db-ea6c8ff445fc', 'Diretor de Departamento de Retalho', 'Os diretores de departamento de retalho são responsáveis pelas atividades e pelo pessoal de uma secção numa loja.', 'released', '["Chefe de Departamento de Grande Armazém", "Chefe de Secção", "Diretora de Departamento de Retalho", "Diretor de Departamento de Retalho"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/a79e7622-2307-44e2-94cc-d1ff1caf655a', 'Diretor de Programas de Juventude', 'Os diretores de programas de juventude desenvolvem e implementam programas e políticas para melhorar e assegurar o bem-estar dos jovens. Facilitam a comunicação com e entre instituições de ensino, recreação, aconselhamento e outras instituições ligadas à juventude, organizam eventos para jovens e famílias e promovem a mobilidade e a sensibilização.', 'released', '["Diretora do Programa", "Diretor do Programa para Jovens", "Diretor do Programa", "Diretor de Programas de Juventude", "Diretora de Programas de Juventude", "Diretora do Programa para Jovens"]'::jsonb, '1344'),
  ('http://data.europa.eu/esco/occupation/a7a74a05-3dd0-46c6-99af-92df8042520c', 'Microbiologista', 'Os microbiologistas estudam e investigam as formas, as características e os processos de vida de organismos microscópicos. Estudam microrganismos como bactérias, protozoários, fungos, etc., a fim de diagnosticar e neutralizar os efeitos que esses microrganismos podem ter nos animais, no ambiente, na indústria alimentar ou no setor da saúde.;', 'released', '["Microbióloga", "Bacterologista", "Microbiólogo", "Virulogista", "Histologista", "Parasitologista"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/a7c1431b-a27c-4ab5-ace2-3f8753b481da', 'Montador de Equipamentos Fotográficos', 'Os montadores de equipamentos fotográficos constroem produtos fotográficos, tais como máquinas fotográficas, câmaras de filmar, projetores. Recolhem os diferentes componentes óticos, eletrônicos e mecânicos, tais como a bateria, os espelhos, o processador de imagem e as lentes e montam as máquinas fotográficas, de acordo com as especificações utilizando ferramentas manuais ou máquinas.', 'released', '["Montador de Equipamentos Fotográficos", "Montadora de Equipamentos Fotográficos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/a7c1d23d-aeca-4bee-9a08-5993ed98b135', 'Desenvolvedor de Sistemas', 'Os programadores de sistemas informáticos executam funções de manutenção, verificação e melhoria de sistemas de apoio à organização. Utilizam tecnologias existentes ou novas para satisfazer necessidades específicas. Testam componentes de sistemas de hardware e de software e diagnosticam e resolvem falhas do sistema.', 'released', '["Programador de Componentes", "Programadora de Sistemas", "Engenheiro de Automação", "Programador de Sistemas Informáticos", "Programadora de Componentes", "Programador de Sistemas", "Engenheira de Automação", "Programadora de Sistemas Informáticos", "Programador", "Desenvolvedora de Sistemas"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/a7d6a377-3d3b-41cf-9301-f4a0a7ad3d96', 'Gestor de Produção Alimentar', 'Os gestores de produção alimentar supervisionam e controlam a produção e têm a responsabilidade global pelo pessoal e por questões conexas. Por conseguinte, têm um conhecimento pormenorizado dos produtos do fabrico e dos seus processos de produção. Por um lado, controlam os parâmetros dos processos e a sua influência no produto e, por outro, asseguram que o pessoal e os níveis de recrutamento são adequados.', 'released', '["Gestora de Produção Alimentar", "Planificadora de Produção Alimentar", "Planificador de Produção Alimentar", "Gestor de Produção Alimentar", "Gerente"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/a7f63810-a21a-4e7e-8aa2-6637d14ea3c1', 'Funcionário Administrativo de Tribunal', 'Os funcionários administrativos de tribunal exercem funções administrativas e de assistência ao tribunal e aos juízes. São designados para aceitar ou rejeitar pedidos de homologação informal e nomeação informal de um representante pessoal. Gerem as contas dos processos e tratam de documentos oficiais. Os funcionários administrativos de tribunal desempenham funções de assistência durante um julgamento, tais como a convocação dos processos e a identificação das partes, a manutenção das notas e o registo das ordens do juiz.', 'released', '["Funcionário Administrativa de Tribunal", "Funcionária Administrativa de Tribunal", "Funcionária Administrativo de Tribunal"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/a8c7004a-e59c-4a4d-9092-2cb4533ffe58', 'Trabalhador da Unidade de Incubação em Aquicultura', 'Os trabalhadores da unidade de incubação em aquicultura trabalham na produção de organismos aquáticos em processos de incubação em terra. Prestam assistência no processo de criação de organismos durante as fases iniciais do seu ciclo de vida e a libertação de organismos, quando necessário.', 'released', '["Trabalhador da Unidade de Incubação em Aquicultura", "Trabalhadora da Unidade de Incubação em Aquicultura"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/a8ccc522-f57d-4800-a821-2e5c910e8301', 'Técnico Especialista em Ensaios Químicos', 'Os técnicos especialistas em ensaios químicos são responsáveis pela análise rápida no local de peças de ensaio de aço recebidas das instalações de fabrico de metais para efeitos de correções atempadas da composição química do metal líquido.', 'released', '["Técnica Especialista em Ensaios Químicos", "Especialista em Metalurgia", "Consultora Química", "Técnico Especialista em Ensaios Químicos", "Consultor Químico"]'::jsonb, '2113'),
  ('http://data.europa.eu/esco/occupation/a8d05b64-f60b-4dd9-91c2-e2e63d82f2f5', 'Cônsul', 'Os cônsules representam os governos em instituições estrangeiras, como embaixadas, a fim de facilitar a cooperação econômica e política entre as duas nações. Protegem os interesses do seu país de origem e prestam assistência burocrática aos cidadãos que residem ou viajam no país de acolhimento.', 'released', '["Cônsul Honorária", "Conselheiro", "Adida", "Cônsul-Geral", "Cônsul Honorário", "Adido Cultural", "Ministro Plenipotenciário", "Adida Cultural", "Adida Militar", "Secretário", "Adido Militar", "Secretária", "Ministra Plenipotenciária", "Conselheira", "Adido"]'::jsonb, '1112'),
  ('http://data.europa.eu/esco/occupation/a9068f84-cecd-4cbb-9acb-e20c714435ec', 'Cimenteiro', 'Os cimenteiros trabalham com agentes aglutinantes, tais como o cimento e o betão. Colocam todos os moldes amovíveis e vertem cimento para os mesmos. Em seguida, executam uma ou várias ações para terminar o cimento: corte, betonilha ou nivelamento, compactação, alisamento e chanfragem para prevenir rachadelas.', 'released', '["Cimenteira", "Cimenteiro"]'::jsonb, '7114'),
  ('http://data.europa.eu/esco/occupation/a92a3e24-93f0-42b3-9ebb-d2d7d8a72cc5', 'Geofísico', 'Os geofísicos estudam as características físicas da terra e aplicam medições físicas a situações geológicas. Os geofísicos utilizam os princípios da gravidade, da sismicidade e da eletromagnética para identificar a estrutura e a composição da Terra.', 'released', '["Geocientista", "Geofísico", "Geofísica"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/a9411821-4f54-406e-ba37-4c6e5a39f9fe', 'Escriturário de Registros Notariais', 'Os escriturários de registos notariais prestam serviços para a transferência legal de títulos jurídicos e propriedades de uma parte para outra. Trocam os contratos necessários e asseguram a transferência de todas as propriedades, títulos e direitos.', 'released', '["Escriturária de Registros Notariais", "Escriturário de Registros Notariais"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/a945757e-e171-46a9-847a-13cf04f7cd27', 'Operador de Serras de Fita', 'Os operadores de serras de fita trabalham com serras industriais que têm uma lâmina flexível e contínua, que gira em torno de duas ou mais rodas. As serras de fita são mais eficazes na produção de formas irregulares.', 'released', '["Operador de Serras de Fita", "Operadora de Serras de Fita"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/a950e88b-cb5e-4a7d-8a94-3f9460b487d7', 'Engenheiro de Verificação de Conformidade', 'Os engenheiros de verificação de conformidade visam manter a maior conformidade dos sistemas com as especificações de engenharia. Podem exercer a sua atividade num conjunto variado de domínios da engenharia, incluindo sistemas mecânicos, elétricos e eletrônicos. Asseguram a conformidade da engenharia com a regulamentação, as medidas de segurança e as diretivas internas.', 'released', '["Engenheira de Verificação de Conformidade", "Engenheiro de Verificação de Conformidade"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/a98f93a6-b1df-4759-88a9-3234f334afad', 'Serigrafista', 'Os serigrafistas cuidam da prensa que pressiona tinta através de uma tela. A serigrafia industrial é frequentemente utilizada para imprimir em materiais difíceis de utilizar com outros processos, tais como superfícies de plástico rígido.', 'released', '["Operadora de Serigrafia", "Operador de Serigrafia"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/a99b38bc-6e71-4bef-b127-0f2b5e357815', 'Gestor de Resiliência Informática', 'Os gestores de resiliência informática investigam, planejam e desenvolvem modelos, políticas, métodos, técnicas e ferramentas destinadas a aumentar a cibersegurança, a resiliência e a recuperação de catástrofes informáticas de uma organização.', 'released', '["Gestora de Segurança das TI", "Gestor de Segurança das Tecnologias da Informação", "Gestora de Resiliência Informática", "Gestora de Segurança das Tecnologias de Informação e Comunicação", "Gestora de Vulnerabilidades", "Gestor de Segurança das Tecnologias de Informação e Comunicação", "Gestor de Segurança da Tecnologia da Informação", "Gestora de Segurança da Tecnologia da Informação", "Gestor de Segurança das TI", "Gestor de Resiliência Informática", "Gestor de Vulnerabilidades", "Gestora de Segurança das Tecnologias da Informação", "Gerente"]'::jsonb, '2529'),
  ('http://data.europa.eu/esco/occupation/a9a41b21-8dd4-476f-96c7-85733fa63d3b', 'Assistente Social de Apoio à Inserção de Refugiados e Migrantes', 'Os assistentes sociais de apoio à inserção de refugiados e migrantes prestam aconselhamento aos migrantes, orientando-os na tomada das medidas necessárias de integração, especificamente no que respeita a viver e trabalhar num país estrangeiro. Explicam os critérios de elegibilidade, os seus direitos e obrigações. Ajudam os migrantes na criação e manutenção das suas informações de utentes, tendo em vista o posterior encaminhamento para programas de centros de dia, de assistência social e de emprego. Os assistentes sociais de apoio à inserção de refugiados e migrantes colaboram com os empregadores e informam-nos dos serviços disponíveis para a população migrante, defendendo os utentes migrantes.', 'released', '["Assistentea Social de Apoio à Inserção de Refugiados e Migrantes"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/a9b20949-897b-481f-8642-d1f69263baff', 'Supervisor de Manutenção Industrial', 'Os supervisores de manutenção industrial organizam e supervisionam as atividades e operações de manutenção de máquinas, sistemas e equipamentos. Asseguram que as inspeções são realizadas em conformidade com as normas em matéria de saúde, de segurança e ambientais, bem como com os requisitos de produtividade e qualidade.', 'released', '["Supervisora de Manutenção Industrial", "Supervisor de Manutenção Industrial"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/a9bcc9e0-5be7-47a0-818b-acad10fe90d9', 'Técnico de Física', 'Os técnicos de física monitorizam os processos físicos e realizam testes para fins de fabrico, de ensino ou científicos. Trabalham em laboratórios, escolas ou unidades de produção, onde prestam assistência aos físicos no seu trabalho. Os técnicos de física efetuam trabalhos técnicos ou práticos e comunicam os seus resultados.', 'released', '["Técnico de Física", "Técnica de Física"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/a9c30651-ccbc-4a80-900c-7880615cdf6e', 'Designer Instrucional', 'Os designers instrucionais desenvolvem material letivo para cursos de formação utilizando tecnologia multimédia e ferramentas de criação. O seu objetivo é criar experiências pedagógicas que tornem a aquisição de conhecimentos e competências mais eficiente, eficaz e atrativa.', 'released', '["Engenheiro Pedagógico", "Designer Instrucional", "Engenheira Pedagógica"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/a9c7a04d-807a-41b5-b441-87c73c73c9c5', 'Linguista', 'Os linguistas estudam as línguas do ponto de vista científico. Dominam as línguas e conseguem interpretá-las em termos de características gramaticais, semânticas e fonéticas. Investigam a evolução das línguas e a forma como são utilizadas pelas sociedades.', 'released', '["Filólogo", "Filóloga"]'::jsonb, '2643'),
  ('http://data.europa.eu/esco/occupation/aa0fd823-2f45-41c8-a3c6-97d97885e455', 'Trabalhador em Infraestruturas Flutuantes ou Submersas de Aquicultura', 'Os trabalhadores em infraestruturas flutuantes ou submersas de aquicultura realizam atividades manuais nos processos de engorda de organismos de aquicultura cultivados em sistemas aquáticos suspensos (estruturas flutuantes ou submersas). Participam em operações de extração e na manipulação de organismos para comercialização. Os trabalhadores em infraestruturas flutuantes ou submersas de aquicultura mantêm as instalações limpas (redes, cabos de amarração, gaiolas).', 'released', '["Trabalhador em Infraestruturas Flutuantes ou Submersas de Aquicultura", "Trabalhadora em Infraestruturas Flutuantes ou Submersas de Aquicultura"]'::jsonb, '9216'),
  ('http://data.europa.eu/esco/occupation/aa3780b7-3b06-40ae-8764-293fec6819d2', 'Operador de Furadora', 'Os operadores de furadora instalam e operam furadoras concebidas para cortar materiais em excesso ou ampliar um orifício numa peça fabricada utilizando uma ferramenta de corte temperada, rotativa e multipontiaguda que insere a broca na peça axialmente.', 'released', '["Operadora de Furadora", "Operador de Furadora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/aa50ae49-1e40-4ba9-959f-22a11ff172b4', 'Técnico de Estúdio de Gravação', 'Os técnicos de estúdio de gravação procedem à operação e manutenção dos microfones e auscultadores utilizados nas cabinas de gravação dos estúdios de gravação. Operam painéis de mistura. Os técnicos de estúdio de gravação são responsáveis pela gestão de todos os requisitos de produção sonora. Aconselham cantores sobre a utilização da sua voz. Os técnicos de estúdio de gravação editam as gravações num produto acabado.', 'released', '["Técnica de Estúdio de Gravação", "Técnico de Estúdio de Gravação"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/aa8fdeff-ab03-4b99-bdba-2f7a1a5c8946', 'Especialista em Import-Export de Vestuário e Calçado', 'Os especialistas em import-export de vestuário e calçado possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Vestuário e Calçado"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/aa9c6416-6a17-4e2f-a7c4-6d47c205d480', 'Vendedor de Produtos Farmacêuticos', 'Os vendedores de produtos farmacêuticos aviam medicamentos e prestam aconselhamento.', 'released', '["Vendedora de Produtos Farmacêuticos", "Vendedor de Produtos Farmacêuticos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/aaa485d0-6787-45c0-8596-b266c0b687fd', 'Serralheiro', 'Os serralheiros instalam e reparam sistemas de fecho mecânico e eletrônico através de ferramentas especializadas. Cortam e fazem chaves duplicadas para os clientes e abrem portas bloqueadas em situações de emergência. Os serralheiros também podem prestar aconselhamento em matéria de medidas de segurança.', 'released', '["Serralheira", "Serralheiro"]'::jsonb, '7222'),
  ('http://data.europa.eu/esco/occupation/aab8009a-5759-4f52-8865-6cc657b1f099', 'Coordenador Editorial', 'Os coordenadores editoriais são responsáveis pela produção de material impresso e em linha, tais como boletins informativos, procedimentos empresariais, documentos técnicos e outras publicações destinadas a instituições e a empresas. Supervisionam as equipes de edição e asseguram que as publicações atingem o seu público-alvo.', 'released', '["Coordenador de Publicações Técnicas", "Diretora de Publicações", "Coordenador Editorial", "Coordenadora Editorial", "Coordenadora de Publicações Técnicas", "Diretor de Publicações"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/aac0c510-f238-4dbe-beeb-1d7b73f4552c', 'Auxiliar de Cemitério', 'Os auxiliares de cemitério mantêm o cemitério em bom estado. Garantem que as sepulturas estão prontas para o enterro antes dos funerais e asseguram o registo exato dos enterros. Os auxiliares de cemitério prestam aconselhamento aos diretores de serviços funerários e ao público em geral.', 'released', '["Coveira", "Coveiro"]'::jsonb, '5163'),
  ('http://data.europa.eu/esco/occupation/aac62c63-b6bf-4387-8ba3-75a487f25824', 'Operador de Turbina a Vapor', 'Os operadores de turbinas a vapor operam e efetuam a manutenção de máquinas que geram energia. Asseguram a segurança das operações e acompanham-nas com vista a detetarem problemas e reagirem a situações de emergência.', 'released', '["Operadora de Turbina a Vapor", "Operador de Turbina a Vapor"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/aacc3918-b5d3-484b-9480-5d29aa550d74', 'Gestor da Cadeia Logística', 'Os gestores da cadeia logística planificam, gerem e coordenam todas as atividades relacionadas com o aprovisionamento e a aquisição dos recursos necessários para realizar as operações de fabrico, desde a aquisição das matérias-primas até à distribuição dos produtos acabados. Os recursos podem ser matérias-primas ou produtos acabados e podem ser utilizados a nível interno ou externo. Além disso, planificam e providenciam a todas as atividades que é necessário realizar nas fábricas e ajustam as operações à evolução da procura dos produtos de uma empresa.', 'released', '["Gestora da Cadeia de Abastecimento", "Gestor da Cadeia de Abastecimento", "Gestor de Canais", "Gestora da Cadeia Logística", "Gestora de Canais", "Gestor da Cadeia Logística", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/aad7819e-d62e-41de-a594-9f2be186a6c2', 'Engenheiro de Transportes', 'Os engenheiros de transportes concebem e estabelecem as especificações técnicas para a construção e o desenvolvimento de estradas e de infraestruturas de transporte. Aplicam conceitos e conhecimentos de engenharia no desenvolvimento de modos de transporte sustentáveis e eficientes, desde estradas a canais, caminhos de ferro e aeroportos.', 'released', '["Engenheiro Civil Especialista em Construção de Aeródromos e Pontes", "Engenheira Civil Especialista em Construção de Estradas", "Engenheiro Civil Especialista em Construção de Estradas", "Engenheira de Transportes", "Engenheiro de Transportes"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/aaeb2402-2ab3-411f-9a44-8ff4dd092de6', 'Comerciante Grossista de Máquinas para a Indústria Extrativa, Construção e Engenharia Civil', 'Os comerciantes grossistas de máquinas para a indústria extrativa, construção e engenharia civil investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Máquinas para a Indústria Extrativa, Construção e Engenharia Civil"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/aaeec9a7-dc57-4485-890c-86b3eef735f9', 'Operador do Serviço de Assistência Informática', 'Os operadores do serviço de assistência informática prestam assistência técnica aos usuários de computadores, respondem a perguntas ou resolvem problemas informáticos para os clientes através do telefone ou por via eletrônica. Prestam assistência no que se refere à utilização de hardware e software informáticos.', 'released', '["Operador de Assistência Técnica Informática", "Operador do Serviço de Suporte Informático", "Operador do Serviço de Apoio Informático", "Operadora do Serviço de Assistência Informática", "Operadora de Assistência Técnica Informática", "Operadora do Serviço de Suporte Informático", "Operadora do Serviço de Apoio Informático", "Operador do Serviço de Assistência Informática"]'::jsonb, '3512'),
  ('http://data.europa.eu/esco/occupation/aaf732b5-ee19-4c82-a08f-700fb98f5ca7', 'Agente de Emissão de Passaportes', 'Os agentes de emissão de passaportes fornecem passaportes e outros documentos de viagem, tais como certificados de identidade e documentos de viagem dos refugiados. Também mantêm um registo de todos os passaportes fornecidos.', 'released', '["Agentea de Emissão de Passaportes"]'::jsonb, '3354'),
  ('http://data.europa.eu/esco/occupation/ab104661-db96-4752-8c84-97d98f6e8969', 'Supervisor de Máquinas de Tricotagem', 'Os supervisores de máquinas de tricotagem supervisionam o processo de tricotagem de um grupo de máquinas, monitorizando a qualidade dos tecidos e as condições de tricotagem. Inspecionam as máquinas de tricotar após a sua instalação, colocação em funcionamento e durante a produção, a fim de assegurar a conformidade do produto com as especificações e as normas de qualidade.;', 'released', '["Supervisor de Máquinas de Tricotagem", "Supervisora de Máquinas de Tricotagem"]'::jsonb, '8152'),
  ('http://data.europa.eu/esco/occupation/ab360abd-32e2-4e03-967d-a10758efffa7', 'Engenheiro Especialista em Mecatrônica', 'Os engenheiros especialistas em mecatrónica concebem e desenvolvem sistemas inteligentes, como dispositivos robóticos, eletrodomésticos inteligentes e aviões, através da combinação de tecnologias de engenharia mecânica, eletrônica, informática e de controlo. Criam modelos ou documentos para peças, conjuntos ou produtos acabados que utilizam programas de software e supervisionam e gerem projetos.', 'released', '["Engenheiro Especialista em Mecatrónica", "Engenheiro Mecatrónico", "Engenheira Especialista em Mecatrónica", "Engenheira Mecatrónica", "Engenheira Especialista em Mecatrônica"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/ab3c4d3e-3189-47ad-82af-57cdae3cb589', 'Engenheiro Ótico', 'Os engenheiros óticos concebem e desenvolvimento de diferentes aplicações industriais com ótica. Possuem conhecimentos sobre a luz, os princípios de transmissão da luz e a ótica com vista a elaborar especificações de engenharia para equipamentos como microscópios, lentes, telescópios e outros dispositivos óticos.', 'released', '["Engenheira Ótica", "Engenheiro Ótico", "Engenheira Ótico"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/ab4086a0-0e2f-436e-80f8-a3291e594bd1', 'Litógrafo', 'Os litógrafos fabricam e preparam placas metálicas para utilizar como original em vários processos de impressão e materiais de suporte. Geralmente, as placas são gravadas a laser a partir de fontes digitais com tecnologia de computador para placa, mas também podem ser feitas mediante a aplicação de tipos de emulsões à placa de impressão.', 'released', '["Litógrafo", "Litógrafa"]'::jsonb, '7321'),
  ('http://data.europa.eu/esco/occupation/ab4dd4f9-ee6c-41cc-8b72-42ad0b13d1e2', 'Engenheiro Especialista em Tratamento de Resíduos', 'Os engenheiros especialistas em tratamento de resíduos instalações e equipamento concebem processos, instalações e equipamento utilizados na recolha, tratamento e distribuição de resíduos. Investigam normas e políticas ambientais, a fim de otimizar os procedimentos de tratamento de resíduos e de garantir uma pressão mínima sobre o ambiente, analisando e classificando os resíduos processados.', 'released', '["Engenheira Especialista em Tratamento de Resíduos", "Engenheiro Especialista em Tratamento de Resíduos Sólidos"]'::jsonb, '2143'),
  ('http://data.europa.eu/esco/occupation/ab5a5073-453c-4a93-aff7-345a19f8b954', 'Segurador de Crédito Hipotecário', 'Os seguradores de crédito hipotecário asseguram a conformidade com as diretrizes aplicáveis aos subscritores. Participam na aplicação de novas diretrizes de subscrição. Além disso, analisam também empréstimos fechados e recusados.', 'released', '["Segurador de Crédito Hipotecário", "Seguradora de Crédito Hipotecário"]'::jsonb, '3312'),
  ('http://data.europa.eu/esco/occupation/ab762f91-d737-485f-a85c-67cab92dee01', 'Delegado de Informação Médica', 'Os delegados de informação médica promovem e vendem dispositivos e equipamentos médicos e produtos farmacêuticos aos profissionais de saúde. Fornecem informações sobre o produto e demonstram as suas características aos profissionais de saúde. Os delegados de informação médica negoceiam e celebram contratos de venda.', 'released', '["Delegada de Informação Médica", "Delegado de Informação Médica"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/ab7bccb2-6f81-4a3d-a0c0-fca5d47d2775', 'Designer Industrial', 'Os designers industriais desenvolvem ideias e desenvolvem-nas em desenhos e conceitos para uma grande variedade de produtos fabricados. Integram a criatividade, a estética, a viabilidade de produção e a relevância de mercado na concepção de novos produtos.', 'released', '["Designer CAD", "Designer Ergonómico", "Designer de Brinquedos", "Designer Ergonómica", "Designer 3D CAD", "Designer de Produto"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/ab9e06c8-e0fc-4c1b-afa2-61421592f1a5', 'Operador de Germinação', 'Os operadores de germinação cuidam de recipientes de imersão e germinação onde a cevada é germinada para produzir malte.', 'released', '["Operador de Sistema de Germinação", "Operadora de Sistema de Germinação", "Operador de Tanque de Germinação", "Operadora de Tanque de Germinação", "Operadora de Germinação"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/abab3d6a-82b9-49bd-8a4b-7bc678130558', 'Tutor Académico', 'Os tutores académicos assistem os alunos, ao nível do ensino pós-secundário, no reconhecimento e na realização dos seus objetivos educativos. Aconselham os alunos sobre a seleção dos programas escolares, comunicam-lhes os requisitos académicos e ajudam-nos no planejamento das carreiras. Os tutores académicos debatem também o desempenho académico do aluno e as suas implicações, e apresentam sugestões de melhoria, incluindo aconselhamento em matéria de estudos. Também trabalham em estreita colaboração com outros administradores e professores universitários e asseguram que estão atualizados quanto a quaisquer alterações aos regulamentos, programas ou requisitos dos estabelecimentos de ensino superior.', 'released', '["Tutora Académica", "Tutor Académico", "Tutora Académico"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/abae06d8-525f-4a2d-8bbd-67b559aad8f2', 'Controlador de Temperatura', 'Os controladores de temperatura são responsáveis pelo controlo da temperatura dos hóspedes, do pessoal ou dos visitantes que entram nas instalações de uma organização ou espaços públicos, como medida para evitar a propagação de doenças infecciosas em espaços privados e públicos.;', 'released', '["Monitor de Triagem de Temperatura", "Rastreador de Saúde", "Verificadora de Temperatura", "Peneira de Entrada", "Verificador de Temperatura", "Controladora de Temperatura"]'::jsonb, '3259'),
  ('http://data.europa.eu/esco/occupation/abc849b6-9e75-41ce-b1aa-4d488280a8a3', 'Controlador de Leite da Exploração Agrícola', 'Os controladores de leite da exploração agrícola são responsáveis por medir e analisar a produção e a qualidade do leite e prestar aconselhamento em conformidade.', 'released', '["Supervisora de Leite da Exploração Agrícola", "Especialista na Supervisão de Leite de Exploração Agrícola", "Controladora de Leite da Exploração Agrícola", "Controlador de Leite da Exploração Agrícola", "Supervisor de Leite da Exploração Agrícola"]'::jsonb, '7515'),
  ('http://data.europa.eu/esco/occupation/ac036ea7-883a-4265-96d5-c02bbe6667e1', 'Supervisor de Instalações de Aquicultura', 'Os supervisores de instalações de aquicultura supervisionam os processos de produção em operações de aquicultura em larga escala e inspecionam os locais de aquicultura, com vista a manter e melhorar o desempenho. Mantêm a saúde e a segurança no local de trabalho, elaboram planos de gestão para reduzir os riscos de pragas, predadores e doenças e supervisionam a eliminação dos resíduos biológicos e químicos e a manutenção dos equipamentos e das máquinas.', 'released', '["Supervisor de Instalações de Aquicultura", "Supervisora de Instalações de Aquicultura"]'::jsonb, '3142'),
  ('http://data.europa.eu/esco/occupation/ac160654-0d3e-49aa-b798-1861ce9d78b6', 'Torneiro de Madeiras', 'Os torneiros de madeiras utilizam um torno para remover material supérfluo da madeira. O torno gira a peça em torno do seu eixo, enquanto se utilizam ferramentas para obter a forma desejada.', 'released', '["Torneiro de Madeiras", "Torneira de Madeiras"]'::jsonb, '7523'),
  ('http://data.europa.eu/esco/occupation/ac1fc6a9-70d2-475c-8fa0-82ef83830968', 'Engenheiro Ambiental', 'Os engenheiros ambientais integram medidas ambientais e sustentáveis no desenvolvimento de projetos de natureza diversa. Procuram preservar os recursos naturais e os sítios naturais. Trabalham em conjunto com engenheiros de outros domínios para lidar com todas as implicações que os projetos possam ter, com vista a conceber formas de conservar as reservas naturais, prevenir a poluição e aplicar medidas sanitárias.', 'released', '["Engenheiro Ambiental", "Engenheira Ambiental"]'::jsonb, '2143'),
  ('http://data.europa.eu/esco/occupation/ac37627c-a999-4779-997e-9795cc4f9a3d', 'Engenheiro Especialista em Distribuição de Energia', 'Os engenheiros especialistas em distribuição de energia concebem e operam instalações que distribuem energia desde a instalação de distribuição até aos consumidores. Investigam métodos para otimizar a distribuição de energia e assegurar a satisfação das necessidades dos consumidores. Asseguram também o cumprimento da regulamentação de segurança, monitorizando os processos automatizados nas instalações e dirigindo o fluxo de trabalho.', 'released', '["Engenheira Especialista em Distribuição de Energia", "Engenheiro Especialista em Distribuição de Energia"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/ac401ec0-7ce0-423f-b8b5-167da9e046a7', 'Operador de Máquinas de Fibras', 'Os operadores de máquinas de fibras procedem à operação e manutenção de máquinas de extrusão que formam fibras a partir de filamentos. Trabalham com materiais sintéticos, tais como fibra de vidro ou polímeros líquidos, ou materiais não sintéticos, tais como o rayon.', 'released', '["Operadora de Máquinas de Extrusão", "Operador de Máquinas de Conformação", "Operador de Máquinas de Extrusão", "Operadora de Máquinas de Fibras", "Operador de Máquinas de Fibras", "Operadora de Máquinas de Conformação"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/ac60ed89-da6d-4f1a-93ee-1031789c7796', 'Escrivão de Direito', 'Os escrivães de direito digitam em processadores de texto ou noutro tipo de software cada um dos termos proferidos na sala de audiências. Fazem a transcrição das audições que se realizam em tribunal, a fim de produzirem as audições oficiais do processo judicial. Permitem que o processo seja analisado de forma mais aprofundada e precisa pelas partes.', 'released', '["Escrivã de Direito", "Escrivão de Direito", "Escrivãa de Direito"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/ac734172-ae9a-41ab-80a0-a7b33694e027', 'Montador de Filmes e Vídeos', 'Os montadores de filmes e vídeos são responsáveis pela montagem e o corte de filmagens não editadas de forma lógica e estética, quer para filmes e séries de televisão, quer para uso doméstico. Reorganizam cenas que foram filmadas e escolhem os efeitos especiais necessários. Os montadores de filmes e vídeos trabalham em estreita colaboração com editores de som e diretores musicais.', 'released', '["Montadora de Filmes e Vídeos", "Montador de Filmes e Vídeos"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/ac7c07d1-bc11-4f19-bca5-e468e9b1a53c', 'Alpinista Industrial', 'Os alpinistas industriais são trabalhadores especializados em altura que escalam de forma segura o exterior dos edifícios e das estruturas para realizar um trabalho importante.', 'released', '["Trabalhador em Altura", "Trabalhadora em Altura"]'::jsonb, '7119'),
  ('http://data.europa.eu/esco/occupation/ac80b511-fd22-4edf-8570-e531704778bd', 'Blogger', 'Os bloggers redigem artigos em linha sobre uma vasta gama de temas, como a política, a moda, a economia e o desporto. Podem relatar fatos objetivos, mas muitas vezes dão também a sua opinião sobre o tema tratado. Os bloggers também interagem com os seus leitores através de comentários.', 'released', NULL, '2642'),
  ('http://data.europa.eu/esco/occupation/ac8b3cd1-a127-4e6a-8208-5cfcf7111955', 'Estaticista', 'Os estaticistas recolhem, tabulam e, sobretudo, analisam as informações quantitativas provenientes de diversos domínios. Interpretam e analisam os estudos estatísticos em domínios como a saúde, a demografia, as finanças, as empresas, etc., e prestam aconselhamento com base em padrões e análises realizadas.', 'released', '["Analista Estatístico", "Especialista em Estatística", "Analista de Estatísticas"]'::jsonb, '2120'),
  ('http://data.europa.eu/esco/occupation/acb6b99a-6c13-482a-81b1-8b5614e0153e', 'Técnico de Palco', 'Os técnicos de palco controlam diferentes aspetos de um espetáculo com base no conceito artístico ou criativo, em interação com os artistas. Preparam e executam a instalação, programam o equipamento e operam vários sistemas. Os técnicos de palco são responsáveis pela iluminação, pelo som, pelo vídeo, pelos cenários e/ou pelos sistemas de varas. O seu trabalho baseia-se em planos, instruções e cálculos. Podem trabalhar em pequenas instalações, teatros e outras pequenas produções artísticas.', 'released', '["Técnica de Palco", "Técnico de Palco"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/acbb7a20-c947-480d-a07e-868a0ab3eab8', 'Especialista em Ciências Biomédicas', 'Os cientistas especializados em biomedicina dirigem um departamento ou área de especialidade, realizando projetos de investigação clínica e trabalhando como parceiros de diagnóstico na equipe de cuidados de saúde (investigação e diagnóstico de doenças, como o cancro, a diabetes, as doenças hematológicas, a coagulação, a biologia molecular ou a genómica, entre outras) utilizando vários métodos, ferramentas digitais e bioinformática.', 'released', '["Investigadora em Ciências Biomédicas", "Especialista em Biomedecina", "Investigador em Ciências Biomédicas"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/acf28133-525f-4838-9248-d852e28b8f98', 'Gerente de Loja Gourmet', 'Os gerentes de loja gourmet assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Charcutaria Gourmet", "Gerentea de Loja Gourmet"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/acf462a3-9c34-46cb-952a-c612c38299f4', 'Procurador-Geral da República', 'Os Procuradores-gerais da República representam organismos governamentais e o público em geral em processos judiciais contra as partes acusadas de atividades ilegais. Investigam os processos judiciais, examinando os elementos de prova, entrevistando as partes envolvidas e interpretando a lei. Utilizam os resultados da sua investigação para apresentarem o caso durante as audiências e para construírem argumentos convincentes que assegurem que o resultado é o mais favorável para as partes que representam.', 'released', '["Procurador da República", "Procurador-Adjunto", "VIce Procuradora-Geral da República", "Procurador-Geral Adjunta", "Vice Procurador-Geral da República", "Procuradora-Geral da República", "Procurador-Geral da República", "Procuradora-Adjunta", "Procurador-Geral Adjunto"]'::jsonb, '2611'),
  ('http://data.europa.eu/esco/occupation/acf69cab-8629-45c8-ae10-c8fb15f474b6', 'Antropólogo', 'Os antropólogos investigam todos os aspetos da vida relacionados com o ser humano. Estudam as diversas civilizações que existiram ao longo do tempo e as suas formas de organização. Procuram analisar os aspetos físicos, sociais, linguísticos, políticos, econômicos, filosóficos e culturais dos diferentes povos. O objetivo dos seus estudos é compreender e descrever o passado da humanidade e resolver problemas sociais atuais. Exploram diferentes perspetivas, como a antropologia filosófica.', 'released', '["Antropólogo", "Antropóloga"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/ad14ec64-128c-4a72-9c1a-257a5f3b180c', 'Geólogo de Exploração', 'Os geólogos de exploração realizam a análise e a prospeção de depósitos minerais. Identificam, definem e obtêm títulos jurídicos para os depósitos minerais economicamente viáveis. São responsáveis pela concepção, gestão e execução dos programas de exploração. ;', 'released', '["Geóloga de Minas", "Geóloga de Exploração", "Geólogo de Minas", "Consultora em Geologia", "Geólogo de Exploração", "Consultor em Geologia"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/ad404c6b-291f-439e-9ad4-c93ddabd3c13', 'Diretor de Distribuição de Maquinaria de Minas, Construção e Engenharia Civil', 'Os diretores de distribuição de maquinaria de minas, construção e engenharia civil planificam a distribuição de maquinaria de minas, construção e engenharia civil a diversos pontos de venda.', 'released', '["Diretora de Logística Maquinaria Minas Construção Civil", "Diretora de Distribuição Maquinaria Minas Construção Civil", "Diretor de Distribuição Maquinaria Minas Construção Civil", "Diretor de Logística Maquinaria Minas Construção Civil", "Diretora de Distribuição de Maquinaria de Minas, Construção e Engenharia Civil"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/ad6589cb-ef1e-482d-863d-d80b2eb6b070', 'Operador de Estampagem a Quente', 'Os operadores de estampagem a quente cuidam de máquinas que aplicam uma película metálica a outros materiais utilizando cilindros de pressão e calor. Também misturam as cores, instalam o equipamento de máquinas adequado e controlar a impressão.', 'released', '["Operadora de Estampagem a Quente", "Operador de Estampagem a Quente"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/ad7bbc92-d5cb-4b64-a1a3-efc593afd437', 'Calibrador de Madeira de Construção', 'Os calibradores de madeira de construção inspecionam madeira de construção ou madeira cortada em pranchas. Testam a madeira de construção, procuram irregularidades e calibram a madeira com base na qualidade e conveniência do padrão.', 'released', '["Calibradora de Madeira de Construção", "Calibrador de Madeira de Construção"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/ad7c76e8-af96-42af-99a5-d579f707758c', 'Montador de Aeronaves', 'Os montadores de aeronaves utilizam ferramentas manuais, ferramentas elétricas e outros equipamentos, tais como máquinas CNC ou robôs, para construir, colocar e instalar peças pré-fabricadas para fabricar aeronaves e subconjuntos de aeronaves, fixos ou rotativos, tais como comandos de voo, revestimento de superfície de aeronave, sistemas de manipulação e outros sistemas mecânicos, etc. Leem e interpretam os esquemas. Operam sistemas de controlo para determinar o desempenho funcional dos conjuntos e ajustar em conformidade.', 'released', '["Montador de Estruturas de Aeronaves", "Montadora de Sistemas Mecânicos de Aeronaves", "Montador de Aeronoves", "Montador de Sistemas Mecânicos de Aeronaves", "Montadora de Estruturas de Aeronaves", "Montadora de Aeronoves", "Montadora de Aeronaves"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/ad8ab454-b506-46a5-afd3-66bbffd54115', 'Cartógrafo', 'Os cartógrafos criam mapas através da combinação de várias informações científicas em função da finalidade do mapa (por exemplo, mapas topográficos, urbanos ou políticos). Combinam a interpretação de notas matemáticas e medições com a estética e a representação visual do local para o desenvolvimento dos mapas. Podem igualmente trabalhar no desenvolvimento e na melhoria dos sistemas de informação geográfica e realizar investigação científica no âmbito da cartografia.', 'released', '["Cartógrafo", "Cartógrafa"]'::jsonb, '2165'),
  ('http://data.europa.eu/esco/occupation/ada3fc30-c205-4279-90b8-ed5c7c467626', 'Diretor de Desenvolvimento de Produtos de Couro', 'Os diretores de desenvolvimento de produtos de couro coordenam o processo de concepção e desenvolvimento dos produtos de couro, a fim de respeitar as especificações de comercialização, os prazos, os requisitos estratégicos e as políticas da empresa. Comunicam e colaboram com outras equipes internacionais ou profissionais envolvidos na produção de artigos de couro, como a logística e o marketing, o cálculo dos custos, o planejamento, a produção e a garantia da qualidade. São responsáveis pelo desenvolvimento de coleções de produtos de couro, que envolvem atividades como o acompanhamento de novos estilos ou a adaptação das especificações de design, a fim de satisfazer a visão do design, o ambiente de fabrico e o objetivo de rentabilidade das empresas.', 'released', '["Diretora de Desenvolvimento de Produtos de Couro", "Diretor de Desenvolvimento de Produtos de Couro", "Coordenadora de Desenvolvimento de Produtos de Couro", "Coordenador de Desenvolvimento de Produtos de Couro"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/ade351da-7bda-424e-8682-bbdcab2a25be', 'Operador de Processamento de Pagamento de Salários', 'Os operadores de processamento de pagamento de salários gerem as folhas de presença e os cheques dos salários dos empregados. Certificam-se de que as informações estão corretas. Verificam as horas extraordinárias, os dias de baixa por doença e as férias. Distribuem os cheques dos salários.', 'released', '["Operadora de Processamento de Pagamento de Salários", "Operador de Processamento de Pagamento de Salários"]'::jsonb, '4313'),
  ('http://data.europa.eu/esco/occupation/adf9257e-78cb-467d-b259-59ed65bd7aed', 'Técnico de Realização de Ensaios de Equipamento de Segurança Contra Incêndios', 'Os técnicos de realização de ensaios de equipamento de segurança contra incêndios realizam uma série de ensaios em materiais, como os materiais de construção, de transporte e têxteis, bem como em sistemas de prevenção de incêndios e de combate a incêndios. Avaliam, entre outras coisas, a resistência às chamas e o comportamento dos materiais em circunstâncias extremas.', 'released', '["Técnico de Realização de Ensaios de Equipamento de Segurança Contra Incêndios", "Técnica de Realização de Ensaios de Equipamento de Segurança Contra Incêndios"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/ae2c1bf4-669e-4fec-a7d7-698753699083', 'Professor de Filosofia', 'Os professores de Filosofia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Filosofia, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Filosofia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora Universitária de Filosofia", "Professor de Filosofia", "Professora de Filosofia", "Professor Universitário de Filosofia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/ae3f1edd-d191-4a8d-8dfc-099dcdc6f1e8', 'Operador de Prensas de Discos de Vinil', 'Operadores de prensas de discos de vinil asseguram o correto funcionamento de uma máquina que pressiona vinil com uma impressão negativa de um disco mestre. À medida que a pressão é aplicada, o vinil é forçado nos sulcos do disco mestre e obtém um disco de música.', 'released', '["Operadora de Prensas de Discos de Vinil", "Operador de Prensas de Discos de Vinil"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/ae66ca51-e762-48b4-bd46-071dc87cb30d', 'Guionista Gráfico', 'Os guionistas gráficos criam as cenas de um filme ou de uma série televisão de acordo com o guião, a fim de verificarem as possibilidades durante a produção. Trabalham em conjunto com o produtor e o realizador de vídeos e de filmes.', 'released', '["Guionista Gráfico", "Guionista Gráfica", "Artista de Guião Gráfico", "Artista de Storyboard"]'::jsonb, '2651'),
  ('http://data.europa.eu/esco/occupation/ae73f0dc-05a7-4e23-a234-9bb7e6d86975', 'Vendedor Porta a Porta', 'Os vendedores porta a porta vendem bens e serviços porta a porta.', 'released', '["Vendedora Porta a Porta", "Vendedora", "Vendedor", "Vendedor Porta a Porta"]'::jsonb, '5243'),
  ('http://data.europa.eu/esco/occupation/ae8b19cc-8c6e-4a16-ada2-c15f97ded133', 'Engenheiro Mecânico Especialista em Optomecânica', 'Os engenheiros mecânicos especialistas em optomecânica concebem e desenvolvem sistemas, dispositivos e componentes optomecânicos, tais como espelhos óticos e armações óticas. A engenharia optomecânica combina a engenharia ótica com a engenharia mecânica na concepção destes sistemas e dispositivos. Realizam atividades de investigação, realizam análises, testam os dispositivos e supervisionam a investigação.', 'released', '["Engenheira Mecânica Especialista em Optomecânica", "Engenheiro Mecânico Especialista em Optomecânica", "Engenheira Mecânico Especialista em Optomecânica"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/aeae4491-91b2-4029-9648-364e0bc4ecff', 'Supervisor de Produção de Equipamento Elétrico', 'Os supervisores de produção de equipamento elétrico coordenam, planeiam e orientam o processo de produção de equipamento elétrico. Gerem os trabalhadores da linha de produção, supervisionam a qualidade dos produtos montados e realizam a gestão dos custos e dos recursos.', 'released', '["Supervisor de Produção de Equipamento Elétrico", "Supervisora de Produção de Equipamento Elétrico"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/aeb7c6bd-22c9-43c2-8551-a1cc2560584f', 'Gestor de Previsões', 'Os gestores de previsões têm uma compreensão profunda das operações da empresa, dos níveis de inventário, dos lotes de produção, dos requisitos e dos custos de produção por produto e das tendências dos níveis da procura. Utilizam todas essas informações em combinação com o software de previsão, a fim de definir as encomendas de produção de acordo com as configurações de produção mais eficientes.', 'released', '["Gestora de Previsões", "Analista de Previsões", "Gestor de Previsões", "Gerente"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/aecb033a-2be8-459c-bbdc-87bbae922894', 'Supervisor de Revestimento de Interiores', 'Os supervisores de revestimento de interiores acompanham as atividades de estucagem. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Revestimento de Interiores", "Supervisora de Revestimento de Interiores", "Supervisor de Revestimento com Gesso", "Supervisora de Revestimento com Gesso"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/af2f3615-63ab-44dc-957d-c9660410d336', 'Montador de Produtos Metálicos', 'Os montadores de produtos metálicos instalam e fixam materiais metálicos de acordo com procedimentos rigorosamente previstos, a fim de produzir várias peças ou produtos finais, utilizando ferramentas elétricas, ferramentas manuais e outras máquinas.', 'released', '["Montadora de Produtos Metálicos", "Montador de Produtos Metálicos"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/af355ac4-dd89-44df-99a6-bba70202d6fe', 'Supervisor de Registro de Dados', 'Os supervisores de registo de dados gerem as operações quotidianas do pessoal de registo de dados. Organizam o fluxo de trabalho e as tarefas.', 'released', '["Supervisora de Registro de Dados"]'::jsonb, '3341'),
  ('http://data.europa.eu/esco/occupation/af513bd8-4340-4452-aa30-05a073ecc49a', 'Motorista de Carro Funerário', 'Os motoristas de carro funerário procedem à operação e manutenção de veículos especializados para transportar pessoas falecidas das suas casas, de um hospital ou de uma casa funerária para o seu local de repouso final. Também prestam assistência aos agentes funerários no exercício das suas funções.', 'released', NULL, '8322'),
  ('http://data.europa.eu/esco/occupation/af69484e-b43f-4685-b22d-f3418df45c4d', 'Psicoterapeuta', 'Os psicoterapeutas prestam assistência a e tratam utentes dos cuidados de saúde com diferentes graus de distúrbios psicológicos, psicossociais ou psicossomáticos e causados por agentes patogénicos através de métodos psicoterapêuticos. Promovem o desenvolvimento e o bem-estar pessoais e prestam aconselhamento sobre a melhoria das relações, das capacidades e das técnicas de resolução de problemas. Utilizam métodos psicoterapêuticos baseados em dados científicos, como a terapia comportamental, a análise existencial e a logoterapia, a psicanálise ou a terapia familiar sistémica, a fim de orientarem os doentes na sua evolução e de os ajudarem a procurar as soluções adequadas para os seus problemas. Os psicoterapeutas não são obrigados a possuir diplomas académicos em psicologia nem qualificação médica em psiquiatria. É uma profissão independente da psicologia, da psiquiatria e do aconselhamento.', 'released', NULL, '2634'),
  ('http://data.europa.eu/esco/occupation/afbe50b0-6634-4677-a3e7-0aada10cb9a7', 'Engenheiro Térmico', 'Os engenheiros térmicos concebem sistemas que fornecem aquecimento ou refrigeração por termodinâmica, que transfere o calor ou a energia através de líquidos e gases. Também constroem estes sistemas e realizam ensaios para garantir uma funcionalidade adequada.', 'released', '["Engenheira Térmico", "Engenheiro Térmico"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/afc5a0f4-42e5-4bfb-910c-2b54b44f99c5', 'Avaliador de Patrimônio', 'Os avaliadores de património realizam análises e investigações pormenorizadas de bens, a fim de determinarem o seu valor para efeitos de venda, hipoteca e seguro. Comparam o valor dos bens tendo em conta a idade, o estado real do bem, a sua qualidade, as reparações necessárias e a sustentabilidade global. Os avaliadores de património elaboram um inventário dos equipamentos, um cronograma do estado do bem e relatórios de avaliação de propriedades comerciais e residenciais.', 'released', '["Avaliador de Património", "Avaliadora de Património", "Avaliadora de Patrimônio"]'::jsonb, '3315'),
  ('http://data.europa.eu/esco/occupation/afcf9d03-6e51-4548-8cec-cfa50972929d', 'Diretor de Importação e Exportação de Açúcar, Chocolate e Produtos de Confeitaria', 'Os diretores de importação e exportação de açúcar, chocolate e produtos de confeitaria implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação de Açúcar, Chocolate e Produtos de Confeitaria", "Diretor de Vendas de Açúcar, Chocolate e Produtos de Confeitaria", "Diretora de Importação e Exportação de Açúcar, Chocolate e Produtos de Confeitaria", "Diretora de Vendas de Açúcar, Chocolate e Produtos de Confeitaria"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/afe9eaa4-433f-4ae6-90ff-afa098ccf1bb', 'Barbeleiro', 'Os barbeleiros cuidam e operam o equipamento e as máquinas adequados para a criação de correntes de metal, incluindo correntes de metais preciosos, tais como para joalharia, e produzem-nas em todas as fases do processo de produção. Fornecem o arame à máquina de fazer correntes, utilizam alicates para prender as extremidades da corrente formada pela máquina, e acabam e aparam os bordos soldando-os numa superfície lisa.', 'released', '["Barbeleiro", "Barbeleira"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/afee6a28-f654-4ac7-a665-f758616bc689', 'Técnico de Produção Alimentar', 'Os técnicos de produção alimentar ajudam os especialistas em tecnologia alimentar no desenvolvimento de processos para o fabrico de gêneros alimentícios e produtos afins, com base em princípios químicos, físicos e biológicos. Realizam atividades de investigação e experiências relacionadas com ingredientes, aditivos e embalagens. Os técnicos de produção alimentar também verificam a qualidade dos produtos, tendo em vista garantir a conformidade com a legislação e a regulamentação.', 'released', '["Encarregada de Produção Alimentar", "Encarregado de Produção Alimentar", "Técnica de Produção Alimentar", "Técnico de Produção Alimentar"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/aff66ae0-d6e1-4de3-b6af-78647defd08c', 'Assistente Social em Empresas', 'Os assistentes sociais em empresas prestam apoio às empresas na resolução de problemas sociais de grande dimensão através da ligação com as comunidades e os clientes. Procuram aumentar a produtividade dos trabalhadores e melhorar a saúde das suas famílias, centrando-se na promoção do equilíbrio entre vida pessoal e profissional.', 'released', '["Assistentea Social em Empresas"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/b00e9e89-fd8d-4655-b6a2-f58b17629473', 'Agente de Segurança Aeroportuária', 'Os agentes de segurança aeroportuária interagem com os passageiros para assegurar uma transição harmoniosa entre as zonas do aeroporto, em conformidade com os regulamentos de segurança. Efetuam revistas aos passageiros, à respetiva identificação e bagagem, a fim de garantir a segurança e impedir a atividade ilegal.', 'released', '["Agentea de Segurança Aeroportuária"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/b01affdd-c8a9-4121-bc50-a5be17f014eb', 'Terapeuta de Shiatsu', 'Os terapeutas de shiatsu prestam serviços de manutenção da saúde, educação em matéria de saúde, avaliação do estado de saúde global e recomendações para o bem-estar, bem como serviços de tratamento de certas doenças, através da avaliação energética do sistema de energia vital do corpo (Qi) e da sua regulação por meio de várias técnicas energéticas e manuais.', 'released', NULL, '3255'),
  ('http://data.europa.eu/esco/occupation/b0473a10-e3de-480c-a841-171f2356a074', 'Inspetor de Aviação Civil', 'Os inspetores de aviação civil efetuam inspeções dos procedimentos seguidos em matéria de manutenção, ajudas à navegação aérea, controlo do tráfego aéreo e equipamento de comunicação. Verificam o cumprimento da regulamentação da Organização da Aviação Civil Internacional (OACI), da UE, nacional e ambiental.', 'released', '["Inspetor de Aviação Civil", "Inspetora de Aviação Civil"]'::jsonb, '3154'),
  ('http://data.europa.eu/esco/occupation/b0480558-269d-4903-9bc7-f390cd6a6964', 'Técnico de Equipamento de Construção', 'Os técnicos de equipamento de construção procedem à inspeção, manutenção e reparação de veículos pesados utilizados na construção, silvicultura e terraplanagens, tais como bulldozers, escavadoras e ceifeiras-debulhadoras. Realizam avaliações do equipamento e asseguram a segurança e a eficiência ideal da máquina.', 'released', '["Técnico de Equipamento de Construção", "Técnica de Equipamento de Construção"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/b059d331-2dd9-4d7d-923e-1dd029d2e58c', 'Vendedor Ambulante', 'Os vendedores ambulantes vendem bens e serviços em rotas estabelecidas, na rua e em locais de mercados.', 'released', '["Vendedora de Mercado", "Vendedora Ambulante", "Vendedor de Rua", "Vendedor Ambulante", "Vendedor de Mercado", "Vendedora de Rua"]'::jsonb, '9520'),
  ('http://data.europa.eu/esco/occupation/b05f53db-b6b0-49bc-aa0c-1790c8c7012b', 'Aparelhador', 'Os aparelhadores especializam-se na elevação de objetos pesados, muitas vezes auxiliados por uma grua ou guindaste. Trabalham com os operadores de gruas para prender e desprender as cargas da grua. Podem também instalar o objeto pesado no local.', 'released', '["Aparelhador", "Aparelhadora"]'::jsonb, '7215'),
  ('http://data.europa.eu/esco/occupation/b065b637-5cb5-44d9-8c39-08004b51734e', 'Engenheiro Especialista em Acústica', 'Os engenheiros de engenharia em acústica estudam e aplicam a ciência do som a várias aplicações. Trabalham numa vasta gama de domínios, incluindo a consulta da acústica e dos elementos que afetam a transmissão do som em espaços de espetáculos ou atividades de gravação. Podem igualmente ser consultados quanto aos níveis de contaminação sonora para as atividades que exigem o cumprimento de normas nesta matéria.', 'released', '["Engenheira Especialista em Acústica", "Engenheiro Especialista em Acústica"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/b06a1dde-e5a1-4219-9491-2bedd0282e4b', 'Escritor', 'Os escritores desenvolvem conteúdos para livros. Escrevem romances, poesia, contos, banda desenhada e outras formas de literatura. Estas formas de escrita podem ser ficcionais ou não ficcionais.', 'released', '["Escritora", "Escritor", "Poetisa", "Romancista", "Poeta"]'::jsonb, '2641'),
  ('http://data.europa.eu/esco/occupation/b07e291d-1ea0-44d6-861c-e2c36861f9e3', 'Cesteiro', 'Os cesteiros utilizam fibras duras para entrançar manualmente objetos, tais como recipientes, cestos, esteiras e mobília. Utilizam várias técnicas e materiais tradicionais de acordo com a região e a utilização prevista do objeto.', 'released', '["Cesteiro", "Cesteira"]'::jsonb, '7317'),
  ('http://data.europa.eu/esco/occupation/b09acdda-6680-49d1-a411-129610ee3bc0', 'Gestor de Riscos Empresariais', 'Os gestores de riscos empresariais identificam e avaliam potenciais ameaças e oportunidades para uma empresa e prestam aconselhamento sobre a forma de lhes responder. Elaboram planos preventivos para evitar e reduzir os riscos e instituem planos para situações em que a empresa esteja sob ameaça. Coordenam os aspetos da gestão dos riscos entre as diferentes funções de uma organização e são responsáveis por atividades técnicas como a avaliação dos riscos, o mapeamento dos riscos e a aquisição de seguros. Comunicam informações sobre questões de risco aos quadros superiores e ao conselho de administração da empresa.;', 'released', '["Analista e Gestor de Risco", "Analista e Gestora de Risco", "Gerente", "Gestora de Riscos Empresariais"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/b09ffdec-b04c-41a8-bacc-2c71d7a3e5ac', 'Tipógrafo', 'Os tipógrafos garantem que o texto impresso seja corretamente colocado e visualmente agradável. Embora originalmente a tipografia fosse feita à mão e, posteriormente, utilizasse as técnicas, tais como o linotipo e a fotocomposição, atualmente a quase totalidade da tipografia é feita digitalmente, utilizando programas de desenho ou programas de tipografia especializados.', 'released', '["Tipógrafa", "Tipógrafo"]'::jsonb, '7321'),
  ('http://data.europa.eu/esco/occupation/b0ad8659-0410-4b5b-9466-a90f8b3cdac9', 'Controlador de Qualidade de Produtos', 'Os controladores de qualidade de produtos verificam a qualidade dos produtos fabricados. Trabalham em instalações de fabrico onde realizam a inspeção básica e a avaliação dos produtos antes, durante ou após o processo de produção. Acompanham problemas de produção e enviam artigos de qualidade inferior ou deficiente para reparação.', 'released', '["Controladora de Qualidade de Produtos", "Controlador de Qualidade de Produtos"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/b0c6f284-f3ed-4820-a62e-4e87869f5a3e', 'Operador de Máquinas de Fabricação de Produtos de Borracha', 'Os operadores de máquinas de fabrico de produtos de borracha utilizam máquinas de amassar, misturar, calandrar, formar, extrudir e curar produtos de borracha a partir de borracha natural e sintética. Medem os ingredientes para a mistura e carregam-nos para a máquina. Os operadores de máquinas de fabrico de produtos de borracha acompanham e controlam a temperatura, a pressão e a velocidade durante a produção.', 'released', '["Operadora de Máquinas de Fabricação de Produtos de Borracha", "Operador de Máquinas de Fabricação de Produtos de Borracha"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/b0cb4f78-c361-48cf-97aa-25104ac2647c', 'Tratador de Madeira', 'Os tratadores de madeira aplicam tratamentos à madeira para torná-la resistente a fatores ambientais, tais como o bolor, o frio, a humidade, ou a coloração. Os tratamentos podem também contribuir para a cor da madeira. Os tratadores de madeira podem utilizar produtos químicos, calor, gases, luz UV, ou uma combinação dos mesmos, para o tratamento da madeira.', 'released', '["Tratadora de Madeira", "Tratador de Madeira"]'::jsonb, '7521'),
  ('http://data.europa.eu/esco/occupation/b0f3f595-4965-4f13-ba5c-f6049b62469f', 'Técnico de Biometria', 'Os técnicos de biometria realizam investigação no domínio da biometria. Realizam projetos de investigação estatística ou biológica através da medição de impressões digitais, da retina e das formas humanas para aplicações médicas ou industriais.', 'released', '["Especialista em Biometria", "Biometrista", "Técnico de Biometria", "Técnica de Biometria", "Investigador em Biometria", "Investigadora em Biometria"]'::jsonb, '2120'),
  ('http://data.europa.eu/esco/occupation/b0fa69b4-998c-4e66-acd3-5f5d73cadb5c', 'Operador de Máquina de Embalagem e Enchimento', 'Os operadores de máquina de embalagem e enchimento asseguram o correto funcionamento de máquinas para preparar e embalar produtos alimentares em vários recipientes de embalagem, tais como frascos, caixas de cartão, latas de conserva e outros.', 'released', '["Operadora de Embalagem e Enchimento", "Operador de Máquina de Embalagem e Enchimento", "Operadora de Máquina de Embalagem e Enchimento", "Operador de Embalagem e Enchimento"]'::jsonb, '8183'),
  ('http://data.europa.eu/esco/occupation/b10d45f4-482d-4301-bc39-da206b17815c', 'Inspetor de Montagem de Aeronaves', 'Os inspetores de montagem de aeronaves utilizam equipamentos de medição e de ensaio para inspecionar e monitorizar as montagens de aeronaves, a fim de garantir a conformidade com as especificações técnicas e as normas e regulamentos de segurança. Analisam as montagens para detectar anomalias ou danos e verificam o trabalho de reparação. Também fornecem documentação de inspeção pormenorizada e recomendam medidas nos casos em que foram detectados problemas.', 'released', '["Inspetora de Montagem de Aeronaves", "Inspetor de Montagem de Aeronaves"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/b10dc548-10e1-4447-8406-5101ff170bbf', 'Pasteleiro-Chefe', 'Os pasteleiros-chefe asseguram a preparação, a confeção e a apresentação das sobremesas, dos produtos doces e dos produtos de pastelaria.', 'released', '["Pasteleira Chefe", "Pasteleiro-Chefe", "Pasteleiro Chefe", "Pasteleira-Chefe", "Chefe de Pastelaria", "Pasteleiro-Chefea"]'::jsonb, '3434'),
  ('http://data.europa.eu/esco/occupation/b11e1742-5e28-4270-b081-b0193d85ee7d', 'Desenvolvedor de Banco de Dados', 'Os programadores de bancos de dados programam, implementam e coordenam alterações aos bancos de dados informáticos com base nos seus conhecimentos especializados em sistemas de gestão de bancos de dados.', 'released', '["Programador de Bancos de Dados", "Codificador de Bancos de Dados", "Programadora de Bancos de Dados", "Criador de Bancos de Dados", "Criadora de Bancos de Dados", "Codificadora de Bancos de Dados", "Programador", "Desenvolvedora de Banco de Dados"]'::jsonb, '2521'),
  ('http://data.europa.eu/esco/occupation/b12b14fd-5b74-40c6-afd9-dd35b34e27ed', 'Supervisor da Indústria de Montagem', 'Os supervisores da indústria de montagem são responsáveis pela organização, pelo planejamento e pela coordenação das operações de montagem. Mantêm um registo de todas as atividades e gerem o processo com vista ao seu funcionamento eficiente, a fim de resolverem problemas como a perda de produção. Respondem perante o gestor de produção industrial e o gestor de fabrico.', 'released', '["Supervisora da Indústria de Montagem", "Supervisor da Indústria de Montagem"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/b148e7a3-e5b0-4edc-b770-85ab81f36ac9', 'Diretor de Importação e Exportação de Bens de Consumo Doméstico', 'Os diretores de importação e exportação de bens de consumo doméstico implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Importação e Exportação de Bens de Consumo Doméstico", "Diretor de Importação e Exportação de Bens de Consumo Doméstico", "Diretor de Vendas de Bens de Consumo Doméstico", "Diretora de Vendas de Bens de Consumo Doméstico"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/b156960c-8508-4067-908d-f167847c55b1', 'Diretor de Pedreira', 'Os diretores de pedreira planificam, supervisionam e coordenam as operações da pedreira. Coordenam a extração, o processamento e o transporte e asseguram que estes processos funcionam bem e de acordo com as normas de saúde e segurança. Os diretores de pedreira asseguram o bom funcionamento da pedreira e executam as estratégias e orientações da empresa.', 'released', '["Diretor de Pedreira", "Diretora de Pedreira"]'::jsonb, '1322'),
  ('http://data.europa.eu/esco/occupation/b176e5d7-1f94-495c-907f-80a7f61aed59', 'Técnico de Teledeteção', 'Os técnicos de teledeteção recolhem dados de equipamentos aerotransportados. Utilizam equipamento destinado à recolha de dados e à determinação de pontos geográficos, contribuindo para uma série de operações, como a conservação de terras, o planejamento urbano e as operações militares.', 'released', '["Técnica de Teledeteção", "Técnico de Teledeteção"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/b1ab3572-fa2f-4624-8eac-3c3d986d237b', 'Copywriter de Publicidade', 'Os copywriters de publicidade são responsáveis pelo design escrito ou verbal de anúncios publicitários e comerciais. Redigem slogans e chavões e trabalham em estreita colaboração com artistas da área da publicidade.;', 'released', '["Copywriter"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/b1c0714d-77f1-4732-8fd8-9f0739fb9974', 'Especialista em Efeitos Especiais', 'Os especialistas de efeitos especiais criam ilusões para filmes, vídeos e jogos de computador. Utilizam programas informáticos.', 'released', '["Técnico de Efeitos Especiais", "Técnica de Efeitos Especiais"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/b1c80369-067e-4041-84c8-dbe65640a5d8', 'Consultor de Tecnologia da Informação', 'Os consultores de tecnologia da informação prestam aconselhamento sobre a forma de otimizar a utilização das ferramentas e sistemas existentes, fazem recomendações para o desenvolvimento e a implementação de um projeto empresarial ou de uma solução tecnológica e contribuem para as definições do projeto. Promovem ações de sensibilização no que respeita às inovações no domínio das tecnologias da informação e ao seu potencial valor para uma empresa. Participam igualmente na avaliação e na escolha de soluções de tecnologia da informação.', 'released', '["Consultora de Informática", "Consultora de Tecnologias de Informação e Comunicação", "Consultor de Tecnologias de Informação e Comunicação", "Perito em Informática", "Consultora de Tecnologia da Informação", "Perita em Informática", "Especialista em Informática", "Consultor de Informática", "Consultor de Tecnologia da Informação", "TI"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/b1ed68f8-8d51-4bcc-8825-bd554859480f', 'Diretor de Conformidade e Segurança da Informação', 'Os diretores de conformidade e segurança da informação asseguram o cumprimento da regulamentação e supervisionam a segurança da informação, a fim de garantir a segurança de todas as tecnologias da informação associadas.', 'released', '["Diretora de Conformidade e Segurança da Informação", "Diretor de Conformidade e Segurança da Informação"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/b206a740-c7eb-407d-9cdb-93502368c4d8', 'Supervisor de Grua', 'Os supervisores de gruas supervisionam as operações das gruas. Mantêm-se atentos à segurança e garantem o cumprimento da regulamentação. Estes supervisores tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Grua", "Supervisora de Grua"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/b21aac17-8237-4264-bc2c-0e315346fd8f', 'Operador de Sala de Controle de Instalações da Indústria Química', 'Os operadores de salas de controlo de instalações da indústria química acompanham e inspecionam remotamente os sistemas de produção durante o seu turno, comunicando todas as anomalias e incidentes utilizando os sistemas necessários. Operam os painéis da sala de controlo e asseguram a segurança dos trabalhadores da área da produção e do equipamento de produção.', 'released', '["Operadora de Sala de Controle de Instalações da Indústria Química", "Operador de Sala de Controle de Instalações da Indústria Química"]'::jsonb, '3133'),
  ('http://data.europa.eu/esco/occupation/b21b5952-1658-44f8-b719-e5be7fb39866', 'Gerente de Stand de Automóveis', 'Os gerentes de stand de automóveis assumem a responsabilidade pelas atividades e pelo pessoal num salão de exposição de veículos. Estes funcionários gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gestora de Vendas Automóveis", "Gestor de Vendas Automóveis", "Gerente de Showroom de Automóveis", "Gerente de Showroom de Autocaravanas", "Gerentea de Stand de Automóveis"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/b223f402-0318-4e27-8691-df6e7f7295d2', 'Tenente', 'Os tenentes são responsáveis pelo comando de pelotões de soldados e pela sua direção em exercícios de formação e disciplina. Exercem igualmente funções administrativas e funcionam como consultores.', 'released', '["Tenente das Forças Armadas", "Tenentea"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/b2678105-9d5c-403f-b822-274aff706309', 'Produtor de Ovinos e Caprinos', 'Os produtores de ovinos e caprinos supervisionam a produção e o cuidado diário dos ovinos e caprinos. Zelam pela saúde e pelo bem-estar dos ovinos e caprinos.', 'released', '["Produtor de Ovinos e Caprinos", "Ovinicultora", "Ovinocultora", "Criador de Ovelhas e Cabras", "Ccriador de Ovelhas", "Ovinocultor", "Criadora de Ovelhas e Cabras", "Produtora de Ovinos e Caprinos", "Ovinicultor", "Criadora de Ovelhas"]'::jsonb, '6121'),
  ('http://data.europa.eu/esco/occupation/b27854dd-3fbe-406e-a750-54f677d55936', 'Coordenador de Manutenção Aeronáutica', 'Os coordenadores de manutenção aeronáutica planeiam, agendam e gerem a preparação e manutenção nos hangares e oficinas. Comunicam com gestores de nível superior, a fim de preparar os recursos necessários para operações regulares e eficientes nos aeroportos.', 'released', '["Coordenador de Manutenção Aeronáutica", "Coordenadora de Manutenção Aeronáutica"]'::jsonb, '7232'),
  ('http://data.europa.eu/esco/occupation/b2826761-6fc4-4344-9d36-d8455cb6b185', 'Diretor de Importação e Exportação de Peixes e Mariscos', 'Os diretores de importação e exportação de peixes e mariscos implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Vendas de Peixes e Mariscos", "Diretora de Vendas de Peixes e Mariscos", "Diretor de Importação e Exportação de Peixes e Mariscos", "Diretora de Importação e Exportação de Peixes e Mariscos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/b2cac4bc-abb7-41b3-a515-2ad006b8ebf6', 'Controlador de Painéis de Controle', 'Os controladores de painéis de controlo testam os painéis de controlo elétrico. Interpretam os esquemas para verificar se a cablagem está corretamente ligada. Os controladores de painéis de controlo utilizam equipamento elétrico de medição e ensaio para detectar avarias e podem corrigir cablagem e componentes com defeito.', 'released', '["Controladora de Painéis de Controle", "Controlador de Painéis de Controle"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/b2cede50-82bb-4684-9f11-1930e12ad672', 'Engenheiro de Energia', 'Os engenheiros de energia concebem formas novas, eficientes e limpas de produção, transformação e distribuição de energia para melhorar a sustentabilidade ambiental e a eficiência energética. Extraem energia através de recursos naturais, como o petróleo ou o gás, ou de fontes renováveis e sustentáveis, como o vento ou o sol.', 'released', '["Engenheiro de Energia", "Engenheira de Energia"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/b2dab4fb-b7f7-4f57-94b2-9c0f0848564a', 'Trabalhador em Isolamentos Acústicos e Térmicos', 'Os trabalhadores em isolamentos acústicos e térmicos instalam uma variedade de materiais de isolamento para proteger uma estrutura ou materiais do calor, do frio e do ruído do ambiente.', 'released', '["Instaladora de Isolamentos", "Trabalhadora em Isolamentos Acústicos", "Instalador de Isolamentos", "Trabalhador em Isolamentos Térmicos", "Trabalhadora em Isolamentos Acústicos e Térmicos", "Trabalhador em Isolamentos Acústicos e Térmicos", "Trabalhadora em Isolamentos Térmicos", "Trabalhador em Isolamentos Acústicos"]'::jsonb, '7124'),
  ('http://data.europa.eu/esco/occupation/b2e81332-0972-4e0f-9a4d-1d15c9c9513b', 'Especialista de Back Office', 'Os especialistas de back office exercem tarefas de natureza administrativa e organizativa na gestão de uma sociedade financeira, em apoio do front office. Realizam tarefas administrativas, efetuam transações financeiras, gerem dados e documentos da empresa e asseguram funções de apoio e operações de back office diversas, em coordenação com outros departamentos da empresa.;', 'released', NULL, '4312'),
  ('http://data.europa.eu/esco/occupation/b2eacfdf-5de5-4e8c-a8cb-3d32e201c210', 'Operador de Reator Nuclear', 'Os operadores de reatores nucleares controlam diretamente os reatores nucleares em centrais elétricas a partir de painéis de controlo, sendo os únicos responsáveis pelas alterações na reatividade dos reatores. Iniciam as operações e tomam medidas face a alterações no estado dos reatores, como, por exemplo, acidentes e situações críticas. Acompanham os parâmetros e asseguram a conformidade com a regulamentação em matéria de segurança.', 'released', '["Operadora de Reator Nuclear", "Operador de Reator Nuclear"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/b2f5ed56-c83f-40d0-b861-f5253cd3d1d9', 'Vitralista', 'Os vitralistas criam obras de arte originais através da montagem de pedaços de vidro. Podem participar em processos de restauro (como os realizados em catedrais, igrejas, etc.) e podem criar acessórios, janelas ou decorações.', 'released', NULL, '2651'),
  ('http://data.europa.eu/esco/occupation/b3086ad2-1f3c-4a60-9bdb-8b4746989d4b', 'Instrutor de Tênis', 'Os instrutores de tênis aconselham e orientam indivíduos e grupos sobre como jogar tênis. Ministram aulas e ensinam as regras e as técnicas do desporto, tais como pegas, pancadas e serviços. Motivam os clientes e ajudam a melhorar o seu desempenho.', 'released', '["Instrutora de Tênis", "Instrutor de Tênis"]'::jsonb, '3422'),
  ('http://data.europa.eu/esco/occupation/b31e404e-9af6-457d-a58a-208f612eeba3', 'Técnico de Engenharia Mecânica', 'Os técnicos de engenharia mecânica prestam apoio técnico a engenheiros mecânicos na produção e no fabrico de máquinas. Prestam assistência na realização de desenhos e ajustes e realizam ensaios. Desenvolvem também configurações e desenhos, recolhem e interpretam dados e elaboram relatórios.', 'released', '["Técnico de Engenharia Mecânica", "Técnica de Engenharia Mecânica"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/b322bb4c-bbef-45c2-bd7e-00a97c3ab268', 'Operador de Tratamento Anticorrosivo', 'Os operadores de tratamento anticorrosivo utilizam o equipamento e as máquinas adequados para fornecer às peças metálicas um acabamento duro e resistente, constituído por fórmulas químicas específicas, que impede ou atrasa a ferrugem nas peças de ferro e aço e protege contra a corrosão.', 'released', '["Operador de Tratamento Anticorrosivo", "Operadora de Proteção Anticorrosiva", "Operador de Proteção Anticorrosiva", "Operadora de Tratamento Anticorrosivo"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/b343dd0c-8a83-4e13-a79c-0ac52f526c64', 'Técnico de Ensaios de Motores de Aeronaves', 'Os técnicos de ensaios de motores de aeronaves testam o desempenho de todo o tipo de motores utilizados em aeronaves em instalações especializadas, como os laboratórios. Posicionam ou fornecem orientações aos trabalhadores para o posicionamento dos motores no banco de ensaios. Utilizam ferramentas manuais e máquinas para posicionar e ligar o motor ao banco de ensaios. Utilizam equipamento informatizado para introduzir, ler e registar dados de ensaios, como a temperatura, a velocidade, o consumo de combustível e a pressão do óleo e dos gases de escape.', 'released', '["Técnica de Ensaios de Motores de Aeronaves", "Técnica de Manutenção", "Técnico de Ensaios de Motores de Aeronaves", "Técnico de Manutenção"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/b37d15b3-402e-4792-8292-f18c0de7aca6', 'Técnico de Dispositivos Móveis', 'Os técnicos de dispositivos móveis efetuam um diagnóstico adequado de avarias para melhorar a qualidade dos dispositivos móveis e para os reparar. Fornecem informações relativas a vários serviços, incluindo garantias e serviços pós-venda.', 'released', '["Técnico de Dispositivos Móveis", "Técnica de Dispositivos Móveis", "Técnica de Aparelhos Móveis", "Técnico de Aparelhos Móveis"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/b3855886-bfee-4fd9-827e-2a0b6b4b4441', 'Engenheiro de Minas Especialista em Sistemas de Ventilação', 'Os engenheiros de minas especialistas em sistemas de ventilação concebem e asseguram o fornecimento de ar fresco e a circulação de ar em minas subterrâneas, e a remoção atempada dos gases nocivos. Coordenam a concepção do sistema de ventilação com a gestão da mina, o engenheiro de segurança mineira e o engenheiro da instalação mineira.', 'released', '["Engenheira de Minas Especialista em Sistemas de Ventilação", "Engenheiro de Minas", "Engenheira de Minas", "Engenheiro de Minas Especialista em Sistemas de Ventilação"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/b3867d0a-e902-4d88-b0c2-3e0d2cf35c83', 'Inspetor de Materiais Perigosos', 'Os inspetores de materiais perigosos inspecionam as instalações que manipulam materiais perigosos para garantir a conformidade com a regulamentação em matéria de saúde e segurança, bem como a legislação relativa ao tratamento de materiais perigosos. Investigam as infrações, supervisionam os testes dos planos de resposta a situações de emergência e risco e prestam aconselhamento sobre a melhoria das operações e procedimentos das instalações, bem como sobre a regulamentação relativa aos materiais perigosos. Prestam ainda aconselhamento aos responsáveis da unidade sobre potenciais fontes de perigo para a comunidade e sobre uma regulamentação mais eficaz em matéria de segurança.', 'released', '["Inspetor de Resíduos Perigosos", "Inspetora de Resíduos Perigosos", "Inspetora de Materiais Perigosos"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/b39a74a2-37fe-4fdc-ba8e-5bbbbdce2d89', 'Diretor de Estação Ferroviária', 'Os diretores de estação ferroviária são responsáveis pela organização de tarefas relacionadas com a exploração das estações ferroviárias. As suas tarefas abrangem a organização das obras de manutenção e reparação dos edifícios e do equipamento interior. Asseguram o conforto, o serviço, a segurança e a proteção dos passageiros e de outros clientes e a utilização comercial dos edifícios. Dependendo da dimensão da estação, o número de efetivos sob a responsabilidade direta dos diretores de estação ferroviária pode ser elevado.', 'released', '["Diretora de Estação Ferroviária", "Diretor de Estação Ferroviária"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/b3b32930-05f0-4b2e-93bf-34d1e3f89a3b', 'Instrutor de Voo', 'Os instrutores de voo formam pilotos novos ou experientes, que procuram obter licenças ou experiência na pilotagem de novas aeronaves, na operação correta de uma aeronave em conformidade com a regulamentação. Ensinam aos seus alunos a teoria e a prática de como pilotar e manter eficientemente um avião, e observam e avaliam a técnica dos alunos. Também incidem sobre os regulamentos relativos aos procedimentos operacionais e de segurança específicos das diferentes aeronaves comerciais.', 'released', '["Instrutor de Voo", "Instrutora de Voo"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/b3b79192-f6e0-4aa0-92d1-f876508e05b3', 'Costureiro de Guarda-Roupa', 'Os costureiros de guarda-roupa criam, costuram, cosem, tingem, adaptam e cuidam do guarda-roupa a utilizar em espetáculos ao vivo, no cinema ou nos programas de televisão. O seu trabalho é baseado na visão artística, em esboços ou moldes acabados combinados com o conhecimento do corpo humano, para assegurar ao usuário a maior amplitude de movimentos. Trabalham em estreita colaboração com os designers. ;', 'released', '["Costureira de Guarda-Roupa", "Costureiro de Guarda-Roupa"]'::jsonb, '7531'),
  ('http://data.europa.eu/esco/occupation/b3cd0522-14a9-4e21-a7ee-c9a1f9c0de51', 'Tecelão de Tapetes', 'Os tecelões de tapetes operam máquinas para criar revestimentos têxteis para pavimentos. Criam alcatifas e tapetes de lã ou de têxteis sintéticos utilizando equipamento especializado. Os tecelões de tapetes podem utilizar diferentes métodos, tais como a tecelagem, nós ou penachos, para criar tapetes de diferentes estilos.', 'released', '["Tecelão de Tapetes", "Tecelã de Tapetes", "Tecelãa de Tapetes"]'::jsonb, '7318'),
  ('http://data.europa.eu/esco/occupation/b3ce981c-5b32-4de2-8e53-502a6357b2bc', 'Analista de Risco de Crédito', 'Os analistas de risco de crédito gerem o risco de crédito individual e implementam medidas de prevenção de fraudes, analisam transações comerciais, analisam documentos legais e fazem recomendações sobre o nível de risco.', 'released', NULL, '3312'),
  ('http://data.europa.eu/esco/occupation/b3e459a2-0103-4182-8882-c255d474a7ff', 'Analista de Política Fiscal', 'Os analistas de política fiscal investigam e desenvolvem políticas e legislação em matéria de fiscalidade, tendo em vista a melhoria e o desenvolvimento de políticas fiscais. Prestam aconselhamento a organismos oficiais sobre a aplicação de políticas e as operações financeiras, além de preverem a influência financeira das alterações nas políticas fiscais.', 'released', '["Consultor Fiscal", "Consultora Fiscal", "Analista Fiscal"]'::jsonb, '2631'),
  ('http://data.europa.eu/esco/occupation/b3ebf55f-5e50-4262-946a-f08d7fbe29b2', 'Professor de Ciências Médicas', 'Os professores de Ciências Médicas são professores universitários ou docentes em geral e, frequentemente, médicos que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências Médicas, que é predominantemente de natureza académica. Trabalham com os seus assistentes de investigação universitária e professores assistentes universitários na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio das Ciências Médicas, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Ciências Médicas", "Professora Universitária de Ciências Médicas", "Professor de Geriatria", "Professora de Geriatria", "Professor de Ciências Médicas", "Professor de Histologia e Embriologia", "Professor de Pediatria", "Professor de Patologia", "Professora de Patologia", "Professor Universitário de Ciências Médicas", "Professora de Histologia e Embriologia", "Professora de Pediatria"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/b42c5ed4-c6e4-4694-934f-96127719cc43', 'Diretor de Instalações', 'Os diretores de instalações realizam o planejamento estratégico e o planejamento operacional de rotina relacionados com a administração e a manutenção dos edifícios. Controlam e gerem procedimentos de saúde e segurança, supervisionam o trabalho dos contratantes, planificam e tratam as operações de manutenção dos edifícios, a proteção contra incêndios e a segurança, supervisionam as atividades de limpeza dos edifícios, as infraestruturas de serviços de utilidade pública e são responsáveis pela gestão do espaço.', 'released', '["Coordenador de Instalações", "Supervisor de Instalações", "Supervisora de Instalações", "Supervisora de Manutenção de Edifício", "Diretor de Instalações", "Diretora de Instalações", "Supervisor de Manutenção de Edifício", "Coordenadora de Instalações"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/b42d8731-386b-4d34-a824-4b736feee1e5', 'Agente de Transações Imobiliárias', 'Os agentes de transações imobiliárias tratam e investigam toda a documentação necessária para a venda de um imóvel, incluindo os contratos, declarações de liquidação, hipotecas, apólices de seguro de propriedade, etc. Garantem o cumprimento dos requisitos legais e analisam todas as taxas relacionadas com o processo da venda do imóvel.', 'released', '["Title Closer", "Agentea de Transações Imobiliárias"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/b4306d87-7992-47fc-914a-4485a4e7003c', 'Classificador de Produtos Alimentares', 'Os classificadores de produtos alimentares procedem à inspeção, triagem e classificação da qualidade dos produtos alimentares. Classificam os produtos alimentares de acordo com critérios sensoriais ou com a ajuda de máquinas. Determinam a utilização do produto através da sua classificação nas categorias adequadas e eliminam os alimentos danificados ou expirados. Os classificadores de produtos medem e pesem os produtos e comunicam as suas conclusões para que os alimentos possam ser transformados posteriormente.', 'released', '["Classificador de Produtos Alimentares", "Classificadora de Produtos Alimentares"]'::jsonb, '7515'),
  ('http://data.europa.eu/esco/occupation/b471350e-23ce-4789-a821-5500b28cffe1', 'Funcionário de Tribunal com Poderes Coercivos', 'Os funcionários de tribunal com poderes coercivos executam ordens de sentenças judiciais, tais como a gestão da recuperação de dinheiro em dívida, a apreensão de bens e a venda de bens em leilões públicos para obter o dinheiro devido. Também enviam intimações e mandados de captura para assegurar a presença em tribunal ou noutros processos judiciais.', 'released', '["Funcionária de Tribunal com Poderes Coercivos", "Funcionário de Tribunal com Poderes Coercivos"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/b476f45f-2c79-44d5-a4d7-fa357aa83074', 'Guia Turístico', 'Os guias turísticos prestam assistência a indivíduos ou grupos durante viagens ou circuitos turísticos ou em locais de interesse turístico, tais como museus, monumentos e locais públicos. Ajudam as pessoas a interpretar o património cultural e natural de um objeto, de um local ou de uma área e fornecem informações e orientações na língua da sua escolha.;', 'released', '["Técnica em Guia de Tursimo", "Técnico em Guia de Turismo", "Guia de Turismo", "Guia Turístico", "Guia Turística"]'::jsonb, '5113'),
  ('http://data.europa.eu/esco/occupation/b493b10d-7131-4814-93bb-a2c1be4a095f', 'Técnico de Reparações de Equipamento de Escritório', 'Os técnicos de reparações de equipamento de escritório prestam serviços às empresas relacionados com a instalação, manutenção e reparação de equipamentos novos ou existentes, tais como impressoras, scanners e modems, nas instalações dos clientes. Procedem à manutenção dos registos de serviços prestados e devolvem equipamento para um centro de reparação, se necessário.', 'released', '["Técnica de Reparações de Equipamento de Escritório", "Técnico de Reparações de Equipamento de Escritório"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/b49f95f8-c1c8-428f-9f1f-5f5abae55e51', 'Diretor de Importação e Exportação de Animais Vivos', 'Os diretores de importação e exportação de animais vivos implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas Animais Vivos", "Diretor de Importação e Exportação de Animais Vivos", "Diretor de Vendas Animais Vivos", "Diretora de Importação e Exportação de Animais Vivos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/b4bff870-5c8f-4c33-b07f-f04d79830633', 'Empregado de Serviços Alimentares', 'Os empregados de serviços alimentares preparam os alimentos e servem os clientes. Preparam pratos simples a servir em locais que servem alimentos, tais como restaurantes, cafés, hotéis, hospitais, e asseguram que as operações de cozinha funcionam de forma harmoniosa e eficiente.;', 'released', '["Empregado de Confeção e Venda de Refeições em Companhia Aérea", "Empregada de Confeção e Venda de Refeições em Companhia Aérea", "Assistente de Venda", "Empregada de Serviços Alimentares"]'::jsonb, '5246'),
  ('http://data.europa.eu/esco/occupation/b4c6d1b0-929e-48be-9f67-47bd8c30658b', 'Colocador de Telhados', 'Os colocadores de telhados cobrem estruturas com telhados. Instalam os elementos de suporte num telhado, plano ou inclinado, e cobrem-nos com uma camada impermeável.', 'released', '["Colocadora de Telhados", "Carpinteira de Telhados", "Latoeiro", "Colocador de Telhados", "Carpinteiro de Telhados", "Latoeira"]'::jsonb, '7121'),
  ('http://data.europa.eu/esco/occupation/b4e26d7f-475e-4ada-b287-d669de03fb21', 'Técnico da Borracha', 'Os técnicos da borracha desenvolvem formulações compostas para dar resposta a necessidades específicas e obter as propriedades de endurecimento necessárias, partindo de especificações técnicas e exigências de aplicação. Conhecem as características físicas e químicas das matérias-primas de borracha e do processo para a sua conversão em produtos de mercado.;', 'released', '["Cientista de Tecnologia da Borracha", "Especialista em Tecnologia de Borracha", "Técnica de Borracha", "Analista de Tecnologia de Borracha", "Técnico de Borracha", "Técnica da Borracha"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/b4f08f2e-3c97-4484-9094-446a17dad802', 'Operador de Laboratório Cinematográfico', 'Os operadores de laboratório cinematográfico revelam material cinematográfico em vídeos e materiais visíveis. Revelam as imagens em diferentes formatos, tais como 65-70 mm e 8 mm, e apresentações, tais como a preto e branco e a cores. Produzem pequenos filmes a pedido de clientes.', 'released', '["Operador de Laboratório Cinematográfico", "Operadora de Laboratório Cinematográfico"]'::jsonb, '8132'),
  ('http://data.europa.eu/esco/occupation/b4f4b21e-7664-45ca-9697-9123cfd8c9ef', 'Operador de Bate-Estacas', 'Os operadores de bate-estacas trabalham com equipamento pesado que posiciona estacas e martela as mesmas no solo através de um mecanismo de perfuração.', 'released', '["Operadora de Bate-Estacas", "Operador de Bate-Estacas"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/b4ff30f8-073b-4dd8-9128-ecf9d0ff87ba', 'Criador de Bovinos', 'Os criadores de bovinos supervisionam a produção e o cuidado diário dos bovinos. Zelam pela saúde e pelo bem-estar dos bovinos.', 'released', '["Produtora de Bovinos", "Operadora Pecuária", "Criador de Gado", "Criadora de Gado", "Produtor de Bovinos", "Operador de Pecuária", "Técnica de Produção Agro-Pecuária", "Operadora de Pecuária", "Técnico de Produção Agro-Pecuária", "Criador de Bovinos", "Operador Pecuário", "Criadora de Bovinos"]'::jsonb, '6121'),
  ('http://data.europa.eu/esco/occupation/b50ae5f6-3f67-4cc7-92bb-6cec7214bfc4', 'Técnico de Ensaios de Veículos a Motor', 'Os técnicos de ensaios de veículos a motor testam o desempenho de motores diesel, a gasolina, a gás e elétricos em instalações especializadas, como os laboratórios. Posicionam ou fornecem orientações aos trabalhadores para o posicionamento dos motores no banco de ensaios. Utilizam ferramentas manuais e máquinas para posicionar e ligar o motor ao banco de ensaios. Utilizam equipamento informatizado para introduzir, ler e registar dados de ensaios, como a temperatura, a velocidade, o consumo de combustível e a pressão do óleo e dos gases de escape.', 'released', '["Técnica de Ensaios de Veículos a Motor", "Técnico de Ensaios de Veículos a Motor"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/b53209fa-ba54-4a7a-b71c-bcc8014053ec', 'Especialista em Import-Export de Máquinas, Equipamento Industrial, Embarcações e Aeronaves', 'Os especialistas em import-export de máquinas, equipamento industrial, embarcações e aeronaves possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Máquinas, Equipamento Industrial, Embarcações e Aeronaves"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/b55718eb-e8ff-4485-8ad0-bbac32cbd77b', 'Planejador de Meios de Publicidade', 'Os planeadores de meios de publicidade prestam aconselhamento sobre as melhores plataformas de meios de comunicação para a transmissão de ideias. Analisam os planos de publicidade, a fim de avaliarem a finalidade/objetivo da estratégia de marketing. Avaliam o potencial e a taxa de resposta que os diferentes canais de comunicação podem ter na transmissão de uma mensagem relacionada com um produto, uma empresa ou uma marca.', 'released', '["Planeador de Meios de Publicidade", "Planeadora de Meios de Publicidade", "Planejadora de Meios de Publicidade"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/b558a934-9308-48fc-b03b-bea8e23ab085', 'Fabricante de Membranofones', 'Os fabricantes de membranofones criam e montam peças para fabricar membranofones, de acordo com instruções ou diagramas especificados. Fazem parte e atribuem a membrana à estrutura do instrumento, testam a qualidade e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Membranofones"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/b560456a-bc4d-41a9-94c8-bf8636147246', 'Instrutor de Primeiros Socorros', 'Os instrutores de primeiros socorros lecionam medidas de socorro imediato em situações de emergência, como a reanimação cardiopulmonar, a posição de recuperação e o cuidado de lesões. Forneceram materiais práticos como manequins especiais.', 'released', '["Instrutor de Primeiros Socorros", "Instrutora de Primeiros Socorros"]'::jsonb, '3253'),
  ('http://data.europa.eu/esco/occupation/b567a979-c556-49fa-8b36-8af6cfe97624', 'Estivador', 'Os estivadores procedem à triagem, ao manuseamento, à carga e descarga de mercadorias em equipamento em estrada, em conformidade com as instruções orais e escritas, bem como com os regulamentos estatais. Movimentam mercadorias, tais como caixas, objetos volumosos, ou mesmo paletes grandes de mercadorias de e para zonas de armazenagem e para veículos de transporte.', 'released', '["Operária da Estiva", "Trabalhadora da Estiva", "Trabalhador da Estiva", "Operário da Estiva", "Estivadora"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/b5b8c259-7557-4f5f-9f56-155b038946c1', 'Operador de Equipamento Pesado em Minas a Céu Aberto', 'Os operadores de equipamento pesado em minas a céu aberto controlam equipamentos pesados, tais como escavadoras e caminhões basculantes, envolvendo frequentemente um elevado nível de consciência espacial, para escavar, carregar e transportar minério, mineral em bruto, incluindo areia, pedra e argila e terras mortas em pedreiras e minas a céu aberto.', 'released', '["Operador de Equipamento Pesado em Minas a Céu Aberto", "Operadora de Equipamento Pesado em Minas a Céu Aberto"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/b5d1912e-89c7-4a66-ab96-0dc5f4f6c426', 'Imunologista', 'Os imunologistas investigam o sistema imunitário dos organismos vivos (por exemplo, do corpo humano) e a forma como reage às infeções externas ou aos agentes nocivos invasivos (por exemplo, vírus, bactérias, parasitas). Centram o seu estudo nas doenças que afetam a imunologia dos organismos vivos, a fim de as classificar para tratamento.', 'released', '["Investigadora em Imunologia", "Investigador em Imunologia"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/b5d2db88-9e2b-4efa-8f2f-0e62a494791e', 'Especialista em Política Ambiental', 'Os especialistas em política ambiental investigam, analisam, desenvolvem e aplicam políticas relacionadas com o ambiente. Prestam aconselhamento especializado a entidades como organizações comerciais, agências governamentais e promotores imobiliários. Os especialistas em política ambiental procuram reduzir o impacto das atividades industriais, comerciais e agrícolas no ambiente.', 'released', '["Especialista em Política de Ambiente"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/b5d76ddd-f59a-491a-9543-f6c0e2d8a950', 'Representante de Posto de Turismo', 'Os representantes de posto de turismo atuam em nome da organizadora de excursões para dar informações práticas, prestar assistência, lidar com serviços e vender excursões a turistas nos seus destinos.', 'released', '["Representante de Posto de Turismo", "Representante de Serviço de Excursões", "Representantea de Posto de Turismo"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/b5e21e2b-ab0c-4c8d-8277-d98be4ad79c4', 'Inspetor de Aviônica', 'Os inspetores de aviónica inspecionam os instrumentos e os sistemas elétricos, mecânicos e eletrônicos das aeronaves, a fim de assegurarem a sua conformidade com o desempenho e as normas de segurança. Supervisionam igualmente os trabalhos de manutenção, reparação e revisão e reveem eventuais modificações com o objetivo de verificarem a sua conformidade com as normas e os procedimentos. Fornecem registos pormenorizados de inspeção, certificação e reparação.', 'released', '["Inspetor de Aviónica", "Inspetora de Aviónica", "Inspetora de Aviônica"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/b5eaf231-77ad-4a86-8e54-15cc4398aad2', 'Engenheiro de Processos', 'Os engenheiros de processos aplicam conceitos de engenharia, a fim de melhorar todos os tipos de produção e processos de fabrico em termos de eficiência e produtividade. Avaliam as variáveis e os condicionalismos existentes em determinados processos e apresentam soluções de engenharia para as otimizar.', 'released', '["Engenheira de Sistemas", "Engenheiro de Processos", "Engenheiro de Sistemas", "Engenheira da Processos", "Engenheira de Processos"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/b5f6bb2c-0602-484d-a87f-9cac33f83010', 'Condutor de Motociclos para Entregas', 'Os condutores de motociclos para entregas efetuam o transporte de todos os tipos de pacotes que contenham objetos, peças soltas, refeições preparadas, medicamentos e documentos que exijam um tratamento especial em termos de urgência, valor ou fragilidade. Transportam e entregam os pacotes por motociclo.', 'released', '["Condutora de Motociclos para Entregas", "Condutor de Motociclos para Entregas"]'::jsonb, '8321'),
  ('http://data.europa.eu/esco/occupation/b633af32-c8c0-4481-9971-7932ea4b16b5', 'Diretor Fabril na Indústria da Madeira', 'Os diretores fabris na indústria da madeira realizam tarefas de planejamento, comerciais e consultivas da fábrica de madeira e do comércio de madeira. Gerem igualmente a compra, a venda, o serviço ao cliente e a comercialização de madeira e de produtos de madeira.', 'released', '["Administradora de Fábrica de Madeiras", "Supervisor de Fábrica de Madeiras", "Diretor de Fábrica de Mobiliário", "Administrador de Fábrica de Madeiras", "Diretora de Fábrica de Mobiliário", "Diretor Fabril na Indústria da Madeira", "Supervisora de Fábrica de Madeiras", "Diretora Fabril na Indústria da Madeira"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/b65133db-b3de-44d1-88fa-1d3deda08245', 'Professor de Direito', 'Os professores de Direito são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, o Direito, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio do Direito, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor de Direito", "Professora de Direito", "Professor Universitário de Direito", "Professora Universitária de Direito"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/b65530b8-0b50-49da-8e9e-331b161374a5', 'Diretor de Informação', 'Os diretores de informação decidem sobre as notícias que serão alvo de cobertura nos noticiários. Nomeiam jornalistas para cada tema tratado. Os diretores de informação determinam também o tempo de cobertura para cada peça jornalística e a sua ordem de apresentação durante a transmissão.', 'released', '["Diretor de Informação", "Diretora de Informação"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/b66eb697-e65d-4bbb-b51c-d847f6875f1a', 'Gerente de Loja de Lavores', 'Os gerentes de lojas de lavores são responsáveis pelas atividades e pelo pessoal em lojas especializadas na venda de equipamentos e provisões para atividades artesanais, tais como costura, pintura ou cerâmica. Estes funcionários gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Loja de Patchwork", "Gerente de Atelier de Cerâmica", "Gerente de Loja de Bricolage", "Gerentea de Loja de Lavores"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/b674a89a-4439-4ad5-822d-518036415503', 'Vendedor de Tabaco', 'Os vendedores de tabaco vendem produtos de tabaco em lojas especializadas.', 'released', '["Vendedor de Tabaco", "Vendedora de Tabaco"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/b680251e-b3c7-4029-9849-66a95081801c', 'Tesoureiro de Banco', 'Os tesoureiros de banco supervisionam todos os aspetos da gestão financeira de um banco. Gerem a liquidez e a solvabilidade do banco. Gerem e apresentam os orçamentos atuais, reveem as previsões financeiras, preparam contas para a auditoria, gerem as contas do banco e mantêm registos exatos da documentação financeira.', 'released', '["Tesoureira de Instituição Financeira", "Tesoureiro de Banco", "Tesoureiro de Instituição Financeira", "Tesoureira de Banco"]'::jsonb, '1211'),
  ('http://data.europa.eu/esco/occupation/b69d9b94-a40c-434d-af8f-e584257314f6', 'Operador de Tratamento Térmico do Leite', 'Os operadores de tratamento térmico do leite utilizam equipamentos para efetuar diferentes métodos de pasteurização e/ou esterilização de produtos lácteos líquidos. Operam equipamentos, tais como as bombas de reforço de produtos em bruto, homogeneizadores, equipamento de controlo do aroma, clarificadoras, separadores, bombas auxiliares e filtros.', 'released', '["Técnica de Tratamento Térmico do Leite", "Operadora de Tratamento Térmico do Leite", "Operadora de Tratamento Térmico da Coalhada", "Técnico de Tratamento Térmico do Leite", "Operador de Tratamento Térmico da Coalhada", "Operador de Tratamento Térmico do Leite"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/b6a62e85-5ffe-41aa-8f2a-9959365dfe85', 'Operador de Máquinas de Fabricação de Tijolos e Telhas', 'Os operadores de máquinas de fabrico de tijolos e telhas procedem à operação e manutenção de máquinas utilizadas na produção de tijolos e telhas.', 'released', '["Operadora de Máquinas de Fabricação de Tijolos e Telhas", "Operadora de Máquinas de Mistura de Argila", "Operador de Máquinas de Mistura de Argila", "Operador de Máquinas de Fabricação de Tijolos e Telhas"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/b6beb46d-9ed2-4a66-9117-7e3f21f234dd', 'Educador de Ensino Especial', 'Os educadores de ensino especial proporcionam um ensino especialmente concebido para os alunos com uma variedade de deficiências ao nível dos jardins de infância e asseguram que os mesmos atingem o seu potencial de aprendizagem. Alguns educadores de ensino especial trabalham com crianças com deficiências ligeiras a moderadas, implementando um programa de estudos alterado para responder às necessidades específicas de cada estudante. Outros educadores de ensino especial assistem e ensinam alunos portadores de deficiência intelectual e autismo, centrando-se no ensino da literacia básica e em competências de vida e sociais. Todos os professores avaliam os progressos dos alunos, tendo em conta os seus pontos fortes e fracos, e comunicam as suas conclusões aos pais, conselheiros, administradores e outras partes envolvidas.', 'released', '["Educador do Ensino Especial", "Educadora de Infância de Educação e Ensino Especial", "Educadora de Educação Especial", "Educadora do Ensino Especial", "Educador de Infância de Educação e Ensino Especial", "Educador de Educação Especial", "Educadora de Ensino Especial"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/b6c851d1-bf09-40aa-aa50-47dde84e7d50', 'Professor de Artes Circenses', 'Os professores de artes circenses ensinam aos alunos as várias técnicas e números de circo, tais como números de trapézio, malabarismos, mimetismo, acrobacias, bambolé, equilibrismo, manipulação de objetos, acrobacias em bicicleta, etc., num contexto recreativo. Proporcionam aos alunos uma noção da história e do repertório circenses, mas centram-se sobretudo numa abordagem prática na suas aulas, nas quais ajudam os alunos a experimentar e a dominar diferentes técnicas, estilos e números circenses e a desenvolver o seu próprio estilo. Criam, dirigem e produzem espetáculos de circo e coordenam a produção técnica e o eventual palco, adereços e trajes.', 'released', '["Professora de Circo", "Professora de Artes Circenses", "Professor de Artes Circenses", "Professor de Circo"]'::jsonb, '2355'),
  ('http://data.europa.eu/esco/occupation/b6f4573d-659f-49ca-a885-850a48d01913', 'Representante de Vendas de Máquinas e Equipamentos Industriais', 'Os representantes de vendas de máquinas e equipamentos industriais prestam serviços em nome de uma empresa para vender as suas mercadorias, fornecendo simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Máquinas e Equipamentos Industriais"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/b73c752b-9858-4f53-82de-f3a340cbcae9', 'Epidemiologista', 'Os epidemiologistas centram a sua investigação na origem e nas causas da erupção de doenças nos seres humanos. Determinam a forma como as doenças são disseminadas e propõem medidas de prevenção dos riscos aos organismos da política de saúde.', 'released', '["Epidemióloga", "Epidemiólogo"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/b73f4ce5-13fa-43a0-bbf6-01d7315849b8', 'Coordenador de Serviço de Ação Social', 'Os coordenadores de serviço de ação social gerem os processos de ação social através da investigação de casos de alegada negligência ou abuso. Realizam avaliações da dinâmica familiar e prestam assistência a pessoas doentes ou com distúrbios emocionais ou mentais. Formam, prestam assistência, aconselham, avaliam e atribuem tarefas a assistentes sociais subordinados, assegurando que todo o trabalho é realizado de acordo com as políticas, a legislação, os procedimentos e as prioridades estabelecidos.', 'released', '["Coordenador de Serviço de Ação Social", "Coordenadora de Serviço de Ação Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/b7474960-a03e-46c3-88ce-81575cb8f657', 'Diretor de Distribuição Perfumaria e Cosméticos', 'Os diretores de distribuição perfumaria e cosméticos planificam a distribuição de perfumes e cosméticos a vários pontos de venda.', 'released', '["Diretora de Logística Perfumaria e Cosméticos", "Diretor de Distribuição Perfumaria e Cosméticos", "Diretora de Distribuição Perfumaria e Cosméticos", "Diretor de Logística Perfumaria e Cosméticos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/b7507136-e71e-47e8-b873-e77d5cdf2922', 'Assistente Social Especialista em Trabalho com Jovens', 'Os assistentes sociais especialistas em trabalho com jovens apoiam, acompanham e aconselham os jovens, focalizando-se no seu desenvolvimento pessoal e social. Participam na gestão de projetos e serviços comunitários mediante atividades com jovens, individualmente ou em grupos. Os assistentes sociais especialistas em trabalho com jovens podem ser voluntários ou profissionais remunerados que facilitam processos de aprendizagem não formal e informal. Estão envolvidos num vasto espetro de atividades por, com e para jovens.;', 'released', '["Assistentea Social Especialista em Trabalho com Jovens"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/b76178c0-a03a-4793-b079-1e61e636c521', 'Especialista em Desenvolvimento de Negócio', 'Os especialistas em desenvolvimento de negócios procuram aumentar a quota de mercado das empresas no mercado. Realizam análises estratégicas das principais vantagens que os produtos ou serviços de uma empresa têm para oferecer, cooperam no desenvolvimento de campanhas de marketing para a captação de potenciais clientes e prestam apoio às ações de vendas.', 'released', '["Business Developer"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/b7744a45-a4ce-4037-b679-3d2377e17f31', 'Gerente de Supermercado', 'Os gerentes de supermercados são responsáveis pelas atividades e pelo pessoal num supermercado.', 'released', '["Gerente de Hipermercado", "Gerente de Loja de Conveniência", "Gerente de Loja Gourmet", "Gerentea de Supermercado"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/b789dae6-6c77-4f46-9253-098c424c92f2', 'Especialista em Import-Export de Peixes, Crustáceos e Moluscos', 'Os especialistas em import-export de peixes, crustáceos e moluscos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Peixes, Crustáceos e Moluscos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/b79cfd33-6e46-4b71-b180-c9a84422f047', 'Sismólogo', 'Os sismólogos analisam o movimento das placas tectónicas da Terra, que provocam a propagação de ondas sísmicas e sismos. Estudam e observam as diversas fontes que provocam sismos, como a atividade vulcânica, fenômenos atmosféricos ou o comportamento dos oceanos. Fornecem as suas observações científicas para prevenir os perigos na construção e nas infraestruturas.', 'released', '["Investigadora Científica em Sismologia", "Sismólogo", "Investigador Científico em Sismologia", "Sismóloga"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/b7aa4b4e-dbb6-4f58-b36c-35b9a7267972', 'Técnico de Reparações de Hardware Informático', 'Os técnicos de reparações de hardware informático instalam, analisam, testam e reparam equipamento informático e componentes periféricos. Testam o funcionamento dos computadores, identificam os problemas e substituem peças e componentes danificados.', 'released', '["Técnica de Reparações de Hardware Informático", "Técnico de Reparações de Hardware Informático"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/b7b17a85-ccd0-4d2f-92f2-7e99839731b0', 'Cientista Biomédico', 'Os cientistas de biomedicina avançada realizam investigação translacional avançada no domínio das ciências laboratoriais biomédicas e exercem funções de educadores da sua profissão ou de outros profissionais, bem como de consultores neste domínio.', 'released', '["Cientista Biomédica", "Cientista Biomédico"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/b7b75eb6-34bc-462d-b412-eed393cc1397', 'Empregado de Centro de Informações ao Cliente', 'Os empregados de centro de informações ao cliente fornecem informações aos clientes através do telefone e de outros meios de comunicação, tal como o correio eletrônico. Respondem a pedidos de informação sobre os serviços, produtos e políticas da empresa ou da organização.', 'released', '["Empregado de Centro de Informações ao Cliente", "Empregada de Centro de Informações ao Cliente"]'::jsonb, '4222'),
  ('http://data.europa.eu/esco/occupation/b7f47c25-bdf3-42fa-a68e-ad32754b2dba', 'Analista de Investimentos', 'Os analistas de investimentos efetuam pesquisas para apresentarem recomendações informadas a gestores de fundos. Pesquisam investimentos a nível mundial, mas, dependendo da natureza e da área de atividade do seu empregador, podem especializar-se em domínios como o retalho, as infraestruturas, a energia, a banca e os serviços financeiros. Centram-se em informações financeiras e econômicas, como os desenvolvimentos políticos e econômicos que podem afetar os mercados financeiros e o desempenho financeiro das empresas-alvo, e utilizam a interpretação de dados de diferentes fontes para compreender a forma como afetam a tomada de decisões de investimento.', 'released', NULL, '2413'),
  ('http://data.europa.eu/esco/occupation/b7fc1cd1-0d6d-4e9e-8a9f-c3270201be81', 'Operador de Câmbios', 'Os operadores de câmbios processam transações em numerário de clientes em moeda nacional e estrangeira. Fornecem informações sobre as condições e as taxas de câmbio para a compra e venda de moeda estrangeira, realizam de depósitos em dinheiro, registam todas as transações em moeda estrangeira e verificam a validade da moeda.', 'released', '["Operador de Câmbios", "Operadora de Câmbios"]'::jsonb, '4312'),
  ('http://data.europa.eu/esco/occupation/b8139469-92cc-4f57-9e69-a0d9f7fc3817', 'Instrutor do Curso de Formação de Bombeiros Profissionais', 'Os instrutores do curso de formação de bombeiros profissionais prestam formação aos novos recrutas ou cadetes sobre a teoria e a prática necessárias para se tornarem bombeiros. Ministram aulas teóricas sobre temas académicos como o direito, química elementar, as regulamentos de segurança, gestão dos riscos, prevenção de incêndios, leitura de plantas, etc.. relações comunitárias e a diversidade humana. Os instrutores do curso de formação de bombeiros profissionais também fornecem instruções mais práticas sobre a utilização de equipamentos de assistência e ferramentas de salvamento, como a mangueira de incêndio, o machado de incêndio, a máscara de fumo, etc., mas também treino física exigente, técnicas de respiração, primeiros socorros, táticas de autodefesa e operações de veículos. Além disso, preparam e desenvolvem planos de aulas e novos programas de formação à medida que surgem novos regulamentos e desenvolvimentos em matéria de serviços públicos. Os instrutores acompanham o progresso dos alunos, avaliam-nos individualmente e elaboram relatórios de avaliação do desempenho.', 'released', '["Instrutor do Curso de Formação de Bombeiros Profissionais", "Instrutora do Curso de Formação de Bombeiros Profissionais"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/b864c9a3-ef6e-46a0-a40c-66188f74dfa7', 'Coronel', 'Os coronéis prestam serviço nos corpos de comando militar e funcionam como conselheiros principais dos oficiais superiores na tomada de decisões operacionais e estratégicas.', 'released', '["Tenente-Coronel", "Comandante de Batalhão", "Tenente-Coronel da Força Aérea"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/b865693a-eb11-44cc-bf6c-38e5b4d7e169', 'Arboricultor', 'Os arboricultores realizam tarefas especializadas relacionadas com a observação, a saúde e a manutenção das árvores.', 'released', '["Arborista", "Silvicultor", "Silvicultora", "Especialista no Cultivo de Árvores", "Arboricultor", "Arboricultora"]'::jsonb, '6112'),
  ('http://data.europa.eu/esco/occupation/b866b3bb-3dbd-4b3d-9a53-9ec15f43ca2f', 'Colunista', 'Os colunistas investigam e redigem artigos de opinião sobre acontecimentos noticiosos para jornais, revistas especializadas, revistas e outros meios de comunicação social. Têm uma área de interesse e podem ser reconhecidos pelo seu estilo de escrita.', 'released', NULL, '2642'),
  ('http://data.europa.eu/esco/occupation/b874b541-2cb3-460b-96d7-4f83fe04b41d', 'Técnico de Bondes', 'Os técnicos de elétricos realizam operações de manutenção para prevenir e reparar danos em ascensores ou teleféricos. Utilizam equipamento específico, mantêm um registo das atividades e respeitam os procedimentos e práticas de segurança, como as evacuações de emergência e as operações de salvamento. Podem recusar o acesso à instalação se as condições não permitirem a sua utilização segura.', 'released', '["Técnica de Bondes", "Técnico de Bondes"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/b87a7a27-ee74-4e5e-b274-84a3cab27bf4', 'Diretor de Importação e Exportação', 'Os diretores de importação e exportação implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Exportação", "Diretor de Importação", "Diretora de Logística", "Diretor de Logística", "Diretora de Exportação", "Diretora de Importação", "Diretor de Importação e Exportação", "Assistente de Logística", "Assistente de Exportação", "Diretora de Importação e Exportação"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/b89ba3a8-f03a-46b8-ac54-c87d7204aad0', 'Porta-Voz', 'Os porta-vozes falam em nome de empresas ou organizações. Utilizam estratégias de comunicação para representarem os clientes através de anúncios públicos e conferências. Promovem os seus clientes numa perspetiva positiva e trabalham no sentido de aumentar a compreensão das suas atividades e interesses.', 'released', NULL, '2432'),
  ('http://data.europa.eu/esco/occupation/b89f5984-3fb7-4339-80d5-00d1b0750b53', 'Chefe de Sala de Jogos de Casino', 'Os chefes de sala de jogos de casino apoiam a equipe de gestão e gerem, inspecionam e lidam com todas as atividades de jogo. Supervisionam a exploração dos jogos de azar e são responsáveis por influenciar a despesa e o rendimento per capita para atingir a margem necessária, assegurando ao mesmo tempo que os padrões mais elevados de eficiência, segurança e assinatura sejam alcançados em conformidade com todos os procedimentos da empresa e a legislação em vigor.', 'released', '["Supervisor de Sala de Jogos de Casino", "Supervisora de Sala de Jogos de Casino", "Chefe de Partida", "Pit Boss", "Chefea de Sala de Jogos de Casino"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/b8b98b65-7db2-43f8-8ac4-2f1903984e7b', 'Agente Municipal', 'Os agentes municipais patrulham as ruas para impor restrições de estacionamento, assegurar a livre circulação do tráfego, garantir a segurança dos peões e assegurar o cumprimento das leis de trânsito e de estacionamento. Contribuem para a luta contra a criminalidade e para a redução da criminalidade, prestando assistência em caso de incidentes e prestando serviços de patrulha.', 'released', '["Agentea Municipal"]'::jsonb, '5419'),
  ('http://data.europa.eu/esco/occupation/b8db7ef4-4057-4e88-8e2a-105b4b59fb67', 'Técnico de Sistemas de Frenagem Automóvel', 'Os técnicos de sistemas de travagem automóvel procedem à manutenção, manutenção, diagnóstico e reparação dos sistemas de travagem, direção e suspensão, bem como rodas e pneus.', 'released', '["Técnico de Sistemas de Travagem Automóvel", "Técnica de Sistemas de Travagem Automóvel", "Técnica de Sistemas de Frenagem Automóvel"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/b91034a0-1d3e-40e4-aced-07052ee0f9e9', 'Operador de Fabricação de Rações para Animais', 'Os operadores de fabrico de rações para animais asseguram o correto funcionamento de várias máquinas de processamento de alimentos para animais em instalações industriais, tais como máquinas de mistura, máquinas de enchimento e máquinas de carga.', 'released', '["Operadora de Produção de Alimentos para Animais", "Operador de Fabricação de Rações para Animais", "Operadora de Fabricação de Rações para Animais", "Operador de Produção de Alimentos para Animais"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/b915ab4a-f7b1-44bc-a5a4-585e91d31dfd', 'Gestor de Aquisição de Propriedades', 'Os gestores de aquisição de propriedades asseguram as transações referentes à aquisição de terrenos ou propriedades. Estabelecem contatos com as partes interessadas pertinentes sobre os aspetos financeiros e os riscos decorrentes da aquisição das propriedades. Os gestores de aquisição de propriedades asseguram o cumprimento dos requisitos legais em matéria de aquisição de bens e tratam de toda a documentação e das técnicas de conclusão de processo necessárias.', 'released', '["Gestor de Aquisição de Propriedades", "Gestora de Aquisição de Propriedades", "Gerente"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/b9296f1a-a68b-4ac7-9904-f2cf1374fbaf', 'Analista de Resistência dos Materiais', 'Os analistas de resistência dos materiais planeiam e utilizam software para realizar análises estruturais, incluindo análises de estática, de estabilidade e de fadiga em várias máquinas. Efetuam a análise das estruturas primárias e secundárias. Elaboram relatórios técnicos para documentar os resultados das suas análises, participam em revisões de projetos e recomendam melhorias para o processo. Além disso, prestam assistência no desenvolvimento de planos de ensaios estruturais.', 'released', NULL, '3115'),
  ('http://data.europa.eu/esco/occupation/b94e2f4c-6604-46a9-bc72-160fc9d2cf36', 'Comerciante Grossista de Metais e Minerais Metálicos', 'Os comerciantes grossistas de metais e minerais metálicos investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Metais e Minerais Metálicos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/b95bdbed-1e7e-482a-aa73-7bdbb3e36358', 'Gestor de Fundos de Investimento', 'Os gestores de fundos de investimento implementam e controlam a estratégia de investimento de um fundo. Gerem as atividades de negociação da carteira do fundo e supervisionam os analistas financeiros, de valores mobiliários e de investimentos responsáveis por analisarem as possibilidades de investimento, emitindo, de seguida, recomendações de compra e de venda. Tomam decisões sobre quando comprar ou vender os ativos incluídos numa carteira. Trabalham numa variedade de contextos, tais como bancos, veículos de investimento e empresas de corretagem, colaborando de perto com o analista de investimentos. Este profissional gere a estratégia e nem sempre trata das relações entre os acionistas ou investidores.;', 'released', '["Gestor de Fundos de Investimento", "Gestora de Fundos de Investimento", "Gerente"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/b9711647-463f-4991-a858-d5de66ff2f83', 'Promotor Imobiliário', 'Os promotores imobiliários compram terras, financiam negócios, encomendam projetos de construção e organizam o processo de desenvolvimento. Compram terrenos, decidem sobre as estratégias de marketing e desenvolvem os programas de construção. Os promotores têm também de obter autorizações legais e financiamento. Terminado o projeto, podem alugar, gerir ou vender os imóveis.', 'released', '["Medidador Imobiliário", "Construtora Imobiliária", "Promotor Imobiliário", "Especulador Imobiliário", "Construtor Imobiliário", "Especuladora Imobiliária", "Promotora Imobiliária", "Mediadora Imobiliária", "Promotora Imobiliário"]'::jsonb, '1323'),
  ('http://data.europa.eu/esco/occupation/b972feaa-e2a6-4b22-9de4-18040f3f04eb', 'Representante de Serviço de Aluguel de Máquinas e Equipamentos Agrícolas', 'Os representantes de serviço de aluguer de máquinas e equipamentos agrícolas são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Máquinas e Equipamentos Agrícolas"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/b9836ed2-1ca7-49b4-9f0e-bb5d2ca14443', 'Coordenador de Manutenção dos Veículos de Transporte Rodoviário', 'Os coordenadores de manutenção dos veículos de transporte rodoviário são responsáveis pela execução efetiva de todos os processos de controlo do trabalho de manutenção dos veículos de transporte urbano, bem como pela utilização eficiente e eficaz do planejamento e pela programação de todos os recursos para a realização de atividades de manutenção.', 'released', '["Coordenador de Manutenção de Veículos de Transporte Ferroviário", "Coordenadora de Manutenção de Veículos de Transporte Ferroviário", "Coordenadora de Manutenção dos Veículos de Transporte Rodoviário"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/b997a091-23b3-4f87-a6bc-bdbea2f609ae', 'Operador de Fermentação de Vinho', 'Os operadores de fermentação de vinho cuidam de cubas para fermentar a fruta esmagada ou o mosto em vinhos. Descarregam quantidades especificadas de fruta esmagada em cubas de vinho e misturam com xarope, produtos químicos ou levedura. Impedem o crescimento das bactérias durante a fermentação.', 'released', '["Operador de Fermentação de Vinho", "Operadora de Instalação de Fermentação de Vinho", "Operador de Destilagem de Vinho", "Operadora de Destilagem de Vinho", "Operadora de Fermentação de Vinho", "Operador de Instalação de Fermentação de Vinho"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/b9b47087-6045-405d-b769-6a0c94e2eb84', 'Gestor de Serviços de Visitantes em Espaços Culturais', 'Os gestores de serviços de visitantes em espaços culturais são responsáveis por todos os programas, atividades, estudos e investigação relativos à apresentação dos artefactos ou programas de um espaço cultural aos visitantes atuais e futuros.;', 'released', '["Gerente", "Gestora de Serviços de Visitantes em Espaços Culturais"]'::jsonb, '2621'),
  ('http://data.europa.eu/esco/occupation/b9c80d74-97b6-4a4b-849e-a3908ba57ae1', 'Calibrador de Chapas de Madeira', 'Os calibradores de chapas de madeira inspecionam a qualidade de chapas de madeira. Procuram irregularidades, defeitos e erros de produção e calibram as tábuas de acordo com a conveniência dos padrões.', 'released', '["Calibradora de Chapas de Madeira", "Calibrador de Chapas de Madeira"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/b9d03330-c71c-4827-8797-3e96249d54db', 'Entalhador de Madeira', 'Os entalhadores de madeira dão forma, manualmente, à madeira, na forma desejada, utilizando equipamentos, tais como facas, goivas e cinzéis. Os entalhadores de madeira produzem produtos de madeira para servir de decoração, para integrar num produto composto, como utensílios ou como brinquedos.', 'released', '["Entalhador de Madeira", "Entalhadora de Madeira", "Escultor de Madeira", "Escultora de Madeira"]'::jsonb, '7317'),
  ('http://data.europa.eu/esco/occupation/b9dd2ee7-5fea-46f8-b226-ddae9501f728', 'Conselheiro em Violência Sexual', 'Os conselheiros em violência sexual prestam serviços de apoio, bem como serviços de assistência e aconselhamento em situações de crise a mulheres e adolescentes que tenham sido direta ou indiretamente expostas a agressões e/ou a violações sexuais. Informam as vítimas dos procedimentos legais e dos serviços de proteção pertinentes, mantendo o sigilo sobre os utentes. Também tratam de comportamentos sexuais problemáticos de crianças.', 'released', '["Assistente Social de Apoio à Vítima", "Conselheiro em Violência Sexual", "Conselheira em Violência Sexual"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/b9de6d8b-1cf6-4722-bf8c-d73aad03bf87', 'Cozinheiro de Pratos de Peixe', 'Os cozinheiros de pratos de peixe são responsáveis pela preparação e apresentação de pratos de peixe através de diversas técnicas. Também podem preparar os molhos e comprar peixe fresco para esses pratos.', 'released', '["Cozinheira de Pratos de Peixe", "Cozinheiro de Pratos de Peixe"]'::jsonb, '5120'),
  ('http://data.europa.eu/esco/occupation/b9e51ff4-d7fb-4653-bc72-65086ffc6e65', 'Consultor em Viticultura', 'Os consultores em viticultura prestam aconselhamento sobre a melhoria da produção vitícola e da vinificação.', 'released', '["Consultora em Viticultura", "Consultor em Viticultura"]'::jsonb, '3142'),
  ('http://data.europa.eu/esco/occupation/ba1e5427-46e0-4b6c-b196-5312d136dd3b', 'Especialista em Import-Export de Máquinas para a Indústria Extrativa, Construção e Engenharia Civil', 'Os especialistas em import-export de máquinas para a indústria extrativa, construção e engenharia civil possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Máquinas para a Indústria Extrativa, Construção e Engenharia Civil"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/ba3bacd4-73e9-4861-a9c0-f89f1f28055a', 'Diretor de Obra', 'Os diretores de obra assumem a responsabilidade de realizar um projeto de construção. Participam nos processos de candidatura a projetos de construção e contratam subcontratantes para realizar as diferentes fases do processo de construção desde o início até à sua conclusão. Certificam-se de que os subcontratantes cumprem a sua parte do acordo e trabalham no estaleiro de construção para garantir que o projeto é finalizado a tempo e de acordo com as normas acordadas.', 'released', '["Diretora de Obra", "Diretor de Obra"]'::jsonb, '1323'),
  ('http://data.europa.eu/esco/occupation/ba490796-46f7-45b7-827b-db6882fca3e1', 'Engenheiro de Energia Eólica Terrestre', 'Os engenheiros de energia eólica terrestre concebem, instalam e procedem à manutenção de parques e equipamentos eólicos. Estudam e testam locais para encontrar o sítio mais produtivo, testam o equipamento e os componentes como lâminas de turbinas eólicas, e desenvolvem estratégias para uma produção de energia mais eficiente e a para a sustentabilidade ambiental.;', 'released', '["Especialista em Engenharia de Tecnologia de Energia Eólica Onshore", "Engenheiro de Sistemas de Energia Eólica Onshore", "Especialista em Energia Eólica Onshore", "Engenheiro de Energia Eólica Onshore", "Engenheira de Energia Eólica Onshore", "Especialista em Engenharia de Energia Eólica Onshore", "Engenheira de Sistemas de Energia Eólica Onshore", "Engenheira de Energia Eólica Terrestre"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/baae6dd1-4a59-480d-83b1-a0708a5a1736', 'Diretor Geral dos Transportes Marítimos', 'Os diretores gerais dos transportes marítimos coordenam as atividades administrativas ligadas à gestão dos navios no contexto do transporte marítimo. Preparam os navios, verificam a disponibilidade, asseguram a ligação com os clientes, gerem os orçamentos e supervisionam as operações de um ponto de vista econômico, no cumprimento da regulamentação das operações marítimas.', 'released', '["Diretor Geral dos Transportes Fluviais", "Diretor Geral dos Transportes Marítimos", "Diretora Geral dos Transportes Marítimos", "Diretora Geral dos Transportes Fluviais"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/bab5fa79-7f96-4e21-87b6-1eba560b8d9a', 'Modelador 3D', 'Os modeladores desenham modelos 3D de objetos, ambientes virtuais, planos, personagens e animações virtuais 3D.', 'released', '["Modelador de Imagens Geradas por Computador", "Artista 3D", "Modeladora de CGI", "Modelador 3D", "Modelador de CGI", "Modeladora de IGC", "Modeladora de Imagens Geradas por Computador", "Modelador de IGC", "Modeladora 3D"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/bac62d45-bb74-45fa-9b38-a3ebf2095212', 'Gestor de Processos Jurídicos', 'Gerencia processos judiciais e administrativos, acompanhando prazos, audiências, documentos e etapas processuais desde a abertura até o encerramento. Analisa autos e a legislação aplicável, controla a conformidade e a tempestividade dos atos e mantém a comunicação com advogados, tribunais e áreas internas. Atua com gestão de processos jurídicos, acompanhamento processual e compliance legal.', 'released', '["Gestor de Processos Jurídicos", "Responsável de Processos", "Gestor de Processos Judiciais", "Analista de Processos Jurídicos", "Assistente Jurídico de Processos", "Coordenador de Processos Jurídicos", "Gestor de Processos Penais e Cíveis", "Analista de Acompanhamento Processual", "Gerente", "Gestora de Processos Jurídicos"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/bac64fa2-dcd6-47bb-8e5c-04e04a86a199', 'Geógrafo', 'Os geógrafos são indivíduos que estudam a geografia humana e física. Em função da sua especialização, estudam os aspetos políticos, econômicos e culturais da humanidade englobados na geografia humana. Além disso, estudam as formações terrestres, os solos, as fronteiras naturais e os cursos de água, pertencentes ao domínio da geografia física.', 'released', '["Geógrafa", "Geógrafo"]'::jsonb, '2632'),
  ('http://data.europa.eu/esco/occupation/bafbc672-0ad9-41af-9de8-db0c91a24f9b', 'Operador de Faturação', 'Os operadores de faturação elaboram notas de crédito, faturas e declarações mensais, emitindo-as aos clientes por todos os meios necessários. Atualizam os arquivos dos clientes em conformidade.;', 'released', '["Operador de Faturação", "Operadora de Faturação"]'::jsonb, '4311'),
  ('http://data.europa.eu/esco/occupation/bb131b09-5fdf-4f4f-a76c-402c69cd090a', 'Operador de Produção de Pasta de Papel', 'Os operadores de produção de pasta de papel desempenham tarefas técnicas na produção de pasta de papel. Trabalham em equipes de produção de pasta de papel procedendo à manutenção das máquinas, resolvem avarias técnicas e asseguram que o processo de produção decorre em conformidade com as especificações.', 'released', '["Operador de Produção de Pasta de Papel", "Operadora de Produção de Pasta de Papel"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/bb2933e9-f6ec-4ab0-b2ea-3cc34cf56d18', 'Operador de Máquinas de Galvanoplastia', 'Os operadores de máquinas de galvanoplastia instalam e asseguram o correto funcionamento de máquinas de galvanoplastia concebidas para acabamento e revestimento da superfície do metal (tais como moedas e joias), utilizando a corrente elétrica para dissolver os catiões metálicos e ligar uma camada fina de outro metal, tal como zinco, cobre ou prata, para produzir uma camada de metal coerente na superfície da peça.', 'released', '["Operadora de Máquinas de Galvanoplastia", "Operador de Máquinas de Galvanoplastia"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/bb4ca5c1-879d-44e8-840d-24f320206bff', 'Administrador de Subvenções', 'Os administradores de subvenções são os intermediários na via de concessão de subvenções, frequentemente atribuídas pelo governo ao beneficiário da subvenção. Preparam a documentação, como os pedidos de subvenção, e concedem as subvenções. São igualmente responsáveis por assegurar que o beneficiário da subvenção gasta corretamente o dinheiro em conformidade com as condições estabelecidas.', 'released', '["Administradora de Subvenções", "Administrador de Subvenções"]'::jsonb, '3313'),
  ('http://data.europa.eu/esco/occupation/bb609566-3ab6-44dd-8f48-cf0b15b96827', 'Engenheiro de Automação', 'Os engenheiros de automação investigam, concebem e desenvolvem aplicações e sistemas para a automatização do processo de produção. Executam a tecnologia e reduzem, sempre que aplicável, a contribuição humana para alcançar todo o potencial da robótica industrial. Os engenheiros de automação supervisionam o processo e asseguram que todos os sistemas funcionam com segurança e sem problemas.', 'released', '["Engenheira de Automação", "Engenheiro de Automação"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/bb95ef58-9139-4967-bfc1-da8386a4e672', 'Comprador de Produtos e Serviços Informáticos', 'Os compradores de produtos e serviços informáticos criam e colocam ordens de compra de produtos e serviços informáticos, tratam de assuntos relacionados com a recepção e faturas, avaliam as práticas correntes em matéria de aquisições e aplicam efetivamente metodologias de aquisição estratégica. Estabelecem relações com os vendedores estratégicos e negoceiam os preços, a qualidade, os níveis de serviços e as condições de entrega.', 'released', '["Compradora de Produtos Informáticos", "Comprador de Serviços e Produtos Informáticos", "Compradora de Produtos e Serviços Informáticos", "Comprador de Serviços Informáticos", "Comprador de Produtos e Serviços Informáticos", "Compradora de Serviços Informáticos", "Compradora de Serviços e Produtos Informáticos", "Comprador de Produtos Informáticos"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/bbaa1444-2c0a-4f76-8375-d72e3ea968fd', 'Cozinheiro de Grelhados', 'Os cozinheiros de grelhados preparam e apresentam carne, produtos hortícolas e peixe utilizando equipamentos de grelhar, tais como grelhas e assadores.', 'released', '["Cozinheira de Grelhados", "Cozinheiro de Grelhados"]'::jsonb, '5120'),
  ('http://data.europa.eu/esco/occupation/bbba890e-ecae-43ba-9c5b-a65baa318f15', 'Diretor de Importação e Exportação de Máquinas-Ferramentas', 'Os diretores de importação e exportação de máquinas-ferramentas implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Máquinas-Ferramentas", "Diretora de Importação e Exportação de Máquinas-Ferramentas", "Diretor de Importação e Exportação de Máquinas-Ferramentas", "Diretor de Vendas de Máquinas-Ferramentas"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/bbd1fe06-1b55-4937-9317-fc162311ab38', 'Brigadeiro', 'Os brigadeiros comandam grandes unidades de tropas chamadas brigadas, supervisionam o planejamento estratégico e tático e controlam as operações da respetiva brigada. Gerem os quartéis-generais da divisão da brigada e asseguram o funcionamento correto da divisão na base e no terreno.', 'released', '["Brigadeiro-General da Força Aérea", "Brigadeiro-General", "Brigadeiro-General doExército", "Brigadeira"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/bbefa1b2-521e-4d87-a7ad-9bbd0b32e271', 'Avaliador de Imóveis', 'Os avaliadores de imóveis realizam trabalhos de investigação para avaliar o valor dos bens para efeitos fiscais. Investigam várias imóveis de uma só vez, com recurso a técnicas de avaliação precisas. Normalmente, prestam os seus serviços a organismos locais e governamentais por razões fiscais.', 'released', '["Avaliadora de Imóveis", "Avaliador de Imóveis"]'::jsonb, '3315'),
  ('http://data.europa.eu/esco/occupation/bc1748c7-29d6-43d5-a304-6b74f317ac26', 'Responsável de Canil', 'Os responsáveis de canil acompanham as operações diárias do canil sob a sua supervisão. Asseguram que os animais mantidos em canis estão a ser devidamente manuseados e tratados. Os responsáveis de canil supervisionam o pessoal e mantêm contato com os proprietários dos animais de companhia quando estes os deixam ou recolhem.', 'released', NULL, '5164'),
  ('http://data.europa.eu/esco/occupation/bc1c82a5-0fc3-453f-8537-9d1a6e9e85aa', 'Engenheiro Civil Especialista no Planejamento de Aeroportos', 'Os engenheiros civis especialistas na planificação de aeroportos gerem e coordenam programas de planejamento, concepção e desenvolvimento nos aeroportos.', 'released', '["Engenheiro Civil Especialista no Desenvolvimento de Aeroportos", "Engenheira Civil Especialista no Desenvolvimento de Aeroportos", "Engenheiro Civil Especialista na Planificação de Aeroportos", "Engenheira Civil Especialista na Planificação de Aeroportos", "Engenheira Civil Especialista no Planejamento de Aeroportos"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/bc4d1659-6860-488e-bc13-e87eb0e36f67', 'Designer de Mobiliário', 'Os designers de mobiliário trabalham em mobiliário e produtos afins. Concebem o produto e estão envolvidos na sua produção como artesãos, criadores ou fabricantes. A concepção do mobiliário combina um design inovador, requisitos funcionais e apelo estético.', 'released', '["Designer de Móveis"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/bc61af54-0c3b-411c-a434-4b0d23c6fcce', 'Instalador de Cozinhas', 'Os instaladores de cozinhas instalam elementos de cozinha nas casas. Efetuam as medições necessárias, preparam a divisão, retirando elementos antigos, se necessário, e instalam os novos equipamentos de cozinha, incluindo as ligações de canos da água, do gás, do saneamento e da eletricidade.', 'released', '["Instalador de Cozinhas", "Montadora de Cozinhas", "Instaladora de Cozinhas", "Montador de Cozinhas"]'::jsonb, '7115'),
  ('http://data.europa.eu/esco/occupation/bc61e0de-2d72-471c-90c1-a9fe371020f9', 'Operador de Prensa Mecânica', 'Os operadores de prensa mecânica instalam e cuidam de prensas mecânicas, concebidas para moldar peças de metal ferroso e não ferroso, incluindo canos, tubos e perfis ocos e outros produtos da primeira transformação de aço na forma desejada, através da utilização de forças de compressão predeterminadas, fornecidas por manivelas, cames e alavancas, em tempos reprodutíveis.', 'released', '["Operadora de Prensa Mecânica", "Operador de Prensa Mecânica"]'::jsonb, '7221'),
  ('http://data.europa.eu/esco/occupation/bc659adc-f42c-4ef6-89fe-fd030033f446', 'Cosmólogo', 'Os cosmólogos centram-se no estudo do universo no seu conjunto, constituído pela sua origem, evolução e destino final. Utilizam ferramentas e instrumentos científicos para observar e estudar outras galáxias e objetos astronómicos, tais como estrelas, buracos negros, planetas e outros corpos celestes.', 'released', '["Cosmólogo", "Cosmologista", "Cosmóloga"]'::jsonb, '2111'),
  ('http://data.europa.eu/esco/occupation/bc6649ff-05f8-4c98-9db6-9be0d13883a9', 'Operador de Máquina de Corte a Laser', 'Os operadores de máquinas de corte a laser instalam, programam e cuidam de máquinas de corte a laser, concebidas para cortar, ou antes queimar e fundir, material em excesso de uma peça metálica direcionando um poderoso feixe laser controlado por computador através de óticas laser. Interpretam os esquemas da máquina de corte a laser e as instruções das ferramentas, realizam operações regulares de manutenção das máquinas e efetuam ajustes aos comandos de fresagem, tais como a intensidade do feixe laser e a sua posição.', 'released', '["Operador de Máquina de Corte a Laser", "Operadora de Máquina de Corte a Laser"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/bca063d2-a904-45db-b3f4-0fd7e681753e', 'Técnico de Instrumentos Cirúrgicos', 'Os técnicos de instrumentos cirúrgicos criam, reparam e concebem instrumentos cirúrgicos, tais como grampos, agarras, cortadores mecânicos, escopros, sondas e outros instrumentos cirúrgicos.', 'released', '["Técnica de Instrumentos Cirúrgicos", "Técnico de Instrumentos Cirúrgicos"]'::jsonb, '7311'),
  ('http://data.europa.eu/esco/occupation/bca2528a-5a87-4576-a3b5-1edbbce40a9f', 'Instrutor de Condução', 'Os instrutores de condução ensinam às pessoas a teoria e a prática de conduzir um veículo em segurança e em conformidade com os regulamentos. Ajudam os alunos a desenvolver as competências necessárias para a condução e preparam-nos para o exame teórico de condução e o exame prático de condução. Também podem supervisionar os exames de navegação.', 'released', '["Instrutor de Condução", "Instrutora de Condução"]'::jsonb, '5165'),
  ('http://data.europa.eu/esco/occupation/bcb7efae-2374-4ea7-a8e7-a77e4c6ecfc8', 'Operador de Trituradoras de Minerais', 'Os operadores de trituradoras de minerais operam e controlam trituradoras e outras máquinas para esmagar materiais e minerais. Transferem pedras para as trituradoras, encham as máquinas com minerais, acompanham o processo de trituração e asseguram que os produtos finais satisfazem os requisitos.', 'released', '["Operadora de Trituradoras de Minerais", "Operador de Trituradoras de Minerais"]'::jsonb, '8112'),
  ('http://data.europa.eu/esco/occupation/bcba793e-44fe-45eb-b0fb-56772529cbab', 'Assistente Editorial', 'Os assistentes editoriais prestam apoio ao pessoal editorial em todas as fases do processo de publicação de jornais, sites, boletins informativos em linha, livros e revistas especializadas. Recolhem, verificam e tratam as informações, adquirem licenças e tratam dos direitos. Os assistentes editoriais funcionam como ponto de contato para o pessoal editorial, marcam reuniões e entrevistas. Procedem à revisão e à formulação de recomendações sobre os conteúdos.', 'released', '["Assistentea Editorial"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/bcc199fe-f7df-42a5-bd45-e33ae6160f26', 'Mergulhador-Salvador', 'Os mergulhadores-salvadores são mergulhadores que gerem emergências subaquáticas. Previnem e gerem os problemas subaquáticos, tratam situações de emergência de mergulho e operam o equipamento de salvamento. Os mergulhadores-salvadores gerem operações de mergulho nos mares e nas vias navegáveis. Trabalham em condições físicas exigentes para salvar e recuperar pessoas ou objetos.', 'released', '["Mergulhadora-Salvadora", "Mergulhador-Salvador", "Mergulhador-Salvadora"]'::jsonb, '7541'),
  ('http://data.europa.eu/esco/occupation/bcc21c63-7eee-4520-8fa7-43eefd389668', 'Técnico de Engenharia Industrial', 'Os técnicos de engenharia industrial auxiliam os engenheiros industriais na melhoria da eficiência, da segurança e da produtividade em instalações fabris. Realizam estudos de produção, preparam os esquemas das máquinas e equipamentos e propõem soluções para resolver os problemas de qualidade.', 'released', '["Técnica de Engenharia Industrial", "Técnico de Engenharia Industrial"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/bcc2c1db-f969-4355-bebf-4878ff6c2a94', 'Diretor de Serviços', 'Os diretores de serviços são responsáveis pela supervisão e coordenação da prestação de diferentes serviços profissionais e técnicos aos clientes. Asseguram uma interação harmoniosa com os clientes e elevados níveis de satisfação após o serviço. Esta atividade inclui a prestação de serviços policiais, correcionais, de biblioteca, jurídicos e de bombeiros.', 'released', '["Diretora de Serviços", "Diretor de Serviços de Limpeza", "Designer Gráfica", "Designer Gráfico", "Diretora de Serviços de Limpeza", "Diretor de Serviços"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/bcde2372-fcf3-4270-8f62-c5583d1bb9ec', 'Instalador de Fibra Ótica', 'Os instaladores de fibra ótica efetuam a instalação de fibra ótica e são responsáveis por todas as tarefas necessárias à montagem do sistema de cablagem: soldadura, empalme, ligação e resolução de problemas. Além disso, concebem e testam toda a instalação e fornecem orientações aos clientes relativas à manutenção.', 'released', '["Instaladora de Fibra Ótica", "Instalador de Fibra Ótica"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/bcead4e9-3697-4831-b62e-ddb83d7d469d', 'Mestre de Pesqueiro', 'Os mestres de pesqueiro planeiam, gerem e executam as atividades dos navios de pesca em águas costeiras e em alto-mar. Dirigem e controlam a navegação. Os mestres de pesqueiro podem dirigir navios de arqueação bruta igual ou superior a 500 toneladas. Controlam o carregamento, o descarregamento e a estiva, bem como a recolha, manuseamento, transformação e preservação da pesca.', 'released', '["Mestrea de Pesqueiro"]'::jsonb, '6223'),
  ('http://data.europa.eu/esco/occupation/bced9b86-d4e7-42f8-bb47-acb2001b9bd0', 'Manicura', 'As manicuras asseguram o tratamento das unhas. Limpam, cortam e moldam as unhas, removem cutículas e aplicam verniz. As manicuras aplicam unhas artificiais e outros objetos decorativos nas unhas. Prestam aconselhamento sobre cuidados das unhas e das mãos e vendem produtos especializados.', 'released', NULL, '5142'),
  ('http://data.europa.eu/esco/occupation/bcf8f332-c7e1-4a08-8651-28d668290eaf', 'Engenheiro Metalúrgico', 'Os engenheiros metalúrgicos especializam-se na extração e no processamento de metais, como o ferro, o aço, o zinco, o cobre e o alumínio. Trabalham na moldagem ou na combinação de metais puros e mistos (ligas) em novas formas e propriedades. Os engenheiros metalúrgicos tratam da extração de minérios metálicos e desenvolvem a sua utilização em técnicas de processamento de metais. Podem trabalhar no fabrico ou na investigação científica do desempenho dos metais.', 'released', '["Engenheira Metalúrgica", "Engenheiro Metalúrgico", "Engenheira Metalúrgico"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/bcffa133-c499-4db4-8e4f-b2d95da3b0fc', 'Ferrador', 'Os ferradores inspecionam, aparam e moldam os cascos dos cavalos e fabricam ferraduras, em conformidade com os eventuais requisitos regulamentares.;', 'released', '["Especialista em Ferragem", "Ferradora", "Ferrador"]'::jsonb, '7221'),
  ('http://data.europa.eu/esco/occupation/bd1cd902-1fb1-40b1-abce-bb9ef60805b4', 'Guarda Costeiro', 'Os guardas costeiros patrulham e vigiam as regiões costeiras e marítimas para prevenir acidentes, bem como realizar missões de busca e salvamento em caso de emergência. Reagem às chamadas de emergência, aconselham sobre procedimentos de segurança e previnem os acidentes e a atividade ilegal no mar. Os guardas costeiros investigam as atividades de transporte marítimo e ajudam durante os incidentes de poluição e durante as inundações.', 'released', '["Guarda Costeiro", "Guarda Costeira"]'::jsonb, '5419'),
  ('http://data.europa.eu/esco/occupation/bd206ee9-61d6-45de-a369-0c71b8429efa', 'Fabricante de Perucas e Adereços', 'Os fabricantes de perucas e adereços procedem à criação, adaptação e manutenção de próteses capilares para utilização em espetáculos ao vivo. Trabalham a partir de esboços, imagens e visões artísticas combinados com o conhecimento do corpo humano, para assegurar ao usuário a maior amplitude de movimentos. Trabalham em estreita colaboração com os designers. ;', 'released', '["Fabricantea de Perucas e Adereços"]'::jsonb, '7531'),
  ('http://data.europa.eu/esco/occupation/bd22a34c-1dc2-48df-a254-66e5d03dec12', 'Marinheiro Fluvial de Convés', 'Os marinheiros fluviais de convés são membros do convés de um navio de transporte de águas interiores. Podem trabalhar no leme, no convés, no porão de carga e na casa das máquinas. Podem ser chamados a utilizar equipamento de emergência, de salvamento, de limitação de avarias e de segurança. Executam todas as operações relacionadas com o lançamento do equipamento de salvação e devem ser capazes de operar equipamento de convés, amarração e ancoragem.', 'released', '["Marinheiro Fluvial de Convés", "Marinheira Fluvial de Convés"]'::jsonb, '8350'),
  ('http://data.europa.eu/esco/occupation/bd2c868c-371b-4958-83b4-012c52bc7faf', 'Humorista Stand-Up Comedy', 'Os humoristas stand-up comedy contam histórias humorísticas, anedotas e piadas, geralmente descritas sob a forma de um monólogo, ato ou rotina. Atuam frequentemente em clubes de comédia, bares, discotecas e teatros. Podem utilizar igualmente música, truques de magia ou adereços para melhorar a sua atuação.', 'released', NULL, '2659'),
  ('http://data.europa.eu/esco/occupation/bd378c4e-f656-46af-a728-fcfb40b113ef', 'Operador de Serras Ziguezague', 'Os operadores de serra de corte transversal utilizam uma serra de corte transversal manual para abater e torar árvores, ou para retirar os ramos a fim de obter toros.', 'released', '["Operadora de Serras Ziguezague", "Operador de Serras Ziguezague"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/bd55e8d7-8bdf-4179-a84b-ed43073f05a1', 'Fabricante de Harpas', 'Os fabricantes de harpas criam e montam peças para criar harpas, de acordo com instruções ou diagramas especificados. Lixam a madeira, medem e colocam cordas, bem como testam a qualidade das cordas e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Harpas"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/bd5a2f44-fc06-45fd-909b-3a4001c8b8a3', 'Praça de Infantaria', 'Os praças de infantaria combatem em missões de combate ou prestam ajuda em missões de manutenção da paz e noutros serviços humanitários. Lidam com armas e prestam serviços de defesa onde necessário e tentam concluir as suas missões causando danos mínimos.', 'released', '["Atirador", "Atiradora", "Praça do Exército"]'::jsonb, '0310'),
  ('http://data.europa.eu/esco/occupation/bd7c070b-333f-4b9d-a70a-25f135ff931e', 'Diretor de Distribuição — Mobiliário e Decoração', 'Os diretores de distribuição — mobiliário e decoração planificam a distribuição de mobiliário e decoração a vários pontos de venda.', 'released', '["Diretora de Distribuição — Mobiliário e Decoração", "Diretora de Logística — Mobiliário e Decoração", "Diretor de Logística — Mobiliário e Decoração", "Diretor de Distribuição — Mobiliário e Decoração"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/bd94312f-05c8-455d-a2f6-5490489ac4a4', 'Responsável de Adereços', 'Os responsáveis de adereços procedem à instalação, verificação e manutenção dos objetos utilizados no palco pelos atores ou outros pequenos objetos móveis chamados adereços. Cooperam com a equipe de apoio de estrada para descarregar, instalar e preparar os adereços. Durante um espetáculo, posicionam os adereços, entregam ou recebem os mesmos dos atores.', 'released', NULL, '3435'),
  ('http://data.europa.eu/esco/occupation/bd9d395a-d587-45c6-8d72-ceef226df9e1', 'Consultor de Integração de Sistemas Informáticos', 'Os consultores de integração de sistemas informáticos prestam aconselhamento sobre o agrupamento de diferentes sistemas tendo em vista a sua interoperabilidade dentro de uma organização, a fim de permitir a partilha de dados e de reduzir a redundância.', 'released', '["Especialista em Integração de Sistemas", "Consultora de Integração de Sistemas", "Consultor de Integração de Sistemas", "Perito em Integração de Sistemas", "Perita em Integração de Sistemas", "Consultora de Integração de Sistemas Informáticos"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/bda98f02-4f92-4015-a0c8-b86b8abc711a', 'Operador de Fabricação de Amostras de Vestuário', 'Os operadores de fabrico de amostras de vestuário criam a primeira amostra de um desenho de uma peça de vestuário. Resolvem questões relacionadas com a montagem de peças de vestuário, tendo em conta a produção a granel para garantir a disponibilidade atempada de amostras de selagem. ; Passam a ferro as peças de vestuário acabadas e efetuam controlos de qualidade.', 'released', '["Costureiro de Modelos de Vestuário", "Operador de Fabricação de Amostras de Vestuário", "Costureira de Modelos de Vestuário", "Operadora de Fabricação de Amostras de Vestuário"]'::jsonb, '8153'),
  ('http://data.europa.eu/esco/occupation/bdc74965-1d1a-4f8e-a490-9cf71f494e02', 'Assistente Dentário', 'Os assistentes dentários prestam apoio aos dentistas em tratamentos clínicos, como a preparação e o apoio na execução prática e no acompanhamento, bem como tarefas administrativas sob supervisão e seguindo as ordens do dentista.', 'released', '["Assistente Dentária", "Assistente Dentário", "Assistentea Dentário"]'::jsonb, '3251'),
  ('http://data.europa.eu/esco/occupation/bdf2dd9d-6c92-46f4-a8e7-76c12302d3e7', 'Funcionário de Bilheteria', 'Os funcionários de bilheteira prestam um serviço inicial aos clientes, vendem bilhetes de viagem e adequam a oferta das reservas aos pedidos e necessidades dos clientes.', 'released', '["Funcionária de Bilheteira", "Agente de Venda de Bilhetes", "Funcionário de Bilheteira", "Agente de Reservas", "Funcionária de Bilheteria"]'::jsonb, '4221'),
  ('http://data.europa.eu/esco/occupation/bdfb48e0-79dc-4b63-8470-db2e03b37326', 'Encarregado de Loja', 'Os encarregados de loja são responsáveis pelo bom funcionamento das lojas de acordo com os regulamentos e a política da empresa. Supervisionam as atividades comerciais, tais como os orçamentos, o inventário e o serviço de apoio ao cliente. Os encarregados de loja também acompanham o desempenham dos trabalhadores e asseguram o cumprimento dos objetivos.', 'released', '["Encarregada de Loja", "Encarregado de Loja", "Gerente de Loja"]'::jsonb, '5222'),
  ('http://data.europa.eu/esco/occupation/bdfd018a-aae1-407e-a88c-471e50b0695d', 'Supervisor de Produção de Madeira', 'Os supervisores de produção de madeira controlam os processos envolvidos na conversão das árvores abatidas em madeira utilizável. Acompanham o processo de produção e tomam decisões rápidas para resolver problemas. Asseguram a concretização dos objetivos de produção, como a quantidade e a qualidade dos produtos, dos prazos e da eficácia em termos de custos.', 'released', '["Supervisora de Produção de Madeira", "Supervisor de Produção de Madeira"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/be0e6189-46a5-4b90-8622-2d1988efba1a', 'Montador de Maquinaria Industrial', 'Os montadores de maquinaria industrial fabricam equipamento industrial, tais como robôs industriais, máquinas para linhas de montagem e máquinas de rotulagem. Utilizam ferramentas manuais e máquinas controladas por computador.', 'released', '["Montador de Maquinaria Industrial", "Montadora de Maquinaria Industrial"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/be235deb-6181-43ca-8127-7010a689643a', 'Quiroprático Especializado', 'Os quiropráticos especializados possuem um conhecimento e uma compreensão avançados numa determinada área da quiroprática, e adquiriram competências de tomada de decisões e competências clínicas complexas no domínio da profissão de quiroprática. Os quiropráticos especializados podem ter realizado estudos avançados para adquirir as competências e qualificações necessárias. Os quiropráticos especializados podem ser encontrados em diversos domínios específicos, como na educação, na neurologia funcional, na ortopedia, na pediatria, na investigação, na radiologia e no desporto. ;', 'released', '["Quiroprático Especializado", "Quiroprática Especializada", "Quiroprática Especializado"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/be2896db-9ab7-4719-a558-96b18c93027d', 'Quiroprata Veterinário', 'Os quiropratas veterinários proporcionam um tratamento terapêutico na sequência de um diagnóstico ou de uma sinalização veterinária. Concentram-se na manipulação da coluna vertebral ou na terapia manual dos animais, em conformidade com a legislação nacional.', 'released', '["Quiroprata Veterinário", "Quiroprata de Veterinária", "Quiropraxista de Veterinária", "Quiropraxista Animal", "Quiroprata Veterinária", "Quiroprata de Animais", "Quiropraxista Veterinária", "Quiropraxista Veterinário"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/be375e11-9a70-47cb-8091-711c94ed0c13', 'Consultor de Bronzeamento', 'Os consultores de bronzeamento ajudam os clientes com as suas necessidades de bronzeamento. Prestam aconselhamento sobre compras e tratamentos em solários e salões de bronzeamento.', 'released', '["Profissional de Solário", "Consultora de Bronzeamento", "Consultor de Bronzeamento"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/be3c021d-bd93-45a0-ad32-e8fa8e0d17ef', 'Professor de Línguas Modernas', 'Os professores de Línguas Modernas são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Línguas Modernas, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio das Línguas Modernas, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor de Línguas Modernas", "Professora Universitária de Línguas Modernas", "Professora de Línguas Modernas", "Professor Universitário de Línguas Modernas"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/be54b8da-bc71-40f0-b150-45c5e0769375', 'Gerente de Recinto de Eventos', 'Os gerentes de recintos de eventos executam a planificação e a gestão de operações relativas a conferências, banquetes e recintos de eventos numa unidade de hotelaria, a fim de refletir as necessidades dos clientes. São responsáveis por eventos promocionais, conferências, seminários, exposições, eventos empresariais e eventos sociais e pelas respetivas instalações.', 'released', '["Organizador de Conferências", "Organizadora de Banquetes", "Organizador de Banquetes", "Organizadora de Conferências", "Gerentea de Recinto de Eventos"]'::jsonb, '3332'),
  ('http://data.europa.eu/esco/occupation/be6d7fd3-2e51-499f-a31d-8aa0bbd32f2a', 'Assistente Social Especialista em Cuidados Paliativos', 'Os assistentes sociais especialistas em cuidados paliativos prestam assistência e aconselhamento a indivíduos com doenças crônicas ou terminais e às suas famílias no que diz respeito às formalidades práticas. Providenciam os cuidados médicos necessários para o doente e ajudam a família a adaptar-se ao diagnóstico, prestando apoio e atenção às suas necessidades emocionais e ajudando-os a compreender as suas opções.', 'released', '["Assistentea Social Especialista em Cuidados Paliativos"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/be845b10-21d0-49a7-b5b9-095828c32515', 'Engenheiro Geotérmico', 'Os engenheiros geotérmicos estudam, desenham, planeiam e operam processos e equipamentos que convertem energia térmica em eletricidade ou aquecimento e arrefecimento. Utilizam fontes de calor naturais do subsolo para produzir eletricidade e alimentar sistemas de refrigeração no verão e aquecimento no inverno em edifícios industriais, comerciais e residenciais. Os engenheiros geotérmicos desenvolvem estratégias para uma produção mais eficiente de energia e para a sustentabilidade ambiental.;', 'released', '["Consultor de Engenharia de Tecnologia Geotérmica", "Consultora de Engenharia Geotérmica", "Gerente de Usina Geotérmica", "Engenheira Geotérmico 0 & M", "Consultora de Engenharia de Tecnologia Geotérmica", "Consultor de Engenharia Geotérmica", "Engenheiro Geotérmico 0 & M", "Engenheira Geotérmico"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/bea705fe-06ac-4147-b8e0-6e8ac1208d8f', 'Fiel de Armazém', 'Os fiéis de armazém executam a manipulação, o acondicionamento e a armazenagem exatos dos materiais num armazém. Recebem mercadorias, rotulam-nas, controlam a qualidade, armazenam-nas e documentam quaisquer danos. Os fiéis de armazém também monitorizam os níveis das existências de artigos, mantêm o inventário e as mercadorias de navios.', 'released', NULL, '9333'),
  ('http://data.europa.eu/esco/occupation/bea99fea-0383-4c63-b944-70d4799de2c5', 'Gestor de Projeto', 'Os gestores de projeto supervisionam o projeto diariamente e são responsáveis pela obtenção de resultados de elevada qualidade em função dos objetivos e condicionalismos identificados, assegurando a utilização eficaz dos recursos afetados. São responsáveis pela gestão dos riscos e dos problemas, pela comunicação no âmbito do projeto e pela gestão das partes interessadas. Os gestores de projeto realizam as atividades de planejamento, organização, obtenção, acompanhamento e gestão dos recursos e do trabalho necessários para atingir objetivos e metas específicos do projeto de forma eficaz e eficiente.;', 'released', '["Coordenadora de Projetos", "Diretora de Projetos", "Diretor de Projetos", "Coordenador de Projetos", "Gerente", "Gestora de Projeto"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/beacd3d6-e414-42ea-baf9-3ddc34fc143a', 'Destilador de Bebidas Alcoólicas', 'Os destiladores de bebidas alcoólicas extraem álcool de levedura para utilizar no fabrico de soluções destiladas. Pesam as quantidades de levedura e medem a temperatura para determinar as condições adequadas para a destilação.', 'released', '["Destilador de Bebidas Alcoólicas", "Destiladora de Bebidas Alcoólicas", "Operador de Destilação de Bebidas Alcoólicas", "Operadora de Destilação de Bebidas Alcoólicas"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/becbe3ca-e000-40c0-9f67-5c4035b930ea', 'Técnico de Ensaios de Hardware', 'Os técnicos de ensaios de hardware realizam ensaios em hardware, como placas de circuito, chips de computador, sistemas informáticos e outros componentes eletrônicos e elétricos. Analisam a configuração do hardware e testam a sua fiabilidade, bem como a sua conformidade com as especificações.', 'released', '["Técnico de Ensaios de Equipamento Informático", "Técnica de Ensaios de Equipamento Informático", "Técnica de Ensaios de Hardware", "Técnico de Ensaios de Hardware"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/beedd3c0-d3e2-4efe-8f39-381df669ee35', 'Tratador de Cavalos', 'Os tratadores de cavalos prestam cuidados de saúde diários práticos a cavalos para garantir a saúde, o bem-estar e a segurança dos mesmos. ; Participam no exercício dos cavalos, na limpeza e na manutenção dos estábulos, dos edifícios e da área.', 'released', '["Tratadora de Cavalos", "Tratador de Cavalos"]'::jsonb, '9212'),
  ('http://data.europa.eu/esco/occupation/bf2ca3bb-5fa5-41d9-a039-949cad61616d', 'Representante de Vendas de Produtos Químicos', 'Os representantes de vendas de produtos químicos prestam serviços em nome de uma empresa para vender as suas mercadorias, prestando simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Produtos Químicos"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/bf367464-950a-416c-98b1-52b9d571550e', 'Operador de Embalamento de Artigos em Couro', 'Os operadores de embalamento de artigos em couro efetuam a revisão final dos artigos em couro. Aplicam acessórios, tais como pegas, aloquetes, ou outras características do produto (por exemplo, etiquetas). Se for o caso, introduzem produtos em sacos têxteis, enchem-nos com papel para manter a forma do produto e colocam os produtos em caixas utilizando ferramentas adequadas para a proteção dos produtos. São responsáveis pelo embalamento geral e controlam a conclusão de cada encomenda, colocando as caixas nas embalagens e preparando a documentação para a expedição pela empresa transportadora.', 'released', '["Operador de Embalamento de Artigos em Couro", "Operadora de Embalamento de Artigos em Couro"]'::jsonb, '8183'),
  ('http://data.europa.eu/esco/occupation/bf7d8b16-4e2c-48ef-b44e-dc25b2d0ab61', 'Cafeteiro', 'Os cafeteiros preparam tipos de café especializados com equipamento profissional num hotel/café/bar.', 'released', '["Empregada de Cafetaria", "Empregado de Cafetaria", "Empregada de Bar Especializada em Cafés", "Cafeteiro", "Cafeteira", "Empregado de Bar Especializado em Cafés"]'::jsonb, '5132'),
  ('http://data.europa.eu/esco/occupation/bf802371-4758-4268-a780-58e3d269831b', 'Supervisor em Proteção Radiológica', 'Os supervisores em proteção radiológica são responsáveis pela proteção contra os efeitos nocivos causados pela exposição a radiações ionizantes. Asseguram o cumprimento da legislação e da regulamentação através da aplicação de medidas de segurança. Além disso, desenvolvem planos de proteção contra as radiações, em especial para as centrais e instalações nucleares.', 'released', '["Supervisor em Proteção Radiológica", "Supervisora em Proteção Radiológica", "Supervisora em Radioproteção Radiológica", "Supervisor em Radioproteção Radiológica"]'::jsonb, '2263'),
  ('http://data.europa.eu/esco/occupation/bf89925d-00a1-4f94-ab3b-2148c887af33', 'Empresário Retalhista', 'Os empresários retalhistas organizam processos e conceitos empresariais na sua própria empresa.', 'released', '["Comerciante", "Empresária Retalhista"]'::jsonb, '5221'),
  ('http://data.europa.eu/esco/occupation/bfc1b4e9-624c-4fba-89f2-d218bba9e257', 'Técnico de Efeitos Especiais de Voo', 'Os técnicos de efeitos especiais de voo concebem efeitos de voo com pessoas para um espetáculo e supervisionam ou levam a cabo a sua execução. O seu trabalho baseia-se na investigação e na visão artística. O seu desenho é influenciado por, e influencia, outros desenhos e deve estar em conformidade com estes desenhos e com a visão artística global. Treinam os atores para a coreografia de voo e manipulam-nos durante o espetáculo. Por conseguinte, os técnicos de efeitos especiais de voo trabalham em estreita colaboração com os diretores artísticos, os operadores, os artistas e a equipe artística. Os técnicos de efeitos especiais de voo preparam e supervisionam a instalação, realizam controlos de segurança e operam os sistemas de voo de pessoas. São formados para reagir de forma adequada em situações de emergência que possam ocorrer com voos durante um espetáculo. O seu trabalho baseia-se em planos, instruções e cálculos. A manipulação de pessoas em altura próximo ou por cima dos artistas e do público faz com que seja uma atividade de alto risco.', 'released', '["Técnico de Efeitos Especiais de Voo", "Técnica de Efeitos Especiais de Voo"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/bfc92738-128b-44f5-92d4-51b10df17961', 'Filósofo', 'Os filósofos estudam e argumentam sobre problemas gerais e estruturais relacionados com a sociedade, os seres humanos e os indivíduos. São dotados de capacidades de raciocínio e argumentação bem desenvolvidas para discutirem sobre temas relacionados com a existência, os sistemas de valores, o conhecimento ou a realidade. Nas suas discussões, recorrem à lógica, a qual conduz a níveis de profundidade e de abstração.', 'released', '["Filósofo", "Filósofa"]'::jsonb, '2633'),
  ('http://data.europa.eu/esco/occupation/bfdc096e-e450-424d-9340-46968047ed68', 'Operador de Neutralização de Nitroglicerina', 'Os operadores de neutralização de nitroglicerina procedem à manutenção de tanques de mistura de explosivos, neutralizando os restantes ácidos do processo.', 'released', '["Operadora de Neutralização de Nitroglicerina", "Operador de Neutralização de Nitroglicerina"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/bfe142b9-a049-4d41-89c4-fd2f34ac56b6', 'Assistente de Contabilidade', 'Os assistentes de contabilidade registam e comunicam ao contabilista com quem trabalham situações contabilísticas relativas à venda de bilhetes, verificam depósitos e elaboram relatórios e documentos de receita diários. Preparam vales de reembolso autorizados, gerem as contas relativas a cheques devolvidos e comunicam com os gestores de bilhética em relação a quaisquer questões relacionadas com os sistemas de emissão de bilhetes.', 'released', '["Assistentea de Contabilidade"]'::jsonb, '3313'),
  ('http://data.europa.eu/esco/occupation/bff716c9-42c7-471e-8af0-582f799fb29a', 'Analista Ambiental em Aquicultura', 'Os analistas ambientais em aquicultura avaliam, planificam e executam programas para reconhecer, monitorizar e controlar fatores ambientais que podem afetar a saúde dos animais e plantas aquáticos.', 'released', '["Analista Ambiental em Aquacultura", "Especialista em Análise Ambiental em Aquacultura", "Cientista Marinha", "Especialista em Análise Ambiental em Aquicultura", "Cientista Marinho"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/bff7e8a3-6206-4d38-b25f-fcb6e634c7af', 'Professor de Arqueologia', 'Os professores de Arqueologia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Arqueologia, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Arqueologia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Arqueologia", "Professor de Arqueologia", "Professor Universitário de Arqueologia", "Professora Universitária de Arqueologia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/bffbe18a-cb8b-4f90-bd87-7505cd3b16f5', 'Optometrista', 'Os optometristas analisam e examinam os olhos para identificar anomalias, problemas visuais ou doenças. Receitam e ajustam lentes, tais como lentes de óculos e de contato, e aconselham sobre problemas visuais. Podem também remeter os doentes para um médico. O seu âmbito de prática e título varia de acordo com as regulamentações nacionais.', 'released', '["Ótico Oftálmico", "Ótica Oftálmica"]'::jsonb, '2267'),
  ('http://data.europa.eu/esco/occupation/c011a88b-95ab-46ad-ad30-539e3fc56092', 'Professor de Literatura do Ensino Secundário', 'Os professores de Literatura do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Literatura. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Literatura através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Literatura Portuguesa do Ensino Secundário", "Professora de Literatura do Ensino Secundário", "Professor de Literatura Portuguesa do Ensino Secundário", "Professor de Literatura do Ensino Secundário", "Professor de Literatura Inglesa do Ensino Secundário", "Professora de Literatura Inglesa do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/c01cdf85-3ce0-4d12-ae86-e4e63493fafa', 'Corretor Financeiro', 'Os corretores financeiros exercem atividades no mercado financeiro em nome dos seus clientes. Monitorizam os títulos, a documentação financeira dos seus clientes, as tendências e condições do mercado e outros requisitos legais. Planificam as atividades de compra e venda e calculam os custos das transações.', 'released', '["Corretora Financeira", "Corretor Financeiro", "Corretora Financeiro"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/c02ee787-c30b-4f0d-9d7f-6eb36fc44a5d', 'Diretor de Investigação', 'Os diretores de investigação supervisionam as funções de investigação e desenvolvimento de um centro ou programa de investigação ou de uma universidade. Apoiam o pessoal executivo, coordenam as atividades de trabalho e supervisionam o pessoal e os projetos de investigação. Podem trabalhar num vasto leque de setores, como o setor químico, técnico e das ciências da vida. Os diretores de investigação também podem aconselhar em investigação e executar eles próprios a investigação.', 'released', '["Diretora de Investigação", "Diretor de Investigação", "Diretor Científico", "Diretora de Laboratório", "Diretor de Laboratório", "Diretora Científica"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/c0386702-0699-4550-920b-1f7027c9a3d9', 'Operador de Peixaria', 'Os operadores de peixaria preparam peixe e marisco de acordo com os regulamentos em matéria de higiene, segurança alimentar e comércio. Realizam operações de tratamento de peixe, bem como atividades de venda a retalho.', 'released', '["Operadora de Peixaria", "Peixeira", "Operador de Peixaria", "Peixeiro"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/c0463fbe-7914-48ac-84ec-abaee1a7f292', 'Corretor de Títulos', 'Os corretores de títulos criam uma ligação entre os investidores e as oportunidades de investimento disponíveis. Compram e vendem títulos em nome dos seus clientes, com base nos conhecimentos especializados que têm dos mercados financeiros. Acompanham o desempenho dos títulos dos seus clientes, avaliando a sua estabilidade ou tendências especulativas. Os corretores de títulos calculam o preço dos títulos e procedem à colocação de ordens.', 'released', '["Corretora de Títulos", "Corretor de Títulos", "Corretora de Valores Mobiliários", "Corretor de Valores Mobiliários"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/c0489e22-6a1b-4e52-974a-eb71bbb42134', 'Técnico de Relações Públicas', 'Os técnicos de relações públicas representam uma empresa ou organização junto das partes interessadas e do público. Utilizam estratégias de comunicação para promover uma compreensão favorável das atividades e da imagem dos seus clientes.', 'released', '["Técnica de Relações Públicas", "Técnico de Relações Públicas"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/c05090e2-d599-46c8-a47b-3d52a893ca55', 'Criador de Máscaras', 'Os criadores de máscaras constroem, adaptam e conservam máscaras para espetáculos ao vivo. Trabalham a partir de esboços, imagens e visões artísticas combinados com o conhecimento do corpo humano, a fim de assegurarem a máxima amplitude de movimentos do usuário. Trabalham em estreita colaboração com os designers.', 'released', '["Criadora de Máscaras", "Criador de Máscaras"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/c0749528-ee2a-41bd-a1f6-c13825b5e569', 'Mecânico de Intervenção', 'Os mecânicos de intervenção realizam reparações, ensaios e manutenção no local de veículos na estrada. Localizam e deslocam-se até aos veículos dos clientes para prestar serviços, tais como substituição de pneus e reparações do motor.', 'released', '["Mecânica de Intervenção", "Mecânico de Intervenção"]'::jsonb, '7231'),
  ('http://data.europa.eu/esco/occupation/c0768628-46ad-4077-aee0-66ab6d7711df', 'Vendedor de Flores e Produtos para Jardinagem', 'Os vendedores de flores e produtos para jardinagem vendem flores, plantas, sementes e/ou adubos em lojas especializadas.', 'released', '["Vendedora de Flores e Produtos para Jardinagem", "Vendedor de Flores e Produtos para Jardinagem"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/c07ab008-79c1-4516-8dcc-8289f797dc34', 'Eletricista de Minas', 'Os eletricistas de minas procedem à instalação, manutenção e reparação de equipamento elétrico especializado, utilizando o seu conhecimento de princípios elétricos. Também controlam o fornecimento de eletricidade nas minas.', 'released', NULL, '7412'),
  ('http://data.europa.eu/esco/occupation/c0a15ec7-10e6-45e7-b69c-b85ff6f4f87f', 'Trabalhador da Unidade de Produção em Aquicultura', 'Os trabalhadores da unidade de produção em aquicultura trabalham na produção de organismos aquáticos em processos de engorda em terra. Prestam assistência no processo de criação de organismos em todas as fases do seu ciclo de vida.', 'released', '["Trabalhador da Unidade de Produção em Aquicultura", "Trabalhadora da Unidade de Produção em Aquicultura"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/c0a35355-be44-44c0-82d2-acf8363ed45e', 'Inspetor de Controle de Qualidade de Produtos Metálicos', 'Os inspetores de controlo de qualidade de produtos metálicos efetuam controlos de qualidade preventivos e operacionais em produtos metálicos. Analisam os materiais em várias fases, a fim de garantir a sua conformidade com a norma desejada, testam os produtos e devolvem-nos para reparação, se necessário.', 'released', '["Inspetora de Controle de Qualidade de Produtos Metálicos", "Inspetor de Controle de Qualidade de Produtos Metálicos"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/c0c1364d-f784-4e76-8d3f-1e998dc6545d', 'Técnico de Sistemas de Alarme', 'Os técnicos de sistemas de alarme procedem à instalação e manutenção de sistemas de alarme para proteger contra riscos, tais como incêndios e assaltos. Instalam sensores e sistemas de controlo e ligam-nos às linhas de eletricidade e de telecomunicações, se necessário. Os técnicos de sistemas de alarme explicam a utilização dos sistemas instalados aos potenciais usuários.', 'released', '["Técnico de Sistemas de Alarme", "Técnica de Sistemas de Alarme"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/c0eb9240-4f70-4393-bdf0-723ce7fdbd36', 'Operador de Máquinas de Fabricação de Aglomerados de Madeira', 'Os operadores de máquinas de fabrico de aglomerados de madeira trabalham com máquinas para unir partículas ou fibras à base de madeira ou cortiça. São aplicadas várias colas ou resinas industriais para obter os painéis de fibras, de partículas ou de cortiça.', 'released', '["Operadora de Máquinas de Fabricação de Aglomerados de Madeira", "Operador de Máquinas de Fabricação de Aglomerados de Madeira"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/c0ec3a06-1dac-4c21-9f08-4c9dfbc9d6cf', 'Técnico de Descontaminação', 'Os técnicos de descontaminação eliminam materiais perigosos, tais como materiais radioativos ou solos contaminados. Tratam materiais perigosos em conformidade com os regulamentos de segurança, investigam causas de contaminação e eliminam a contaminação da estrutura ou do local.', 'released', '["Técnica de Descontaminação", "Técnico de Descontaminação"]'::jsonb, '7133'),
  ('http://data.europa.eu/esco/occupation/c11e2b53-06f7-465f-9b5c-708016bc96f4', 'Operador de Prensa Dobradeira', 'Os operadores de prensa dobradeira cuidam da máquina que prensa o papel e faz molhos de papel.', 'released', '["Operador de Prensa Dobradeira", "Operadora de Prensa Dobradeira"]'::jsonb, '7323'),
  ('http://data.europa.eu/esco/occupation/c143d51a-5267-41a8-a73b-9022cf74c495', 'Especialista em Import-Export de Máquinas e Equipamento de Escritório', 'Os especialistas em import-export de máquinas e equipamento de escritório possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Máquinas e Equipamento de Escritório"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/c18fddf5-cfc4-4f9c-94d6-86608faaa1dd', 'Diretor dos Serviços Sociais', 'Os diretores dos serviços sociais têm a responsabilidade de assumir a liderança estratégica e operacional e gerir as equipes e os recursos do pessoal dentro e por todos os serviços sociais. São responsáveis pela aplicação da legislação e das políticas relativas, por exemplo, às decisões sobre pessoas vulneráveis. Promovem os valores e a ética do trabalho social e do cuidado social, a igualdade e a diversidade, bem como os códigos de que regem a prática. São responsáveis pela ligação com outros profissionais no domínio da justiça penal, da educação e da saúde. Podem ser responsáveis por contribuir para o desenvolvimento das políticas locais e nacionais.', 'released', '["Diretor dos Serviços Sociais", "Gestora de Serviços Sociais", "Diretora dos Serviços Sociais", "Gestor de Serviços Sociais"]'::jsonb, '1344'),
  ('http://data.europa.eu/esco/occupation/c1a86d6d-7785-43e1-994b-958eba58fff7', 'Assistente de Farmácia', 'Os assistentes de farmácia desempenham funções gerais, como a gestão de existências, o atendimento ao balcão ou o desempenho de funções administrativas. Tratam do inventário na farmácia sob a supervisão de um farmacêutico.', 'released', '["Assistentea de Farmácia"]'::jsonb, '3213'),
  ('http://data.europa.eu/esco/occupation/c1ee52e0-f30a-4f8d-a7f5-b07f5f06f88f', 'Diretor de Distribuição — Laticínios e Óleos Alimentares', 'Os diretores de distribuição — lacticínios e óleos alimentares planificam a distribuição de lacticínios e óleos alimentares a diversos pontos de venda.', 'released', '["Diretora de Distribuição — Lacticínios e Óleos Alimentares", "Diretora de Logística — Lacticínios e Óleos Alimentares", "Diretor de Logística — Lacticínios e Óleos Alimentares", "Diretor de Distribuição — Lacticínios e Óleos Alimentares", "Diretora de Distribuição — Laticínios e Óleos Alimentares"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/c22724a3-079c-4897-bd92-d99e068b6ffc', 'Operador de Máquinas de Pultrusão', 'Os operadores das máquinas de pultrusão procedem à operação, ao controlo e à manutenção de máquinas que permitem a produção de materiais compósitos com secções transversais consistentes, acrescentando fibras de reforço, tais como fibra de vidro, ao material existente e revestindo o material resultante com resina; este é, então, puxado através de uma tintura aquecida, onde fica curado.', 'released', '["Operadora de Máquinas de Pultrusão", "Operador de Máquinas de Pultrusão"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/c227dcff-dd84-487e-a171-da3d919129bb', 'Coordenador de Apoio Financeiro a Estudantes', 'Os coordenadores de apoio financeiro a estudantes ajudam os estudantes e os administradores de estabelecimentos de ensino na gestão de propinas e de empréstimos a estudantes. Prestam aconselhamento sobre e determinam os montantes e a elegibilidade dos empréstimos concedidos aos estudantes, aconselham os estudantes sobre os empréstimos adequados disponíveis e estabelecem contatos com fontes externas de crédito, como os bancos, para facilitar o processo de concessão de empréstimos a estudantes. Tomam decisões baseadas no seu discernimento profissional sobre a elegibilidade dos estudantes para apoio financeiro e podem organizar reuniões de aconselhamento que contam com a presença dos pais do estudante, para debater questões e soluções de apoio financeiro.', 'released', '["Coordenadora de Apoio Financeiro a Estudantes", "Coordenador de Apoio Financeiro a Estudantes"]'::jsonb, '3312'),
  ('http://data.europa.eu/esco/occupation/c25b3700-6095-42b7-99fc-b87dc326c044', 'Investigador de Agronomia', 'Os investigadores de agronomia investigam e estudam os solos, os animais e as plantas, com o objetivo de melhorar os processos agrícolas, a qualidade dos produtos agrícolas ou o impacto dos processos agrícolas no ambiente. Planificam e implementam projetos como projetos de desenvolvimento em nome de clientes ou instituições.', 'released', '["Investigador de Agronomia", "Investigadora de Agronomia", "Engenheiro Agrícola", "Engenheira Agrícola", "Agrónoma", "Agrónomo"]'::jsonb, '2132'),
  ('http://data.europa.eu/esco/occupation/c262bb96-03bb-4c97-a45b-0cf36db5b048', 'Professor Assistente', 'Os professores assistentes partilham o volume de trabalho académico dos professores universitários ou dos professores do ensino superior, nomeadamente ministrando aulas aos alunos. Preparam e ministram aulas e reúnem-se com os alunos individualmente em matéria de avaliação. Além disso, combinam a sua atividade de ensino e outras funções académicas com a realização da sua própria investigação na sua área de estudos. Os professores assistentes ocupam uma posição autónoma a tempo inteiro, apesar do que o elemento de subserviência do título da profissão possa sugerir.', 'released', '["Professor Assistente", "Professora Assistente"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/c269387f-a652-4880-860a-e91ef105bfb7', 'Diretor de Creche', 'Os diretores de creche gerem as atividades quotidianas de um jardim de infância ou de uma creche. Gerem o pessoal, tomam decisões sobre as admissões e são responsáveis pelo cumprimento de normas curriculares adequadas à idade dos alunos dos jardins de infância e facilitadoras do desenvolvimento social e comportamental. Além disso, asseguram que a escola cumpre os requisitos nacionais em matéria de educação previstos na lei.', 'released', '["Diretor de Creche", "Diretora de Creche"]'::jsonb, '1341'),
  ('http://data.europa.eu/esco/occupation/c28cb56b-003e-499a-8dbf-b654864e7867', 'Instalador de Publicidade', 'Os instaladores de publicidade afixam cartazes e outro material publicitário em edifícios, ônibus e transportes subterrâneos e noutros locais públicos, tais como centros comerciais, para chamar a atenção dos transeuntes. Utilizam equipamento para subir aos edifícios e atingir locais mais altos, cumprindo os regulamentos e procedimentos de saúde e segurança.', 'released', '["Instalador de Publicidade", "Colocadora de Anúncios", "Colocador de Anúncios", "Montadora de Anúncios", "Instaladora de Publicidade", "Montador de Anúncios"]'::jsonb, '9629'),
  ('http://data.europa.eu/esco/occupation/c29f1a42-25cb-4192-9bc1-cc7560c00590', 'Instrutor de Condução de Veículos Pesados', 'Os instrutores de condução de veículos pesados ensinam às pessoas a teoria e a prática de conduzir um caminhão em segurança e em conformidade com os regulamentos. Ajudam os alunos a desenvolver as competências necessárias para a condução e preparam-nos para os exames teóricos de condução e o exame prático de condução.', 'released', '["Instrutor de Condução de Veículos Pesados", "Instrutora de Condução de Veículos Pesados"]'::jsonb, '5165'),
  ('http://data.europa.eu/esco/occupation/c2a29b8d-1042-4766-a162-e174c7a77421', 'Terapeuta Complementar', 'Os terapeutas complementares utilizam uma série de terapêuticas complementares e alternativas para trabalhar em simultâneo com o corpo, a mente e o espírito dos clientes numa abordagem holística. Fornecem práticas e serviços para o bem-estar holístico, a manutenção da saúde, a educação sanitária, a promoção da saúde e a prevenção de doenças, bem como o tratamento sustentável de determinadas doenças, especialmente doenças crônicas. As suas práticas incluem, entre outras, a acupuntura, a aromaterapia, a hidroterapia, a homeopatia e medicamentos à base de plantas.', 'released', '["Terapeuta de Reiki", "Terapeuta Holística", "Naturopata", "Terapeuta de Ayurveda", "Terapeuta Holístico", "Terapeuta de Massagem Ayurvédica"]'::jsonb, '2230'),
  ('http://data.europa.eu/esco/occupation/c2d36adb-ecf4-4823-980b-d84b0f11b2c8', 'Engenheiro de Simulação de Baterias', 'Os engenheiros de simulação de baterias preveem o desempenho das baterias e dos sistemas de baterias em diferentes condições, utilizando modelos matemáticos e ferramentas de simulação. Trabalham com uma equipe de engenheiros e cientistas para criar simulações precisas e fiáveis dos sistemas de baterias, que podem ser utilizadas para analisar e otimizar a concepção, o desempenho e a segurança das baterias. São responsáveis pelo desenvolvimento e manutenção dos modelos de simulação, pela realização de simulações e pela análise dos resultados, bem como pela formulação de recomendações para alterações e melhorias na concepção.', 'released', '["Engenheira de Simulação de Baterias", "Engenheiro de Simulação de Baterias"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/c2d5daae-8f8a-45b1-8e76-3284b84ce195', 'Operador de Máquinas para Fabricação de Molas', 'Os operadores de máquinas para fabrico de molas operam uma série de equipamentos e máquinas concebidos para o fabrico de diferentes tipos de molas, incluindo folhas, bobinas, torção, relógio, tensão e mola de tração.', 'released', '["Operador de Máquinas para Fabricação de Molas", "Operadora de Máquinas para Fabricação de Molas"]'::jsonb, '8121'),
  ('http://data.europa.eu/esco/occupation/c2e6609d-0abe-4a38-b295-e06edbd52e82', 'Responsável Pela Angariação de Fundos', 'Os responsáveis pela angariação de fundos são responsáveis por angariar fundos em nome de organizações, muitas vezes sem fins lucrativos, tais como instituições de beneficência. Além disso, gerem os programas de desenvolvimento dos recursos angariados para a sua utilização. Desempenham uma série de tarefas destinadas à angariação de fundos, como o desenvolvimento de parcerias empresariais, a coordenação de campanhas de publicidade direta, a organização de angariadores de fundos, o contato com doadores ou patrocinadores e a obtenção de receitas provenientes de subvenções de fundos fiduciários, fundações e outros órgãos estatutários.', 'released', '["Responsável Pelo Fundraising"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/c2efadc4-6f47-4f34-997b-dd80aba609dd', 'Coordenador de Serviço Educativo de Espaços Museológicos', 'Os coordenadores de serviços educativos e de serviços prestados aos visitantes tratam de todas as atividades relativas aos visitantes, atuais e futuros, de espaços culturais e espaços museológicos. O seu objetivo é o fornecimento de programas de aprendizagem e de participação dinâmicos e de elevada qualidade. Asseguram que as coleções de espaços culturais e museológicos ou os espetáculos ao vivo continuam a servir como recursos de aprendizagem valiosos para todas as idades. Estes profissionais desenvolvem, distribuem e avaliam programas e eventos para turmas, grupos ou indivíduos.', 'released', '["Coordenador do Serviço Educativo de Espaços Museológicos", "Coordenadora do Serviço Educativo de Espaços Museológicos", "Coordenadora de Serviço Educativo de Espaços Museológicos"]'::jsonb, '2355'),
  ('http://data.europa.eu/esco/occupation/c302791c-6864-4ec5-9a6c-2fca38764f0e', 'Inspetor de Incêndio', 'Os inspetores de incêndios realizam inspeções em edifícios e propriedades, a fim de garantir a sua conformidade com a regulamentação em matéria de prevenção de incêndios e de segurança contra incêndios, aplicando a regulamentação nas instalações que não estão conformes. Realizam igualmente atividades educativas, instruindo o público em matéria de segurança contra incêndios e de métodos de prevenção, políticas e resposta a situações de catástrofe.', 'released', '["Inspetora de Incêndio"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/c32155d3-9ac5-4e44-8e8b-25c47ad31c38', 'Operador de Digestor', 'Os operadores de digestor, ou cozinheiros, cozinham aparas de madeira com carbonato de sódio ou ácido para separar a polpa de madeira de constituintes indesejáveis. Testam a solução resultante.', 'released', '["Operador de Digestores", "Operadora de Digestor"]'::jsonb, '8171'),
  ('http://data.europa.eu/esco/occupation/c332af81-4481-4494-9786-aea1f5c5ffcf', 'Técnico de Calibração', 'Os técnicos de calibração testam e calibram equipamentos elétricos e eletrônicos. Efetuam a leitura de planos e outros desenhos técnicos para desenvolverem procedimentos de ensaio para cada produto.', 'released', '["Técnico de Calibração", "Técnica de Calibração"]'::jsonb, '3113'),
  ('http://data.europa.eu/esco/occupation/c36fc197-1f5b-4563-acd8-6f1d06aa1c03', 'Engenheiro Naval', 'Os engenheiros navais concebem, constroem, mantêm e reparam o casco, os equipamentos mecânicos e eletrônicos e os sistemas auxiliares, tais como motores, bombas, bombas de aquecimento, ventilação e grupos eletrogéneos. Trabalham em todos os tipos de embarcações, desde embarcações de recreio a embarcações navais, incluindo submarinos.', 'released', '["Engenheira Naval", "Engenheiro Naval"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/c3760388-d070-491a-9c1f-be305a576815', 'Oficial de Serviço de Pilotagem de Navios', 'Os oficiais de serviço de pilotagem de navios coordenam os navios que entram ou saem do porto. Escrevem despachos que indicam o nome do navio, o posto de atracagem, a companhia de rebocadores e a hora de chegada ou de partida, e notificam o piloto marítimo da missão. Obtêm as receitas de pilotagem do piloto aquando do regresso do navio. Os oficiais de serviço de pilotagem de navios também registam taxas de recepção, utilizando o livro aduaneiro como guia, elaboram relatórios de atividades, tais como o número de navios pilotados e as cobranças realizadas, e procedem à manutenção dos registos dos navios que entram no porto, indicando o seu proprietário, o nome do navio, a tonelagem de deslocamento, o agente e o país de registo.', 'released', NULL, '4323'),
  ('http://data.europa.eu/esco/occupation/c37d0026-989b-4705-9bcb-30cccd8308fa', 'Nutricionista', 'Os nutricionistas avaliam os ingredientes, os processos de fabrico e os gêneros alimentícios, a fim de garantir a qualidade nutricional e a adequação das refeições e pratos preparados. Estudam o valor nutricional dos gêneros alimentícios e dos pratos e aconselham sobre a composição de diferentes refeições ou pratos para alimentação humana (produtos alergénicos, macro e micronutrientes,...)', 'released', '["Nutricionista Especialista em Refeições Preparadas"]'::jsonb, '2265'),
  ('http://data.europa.eu/esco/occupation/c3959398-a5d7-4b26-abcf-ef7af87e5822', 'Operador de Central Geotérmica', 'Os operadores de centrais geotérmicas operam e efetuam a manutenção de equipamentos, muitas vezes turbinas a vapor, que produzem energia elétrica. Monitorizam o equipamento de medição para garantir a segurança das operações e a satisfação das necessidades de produção. Tomam igualmente medidas relativas a problemas do sistema e a anomalias de reparação. Podem regular os geradores a fim de controlar o fluxo de eletricidade para as linhas elétricas.', 'released', '["Operador de Central Geotérmica", "Operadora de Central Geotérmica"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/c3aae59e-1441-4b3e-bdd1-6da50dc7cf42', 'Guarda-Livros', 'Os guarda-livros registam e compilam as transações financeiras correntes de uma organização ou empresa, que consistem geralmente em vendas, compras, pagamentos e receitas. Asseguram a documentação de todas as transações financeiras no livro diário e no livro-razão adequados e o seu equilíbrio. Os guarda-livros preparam os livros de registo e os livros-razão com as transações financeiras para que o contabilista analise posteriormente os balanços e as demonstrações de resultados.', 'released', NULL, '3313'),
  ('http://data.europa.eu/esco/occupation/c3abb0cb-c78c-4136-b9f9-f9feca9179fa', 'Operador de Redes de Aprovisionamento de Gás', 'Os operadores de redes de aprovisionamento de gás acompanham e controlam o fluxo de gás natural entre gasodutos e o sistema de distribuição, em conformidade com os horários e os pedidos. Apresentam um relatório sobre o fluxo de gás natural, asseguram o cumprimento do calendário ou preveem adaptações em caso de problemas para tentar satisfazer os pedidos.', 'released', '["Operador de Redes de Aprovisionamento de Gás", "Operadora de Redes de Aprovisionamento de Gás"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/c3b82711-273d-4fa8-8de7-0ac3d99c16fc', 'Professor de Ciências Informáticas', 'Os professores de Ciências Informáticas são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Ciências Informáticas, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio das Ciências Informáticas, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Ciências Informáticas", "Professor Universitário de Ciências Informáticas", "Professora Universitária de Informática", "Professor Universitário de Informática", "Professor de Informática", "Professora Universitária de Ciências Informáticas", "Professor de Ciências Informáticas", "Professora de Informática"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/c3c8c56c-b3ab-4425-a38a-abcace020d22', 'Psicólogo Clínico', 'Os psicólogos clínicos diagnosticam, reabilitam e prestam apoio a indivíduos afetados por distúrbios e problemas mentais, emocionais e comportamentais, bem como por alterações mentais e doenças causadas por agentes patogénicos, através da utilização de ferramentas cognitivas e de uma intervenção adequada. Utilizam recursos da psicologia clínica com base na ciência psicológica, nas suas conclusões, teorias, métodos e técnicas de investigação, interpretação e previsão de experiências e comportamentos humanos.', 'released', '["Psicólogo Clínico", "Psicóloga Clínica", "Psicóloga Clínico"]'::jsonb, '2634'),
  ('http://data.europa.eu/esco/occupation/c3cae318-8b15-4339-a617-1a66b9ff6609', 'Montador de Motores de Veículos', 'Os montadores de motores de veículos constroem e instalam peças pré-fabricadas para motores para veículos, tais como motores a gasóleo, a gás, a gasolina e motores elétricos. Analisam as especificações e os desenhos técnicos para determinar os materiais e as instruções de montagem. Inspecionam e testam os motores e rejeitam os componentes avariados.', 'released', '["Montador de Motores de Veículos", "Montadora de Motores de Veículos", "Construtor de Motores de Veículos", "Construtora de Motores Híbridos de Veículos", "Construtora de Motores Elétricos de Veículos", "Construtor de Motores Elétricos de Veículos", "Construtor de Motores Híbridos de Veículos", "Construtora de Motores de Veículos"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/c3dc576e-2a58-4481-9b6f-9853067af8ea', 'Negociante de Madeira', 'Os negociantes de madeira avaliam a qualidade, a quantidade e o valor de mercado da madeira e dos produtos de madeira para comercialização. Organizam o processo de venda de madeira nova e compram existências de madeira.', 'released', '["Negociantea de Madeira"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/c3fc5265-6333-483f-9339-b4b860efa08d', 'Observador de Pescas', 'Os observadores das pescas registam e comunicam as atividades de pesca e o nível de conformidade e de execução das medidas de conservação em vigor na zona de trabalho, através do controlo da posição do navio, da utilização das artes de pesca e das capturas. Fornecem os relatórios necessários para a monitorização científica da zona de pesca, prestam aconselhamento sobre políticas e planeiam e coordenam atividades.', 'released', '["Observadora de Pescas", "Observador de Pescas"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/c4046ba8-cfe0-4748-beac-22e865962d75', 'Encarregado de Fabricação de Malte', 'Os encarregados de fabrico de malte supervisionam os processos de maltagem na sua totalidade. Supervisionam os processos de maceração, de germinação e de secagem em estufa. Controlam todos os parâmetros da transformação com vista a cumprir as especificações dos clientes. Prestam assistência e liderança aos trabalhadores encarregados do fabrico de malte e asseguram que trabalham de forma segura e profissional.', 'released', '["Diretora de Produção de Malte", "Encarregado de Fabricação de Malte", "Encarregada de Fabricação de Malte", "Diretor de Produção de Malte"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/c4071145-a774-4cf4-aefa-ae18a385cca4', 'Engenheiro de Logística', 'Os engenheiros logísticos de concebem e implementam sistemas destinados a otimizar o tempo e os esforços investidos nas atividades de transporte. Asseguram que os sistemas permitem o microrrastreio e a comunicação harmoniosa entre os métodos e as fases de transporte.', 'released', '["Engenheiro de Logística e Melhoria Contínua", "Engenheiro de Logística", "Engenheira de Logística", "Engenheira de Logística e Melhoria Contínua", "Engenheiro de Planejamento Logístico", "Engenheira de Planejamento Logístico"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/c40a2919-48a9-40ea-b506-1f34f693496d', 'Desenvolvedor Web', 'Os programadores Web desenvolvem, implementam e documentam software acessível via Web com base nos desenhos fornecidos. Alinham a presença na Web do cliente com a sua estratégia empresarial, solucionam problemas de software e procuram formas de melhorar a aplicação.', 'released', '["Programadora Web", "Programador de Aplicações Web", "Programadora de Aplicações Web", "Programador Web", "Programador", "Desenvolvedora Web"]'::jsonb, '2513'),
  ('http://data.europa.eu/esco/occupation/c40ef517-d4ab-4932-b184-9c2ea5b24fe2', 'Agrónomo', 'Os agrónomos prestam serviços de consultoria a empresas, cooperativas agrícolas, produtores de culturas agronómicas e produtores hortícolas no cultivo de culturas alimentares. Estudam a ciência, a tecnologia e a atividade relacionadas com a cultura de plantas. Analisam as culturas e realizam experiências a fim de melhorar o rendimento das culturas e a produção das explorações agrícolas. Os agrónomos analisam também as formas mais eficazes de colheita e cultivo.', 'released', '["Consultor em Proteção das Culturas", "Consultor em Ciências Agrárias", "Consultora em Produção Biológica", "Engenheiro Agrícola", "Engenheira Agrícola", "Agrónoma", "Engenheiro Agrónomo", "Engenheiro Técnico Agrário", "Agrónomo", "Engenheira Agrónoma", "Consultor em Produção Biológica", "Consultora em Ciências Agrárias", "Consultora em Proteção das Culturas", "Engenheira Técnica Agrária"]'::jsonb, '2132'),
  ('http://data.europa.eu/esco/occupation/c418ed9a-132f-48cd-ae5c-dd375070ee0e', 'Responsável Pelo Desenvolvimento de Relações Comerciais', 'Os responsáveis pelo desenvolvimento de relações comerciais desenvolvem e implementam políticas comerciais, quer a nível interno quer das relações internacionais de importação e exportação. Analisam os mercados nacionais e estrangeiros, a fim de promoverem e estabelecerem operações comerciais, e asseguram que os processos comerciais estão em conformidade com a legislação e que as empresas estão protegidas de distorções.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/c430500d-0b8b-4ef5-8f91-3e98cff32356', 'Diretor de Importação e Exportação de Produtos do Tabaco', 'Os diretores de importação e exportação de produtos do tabaco implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Vendas de Produtos do Tabaco", "Diretor de Importação e Exportação de Produtos do Tabaco", "Diretora de Vendas de Produtos do Tabaco", "Diretora de Importação e Exportação de Produtos do Tabaco"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/c44a118d-18c1-46ac-985f-3e802a064b73', 'Montador de Quadros Elétricos', 'Os montadores de quadros elétricos interpretam esquemas de montagem de unidades de quadros elétricos para o material elétrico. Instalam a cablagem, os comutadores, os aparelhos de controlo e de medição e os cabos com ferramentas manuais.', 'released', '["Montadora de Quadros Elétricos", "Montador de Quadros Elétricos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/c44c078d-85e4-40a3-9598-2c333d7a24ca', 'Engenheiro do Papel', 'Os engenheiros do papel asseguram um processo de produção otimizado no fabrico de papel e produtos conexos. Selecionam as matérias-primas primárias e secundárias e controlam a sua qualidade. Além disso, otimizam a utilização de máquinas e equipamentos, bem como dos aditivos químicos para a produção do papel.', 'released', '["Engenheiro do Papel", "Engenheira do Papel"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/c44c37a2-88c3-4ac2-9cf9-959f42deb02b', 'Engenheiro de Energias Marítimas Renováveis', 'Os engenheiros de energias marítimas renováveis concebem e supervisionam a instalação de parques e equipamentos de energia marítima. Estudam e testam locais para encontrar o sítio mais produtivo, asseguram a boa execução do plano de concepção, efetuam alterações eventualmente necessárias ou prestam aconselhamento específico. Os engenheiros de energias marítimas renováveis testam equipamento como pás de turbinas eólicas, geradores de correntes de maré e geradores de ondas. Desenvolvem estratégias para uma produção de energia mais eficiente e para a sustentabilidade ambiental.;', 'released', '["Engenheira ORE", "Engenheiro de Energia Renovável do Oceano", "Engenheira de Energia Renovável Marinha", "Engenheiro de Energia Renovável Marinha", "Engenheiro de Hidrodinâmica", "Engenheiro ORE", "Engenheira de Energia Renovável do Oceano", "Engenheira de Hidrodinâmica", "Engenheira de Energias Marítimas Renováveis"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/c44f9f8c-46a6-40da-9630-cc568a18cc51', 'Modelador de Metais Ornamentais', 'Os modeladores de metais ornamentais utilizam equipamento de acabamento e máquinas para dar forma e acabar peças metálicas ornamentais fabricadas, frequentemente utilizadas para o processo de instalação na construção, tais como balaustradas, escadas, pavimentos de aço aberto, vedações e portões, etc.', 'released', '["Modelador de Metais Ornamentais", "Modeladora de Metais Ornamentais"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/c453886f-a8f0-434c-be0e-e6a12c49954f', 'Polidor de Pedra', 'Os polidores de pedra operam ferramentas e equipamento de trituração e de polimento para suavizar as pedras.', 'released', '["Fabricante de Blocos de Pedra", "Operador de Máquinas de Partir Pedra", "Serrador de Pedra", "Serradora de Pedra", "Polidor de Pedra", "Polidora de Pedra", "Trituradora de Pedra", "Operadora de Máquinas de Partir Pedra", "Triturador de Pedra"]'::jsonb, '8114'),
  ('http://data.europa.eu/esco/occupation/c467efc2-6b87-429d-b0be-44512cf9535d', 'Instalador de Lareira', 'Os instaladores de lareiras instalam lareiras a lenha, a gás e elétricas em residências, de acordo com as instruções do fabricante e em conformidade com os requisitos de saúde e segurança. Efetuam as medições necessárias, preparam o equipamento e os materiais para a instalação e instalam lareiras em condições de segurança. Os instaladores de lareiras procedem à manutenção e a reparações de sistemas quando necessário. São o principal ponto de contato para os clientes, fornecem informações sobre o modo de funcionamento do produto e servem de ponte com o fabricante em caso de problemas.;', 'released', '["Técnico de Instalação de Lareira", "Prestador de Serviço de Lareira a Gás", "Técnica de Instalação de Lareira", "Técnico de Chaminé", "Construtora de Lareira", "Técnico de Lareira", "Construtor de Lareira", "Ajudante de Instalador de Lareira", "Ajudante de Instaladora de Lareira", "Técnica de Lareira", "Técnica de Chaminé", "Instaladora de Lareira"]'::jsonb, '7115'),
  ('http://data.europa.eu/esco/occupation/c4a81f47-6ed8-4a17-ab4a-21a2e67fa1d9', 'Babysitter', 'Os babysitters prestam serviços de cuidados de curta duração a crianças nas instalações do empregador, em função das necessidades do empregador. Organizam atividades de jogos e entretêm as crianças com jogos e outras atividades culturais e educativas, de acordo com a respetiva idade, preparam as refeições, dão-lhes banho, transportam-nas de e para a escola e ajudam-nas pontualmente com os trabalhos de casa.', 'released', NULL, '5311'),
  ('http://data.europa.eu/esco/occupation/c4d6d07a-ae90-40ce-bc5a-c952805a9bf3', 'Audiologista', 'Os audiologistas avaliam, diagnosticam e tratam os doentes (crianças ou adultos) com doenças audiológicas e vestibulares causadas por patologias infeciosas, genéticas, traumáticas ou degenerativas, tais como perda de audição, tonturas, desequilíbrio, hiperacusia e problemas auditivos. Podem prescrever uma ajuda auditiva e desempenhar um papel na avaliação e gestão dos doentes, que podem beneficiar de implantes cocleares. ;', 'released', '["Audioprotesista"]'::jsonb, '2266'),
  ('http://data.europa.eu/esco/occupation/c52129d9-4656-4ce8-ba13-8a72a51d5400', 'Projetista de Desenvolvimento de Produtos', 'Os projetistas de desenvolvimento de produtos elaboram e desenham planos técnicos para a concretização de novos conceitos e produtos. Elaboram e desenham planos pormenorizados sobre a forma de fabricar um produto.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/c530b0ee-46f8-40fb-818c-d9b44b891cb9', 'Gestor de Produtos Bancários', 'Os gestores de produtos bancários estudam o mercado de produtos bancários e adaptam os existentes às características da evolução ou criam novos produtos para responder às necessidades dos clientes. Acompanham e avaliam os indicadores de desempenho destes produtos e sugerem melhorias. Os gestores de produtos bancários contribuem para a estratégia de vendas e marketing do banco.', 'released', '["Gestora de Produtos Bancários", "Gestor de Produtos Bancários", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/c5328083-eda0-4ca8-b9cb-99a46e73a9bc', 'Especialista em Botânica', 'Os especialistas em botânica contribuem com conhecimentos aprofundados sobre a ciência das plantas e a botânica para a produção de bebidas alcoólicas à base de plantas aromáticas. Estes profissionais combinam os conhecimentos sobre química gustativa, ciências biológicas e processos tecnológicos. Podem operar máquinas de moagem botânica, garantindo que o processo de moagem mantém o sabor e o aroma tanto quanto possível.', 'released', '["Biólogo Especializado em Botânica", "Especialista em Botânica", "Bióloga Especializada em Botânica"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/c549f0de-c415-428e-865c-973bcd224b39', 'Professor de Linguística', 'Os professores de Linguística são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Linguística, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Linguística, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora Universitária de Linguística", "Professor de Linguística", "Professor de Linguística Aplicada", "Professor Universitário de Linguística", "Professora de Linguística"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/c56295bb-ef33-4ccd-a929-59e3dd73f876', 'Viticultor', 'Os viticultores são responsáveis pelas caves, desde a entrada de uvas ao engarrafamento no local e distribuição. Asseguram a qualidade em todas as fases, em conformidade com a regulamentação e a legislação.', 'released', '["Viticultora", "Viticultor"]'::jsonb, '6112'),
  ('http://data.europa.eu/esco/occupation/c56bb750-db0b-487b-89f4-82dee6dcab09', 'Responsável Pela Realização de Testes à Covid', 'Os responsáveis pela realização de testes à Covid fazem colheitas de amostras por meio de esfregaços nasais ou faríngeos. Complementam a informação da amostra recolhida com perguntas relacionadas com a saúde das pessoas e introduzem os dados recolhidos em dispositivos digitais.;', 'released', '["Enfermeira de Triagem Móvel", "Testadora de Coronavírus", "Assistente de Suporte de Teste", "Supervisora de Teste", "Testador de Coronavírus", "Supervisor de Teste"]'::jsonb, '3259'),
  ('http://data.europa.eu/esco/occupation/c5902c47-0c2e-45aa-94dd-951ad641449c', 'Moldador de Fundição', 'Os moldadores de fundição fabricam núcleos para moldes de metal, que são utilizados para preencher um espaço no molde que deve permanecer por preencher durante o vazamento. Utilizam madeira, plástico ou outros materiais para criar o núcleo, selecionado para suportar o ambiente extremo de um molde metálico.', 'released', '["Moldador de Fundição", "Moldadora de Fundição"]'::jsonb, '7211'),
  ('http://data.europa.eu/esco/occupation/c593ded7-2e97-44a5-a5f3-f6115ff98233', 'Professor de Ciência Política', 'Os professores de Ciência Política são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Ciência Política, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Ciência Política, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Ciência Política", "Professora Universitária de Ciência Política", "Professor de Ciência Política", "Professor Universitário de Ciência Política"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/c5b45ebe-0e9f-4bc4-9563-7fdf31115e53', 'Inspetor de Montagem de Material Circulante', 'Os inspetores de montagem de material circulante utilizam equipamento de medição e de ensaio para inspecionar e monitorizar as montagens de material circulante, a fim de garantir a conformidade com as especificações técnicas e as normas e regulamentos de segurança. Analisam os conjuntos para detectar anomalias e danos e verificam o trabalho de reparação. Também fornecem documentação de inspeção pormenorizada e recomendam medidas nos casos em que foram detectados problemas.', 'released', '["Inspetora de Montagem de Material Circulante", "Inspetor de Montagem de Material Circulante"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/c5c1c40f-d2b7-437f-b3e8-b9da48f6d728', 'Assistente de Gestão Imobiliária', 'Os assistentes de gestão imobiliária desempenham várias funções, incluindo tarefas administrativas no setor imobiliário. Fornecem aos clientes informações financeiras sobre as propriedades e aconselham-nos, programam marcações e organizam visitas imobiliárias, preparam contratos e prestam assistência na avaliação dos imóveis.', 'released', '["Assistentea de Gestão Imobiliária"]'::jsonb, '4312'),
  ('http://data.europa.eu/esco/occupation/c5d36eef-df20-47a8-a332-5b4358fa83e3', 'Analista de Telecomunicações', 'Os analistas de telecomunicações analisam e avaliam as necessidades e os sistemas de telecomunicações de uma organização. Proporcionam formação sobre as características e funcionalidades dos sistemas de telecomunicações.', 'released', '["Analista de Telecomunicações", "Analista de Sistemas de Telecomunicações"]'::jsonb, '2153'),
  ('http://data.europa.eu/esco/occupation/c5d779f4-345b-4918-872b-a1cbaeb1d9be', 'Motorista de Veículos de Transporte de Matérias Perigosas', 'Os motoristas de veículos de transporte de matérias perigosas realizam o transporte rodoviário de combustível e líquidos a granel, produtos perigosos e produtos químicos.', 'released', NULL, '8332'),
  ('http://data.europa.eu/esco/occupation/c60ede09-b67b-4173-8991-b9b694149488', 'Assistente Social em Centros de Emprego', 'Os assistentes sociais em centros de emprego prestam assistência às pessoas com dificuldades em encontrar emprego e aos desempregados de longa duração. Fornecem orientações para a criação de CV, a procura de ofertas de emprego, o contato com empregadores e a preparação para entrevistas de emprego.', 'released', '["Assistentea Social em Centros de Emprego"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/c6196b21-20f9-4608-83fb-6f143afc740d', 'Geólogo', 'Os geólogos investigam os materiais que formam a Terra. As suas observações dependem do objetivo da investigação. Em função da sua especialização, os geólogos estudam a forma como a Terra foi moldada ao longo do tempo, as suas camadas geológicas, a qualidade dos minerais para fins mineiros, sismos e atividade vulcânica para serviços privados e fenômenos similares.', 'released', '["Geóloga", "Especialista em Geologia do Quaternário", "Sismologista", "Geólogo"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/c6239b9e-5973-4b0a-a2ed-4c4b41331e04', 'Técnico de Ação Social Comunitária', 'Os técnicos de ação social comunitária realizam avaliações e cuidados de saúde das comunidades de adultos que vivem com deficiências físicas ou que estão em convalescença. Visam melhorar a sua vida na comunidade e permitir-lhes viver de forma segura e independente na sua própria casa.', 'released', '["Técnica de Ação Social Comunitária", "Técnico de Ação Social Comunitária"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/c644e6f6-dffc-4d7a-bf36-a384e465937b', 'Fabricante de Instrumentos de Teclas', 'Os fabricantes de instrumentos de teclas criam e montam peças para criar instrumentos de teclas, de acordo com instruções ou diagramas especificados. Lixam a madeira, afinam, testam e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Instrumentos de Teclas"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/c64a6e4e-5b38-4f93-b26d-aded817aeaf3', 'Diretor de Operações', 'Os diretores de operações são a mão direita e o segundo cargo na hierarquia após o diretor-geral da empresa. Asseguram o bom funcionamento diário da empresa. Os diretores de operações também desenvolvem políticas, regras e objetivos empresariais.', 'released', '["Diretora Operacional", "Diretor Operacional", "Diretor Geral Administrativo", "Diretora de Operações", "Diretor de Operações", "Diretora Geral Administrativa"]'::jsonb, '1120'),
  ('http://data.europa.eu/esco/occupation/c66b4569-09aa-4d8d-93d9-ac9b9176655d', 'Consultor de Sistemas de Segurança', 'Os consultores de sistemas de segurança prestam serviços de segurança a clientes e indivíduos que os ajudam a prevenir, planear e atenuar ameaças, tais como o terrorismo, a espionagem, o roubo e a violência contra a sua organização, incluindo os edifícios, as operações e os trabalhadores. Os serviços que prestam dependem das necessidades e dos requisitos de segurança dos clientes e podem incluir serviços como a análise de ameaças, a gestão de riscos em matéria de segurança e o desenvolvimento de programas de segurança.', 'released', '["Consultor de Sistemas de Segurança", "Consultora de Sistemas de Segurança"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/c6a26e11-bdf1-47a1-849d-fdcf819d458d', 'Oficial do Exército', 'Os oficiais do Exército supervisionam operações e manobras, atribuem funções e comandam pessoal subordinado. Asseguram uma comunicação eficiente no interior e entre as unidades e desempenham funções de formação. Utilizam equipamentos e supervisionam a manutenção de equipamentos.', 'released', '["Alferes do Exército", "Marechal do Exército", "Tenente-Capitão do Exército"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/c6bd511a-d966-4df9-a48e-4f800354f268', 'Gestor de Operações', 'Os gestores de operações controlam e coordenam as operações diárias de produção de bens e prestação de serviços. Também formulam e implementam políticas empresariais e planificam a utilização de recursos humanos e materiais.', 'released', '["Gestor de Exploração", "Diretora de Operações", "Diretora Operacional", "Gestora de Operações", "Diretor Operacional", "Gestora de Exploração", "Diretor de Operações", "Gestor de Operações", "Gerente"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/c6c48286-2037-47e3-a132-b745dce858e2', 'Médico Legista', 'Os médicos legistas supervisionam o exame de cadáveres, a fim de determinarem a causa da morte em circunstâncias invulgares. Asseguram a manutenção dos registos das mortes sob a sua jurisdição e facilitam a comunicação com outros agentes, a fim de garantir a conclusão da investigação.', 'released', '["Médica Legista", "Médico Legista"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/c6e5e0e7-fa99-4f71-9fc1-9889d85282a5', 'General do Exército', 'Os generais do Exército comandam grandes divisões do Exército. Exercem funções de gestão, funções administrativas, e tarefas de planejamento e estratégicas. Desenvolvem políticas destinadas a melhorar a defesa militar e a defesa geral e asseguram a segurança da nação.', 'released', '["Tenente-General do Exército", "General", "General das Forças Armadas", "Major-General do Exército"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/c706886d-5bc7-4430-9a72-051fc483235f', 'Operador de Máquinas de Fabricação de Produtos Absorventes em Celulose', 'Os operadores de máquinas de fabrico de produtos absorventes em celulose operam uma máquina que utiliza fibras de celulose e as comprime num material altamente absorvente para utilização em produtos de higiene, tais como fraldas e tampões.', 'released', '["Operador de Máquinas de Fabricação de Produtos Absorventes em Celulose", "Operadora de Máquinas de Fabricação de Produtos Absorventes em Celulose"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/c71ee6a5-ce48-4afd-aa1e-eaabf17ccbc0', 'Diretor de Importação e Exportação de Sucata e Desmantelamento', 'Os diretores de importação e exportação de sucata e desmantelamento implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação de Sucata e Desmantelamento", "Diretora de Importação e Exportação de Sucata e Desmantelamento", "Diretor de Vendas de Sucata e Desmantelamento", "Diretora de Vendas de Sucata e Desmantelamento"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/c737f094-7921-4d57-b883-6442343a5fd8', 'Coreólogo', 'Os coreólogos são criadores especializados de dança em estilos ou tradições específicos, como a dança étnica, a dança histórica ou a dança barroca. O seu trabalho é contextualizado histórica e sociologicamente como uma expressão do grupo humano que desenvolveu o estilo de dança em causa. Os coreólogos analisam a dança em relação aos seus aspetos intrínsecos: teoria, prática e epistemologia dos movimentos em si. Também estudam a dança de uma perspetiva extrínseca: o contexto social, etnológico, etnográfico e sociológico em que a dança foi desenvolvida.', 'released', '["Coerólogo", "Folclorista", "Coeróloga", "Coreóloga"]'::jsonb, '2653'),
  ('http://data.europa.eu/esco/occupation/c76566f1-97a1-43e9-a7d8-155db0e56987', 'Operador de Máquinas de Produção de Verniz', 'Os operadores de máquinas de produção de verniz operam equipamento e misturadores para a produção de vernizes, por fusão, mistura e cozedura dos ingredientes químicos necessários, de acordo com as especificações.', 'released', '["Operador de Máquinas de Produção de Verniz", "Operadora de Máquinas de Produção de Verniz"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/c766198e-5b9c-4c85-9fef-be27c783ab19', 'Inspetor Tributário', 'Os inspetores tributários são responsáveis pelo cálculo da tributação e pela garantia do seu pagamento atempado por pessoas e organizações. Fornecem informações e orientações relativas à legislação fiscal e analisam os documentos financeiros e as contas para assegurar o cumprimento da legislação. Também examinam registos para investigar casos de fraude.', 'released', '["Inspetora de Impostos", "Inspetora Tributária", "Inspetor de Impostos", "Inspetora Tributário"]'::jsonb, '3352'),
  ('http://data.europa.eu/esco/occupation/c76dda38-938c-404e-8a6d-78c8705eebc0', 'Supervisor de Caixa', 'Os supervisores de caixa supervisionam os operadores de caixa nas lojas e noutros estabelecimentos comerciais.', 'released', '["Supervisor de Caixa", "Supervisora de Caixa"]'::jsonb, '5222'),
  ('http://data.europa.eu/esco/occupation/c784c2db-e636-429f-8492-3191790a58d7', 'Instrutor de Fitness', 'Os instrutores de fitness ampliam a participação de membros novos e dos já existentes no centro de fitness através de experiências de fitness que deem resposta às suas necessidades. Fornecem aos indivíduos instruções de fitness, com a utilização de equipamento, ou a um grupo, através de aulas de fitness. Tanto os instrutores individuais como os de grupo têm por objetivo promover e garantir um exercício seguro e eficaz. Consoante a situação específica, poderão ser necessários conhecimentos, aptidões e competências adicionais.', 'released', '["Instrutor de Fitness", "Instrutora de Fitness"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/c7ad889f-10fc-4346-b740-bd479ad82b47', 'Técnico de Saúde Comunitária', 'Os técnicos de saúde comunitária prestam aconselhamento e informações à comunidade sobre vários temas relacionados com a saúde. Podem dar assistência na prestação de cuidados de saúde pré e pós-natais, prestar aconselhamento nutricional e ajudar os indivíduos a deixarem de fumar. Os profissionais de saúde comunitária desenvolvem programas de saúde e de prevenção.', 'released', '["Técnica de Saúde Comunitária", "Técnico de Saúde Comunitária"]'::jsonb, '3253'),
  ('http://data.europa.eu/esco/occupation/c7b31477-88e3-400f-988f-3baa090de173', 'Fabricante de Órgãos', 'Os fabricantes de órgãos criam e montam peças para construir órgãos, de acordo com instruções ou diagramas especificados. Lixam a madeira, afinam, testam e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Órgãos"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/c7c3f05b-319b-4aa7-891e-78106f875de2', 'Operador de Controle de Fabricação de Sabão', 'Os operadores de controlo de fabrico de sabão procedem ao controlo, monitorização e manutenção das operações de fabrico de sabão, utilizando o painel de controlo, a fim de produzir pós de sabão. Inspecionam as unidades operacionais para assegurar que os parâmetros do fluxo de óleo, ar, perfume ou vapor estejam de acordo com as especificações.', 'released', '["Operadora de Controle de Fabricação de Sabão", "Operador de Controle de Fabricação de Sabão"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/c7ee21d5-9a13-4cf8-a3b9-292eefd37f7a', 'Supervisor de Produção de Alimentos para Animais', 'Os supervisores de produção de alimentos para animais supervisionam o processo de fabrico dos alimentos para animais. Controlam a qualidade, recolhem amostras para laboratórios, acompanham os resultados laboratoriais e tomam medidas de acordo com os resultados.', 'released', '["Supervisora de Produção de Carne e Alimentos para Animais", "Supervisor de Produção de Carne e Alimentos para Animais", "Encarregado de Produção de Alimentos para Animais", "Encarregada de Produção de Alimentos para Animais", "Supervisora de Produção de Alimentos para Animais"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/c7f5cab7-7cfb-47d7-890c-6b9c00a9eaaf', 'Assessor de Desempenho Energético', 'Os assessores de desempenho energético determinam o desempenho energético dos edifícios. Criam um certificado de desempenho energético (CDE) que indica qual é o consumo de energia estimado de um imóvel. Além disso, prestam aconselhamento sobre a forma de reforçar a conservação de energia.', 'released', '["Assessora de Desempenho Energético", "Assessor de Desempenho Energético"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/c7ffc270-7bd2-4bb1-a51a-4766170d7935', 'Comerciante Grossista de Produtos Químicos', 'Os comerciantes grossistas de produtos químicos investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Produtos Químicos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/c81af273-1112-4b3f-a2a5-b85b1290ae22', 'Soldador a Laser', 'Os soldadores a laser instalam e cuidam das máquinas de soldar a laser concebidas para unir peças metálicas separadas através da utilização de um feixe laser que irradia uma fonte de calor concentrada que permite a soldadura exata.', 'released', '["Soldador a Laser", "Soldadora a Laser"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/c822ca35-6c36-4eab-97fa-90f2775091c3', 'Vendedor em Mercados', 'Os vendedores em mercados vendem produtos, tais como fruta, produtos hortícolas e produtos de uso doméstico, em mercados organizados ao ar livre ou em espaços interiores. Utilizam técnicas de venda para recomendar as suas mercadorias aos transeuntes.', 'released', '["Vendedora em Mercados", "Vendedor em Mercados"]'::jsonb, '5211'),
  ('http://data.europa.eu/esco/occupation/c84a055d-00fe-4789-a054-f4a62914ff6e', 'Trabalhador de Empresa de Mudanças', 'Os trabalhadores de empresa de mudanças são responsáveis pelo manuseamento físico de bens e objetos a recolocar ou transportar de um local para o outro. Desmontam bens, máquinas ou pertences para transportar e montam-nos ou instalam-nos no novo local. Asseguram que os objetos estejam bem protegidos e embalados, seguros e corretamente colocados em caminhões e transportes.', 'released', '["Trabalhadora de Empresa de Mudanças", "Trabalhador de Empresa de Mudanças"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/c8505fa5-0a33-4143-bd87-f24f569e8813', 'Empregado Responsável Pela Correspondência em Línguas Estrangeiras', 'Os empregados responsáveis pela correspondência em línguas estrangeiras leem e respondem à correspondência de uma empresa em línguas estrangeiras. Também desempenham tarefas administrativas.', 'released', '["Empregado Responsável Pela Correspondência em Línguas Estrangeiras", "Empregada Responsável Pela Correspondência em Línguas Estrangeiras"]'::jsonb, '4419'),
  ('http://data.europa.eu/esco/occupation/c85e39a4-2c40-413f-a171-45907ecdd599', 'Agente Artístico', 'Os agentes artísticos representam atores, autores, jornalistas de radiodifusão, realizadores de cinema, músicos, modelos, atletas profissionais, argumentistas, escritores e outros profissionais de diversas empresas de entretenimento ou radiodifusão. Promovem os seus clientes com o objetivo de atrair potenciais empregadores. Os agentes artísticos organizam aparições públicas, audições e espetáculos. Tratam das negociações de contratos.;', 'released', '["Agente Artística", "Agente Artístico", "Agentea Artístico"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/c871b431-2bef-4824-a504-50b60cf633f7', 'Comerciante Grossista de Tabaco', 'Os comerciantes grossistas de tabaco investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Tabaco"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/c872187a-079b-413b-8503-7b5dd92abb88', 'Consultor em Regulamentação Alimentar', 'Os consultores em regulamentação alimentar são peritos extrajudiciais ou judiciais. Garantem a conformidade das práticas da indústria alimentar com as normas regulamentares. Realizam auditorias, efetuam diagnósticos e acompanham as atividades de inspeção. Estes peritos possuem conhecimentos especializados em matéria de transformação de alimentos e de análise, qualidade, segurança, certificação e rastreabilidade de alimentos. Atualizam, reveem e aprovam modelos de rotulagem, desenvolvem tabelas de informação nutricional e asseguram que os produtos e os rótulos cumprem as normas e os regulamentos adequados.', 'released', '["Perito em Tecnologia Alimentar", "Consultora Alimentar", "Consultor Alimentar", "Perita em Tecnologia Alimentar", "Consultora em Regulamentação Alimentar"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/c89afd9a-7dad-4bae-9315-5fcadd9ad8b6', 'Técnico de Rede de Distribuição de Eletricidade', 'Os técnicos de rede de distribuição de eletricidade constroem e fazem a manutenção de sistemas de transmissão e distribuição de energia elétrica. Procedem à manutenção e à reparação de linhas elétricas, em conformidade com os regulamentos de segurança.;', 'released', '["Operadora da Rede de Distribuição", "Operador da Rede de Distribuição", "Técnica de Rede de Distribuição de Eletricidade"]'::jsonb, '7413'),
  ('http://data.europa.eu/esco/occupation/c8b296be-54ae-48cf-be21-031fa8457937', 'Assistente de Cadeia de Abastecimento', 'Os assistentes de cadeia de abastecimento trabalham em estreita colaboração com os gestores dos processos operacionais, nomeadamente os processos de compra, fabrico e distribuição. Prestam assistência no acompanhamento administrativo e pragmático de atividades como a faturação, a redação e preparação de contratos e ordens de compra, a conciliação do inventário com os documentos e a comunicação com os canais de distribuição.', 'released', '["Assistentea de Cadeia de Abastecimento"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/c8e6cdcc-824e-4887-8ee2-197e7d794258', 'Geoquímico', 'Os geoquímicos estudam as características e os elementos químicos nos minerais, nas rochas e nos solos e a forma como interagem com os sistemas hidrológicos. Coordenam a recolha de amostras e indicam o conjunto de metais a analisar.', 'released', '["Analista de Metais", "Geoquímico", "Geoquímica"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/c8ee41fc-7a5f-4255-adbd-dcc47cf2a28e', 'Caçador', 'Os caçadores seguem e perseguem animais com a intenção de os prender ou matar. Caçam animais com o objetivo de obter alimentos e outros produtos de origem animal, por lazer, comércio ou gestão da fauna e da flora selvagens. Os caçadores especializam-se na capacidade de seguir e de abater a tiro animais com armas como espingardas e arcos. Também utilizam dispositivos para apanhar animais para fins semelhantes.', 'released', '["Caçadora", "Caçador"]'::jsonb, '6224'),
  ('http://data.europa.eu/esco/occupation/c8ee6499-7613-4c02-9edf-2a0edcf47705', 'Técnico de Segurança na Aviação', 'Os técnicos de segurança na aviação planeiam e desenvolvem procedimentos de segurança para empresas do setor da aviação. Estudam os regulamentos em matéria de segurança e as restrições relativas às operações das empresas do setor da aviação. Por conseguinte, coordenam as atividades do pessoal de modo a salvaguardar a aplicação das medidas de segurança, em conformidade com a regulamentação.', 'released', '["Técnica de Segurança na Aviação"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/c8fa93eb-7c2c-42c3-b135-c2e825a6615e', 'Engenheiro de Testes', 'Os engenheiros de testes planificam e realizam testes de qualidade pormenorizados durante as várias fases do processo de concepção, a fim de garantir que os sistemas estão corretamente instalados e funcionam corretamente. Analisam os dados recolhidos durante os testes e elaboram relatórios. São igualmente responsáveis pela segurança das operações de teste.', 'released', '["Engenheira de Testes", "Engenheiro de Testes"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/c90a6ebe-adcc-4395-9f5b-ff3e96e93cef', 'Professor de Teologia', 'Os professores de Teologia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Teologia, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Teologia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Teologia", "Professor de Teologia", "Professora Universitária de Teologia", "Professor Universitário de Teologia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/c90e5009-37f2-4dcd-aea2-362fc817bc98', 'Gestor de Ambientes Informáticos', 'Os gestores de ambientes informáticos conhecem o quadro jurídico das TIC verdes, compreendem o papel das configurações de rede de TIC na economia e na utilização dos recursos energéticos e avaliam o impacto da pegada de CO2 de cada recurso TIC na rede da organização. Planificam e gerem a aplicação de estratégias ambientais para as redes e sistemas de TIC através da realização de investigação aplicada, do desenvolvimento de políticas organizacionais e da concepção de estratégias para cumprir os objetivos de sustentabilidade. Asseguram que toda a organização utiliza recursos de TIC de uma forma tão amiga do ambiente quanto possível.', 'released', '["Gestor de Ambientes Informáticos", "Gestora de Ambientes Informáticos", "Gestor Ambiental Informático", "Gestor de Ambientes de TI", "Gestor de Ambientes de Tecnologias de Informação e Comunicação", "Gestora de Ambientes de Tecnologias de Informação e Comunicação", "Gestora Ambiental Informática", "Gestora de Ambientes de TI", "Gerente"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/c9191f7f-28b5-4df8-991d-804c53009b83', 'Trabalhador de Produção Agrícola', 'Os trabalhadores da produção agrícola realizam atividades práticas e auxiliam na produção de culturas agronómicas.', 'released', '["Trabalhador de Produção Agrícola", "Trabalhadora de Produção Agrícola", "Trabalhador Agrícola", "Trabalhadora Agrícola"]'::jsonb, '9213'),
  ('http://data.europa.eu/esco/occupation/c92a4851-9418-4fb5-8201-c7e03cc2b6e2', 'Guarda de Passagem de Nível', 'Os guardas de passagem de nível operam equipamentos para a proteção das passagens de nível, em conformidade com as regras de segurança. Supervisionam a situação do tráfego na passagem de nível e comunicam com os controladores de tráfego, os condutores e outros guardas de passagem de nível, quando necessário.', 'released', '["Guarda de Passagem de Nível"]'::jsonb, '8312'),
  ('http://data.europa.eu/esco/occupation/c932109b-3e4f-43aa-b346-1ea421da0adb', 'Técnico de Interiores Aeronáuticos', 'Os técnicos de interiores aeronáuticos fabricam, montam e reparam componentes interiores de aeronaves, tais como assentos, carpetes, painéis de portas, teto, iluminação, etc. Também substituem equipamentos de entretenimento como os sistemas de vídeo. Inspecionam os materiais recebidos e preparam o interior do veículo para novos componentes.', 'released', '["Técnico de Interiores Aeronáuticos", "Técnica de Interiores Aeronáuticos"]'::jsonb, '7534'),
  ('http://data.europa.eu/esco/occupation/c93d58bd-3aa6-4de4-812d-010542f1dec8', 'Operador de Máquinas de Fabricação de Comprimidos', 'Os operadores de máquinas de fabrico de comprimidos asseguram o correto funcionamento das máquinas de fabrico de comprimidos que produzem comprimidos em vários tamanhos e formas. Também enchem a máquina com os materiais necessários, abrem as válvulas para controlar o fluxo dos materiais e regulam a temperatura da máquina.', 'released', '["Operador de Máquinas de Fabricação de Comprimidos", "Operadora de Máquinas de Fabricação de Comprimidos"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/c94dc5b2-6b23-4915-8de5-a4e6ae86d802', 'Piloto da Força Aérea', 'Os pilotos da Força Aérea operam aeronaves em missões de combate, missões de patrulha ou missões de busca e salvamento. Asseguram a manutenção das aeronaves e comunicam com as bases da Força ; Aérea e outras aeronaves, a fim de garantir a segurança e a eficácia das operações.', 'released', '["Piloto Aviador", "Piloto", "Piloto Naval", "Piloto das Forças Armadas", "Piloto de Avião Militar", "Piloto do Exército", "Pilota da Força Aérea"]'::jsonb, '0310'),
  ('http://data.europa.eu/esco/occupation/c94f3565-d987-431f-a46b-6f4e018e0bd7', 'Gestor de Programa', 'Os gestores de programa coordenam e supervisionam vários projetos que funcionam em simultâneo. Asseguram a viabilidade e a compatibilidade entre os projetos, garantindo que, de um modo geral, os projetos sob a gestão de gestores de projetos são rentáveis e equilibrados entre si.', 'released', '["Diretor de Programa", "Diretora de Programa", "Gestora de Programa", "Gestor de Programa", "Coordenador de Programa", "Coordenadora de Programa", "Gerente"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/c95121e9-e9f7-40a9-adcb-6fda1e82bbd2', 'Operador de Resíduos Perigosos', 'Os operadores de resíduos perigosos procedem à eliminação de materiais inflamáveis, corrosivos, reativos, tóxicos ou que apresentem uma combinação das características de perigosidade referidas, ou que tenham estado em contato com este tipo de substâncias. Removem os resíduos de instalações industriais ou de habitações e transportam-nos para uma unidade de tratamento, a fim de garantir que são tratados e eliminados em conformidade com a regulamentação. Podem também prestar aconselhamento sobre o tratamento adequado dos resíduos perigosos e ajudar na limpeza de derramamentos de resíduos perigosos.', 'released', '["Operador de Resíduos Perigosos", "Operadora de Resíduos Perigosos"]'::jsonb, '3116'),
  ('http://data.europa.eu/esco/occupation/c956be07-53a3-4b01-b8f8-f0c5a428eaa8', 'Representante de Vendas Comerciais', 'Os representantes de vendas comerciais prestam serviços em nome de uma empresa para vender as suas mercadorias, fornecendo simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas Comerciais"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/c9839843-6cac-4564-8aa7-de4a5b9b62e1', 'Corretor de Fundos Mutualistas', 'Os corretores de fundos mutualistas gerem e obtêm fundos de acionistas, a fim de os investirem em ações, obrigações e títulos do mercado monetário. Interagem com os investidores inquirindo-os sobre o estado das contas e os procedimentos de transação dos fundos mutualistas do cliente. Os corretores de fundos mutualistas utilizam os seus conhecimentos especializados em teoria do investimento, experiência de mercado e investigação para selecionarem os investimentos mais adequados para a sua carteira de fundos. Asseguram que as operações do fundo mutualista estão em conformidade com os requisitos legais.', 'released', '["Corretora de Fundos Mutualistas", "Corretor de Fundos Mutualistas"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/c9862fdd-53b7-4da9-b742-4302d704836c', 'Gestor de Processos Eficientes', 'Os gestores de processos eficientes planeiam e gerem programas eficientes em diferentes unidades empresariais de uma organização. Promovem e coordenam projetos de melhoria contínua destinados a alcançar a eficiência da produção, a otimizar a produtividade da mão de obra, a gerar inovação empresarial e a efetivar mudanças com impacto nas operações e nos processos empresariais, e comunicam os resultados e progressos à direção da empresa. Contribuem para a criação de uma cultura de melhoria contínua na empresa e são responsáveis por desenvolver e formar uma equipe de especialistas em processos eficientes.;', 'released', '["Gerente de Excelência em Manufatura", "Gerente de Excelência Operacional", "Facilitador Lean", "Gerente Kaizen", "Gerente de Excelência de Processo", "Especialista em Lean", "Gerente de Melhoria Contínua", "Especialista em Melhoria Contínua", "Gerente", "Gestora de Processos Eficientes"]'::jsonb, '2421'),
  ('http://data.europa.eu/esco/occupation/c9874f14-5474-43f6-b4a2-77a94f9abfb3', 'Estofador Auto', 'Os estofadores auto criam modelos de fabrico, fabricam e montam componentes interiores para automóveis, ônibus, caminhões, etc. Utilizam ferramentas elétricas, ferramentas manuais e equipamento de oficina para preparar e fixar os materiais. Também inspecionam os materiais recebidos e preparam o interior do veículo para os elementos de acabamento.', 'released', '["Estofadora Auto", "Estofador de Automóveis", "Estofadora de Veículos", "Estofadora de Automóveis", "Estofador Auto", "Estofador de Veículos"]'::jsonb, '7534'),
  ('http://data.europa.eu/esco/occupation/c995fe34-0909-4ce3-b7b7-97945efede56', 'Video Designer', 'Os video designers elaboram um conceito de design de imagem para um espetáculo e supervisionam a sua execução. O seu trabalho baseia-se na investigação e na visão artística. Os seus desenhos são influenciados por, e influenciam, outros desenhos e devem estar em conformidade com esses desenhos e com a visão artística global. Por conseguinte, os designers trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Os video designers preparam os fragmentos de multimédia para utilização num espetáculo, o que pode envolver o registo, a composição, a manipulação e a edição. Durante os ensaios e o espetáculo, podem dirigir os operadores com vista a obter os melhores tempos e manipulação. Os video designers desenvolvem planos, mapas, listas de orientação e outros documentos para apoiar os operadores e os artistas. Por vezes, os video designers trabalham também como artistas autónomos, criando artes de vídeo paralelamente a um contexto de espetáculo.', 'released', '["Videa Designer"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/c9a5f7c5-0f8b-4252-9729-5f19c105ef81', 'Técnico de Manutenção de Estradas', 'Os técnicos de manutenção de estradas inspecionam e gerem estradas em áreas delimitadas para fins de manutenção e reparação. Ajudam a reduzir o tráfego de forma segura e fluida e verificam se os sinais de trânsito, as estradas e os pavimentos estão em bom estado.', 'released', '["Técnica de Manutenção de Estradas", "Técnico de Manutenção de Estradas"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/c9b2b0a7-0adc-4ca7-bf7c-dc95e18aeac7', 'Responsável Pelo Apoio à Contratação Pública', 'Os responsáveis pelo apoio à contratação pública prestam assistência aos membros do pessoal ao longo de todo o ciclo da contratação pública, certificando-se de que todos os documentos de concurso cumprem os requisitos processuais, técnicos e jurídicos, velando pela boa organização das reuniões e de outros contatos.;', 'released', '["Compradora Júnior", "Escriturária de Compras", "Comprador Júnior", "Assistente de Compras", "Escriturário de Compras"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/c9d89e09-d57f-4980-9164-880e60711e97', 'Diretor de Instituição do Ensino Básico', 'Os diretores de instituição do ensino básico gerem as atividades quotidianas de uma escola primária ou do ensino básico. Gerem o pessoal, tomam decisões sobre as admissões e são responsáveis pelo cumprimento das normas curriculares adequadas à idade dos alunos do ensino primário e facilitam a educação para o desenvolvimento social e académico. Além disso, asseguram que a escola cumpre os requisitos nacionais em matéria de educação previstos na lei.', 'released', '["Diretor de Instituição do Ensino Básico", "Diretora de Escola Primária", "Diretora de Instituição do Ensino Básico", "Diretor de Escola Primária"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/c9f6c245-8c66-4b13-9253-9835194abb23', 'Técnico de Instalação de Vidro', 'Os técnicos de instalação de vidro medem, cortam, montam e instalam vidro plano e espelhos. Também carregam e descarregam vidro, espelhos e equipamento, conduzem até aos locais de instalação, instalam estruturas de metal ou madeira que precisam de ser equipadas com vidro e trabalham de acordo com as especificações dos clientes.', 'released', '["Técnico de Instalação de Vidro", "Técnica de Instalação de Vidro"]'::jsonb, '7315'),
  ('http://data.europa.eu/esco/occupation/ca2da084-3bfa-47d8-84ba-ef890191708d', 'Fabricante de Vermute', 'Os fabricantes de vermute realizam todos os processos de produção necessários para a produção do vermute. Misturam ingredientes e produtos vegetais com vinho e outras bebidas alcoólicas. Procedem à maceração, mistura e filtragem de bebidas, juntamente com os ingredientes de origem vegetal. Também gerem a maturação das bebidas e preveem quando o vermute está pronto para engarrafamento.', 'released', '["Operador de Fabricação de Vermute", "Técnica de Produção de Vermute", "Técnico de Produção de Vermute", "Operadora de Fabricação de Vermute", "Fabricantea de Vermute"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/caa75a5b-b32f-4d57-bffa-03dbb91058cf', 'Gestor de Produção de Café Verde', 'Os gestores de produção de café verde organizam e gerem as operações dos trabalhadores das fábricas de café e planeiam o funcionamento das máquinas que misturam vários tipos de grãos de café verde.', 'released', '["Gestor de Produção de Café Verde", "Gestora de Produção de Café Verde", "Encarregado de Produção de Café Verde", "Encarregada de Produção de Café Verde", "Gerente"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/caafca69-9faa-4850-8930-a3fa07fea4e6', 'Técnico Oficial de Contas', 'Os técnicos oficiais de contas avaliam as demonstrações financeiras de clientes, geralmente empresas, onde se incluem a demonstração de receitas, o balanço, a demonstração dos fluxos de caixa e notas adicionais a outras demonstrações financeiras. Interpretam e aplicam novos sistemas e procedimentos contabilísticos e analisam e determinam se os sistemas propostos estão em conformidade com a regulamentação contabilística e satisfazem os requisitos de informação do usuário.', 'released', '["Técnica Oficial de Contas", "Técnico Oficial de Contas"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/cadbf9af-1da0-406f-8282-b6d27a7e1a74', 'Operador de Montagem de Estruturas ao Nível do Solo', 'Os operadores de montagem de estruturas ao nível do solo montam estruturas de suspensão temporária para apoio ao equipamento de espetáculos. O seu trabalho baseia-se em instruções e planos. Trabalham tanto no exterior como no exterior. Cooperam estreitamente com os operadores de montagem de estruturas em altura. \;', 'released', '["Operadora de Montagem de Estruturas ao Nível do Solo", "Operador de Montagem de Estruturas ao Nível do Solo"]'::jsonb, '7215'),
  ('http://data.europa.eu/esco/occupation/cae71f3f-ad4d-480e-b501-bff22827e60c', 'Operador de Buldózer', 'Os operadores de buldózer operam um veículo pesado para transportar terra, escombros ou outro material no solo.', 'released', '["Operadora de Buldózer", "Operador de Buldózer"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/caf7b8fb-b2d6-46b7-bffa-bea7f8e4aed8', 'Analista de Políticas', 'Os analistas de políticas investigam, analisam e desenvolvem políticas em diversos setores públicos e adaptam e aplicam estas políticas com vista a melhorar a regulamentação existente nestes setores. Avaliam os efeitos das políticas existentes e comunicam as conclusões ao governo e aos cidadãos. Os analistas de políticas trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/cb3432f8-bad7-4703-ba66-dc980a4ce4f7', 'Operativo de Sucata Metálica', 'Os operativos de sucata metálica cortam grandes chapas de sucata metálica a fim de prepará-las para serem utilizadas numa fundição.', 'released', '["Operativo de Sucata Metálica", "Operativa de Sucata Metálica"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/cb3b2662-774a-4e6f-841e-f120244d7031', 'Sargento', 'Os sargentos comandam esquadras como segundos graduados. Atribuem tarefas e funções, supervisionam o equipamento e asseguram a formação adequada do pessoal. Aconselham também os oficiais de comando e desempenham funções de apoio.', 'released', '["Furriel", "Sargento-Mor", "Sargento-Chefe", "Segundo Sargento", "Sargento Ajudante", "Primeiro Sargento", "Sargenta"]'::jsonb, '0210'),
  ('http://data.europa.eu/esco/occupation/cb3c0f82-a79b-4518-ad1f-5463b3e74831', 'Operador de Escrêiperes', 'Os operadores de escrêiperes trabalham com um equipamento pesado móvel que raspa a camada superior da terra e a deposita numa tremonha para ser removida. Conduzem o escrêiper sobre a superfície a ser raspada, adaptando a velocidade da máquina à dureza da superfície.', 'released', '["Operadora de Escrêiperes", "Operador de Escrêiperes"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/cb446db8-e8b3-418c-a21c-2d10faea42a5', 'Diretor de Central de Energia', 'Os diretores de central de energia supervisionam as operações nas centrais elétricas que produzem e transportam energia. Coordenam a produção de energia na fábrica e supervisionam a construção, a exploração e a manutenção das redes e sistemas de transporte e distribuição de energia.', 'released', '["Diretora de Central Termoelétrica", "Diretor de Central de Energia", "Diretor de Central Nuclear", "Diretor de Central Termoelétrica", "Diretora de Central Nuclear", "Diretora de Central de Energia"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/cb4f98c8-6b8d-41d8-87eb-a2a2033a3a25', 'Especialista em Contratação Pública', 'Os especialistas em contratação pública são profissionais da área a tempo inteiro que fazem parte de uma equipe de contratação pública numa grande organização ou central de compras e intervêm em todas as fases do ciclo de contratação pública. Traduzem as necessidades em contratos e proporcionam uma boa relação custo-benefício à organização e ao público.;', 'released', '["Especialista em Compras Públicas e Contratos", "Oficial de Contratação de Compras Públicas", "Agente de Compras Públicas", "Consultor de Compras Públicas", "Consultora de Compras Públicas"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/cb60beab-7afb-4e99-8162-221abea68e6d', 'Conselheiro em Direitos do Consumidor', 'Os conselheiros em direitos do consumidor prestam assistência aos consumidores com queixas e prestam aconselhamento e informação sobre os direitos enquanto consumidor após a aquisição de produtos ou serviços. Acompanham as organizações para garantir o cumprimento das normas em matéria de direitos dos consumidores e ajudam os consumidores na resolução de litígios.', 'released', '["Conselheira em Direitos do Consumidor", "Conselheiro em Direitos do Consumidor"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/cb8be514-9388-4ef0-a58d-cff496747610', 'Montador de Feixes de Cabos', 'Os montadores de feixes de cabos unem fios ou cabos para formar feixes de cabos utilizados nos sistemas e equipamentos eletrônicos e elétricos. Interpretam os planos de cablagem elétrica e atam os fios em conjunto de acordo com as especificações, utilizando abraçadeiras, atilhos para cabos, condutas elétricas e mangas.', 'released', '["Montadora de Feixes de Cabos", "Montador de Arneses", "Montadora de Cabos de Ligação", "Montadora de Arneses", "Montador de Cabos de Ligação", "Montador de Feixes de Cabos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/cb932c74-c13b-47e9-9a85-318bd8eb2f96', 'Técnico de Limpeza de Trens', 'Os técnicos de limpeza de comboios mantêm os interiores dos comboios arrumados e limpos. Esvaziam os contentores nos diferentes compartimentos e realizam outras atividades de limpeza, tais como aspirar, lavar o chão e a limpeza profunda.', 'released', '["Técnico de Limpeza de Trens", "Técnica de Limpeza de Trens"]'::jsonb, '9112'),
  ('http://data.europa.eu/esco/occupation/cb93fd23-1f51-4495-867a-936c1967066b', 'Diretor de Arte', 'Os diretores de arte definem a configuração visual de um conceito. Criam projetos inovadores, desenvolvem projetos artísticos e gerem a cooperação entre todos os aspetos envolvidos. Os diretores de arte podem realizar trabalhos criativos no teatro, em marketing, em publicidade, em filmes, na moda ou em empresas em linha. Garantem que o trabalho realizado é visualmente apelativo para o público.', 'released', '["Diretor de Arte", "Diretora de Arte"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/cbad55a4-c7cf-4ab6-9540-eac72b26729b', 'Auxiliar de Limpeza', 'Os empregados de limpeza realizam todas as atividades de limpeza necessárias para limpar as casas dos clientes. Aspiram e varrem os pavimentos, lavam a louça, lavam a roupa, limpam o pó, esfregam e pulem superfícies e desinfetam equipamento e materiais.', 'released', '["Empregada de Limpeza", "Empregada Doméstica", "Empregado Doméstico", "Empregado de Limpeza"]'::jsonb, '9111'),
  ('http://data.europa.eu/esco/occupation/cbdb80db-c760-4b68-b074-88c397650ef5', 'Diretor Editorial', 'Os diretores editoriais supervisionam a produção de notícias para jornais, revistas, revistas especializadas e outros meios de comunicação social. Gerem as operações quotidianas de uma publicação e garantem que fica pronta a tempo.', 'released', '["Diretor Editorial", "Diretora Editorial", "Editor-Chefe", "Editora-Chefe"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/cbdbe324-81fe-48da-a8f7-0106dd94a05b', 'Operador de Processamento de Gás Industrial', 'Opera e monitora unidades de processamento de gás natural e industrial, controlando compressores, bombas, trocadores de calor, válvulas e sistemas de segurança. Realiza inspeções, testes e manutenção preventiva, registra parâmetros de pressão, temperatura e vazão e atua na identificação e correção de desvios para garantir qualidade, continuidade operacional e segurança.', 'released', '["Operador de Processamento de Gás Industrial", "Operador de Unidade de Processamento de Gás", "Operador de Unidade de Transformação de Gás", "Operador de Processo Químico", "Operador de Utilidades", "Operador de Painel", "Operador de Sistemas de Gás", "Operador de Compressores", "Operadora de Processamento de Gás Industrial"]'::jsonb, '3133'),
  ('http://data.europa.eu/esco/occupation/cbde1a3a-406d-4d17-b30b-03981925035d', 'Analista Energético', 'Os analistas energéticos avaliam o consumo de energia em edifícios pertencentes a particulares e empresas. Na análise dos sistemas energéticos existentes, recomendam alternativas eficazes em termos de custos. Os analistas energéticos sugerem melhorias em termos de eficiência, realizam análises empresariais e participam no desenvolvimento de políticas relativas à utilização de combustíveis tradicionais, ao transporte e a outros fatores relacionados com o consumo de energia.', 'released', '["Analista de Gestão Energética", "Analista Energético", "Analista Energética"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/cbde2432-cb7f-451f-a686-b22cad3957a6', 'Professor de Teatro', 'Os professores de teatro ensinam aos alunos os vários gêneros de teatro e formas de expressão dramática, como a comédia, a tragédia, a prosa, a poesia, a improvisação, os monólogos, os diálogos, etc., num contexto recreativo. instruíram os alunos num contexto recreativo nos vários gêneros de teatro e formas dramáticas, como a comédia, a tragédia, a prose, a poesia, a improvisação, os diálogos, etc. Proporcionam aos alunos uma noção da história e do repertório do Teatro, mas centram-se sobretudo numa abordagem prática na suas aulas, nas quais ajudam os alunos a experimentar e a dominar diferentes estilos e técnicas de expressão dramática e a desenvolver o seu próprio estilo. Criam, dirigem e produzem peças de teatro e outros espetáculos e coordenam a produção técnica e o palco, adereços e trajes.', 'released', '["Professor de Teatro", "Professora de Drama", "Professor de Drama", "Professora de Teatro", "Professora de Artes Dramáticas", "Professor de Artes Dramáticas"]'::jsonb, '2355'),
  ('http://data.europa.eu/esco/occupation/cc325a8f-702e-4bf0-893f-5b5d456475ad', 'Gestor de Identidade na Cloud', 'Os gestores de identidade na cloud trabalham com aplicações de gestão do acesso e da identidade. Colaboram com os quadros superiores para fazer face aos principais riscos na gestão da identidade. Planejam estratégias para cumprir as normas profissionais.', 'released', '["Gestora de Identidade na Cloud", "Gestor de Identidade na Cloud", "Gerente"]'::jsonb, '2514'),
  ('http://data.europa.eu/esco/occupation/cc844eb8-c81d-40ff-af3d-119700e60f23', 'Técnico de Compras de Guarda Roupa', 'Os técnicos de compras de guarda-roupa trabalham com o designer de guarda-roupa, a fim de identificarem os materiais para o guarda-roupa. Compram e alugam tecidos, fios, acessórios e outros artigos necessários para terminar o guarda-roupa. Os técnicos de compras de guarda-roupa podem também comprar artigos de vestuário feitos em série, ou seja prontos a vestir. Baseiam as suas compras nos esboços do designer de guarda-roupa.', 'released', '["Técnico de Compras de Guarda Roupa", "Técnica de Compras de Guarda Roupa"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/cc867bee-ab5c-427f-9244-f7a204d9574b', 'Engenheiro de DevOps de Computação em Cloud', 'Os engenheiros de DevOps de computação em cloud implementam e gerem sistemas e metodologias de entrega contínua de software. Tal inclui a gestão e configuração de repositórios de códigos, serviços de construção, testes automatizados e mecanismos de implantação. Para as cargas de trabalho baseadas na cloud, os engenheiros de DevOps de computação em cloud definem e implementam a infraestrutura como código, automatizando os ambientes de teste e de desenvolvimento. Podem definir e configurar soluções automatizadas de recuperação após desastre, que satisfaçam os objetivos empresariais.', 'released', '["Engenheira de DevOps de Computação em Cloud", "Engenheiro de DevOps de Computação em Cloud"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/cc8f929a-75fa-404d-aa17-3301fb494b4f', 'Calibrador de Produtos', 'Os calibradores de produtos procedem ao controlo da qualidade preventivo e operacional dos produtos e dos recursos. Inspecionam, calibram e avaliam os materiais em várias fases, a fim de garantir a sua conformidade com a norma desejada, e devolvem o produto para reparação ou melhoramento, se necessário. Trabalham em empresas e instalações industriais para assegurar que os produtos produzidos cumprem as normas de qualidade.', 'released', '["Calibrador de Produtos", "Calibradora de Produtos"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/cc937d5f-4072-4fe7-bc23-2c9a465b8754', 'Diretor de Museu', 'Os diretores de museu supervisionam a gestão das coleções, dos artefactos e das instalações de exposição. Adquirem e vendem obras de arte, por um lado, e procuram preservar e manter a coleção de arte de um museu, por outro. Além disso, gerem igualmente as finanças, os trabalhadores e os esforços de marketing do museu.', 'released', '["Conservadora de Museu", "Diretora de Galeria de Arte", "Diretora de Museu", "Diretor de Museu", "Diretor de Galeria de Arte", "Conservador de Museu"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/cc9fcab5-a5c6-4cc9-9606-cbcc2852537f', 'Curador de Jardim Botânico', 'Os curadores de jardim botânico desenvolvem e mantêm as seleções, espécimes e paisagens botânicas do jardim botânico.', 'released', '["Curadora de Jardim Botânico", "Curador de Jardim Botânico"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/ccbb7213-79f7-489e-9dad-f90091e550d0', 'Diretor de Importação e Exportação de Vestuário e Calçado', 'Os diretores de importação e exportação de vestuário e calçado implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Vestuário e Calçado", "Diretor de Vendas de Vestuário e Calçado", "Diretora de Importação e Exportação de Vestuário e Calçado", "Diretor de Importação e Exportação de Vestuário e Calçado"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/ccf0becd-247d-4497-9ee7-25a46c1ffb7a', 'Vendedor de Jornais, Revistas e Artigos de Papelaria', 'Os vendedores de jornais, revistas e artigos de papelaria vendem jornais e material de escritório, tais como canetas, lápis, papel, etc., em lojas especializadas.', 'released', '["Vendedora de Jornais, Revistas e Artigos de Papelaria", "Vendedor de Jornais, Revistas e Artigos de Papelaria"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/cd19e8d1-6abd-4c99-a9bb-85e7c30aca31', 'Chefe de Máquinas', 'Os chefes de máquinas são responsáveis pela totalidade das operações técnicas da embarcação, incluindo das divisões de engenharia, elétrica e mecânica. São os responsáveis máximos da totalidade da casa das máquinas do navio. Têm a responsabilidade global por todas as operações técnicas e pelos equipamentos instalados a bordo do navio. Os chefes de máquinas colaboram em matéria de segurança, sobrevivência e cuidados de saúde a bordo do navio, observando as normas nacionais e internacionais de aplicação.', 'released', '["Chefea de Máquinas"]'::jsonb, '3151'),
  ('http://data.europa.eu/esco/occupation/cd3f5356-a16f-4aca-9d4b-ceba2b2afec5', 'Estofador de Mobiliário', 'Os estofadores de mobiliário dotam o mobiliário de estofamento, molas, cintas e coberturas. Por vezes, têm de remover o estofamento antigo, o enchimento e as molas partidas antes de substituí-los, utilizando ferramentas, tais como um arrancador de tachas, cinzel ou maço. O objetivo é assegurar o conforto e a beleza dos assentos e encostos do mobiliário.', 'released', '["Estofadora de Mobiliário", "Estofador de Mobiliário"]'::jsonb, '7534'),
  ('http://data.europa.eu/esco/occupation/cd4f41a5-87a6-4b3c-8ee3-14e6f457c365', 'Gestor de Auditoria', 'Os gestores de auditoria supervisionam o pessoal de auditoria, o planejamento e a comunicação financeira e analisam os documentos de trabalho de auditoria automatizada do pessoal de auditoria, a fim de garantir a conformidade com a metodologia da empresa. Elaboram relatórios, avaliam as auditorias gerais e as práticas operacionais e comunicam as conclusões à direção.', 'released', '["Gestor de Auditoria", "Gestora de Auditoria", "Gerente"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/cd7b838c-51f6-41ec-9067-bb974c0f991b', 'Diretor de Comunicação', 'Os diretores de comunicação são responsáveis pelo desenvolvimento de estratégias de comunicação destinadas a promover a missão, os serviços ou os produtos da empresa. Coordenam projetos de comunicação e gerem as comunicações transmitidas pela empresa aos clientes internos e externos. Supervisionam as comunicações internas, assegurando que chegam a todos os trabalhadores e que é possível dar resposta a todas as perguntas. No que respeita às comunicações externas, coordenam a coerência das mensagens transmitidas por correio eletrônico, materiais impressos, artigos de imprensa e materiais de promoção da empresa. Esforçam-se por assegurar que as informações comunicadas correspondem à verdade.;', 'released', '["Diretora de Comunicações Internas", "Gestora de Redes Sociais", "Diretora de Comunicações Externas", "Diretor de Comunicações Externas", "Porta-Voz", "Gestor de Redes Sociais", "Diretor de Comunicações Internas", "Diretora de Comunicação"]'::jsonb, '1222'),
  ('http://data.europa.eu/esco/occupation/cd92596c-bd96-4126-8b67-7bf6ed2ca8fb', 'Técnico de Mecatrônica Naval', 'Os técnicos de mecatrónica naval trabalham em estaleiros e navios para configurar e otimizar sistemas e planos mecatrónicos industriais, supervisionar e proceder à sua montagem e manutenção.;', 'released', '["Tecnólogo em Mecatrônica Náutica", "Técnico em Mecatrônica Naval", "Técnica em Mecatrônica Náutica", "Técnico de Mecatrônica de Navio", "Tecnólogo em Mecatrônica Marinha", "Tecnólogo em Mecatrônica Naval", "Técnico de Mecatrônica Marítima", "Tecnólogo em Mecatrônica Marítima", "Técnica de Mecatrônica Marítima", "Técnica em Mecatrônica Naval", "Técnica de Mecatrônica de Navio", "Técnico em Mecatrônica Náutica", "Técnica de Mecatrônica Naval"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/cd94def5-3442-4c2e-ae3d-0761a3008bcb', 'Operador de Armazém', 'Os operadores de armazém preparam manualmente as encomendas. Recolhem as encomendas e levam-nas para a plataforma de entrega para tratamento, ou no setor comercial, a fim de permitir que os clientes as recolham. Devem concluir as encomendas para expedição, tendo em conta a quantidade e o tipo de mercadorias especificadas, e cumprir os critérios de qualidade estabelecidos pela empresa. Também reúnem vários tipos de mercadorias para expedição e transportam as encomendas para os locais de expedição especificados por um supervisor. Geralmente, empilham manualmente artigos agrupados em paletes, são responsáveis pela embalagem dos artigos na palete, para protegê-los durante a sua deslocação, bem como por garantir a integridade da palete.', 'released', '["Operador de Armazém", "Operadora de Armazém"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/cdd3d773-75a4-4f35-bd1d-1ac720afcf9d', 'Auditor de Sistemas de Informação', 'Os auditores de sistemas de informação realizam auditorias aos sistemas de informação, às plataformas e aos procedimentos operacionais, em conformidade com as normas empresariais estabelecidas em matéria de eficiência, exatidão e segurança. Avaliam as infraestruturas de tecnologia da informação em termos de risco para a organização e estabelecem controles para atenuar as perdas. Determinam e recomendam melhorias relativamente aos atuais controles de gestão de riscos e à implementação de alterações ou atualizações dos sistemas.', 'released', '["Auditor de Sistemas de Tecnologia da Informação", "Auditor de Sistemas de Informação", "Auditora de Sistemas de Informação", "Auditora de Sistemas de Tecnologia da Informação"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/cdef4961-fcc2-4e00-bfe8-4480b33aa6f3', 'Supervisor de Soldadura', 'Os supervisores de soldadura supervisionam o fluxo de trabalho das aplicações de soldadura. Acompanham os processos de soldadura realizados por outros soldadores, supervisionam o pessoal, sendo por vezes responsáveis pela formação profissional. Também soldam peças particularmente exigentes. Os supervisores de soldadura asseguram que o equipamento de soldadura necessário esteja pronto para utilização. Coordenam, em geral, as aplicações de soldadura e as atividades profissionais conexas.', 'released', '["Supervisora de Soldadura", "Supervisor de Soldadura"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/ce2b8609-34c7-40d3-a4f7-581c76bd258a', 'Inspetor da Polícia', 'Os inspetores da polícia coordenam e supervisionam uma divisão num departamento de polícia. Asseguram a conformidade da divisão com as regras e os regulamentos e supervisionam o desempenho do pessoal, bem como a atribuição das respetivas tarefas. Desempenham funções administrativas para assegurar a manutenção de registos e relatórios e podem também elaborar orientações regulamentares.', 'released', '["Inspetora da Polícia", "Inspetor da Polícia"]'::jsonb, '3355'),
  ('http://data.europa.eu/esco/occupation/ce53a1b2-2fec-4d04-9390-47fb3dd525f0', 'Assistente Social Especialista em Integração Social', 'Os assistentes sociais especialistas em integração social ajudam pessoas desfavorecidas ou excluídas da sociedade a mudar a sua situação e a lidar com os seus problemas de integração. Trabalham com comunidades e focam-se em grupos específicos. Os assistentes sociais especialistas em integração social mantêm uma ligação estreita com assistentes sociais, escolas, autoridades locais e agentes de liberdade condicional que representam as pessoas perante os decisores políticos a nível local e nacional.', 'released', '["Assistentea Social Especialista em Integração Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/ce594060-b05a-45d8-ac41-1cf3bb980085', 'Costureiro de Calçado', 'Os costureiros de calçado unem as peças cortadas de couro e outros materiais, utilizando ferramentas simples, tais como agulhas, alicates e tesouras, para produzir as gáspeas. Também realizam pontos à mão para fins decorativos ou para a montagem das gáspeas nas solas, no caso de calçado completo.', 'released', '["Costureira de Calçado", "Costureiro de Calçado"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/ce5b1eb1-5862-4f00-a813-0f90aecd5ef5', 'Operador de Galvanização por Imersão', 'Os operadores de galvanização por imersão instalam e asseguram o correto funcionamento de tanques de imersão, que são máquinas de revestimento, concebidas para fornecer às peças acabadas um revestimento duradouro, mergulhando-as num tipo específico de tinta, conservante ou zinco fundido.', 'released', '["Operadora de Galvanização por Imersão", "Operador de Galvanização por Imersão"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/ce6230b8-154f-4e0b-ac03-dca3a269a19c', 'Diretor de Centro Cultural', 'Os diretores de centro cultural gerem as operações de um centro cultural comunitário, organizam e promovem atividades e eventos culturais, gerem o pessoal e visam promover a inclusão global de programas culturais na comunidade.', 'released', '["Diretora de Centro Cultural", "Diretor de Centro Comunitário", "Diretor de Centro Cultural", "Diretora de Centro Comunitário"]'::jsonb, '1431'),
  ('http://data.europa.eu/esco/occupation/ce7d3362-5383-47d1-b66f-57b021c3d862', 'Produtor de Rádio', 'Os produtores de rádio são responsáveis pela organização da produção de programas de rádio. Supervisionam aspetos dos programas de rádio como o conteúdo, a produção de áudio, o planejamento de recursos e a supervisão do pessoal.', 'released', '["Produtora de Rádio", "Produtor de Rádio"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/ce8145f5-d7ea-40ea-b12e-ef168f11184a', 'Artista de Som', 'Os artistas de som utilizam o som como suporte criativo principal. Expressam, através da criação de sons, a sua intenção e identidade. A arte sonora é de natureza interdisciplinar e assume formas híbridas.', 'released', NULL, '2652'),
  ('http://data.europa.eu/esco/occupation/cea4d5c9-7805-434a-8e6b-af5e9fa54c9e', 'Operador de Scanner', 'Os operadores de scanner cuidam dos scanners. Fornecem os materiais de impressão para a máquina e definem os controlos na máquina ou num computador de controlo para obter uma digitalização com a resolução mais elevada.', 'released', '["Operadora de Scanner", "Operador de Scanner"]'::jsonb, '7321'),
  ('http://data.europa.eu/esco/occupation/ceb1a21b-a6d5-49eb-a3f3-d53fec25d5f8', 'Comerciante Grossista de Vestuário e Calçado', 'Os comerciantes grossistas de vestuário e calçado investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Vestuário e Calçado"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/ceb5277b-2c4d-4cb9-9b7e-b386e66e11ba', 'Operador de Máquina de Pregar', 'Os operadores de máquina de pregar trabalham com máquinas que pregam elementos de madeira juntos, regra geral hidraulicamente. Colocam os elementos a ser pregados na posição correta e acompanham o processo para evitar períodos de paragem.', 'released', '["Operador de Máquina de Pregar", "Operadora de Máquina de Pregar"]'::jsonb, '7523'),
  ('http://data.europa.eu/esco/occupation/ceb9910a-1174-4926-82c9-5afee2bd3702', 'Supervisor de Instalação de Vidros', 'Os supervisores de instalação de vidros acompanham o processo de instalação de vidro plano. Atribuem tarefas e tomam decisões rápidas para resolver problemas.', 'released', '["Supervisor de Instalação de Vidros", "Supervisora de Instalação de Vidros"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/ceda53cd-3f1f-425b-bd1b-c4fa17254680', 'Gestor de Fundos de Pensões', 'Os gestores de fundos de pensões coordenam os regimes de pensões de modo a proporcionar benefícios de reforma a indivíduos ou organizações. Asseguram a utilização diária do fundo de pensões e definem a política estratégica de desenvolvimento de novos pacotes de pensões.', 'released', '["Gestora de Fundos de Pensões", "Gestor de Fundos de Pensões", "Gerente"]'::jsonb, '1346'),
  ('http://data.europa.eu/esco/occupation/ceda6443-e1dd-4890-b018-42318e3abac2', 'Sofrologista', 'Os sofrologistas procuram reduzir o stress dos seus clientes e produzir condições ótimas de saúde e bem-estar através da aplicação de um método de relaxamento dinâmico, que consiste num conjunto específico de exercícios físicos e mentais, por indicação de um médico.', 'released', NULL, '3255'),
  ('http://data.europa.eu/esco/occupation/cee31c49-abe9-4f29-ad10-5eefe63f2a57', 'Gestor de Locação Imobiliária', 'Os gestores de locação imobiliária desenvolvem atividades de locação ou arrendamento de uma comunidade de apartamentos e de propriedades que não gozem do regime de copropriedade e gerem o pessoal responsável pela locação. Produzem, acompanham e gerem depósitos e documentos referentes ao processo de locação. Também supervisionam a administração da locação e elaboram os orçamentos de locação numa base anual e mensal. Além disso, promovem ativamente as vagas disponíveis a fim de obterem novos residentes, mostram propriedades a potenciais inquilinos e marcam presença na celebração dos contratos entre os senhorios e os inquilinos, no caso das propriedades privadas.', 'released', '["Gestora de Locação Imobiliária", "Gestor de Locação Imobiliária", "Gerente"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/cf2b03cd-feb7-4f47-90f6-ff1ed6016d3d', 'Engenheiro de Redes Informáticas', 'Os engenheiros de redes informáticas implementam, efetuam a manutenção e prestam apoio a redes informáticas. Executam também a modelagem, a análise e o planejamento das redes. Podem igualmente conceber medidas de segurança de redes e informática. Podem ainda pesquisar e recomendar hardware e software de redes e de comunicação de dados.', 'released', '["Configurador de Redes", "Configuradora de Redes", "Engenheiro de Redes", "Engenheira de Redes", "Responsável Pelo Desenvolvimento de Redes", "Engenheira de Redes Informáticas"]'::jsonb, '2523'),
  ('http://data.europa.eu/esco/occupation/cf578f1d-1832-4a4d-a3b2-e0a00517b51d', 'Operador de Pré-Impressão', 'Os operadores de pré-impressão criam uma prova de pré-impressão, ou uma amostra de qual será o aspeto do produto acabado. Em muitos contratos de impressão, o cliente decide, nesta fase, se a impressão pode ser feita de acordo com o previsto. Uma vez que os processos de impressão de provas são diferentes dos utilizados no processo final, as provas são sempre uma apresentação aproximada.', 'released', '["Operador de Pré-Impressão", "Operadora de Pré-Impressão"]'::jsonb, '7321'),
  ('http://data.europa.eu/esco/occupation/cf74a14f-f1fe-4008-a935-5c173f246655', 'Operador de Máquinas para Fabricação de Colchões', 'Os operadores de máquinas para fabrico de colchões utilizam máquinas para formar colchões. Criam almofadas e revestimentos e cortam, espalham e fixam o enchimento e o material de revestimento sobre as montagens interiores de molas.', 'released', '["Operadora de Máquinas de Fabricação de Colchões", "Operador de Máquinas para Fabricação de Colchões", "Operadora de Máquinas para Fabricação de Colchões"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/cf7b89d0-1cf9-4567-a8bf-9d6905a2b31b', 'Regente de Coro', 'Os regentes de coro gerem vários aspetos da representação vocal, e, por vezes, instrumental de grupos musicais, como coros, conjuntos ou grupos corais.', 'released', '["Maestro de Coro", "Maestro de Coral", "Regente de Coral", "Regentea de Coro"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/cf9b6da9-3a59-4780-bec9-500b148b8878', 'Podólogo', 'Os podólogos são especialistas dos pés que estudam a fisiologia e a patologia dos pés de um ponto de vista estrutural e funcional. Avaliam, diagnosticam e tratam os problemas físicos, desportivos, de reabilitação, médicos e cirúrgicos dos pés e dos membros inferiores na prática clínica. Exercem a sua atividade fora do ambiente clínico em atividades de investigação, médico-legais e forenses. Os podólogos atuam no âmbito da sua formação de podologia, experiência e autoridade de regulação do seu país.', 'released', '["Podólogo", "Podóloga"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/cfda19c9-c7e1-497d-a18b-66e29c773745', 'Gestor do Espaço Aéreo', 'Os gestores do espaço aéreo controlam atividades destinadas a desenvolver o espaço aéreo europeu num continuum flexível e reativo à evolução das necessidades dos usuários do espaço aéreo. Visam otimizar a capacidade de rede e melhorar o desempenho.', 'released', '["Diretora do Espaço Aéreo", "Gestora do Espaço Aéreo", "Diretor do Espaço Aéreo", "Gestor do Espaço Aéreo", "Gerente"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/d00b4607-c4fe-4f3e-8974-29401e23223c', 'Administrador da Segurança Social', 'Os administradores da Segurança Social dirigem e desenvolvem programas públicos de segurança social com o objetivo de contribuir para o bem-estar público, e promovem programas de segurança social. Supervisionam o pessoal que trabalha no domínio da segurança social pública e investigam as políticas existentes a fim de avaliar as questões e desenvolver propostas de melhoria.', 'released', '["Administrador da Segurança Social", "Funcionário da Segurança Social", "Assistente Social", "Administradora da Segurança Social", "Administradora de Serviços Comunitários", "Funcionária da Segurança Social", "Administrador de Serviços Comunitários"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/d0341f2c-f797-4306-b847-411dee1058a9', 'Modelo Vivo para Artes Visuais', 'Os modelos vivos para artes visuais posam para os artistas visuais como referência ou inspiração para o seu trabalho criativo. Posam como modelo para artistas que executam desenho de figuras, pintam, fazem esculturas ou criam arte fotográfica. Os modelos vivos para artes visuais são modelos profissionais que usam o corpo para se tornarem o objeto da criação do artista.', 'released', '["Modelo", "Modela Vivo para Artes Visuais"]'::jsonb, '5241'),
  ('http://data.europa.eu/esco/occupation/d051a141-92cd-4800-b0ee-6c8c31ea5838', 'Técnico de Gruas', 'Os técnicos das gruas montam componentes de gruas industriais e portuárias. Instalam transportadores e dispositivos de controlo. Os técnicos de gruas realizam a montagem final no local e procedem à manutenção e reparação de gruas.', 'released', '["Técnica de Gruas", "Técnico de Gruas"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/d07a4984-e775-46a7-b967-a3d0b3a54268', 'Polidor de Metal', 'Os polidores de metal utilizam equipamento para trabalhar metal e máquinas para polir e lixar peças metálicas quase acabadas para melhorar a sua suavidade e aspeto, bem como para remover a oxidação, que mancha o metal depois dos outros processos de fabrico. Podem operar equipamento utilizando soluções de diamante, almofadas de polir à base de silício, ou rodas de trabalho com uma tira de couro para polir, e cuidam destes materiais para garantir a sua eficácia.', 'released', '["Polidora de Metal", "Polidor de Metal"]'::jsonb, '7224'),
  ('http://data.europa.eu/esco/occupation/d07e6a57-a339-4cfd-bf22-a951713148a3', 'Responsável Pela Manutenção de Equipamentos de Telecomunicações', 'Os responsáveis pela manutenção de equipamentos de telecomunicações procedem à reparação, à instalação ou manutenção de equipamentos móveis ou fixos de transmissão de equipamentos de telecomunicações, de radiodifusão e de recepção e de sistemas de radiocomunicações bidirecionais (telecomunicações celulares, banda larga móvel, comunicações navio-terra, comunicações ar-terra, equipamento de rádio em veículos de serviço e de emergência). Centram-se também nas torres de comunicação, antenas, amplificadores e conectores. Podem testar e analisar a cobertura da rede.', 'released', '["Responsável Pela Manutenção de Equipamentos de Telecomunicações", "Técnico de Manutenção de Equipamentos de Telecomunicações", "Técnica de Manutenção de Equipamentos de Telecomunicações"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/d08b4700-758c-467d-ab77-d5a8029c4070', 'Adquirente Público Independente', 'Os adquirentes públicos independentes gerem o processo de contratação e suprem todas as necessidades de contratação relativas a uma pequena autoridade adjudicante. Estão envolvidos em todas as fases do processo de adjudicação e colaboram com profissionais de outros departamentos da organização para encontrar os tipos de conhecimentos especializados que podem não estar disponíveis.;', 'released', '["Procurador Público", "Compradora Pública", "Comprador Público", "Especialista em Compras", "Procurador Pública", "Adquirentea Público Independente"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/d0aa0792-4345-474b-9365-686cf4869d2e', 'Arquiteto de Software', 'Os arquitetos de software criam o desenho técnico e o modelo funcional de um sistema de software, com base em especificações funcionais. Concebem igualmente a arquitetura do sistema ou os diferentes módulos e componentes relacionados com os requisitos da empresa ou do cliente, a plataforma técnica, a linguagem informática ou o ambiente de desenvolvimento.', 'released', '["Arquiteta de Software", "Arquiteta de Aplicações", "Designer de Software", "Arquiteto de Software", "Arquiteto de Aplicações", "Designer de Aplicações"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/d0c923f1-e32b-4838-a109-eac58945dab1', 'Fabricante de Violinos', 'Os fabricantes de violinos criam e montam peças para criar violinos, de acordo com instruções ou diagramas especificados. Lixam a madeira, medem e colocam cordas, bem como testam a qualidade das cordas e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Violinos"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/d0d7d777-073f-4c33-8f27-1d4a0e8e626f', 'Operador de Sistemas de Controle na Produção de Pasta de Papel', 'Os operadores de sistemas de controlo na produção de pasta de papel operam e monitorizam máquinas e equipamentos de controlo de processos multifuncionais, para controlar o processamento de madeira, pasta de aparas de papel, papel reciclado e outros materiais celulósicos na produção de pasta de papel. Instalam, operam e efetuam a manutenção das máquinas, analisam os resultados da produção e ajustam o processo, quando necessário.', 'released', '["Operadora de Sistemas de Controle na Produção de Pasta de Papel"]'::jsonb, '3139'),
  ('http://data.europa.eu/esco/occupation/d0e85fe6-78e3-4218-b21a-99b75438b775', 'Diretor de Corretora de Valores Mobiliários', 'Os diretores de corretora de valores mobiliários organizam as atividades e as pessoas envolvidas na negociação de valores mobiliários. Visam estratégias destinadas a aumentar a eficiência da negociação de ativos, com destaque para a rendibilidade. Podem igualmente aconselhar os clientes sobre negócios adequados.', 'released', '["Diretor de Corretora de Valores Mobiliários", "Diretora de Corretora de Valores Mobiliários"]'::jsonb, '1346'),
  ('http://data.europa.eu/esco/occupation/d117ef65-b253-4f04-bc85-353ef853443a', 'Citologista', 'Os citologistas examinam ao microscópio amostras de células humanas obtidas de várias partes do corpo, como o aparelho reprodutor feminino, o pulmão ou o trato gastrointestinal, e ajudam a identificar anomalias celulares e doenças como o cancro ou agentes infecciosos, sob supervisão e seguindo as ordens de um médico. As células anómalas são encaminhadas para um patologista para diagnóstico médico. Podem também trabalhar sob a supervisão de um especialista biomédico. Não tratam doentes nem prestam assistência em tratamentos médicos.', 'released', '["Técnica de Anatomia Citológica", "Técnico de Anatomia Citológica"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/d185c066-cddf-4a8c-a931-5eefc21fc2a1', 'Instrutor de Tripulação de Cabina', 'Os instrutores de tripulação de cabina ensinam todos os aspetos relativos às operações nas cabinas das aeronaves. Ensinam, dependendo do tipo de avião, as operações efetuadas na aeronave, os controlos pré e pós-voo, os procedimentos de segurança, o equipamento de serviço e procedimentos e formalidades de serviço ao cliente.', 'released', '["Instrutor de Tripulantes de Cabine", "Instrutora de Tripulação de Cabina", "Instrutora de Tripulantes de Cabina", "Instrutor de Tripulantes de Cabina", "Instrutor de Tripulação de Cabina", "Instrutora de Tripulantes de Cabine", "Instrutora de Tripulação de Cabine", "Instrutor de Tripulação de Cabine"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/d18a8976-a283-42ad-9541-75c49396dbd7', 'Operador de Lotaria', 'Os operadores de lotaria asseguram as funções quotidianas das lotarias. Verificam e introduzem dados no sistema, elaboram relatórios e prestam assistência no envio de equipamento às empresas. Operam os instrumentos de comunicação utilizados.', 'released', '["Operador de Lotaria", "Operadora de Lotaria"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/d18deca3-3063-4970-9ddc-e3c70404a28c', 'Higienista Dentário', 'Os higienistas dentários executam funções de limpeza e polimento dentários, destartarização supra e subgengival, aplicação de materiais profiláticos nos dentes, recolha de dados e administração de conselhos abrangentes em matéria de higiene oral e cuidados da boca, em função das necessidades dos doentes, sob a supervisão e seguindo as instruções do dentista.', 'released', '["Higienista Dentária", "Higienista Dentário"]'::jsonb, '2261'),
  ('http://data.europa.eu/esco/occupation/d1974e0c-8f92-473b-a32d-f0616c08b1ff', 'Técnico em Mecânica de Precisão', 'Os técnicos em mecânica de precisão fabricam componentes metálicos de precisão para máquinas e realizam a sua montagem em unidades funcionais. Também criam componentes eletrônicos de medição e controlo. Os técnicos em mecânica de precisão utilizam máquinas de fresar, perfurar, esmerilar e afiar.', 'released', '["Técnica em Mecânica de Precisão", "Técnico em Mecânica de Precisão"]'::jsonb, '7222'),
  ('http://data.europa.eu/esco/occupation/d19932b3-169a-4cdf-a9cd-bdf8857b0184', 'Representante de Vendas de Máquinas para a Indústria Têxtil', 'Os representantes de vendas de máquinas para indústria têxtil prestam serviços em nome de uma empresa para vender as suas mercadorias, fornecendo simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Máquinas para a Indústria Têxtil"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/d1a554d0-7ad6-4d42-897e-ed31d022fb0b', 'Designer de Vestuário de Moda', 'Os designers de vestuário de moda criam conceitos e desenham, à mão ou com recurso a software, as suas ideias criativas. Analisam e interpretam as tendências da moda para propor novas ideias com elevado valor estético. Realizam estudos de previsão e de mercado para criar coleções. Criam linhas de moda com recurso a painéis de conceitos ou tendências, paletes de cor, materiais, desenhos e esboços, tendo em conta, entre outros, critérios ergonómicos, etc..;', 'released', '["Designer de Vestuário de Moda Contemporânea", "Designer de Moda"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/d1b1dfdf-7d60-430a-b569-7dd71b2ebeaa', 'Designer de Guarda-Roupa', 'Os designers de guarda-roupa desenvolvem um conceito de design de trajes para um espetáculo, um filme ou um programa de televisão. Supervisionam a sua execução. O seu trabalho baseia-se na investigação e na visão artística. Os seus desenhos são influenciados por, e influenciam, outros desenhos e devem estar em conformidade com esses desenhos e com a visão artística global. Por conseguinte, os designers trabalham em estreita colaboração com os diretores artísticos, os operadores e a equipe artística. Os designers de guarda-roupa concebem esboços, desenhos e padrões ou outra documentação para apoiar a equipe de trabalho e os artistas. ;', 'released', NULL, '2163'),
  ('http://data.europa.eu/esco/occupation/d1b8c046-3867-423a-84fd-41f7be3a6d29', 'Assistente de Psicólogo', 'Os assistentes de psicólogos prestam assistência aos psicólogos nas suas funções. Trabalham em unidades de cuidados de saúde ou clínicas privadas, onde prestam assistência aos psicólogos nos tratamentos administrados aos doentes. Os assistentes de psicólogos são profissionais de saúde que podem avaliar os doentes por meio de testes psicológicos e ajudar com a terapia, bem como desempenhar funções administrativas.', 'released', '["Assistentea de Psicólogo"]'::jsonb, '3259'),
  ('http://data.europa.eu/esco/occupation/d1fc31d2-38e1-4000-85b7-3f82d2fbed9e', 'Animador de Clube', 'Os animadores de clube dão as boas-vindas aos clientes ao clube. Asseguram que os clientes estão devidamente cuidados e satisfeitos.', 'released', '["Animador de Clube", "Animadora de Clube"]'::jsonb, '5169'),
  ('http://data.europa.eu/esco/occupation/d2078576-9c43-40f7-bf52-356f53d650fd', 'Operador de Triagem de Peles', 'Os operadores de triagem classificam couros, peles, Wet Blue e crosta em função das características naturais, da categoria, do peso e também da magnitude, da localização, do número e do tipo de defeitos. Comparam o lote com as especificações, fornecem uma atribuição do grau e estão encarregados da aparagem.', 'released', '["Operador de Triagem de Peles", "Operadora de Triagem de Peles"]'::jsonb, '7531'),
  ('http://data.europa.eu/esco/occupation/d20fd82a-9d99-4335-ad83-87484e297a46', 'Avicultor', 'Os avicultores supervisionam a produção e o cuidado diário das aves de capoeira. Zelam pela saúde e pelo bem-estar das aves de capoeira.', 'released', '["Produtor de Aves", "Criadora de Aves Domésticas", "Produtora de Aves", "Avicultora", "Criador de Aves", "Avicultor", "Criador de Aves Domésticas", "Criadora de Aves"]'::jsonb, '6122'),
  ('http://data.europa.eu/esco/occupation/d21890a3-cbe9-49df-9a19-a4120d866548', 'Notário', 'Os notários asseguram a autenticidade e a legitimidade dos documentos oficiais, tais como declarações, certificados, contratos, escrituras e aquisições. Examinam os documentos, testemunham a assinatura e procedem à sua autenticação. Administram juramentos e declarações sob compromisso de honra e procedem a outros atos de autenticação notarial.', 'released', '["Notário", "Notária"]'::jsonb, '2619'),
  ('http://data.europa.eu/esco/occupation/d23f4d59-2bea-4bd8-bcdb-5e23b1c50552', 'Coordenador de Programa Educacional', 'Os coordenadores de programa educacional supervisionam o desenvolvimento e a execução dos programas educativos. Desenvolvem políticas de promoção da educação e gerem os orçamentos. Comunicam com os estabelecimentos de ensino para analisar os problemas e investigar as soluções.', 'released', '["Coordenador de Programa Educacional", "Coordenadora de Programa Educacional", "Coordenador de Programa Educativo Internacional", "Coordenadora de Programa Educativo Internacional"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/d23fbcdc-d5e9-4724-a83f-99a0cfa8adb0', 'Repetidor', 'Os repetidores acompanham os artistas intérpretes ou executantes, geralmente cantores, seguindo as instruções dos maestros na direção dos ensaios e na orientação dos artistas no processo de ensaio.', 'released', '["Diretor Musical", "Repetidor", "Diretora Musical", "Repetidora"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/d261a6a4-7ea7-4295-a84e-f4b1a56990d7', 'Mediador Imobiliário', 'Os mediadores imobiliários marcam reuniões com os clientes para mostrarem e arrendarem bens imóveis a potenciais residentes. Participam no marketing da propriedade destinada a arrendamento através de publicidade e da divulgação junto da comunidade. Estão igualmente envolvidos em tarefas diárias de comunicação e administração.', 'released', '["Mediador Imobiliária", "Mediadora Imobiliária", "Mediadora Imobiliário"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/d26a941d-443a-4301-a648-3cb3a4427775', 'Operador de Distribuição de Gás Natural', 'Opera e mantém equipamentos de distribuição de gás natural, incluindo gasodutos, estações de redução de pressão, válvulas e sistemas de medição. Monitora pressão, vazão e conformidade do plano de distribuição, executa inspeções e manutenção preventiva e atende ocorrências para garantir o fornecimento seguro e contínuo a clientes residenciais, comerciais e industriais.', 'released', '["Operador de Distribuição de Gás Natural", "Operador de Unidade de Processamento de Gás", "Operador de Distribuição de Gás", "Operador de Gasoduto", "Operador de Rede de Gás", "Operador de Estação de Redução de Pressão", "Operador de Medição de Gás", "Operadora de Distribuição de Gás Natural"]'::jsonb, '3134'),
  ('http://data.europa.eu/esco/occupation/d2af4f6b-c990-4d8e-bb17-befca23a307a', 'Técnico de Engenharia Optomecânica', 'Os técnicos de engenharia optomecânica colaboram com os engenheiros no desenvolvimento de dispositivos optomecânicos, como mesas óticas, espelhos deformáveis e suportes óticos. Os técnicos de engenharia optomecânica constroem, instalam, testam e efetuam a manutenção de protótipos de equipamentos optomecânicos. Determinam as necessidades de materiais e de montagem.', 'released', '["Técnica de Engenharia Optomecânica", "Técnico de Engenharia Optomecânica"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/d2d451cc-e839-4192-be54-d7724814aa03', 'Consultor Bancário de Empresas', 'Os consultores bancários de empresas aconselham instituições e organizações sobre uma vasta gama de bens e serviços financeiros, tais como serviços de valores mobiliários, serviços de crédito, gestão de tesouraria, produtos de seguros, locação financeira, informações sobre fusões e aquisições e atividades do mercado de capitais.', 'released', '["Consultora Bancária de Empresas", "Gestora de Conta de Empresas", "Consultor Bancário de Empresas", "Gestor de Conta de Empresas", "Consultora Bancário de Empresas"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/d2db926b-8b14-4686-9c98-fb0dc3a38cbb', 'Diretor Criativo', 'Os diretores criativos gerem a equipe responsável pela criação de anúncios publicitários e comerciais. Supervisionam todo o processo de criação. Os diretores criativos apresentam as criações da sua equipe ao cliente, procurando despertar o seu interesse pelas mesmas.', 'released', '["Diretora Criativa", "Diretor Criativo", "Diretora Criativo"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/d2df16f3-87d7-4c6e-a640-95cee39a8f4e', 'Produtor de Cidra', 'Os produtores de sidra ocupam-se do processo de fabrico da sidra. Asseguram a qualidade da sidra e seguem um dos vários processos de fabrico de sidra. Alteram as fórmulas de fabrico e as técnicas de transformação existentes, a fim de desenvolver novos produtos de sidra e bebidas à base de sidra.', 'released', '["Fabricante de Cidra", "Produtor de Cidra", "Produtora de Cidra"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/d2e63d7e-2605-4af1-bb7d-b1ed9ad08825', 'Assistente de Estatística', 'Os assistentes de estatística recolhem dados e utilizam fórmulas estatísticas para executar estudos estatísticos e elaborar relatórios. Criam mapas, gráficos e inquéritos.', 'released', '["Assistentea de Estatística"]'::jsonb, '3314'),
  ('http://data.europa.eu/esco/occupation/d2ff134e-b41a-4fa3-aceb-1b9f5f5cf015', 'Diretor de Serviços Jurídicos', 'Os diretores de serviços jurídicos supervisionam a gestão geral de um serviço jurídico. Não só se esforçam pela maior eficiência e eficácia quando prestam serviços jurídicos e aconselhamento, mas também coordenam uma equipe de profissionais com formação jurídica. Gerem diferentes perfis de clientes e ajustam os serviços jurídicos às suas necessidades.', 'released', '["Técnico de Serviços Jurídicos", "Diretora de Serviços Jurídicos", "Diretor de Serviços Jurídicos", "Técnica de Serviços Jurídicos"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/d3382c5a-589f-453d-a6d8-d28695057079', 'Operador de Fermentadores', 'Os operadores de fermentadores procedem ao controlo e manutenção do equipamento e dos tanques para a produção de ingredientes ativos e funcionais para produtos farmacêuticos, tais como antibióticos ou vitaminas. Também trabalham na produção de cosméticos ou de produtos de higiene pessoal.', 'released', '["Operador de Fermentadores", "Operadora de Fermentadores"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/d3570716-cc0d-4a61-b9a0-9b3081050e9d', 'Jornalista Especializado em Eventos Culturais e Sociais', 'Os jornalistas especializados em eventos culturais e sociais investigam e redigem artigos sobre eventos culturais e sociais para jornais, revistas, televisão e outros meios de comunicação social. Realizam entrevistas com artistas e celebridades e participam em eventos.', 'released', '["Jornalista Especializada em Eventos Culturais e Sociais", "Jornalista Especializado em Eventos Culturais e Sociais"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/d35f9e79-5778-43b4-8667-0e3ba1fcb19a', 'Repositor', 'Os repositores procedem à reposição e rotação de mercadorias em prateleiras, identificando e removendo produtos fora de prazo. Limpam a loja após o horário de funcionamento, assegurando que as prateleiras estejam totalmente repostas no dia seguinte. Os repositores podem utilizar carrinhos, pequenos empilhadores para deslocar as existências e escadas para chegar às prateleiras altas. Também dão indicações aos clientes a fim de localizar produtos específicos. ; ;', 'released', '["Repositora de Prateleiras", "Repositor", "Repositora", "Repositor de Prateleiras", "Repositora de Supermercado", "Repositor de Supermercado"]'::jsonb, '9334'),
  ('http://data.europa.eu/esco/occupation/d36b66f8-c08a-4416-953b-62c271ca7509', 'Gestor de Cultivo Hortícola', 'Os gestores de cultivo hortícola planeiam a produção, gerem a empresa e participam na produção.', 'released', '["Gestora de Cultivo Hortícola", "Gestor de Cultivo Hortícola", "Assessor de Cultivo Hortícola", "Gestor de Cultivo de Produtos Hortícolas", "Gestora de Cultivo de Produtos Hortícolas", "Assessora de Cultivo Hortícola", "Gerente"]'::jsonb, '6113'),
  ('http://data.europa.eu/esco/occupation/d372b694-041a-4978-bd81-efbb763ee70d', 'Jornalista Especializado em Criminalidade', 'Os jornalistas especializados em criminalidade investigam e redigem artigos sobre eventos criminais para jornais, revistas, televisão e outros meios de comunicação social. Realizam entrevistas e assistem a audiências em tribunal.', 'released', '["Jornalista Especializado em Criminalidade", "Jornalista Especializada em Criminalidade"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/d372e2e4-714a-4127-bb82-6b53eb817410', 'Comerciante Grossista de Madeira e Materiais de Construção', 'Os comerciantes grossistas de madeira e materiais de construção investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Madeira e Materiais de Construção"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/d37cc820-15f5-4a81-88db-af48b0ee6a32', 'Chefe de Departamento de Escola Secundária', 'Os chefes de departamento de escola secundária gerem e supervisionam os serviços que lhes são atribuídos, a fim de assegurar que os alunos recebem instruções e apoio num ambiente de aprendizagem seguro. Trabalham em estreita colaboração com o diretor da escola secundária para liderar e ajudar o pessoal da escola e otimizar a comunicação entre o órgão diretivo e os professores, os pais e outros distritos e escolas. Facilitam as reuniões, desenvolvem e analisam programas curriculares, supervisionam o pessoal quando o diretor lhes delega esta função e assumem uma responsabilidade partilhada com o diretor na gestão dos recursos financeiros.', 'released', '["Chefe de Departamento de Escola", "Chefea de Departamento de Escola Secundária"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/d38c2107-98f2-47b7-8bb4-f69750d51082', 'Assistente de Cuidados de Saúde', 'Os assistentes de cuidados de saúde trabalham em equipes de enfermeiros nos domínios profissionais de enfermagem, cuidados sociais, cuidados clínicos e cuidados a pessoas de todos os grupos etários. Os assistentes de cuidados de saúde prestam assistência na promoção e no restabelecimento da saúde dos doentes, prestando-lhes apoio físico e psicológico, bem como aos respetivos amigos e familiares.;', 'released', '["Auxiliar de Ação Médica", "Assistentea de Cuidados de Saúde"]'::jsonb, '5321'),
  ('http://data.europa.eu/esco/occupation/d3ac4c05-79e2-42da-b8c6-e55765aee381', 'Especialista em Import-Export de Desperdícios e Sucata', 'Os especialistas em import-export de desperdícios e sucata possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Desperdícios e Sucata"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/d3c1c718-a093-4e2e-80a0-2bd331266a8b', 'Operador de Motores de Equipamento de Perfuração', 'Os operadores de motores de equipamento de perfuração assumem a responsabilidade pelos motores que alimentam o equipamento de perfuração. Asseguram que todo outro equipamento da plataforma funcione corretamente.', 'released', '["Operador de Motores de Equipamento de Perfuração", "Operadora de Motores de Equipamento de Perfuração"]'::jsonb, '8113'),
  ('http://data.europa.eu/esco/occupation/d3de3205-dd5c-4112-86bc-161e41cd77a5', 'Inspetor de Produção de Charutos', 'Os inspetores de produção de charutos procedem ao teste, à triagem, à amostragem e à pesagem dos charutos a fim de encontrar defeitos e desvios em relação às especificações do produto.', 'released', '["Inspetor de Produção de Charutos", "Inspetora da Indústria do Tabaco", "Inspetora de Produção de Charutos", "Inspetor da Indústria do Tabaco"]'::jsonb, '7543'),
  ('http://data.europa.eu/esco/occupation/d3e32e5e-7f24-48e3-b939-e4f800eb62fb', 'Técnico de Recursos Humanos', 'Os técnicos de recursos humanos desenvolvem e implementam estratégias que ajudam os seus empregadores a selecionarem e reterem pessoal devidamente qualificado no setor empresarial pertinente. Recrutam pessoal, preparam anúncios de emprego, entrevistam e pré-selecionam os candidatos, negoceiam com agências de emprego e criam condições de trabalho. Os técnicos de recursos humanos também administram as folhas de vencimento, reveem os salários e prestam aconselhamento em matéria de benefícios salariais e direito do trabalho. Organizam oportunidades de formação para melhorar o desempenho dos trabalhadores.', 'released', '["Técnico de Recursos Humanos", "Técnica de Recursos Humanos", "RH"]'::jsonb, '2423'),
  ('http://data.europa.eu/esco/occupation/d3edb8f8-3a06-47a0-8fb9-9b212c006aa2', 'Analista de Dados', 'Os analistas de dados executam funções de importação, inspeção, depuração, transformação, validação, modelagem ou interpretação de conjuntos de dados relativos aos objetivos empresariais da empresa. Asseguram que as fontes e os repositórios de dados fornecem dados consistentes e fiáveis. Os analistas de dados utilizam diferentes algoritmos e ferramentas de TI, conforme exigido pela situação e pelos dados do momento. Podem elaborar relatórios sob a forma de visualizações como gráficos, mapas e quadros.', 'released', '["Analista de Dados", "Analista de Informação"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/d3fd0898-51f7-42a3-8f44-09408fc796f6', 'Empregado de Instituto de Beleza', 'Os empregados de instituto de beleza programam as marcações dos clientes, acolhem clientes nas instalações, fornecem informações pormenorizadas sobre os serviços e tratamentos e recebem as queixas dos clientes. Limpam regularmente o instituto de beleza e garantem que todos os produtos estão em stock e estão bem depositados. Os empregados de instituto de beleza recebem pagamentos de clientes e podem vender vários produtos de beleza.', 'released', '["Empregada de Instituto de Beleza", "Empregado de Instituto de Beleza"]'::jsonb, '5142'),
  ('http://data.europa.eu/esco/occupation/d41ff08f-1ba9-4e39-b9b5-ad6bfe8f9611', 'Moldador de Chocolate', 'Os moldadores de chocolate asseguram o correto funcionamento de máquinas e equipamentos que vertem o chocolate temperado nos moldes para formar barras, blocos e outras formas de chocolate. Controlam as máquinas para assegurar que os moldes não encravem.', 'released', '["Moldadora de Chocolate", "Operador de Moldagem de Chocolate", "Moldador de Chocolate", "Operadora de Moldagem de Chocolate"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/d43e9693-7087-412c-b54c-e9068012630a', 'Operador de Estação de Tratamento de Águas Residuais', 'Os operadores de estações de tratamento de águas residuais operam os equipamentos utilizados numa estação de tratamento de água ou de águas residuais. Procedem ao tratamento e à purificação de água potável antes de ser distribuída ao consumidor, bem como ao tratamento de águas residuais com vista à remoção das substâncias nocivas antes de serem devolvidas aos rios e aos mares. Recolhem amostras e realizam testes para analisar a qualidade da água.', 'released', '["Operador de Estação de Tratamento de Águas Residuais", "Operadora de Estação de Tratamento de Águas Residuais"]'::jsonb, '3132'),
  ('http://data.europa.eu/esco/occupation/d44c5eb0-fc6c-4f4a-9850-f2f29aaac505', 'Montador de Equipamentos Eletromecânicos', 'Os montadores de equipamentos eletromecânicos leem e interpretam esquemas, desenhos e instruções para a montagem ou modificação de equipamentos ou dispositivos eletromecânicos. Inspecionam e testam as unidades, a fim de garantir uma boa ordem de trabalho e a conformidade com as especificações e as normas.', 'released', '["Fabricante de Equipamentos Eletromecânicos", "Montador de Equipamentos Eletromecânicos", "Montadora de Equipamentos Eletromecânicos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/d46a0f9d-4474-46f8-b59d-7970da915b94', 'Diretor de Distribuição — Sistemas Combinados de Água Quente Doméstica e Calefação', 'Os diretores de distribuição — sistemas combinados de água quente doméstica e calefação planificam a distribuição de estruturas e equipamentos e produtos de canalização e calefação a vários pontos de venda.', 'released', '["Diretora de Logística — Sistemas Combinados de Água Quente Doméstica e Calefação", "Diretor de Distribuição — Sistemas Combinados de Água Quente Doméstica e Calefação", "Diretor de Logística — Sistemas Combinados de Água Quente Doméstica e Calefação", "Diretora de Distribuição — Sistemas Combinados de Água Quente Doméstica e Calefação"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/d4709722-6f17-4bec-a5f4-1b660e6b28b1', 'Responsável por Sistemas de Amarração em Aquicultura', 'Os responsáveis por sistemas de amarração em aquicultura executam e supervisionam a amarração das gaiolas em estações estáveis, gaiolas flutuantes, ou mesmo gaiolas autopropulsionadas e semissubmersas. Operam e atracam em segurança uma variedade de diferentes tipos de gaiolas em grande escala, gerem condições como correntes, clima e perfil dos fundos marinhos, em áreas de águas abertas ou semiabertas.', 'released', NULL, '6221'),
  ('http://data.europa.eu/esco/occupation/d47d495f-159b-40c9-b3d2-6b651c903e28', 'Operador de Abate Kosher', 'Os operadores de abate kosher abatem animais e processam carcaças de carne kosher para transformação e distribuição. Procedem ao abate de animais como declarado na lei judaica e de acordo com os rituais.', 'released', '["Operador de Abate Kosher", "Operadora de Abate Kosher"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/d48d4949-73a2-40d7-8350-329cda6b5a9a', 'Segundo Oficial', 'Os segundos oficiais são responsáveis pela monitorização e pelo controlo dos vários sistemas das aeronaves, incluindo as de asa fixa e de asa rotativa. Trabalham em estreita coordenação com os dois pilotos durante todas as fases do voo. Procedem a inspeções, ajustes e pequenas reparações pré-voo, durante o voo e pós-voo. Verificam parâmetros como a distribuição de passageiros e de carga, a quantidade de combustível, o desempenho da aeronave e a velocidade adequada do motor de acordo com as instruções dos pilotos.', 'released', '["Segunda Oficial"]'::jsonb, '3153'),
  ('http://data.europa.eu/esco/occupation/d4cbc865-ad88-4b07-9525-2af3dd31cf0d', 'Cortador Kosher', 'Os cortadores kosher encomendam, inspecionam e compram carne para a preparar e vender como produtos consumíveis de carne, em conformidade com as práticas judaicas. Realizam atividades como o corte, o aparo, a desossa, a atadura e a trituração de carne de animais kosher, tais como vacas, ovinos e caprinos. Preparam a carne kosher para consumo.', 'released', '["Cortador Kosher", "Cortadora Kosher"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/d4ccb6d4-ea97-47e5-a319-b72cffbf0631', 'Operador de Salvamento em Minas', 'Os operadores de salvamento em minas coordenam as operações de salvamento em minas e precisam de receber formação para trabalhar no subterrâneo. São a primeira linha de resposta em situações de emergência.', 'released', '["Operador de Salvamento em Minas", "Operadora de Salvamento em Minas"]'::jsonb, '5411'),
  ('http://data.europa.eu/esco/occupation/d4d6842b-27f0-4222-85db-c542acf6d434', 'Especialista em Política de Saúde Pública', 'Os especialistas em política de saúde pública desenvolvem e implementam estratégias para melhorar a política de cuidados de saúde da comunidade. Aconselham os governos sobre as mudanças políticas e identificam problemas nas atuais políticas de cuidados de saúde.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/d4dd502d-9407-456c-a54a-b733fc9cf68b', 'Gerente de Loja de Produtos de Beleza', 'Os gerentes de loja de produtos de beleza assumem a responsabilidade pelo pessoal e pelas atividades numa loja. Gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário. Vendem cosméticos, perfumes, medicamentos e produtos diversos.', 'released', '["Gerente de Perfumaria", "Gerente de Loja de Produtos Cosméticos", "Gerentea de Loja de Produtos de Beleza"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/d4edb527-2e5d-440c-9f8c-cd5caa9cc4d6', 'Astronauta', 'Os astronautas são membros da tripulação que comandam veículos espaciais em operações para além da órbita terrestre baixa ou a uma altitude regular superior à dos voos comerciais. Realizam a órbita da Terra, a fim de executarem operações como investigações e experiências científicas, o lançamento ou a libertação de satélites e a construção de estações espaciais.', 'released', NULL, '3153'),
  ('http://data.europa.eu/esco/occupation/d4fdb8cb-8928-4047-8166-5feedc3c1a98', 'Operador de Prensas de Moldagem a Seco', 'Os operadores de prensas de moldagem a seco utilizam argila ou sílica temperada e seca transformando-a em tijolos e outras formas. Selecionam e fixam os moldes de prensagem, utilizando a régua e chaves. Os operadores de prensas de moldagem a seco removem os tijolos da máquina de prensagem, empilhando-os num padrão especificado nos vagões dos fornos.', 'released', '["Operador de Prensas de Moldagem a Seco", "Operadora de Prensas de Moldagem a Seco"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/d515e82a-ca9f-4be4-9823-33694dff7304', 'Técnico de Desenvolvimento de Marroquinaria', 'Os técnicos de desenvolvimento de marroquinaria executam as suas funções e estabelecem uma interface entre a fase da concepção e a da produção propriamente dita. Analisam e estudam as especificações do «designer» e transformam-nas em requisitos técnicos, atualizando os conceitos para se adequarem às linhas de fabrico, selecionando ou até mesmo concebendo os componentes e selecionando os materiais. Os técnicos de desenvolvimento de marroquinaria também executam a engenharia de padrões, ou seja elaboram os padrões manualmente, e produzem desenhos técnicos para uma série de ferramentas, especialmente de corte. Avaliam os protótipos, executando os ensaios necessários nas amostras e confirmando os requisitos de qualidade e as condicionantes em matéria de preços do cliente.', 'released', '["Técnico de Desenvolvimento de Maquinaria", "Técnica de Desenvolvimento de Maquinaria", "Técnica de Desenvolvimento de Marroquinaria"]'::jsonb, '2163'),
  ('http://data.europa.eu/esco/occupation/d52db93d-9ae5-47d9-b9dc-eab8aa9f2ba9', 'Assistente de Palco', 'Os assistentes de palco apoiam os técnicos de palco com a instalação e a preparação de equipamento para o espetáculo ao vivo. O seu trabalho inclui a preparação do cenário, das luzes, do som, dos adereços, dos mecanismos de manobras e dos efeitos especiais de uma produção. ;', 'released', '["Assistentea de Palco"]'::jsonb, '7215'),
  ('http://data.europa.eu/esco/occupation/d5954a2b-a525-45b7-b6d9-b62efafc6c78', 'Pessoal de Companhia', 'O pessoal de companhia executa tarefas domésticas e preparam as refeições para as pessoas a quem prestam assistência nas suas próprias instalações, tais como idosos ou pessoas com necessidades especiais ou que sofrem de uma doença. Também fornecem atividades de entretenimento, tais como jogar às cartas ou ler histórias. Podem fazer compras, bem como efetuar transportes pontuais para consultas médicas, etc.', 'released', '["Dama de Companhia"]'::jsonb, '5162'),
  ('http://data.europa.eu/esco/occupation/d5a43cd3-230e-46d0-ba05-d67d61e5cfbb', 'Designer Multimédia', 'Os designers multimédia criam e editam gráficos, animações, som, texto e vídeo para ajudar na criação de produtos multimédia integrados. Podem realizar atividades relacionadas com a Web, as redes sociais, a realidade aumentada e a realidade virtual, excluindo a produção de música através de instrumentos físicos e ferramentas de software complexas de síntese de som. Os designers multimédia podem programar e criar sites, aplicações móveis e outros produtos multimédia.', 'released', '["Designer Multimédia", "Designer para Meios Digitais", "Designer de Novos Média"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/d5ad1da5-cf69-4508-9148-a5338f4ffe0e', 'Operador de Máquinas de Fabricação de Perfumes', 'Os operadores de máquinas de fabrico de perfumes asseguram o correto funcionamento da maquinaria para o fabrico de perfumes, através da instalação das máquinas e ferramentas, da limpeza e da manutenção do equipamento e do cumprimento do calendário de produção.', 'released', '["Operador de Máquinas de Fabricação de Perfumes", "Operadora de Máquinas de Fabricação de Perfumes"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/d5c4ab26-c293-4f4d-ad89-fe776f49a67f', 'Artista Digital', 'Os artistas digitais criam arte que aplica a tecnologia digital como parte essencial do processo criativo. A arte digital é geralmente criada utilizando computadores ou equipamentos digitais mais especializados. Pode ser fruída através dos mesmos instrumentos, partilhada através da Internet, ou apresentada através de meios de comunicação social mais tradicionais.', 'released', '["Compositora Digital", "Compositor Digital", "Designer Digital", "Especialista em Design Digital", "Artista Multimédia"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/d5ce0c23-6f8a-459f-9bf9-a7cb9768740a', 'Estilista de Imagem', 'Os estilistas de imagem ajudam os clientes a fazer escolhas de moda. Aconselham sobre as últimas tendências da moda em vestuário, joias e acessórios e ajudam os clientes a escolher a roupa adequada, em função do tipo de acontecimento social, dos seus gostos e tipo de corpo. Os estilistas de imagem ensinam os clientes a tomar decisões sobre o seu aspeto geral e a sua imagem.', 'released', NULL, '5142'),
  ('http://data.europa.eu/esco/occupation/d5db9d5c-2ebf-4a54-a79a-1b7e7ff70471', 'Garçom', 'Os empregados de mesa fornecem aos clientes alimentos e bebidas, tal como solicitado. Os empregados de mesa trabalham habitualmente em restaurantes, bares e hotéis. Tal implica a preparação de mesas, servir alimentos ou bebidas e receber pagamentos.', 'released', '["Empregado de Restaurante", "Empregada de Mesa", "Técnico de Restaurante", "Técnico de Mesa", "Técnica de Mesa", "Empregado de Serviços de Alimentação e Bebidas", "Empregada de Restaurante", "Técnica de Restaurante", "Empregado de Mesa", "Empregada de Serviços de Alimentação e Bebidas"]'::jsonb, '5131'),
  ('http://data.europa.eu/esco/occupation/d5eb6150-bbff-4a9c-9d0c-21eab4dbe2b6', 'Gerente de Restaurante', 'Os gerentes de restaurante são responsáveis pela gestão das operações relacionadas com alimentos e bebidas na cozinha e noutros estabelecimentos ou unidades de restauração num estabelecimento de hotelaria e restauração.', 'released', '["Gestor de Alimentos e Bebidas", "Gestora de Cozinha", "Gestora de Alimentos e Bebidas", "Gestor de Cozinha", "Gerentea de Restaurante"]'::jsonb, '1412'),
  ('http://data.europa.eu/esco/occupation/d63789ac-74b5-40e3-b890-685513c38e12', 'Governador', 'Os governadores são os principais legisladores de uma unidade nacional como um Estado ou uma província. Supervisionam o pessoal, exercem funções administrativas e protocolares e funcionam como o principal representante da sua região. Regulam os governos locais na sua região.', 'released', '["Governadora Civil", "Prefeito", "Governador", "Prefeita", "Representante da República para os Governos das Regiões Autónomas", "Governador Civil", "Governadora"]'::jsonb, '1111'),
  ('http://data.europa.eu/esco/occupation/d63b95e6-cf44-479e-bea2-e93498d171d0', 'Operador de Máquina de Corte de Sulcos em Madeira', 'Os operadores de máquina de corte de sulcos em madeira trabalham com máquinas industriais para cortar a madeira na forma desejada. As máquinas de corte de sulcos têm uma cabeça que se desloca sobre a madeira, para cima e para baixo, para regular a profundidade da incisão. As atuais máquinas de corte de sulcos em madeira industriais são geralmente controladas por computador para obter resultados extremamente delicados e consistentes.', 'released', '["Operador de Máquina de Corte de Sulcos em Madeira", "Operadora de Máquina de Corte de Sulcos em Madeira"]'::jsonb, '8172'),
  ('http://data.europa.eu/esco/occupation/d68ff35f-e34d-4e32-88ab-d6c06a6c25b9', 'Designer de Jogos Digitais', 'Os designers de jogos digitais desenvolvem a configuração, a lógica, o conceito e a jogabilidade de um jogo digital. Centram-se na concepção dos terrenos de jogo, na redação de especificações e na inserção de propriedades numéricas que equilibram e aperfeiçoam o jogo.', 'released', '["Criador de Jogos Digitais", "Designer de Jogos Digitais", "Criadora de Jogos Digitais", "Designer de Videogames", "Designer de Jogos de Computador"]'::jsonb, '2166'),
  ('http://data.europa.eu/esco/occupation/d694b54f-208a-4154-9fe1-d3d335992467', 'Especialista em Import-Export de Equipamento Eletrônico e de Telecomunicações', 'Os especialistas em import-export de equipamento eletrônico e de telecomunicações possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Equipamento Eletrônico e de Telecomunicações"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/d6a395eb-6664-47f1-9be5-91aa2e8ba87d', 'Diretor de Combate Cénico', 'Os diretores de combate cénico treinam os artistas para executarem com segurança sequências de combate. Dirigem combates cénicos para espetáculos, tais como de dança, cinema e televisão, circo, variedades e outros. Os diretores de combate cénico podem ter antecedentes em desportos, tais como esgrima, tiro ou boxe, artes marciais como judo, kung fu ou karaté, ou treino militar.', 'released', '["Diretora de Combate Cénico", "Diretor de Combate Cénico"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/d6b339ed-8dc9-4281-8c91-c8287eceee40', 'Representante de Serviço de Aluguel de Videocassetes e Discos', 'Os representantes de serviço de aluguer de videocassetes e discos são responsáveis pelo aluguer do equipamento e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Videocassetes e Discos"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/d6bffef4-f09a-4711-9ecb-92ec04353b21', 'Assistente Social Especialista em Casos de Toxicodependência', 'Os assistentes sociais especialistas em casos de toxicodependência prestam assistência e aconselhamento a pessoas com problemas de toxicodependência. Acompanham os seus progressos, defendem-nas, realizam intervenções em situações de crise e recorrem à terapia de grupo. Além disso, ajudam os doentes a lidar com as consequências do abuso de tabaco, álcool ou drogas recreativas, que podem ser problemáticas, como o desemprego, os distúrbios físicos ou mentais e a pobreza.', 'released', '["Assistente Social Especialista em Casos de Abuso de Drogas", "Assistente Social Especialista em Casos de Substâncias Ilícitas", "Assistentea Social Especialista em Casos de Toxicodependência"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/d6d1af75-7811-4914-b16f-50441bcb0e74', 'Engenheiro Especialista em Segurança e Saúde na Indústria Extrativa', 'Os engenheiros especialistas em segurança e saúde na indústria extrativa desenvolvem e implementam sistemas e procedimentos para prevenir o acidente e a doença dos trabalhadores, melhorar as condições de trabalho das minas, reduzir os riscos para a saúde e a segurança e evitar danos nos equipamentos e na propriedade.', 'released', '["Engenheiro Especialista em Segurança e Saúde na Indústria Extrativa", "Engenheira Especialista em Segurança e Saúde na Indústria Extrativa"]'::jsonb, '2146'),
  ('http://data.europa.eu/esco/occupation/d6ef013f-57e9-4100-bbe5-3e4930664dee', 'Especialista em Política de Assistência Social', 'Os especialistas em política de assistência social investigam, analisam e desenvolvem serviços e políticas de assistência social e implementam estas políticas e serviços a fim de melhorarem as circunstâncias de cidadãos desfavorecidos e vulneráveis, como as crianças e os idosos. Trabalham na administração dos serviços sociais e mantêm contato com organizações e outras partes interessadas, disponibilizando-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/d71eb4f9-2de3-4955-ba79-7b82ea3fe32c', 'Operador de Projetores de Seguimento', 'Os operadores de projetores de seguimento controlam os projetores de seguimento com base no conceito artístico ou criativo, em interação com os artistas. Os projetores de seguimento são instrumentos de iluminação especializados, concebidos para acompanhar os artistas ou os movimentos no palco. O movimento, a dimensão, a largura do feixe e a cor são controlados manualmente. Por conseguinte, os operadores trabalham em estreita colaboração com os operadores de luz e os artistas. O seu trabalho baseia-se em instruções e outra documentação. O seu trabalho pode incluir trabalho em altura, em pontes ou por cima de um público.', 'released', '["Operador de Follow Spots", "Operadora de Follow Spots", "Operadora de Projetores de Seguimento"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/d7380260-1386-4e36-98b5-8115ca4a3536', 'Engenheiro de Produção', 'Os engenheiros de produção analisam e avaliam o desempenho da produção, realizam análises de dados e identificam sistemas de produção com desempenho insuficiente. Procuram soluções a longo ou a curto prazo, planificam melhorias da produção e otimizações dos processos.', 'released', '["Engenheiro de Produção", "Engenheira de Produção"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/d7607255-746f-4ad4-bb4e-812e73d24983', 'Agente Funerário', 'Os agentes funerários transportam e carregam o caixão antes e durante o serviço funerário, colocando-o na capela e no cemitério. Tratam das ofertas florais em torno do caixão, dirigem o cortejo fúnebre e assistem no armazenamento do equipamento após o funeral.', 'released', '["Técnico de Serviços Funerários", "Técnica de Serviços Funerários", "Agentea Funerário"]'::jsonb, '5163'),
  ('http://data.europa.eu/esco/occupation/d792974a-077b-44a7-9421-b3ab7fdc7c40', 'Operador de Máquina para Reduzir o Diâmetro de Tubos ou Barras', 'Os operadores de máquina para reduzir o diâmetro de tubos ou barras utilizam e cuidam destas máquinas concebidas para alterar peças de metal ferroso e não ferroso na sua forma desejada, martelando-as até obter um menor diâmetro, através de uma força de compressão de dois ou mais moldes, e, em seguida, com recurso a uma máquina rotativa, um processo através do qual não se perde qualquer material em excesso.', 'released', '["Operadora de Máquina para Reduzir o Diâmetro de Tubos ou Barras", "Operador de Máquina para Reduzir o Diâmetro de Tubos ou Barras"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/d7a12ff0-7e25-4dab-98c5-1f5a781da8ad', 'Diretor de Importação e Exportação da Indústria de Curtumes', 'Os diretores de importação e exportação da indústria de curtumes implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação da Indústria de Curtumes", "Diretora de Vendas da Indústria de Curtumes", "Diretor de Vendas da Indústria de Curtumes", "Diretora de Importação e Exportação da Indústria de Curtumes"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/d7a9f9e0-e2f5-4804-a0e0-b21ebb1403ee', 'Coordenador de Inventário', 'Os coordenadores de inventário mantêm o registo de produtos armazenados em armazéns para transporte para lojas, grossistas e clientes individuais. Procedem à inspeção do inventário e à manutenção de documentos.', 'released', '["Coordenador de Inventário", "Coordenadora de Inventário"]'::jsonb, '4321'),
  ('http://data.europa.eu/esco/occupation/d7d986e1-7333-431b-9719-0c5c6939e360', 'Engenheiro de Obras de Engenharia Civil', 'Os engenheiros de obras de engenharia civil concebem, planificam e desenvolvem especificações técnicas e de engenharia para projetos de infraestruturas e construção. Aplicam conhecimentos de engenharia num vasto leque de projetos, desde a construção de infraestruturas de transporte, projetos de habitação e edifícios de luxo, até à construção de sítios naturais. Elaboram planos que procuram otimizar os materiais e integrar as especificações e a afetação de recursos nos condicionalismos de tempo.', 'released', '["Engenheira Civil", "Engenheiro Civil Especialista em Estruturas", "Gestor de Projetos de Infraestruturas", "Engenheiro Civil", "Engenheira de Obras de Engenharia Civil", "Engenheiro de Obras de Engenharia Civil", "Gestora de Projetos de Infraestruturas", "Engenheira Civil Especialista em Estruturas"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/d7e663b2-f042-47d8-9fda-b5b8ba30ca04', 'Engenheiro Aeroespacial', 'Os engenheiros aeroespaciais desenvolvem, testam e supervisionam o fabrico de veículos de voo, tais como aeronaves, mísseis e naves espaciais. O domínio da engenharia em que trabalham pode dividir-se em dois ramos: engenharia aeronáutica e engenharia astronáutica.', 'released', '["Engenheiro Aeronáutico", "Engenheira Aeronáutica", "Engenheira Aeroespacial", "Engenheiro Aeroespacial"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/d7f3d76b-23e8-447e-93d5-da13ff9bc102', 'Montador de Mobiliário', 'Os montadores de mobiliário montam em conjunto todas as peças do mobiliário e as peças auxiliares, tais como as pernas e as almofadas do mobiliário. Também podem instalar molas ou mecanismos especiais. Os montadores de mobiliário seguem instruções ou esquemas para a montagem do mobiliário e utilizam ferramentas manuais e elétricas.', 'released', '["Montadora de Mobiliário", "Montador de Mobiliário"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/d811881c-5241-47b1-be29-64ee488d3642', 'Supervisor de Fluxo de Bagagens', 'Os supervisores de fluxo de bagagens acompanham o fluxo de bagagens nos aeroportos para assegurar que as bagagens fazem as ligações e chegam aos destinos em tempo útil. Comunicam com os gestores de bagagens para assegurar o cumprimento da regulamentação e aplicar soluções corretas. Os supervisores de fluxo de bagagens procedem à recolha, análise e manutenção de registos dos dados sobre as companhias aéreas, os passageiros e o fluxo de bagagens, bem como elaboram e distribuem relatórios diários sobre as necessidades do pessoal, os perigos para a segurança, as necessidades de manutenção e os relatórios de incidentes. Asseguram um comportamento cooperativo e resolvem conflitos.', 'released', '["Supervisor de Fluxo de Bagagens", "Supervisora de Fluxo de Bagagens"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/d849fd2a-5210-434b-a50b-2d92de3a4bac', 'Projetista de Eletrônica', 'Os projetistas de eletrônica prestam apoio aos engenheiros eletrônicos na concepção e conceptualização de equipamentos eletrônicos. Elaboram planos técnicos e diagramas de montagem de sistemas e componentes eletrônicos utilizando software de desenho técnico.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/d84bf1d7-ef99-40c4-a407-3791d6531b44', 'Técnico de Engenharia de Telecomunicações', 'Os técnicos de engenharia de telecomunicações procedem à utilização, manutenção e controlo de um sistema de telecomunicações que fornece interações entre os dados e as comunicações de voz, tais como telefone, videoconferência, computador e sistemas de correio de voz. Também estão envolvidos na concepção, fabrico, construção, manutenção e reparação dos sistemas de telecomunicações. Os técnicos de engenharia de telecomunicações prestam assistência técnica na investigação e desenvolvimento de equipamento de telecomunicações.', 'released', '["Gestor de Telecomunicações", "Administrador de Telecomunicações", "Gestora de Telecomunicações", "Administradora de Telecomunicações", "Técnica de Engenharia de Telecomunicações"]'::jsonb, '3522'),
  ('http://data.europa.eu/esco/occupation/d85e041f-8306-476e-a2cd-59baa1e61992', 'Técnico de Captura em Aquicultura', 'Os técnicos de captura em aquicultura são responsáveis pelo processo de colheita da produção de organismos aquáticos, gerindo as máquinas e os equipamentos complexos utilizados na colheita de espécies cultivadas específicas.', 'released', '["Técnica de Captura em Aquicultura", "Técnico de Captura em Aquicultura"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/d871af8b-f6d7-4377-b609-d422afe3b5de', 'Gerente de Grande Drogaria', 'Os gerentes de grande drogaria são responsáveis pelas atividades e pessoal em drogarias que vendem artigos como revistas, produtos de uso doméstico, medicamentos, cosméticos, rebuçados ou refrescos. Estes funcionários gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerente de Centro Comercial", "Gerente de Loja de Conveniência", "Gerentea de Grande Drogaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/d87b1c64-eed1-404c-87de-f9f81c85fbde', 'Operador de Descaroçadoras de Algodão', 'Os operadores de descaroçadoras de algodão efetuam operações de descaroçamento para separar as fibras de algodão das sementes. Operam as enfardadeiras de algodão e removem os fardos processados da descaroçadora. Asseguram a manutenção da máquina e asseguram o bom funcionamento das operações de transformação.', 'released', '["Operador de Descaroçadoras de Algodão", "Operadora de Descaroçadoras de Algodão"]'::jsonb, '8151'),
  ('http://data.europa.eu/esco/occupation/d89b23c2-d042-4ca6-a917-109fe5a0b30c', 'Gestor Curricular', 'Os gestores curriculares desenvolvem e melhoram os programas curriculares das instituições de ensino. Analisam a qualidade dos programas curriculares existentes e trabalham para a sua melhoria. Comunicam com os profissionais do ensino a fim de assegurar uma análise rigorosa. Comunicam a evolução dos programas curriculares e desempenham funções administrativas.', 'released', '["Gestora Curricular", "Coordenador de Currículos", "Coordenadora de Currículos", "Gestor Curricular", "Gerente"]'::jsonb, '2351'),
  ('http://data.europa.eu/esco/occupation/d8e502b4-1be6-4d10-a224-151688f8f0c8', 'Agrimensor', 'Os agrimensores determinam, por meio de equipamento especializado, as distâncias e posições de pontos na superfície dos sítios para fins de construção. Utilizam medições dos aspetos específicos dos estaleiros, como a eletricidade, medições à distância e volumes de estruturas metálicas, para criar desenhos arquitetónicos e desenvolver projetos de construção.', 'released', '["Agrimensor", "Agrimensora"]'::jsonb, '2165'),
  ('http://data.europa.eu/esco/occupation/d8e5410b-5199-403f-8cbd-d32efb17a296', 'Gerente de Loja de Computadores', 'Os gerentes de loja de computadores assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja TI", "Gerente de Loja Multimédia", "Gerentea de Loja de Computadores"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/d8ed1703-9c03-4ea0-83cc-b6169bc54ffd', 'Assistente de Recursos Humanos', 'Os assistentes de recursos humanos prestam apoio em todos os processos e esforços levados a cabo pelos gestores de recursos humanos. Contribuem para a preparação dos processos de recrutamento através da digitalização de CV e da redução da seleção dos candidatos mais adequados. Executam tarefas administrativas, elaboram comunicações e cartas e procedem à classificação dos resultados dos inquéritos e avaliações efetuados pelo departamento.', 'released', '["RH", "Assistentea de Recursos Humanos"]'::jsonb, '4416'),
  ('http://data.europa.eu/esco/occupation/d8ff83c0-be8b-47f9-93e3-b13e261e7da5', 'Técnico de Prospeção Geológica', 'Os técnicos de prospeção geológica analisam os fluidos de perfuração após a perfuração. Analisam os fluidos num laboratório. Os técnicos de prospeção geológica determinam a posição dos hidrocarbonetos no que diz respeito à profundidade. Monitorizam também o gás natural e identificam a litologia.', 'released', '["Técnica de Prospeção Geológica", "Técnico de Prospeção Geológica"]'::jsonb, '2114'),
  ('http://data.europa.eu/esco/occupation/d9004a14-bda2-4c63-ab64-17ca163ac1bd', 'Assessor Parlamentar', 'Os assessores parlamentares prestam apoio a funcionários e políticos dos parlamentos regionais, nacionais e internacionais e desempenham tarefas logísticas. Procedem à revisão dos documentos oficiais e seguem os procedimentos estabelecidos pelos respetivos parlamentos. Prestam apoio na comunicação com as partes interessadas e fornecem o apoio logístico necessário para o tratamento dos processos oficiais.', 'released', '["Assessor Parlamentar", "Assessora Parlamentar"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/d907b046-682b-45fa-bdd0-d2ed7a382670', 'Especialista em Import-Export de Produtos do Tabaco', 'Os especialistas em import-export de produtos do tabaco possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Produtos do Tabaco"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/d954fd71-0e2f-4cf9-85f0-c040fa6cbda9', 'Diretor de Promoção e Vendas', 'Os diretores de promoção e vendas planificam e executam programas de promoção no ponto de venda dos produtos. Coordenam todos os esforços do pessoal, o material de publicidade abaixo da linha (BTL) e os esforços de publicidade convencionais, a fim de aumentar a sensibilização para uma promoção específica.', 'released', '["Diretora de Promoção e Vendas", "Diretor de Promoção e Vendas", "Sales"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/d9612966-e295-4d81-ba2b-9f36bad0b392', 'Coach Profissional', 'Os coaches profissionais orientam os trabalhadores de uma empresa ou de outra instituição, a fim de melhorarem a sua eficácia pessoal, aumentarem a sua satisfação no trabalho e terem um impacto positivo no seu desenvolvimento profissional no contexto empresarial. Para tal, levam o «coachee» (a pessoa que recebe a orientação) a resolver os seus desafios pelos próprios meios. O objetivo dos coaches profissionais é a realização de tarefas específicas ou o cumprimento de objetivos específicos, e não o desenvolvimento global.', 'released', '["Business Coach"]'::jsonb, '2424'),
  ('http://data.europa.eu/esco/occupation/d9632b0a-3c95-4a8a-a15c-c5413beda52e', 'Diretor de Importação e Exportação de Produtos Farmacêuticos', 'Os diretores de importação e exportação de produtos farmacêuticos implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Produtos Farmacêuticos", "Diretor de Importação e Exportação de Produtos Farmacêuticos", "Diretor de Vendas de Produtos Farmacêuticos", "Diretora de Importação e Exportação de Produtos Farmacêuticos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/d96de969-d43d-4082-8559-7fc35484a217', 'Gestor de Conta Bancária', 'Os gestores de conta bancária mantêm e alargam as relações com clientes atuais ou futuros. Utilizam técnicas de venda cruzada para aconselhar e vender vários produtos e serviços bancários e financeiros aos clientes. Gerem igualmente toda a relação com os clientes e são responsáveis pela otimização dos resultados empresariais e da satisfação dos clientes.', 'released', '["Gestora de Conta Bancária", "Gestor de Conta Bancária", "Gerente"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/d9723f33-7faf-4f8a-8a98-6b02d1e10f2b', 'Administrador de Insolvência', 'Os administradores de insolvência administram o processo de insolvência de um cliente, investigam as possibilidades de fraude e gerem os fundos recebidos da venda de bens não isentos, a fim de os distribuir aos devidos credores.', 'released', '["Administrador de Insolvência", "Administradora de Insolvência"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/d97fd1e8-4c61-459b-82cd-1bd0e792c568', 'Operário da Construção de Vias-Férreas', 'Os operários da construção de vias-férreas constroem linhas ferroviárias em locais preparados para o efeito. Supervisionam o equipamento que coloca travessas ou dormentes de caminho-de-ferro, normalmente numa camada de pedra britada ou balastro. Em seguida, os operários da construção de vias férreas colocam os carris ferroviários em cima das travessas e fixam-nos para garantir que os carris têm uma bitola constante, ou distância entre os mesmos. Estas operações são geralmente efetuadas com uma única máquina em movimento, mas podem ser executadas manualmente.', 'released', '["Operária da Construção de Vias Férreas", "Operário da Construção de Vias Férreas", "Operária da Construção de Vias-Férreas"]'::jsonb, '9312'),
  ('http://data.europa.eu/esco/occupation/d99e2022-cbe1-4aaa-8f9d-7db129d61f0c', 'Técnico de Tratamento de Águas Residuais', 'Os técnicos de tratamento de águas residuais prestam assistência aos operadores de estações de tratamento de águas residuais na operação e manutenção de equipamentos de tratamento de águas residuais e no processo de purificação de águas residuais em estações de tratamento de esgotos. Desempenham funções de reparação.', 'released', '["Técnica de Tratamento de Águas Residuais", "Técnico de Tratamento de Águas Residuais"]'::jsonb, '3132'),
  ('http://data.europa.eu/esco/occupation/d9ab0f3d-078d-42a7-a502-3e739e0aeff6', 'Técnico de Aviônica', 'Os técnicos de aviónica instalam, ensaiam, inspecionam e ajustam equipamentos elétricos e eletrônicos, tais como de navegação, comunicação e sistemas de controlo de voo em aeronaves e veículos espaciais. Realizam trabalhos de manutenção e reparação. Realizam testes funcionais, diagnosticam problemas e tomam medidas corretivas.', 'released', '["Técnica de Aviónica", "Técnico de Aviónica", "Técnica de Aviônica"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/d9e4581a-91b3-47f9-a2d5-70eb542caac5', 'Operador de Acabamento e Embalamento de Calçado', 'Os operadores de acabamento e embalamento de calçado aplicam várias técnicas para assegurar um aspeto final adequado dos pares de calçado embalados que vão ser vendidos. Seguem as informações recebidas do seu supervisor sobre o calçado que vai ser acabado, os meios e os materiais a utilizar e a sequência das operações.;', 'released', '["Operadora de Acabamento e Embalamento de Calçado", "Operador de Acabamento e Embalamento de Calçado"]'::jsonb, '8183'),
  ('http://data.europa.eu/esco/occupation/d9f67d41-5e35-49c1-82a4-05ed94fbc3ab', 'Inspetor de Pesos e Medidas', 'Os inspetores de pesos e medidas asseguram o cumprimento de regulamentos e acordos relativos aos pesos e medidas de produtos embalados. Investigam e documentam questões de conformidade e violações, a fim de promover as melhores práticas. Os inspetores de pesos e medidas confirmam que os produtos embalados estão em conformidade com acordos, tais como relativamente a quantidade, conteúdo e embalagem.', 'released', '["Inspetora de Pesos e Medidas", "Inspetor de Pesos e Medidas"]'::jsonb, '3359'),
  ('http://data.europa.eu/esco/occupation/d9fb82d0-9b07-4c38-b8e2-d146ff8850b9', 'Vendedor de Revestimentos de Paredes e Solos', 'Os vendedores de revestimentos de paredes e solos vendem revestimentos para paredes e solos em lojas especializadas.', 'released', '["Vendedora de Revestimentos de Paredes e Solos", "Vendedor de Revestimentos de Paredes e Solos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/da00cd76-22fe-450d-aefc-f4e4a3864171', 'Montador de Placas de Circuito Impresso', 'Os montadores de placas de circuito impresso interpretam esquemas e desenhos para montar placas de circuito impresso. Utilizam ferramentas de soldadura manual e automática e máquinas para ligar os componentes eletrônicos à placa.', 'released', '["Montador de Placas de Circuito Impresso", "Montadora de Placas de Circuito Impresso"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/da4589ce-7534-4cc1-9ce4-cabf9364b87c', 'Localizador', 'Os localizadores traduzem e adaptam textos para a língua e a cultura de um público-alvo específico. Convertem a tradução normalizada em textos localmente compreensíveis com toques da cultura, provérbios e outras subtilezas que tornam a tradução mais rica e mais significativa do que era anteriormente para um determinado grupo-alvo cultural.', 'released', '["Localizadora", "Localizador"]'::jsonb, '2643'),
  ('http://data.europa.eu/esco/occupation/da6220cb-21ee-4076-8796-1e922b44c394', 'Inspetor de Motores de Navios', 'Os inspetores de motores de navios inspecionam os motores de navios e de embarcações, como os motores elétricos, os reatores nucleares, os motores de turbinas a gás, os motores fora de borda, os motores diesel a dois ou a quatro tempos, os motores a GNL, os motores de duplo combustível e, em alguns casos, os motores marítimos a vapor, em instalações de montagem, a fim de garantir a sua conformidade com as normas e a regulamentação em matéria de segurança. Realizam inspeções de rotina, pós-revisão, pré-disponibilidade e pós-acidentes. Fornecem documentação para atividades de reparação e apoio técnico aos centros de manutenção e reparação. Verificam os registos administrativos, analisam o desempenho operacional dos motores e elaboram relatórios com as suas conclusões.', 'released', '["Inspetora de Motores de Navios", "Inspetor de Motores de Navios"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/daa6197d-dba6-49b5-8223-b31b7a126e4e', 'Operador de Branqueamento de Cera', 'Os operadores de branqueamento de cera procedem à operação e manutenção de filtros-prensa e tanques, utilizados no branqueamento de cera, para processos de produção de velas.', 'released', '["Operador de Branqueamento de Cera", "Operadora de Branqueamento de Cera"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/dab60fc6-c16e-4de7-b969-b323784f5a49', 'Gestor de Categorias', 'Os gestores de categoria definem o programa de vendas para grupos específicos de produtos. Analisam as exigências do mercado e os produtos recentemente fornecidos.', 'released', '["Compradora", "Gestora de Categoria de Produtos", "Gestora de Categorias", "Gestor de Categorias", "Gestor de Categoria de Produtos", "Comprador", "Gerente"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/dab9c6dd-8efb-4fe2-8b10-477ef2bcfd8b', 'Professor de Matemática', 'Os professores de Matemática lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Matemática, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Matemática, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Matemática", "Professor Universitário de Matemática", "Professora Universitária de Matemática", "Professor de Matemática"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/dacaa18b-93f6-48b4-b4f2-cb33e21804e7', 'Técnico de Qualidade na Indústria Química', 'Os técnicos de qualidade na indústria química realizam inspeções e medições de precisão, a fim de testar e garantir a qualidade dos produtos, utilizando máquinas e sistemas controlados por computador.', 'released', '["Técnica de Qualidade na Indústria Química", "Técnico de Qualidade na Indústria Química"]'::jsonb, '3116'),
  ('http://data.europa.eu/esco/occupation/db20c08e-819e-4410-91e2-6ac06add4e27', 'Acompanhante de Serviço Escort', 'Os acompanhantes de serviço escort acompanham pessoas a eventos sociais, mas também em ocasiões mais privadas, tais como jantares ou visitas a clubes noturnos. Podem ser responsáveis pela organização do transporte e pela compra de bilhetes para locais de interesse. Esta atividade pode incluir a prestação de serviços eróticos ou sexuais ao cliente, caso seja uma atividade legal no respetivo país. ;', 'released', '["Escort", "Acompanhantea de Serviço Escort"]'::jsonb, '5169'),
  ('http://data.europa.eu/esco/occupation/db25e659-d77c-4f4a-a8a2-ee199d060345', 'Moleiro', 'Os moleiros asseguram o correto funcionamento de moinhos para esmagar as culturas de cereais para obter farinha. Regulam o fluxo de materiais que entram nos moinhos e ajustam a moagem para uma espessura especificada. Asseguram a manutenção básica e a limpeza dos equipamentos. Avaliam a amostra do produto para verificar o grau de trituração.', 'released', '["Operadora de Instalação de Moagem", "Operador de Instalação de Moagem", "Operadora de Moinho", "Operador de Moinho", "Moleira", "Moleiro"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/db3b1cb9-8460-4de0-8fc7-aff7a9a74b7e', 'Pintor de Porcelana', 'Os pintores de porcelana concebem e criam arte visual em superfícies e objetos de porcelana, tais como azulejos e cerâmica. Recorrem a várias técnicas para produzir ilustrações decorativas, desde desenho com estêncil até à mão livre.', 'released', '["Pintora de Porcelana", "Pintor de Azulejos", "Pintora de Azulejos", "Pintor de Porcelana", "Pintora de Cerâmica", "Pintor de Cerâmica"]'::jsonb, '7316'),
  ('http://data.europa.eu/esco/occupation/db3da11f-67a0-415f-b785-81f33d3be810', 'Jornalista de Economia', 'Os jornalistas de economia investigam e redigem artigos sobre economia e eventos econômicos para jornais, revistas, televisão e outros meios de comunicação social. Realizam entrevistas e participam em eventos.', 'released', '["Jornalista Especializada em Economia", "Jornalista Especializado em Economia"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/db4057de-0c5a-4f68-8f81-2c0765978afb', 'Chefe de Sala', 'Os chefes de sala são responsáveis pelas áreas de eventos ao vivo acessíveis ao público. Asseguram a interação com os clientes ou os visitantes de forma harmoniosa e profissional. Os chefes de sala são responsáveis pela venda de bilhetes e bebidas e asseguram que os espaços acessíveis ao público são devidamente delimitados. Interagem com o diretor das instalações e o diretor de palco.', 'released', '["Diretor de Restaurante", "Profissional de Sala", "Diretora de Restaurante", "Chefea de Sala"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/db4f28ff-c208-4830-ab8b-4b07776db134', 'Diretor Artístico', 'Os diretores artísticos são responsáveis pelo programa de um projeto artístico ou de uma organização cultural. São responsáveis pela visão estratégica, pela visibilidade e pela qualidade de todo o tipo de atividades e serviços artísticos, como companhias de teatro e de dança. Os diretores artísticos gerem igualmente o pessoal, as finanças e as políticas.', 'released', '["Diretora Artística", "Diretor Artístico", "Diretora Artístico"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/db55bf08-3ad3-4bf6-bf59-7f9f426a6de5', 'Operador de Processos de Alteração de Vestuário', 'Os operadores de processos de alteração de vestuário asseguram a alteração das peças de vestuário acabadas de acordo com os requisitos das empresas. São responsáveis pela qualidade de quaisquer alterações ou adaptações e pelo estoque genérico da marca, em conformidade com as orientações relativas à marca dos clientes.', 'released', '["Operador de Processos de Alteração de Vestuário", "Operadora de Processos de Alteração de Vestuário"]'::jsonb, '8153'),
  ('http://data.europa.eu/esco/occupation/dbc88790-a8c1-4dc4-9507-8f9dcff9c990', 'Engenheiro Projetista de Motores', 'Os engenheiros projetistas de motores executam tarefas de engenharia na concepção de equipamentos mecânicos, tais como máquinas e todos os tipos de motores. Supervisionam também a sua instalação e manutenção.', 'released', '["Engenheiro Projetista de Motores", "Engenheira Projetista de Motores", "Projetista de Motores"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/dbdc9f7b-31c6-4f21-a9c5-48253bb69c08', 'Planejador de Compras', 'Os planificadores de compras organizam o fornecimento contínuo de produtos a partir de contratos existentes.', 'released', '["Planificadora de Compras", "Gestor de Compras", "Planificador de Compras", "Gestora de Compras", "Planejadora de Compras"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/dc14bed4-87ca-4e6c-9f69-458e2689d2d6', 'Operador de Fundição', 'Os operadores de fundição fabricam peças vazadas, incluindo canos, tubos, perfis ocos e outros produtos da primeira transformação de aço, operando equipamento sob controlo manual numa fundição. Conduzem o fluxo de metais ferrosos e não ferrosos derretidos para moldes, tendo o cuidado de criar as condições exatas adequadas para obter metal da mais elevada qualidade. Observam o fluxo de metal para identificar falhas. Em caso de falha, notificam o pessoal autorizado e participam na eliminação da falha.', 'released', '["Operador de Fundição", "Operadora de Fundição"]'::jsonb, '7211'),
  ('http://data.europa.eu/esco/occupation/dc29cd23-d6ba-46b0-bc2f-424e20270099', 'Diretor de Importação e Exportação de Frutas e Hortaliças', 'Os diretores de importação e exportação de frutos e produtos hortícolas implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação de Frutos e Produtos Hortícolas", "Diretora de Importação e Exportação de Frutos e Produtos Hortícolas", "Diretora de Vendas de Frutos e Produtos Hortícolas", "Diretor de Vendas de Frutos e Produtos Hortícolas", "Diretora de Importação e Exportação de Frutas e Hortaliças"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/dc2a924c-653a-4922-9226-f6909dd64580', 'Diretor de Importação e Exportação do Setor Agrícola', 'Os diretores de importação e exportação do setor agrícola implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas Setor Agrícola", "Diretora de Importação e Exportação do Setor Agrícola", "Diretor de Importação e Exportação do Setor Agrícola", "Diretor de Vendas Setor Agrícola"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/dc34c345-caf9-4ab7-b496-e18a572194ba', 'Tanatopractor', 'Os tanatopractores asseguram a remoção de corpos de pessoas falecidas do local do óbito e preparam os corpos para os enterros e as cremações. Limpam e desinfetam os corpos, utilizam maquilhagem para criar a impressão de um aspeto mais natural e ocultar qualquer dano visível. Estão em contato estreito com os diretores de serviços funerários a fim de dar cumprimento à vontade dos familiares da pessoa falecida.', 'released', '["Taxidermista", "Tanatopractora", "Embalsamadora", "Tanatopractor", "Embalsamador"]'::jsonb, '5163'),
  ('http://data.europa.eu/esco/occupation/dc3cc282-488d-4d8f-be80-191c6b521823', 'Produtor de Malte', 'Os produtores de malte avaliam e classificam diferentes maltes, numa base sensorial, para fins de fabrico de cerveja. Avaliam o aspeto, o aroma e o sabor das matérias-primas e dos produtos inacabados para manter a consistência dos produtos. Utilizam os seus conhecimentos para preparar misturas no âmbito do desenvolvimento de produtos.', 'released', '["Produtor de Malte", "Produtor de Whisky de Malte", "Produtora de Malte", "Produtora de Whisky de Malte"]'::jsonb, '7515'),
  ('http://data.europa.eu/esco/occupation/dc52966e-72db-4ad0-b3a9-5e17f1311ab8', 'Reparador de Joias', 'Os reparadores de joias recorrem a ferramentas manuais especializadas para efetuar ajustes e reparações em todos os tipos de peças de joalharia. Redimensionam anéis ou colares, reengastam pedras preciosas e reparam peças de joalharia partidas. Os reparadores de joias identificam os metais preciosos adequados para serem utilizados como substitutos, soldam e alisam uniões. Limpam e pulem as peças reparadas a ser devolvidas ao cliente.', 'released', '["Reparador de Joias", "Reparadora de Joias", "Ourives"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/dc54d531-70b5-4301-bc75-da76c2dfac1a', 'Supervisor de Montagem de Material Circulante', 'Os supervisores de montagem de material circulante coordenam os trabalhadores envolvidos no fabrico de material circulante e programam as suas atividades. Elaboram relatórios de produção e recomendam medidas para reduzir os custos e aumentar a produtividade, como a contratação, a encomenda de novos equipamentos e a implementação de novos métodos de produção. Formam os trabalhadores nas políticas da empresa, no exercício das funções e nas medidas de segurança. Supervisionam as existências e comunicam com outros departamentos, tendo em vista evitar interrupções desnecessárias do processo de produção.', 'released', '["Supervisora de Montagem de Material Circulante", "Supervisor de Montagem de Material Circulante"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/dc69f2ed-ebe9-43da-bf9d-31aac874d4c2', 'Assistente Social Especialista em Reabilitação', 'Os assistentes sociais especialistas em reabilitação prestam aconselhamento a indivíduos com malformações congénitas ou com sequelas graves provocadas por doenças, acidentes e situações de esgotamento. Ajudam-nos a lidar com problemas pessoais, sociais e profissionais. Avaliam as necessidades pessoais dos utentes, desenvolvem planos de reabilitação, participam na formação e ajudam os indivíduos submetidos a planos de reabilitação a obterem uma colocação profissional.', 'released', '["Assistente Social Especialista em Reabilitação Profissional", "Assistentea Social Especialista em Reabilitação"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/dc6c0b28-adf7-4558-a987-2ef1506ef2d1', 'Especialista em Import-Export de Porcelana e Outros Artigos de Vidro', 'Os especialistas em import-export de porcelana e outros artigos de vidro possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Porcelana e Outros Artigos de Vidro"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/dc8ef7da-d2c0-4474-96a0-6d0385eeec1e', 'Webmaster', 'Os webmasters procedem à instalação, manutenção, controlo e apoio de um servidor Web para dar resposta aos requisitos do serviço. Asseguram a integridade, a segurança, a salvaguarda e o desempenho máximos do sistema. Coordenam o conteúdo, a qualidade e o estilo dos sites, executam a estratégia do site e atualizam e acrescentam novas funcionalidades aos sites.', 'released', '["Administradora de Websites", "Administrador de Sites", "Webmaster", "Administradora de Sites", "Administrador de Websites"]'::jsonb, '3514'),
  ('http://data.europa.eu/esco/occupation/dc90cee4-bf4a-4d62-b729-faf49e62643e', 'Operador de Gruas para Movimentação de Contêineres', 'Os operadores de gruas para movimentação de contentores operam gruas elétricas equipadas com braços horizontais, nos quais é suportado o equipamento de elevação para carregar ou descarregar carga contentorizada. Deslocam torres para a posição ao longo do navio e descem os braços horizontais sobre o convés ou o porão de um navio. Elevam e movem o contentor ao longo do braço horizontal e posicionam o contentor na doca, no convés ou no porão do navio.', 'released', '["Operador de Gruas para Movimentação de Contentores", "Operadora de Gruas para Movimentação de Contentores", "Operadora de Gruas para Movimentação de Contêineres"]'::jsonb, '8343'),
  ('http://data.europa.eu/esco/occupation/dc97adbe-f807-4ad8-8f3c-c24b3416cdef', 'Gestor de Marketing Digital', 'Os gestores de marketing digital são responsáveis pela elaboração da estratégia de marketing digital da empresa, com o objetivo de melhorar o reconhecimento e a promoção da marca, em consonância com a missão e a visão da empresa. Supervisionam a execução de estratégias de marketing e comunicação digitais que envolvem a utilização das redes sociais, marketing por correio eletrônico, automatização do marketing, otimização dos motores de pesquisa, eventos em linha e publicidade em linha através de metodologias baseadas em dados e da medição e monitorização dos indicadores-chave de desempenho para o marketing digital, a fim de aplicar um plano de medidas corretivas. Gerem e interpretam os dados dos concorrentes e dos consumidores e realizam estudos sobre as condições de mercado.;', 'released', '["Especialista em Marketing na Web", "Técnico de Marketing Digital", "Estrategista de Marketing Digital", "Especialista em Mídia Social", "Profissional de Marketing e Comunicação Digital", "Especialista em Marketing Digital", "Associado de Marketing Digital", "Técnica de Marketing Digital", "Gerente", "Marketing Digital", "Gestora de Marketing Digital"]'::jsonb, '1221'),
  ('http://data.europa.eu/esco/occupation/dc9b98da-c389-4caf-a21a-c6f8c530c0bf', 'Reparador de Calçado', 'Os reparadores de calçado reparam e renovam o calçado deteriorado e outros artigos, tais como cintos ou sacos. Utilizam ferramentas manuais e especializadas para acrescentar solas e tacões, substituem as fivelas gastas e limpam e pulem o calçado.', 'released', '["Sapateiro", "Reparador de Calçado", "Reparadora de Calçado", "Sapateira"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/dca305c8-d665-462c-bdc9-c3a19734ba18', 'Engenheiro de Superfícies', 'Os engenheiros de superfície investigam e desenvolvem tecnologias para processos de fabrico que ajudam à alteração das propriedades da superfície do material de base, tal como o metal, a fim de reduzir a degradação por corrosão ou desgaste. Exploram e concebem formas de proteger superfícies de peças e produtos (metálicos) utilizando materiais sustentáveis e realizando testes com um mínimo de resíduos.', 'released', '["Engenheiro de Superfícies", "Engenheira de Superfícies"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/dce6a68c-8a05-4c26-85d4-6fbc43e7d822', 'Projecionista', 'Os projecionistas procedem à operação e manutenção do equipamento de projeção em salas de cinema. Inspecionam os filmes de cinema antes de carregá-los no projetor. Os projecionistas asseguram que ocorram problemas durante a projeção do filme. São também responsáveis pelo armazenamento adequado dos filmes de cinema.', 'released', NULL, '3521'),
  ('http://data.europa.eu/esco/occupation/dcfeb6e4-f39d-49fb-96cd-23292fb3e037', 'Técnico de Optoeletrônica', 'Os técnicos de optoeletrónica colaboram com os engenheiros no desenvolvimento de sistemas e componentes optoeletrónicos, como fotodíodos, sensores óticos, «lasers» e LED. Os técnicos de optoeletrónica constroem, testam, instalam e calibram equipamentos optoeletrónicos. Efetuam a leitura de planos e outros desenhos técnicos para desenvolverem os procedimentos de ensaio e calibração.', 'released', '["Técnico de Optoeletrónica", "Técnica de Optoeletrónica", "Técnica de Optoeletrônica"]'::jsonb, '3114'),
  ('http://data.europa.eu/esco/occupation/dd25a2b0-add0-4ae2-bd85-bb644e0d0c39', 'Responsável de Centro de Atendimento', 'Os responsáveis de centros de atendimento definem os objetivos do serviço para cada mês, semana e dia. Executam atividades de microgestão dos resultados obtidos no centro, a fim de agirem de forma proativa relativamente a planos, ações de formação ou planos de motivação, em função dos problemas enfrentados pelo serviço. Procuram alcançar os indicadores-chave de desempenho, como o tempo mínimo de funcionamento, as vendas por dia e o cumprimento dos parâmetros de qualidade.', 'released', '["Responsável de Centro de Chamadas", "Responsável de Centro Telefônico de Atendimento", "Responsável de Call Centre"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/dd89e26f-bb5c-45cb-91c6-8b4d5d82a31f', 'Trabalhador de Demolição', 'Os trabalhadores de demolição utilizam equipamento de demolição de estruturas. Destroem com segurança os edifícios e removem os detritos para que o sítio possa ser utilizado para uma finalidade diferente.', 'released', '["Trabalhador de Demolição", "Operário de Demolição", "Trabalhadora de Demolição", "Operária de Demolição"]'::jsonb, '7119'),
  ('http://data.europa.eu/esco/occupation/dd935705-d703-40ba-9ba7-2a8a2b7651b4', 'Gestor de Condomínios', 'Os gestores de condomínios supervisionam os serviços de um condomínio para os arrendatários ou residentes. Trabalham para associações de habitação ou organizações privadas para as quais cobram taxas de arrendamento, inspecionam as propriedades, sugerem e aplicam melhorias no que se refere a reparações ou questões de perturbação da vizinhança, mantêm a comunicação com os inquilinos, tratam de pedidos de habitação e estabelecem contatos com as autoridades locais e os gestores imobiliários. Contratam, formam e supervisionam o pessoal.', 'released', '["Gestora de Condomínios", "Gestor de Condomínios", "Gerente"]'::jsonb, '3334'),
  ('http://data.europa.eu/esco/occupation/ddac39cf-5d8b-416a-b24b-9ce3a8a4a668', 'Especialista em Import-Export de Perfumes e Cosméticos', 'Os especialistas em import-export de perfumes e cosméticos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Perfumes e Cosméticos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/ddb3e6a4-5bae-480a-a49a-748f93022892', 'Marinheiro de Convés', 'Os marinheiros de convés são membros não licenciados do convés de uma embarcação de navegação interior. Esta posição é geralmente o primeiro passo no sentido de se tornar um marinheiro capaz e progredir na carreira. Desempenham uma série de tarefas relacionadas com a exploração e a manutenção das zonas de convés, o motor e outro equipamento, a amarração e desamarração, bem como (até certo ponto) a direção do navio.', 'released', '["Marinheiro de Convés", "Marinheira de Convés"]'::jsonb, '8350'),
  ('http://data.europa.eu/esco/occupation/dddf9385-2939-4395-951a-70ef8a36cabe', 'Superintendente de Estivador', 'Os superintendentes de estivador supervisionam e acompanham a movimentação de carga e o trabalho de estiva num estaleiro para maximizar a produtividade. Gerem as operações de carga e a descarga e controlam a segurança da zona de trabalho. Os superintendentes de estivador também podem investigar incidentes e preparar relatórios de acidentes.', 'released', '["Operadora de Pórtico", "Superintendente de Estivador", "Superintendente de Estivadora", "Estagiária de Estivadora", "Estagiário de Estivador", "Manobrador", "Operador de Pórtico", "Manobradora", "Superintendentea de Estivador"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/de0084a5-7e00-43cc-bc51-3cb70a031295', 'Diretor de Distribuição de Eletrodomésticos', 'Os diretores de distribuição de eletrodomésticos planificam a distribuição de eletrodomésticos a diversos pontos de venda.', 'released', '["Diretor de Distribuição de Eletrodomésticos", "Diretor de Logística no Setor dos Eletrodomésticos", "Diretora de Logística no Setor dos Eletrodomésticos", "Diretora de Distribuição de Eletrodomésticos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/de0856fe-21fa-46d6-88ee-f99d3b4946bc', 'Inspetor de Resíduos Perigosos', 'Os inspetores de resíduos perigosos inspecionam instalações industriais para garantir que respeitam a legislação relativa à eliminação de resíduos e inspecionam os seus equipamentos, a fim de verificar a sua operacionalidade e conformidade com a regulamentação. Visam igualmente informar o público sobre questões relativas às substâncias perigosas e sobre a regulamentação em matéria de tratamento de resíduos perigosos.', 'released', '["Inspetora de Resíduos Perigosos", "Inspetor de Resíduos Perigosos"]'::jsonb, '3257'),
  ('http://data.europa.eu/esco/occupation/de31a27f-c6ba-4d4f-87cd-b405e1852121', 'Gerente de Agência de Aluguel', 'Os gerentes de agência de aluguer supervisionam as atividades de um escritório ou estação de aluguer e o respetivo pessoal.', 'released', '["Gerentea de Agência de Aluguel"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/de50b422-8700-4153-955c-131c3d277738', 'Comerciante Grossista de Animais Vivos', 'Os comerciantes grossistas de animais vivos investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Animais Vivos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/de74eb4e-c95e-425a-9b3a-7be805ec0321', 'Consultor Energético', 'Os consultores energéticos aconselham os clientes sobre as vantagens e as desvantagens das diferentes fontes de energia. Ajudam os clientes a compreender as tarifas de energia e procuram reduzir o seu consumo de energia e a pegada de carbono utilizando produtos e métodos eficientes do ponto de vista energético.', 'released', '["Consultora Energética", "Consultora em Energia", "Consultor em Energia", "Consultor Energético", "Consultora Energético"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/de80bbf0-447d-4a6a-845a-fdba4e0dc30c', 'Gestor de Marca', 'Os gestores de marca analisam e planeiam a forma como uma marca é posicionada no mercado.', 'released', '["Gestor de Marca", "Gestora de Marca", "Gerente"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/de99886e-59e3-432d-ba53-9652dbe378d6', 'Gestor de Programas de Financiamento', 'Os gestores de programas de financiamento chefiam o desenvolvimento e a execução da estratégia de financiamento dos programas de uma organização.', 'released', '["Gestor de Programas de Financiamento", "Gestora de Programas de Financiamento", "Gerente"]'::jsonb, '2412'),
  ('http://data.europa.eu/esco/occupation/dec7ed73-8688-4328-bc50-c72d31b25956', 'Técnico de Instrumentos de Precisão', 'Os técnicos de instrumentos de precisão interpretam esquemas e desenhos de montagem de instrumentos de precisão, tais como micrómetros, calibres, termóstatos e contadores de serviços públicos. Recolhem os diferentes componentes e montam-nos com ferramentas manuais ou máquinas. Também calibram os instrumentos e testam a sua precisão.', 'released', '["Técnica de Instrumentos de Precisão", "Técnico de Instrumentos de Precisão"]'::jsonb, '7311'),
  ('http://data.europa.eu/esco/occupation/defbf906-e823-44b4-872f-99406c51022b', 'Projetista de Sistemas de Aquecimento, Ventilação, Ar Condicionado e Refrigeração', 'Os projetistas de sistemas de aquecimento, ventilação, ar condicionado e refrigeração criam protótipos e esboços, pormenores técnicos e instruções estéticas fornecidas por engenheiros para a criação de desenhos, geralmente assistida por computador, de sistemas de aquecimento, ventilação e ar condicionado e, possivelmente, de refrigeração. Podem desenhar para todos os tipos de projetos em que estes sistemas possam ser utilizados.', 'released', NULL, '3118'),
  ('http://data.europa.eu/esco/occupation/defc8417-eeb6-4f13-8fcd-6518b99a40f4', 'Operador de Máquina de Enlatamento de Frutas e Vegetais', 'Os operadores de máquina de enlatamento de frutas e vegetais asseguram o correto funcionamento de máquinas para preparar produtos industriais à base de frutas e vegetais para armazenagem ou expedição. Executam uma vasta gama de tarefas, tais como a triagem, a triagem, a lavagem, a descasca, a aparagem e a laminagem. Também cumprem procedimentos para o fabrico de conservas, a congelação, a conservação e a embalagem de produtos alimentares.', 'released', '["Conserveiro de Frutos e Vegetais", "Conserveira de Frutos e Vegetais", "Operador de Máquina de Enlatamento de Frutas e Vegetais", "Conserveira de Frutas e Legumes", "Conserveiro de Frutas e Legumes", "Operadora de Máquina de Enlatamento de Frutas e Vegetais"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/df433613-4856-4e50-9be5-7a0ec0f4260a', 'Operador de Máquinas de Imersão de Borracha', 'Os operadores das máquinas de imersão de borracha mergulham as formas em látex líquido para fabricar produtos de borracha, tais como balões, dedeiras ou preservativos. Misturam o látex e vertem-no na máquina. Os operadores de máquinas de imersão de borracha recolhem uma amostra de produtos de látex após o mergulho final e pesam-na. Acrescentam amoníaco ou mais látex à máquina se o produto não cumprir os requisitos.', 'released', '["Operador de Máquinas de Imersão de Borracha", "Operadora de Máquinas de Imersão de Borracha"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/df66a6e6-2130-4932-8aaf-263dafa569fa', 'Gestor de Produção de Minas', 'Os gestores de produção de minas coordenam e executam planos e programas de produção de minas de curto e médio prazo, como a perfuração, a dinamitação, a extração de minério e minerais e a gestão de resíduos.', 'released', '["Gestora de Produção Minas", "Gestor de Produção Minas", "Chefe de Mina", "Chefe de Pedreira", "Gerente", "Gestora de Produção de Minas"]'::jsonb, '1322'),
  ('http://data.europa.eu/esco/occupation/dfa51b4d-0929-4885-b682-29e375c6b52c', 'Analista de Dividendos', 'Os analistas de dividendos calculam e atribuem os dividendos e os rendimentos dos juros dos lucros de uma empresa a uma categoria dos seus acionistas. Avaliam os sistemas e processos empresariais, a fim de identificar as necessidades dos usuários e apresentar soluções adequadas. Também realizam previsões de dividendos sobre montantes e prazos de pagamento e identificam riscos potenciais, com base nos seus conhecimentos financeiros e de preços de mercado.', 'released', '["Analista de Dividendos"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/dfb93ddb-ce34-4d2e-a178-541d45a7d98b', 'Supervisor de Operadores de Máquinas de Lavandaria', 'Os supervisores de operadores de máquinas de lavandaria supervisionam e coordenam as atividades do pessoal da lavandaria e de limpeza a seco das lavandarias e das empresas de lavandaria industrial. Planeiam e implementam programas de produção, contratam e dão formação a funcionários e supervisionam os níveis de qualidade da produção.', 'released', '["Supervisora de Operadores de Máquinas de Lavandaria", "Supervisor de Operadores de Máquinas de Lavandaria"]'::jsonb, '8157'),
  ('http://data.europa.eu/esco/occupation/e00c46c4-bd3c-4d88-8d30-fc6f951554bd', 'Confeiteiro', 'Os confeiteiros apresentam uma gama variada de bolos, guloseimas e outros artigos de confeitaria para fins industriais ou venda direta.', 'released', '["Confeiteira", "Produtor de Confeitaria", "Produtora de Confeitaria", "Confeiteiro"]'::jsonb, '7512'),
  ('http://data.europa.eu/esco/occupation/e011f10f-e172-43ce-bfd9-fb56e426c0c9', 'Técnico de Reservas Naturais', 'Os técnicos de reservas naturais são responsáveis por uma série de atividades que gerem e mantêm o ambiente natural, bem como o acesso público associado e as atividades de lazer. Atraem visitantes a espaços/zonas rurais, promovem a sensibilização para o ambiente natural e protegem e preservam os espaços/zonas rurais para utilização futura.', 'released', '["Guarda de Recursos Florestais", "Operária de Reservas Naturais", "Operário de Reservas Naturais", "Guarda-Florestal", "Técnico de Reservas Naturais", "Técnica de Reservas Naturais"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/e01719f4-d7dd-42fe-b504-93128520f84a', 'Especialista em Publicidade', 'Os especialistas em publicidade prestam aconselhamento às empresas e organizações sobre o desenvolvimento das suas estratégias publicitárias e sobre temas relacionados com publicidade que incluam uma abordagem estratégica mais geral. Combinam os conhecimentos sobre marketing, orçamentos e psicologia com um espírito criativo para desenvolverem campanhas publicitárias. Propõem alternativas aos clientes para a promoção das suas organizações, produtos ou projetos.', 'released', NULL, '2431'),
  ('http://data.europa.eu/esco/occupation/e027434f-8aa4-4d87-a070-b1d5c57749e6', 'Químico Especialista em Fragrâncias', 'Os químicos especialistas em fragrâncias desenvolvem e melhoram os produtos químicos de fragrâncias através da formulação, ensaio e análise de substâncias das fragrâncias e dos seus ingredientes, de modo a que o produto final satisfaça as expectativas e as necessidades dos clientes.', 'released', '["Químico Especialista em Fragrâncias", "Especialista no Desenvolvimento de Fragrâncias", "Perfumista", "Formuladora de Fragrâncias", "Formulador de Fragrâncias", "Química Especialista em Fragrâncias"]'::jsonb, '2113'),
  ('http://data.europa.eu/esco/occupation/e02d7c8a-1e38-4a67-a6e1-f580e550238f', 'Vendedor de Discos e Vídeos', 'Os vendedores de discos e vídeos vendem discos de música, cassetes áudio, discos compactos, cassetes de vídeo e DVD em lojas especializadas.', 'released', '["Vendedora de Discos e Vídeos", "Vendedor de Discos e Vídeos"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/e0433bbb-8a93-4ab4-ac7a-84ccc1a04637', 'Diretor de Distribuição de Bebidas', 'Os diretores de distribuição de bebidas planificam a distribuição de bebidas a vários pontos de venda.', 'released', '["Diretor de Distribuição de Bebidas", "Diretora de Logística de Bebidas", "Diretora de Distribuição de Bebidas", "Diretor de Logística de Bebidas"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/e047b8f5-9491-4da2-8816-7aa37ad2370d', 'Engenheiro Examinador de Patentes', 'Os engenheiros examinadores de patentes aconselham as empresas sobre diferentes aspetos do direito de propriedade intelectual. Analisam invenções e analisam o seu potencial econômico. Verificam se os direitos de patente já foram atribuídos a uma invenção e garantem que esses direitos não foram afetados ou violados.', 'released', '["Engenheira Examinadora de Patentes", "Engenheiro Examinador de Patentes", "Engenheira Examinador de Patentes"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/e04bca7b-c0c7-454d-9d15-dfb64a30dc0a', 'Diretor de Distribuição — Máquinas e Equipamento Agrícola', 'Os diretores de distribuição — máquinas e equipamento agrícola planificam a distribuição de máquinas e equipamentos agrícolas a diversos pontos de venda.', 'released', '["Gestor da Cadeia de Distribuição de Maquinaria e Equipamento Agrícola", "Diretora de Distribuição — Máquinas e Equipamento Agrícola", "Gestora da Cadeia de Distribuição de Maquinaria e Equipamento Agrícola", "Diretor de Distribuição — Máquinas e Equipamento Agrícola"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/e0628770-57f0-4cf2-952e-5b16547db8c1', 'Técnico de Cultivo de Aquicultura', 'Os técnicos de cultivo de aquicultura são responsáveis pela produção de organismos aquáticos, especializando-se na criação de processos de cultura de engorda, especialmente na gestão da alimentação e das unidades populacionais.', 'released', '["Técnico de Cultivo de Aquicultura", "Técnica de Produção em Aquicultura", "Técnica de Cultivo de Aquicultura"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/e0904e3f-d3e7-4313-8ff9-3facf9fce70d', 'Comerciante Grossista de Bebidas', 'Os comerciantes grossistas de bebidas investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Bebidas"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/e0b347de-f88b-4f69-b7d0-0a965e41f0d5', 'Operador de Moinho de Cacau', 'Os operadores de moinho de cacau asseguram o correto funcionamento de máquinas para pulverizar os grãos de cacau em pó com uma finura especificada. Utilizam sistemas de classificação por ar que separam o pó com base na sua densidade. Também pesam, ensacam e empilham o produto.', 'released', '["Operador de Moinho de Cacau", "Operadora de Moinho de Cacau", "Operador de Máquina de Moer Cacau", "Operadora de Máquina de Moer Cacau"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/e0b544dd-b621-4126-a55e-054af25c6ea0', 'Arquiteto de Redes Informáticas', 'Os arquitetos de redes informáticas concebem a topologia e a conectividade das redes informáticas, como o hardware, as infraestruturas, a comunicação e os componentes de hardware.', 'released', '["Arquiteto de Redes", "Arquiteta de Redes", "Arquiteta de Redes Informáticas", "Arquiteto de Redes Informáticas"]'::jsonb, '2523'),
  ('http://data.europa.eu/esco/occupation/e0c5e005-6303-4d5a-9125-a7f86ed1c4df', 'Operador de Liquidificador de Cacau', 'Os operadores de liquidificador de cacau operam moinhos que moem os grãos de cacau quebrados ou flocos de pasta de cacau, para obter chocolate líquido da consistência especificada. Em seguida, operam tremonhas, deslocando as respetivas portas para libertar os flocos de cacau, que depois passam por rodas de esmerilagem.', 'released', '["Operadora de Máquina de Liquidificação de Cacau", "Operadora de Liquidificador de Cacau", "Operador de Liquidificador de Cacau", "Operador de Máquina de Liquidificação de Cacau"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/e1106f6d-81fc-44f8-af94-8b7d2763065c', 'Assistente de Direção de Cena', 'Os assistentes de direção de cena apoiam as necessidades do encenador de teatro e da produção para cada produção de teatro atribuída e servem de ligação entre artistas, pessoal de teatro e encenador de teatro. Tomam notas, dão opinião, coordenam o horário do ensaio, fazem as marcações de cena, ensaiam ou analisam cenas, preparam ou distribuem notas dos atores e facilitam a comunicação entre os designers, o pessoal de produção e o encenador de teatro.', 'released', '["Assistentea de Direção de Cena"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/e11e5be4-49e7-48ac-8e0d-6d3ffd3dbcd0', 'Vendedor de Produtos de Mercearia Fina', 'Os vendedores de produtos de mercearia fina vendem especialidades finas em lojas especializadas.', 'released', '["Vendedor de Produtos de Mercearia Fina", "Vendedora de Produtos de Mercearia Fina"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/e12f08fb-4748-4388-9489-b647df60332a', 'Engenheiro Especialista em Centrais Hidroelétricas', 'Os engenheiros especialistas em centrais hidroelétricas investigam, concebem e planificam a construção de instalações que produzem eletricidade a partir do movimento da água. Pesquisam localizações ótimas, realizam ensaios e experimentam diferentes materiais para obter o melhor resultado. Os engenheiros especialistas em centrais hidroelétricas desenvolvem estratégias para uma produção de energia mais eficiente e analisam as consequências ambientais.', 'released', '["Engenheiro Especialista em Centrais Hidroelétricas", "Engenheira Especialista em Centrais Hidroelétricas"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/e139b0a3-3bc5-4c33-bfbf-51ac20ac12fa', 'Radioterapeuta', 'Os radioterapeutas são responsáveis pela ministração exata dos tratamentos de radioterapia a doentes oncológicos e, no âmbito da equipe multidisciplinar, por alguns aspetos da preparação dos tratamentos e cuidados aos doentes. Tal inclui a administração segura e exata da dose de radiação prescrita, e os cuidados clínicos e apoio ao doente durante as fases de preparação do tratamento, da administração do tratamento e do pós-tratamento imediato.;', 'released', '["Radiologista Terapêutico", "RTT", "Tecnologista de Radioterapia", "Radiologista de Terapia", "Terapeuta Radiológica", "Tecnologista em Radioterapia", "Terapeuta Radiológico", "Praticante de Radiografia Terapêutica"]'::jsonb, '3211'),
  ('http://data.europa.eu/esco/occupation/e1416610-ad08-4f37-8b46-9f99632a5c0f', 'Marceneiro', 'Os marceneiros fabricam armários ou outros artigos de mobiliário através do corte, moldagem e montagem de peças de madeira. Utilizam diferentes tipos de ferramentas manuais e elétricas, tais como tornos, plainas e serras.', 'released', '["Carpinteiro", "Marceneira", "Marceneiro", "Carpinteira"]'::jsonb, '7522'),
  ('http://data.europa.eu/esco/occupation/e14548c8-c2b9-4ef8-8670-d5967d7ad804', 'Urbanista de Cidade', 'Os urbanistas de cidade criam planos de desenvolvimento para as cidades, as zonas urbanas, as cidades e as regiões. Investigam as necessidades da comunidade ou da região (econômicas, sociais, de transporte) e avaliam outros parâmetros, como a sustentabilidade, a fim de apresentar programas sólidos destinados a melhorar o sítio.', 'released', '["Planejador de Cidade Inteligente"]'::jsonb, '2164'),
  ('http://data.europa.eu/esco/occupation/e148e1ed-4f46-40a7-95c9-d6914f664f17', 'Fabricante de Velas', 'Os fabricantes de velas moldam as velas, colocam o pavio no meio do molde e enchem-no com cera, manualmente ou por máquina. Retiram a vela do molde, raspam o excesso de cera e inspecionam a vela para eliminar defeitos.', 'released', '["Fabricantea de Velas"]'::jsonb, '7319'),
  ('http://data.europa.eu/esco/occupation/e1587bbb-2d4e-4726-839a-7f4895c440e7', 'Diretor de Instituição de Ensino', 'Os diretores de instituição de ensino gerem as atividades quotidianas de um estabelecimento de ensino. Tomam decisões sobre as admissões e são responsáveis pelo cumprimento das normas curriculares, que facilitam o desenvolvimento académico dos alunos. Gerem o pessoal, trabalham em estreita colaboração com os diferentes departamentos e avaliam os professores em tempo útil, a fim de garantir um desempenho ótimo das turmas. Além disso, asseguram que a escola cumpre os requisitos nacionais em matéria de educação previstos na lei e cooperam com as comunidades locais e os governos.', 'released', '["Diretora de Instituição de Ensino", "Diretor de Instituição de Ensino"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/e16c2422-1323-4d8a-bd0f-c7584de70be1', 'Especialista em Estratégias de Preços', 'Os especialistas em estratégias de preços analisam os preços de produção, as tendências do mercado e os concorrentes, a fim de definirem o preço certo, tendo em conta os conceitos de marca e de marketing.', 'released', NULL, '2431'),
  ('http://data.europa.eu/esco/occupation/e16e4cb0-6f7d-4bf9-8f90-d1d866ad229b', 'Empregado de Lavandaria Self-Service', 'Os empregados de lavandaria self-service auxiliam os clientes das lavandarias self-service com questões relacionadas com máquinas, secadores ou máquinas de venda automática que funcionam com moedas. Mantêm a limpeza geral da roupa.', 'released', '["Empregado de Lavandaria Self-Service", "Empregada de Lavandaria Self-Service", "Encarregado de Lavandaria Self-Service", "Encarregada de Lavandaria Self-Service"]'::jsonb, '9629'),
  ('http://data.europa.eu/esco/occupation/e19a0f13-da49-42cb-8b3a-27da8ce44c8c', 'Operador de Máquinas de Moldagem de Vidro', 'Os operadores de máquinas de moldagem de vidro procedem à operação e manutenção de máquinas que pressionam ou sopram vidro fundido em moldes para formar ou moldar produtos, tais como néons, garrafas, frascos e copos. Instalam e ajustam máquinas e pesam, medem e verificam amostras de produção para verificar a conformidade com as especificações definidas.', 'released', '["Operadora de Máquinas de Moldagem de Vidro", "Operador de Máquinas de Moldagem de Vidro"]'::jsonb, '8181'),
  ('http://data.europa.eu/esco/occupation/e19fe26f-0759-4bb1-af71-5bbecf3df69f', 'Consultor em Questões de Imigração', 'Os consultores em questões de imigração auxiliam as pessoas que procuram deslocar-se de uma nação para outra, aconselhando-as sobre a legislação em matéria de imigração, ajudando-os a obter a documentação necessária para assegurar o processo de imigração em conformidade com a legislação em matéria de imigração.', 'released', '["Consultor em Questões de Imigração", "Consultora em Questões de Imigração"]'::jsonb, '3354'),
  ('http://data.europa.eu/esco/occupation/e1c72b5f-4c5c-487c-a6df-e84b64a51dae', 'Arquiteto de Sistemas Informáticos', 'Os arquitetos de sistemas informáticos concebem a arquitetura, os componentes, os módulos, as interfaces e os dados de um sistema com múltiplos componentes, tendo em vista a satisfação dos requisitos especificados.', 'released', '["Arquiteto de Sistemas Informáticos", "Arquiteto de Sistemas de Tecnologia da Informação", "Arquiteta de Sistemas de Tecnologia da Informação", "Arquiteto de Sistemas de Tecnologias de Informação e Comunicação", "Arquiteta de Sistemas", "Arquiteta de Sistemas de Tecnologias de Informação e Comunicação", "Arquiteto de Sistemas", "Arquiteta de Sistemas Informáticos"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/e1c9b304-2784-48e7-b7e8-089867743bbf', 'Gerente de Confeitaria', 'Os gerentes de pastelaria assumem a responsabilidade pelas atividades e pelo pessoal das lojas especializadas em produtos de confeitaria, por exemplo produtos de pastelaria, rebuçados e chocolate.', 'released', '["Gerente de Cafetaria", "Gerente de Chocolataria", "Gerente de Confeitaria", "Gerentea de Confeitaria"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/e1cf6897-158d-4b48-a39e-2a3a8cac216c', 'Assistente de Cozinha', 'Os assistentes de cozinha auxiliam na preparação de alimentos e na limpeza da área de cozinha.', 'released', '["Estagiária de Cozinha", "Assistente de Catering", "Estagiário de Cozinha", "Assistentea de Cozinha"]'::jsonb, '9412'),
  ('http://data.europa.eu/esco/occupation/e1fdca51-a0e1-4bea-822f-82a090ece780', 'Consultor Pecuário', 'Os consultores pecuários prestam aconselhamento especializado complexo aos agricultores e aos criadores de gado, a fim de garantir a otimização da sua atividade e produção.', 'released', '["Técnico de Produção Animal", "Consultora Pecuária", "Consultor de Agricultura", "Consultor Pecuário", "Consultor de Produção Agrícola", "Consultora de Agricultura", "Consultora de Produção Animal", "Consultor de Produção Animal", "Assessor Agropecuário", "Técnica de Produção Animal", "Assessora Agropecuária", "Consultora de Produção Agrícola", "Consultora Pecuário"]'::jsonb, '2132'),
  ('http://data.europa.eu/esco/occupation/e1fdd92c-46bd-45a0-8672-7f500c950cb0', 'Especialista em Import-Export de Produtos Têxteis, Têxteis Semiacabados e Matérias-Primas Têxteis', 'Os especialistas em import-export de produtos têxteis, têxteis semiacabados e matérias-primas têxteis possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Produtos Têxteis, Têxteis Semi-Acabados e Matérias-Primas Têxteis"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/e20816a9-51d0-410b-b2c6-cbc22c1c4256', 'Barman', 'Os barmen realizam a mistura de especialistas em cocktails alcoólicos e não alcoólicos.', 'released', '["Empregada de Serviço de Bebidas", "Barman", "Barmaid", "Empregado de Serviço de Bebidas"]'::jsonb, '5132'),
  ('http://data.europa.eu/esco/occupation/e20eee17-4876-4f21-a0cb-5d7f40c63cd8', 'Gestor de Ativos', 'Os gestores de ativos investem o dinheiro de um cliente em ativos financeiros, através de veículos como os fundos de investimento ou a gestão de carteiras de clientes individuais. Tal inclui a gestão de ativos financeiros, no âmbito de uma política de investimento e de um quadro de risco específicos, a prestação de informações, a avaliação e o controlo dos riscos.', 'released', '["Gestor de Ativos", "Gestora de Ativos", "Gerente"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/e246eca2-2cec-45b4-ae76-aa1f37d07bc5', 'Presidente de Região de Turismo', 'Os presidentes de região de turismo desenvolvem e implementam políticas destinadas a melhorar o turismo na sua região. Desenvolvem planos de comercialização para promover a região em regiões estrangeiras e acompanham o funcionamento do setor do turismo. Realizam investigação para investigar de que forma as políticas de turismo podem ser melhoradas e implementadas e investigam os benefícios do setor do turismo para o governo.', 'released', '["Diretora de Atração Turística", "Secretário de Estado do Turismo", "Secretária de Estado do Turismo", "Diretor de Atração Turística", "Presidentea de Região de Turismo"]'::jsonb, '1213'),
  ('http://data.europa.eu/esco/occupation/e297ec12-4712-40a4-ad98-ba004cacb205', 'Diretor de Dados', 'Os diretores de dados gerem funções de administração de dados e de prospeção de dados em toda a empresa. Asseguram que os dados são utilizados como ativos estratégicos a nível executivo e implementam e apoiam uma infraestrutura de gestão da informação mais colaborativa e alinhada em benefício da organização em geral.', 'released', '["Diretor de Dados", "Diretora de Dados", "Principal Responsável Pelos Dados"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/e2a495fb-68a3-46f9-8753-6ce566a7a085', 'Engenheiro Farmacêutico', 'Os engenheiros farmacêuticos concebem e desenvolvem tecnologias utilizadas na investigação farmacêutica e no fabrico de fármacos, aconselhando as fábricas de produtos farmacêuticos a manter e explorar essas tecnologias e garantindo o cumprimento dos requisitos de segurança dos clientes e dos trabalhadores. Podem também participar na concepção e desenho de fábricas de produtos farmacêuticos e de centros de investigação.', 'released', '["Engenheira Farmacêutica", "Engenheiro Farmacêutico", "Engenheira Farmacêutico"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/e2ad6d3e-1736-466b-a2bf-9823f683c8ab', 'Editor', 'Os editores são responsáveis pela seleção de novos materiais. Decidem quais os manuscritos fornecidos pela editora que serão publicados. Os editores supervisionam a produção, a comercialização e a distribuição desses textos.', 'released', '["Diretora de Casa Editora", "Diretor de Casa Editora", "Editora", "Editor"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/e2c38c87-2bcf-492a-a78e-3be9480481cc', 'Supervisor de Montagem de Veículos a Motor', 'Os supervisores de montagem de veículos a motor coordenam os trabalhadores envolvidos no fabrico de veículos a motor e programam as suas atividades. Elaboram relatórios de produção e recomendam medidas para reduzir os custos e aumentar a produtividade, como a contratação, a encomenda de novos equipamentos e a implementação de novos métodos de produção. Formam os trabalhadores nas políticas da empresa, no exercício das funções e nas medidas de segurança. Supervisionam as existências e comunicam com outros departamentos, tendo em vista evitar interrupções desnecessárias do processo de produção.', 'released', '["Supervisora de Montagem de Veículos a Motor", "Supervisor de Montagem de Veículos a Motor"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/e2e3ecfa-a77b-49df-857e-09dee26e4198', 'Montador de Bicicletas', 'Os montadores de bicicletas constroem, afinam e garantem o bom funcionamento de todos os tipos de bicicletas, tais como bicicletas de montanha, bicicletas de estrada, bicicletas para crianças, etc. Também montam produtos acessórios, tais como carrinhos e reboques.', 'released', '["Montador de Bicicletas", "Fabricante de Bicicletas", "Montadora de Bicicletas"]'::jsonb, '8219'),
  ('http://data.europa.eu/esco/occupation/e31c83ac-cb74-4936-88f1-90ed0997b29b', 'Monitor-Animador de Parque de Diversões', 'Os monitores-animadores de parque de diversões desempenham uma série de funções relacionadas com a instalação de diversão ou recreio. Podem programar a utilização de instalações de diversão, proceder à manutenção de e fornecer equipamento aos participantes em eventos desportivos ou atividades recreativas ou operam as concessões de diversões e os carrosséis.', 'released', '["Monitor-Animador de Parque de Diversões", "Monitora-Animadora de Parque de Diversões", "Monitor-Animadora de Parque de Diversões"]'::jsonb, '9629'),
  ('http://data.europa.eu/esco/occupation/e3229e40-f571-4b26-baca-29edc8fe313e', 'Investigador em Tecnologia da Informação', 'Os investigadores em tecnologia da informação realizam investigações no domínio da informática e ciência da informação, tendo em vista a obtenção de um maior conhecimento e compreensão dos aspectos fundamentais dos fenômenos da tecnologia da informação. Redigem relatórios e propostas de investigação. Além disso, os investigadores em tecnologia da informação inventam e concebem novas abordagens em matéria de tecnologia informática, descobrem aplicações inovadoras para a tecnologia e os estudos existentes e resolvem problemas complexos no domínio da informática.', 'released', '["Investigadora em Informática", "Investigadora em Tecnologia da Informação", "Investigadora Informática", "Investigadora em Tecnologias de Informação e Comunicação", "Investigador Informático", "Investigador em Tecnologias de Informação e Comunicação", "Investigador em Informática", "Investigador em Tecnologia da Informação", "TI"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/e34b93ec-5e11-4858-ba1e-e245c4c39cec', 'Supervisor de Montagem de Produtos de Madeira', 'Os supervisores de montagem de produtos de madeira acompanham os vários processos de montagem de produtos de madeira. Têm um profundo conhecimento dos processos de produção sob a sua supervisão e tomam decisões rápidas quando necessário.', 'released', '["Supervisora de Montagem de Produtos de Madeira", "Supervisor de Montagem de Produtos de Madeira"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/e3713dd7-572d-4c6c-87ec-1944b3572175', 'Operador de Máquina de Fermentação de Cidra', 'Os operadores de máquina de fermentação de cidra controlam o processo de fermentação de mosto inoculado com levedura.', 'released', '["Operadora de Fermentação de Cidra", "Operador de Máquina de Fermentação de Cidra", "Operadora de Máquina de Fermentação de Cidra", "Operador de Fermentação de Cidra"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/e3b08984-19fe-4d51-a1b0-990676fc7234', 'Arquivista', 'Os arquivistas avaliam, recolhem, organizam, preservam e facultam o acesso a registos e arquivos. Os registos mantidos incluem todos os formatos, analógicos ou digitais, e incluem vários tipos de suportes (documentos, fotografias, vídeos e gravações de som, etc.).', 'released', NULL, '2621'),
  ('http://data.europa.eu/esco/occupation/e3cc09ba-7ad5-4411-940c-20613000863a', 'Conservacionista', 'Os conservacionistas gerem a qualidade de florestas, parques e outros recursos naturais específicos. Protegem o habitat da fauna, a biodiversidade, o valor paisagístico e outros atributos únicos de terras preservadas e conservadas. Os conservacionistas realizam trabalho de campo.', 'released', NULL, '2133'),
  ('http://data.europa.eu/esco/occupation/e3dc66de-99c7-4607-a82b-7244036d316d', 'Operador de Produção Alimentar', 'Os operadores de produção alimentar fornecem e executam uma ou mais tarefas em diferentes fases do processo de produção alimentar. Realizam operações e processos de fabrico de alimentos e bebidas, realizam a embalagem, operam máquinas manual ou automaticamente, cumprem procedimentos predeterminados e aplicam as regras de segurança alimentar.', 'released', '["Técnico de Produção Alimentar", "Técnica de Produção Alimentar", "Operador de Produção Alimentar", "Operadora de Produção Alimentar"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/e3df1f82-3df9-41e5-8487-635e184653d1', 'Oficial de Convés', 'Os oficiais de convés ou imediatos desempenham funções de vigilância a bordo dos navios, como a determinação do curso e da velocidade, as manobras para evitar riscos e a monitorização contínua da posição do navio através do recurso a cartas e de ajudas à navegação. Mantêm diários de bordo e outros registos que acompanham os movimentos do navio. Asseguram o seguimento dos procedimentos e das práticas de segurança adequados, verificam se o equipamento está em bom estado de funcionamento e supervisionam a carga e a descarga de mercadorias ou de passageiros. Supervisionam os membros da tripulação responsáveis pelas operações de manutenção e de conservação primária do navio.', 'released', NULL, '3152'),
  ('http://data.europa.eu/esco/occupation/e40e4a07-4246-4c6f-a51c-89d35b6fe75e', 'Corretor de Resíduos', 'Os corretores de resíduos atuam na qualidade de mediador entre os clientes e as indústrias de gestão de resíduos. Asseguram que os resíduos são recolhidos nas instalações do cliente por um profissional especializado e transportados para uma unidade de gestão de resíduos, onde são objeto de tratamento.', 'released', '["Corretor de Resíduos", "Corretora de Resíduos"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/e4112a88-973f-4c7a-97f5-2241e6b6833f', 'Técnico de Inserção Profissional', 'Os técnicos de inserção profissional prestam assistência a pessoas desempregadas na procura de emprego ou de oportunidades de formação profissional, em função das suas qualificações e da experiência educativa ou profissional. Prestam aconselhamento sobre a forma de promoverem as suas competências no processo de procura de emprego. Os técnicos de inserção profissional ajudam os candidatos a emprego a redigirem CV e cartas de apresentação e a prepararem-se para uma entrevista de emprego e indicam-lhes onde procurar novas oportunidades de emprego ou de formação.', 'released', '["Técnico de Inserção Profissional", "Técnica de Inserção Profissional"]'::jsonb, '2423'),
  ('http://data.europa.eu/esco/occupation/e43d0f86-7abf-4c6e-b2b3-10970ddf6518', 'Colocador de Carpetes', 'Os colocadores de alcatifas instalam alcatifa como revestimento de pavimentos. Cortam as alcatifas à medida, preparam a superfície e colocam as alcatifas no sítio.', 'released', '["Colocadora de Carpetes", "Colocador de Alcatifas", "Colocador de Revestimentos", "Colocador de Carpetes", "Colocadora de Revestimentos", "Colocadora de Alcatifas"]'::jsonb, '7122'),
  ('http://data.europa.eu/esco/occupation/e44b2459-af5e-492d-9c57-d9c2e62944e7', 'Capitão de Esquadra', 'Os capitães de esquadra comandam uma esquadra especializada em diferentes operações, tais como esquadras aéreas, esquadras de operações em terra ou esquadras de veículos de combate blindados.', 'released', '["Comandante de Esquadrão", "Comandante de Bateria", "Comandante de Companhia", "Major", "Capitãa de Esquadra"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/e44d2570-10cc-4984-9692-63ece1b6dce8', 'Polidor de Joias', 'Os polidores de joias asseguram que as peças de joalharia acabadas são limpas a pedido do cliente ou preparadas para venda. Também podem efetuar pequenas reparações. Utilizam ferramentas manuais, tais como limas e varetas com papel abrasivo e/ou máquinas de polir portáteis. Também utilizam máquinas de polimento mecanizado, tais como os tornos rotativos.', 'released', '["Polidor de Joias", "Polidora de Joias", "Ourives"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/e4ad2547-9188-4fbd-897a-c91b3c097779', 'Decano de Faculdade', 'Os decanos de faculdade dirigem e gerem um conjunto de departamentos académicos conexos e trabalham com o diretor do estabelecimento de ensino pós-secundário e com os diferentes chefes de serviço para atingir os objetivos estratégicos da faculdade e da universidade acordados. Promovem a faculdade nas comunidades associadas e a nível nacional e internacional. Além disso, os decanos de faculdade centram-se na realização das metas de gestão financeira da faculdade.', 'released', '["Reitor de Faculdade", "Decana de Faculdade", "Vice-Reitor de Universidade", "Reitora de Faculdade", "Decano de Faculdade", "Vice-Reitora de Universidade"]'::jsonb, '1345'),
  ('http://data.europa.eu/esco/occupation/e4c915ff-6c9c-4fa9-a8fb-09d0c67e30d4', 'Major do Exército', 'Os majores do Exército comandam grandes unidades de oficiais e de soldados, e supervisionam a sua formação e bem-estar. Supervisionam também a sua administração e a gestão do equipamento.', 'released', '["Major", "Comandante de Batalhão", "Comandante", "Major das Forças Armadas", "Majora do Exército"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/e4cdfa86-c3b1-41f1-a4e2-384c73d03bd3', 'Operador no Mercado de Commodities', 'Os operadores no mercado de «commodities» (mercadorias) utilizam técnicas de negociação para vender e comprar bens físicos e matérias-primas como ouro, gado bovino, petróleo, algodão e trigo, na sala de mercados. Recebem e implementam instruções de compra e venda e negoceiam as condições de venda e entrega das mercadorias. Os operadores no mercado de mercadorias investigam as condições de mercado de mercadorias específicas, as suas tendências de preços e a procura, a fim de informarem os seus empregadores, apresentam propostas de licitação e calculam o custo das transações.', 'released', '["Trader de Commodities", "Operador no Mercado de Commodities", "Operadora no Mercado de Mercadorias", "Operador no Mercado de Mercadorias", "Operadora no Mercado de Commodities"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/e4f33b45-ee95-48b5-b2f8-e397aa14ed41', 'Operador de Centro de Distribuição', 'Os operadores de centro de distribuição asseguram a expedição eficaz de produtos manufaturados. Definem os itinerários e ultimam os documentos de expedição.', 'released', '["Funcionário de Centro de Distribuição", "Operador de Centro de Distribuição", "Funcionária de Centro de Distribuição", "Operadora de Centro de Distribuição"]'::jsonb, '9333'),
  ('http://data.europa.eu/esco/occupation/e4fca489-4c79-4392-874f-9ea1051c05c8', 'Figurante', 'Os figurantes realizam ações em segundo plano ou em multidões durante a filmagem. Não contribuem diretamente para a ação, mas são importantes para a criação de uma determinada atmosfera.', 'released', '["Figurantea"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/e5257110-e7f1-453a-a2dc-bd374945bc4a', 'Diretor de Produção no Setor da Marroquinaria', 'Os diretores de produção no setor da marroquinaria desempenham uma vasta gama de atividades e tarefas no domínio da gestão, nomeadamente planificam, distribuem e coordenam todas as atividades necessárias das diferentes fases de fabrico de produtos de couro, dentro do cumprimento das normas de qualidade e dos objetivos predefinidos de produção e produtividade.', 'released', '["Diretora de Investigação e Desenvolvimento no Setor da Marroquinaria", "Diretor de Produção no Setor da Marroquinaria", "Diretora de Produção no Setor da Marroquinaria", "Diretor de Investigação e Desenvolvimento no Setor da Marroquinaria"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/e52b5707-7097-4dbc-ac61-054e917da241', 'Médico Estomatologista', 'Os médicos estomatologistas previnem, diagnosticam e tratam anomalias e doenças dos dentes, da boca, dos maxilares e dos tecidos adjacentes.', 'released', '["Estomatologista", "Médico Estomatologista", "Médica Estomatologista"]'::jsonb, '2261'),
  ('http://data.europa.eu/esco/occupation/e53e1bd8-7316-4fab-9338-c6a66f50e5b7', 'Técnico de Operações de Voo', 'Os técnicos de operações de voo compilam informações de voo para agilizar a circulação de aeronaves entre aeroportos e em aeroportos. Compilam os dados referentes à expedição de aeronaves, como as horas previstas de chegada e de partida nos postos de controlo e as paragens previstas, a quantidade de combustível necessário para o voo e o peso bruto máximo admissível à descolagem e à aterragem.', 'released', '["Técnica de Operações de Voo", "Técnico de Operações de Voo"]'::jsonb, '3154'),
  ('http://data.europa.eu/esco/occupation/e54683ca-1fc9-468d-b880-6544ff6b7d0b', 'Trabalhador de Recolha do Lixo', 'Os trabalhadores de recolha do lixo retiram resíduos de casas e de outras instalações e colocam-nos no caminhão do lixo, para transportá-los para uma instalação de tratamento e eliminação. Auxiliam o condutor do caminhão do lixo, ajudam a descarregar os resíduos e registam a quantidade de resíduos recolhidos. Também podem recolher resíduos de estaleiros de construção e demolição, bem como resíduos perigosos.', 'released', '["Varredora do Lixo", "Varredor do Lixo", "Trabalhadora de Recolha do Lixo", "Trabalhador de Recolha do Lixo"]'::jsonb, '9611'),
  ('http://data.europa.eu/esco/occupation/e55e1a62-eab4-4829-a71e-e0d294cacf6b', 'Letrista', 'Os letristas interpretam o estilo de uma peça musical e redigem as letras para acompanhar a melodia. Trabalham em conjunto com o compositor.', 'released', NULL, '2641'),
  ('http://data.europa.eu/esco/occupation/e575efca-c3e4-43fe-8c46-327d310f795e', 'Supervisor de Construções Subaquáticas', 'Os supervisores de construções subaquáticas acompanham projetos de construção subaquática, como túneis, eclusas e pilares de pontes. Orientam e dão instruções a mergulhadores comerciais do setor da construção e asseguram que cumprem a regulamentação em matéria de segurança.', 'released', '["Supervisor de Construções Subaquáticas", "Supervisora de Construções Subaquáticas"]'::jsonb, '3123'),
  ('http://data.europa.eu/esco/occupation/e58eadca-e512-4167-96f1-fff980f117e3', 'Técnico de Ensaios de Motores de Navios', 'Os técnicos de ensaios de motores de navios testam o desempenho dos motores de navios, como os motores elétricos, os reatores nucleares, os motores de turbinas a gás, os motores fora de borda, os motores diesel a dois ou a quatro tempos, os motores a GNL, os motores de duplo combustível e, em alguns casos, os motores marítimos a vapor, em instalações especializadas, como os laboratórios. Posicionam ou fornecem orientações aos trabalhadores para o posicionamento dos motores no banco de ensaios. Utilizam ferramentas manuais e máquinas para posicionar e ligar o motor ao banco de ensaios. Utilizam equipamento informatizado para introduzir, ler e registar dados de ensaios, como a temperatura, a velocidade, o consumo de combustível e a pressão do óleo e dos gases de escape.', 'released', '["Técnica de Ensaios de Motores de Navios", "Técnico de Ensaios de Motores de Navios"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/e5a63940-57d3-4065-8713-74b4e2c93063', 'Gestor de Produtos e Serviços', 'Os gestores de produtos e serviços estão encarregados de definir o conteúdo e a estrutura de um catálogo ou de uma carteira numa empresa.', 'released', '["Gestor de Produtos e Serviços", "Gestora de Produtos e Serviços", "Gerente"]'::jsonb, '2431'),
  ('http://data.europa.eu/esco/occupation/e5e3ea36-4ed9-4c57-987c-9974385551a8', 'Trabalhador Agrícola do Setor Vinícola', 'Os trabalhadores agrícolas do setor vinícola realizam atividades manuais relacionadas com o cultivo, a propagação de variedades de uvas e a produção e/ou a embalagem de vinhos.', 'released', '["Trabalhador Agrícola do Setor Vinícola", "Trabalhadora Agrícola do Setor Vinícola"]'::jsonb, '9211'),
  ('http://data.europa.eu/esco/occupation/e6023abf-ced3-4ac9-9437-cc79e4396e3e', 'Terapeuta Especialista em Terapia Assistida por Animais', 'Os terapeutas especialistas em terapia assistida por animais prestam apoio a indivíduos com deficiências cognitivas, motoras ou sociais-emocionais através da intervenção assistida por animais. Envolvem animais de companhia e animais domésticos num plano de intervenção específico, como a terapia, a educação e o serviço humano, e visam restaurar e manter o bem-estar e a recuperação dos doentes.', 'released', NULL, '2269'),
  ('http://data.europa.eu/esco/occupation/e614861b-4685-4699-a12d-965cdd65ec64', 'Operador de Manutenção de Máquinas de Acabamento de Calçado', 'Os operadores de manutenção de máquinas de acabamento de calçado são os profissionais que instalam, programam e afinam diferentes tipos de equipamento de corte, costura, montagem e acabamento de calçado utilizado na produção de calçado. Realizam uma manutenção preventiva e corretiva e verificam periodicamente as condições de trabalho e o desempenho. Analisam os defeitos, corrigem os problemas, reparam e substituem os componentes ou peças e fazem lubrificações de rotina, fornecendo informações sobre a sua utilização e consumo energético, sobretudo aos diretores da empresa.', 'released', '["Operadora de Manutenção de Máquinas de Acabamento de Calçado", "Operador de Manutenção de Máquinas de Acabamento de Calçado", "Técnico de Manutenção de Máquinas de Fabricação de Calçado", "Técnica de Manutenção de Máquinas de Fabricação de Calçado"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/e65a9b0e-7347-4f6e-945e-aaeee976ef6e', 'Mordomo', 'Os mordomos prestam serviços personalizados aos clientes dos hotéis de alto nível. Gerem o pessoal de serviço de quartos para assegurar a limpeza dos espaços interiores e um excelente serviço ao cliente. Os mordomos são responsáveis pelo bem-estar geral e pela satisfação dos convidados.', 'released', '["Governante em Geral", "Governanta em Geral", "Mordoma"]'::jsonb, '5151'),
  ('http://data.europa.eu/esco/occupation/e666c384-2a14-4cd9-981f-7067dc0bb9a9', 'Operador de Costura à Mão em Artigos de Marroquinaria', 'Os operadores de costura à mão em artigos de marroquinaria unem as peças cortadas de couro e outros materiais, utilizando ferramentas simples, tais como agulhas, alicates e tesouras, para terminar o produto. Também realizam pontos à mão para fins decorativos.', 'released', '["Operadora de Costura à Mão em Artigos de Marroquinaria", "Operador de Costura à Mão em Artigos de Marroquinaria"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/e6800524-eec2-4c33-af0e-6f36d1d679bc', 'Engenheiro de Instrumentação', 'Os engenheiros de instrumentação idealizam e concebem equipamentos utilizados em processos de fabrico para controlar e monitorizar vários processos de engenharia à distância. Concebem equipamentos de monitorização de centrais de produção, como sistemas de fabrico, utilizações de máquinas e processos de produção.', 'released', '["Engenheira de Instrumentação", "Engenheiro de Instrumentação"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/e69697d0-2639-4aad-b73a-05e0b98357b1', 'Engenheiro Especialista em Instalações Elétricas em Minas', 'Os engenheiros especialistas em instalações elétricas em minas supervisionam a aquisição, a instalação e a manutenção de equipamento elétrico mineiro, utilizando o seu conhecimento de princípios elétricos e eletrônicos. Organizam a substituição e a reparação de material e componentes elétricos.', 'released', '["Enhenheiro Especialista em Instalações Elétricas em Minas", "Engenheira Especialista em Instalações Elétricas em Minas"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/e6a3ce2e-c0f2-47a7-937a-61ae9abfe1fa', 'Técnico de Metrologia', 'Os técnicos de metrologia aplicam o seu conhecimento prático da metrologia para calibrar instrumentos de medição, testar equipamentos e analisar o seu desempenho. Asseguram que o equipamento avaliado cumpre os requisitos de precisão, desempenho e exatidão. Comunicam os resultados do seu trabalho e prestam aconselhamento sobre questões técnicas relacionadas com os instrumentos de medição.', 'released', '["Técnico de Metrologia", "Técnica de Metrologia"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/e6c298a4-62de-4b62-b48e-c5fdca8f6071', 'Representante de Vendas de Máquinas e Equipamento de Escritório', 'Os representantes de vendas de máquinas e equipamento de escritório prestam serviços em nome de uma empresa para vender as suas mercadorias, prestando simultaneamente informações técnicas aos clientes.', 'released', '["Sales", "Representantea de Vendas de Máquinas e Equipamento de Escritório"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/e6dfc67e-331e-4468-a249-347a08decbdb', 'Engenheiro de Materiais de Microeletrônica', 'Os engenheiros de materiais de microeletrónica concebem, desenvolvem e supervisionam a produção dos materiais necessários para a microeletrónica e os sistemas microeletromecânicos (MEMS), e são capazes de os aplicar nestes dispositivos, aparelhos e produtos. Contribuem para o design da microeletrónica com conhecimentos físicos e químicos sobre metais, semicondutores, cerâmica, polímeros e materiais compósitos. Realizam investigação sobre estruturas materiais, efetuam análises, estudam mecanismos de falha e supervisionam trabalhos de investigação.;', 'released', '["Engenheiro em Materiais Microeletrônicos", "Engenheiro de Projeto de Materiais Microeletrônicos", "Consultor de Engenharia de Materiais Microeletrônicos", "Engenheiro Especializado em Materiais Microeletrônicos", "Desenvolvedor de Materiais Microeletrônicos", "Engenheira de Desenvolvimento de Materiais Microeletrônicos", "Consultora de Engenharia de Tecnologia de Materiais Microeletrônicos", "Engenheiro Especialista em Materiais Microeletrônicos", "Designer de Materiais Microeletrônicos", "Engenheira Especializada em Materiais Microeletrônicos", "Especialista em Engenharia de Tecnologia de Materiais Microeletrônicos", "Engenheira Especialista em Materiais Microeletrônicos", "Engenheiro de Desenvolvimento de Materiais Microeletrônicos", "Engenheiro de Materiais Microeletrônicos", "Desenvolvedora de Materiais Microeletrônicos", "Engenheira de Projeto de Materiais Microeletrônicos", "Engenheira em Materiais Microeletrônicos", "Engenheiro de Tecnologia de Materiais Microeletrônicos", "Consultora de Engenharia de Materiais Microeletrônicos", "Engenheira de Materiais Microeletrônicos", "Especialista em Engenharia de Materiais Microeletrônicos", "Consultor de Engenharia de Tecnologia de Materiais Microeletrônicos", "Engenheira de Tecnologia de Materiais Microeletrônicos", "Engenheira de Materiais de Microeletrônica"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/e6eea1ed-e982-4583-bafe-a0ac796f6cf1', 'Operador de Classificação de Peles', 'Os operadores de classificação de peles inspecionam e classificam o couro durante e no final do processo de produção, de acordo com as características qualitativas, os destinos de utilização e os requisitos do cliente. Trabalham na fábrica de curtumes e nos armazéns, verificando a qualidade, a cor, o tamanho, a espessura, a suavidade e os defeitos naturais.', 'released', '["Operador de Classificação de Peles", "Operadora de Classificação de Peles"]'::jsonb, '7535'),
  ('http://data.europa.eu/esco/occupation/e7117cdc-ee3d-45b0-9680-6b3a60c7c9b3', 'Especialista em Import-Export de Metais e Minerais Metálicos', 'Os especialistas em import-export de metais e minerais metálicos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Metais e Minerais Metálicos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/e7417f4f-7072-4b07-a71f-71f6fc7f5e5b', 'Responsável Pelo Registro de Animais em Jardins Zoológicos', 'Os responsáveis pelo registo de animais em jardins zoológicos realizam a manutenção de uma grande variedade de registos em coleções zoológicas relativos aos animais e aos cuidados que lhes são prestados. Incluem registos históricos e atuais. Têm a responsabilidade de reunir os registos num sistema organizado e reconhecido de conservação de registos. Na maioria dos casos, isto implica também a apresentação periódica de relatórios aos sistemas de informação regionais ou internacionais de espécies e/ou no âmbito de programas de reprodução geridos, ou seja os responsáveis pelo registo de animais em jardins zoológicos estão geralmente encarregados da gestão interna e externa dos registos institucionais. Além disso, os responsáveis pelo registo de animais em jardins zoológicos coordenam frequentemente o transporte de animais para a coleção do zoológico.', 'released', NULL, '2621'),
  ('http://data.europa.eu/esco/occupation/e74513c3-8ba8-462f-978c-0450522f4427', 'Professor de Química', 'Os professores de Química são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Química, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Química, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora Universitária de Química", "Professor de Química", "Professora de Química", "Professor Universitário de Química"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/e75305db-9011-4ee0-ab62-8d41a98f807e', 'Motorista Privado', 'Os motoristas privados transportam os seus empregadores para um destino determinado de forma segura e atempada. Utilizam dispositivos de navegação para chegar ao destino no prazo mais curto possível, aconselham sobre as condições meteorológicas e de tráfego e cumprem as normas legais de condução.', 'released', '["Motorista Privada", "Motorista Privado"]'::jsonb, '8322'),
  ('http://data.europa.eu/esco/occupation/e763dfa6-924d-493b-892a-6435e0cffe70', 'Especialista em Import-Export de Eletrodomésticos', 'Os especialistas em import-export de eletrodomésticos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Eletrodomésticos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/e777fb61-16f5-476b-8262-578edfdb4d9d', 'Professor de Cursos Profissionais de Educação Física', 'Os professores de cursos profissionais de Educação Física formam os alunos no seu domínio de estudos especializado, a Educação Física, que é de natureza predominantemente prática. Prestam formação teórica ao serviço das competências práticas e técnicas que os alunos deverão posteriormente dominar numa profissão relacionada com a Educação Física, como organizador de atividades de saúde ou de atividades ao ar livre. Induzem os alunos nos quadros sociais adequados da sua área de estudo e ensinam as atitudes e os valores adequados. Os professores de cursos profissionais de Educação Física acompanham os progressos dos alunos, prestam assistência individual, quando necessário, e avaliam os seus conhecimentos e desempenho no domínio da Educação Física através de trabalhos, testes e exames.', 'released', '["Professora de Cursos Profissionais de Educação Física", "Instrutora de Educação Física", "Instrutor de Educação Física", "Professor de Cursos Profissionais de Educação Física"]'::jsonb, '2320'),
  ('http://data.europa.eu/esco/occupation/e7970c7a-7769-4002-87d3-0a8ea94fdd6f', 'Paisagista', 'Os paisagistas planeiam, constroem, renovam e procedem à manutenção de parques, jardins e espaços verdes públicos.', 'released', '["Jardineira Paisagista", "Horticultora Paisagista", "Horticultor Paisagista", "Jardineiro", "Jardineira", "Jardineiro Paisagista"]'::jsonb, '6113'),
  ('http://data.europa.eu/esco/occupation/e7ef8a86-6acd-458d-bf48-634b8fd28950', 'Misturador de Borracha Esponjosa', 'Os misturadores de borracha esponjosa asseguram o correto funcionamento da máquina que mistura partículas de borracha esponjosa com látex líquido. Pesam a quantidade certa de ingredientes e vertem as misturas em moldes para fabricar almofadas e colchões.', 'released', '["Misturadora de Espuma de Borracha", "Misturador de Borracha Esponjosa", "Misturadora de Borracha Esponjosa"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/e7f6e98a-cef5-41be-b65c-70cf1feed11d', 'Gerente de Horto', 'Os gerentes de horto assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Jardinaria", "Gerente de Centro de Jardinagem", "Gerente de Viveiro", "Gerente de Florista", "Gerentea de Horto"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/e80cee57-3672-4aaf-8ca7-53b90771c364', 'Operador de Máquinas de Revestimento de Correias Trapezoidais', 'Os operadores de máquinas de revestimento de correias trapezoidais operam máquinas que cobrem as correias com tecido com borracha. Cortam o tecido após uma rotação da correia.', 'released', '["Operadora de Máquinas de Revestimento de Correias Trapezoidais", "Operador de Máquinas de Revestimento de Correias Trapezoidais"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/e81269d8-f301-4c82-9235-ba33ec9b0434', 'Osteopata Veterinário', 'Os osteopatas animais fornecem um tratamento terapêutico na sequência de um diagnóstico ou de uma sinalização veterinária. Concentram-se na aplicação de técnicas de tratamento que utilizam a manipulação dos tecidos do corpo para resolver deformações e lesões nos animais, em conformidade com a legislação nacional.', 'released', '["Osteopata Veterinário", "Osteopata de Veterinária", "Osteopata Veterinária", "Osteopata de Animais", "Osteopata Animal"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/e83bf81f-c1d0-48e1-8533-7d65be8007c5', 'Diretor de Distribuição Açúcar, Chocolate e Produtos de Confeitaria', 'Os diretores de distribuição açúcar, chocolate e produtos de confeitaria planificam a distribuição de açúcar, chocolate e produtos de confeitaria a vários pontos de vendas.', 'released', '["Diretor de Logística Açúcar, Chocalate e Produtos de Confeitaria", "Diretor de Distribuição Açúcar, Chocalate e Produtos de Confeitaria", "Diretora de Logística Açúcar, Chocalate e Produtos de Confeitaria", "Diretora de Distribuição Açúcar, Chocalate e Produtos de Confeitaria", "Diretora de Distribuição Açúcar, Chocolate e Produtos de Confeitaria"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/e8461d2e-3d75-477c-93a2-ea8d342bb55b', 'Técnico Ambiental', 'Os técnicos ambientais investigam fontes de poluição e prestam auxílio no desenvolvimento de planos de prevenção da poluição e de proteção do ambiente. Recolhem amostras do solo, da água ou de outros materiais e realizam testes para analisar o nível de poluição e identificar a sua origem.', 'released', '["Técnica Ambiental", "Técnico Ambiental"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/e859428d-6dbd-406b-bb2e-d5a0ae21df29', 'Eletricista de Eventos', 'Os eletricistas de eventos instalam e desmantelam de sistemas elétricos temporários e fiáveis de apoio a eventos. Trabalham em locais sem acesso à rede elétrica, bem como em locais com acesso a energia temporária. O seu trabalho baseia-se em instruções, planos e cálculos. Trabalham no interior e no exterior. Cooperam estreitamente com a equipe técnica e os operadores.', 'released', NULL, '7411'),
  ('http://data.europa.eu/esco/occupation/e89e330c-daa3-48f0-b34e-04e3344ea8dc', 'Ator para Dobragem', 'Os atores para dobragem emprestam a sua voz a personagens de programas de animação televisivos ou cinematográficos. Criam empatia com os seus personagens e dão-lhes vida com a sua voz.', 'released', '["Ator Voice-Over", "Atora para Dobragem", "Atora de Dobragem", "Ator para Dobragem", "Atora Voice-Over", "Ator de Dobragem"]'::jsonb, '2655'),
  ('http://data.europa.eu/esco/occupation/e8b93ce7-e39b-4261-a25a-9b84764eb724', 'Professor de Filosofia do Ensino Secundário', 'Os professores de Filosofia do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Filosofia. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Filosofia através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Filosofia do Ensino Secundário", "Professora de Filosofia do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/e8bbc7fd-cfa2-406f-a664-57e5024cfbc5', 'Gestor de Relações com os Fornecedores de Tecnologia da Informação', 'Os gestores de relações com os fornecedores de TIC estabelecem e mantêm relações comerciais positivas entre as partes interessadas (externas ou internas), através da implantação de atividades conformes com os processos organizacionais. Gerem igualmente o processo de externalização em nome do departamento de TIC da organização e as comunicações da cadeia de abastecimento.', 'released', '["Gestor de Relações com os Fornecedores de Produtos Informáticos", "Gestor de Relações com os Fornecedores de TI", "Gestor de Relações com Fornecedores de Produtos Informáticos", "Gestora de Relações com Fornecedores de Produtos Informáticos", "Gestora de Relações com os Fornecedores de Tecnologias de Informação e Comunicação", "Gestora de Relações com os Fornecedores de TI", "Gestor de Relações com os Fornecedores de Tecnologias de Informação e Comunicação", "Gestor de Relações com Fornecedores de Tecnologias de Informação e Comunicação", "Gestora de Relações com Fornecedores de Tecnologias de Informação e Comunicação", "Gestora de Relações com os Fornecedores de Produtos Informáticos", "TI", "Gerente", "Gestora de Relações com os Fornecedores de Tecnologia da Informação"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/e8fca903-6590-48a8-8902-094bb41ee90c', 'Especialista em Condução Autônoma', 'Os especialistas em condução autónoma concebem e supervisionam o funcionamento de um veículo autónomo. Recolhem dados sobre o desempenho dos sistemas, efetuam ensaios dos veículos e analisam os dados desses ensaios. Os especialistas em condução autónoma conhecem as diferentes tecnologias utilizadas nos automóveis autónomos, nos sistemas e nas tecnologias automóveis.;', 'released', '["Especialista em Veículos Conectados", "Engenheira de Direção Altamente Automatizado", "Engenheiro de Direção Autônomo", "Engenheira de Automóveis Autônomo", "Especialista em Carros Conectados", "Engenheiro de Teste e Validação ADAS", "Engenheira de Teste e Validação ADAS", "Engenheira AV", "Engenheira de Veículos Autônomo", "Especialista em Veículos Autônomos", "Engenheiro de Teste e Validação ADF", "Engenheiro de Direção Altamente Automatizado", "Engenheiro de Veículos Autônomo", "Engenheira de Direção Autônomo", "Especialista C-V2X", "Engenheiro AV", "Especialista em Carro Autônomo", "Engenheira de Teste e Validação ADF", "Engenheiro de Automóveis Autônomo"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/e91bc34c-0c4f-4ac9-8e2f-8f337d75f9ca', 'Averiguador de Prejuízos', 'Os averiguadores de prejuízos tratam e avaliam pedidos de indemnização de seguros através da investigação dos processos e da determinação da responsabilidade e dos danos, em conformidade com as políticas da companhia de seguros. Entrevistam o requerente e as testemunhas e redigem relatórios para a seguradora, onde são feitas recomendações apropriadas relativas à liquidação do pedido. As tarefas dos averiguadores de prejuízos incluem a realização de pagamentos ao segurado na sequência do seu pedido, a consulta de peritos em matéria de danos e a prestação de informações por telefone aos clientes.', 'released', '["Averiguador de Prejuízos", "Averiguadora de Prejuízos"]'::jsonb, '3315'),
  ('http://data.europa.eu/esco/occupation/e937449a-d9e0-4ab7-9ea5-4d3ac673be6d', 'Analista de Subscrição de Seguros', 'Os analistas de subscrição de seguros avaliam os riscos de um negócio e as apólices de seguros de responsabilidade civil e tomam decisões sobre o imóvel comercial. Inspecionam as condições das instalações das empresas, analisam as políticas de inspeção, prestam apoio em questões imobiliárias e de arrendamento, elaboram contratos de empréstimo e tratam dos riscos comerciais, a fim de os ajustar às práticas comerciais. Os analistas de subscrição de seguros analisam informações diversas de potenciais clientes, a fim de avaliarem a probabilidade de apresentarem um pedido de indemnização. Trabalham no sentido de minimizar os riscos para a companhia de seguros e de garantir que o prémio de seguro é consentâneo com os riscos associados. Podem ser especialistas em seguros de vida, seguros de saúde, resseguros, seguros comerciais e seguros hipotecários.', 'released', NULL, '3321'),
  ('http://data.europa.eu/esco/occupation/e93b3b49-12e1-4b47-991c-dd4b0aec17d8', 'Avaliador de Bens Pessoais', 'Os avaliadores de bens pessoais efetuam uma análise e investigação pormenorizadas de bens pessoais como livros, vinhos, objetos de arte e antiguidades, a fim de determinarem o seu valor para efeitos de venda e de seguro. Avaliam o valor dos artigos, tendo em conta a idade, o estado atual, a qualidade e a necessidade de reparações. Os avaliadores de bens pessoais elaboram relatórios de avaliação.', 'released', '["Avaliador de Bens Pessoais", "Avaliadora de Bens Pessoais"]'::jsonb, '3315'),
  ('http://data.europa.eu/esco/occupation/e93d5c8d-1219-4c11-91d7-9d0ab8d9c08e', 'Técnico de Incubação em Aquicultura', 'Os técnicos de incubação em aquicultura são responsáveis por e controlam todos os aspetos dos processos de produção de incubação, da gestão dos reprodutores à pré-engorda de juvenis.', 'released', '["Técnico de Incubação em Aquicultura", "Técnica de Incubação em Aquicultura"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/e9507d34-c70f-474f-a4a3-d2cbfe50f6e9', 'Diretor de Segurança', 'Os diretores de segurança asseguram a segurança das pessoas, tais como clientes e empregados, e os ativos da empresa, fixos, móveis, máquinas, veículos e imóveis. Asseguram a segurança e a proteção mediante a aplicação de políticas de segurança, o acompanhamento de diferentes eventos, a aplicação de protocolos de segurança, a criação de procedimentos de resposta a emergências, a realização de avaliações de segurança e a supervisão dos membros do pessoal de segurança. ;', 'released', '["Especialista em Questões de Segurança", "Diretora de Segurança", "Diretora de Sistemas de Segurança", "Diretor de Segurança", "Diretor de Sistemas de Segurança"]'::jsonb, '1219'),
  ('http://data.europa.eu/esco/occupation/e95ea9ec-3ac6-4a2d-a3cc-f9e8829cf15e', 'Especialista em Import-Export de Produtos Químicos', 'Os especialistas em import-export de produtos químicos possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Produtos Químicos"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/e9640041-ca34-4955-aa8c-629717d0dcda', 'Supervisor de Transporte por Bonde', 'Os supervisores de transporte por elétrico atribuem e gerem veículos elétricos e guarda-freios para o transporte de passageiros, incluindo registos das distâncias percorridas e das reparações efetuadas.', 'released', '["Supervisora de Transporte por Bonde"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/e9665bdf-2989-4dc5-9aa9-7b791e489779', 'Técnico em Geotecnia', 'Os técnicos em geotecnia recolhem e tratam amostras de rocha e de solo para ensaios geomecânicos. Descrevem igualmente a qualidade das massas rochosas, incluindo a estrutura, as descontinuidades, a cor e a exposição aos agentes atmosféricos. Os técnicos em geotecnia de minas podem medir a dimensão das aberturas subterrâneas. Comunicam as informações recolhidas aos geólogos e aos engenheiros, conforme necessário.', 'released', '["Técnico em Geotecnia", "Técnica em Geotecnia"]'::jsonb, '3117'),
  ('http://data.europa.eu/esco/occupation/e96cec32-9960-4496-a790-a9d2254906fc', 'Operador de Pistas de Corridas de Cavalos', 'Os operadores de pistas de corridas de cavalos gerem o funcionamento corrente da operação de apostas tote numa pista de corridas de cavalos, tais como a introdução e a verificação dos dados do sistema de apostas tote, preparam os relatórios necessários e prestam assistência no envio de equipamento e peças sobresselentes da empresa. Procedem à manutenção, operam e resolvem problemas nos painéis de apostas e nos painéis auxiliares de probabilidades. Operam os instrumentos de comunicação utilizados na pista de corridas. Procedem à instalação, desmontagem e manutenção do equipamento.;', 'released', '["Operadora de Apostas Tote", "Operador de Apostas Tote", "Operadora de Pistas de Corridas de Cavalos"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/e97ce81a-cf24-4012-b39e-f87bedc5b450', 'Nutricionista Animal', 'Os nutricionistas animais analisam o valor nutricional dos alimentos para animais, a fim de prestar aconselhamento alimentar aos profissionais da agricultura, da indústria transformadora, da zoologia e do setor público. Realizam investigação sobre alimentos nutricionalmente equilibrados e mantêm a sensibilização para a evolução técnica e científica nesta matéria.', 'released', '["Técnica de Nutrição Animal", "Técnico de Nutrição Animal", "Nutricionista Animal"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/e982a28b-9de2-460c-b85d-0f65ea0aa3ca', 'Vendedor Ambulante de Alimentos', 'Os vendedores ambulantes de alimentos vendem preparados alimentares, pratos e produtos em mercados organizados ao ar livre ou em espaços interiores, ou nas ruas. Preparam os alimentos nas suas bancas. Os vendedores ambulantes de alimentos utilizam técnicas de venda para recomendar os seus produtos aos transeuntes.', 'released', '["Vendedora Ambulante de Alimentos", "Vendedor Ambulante de Alimentos"]'::jsonb, '5212'),
  ('http://data.europa.eu/esco/occupation/e997358a-f6ed-4b5d-bebe-2a33b01ea3d2', 'Diretor de Importação e Exportação de Eletrodomésticos', 'Os diretores de importação e exportação de eletrodomésticos implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretor de Importação e Exportação de Eletrodomésticos", "Diretora de Importação e Exportação de Eletrodomésticos", "Diretor de Vendas de Eletrodomésticos", "Diretora de Vendas de Eletrodomésticos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/e9a65aca-64f6-450d-a637-1ecf86ba2a53', 'Soldador por Feixe de Eletrões', 'Os soldadores por feixe de eletrões instalam e cuidam das máquinas concebidas para unir peças metálicas separadas através da utilização de um feixe de eletrões de alta velocidade. Controlam os processos de maquinagem que proporcionam uma alteração na energia cinética dos eletrões que lhes permite transformar em calor para fundir e unir metal num processo de soldadura precisa.', 'released', '["Soldador por Feixe de Eletrões", "Soldadora por Feixe de Eletrões"]'::jsonb, '7212'),
  ('http://data.europa.eu/esco/occupation/e9cf8b24-6b8b-47cc-9dd3-b601aa135960', 'Representante de Grupos de Interesse Especial', 'Os representantes de grupos de interesse especial representam e atuam em nome de grupos de interesse social, como sindicatos, organizações patronais, associações comerciais e industriais, associações desportivas e organizações humanitárias. Desenvolvem políticas e asseguram a sua aplicação. Os representantes de grupos de interesse especial representam seus associados nas negociações sobre temas como as condições de trabalho e a segurança.', 'released', '["Sindicalista", "Representante de Associações Humanitárias", "Representante do Patronato", "Representante de Associações Comerciais e Industriais", "Representantea de Grupos de Interesse Especial"]'::jsonb, '1114'),
  ('http://data.europa.eu/esco/occupation/e9f0b7ae-c848-464e-af9d-55eb87a592e0', 'Operador de Máquinas de Anodização', 'Os operadores de máquinas de anodização instalam e asseguram o correto funcionamento de máquinas de anodização, concebidas para fornecer às peças metálicas acabadas, geralmente à base de alumínio, um revestimento durável resistente à corrosão, por oxidação anódica, através de um processo de passivação eletrolítica que aumenta a espessura da camada natural de óxido da superfície das peças metálicas.', 'released', '["Operadora de Máquinas de Anodização", "Operador de Máquinas de Anodização"]'::jsonb, '8122'),
  ('http://data.europa.eu/esco/occupation/e9f50268-4dab-4579-90c2-2ff219eb56f1', 'Professor de Engenharia', 'Os professores de Engenharia são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, a Engenharia, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames, na condução de práticas de laboratório e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio da Engenharia, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professor Universitário de Engenharia", "Professora de Engenharia", "Professora Universitária de Engenharia", "Professor de Engenharia"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/ea034d66-0d35-4891-b82c-6434cad2c76f', 'Revisor de Bilhetes de Caminhos-de-Ferro', 'Os revisores de bilhetes de caminhos-de-ferro prestam assistência aos passageiros no embarque e saída do comboio. Respondem a perguntas dos passageiros sobre as regras relativas aos comboios e às estações e fornecem informações sobre o horário. Recolhem bilhetes, títulos e cartões dos passageiros e apoiam o chefe de estação nas suas funções operacionais, por exemplo, no fecho de portas ou em determinadas comunicações operacionais. Garantem a segurança dos passageiros em resposta a incidentes técnicos e a situações de emergência.', 'released', '["Revisora de Bilhetes de Caminhos-de-Ferro", "Revisor de Bilhetes de Caminhos-de-Ferro"]'::jsonb, '5112'),
  ('http://data.europa.eu/esco/occupation/ea3db1b3-7c03-4306-9e3d-7e20eb7f1826', 'Suinicultor', 'Os suinicultores supervisionam a produção e o cuidado diário dos suínos. Zelam pela saúde e pelo bem-estar dos suínos.', 'released', '["Criador de Suínos", "Suinicultora", "Suinicultor", "Criadora de Suínos"]'::jsonb, '6121'),
  ('http://data.europa.eu/esco/occupation/ea4aff10-4d20-4a2b-886b-299c2bd349f1', 'Impressor Offset', 'Os impressores offset utilizam uma impressora offset para imprimir uma imagem. A impressora offset transfere uma imagem com tinta da placa para uma camada de borracha antes de imprimi-la na superfície de impressão.', 'released', '["Impressor Offset", "Impressora Offset", "Impressora de Offset", "Impressor de Offset"]'::jsonb, '7322'),
  ('http://data.europa.eu/esco/occupation/ea4c9aa1-cb9d-4037-a748-ac1305af7129', 'Agente da Proteção Civil', 'Os agentes da proteção civil trabalham em missões de ajuda em situações de emergência e de catástrofe, tais como catástrofes naturais ou derrames de petróleo. Limpam os detritos ou resíduos causados pelo evento, garantem a segurança das pessoas envolvidas, evitam danos adicionais e transportar bens, tais como alimentos e material médico.', 'released', '["Agentea da Proteção Civil"]'::jsonb, '5419'),
  ('http://data.europa.eu/esco/occupation/ea6cd713-94ca-4292-9ba9-ca8a4ec3ed5f', 'Operador de Desmontagem', 'Os operadores de desmontagem executam a desmontagem de equipamento industrial, máquinas e edifícios de acordo com as instruções do líder da equipe. Utilizam maquinaria pesada e diferentes ferramentas elétricas, dependendo da tarefa. Em todas as circunstâncias, são tidos em conta os regulamentos de segurança.', 'released', '["Operadora de Desmontagem", "Operador de Desmontagem"]'::jsonb, '7214'),
  ('http://data.europa.eu/esco/occupation/eaba592d-f3f0-4c7d-b7c0-302b7d0212ce', 'Técnico de Recirculação em Aquicultura', 'Os técnicos de recirculação em aquicultura são responsáveis por e controlam os processos de produção dos organismos aquáticos em sistemas de recirculação em terra, utilizando processos de reutilização da água e equipamento de bombagem, arejamento, aquecimento, iluminação e biofiltração, bem como sistemas de alimentação de reserva.', 'released', '["Técnico de Recirculação em Aquicultura", "Técnica de Recirculação em Aquicultura"]'::jsonb, '6221'),
  ('http://data.europa.eu/esco/occupation/eb00745b-9abb-4bd8-8291-aade48af029d', 'Técnico de Ensaios de Materiais', 'Os técnicos de ensaios de materiais realizam uma série de ensaios em materiais como solos, betão, alvenaria e asfalto, a fim de verificarem a conformidade com os casos e especificações de utilização previstos.', 'released', '["Técnica de Ensaios de Materiais", "Técnico de Ensaios de Materiais"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/eb198788-0b99-4583-a7c5-0139ff9f91ad', 'Chefe de Sala de Jogo', 'Os chefes de sala de jogo supervisionam as operações correntes das instalações de jogo. Supervisionam o pessoal, controlam as áreas de jogo, supervisionam os serviços de segurança, asseguram que todas as regras em matéria de jogo são respeitadas e acompanham o cumprimento dos requisitos regulamentares, responsáveis pela execução dos objetivos operacionais da empresa.', 'released', '["Chefea de Sala de Jogo"]'::jsonb, '4212'),
  ('http://data.europa.eu/esco/occupation/eb48ccbd-75f2-4799-81be-443034858473', 'Arte-Terapeuta', 'Os arte-terapeutas ajudam os doentes a ultrapassar dificuldades psicológicas e emocionais através de um processo artístico que reflete emoções e sentimentos, centrando-se nos doentes que sofrem uma série de problemas, como perturbações mentais, psicológicas e comportamentais, a fim de facilitar a autocompreensão e a sensibilização.', 'released', '["Arte Terapeuta"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/eb5df714-15ce-4e31-853c-678d2aba568b', 'Operador de Máquinas de Canelar', 'Os operadores de máquinas de canelar operam uma máquina que dobra uma folha de papel pesado num padrão semelhante a uma onda e abrange ambos os lados para criar um material leve, resistente e adequado para embalagem.', 'released', '["Operadora de Máquinas de Canelar", "Operador de Máquinas de Canelar"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/eb64b583-20fe-467f-8e44-8aae263a0139', 'Ourives de Prata', 'Os ourives de prata concebem, fabricam e vendem joias. Também ajustam, reparam e avaliam pedras preciosas e joalharia. Os ourives de prata são especializados no trabalho com prata e outros metais preciosos.', 'released', '["Ourives Dourador Prateador", "Ourives Polidor de Prata", "Ourives Douradora Prateadora", "Ourives Polidora de Prata"]'::jsonb, '7313'),
  ('http://data.europa.eu/esco/occupation/eb6e7100-446f-407c-a764-2d65f3ffc7eb', 'Comerciante Grossista em Maquinaria e Equipamento Agrícola', 'Os comerciantes grossistas em maquinaria e equipamento agrícola investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista em Maquinaria e Equipamento Agrícola"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/eb6efbb9-9216-4e86-bc3b-de2223cd4667', 'Veterinário Geral', 'Os veterinários gerais são profissionais com uma formação científica abrangente. Têm autoridade para exercer, de forma independente, ética e pessoalmente responsável, todos os aspetos da medicina veterinária, no interesse da saúde e do bem-estar dos animais e da saúde pública, em conformidade com a legislação nacional e internacional. Os veterinários gerais podem trabalhar com qualquer espécie. No entanto, podem optar por trabalhar com uma única espécie ou tipo como os equídeos, os animais de companhia ou os animais de produção.', 'released', '["Veterinária Geral", "Médica Veterinária Geral", "Médico Veterinário Geral", "Veterinário Geral"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/eb7e42d0-9b3f-49ad-81f1-b9ee8491bf39', 'Jornalista de Política', 'Os jornalistas de política investigam e redigem artigos sobre política e políticos para jornais, revistas, televisão e outros meios de comunicação social. Realizam entrevistas e participam em eventos.', 'released', '["Jornalista Especializado em Política", "Jornalista Especializada em Política"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/eb9479c6-5fdf-4f45-ace4-28b547b8c7e5', 'Diretor de Produção Industrial', 'Os diretores de produção industrial supervisionam as operações e os recursos necessários nas instalações industriais e nas fábricas, tendo em vista o bom funcionamento das operações. Elaboram o calendário de produção, combinando as necessidades dos clientes com os recursos da unidade de produção. Organizam o percurso das matérias-primas ou dos produtos semiacabados na fábrica até à entrega de um produto final, através da coordenação dos inventários, dos armazéns, da distribuição e das atividades de apoio.', 'released', '["Diretora de Produção Industrial", "Diretor de Produção Industrial"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/ebb4061a-906f-45fe-b4c0-a871c11f6fab', 'Gerente de Segurança de Hotel', 'Os gerentes de segurança de hotel são responsáveis pela gestão do processo global e pela implementação da segurança de hotel em termos de segurança dos bens, segurança pessoal e segurança do edifício.', 'released', '["Agente de Segurança", "Gerente de Segurança de Hotel", "Segurança", "Gerentea de Segurança de Hotel"]'::jsonb, '5414'),
  ('http://data.europa.eu/esco/occupation/ebe42b55-4801-493f-af18-04a35ebfbb9c', 'Operador de Perfuradora', 'Os operadores de perfuradora instalam, programam e controlam as perfuradoras, concebidas para perfurar orifícios em peças separadas através de uma ferramenta de corte, rotativa e multipontiaguda, controlada por computador, inserida na peça axialmente. Interpretam os esquemas das perfuradoras e as instruções das ferramentas, realizam operações regulares de manutenção das máquinas e efetuam ajustes aos comandos de perfuração, tais como a profundidade das perfurações ou a velocidade de rotação.', 'released', '["Operadora de Perfuradora", "Operador de Perfuradora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/ebe936e2-64e7-4777-94d6-42caa5a12409', 'Argumentista', 'Os argumentistas criam guiões para filmes ou séries de televisão. Escrevem uma história pormenorizada constituída por um enredo, personagens, um diálogo e um ambiente físico.', 'released', NULL, '2641'),
  ('http://data.europa.eu/esco/occupation/ebff4fcf-6b69-4290-a55c-9bfe4cc7a1ef', 'Fabricante de Redes de Pesca', 'Os fabricantes de redes de pesca fabricam e procedem à montagem das artes de pesca, bem como à reparação e manutenção, em conformidade com os desenhos e/ou os métodos tradicionais.', 'released', '["Fabricantea de Redes de Pesca"]'::jsonb, '7318'),
  ('http://data.europa.eu/esco/occupation/ec0e64c9-6d9b-4a9f-a022-a418f3b381fe', 'Artista de Cerâmica', 'Os artistas de cerâmica possuem um profundo conhecimento dos materiais e os conhecimentos necessários para desenvolverem os seus próprios métodos de expressão e projetos pessoais através da cerâmica. As suas criações podem incluir esculturas de cerâmica, artigos de joalharia, artigos de mesa e de cozinha para uso doméstico e comercial, bem como artigos para oferta, cerâmica de jardim, azulejos e mosaicos.', 'released', NULL, '2651'),
  ('http://data.europa.eu/esco/occupation/ec21ce88-ce14-49b6-be0a-cc53cf5a3a67', 'Engenheiro Químico', 'Os engenheiros químicos concebem e desenvolvem grandes processos de produção química e física e estão envolvidos em todo o processo industrial necessário para transformar as matérias-primas em produtos.', 'released', '["Engenheira Química", "Engenheiro Químico", "Engenheira Químico"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/ec238461-93b6-4516-a251-52d1153b53ac', 'Operador de Máquinas de Moldagem por Compressão', 'Os operadores de máquinas de moldagem por compressão instalam e operam máquinas para moldar produtos de plástico, de acordo com os requisitos. Procedem à seleção e à instalação de moldes na prensa. Os operadores de máquinas de moldagem por compressão pesam a quantidade de composto pré-misturado necessário e vertem-no para o poço do molde. Regulam a temperatura dos moldes.', 'released', '["Operadora de Máquinas de Moldagem por Compressão", "Operador de Máquinas de Moldagem por Compressão"]'::jsonb, '8142'),
  ('http://data.europa.eu/esco/occupation/ec2c0655-5ba0-4cc8-860a-977f73b37f34', 'Especialista em Legendagem', 'Os especialistas em legendagem podem trabalhar de forma intralingual, ou seja dentro da mesma língua, ou interlingual, ou seja entre línguas. Os especialistas em legendagem intralingual criam as legendas para os telespetadores com dificuldades auditivas, ao passo que os especialistas em legendagem interlingual criam as legendas de filmes ou programas de televisão numa língua diferente da que é ouvida na produção audiovisual. Ambos garantem que as legendas estão sincronizadas com o som, as imagens e o diálogo da obra audiovisual.', 'released', NULL, '2643'),
  ('http://data.europa.eu/esco/occupation/ec5a067f-6278-4e35-990f-c9b7205a9ff4', 'Engenheiro de Homologação', 'Os engenheiros de homologação são responsáveis pelo processo de homologação de novos tipos de veículos, componentes e sistemas e por assegurar a conformidade com os requisitos regulamentares aplicáveis no país de venda. Desenvolvem e implementam programas de homologação e facilitam ensaios de homologação em conformidade com a legislação europeia, garantindo o respeito dos calendários de homologação. Estudam e interpretam os requisitos regulamentares e são o principal ponto de contato para efeitos de homologação e certificação dentro da organização e com agências externas. Os engenheiros de homologação elaboram documentação técnica e apoiam os engenheiros de design e ensaio no processo de desenvolvimento de veículos.;', 'released', '["Gerente de Homologação", "Engenheira de Homologação Automotiva", "Engenheiro de Homologação Automotiva", "Engenheira de Garantia de Design de Veículos", "Engenheiro de Garantia de Design de Veículos", "Engenheira de Conformidade de Veículos Motorizados", "Engenheiro de Conformidade de Veículos Motorizados", "Engenheira de Homologação"]'::jsonb, '2141'),
  ('http://data.europa.eu/esco/occupation/ec5b72d1-0206-4179-9abd-570c66bc44b9', 'Desenvolvedor de E-learning', 'Os programadores de e-learning criam e desenvolvem formas mais simples de conteúdos de aprendizagem digital, incluindo materiais de referência, diapositivos, avaliações, screen-casts, vídeos de entrevistas e podcasts. Escrevem e fornecem conteúdos para uma aplicação de aprendizagem baseada em computador.', 'released', '["Produtor de Conteúdos e-Learning", "Produtor de e-Learning", "Produtora de Elearning", "Produtora de Conteúdos e-Learning", "Produtor de Elearning", "Programadora de Elearning", "Produtor de Conteúdos Elearning", "Criadora de Conteúdos Elearning", "Criadora de Conteúdos e-Learning", "Produtora de Conteúdos Elearning", "Programadora de e-Learning", "Produtora de e-Learning", "Criador de Conteúdos e-Learning", "Programador de Elearning", "Criador de Conteúdos Elearning", "Programador de e-Learning", "Programador", "Desenvolvedora de E-learning"]'::jsonb, '2359'),
  ('http://data.europa.eu/esco/occupation/ecac98ea-9fc3-4475-9b23-8af94f41603d', 'Serralheiro de Moldes', 'Os serralheiros de moldes operam máquinas e equipamentos concebidos para a criação de ferramentas e moldes metálicos, que são necessários em várias áreas da indústria transformadora e produzem estes instrumentos em todas as fases do processo de produção. Concebem os instrumentos e moldes, depois cortam-nos e dão-lhes forma à medida, e procedem ao seu acabamento por máquinas-ferramentas manuais, ferramentas elétricas, ferramentas manuais ou por programação e tratamento de ferramentas CNC e máquinas de fabrico de moldes.', 'released', '["Serralheiro de Moldes", "Serralheira de Moldes"]'::jsonb, '7222'),
  ('http://data.europa.eu/esco/occupation/ecd0fad8-b099-4c47-93f6-dde9f6f6c5fc', 'Caricaturista', 'Os caricaturistas desenham pessoas, objetos, eventos, etc., de forma cômica ou depreciativa. Exageram as características físicas e os traços de personalidade. Além disso, os caricaturistas retratam acontecimentos políticos, econômicos, culturais e sociais de forma humorística.', 'released', NULL, '2651'),
  ('http://data.europa.eu/esco/occupation/ecdc43f5-3b32-4f94-abf8-cd46480c8cb8', 'Instalador de Sistemas Eletrônicos em Veículos', 'Os instaladores de sistemas eletrônicos em veículos instalam equipamento e acessórios em veículos a motor, tais como leitores de CD e GPS. Utilizam berbequins elétricos e fresadoras para instalar e examinar o mau funcionamento dos sistemas eletrônicos. ;', 'released', '["Instaladora de Sistemas Eletrônicos em Veículos", "Instalador de Sistemas Eletrônicos em Veículos"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/ecfcf554-254f-4dd7-a20c-b60cc6b16054', 'Operador de Máquina de Fabricação de Cigarros', 'Os operadores de máquinas de fabrico de cigarros asseguram o correto funcionamento de máquinas de fabrico de cigarros para envolver tabaco em rolos de papel contínuo, seguindo-se o corte dos cigarros dos rolos. Colocam o rolo de papel de cigarro em fusos e regulam dispositivos de impressão de monogramas para imprimir a marca no papel de cigarro numa posição especificada.', 'released', '["Técnico de Operação de Instalação de Enrolar e Cortar Tabaco", "Operadora de Máquina de Fabricação de Cigarros", "Operador de Máquina de Fabricação de Cigarros", "Técnica de Operação de Instalação de Enrolar e Cortar Tabaco"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/ed096599-56a9-443d-9683-8a92f58aa894', 'Operador de Máquina de Bordar', 'Os operadores de máquinas de bordar decoram o vestuário utilizando máquinas de bordar, que variam na sua tecnologia, a fim de bordar e ornamentar artigos de vestuário.', 'released', '["Operador de Máquina de Bordar", "Operadora de Máquina de Bordar"]'::jsonb, '8153'),
  ('http://data.europa.eu/esco/occupation/ed256ed0-0432-4969-8544-3e5e01a517a9', 'Ministro do Culto', 'Os ministros do culto lideram organizações ou comunidades religiosas, realizam cerimónias espirituais e religiosas e fornecem orientação espiritual aos membros de um determinado grupo religioso. Podem realizar trabalho missionário, pastoral ou de pregação, ou trabalhar numa ordem ou comunidade religiosa, como um mosteiro ou um convento. Os ministros do culto exercem funções como a condução de serviços de culto, a ministração de educação religiosa, a celebração de funerais e de casamentos, o aconselhamento a membros da congregação e a prestação de uma série de outros serviços comunitários, quer em conjunto com a organização para a qual trabalham, quer através das suas próprias atividades pessoais quotidianas.', 'released', '["Minstra do Culto", "Ministro do Culto", "Ministra do Culto"]'::jsonb, '2636'),
  ('http://data.europa.eu/esco/occupation/ed3cf43d-c2c1-4c46-82fc-1375e27e0290', 'Canalizador', 'Os canalizadores procedem à manutenção e instalação de sistemas de água, gás e saneamento. Procedem à inspeção regular dos tubos e dos equipamentos, ou efetuam as reparações necessárias. Dobram, cortam e instalam tubos. Testam os sistemas e procedem a ajustes de forma segura e seguindo os regulamentos. Instalam equipamento sanitário.', 'released', '["Canalizadora", "Canalizador"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/ed41ca50-bb2a-41e2-a332-9b2df83040c1', 'Operador de Instalação de Refinação', 'Os operadores de instalação de refinação asseguram o correto funcionamento de máquinas para refinar os óleos brutos, tais como o óleo de soja, o óleo de sementes de algodão e o óleo de amendoim. Cuidam dos tanques para remover os subprodutos e remover as impurezas com calor.', 'released', '["Operadora de Máquina de Refinação", "Operador de Instalação de Refinação", "Operador de Máquina de Refinação", "Operadora de Instalação de Refinação"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/ed976196-3d5d-4121-9367-e1022af603fa', 'Técnica de Laboratório de Controle de Qualidade na Indústria do Calçado', 'Os técnicos de laboratório de controlo de qualidade na indústria do calçado realizam todo o tipo de testes laboratoriais no calçado e nos respetivos materiais ou componentes, de acordo com as normas nacionais e internacionais. Analisam e interpretam os seus resultados e elaboram os relatórios para o gestor da qualidade, prestando aconselhamento sobre rejeições ou aceitações. Utilizam ferramentas de gestão da qualidade previamente definidas, com vista ao cumprimento dos objetivos enunciados na política de qualidade. Participam na monitorização e no controlo do sistema de qualidade, nomeadamente através de auditorias internas e externas. Colaboram na preparação de documentos relacionados com a qualidade e na ligação com laboratórios subcontratados para a realização dos testes que não podem ser realizados na empresa.', 'released', '["Técnico de Laboratório de Controle de Qualidade na Indústria do Calçado", "Técnica de Laboratório", "Técnica de Laboratório de Controle de Qualidade na Indústria do Calçado", "Técnico de Laboratório"]'::jsonb, '3119'),
  ('http://data.europa.eu/esco/occupation/eda0d957-3c3c-4139-b89a-a18bc9e18897', 'Contabilista', 'Os contabilistas reveem e analisam as demonstrações financeiras, os orçamentos, os relatórios financeiros e os planos de negócios, a fim de verificar se existem irregularidades resultantes de erros ou de fraude, e prestam aconselhamento financeiro aos seus clientes em questões como a previsão financeira e a análise de risco. Podem proceder à auditoria de dados financeiros, resolver casos de insolvência, preparar declarações fiscais e fornecer outros conselhos de natureza fiscal, em referência à legislação em vigor.', 'released', '["Técnico Contabilista", "Técnica Contabilista"]'::jsonb, '2411'),
  ('http://data.europa.eu/esco/occupation/eda6cb5e-c27a-4661-b536-eadeb387dee3', 'Gerente de Loja de Bicicletas', 'Os gerentes de loja de bicicletas são responsáveis pelas atividades e pelo pessoal em lojas especializadas que vendem e reparam bicicletas. Estes funcionários gerem os trabalhadores, controlam as vendas da loja, gerem orçamentos e efetuam encomendas quando um produto se encontra esgotado e executam tarefas administrativas, se necessário.', 'released', '["Gerentea de Loja de Bicicletas"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/edf2e989-d7c5-496e-b365-81fc5cb9eb39', 'Técnico de Engenharia Mecatrônica', 'Os técnicos de engenharia mecatrónica colaboram com os engenheiros no desenvolvimento de dispositivos e aplicações de mecatrónica, através de uma combinação de engenharia mecânica, engenharia eletrônica e engenharia informática. Constroem, testam, instalam e calibram dispositivos de mecatrónica e resolvem problemas técnicos.', 'released', '["Técnico de Engenharia Mecatrónica", "Técnica de Engenharia Mecatrónica", "Técnica de Engenharia Mecatrônica"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/ee37a4a5-5360-4e94-a749-a2b8ead08500', 'Misturador de Explosivos', 'Os misturadores de explosivos operam as máquinas e o equipamento utilizado para criar detonadores e explosivos, através da mistura de produtos químicos líquidos e secos, certificando-se de que os parâmetros requeridos estejam definidos e que as misturas inflamáveis estejam em conformidade com as especificações.', 'released', '["Misturadora de Explosivos", "Misturador de Explosivos"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/ee5f8b2f-4b40-4426-8290-a6926ae4898b', 'Diretor de Distribuição — Carne e Produtos à Base de Carne', 'Os diretores de distribuição — carne e produtos à base de carne planificam a distribuição de carne e de produtos à base de carne em vários pontos de venda.', 'released', '["Diretor de Distribuição — Carne e Produtos à Base de Carne", "Diretora de Logística — Carne e Produtos à Base de Carne", "Diretor de Logística — Carne e Produtos à Base de Carne", "Diretora de Distribuição — Carne e Produtos à Base de Carne"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/ee646fa1-3f09-4e43-9275-3aa958ca00ae', 'Skipper', 'Os skippers são a mais alta autoridade a bordo de navios de navegação por via marítima ou por vias navegáveis interiores, são responsáveis pelo navio e são responsabilizados pela segurança e pelo bem-estar dos clientes e da tripulação. São licenciados pela autoridade responsável e determinam as operações do navio em qualquer altura. Constituem a última instância responsável pela tripulação, pelo navio, pela carga e/ou pelos passageiros e pela viagem.', 'released', '["Capitã", "Capitão", "Skipper"]'::jsonb, '3152'),
  ('http://data.europa.eu/esco/occupation/eea2b5c6-48d1-4612-957e-585783b3c7bb', 'Diretor de Lar de Idosos', 'Os diretores de lar de idosos supervisionam, planificam, organizam e avaliam a prestação de serviços de cuidados a idosos para as pessoas que necessitam destes serviços devido aos efeitos do envelhecimento. Gerem os cuidados a idosos e supervisionam as atividades do pessoal.', 'released', '["Diretor de Lar de Idosos", "Diretora de Lar de Idosos"]'::jsonb, '1343'),
  ('http://data.europa.eu/esco/occupation/eeac6251-1974-42f5-91ed-513c6c883755', 'Operador de Empilhadores', 'Os operadores de empilhadores são responsáveis pela operação dos empilhadores para movimentar, colocar, recolocar, empilhar e contabilizar mercadorias. São responsáveis pela segurança e eficácia do funcionamento dos empilhadores. Também executam as encomendas e verificam a exatidão das outras encomendas.', 'released', '["Operador de Empilhadores", "Operadora de Empilhadores"]'::jsonb, '8344'),
  ('http://data.europa.eu/esco/occupation/eedbf8b1-9432-4f42-ab7f-db5cd3eb2a05', 'Operador de Escavadora', 'Os operadores de escavadora utilizam escavadoras para cavar a terra ou outros materiais para a sua remoção. Participam em vários projetos, tais como a demolição, a dragagem e a realização de furos, fundações e valas.', 'released', '["Operador de Escavadora", "Operadora de Escavadora"]'::jsonb, '8342'),
  ('http://data.europa.eu/esco/occupation/eee68e13-8248-43bb-a9fb-959832a6c217', 'Biólogo', 'Os biólogos estudam os organismos vivos e a vida em sentido lato, em combinação com o seu ambiente. Através da investigação, procuram explicar os mecanismos funcionais, as interações e a evolução dos organismos.', 'released', '["Zoóloga", "Ornitólogo", "Bióloga Especialista em Genética", "Bióloga", "Entomóloga", "Micólogo", "Ornitóloga", "Biólogo Especialista em Genética", "Zoologista", "Biólogo", "Entomólogo", "Micologista", "Virologista", "Patologista de Plantas", "Microbióloga", "Botanista", "Zoólogo", "Microbiologista", "Microbiólogo", "Bactereologista", "Ornitologista", "Entomologista", "Micóloga"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/ef0363cf-361a-47df-9431-d94afb757ce0', 'Produtor de Podcasts', 'Os produtores de podcasts supervisionam todo o processo de produção de um podcast. Este processo envolve o planejamento dos episódios, o apoio à gravação e edição áudio, as tarefas de produção e a publicação da versão final do produto. Desenvolvem igualmente estratégias de promoção e de marketing baseadas nas tendências do mercado de podcasts e no público-alvo.', 'released', '["Produtora de Podcasts", "Produtor de Podcasts"]'::jsonb, '2654'),
  ('http://data.europa.eu/esco/occupation/ef53663e-c295-43a4-a48e-84254270b138', 'Instalador de Sistemas de Irrigação', 'Os instaladores de sistemas de irrigação criam as infraestruturas necessárias para a irrigação do solo, geralmente para fins agrícolas. Podem ser especializadas em um ou mais dos diferentes tipos de sistemas de irrigação fixos.', 'released', '["Técnica de Sistemas de Irrigação", "Instalador de Sistemas de Irrigação", "Instaladora de Sistemas de Irrigação", "Técnico de Sistemas de Irrigação"]'::jsonb, '7126'),
  ('http://data.europa.eu/esco/occupation/ef5b17a5-3ca8-4965-bd3d-61c4aca490d1', 'Responsável Pela Gestão de Documentos', 'Os responsáveis pela gestão de documentos asseguram que os documentos necessários ao funcionamento e às operações diárias da sua organização são corretamente registados, classificados e arquivados e disponibilizados aos diferentes serviços ou ao público mediante pedido. Supervisionam a aplicação de procedimentos internos e promovem práticas adequadas de gestão de documentos na organização, dando formação a outros funcionários sobre os procedimentos de gestão de documentos. Podem utilizar sistemas de gestão de registos eletrônicos (ERMS), sistemas de gestão de documentos eletrônicos (EDMS) e sistemas de gestão de arquivos (AMS) e prestar apoio na definição dos requisitos técnicos conexos.;', 'released', '["Gerente de Arquivo", "Gerente de Registros", "Controladora de Documento", "Controladora de Documento Líder", "Gerente de Documentação", "Controlador de Documento", "Gerenciador de Documentos", "Gerente de Controle de Documentos", "Especialista em Gestão de Documentos", "Controlador de Documento Líder"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/ef6020f9-11b4-4d1a-96e0-903331594121', 'Diretor de Desenvolvimento de Produtos de Calçado', 'Os diretores de desenvolvimento de produtos de calçado coordenam o design do calçado e o processo de desenvolvimento do produto e da coleção, a fim de respeitar especificações de design, prazos, exigências estratégicas e as políticas da empresa. Acompanham o desenvolvimento de novos estilos e adaptam as especificações de forma a corresponderem à visão do design, ao ambiente de fabrico e aos objetivos financeiros da empresa.;', 'released', '["Diretora de Desenvolvimento de Novos Produtos", "Diretor de Desenvolvimento de Produtos", "Chefe de Projeto de Desenvolvimento de Produtos de Calçado", "Diretor de Desenvolvimento de Produtos de Calçado", "Diretora de Desenvolvimento de Produtos", "Diretor de Desenvolvimento de Novos Produtos", "Diretora de Desenvolvimento de Produtos de Calçado"]'::jsonb, '1223'),
  ('http://data.europa.eu/esco/occupation/ef909843-97c6-4c48-8038-2e7aefdfcad5', 'Diretor de Informática Médica', 'Os diretores de informática médica supervisionam as operações diárias dos sistemas de informação utilizados nas instituições médicas. Também realizam investigação, utilizando a sua compreensão das práticas clínicas para encontrar formas de melhorar os serviços de saúde.', 'released', '["Diretor de Informática Médica", "Diretora de Informática Médica", "Gestor de Informática Médica", "Gestora de Informática Médica"]'::jsonb, '1342'),
  ('http://data.europa.eu/esco/occupation/ef937393-3382-438d-b570-399d44b5a41c', 'Especialista em Import-Export de Máquinas Ferramentas', 'Os especialistas em import-export de máquinas ferramentas possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Máquinas Ferramentas"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/ef9c2914-2f3d-464c-ae0a-d02b403dc7e9', 'Inspetor de Motores de Aeronaves', 'Os inspetores de motores de aeronaves inspecionam, em fábricas, todos os tipos de motores utilizados em aeronaves, a fim de garantir a sua conformidade com as normas e a regulamentação em matéria de segurança. Realizam inspeções de rotina, pós-revisão, pré-disponibilidade e pós-acidentes. Fornecem documentação para atividades de reparação e apoio técnico aos centros de manutenção e reparação. Verificam os registos administrativos, analisam o desempenho operacional dos motores e elaboram relatórios com as suas conclusões.', 'released', '["Inspetor de Motores de Aeronaves", "Técnica de Manutenção", "Inspetora de Motores de Aeronaves", "Técnico de Manutenção"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/efa81635-9125-4276-8902-9deb12170ea7', 'Arquiteto de Interiores', 'Os arquitetos de interiores criam planos para o interior de um casa, edifício ou outra estrutura. Determinam as especificações e a distribuição do espaço. Os arquitetos de interiores combinam uma compreensão do espaço com sentido de estética, a fim de criar uma concepção de interiores harmoniosa. Elaboram desenhos arquitetónicos utilizando equipamento assistido por computador e software ou métodos convencionais, como papel e caneta.', 'released', '["Designer de Interiores", "Arquiteto de Interiores", "Arquiteta de Interiores"]'::jsonb, '2161'),
  ('http://data.europa.eu/esco/occupation/efc75d4e-dfbf-4178-929c-0ae198801c36', 'Engenheiro Geoténico', 'Os engenheiros geotécnicos realizam atividades de engenharia e ensaios e análises hidrológicos e geológicos para melhorar a segurança e a eficiência das operações mineiras. Supervisionam a recolha de amostras e a realização de medições utilizando métodos e técnicas de investigação geotécnica. Modelam o comportamento mecânico da massa rochosa e contribuem para a concepção da geometria da mina.', 'released', '["Engenheira de Minas", "Engenheiro de Minas", "Engenheiro Geoténico", "Geólogo de Exploração", "Engenheira Geoténica", "Geóloga de Exploração", "Engenheira Geoténico"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/efd5d3cb-3716-43b7-b21b-98e17f00e9eb', 'Assistente de Mineiro', 'Os assistentes de mineiro desempenham funções de rotina nas operações de exploração mineira e de exploração de pedreiras. Prestam assistência aos mineiros na manutenção do equipamento, com a instalação de tubos, cabos e túneis, e com a remoção de detritos.', 'released', '["Assistentea de Mineiro"]'::jsonb, '9311'),
  ('http://data.europa.eu/esco/occupation/f00154a5-d27f-429e-b9a4-1d65c672cee7', 'Recepcionista Veterinário', 'Os rececionistas veterinários acolhem e prestam apoio de escritório/administrativo num consultório veterinário, realizam marcações e recebem os clientes, vendem e aconselham produtos relacionados com animais, em conformidade com a legislação nacional.', 'released', '["Recepcionista Veterinário", "Recepcionista Veterinária", "Recepcionista de Hospital Veterinário", "Recepcionista de Clínica Veterinária"]'::jsonb, '4226'),
  ('http://data.europa.eu/esco/occupation/f0296b9c-764d-42ab-8de9-2a3729a9b67a', 'Biólogo Marinho', 'Os biólogos marinhos estudam os organismos vivos e os ecossistemas marinhos e a sua interação subaquática. Estudam a fisiologia, as interações entre organismos e entre estes e os seus habitats, a evolução das espécies marinhas e o papel do ambiente nas suas adaptações. Os biólogos marinhos também realizam experiências científicas em condições controladas no intuito de compreender estes processos. Centram-se também nos efeitos das atividades humanas na vida dos mares e oceanos.;', 'released', '["Pesquisador em Biologia Marinha", "Botânica Marinho", "Zoólogo Marinho", "Pesquisador de Biologia Marinha", "Bióloga Marinho", "Ecologista Marinho", "Botânico Marinho"]'::jsonb, '2131'),
  ('http://data.europa.eu/esco/occupation/f04eaeff-52f5-4d52-93ad-6f846884827f', 'Silvicultor', 'Os silvicultores são responsáveis pelo controlo da viabilidade natural e econômica de um bosque ou floresta e por atividades relacionadas com a sua gestão e conservação.', 'released', '["Administrador Florestal", "Administradora Florestal", "Responsável Florestal", "Silvicultora", "Silvicultor"]'::jsonb, '1311'),
  ('http://data.europa.eu/esco/occupation/f0691bb2-c717-4215-a814-88a15b10ee4d', 'Pintor Naval', 'Os pintores navais trabalham no setor da construção naval e são responsáveis pela conclusão dos trabalhos de decapagem, pintura, lavagem e limpeza de casco, desmantelamento e tarefas várias de proteção atribuídas pelos supervisores. Seguem orientações, processos e procedimentos definidos para assegurar a correta conclusão dos trabalhos.;', 'released', '["Pintor de Navios", "Pintora de Barco", "Pintor de Barco", "Pintora Marítima", "Pintora de Navios", "Blaster Marinho", "Pintor Marítimo", "Pintora Naval"]'::jsonb, '7131'),
  ('http://data.europa.eu/esco/occupation/f07aab15-c7e8-49a4-a8dd-221d9cf3a925', 'Gerente de Posto de Combustível', 'Os gerentes de posto de combustível assumem a responsabilidade pelas atividades e pelo pessoal de um posto de combustível.', 'released', '["Gerente de Estação de Combustível", "Gerente de Posto de Abastecimento", "Gerentea de Posto de Combustível"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/f0978ec0-ae7d-4c4a-8f80-3fd200edddac', 'Inspetor de Controle de Qualidade na Construção', 'Os inspetores de controlo de qualidade na construção monitorizam as atividades em estaleiros de maior dimensão, garantindo que as operações decorrem de acordo com as normas e as especificações. Dão especial atenção a potenciais problemas de segurança e recolhem amostras de produtos para testar a sua conformidade com as normas e especificações.', 'released', '["Inspetora de Controle de Qualidade na Construção", "Inspetor de Controle de Qualidade na Construção"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/f09b6100-28a6-4be5-9726-ecf5b24f74f6', 'Técnico de Teatro', 'Os técnicos de teatro executam todas as tarefas técnicas de apoio para os espetáculos ao vivo. Constroem e desmontam palcos e cenários, instalam e operam equipamentos de som, de luz, de gravação e de vídeo e organizam o transporte dos cenários e do equipamento técnico para espetáculos com deslocações.', 'released', '["Técnico de Teatro", "Técnica de Teatro"]'::jsonb, '3435'),
  ('http://data.europa.eu/esco/occupation/f0ca39a8-1e30-487c-95f9-ef2d5e734adc', 'Gestor de Operações Informáticas', 'Os gestores de operações de informáticas coordenam os serviços e as infraestruturas informáticos que asseguram que a organização dispõe dos recursos de infraestruturas necessários. Também planificam e acompanham as fases de um processo empresarial ou de um processo informático, negoceiam contratos e tomam medidas de atenuação em caso de incumprimento dos acordos. Supervisionam as tarefas quotidianas que envolvem componentes de infraestruturas, sistemas informáticos e software.', 'released', '["Gestor de Processos Informáticos", "Gestor de Redes e Sistemas", "Gestora de Redes e Sistemas", "Gestora de Processos Informáticos", "Gestora de Processamento de Dados", "Gestora de Operações Informáticas", "Gestor de Operações Informáticas", "Gestor de Processamento de Dados", "Gestora de Sistemas e Redes", "Gestor de Sistemas e Redes", "Gerente"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/f0e1cc13-48e0-4995-8699-ee43467bce0d', 'Professor de Matemática do Ensino Secundário', 'Os professores de Matemática do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Matemática. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Matemática através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Matemática do Ensino Secundário", "Professora de Matemática do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/f0e479d9-7afd-40b1-b60f-b68c400c15fb', 'Inspetor de Edifícios', 'Os inspetores de edifícios realizam inspeções de edifícios para determinar a conformidade com as especificações no que respeita a diversos pontos de avaliação. Observam e determinam a adequação, a qualidade e a resistência da construção e a conformidade geral com os regulamentos.', 'released', '["Inspetor de Edifícios", "Inspetora de Edifícios"]'::jsonb, '3112'),
  ('http://data.europa.eu/esco/occupation/f0f6d531-eb96-4bad-84ff-8e2999ea68e6', 'Técnico de Reparações de Celulares', 'Os técnicos de reparações de celulares realizam testes para avaliar o funcionamento do celular, instalam e atualizam software do telefone, resolvem problemas de cablagem e substituem peças e componentes danificados, tais como baterias, telas LCD, teclados e botões. Também aconselham os clientes sobre questões de garantia e recomendam produtos com base nos seus conhecimentos especializados.', 'released', '["Técnico de Reparações de Celulares", "Técnica de Reparações de Celulares"]'::jsonb, '7422'),
  ('http://data.europa.eu/esco/occupation/f14194e2-8e7f-4fc9-9c8c-78d9ae2e7284', 'Engenheiro Nuclear', 'Os engenheiros nucleares planificam e concebem equipamentos e processos de engenharia em centrais e instalações nucleares. Participam em atividades de engenharia relacionadas com centrais nucleares e desenvolvem soluções de risco.', 'released', '["Engenheira Nuclear", "Engenheiro Nuclear"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/f1783e61-38b7-468e-b495-9c3c92f5ab0d', 'Operador de Abate Halal', 'Os operadores de abate halal abatem animais e processam carcaças de carne halal de vacas e frangos de transformação e distribuição. Procedem ao abate de animais de acordo com a lei islâmica e asseguram que os animais são alimentados, abatidos e suspensos em conformidade.', 'released', '["Operador de Abate Halal", "Operadora de Abate Halal"]'::jsonb, '7511'),
  ('http://data.europa.eu/esco/occupation/f1b89616-5dfe-40d4-8b02-58a6982b1a01', 'Engenheiro Projetista de Subestações', 'Os engenheiros projetistas de subestações concebem subestações de média e alta tensão utilizadas para a transmissão, a distribuição e a produção de energia elétrica. Desenvolvem métodos para o funcionamento eficiente do processo energético e asseguram a conformidade com as normas de segurança e ambientais.', 'released', '["Engenheira Projetista de Subestações", "Engenheira de Manutenção de Subestações", "Engenheiro de Manutenção de Subestações", "Engenheira de Automação de Subestações", "Engenheiro de Fiscalização de Subestações", "Engenheiro Projetista de Subestações", "Engenheiro de Automação de Subestações", "Engenheira de Fiscalização de Subestações"]'::jsonb, '2151'),
  ('http://data.europa.eu/esco/occupation/f1c8c186-bef9-4d72-9257-90fc4f992ab7', 'Operador de Estação de Gás', 'Os operadores de estações de gás tratam os gases para compressão, transmissão ou recuperação por meio de compressores de gás, de vapor ou elétricos. Realizam ensaios químicos aos gases e são responsáveis pelas operações em bombas e condutas.', 'released', '["Operador de Estação de Gás", "Operadora de Estação de Gás"]'::jsonb, '3133'),
  ('http://data.europa.eu/esco/occupation/f1ecc3c4-8212-4386-871a-6fda1b5b4d91', 'Leiloeiro', 'Os leiloeiros realizam leilões, aceitando licitações e declarando as mercadorias vendidas.', 'released', '["Leiloeira", "Leiloeiro"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/f1fcad3b-fdf0-444a-81b0-e50e96f8966a', 'Técnico de Merchandising', 'Os técnicos de merchandising são responsáveis pelo posicionamento de mercadorias em conformidade com normas e procedimentos.', 'released', '["Técnica de Merchandising", "Técnico de Merchandising"]'::jsonb, '3432'),
  ('http://data.europa.eu/esco/occupation/f20d3ae6-baeb-482c-b68d-c2fb115e5dde', 'Tripulante de Cabine', 'Os tripulantes de cabine desempenham uma série de serviços pessoais conducentes à segurança e conforto dos passageiros das companhias aéreas durante o voo. Recebem os passageiros, verificam os bilhetes e orientam os passageiros para os lugares atribuídos. Elaboram relatórios após o desembarque que descrevem como o voo decorreu em termos de operações, procedimentos e anomalias.', 'released', '["Comissária de Bordo", "Comissário de Bordo", "Assistente de Bordo", "Tripulantea de Cabine"]'::jsonb, '5111'),
  ('http://data.europa.eu/esco/occupation/f219f643-4df1-4a9a-b6c5-dc2f48c22806', 'Au Pair', 'Os au pairs vivem e trabalham para uma família de acolhimento noutro país e são normalmente responsáveis por cuidar dos filhos da família. São pessoas jovens que procuram explorar outra cultura, prestando simultaneamente serviços de cuidados de crianças, bem como outras atividades domésticas ligeiras, tais como a limpeza, a jardinagem e as compras.', 'released', NULL, '5311'),
  ('http://data.europa.eu/esco/occupation/f235bc5a-dbf6-4f9e-bbdb-cf313d32b75b', 'Professor de Música', 'Os professores de música ensinam aos alunos diferentes gêneros musical e formas de expressão, como a música clássica, o jazz, o folk, o pop, os blues, o rock, a música eletrônica, etc., num contexto recreativo. Proporcionam aos alunos uma visão geral da história e do repertório musicais, recorrendo sobretudo a uma abordagem prática nas sua aulas. Nas aulas, ajudam os alunos a experimentar diferentes estilos e técnicas, no instrumento musical da sua escolha, incentivando-os a desenvolver o seu próprio estilo. Criam, dirigem e produzem espetáculos musicais e coordenam a produção técnica.', 'released', '["Professor de Solfejo", "Professor de Música", "Professora de Guitarra", "Professora de Piano", "Professor de Guitarra", "Professor de Canto", "Professora de Violino", "Professor de Piano", "Professora de Música", "Professor de Violino", "Professora de Canto", "Professora de Solfejo"]'::jsonb, '2354'),
  ('http://data.europa.eu/esco/occupation/f2413988-f76a-4636-a4b1-9952517aa21f', 'Especialista em Segurança Contra Incêndio Acreditado Pela Autoridade Nacional de Proteção Civil', 'Os especialistas em segurança contra incêndio acreditados pela Autoridade Nacional de Proteção Civil supervisionam a atividade do serviço de bombeiros, garantindo que os serviços prestados são eficazes e que o equipamento necessário está disponível. Desenvolvem e gerem as políticas comerciais que asseguram a legislação neste domínio. Os especialistas em segurança contra incêndio acreditados pela Autoridade Nacional de Proteção Civil realizam inspeções de segurança e promovem a educação para a prevenção de incêndios.', 'released', NULL, '1112'),
  ('http://data.europa.eu/esco/occupation/f272a521-1a38-4d34-a78e-3adeca95b977', 'Operário da Manutenção Rodoviária', 'Os operários da manutenção rodoviária efetuam inspeções de rotina das estradas e são enviados para efetuar reparações quando solicitado. Reparam buracos, fissuras e outros danos nas estradas.', 'released', '["Operário da Manutenção Rodoviária", "Operária da Manutenção Rodoviária"]'::jsonb, '9312'),
  ('http://data.europa.eu/esco/occupation/f2a416b8-c7e4-49ee-964d-a49f6af79b84', 'Comandante de Navio', 'Os comandantes de navios são responsáveis por navios destinados ao transporte de mercadorias e de passageiros, operando em alto mar ou em águas costeiras. A dimensão do navio pode variar entre uma pequena embarcação e um navio de cruzeiro, dependendo da arqueação para a qual possuem certificação de navegação. Os comandantes de navios possuem uma vasta experiência com os navios e o seu funcionamento, sendo provável que tenham exercido outros cargos na hierarquia de funções de um navio.', 'released', '["Comandantea de Navio"]'::jsonb, '3152'),
  ('http://data.europa.eu/esco/occupation/f2b15a0e-e65a-438a-affb-29b9d50b77d1', 'Desenvolvedor de Software', 'Desenvolve, testa, documenta e mantém sistemas e aplicações de software a partir de requisitos e especificações técnicas. Atua no back-end e/ou front-end, implementa APIs, integrações e bancos de dados, escreve código limpo e seguro e participa de revisões, testes automatizados e implantação contínua. Colabora com product managers, designers, QA e DevOps para entregar soluções escaláveis e de qualidade.', 'released', '["Desenvolvedor de Software", "Programador de Software", "Programadora de Software", "Programador de Aplicações", "Desenvolvedor de Aplicações", "Engenheiro de Software", "Engenheira de Software", "Desenvolvedor Full-Stack", "Desenvolvedor Back-End", "Desenvolvedor de Sistemas", "Programador de Software de Aplicações", "Criador de Aplicações", "Desenvolvedor de Software de Aplicação", "Programador", "Desenvolvedora de Software"]'::jsonb, '2512'),
  ('http://data.europa.eu/esco/occupation/f2cc5978-e45c-4f28-b859-7f89221b0505', 'Oficial da Força Aérea', 'Os oficiais da Força Aérea especializam-se em operações de voo ou terrestres e supervisionam uma equipe de pessoal da Força Aérea. Coordenam a formação e o bem-estar da sua equipe e executam tarefas específicas no seu domínio de especialização.', 'released', '["Marechal da Força Aérea", "Oficial da Área de Operações Aéreas", "Major-General da Força Aérea", "Oficial Piloto Aviador", "Capitão"]'::jsonb, '0110'),
  ('http://data.europa.eu/esco/occupation/f2ee2cda-9d02-49c3-8280-da5892d0055b', 'Técnico de Iluminação Pública', 'Os técnicos de iluminação pública procedem à construção e manutenção da transmissão e distribuição de energia elétrica na iluminação pública. Procedem à manutenção, ao ensaio e à reparação da iluminação pública, em conformidade com a regulamentação em matéria de segurança.', 'released', '["Técnico de Iluminação Pública", "Técnica de Iluminação Pública"]'::jsonb, '7413'),
  ('http://data.europa.eu/esco/occupation/f2f4ed8f-c9d3-47e4-8f72-a30739bcea2b', 'Gerente de Loja de Bebidas', 'Os gerentes de loja de bebidas assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Bebidas Alcoólicas", "Gerentea de Loja de Bebidas"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/f31e25d0-8794-4f88-ac07-a229199c6f0f', 'Operador de Manutenção de Máquinas de Fabricação de Artigos em Couro', 'Os operadores de manutenção de máquinas de fabrico de artigos em couro programam e afinam diferentes tipos de equipamento específico de corte, costura e acabamento relacionado com o fabrico de artigos em couro. Cuidam da manutenção preventiva e corretiva dos diferentes equipamentos, verificando periodicamente as suas condições de trabalho e o seu desempenho, analisando as falhas, corrigindo os problemas, corrigindo os problemas, reparando e substituindo os componentes e procedendo à lubrificação de rotina. Fornecem informações sobre a utilização de equipamento e o seu consumo energético aos diretores da empresa.', 'released', '["Operador de Manutenção de Máquinas de Fabricação de Artigos em Couro", "Operadora de Manutenção de Máquinas de Fabricação de Artigos em Couro"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/f31f487b-4ce2-40f3-90e8-7d0011b4ef1d', 'Gestor de Software', 'Os gestores de software supervisionam a aquisição e o desenvolvimento de sistemas de software, a fim de prestar apoio a todas as unidades organizacionais. Acompanham também os resultados e a qualidade das diferentes soluções e projetos de software implementados na organização.', 'released', '["Gestor de Aplicações", "Gestor de Software", "Gestor de Aplicações Web", "Gestora de Software", "Gestora de Aplicações Web", "Gestora de Aplicações", "Gerente"]'::jsonb, '1330'),
  ('http://data.europa.eu/esco/occupation/f33a70bd-c5b6-495d-8e0c-5e2c6e56d93e', 'Operador de Sala de Controle de Central Elétrica', 'Os operadores de salas de controlo de centrais elétricas são responsáveis pelo funcionamento seguro e adequado das centrais elétricas, das subestações e das estruturas de controlo associadas. Efetuam a reparação e a manutenção das máquinas e equipamentos, a fim de assegurar o funcionamento eficiente da central e de resolver situações de emergência, como apagões.', 'released', '["Operadora de Sala de Controle de Central Elétrica", "Operador de Sala de Controle de Central Elétrica"]'::jsonb, '3131'),
  ('http://data.europa.eu/esco/occupation/f34cad67-3cd9-4d31-8dde-e439ac720136', 'Especialista em Import-Export de Máquinas para a Indústria Têxtil', 'Os especialistas em import-export de máquinas para a indústria têxtil possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Máquinas para a Indústria Têxtil"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/f3b99acc-b212-45cf-bb4f-7b83cc6f0d71', 'Técnico de Bacteriologia', 'Os técnicos de bacteriologia prestam assistência técnica na investigação e na análise de bactérias utilizando equipamento de laboratório. Recolhem e analisam dados para fins de experiências, elaboram relatórios e mantêm as existências do material de laboratório.', 'released', '["Técnico de Bacteriologia", "Técnica de Bacteriologia"]'::jsonb, '3141'),
  ('http://data.europa.eu/esco/occupation/f3d2074e-3f44-45b0-b896-5ee5629a23c1', 'Especialista em Import-Export de Café, Chá, Cacau e Especiarias', 'Os especialistas em import-export de café, chá, cacau e especiarias possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Café, Chá, Cacau e Especiarias"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/f3d8bc61-f812-4106-afd2-a356e4c11fce', 'Estudioso de Literatura', 'Os estudiosos de literatura investigam obras literárias, a história da literatura, gêneros e críticas literárias, com vista a avaliarem as obras e os seus aspetos envolventes num contexto adequado e a produzirem resultados de investigação sobre temas específicos no domínio da literatura.', 'released', '["Teórica de Literatura", "Estudiosa de Literatura", "Crítico Literário", "Teórico de Literatura", "Crítica Literária", "Estudioso de Literatura", "Especialista em Literatura"]'::jsonb, '2641'),
  ('http://data.europa.eu/esco/occupation/f3da16bd-157d-4a48-8a49-33809a8b5d96', 'Comerciante Grossista de Flores e Plantas Ornamentais', 'Os comerciantes grossistas de flores e plantas ornamentais investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Flores e Plantas Ornamentais"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/f3e23761-0663-4ae0-97a2-0b2dd3fa38a1', 'Engenheiro Bioquímico', 'Os engenheiros bioquímicos realizam investigação no domínio das ciências da vida com vista a novas descobertas. Convertem essas conclusões em soluções químicas que podem melhorar o bem-estar da sociedade, como as vacinas, a reparação de tecidos, a melhoria das culturas e tecnologias verdes como combustíveis mais limpos provenientes de recursos naturais.', 'released', '["Engenheira Bioquímica Especialista em Biocombustíveis", "Engenheira Alimentar", "Engenheiro Bioquímico", "Engenheiro Alimentar", "Engenheira Bioquímica Especialista em Enzimas", "Engenheiro Bioquímico Especialista em Biocombustíveis", "Engenheiro Bioquímico Especialista em Enzimas", "Engenheira Bioquímica", "Engenheira Bioquímico"]'::jsonb, '2145'),
  ('http://data.europa.eu/esco/occupation/f3eb330a-03b5-4537-ac0e-bcee5c67bcff', 'Coordenador de Operações de Carga Aérea', 'Os coordenadores de operações de carga aérea dirigem e coordenam as atividades dos terminais de transporte aéreo de carga e de acesso. Analisam os dados sobre os voos de chegada para planear as atividades de trabalho. Dirigem a preparação dos planos de carregamento para cada voo de partida e dialogam com o pessoal de supervisão para garantir a disponibilidade de trabalhadores e equipamento para as atividades de cargas aéreas e de carga, descarga e manuseamento de bagagens.', 'released', '["Coordenador de Operações de Carga Aérea", "Coordenadora de Operações de Carga Aérea"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/f3fc11ca-9a72-40da-bf0f-b2aab7e33079', 'Canteiro', 'Os canteiros entalham e montam à mão pedra para fins de construção. Embora o equipamento CNC para entalhe seja a norma do setor, o entalhe artesanal de pedra ornamental é ainda é feito à mão.', 'released', '["Cortadora de Pedra", "Cortador de Pedra", "Polidor de Pedra", "Canteiro", "Polidora de Pedra", "Canteira"]'::jsonb, '7113'),
  ('http://data.europa.eu/esco/occupation/f444e8ec-5eed-4777-866e-7127aa06ce4f', 'Técnico de Controle na Fabricação de Vestuário', 'Os técnicos de controlo no fabrico de vestuário operam vários equipamentos de controlo de processos nas linhas de montagem do setor da produção.', 'released', '["Técnica de Controle no Fabricação de Vestuário", "Técnico de Controle no Fabricação de Vestuário", "Técnica de Controle na Fabricação de Vestuário"]'::jsonb, '3139'),
  ('http://data.europa.eu/esco/occupation/f4525ed8-54eb-4a3b-90db-55cc01b0d9fd', 'Prestador de Cuidados Domiciliários', 'Os prestadores de cuidados domiciliários prestam serviços ao domicílio a adultos vulneráveis, incluindo idosos frágeis, pessoas com deficiência que têm limitações de mobilidade ou pessoas em convalescença, seguindo um plano específico de prestação de cuidados diários aos clientes. Zelam pelo bem-estar físico e mental dos clientes, prestando-lhes assistência social. Estes serviços podem ser prestados em lares, em casas de repouso ou no domicílio do doente. Neste último caso, visam melhorar a vida dos doentes na comunidade e garantir que estes possam viver de forma segura e independente na sua própria casa.', 'released', '["Técnico de Cuidados Domiciliários", "Prestadora de Cuidados Domiciliários", "Técnica de Cuidados Domiciliários", "Prestador de Cuidados Domiciliários"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/f470b785-643c-46f9-8b31-6085427ab7b8', 'Especialista em Informação Aeronáutica', 'Os especialistas em informação aeronáutica prestam serviços de gestão de informação aeronáutica de alta qualidade através de meios tecnológicos. Prestam apoio a especialistas seniores em informação aeronáutica e avaliam as alterações nas informações aeronáuticas responsáveis por afetar as cartas aeronáuticas e outros produtos. Respondem aos pedidos de dados aeronáuticos solicitados por grupos e sistemas operacionais de companhias aéreas.', 'released', NULL, '3154'),
  ('http://data.europa.eu/esco/occupation/f489b1ec-3d6c-44b1-b1d7-c6c97db7df30', 'Sapador Florestal', 'Os sapadores florestais são responsáveis pela proteção e conservação dos recursos naturais, nomeadamente das florestas e zonas arborizadas.', 'released', '["Guarda-Florestal", "Sapador Florestal", "Sapadora Florestal"]'::jsonb, '6210'),
  ('http://data.europa.eu/esco/occupation/f49d893a-ac89-4f3b-b547-1cbdf4d69fde', 'Técnico de Equipamento Florestal', 'Os técnicos de equipamento florestal procedem à manutenção e ao transporte de máquinas florestais. Como parte da manutenção de máquinas florestais, recorrem a sistemas e instrumentos especializados em matéria de software e de registo de dados.', 'released', '["Técnica de Equipamento Florestal", "Técnico de Dispositivos Florestais", "Técnico de Maquinaria Florestal", "Técnico de Equipamento Florestal", "Técnica de Dispositivos Florestais", "Técnica de Maquinaria Florestal", "Técnica Especialista de Manutenção de Equipamento Florestal", "Técnico Especialista de Manutenção de Equipamento Forestal", "Técnico Especializado na Manutenção de Equipamento Forestal", "Técnica Especializada na Manutenção de Equipamento Florestal"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/f4a22809-c00c-4dd0-8b09-c7251f8dcd1c', 'Estucador', 'Os estucadores aplicam gesso proveniente de gipso, cimento ou outras soluções em paredes, como um acabamento liso. Misturam o gesso seco em pó com água, aplicando depois a massa resultante na parede. O gesso é depois alisado antes de endurecer e forma um revestimento sólido na parede.', 'released', '["Rebocadora", "Estucador", "Rebocador", "Estucadora"]'::jsonb, '7123'),
  ('http://data.europa.eu/esco/occupation/f4a25243-b06a-42a9-9c69-246853df63ad', 'Zelador', 'Os zeladores realizam várias atividades de manutenção e reparação de edifícios, terrenos e outras instalações. Reparam e renovam estruturas e componentes, vedações, portões e telhados, montam mobiliário e executam atividades de canalização e eletricidade. Verificam os sistemas de aquecimento e ventilação, a qualidade do ar e a humidade no edifício.', 'released', '["Zeladora", "Zelador", "Trabalhador Polivalente", "Trabalhadora Polivalente"]'::jsonb, '9622'),
  ('http://data.europa.eu/esco/occupation/f4b4fb1d-0224-4e6b-b7c9-84bcf133be00', 'Vendedor de Equipamento de Telecomunicações', 'Os vendedores de equipamento de telecomunicações vendem equipamentos e serviços de telecomunicações em lojas especializadas.', 'released', '["Vendedor de Equipamento de Telecomunicações", "Vendedora de Equipamento de Telecomunicações"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/f4c997b5-f9e0-4419-b8e7-8e5e2cffc73e', 'Técnico de Produção de Filamentos Têxteis', 'Os técnicos de produção de filamentos têxteis efetuam operações relacionadas com a criação de processos de filamentos têxteis.', 'released', '["Técnico de Produção de Filamentos Têxteis", "Técnico de Produção de Têxteis não Tecidos", "Técnica de Produção de Filamentos Têxteis", "Técnica de Produção de Têxteis não Tecidos"]'::jsonb, '8159'),
  ('http://data.europa.eu/esco/occupation/f4de7e28-ca67-46cd-b760-30e02b3aa83b', 'Diretor de Laboratório Médico', 'Os diretores de laboratório médico supervisionam as operações diárias de um laboratório médico. Gerem os trabalhadores e comunicam o calendário das atividades. Acompanham e asseguram a realização de todas as operações laboratoriais de acordo com as especificações, organizam o equipamento de laboratório necessário e asseguram a observância das normas adequadas em matéria de saúde e segurança.', 'released', '["Diretor de Laboratório Médico", "Diretora de Laboratório Médico", "Chefe de Laboratório"]'::jsonb, '1349'),
  ('http://data.europa.eu/esco/occupation/f4e0016b-29fa-48ac-b98d-364c658f8aed', 'Operador de Misturador de Bebidas Alcoólicas', 'Os operadores de misturador de bebidas alcoólicas recalibram, filtram, retificam, misturam e verificam as provas das bebidas alcoólicas antes de estas serem preparadas para engarrafamento. Para o efeito, asseguram o correto funcionamento de equipamento e máquinas para realizar cada um destes processos.', 'released', '["Misturadora de Licores", "Misturador de Licores", "Operador de Misturador de Bebidas Alcoólicas", "Operadora de Misturador de Bebidas Alcoólicas"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/f4e3dd1c-f86b-4a69-8887-547255eadc79', 'Gestor de Centro de Informação Turística', 'Os gestores de centro de informação turística são responsáveis pela gestão dos empregados e pelas atividades de um centro que presta informações e aconselhamento aos viajantes e visitantes sobre atrações, eventos, viagens e alojamento a nível local.', 'released', '["Supervisora de Centro de Informação Turística", "Gestor de Centro de Informação Turística", "Supervisor de Centro de Informação Turística", "Gestora de Centro de Informação Turística", "Gerente"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/f4eaff3d-f8d0-4a6a-aa90-76827c0fbada', 'Técnico de Reparação de Eletrodomésticos', 'Os técnicos de reparação de eletrodomésticos utilizam equipamento elétrico para testar a resistência ou a tensão e identificar as anomalias dos aparelhos. Reparam pequenos e grandes eletrodomésticos, tais como aspiradores, máquinas de lavar roupa, máquinas de lavar louça, aparelhos de ar condicionado e frigoríficos.', 'released', '["Técnica de Reparação de Eletrodomésticos", "Técnico de Reparação de Eletrodomésticos"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/f4f671d5-208f-4423-a250-c049de8d9adc', 'Hidroterapeuta Veterinário', 'Os hidroterapeutas veterinários administram tratamentos terapêuticos na sequência de um diagnóstico ou indicação veterinários. O seu método baseia-se na resistência à água para o tratamento das doenças, para auxiliar a recuperação pós-cirúrgica, para a realização de exercícios pré-operatórios e para melhorar a condição física geral, em conformidade com a legislação nacional.', 'released', '["Hidroterapeuta Veterinário", "Hidroterapeuta de Animais", "Hidroterapeuta de Veterinária", "Hidroterapeuta Animal", "Hidroterapeuta Veterinária"]'::jsonb, '2250'),
  ('http://data.europa.eu/esco/occupation/f5166c6b-3467-4fc4-9343-d12e870d9def', 'Gestor de Serviço de Clientes', 'Os gestores de serviço de clientes coordenam e planificam as operações diárias dos centros de contato. Asseguram que as dúvidas dos clientes são esclarecidas de forma eficiente e de acordo com as políticas. Gerem os trabalhadores, os recursos e os procedimentos para criar as melhores práticas e atingir níveis elevados de satisfação dos clientes.', 'released', '["Gestor de Serviço de Clientes", "Gestora de Serviço de Clientes", "Gerente"]'::jsonb, '1439'),
  ('http://data.europa.eu/esco/occupation/f5332f2d-3119-4194-8b5c-d0a5d97f55ef', 'Agente de Promoção de Vendas', 'Os agentes de promoção de vendas vendem espaço publicitário e tempo em meios de comunicação social a empresas e a particulares. Apresentam argumentos persuasivos de vendas a potenciais clientes e acompanham os serviços pós-venda.', 'released', '["Sales", "Agentea de Promoção de Vendas"]'::jsonb, '3339'),
  ('http://data.europa.eu/esco/occupation/f53dbdb1-2f64-42f8-a6a4-0552c40e4f57', 'Operador de Purificador de Farinha', 'Os operadores de purificador de farinha asseguram o correto funcionamento de máquinas para misturar e peneirar a farinha. asseguram o correto funcionamento de transportadores helicoidais para transportar a farinha para os processos de mistura e purificação. Operam separadores para peneirar a farinha misturada e para eliminar grumos antes de estar pronta a embalar.', 'released', '["Operador de Instalação de Purificação de Farinha", "Operadora de Purificador de Farinha", "Operadora de Instalação de Purificação de Farinha", "Operador de Purificador de Farinha"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/f5576c5b-8d03-4a3d-9cb7-b8c4ac07a7ef', 'Diretor de Casa da Juventude', 'Os diretores de casa da juventude planificam e supervisionam as operações das casas da juventude que prestam serviços de assistência e de aconselhamento. Avaliam as necessidades dos jovens na comunidade, desenvolvem e implementam métodos pedagógicos e desenvolvem programas para melhorar a assistência aos jovens no casa da juventude.', 'released', '["Diretor de Casa da Juventude", "Diretora de Centro Juvenil", "Diretor de Centro Juvenil", "Diretora de Casa da Juventude", "Diretor de Centro de Jovens", "Diretora de Centro de Jovens"]'::jsonb, '1344'),
  ('http://data.europa.eu/esco/occupation/f5596182-70b2-4c18-97ab-f9405bae0385', 'Técnico de Serigrafia', 'Os técnicos de serigrafia gravam ou entalham serigrafias para impressão de têxteis.', 'released', '["Técnica de Serigrafia", "Técnico de Serigrafia"]'::jsonb, '7321'),
  ('http://data.europa.eu/esco/occupation/f569145d-8f87-4f80-b861-45583430d9f4', 'Fabricante de Idiofones', 'Os fabricantes de idiofones criam e montam peças para fabricar idiofones, de acordo com instruções ou diagramas especificados. Dão forma, perfuram, lixam e colocam cordas nas peças que são principalmente feitas de vidro, metal, cerâmica ou madeira, limpam, testam a qualidade e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Idiofones"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/f56e33a3-01bb-46ba-98f4-d47aa242b983', 'Diretor dos Transportes Rodoviários', 'Os diretores dos transportes rodoviários mantêm o controlo dos processos relacionados com veículos, pessoal, clientes, rotas e contratos.', 'released', '["Gestor de Operações de Transportes Rodoviários", "Diretor dos Transportes Rodoviários", "Diretora dos Transportes Rodoviários", "Gestora de Operações de Transportes Rodoviários"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/f57eb0cb-e67a-419c-9b7b-4abd811b7e2f', 'Coordenador de Mudanças', 'Os coordenadores de mudanças planeiam todas as atividades necessárias para uma mudança bem-sucedida. Recebem informações do cliente e traduzem-nas em ações e atividades que asseguram uma mudança calma, competitiva e satisfatória.', 'released', '["Coordenadora de Mudanças", "Coordenador de Mudanças"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/f5aa06b0-745e-4eb1-b050-3e15d11e5eb5', 'Supervisor de Tratamento Químico', 'O supervisores de tratamento químico coordenam as atividades e o pessoal envolvido no processo de produção química, assegurando o cumprimento dos objetivos e dos prazos de produção. Controlam a qualidade e otimizam o tratamento dos produtos químicos, garantindo a execução dos procedimentos de teste, de análise e de controlo de qualidade definidos.', 'released', '["Supervisora de Laboratório", "Supervisor de Tratamento Químico", "Supervisor de Laboratório", "Supervisora de Tratatamento Químido", "Supervisora de Tratamento Químico"]'::jsonb, '3122'),
  ('http://data.europa.eu/esco/occupation/f5ba8fb4-1387-459a-9b22-59feb891e229', 'Montador de Cabos Elétricos', 'Os montadores de cabos elétricos manipulam cabos e fios de aço, cobre ou alumínio, para que possam ser utilizados para produzir eletricidade numa variedade de aparelhos.', 'released', '["Montadora de Cabos Elétricos", "Montador de Cabos Elétricos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/f5cb9901-86fc-48d0-9cde-667fbe8cef3a', 'Embalador Manual', 'Os embaladores manuais recolhem, embalam e rotulam as mercadorias e os materiais à mão. Asseguram que todas as mercadorias e materiais sejam embalados de acordo com as instruções e os requisitos.', 'released', '["Embalador Manual", "Embaladora Manual"]'::jsonb, '9321'),
  ('http://data.europa.eu/esco/occupation/f5e80af5-eebe-4133-878a-5dc5ef34fe93', 'Chefe de Equipe de Produção Agrícola', 'Os chefes de equipe de produção agrícola são responsáveis por liderar e trabalhar com uma equipe de trabalhadores da produção agrícola. Organizam os horários de trabalho diários para a produção agrícola e participam na produção.', 'released', '["Chefea de Equipe de Produção Agrícola"]'::jsonb, '6111'),
  ('http://data.europa.eu/esco/occupation/f605bcd2-90b6-45a0-a558-d05016d68a77', 'Diretor de Recursos Humanos', 'Os diretores de recursos humanos planificam, concebem e aplicam processos relacionados com o capital humano das empresas. Desenvolvem programas de recrutamento, entrevista e seleção de trabalhadores com base numa avaliação anterior do perfil e das competências exigidas na empresa. Além disso, gerem programas de compensação e desenvolvimento para os trabalhadores da empresa, incluindo formação, avaliação de competências e avaliações anuais, promoção, programas de expatriados e garantia geral do bem-estar dos trabalhadores no local de trabalho.', 'released', '["Diretor de Pessoal", "Diretora de Recursos Humanos", "Diretor de Recursos Humanos", "Diretora de Pessoal", "Chefe de Pessoal", "RH"]'::jsonb, '1212'),
  ('http://data.europa.eu/esco/occupation/f60dc59b-7681-45d4-8114-b3a646e02ab2', 'Cabeleireiro de Espetáculos', 'Os cabeleireiros de espetáculos prestam assistência e apoio aos artistas antes, durante e após o espetáculo para assegurar que os penteados estão de acordo com a visão artística do encenador de teatro e da equipe artística. Procedem à manutenção, verificam e reparam perucas e prestam assistência com mudanças rápidas. ;', 'released', '["Cabeleireira de Espetáculos", "Cabeleireiro de Espetáculos"]'::jsonb, '5141'),
  ('http://data.europa.eu/esco/occupation/f634ce9b-68a5-4a8a-af4a-ed13fc0deba9', 'Técnico de Julgado de Paz', 'Os julgados de paz tratam de ações e litígios de pequeno montante e de pequenas infrações. Asseguram a manutenção da paz sob a sua jurisdição e promovem a mediação entre as partes litigantes.', 'released', '["Técnica de Julgado de Paz", "Técnico de Julgado de Paz"]'::jsonb, '3411'),
  ('http://data.europa.eu/esco/occupation/f643bff3-74ef-48d1-b033-820e2d8659e9', 'Controlador de Tráfego Ferroviário', 'Os controladores de tráfego ferroviário utilizam sinais e pontos que ajudam a garantir que os comboios circulam de forma segura e atempada. Trabalham a partir de uma caixa de sinal para controlar a ordem e a circulação dos comboios e garantir a segurança a qualquer momento. São responsáveis pela manutenção das normas de segurança quando os comboios circulam normalmente e também em situações operacionais degradadas ou de emergência.', 'released', '["Controlador de Tráfego Rodoviário", "Controladora de Tráfego Rodoviário", "Controladora de Tráfego Ferroviário"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/f6803a58-91d9-4251-9a07-09fc387cec16', 'Músico', 'Os músicos executam uma peça vocal ou musical que pode ser gravada ou tocada para um público. Possuem conhecimentos e prática de um ou vários instrumentos ou utilizam a sua voz. O músico pode igualmente escrever e transcrever música.', 'released', '["Flautista", "Música", "Percussionista", "Pianista", "Guitarrista", "Saxofonista", "Instrumentalista", "Músico", "Violoncelista", "Violonista", "Baterista", "Baixista"]'::jsonb, '2652'),
  ('http://data.europa.eu/esco/occupation/f6811475-94d4-4d13-8d5f-f173978ae7ec', 'Agente Partidário', 'Os agentes partidários gerem as tarefas administrativas de um partido político, como a gestão do orçamento, a conservação de registos, a elaboração da agenda, etc. Asseguram, além disso, uma comunicação produtiva com os organismos governamentais, bem como com a imprensa e os meios de comunicação social.', 'released', '["Agente Partidária", "Agente Partidário", "Agentea Partidário"]'::jsonb, '2432'),
  ('http://data.europa.eu/esco/occupation/f6ca9392-708d-46cb-a2e9-51519595baa2', 'Professor de Teatro do Ensino Secundário', 'Os professores de Teatro do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, o Teatro. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio do Teatro através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Expressão Dramática do Ensino Secundário", "Professora de Teatro do Ensino Secundário", "Professora de Expressão Dramática do Ensino Secundário", "Professor de Teatro do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/f6f1a9c5-a956-4a10-98ad-b83525e843fb', 'Preparador de Lotes', 'Os preparadores de lotes descarregam produtos alimentares em barris, tinas ou recipientes, juntamente com as quantidades prescritas de conservantes, tais como sal, açúcar, salmoura, xarope ou vinagre, para o fabrico de produtos alimentares.', 'released', '["Embalador", "Preparadora de Lotes", "Embaladora", "Enfardadora", "Preparador de Lotes", "Enfardador"]'::jsonb, '8160'),
  ('http://data.europa.eu/esco/occupation/f7066fc0-5f2f-43a9-bd35-a99e6119490d', 'Tratador de Animais em Jardim Zoológico', 'Os tratadores de animais em jardim zoológico gerem os animais mantidos em cativeiro para fins de conservação, educação, investigação e/ou exposição ao público. São geralmente responsáveis pela alimentação e pelos cuidados e bem-estar diários dos animais. Como parte da sua rotina, os tratadores de animais em jardim zoológico limpam as exposições e comunicam possíveis problemas de saúde. Podem também participar na investigação científica específica ou no ensino público, através da realização de visitas guiadas e da resposta a perguntas.', 'released', '["Tratador de Animais (Jardim Zoológico)", "Tratadora de Animais (Jardim Zoológico)", "Tratadora de Animais em Jardim Zoológico"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/f70e5875-df7e-40be-a315-3ac1c9d36d64', 'Gerente de Loja de Artigos em Segunda Mão', 'Os gerentes de loja de artigos em segunda mão assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Caridade", "Gerente de Bric-a-Brac", "Gerente de Loja de Roupas em Segunda Mão", "Gerente de Loja Vintage", "Gerentea de Loja de Artigos em Segunda Mão"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/f7145f87-5940-43f5-bc98-aa1a2b872b47', 'Técnico de Máquinas Agrícolas', 'Os técnicos de máquinas agrícolas procedem à reparação, instalação e manutenção de equipamento agrícola, incluindo tratores, equipamento de mobilização do solo, de sementeira e de colheita. Realizam avaliações do equipamento e atividades de manutenção preventiva e reparam falhas.', 'released', '["Técnico de Máquinas Agrícolas", "Técnica de Máquinas Agrícolas"]'::jsonb, '7233'),
  ('http://data.europa.eu/esco/occupation/f7177f79-63e7-4944-8896-044056b62523', 'Treinador Pessoal', 'Os treinadores pessoais concebem, implementam e avaliam programas de exercício ou de atividade física para um ou mais clientes individuais, recolhendo e analisando informações sobre o cliente. Procuram assegurar a eficácia dos programas de exercícios pessoais. Um treinador pessoal também deve incentivar ativamente os potenciais clientes a participar e aderir a programas regulares, recorrendo a estratégias de motivação adequadas.', 'released', '["Personal Trainer", "Treinadora Pessoal", "Treinador Pessoal"]'::jsonb, '3423'),
  ('http://data.europa.eu/esco/occupation/f738f568-b4ff-4f23-acb7-5f99d9a3b393', 'Especialista em Import-Export de Laticínios e Óleos Alimentares', 'Os especialistas em import-export de lacticínios e óleos alimentares possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Lacticínios e Óleos Alimentares"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/f73e11e7-0eb8-4a46-b2e1-9e544c2f3652', 'Operador de Máquinas de Acabamento Têxtil', 'Os operadores de máquinas de acabamento têxtil procedem à operação, supervisão, controlo e manutenção da produção de máquinas de acabamento têxtil.', 'released', '["Operador de Máquinas de Acabamento Têxtil", "Operadora de Máquinas de Acabamento Têxtil"]'::jsonb, '8154'),
  ('http://data.europa.eu/esco/occupation/f7450c1f-20b7-45dd-b3bb-25095830bf3f', 'Especialista em Política Externa', 'Os especialistas em política externa analisam as políticas e operações no domínio dos assuntos externos e elaboram relatórios que apresentam as suas análises de forma clara e compreensível. Comunicam com as partes que beneficiam das suas conclusões e prestam aconselhamento no domínio do desenvolvimento ou da aplicação de políticas externas, ou da divulgação de relatórios sobre política externa. Os especialistas em política externa podem desempenhar igualmente funções administrativas no departamento, como a assistência relativa a problemas com passaportes e vistos. Promovem uma comunicação amistosa e aberta entre os diferentes governos e instituições nacionais.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/f756fdab-7726-4c48-bfcc-94ff8810fc08', 'Ajudante de Cozinha', 'Os ajudantes de cozinha lavam e limpam as superfícies de cozinha, incluindo panelas, frigideiras, utensílios, cutelaria e pratos. Preparam a área de cozinha antes da prestação de serviços e recebem e armazenam os mantimentos.', 'released', '["Empregada de Copa", "Empregado de Copa", "Empregada de Cozinha", "Copeiro", "Copeira", "Empregado de Cozinha", "Ajudantea de Cozinha"]'::jsonb, '9412'),
  ('http://data.europa.eu/esco/occupation/f7b04542-d8c7-42db-8475-e63b507cce82', 'Recepcionista', 'Os rececionistas são responsáveis pela área de recepção de uma empresa. Atendem o telefone, recebem os visitantes, transmitem informações, respondem a pedidos de informação e dão instruções aos visitantes. São o primeiro ponto de contato para os clientes.', 'released', NULL, '4226'),
  ('http://data.europa.eu/esco/occupation/f7ddb68a-beba-4aa9-b5cb-d174d70ea724', 'Inspetor de Soldadura', 'Os inspetores de soldadura analisam as conexões e as ligações entre os metais. Utilizam ferramentas de visualização e instrumentos elétricos para inspecionar e garantir a qualidade e a segurança das ligações. Os inspetores de soldadura asseguram que todas as atividades, planos e materiais relacionados com a soldadura cumprem as diretrizes adequadas, em conformidade com a regulamentação em matéria de segurança. Para além de trabalharem no terreno na inspeção dos projetos de soldadura, os inspetores também exercem funções num gabinete compilando os seus relatórios.', 'released', '["Inspetora de Soldadura", "Inspetor de Soldadura"]'::jsonb, '3115'),
  ('http://data.europa.eu/esco/occupation/f7f8c077-26ec-455f-8311-aeafbc24d9a5', 'Conselheiro do Luto', 'Os conselheiros do luto apoiam e orientam os doentes e as suas famílias a lidar melhor com a morte de entes queridos, ajudando-os em situações emergentes, nas unidades de cuidados paliativos e nos serviços fúnebres. Dão formação a outros profissionais e comunidades, antecipando as necessidades de apoio ao luto e dando resposta aos requisitos em matéria de educação.', 'released', '["Conselheiro do Luto", "Conselheira do Luto"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/f817aab2-ec8a-45ec-88ef-c11e0f19fd85', 'Especialista em Política Educativa', 'Os especialistas em política educativa investigam, analisam e desenvolvem políticas de educação e procedem à sua aplicação para melhorar o sistema de ensino existente. Procuram melhorar todos os aspetos da educação que terão impacto nas instituições, como escolas, universidades e escolas profissionais. Trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', '["Especialista em Política de Educação"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/f8304b4c-1220-4979-b2dd-47d2a2f0734a', 'Antiquário', 'Os antiquários vendem artigos antigos em lojas especializadas.', 'released', '["Antiquário", "Antiquária"]'::jsonb, '5223'),
  ('http://data.europa.eu/esco/occupation/f83f19ca-b816-484a-b8be-92b7785121ea', 'Inspetor de Minas', 'Os inspetores de minas supervisionam os sistemas de saúde e segurança em operações mineiras. Comunicam acidentes de trabalho, elaboram estatísticas de acidentes, calculam os riscos para a segurança e a saúde dos trabalhadores e sugerem soluções ou novas medições e técnicas.', 'released', '["Inspetor de Minas", "Inspetora de Minas"]'::jsonb, '3117'),
  ('http://data.europa.eu/esco/occupation/f8438d21-c726-4534-8d7c-1c5aa9ef05ef', 'Técnico de Limpeza de Tapetes e Outros Têxteis', 'Os técnicos de limpeza de tapetes e outros têxteis limpam tapetes e outros têxteis para os seus clientes, através da remoção de manchas, pó ou cheiros. Fazem-no através da aplicação de soluções químicas e repelentes e com a utilização de escovas ou de equipamento mecânico.', 'released', '["Técnica de Limpeza de Tapetes", "Lavador de Carpetes", "Técnico de Limpeza de Tapetes e Outros Têxteis", "Lavadora de Carpetes", "Técnico de Limpeza de Tapetes", "Técnica de Limpeza de Tapetes e Outros Têxteis"]'::jsonb, '9129'),
  ('http://data.europa.eu/esco/occupation/f84aae41-28cc-4aa0-a0df-e7c3030516fd', 'Consultor de Serviços de Encontros', 'Os consultores de serviços de encontros prestam apoio aos clientes na procura e localização de um parceiro e na marcação de um encontro. Prestam aconselhamento personalizado para ajudar os clientes a cumprir os seus objetivos. Trabalham também no ambiente virtual, onde prestam assistência aos usuários em linha na gestão de perfis pessoais, no envio de mensagens e na criação de ligações.', 'released', '["Consultora de Serviços de Encontros", "Consultor de Serviços de Encontros"]'::jsonb, '5169'),
  ('http://data.europa.eu/esco/occupation/f84dbfe2-fa6b-43ef-97f5-54c3ad9c631f', 'Trabalhador de Recepção de Matérias-Primas', 'Os trabalhadores de recepção de matérias-primas utilizam e procedem à manutenção de ferramentas e equipamento para assegurar o cumprimento dos requisitos qualitativos e quantitativos na recepção da matéria-prima. Utilizam equipamento para avaliar produtos, tais como grãos, batatas, raízes de mandioca, etc. Armazenam e distribuem produtos às diferentes unidades de transformação.', 'released', '["Trabalhador de Recepção de Matérias-Primas", "Trabalhadora de Recepção de Matérias-Primas", "Empregada de Recepção de Matérias-Primas", "Empregado de Recepção de Matérias-Primas"]'::jsonb, '4321'),
  ('http://data.europa.eu/esco/occupation/f874980a-e08f-4a58-bc21-2ff3cf472ec5', 'Representante de Serviço de Aluguel de Automóveis e Veículos Ligeiros', 'Os representantes de serviço de aluguer de automóveis e veículos ligeiros são responsáveis pelo aluguer de veículos e pela determinação de períodos específicos de utilização. Documentam as transações, os seguros e os pagamentos.', 'released', '["Representantea de Serviço de Aluguel de Automóveis e Veículos Ligeiros"]'::jsonb, '5249'),
  ('http://data.europa.eu/esco/occupation/f87779ae-7389-44e7-b155-16e87904857e', 'Gemólogo', 'Os gemólogos avaliam pedras preciosas através da análise das suas características, corte e proveniência, quer para fins de comercialização, quer para efeitos de novos trabalhos de polimento. Avaliam as pedras e as gemas para lhes atribuírem um valor de mercado.', 'released', '["Gemólogo", "Gemóloga"]'::jsonb, '3315'),
  ('http://data.europa.eu/esco/occupation/f88124d7-ee7e-4d21-9036-0658b496c119', 'Assistente de Fisioterapia', 'Os assistentes de fisioterapia trabalham sob supervisão, em contextos definidos, utilizando protocolos e procedimentos de tratamento acordados, como a recolha de dados dos utentes e a manutenção dos equipamentos necessários para as intervenções de fisioterapia. A responsabilidade global é do profissional delegante.', 'released', '["Assistentea de Fisioterapia"]'::jsonb, '3255'),
  ('http://data.europa.eu/esco/occupation/f889dcbd-d058-4177-927f-5fe59d044fa6', 'Montador de Instrumentos Musicais Eletrônicos', 'Os montadores de instrumentos musicais eletrônicos criam e montam peças para fabricar instrumentos eletrônicos de acordo com instruções ou diagramas especificados. Instalam e testam dispositivos elétricos de tomada de som, limpam e inspecionam o instrumento acabado.', 'released', '["Montadora de Instrumentos Musicais Eletrônicos", "Montador de Instrumentos Musicais Eletrônicos"]'::jsonb, '8212'),
  ('http://data.europa.eu/esco/occupation/f88fb9dd-5a46-4086-a284-b1992174e55c', 'Gerente de Ótica', 'Os gerentes de ótica assumem a responsabilidade pelas atividades e pelo pessoal em lojas especializadas.', 'released', '["Gerente de Loja de Produtos de Optometria", "Gerente de Loja de Produtos Óticos", "Gerentea de Ótica"]'::jsonb, '1420'),
  ('http://data.europa.eu/esco/occupation/f89b12a1-689f-4a4f-8695-abb620810f1e', 'Professor de Ensino Especial de Escola Primária', 'Os professores de ensino especial de escola primária proporcionam um ensino especialmente concebido para os alunos com uma variedade de deficiências ao nível da escola primária e asseguram que os mesmos atingem o seu potencial de aprendizagem. Alguns professores de ensino especial de escola primária trabalham com crianças com deficiências ligeiras a moderadas, implementando um programa de estudos alterado para responder às necessidades específicas de cada estudante. Outros professores de ensino especial de escola primária assistem e ensinam alunos portadores de deficiência intelectual e autismo, centrando-se no ensino da literacia básica e em competências de vida e sociais. Todos os professores avaliam os progressos dos alunos, tendo em conta os seus pontos fortes e fracos, e comunicam as suas conclusões aos pais, conselheiros, administradores e outras partes envolvidas.', 'released', '["Professora de de Educação Especial Escola Primária", "Professor de de Educação Especial Escola Primária", "Professora de Ensino Especial de Escola Primária"]'::jsonb, '2352'),
  ('http://data.europa.eu/esco/occupation/f8ab2e08-d14e-4938-a2cd-c04821556db7', 'Técnico de Reparações de Bens de Consumo Eletrônicos', 'Os técnicos de reparações de bens de consumo eletrônicos utilizam equipamento elétrico para diagnosticar as anomalias e testar o funcionamento de bens de consumo eletrônicos, tais como televisores, sistemas de vídeo e áudio e câmaras digitais. Leem as instruções dos fabricantes e efetuam as reparações ou substituições necessárias.', 'released', '["Técnico de Reparações de Bens de Consumo Eletrônicos", "Técnica de Reparações de Bens de Consumo Eletrônicos"]'::jsonb, '7421'),
  ('http://data.europa.eu/esco/occupation/f8d14b95-6a36-4290-b226-2342e236406e', 'Editor de Revistas', 'Os editores de revistas decidem sobre as histórias com interesse suficiente para serem publicadas na revista. Nomeiam jornalistas para cada tema tratado. Os editores de revistas determinam a extensão de cada artigo e a parte da revista onde irá figurar. Além disso, asseguram a conclusão pontual das publicações para edição.', 'released', '["Editor de Revistas", "Editora de Revistas"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/f8d1bcf9-9ca1-408f-a713-7bdf28c400fd', 'Técnico de Elevadores', 'Os técnicos de elevadores montam elevadores em caixas de corrida preparadas para o efeito. Instalam o quadro de apoio, a bomba ou o motor, o pistão ou o cabo e o mecanismo do elevador. Os técnicos de elevadores procedem à ligação dos elementos eletrônicos necessários para concluir a instalação e a ligação da cabina do elevador. Também realizam as necessárias inspeções e reparações nos elevadores, bem como no poço e outros componentes eletrônicos conexos. Os técnicos de elevadores asseguram que cada inspeção e elemento a assinalar são registados num livro de registo e informam o cliente sobre o estado do elevador objeto da manutenção.;', 'released', '["Técnico de Elevadores", "Técnica de Elevadores"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/f8d7d59d-242d-4903-9e0d-d2d23a0ef4c3', 'Diretor de Distribuição de Café, Chá, Cacau e Especiarias', 'Os diretores de distribuição de café, chá, cacau e especiarias planificam a distribuição de café, chá, cacau e especiarias a diversos pontos de venda.', 'released', '["Diretora de Distribuição de Café, Chá, Cacau e Especiarias", "Diretor de Distribuição de Café, Chá, Cacau e Especiarias", "Diretora de Logística — Café, Chá, Cacau e Especiarias", "Diretor de Logística — Café, Chá, Cacau e Especiarias"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/f8da6546-0c8a-4bd0-a952-6f3c253c9aba', 'Personal Shopper', 'Os personal shoppers ajudam os clientes individuais a selecionar e comprar artigos de vestuário e outros artigos, tais como presentes, de acordo com os seus gostos pessoais, desejos e estilo.', 'released', NULL, '5223'),
  ('http://data.europa.eu/esco/occupation/f8e435dd-7aa9-4d7a-97c3-b3b5789b6b25', 'Guarda-Costas', 'Os guarda-costas oferecem proteção aos clientes contra ferimentos, ataques e assédio. Acompanham indivíduos como políticos e participantes em diversos eventos e reuniões. Os guarda-costas observam o ambiente circundante, antecipam as ameaças e respondem a situações de emergência em matéria de segurança. Podem transportar e utilizar armas.', 'released', NULL, '5414'),
  ('http://data.europa.eu/esco/occupation/f8e76759-811e-4b39-9adf-3e77429cff8f', 'Sapateiro', 'Os sapateiros utilizam operações manuais ou com máquina para o fabrico tradicional de diversos tipos de calçado. Também reparam todos os tipos de calçado numa oficina de consertos.', 'released', '["Sapateira", "Sapateiro", "Fabricante de Sapatos"]'::jsonb, '7536'),
  ('http://data.europa.eu/esco/occupation/f8f34041-3640-41a9-852e-c5a7574de780', 'Corretor de Provas', 'Os corretores de provas examinam fac-símiles dos produtos acabados, tais como livros, jornais e revistas. Corrigem erros gramaticais, tipográficos e ortográficos a fim de garantir a qualidade do produto impresso.', 'released', '["Revisor de Provas", "Revisora de Provas", "Corretora de Provas"]'::jsonb, '4413'),
  ('http://data.europa.eu/esco/occupation/f9116001-8cf5-453c-af51-3adaef7841ef', 'Operador de Máquinas de Pré-Montagem de Calçado', 'Os operadores de máquinas de pré-montagem de calçado utilizam as ferramentas e o equipamento de colocação de contrafortes, moldar biqueiras, e outras ações necessárias para montagem das gáspeas do calçado sobre a forma. Fazem preparativos para a construção colada da montagem, fixando a palmilha, inserindo o contraforte, o molde posterior e condicionando as gáspeas antes da montagem.', 'released', '["Operador de Máquinas de Pré-Montagem de Calçado", "Operadora de Máquinas de Pré-Montagem de Calçado"]'::jsonb, '8156'),
  ('http://data.europa.eu/esco/occupation/f9395e4d-d66f-49ce-a8f5-721991139e79', 'Terapeuta Recreativo', 'Os terapeutas recreativos prestam tratamento a pessoas com perturbações ou distúrbios comportamentais. Utilizam técnicas e intervenções como arte, música, animais e dança para promover, manter e restaurar o desenvolvimento e a saúde do doente.', 'released', '["Terapeuta Recreativo", "Terapeuta Psicomotor", "Terapeuta Recreativa", "Psicomotricista", "Terapeuta Psicomotora"]'::jsonb, '2269'),
  ('http://data.europa.eu/esco/occupation/f9433fdb-dde1-46cf-9e91-b49d243946a7', 'Engenheiro Biológico', 'Os engenheiros biológicos combinam as descobertas mais recentes no domínio da biologia com a lógica de engenharia, a fim de desenvolver soluções destinadas a melhorar o bem-estar da sociedade. Podem desenvolver sistemas para a melhoria da conservação dos recursos naturais, da agricultura, da produção alimentar, da modificação genética e da utilização econômica.', 'released', '["Engenheira Biológica", "Engenheiro Biológico", "Engenheira Biológico"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/f96e3735-405c-4ca9-8a86-d37f64ea7164', 'Fabricante de Instrumentos de Sopro', 'Os fabricantes de instrumentos de sopro criam e montam peças para fabricar instrumentos de sopro, de acordo com instruções e diagramas especificados. Medem e cortam a tubagem do ressoador, montam peças, tais como abraçadeiras, varas, válvulas, pistões, embocaduras e boquilhas, testam e inspecionam o instrumento acabado.', 'released', '["Fabricantea de Instrumentos de Sopro"]'::jsonb, '7312'),
  ('http://data.europa.eu/esco/occupation/f97dedb0-da68-4fc3-8bcc-3f4025ccacd3', 'Especialista em Import-Export de Couros, Peles e Produtos do Couro', 'Os especialistas em import-export de couros, peles e produtos do couro possuem e aplicam conhecimentos profundos sobre importação e exportação de mercadorias, incluindo sobre desalfandegamento e documentação.', 'released', '["Especialista em Import-Export de Couros, Peles e Produtos do Couro"]'::jsonb, '3331'),
  ('http://data.europa.eu/esco/occupation/f9cbdeb4-1559-4d45-b2d7-edf8aebe400b', 'Supervisor de Qualidade na Aquicultura', 'Os supervisores de qualidade na aquicultura estabelecem normas e políticas para o controlo da qualidade da produção de organismos aquáticos. Testam e inspecionam os efetivos de acordo com os princípios de análise de perigos e pontos críticos de controlo (HACCP) e com a regulamentação em matéria de segurança.', 'released', '["Supervisora de Qualidade na Aquicultura", "Supervisor de Qualidade na Aquicultura"]'::jsonb, '3142'),
  ('http://data.europa.eu/esco/occupation/fa1aef45-49a4-4446-94b4-e2b563d9d025', 'Assistente de Bordo de Trem', 'Os assistentes de bordo de comboio trabalham nos comboios para prestar serviços aos passageiros, tais como acolher os passageiros, responder às suas perguntas e servir refeições.', 'released', '["Assistentea de Bordo de Trem"]'::jsonb, '5111'),
  ('http://data.europa.eu/esco/occupation/fa30c1cb-dbc5-409c-8124-7284592b123c', 'Arborista', 'Os arboristas procedem à manutenção das árvores. Utilizam maquinaria pesada para podar cortar as árvores. Os arboristas são frequentemente obrigados a subir às árvores para realizarem a manutenção.', 'released', '["Arboricultor", "Arboricultora"]'::jsonb, '6113'),
  ('http://data.europa.eu/esco/occupation/fa32eb3f-5c9f-4668-8f85-5eefb3badab8', 'Assessor Florestal', 'Os assessores florestais prestam serviços e aconselhamento sobre questões econômicas e ambientais relacionadas com a gestão da madeira e da floresta, em conformidade com a legislação e a regulamentação.;', 'released', '["Engenheiro Florestal", "Consultor Florestal", "Assessor Florestal", "Assessora Florestal", "Engenheira Florestal", "Consultora Florestal"]'::jsonb, '2132'),
  ('http://data.europa.eu/esco/occupation/fa3fde92-f773-4381-9ae6-8e23d7334cd4', 'Montador de Carroçaria de Veículos', 'Os montadores de carroçaria de veículos montam peças e componentes da carroçaria de veículos, tais como quadros, portas, chassi e capôs. Utilizam ferramentas manuais, ferramentas elétricas e outros equipamentos, tais como máquinas CNC ou robôs. Interpretam planos técnicos e utilizam equipamento automatizado de montagem para construir carroçarias de veículos. Inspecionam as peças individuais para detectar eventuais avarias e verificam a qualidade das montagens, para garantir que as normas são cumpridas e as especificações são respeitadas. Os montadores de carroçaria de veículos comunicam todas as questões de montagem ao respetivo supervisor.', 'released', '["Ajustadora de Motores de Veículos", "Ajustador de Motores de Veículos", "Montadora de Veículos", "Montador de Carroçaria de Veículos", "Montadora de Carroçaria de Veículos", "Montador de Veículos"]'::jsonb, '8211'),
  ('http://data.europa.eu/esco/occupation/fa404a79-4091-47f9-a635-c2e3c576ece8', 'Coordenador Portuário', 'Os coordenadores portuários gerem operações de divisão de tráfego para as autoridades portuárias. Aplicam regras e regulamentos, tais como a atracagem de navios, o manuseamento e armazenamento de carga e a utilização de instalações portuárias. Dirigem as atividades de policiamento e de limpeza da zona portuária, das ruas, dos edifícios e das águas. Os coordenadores portuários também asseguram que as atividades relativas às receitas são documentadas e submetidas à divisão contabilística. Aconselham as autoridades portuárias sobre as taxas e revisões das tarifas portuárias e solicitam às empresas de navegação que utilizem as instalações portuárias. Dirigem as atividades relacionadas com a compilação de estatísticas diárias e anuais dos navios e da carga.', 'released', '["Coordenador Portuária", "Coordenadora Portuária", "Coordenadora Portuário"]'::jsonb, '4323'),
  ('http://data.europa.eu/esco/occupation/fa4a3b52-990c-44eb-a912-490f5d689400', 'Pedagogo Social', 'Os pedagogos sociais prestam cuidados, apoio e educação às crianças e aos jovens com origens ou capacidades diferentes. Desenvolvem processos educativos para que os jovens sejam responsáveis pelas suas próprias experiências, utilizando uma abordagem multidisciplinar definida para a experiência de aprendizagem. Os pedagogos sociais contribuem para a aprendizagem, o bem-estar e a inclusão social dos indivíduos, privilegiando o reforço da autoconfiança.', 'released', '["Pedagogo Social", "Pedagoga Social"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/fa5b9075-3796-4e86-be0a-b5e6d725c25a', 'Metrologista', 'Os metrologistas estudam e praticam a ciência da medição. Desenvolvem sistemas de quantidade, unidades de medida e métodos de medição a utilizar na ciência. Os metrologistas estabelecem novos métodos e instrumentos para quantificar e compreender melhor a informação.', 'released', NULL, '2112'),
  ('http://data.europa.eu/esco/occupation/fa6bd9e9-9631-4abe-b2f8-fad7bf8a819d', 'Diretor de Centro de Atividades de Tempos Livres', 'Os diretores de centro de atividades de tempos livres prestam serviços sociais às crianças e às suas famílias. Supervisionam e apoiam os serviços de acolhimento de crianças e gerem as estruturas de acolhimento de crianças. Os diretores de centro de atividades de tempos livres são responsáveis pela liderança estratégica e operacional e pela gestão das equipes e recursos do pessoal no âmbito de cada serviço de acolhimento de crianças e transversalmente.', 'released', '["Diretora de Centro de Atividades de Tempos Livres", "Diretor de Centro de Atividades de Tempos Livres"]'::jsonb, '1341'),
  ('http://data.europa.eu/esco/occupation/fab474ea-a4a9-4c11-9548-1d50ad594a34', 'Consultor de Gestão e Conservação de Recursos Naturais', 'Os consultores de gestão e conservação de recursos naturais prestam aconselhamento sobre a proteção e a gestão de recursos naturais, nomeadamente a fauna, a flora, o solo e a água, às empresas e às autoridades que exploram esses recursos. Procuram orientar as empresas para uma política adequada de exploração dos recursos naturais em contextos industriais, sensibilizam para problemas de saúde e asseguram a conservação dos ecossistemas para intervenções sustentáveis em habitats naturais.', 'released', '["Consultor de Gestão e Conservação de Recursos Naturais", "Consultora de Gestão e Conservação de Recursos Naturais"]'::jsonb, '2133'),
  ('http://data.europa.eu/esco/occupation/fad4abdf-fe1b-4751-8253-aef40b49afe0', 'Técnico de Dessalinização', 'Os técnicos de dessalinização operam, monitorizam e efetuam a manutenção de equipamento de instalações de dessalinização. Asseguram o cumprimento da regulamentação e dos requisitos em matéria de saúde e segurança.', 'released', '["Técnica de Dessalinização", "Técnico de Dessalinização"]'::jsonb, '3117'),
  ('http://data.europa.eu/esco/occupation/fadb09c5-db84-4240-9fd6-68b4c0abeed5', 'Agente de Câmbio', 'Os agentes de câmbio compram e vendem divisas em nome dos seus clientes com o objetivo de obterem lucro em resultado das flutuações das taxas de câmbio. Realizam análises técnicas de informações econômicas, como a liquidez e volatilidade do mercado, para preverem as taxas futuras das divisas no mercado cambial.', 'released', '["Agentea de Câmbio"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/fae51298-03a8-4df4-829a-685dddc1580e', 'Chefe de Serviço de Quartos', 'Os chefes de serviço de quartos são responsáveis pela supervisão e coordenação do funcionamento diário das atividades de limpeza e de serviço de quartos dos hotéis.', 'released', '["Encarregado de Andar", "Governante de Andares", "Encarregada de Andar", "Governanta de Andares", "Chefea de Serviço de Quartos"]'::jsonb, '5151'),
  ('http://data.europa.eu/esco/occupation/faed05c0-c1d1-4e34-b575-0dea96459e56', 'Diretor de Fiscalização de Obra', 'Os diretores de fiscalização de obra são responsáveis pelo planejamento e coordenação dos projetos de construção. Proporcionam conhecimentos especializados na fase de concepção dos projetos de construção, facilitando uma melhor estimativa dos custos e das implicações funcionais. Participam nos processos de apresentação de propostas para projetos de construção e lidam com os subcontratantes para realizar as diferentes fases do processo de construção desde o início até à sua conclusão. Procuram aumentar o valor dos projetos, melhorando a eficiência e criando valor para os clientes.', 'released', '["Diretor de Obra", "Diretora de Fiscalização de Obra", "Diretora de Obra", "Diretor de Fiscalização de Obra"]'::jsonb, '1323'),
  ('http://data.europa.eu/esco/occupation/faed411a-f920-4100-86a8-b877928b429c', 'Analista de Experiência do Usuário', 'Os analistas de experiência do usuário avaliam a interação e a experiência dos clientes e analisam os comportamentos, as atitudes e as emoções dos usuários relativamente à utilização de um determinado produto, sistema ou serviço. Apresentam propostas para melhorar a interface e a capacidade de utilização dos produtos, sistemas ou serviços. Para tal, têm em consideração aspectos relacionados com a prática, a experiência, a afetividade, o significado e o valor da interação homem-computador e da propriedade dos produtos, bem como a percepção do indivíduo relativamente aos aspectos do sistema, como a utilidade, a facilidade de utilização e a eficiência, e a dinâmica da experiência do usuário.', 'released', '["Analista de Experiência do Usuário", "Analista de Usabilidade"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/fb022de4-920a-4eb0-80f9-fbb8ecfc36b1', 'Gestor de Arquivos Culturais', 'Os gestores de arquivos culturais asseguram o cuidado e a preservação de uma instituição cultural e dos seus arquivos. Asseguram a gestão e o desenvolvimento dos ativos e das coleções da instituição, incluindo a digitalização das coleções de arquivo.;', 'released', '["Diretor do Arquivo", "Diretor-Geral do Livro, dos Arquivos e das Bibliotecas", "Diretora do Arquivo", "Diretora-Geral do Livro, dos Arquivos e das Bibliotecas", "Gerente", "Gestora de Arquivos Culturais"]'::jsonb, '2621'),
  ('http://data.europa.eu/esco/occupation/fb0c7da2-6d0e-4a3f-be3e-344f58f0e82d', 'Professor de Línguas Modernas do Ensino Secundário', 'Os professores de Línguas Modernas do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, as Línguas Modernas. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio das Línguas Modernas através da atribuição de trabalhos, testes e exames.', 'released', '["Professor de Francês do Ensino Secundário", "Professora de Línguas Modernas do Ensino Secundário", "Professor de Inglês do Ensino Secundário", "Professora de Alemão do Ensino Secundário", "Professor de Alemão do Ensino Secundário", "Professor de Espanhol do Ensino Secundário", "Professora de Francês do Ensino Secundário", "Professor de Línguas Modernas do Ensino Secundário", "Professora de Espanhol do Ensino Secundário", "Professora de Inglês do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/fb18dfef-2b90-4219-8b39-a5fcddb8f238', 'Operário de Serviços de Drenagem', 'Os operários de serviços de drenagem procedem à instalação e manutenção de sistemas de drenagem e de esgotos. Colocam tubos ou algerozes para secar o solo de uma determinada estrutura, para conter a água subterrânea iminente. Este trabalho é geralmente realizado sob os pavimentos e nas caves.', 'released', '["Operária de Serviços de Drenagem", "Operário de Serviços de Drenagem"]'::jsonb, '9312'),
  ('http://data.europa.eu/esco/occupation/fb1a7aab-1e33-4712-b8e0-d335243aba58', 'Croupier', 'Os croupiers operam jogos de mesa. Está de pé atrás da mesa e exploram jogos de fortuna ou azar através da distribuição do número adequado de cartões aos jogadores ou utilizam outros equipamentos de jogo. Também distribuem prémios ou recolhem dinheiro ou fichas dos jogadores.', 'released', NULL, '4212'),
  ('http://data.europa.eu/esco/occupation/fb3f5f35-e6f7-4168-aef2-e4dfb7f2a3ee', 'Técnico de Geologia', 'Os técnicos de geologia prestam assistência em todas as atividades levadas a cabo pelos geólogos. Sob a supervisão de geólogos, recolhem materiais, investigam e estudam as amostras colhidas da Terra. Os técnicos de geologia ajudam a determinar o valor das terras para a exploração de petróleo ou de gás. Realizam várias atividades técnicas, incluindo a recolha de amostras durante levantamentos geoquímicos, o trabalho em locais de perfuração e a participação em levantamentos geofísicos e estudos geológicos.;', 'released', '["Técnica de Geologia", "Técnico de Geologia"]'::jsonb, '3111'),
  ('http://data.europa.eu/esco/occupation/fb4819db-03fa-4dc1-a471-2cdc24dcbe6f', 'Aplicador de Revestimentos de Superfície', 'Os aplicadores de revestimentos de superfície aplicam produtos químicos e pintura à superfície do material para proteger contra a corrosão. Calculam os materiais necessários para a proteção da superfície.', 'released', '["Aplicadora de Revestimentos Anticorrosão", "Aplicador de Revestimentos Anticorrosão", "Aplicador de Revestimentos de Superfície", "Aplicadora de Revestimentos de Superfície"]'::jsonb, '7132'),
  ('http://data.europa.eu/esco/occupation/fb6df00f-4810-442b-8f93-89b9580c7c9f', 'Polidor de Mobiliário', 'Os polidores de mobiliário tratam da superfície do mobiliário de madeira, utilizando ferramentas manuais e elétricas, para lixar, limpar e polir. Aplicam revestimentos para madeira em superfícies de madeira, utilizando técnicas diferentes, tais como a escovagem ou a utilização de uma pistola de pulverização. Escolhem e aplicam os revestimentos adequados com fins protetores e/ou decorativos.', 'released', '["Polidor de Mobiliário", "Polidora de Mobiliário"]'::jsonb, '7522'),
  ('http://data.europa.eu/esco/occupation/fb7e2f4f-1545-42f1-972e-94082e49c6dc', 'Operário da Construção de Edifícios', 'Os operários da construção de edifícios procedem à preparação e manutenção de atividades de construção de edifícios em estaleiros de construção. Realizam trabalhos de preparação e limpeza para auxiliar os operários da construção especializados.', 'released', '["Operário da Construção de Edifícios", "Operária da Construção de Edifícios"]'::jsonb, '9313'),
  ('http://data.europa.eu/esco/occupation/fbc9ab3e-18f1-4b7b-8cd5-d6374ed5e9a9', 'Professor de Línguas Clássicas', 'Os professores de Línguas Clássicas são professores universitários ou docentes em geral que lecionam a alunos com um diploma do ensino secundário o seu próprio domínio de estudos especializado, as Línguas Clássicas, que é predominantemente de natureza académica. Trabalham com os seus assistentes académicos e de investigação na preparação de aulas e exames, na classificação de estudos e exames e na realização de sessões de informação e de feedback para os alunos. Realizam também investigação académica no seu domínio das Línguas Clássicas, publicam as suas conclusões e mantêm contatos com os seus colegas académicos.', 'released', '["Professora de Latim", "Professor Universitário de Latim", "Professor de Línguas Clássicas", "Professor Universitário de Grego", "Professor de Grego", "Professora de Línguas Clássicas", "Professor Universitário de Línguas Clássicas", "Professora Universitária de Grego", "Professora de Grego", "Professor de Latim", "Professora Universitária de Línguas Clássicas", "Professora Universitária de Latim"]'::jsonb, '2310'),
  ('http://data.europa.eu/esco/occupation/fbceeac6-798b-4307-a825-626707a753ad', 'Engenheiro Especialista em Cálculos', 'Os engenheiros especialistas em cálculos retiram conclusões sobre sistemas reais, como a solidez, a estabilidade e a durabilidade, através da realização de experiências em modelos virtuais. Também testam os processos de produção.', 'released', '["Engenheira Especialista em Cálculos", "Engenheiro Especialista em Cálculos"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/fbf23c18-d9a3-4349-83dc-2bc39948bdf7', 'Colhedor em Aquicultura', 'Os colhedores em aquicultura trabalham na colheita de organismos aquáticos cultivados em processos de engorda em terra.', 'released', '["Colhedor em Aquicultura", "Colhedora em Aquicultura"]'::jsonb, '9216'),
  ('http://data.europa.eu/esco/occupation/fbf3aefb-70ff-440b-8724-bac3ed5e2c93', 'Técnico de Silvicultura', 'Os técnicos de silvicultura prestam assistência e apoio aos responsáveis pelas operações florestais e aplicam as suas decisões. Supervisionam uma equipe de operadores de equipamento florestal e apoiam e supervisionam a proteção das florestas e do ambiente através da investigação e da recolha de dados. Gerem igualmente planos de conservação dos recursos e de colheita.', 'released', '["Supervisora de Operações Florestais", "Supervisora de Operação Florestal", "Supervisor de Operações Florestais", "Responsável Pelas Operações Florestais", "Supervisor de Operação Florestal", "Técnica de Silvicultura"]'::jsonb, '3143'),
  ('http://data.europa.eu/esco/occupation/fc1da244-880f-407d-bfa7-789a2f468ea0', 'Treinador de Animais', 'Os treinadores de animais treinam os animais e/ou os instrutores de animais para fins gerais e específicos, incluindo assistência, segurança, competição, transporte, obediência e lida diária, entretenimento e educação, em conformidade com a legislação nacional.', 'released', '["Treinadora de Animais", "Treinador de Animais"]'::jsonb, '5164'),
  ('http://data.europa.eu/esco/occupation/fc35b7ca-ecec-40d7-91b5-5065f662d955', 'Diretor de Aeroporto', 'Os diretores de aeroporto supervisionam um grupo de diretores que dirigem ou supervisionam uma área específica do aeroporto, de um programa ou de um projeto.', 'released', '["Diretora de Operações de Aeroporto", "Diretor Financeiro", "Diretora de Aeroporto", "Diretor de Aeroporto", "Diretora de Segurança Aeroportuária", "Diretora de Aeródromo", "Diretor de Operações de Aeroporto", "Diretor de Segurança Aeroportuária", "Diretora Financeira", "Diretor de Aeródromo"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/fc81b573-e0ea-4466-8560-c2bb278c314a', 'Operador de Futuros', 'Os operadores de futuros exercem atividades diárias de negociação no mercado de futuros através da compra e venda de contratos de futuros. Especulam sobre a direção dos contratos de futuros, tentando obter lucros com a compra de contratos de futuros relativamente aos quais preveem o aumento do preço e a venda de contratos cujas previsões apontam para uma queda do preço.', 'released', '["Operador de Futuros", "Trader de Futuros", "Operadora de Futuros"]'::jsonb, '3311'),
  ('http://data.europa.eu/esco/occupation/fc85156e-4f0b-46c4-ba66-a3b17318d932', 'Conselheiro de Vida', 'Os conselheiros de vida ajudam os clientes a definir objetivos claros para o seu desenvolvimento pessoal e ajudam-nos a atingir os seus objetivos e visão pessoal. Prestam aconselhamento e orientação e elaboram relatórios de progresso, a fim de acompanhar as realizações dos seus clientes.', 'released', '["Conselheira de Vida", "Life Coach", "Coach", "Conselheiro de Vida"]'::jsonb, '3412'),
  ('http://data.europa.eu/esco/occupation/fc9a86ec-7ad5-4ccb-a08f-1e369197e14a', 'Montador de Produtos em Cartão', 'Os montadores de produtos em cartão constroem os componentes ou peças fabricados em cartão em conformidade com procedimentos estritamente previstos. Montam produtos, tais como tubos, bobinas, caixas de cartão, pratos de papel e painéis.', 'released', '["Montadora de Produtos em Cartão", "Montador de Produtos em Cartão"]'::jsonb, '8143'),
  ('http://data.europa.eu/esco/occupation/fcaab37b-ada2-4832-a2fd-9d64362e0280', 'Coordenador de Intercâmbio Internacional de Estudantes', 'Os coordenadores de intercâmbio internacional de estudantes conduzem todo o processo de um programa de intercâmbio internacional para os estudantes de intercâmbio. Gerem os pedidos e candidaturas dos estudantes, organizam o alojamento, num campus universitário ou com famílias de acolhimento, e tratam de toda a burocracia relativa a estas atividades, incluindo as habilitações e a partida oficial do estudante. Funcionam como guias para os (jovens) estudantes internacionais através da sua adaptação cultural.', 'released', '["Coordenadora de Intercâmbio Internacional de Estudantes", "Coordenador de Intercâmbio Internacional de Estudantes"]'::jsonb, '3343'),
  ('http://data.europa.eu/esco/occupation/fcab4bb1-c05b-43e3-98d8-f60b13c152f2', 'Operador de Coagulação de Borracha', 'Os operadores de coagulação de borracha controlam as máquinas de coagulação do látex de borracha sintética numa pasta de aglomerado de borracha. Preparam os fragmentos de borracha para os processos de acabamento. Os operadores de coagulação de borracha analisam o aspeto dos fragmentos e ajustam a operação dos filtros, dos filtros de agitação e do moinho de martelos para remover a humidade dos fragmentos de borracha.', 'released', '["Operadora de Coagulação de Borracha", "Operador de Coagulação de Borracha"]'::jsonb, '8141'),
  ('http://data.europa.eu/esco/occupation/fcbb66f5-843b-4152-9ce4-e7b19c2a88d9', 'Engenheiro Mecânico de Minas', 'Os engenheiros mecânicos da minas supervisionam o fornecimento, a instalação, a remoção e a manutenção de equipamento mecânico de extração mineira, utilizando o seu conhecimento das especificações mecânicas. Organizam a substituição e a reparação de equipamentos e componentes mecânicos.', 'released', '["Engenheira Mecânica de Minas", "Engenheiro Mecânico de Minas", "Engenheira Mecânico de Minas"]'::jsonb, '2144'),
  ('http://data.europa.eu/esco/occupation/fccecd5d-ad90-41a8-bb89-96d7595abca3', 'Ferreiro', 'Os ferreiros aquecem metal, geralmente aço, numa forja e dão-lhe forma com um martelo, cinzel e bigorna. Por outro lado, criam predominantemente produtos de metal artesanais, incluindo trabalhos ornamentais, bem como ferraduras, um dos únicos processos de fabricação de metais que não foi industrializado.', 'released', '["Ferreira", "Ferreiro"]'::jsonb, '7221'),
  ('http://data.europa.eu/esco/occupation/fcf9024e-277c-43c7-8ec8-8903e5c9c576', 'Engenheiro Hídrico', 'Os engenheiros hídricos investigam e desenvolvem métodos para o fornecimento de água potável, o tratamento de águas e a prevenção e reação aos danos causados pelas inundações. Investigar necessidades de água num local e desenvolvem métodos para satisfazer essas necessidades, tais como a concepção e o desenvolvimento de projetos de gestão de recursos hídricos, como estações de tratamento, condutas, sistemas de bombas, sistemas de irrigação ou drenagem e outros sistemas de abastecimento de água. Os engenheiros hídricos asseguram também a instalação adequada destes sistemas nos estaleiros de construção. Os engenheiros hídricos também mantêm, reparam e constroem estruturas de controlo dos recursos hídricos, como pontes, canais e barragens.', 'released', '["Engenheiro Hídrica", "Engenheiro Hidráulico", "Engenheira Hidráulica", "Engenheira Hídrica", "Engenheira Hídrico"]'::jsonb, '2142'),
  ('http://data.europa.eu/esco/occupation/fd00e4bb-dcee-41d7-81d3-2cdebad8fe70', 'Diretor de Importação e Exportação de Produtos Químicos', 'Os diretores de importação e exportação de produtos químicos implementam e mantêm procedimentos de comércio transfronteiriço, coordenando as partes internas e externas.', 'released', '["Diretora de Vendas de Produtos Químicos", "Diretor de Importação e Exportação de Produtos Químicos", "Diretor de Vendas de Produtos Químicos", "Diretora de Importação e Exportação de Produtos Químicos"]'::jsonb, '1324'),
  ('http://data.europa.eu/esco/occupation/fd0801c9-809a-4cfd-98ed-6c5860c163f2', 'Escriturário de Instituições de Investimento', 'Os escriturários de instituições de investimento prestam assistência na administração de investimentos, tais como ações, obrigações ou outros valores mobiliários, e desempenham tarefas administrativas gerais no setor do investimento de uma empresa financeira.', 'released', '["Escriturária de Instituições de Investimento", "Escriturário de Instituições de Investimento"]'::jsonb, '4312'),
  ('http://data.europa.eu/esco/occupation/fd1c0f5a-f465-4067-af54-621e68c90f74', 'Modista de Chapéus', 'As modistas de chapéus concebem e fabricam chapéus e outros enfeites para a cabeça.', 'released', '["Estilista de Chapéus"]'::jsonb, '7531'),
  ('http://data.europa.eu/esco/occupation/fd1c4e94-25aa-4020-b0ef-0cf5aaf2e4d2', 'Intermediário de Aprovisionamento no Setor Têxtil', 'Os comerciantes de aprovisionamento têxtil coordenam os esforços para os produtores têxteis, desde a fibra até aos produtos finais. O aprovisionamento envolve o processo de pesquisa, avaliação e localização de fornecedores de têxteis através de uma prospeção cuidadosa.', 'released', '["Técnico de Merchandising de Têxteis", "Intermediário de Aprovisionamento no Setor Têxtil", "Técnica de Merchandising de Têxteis", "Intermediária de Aprovisionamento no Setor Têxtil", "Técnico de Marketing", "Técnica de Marketing"]'::jsonb, '3323'),
  ('http://data.europa.eu/esco/occupation/fd1c83b3-60d5-4a5f-86c5-94dc2842c246', 'Engenheiro Projetista de Circuitos Integrados', 'Os engenheiros projetistas de circuitos integrados elaboram a configuração dos circuitos integrados, de acordo com os princípios da engenharia eletrônica. Utilizam software para criar esquemas e diagramas de concepção.', 'released', '["Engenheira Projetista de Circuitos Integrados", "Engenheira Especialista em Concepção de Circuitos Integrados", "Engenheiro Especialista em Concepção de Circuitos Integrados", "Engenheiro Projetista de Circuitos Integrados"]'::jsonb, '2152'),
  ('http://data.europa.eu/esco/occupation/fd2dd3e9-498f-490f-8589-8c1eea05aa3f', 'Operador de Puncionadora', 'Os operadores de puncionadora instalam e cuidam de puncionadoras para cortar as peças na forma desejada, através da propulsão de um êmbolo hidráulico para produzir orifícios nas mesmas com um só molde que empurra através do ponto morto superior, através da superfície, e para o ponto morto inferior da peça.', 'released', '["Operadora de Puncionadora", "Operador de Puncionadora"]'::jsonb, '7223'),
  ('http://data.europa.eu/esco/occupation/fd4b90ed-6bb4-447e-b13a-afb8015700b3', 'Especialista em Vendas de Energia Solar', 'Os especialistas em vendas de energia solar prestam aconselhamento em matéria de energia solar para fins domésticos ou industriais e procuram promover a utilização da energia solar como fonte de energia alternativa e mais sustentável. Comunicam com potenciais clientes e participam em eventos em rede, a fim de assegurarem o acréscimo das vendas de produtos de energia solar.', 'released', '["Sales"]'::jsonb, '2433'),
  ('http://data.europa.eu/esco/occupation/fd6a1c18-b0ff-419f-a36a-e05957452d55', 'Operador de Estação de Incineração de Resíduos Sólidos', 'Os operadores de estações de incineração de resíduos sólidos operam e efetuam a manutenção dos equipamentos de tratamento e distribuição de resíduos sólidos e testam amostras para monitorizar a poluição. Prestam assistência na recolha e eliminação de resíduos sólidos, como o entulho de trabalhos de construção e demolição, e asseguram a conformidade do tratamento com a regulamentação em matéria de segurança. Asseguram que os contentores de resíduos de uso comunitário são esvaziados, garantem a diferenciação adequada entre os resíduos que necessitam de ser reciclados ou eliminados e monitorizam os equipamentos.', 'released', '["Operador de Estação de Incineração de Resíduos Sólidos", "Operadora de Estação de Incineração de Resíduos Sólidos"]'::jsonb, '3132'),
  ('http://data.europa.eu/esco/occupation/fd86ebe1-bad4-4486-9b76-01a48030e49a', 'Eletricista Ferroviário', 'Os eletricistas ferroviários procedem à instalação, manutenção e reparação de sistemas elétricos e eletrônicos nos veículos ferroviários, tais como sistemas de ar condicionado, lâmpadas, sistemas de aquecimento, cablagem elétrica, etc. Utilizam equipamento de teste de diagnóstico para inspecionar os veículos e encontrar falhas. Para realizar o trabalho de reparação, utilizam ferramentas manuais e instrumentos e máquinas elétricos especializados.', 'released', '["Eletricista Ferroviária", "Eletricista Ferroviário"]'::jsonb, '7412'),
  ('http://data.europa.eu/esco/occupation/fd882949-aad7-42ff-825e-00d49a5ec469', 'Comerciante Grossista de Fruta e Hortaliças', 'Os comerciantes grossistas de fruta e produtos hortícolas investigam potenciais compradores e fornecedores grossistas e atendem às suas necessidades. Concluem transações que envolvem grandes quantidades de mercadorias.', 'released', '["Comerciantea Grossista de Fruta e Hortaliças"]'::jsonb, '3324'),
  ('http://data.europa.eu/esco/occupation/fd8b68c0-7341-44bb-855d-9b1254eade33', 'Clarividente', 'Os clarividentes alegam ter talentos extrassensoriais para recolher informações e conhecimentos sobre a vida, os acontecimentos ou as situações das pessoas. Prestam aconselhamento aos clientes sobre temas importantes para os mesmos, tais como a saúde, o dinheiro e o amor. Os clarividentes trabalham frequentemente com práticas tradicionais, tais como a leitura de cartas de tarot, a leitura das mãos ou a utilização de mapas astrológicos. ;', 'released', '["Quiromante", "Cartomante", "Taróloga", "Tarólogo", "Clarividentea"]'::jsonb, '5161'),
  ('http://data.europa.eu/esco/occupation/fdb16700-109e-4d02-949e-3213f278df93', 'Diretor de Qualidade Industrial', 'Os diretores de qualidade industrial acompanham e controlam os ativos de informação, especificando os processos e os procedimentos destinados a garantir a conformidade com as normas industriais. Realizam auditorias em processos industriais, aconselham sobre ações preventivas e corretivas e asseguram a conformidade com as normas industriais.', 'released', '["Diretor de Qualidade Industrial", "Diretora de Qualidade Industrial"]'::jsonb, '1321'),
  ('http://data.europa.eu/esco/occupation/fdc8adfb-1807-4146-98ae-3a26fbe19996', 'Técnico de Minas e Armadilhas', 'Os técnicos de minas e armadilhas perscrutam áreas utilizando equipamento especial, como detetores de metais, ou utilizando animais treinados, para detectar a presença de minas e armadilhas terrestres, e removem os materiais explosivos em conformidade com as normas de segurança. Após a procura e a localização das minas e armadilhas, desarmam-nas para evitar qualquer risco de detonação e asseguram que a área se encontra desimpedida antes dos processos de desarme e remoção.', 'released', '["Especialista de Minas e Armadilhas", "Técnica de Minas e Armadilhas", "Técnico de Minas e Armadilhas"]'::jsonb, '0310'),
  ('http://data.europa.eu/esco/occupation/fdd8eef7-d89c-419f-9166-0747f466a769', 'Crítico', 'Os críticos redigem críticas sobre obras literárias, musicais e artísticas, restaurantes, filmes, programas de televisão e outros temas para jornais, revistas especializadas, rádio, televisão e outros meios de comunicação social. Avaliam o tema, a expressão e a técnica. Os críticos tomam decisões com base na sua experiência e conhecimentos pessoais.', 'released', '["Crítica", "Crítico"]'::jsonb, '2642'),
  ('http://data.europa.eu/esco/occupation/fddb7bd8-f176-4dc8-9d12-32b6072452c9', 'Técnico de Contadores Elétricos', 'Os técnicos de contadores elétricos procedem à instalação e manutenção de sistemas de contadores elétricos em instalações ou edifícios. Instalam o equipamento em conformidade com os regulamentos e reparam falhas e outros problemas. Testam o equipamento e aconselham sobre a utilização e os cuidados a ter.', 'released', '["Técnico de Contadores Elétricos", "Técnica de Contadores Elétricos"]'::jsonb, '7411'),
  ('http://data.europa.eu/esco/occupation/fde4372d-8293-42de-afbb-8b5a9b274fe7', 'Engenheiro de Aplicações', 'Os engenheiros de aplicações lidam com os requisitos técnicos, a gestão e a concepção para o desenvolvimento de várias aplicações de engenharia, tais como sistemas, a concepção de novos produtos ou a melhoria dos processos. São responsáveis pela aplicação de uma melhoria da concepção ou do processo, fornecem apoio técnico quanto aos produtos, respondem a perguntas sobre a funcionalidade técnica e ajudam a equipe de vendas.', 'released', '["Engenheiro de Aplicações", "Engenheira de Aplicações"]'::jsonb, '2149'),
  ('http://data.europa.eu/esco/occupation/fde97584-d8e3-413e-a662-511c9055357e', 'Operador de Live Chat', 'Os operadores de live chat respondem às respostas e aos pedidos apresentados pelos clientes de toda a natureza através de plataformas em linha em sites e serviços de assistência em linha em tempo real. Estão disponíveis para prestar serviços através de plataformas de chat em linha e têm a capacidade de resolver questões de clientes apenas através de comunicação escrita.', 'released', '["Operador de Live Chat", "Operadora de Live Chat"]'::jsonb, '4222'),
  ('http://data.europa.eu/esco/occupation/fdf7b000-d923-4086-9660-eb8ee5e77ef0', 'Especialista em Política Esportiva', 'Os especialistas em política desportiva investigam, analisam e desenvolvem políticas no setor do desporto e da recreação e procedem à sua aplicação, com vista à melhoria do sistema desportivo e recreativo e da saúde da população. Procuram aumentar a participação em atividades desportivas, apoiar os atletas, melhorar o desempenho dos atletas em competições nacionais e internacionais e aumentar a inclusão social e o desenvolvimento da comunidade. Trabalham em estreita colaboração com parceiros, organizações externas ou outras partes interessadas e disponibilizam-lhes atualizações periódicas.', 'released', NULL, '2422'),
  ('http://data.europa.eu/esco/occupation/fdfce14e-992d-4ff4-9f9d-7a353c75654e', 'Advogado de Empresa', 'Os advogados de empresas prestam serviços de consultoria e representação jurídicas a empresas e organizações. Prestam aconselhamento sobre questões relacionadas com impostos, direitos legais e patentes, comércio internacional, marcas comerciais e questões jurídicas financeiras decorrentes da exploração de uma empresa.', 'released', '["Advogada de Empresa", "Advogado de Empresa"]'::jsonb, '2611'),
  ('http://data.europa.eu/esco/occupation/fe0fa514-b48d-4a53-9757-a283c0baacf0', 'Analista de Negócios de TI', 'Os analistas de negócios de informática são responsáveis pela análise e concepção dos processos e dos sistemas de uma organização, avaliando o modelo de negócio e a sua integração na tecnologia. Identificam igualmente as necessidades de alterações, avaliam o impacto das alterações, recolhem e documentam os requisitos, assegurando depois a sua aplicação e prestando simultaneamente apoio aos negócios através do processo de execução.', 'released', '["Analista de Negócios de Tecnologia da Informação", "Analista de Negócios de Tecnologias de Informação e Comunicação", "Analista de Empresas de TI", "Analista de Negócios de Informática", "Analista de Empresas de Tecnologias de Informação", "Tecnologia da Informação", "Business Analyst"]'::jsonb, '2511'),
  ('http://data.europa.eu/esco/occupation/fe4a72af-6206-4d86-90c1-b5fb4b5ba2b2', 'Técnico de Radiodifusão', 'Os técnicos de radiodifusão procedem à instalação, colocação em funcionamento, manutenção, controlo e reparação do equipamento utilizado para a transmissão e recepção de sinais de radiodifusão de televisão e de rádio. Asseguram que todos os materiais estejam disponíveis num formato adequado de qualidade transmissível, de acordo com o prazo de transmissão. Os técnicos de radiodifusão também procedem à manutenção e reparação deste equipamento.', 'released', '["Técnica de Rádio e Televisão", "Técnico de Televisão e Rádio", "Técnico de Transmissão de Televisão e Rádio", "Técnica de Transmissão de Televisão e Rádio", "Técnico de Radiodifusão", "Técnica de Televisão e Rádio", "Técnica de Radiodifusão", "Técnica de Transmissão de Rádio e Televisão", "Técnico de Rádio e Televisão", "Técnico de Transmissão de Rádio e Televisão"]'::jsonb, '3521'),
  ('http://data.europa.eu/esco/occupation/febd4100-9a9b-46a0-b964-8623d79d0f32', 'Analista de Poluição Atmosférica', 'Os analistas de poluição atmosférica realizam análises no terreno e em laboratório para examinar a poluição do ar em diferentes áreas. Identificam igualmente fontes de poluição.', 'released', NULL, '2133'),
  ('http://data.europa.eu/esco/occupation/ff142063-f89d-446d-92ac-9a3a124210a0', 'Professor de Química do Ensino Secundário', 'Os professores de Química do ensino secundário ensinam alunos, geralmente crianças e jovens adultos, num contexto de escola secundária. Geralmente, são professores da disciplina especializados que lecionam no seu próprio domínio de estudos, a Química. Elaboram planos de aulas e materiais, acompanham os progressos dos alunos, ajudam-nos individualmente, quando necessário, e avaliam os conhecimentos e o desempenho dos alunos no domínio da Química através da atribuição de trabalhos, testes e exames.', 'released', '["Professora de Química do Ensino Secundário", "Professor de Química do Ensino Secundário"]'::jsonb, '2330'),
  ('http://data.europa.eu/esco/occupation/ff2c1183-3fd7-40c7-8ddc-b20b100363c3', 'Assistente Social em Áreas Desfavorecidas', 'Os assistentes sociais em áreas desfavorecidas prestam apoio a indivíduos, famílias e grupos em áreas social ou financeiramente desfavorecidas. Desempenham um papel de liderança e reúnem as populações locais para alterar e combater as desigualdades sociais, ajudando as pessoas a desenvolver as competências necessárias para poderem finalmente gerir os seus próprios grupos comunitários.', 'released', '["Assistentea Social em Áreas Desfavorecidas"]'::jsonb, '2635'),
  ('http://data.europa.eu/esco/occupation/ff3a164d-4045-4511-a472-49093dabf9fc', 'Delegado Comercial para Venda de Energias Renováveis', 'Os delegados comerciais para venda de energias renováveis avaliam as necessidades de fornecimento de energia dos clientes e procuram assegurar a venda de energia de fontes renováveis. Promovem os fornecedores de energias renováveis e a utilização de produtos de energias renováveis e estabelecem contatos com os clientes a fim de aumentarem as vendas.', 'released', '["Delegada Comercial para Venda de Energias Renováveis", "Delegado Comercial para Venda de Energias Renováveis"]'::jsonb, '3322'),
  ('http://data.europa.eu/esco/occupation/ff42d44c-34f8-46be-ad3a-2aad9a5e43f0', 'Pasteleiro', 'Os pasteleiros preparam e elaboram bolos, biscoitos, croissants, empadas e produtos similares, acordo com receitas.', 'released', '["Pasteleira", "Pasteleiro", "Chefe de Pastelaria"]'::jsonb, '7512'),
  ('http://data.europa.eu/esco/occupation/ff4c28e2-66b1-4ae7-9053-fba8ec3428be', 'Técnico de Zoologia', 'Os técnicos de Zoologia prestam assistência técnica na investigação e na análise de espécies animais utilizando equipamento de laboratório. Prestam assistência nas investigações relacionadas com animais, bem como com os seus ambientes e ecossistemas. Recolhem e analisam dados, elaboram relatórios e mantêm as existências de material de laboratório.', 'released', '["Técnico de Zoologia", "Técnica de Zoologia"]'::jsonb, '3141'),
  ('http://data.europa.eu/esco/occupation/ff5210a5-2ea9-43b4-bebc-8d565f928eaa', 'Operador de Máquinas de Fabricar Produtos Cosméticos', 'Os operadores de máquinas de fabricar produtos cosméticos asseguram o correto funcionamento de máquinas para o fabrico de produtos cosméticos através da instalação das máquinas e ferramentas, da limpeza e da manutenção do equipamento e do cumprimento do calendário de produção.', 'released', '["Operadora de Máquinas de Fabricar Produtos Cosméticos", "Operador de Máquinas de Fabricar Produtos Cosméticos"]'::jsonb, '8131'),
  ('http://data.europa.eu/esco/occupation/ff63fa99-c634-4e6f-a693-6a49482952e9', 'Mestre de Navio Pesqueiro', 'Os mestres de navio pesqueiro dirigem navios de pesca nas águas costeiras, realizando operações no convés e no motor. Controlam a navegação, bem como a captura e conservação do peixe dentro dos limites estabelecidos, em conformidade com a regulamentação nacional e internacional.', 'released', '["Mestrea de Navio Pesqueiro"]'::jsonb, '6223'),
  ('http://data.europa.eu/esco/occupation/ff656b3a-65a8-4b4f-b04e-9db12936519b', 'Demógrafo', 'Os demógrafos estudam uma série de parâmetros relacionados com a população. Com base nas suas observações, desenvolvem análises estatísticas sobre a evolução e as alterações dos nascimentos, da população idosa, do casamento e do divórcio, do emprego, da mortalidade, da imigração e de questões conexas.', 'released', '["Demógrafo", "Demógrafa"]'::jsonb, '2120'),
  ('http://data.europa.eu/esco/occupation/ff8d4065-db44-47c7-a4bd-51b3c306ef70', 'Operador da Triagem de Resíduos', 'Os operadores da triagem de resíduos separam materiais recicláveis de um fluxo de reciclagem e garantem que não existam materiais inadequados entre os materiais recicláveis. Inspecionam os materiais, executam tarefas de limpeza e trabalham em conformidade com a regulamentação relativa aos resíduos.', 'released', '["Operadora da Triagem de Resíduos", "Operador da Triagem de Resíduos"]'::jsonb, '9612'),
  ('http://data.europa.eu/esco/occupation/ffa4dd5d-702b-4828-ad85-17ec50db6656', 'Guarda de Veículos Blindados', 'Os guardas de veículos blindados asseguram o transporte seguro de artigos valiosos, tais como dinheiro, entre locais como lojas e bancos. Carregam e descarregam o veículo, tratam da documentação da transferência, entregam os itens para no local correto e respondem rapidamente aos roubos, de acordo com o protocolo de segurança existente. Podem também manipular armas e conduzir o carro blindado.', 'released', NULL, '5414'),
  ('http://data.europa.eu/esco/occupation/ffade2f4-2528-4dfd-b36a-6e4092be08ed', 'Funcionário Administrativo', 'Os funcionários administrativos desempenham funções administrativas em organizações da função pública e em departamentos governamentais. Asseguram a manutenção de registos, tratam os pedidos de informação e prestam informações ao público, pessoalmente, através de mensagens de correio eletrônico ou por telefone. Prestam apoio a quadros superiores e asseguram a constância do fluxo interno de informação.', 'released', '["Funcionário Administrativo", "Funcionária Administrativa", "Funcionária Administrativo"]'::jsonb, '2422'),
  ('http://data.europa.eu/esco/occupation/ffc292f1-89e2-4406-8eff-39096c94e731', 'Montador de Veículos Motorizados', 'Os montadores de veículos motorizados instalam e montam peças e componentes pré-fabricados de veículos motorizados. Inspecionam os veículos motorizados para detectar eventuais defeitos e testam o equipamento montado para assegurar o bom desempenho e a conformidade com as normas de qualidade.', 'released', '["Montador de Veículos Motorizados", "Montadora de Veículos Motorizados"]'::jsonb, '8211')
) AS v(uri, titulo, descricao, status, nomes_alternativos, codigo_grupo)
JOIN esco_dataset.grupo_ocupacao g ON g.codigo = v.codigo_grupo
ON CONFLICT (uri) DO NOTHING;

-- ===========================================================================
-- OCUPAÇÕES DE MERCADO (NEXT HIRE)
-- ===========================================================================
-- Extensões sintéticas para títulos comuns do mercado brasileiro que não
-- existem como ocupação canônica no ESCO. As URIs usam o namespace
-- https://nexthire.local/esco/occupation/ e são determinísticas.
