-- ===========================================================================

SELECT v.uri, v.titulo, v.descricao, v.status::esco_dataset.status_enum, v.nomes_alternativos::jsonb, g.grupo_id
FROM (VALUES
  ('https://nexthire.local/esco/occupation/715c5b9f-8986-5513-ac37-8e6c1186baa8', 'Desenvolvedor Full-stack', 'Desenvolve aplicações web completas, atuando no front-end e no back-end, incluindo interfaces, APIs, bancos de dados, integrações, testes e implantação. Colabora com designers, product managers e equipes de QA e DevOps para entregar soluções escaláveis.', 'released', '["Desenvolvedor Full-stack", "Desenvolvedora Full-stack", "Full-stack Developer", "Dev Full-stack"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/30658f44-505a-5a99-a1ad-2d39ab000bc5', 'Desenvolvedor Back-end', 'Desenvolve e mantém a lógica de servidor, APIs, serviços, bancos de dados e integrações de sistemas. Preocupa-se com desempenho, segurança, escalabilidade e qualidade do código.', 'released', '["Desenvolvedor Back-end", "Desenvolvedora Back-end", "Back-end Developer", "Dev Back-end"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/47b74f32-3676-53ac-99d0-11f360708a36', 'Desenvolvedor de Aplicativos', 'Desenvolve aplicações para web, mobile ou desktop, implementando interfaces, regras de negócio, integrações e testes. Atua em todas as etapas do ciclo de desenvolvimento.', 'released', '["Desenvolvedor de Aplicativos", "Desenvolvedora de Aplicativos", "Desenvolvedor de Aplicações", "Application Developer"]'::jsonb, '2514'),
  ('https://nexthire.local/esco/occupation/b5ba576f-9166-5170-952d-5c1b7d7998ad', 'Engenheiro de Software', 'Projeta, desenvolve, testa e mantém sistemas de software, aplicando boas práticas de engenharia, arquitetura, qualidade e segurança.', 'released', '["Engenheiro de Software", "Engenheira de Software", "Software Engineer"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/8b485d95-9fe0-57df-b57e-a8d4f95282f0', 'Desenvolvedor de Jogos', 'Desenvolve jogos digitais, implementando mecânicas, sistemas, interfaces e integrações, com foco em desempenho e experiência do jogador.', 'released', '["Desenvolvedor de Jogos", "Desenvolvedora de Jogos", "Game Developer", "Programador de Jogos"]'::jsonb, '2513'),
  ('https://nexthire.local/esco/occupation/4589d5b4-de65-58be-94af-98ef0a0f6691', 'Tech Lead', 'Lidera tecnicamente uma equipe de desenvolvimento, define padrões, revisa código, apoia decisões de arquitetura e garante a entrega de soluções de qualidade.', 'released', '["Tech Lead", "Techlead", "Líder Técnico", "Líder Técnica"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/37cd97c1-f2bf-5c18-9931-f7e9a9bc13a4', 'Líder Técnico', 'Coordena tecnicamente a equipe, orienta decisões de arquitetura, acompanha a qualidade do código e apoia o desenvolvimento e a entrega das soluções.', 'released', '["Líder Técnico", "Líder Técnica", "Tech Lead", "Techlead"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/2f091cc9-9ae7-5ce3-95ef-cb32224dd7b3', 'Engenheiro DevOps', 'Implementa e mantém pipelines de CI/CD, automação de infraestrutura, monitoramento e práticas de confiabilidade para acelerar e estabilizar entregas.', 'released', '["Engenheiro DevOps", "Engenheira DevOps", "DevOps Engineer", "Engenheiro de DevOps"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/24ecdb26-da81-5e10-88e9-5037d8b42059', 'Site Reliability Engineer', 'Garante a confiabilidade, disponibilidade e desempenho de sistemas em produção, atuando em observabilidade, automação, capacidade e resposta a incidentes.', 'released', '["Site Reliability Engineer", "SRE", "Engenheiro de Confiabilidade de Sites", "Engenheira de Confiabilidade de Sites"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/6cdc13d8-6ba9-59ed-9607-fbe7c6b82e0c', 'Engenheiro de Confiabilidade de Sites', 'Atua na confiabilidade e disponibilidade de sistemas, com observabilidade, automação, gestão de capacidade e resposta a incidentes.', 'released', '["Engenheiro de Confiabilidade de Sites", "Engenheira de Confiabilidade de Sites", "Site Reliability Engineer", "SRE"]'::jsonb, '2512'),
  ('https://nexthire.local/esco/occupation/7dd68278-91c5-57cb-a4e0-5e16d7200d5c', 'Engenheiro de Plataforma', 'Constrói e mantém plataformas internas e ferramentas de autoatendimento que apoiam o desenvolvimento, a implantação e a operação de aplicações.', 'released', '["Engenheiro de Plataforma", "Engenheira de Plataforma", "Platform Engineer"]'::jsonb, '2512'),
