  ('https://nexthire.local/esco/occupation/e440b9ed-4729-5972-9f7c-b21da3af583a', 'Analista de BI', 'Analisa dados, constrói indicadores, relatórios e dashboards para apoiar decisões de negócio.', 'released', '["Analista de BI", "Business Intelligence Analyst", "Analista de Business Intelligence"]'::jsonb, '2511'),
  ('https://nexthire.local/esco/occupation/1f42aa53-7da6-54bb-bbcc-d01eccac6f62', 'Desenvolvedor BI', 'Desenvolve soluções de business intelligence, incluindo modelos de dados, ETL, relatórios e dashboards.', 'released', '["Desenvolvedor BI", "Desenvolvedora BI", "BI Developer", "Desenvolvedor de Business Intelligence"]'::jsonb, '2521'),
