-- Totais esperados por arquivo (linhas de origem; antes de deduplicação cruzada):
-- digitalSkillsCollection_pt(2).json: 1284 conceitos; tipo(s) = KnowledgeSkillCompetence
-- greenSkillsCollection_pt.json: 591 conceitos; tipo(s) = KnowledgeSkillCompetence
-- languageSkillsCollection_pt(2).json: 359 conceitos; tipo(s) = KnowledgeSkillCompetence
-- transversalSkillsCollection_pt(2).json: 95 conceitos; tipo(s) = KnowledgeSkillCompetence
-- digCompSkillsCollection_pt.json: 25 conceitos; tipo(s) = KnowledgeSkillCompetence
-- researchSkillsCollection_pt.json: 40 conceitos; tipo(s) = KnowledgeSkillCompetence
-- researchOccupationsCollection_pt.json: 122 conceitos; tipo(s) = Occupation
-- Nota: researchOccupationsCollection contém ocupações, mas o schema atual não possui
-- tabela de associação ocupação-coleção. A coleção foi cadastrada, porém seus 122 membros
-- não foram relacionados. Para persistir esses membros, seria necessária uma tabela nova
-- (por exemplo, ocupacao_colecao), o que está fora do escopo desta carga sem alteração do schema.


-- ===========================================================================
-- PARTE 4/5 — relações ocupação-habilidade (original)
-- ===========================================================================
-- PARTE 4/5 — relacionamentos entre ocupações e habilidades
-- Fonte: occupationSkillRelations_pt.json.
-- Dependências: Partes 1 e 2 já importadas; schema e ENUMs já criados.
-- URIs são resolvidas pelas chaves naturais; IDs SERIAL nunca são presumidos.
-- Há 17 pares duplicados na fonte com tipos essencial e opcional simultaneamente.
-- Para respeitar a PK (ocupacao_id, habilidade_id), foi mantido essencial (precedência).
-- Refatoração: URIs das ocupações consolidadas foram remapeadas para as canônicas; o GROUP BY resolve conflitos.
-- Relações são validadas antes da inserção; nenhum endpoint ausente é descartado silenciosamente.


CREATE TEMPORARY TABLE tmp_relacao_ocupacao_habilidade (
  ocupacao_uri TEXT NOT NULL,
  habilidade_uri TEXT NOT NULL,
  tipo_relacionamento esco_dataset.tipo_relacionamento_enum NOT NULL
) ON COMMIT DROP;

