DO $validation$
DECLARE
  v_missing_occupations BIGINT;
  v_missing_skills BIGINT;
BEGIN
  SELECT COUNT(DISTINCT r.ocupacao_uri) INTO v_missing_occupations
  FROM tmp_relacao_ocupacao_habilidade r
  LEFT JOIN esco_dataset.ocupacao o ON o.uri = r.ocupacao_uri
  WHERE o.ocupacao_id IS NULL;
  SELECT COUNT(DISTINCT r.habilidade_uri) INTO v_missing_skills
  FROM tmp_relacao_ocupacao_habilidade r
  LEFT JOIN esco_dataset.habilidade h ON h.uri = r.habilidade_uri
  WHERE h.habilidade_id IS NULL;
  IF v_missing_occupations > 0 OR v_missing_skills > 0 THEN
    RAISE EXCEPTION 'Parte 4 interrompida: % URI(s) de ocupação e % URI(s) de habilidade não encontradas. Execute as Partes 1 e 2 completas.', v_missing_occupations, v_missing_skills;
  END IF;
END $validation$;

-- Uma habilidade pode aparecer como essencial e opcional para a mesma ocupação na fonte; essencial prevalece.
SELECT o.ocupacao_id, h.habilidade_id, MIN(r.tipo_relacionamento::TEXT)::esco_dataset.tipo_relacionamento_enum
FROM tmp_relacao_ocupacao_habilidade r
JOIN esco_dataset.ocupacao o ON o.uri = r.ocupacao_uri
JOIN esco_dataset.habilidade h ON h.uri = r.habilidade_uri
GROUP BY o.ocupacao_id, h.habilidade_id
ON CONFLICT (ocupacao_id, habilidade_id) DO UPDATE
SET tipo_relacionamento = CASE
  WHEN esco_dataset.ocupacao_habilidade.tipo_relacionamento = 'essencial' OR EXCLUDED.tipo_relacionamento = 'essencial' THEN 'essencial'::esco_dataset.tipo_relacionamento_enum
  ELSE 'opcional'::esco_dataset.tipo_relacionamento_enum
END;



-- ===========================================================================
-- RELAÇÕES DAS OCUPAÇÕES DE MERCADO
-- ===========================================================================
-- Clona as relações ocupação-habilidade da ocupação ESCO pai para cada
-- ocupação de mercado. A PK evita duplicatas.
-- ===========================================================================

CREATE TEMP TABLE tmp_ref_mercado (
    uri_mercado TEXT NOT NULL,
    uri_pai TEXT NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
    total INTEGER;
    faltantes INTEGER;
BEGIN
    SELECT count(*) INTO total FROM tmp_ref_mercado;
    SELECT count(*) INTO faltantes
    FROM tmp_ref_mercado t
    WHERE NOT EXISTS (SELECT 1 FROM esco_dataset.ocupacao o WHERE o.uri = t.uri_mercado)
       OR NOT EXISTS (SELECT 1 FROM esco_dataset.ocupacao o WHERE o.uri = t.uri_pai);
    IF total <> 35 THEN
        RAISE EXCEPTION 'Ocupações de mercado: esperava 35 linhas, encontrou %', total;
    END IF;
    IF faltantes <> 0 THEN
        RAISE EXCEPTION 'Ocupações de mercado: % URI(s) sem correspondência', faltantes;
    END IF;
END $$;

SELECT m.ocupacao_id, oh.habilidade_id, oh.tipo_relacionamento
FROM tmp_ref_mercado t
JOIN esco_dataset.ocupacao m ON m.uri = t.uri_mercado
JOIN esco_dataset.ocupacao p ON p.uri = t.uri_pai
JOIN esco_dataset.ocupacao_habilidade oh ON oh.ocupacao_id = p.ocupacao_id
ON CONFLICT (ocupacao_id, habilidade_id) DO NOTHING;

-- ===========================================================================
-- PARTE 5/5 — hierarquia de habilidades (original)
-- ===========================================================================
-- ESCO / Next Hire - Populacao Parte 5/5
-- Importa relacoes hierarquicas pai-filho de habilidades e grupos de habilidades.
-- Fonte: broaderRelationsSkillPillar_pt.json (ESCO, PT).
-- Direcao: broaderUri = conceito pai; conceptUri = conceito filho.
-- A tabela hierarquia_habilidade guarda (habilidade_pai, habilidade_filha).
-- Este script nao importa skillSkillRelations_pt.json: esse arquivo descreve relacoes
-- essential/optional entre habilidades, nao relacoes hierarquicas pai-filho. O schema
-- atual nao possui uma tabela adequada para armazenar esse tipo de relacao.
-- A colecao de ocupacoes de pesquisa tambem nao pode ser associada: nao existe
-- tabela ocupacao_colecao no schema atual.


CREATE TEMP TABLE tmp_hierarquia_esco (
    uri_pai TEXT NOT NULL,
    uri_filha TEXT NOT NULL,
    PRIMARY KEY (uri_pai, uri_filha)
) ON COMMIT DROP;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

ON CONFLICT (uri_pai, uri_filha) DO NOTHING;

DO $$
DECLARE
    total_relacoes INTEGER;
    pais_ausentes INTEGER;
    filhos_ausentes INTEGER;
BEGIN
    SELECT COUNT(*) INTO total_relacoes FROM tmp_hierarquia_esco;

    SELECT COUNT(DISTINCT t.uri_pai)
      INTO pais_ausentes
      FROM tmp_hierarquia_esco t
      LEFT JOIN esco_dataset.habilidade h ON h.uri = t.uri_pai
     WHERE h.habilidade_id IS NULL;

    SELECT COUNT(DISTINCT t.uri_filha)
      INTO filhos_ausentes
      FROM tmp_hierarquia_esco t
      LEFT JOIN esco_dataset.habilidade h ON h.uri = t.uri_filha
     WHERE h.habilidade_id IS NULL;

    IF pais_ausentes > 0 OR filhos_ausentes > 0 THEN
        RAISE EXCEPTION 'Importacao de hierarquia abortada: % URIs de pai e % URIs de filho sem correspondencia em esco_dataset.habilidade.', pais_ausentes, filhos_ausentes;
    END IF;

    RAISE NOTICE 'Validacao concluida: % relacoes hierarquicas e todas as URIs foram encontradas.', total_relacoes;
END $$;

SELECT pai.habilidade_id, filha.habilidade_id
  FROM tmp_hierarquia_esco t
  JOIN esco_dataset.habilidade pai ON pai.uri = t.uri_pai
  JOIN esco_dataset.habilidade filha ON filha.uri = t.uri_filha
ON CONFLICT (habilidade_pai, habilidade_filha) DO NOTHING;


-- Fim da Parte 5/5.


-- ===========================================================================
-- NOVOS VÍNCULOS
-- ===========================================================================

-- 1. Hierarquia grupo -> grupo
CREATE TEMP TABLE tmp_ref_grupo (
    uri_pai TEXT NOT NULL,
    uri_filho TEXT NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
    total INTEGER;
    faltantes INTEGER;
BEGIN
    SELECT count(*) INTO total FROM tmp_ref_grupo;
    SELECT count(*) INTO faltantes
    FROM tmp_ref_grupo t
    WHERE NOT EXISTS (SELECT 1 FROM esco_dataset.grupo_ocupacao g WHERE g.uri = t.uri_pai)
       OR NOT EXISTS (SELECT 1 FROM esco_dataset.grupo_ocupacao g WHERE g.uri = t.uri_filho);
    IF total <> 609 THEN
        RAISE EXCEPTION 'Hierarquia de grupos: esperava 609 linhas, encontrou %', total;
    END IF;
    IF faltantes <> 0 THEN
        RAISE EXCEPTION 'Hierarquia de grupos: % URI(s) sem correspondência', faltantes;
    END IF;
END $$;

SELECT pai.grupo_id, filho.grupo_id
FROM tmp_ref_grupo t
JOIN esco_dataset.grupo_ocupacao pai ON pai.uri = t.uri_pai
JOIN esco_dataset.grupo_ocupacao filho ON filho.uri = t.uri_filho
ON CONFLICT DO NOTHING;


-- 2. Hierarquia ocupação -> ocupação
CREATE TEMP TABLE tmp_ref_ocupacao (
    uri_pai TEXT NOT NULL,
    uri_filha TEXT NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
    total INTEGER;
    faltantes INTEGER;
BEGIN
    SELECT count(*) INTO total FROM tmp_ref_ocupacao;
    SELECT count(*) INTO faltantes
    FROM tmp_ref_ocupacao t
    WHERE NOT EXISTS (SELECT 1 FROM esco_dataset.ocupacao o WHERE o.uri = t.uri_pai)
       OR NOT EXISTS (SELECT 1 FROM esco_dataset.ocupacao o WHERE o.uri = t.uri_filha);
    IF total <> 1248 THEN
        RAISE EXCEPTION 'Hierarquia de ocupações: esperava 1248 linhas, encontrou %', total;
    END IF;
    IF faltantes <> 0 THEN
        RAISE EXCEPTION 'Hierarquia de ocupações: % URI(s) sem correspondência', faltantes;
    END IF;
END $$;

SELECT pai.ocupacao_id, filha.ocupacao_id
FROM tmp_ref_ocupacao t
JOIN esco_dataset.ocupacao pai ON pai.uri = t.uri_pai
JOIN esco_dataset.ocupacao filha ON filha.uri = t.uri_filha
ON CONFLICT DO NOTHING;

-- Hierarquia das ocupações de mercado (filhas da ocupação ESCO pai)
SELECT p.ocupacao_id, m.ocupacao_id
FROM tmp_ref_mercado t
JOIN esco_dataset.ocupacao m ON m.uri = t.uri_mercado
JOIN esco_dataset.ocupacao p ON p.uri = t.uri_pai
ON CONFLICT DO NOTHING;


-- 3. Ocupação -> coleção
CREATE TEMP TABLE tmp_ref_ocupacao_colecao (
    uri_ocupacao TEXT NOT NULL,
    uri_colecao TEXT NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
    total INTEGER;
    faltantes INTEGER;
BEGIN
    SELECT count(*) INTO total FROM tmp_ref_ocupacao_colecao;
    SELECT count(*) INTO faltantes
    FROM tmp_ref_ocupacao_colecao t
    WHERE NOT EXISTS (SELECT 1 FROM esco_dataset.ocupacao o WHERE o.uri = t.uri_ocupacao)
       OR NOT EXISTS (SELECT 1 FROM esco_dataset.colecao c WHERE c.uri = t.uri_colecao);
    IF total <> 122 THEN
        RAISE EXCEPTION 'Ocupação-coleção: esperava 122 linhas, encontrou %', total;
    END IF;
    IF faltantes <> 0 THEN
        RAISE EXCEPTION 'Ocupação-coleção: % URI(s) sem correspondência', faltantes;
    END IF;
END $$;

SELECT o.ocupacao_id, c.colecao_id
FROM tmp_ref_ocupacao_colecao t
JOIN esco_dataset.ocupacao o ON o.uri = t.uri_ocupacao
JOIN esco_dataset.colecao c ON c.uri = t.uri_colecao
ON CONFLICT DO NOTHING;


-- 4. Habilidade -> habilidade
CREATE TEMP TABLE tmp_ref_habilidade (
    uri_origem TEXT NOT NULL,
    uri_relacionada TEXT NOT NULL,
    tipo_relacionamento TEXT NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
    total INTEGER;
    faltantes INTEGER;
BEGIN
    SELECT count(*) INTO total FROM tmp_ref_habilidade;
    SELECT count(*) INTO faltantes
    FROM tmp_ref_habilidade t
    WHERE NOT EXISTS (SELECT 1 FROM esco_dataset.habilidade h WHERE h.uri = t.uri_origem)
       OR NOT EXISTS (SELECT 1 FROM esco_dataset.habilidade h WHERE h.uri = t.uri_relacionada);
    IF total <> 5817 THEN
        RAISE EXCEPTION 'Relações habilidade-habilidade: esperava 5817 linhas, encontrou %', total;
    END IF;
    IF faltantes <> 0 THEN
        RAISE EXCEPTION 'Relações habilidade-habilidade: % URI(s) sem correspondência', faltantes;
    END IF;
END $$;

SELECT o.habilidade_id, r.habilidade_id, t.tipo_relacionamento::esco_dataset.tipo_relacionamento_enum
FROM tmp_ref_habilidade t
JOIN esco_dataset.habilidade o ON o.uri = t.uri_origem
JOIN esco_dataset.habilidade r ON r.uri = t.uri_relacionada
WHERE o.habilidade_id <> r.habilidade_id
ON CONFLICT DO NOTHING;


-- ===========================================================================
-- VALIDAÇÃO FINAL
-- ===========================================================================

DO $$
DECLARE
    v_grupos INTEGER;
    v_ocupacoes INTEGER;
    v_ocupacoes_esco INTEGER;
    v_ocupacoes_mercado INTEGER;
    v_habilidades INTEGER;
    v_relacoes INTEGER;
    v_relacoes_esco INTEGER;
    v_relacoes_mercado INTEGER;
    v_hierarquias INTEGER;
    v_colecoes INTEGER;
    v_habilidade_colecao INTEGER;
    v_hier_grupo INTEGER;
    v_hier_ocupacao INTEGER;
    v_ocupacao_colecao INTEGER;
    v_relacao_habilidade INTEGER;
    v_ciclos INTEGER;
BEGIN
    SELECT count(*) INTO v_grupos FROM esco_dataset.grupo_ocupacao;
    SELECT count(*) INTO v_ocupacoes FROM esco_dataset.ocupacao;
    SELECT count(*) INTO v_ocupacoes_esco FROM esco_dataset.ocupacao WHERE uri LIKE 'http://data.europa.eu/esco/occupation/%';
    SELECT count(*) INTO v_ocupacoes_mercado FROM esco_dataset.ocupacao WHERE uri LIKE 'https://nexthire.local/esco/occupation/%';
    SELECT count(*) INTO v_habilidades FROM esco_dataset.habilidade;
    SELECT count(*) INTO v_relacoes FROM esco_dataset.ocupacao_habilidade;
    SELECT count(*) INTO v_relacoes_esco
        FROM esco_dataset.ocupacao_habilidade oh
        JOIN esco_dataset.ocupacao o ON o.ocupacao_id = oh.ocupacao_id
        WHERE o.uri LIKE 'http://data.europa.eu/esco/occupation/%';
    SELECT count(*) INTO v_relacoes_mercado
        FROM esco_dataset.ocupacao_habilidade oh
        JOIN esco_dataset.ocupacao o ON o.ocupacao_id = oh.ocupacao_id
        WHERE o.uri LIKE 'https://nexthire.local/esco/occupation/%';
    SELECT count(*) INTO v_hierarquias FROM esco_dataset.hierarquia_habilidade;
    SELECT count(*) INTO v_colecoes FROM esco_dataset.colecao;
    SELECT count(*) INTO v_habilidade_colecao FROM esco_dataset.habilidade_colecao;
    SELECT count(*) INTO v_hier_grupo FROM esco_dataset.hierarquia_grupo_ocupacao;
    SELECT count(*) INTO v_hier_ocupacao FROM esco_dataset.hierarquia_ocupacao;
    SELECT count(*) INTO v_ocupacao_colecao FROM esco_dataset.ocupacao_colecao;
    SELECT count(*) INTO v_relacao_habilidade FROM esco_dataset.relacao_habilidade;

    RAISE NOTICE 'Contagens: grupos=%, ocupações=% (ESCO=%, mercado=%), habilidades=%, relações=% (ESCO=%, mercado=%), hierarquias=%, coleções=%, habilidade-coleção=%',
        v_grupos, v_ocupacoes, v_ocupacoes_esco, v_ocupacoes_mercado, v_habilidades,
        v_relacoes, v_relacoes_esco, v_relacoes_mercado, v_hierarquias, v_colecoes, v_habilidade_colecao;
    RAISE NOTICE 'Novos vínculos: hierarquia_grupo=%, hierarquia_ocupação=%, ocupação_coleção=%, relação_habilidade=%',
        v_hier_grupo, v_hier_ocupacao, v_ocupacao_colecao, v_relacao_habilidade;

    IF v_grupos <> 619 OR v_ocupacoes_esco <> 3036 OR v_habilidades <> 14576
       OR v_relacoes_esco <> 128814 OR v_hierarquias <> 20819
       OR v_colecoes <> 7 OR v_habilidade_colecao <> 2394 THEN
        RAISE WARNING 'Contagens ESCO diferentes do esperado (619/3036/14576/128814/20819/7/2394).';
    END IF;
    IF v_ocupacoes_mercado <> 35 THEN
        RAISE WARNING 'Ocupações de mercado: esperava 35, encontrou %.', v_ocupacoes_mercado;
    END IF;
    IF v_relacoes_mercado <> 2561 THEN
        RAISE WARNING 'Relações das ocupações de mercado: esperava 2561, encontrou %.', v_relacoes_mercado;
    END IF;
    IF v_hier_ocupacao <> 1283 THEN
        RAISE WARNING 'Hierarquia de ocupações: esperava 1283, encontrou %.', v_hier_ocupacao;
    END IF;

    WITH RECURSIVE reach AS (
        SELECT grupo_pai_id AS start_id, grupo_filho_id AS node, 1 AS depth
        FROM esco_dataset.hierarquia_grupo_ocupacao
        UNION ALL
        SELECT r.start_id, h.grupo_filho_id, r.depth + 1
        FROM reach r
        JOIN esco_dataset.hierarquia_grupo_ocupacao h ON h.grupo_pai_id = r.node
        WHERE r.depth < 100
    )
    SELECT count(*) INTO v_ciclos FROM reach WHERE start_id = node;
    IF v_ciclos <> 0 THEN
        RAISE EXCEPTION 'Ciclos detectados em hierarquia_grupo_ocupacao: %', v_ciclos;
    END IF;

    WITH RECURSIVE reach AS (
        SELECT ocupacao_pai_id AS start_id, ocupacao_filha_id AS node, 1 AS depth
        FROM esco_dataset.hierarquia_ocupacao
        UNION ALL
        SELECT r.start_id, h.ocupacao_filha_id, r.depth + 1
        FROM reach r
        JOIN esco_dataset.hierarquia_ocupacao h ON h.ocupacao_pai_id = r.node
        WHERE r.depth < 100
    )
    SELECT count(*) INTO v_ciclos FROM reach WHERE start_id = node;
    IF v_ciclos <> 0 THEN
        RAISE EXCEPTION 'Ciclos detectados em hierarquia_ocupacao: %', v_ciclos;
    END IF;

    WITH RECURSIVE reach AS (
        SELECT habilidade_pai AS start_id, habilidade_filha AS node, 1 AS depth
        FROM esco_dataset.hierarquia_habilidade
        UNION ALL
        SELECT r.start_id, h.habilidade_filha, r.depth + 1
        FROM reach r
        JOIN esco_dataset.hierarquia_habilidade h ON h.habilidade_pai = r.node
        WHERE r.depth < 100
    )
    SELECT count(*) INTO v_ciclos FROM reach WHERE start_id = node;
    IF v_ciclos <> 0 THEN
        RAISE EXCEPTION 'Ciclos detectados em hierarquia_habilidade: %', v_ciclos;
    END IF;
END $$;

COMMIT;
